public class MirrorTest : MonoBehaviour
{
	public Transform Wrapper;

	public Transform ReferencePoint;

	public Transform Mirrored;

	public bool mirror;

	private void Update()
	{
		base.transform.Rotate(Vector3.forward, 0.2f);
		Vector3 direction = ReferencePoint.forward;
		Vector3 position = ReferencePoint.localPosition;
		if (mirror)
		{
			direction = new Vector3(0f - direction.x, direction.y, 0f - direction.z);
			position = new Vector3(0f - ReferencePoint.localPosition.x, ReferencePoint.localPosition.y, ReferencePoint.localPosition.z);
		}
		Mirrored.position = Wrapper.TransformPoint(position);
		Mirrored.rotation = Quaternion.Euler(Wrapper.InverseTransformDirection(direction));
	}

	protected Quaternion MirrorRotation(Quaternion source)
	{
		return Quaternion.Euler(source.eulerAngles.x, 0f - source.eulerAngles.y, source.eulerAngles.z);
	}

	protected Vector3 MirrorVector(Vector3 source)
	{
		return new Vector3(0f - source.x, source.y, source.z);
	}
}
