public class RibbonBinder : MonoBehaviour
{
	public bool debug = true;

	private ParticleSystem system;

	private bool testSwitch = true;

	private void Awake()
	{
		system = GetComponent<ParticleSystem>();
	}

	private void Update()
	{
		if (system == null)
		{
			return;
		}
		if (testSwitch && (float)system.particleCount == system.emission.GetBurst(0).count.constantMax)
		{
			BindRibbon();
			if (debug)
			{
				testSwitch = false;
			}
			else
			{
				UnityEngine.Object.Destroy(this);
			}
		}
		else if (debug && !testSwitch && system.particleCount == 0)
		{
			testSwitch = true;
		}
	}

	private void BindRibbon()
	{
		system.Emit(1);
	}
}
public class ShakeChildren : MonoBehaviour
{
	public float magnitude = 0.1f;

	public float frequency = 10f;

	private List<Transform> childrenTransforms = new List<Transform>();

	private Dictionary<Transform, Vector3> originalLocalPositions = new Dictionary<Transform, Vector3>();

	private float shakeTime;

	private void Start()
	{
		foreach (Transform item in base.transform)
		{
			childrenTransforms.Add(item);
			originalLocalPositions[item] = item.localPosition;
		}
	}

	private void Update()
	{
		Shake();
	}

	private void Shake()
	{
		shakeTime += Time.deltaTime * frequency;
		foreach (Transform childrenTransform in childrenTransforms)
		{
			Vector3 vector = new Vector3(Mathf.PerlinNoise(shakeTime, 0f) - 0.5f, Mathf.PerlinNoise(shakeTime, 1f) - 0.5f, Mathf.PerlinNoise(shakeTime, 2f) - 0.5f);
			vector *= magnitude;
			childrenTransform.localPosition = originalLocalPositions[childrenTransform] + vector;
		}
	}
}
