public class CharacterCustomizationDefaults : MonoBehaviour
{
	[Serializable]
	public class MeshMaterialPair
	{
		public string refID;

		public Mesh mesh;

		public Material[] materials;

		public Mesh femaleMesh;

		public Material[] femaleMaterials;
	}

	[Serializable]
	public class CustomizationCategory
	{
		public SkinnedMeshRenderer SkinnedMesh;

		public Material defaultMaterial;

		[HideInInspector]
		public Mesh defaultMesh;

		public List<MeshMaterialPair> overrides = new List<MeshMaterialPair>();

		public int MaleOverrideCount
		{
			get
			{
				if (overrides != null)
				{
					return overrides.CountIf((MeshMaterialPair mmp) => mmp.mesh != null);
				}
				return 0;
			}
		}

		public int FemaleOverrideCount
		{
			get
			{
				if (overrides != null)
				{
					return overrides.CountIf((MeshMaterialPair mmp) => mmp.femaleMesh != null);
				}
				return 0;
			}
		}
	}

	[Serializable]
	public class RaceSetup
	{
		public Race targetRace;

		public CustomizationCategory head = new CustomizationCategory();

		public CustomizationCategory hair = new CustomizationCategory();

		public MeshMaterialPair upper;

		public Material lowerMaterial;

		public Material handMaterial;
	}

	public FateDB editorFateDB;

	public GameObject editorMeshRef;

	public RaceSetup[] raceSetups;

	public CustomizationCategory helmet = new CustomizationCategory();

	public CustomizationCategory upperBody = new CustomizationCategory();

	public CustomizationCategory lowerBody = new CustomizationCategory();

	public CustomizationCategory gloves = new CustomizationCategory();

	public CustomizationCategory back = new CustomizationCategory();

	public MeshMaterialPair hands = new MeshMaterialPair();

	public SkinnedMeshRenderer handsMeshRenderer;

	public EquipmentHandle rightSocket;

	public EquipmentHandle leftSocket;

	private bool hasInitialized;

	private bool isMale = true;

	private RaceSetup activeSetup;

	public bool IsNemesis { get; set; }

	private void Init()
	{
		if (!hasInitialized)
		{
			helmet.defaultMesh = helmet.SkinnedMesh.sharedMesh;
			upperBody.defaultMesh = upperBody.SkinnedMesh.sharedMesh;
			lowerBody.defaultMesh = lowerBody.SkinnedMesh.sharedMesh;
			gloves.defaultMesh = gloves.SkinnedMesh.sharedMesh;
			back.defaultMesh = back.SkinnedMesh.sharedMesh;
			isMale = true;
			activeSetup = raceSetups.Find((RaceSetup r) => r.targetRace == Race.Human);
			hasInitialized = true;
		}
	}

	public int GetHeadCount()
	{
		if (!isMale)
		{
			return activeSetup.head.FemaleOverrideCount;
		}
		return activeSetup.head.MaleOverrideCount;
	}

	public int GetHairCount()
	{
		if (!isMale)
		{
			return activeSetup.hair.FemaleOverrideCount;
		}
		return activeSetup.hair.MaleOverrideCount;
	}

	public void SetRightHand(string key, List<ElementAmount> elements = null, string aRefID = null)
	{
		rightSocket.SetEquipment(key, rightHand: true);
		if (elements != null)
		{
			UtilityTG.UnityDelay(delegate
			{
				rightSocket.LoadWeaponParticles(elements, aRefID);
			});
		}
	}

	public void SetLeftHand(string key, List<ElementAmount> elements = null, string aRefID = null)
	{
		leftSocket.SetEquipment(key, rightHand: false);
		if (elements != null)
		{
			UtilityTG.UnityDelay(delegate
			{
				leftSocket.LoadWeaponParticles(elements, aRefID);
			});
		}
	}

	public void SetHelmet(string helmetKey)
	{
		Init();
		SetMeshAndMaterial(helmet, helmetKey, disableIfNull: true);
		if (!IsNemesis)
		{
			activeSetup.hair.SkinnedMesh.gameObject.SetActive(string.IsNullOrEmpty(helmetKey));
		}
	}

	public void SetUpper(string upperKey)
	{
		Init();
		SetMeshAndMaterial(upperBody, upperKey, IsNemesis);
	}

	public void SetBoots(string bootsKey)
	{
		Init();
		SetMeshAndMaterial(lowerBody, bootsKey, IsNemesis);
	}

	public void SetGloves(string glovesKey)
	{
		Init();
		SetMeshAndMaterial(gloves, glovesKey, disableIfNull: true);
		if (!IsNemesis)
		{
			handsMeshRenderer.gameObject.SetActive(string.IsNullOrEmpty(glovesKey));
		}
	}

	public void SetBack(string backKey)
	{
		if (back != null && !(back.defaultMesh == null))
		{
			Init();
			SetMeshAndMaterial(back, backKey, disableIfNull: true);
		}
	}

	private void SetMeshAndMaterial(CustomizationCategory category, string key, bool disableIfNull)
	{
		if (!string.IsNullOrEmpty(key))
		{
			MeshMaterialPair meshMaterialPair = category.overrides.Find((MeshMaterialPair h) => string.Compare(h.refID.TrimEnd(), key, StringComparison.OrdinalIgnoreCase) == 0);
			if (meshMaterialPair == null)
			{
				UnityEngine.Debug.Log("Override not found: " + key);
				SetFallback();
			}
			else
			{
				category.SkinnedMesh.sharedMesh = meshMaterialPair.mesh;
				category.SkinnedMesh.materials = meshMaterialPair.materials;
				category.SkinnedMesh.gameObject.SetActive(value: true);
			}
		}
		else
		{
			SetFallback();
		}
		void SetFallback()
		{
			if (disableIfNull)
			{
				category.SkinnedMesh.gameObject.SetActive(value: false);
			}
			else
			{
				category.SkinnedMesh.sharedMesh = category.defaultMesh;
				category.SkinnedMesh.material = category.defaultMaterial;
			}
		}
	}

	public void SetHead(int headIndex)
	{
		Init();
		if (headIndex == -1)
		{
			activeSetup.head.SkinnedMesh.sharedMesh = activeSetup.head.defaultMesh;
			activeSetup.head.SkinnedMesh.material = activeSetup.head.defaultMaterial;
		}
		else
		{
			activeSetup.head.SkinnedMesh.sharedMesh = (isMale ? activeSetup.head.overrides[headIndex].mesh : activeSetup.head.overrides[headIndex].femaleMesh);
			activeSetup.head.SkinnedMesh.materials = (isMale ? activeSetup.head.overrides[headIndex].materials : activeSetup.head.overrides[headIndex].femaleMaterials);
		}
	}

	public void SetHair(int hairIndex)
	{
		Init();
		if (hairIndex == -1)
		{
			activeSetup.hair.SkinnedMesh.sharedMesh = activeSetup.hair.defaultMesh;
			activeSetup.hair.SkinnedMesh.material = activeSetup.hair.defaultMaterial;
		}
		else
		{
			activeSetup.hair.SkinnedMesh.sharedMesh = (isMale ? activeSetup.hair.overrides[hairIndex].mesh : activeSetup.hair.overrides[hairIndex].femaleMesh);
			activeSetup.hair.SkinnedMesh.materials = (isMale ? activeSetup.hair.overrides[hairIndex].materials : activeSetup.hair.overrides[hairIndex].femaleMaterials);
		}
	}

	public void SetGender(bool male)
	{
		Init();
		if (isMale != male)
		{
			isMale = male;
			UpdateDefaults();
			SetHair(0);
			SetHead(0);
			upperBody.SkinnedMesh.sharedMesh = (male ? activeSetup.upper.mesh : activeSetup.upper.femaleMesh);
			upperBody.SkinnedMesh.materials = (male ? activeSetup.upper.materials : activeSetup.upper.femaleMaterials);
			handsMeshRenderer.material = activeSetup.handMaterial;
		}
	}

	public void SetRace(Race targetRace)
	{
		Init();
		activeSetup = raceSetups.Find((RaceSetup r) => r.targetRace == targetRace);
		if (activeSetup == null)
		{
			activeSetup = raceSetups.Find((RaceSetup r) => r.targetRace == Race.Human);
		}
		UpdateDefaults();
		activeSetup.head.SkinnedMesh.sharedMesh = activeSetup.head.defaultMesh;
		activeSetup.head.SkinnedMesh.material = activeSetup.head.defaultMaterial;
		activeSetup.hair.SkinnedMesh.sharedMesh = activeSetup.hair.defaultMesh;
		activeSetup.hair.SkinnedMesh.material = activeSetup.hair.defaultMaterial;
		upperBody.defaultMesh = (isMale ? activeSetup.upper.mesh : activeSetup.upper.femaleMesh);
		upperBody.defaultMaterial = (isMale ? activeSetup.upper.materials[0] : activeSetup.upper.femaleMaterials[0]);
		upperBody.SkinnedMesh.sharedMesh = upperBody.defaultMesh;
		upperBody.SkinnedMesh.material = upperBody.defaultMaterial;
		lowerBody.defaultMaterial = activeSetup.lowerMaterial;
		lowerBody.SkinnedMesh.material = activeSetup.lowerMaterial;
		handsMeshRenderer.material = activeSetup.handMaterial;
		_ = targetRace;
		_ = 5;
	}

	private void UpdateDefaults()
	{
		activeSetup.head.defaultMesh = (isMale ? activeSetup.head.overrides[0].mesh : activeSetup.head.overrides[0].femaleMesh);
		activeSetup.head.defaultMaterial = (isMale ? activeSetup.head.overrides[0].materials[0] : activeSetup.head.overrides[0].femaleMaterials[0]);
		activeSetup.hair.defaultMesh = (isMale ? activeSetup.hair.overrides[0].mesh : activeSetup.hair.overrides[0].femaleMesh);
		activeSetup.hair.defaultMaterial = (isMale ? activeSetup.hair.overrides[0].materials[0] : activeSetup.hair.overrides[0].femaleMaterials[0]);
	}
}
[RequireComponent(typeof(LineRenderer))]
public class PathVisualizer : MonoBehaviour
{
	public float updateFrequency = 0.1f;

	private NavMeshAgent navMeshAgent;

	private LineRenderer lineRenderer;

	private Transform playerTansform;

	private void Awake()
	{
		ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Combine(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
	}

	private void Start()
	{
		navMeshAgent = GetComponent<NavMeshAgent>();
		lineRenderer = GetComponent<LineRenderer>();
		lineRenderer.startWidth = 0.5f;
		lineRenderer.endWidth = 0.5f;
		lineRenderer.positionCount = 0;
		StartCoroutine(UpdatePath());
	}

	private void OnDestroy()
	{
		ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Remove(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
	}

	private void OnAvatarSpawn(ProdigyPlayer arg1, ProdigyAgent arg2)
	{
		FindPlayer();
	}

	private void FindPlayer()
	{
		Player player = UnityEngine.Object.FindObjectOfType<Player>();
		if (player != null)
		{
			playerTansform = player.GetComponent<Transform>();
		}
		if (playerTansform == null)
		{
			UnityEngine.Debug.LogError("Player with NavMeshAgent not found.");
		}
	}

	private IEnumerator UpdatePath()
	{
		while (playerTansform == null)
		{
			yield return null;
		}
		while (base.gameObject.activeSelf)
		{
			UpdateLine();
			yield return new WaitForSeconds(updateFrequency);
		}
	}

	private void UpdateLine()
	{
		NavMeshPath navMeshPath = new NavMeshPath();
		if (navMeshAgent.CalculatePath(playerTansform.position, navMeshPath))
		{
			lineRenderer.positionCount = navMeshPath.corners.Length;
			for (int i = 0; i < navMeshPath.corners.Length; i++)
			{
				lineRenderer.SetPosition(i, navMeshPath.corners[i]);
			}
		}
	}
}
public class ActivateDeactivateByVisibility : MonoBehaviour
{
	[SerializeField]
	private List<MonoBehaviour> scriptsToToggle;

	public bool IsVisible { get; private set; }

	private void Start()
	{
		IsVisible = false;
		SetActiveState(state: false);
	}

	private void OnBecameVisible()
	{
		IsVisible = true;
		SetActiveState(state: true);
	}

	private void OnBecameInvisible()
	{
		IsVisible = false;
		SetActiveState(state: false);
	}

	private void SetActiveState(bool state)
	{
		foreach (MonoBehaviour item in scriptsToToggle)
		{
			if (!(item == null))
			{
				item.enabled = state;
			}
		}
	}
}
public class AnimateCookieTexture : MonoBehaviour
{
	public enum AnimMode
	{
		forwards,
		backwards,
		random
	}

	public Cubemap[] textures;

	public float fps = 15f;

	public AnimMode animMode;

	private int frameNr;

	private Light cLight;

	private void Start()
	{
		cLight = GetComponent(typeof(Light)) as Light;
		if (cLight == null)
		{
			UnityEngine.Debug.LogWarning("AnimateCookieTexture: No light found on this gameObject", this);
			base.enabled = false;
		}
		StartCoroutine("switchCookie");
	}

	private IEnumerator switchCookie()
	{
		while (true)
		{
			cLight.cookie = textures[frameNr];
			yield return new WaitForSeconds(1f / fps);
			switch (animMode)
			{
			case AnimMode.forwards:
				frameNr++;
				if (frameNr >= textures.Length)
				{
					frameNr = 0;
				}
				break;
			case AnimMode.backwards:
				frameNr--;
				if (frameNr < 0)
				{
					frameNr = textures.Length - 1;
				}
				break;
			case AnimMode.random:
				frameNr = UnityEngine.Random.Range(0, textures.Length);
				break;
			}
		}
	}
}
public class ApplyHeightNoise : MonoBehaviour
{
	public ComputeShader heightNoiseComputeShader;

	public float maxHeight = 0.5f;

	public float minHeight = -0.5f;

	private float startTime;

	private void Start()
	{
		startTime = Time.time;
		Invoke("ApplyNoiseToStaticMeshes", 2f);
	}

	private void ApplyNoiseToStaticMeshes()
	{
		MeshFilter[] array = UnityEngine.Object.FindObjectsOfType<MeshFilter>();
		foreach (MeshFilter meshFilter in array)
		{
			Mesh sharedMesh = meshFilter.sharedMesh;
			if (sharedMesh.isReadable)
			{
				Mesh mesh2 = (meshFilter.mesh = UnityEngine.Object.Instantiate(sharedMesh));
				Vector3[] vertices = mesh2.vertices;
				Vector3[] vertices2 = mesh2.vertices;
				ComputeBuffer computeBuffer = new ComputeBuffer(vertices.Length, 12);
				ComputeBuffer computeBuffer2 = new ComputeBuffer(vertices2.Length, 12);
				computeBuffer.SetData(vertices);
				computeBuffer2.SetData(vertices2);
				int kernelIndex = heightNoiseComputeShader.FindKernel("ApplyHeightNoise");
				heightNoiseComputeShader.SetBuffer(kernelIndex, "vertices", computeBuffer);
				heightNoiseComputeShader.SetBuffer(kernelIndex, "initialVertices", computeBuffer2);
				heightNoiseComputeShader.SetFloat("maxHeight", maxHeight);
				heightNoiseComputeShader.SetFloat("minHeight", minHeight);
				heightNoiseComputeShader.SetFloat("time", Time.time - startTime);
				Matrix4x4 localToWorldMatrix = meshFilter.transform.localToWorldMatrix;
				Matrix4x4 worldToLocalMatrix = meshFilter.transform.worldToLocalMatrix;
				heightNoiseComputeShader.SetMatrix("objectToWorld", localToWorldMatrix);
				heightNoiseComputeShader.SetMatrix("worldToObject", worldToLocalMatrix);
				int threadGroupsX = Mathf.CeilToInt((float)vertices.Length / 256f);
				heightNoiseComputeShader.Dispatch(kernelIndex, threadGroupsX, 1, 1);
				computeBuffer.GetData(vertices);
				mesh2.vertices = vertices;
				mesh2.RecalculateNormals();
				computeBuffer.Release();
				computeBuffer2.Release();
				MeshCollider component = meshFilter.GetComponent<MeshCollider>();
				if (component != null)
				{
					component.sharedMesh = null;
					component.sharedMesh = mesh2;
				}
			}
		}
	}
}
public class DisableEmissionAndParticle : MonoBehaviour
{
	public ParticleSystem pSystem;

	public ParticleSystem additionalParticleSystem1;

	public ParticleSystem additionalParticleSystem2;

	public MeshRenderer targetRenderer;

	public Light pointLight;

	public float fadeDuration = 2f;

	public float maxIntensity = 2f;

	private Material targetMaterial;

	private void Start()
	{
		if (TryGetComponent<Monster>(out var component) && component.loadedAsDead)
		{
			if (targetRenderer != null)
			{
				targetMaterial = targetRenderer.material;
			}
			DisableAll();
			return;
		}
		if (targetRenderer != null)
		{
			targetMaterial = targetRenderer.material;
			if (!targetMaterial.HasProperty("_EMISSION"))
			{
				UnityEngine.Debug.LogWarning("Material does not have a property with reference _EMISSION.");
			}
			if (!targetMaterial.HasProperty("_Rolling"))
			{
				UnityEngine.Debug.LogWarning("Material does not have a property with reference _Rolling.");
			}
		}
		else
		{
			UnityEngine.Debug.LogWarning("Target Renderer is not assigned.");
		}
		if (pointLight == null)
		{
			UnityEngine.Debug.LogWarning("Point Light is not assigned.");
		}
		if (additionalParticleSystem1 == null)
		{
			UnityEngine.Debug.LogWarning("Additional Particle System 1 is not assigned.");
		}
		if (additionalParticleSystem2 == null)
		{
			UnityEngine.Debug.LogWarning("Additional Particle System 2 is not assigned.");
		}
	}

	public void DeathEffectTrigger()
	{
		if (pSystem != null)
		{
			pSystem.Stop();
		}
		if (targetRenderer != null && targetMaterial != null)
		{
			MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
			targetRenderer.GetPropertyBlock(materialPropertyBlock);
			if (targetMaterial.HasProperty("_EMISSION"))
			{
				materialPropertyBlock.SetFloat("_EmissionPower", 0f);
			}
			if (targetMaterial.HasProperty("_Rolling"))
			{
				materialPropertyBlock.SetVector("_Rolling", Vector2.zero);
			}
			targetRenderer.SetPropertyBlock(materialPropertyBlock);
		}
		if (additionalParticleSystem1 != null)
		{
			additionalParticleSystem1.Play();
		}
		if (additionalParticleSystem2 != null)
		{
			additionalParticleSystem2.Play();
		}
		if (pointLight != null)
		{
			StartCoroutine(LightIntensity(pointLight, fadeDuration, maxIntensity));
		}
	}

	public void DisableAll()
	{
		if (pSystem != null)
		{
			pSystem.Stop();
		}
		if (targetRenderer != null && targetMaterial != null)
		{
			MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
			targetRenderer.GetPropertyBlock(materialPropertyBlock);
			if (targetMaterial.HasProperty("_EMISSION"))
			{
				materialPropertyBlock.SetFloat("_EmissionPower", 0f);
			}
			if (targetMaterial.HasProperty("_Rolling"))
			{
				materialPropertyBlock.SetVector("_Rolling", Vector2.zero);
			}
			targetRenderer.SetPropertyBlock(materialPropertyBlock);
		}
		if (additionalParticleSystem1 != null)
		{
			additionalParticleSystem1.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmittingAndClear);
		}
		if (additionalParticleSystem2 != null)
		{
			additionalParticleSystem2.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmittingAndClear);
		}
		if (pointLight != null)
		{
			pointLight.enabled = false;
		}
	}

	private IEnumerator LightIntensity(Light light, float duration, float maxIntensity)
	{
		float startIntensity = light.intensity;
		float elapsedTime2 = 0f;
		float halfDuration = duration / 2f;
		while (elapsedTime2 < halfDuration)
		{
			light.intensity = Mathf.Lerp(startIntensity, maxIntensity, elapsedTime2 / halfDuration);
			elapsedTime2 += Time.deltaTime;
			yield return null;
		}
		light.intensity = maxIntensity;
		elapsedTime2 = 0f;
		while (elapsedTime2 < halfDuration)
		{
			light.intensity = Mathf.Lerp(maxIntensity, 0f, elapsedTime2 / halfDuration);
			elapsedTime2 += Time.deltaTime;
			yield return null;
		}
		light.intensity = 0f;
		light.enabled = false;
	}
}
