public class LightIntensityLerp : MonoBehaviour
{
	public Light lightToLerp;

	public float minIntensity;

	public float maxIntensity = 1f;

	public float minLerpDuration = 1f;

	public float maxLerpDuration = 3f;

	private float elapsedTime;

	private float currentLerpDuration;

	private float startIntensity;

	private float targetIntensity;

	private void Start()
	{
		SetRandomLerpDuration();
		startIntensity = lightToLerp.intensity;
		SetRandomTargetIntensity();
	}

	private void Update()
	{
		elapsedTime += Time.deltaTime;
		float t = elapsedTime / currentLerpDuration;
		lightToLerp.intensity = Mathf.Lerp(startIntensity, targetIntensity, t);
		if (elapsedTime >= currentLerpDuration)
		{
			elapsedTime = 0f;
			startIntensity = lightToLerp.intensity;
			SetRandomLerpDuration();
			SetRandomTargetIntensity();
		}
	}

	private void SetRandomLerpDuration()
	{
		currentLerpDuration = UnityEngine.Random.Range(minLerpDuration, maxLerpDuration);
	}

	private void SetRandomTargetIntensity()
	{
		targetIntensity = UnityEngine.Random.Range(minIntensity, maxIntensity);
	}
}
[RequireComponent(typeof(ParticleSystem))]
public class ParticleMeshShapeAssigner : MonoBehaviour
{
	private MeshFilter weaponMesh;

	private void Start()
	{
		ParticleSystem component = GetComponent<ParticleSystem>();
		GameObject gameObject = component.transform.parent.gameObject;
		weaponMesh = gameObject.GetComponentInChildren<MeshFilter>();
		base.transform.SetParent(weaponMesh.transform);
		base.transform.localPosition = Vector3.zero;
		base.transform.localRotation = Quaternion.identity;
		ParticleSystem[] componentsInChildren = GetComponentsInChildren<ParticleSystem>();
		if (weaponMesh != null)
		{
			ApplyShapeModule(component);
			ParticleSystem[] array = componentsInChildren;
			foreach (ParticleSystem particleSystem in array)
			{
				ApplyShapeModule(particleSystem);
			}
		}
	}

	private void ApplyShapeModule(ParticleSystem particleSystem)
	{
		ParticleSystem.ShapeModule shape = particleSystem.shape;
		shape.shapeType = ParticleSystemShapeType.Mesh;
		if (weaponMesh.mesh != null)
		{
			shape.mesh = weaponMesh.mesh;
		}
		else
		{
			particleSystem.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmittingAndClear);
		}
	}
}
