public class RandomRotation : MonoBehaviour
{
	public enum Axis
	{
		X,
		Y,
		Z
	}

	public Axis rotationAxis;

	private void Awake()
	{
		ApplyRandomRotation();
	}

	private void ApplyRandomRotation()
	{
		float num = UnityEngine.Random.Range(0f, 360f);
		switch (rotationAxis)
		{
		case Axis.X:
			base.transform.Rotate(num, 0f, 0f);
			break;
		case Axis.Y:
			base.transform.Rotate(0f, num, 0f);
			break;
		case Axis.Z:
			base.transform.Rotate(0f, 0f, num);
			break;
		default:
			UnityEngine.Debug.LogError("Invalid axis selected.");
			break;
		}
	}
}
public class RigidbodyKinematicSetter : MonoBehaviour
{
	[SerializeField]
	private bool explode;

	[SerializeField]
	private float explosionForce = 200f;

	[SerializeField]
	private float explosionRadius = 5f;

	[SerializeField]
	private GameObject[] objectsToModify;

	[SerializeField]
	private float disablePhysInSec = 5f;

	private void Awake()
	{
		if (explode)
		{
			GameObject[] array = objectsToModify;
			for (int i = 0; i < array.Length; i++)
			{
				Rigidbody component = array[i].GetComponent<Rigidbody>();
				if (component != null)
				{
					component.AddExplosionForce(explosionForce, base.transform.position, explosionRadius);
				}
			}
		}
		StartCoroutine(DelayedKinematicAndColliderDisable());
	}

	private IEnumerator DelayedKinematicAndColliderDisable()
	{
		yield return new WaitForSeconds(disablePhysInSec);
		GameObject[] array = objectsToModify;
		foreach (GameObject gameObject in array)
		{
			if (gameObject != null)
			{
				Rigidbody component = gameObject.GetComponent<Rigidbody>();
				if (component != null)
				{
					component.isKinematic = true;
				}
				MeshCollider component2 = gameObject.GetComponent<MeshCollider>();
				if (component2 != null)
				{
					component2.enabled = false;
				}
			}
		}
	}
}
public class RotateOnTrigger : MonoBehaviour
{
	public GameObject objectToRotate;

	public Collider triggerObject;

	public Vector3 rotationValue1;

	public Vector3 rotationValue2;

	public float rotationSpeed = 2f;

	public LayerMask triggerLayers;

	private AudioSource audioSource;

	public AudioClip doorOpenSound;

	public AudioClip doorShutSound;

	private Vector3 targetRotation;

	private int objectsInTrigger;

	public bool IsDoorOpen { get; private set; }

	private void Start()
	{
		audioSource = GetComponent<AudioSource>();
		if (audioSource == null)
		{
			UnityEngine.Debug.Log(base.gameObject.name + " is missing audioSource component");
		}
		if (objectToRotate != null)
		{
			targetRotation = objectToRotate.transform.localRotation.eulerAngles;
		}
		base.gameObject.layer = LayerMask.NameToLayer("Trigger");
	}

	private void OnTriggerEnter(Collider other)
	{
		if (((1 << other.gameObject.layer) & (int)triggerLayers) != 0)
		{
			objectsInTrigger++;
			targetRotation = rotationValue1;
			if (!IsDoorOpen && audioSource != null && doorOpenSound != null)
			{
				audioSource.PlayOneShot(doorOpenSound);
			}
			IsDoorOpen = true;
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (((1 << other.gameObject.layer) & (int)triggerLayers) == 0)
		{
			return;
		}
		objectsInTrigger--;
		if (objectsInTrigger <= 0)
		{
			targetRotation = rotationValue2;
			objectsInTrigger = 0;
			if (audioSource != null && doorShutSound != null)
			{
				audioSource.PlayOneShot(doorShutSound);
			}
			IsDoorOpen = false;
		}
	}

	private void Update()
	{
		if (!(objectToRotate == null))
		{
			objectToRotate.transform.localRotation = Quaternion.Lerp(objectToRotate.transform.localRotation, Quaternion.Euler(targetRotation), rotationSpeed * Time.deltaTime);
		}
	}
}
[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer), typeof(MeshCollider))]
public class ProceduralFloor : MonoBehaviour
{
	[Header("Floor Settings")]
	public float floorSize = 10f;

	public int resolution = 100;

	public float minHeight;

	public float maxHeight = 2f;

	public float noiseScale = 0.1f;

	public float elevationControl;

	public Material floorMaterial;

	private MeshFilter meshFilter;

	private MeshCollider meshCollider;

	private Mesh mesh;

	private bool hasInitialized;

	private void Start()
	{
		Init();
	}

	private void Init()
	{
		if (!hasInitialized)
		{
			meshFilter = GetComponent<MeshFilter>();
			meshCollider = GetComponent<MeshCollider>();
			GenerateFloorMesh();
			hasInitialized = true;
		}
	}

	private void OnDestroy()
	{
		if (hasInitialized && mesh != null)
		{
			UnityEngine.Object.Destroy(mesh);
		}
	}

	private void GenerateFloorMesh()
	{
		mesh = new Mesh();
		mesh.name = "ProceduralFloor";
		Vector3[] array = new Vector3[(resolution + 1) * (resolution + 1)];
		Vector2[] array2 = new Vector2[array.Length];
		int[] array3 = new int[resolution * resolution * 6];
		float num = floorSize / 2f;
		float num2 = floorSize / (float)resolution;
		int num3 = 0;
		int num4 = 0;
		for (int i = 0; i <= resolution; i++)
		{
			for (int j = 0; j <= resolution; j++)
			{
				float x = (float)i * num2 - num;
				float z = (float)j * num2 - num;
				bool flag = Physics.CheckBox(new Vector3(x, 0f, z) + base.transform.position, new Vector3(num2 / 2f, 1f, num2 / 2f), Quaternion.identity, LayerMask.GetMask("Pits"));
				float y = (flag ? minHeight : Mathf.Lerp(minHeight, maxHeight, (Mathf.PerlinNoise((float)i * noiseScale, (float)j * noiseScale) + elevationControl) / 2f + 0.5f));
				array[num3] = new Vector3(x, y, z);
				array2[num3] = new Vector2((float)i / (float)resolution, (float)j / (float)resolution);
				if (i < resolution && j < resolution && !flag)
				{
					array3[num4] = num3;
					array3[num4 + 1] = num3 + resolution + 1;
					array3[num4 + 2] = num3 + 1;
					array3[num4 + 3] = num3 + 1;
					array3[num4 + 4] = num3 + resolution + 1;
					array3[num4 + 5] = num3 + resolution + 2;
					num4 += 6;
				}
				num3++;
			}
		}
		mesh.vertices = array;
		mesh.triangles = array3;
		mesh.uv = array2;
		mesh.RecalculateNormals();
		meshFilter.mesh = mesh;
		meshCollider.sharedMesh = mesh;
		if (floorMaterial != null)
		{
			GetComponent<MeshRenderer>().material = floorMaterial;
		}
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.red;
		for (int i = 0; i <= resolution; i++)
		{
			for (int j = 0; j <= resolution; j++)
			{
				float x = (float)i * (floorSize / (float)resolution) - floorSize / 2f;
				float z = (float)j * (floorSize / (float)resolution) - floorSize / 2f;
				if (Physics.CheckBox(new Vector3(x, 0f, z) + base.transform.position, new Vector3(floorSize / (float)resolution / 2f, 1f, floorSize / (float)resolution / 2f), Quaternion.identity, LayerMask.GetMask("Pits")))
				{
					Gizmos.DrawCube(new Vector3(x, 0f, z) + base.transform.position, Vector3.one * (floorSize / (float)resolution));
				}
			}
		}
	}
}
[DisallowMultipleComponent]
public class SteamManager : MonoBehaviour
{
	protected static bool s_EverInitialized;

	protected static SteamManager s_instance;

	protected Callback<UserStatsReceived_t> m_UserStatsReceived;

	protected Callback<UserStatsStored_t> m_UserStatsStored;

	protected Callback<UserAchievementStored_t> m_UserAchievementStored;

	private CGameID m_GameID;

	private Dictionary<Fate.DLC, uint> dlcLookup = new Dictionary<Fate.DLC, uint> { 
	{
		Fate.DLC.Prometheus,
		4362450u
	} };

	private bool m_bRequestedStats;

	private bool m_bStatsValid;

	private bool m_bStoreStats;

	protected bool m_bInitialized;

	protected SteamAPIWarningMessageHook_t m_SteamAPIWarningMessageHook;

	public static SteamManager Instance
	{
		get
		{
			if (s_instance == null)
			{
				return new GameObject("SteamManager").AddComponent<SteamManager>();
			}
			return s_instance;
		}
	}

	public static bool Initialized => Instance.m_bInitialized;

	[MonoPInvokeCallback(typeof(SteamAPIWarningMessageHook_t))]
	protected static void SteamAPIDebugTextHook(int nSeverity, StringBuilder pchDebugText)
	{
		UnityEngine.Debug.LogWarning(pchDebugText);
	}

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
	private static void InitOnPlayMode()
	{
		s_EverInitialized = false;
		s_instance = null;
	}

	protected virtual void Awake()
	{
		if (s_instance != null)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		s_instance = this;
		if (s_EverInitialized)
		{
			throw new Exception("Tried to Initialize the SteamAPI twice in one session!");
		}
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		if (!Packsize.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Packsize Test returned false, the wrong version of Steamworks.NET is being run in this platform.", this);
		}
		if (!DllCheck.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] DllCheck Test returned false, One or more of the Steamworks binaries seems to be the wrong version.", this);
		}
		try
		{
			if (SteamAPI.RestartAppIfNecessary(AppId_t.Invalid))
			{
				Application.Quit();
				return;
			}
		}
		catch (DllNotFoundException ex)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Could not load [lib]steam_api.dll/so/dylib. It's likely not in the correct location. Refer to the README for more details.\n" + ex, this);
			Application.Quit();
			return;
		}
		m_bInitialized = SteamAPI.Init();
		if (!m_bInitialized)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] SteamAPI_Init() failed. Refer to Valve's documentation or the comment above this line for more information.", this);
			return;
		}
		s_EverInitialized = true;
		m_GameID = new CGameID(SteamUtils.GetAppID());
		m_UserStatsReceived = Callback<UserStatsReceived_t>.Create(OnUserStatsReceived);
		m_UserStatsStored = Callback<UserStatsStored_t>.Create(OnUserStatsStored);
		m_UserAchievementStored = Callback<UserAchievementStored_t>.Create(OnAchievementStored);
		m_bRequestedStats = false;
		m_bStatsValid = false;
	}

	public bool HasEntitlement(Fate.DLC id)
	{
		if (!Initialized)
		{
			return false;
		}
		return SteamApps.BIsDlcInstalled(new AppId_t(dlcLookup[id]));
	}

	public void UnlockAchievement(int index)
	{
		if (Initialized)
		{
			bool pbAchieved = false;
			string achievementName = SteamUserStats.GetAchievementName((uint)(index - 1));
			SteamUserStats.GetAchievement(achievementName, out pbAchieved);
			bool flag = false;
			if (!pbAchieved)
			{
				SteamUserStats.SetAchievement(achievementName);
				flag = SteamUserStats.StoreStats();
			}
			UnityEngine.Debug.Log("UnlockAchievement SetAchievement: " + index + " " + achievementName + "bool locked :" + pbAchieved + " StoreStats: " + flag);
		}
	}

	private void OnUserStatsReceived(UserStatsReceived_t pCallback)
	{
		if (Initialized && (ulong)m_GameID == pCallback.m_nGameID && EResult.k_EResultOK != pCallback.m_eResult)
		{
			UnityEngine.Debug.Log("RequestStats - failed, " + pCallback.m_eResult);
		}
	}

	private void OnUserStatsStored(UserStatsStored_t pCallback)
	{
		if ((ulong)m_GameID == pCallback.m_nGameID)
		{
			if (EResult.k_EResultOK == pCallback.m_eResult)
			{
				UnityEngine.Debug.Log("StoreStats - success");
			}
			else if (EResult.k_EResultInvalidParam == pCallback.m_eResult)
			{
				UnityEngine.Debug.Log("StoreStats - some failed to validate");
				UserStatsReceived_t pCallback2 = default(UserStatsReceived_t);
				pCallback2.m_eResult = EResult.k_EResultOK;
				pCallback2.m_nGameID = (ulong)m_GameID;
				OnUserStatsReceived(pCallback2);
			}
			else
			{
				UnityEngine.Debug.Log("StoreStats - failed, " + pCallback.m_eResult);
			}
		}
	}

	private void OnAchievementStored(UserAchievementStored_t pCallback)
	{
		if ((ulong)m_GameID == pCallback.m_nGameID)
		{
			if (pCallback.m_nMaxProgress == 0)
			{
				UnityEngine.Debug.Log("Achievement '" + pCallback.m_rgchAchievementName + "' unlocked!");
				return;
			}
			UnityEngine.Debug.Log("Achievement '" + pCallback.m_rgchAchievementName + "' progress callback, (" + pCallback.m_nCurProgress + "," + pCallback.m_nMaxProgress + ")");
		}
	}

	protected virtual void OnEnable()
	{
		if (s_instance == null)
		{
			s_instance = this;
		}
		if (m_bInitialized && m_SteamAPIWarningMessageHook == null)
		{
			m_SteamAPIWarningMessageHook = SteamAPIDebugTextHook;
			SteamClient.SetWarningMessageHook(m_SteamAPIWarningMessageHook);
		}
	}

	protected virtual void OnDestroy()
	{
		if (!(s_instance != this))
		{
			s_instance = null;
			if (m_bInitialized)
			{
				SteamAPI.Shutdown();
			}
		}
	}

	protected virtual void Update()
	{
		if (m_bInitialized)
		{
			SteamAPI.RunCallbacks();
			SteamUserStats.RequestCurrentStats();
		}
	}

	public bool IsSteamRunningOnSteamDeck()
	{
		return SteamUtils.IsSteamRunningOnSteamDeck();
	}

	public void ShowFloatingGamepadTextInput()
	{
		SteamUtils.ShowFloatingGamepadTextInput(EFloatingGamepadTextInputMode.k_EFloatingGamepadTextInputModeModeSingleLine, 0, 0, 500, 200);
	}

	private void DebugPrint()
	{
		string personaName = SteamFriends.GetPersonaName();
		uint numAchievements = SteamUserStats.GetNumAchievements();
		string[] obj = new string[5]
		{
			personaName,
			" - ",
			SteamUser.GetSteamID().ToString(),
			" gameID: ",
			null
		};
		CGameID gameID = m_GameID;
		obj[4] = gameID.ToString();
		UnityEngine.Debug.Log(string.Concat(obj));
		UnityEngine.Debug.Log("number of achievements: " + numAchievements);
		for (uint num = 0u; num < numAchievements; num++)
		{
			bool pbAchieved = false;
			SteamUserStats.GetAchievement(SteamUserStats.GetAchievementName(num), out pbAchieved);
			UnityEngine.Debug.Log(num + " - Achievement: " + SteamUserStats.GetAchievementName(num) + " : " + pbAchieved);
		}
	}
}
