public class RadialLayout : LayoutGroup
{
	public float fDistance;

	public bool clockwise;

	[Range(0f, 360f)]
	public float MinAngle;

	[Range(0f, 360f)]
	public float MaxAngle;

	[Range(0f, 360f)]
	public float StartAngle;

	protected override void OnEnable()
	{
		base.OnEnable();
		CalculateRadial();
	}

	public override void SetLayoutHorizontal()
	{
	}

	public override void SetLayoutVertical()
	{
	}

	public override void CalculateLayoutInputVertical()
	{
		CalculateRadial();
	}

	public override void CalculateLayoutInputHorizontal()
	{
		CalculateRadial();
	}

	private void CalculateRadial(bool setAnchorAndPivots = true)
	{
		m_Tracker.Clear();
		if (base.transform.childCount == 0)
		{
			return;
		}
		float num = (MaxAngle - MinAngle) / (float)(base.transform.childCount - 1);
		float num2 = StartAngle;
		for (int i = 0; i < base.transform.childCount; i++)
		{
			RectTransform rectTransform = (RectTransform)base.transform.GetChild(i);
			if (rectTransform != null)
			{
				m_Tracker.Add(this, rectTransform, DrivenTransformProperties.Anchors | DrivenTransformProperties.AnchoredPosition);
				Vector3 vector = new Vector3(Mathf.Cos(num2 * (MathF.PI / 180f)), Mathf.Sin(num2 * (MathF.PI / 180f)), 0f);
				rectTransform.localPosition = vector * fDistance;
				if (setAnchorAndPivots)
				{
					Vector2 anchorMin = (rectTransform.anchorMax = new Vector2(0.5f, 0.5f));
					rectTransform.anchorMin = anchorMin;
				}
				num2 = (clockwise ? (num2 - num) : (num2 + num));
			}
		}
	}
}
public class LoadLevelsWithInput : MonoBehaviour
{
	public LevelGenerator levelGenerator;

	public int levelDepth;

	private bool start = true;

	private void Start()
	{
		start = true;
		levelGenerator.Create(0f, 0f, levelDepth, 10, goesDown: true, useSavedPosition: false);
		levelDepth++;
		levelGenerator.SetPlayerPositionInLevel();
	}

	private void Update()
	{
		if (Input.GetKeyDown(KeyCode.Alpha1))
		{
			if (levelGenerator.HasActiveDungeon())
			{
				levelGenerator.Remove();
			}
			if (!start)
			{
				levelDepth++;
			}
			start = true;
			levelGenerator.Create(0f, 0f, levelDepth, 10, goesDown: true, useSavedPosition: false);
			levelDepth++;
			levelGenerator.SetPlayerPositionInLevel();
		}
		else if (Input.GetKeyDown(KeyCode.Alpha2))
		{
			if (levelGenerator.HasActiveDungeon())
			{
				levelGenerator.Remove();
			}
			if (start)
			{
				levelDepth--;
				start = false;
			}
			levelDepth--;
			if (levelDepth >= 1)
			{
				levelGenerator.Create(0f, 0f, levelDepth, 10, goesDown: true, useSavedPosition: false);
				levelGenerator.SetPlayerPositionInLevel(downStairs: false);
			}
		}
	}
}
public class EnemyAIPatrol : MonoBehaviour
{
	private NavMeshAgent navAgent;

	[SerializeField]
	private LayerMask groundLayer;

	[SerializeField]
	private LayerMask playerLayer;

	private Vector3 destPoint;

	private bool walkPointSet;

	private float walkingRange;

	[SerializeField]
	private float range;

	private void Start()
	{
		navAgent = GetComponent<NavMeshAgent>();
	}

	private void Update()
	{
		Patrol();
	}

	private void Patrol()
	{
		if (!walkPointSet)
		{
			SearchForDest();
		}
		if (walkPointSet)
		{
			navAgent.SetDestination(destPoint);
		}
		if (Vector3.Distance(base.transform.position, destPoint) < 10f)
		{
			walkPointSet = false;
		}
	}

	private void SearchForDest()
	{
		float num = UnityEngine.Random.Range(0f - range, range);
		float num2 = UnityEngine.Random.Range(0f - range, range);
		destPoint = new Vector3(base.transform.position.x + num2, base.transform.position.y, base.transform.position.z + num);
		if (Physics.Raycast(destPoint, Vector3.down, (int)groundLayer))
		{
			walkPointSet = true;
		}
	}
}
