namespace Tivola.Framework
{
	public interface IAchievements
	{
		IEnumerator Initialize();

		void UnlockAchievement(int index);

		void UpdateAchievement(int index, uint progress);

		void AddAchievementListener(Action<int> onAchievement);

		void RemoveAchievementListener(Action<int> onAchievement);
	}
	public class SteamAchievements : IAchievements
	{
		private Action<int> m_OnAchievementUnlock;

		public void AddAchievementListener(Action<int> onAchievement)
		{
			m_OnAchievementUnlock = (Action<int>)Delegate.Combine(m_OnAchievementUnlock, onAchievement);
		}

		public void RemoveAchievementListener(Action<int> onAchievement)
		{
			m_OnAchievementUnlock = (Action<int>)Delegate.Remove(m_OnAchievementUnlock, onAchievement);
		}

		public IEnumerator Initialize()
		{
			yield break;
		}

		public void UnlockAchievement(int index)
		{
			UnityEngine.Debug.Log("UnlockAchievement Steam: " + index);
			SteamManager.Instance.UnlockAchievement(index);
		}

		public void UpdateAchievement(int index, uint progress)
		{
		}
	}
	public interface IPlatformManager
	{
		Task Initialize();

		void ManagerUpdate();

		Task<bool> DoMainUserEngagement(InputDevice inputDevice);

		Task EngageUserByControllerIndex(uint index);

		Task SetUserAsSecondary(ILocalUser user);

		ILocalUser GetMainUser();

		T GetMainUser<T>() where T : ILocalUser;

		List<ILocalUser> GetAllUsers();

		ILocalUser GetUserByControllerIndex(uint index);

		bool IsControllerIDMapped(uint controllerID);

		bool HasMainUserEngaged();

		void RegisterMainUserEventCallback(Action<MainUserEvent> callback);

		void UnRegisterMainUserEventCallback(Action<MainUserEvent> callback);

		string GetSystemLanguage();

		void HasEntitlement(Fate.DLC entitlement, Action<bool> onDone);

		void OnManagerDestroy();
	}
	public interface ILocalUser : IComparable
	{
		string GetDisplayName();

		bool TryGetAvatarImage(out Sprite avatarImage, bool getCachedImage = true);

		string GetUniqueID();

		string GetDebugName();

		bool HasController();

		void RegisterCallback();

		void UnregisterCallback();
	}
	public enum LocalUserEvent
	{
		DisplayNameChanged,
		AvatarChanged
	}
	public enum MainUserEvent
	{
		SignedOut,
		ChangedUser,
		SignedIn
	}
	public class PlatformManager : SingletonBehaviour<PlatformManager>
	{
		private static IPlatformManager s_Instance;

		public static Action OnPlatformInitialized;

		public static bool HasInitialized;

		protected override bool DontDestroy => true;

		protected override void Init()
		{
			UnityEngine.Debug.Log("--------------------------------- Platform manager init --------------------- Main Thread: " + UtilityTG.IsInMainThread());
			SetInstance();
		}

		private static void SetInstance()
		{
			if (s_Instance == null)
			{
				if (s_Instance == null)
				{
					s_Instance = new PlatformManagerPC();
				}
				if (s_Instance == null)
				{
					UnityEngine.Debug.LogError($"PlatformManager not implemented for platform '{Application.platform}', creating dummy one.");
					s_Instance = new PlatformManagerNull();
				}
				s_Instance.Initialize();
			}
		}

		public static void OnInit()
		{
			HasInitialized = true;
			OnPlatformInitialized?.Invoke();
		}

		private static IPlatformManager SecuredInstance()
		{
			if (s_Instance == null)
			{
				SetInstance();
			}
			return s_Instance;
		}

		private void Update()
		{
			SecuredInstance().ManagerUpdate();
		}

		private void OnDestroy()
		{
			SecuredInstance().OnManagerDestroy();
		}

		public static bool ControlSchemeEnabled(string schemeName)
		{
			return true;
		}

		public static async Task<bool> DoMainUserEngagement(InputDevice inputDevice)
		{
			if (!Application.isEditor)
			{
				UnityEngine.Debug.Log("Doing main user engagement");
			}
			return await SecuredInstance().DoMainUserEngagement(inputDevice).ConfigureAwait(continueOnCapturedContext: false);
		}

		public static async Task EngageUserByControllerIndex(uint index)
		{
			if (!Application.isEditor)
			{
				UnityEngine.Debug.Log("Engaging user");
			}
			await SecuredInstance().EngageUserByControllerIndex(index).ConfigureAwait(continueOnCapturedContext: false);
		}

		public static async Task SetUserAsSecondary(ILocalUser user)
		{
			if (!Application.isEditor)
			{
				UnityEngine.Debug.Log("Setting user as secondary");
			}
			await SecuredInstance().SetUserAsSecondary(user).ConfigureAwait(continueOnCapturedContext: false);
		}

		public static ILocalUser GetMainUser()
		{
			return SecuredInstance().GetMainUser();
		}

		public static T GetMainUser<T>() where T : ILocalUser
		{
			return SecuredInstance().GetMainUser<T>();
		}

		public static List<ILocalUser> GetAllUsers()
		{
			return SecuredInstance().GetAllUsers();
		}

		public static ILocalUser GetUserByControllerIndex(uint index)
		{
			return SecuredInstance().GetUserByControllerIndex(index);
		}

		public static bool IsControllerIDMapped(uint controllerID)
		{
			return SecuredInstance().IsControllerIDMapped(controllerID);
		}

		public static bool HasMainUserEngaged()
		{
			return SecuredInstance().HasMainUserEngaged();
		}

		public static void RegisterMainUserEventCallback(Action<MainUserEvent> callback)
		{
			SecuredInstance().RegisterMainUserEventCallback(callback);
		}

		public static void UnRegisterMainUserEventCallback(Action<MainUserEvent> callback)
		{
			SecuredInstance().UnRegisterMainUserEventCallback(callback);
		}

		public static string GetPlatformLanguage()
		{
			return SecuredInstance().GetSystemLanguage();
		}

		public static void HasEntitlement(Fate.DLC entitlement, Action<bool> onDone)
		{
			SecuredInstance().HasEntitlement(entitlement, onDone);
		}
	}
