		public ILocalUser GetMainUser()
		{
			return null;
		}

		public T GetMainUser<T>() where T : ILocalUser
		{
			return default(T);
		}

		public string GetSystemLanguage()
		{
			switch (Application.systemLanguage)
			{
			case SystemLanguage.Japanese:
				return "ja";
			case SystemLanguage.Korean:
				return "ko";
			case SystemLanguage.Chinese:
			case SystemLanguage.ChineseSimplified:
			case SystemLanguage.ChineseTraditional:
				return "zh-CN";
			case SystemLanguage.French:
				return "fr-FR";
			case SystemLanguage.German:
				return "de-DE";
			case SystemLanguage.Spanish:
				return "es-ES";
			default:
				return "en";
			}
		}

		public ILocalUser GetUserByControllerIndex(uint index)
		{
			return null;
		}

		public bool IsControllerIDMapped(uint controllerID)
		{
			return false;
		}

		public Task SetUserAsSecondary(ILocalUser user)
		{
			return Task.CompletedTask;
		}

		public bool HasMainUserEngaged()
		{
			return true;
		}

		public void HasEntitlement(Fate.DLC entitlement, Action<bool> onDone)
		{
			onDone?.Invoke(SteamManager.Instance.HasEntitlement(entitlement));
		}
	}
