		private static void SetInstance()
		{
			if (s_Instance == null)
			{
				s_Instance = new SaveManagerStandalone();
				if (s_Instance == null)
				{
					UnityEngine.Debug.LogWarning($"SaveManager not implemented for platform '{Application.platform}', creating dummy one.");
					s_Instance = new SaveManagerNull();
				}
				s_Instance.Initialize(delegate
				{
					HasInitialized = true;
				});
			}
		}

		public static void OnGameConstrained()
		{
			if (s_SaveCancelTokenSource != null)
			{
				try
				{
					s_SaveCancelTokenSource.Cancel();
				}
				catch (ObjectDisposedException)
				{
				}
			}
			SecuredInstance().OnGameConstrained();
		}

		public static async Task SaveAsync(string fileName, byte[] bytes)
		{
			s_PendingData = bytes;
			if (s_IsSaving)
			{
				return;
			}
			s_IsSaving = true;
			try
			{
				s_SaveCancelTokenSource = new CancellationTokenSource();
				try
				{
					await Task.Delay(1000, s_SaveCancelTokenSource.Token);
					await SecuredInstance().SaveAsync(fileName, s_PendingData).ConfigureAwait(continueOnCapturedContext: false);
					s_SaveCancelTokenSource.Dispose();
				}
				catch (TaskCanceledException)
				{
					UnityEngine.Debug.Log($"CANCELLED: Async Save: {bytes.Length} bytes as '{fileName}'...");
					s_SaveCancelTokenSource.Dispose();
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
			finally
			{
				s_IsSaving = false;
			}
		}

		public static async Task<(bool isSuccess, byte[] data)> LoadAsync(string fileName)
		{
			s_IsLoading = true;
			byte[] data = null;
			try
			{
				data = await SecuredInstance().LoadAsync(fileName).ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
			finally
			{
				s_IsLoading = false;
				s_HasEverLoaded = true;
			}
			if (!Application.isEditor)
			{
				if (data == null)
				{
					UnityEngine.Debug.Log("No data to load from '" + fileName + "'");
				}
				else
				{
					UnityEngine.Debug.Log($"Loaded {data.Length} bytes from '{fileName}'...");
				}
			}
			return (isSuccess: data != null, data: data);
		}

		private static ISaveManager SecuredInstance()
		{
			if (s_Instance == null)
			{
				SetInstance();
			}
			return s_Instance;
		}
	}
