	public sealed class SaveManagerPlayerPrefs : ISaveManager
	{
		public void Initialize(Action onInitialized)
		{
			onInitialized?.Invoke();
		}

		private void Save(string fileName, byte[] bytes)
		{
			StringBuilder stringBuilder = new StringBuilder(bytes.Length * 2);
			for (int i = 0; i < bytes.Length; i++)
			{
				stringBuilder.AppendFormat("{0:X2}", bytes[i]);
			}
			PlayerPrefs.SetString(fileName, stringBuilder.ToString());
		}

		public async Task SaveAsync(string fileName, byte[] bytes)
		{
			await Task.Run(delegate
			{
				Save(fileName, bytes);
			}).ConfigureAwait(continueOnCapturedContext: false);
		}

		private byte[] Load(string fileName)
		{
			byte[] array = null;
			try
			{
				string @string = PlayerPrefs.GetString(fileName);
				if (!string.IsNullOrEmpty(@string))
				{
					array = new byte[@string.Length / 2];
					int num = 0;
					for (int i = 0; i < @string.Length; i += 2)
					{
						string s = @string.Substring(i, 2);
						array[num++] = byte.Parse(s, NumberStyles.HexNumber);
					}
				}
			}
			catch (Exception ex)
			{
				array = null;
				throw ex;
			}
			return array;
		}

		public async Task<byte[]> LoadAsync(string fileName)
		{
			return await Task.Run(() => Load(fileName)).ConfigureAwait(continueOnCapturedContext: false);
		}

		public void OnGameConstrained()
		{
		}
	}
	public sealed class SaveManagerStandalone : ISaveManager
	{
		private const int k_MaxSaveDataSize = 33554432;

		private const int k_SaveDataHeaderSize = 1024;

		private const int k_BufferSize = 524288;

		private const uint k_SaveDataMagic = 3735928559u;

		private const uint k_SaveDataVersion = 1u;

		private static readonly ConcurrentDictionary<string, SemaphoreSlim> s_FileAccessSemaphores = new ConcurrentDictionary<string, SemaphoreSlim>();

		public void Initialize(Action onInitialized)
		{
			onInitialized?.Invoke();
		}

		public async Task SaveAsync(string fileName, byte[] bytes)
		{
			await WriteToFileAsync(fileName, await Task.Run(() => SerializeData(bytes))).ConfigureAwait(continueOnCapturedContext: false);
		}

		public async Task<byte[]> LoadAsync(string fileName)
		{
			var (flag, data) = await TryReadFromFileAsync(fileName).ConfigureAwait(continueOnCapturedContext: false);
			if (!flag)
			{
				return null;
			}
			return await Task.Run(() => DeserializeData(data));
		}

		private byte[] SerializeData(byte[] data)
		{
			if (data == null)
			{
				return null;
			}
			using MemoryStream memoryStream = new MemoryStream(33554432);
			using BinaryWriter binaryWriter = new BinaryWriter(memoryStream);
			binaryWriter.Write(3735928559u);
			binaryWriter.Write(1u);
			binaryWriter.Write(data.Length);
			binaryWriter.Write(data);
			byte[] array = memoryStream.ToArray();
			if (array.Length > 33554432)
			{
				throw new Exception($"Savegame data size is larger than size limit. ({array.Length}) Max: {33554432}");
			}
			return array;
		}

		private byte[] DeserializeData(byte[] data)
		{
			using MemoryStream input = new MemoryStream(data);
			using BinaryReader binaryReader = new BinaryReader(input);
			if (binaryReader.ReadUInt32() != 3735928559u)
			{
				return null;
			}
			if (binaryReader.ReadUInt32() < 1)
			{
				return null;
			}
			int count = binaryReader.ReadInt32();
			return binaryReader.ReadBytes(count);
		}

		private async Task WriteToFileAsync(string fileName, byte[] data)
		{
			SemaphoreSlim semaphore = s_FileAccessSemaphores.GetOrAdd(fileName, new SemaphoreSlim(1, 1));
			await semaphore.WaitAsync().ConfigureAwait(continueOnCapturedContext: false);
			try
			{
				using FileStream fileStream = new FileStream(GetFilePath(fileName), FileMode.Create, FileAccess.Write, FileShare.None, 524288, useAsync: true);
				await fileStream.WriteAsync(data, 0, data.Length).ConfigureAwait(continueOnCapturedContext: false);
			}
			finally
			{
				semaphore.Release();
			}
		}

		private async Task<(bool isSuccess, byte[] data)> TryReadFromFileAsync(string fileName)
		{
			string filePath = GetFilePath(fileName);
			if (!File.Exists(filePath))
			{
				return (isSuccess: false, data: null);
			}
			SemaphoreSlim semaphore = s_FileAccessSemaphores.GetOrAdd(fileName, new SemaphoreSlim(1, 1));
			await semaphore.WaitAsync().ConfigureAwait(continueOnCapturedContext: false);
			byte[] buffer;
			try
			{
				using FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 524288, useAsync: true);
				buffer = new byte[fileStream.Length];
				await fileStream.ReadAsync(buffer, 0, Convert.ToInt32(fileStream.Length)).ConfigureAwait(continueOnCapturedContext: false);
			}
			finally
			{
				semaphore.Release();
			}
			return (isSuccess: true, data: buffer);
		}

		private string GetFilePath(string fileName)
		{
			string text = (Application.isEditor ? Application.streamingAssetsPath : Application.persistentDataPath);
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			return $"{text}/{fileName}.save";
		}

		public void OnGameConstrained()
		{
		}
	}
