		[Serializable]
		private class Data : IData
		{
			[Serializable]
			public class Entry
			{
				[Serializable]
				public static class Type
				{
					public const byte k_None = 0;

					public const byte k_Int = 1;

					public const byte k_Float = 2;

					public const byte k_String = 3;

					public const byte k_Bool = 4;

					public const byte k_Vector2 = 5;

					public const byte k_Vector3 = 6;

					public const byte k_Vector4 = 7;

					public const byte k_Quaternion = 8;

					public const byte k_Vector2Int = 9;

					public const byte k_Vector3Int = 10;

					public const byte k_Object = 11;
				}

				public string key;

				public int keyId;

				public byte type;

				public float floatValue;

				public int intValue;

				public string stringValue;

				public Vector4 vector4Value;

				public Vector3Int vectorIntValue;

				public static int StringToHash(string s)
				{
					return Animator.StringToHash(s);
				}
			}

			[SerializeField]
			private const int k_StorageVersion = 1;

			[SerializeField]
			private List<Entry> m_Entries = new List<Entry>();

			private bool m_Locked;

			private int FindEntry(string key)
			{
				int num = Entry.StringToHash(key);
				for (int i = 0; i < m_Entries.Count; i++)
				{
					Entry entry = m_Entries[i];
					if (entry.keyId == num && string.Equals(entry.key, key, StringComparison.OrdinalIgnoreCase))
					{
						return i;
					}
				}
				return -1;
			}

			private Entry CreateEntry(string key, byte type)
			{
				return new Entry
				{
					type = type,
					key = key,
					keyId = Entry.StringToHash(key)
				};
			}

			public Vector2Int GetVector2Int(string key, Vector2Int defaultValue)
			{
				int num = FindEntry(key);
				if (num != -1)
				{
					Entry entry = m_Entries[num];
					if (entry.type == 9)
					{
						return new Vector2Int(entry.vectorIntValue.x, entry.vectorIntValue.y);
					}
				}
				return defaultValue;
			}

			public void SetVector2Int(string key, Vector2Int value)
			{
				int num = FindEntry(key);
				if (num != -1)
				{
					Entry entry = m_Entries[num];
					entry.type = 9;
					entry.vectorIntValue = new Vector3Int(value.x, value.y, 0);
				}
				else
				{
					Entry entry2 = CreateEntry(key, 9);
					entry2.vectorIntValue = new Vector3Int(value.x, value.y, 0);
					m_Entries.Add(entry2);
				}
			}

			public Vector2 GetVector2(string key, Vector2 defaultValue)
			{
				int num = FindEntry(key);
				if (num != -1)
				{
					Entry entry = m_Entries[num];
					if (entry.type == 5)
					{
						return entry.vector4Value;
					}
				}
				return defaultValue;
			}

			public void SetVector2(string key, Vector2 value)
			{
				int num = FindEntry(key);
				if (num != -1)
				{
					Entry entry = m_Entries[num];
					entry.type = 5;
					entry.vector4Value = new Vector4(value.x, value.y, 0f, 0f);
				}
				else
				{
					Entry entry2 = CreateEntry(key, 5);
