			}

			public void SetObject(string key, object value)
			{
				if (m_Locked)
				{
					UnityEngine.Debug.LogWarning("SetObject called while locked");
					return;
				}
				string stringValue = JsonUtility.ToJson(value);
				int num = FindEntry(key);
				if (num != -1)
				{
					Entry entry = m_Entries[num];
					entry.type = 11;
					entry.stringValue = stringValue;
				}
				else
				{
					Entry entry2 = CreateEntry(key, 11);
					entry2.stringValue = stringValue;
					m_Entries.Add(entry2);
				}
			}

			public T GetObject<T>(string key) where T : class
			{
				int num = FindEntry(key);
				if (num != -1)
				{
					Entry entry = m_Entries[num];
					if (entry.type == 11)
					{
						try
						{
							return JsonUtility.FromJson<T>(entry.stringValue);
						}
						catch
						{
						}
					}
				}
				return null;
			}

			public T GetStruct<T>(string key, T defaultValue) where T : struct
			{
				int num = FindEntry(key);
				if (num != -1)
				{
					Entry entry = m_Entries[num];
					if (entry.type == 11)
					{
						try
						{
							return JsonUtility.FromJson<T>(entry.stringValue);
						}
						catch
						{
						}
					}
				}
				return defaultValue;
			}

			public string GetJson(string key, string defaultValue)
			{
				int num = FindEntry(key);
				if (num != -1)
				{
					Entry entry = m_Entries[num];
					if (entry.type == 11)
					{
						return entry.stringValue;
					}
				}
				return defaultValue;
			}

			public bool HasKey(string key)
			{
				if (FindEntry(key) != -1)
				{
					return true;
				}
				return false;
			}

			public void DeleteKey(string key)
			{
				int num = FindEntry(key);
				if (num != -1)
				{
					m_Entries.RemoveAt(num);
				}
			}

			public async Task LoadFromArrayAsync(byte[] data)
			{
				m_Entries = new List<Entry>();
				using MemoryStream stream = new MemoryStream(data);
				BinaryReader reader = new BinaryReader(stream);
				try
				{
					if (await Task.Run(() => reader.ReadInt32()).ConfigureAwait(continueOnCapturedContext: false) < 1)
					{
						UnityEngine.Debug.LogError("Unable to load data, version does not match.");
						return;
					}
					int entryCount = await Task.Run(() => reader.ReadInt32()).ConfigureAwait(continueOnCapturedContext: false);
					int i = 0;
					while (i < entryCount)
					{
						await Task.Run(delegate
						{
							m_Entries.Add(ReadEntry(reader));
						}).ConfigureAwait(continueOnCapturedContext: false);
						int num = i + 1;
						i = num;
					}
				}
				finally
				{
					if (reader != null)
					{
						((IDisposable)reader).Dispose();
					}
				}
			}

			public async Task<byte[]> SaveToArrayAsync()
			{
				using MemoryStream stream = new MemoryStream(523264);
				BinaryWriter writer = new BinaryWriter(stream);
				try
				{
					_ = 2;
					try
					{
						await Task.Run(delegate
						{
							writer.Write(1);
						}).ConfigureAwait(continueOnCapturedContext: false);
						await Task.Run(delegate
						{
							writer.Write(m_Entries.Count);
						}).ConfigureAwait(continueOnCapturedContext: false);
						m_Locked = true;
						foreach (Entry entry in m_Entries)
						{
							await Task.Run(delegate
							{
								WriteEntry(entry, writer);
							}).ConfigureAwait(continueOnCapturedContext: false);
						}
					}
					finally
					{
						writer.Flush();
						m_Locked = false;
					}
					return stream.ToArray();
				}
				finally
				{
					if (writer != null)
					{
						((IDisposable)writer).Dispose();
					}
				}
			}

			public List<KeyValuePair<string, string>> GetDataAsStringPairs()
			{
				List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>(m_Entries.Count);
				foreach (Entry entry in m_Entries)
				{
					switch (entry.type)
					{
					case 4:
					{
						string value = ((entry.intValue > 0) ? "TRUE" : "FALSE");
						list.Add(new KeyValuePair<string, string>(entry.key, value));
						break;
					}
					case 1:
						list.Add(new KeyValuePair<string, string>(entry.key, entry.intValue.ToString()));
						break;
					case 2:
						list.Add(new KeyValuePair<string, string>(entry.key, entry.floatValue.ToString()));
						break;
					case 3:
					case 11:
						list.Add(new KeyValuePair<string, string>(entry.key, entry.stringValue));
						break;
					case 5:
					{
						string value = $"[x: {entry.vector4Value.x}, y: {entry.vector4Value.y}]";
						list.Add(new KeyValuePair<string, string>(entry.key, value));
						break;
					}
					case 6:
					{
						string value = $"[x: {entry.vector4Value.x}, y: {entry.vector4Value.y}, z: {entry.vector4Value.z}]";
						list.Add(new KeyValuePair<string, string>(entry.key, value));
						break;
					}
					case 7:
					case 8:
					{
						string value = $"[x: {entry.vector4Value.x}, y: {entry.vector4Value.y}, z: {entry.vector4Value.z}, w: {entry.vector4Value.w}]";
						list.Add(new KeyValuePair<string, string>(entry.key, value));
						break;
					}
					case 9:
					{
						string value = $"[x: {entry.vectorIntValue.x}, y: {entry.vectorIntValue.y}]";
						list.Add(new KeyValuePair<string, string>(entry.key, value));
						break;
					}
					case 10:
					{
						string value = $"[x: {entry.vectorIntValue.x}, y: {entry.vectorIntValue.y}, z: {entry.vectorIntValue.z}]";
						list.Add(new KeyValuePair<string, string>(entry.key, value));
						break;
					}
					default:
						list.Add(new KeyValuePair<string, string>(entry.key, "VALUE_IS_UNSUPPORTED"));
						break;
					}
				}
				return list;
			}

			public void DeleteAll()
			{
				m_Entries = new List<Entry>();
			}

			private void WriteEntry(Entry entry, BinaryWriter writer)
			{
				writer.Write(entry.type);
				writer.Write(entry.key);
				switch (entry.type)
				{
				case 4:
					writer.Write((sbyte)entry.intValue);
					break;
				case 1:
					writer.Write(entry.intValue);
					break;
				case 2:
					writer.Write(entry.floatValue);
					break;
				case 3:
				case 11:
					writer.Write(entry.stringValue);
					break;
				case 5:
					writer.Write(entry.vector4Value.x);
					writer.Write(entry.vector4Value.y);
					break;
				case 6:
					writer.Write(entry.vector4Value.x);
					writer.Write(entry.vector4Value.y);
					writer.Write(entry.vector4Value.z);
					break;
				case 7:
				case 8:
					writer.Write(entry.vector4Value.x);
					writer.Write(entry.vector4Value.y);
					writer.Write(entry.vector4Value.z);
					writer.Write(entry.vector4Value.w);
					break;
				case 9:
					writer.Write(entry.vectorIntValue.x);
					writer.Write(entry.vectorIntValue.y);
					break;
				case 10:
					writer.Write(entry.vectorIntValue.x);
					writer.Write(entry.vectorIntValue.y);
					writer.Write(entry.vectorIntValue.z);
					break;
				default:
					throw new NotImplementedException($"entry.type '{entry.type}' ({(int)entry.type}) not supported yet.");
				}
			}

			private Entry ReadEntry(BinaryReader reader)
			{
				Entry entry = new Entry();
				entry.type = reader.ReadByte();
				entry.key = reader.ReadString();
				entry.keyId = Entry.StringToHash(entry.key);
				switch (entry.type)
				{
				case 4:
					entry.intValue = reader.ReadSByte();
					break;
				case 1:
					entry.intValue = reader.ReadInt32();
					break;
				case 2:
					entry.floatValue = reader.ReadSingle();
					break;
				case 3:
				case 11:
					entry.stringValue = reader.ReadString();
					break;
				case 5:
					entry.vector4Value = default(Vector4);
					entry.vector4Value.x = reader.ReadSingle();
					entry.vector4Value.y = reader.ReadSingle();
					break;
				case 6:
					entry.vector4Value = default(Vector4);
					entry.vector4Value.x = reader.ReadSingle();
					entry.vector4Value.y = reader.ReadSingle();
					entry.vector4Value.z = reader.ReadSingle();
					break;
				case 7:
				case 8:
					entry.vector4Value = default(Vector4);
					entry.vector4Value.x = reader.ReadSingle();
					entry.vector4Value.y = reader.ReadSingle();
					entry.vector4Value.z = reader.ReadSingle();
					entry.vector4Value.w = reader.ReadSingle();
					break;
				case 9:
					entry.vectorIntValue = default(Vector3Int);
					entry.vectorIntValue.x = reader.ReadInt32();
					entry.vectorIntValue.y = reader.ReadInt32();
					break;
				case 10:
					entry.vectorIntValue = default(Vector3Int);
					entry.vectorIntValue.x = reader.ReadInt32();
					entry.vectorIntValue.y = reader.ReadInt32();
					entry.vectorIntValue.z = reader.ReadInt32();
					break;
				default:
					throw new NotImplementedException($"entry.type '{entry.type}' ({(int)entry.type}) not supported yet.");
				}
				return entry;
			}
		}

