		public static async Task SaveAsync(bool force = false)
		{
			if (!force)
			{
				if (s_IsSavePending)
				{
					return;
				}
				s_IsSavePending = true;
				await Task.Delay(Mathf.RoundToInt(1000f));
				if (!s_IsSavePending)
				{
					return;
				}
			}
			s_IsSavePending = false;
			await SaveManager.SaveAsync("SaveData", await Task.Run((Func<Task<byte[]>>)SaveToArrayAsync)).ConfigureAwait(continueOnCapturedContext: false);
			static async Task<byte[]> SaveToArrayAsync()
			{
				return await IO.SaveToArrayAsync();
			}
		}

		public static async Task LoadAsync()
		{
			if (await LoadAsyncInternal())
			{
				OnDataUpdated();
			}
		}

		private static async Task<bool> LoadAsyncInternal()
		{
			var (flag, data) = await SaveManager.LoadAsync("SaveData").ConfigureAwait(continueOnCapturedContext: false);
			if (!flag)
			{
				return false;
			}
			await IO.LoadFromArrayAsync(data).ConfigureAwait(continueOnCapturedContext: false);
			return true;
		}

		private static void OnDataUpdated()
		{
			dataChanged?.Invoke();
		}
	}
	public static class CoroutineSlave
	{
		private class CoroutineSlaveInternal : MonoBehaviour
		{
			private void Awake()
			{
				UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
			}

			public Coroutine StartCoroutineInternal(IEnumerator enumerator)
			{
				return StartCoroutine(enumerator);
			}

			public void StopCoroutineInternal(IEnumerator enumerator)
			{
				StopCoroutine(enumerator);
			}

			public void StopCoroutineInternal(Coroutine coroutine)
			{
				StopCoroutine(coroutine);
			}

			public void StopAllCoroutinesInternal()
			{
				StopAllCoroutines();
			}

			private void OnApplicationQuit()
			{
				StopAllCoroutines();
				UnityEngine.Object.Destroy(base.gameObject);
			}
		}

		private static bool s_IsApplicationQuitting;

		private static CoroutineSlaveInternal s_Instance;

		private static CoroutineSlaveInternal instance
		{
			[DebuggerStepThrough]
			get
			{
				if (s_IsApplicationQuitting || !SceneManager.GetActiveScene().isLoaded || s_Instance != null)
				{
					return s_Instance;
				}
				s_Instance = UnityEngine.Object.FindObjectOfType<CoroutineSlaveInternal>();
				if (s_Instance != null)
				{
					return s_Instance;
				}
				s_Instance = new GameObject("Zzz_CoroutineSlave").AddComponent<CoroutineSlaveInternal>();
				return s_Instance;
			}
		}

		public static Coroutine StartCoroutine(IEnumerator enumerator)
		{
			if (s_IsApplicationQuitting)
			{
				return null;
			}
			if (instance == null)
			{
				return null;
			}
			return instance.StartCoroutineInternal(enumerator);
		}

		public static void StopCoroutine(IEnumerator enumerator)
		{
			if (!s_IsApplicationQuitting && !(s_Instance == null))
			{
				s_Instance.StopCoroutineInternal(enumerator);
			}
		}

		public static void StopCoroutine(Coroutine coroutine)
		{
			if (!s_IsApplicationQuitting && !(s_Instance == null))
			{
				s_Instance.StopCoroutineInternal(coroutine);
			}
		}

		public static void StopAllCoroutines()
		{
			if (!s_IsApplicationQuitting && !(s_Instance == null))
			{
				s_Instance.StopAllCoroutinesInternal();
			}
		}

		[RuntimeInitializeOnLoadMethod]
		private static void OnStart()
		{
			s_IsApplicationQuitting = false;
			Application.quitting += OnQuit;
		}

		private static void OnQuit()
		{
			s_IsApplicationQuitting = true;
			s_Instance = null;
			Application.quitting -= OnQuit;
		}
	}
