	public class LocalOscillate : MonoBehaviour
	{
		public float speed = 1f;

		public float amplitude = 1f;

		private Vector3 localStart;

		private float myTimer;

		private void Start()
		{
			localStart = base.transform.localPosition;
			myTimer = 0f;
		}

		private void Update()
		{
			myTimer += Time.deltaTime * speed;
			Vector3 localPosition = (localStart = Mathf.Sin(myTimer) * amplitude * Vector3.forward);
			base.transform.localPosition = localPosition;
		}
	}
	public class AudioManager : SingletonBehaviour<AudioManager>
	{
		public AudioMixer masterMixer;

		public int soundChannels = 20;

		public int musicChannels = 2;

		private int currentIndex;

		private AudioSource[] audioSourceSFXChannels;

		private AudioSource[] audioSourceMusicChannels;

		public AudioData[] mAudioDataSFXList;

		public AudioData[] mAudioDataMusicList;

		private bool hasStoppedByScript;

		private AudioData.AudioClipName currentMusicData;

		protected override bool DontDestroy => true;

		protected override void Init()
		{
			audioSourceSFXChannels = new AudioSource[soundChannels];
			audioSourceMusicChannels = new AudioSource[musicChannels];
			AudioMixerGroup outputAudioMixerGroup = masterMixer.FindMatchingGroups("Sound")[0];
			AudioMixerGroup outputAudioMixerGroup2 = masterMixer.FindMatchingGroups("Music")[0];
			for (int i = 0; i < soundChannels; i++)
			{
				GameObject obj = new GameObject("SFX_" + i, typeof(AudioSource));
				obj.transform.SetParent(base.transform);
				AudioSource component = obj.GetComponent<AudioSource>();
				component.outputAudioMixerGroup = outputAudioMixerGroup;
				audioSourceSFXChannels[i] = component;
			}
			for (int j = 0; j < musicChannels; j++)
			{
				GameObject obj2 = new GameObject("Music_" + j, typeof(AudioSource));
				obj2.transform.SetParent(base.transform);
				AudioSource component2 = obj2.GetComponent<AudioSource>();
				component2.outputAudioMixerGroup = outputAudioMixerGroup2;
				audioSourceMusicChannels[j] = component2;
			}
			hasStoppedByScript = true;
		}

		private void Update()
		{
			if (!IsMusicPlaying() && !hasStoppedByScript)
			{
				PlayMusic(currentMusicData, stopOthers: true);
			}
		}

		public void SetMusicVol(float soundLevel)
		{
			masterMixer.SetFloat("musicVolume", GetDecibel01(soundLevel));
		}

		public void SetEffectsVol(float soundLevel)
		{
			masterMixer.SetFloat("soundVolume", GetDecibel01(soundLevel));
		}

		public void SetVoiceVol(float voiceLevel)
		{
			masterMixer.SetFloat("voiceVolume", GetDecibel01(voiceLevel));
		}

		private float GetDecibel01(float value)
		{
			value = Mathf.Clamp(value, 0.0001f, 1f);
			return Mathf.Log(Mathf.Lerp(0.001f, 0.8f, value)) * 10f;
		}

		public float GetMusicVol()
		{
			masterMixer.GetFloat("Music", out var value);
			return value;
		}

		public float GetEffectsVol()
		{
			masterMixer.GetFloat("Sound", out var value);
			return value;
		}

		public void StopAudioClip(AudioData.AudioClipName clip)
		{
			AudioData audioData = mAudioDataSFXList.Find((AudioData m) => m.mAudioClipName == clip);
			string text = ((audioData != null) ? audioData.mAudioClip[0].name : null);
			if (string.IsNullOrEmpty(text))
			{
				return;
			}
			for (int i = 0; i < audioSourceSFXChannels.Length; i++)
			{
				if (audioSourceSFXChannels[i].isPlaying && audioSourceSFXChannels[i].clip != null && audioSourceSFXChannels[i].clip.name == text)
				{
					audioSourceSFXChannels[i].Stop();
				}
			}
		}

		public void StopAllSoundFx()
		{
			for (int i = 0; i < audioSourceSFXChannels.Length; i++)
			{
				if (audioSourceSFXChannels[i].isPlaying && audioSourceSFXChannels[i].clip != null)
				{
					audioSourceSFXChannels[i].Stop();
				}
			}
		}

		public void PlayAudioClip(AudioData.AudioClipName clip, bool randomizePitch)
		{
			AudioData audioData = mAudioDataSFXList.Find((AudioData a) => a.mAudioClipName == clip);
			if (audioData != null)
			{
				SetupAudioSourceAndPlay(audioData, randomizePitch);
			}
			else
			{
				UnityEngine.Debug.Log("PlayAudioClip NOT FOUND: " + clip);
			}
		}

		public void PlayAudioClipPrio(AudioData.AudioClipName clip)
		{
			AudioData audioData = mAudioDataSFXList.Find((AudioData a) => a.mAudioClipName == clip);
			if (audioData != null)
			{
				SetupAudioSourceAndPlayPrio(audioData);
			}
			else
			{
				UnityEngine.Debug.Log("PlayAudioClip NOT FOUND: " + clip);
			}
		}

		public void ForcePlayAudioClip(AudioData.AudioClipName clip)
		{
			AudioData audioData = mAudioDataSFXList.Find((AudioData a) => a.mAudioClipName == clip);
			if (audioData != null)
			{
				ForceSetupAudioSourceAndPlay(audioData);
			}
			else
			{
				UnityEngine.Debug.Log("PlayAudioClip NOT FOUND: " + clip);
			}
		}

		public void PlayAudioClip(AudioData.AudioClipName clip, float delayTime)
		{
			AudioData audioData = mAudioDataSFXList.Find((AudioData a) => a.mAudioClipName == clip);
			if (audioData != null)
			{
				SetupAudioSourceAndPlay(audioData, delayTime, randomizePitch: true);
			}
			else
			{
				UnityEngine.Debug.Log("PlayAudioClip NOT FOUND: " + clip);
