		private void SetupAudioSourceAndPlay(AudioData clip, bool randomizePitch = false)
		{
			AudioSource freeAudioSource = GetFreeAudioSource();
			if (freeAudioSource != null)
			{
				freeAudioSource.volume = clip.mVolume;
				freeAudioSource.loop = clip.mLoop;
				freeAudioSource.spatialBlend = 0f;
				if (randomizePitch)
				{
					freeAudioSource.pitch = UnityEngine.Random.Range(0.9f, 1.1f);
				}
				else
				{
					freeAudioSource.pitch = 1f;
				}
				if (!string.IsNullOrEmpty(clip.mAudioClipLocaKey))
				{
					freeAudioSource.clip = LocalizationManager.GetTranslatedObjectByTermName<AudioClip>(clip.mAudioClipLocaKey);
				}
				else if (clip.mRandom)
				{
					freeAudioSource.clip = clip.mAudioClip[UnityEngine.Random.Range(0, clip.mAudioClip.Length)];
				}
				else
				{
					freeAudioSource.clip = clip.mAudioClip[0];
				}
				freeAudioSource.Play();
			}
		}

		private void SetupAudioSourceAndPlayPrio(AudioData clip)
		{
			StopAllSoundFx();
			List<AudioSource> list = new List<AudioSource>();
			for (int i = 0; i < audioSourceSFXChannels.Length; i++)
			{
				list.Add(audioSourceSFXChannels[i]);
			}
			for (int j = 0; j < list.Count; j++)
			{
				list[j].volume = 0.1f;
				list[0].volume = clip.mVolume;
				list[0].loop = clip.mLoop;
				list[0].spatialBlend = 0f;
				if (!string.IsNullOrEmpty(clip.mAudioClipLocaKey))
				{
					list[j].clip = LocalizationManager.GetTranslatedObjectByTermName<AudioClip>(clip.mAudioClipLocaKey);
				}
				else if (clip.mRandom)
				{
					list[j].clip = clip.mAudioClip[UnityEngine.Random.Range(0, clip.mAudioClip.Length)];
				}
				else
				{
					list[j].clip = clip.mAudioClip[0];
				}
				list[j].Play();
			}
		}

		private void ForceSetupAudioSourceAndPlay(AudioData clip)
		{
			AudioSource freeAudioSource = GetFreeAudioSource();
			if (freeAudioSource != null)
			{
				freeAudioSource.ignoreListenerPause = true;
				freeAudioSource.volume = clip.mVolume;
				freeAudioSource.loop = clip.mLoop;
				freeAudioSource.spatialBlend = 0f;
				freeAudioSource.pitch = 1f;
				if (!string.IsNullOrEmpty(clip.mAudioClipLocaKey))
				{
					freeAudioSource.clip = LocalizationManager.GetTranslatedObjectByTermName<AudioClip>(clip.mAudioClipLocaKey);
				}
				else if (clip.mRandom)
				{
					freeAudioSource.clip = clip.mAudioClip[UnityEngine.Random.Range(0, clip.mAudioClip.Length)];
				}
				else
				{
					freeAudioSource.clip = clip.mAudioClip[0];
				}
				freeAudioSource.Play();
			}
		}

