		private AudioSource GetFreeAudioSource()
		{
			for (int i = 0; i < audioSourceSFXChannels.Length; i++)
			{
				if (!audioSourceSFXChannels[i].isPlaying)
				{
					return audioSourceSFXChannels[i];
				}
			}
			UnityEngine.Debug.Log("AudioManager: No free AudioSource");
			return null;
		}

		private AudioSource GetFreeMusicAudioSource()
		{
			for (int i = 0; i < audioSourceMusicChannels.Length; i++)
			{
				if (audioSourceMusicChannels[i].clip == null || !audioSourceMusicChannels[i].isPlaying)
				{
					return audioSourceMusicChannels[i];
				}
			}
			return null;
		}

		public void PlayMusic(AudioData.AudioClipName clip, bool stopOthers)
		{
			AudioData audioData = mAudioDataMusicList.Find((AudioData m) => m.mAudioClipName == clip);
			if (audioData != null)
			{
				for (int i = 0; i < audioSourceMusicChannels.Length; i++)
				{
					bool flag = stopOthers;
					if (audioSourceMusicChannels[i].clip == null || !audioSourceMusicChannels[i].isPlaying)
					{
						continue;
					}
					for (int j = 0; j < audioData.mAudioClip.Length; j++)
					{
						if (audioSourceMusicChannels[i].clip.name == audioData.mAudioClip[j].name)
						{
							if (!stopOthers)
							{
								return;
							}
							flag = false;
							break;
						}
					}
					if (flag)
					{
						AudioSource source = audioSourceMusicChannels[i];
						TweenTG.TweenTo(source, AudioSourceFloat.Volume, 0f, 1f, Easing.Mode.CubicIn, delegate
						{
							source.Stop();
						});
						hasStoppedByScript = true;
					}
				}
				SetupMusicAudioSourceAndPlay(audioData);
				currentMusicData = clip;
				hasStoppedByScript = false;
			}
			else
			{
				if (!stopOthers)
				{
					return;
				}
				for (int k = 0; k < audioSourceMusicChannels.Length; k++)
				{
					AudioSource source2 = audioSourceMusicChannels[k];
					TweenTG.TweenTo(source2, AudioSourceFloat.Volume, 0f, 1f, Easing.Mode.CubicIn, delegate
					{
						source2.Stop();
					});
				}
			}
		}

		public void ForcePlayMusic(AudioData.AudioClipName clip, bool stopOthers)
		{
			AudioData audioData = mAudioDataMusicList.Find((AudioData m) => m.mAudioClipName == clip);
			if (audioData != null)
			{
				for (int i = 0; i < audioSourceMusicChannels.Length; i++)
				{
					bool flag = stopOthers;
					if (audioSourceMusicChannels[i].clip == null || !audioSourceMusicChannels[i].isPlaying)
					{
						continue;
					}
					for (int j = 0; j < audioData.mAudioClip.Length; j++)
					{
						if (audioSourceMusicChannels[i].clip.name == audioData.mAudioClip[j].name)
						{
							if (!stopOthers)
							{
								return;
							}
							flag = false;
							break;
						}
					}
					if (flag)
					{
						AudioSource obj = audioSourceMusicChannels[i];
						obj.ignoreListenerPause = true;
						obj.Stop();
						hasStoppedByScript = true;
					}
				}
				ForceSetupMusicAudioSourceAndPlay(audioData);
				currentMusicData = clip;
				hasStoppedByScript = false;
			}
			else
			{
				if (!stopOthers)
				{
					return;
				}
				for (int k = 0; k < audioSourceMusicChannels.Length; k++)
				{
					AudioSource source = audioSourceMusicChannels[k];
					TweenTG.TweenTo(source, AudioSourceFloat.Volume, 0f, 1f, Easing.Mode.CubicIn, delegate
					{
						source.Stop();
					});
				}
			}
		}

		public void StopMusic(AudioData.AudioClipName musicClipName)
		{
			AudioData audioData = mAudioDataMusicList.Find((AudioData a) => a.mAudioClipName == musicClipName);
			if (audioData == null)
			{
				return;
			}
			List<string> clipNames = new List<string>();
			for (int i = 0; i < audioData.mAudioClip.Length; i++)
			{
				clipNames.Add(audioData.mAudioClip[i].name);
			}
			if (clipNames.Count == 0)
			{
				return;
			}
			AudioSource targetChannel = audioSourceMusicChannels.Find((AudioSource c) => c.isPlaying && c.clip != null && clipNames.Contains(c.clip.name));
			if (targetChannel != null)
			{
				TweenTG.TweenTo(targetChannel, AudioSourceFloat.Volume, 0f, 1f, Easing.Mode.CubicIn, delegate
				{
					targetChannel.Stop();
				});
			}
			hasStoppedByScript = true;
		}

		public void ForceStopMusic(AudioData.AudioClipName musicClipName)
		{
			AudioData audioData = mAudioDataMusicList.Find((AudioData a) => a.mAudioClipName == musicClipName);
			if (audioData == null)
			{
				return;
			}
			List<string> clipNames = new List<string>();
			for (int i = 0; i < audioData.mAudioClip.Length; i++)
			{
				clipNames.Add(audioData.mAudioClip[i].name);
			}
			if (clipNames.Count == 0)
			{
				return;
			}
			AudioSource targetChannel = audioSourceMusicChannels.Find((AudioSource c) => c.isPlaying && c.clip != null && clipNames.Contains(c.clip.name));
			if (targetChannel != null)
			{
				targetChannel.ignoreListenerPause = false;
				TweenTG.TweenTo(targetChannel, AudioSourceFloat.Volume, 0f, 1f, Easing.Mode.CubicIn, delegate
				{
					targetChannel.Stop();
				});
			}
			hasStoppedByScript = true;
		}

		public void StopMusic()
		{
			for (int i = 0; i < audioSourceMusicChannels.Length; i++)
			{
				if (audioSourceMusicChannels[i].isPlaying)
				{
					int idx = i;
					TweenTG.TweenTo(audioSourceMusicChannels[i], AudioSourceFloat.Volume, 0f, -1f, Easing.Mode.CubicIn, delegate
					{
						audioSourceMusicChannels[idx].Stop();
					});
				}
			}
			hasStoppedByScript = true;
		}

		private void SetupMusicAudioSourceAndPlay(AudioData clip)
		{
			AudioSource freeMusicAudioSource = GetFreeMusicAudioSource();
			if (freeMusicAudioSource != null)
			{
				freeMusicAudioSource.volume = clip.mVolume;
				freeMusicAudioSource.loop = clip.mLoop;
				freeMusicAudioSource.pitch = 1f;
				if (clip.mRandom)
				{
					if (clip.mAudioClipName == AudioData.AudioClipName.MusicTempleFate2)
					{
						for (int i = 0; i < clip.mAudioClip.Length; i++)
						{
							if (freeMusicAudioSource.clip == clip.mAudioClip[i])
							{
								currentIndex = i;
								break;
							}
						}
						freeMusicAudioSource.clip = clip.mAudioClip[(currentIndex + 1) % clip.mAudioClip.Length];
						currentIndex++;
					}
					else
					{
						freeMusicAudioSource.clip = clip.mAudioClip[UnityEngine.Random.Range(0, clip.mAudioClip.Length)];
					}
				}
				else
				{
					freeMusicAudioSource.clip = clip.mAudioClip[0];
				}
				freeMusicAudioSource.Play();
				TweenTG.Tween(freeMusicAudioSource, AudioSourceFloat.Volume, 0f, clip.mVolume, 1f, Easing.Mode.QuarticOut);
			}
			else
			{
				UnityEngine.Debug.Log("SetupMusicAudioSourceAndPlay _AudioSource == null for " + clip.mAudioClipName);
			}
		}

		private void ForceSetupMusicAudioSourceAndPlay(AudioData clip)
		{
			AudioSource freeMusicAudioSource = GetFreeMusicAudioSource();
			if (freeMusicAudioSource != null)
			{
				freeMusicAudioSource.volume = clip.mVolume;
				freeMusicAudioSource.loop = clip.mLoop;
				freeMusicAudioSource.pitch = 1f;
				if (clip.mRandom)
				{
					freeMusicAudioSource.clip = clip.mAudioClip[UnityEngine.Random.Range(0, clip.mAudioClip.Length)];
				}
				else
				{
					freeMusicAudioSource.clip = clip.mAudioClip[0];
				}
				freeMusicAudioSource.ignoreListenerPause = true;
				freeMusicAudioSource.Play();
			}
			else
			{
				UnityEngine.Debug.Log("SetupMusicAudioSourceAndPlay _AudioSource == null for " + clip.mAudioClipName);
			}
		}

		private void OnValidate()
		{
			for (int i = 0; i < mAudioDataSFXList?.Length; i++)
			{
				mAudioDataSFXList[i].editorName = mAudioDataSFXList[i].mAudioClipName.ToString();
			}
			for (int j = 0; j < mAudioDataMusicList?.Length; j++)
			{
				mAudioDataMusicList[j].editorName = mAudioDataMusicList[j].mAudioClipName.ToString();
			}
		}

		public bool IsMusicPlaying()
		{
			for (int i = 0; i < audioSourceMusicChannels.Length; i++)
			{
				if (audioSourceMusicChannels[i].isPlaying)
				{
					return true;
				}
			}
			return false;
		}
	}
