		private int allItemsGameVersionIndex = -1;

		private List<ItemData> _allItemsCurrentGame;

		public List<ItemData> AllItems
		{
			get
			{
				if (allItemsGameVersionIndex == -1 || Fate.CurrentFateVer != (Fate.FateVer)allItemsGameVersionIndex)
				{
					if (_allItemsCurrentGame == null)
					{
						_allItemsCurrentGame = new List<ItemData>();
					}
					else
					{
						_allItemsCurrentGame.Clear();
					}
					_allItemsCurrentGame.AddRange(allItems);
					ItemDisallows itemDisallows = GetDisallowsByGame(Fate.CurrentFateVer);
					if (itemDisallows.disallowedTypes.Length != 0)
					{
						_allItemsCurrentGame.RemoveAll((ItemData data) => itemDisallows.disallowedTypes.Contains(data.itemType));
					}
					if (itemDisallows.disallowedItemDatas.Length != 0)
					{
						_allItemsCurrentGame.RemoveAll((ItemData data) => itemDisallows.disallowedItemDatas.Contains(data));
					}
					allItemsGameVersionIndex = (int)Fate.CurrentFateVer;
				}
				return _allItemsCurrentGame;
			}
		}

