		public ItemDisallows GetDisallowsByGame(Fate.FateVer version)
		{
			return version switch
			{
				Fate.FateVer.Original => fate1ItemDisallows, 
				Fate.FateVer.UndiscoveredRealms => fate2ItemDisallows, 
				Fate.FateVer.TraitorSoul => fate3ItemDisallows, 
				Fate.FateVer.CursedKing => fate4ItemDisallows, 
				_ => throw new Exception($"Item disallows not found for {version}"), 
			};
		}

