		public GameObject GetItemPrefab(Item item, string path)
		{
			bool flag = true;
			string text = null;
			switch (item.category)
			{
			case ItemCategory.Item:
				switch (item.itemType)
				{
				case ItemType.Spell:
					text = "SpellScroll";
					flag = true;
					break;
				case ItemType.Gem:
					flag = true;
					text = item.itemData.IconName;
					break;
				case ItemType.Potion:
				case ItemType.Scroll:
				case ItemType.Book:
				case ItemType.EndUrn:
				case ItemType.EndHammer:
					flag = true;
					break;
				case ItemType.PetFood:
					flag = (item.itemData.reserved ? true : false);
					break;
				case ItemType.FishingPole:
				case ItemType.Tarot:
					flag = false;
					break;
				default:
					UnityEngine.Debug.Log("Unhandled Item drop: " + item.itemBaseName);
					flag = false;
					break;
				}
				break;
			case ItemCategory.Jewelry:
				flag = false;
				break;
			case ItemCategory.Key:
				flag = true;
				text = "Key";
				break;
			case ItemCategory.Weapon:
				flag = true;
				break;
			case ItemCategory.Armor:
				flag = item.itemType == ItemType.Shield;
				break;
			default:
				return itemPrefabs[0];
			}
			if (!flag)
			{
				string cat = item.itemType.ToString().ToLower();
				GameObject gameObject = itemPrefabs.Find((GameObject a) => a.name.Replace("P_", "").ToLower() == cat);
				if (!(gameObject != null))
				{
					return itemPrefabs[0];
				}
				return gameObject;
			}
			string find = ((!string.IsNullOrEmpty(text)) ? text : path);
			GameObject gameObject2 = itemPrefabs.Find((GameObject a) => a.name.Replace("P_", "").ToLower() == find.ToLower());
			if (gameObject2 == null)
			{
				UnityEngine.Debug.LogError("FateDB.GetItemPrefab: Prefab for item with name " + find + " is null. Defaulting to itemPrefabs[0].");
			}
			if (!(gameObject2 != null))
			{
				return itemPrefabs[0];
			}
			return gameObject2;
		}

		public GameObject GetItemPrefabExact(string exactName)
		{
			GameObject obj = itemPrefabs.Find((GameObject a) => a.name.Replace("P_", "").ToLower() == exactName.ToLower());
			if (obj == null)
			{
				UnityEngine.Debug.LogError("FateDB.GetItemPrefabExact: Prefab for item with exact name " + exactName + " is null. This could cause exceptions.");
			}
			return obj;
		}

		public GameObject GetContainerPrefab(string name)
		{
			string splitName = name;
			if (name.Split('_').Length > 1)
			{
				splitName = name.Split('_')[1];
			}
			if (splitName.Contains("Chest") && !splitName.Contains("Small") && !splitName.Contains("Large"))
			{
				splitName = "Medium" + splitName;
			}
			if (splitName.Contains("Urn"))
			{
				List<GameObject> list = new List<GameObject>();
				GameObject[] array = containerPrefabs;
				foreach (GameObject gameObject in array)
				{
					if (gameObject.name.Contains("Urn"))
					{
						list.Add(gameObject);
					}
				}
				int index = UnityEngine.Random.Range(0, list.Count);
				return list[index];
			}
			GameObject gameObject2 = containerPrefabs.Find((GameObject a) => a.name.Split('_')[1] == splitName);
			if (!(gameObject2 != null))
			{
				return null;
			}
			return gameObject2;
		}

		public GameObject GetMerchantPrefab(MerchantType merchantType, RealmData.RealmId specificRealm)
		{
			TravelingMerchantsPerRealm[] array = merchantPrefabs;
			foreach (TravelingMerchantsPerRealm travelingMerchantsPerRealm in array)
			{
				if (travelingMerchantsPerRealm.realmVersion == specificRealm && travelingMerchantsPerRealm.merchantPrefab.TryGetComponent<Merchant>(out var component) && component.merchantType == merchantType)
				{
					return travelingMerchantsPerRealm.merchantPrefab;
				}
			}
			return null;
		}

		public GameObject GetParticlePrefab(string name)
		{
			if (string.IsNullOrEmpty(name))
			{
				return null;
			}
			GameObject gameObject = particlePrefabs.Find((GameObject a) => string.Equals(a.name, "PS_" + name, StringComparison.OrdinalIgnoreCase));
			if (!(gameObject != null))
			{
				return null;
			}
			return gameObject;
		}

