	[Serializable]
	public class AttackData
	{
		public int toHitBonus;

		public int rarity;

		public float speed = 1f;

		public string animKey;

		public int animIndex;

		public float attackRadius;

		public float strikeRadius;

		public Range damageRange;

		public DamageType damageType;

		public List<EffectData> effectData;

		public AttackData()
		{
		}

		public AttackData(Item sourceItem, bool isInRightHand)
		{
			toHitBonus = sourceItem.toHitBonus;
			rarity = 0;
			speed = Fate.AttackSpeedValues[sourceItem.itemData.speed];
			animKey = (isInRightHand ? sourceItem.itemData.RightWeaponAnimationId[0] : sourceItem.itemData.LeftWeaponAnimationId[0]);
			animIndex = 0;
			attackRadius = sourceItem.attackRadius;
			strikeRadius = sourceItem.strikeRadius;
			damageRange = new Range((int)sourceItem.minimumDamage, (int)sourceItem.maximumDamage);
			damageType = sourceItem.baseDamageType;
			if (sourceItem.effects == null)
			{
				return;
			}
			effectData = new List<EffectData>();
			foreach (KeyValuePair<ActivationType, List<EffectData>> effect in sourceItem.effects)
			{
				effectData.AddRange(effect.Value);
			}
		}

		public int GetDamage()
		{
			return (int)UnityEngine.Random.Range(damageRange.Min, damageRange.Max);
		}

		public float EffectValue(ActivationType activationType, EffectType effectType)
		{
			if (this.effectData == null)
			{
				return 0f;
			}
			EffectData effectData = this.effectData.Find((EffectData a) => a.buffType == effectType);
			if (effectData == null)
			{
				return 0f;
			}
			if (activationType == ActivationType.Usage || effectType == EffectType.PercentPoison)
			{
				return effectData.value;
			}
			if (activationType == ActivationType.Passive)
			{
				return effectData.chance;
			}
			return 0f;
		}
	}
	public class AppliedEffect
	{
		public string sourceSpriteName;

		public EffectData sourceEffect;

		public int value;

		public int value2;

		public int value3;

		public int duration;

		public int level;

		public int itemSlotIndex;

		private int _value;

		public Character source;

		public string Name => sourceEffect.name ?? string.Empty;

		public EffectType BuffType => sourceEffect.buffType;

		public DamageType DamageType => sourceEffect.damageType;

		public bool Permanent
		{
			get
			{
				if (!sourceEffect.permanent)
				{
					return sourceEffect.duration == -1000;
				}
				return true;
			}
		}

		public bool Positive => sourceEffect.IsPositive;

		public bool Exclusive => sourceEffect.exclusive;

		public int Value
		{
			get
			{
				if (_value != 0)
				{
					return _value;
				}
				if (BuffType == EffectType.Summon)
				{
					return value;
				}
				if (value2 != 0 && value2 != value)
				{
					_value = ((value > value2) ? UnityEngine.Random.Range(value2, value + 1) : UnityEngine.Random.Range(value, value2 + 1));
				}
				else
				{
					_value = value;
				}
				return _value;
			}
		}

		public AppliedEffect(EffectData effectSource, int level, Character source, int itemSlotIndex, bool isSpellEffect = false)
		{
			sourceEffect = effectSource;
			this.source = source;
			this.level = level;
			this.itemSlotIndex = itemSlotIndex;
			value = effectSource.value + (int)(effectSource.valueBonus * (float)level);
			value2 = effectSource.value2 + (int)(effectSource.value2Bonus * (float)level);
			value3 = effectSource.value3 + (int)(effectSource.value3Bonus * (float)level);
			if (isSpellEffect)
			{
				EffectValueResult playerEffectValues = GetPlayerEffectValues(effectSource.buffType, value, value2, source, isSpellEffect: true);
				value = playerEffectValues.value;
				value2 = playerEffectValues.value2;
			}
			if (effectSource.permanent || effectSource.duration == -1000 || effectSource.duration == -900)
			{
				duration = effectSource.duration;
				return;
			}
			duration = effectSource.duration;
			duration += (int)(effectSource.durationBonus * (float)level);
			if (duration > 1000)
			{
				UnityEngine.Debug.Log($"Very long duration of applied effect detected. Duration is {duration}. base duration is {effectSource.duration}, bonus duration is {effectSource.durationBonus} multipled by level ({level})");
			}
		}

		public static EffectValueResult GetPlayerEffectValues(EffectType effectType, int originalValue, int originalValue2, Character caster, bool isSpellEffect)
		{
			EffectValueResult effectValueResult = default(EffectValueResult);
			effectValueResult.value = originalValue;
			effectValueResult.value2 = originalValue2;
			EffectValueResult result = effectValueResult;
			if (!isSpellEffect)
			{
				return result;
			}
			if (caster != null && originalValue < 0 && (caster.IsPlayer() || caster.IsPartyMember()) && effectType == EffectType.HPRecharge)
			{
				float num = originalValue;
				num = num * (float)(caster.attributes.Magic + 100) / 100f;
				float num2 = caster.EffectValue(EffectType.PercentDamageBonus);
				float num3 = caster.EffectValue(EffectType.DamageBonus);
				num -= (float)(int)Mathf.Ceil(num * num2 / -100f);
				num -= (float)(int)num3;
				result.value = (int)num;
				float num4 = originalValue2;
				num4 = num4 * (float)(caster.attributes.Magic + 100) / 100f;
				num4 -= (float)(int)Mathf.Ceil(num4 * num2 / -100f);
				num4 -= (float)(int)num3;
				result.value2 = (int)num4;
			}
			return result;
		}

		public AppliedEffect(EffectSave effectSave)
			: this(effectSave.effectData, effectSave.level, null, effectSave.itemSlotIndex)
		{
			duration = effectSave.duration;
			sourceSpriteName = effectSave.sourceSpriteName;
		}
	}
	[Serializable]
	public class EffectSave
	{
		public EffectData effectData;

		public int duration;

		public int level;

