			{
				effectData = effectData,
				duration = duration,
				itemSlotIndex = itemSlotIndex,
				sourceSpriteName = sourceSpriteName
			};
		}
	}
	[Serializable]
	public class EffectData
	{
		public enum TooltipSource
		{
			Item,
			Gem,
			Spell
		}

		public string name;

		public bool exclusive;

		public bool permanent;

		public string applicationMessage;

		public int chance;

		public ActivationType activationType;

		public EffectType buffType;

		public ItemTarget target;

		public int duration;

		public int value;

		public int value2;

		public int value3;

		public float valueBonus;

		public float value2Bonus;

		public float value3Bonus;

		public float durationBonus = 1f;

		public float priceMultiplier = 1f;

		public DamageType damageType;

		public List<VisualEffect> sfx;

		public int sfxDurationBonus;

		public bool IsPositive => MathF.Sign(value) == MathF.Sign(Fate.GetEffectMaximum(buffType));

		public EffectData()
		{
		}

		public EffectData(EffectData reference)
		{
			name = reference.name;
			exclusive = reference.exclusive;
			permanent = reference.permanent;
			applicationMessage = reference.applicationMessage;
			chance = reference.chance;
			activationType = reference.activationType;
			buffType = reference.buffType;
			target = reference.target;
			duration = reference.duration;
			durationBonus = reference.durationBonus;
			value = reference.value;
			value2 = reference.value2;
			value3 = reference.value3;
			valueBonus = reference.valueBonus;
			value2Bonus = reference.value2Bonus;
			value3Bonus = reference.value3Bonus;
			damageType = reference.damageType;
			sfx = reference.sfx;
		}

		public EffectData(EffectType effectType, bool positive, ActivationType aType, int duration, int value, float priceMultiplier)
		{
			buffType = effectType;
			activationType = aType;
			this.duration = duration;
			this.value = value;
			this.priceMultiplier = priceMultiplier;
		}

		public bool AffectsCharacter(Character character)
		{
			return true;
		}

		public override string ToString()
		{
			return $"{activationType.ToString()[0]}: {buffType} {value}";
		}

		public string GenerateTooltipString(TooltipSource source, int skillBonus = 0, bool isSpellEffect = false)
		{
			EffectType effectType = buffType;
			bool flag = effectType == EffectType.HPRecharge || effectType == EffectType.ManaRecharge || effectType == EffectType.StaminaRecharge;
			bool flag2 = !permanent && duration != 0 && duration != -900 && duration != -1000;
			if (buffType == EffectType.HPRecharge)
			{
				_ = value < 0;
			}
			else
				_ = 0;
			bool flag3 = Fate.EffectIsPercent(buffType);
			int num = value + Mathf.CeilToInt(valueBonus * (float)skillBonus);
			if (flag && flag2)
			{
				num = Mathf.CeilToInt((float)num / 60f);
			}
			int originalValue = value2 + Mathf.CeilToInt(value2Bonus * (float)skillBonus);
			if (isSpellEffect)
			{
				EffectValueResult playerEffectValues = AppliedEffect.GetPlayerEffectValues(buffType, num, originalValue, Player.PlayerChar, isSpellEffect: true);
				num = Mathf.Abs(playerEffectValues.value);
				originalValue = Mathf.Abs(playerEffectValues.value2);
			}
			string text = originalValue.ToString();
			string text2 = (Mathf.Abs(value3) + Mathf.CeilToInt(Mathf.Abs(value3Bonus) * (float)skillBonus)).ToString();
			string text3 = (((duration != 0 && duration != -900) || value2 == 0 || value2 == value) ? ((flag3 && num < 0 && source == TooltipSource.Spell) ? Mathf.Clamp(num, -100, 100) : num).ToString() : $"{num}-{text}");
			bool flag4 = num == 0;
			if (buffType == EffectType.RevertTransform)
			{
				return I2Loca.GetIgnoreLinebreaks("Tooltip_ReturnsPetToOriginalForm");
			}
			if (buffType == EffectType.Transform)
			{
				string ignoreLinebreaksFormat = I2Loca.GetIgnoreLinebreaksFormat("Tooltip_TransformsPetInto", I2Loca.Get(name));
				if (value == -1)
				{
					return I2Loca.GetFormat("Tooltip_TransformPermanently", ignoreLinebreaksFormat);
				}
				return I2Loca.GetFormat("Tooltip_TransformForSeconds", ignoreLinebreaksFormat, value.ToString());
			}
			if (buffType == EffectType.WriteSpell)
			{
				SpellData spellData = SingletonBehaviour<FateDB>.Instance.allSpells.Find((SpellData s) => s.spellName == name);
				if (spellData.effects != null && spellData.effects.Count > 0 && spellData.effects[0].buffType == EffectType.OpenPortal && spellData.sphereType == SpellSphere.Charm)
				{
					_ = spellData.effects[0];
					return I2Loca.GetMultiLineFormat(spellData.description, I2Loca.Get($"RealmName_{SingletonBehaviour<PlayerStatus>.Instance.TownRealm}"));
				}
				return I2Loca.GetMultiLineReplaceTags(spellData.description);
			}
			if (buffType == EffectType.Dispel)
			{
				return I2Loca.Get("TooltipDispel");
			}
			if (buffType == EffectType.DispelEnemy)
			{
				return I2Loca.Get("TooltipDispelEnemy");
			}
			if (buffType == EffectType.Flee)
			{
				return I2Loca.GetFormat("TooltipIfLevelIsBelow", I2Loca.Get("DescFlee"), text3);
			}
			if (buffType == EffectType.Discover)
			{
				return I2Loca.GetFormat("TooltipIfDungeonLevelEqualOrAbove", I2Loca.Get("DescDiscover"), text3);
			}
			if (source == TooltipSource.Spell && buffType == EffectType.OpenPortal)
			{
				return I2Loca.GetFormat("TooltipIfDungeonLevelEqualOrAbove", I2Loca.Get("Item_DescriptionOpenTownPortal"), text3);
			}
			if (buffType == EffectType.Identify)
			{
				return I2Loca.GetFormat("TooltipIdentificationLevelEqualAndBelow", I2Loca.Get("DescIdentify"), text3);
			}
			if (buffType == EffectType.TurnAlignment)
			{
				return I2Loca.GetFormat("TooltipOfLevelEqualAndBelow", I2Loca.Get("DescTurnAlignment"), text3);
			}
			if (buffType == EffectType.Summon)
			{
				return I2Loca.GetFormat("TooltipOfLevelForSeconds", I2Loca.Get("DescSummon"), text, text2);
			}
			string text4 = ((flag4 || source == TooltipSource.Gem) ? "" : (flag3 ? text3 : (text3 + " "))) + I2Loca.Get(IsPositive ? Fate.GetEffectPositiveDesc(buffType) : Fate.GetEffectNegativeDesc(buffType));
			if (flag && flag2)
			{
				text4 += I2Loca.GetFormat("TooltipPerSecond", "");
			}
			return text4;
		}
	}
