		public void Parse(string monsterString)
		{
			rawData = monsterString;
			string[] array = monsterString.Split("\n");
			merchantMaximum = 32000;
			uses = -9999;
			itemEffects = new List<EffectData>();
			realmData = new List<RealmOverrideData>();
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = false;
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text))
				{
					if (text.Contains("[/EFFECT]"))
					{
						flag = false;
						itemEffects.Add(FateParseHelper.ParseEffect(stringBuilder.ToString()));
						stringBuilder.Length = 0;
					}
					else if (text.Contains("[EFFECT]"))
					{
						flag = true;
					}
					else if (text.Contains("[/REALMINFO]"))
					{
						flag = false;
						realmData.Add(ParseRealmData(stringBuilder.ToString()));
						stringBuilder.Length = 0;
					}
					else if (text.Contains("[REALMINFO]"))
					{
						flag = true;
					}
					else if (flag)
					{
						stringBuilder.AppendLine(text);
					}
					else
					{
						ParseKVPLine(text);
					}
				}
			}
		}

		private RealmOverrideData ParseRealmData(string realmData)
		{
			RealmOverrideData realmOverrideData = new RealmOverrideData();
			string[] array = realmData.Split('\n');
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text))
				{
					string text2 = text.Substring(text.IndexOf('<') + 1, text.IndexOf('>') - 1).ToUpper();
					string text3 = text;
					int num = text.IndexOf(':') + 1;
					string rawValue = text3.Substring(num, text3.Length - num).Trim('\r');
					switch (text2)
					{
					case "ID":
						realmOverrideData.realmId = FateParseHelper.ParseInt(rawValue);
						break;
					case "RARITY":
						realmOverrideData.rarity = FateParseHelper.ParseInt(rawValue);
						break;
					case "MINIMUM_DEPTH":
						realmOverrideData.minimumDepth = FateParseHelper.ParseInt(rawValue);
						break;
					case "MAXIMUM_DEPTH":
						realmOverrideData.maximumDepth = FateParseHelper.ParseInt(rawValue);
						break;
					default:
						UnityEngine.Debug.LogWarning("Unhandled key: " + text2);
						break;
					}
				}
			}
			return realmOverrideData;
		}

		private void ParseKVPLine(string line)
		{
			try
			{
				string text = line.Substring(line.IndexOf('<') + 1, line.IndexOf('>') - 1).ToUpper();
				string text2 = line;
				int num = line.IndexOf(':') + 1;
				string text3 = text2.Substring(num, text2.Length - num).Trim('\r');
				switch (text)
				{
				case "TYPE":
					itemType = FateParseHelper.ParseEnum<ItemType>(text3);
					if (itemType == ItemType.None)
					{
						UnityEngine.Debug.LogError("MISSED TYPE: " + text3);
					}
					break;
				case "NAME":
					displayName = text3;
					break;
				case "REFID":
					refId = text3;
					break;
				case "DESCRIPTION":
					description = text3;
					break;
				case "ARMOR":
					armorRange = FateParseHelper.ParseRange(text3);
					break;
				case "RARITY":
					rarity = FateParseHelper.ParseInt(text3);
					break;
				case "MERCHANT_MINIMUM":
					merchantMinimum = FateParseHelper.ParseInt(text3);
					break;
				case "MERCHANT_MAXIMUM":
					merchantMaximum = FateParseHelper.ParseInt(text3);
					break;
				case "FISHING_RARITY":
					fishingRarity = FateParseHelper.ParseInt(text3);
					break;
				case "MINIMUM_FISHING_DEPTH":
					minimumFishingDepth = FateParseHelper.ParseInt(text3);
					break;
				case "MAXIMUM_FISHING_DEPTH":
					maximumFishingDepth = FateParseHelper.ParseInt(text3);
					break;
				case "VALUE":
					value = FateParseHelper.ParseInt(text3);
					break;
				case "DAMAGE":
					damageRange = FateParseHelper.ParseRange(text3);
					break;
				case "DAMAGE_BONUS":
					if (damageBonuses == null)
					{
						damageBonuses = new List<ElementAmount>();
					}
					damageBonuses.Add(FateParseHelper.ParseElementValue(text3));
					break;
				case "ATTACK_RADIUS":
					attackRadius = FateParseHelper.ParseFloat(text3);
					break;
				case "STRIKE_RADIUS":
					strikeRadius = FateParseHelper.ParseFloat(text3);
					break;
				case "SPEED":
					speed = FateParseHelper.ParseEnum<Speed>(text3);
					break;
				case "RESERVED":
					reserved = FateParseHelper.ParseBool(text3);
					break;
				case "FORCEPICKUPHOLD":
					forcePickupHold = FateParseHelper.ParseBool(text3);
					break;
				case "AUTOPICKUP":
					autoPickup = FateParseHelper.ParseBool(text3);
					break;
				case "DESTRUCTIBLE":
					destructible = FateParseHelper.ParseBool(text3);
					break;
				case "TAROTFLAVOR":
					tarotFlavour = FateParseHelper.ParseInt(text3) + 1;
					break;
				case "TAROTLEVEL":
					tarotLevel = FateParseHelper.ParseInt(text3);
					break;
				case "SHADOW":
					hasShadow = FateParseHelper.ParseBool(text3);
					break;
				case "COLLIDEABLE":
					collision = FateParseHelper.ParseBool(text3);
					break;
				case "TAKEABLE":
					takeable = FateParseHelper.ParseBool(text3);
					break;
				case "USEABLE":
					usable = FateParseHelper.ParseBool(text3);
					break;
				case "TARGET":
					itemTarget = FateParseHelper.ParseEnum<ItemTarget>(text3);
					break;
				case "USES":
					uses = FateParseHelper.ParseInt(text3);
					break;
				case "SOCKETS":
					sockets = FateParseHelper.ParseInt(text3);
					break;
				case "ARTIFACT":
					artifact = FateParseHelper.ParseBool(text3);
					break;
				case "EXPANSION":
					expansion = FateParseHelper.ParseBool(text3);
					break;
				case "UNVENDABLE":
					notSellable = FateParseHelper.ParseBool(text3);
					break;
				case "PURCHASABLE":
				case "PURCHASEABLE":
					notPurchasable = !FateParseHelper.ParseBool(text3);
					break;
				case "MINIMUM_DEPTH":
					minimumDepth = FateParseHelper.ParseInt(text3);
					break;
				case "MAXIMUM_DEPTH":
					maximumDepth = FateParseHelper.ParseInt(text3);
					break;
				case "MODEL":
					modelPath = text3;
					break;
				case "ANIMATED_MODEL":
					animatedModelPath = text3;
					break;
				case "ICON":
				{
					iconPath = text3;
					num = (text2 = iconPath.Split(':')[0]).LastIndexOf('/') + 1;
					string text4 = text2.Substring(num, text2.Length - num);
					iconName = text4.Substring(0, text4.IndexOf('.'));
					break;
				}
				case "DROP_SOUND":
					dropSoundPath = text3;
					break;
				case "TAKE_SOUND":
					takeSoundPath = text3;
					break;
				case "LAND_SOUND":
					landSoundPath = text3;
					break;
				case "MISS_SOUND":
					missSoundPath = text3;
					break;
				case "STRIKE_SOUND":
					AddElementToList(ref strikeSoundPaths, text3);
					break;
				case "ATTACK_SOUND":
					AddElementToList(ref attackSoundPaths, text3);
					break;
				case "USE_SOUND":
					useSoundPath = text3;
					break;
				case "AMBIENT_SOUND":
					ambientSoundPath = text3;
					break;
				case "ACTIVATE_SOUND":
					AddElementToList(ref activateSoundPaths, text3);
					break;
				case "DEACTIVATE_SOUND":
					deactivateSoundPath = text3;
					break;
				case "IDENTIFIED":
					identified = FateParseHelper.ParseBool(text3);
					break;
				case "SFX":
					if (sfx == null)
					{
						sfx = new List<VisualEffect>();
					}
					sfx.Add(FateParseHelper.ParseVisualFX(text3));
					break;
				case "REQUIRES":
					if (requirements == null)
					{
						requirements = new List<AttributeData>();
					}
					requirements.Add(FateParseHelper.ParseAttributeData(text3));
					break;
				case "LIGHT":
					lightRaw = text3;
					break;
				default:
					UnityEngine.Debug.LogWarning("Unhandled key: " + text);
					break;
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("Exception parsing line: " + line);
				throw ex;
			}
			static void AddElementToList(ref List<string> targetList, string value)
			{
				if (targetList == null)
				{
					targetList = new List<string>();
				}
				targetList.Add(value);
			}
		}
	}
	public class MerchantData : SingletonBehaviour<MerchantData>
	{
		public static Action onDataUpdated;

		private Randomizer fishMerchantItemGenerator;

		private Randomizer gamblerMerchantItemGenerator;

		private Randomizer travelingMerchantItemGenerator;

		private Randomizer goodsMerchantItemGenerator;

		private Randomizer weaponsMerchantItemGenerator;

		private Randomizer armorMerchantItemGenerator;

		private Randomizer magicMerchantItemGenerator;

		private Randomizer jewelerMerchantItemGenerator;

		private Randomizer potionsMerchantItemGenerator;

		private Randomizer gemRandomizer;

		private Randomizer potionRandomizer;

		private Randomizer bookRandomizer;

		private Randomizer scrollRandomizer;

		private Randomizer fishPoleRandomizer;

		private Randomizer petFoodRandomizer;

		private Randomizer heroRewardRandomizer;

		private List<ItemData> itemDataManifest;

		private ItemData townPortalScoll;

		protected override bool DontDestroy => true;

		public int DepthUpdatedOn { get; set; }

		protected override void Init()
		{
			DepthUpdatedOn = -1;
			RefreshRandomGenerators();
		}

		private void RefreshRandomGenerators()
		{
			fishMerchantItemGenerator = new Randomizer();
			gamblerMerchantItemGenerator = new Randomizer();
			travelingMerchantItemGenerator = new Randomizer();
			goodsMerchantItemGenerator = new Randomizer();
			weaponsMerchantItemGenerator = new Randomizer();
			armorMerchantItemGenerator = new Randomizer();
			magicMerchantItemGenerator = new Randomizer();
			jewelerMerchantItemGenerator = new Randomizer();
			potionsMerchantItemGenerator = new Randomizer();
			gemRandomizer = new Randomizer();
			potionRandomizer = new Randomizer();
			bookRandomizer = new Randomizer();
			scrollRandomizer = new Randomizer();
			fishPoleRandomizer = new Randomizer();
			petFoodRandomizer = new Randomizer();
			heroRewardRandomizer = new Randomizer();
			itemDataManifest = new List<ItemData>();
			itemDataManifest.AddRange(SingletonBehaviour<FateDB>.Instance.AllItems);
		}

		public ItemData FindRandomItemByType(ItemType itemType)
		{
			switch (itemType)
			{
			case ItemType.FishingPole:
			{
				int random = fishPoleRandomizer.GetRandom();
				if (random == -1)
				{
					return null;
				}
				return itemDataManifest[random];
			}
			case ItemType.Book:
			{
				int random = bookRandomizer.GetRandom();
				if (random == -1)
				{
					return null;
				}
				return itemDataManifest[random];
			}
			case ItemType.Scroll:
			{
				int random = scrollRandomizer.GetRandom();
				if (random == -1)
				{
					return null;
				}
				return itemDataManifest[random];
			}
			case ItemType.Gem:
