		public void UpdateRandomizerTables()
		{
			RefreshRandomGenerators();
			if (!Fate.DifficultyMod.TryGetValue(SingletonBehaviour<PlayerStatus>.Instance.Difficulty, out var value))
			{
				return;
			}
			int num = ActiveLevel.DigGreedilyAfterDeepestDepthReached();
			if (Player.PlayerChar != null)
			{
				num += Player.PlayerChar.Level / 3;
			}
			int num2 = Mathf.Max(num, 1);
			int num3 = Mathf.CeilToInt((float)num2 * value.itemMultiplier);
			if (num2 < 5)
			{
				num2 = 5;
			}
			int num4 = 0;
			foreach (ItemData item in itemDataManifest)
			{
				if (!item.reserved && !item.notPurchasable)
				{
					if (item.minimumDepth <= num3 && (item.maximumDepth <= 0 || item.maximumDepth >= num3))
					{
						int num5 = 1000 - item.rarity;
						if (num5 < 0)
						{
							num5 = 0;
						}
						if (num5 > 0)
						{
							if (item.takeable && item.itemType == ItemType.Gem)
							{
								gemRandomizer.AddChoice(num4, num5);
							}
							if (item.itemType == ItemType.Potion)
							{
								potionRandomizer.AddChoice(num4, num5);
							}
							if (item.itemType == ItemType.Book)
							{
								bookRandomizer.AddChoice(num4, num5);
							}
							if (item.itemType == ItemType.Scroll)
							{
								scrollRandomizer.AddChoice(num4, num5);
							}
							if (item.itemType == ItemType.FishingPole)
							{
								fishPoleRandomizer.AddChoice(num4, num5);
							}
							if (item.itemType == ItemType.PetFood)
							{
								petFoodRandomizer.AddChoice(num4, num5);
							}
						}
					}
					if (item.takeable && item.itemType == ItemType.Gem)
					{
						int num6 = 1000 - item.rarity;
						if (num6 < 0)
						{
							num6 = 0;
						}
						bool flag = item.minimumDepth > 3 || num6 < 99;
						if (num6 > 0 && flag)
						{
							heroRewardRandomizer.AddChoice(num4, num6);
						}
					}
				}
				if (item.takeable && item.itemType != ItemType.Tarot && !item.reserved && item.itemType != ItemType.FishingPole)
				{
					int num7 = 100;
					if (item.itemType == ItemType.Gem)
					{
						num7 = 95;
					}
					int num8 = num2;
					num8 -= 10;
					if (num8 < 1)
					{
						num8 = 1;
					}
					if (item.itemType == ItemType.PetFood && item.itemType == ItemType.PetFood && !item.notSellable && num8 >= item.minimumDepth && (item.maximumDepth == 0 || num8 + 1 < item.maximumDepth))
					{
						num7 = 98;
						fishMerchantItemGenerator.AddChoice(num4, num7);
					}
					if (item.notPurchasable)
					{
						num7 = 0;
					}
					if ((item.ItemCategory == ItemCategory.Weapon || item.ItemCategory == ItemCategory.Armor || item.ItemCategory == ItemCategory.Jewelry) && item.merchantMaximum >= num2 && item.merchantMinimum <= num2 + 3)
					{
						gamblerMerchantItemGenerator.AddChoice(num4, num7);
					}
					if (item.merchantMaximum >= num2 && item.merchantMinimum <= num2 + 2)
					{
						travelingMerchantItemGenerator.AddChoice(num4, num7);
					}
					if (item.ItemCategory != ItemCategory.Weapon && item.ItemCategory != ItemCategory.Armor && item.itemType != ItemType.Spell && item.itemType != ItemType.Necklace && item.itemType != ItemType.Ring && item.merchantMaximum >= num2 && item.merchantMinimum <= num2)
					{
						if (item.itemType == ItemType.Gem)
						{
							num7 /= 5;
						}
						goodsMerchantItemGenerator.AddChoice(num4, num7);
					}
					if (item.ItemCategory == ItemCategory.Weapon && item.merchantMaximum >= num2 && item.merchantMinimum <= num2)
					{
						weaponsMerchantItemGenerator.AddChoice(num4, num7);
					}
					if ((item.ItemCategory == ItemCategory.Weapon || item.ItemCategory == ItemCategory.Armor) && item.merchantMaximum >= num2 && item.merchantMinimum <= num2)
					{
						armorMerchantItemGenerator.AddChoice(num4, num7);
					}
					if ((item.itemType == ItemType.Potion || item.itemType == ItemType.Scroll || item.itemType == ItemType.Spell || item.itemType == ItemType.Staff || item.itemType == ItemType.Gem || item.itemType == ItemType.Necklace || item.itemType == ItemType.Ring || item.itemType == ItemType.PetFood || item.itemType == ItemType.Book) && item.merchantMaximum >= num2 && item.merchantMinimum <= num2 + 5)
					{
						magicMerchantItemGenerator.AddChoice(num4, num7);
					}
					if (item.ItemCategory == ItemCategory.Jewelry && item.merchantMaximum >= num2 && item.merchantMinimum <= num2 + 5)
					{
						jewelerMerchantItemGenerator.AddChoice(num4, num7);
					}
					if ((item.itemType == ItemType.Potion || item.itemType == ItemType.Scroll || item.itemType == ItemType.Book) && item.merchantMaximum >= num2 && item.merchantMinimum <= num2)
					{
						potionsMerchantItemGenerator.AddChoice(num4, num7);
					}
				}
				if (item.itemType == ItemType.Scroll && item.displayName == "Item_TownPortalScroll")
				{
					townPortalScoll = item;
				}
				num4++;
			}
			DepthUpdatedOn = LevelGenerator.effectiveLevelDepth;
			onDataUpdated?.Invoke();
		}

		public ItemData GetTownPortalScollItem()
		{
			return townPortalScoll;
		}
	}
