		public bool ValidForRealm(int targetRealm)
		{
			int num = -1;
			int num2 = 0;
			if (realms != null && realms.Count > 0)
			{
				for (int i = 0; i < realms.Count; i++)
				{
					if (realms[i] == num || realms[i] == num2 || realms[i] == targetRealm)
					{
						return true;
					}
					if (targetRealm == 4 && (realms[i] == 1 || realms[i] == 2 || realms[i] == 5))
					{
						return true;
					}
				}
				return false;
			}
			return true;
		}

		public bool CanEquip(ItemType itemType)
		{
			if (canEquip == null)
			{
				return false;
			}
			if (canEquip.Contains("ALL"))
			{
				return true;
			}
			for (int i = 0; i < canEquip.Count; i++)
			{
				if (canEquip[i] == itemType.ToString().ToUpper())
				{
					return true;
				}
			}
			return false;
		}

		public bool CanEquip(ItemSlot itemSlot)
		{
			if (canEquip == null)
			{
				return false;
			}
			if (canEquip.Contains("ALL"))
			{
				return true;
			}
			for (int i = 0; i < canEquip.Count; i++)
			{
				ItemType itemType = (ItemType)Enum.Parse(typeof(ItemType), canEquip[i], ignoreCase: true);
				switch (itemSlot)
				{
				case ItemSlot.Head:
					if (itemType == ItemType.Helmet)
					{
						return true;
					}
					break;
				case ItemSlot.Chest:
					if (itemType == ItemType.Shirt)
					{
						return true;
					}
					break;
				case ItemSlot.LeftHand:
				case ItemSlot.RightHand:
				case ItemSlot.LeftHand2:
				case ItemSlot.RightHand2:
					if (itemType == ItemType.Sword || itemType == ItemType.Club || itemType == ItemType.Spear || itemType == ItemType.Bow || itemType == ItemType.Polearm || itemType == ItemType.Axe || itemType == ItemType.Hammer || itemType == ItemType.Staff || itemType == ItemType.Crossbow || itemType == ItemType.EndHammer)
					{
						return true;
					}
					break;
				case ItemSlot.LeftArm:
				case ItemSlot.LeftArm2:
					if (itemType == ItemType.Shield)
					{
						return true;
					}
					break;
				}
			}
			return false;
		}

		[ContextMenu("Reparse MonsterData")]
		public void ReParse()
		{
			Parse(rawData);
		}

		public void Parse(string monsterString)
		{
			rawData = monsterString;
			string[] array = monsterString.Split("\n");
			attacks = new List<AttackData>();
			effects = new List<EffectData>();
			realms = new List<int>();
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = false;
			bool flag2 = false;
			bravery = 1f;
			scale.Min = 1f;
			scale.Max = 1f;
			minimumDepth = 1;
			maximumDepth = 100;
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text))
				{
					if (!flag2 && text.Contains("[/EFFECT]"))
					{
						flag = false;
						effects.Add(FateParseHelper.ParseEffect(stringBuilder.ToString()));
						stringBuilder.Length = 0;
					}
					else if (!flag2 && text.Contains("[EFFECT]"))
					{
						flag = true;
					}
					else if (text.Contains("[/UNARMED_ATTACK]"))
					{
						flag2 = false;
						attacks.Add(ParseAttack(stringBuilder.ToString()));
						stringBuilder.Length = 0;
					}
					else if (text.Contains("[UNARMED_ATTACK]"))
					{
						flag2 = true;
					}
					else if (flag2 || flag)
					{
						stringBuilder.AppendLine(text);
					}
					else
					{
						ParseKVPLine(text);
					}
				}
			}
		}

		private AttackData ParseAttack(string attackData)
		{
			AttackData attackData2 = new AttackData();
			string[] array = attackData.Split('\n');
			bool flag = false;
			StringBuilder stringBuilder = new StringBuilder();
			foreach (string text in array)
			{
				if (string.IsNullOrEmpty(text))
				{
					continue;
				}
				if (text.Contains("[/EFFECT]"))
				{
					flag = false;
					if (attackData2.effectData == null)
					{
						attackData2.effectData = new List<EffectData>();
					}
					attackData2.effectData.Add(FateParseHelper.ParseEffect(stringBuilder.ToString()));
					stringBuilder.Length = 0;
					continue;
				}
				if (text.Contains("[EFFECT]"))
				{
					flag = true;
					continue;
				}
				if (flag)
				{
					stringBuilder.AppendLine(text);
					continue;
				}
				string text2 = text.Substring(text.IndexOf('<') + 1, text.IndexOf('>') - 1).ToUpper();
				string text3 = text;
				int num = text.IndexOf(':') + 1;
				string text4 = text3.Substring(num, text3.Length - num).Trim('\r');
				switch (text2)
				{
				case "TOHITBONUS":
					attackData2.toHitBonus = FateParseHelper.ParseInt(text4);
					break;
				case "ANIMATION":
					attackData2.animKey = text4;
					break;
				case "RANGE":
				{
					Range range = FateParseHelper.ParseRange(text4);
					attackData2.attackRadius = range.Min;
					attackData2.strikeRadius = range.Max;
					break;
				}
				case "DAMAGE":
					attackData2.damageRange = FateParseHelper.ParseRange(text4);
					break;
				case "DAMAGE_TYPE":
					attackData2.damageType = FateParseHelper.ParseEnum<DamageType>(text4);
					break;
				}
			}
			return attackData2;
		}

		private void ParseKVPLine(string line)
		{
			try
			{
				string text = line.Substring(line.IndexOf('<') + 1, line.IndexOf('>') - 1).ToUpper();
				int num = line.IndexOf(':') + 1;
				string text2 = line.Substring(num, line.Length - num).Trim('\r');
				switch (text)
				{
				case "FAMILY":
					family = FateParseHelper.ParseEnum<Family>(text2.Replace(" ", ""));
					break;
				case "NAME":
					displayName = text2;
					break;
				case "REFID":
					refId = text2;
					break;
				case "MIMIC_NAME":
					mimicName = text2;
					break;
				case "RARITY":
					rarity = FateParseHelper.ParseInt(text2);
					break;
				case "RESERVED":
					reserved = FateParseHelper.ParseBool(text2);
					break;
				case "BRAVERY":
					bravery = FateParseHelper.ParseFloat(text2);
					break;
				case "BASE_LEVEL":
					baseLevel = FateParseHelper.ParseInt(text2);
					break;
				case "MINIMUM_DEPTH":
					minimumDepth = FateParseHelper.ParseInt(text2);
					break;
				case "MAXIMUM_DEPTH":
					maximumDepth = FateParseHelper.ParseInt(text2);
					break;
				case "ALIGNMENT":
					alignment = FateParseHelper.ParseEnum<Alignment>(text2);
					break;
				case "REALM":
					if (text2.Contains(':'))
					{
						string[] array2 = text2.Split(':');
						for (int i = 0; i < array2.Length; i++)
						{
							realms.Add(FateParseHelper.ParseInt(array2[i]));
						}
					}
					else
					{
						realms.Add(FateParseHelper.ParseInt(text2));
					}
					break;
				case "SCALE":
					scale = FateParseHelper.ParseRange(text2);
					break;
				case "MATERIAL_OVERRIDE":
					materialOverrideRaw = text2;
					break;
				case "WALKING_SPEED":
					walkingSpeed = FateParseHelper.ParseInt(text2);
					break;
				case "RUNNING_SPEED":
					runningSpeed = FateParseHelper.ParseInt(text2);
					break;
				case "TURN_RATE":
					turnRate = FateParseHelper.ParseInt(text2);
					break;
				case "VIEW_RADIUS":
					viewRadius = FateParseHelper.ParseInt(text2);
					break;
				case "MOTION_RADIUS":
					motionRadius = FateParseHelper.ParseInt(text2);
					break;
				case "ATTENTION_RADIUS":
					attentionRadius = FateParseHelper.ParseInt(text2);
					break;
				case "FOLLOW_RADIUS":
					followRadius = FateParseHelper.ParseInt(text2);
					break;
				case "HP":
					hpRange = FateParseHelper.ParseRange(text2);
					break;
				case "NATURAL_ARMOR":
					naturalArmor = FateParseHelper.ParseInt(text2);
					break;
				case "TOHIT":
					toHit = FateParseHelper.ParseInt(text2);
					break;
				case "REACH_BONUS":
					reachBonus = FateParseHelper.ParseInt(text2);
					break;
				case "VERTICAL_OFFSET":
					verticalOffset = FateParseHelper.ParseFloat(text2);
					break;
				case "STRENGTH":
					strength = FateParseHelper.ParseInt(text2);
					break;
				case "DEXTERITY":
					dexterity = FateParseHelper.ParseInt(text2);
					break;
				case "VITALITY":
					vitality = FateParseHelper.ParseInt(text2);
					break;
				case "MAGIC":
					magic = FateParseHelper.ParseInt(text2);
					break;
				case "EXPERIENCE":
					experience = FateParseHelper.ParseInt(text2);
					break;
				case "FREQUENCY":
					frequency = FateParseHelper.ParseInt(text2);
					break;
				case "DEATH_SOUND":
					AddElementToList(ref deathSoundPaths, text2);
					break;
				case "STEP_SOUND":
					AddElementToList(ref stepSoundPaths, text2);
					break;
				case "ATTACK_SOUND":
					AddElementToList(ref attackSoundPaths, text2);
					break;
				case "ARMED_ATTACK_SOUND":
					AddElementToList(ref armedAttackSoundPaths, text2);
					break;
				case "STRIKE_SOUND":
					AddElementToList(ref strikeSoundPaths, text2);
					break;
				case "MISS_SOUND":
					AddElementToList(ref missSoundPaths, text2);
					break;
				case "IDLE_SOUND":
					AddElementToList(ref idleSoundPaths, text2);
					break;
				case "ROAR_SOUND":
					AddElementToList(ref roarSoundPaths, text2);
					break;
				case "BLOOD_PARTICLE":
					bloodParticle = text2;
					break;
				case "DAMAGE_RESISTANCE":
					if (damageResists == null)
					{
						damageResists = new List<ElementAmount>();
					}
					damageResists.Add(FateParseHelper.ParseElementValue(text2));
					break;
				case "MATCH_SPEED":
					matchSpeed = FateParseHelper.ParseBool(text2);
					break;
				case "THROES":
					throes = text2;
					break;
				case "EXPANSION":
					expansion = FateParseHelper.ParseBool(text2);
					break;
				case "LIGHT":
					lightDataRaw = text2;
					break;
				case "CAN_EQUIP":
					AddElementToList(ref canEquip, text2);
					break;
				case "DUAL_WIELDING":
					dualWielding = FateParseHelper.ParseBool(text2);
					break;
				case "PREFERRED_WEAPON":
					AddElementToList(ref preferredWeapons, text2);
					break;
				case "PREFERRED_ARMOR":
					AddElementToList(ref preferredArmors, text2);
					break;
				case "PREFERRED_SHIELD":
					AddElementToList(ref preferredShields, text2);
					break;
				case "SPELL":
					AddElementToList(ref spells, text2);
					break;
				case "SKILL":
					if (skills == null)
					{
						skills = new List<AttributeData>();
					}
					skills.Add(FateParseHelper.ParseAttributeData(text2));
					break;
				case "TACTICS":
					tacticType = FateParseHelper.ParseEnum<TacticType>(text2);
					break;
				case "MINION":
				{
					if (minions == null)
					{
						minions = new List<MinionData>();
					}
					MinionData minionData = new MinionData();
					string[] array = text2.Split(':');
					minionData.name = array[0];
					if (!minionData.name.StartsWith("Monster_"))
					{
						minionData.name = "Monster_" + minionData.name;
					}
					minionData.range = new Range
					{
						Min = FateParseHelper.ParseFloat(array[1]),
						Max = FateParseHelper.ParseFloat(array[2])
					};
					minions.Add(minionData);
					break;
				}
				case "MINIONS_COLLIDE":
					minionsCollide = FateParseHelper.ParseBool(text2);
					break;
				case "SOUND_RADIUS":
					soundRadius = FateParseHelper.ParseInt(text2);
					break;
				case "UNIQUE_IDLE":
					AddElementToList(ref uniqueIdleAnimKeys, text2);
					break;
				case "UNIQUE_IDLE_SOUND":
					AddElementToList(ref uniqueIdleSoundPaths, text2);
					break;
				case "TYPE_TAG":
				case "TYPE_BONUS":
				{
					if (realmTypeBonuses == null)
					{
						realmTypeBonuses = new Dictionary<string, int>();
					}
					(string, int) tuple = FateParseHelper.ParseStringIntKVP(text2);
					realmTypeBonuses[tuple.Item1] = tuple.Item2;
					break;
				}
				default:
					UnityEngine.Debug.LogWarning("Unhandled key: " + text);
					break;
				case "MODEL":
					break;
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("Exception parsing line: " + line);
				throw ex;
			}
			static void AddElementToList(ref List<string> targetList, string value)
			{
				if (targetList == null)
				{
					targetList = new List<string>();
				}
				targetList.Add(value);
			}
		}
	}
