	public class RealmData : ScriptableObject
	{
		public enum RealmId
		{
			ANY = -1,
			Grove = 0,
			Druantia = 1,
			Typhon = 2,
			TempleOfFate = 4,
			ChamberOfTrials = 5,
			Ekbatan = 10,
			CavernsLivingFire = 11,
			TkalaCrypt = 12,
			HauntedPalace = 13,
			Prometheus = 6
		}

		public RealmId realmId;

		public string rootDir;

		public string townHero;

		public int monsterRatio;

		public int difficultyBump;

		public int townRealm;

		public string townAmbience;

		public List<string> townMusic;

		public void Parse(string realmString, string baseAssetPath)
		{
			string[] array = realmString.Split("\n");
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = false;
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text))
				{
					if (text.Contains("[/QUEST]"))
					{
						flag = false;
						ParseQuest(stringBuilder.ToString(), baseAssetPath);
						stringBuilder.Length = 0;
					}
					else if (text.Contains("[QUEST]"))
					{
						flag = true;
					}
					else if (flag)
					{
						stringBuilder.AppendLine(text);
					}
					else
					{
						ParseKVPLine(text);
					}
				}
			}
		}

		private RealmQuest ParseQuest(string questData, string baseAssetPath)
		{
			RealmQuest realmQuest = ScriptableObject.CreateInstance<RealmQuest>();
			string[] array = questData.Split('\n');
			new StringBuilder();
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text))
				{
					string text2 = text.Substring(text.IndexOf('<') + 1, text.IndexOf('>') - 1).ToUpper();
					string text3 = text;
					int num = text.IndexOf(':') + 1;
					string text4 = text3.Substring(num, text3.Length - num).Trim('\r');
					switch (text2)
					{
					case "ID":
						realmQuest.id = FateParseHelper.ParseInt(text4);
						break;
					case "TITLE":
						realmQuest.title = text4;
						break;
					case "REQUIRED":
						realmQuest.required = FateParseHelper.ParseBool(text4);
						break;
					case "OPTIONAL":
						realmQuest.optional = FateParseHelper.ParseBool(text4);
						break;
					case "CURSED":
						realmQuest.cursed = FateParseHelper.ParseBool(text4);
						break;
					case "TYPE":
						realmQuest.questType = FateParseHelper.ParseEnum<QuestData.QuestType>(text4);
						break;
					case "MINLEVEL":
						realmQuest.minLevel = FateParseHelper.ParseInt(text4);
						break;
					case "DEPTH":
						realmQuest.depth = FateParseHelper.ParseInt(text4);
						break;
					case "BLOCK":
						realmQuest.block = FateParseHelper.ParseInt(text4);
						break;
					case "MONSTER_TARGET_REFID":
					case "TARGET_REFID":
						realmQuest.target = text4;
						break;
					case "MONSTER_REFID":
						realmQuest.monster = text4;
						break;
					case "ITEM_REFID":
						realmQuest.item = text4;
						break;
					case "PROGRESS_FLAG":
					case "KEYS_QUEST":
						realmQuest.progressFlag = text4;
						break;
					case "RACE":
						realmQuest.raceReq = FateParseHelper.ParseEnum<Race>(text4);
						break;
					case "FORCE_BASENAME":
						realmQuest.forceBaseName = FateParseHelper.ParseBool(text4);
						break;
					case "QUEST_TEMPLATE":
						realmQuest.questTemplate = text4;
						break;
					case "COMPLETIONSTORY":
						realmQuest.completionStory = text4;
						break;
					case "CUSTOMGREET":
						realmQuest.customGreetSound = text4;
						break;
					case "KEYS_PROGRESS":
						realmQuest.keysToProgress = new List<string>(text4.Split(':'));
						break;
					case "KEYS_REQUIRED":
						realmQuest.keysRequired = new List<string>(text4.Split(':'));
						break;
					case "NO_REWARD_ITEM":
						realmQuest.noRewardItem = FateParseHelper.ParseBool(text4);
						break;
					case "MINI_DESCRIPTION":
						realmQuest.miniDesc = text4;
						break;
					case "INCOMPLETE_DESCRIPTION":
						realmQuest.incompleteDesc = text4;
						break;
					case "COMPLETE_DESCRIPTION":
						realmQuest.completeDesc = text4;
						break;
					default:
						UnityEngine.Debug.LogWarning("Unhandled key: " + text2);
						break;
					}
				}
			}
			_ = $"{baseAssetPath}/{$"RQ_{realmId}_{realmQuest.title}_{realmQuest.id}"}.asset";
			return realmQuest;
		}

		private void ParseKVPLine(string line)
		{
			try
			{
				string text = line.Substring(line.IndexOf('<') + 1, line.IndexOf('>') - 1).ToUpper();
				int num = line.IndexOf(':') + 1;
				string text2 = line.Substring(num, line.Length - num).Trim('\r');
				switch (text)
				{
				case "ID":
					realmId = (RealmId)FateParseHelper.ParseInt(text2);
					break;
				case "ROOTDIR":
					rootDir = text2;
					break;
				case "MONSTERRATIO":
					monsterRatio = FateParseHelper.ParseInt(text2);
					break;
				case "TOWNREALM":
					townRealm = FateParseHelper.ParseInt(text2);
					break;
				case "HERO":
					townHero = text2;
					break;
				case "TOWN_AMBIENCE":
					townAmbience = text2;
					break;
				case "TOWN_MUSIC":
					if (townMusic == null)
					{
						townMusic = new List<string>();
					}
					townMusic.Add(text2);
					break;
				case "DIFFICULTY_BUMP":
					difficultyBump = FateParseHelper.ParseInt(text2);
					break;
				default:
					UnityEngine.Debug.LogWarning("Unhandled key: " + text);
					break;
				case "HAS_REALM_QUEST":
					break;
				case "LEVEL":
					break;
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("Exception parsing line: " + line);
				throw ex;
			}
		}
	}
