	public class SpellData : ScriptableObject
	{
		public string spellName;

		public string refId;

		public SpellSphere sphereType;

		public bool reserved;

		public Range shakeRange;

		public Alignment targetAlignment;

		public ItemTarget targetType;

		public RageType rageType;

		public int range;

		public float castTime;

		public int manaCost;

		public int staminaCost;

		public int minimumDepth;

		public string iconRaw;

		public List<VisualEffect> sfx;

		public List<VisualEffect> payloadSfx;

		public int sfxDurationBonus;

		public string description;

		public List<string> particles;

		public List<string> sounds;

		public AudioData.AudioClipName successSoundName;

		public AudioData.AudioClipName castSoundName;

		public AudioData.AudioClipName strikeSoundName;

		public List<AttributeData> requirements;

		public List<EffectData> effects;

		public List<EffectData> payloadEffects;

		[Header("Particle prefabs")]
		public GameObject particleProjectilePrefab;

		public GameObject particleImpactPrefab;

		private string iconName;

		public string IconName
		{
			get
			{
				if (string.IsNullOrEmpty(iconRaw))
				{
					return null;
				}
				if (string.IsNullOrEmpty(iconName))
				{
					string text;
					int num = (text = iconRaw.Split(':')[0]).LastIndexOf('/') + 1;
					string text2 = text.Substring(num, text.Length - num);
					iconName = text2.Substring(0, text2.IndexOf('.'));
				}
				return iconName;
			}
		}

		public bool IsHealSpell()
		{
			if (effects == null || sphereType != SpellSphere.Defense)
			{
				return false;
			}
			foreach (EffectData effect in effects)
			{
				if (effect.buffType == EffectType.HPRecharge)
				{
					return true;
				}
			}
			return false;
		}

		public bool IsSummonSpell()
		{
			if (effects == null || sphereType != SpellSphere.Charm)
			{
				return false;
			}
			foreach (EffectData effect in effects)
			{
				if (effect.buffType == EffectType.Summon)
				{
					return true;
				}
			}
			return false;
		}

		public bool IsPortalSpell()
		{
			if (effects == null)
			{
				return false;
			}
			foreach (EffectData effect in effects)
			{
				if (effect.buffType == EffectType.OpenPortal)
				{
					return true;
				}
			}
			return false;
		}

		public bool RequiresCharacterTarget()
		{
			switch (targetType)
			{
			case ItemTarget.Character:
			case ItemTarget.CharacterArea:
			case ItemTarget.CharacterPets:
			case ItemTarget.CharacterAndPets:
				return true;
			default:
				return false;
			}
		}

		public void Parse(string spellString)
		{
			string[] array = spellString.Split("\n");
			effects = new List<EffectData>();
			payloadEffects = new List<EffectData>();
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = false;
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text))
				{
					if (text.Contains("[/EFFECT]"))
					{
						flag = false;
						effects.Add(FateParseHelper.ParseEffect(stringBuilder.ToString()));
						stringBuilder.Length = 0;
					}
					else if (text.Contains("[EFFECT]"))
					{
						flag = true;
					}
					else if (text.Contains("[/PAYLOADEFFECT]"))
					{
						flag = false;
						payloadEffects.Add(FateParseHelper.ParseEffect(stringBuilder.ToString()));
						stringBuilder.Length = 0;
					}
					else if (text.Contains("[PAYLOADEFFECT]"))
					{
						flag = true;
					}
					else if (flag)
					{
						stringBuilder.AppendLine(text);
					}
					else
					{
						ParseKVPLine(text);
					}
				}
			}
		}

		private void ParseKVPLine(string line)
		{
			try
			{
				string text = line.Substring(line.IndexOf('<') + 1, line.IndexOf('>') - 1).ToUpper();
				int num = line.IndexOf(':') + 1;
				string text2 = line.Substring(num, line.Length - num).Trim('\r');
				switch (text)
				{
				case "SPHERE":
					sphereType = FateParseHelper.ParseEnum<SpellSphere>(text2);
					if (sphereType == SpellSphere.None)
					{
						UnityEngine.Debug.LogError("MISSED TYPE: " + text2);
					}
					break;
				case "NAME":
					spellName = text2;
					break;
				case "SHAKE":
					shakeRange = FateParseHelper.ParseRange(text2);
					break;
				case "REFID":
					refId = text2;
					break;
				case "DESCRIPTION":
					description = text2;
					break;
				case "CAST_TIME":
					castTime = FateParseHelper.ParseFloat(text2);
					break;
				case "RANGE":
					range = FateParseHelper.ParseInt(text2);
					break;
				case "MANA":
					manaCost = FateParseHelper.ParseInt(text2);
					break;
				case "STAMINA":
					staminaCost = FateParseHelper.ParseInt(text2);
					break;
				case "RESERVED":
					reserved = FateParseHelper.ParseBool(text2);
					break;
				case "TARGET":
					targetType = FateParseHelper.ParseEnum<ItemTarget>(text2);
					break;
				case "TARGET_ALIGNMENT":
					targetAlignment = FateParseHelper.ParseEnum<Alignment>(text2);
					break;
				case "MINIMUM_DEPTH":
					minimumDepth = FateParseHelper.ParseInt(text2);
					break;
				case "ICON":
					iconRaw = text2;
					break;
				case "SFX":
					if (sfx == null)
					{
						sfx = new List<VisualEffect>();
					}
					sfx.Add(FateParseHelper.ParseVisualFX(text2));
					break;
				case "PAYLOADSFX":
					if (payloadSfx == null)
					{
						payloadSfx = new List<VisualEffect>();
					}
					payloadSfx.Add(FateParseHelper.ParseVisualFX(text2));
					break;
				case "SFX_DURATION_BONUS":
					sfxDurationBonus = FateParseHelper.ParseInt(text2);
					break;
				case "SOUND":
					AddElementToList(ref sounds, text2);
					break;
				case "CAST_PARTICLE":
					AddElementToList(ref particles, text2);
					break;
				case "REQUIRES":
					if (requirements == null)
					{
						requirements = new List<AttributeData>();
					}
					requirements.Add(FateParseHelper.ParseAttributeData(text2));
					break;
				case "RAGETYPE":
					rageType = FateParseHelper.ParseEnum<RageType>(text2);
					break;
				default:
					UnityEngine.Debug.LogWarning("Unhandled key: " + text);
					break;
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("Exception parsing line: " + line);
				throw ex;
			}
			static void AddElementToList(ref List<string> targetList, string value)
			{
				if (targetList == null)
				{
					targetList = new List<string>();
				}
				targetList.Add(value);
			}
		}
	}
