		public void Parse(string templateString)
		{
			SetDefaultValues();
			rawData = templateString;
			string[] array = templateString.Split("\n");
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = false;
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text) && text[0] != '#')
				{
					if (text.Contains("[/GROUND]"))
					{
						flag = false;
						ParseGround(stringBuilder.ToString());
						stringBuilder.Length = 0;
					}
					else if (text.Contains("[GROUND]"))
					{
						flag = true;
					}
					else if (text.Contains("[/WALL]"))
					{
						flag = false;
						AddElementToList(ref wallSets, ParseWallSet(stringBuilder.ToString()));
						stringBuilder.Length = 0;
					}
					else if (text.Contains("[WALL]"))
					{
						flag = true;
					}
					else if (text.Contains("[/PROP]"))
					{
						flag = false;
						AddElementToList(ref props, ParsePropData(stringBuilder.ToString()));
						stringBuilder.Length = 0;
					}
					else if (text.Contains("[PROP]"))
					{
						flag = true;
					}
					else if (flag)
					{
						stringBuilder.AppendLine(text);
					}
					else
					{
						ParseMainValues(text);
					}
				}
			}
			UpdatePropsInLocations();
		}

		private void SetDefaultValues()
		{
			templateName = "Default";
			typeTag = "Default";
			realmId = RealmData.RealmId.ANY;
			minimumWidth = 24;
			maximumWidth = 48;
			minimumHeight = 24;
			maximumHeight = 48;
			minimumRoomWidth = 3;
			maximumRoomWidth = 9;
			minimumRoomHeight = 3;
			maximumRoomHeight = 9;
			minimumRooms = 4;
			maximumRooms = 12;
			minimumPits = 0;
			maximumPits = 12;
			minimumTwistiness = 0;
			maximumTwistiness = 1000;
			minimumConnectedness = 0;
			maximumConnectedness = 1000;
			minimumSparseness = 0;
			maximumSparseness = 1000;
			minimumRoundedness = 0;
			maximumRoundedness = 1000;
			ceilingTerrain = 0;
			tileWidth = 2f;
			tileHeight = 2f;
			heightDistortion = 0f;
			XYDistortion = 0f;
			hasWater = false;
			waterDepth = -4f;
			waterSoundPath = "";
			waterSoundRadius = 64f;
			terrainRandomizer = new Randomizer();
		}

		private WallSet ParseWallSet(string wallSet)
		{
			WallSet wallSet2 = new WallSet();
			for (int i = 0; i < 5; i++)
			{
				AddElementToList(ref wallSet2.wallTypes, new WallData());
			}
			string[] array = wallSet.Split("\n");
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text) && text[0] != '#')
				{
					string text2 = text.Substring(text.IndexOf('<') + 1, text.IndexOf('>') - 1).ToUpper();
					string text3 = text;
					int num = text.IndexOf(':') + 1;
					string text4 = text3.Substring(num, text3.Length - num).Trim('\r');
					switch (text2)
					{
					case "TILELEVEL":
						AddElementToList(ref wallSet2.tileLayer, FateParseHelper.ParseInt(text4));
						break;
					case "TEXTURE":
						wallSet2.texture = text4;
						break;
					case "NWCORNER":
					case "SWCORNER":
					case "NECORNER":
					case "SECORNER":
					case "NWINNERCORNER":
					case "SWINNERCORNER":
					case "NEINNERCORNER":
					case "SEINNERCORNER":
					case "NWCORNERJOIN":
					case "SWCORNERJOIN":
					case "NECORNERJOIN":
					case "SECORNERJOIN":
					case "NWHORIZONTAL":
					case "SWHORIZONTAL":
					case "NEHORIZONTAL":
					case "SEHORIZONTAL":
					case "NWVERTICAL":
					case "SWVERTICAL":
					case "NEVERTICAL":
					case "SEVERTICAL":
						AddElementToList(ref wallSet2.wallTypes, ParseWallData(text4, text2));
						break;
					default:
						UnityEngine.Debug.LogWarning("Unhandled key: " + text2);
						break;
					}
				}
			}
			return wallSet2;
		}

		private WallData ParseWallData(string rawValue, string key)
		{
			WallData wallData = new WallData();
			return key switch
			{
				_ => wallData, 
			};
		}

		private PropData ParsePropData(string propData)
		{
			PropData propData2 = new PropData();
			propData2.collideable = true;
			propData2.shadow = true;
			propData2.rotateable = true;
			propData2.minimumBunch = 1;
			propData2.maximumBunch = 1;
			propData2.rarity = 1000;
			string[] array = propData.Split('\n');
			foreach (string text in array)
			{
				if (string.IsNullOrEmpty(text) || text[0] == '#')
				{
					continue;
				}
				string text2 = text.Substring(text.IndexOf('<') + 1, text.IndexOf('>') - 1).ToUpper();
				string text3 = text;
				int num = text.IndexOf(':') + 1;
				string text4 = text3.Substring(num, text3.Length - num).Trim('\r');
				switch (text2)
				{
				case "ROTATEABLE":
					propData2.rotateable = FateParseHelper.ParseBool(text4);
					break;
				case "COLLIDEABLE":
					propData2.collideable = FateParseHelper.ParseBool(text4);
					break;
				case "SHADOW":
					propData2.shadow = FateParseHelper.ParseBool(text4);
					break;
				case "LOCATION":
					AddElementToList(ref propData2.locations, FateParseHelper.ParseEnum<PropLocation>(text4));
					break;
				case "LIGHT":
					propData2.lightData = FateParseHelper.ParseLightData(text4);
					propData2.hasLightPool = true;
					break;
				case "SCALE_VARIATION":
					propData2.scaleVariation = FateParseHelper.ParseFloat(text4);
					break;
				case "MINIMUM_OFFSET":
					propData2.minimumOffset = FateParseHelper.ParseVector3(text4);
					break;
				case "MAXIMUM_OFFSET":
					propData2.maximumOffset = FateParseHelper.ParseVector3(text4);
					break;
				case "MINIMUM_BUNCH":
					propData2.minimumBunch = FateParseHelper.ParseInt(text4);
					break;
				case "MAXIMUM_BUNCH":
					propData2.maximumBunch = FateParseHelper.ParseInt(text4);
					break;
				case "STRUCTURAL":
					propData2.structural = FateParseHelper.ParseBool(text4);
					break;
				case "PLACEMENT_RAY":
					propData2.directionRay = FateParseHelper.ParseVector3(text4);
					propData2.hasPlacementRay = true;
					break;
				case "RAY_HEIGHT":
					propData2.rayHeight = FateParseHelper.ParseFloat(text4);
					break;
				case "BASE_ROTATION":
					propData2.baseRotation = FateParseHelper.ParseFloat(text4);
					break;
				case "AMBIENT_SOUND":
					propData2.ambientSoundPath = text4;
					break;
				case "BASE_SOUND_RADIUS":
					propData2.baseSoundRadius = FateParseHelper.ParseFloat(text4);
					break;
				case "BASE_SOUND_VOLUME":
					propData2.baseSoundVolume = FateParseHelper.ParseFloat(text4);
					break;
				case "RARITY":
				{
					int num2 = FateParseHelper.ParseInt(text4);
					num2 = 1000 - num2;
					if (num2 < 0)
					{
						num2 = 0;
					}
					propData2.rarity = num2;
					break;
				}
				case "BUFFER_N":
					propData2.bufferN = FateParseHelper.ParseBool(text4);
					break;
				case "BUFFER_S":
					propData2.bufferS = FateParseHelper.ParseBool(text4);
					break;
				case "BUFFER_E":
					propData2.bufferE = FateParseHelper.ParseBool(text4);
					break;
				case "BUFFER_W":
					propData2.bufferW = FateParseHelper.ParseBool(text4);
					break;
				case "BUFFER_NW":
					propData2.bufferNW = FateParseHelper.ParseBool(text4);
					break;
				case "BUFFER_NE":
					propData2.bufferNE = FateParseHelper.ParseBool(text4);
					break;
				case "BUFFER_SW":
					propData2.bufferSW = FateParseHelper.ParseBool(text4);
					break;
				case "BUFFER_SE":
					propData2.bufferSE = FateParseHelper.ParseBool(text4);
					break;
				case "ACTIVATE_RADIUS":
					propData2.activationRadius = FateParseHelper.ParseFloat(text4);
					break;
				case "DEACTIVATE_RADIUS":
					propData2.deactivationRadius = FateParseHelper.ParseFloat(text4);
					break;
				case "ACTIVATE_SOUND":
					propData2.activationSoundPath = text4;
					break;
				case "DEACTIVATE_SOUND":
					propData2.deactivationSoundPath = text4;
					break;
				case "STAIRS_UP":
					propData2.isStairsUp = FateParseHelper.ParseBool(text4);
					break;
				case "STAIRS_DOWN":
					propData2.isStairsDown = FateParseHelper.ParseBool(text4);
					break;
				case "REQUIRES_FLAT":
					propData2.requiresFlat = FateParseHelper.ParseBool(text4);
					break;
				case "NAME":
					propData2.propName = text4;
					break;
				case "TEXTUREPATH":
					propData2.texturePath = text4;
					break;
				default:
					UnityEngine.Debug.LogWarning("Unhandled key: " + text2);
					break;
				case "MODEL":
				case "COLLISION":
					break;
				}
			}
			return propData2;
		}

		private void ParseGround(string tileData)
		{
			string[] array = tileData.Split('\n');
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text) && text[0] != '#')
				{
					string text2 = text.Substring(text.IndexOf('<') + 1, text.IndexOf('>') - 1).ToUpper();
					string text3 = text;
					int num = text.IndexOf(':') + 1;
					string rawValue = text3.Substring(num, text3.Length - num).Trim('\r');
					if (text2 == "TILES")
					{
						AddElementToList(ref floorTiles, FateParseHelper.ParseTileData(rawValue));
						int odds = 1000 - floorTiles[floorTiles.Count - 1].rarity;
						terrainRandomizer.AddChoice(floorTiles[floorTiles.Count - 1].layer, odds);
					}
				}
			}
		}

