				int num = line.IndexOf(':') + 1;
				string text2 = line.Substring(num, line.Length - num).Trim('\r');
				switch (text)
				{
				case "MINIMUMWIDTH":
					minimumWidth = FateParseHelper.ParseInt(text2);
