				case "MINIMUMCONNECTEDNESS":
					minimumConnectedness = FateParseHelper.ParseInt(text2);
					break;
				case "MAXIMUMCONNECTEDNESS":
					maximumConnectedness = FateParseHelper.ParseInt(text2);
					break;
				case "MINIMUMSPARSENESS":
					minimumSparseness = FateParseHelper.ParseInt(text2);
					break;
				case "MAXIMUMSPARSENESS":
					maximumSparseness = FateParseHelper.ParseInt(text2);
					break;
				case "MINIMUMROUNDEDNESS":
					minimumRoundedness = FateParseHelper.ParseInt(text2);
					break;
				case "MAXIMUMROUNDEDNESS":
					maximumRoundedness = FateParseHelper.ParseInt(text2);
					break;
				case "TILEWIDTH":
					tileWidth = FateParseHelper.ParseInt(text2);
					break;
				case "TILEHEIGHT":
					tileHeight = FateParseHelper.ParseInt(text2);
					break;
				case "HEIGHT_DISTORTION":
					heightDistortion = FateParseHelper.ParseFloat(text2);
					break;
				case "XY_DISTORTION":
					XYDistortion = FateParseHelper.ParseFloat(text2);
					break;
				case "MUSIC_TRACK":
					AddElementToList(ref musicTracks, text2);
					break;
				case "WATER":
					hasWater = true;
					break;
				case "WATER_DEPTH":
					waterDepth = FateParseHelper.ParseFloat(text2);
