					ceilingTerrain = FateParseHelper.ParseInt(text2);
					break;
				case "TYPE_TAG":
					typeTag = text2;
					break;
				default:
					UnityEngine.Debug.LogWarning("Unhandled key: " + text);
					break;
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("Exception parsing line: " + line);
				throw ex;
