		private static void AddElementToList<T>(ref List<T> targetList, T value)
		{
			if (targetList == null)
			{
				targetList = new List<T>();
			}
			targetList.Add(value);
		}

		private void UpdatePropsInLocations()
		{
			doneUpdate = true;
			Array values = Enum.GetValues(typeof(PropLocation));
			propsForLocation = new List<LocationWithProps>();
			for (int i = 0; i < values.Length - 1; i++)
			{
				LocationWithProps item = default(LocationWithProps);
				item.props = new List<PropData>();
				item.location = (PropLocation)values.GetValue(i);
				propsForLocation.Add(item);
			}
			propRandomizer = new List<Randomizer>();
			for (int j = 0; j < values.Length - 1; j++)
			{
				propRandomizer.Add(new Randomizer());
			}
			for (int k = 0; k < props.Count; k++)
			{
				for (int l = 0; l < props[k].locations.Count; l++)
				{
					int index = (int)props[k].locations[l];
					if (props[k].locations[l] == PropLocation.Anywhere)
					{
						for (int m = 0; m < 14; m++)
						{
							propRandomizer[m].AddChoice(propsForLocation[index].props.Count, props[k].rarity);
							propsForLocation[m].props.Add(props[k]);
						}
					}
					else
					{
						propRandomizer[index].AddChoice(propsForLocation[index].props.Count, props[k].rarity);
						propsForLocation[index].props.Add(props[k]);
					}
				}
			}
		}

		public PropData RandomProp(PropLocation location)
		{
			if (!doneUpdate || propRandomizer.Count < 1 || propsForLocation.Count < 1)
			{
				UpdatePropsInLocations();
			}
			if (location >= PropLocation.Room && location < PropLocation.Locations)
			{
				if (propsForLocation[(int)location].props.Count == 0)
				{
					return null;
				}
				int random = propRandomizer[(int)location].GetRandom();
				if (random >= 0 && random < propsForLocation[(int)location].props.Count)
				{
					PropData propData = propsForLocation[(int)location].props[random];
					if (propData.cap <= -1)
					{
						return propData;
					}
					if (propData.count == propData.cap)
					{
						return null;
					}
					propsForLocation[(int)location].props[random].count++;
					return propData;
				}
			}
			return null;
		}

		public void ResetCounters()
		{
			for (int i = 0; i < props.Count; i++)
			{
				props[i].count = 0;
			}
			doneUpdate = false;
		}

		public int RandomTerrain()
		{
			if (terrainRandomizer == null)
			{
				terrainRandomizer = new Randomizer();
			}
			return terrainRandomizer.GetRandom();
		}

		public int WallTemplates(int wallSetIndex, WallTypes wallType)
		{
			if (wallSetIndex >= wallSets.Count)
			{
				return 0;
			}
			if ((int)wallType >= wallSets[wallSetIndex].wallTypes.Count)
			{
				return 0;
			}
			return wallSets[wallSetIndex].wallTypes[(int)wallType].walls.Count;
		}

		public int TileGroundLayers(int TileIndex)
		{
			return floorTiles[TileIndex].layer;
		}

		public int TileCeilingLayers(int TileIndex)
		{
			return ceilingTiles[TileIndex].layer;
		}

		public void UpdateFloorDictionary()
		{
			floorDictionary = new Dictionary<CellTypes, Dictionary<bool, GameObject>>();
			for (int i = 0; i < 9; i++)
			{
				GameObject gameObject = null;
				foreach (FloorSet floorPrefab in floorPrefabs)
				{
					if (i == (int)floorPrefab.floorType)
					{
						gameObject = floorPrefab.floorPrefab;
						bool key = gameObject.name.Split('_')[^1].Contains("Split");
						if (floorDictionary.ContainsKey((CellTypes)i) && floorDictionary[(CellTypes)i] != null)
						{
							floorDictionary[(CellTypes)i].Add(key, gameObject);
							continue;
						}
						floorDictionary.Add((CellTypes)i, new Dictionary<bool, GameObject>());
						floorDictionary[(CellTypes)i].Add(key, gameObject);
					}
				}
			}
		}
	}
	public static class FateParseHelper
	{
		public static float ParseFloat(string rawValue)
		{
			if (rawValue[0] == '.')
			{
				return float.Parse("0" + rawValue, CultureInfo.InvariantCulture);
			}
			return float.Parse(rawValue, CultureInfo.InvariantCulture);
		}

		public static int ParseInt(string rawValue)
		{
			return int.Parse(rawValue);
		}

		public static bool ParseBool(string rawValue)
		{
			return rawValue != "0";
		}

		public static Vector3 ParseVector3(string rawValue)
		{
			string[] array = rawValue.Split(':');
			if (array.Length != 3)
			{
				UnityEngine.Debug.LogError("Failed to parse Vector3");
				return default(Vector3);
			}
			float x = ((array[0][0] != '.') ? float.Parse(array[0], CultureInfo.InvariantCulture) : float.Parse("0" + array[0], CultureInfo.InvariantCulture));
			float y = ((array[1][0] != '.') ? float.Parse(array[1], CultureInfo.InvariantCulture) : float.Parse("0" + array[1], CultureInfo.InvariantCulture));
			float z = ((array[2][0] != '.') ? float.Parse(array[2], CultureInfo.InvariantCulture) : float.Parse("0" + array[2], CultureInfo.InvariantCulture));
			return new Vector3(x, y, z);
		}

		public static T ParseEnum<T>(string rawValue) where T : Enum
		{
			string[] names = Enum.GetNames(typeof(T));
			for (int i = 0; i < names.Length; i++)
			{
				char[] array = names[i].ToUpper().ToCharArray();
				char[] array2 = rawValue.ToUpper().ToCharArray();
				if (array.Length != array2.Length)
				{
					continue;
				}
				bool flag = true;
				for (int j = 0; j < array.Length; j++)
				{
					if (array[j] != array2[j])
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					return (T)Enum.Parse(typeof(T), names[i]);
				}
			}
			if (!Application.isPlaying)
			{
				throw new ArgumentException("Failed to parse enum: T string: " + rawValue);
			}
			return default(T);
		}

		public static EffectData ParseEffect(string effectData)
		{
			EffectData effectData2 = new EffectData();
			string[] array = effectData.Split('\n');
			foreach (string text in array)
			{
				if (string.IsNullOrEmpty(text))
				{
					continue;
				}
				try
				{
					string text2 = text.Substring(text.IndexOf('<') + 1, text.IndexOf('>') - 1).ToUpper();
					string text3 = text;
					int num = text.IndexOf(':') + 1;
					string text4 = text3.Substring(num, text3.Length - num).Trim('\r');
					switch (text2)
					{
					case "NAME":
						effectData2.name = text4;
						break;
					case "EXCLUSIVE":
						effectData2.exclusive = ParseBool(text4);
						break;
					case "MESSAGE":
						effectData2.applicationMessage = text4;
						break;
					case "CHANCE_OF_SUCCESS":
						effectData2.chance = ParseInt(text4);
						break;
					case "ACTIVATION":
						effectData2.activationType = ParseEnum<ActivationType>(text4);
						break;
					case "TYPE":
						effectData2.buffType = ParseEnum<EffectType>(text4);
						if (effectData2.buffType == EffectType.None)
						{
							UnityEngine.Debug.LogWarning("MISSING BUFFTYPE: " + text4);
						}
						break;
					case "TARGET":
						effectData2.target = ParseEnum<ItemTarget>(text4);
						break;
					case "DURATION":
						if (text4.Contains("INSTANT"))
						{
							effectData2.duration = -900;
						}
						else if (text4.Contains("ALWAYS"))
						{
							effectData2.duration = -1000;
						}
						else
						{
							effectData2.duration = ParseInt(text4);
						}
						break;
					case "DURATION_BONUS":
						effectData2.durationBonus = ParseFloat(text4);
						break;
					case "VALUE":
						effectData2.value = ParseInt(text4);
						break;
					case "VALUE2":
						effectData2.value2 = ParseInt(text4);
						break;
					case "VALUE3":
						effectData2.value3 = ParseInt(text4);
						break;
					case "VALUE_BONUS":
						effectData2.valueBonus = ParseFloat(text4);
						break;
					case "VALUE2_BONUS":
						effectData2.value2Bonus = ParseFloat(text4);
						break;
					case "VALUE3_BONUS":
						effectData2.value3Bonus = ParseFloat(text4);
						break;
					case "DAMAGE_TYPE":
						effectData2.damageType = ParseEnum<DamageType>(text4);
						break;
					case "SFX":
						if (effectData2.sfx == null)
						{
							effectData2.sfx = new List<VisualEffect>();
						}
						effectData2.sfx.Add(ParseVisualFX(text4));
						break;
					case "SFX_DURATION_BONUS":
						effectData2.sfxDurationBonus = ParseInt(text4);
						break;
					default:
						UnityEngine.Debug.LogWarning("Unhandled key: " + text2);
						break;
					}
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogError("Error parsing effect: " + text);
					throw ex;
				}
			}
			return effectData2;
		}

		public static Range ParseRange(string rawValue)
		{
			string[] array = rawValue.Split(':');
			if (array.Length != 2)
			{
				UnityEngine.Debug.LogError("Failed to parse Range");
				return default(Range);
			}
			float min = ((array[0][0] != '.') ? float.Parse(array[0], CultureInfo.InvariantCulture) : float.Parse("0" + array[0], CultureInfo.InvariantCulture));
			float max = ((array[1][0] != '.') ? float.Parse(array[1], CultureInfo.InvariantCulture) : float.Parse("0" + array[1], CultureInfo.InvariantCulture));
			Range result = default(Range);
			result.Min = min;
			result.Max = max;
			return result;
		}

		public static AttributeData ParseAttributeData(string rawValue)
		{
			string[] array = rawValue.Split(':');
			return new AttributeData
			{
				attribute = ParseEnum<Attribute>(array[0]),
				value = ParseInt(array[1])
			};
		}

		public static ElementAmount ParseElementValue(string rawValue)
		{
			string[] array = rawValue.Split(':');
			return new ElementAmount
			{
				type = ParseEnum<DamageType>(array[0]),
				value = ParseInt(array[1])
			};
		}

		public static (string, int) ParseStringIntKVP(string rawValue)
		{
			string[] array = rawValue.Split(':');
			return (array[0], ParseInt(array[1]));
		}

		public static LightData ParseLightData(string rawValue)
		{
			string[] array = rawValue.Split(':');
			return new LightData
			{
				lightPoolImage = array[0],
				radius = ParseFloat(array[1]),
				behaviour = ParseEnum<LightBehaviour>(array[2])
			};
		}

		public static TileData ParseTileData(string rawValue)
		{
			string[] array = rawValue.Split(':');
			return new TileData
			{
				layer = ParseInt(array[0]),
				available = ParseBool(array[1]),
				rarity = ParseInt(array[2])
			};
		}

		public static VisualEffect ParseVisualFX(string rawValue)
		{
			string[] array = rawValue.Split(':');
			VisualEffect visualEffect = new VisualEffect();
			visualEffect.sfxType = ParseEnum<SFXType>(array[0]);
			visualEffect.duration = ParseFloat(array[1]);
			visualEffect.looping = ParseBool(array[2]);
			visualEffect.speed = ParseFloat(array[3]);
			visualEffect.turnRate = ParseFloat(array[4]);
			visualEffect.particlePath = array[5];
			if (array.Length > 6)
			{
				visualEffect.exclusive = ParseBool(array[6]);
			}
			if (array.Length > 7)
			{
				visualEffect.respectBonuses = ParseBool(array[7]);
			}
			return visualEffect;
		}
	}
	[Serializable]
	public class Randomizer
	{
		private List<int> odds = new List<int>();

		private List<float> computedOdds = new List<float>();

		private bool needsComputation;

		public int Count => odds.Count;

		public void Clear()
		{
			odds.Clear();
			computedOdds.Clear();
			needsComputation = true;
		}

		public void AddChoice(int Index, int Odds)
		{
			while (Index + 1 > odds.Count)
			{
				odds.Add(0);
				computedOdds.Add(0f);
			}
			odds[Index] = Odds;
			needsComputation = true;
		}

		public void RemoveChoice(int Index)
		{
			odds.RemoveAt(Index);
			computedOdds.RemoveAt(Index);
			needsComputation = true;
		}

		public int GetRandom()
		{
			if (needsComputation)
			{
				ComputeOdds();
			}
			if (computedOdds.Count == 1)
			{
				return 0;
			}
			float num = UnityEngine.Random.Range(0f, float.MaxValue) / float.MaxValue;
			if (num == 1f)
			{
				num -= 0.001f;
			}
			float num2 = 0f;
			for (int i = 0; i < computedOdds.Count; i++)
			{
				num2 += computedOdds[i];
				if (num2 > num)
				{
					return i;
				}
			}
			return -1;
		}

		public int GetOdds(int Choice)
		{
			return odds[Choice];
		}

		private void ComputeOdds()
		{
			int num = 0;
			for (int i = 0; i < odds.Count; i++)
			{
				num += odds[i];
			}
			for (int j = 0; j < odds.Count; j++)
			{
				computedOdds[j] = (float)odds[j] / (float)num;
			}
			needsComputation = false;
		}
	}
	public class DemoFateUI : MonoBehaviour
	{
		public Button playButton;

		public GameObject[] firstTimeToggledOn;

		public GameObject[] firstTimeToggledOff;

		private void Awake()
		{
			InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
			instance.OnMenuCancelPerformed = (Action)Delegate.Combine(instance.OnMenuCancelPerformed, new Action(QuitToMenu));
		}

		private void OnDestroy()
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
				instance.OnMenuCancelPerformed = (Action)Delegate.Remove(instance.OnMenuCancelPerformed, new Action(QuitToMenu));
			}
		}

		private void QuitToMenu()
		{
			if (!base.gameObject.activeInHierarchy)
			{
				return;
			}
			SingletonBehaviour<PromptUI>.Instance.ShowPrompt(I2Loca.Get("QuitPrompt"), delegate(bool positive)
			{
				if (positive)
				{
					if (SingletonBehaviour<InputBroker>.InstanceExists())
					{
						InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
						instance.OnMenuCancelPerformed = (Action)Delegate.Remove(instance.OnMenuCancelPerformed, new Action(QuitToMenu));
					}
					SingletonBehaviour<AudioManager>.Instance.StopMusic(AudioData.AudioClipName.DungeonMusic);
					SceneLoad.LoadMainMenuCurrentGame(saveFirst: false, null);
					SingletonBehaviour<AudioManager>.Instance.StopMusic();
				}
			});
		}

		public void ShowDemoPrompt(bool firstTime, Action onPlayButton)
		{
			if (firstTimeToggledOff != null)
			{
				for (int i = 0; i < firstTimeToggledOff.Length; i++)
				{
					firstTimeToggledOff[i].SetActive(!firstTime);
				}
			}
			if (firstTimeToggledOn != null)
			{
				for (int j = 0; j < firstTimeToggledOn.Length; j++)
				{
					firstTimeToggledOn[j].SetActive(firstTime);
				}
			}
			playButton.onClick.RemoveAllListeners();
			playButton.onClick.AddListener(delegate
			{
				base.gameObject.SetActive(value: false);
				onPlayButton();
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			});
		}
	}
