	public static class ActiveLevel
	{
		public static void SpawnGoldPile(Vector3 position, int goldAmount)
		{
			if (goldAmount <= 0)
			{
				UnityEngine.Debug.LogWarning($"Tried spawning a gold pile with {goldAmount} gold. Not allowing it, no gold pile will be spawned.");
				return;
			}
			GameObject goldPilePrefab = SingletonBehaviour<FateDB>.Instance.goldPilePrefab;
			if (goldPilePrefab == null)
			{
				UnityEngine.Debug.LogError("Gold pile prefab is null");
				return;
			}
			Transform parent = null;
			if (LevelGenerator.currentInstance != null)
			{
				parent = LevelGenerator.currentInstance.GetActiveContainersParent;
			}
			else if (SingletonBehaviour<Town>.InstanceExists())
			{
				parent = SingletonBehaviour<Town>.Instance.GetActiveContainersParent;
			}
			GameObject gameObject = UnityEngine.Object.Instantiate(goldPilePrefab, position, Quaternion.identity, parent);
			if (gameObject.TryGetComponent<GoldPileTrigger>(out var component))
			{
				component.Init(goldAmount);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Prefab does not contain a needed script, GoldPileTrigger is missing from " + gameObject.name);
			}
		}

		public static Vector3 AdjustPositionToNavMesh(Vector3 intendedPosition, Vector3 fallbackPosition, bool performObstructionTest)
		{
			if (NavMesh.SamplePosition(intendedPosition, out var hit, 2f, -1))
			{
				Vector3 vector = intendedPosition - fallbackPosition;
				float magnitude = vector.magnitude;
				bool flag = magnitude < 0.05f;
				bool flag2 = false;
				if (performObstructionTest && !flag && Physics.Raycast(fallbackPosition + Vector3.up, vector.normalized, magnitude, LevelGenerator.WallLayerMask))
				{
					flag2 = true;
				}
				if (!flag2)
				{
					return hit.position;
				}
			}
			if (NavMesh.SamplePosition(intendedPosition, out var hit2, 1f, -1))
			{
				Vector3 vector2 = intendedPosition - hit2.position;
				float magnitude2 = vector2.magnitude;
				if (!(magnitude2 < 0.05f) && !Physics.Raycast(intendedPosition + Vector3.up, vector2.normalized, magnitude2, LevelGenerator.WallLayerMask))
				{
					fallbackPosition = hit2.position;
				}
			}
			else
			{
				UnityEngine.Debug.LogWarning("AdjustPositionToNavMesh: Using fallback position, but could not adjust it to the nav mesh. This could lead to player being unable to reach things.");
			}
			return fallbackPosition;
		}

		public static int GetEffectiveDungeonDepth()
		{
			if (LevelGenerator.currentInstance == null)
			{
				return 0;
			}
			return LevelGenerator.effectiveLevelDepth;
		}

		public static int GetCurrentDungeonDepth()
		{
			if (!(LevelGenerator.currentInstance != null))
			{
				return 0;
			}
			FateSaveData currentSaveData = SaveData.CurrentSaveData;
			if (currentSaveData == null)
			{
				return 0;
			}
			if (!SingletonBehaviour<PlayerStatus>.InstanceExists())
			{
				return 0;
			}
			return currentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm).latestDungeonDepth;
