		public static int DigGreedilyAfterDeepestDepthReached()
		{
			FateSaveData currentSaveData = SaveData.CurrentSaveData;
			if (currentSaveData == null || currentSaveData.realmSaveData == null || currentSaveData.realmSaveData.realms == null)
			{
				return 0;
			}
			int num = 0;
			foreach (RealmSave realm in currentSaveData.realmSaveData.realms)
			{
				if (realm.maxDepthReached > num)
				{
					num = realm.maxDepthReached;
				}
			}
			return num;
		}

		public static bool TryRankUpItem(Item item, int depth)
		{
			if (item.rank == Rank.Normal && !item.IsHeroItem())
			{
				ItemCategory category = item.category;
				if ((category == ItemCategory.Weapon || category == ItemCategory.Armor) && item.itemData.maximumDepth > 12)
				{
					if (item.itemData.minimumDepth >= Fate.RankMod[Rank.Elite].levelOffset)
					{
						float min = Fate.ItemRankChanceElite.Min;
						float max = Fate.ItemRankChanceElite.Max;
						float num = Mathf.Clamp01(Mathf.InverseLerp(Fate.RankMod[Rank.Elite].levelOffset, 100f, depth));
						float num2 = min + (max - min) * num;
						if (UnityEngine.Random.value < num2)
						{
							ImproveItemToRank(item, Rank.Elite, depth);
							return true;
						}
					}
					if (item.itemData.minimumDepth >= Fate.RankMod[Rank.Legendary].levelOffset)
					{
						float min2 = Fate.ItemRankChanceLegendary.Min;
						float max2 = Fate.ItemRankChanceLegendary.Max;
						float num3 = Mathf.Clamp01(Mathf.InverseLerp(Fate.RankMod[Rank.Legendary].levelOffset, 100f, depth));
						float num4 = min2 + (max2 - min2) * num3;
						if (UnityEngine.Random.value < num4)
						{
							ImproveItemToRank(item, Rank.Legendary, depth);
							return true;
						}
					}
					return false;
				}
			}
			return false;
		}

		public static void ImproveItemToRank(Item item, Rank rank, int depth)
		{
			if (rank == Rank.Normal)
			{
				return;
			}
			Fate.RankSetup rankSetup = Fate.RankMod[rank];
			foreach (ElementAmount damageBonuse in item.damageBonuses)
			{
				damageBonuse.value = Mathf.RoundToInt((float)damageBonuse.value * rankSetup.powerMultiplier);
			}
			item.sockets = Mathf.Min(Mathf.RoundToInt((float)item.sockets * rankSetup.powerMultiplier), item.slotsTall);
			item.toHitBonus = Mathf.RoundToInt((float)item.toHitBonus * rankSetup.toHitMultiplier);
			foreach (AttributeData itemRequirement in item.itemRequirements)
			{
				itemRequirement.value = Mathf.RoundToInt((float)itemRequirement.value * rankSetup.requirementMultiplier);
			}
			int num;
			if (rank == Rank.Elite)
			{
				num = (depth - 15) / 10;
				if (num > 10)
				{
					num = 10;
				}
				num = Fate.MaxFame - 17 + num;
				num = Mathf.Clamp(num, 0, Fate.MaxFame);
			}
			else
			{
				num = (depth - 15) / 7;
				if (num > 10)
				{
					num = 10;
				}
				num = Fate.MaxFame - 12 + num;
				num = Mathf.Clamp(num, 0, Fate.MaxFame);
			}
			item.itemRequirements.Add(new AttributeData
			{
				attribute = Attribute.Renown,
				value = num
			});
			item.value = Mathf.RoundToInt((float)item.value * rankSetup.priceMultiplier);
			item.rank = rank;
		}

		public static void ApplyMagicFindToInventory(List<Item> inventory, bool applyToEquippedItems)
		{
			if (inventory == null || inventory.Count == 0)
			{
				return;
			}
			if (LevelGenerator.currentInstance == null)
			{
				UnityEngine.Debug.LogError("Could not apply magic find to items, need to be in dungeon level");
				return;
			}
			(float, int, int) magicFindParams = DetermineMagicFindParameters();
			foreach (Item item in inventory)
			{
				bool inEquipmentSlot = item.InEquipmentSlot;
				if (!inEquipmentSlot || (inEquipmentSlot && applyToEquippedItems))
				{
					ApplyMagicFindToItem(item, magicFindParams);
				}
			}
		}

		public static void ApplyMagicFindToItem(Item item)
		{
			if (item != null)
			{
				if (LevelGenerator.currentInstance == null)
				{
					UnityEngine.Debug.LogError("Could not apply magic find to items, need to be in dungeon level");
					return;
				}
				(float, int, int) magicFindParams = DetermineMagicFindParameters();
				ApplyMagicFindToItem(item, magicFindParams);
			}
		}

		public static void ApplyMagicFindToItem(Item item, (float chance, int minimumLevel, int targetLevel) magicFindParams)
		{
			if (item == null)
			{
				return;
			}
			if (LevelGenerator.currentInstance == null)
			{
				UnityEngine.Debug.LogError("Could not apply magic find to items, need to be in dungeon level");
				return;
			}
			ItemCategory category = item.category;
			if ((category == ItemCategory.Weapon || category == ItemCategory.Armor || category == ItemCategory.Jewelry) && (item.effects == null || item.effects.Count <= 0) && (item.damageBonuses == null || item.damageBonuses.Count <= 0) && !item.IsHeroItem() && !item.isArtifact && UnityEngine.Random.value < magicFindParams.chance)
			{
				if (UnityEngine.Random.value < 0.2f)
				{
					item.BestowUniquePowers(magicFindParams.targetLevel, AllowCurse: true, magicFindParams.minimumLevel);
				}
				else
				{
					item.TryBestowPowers(magicFindParams.targetLevel, AllowCurse: true, magicFindParams.minimumLevel);
				}
			}
		}

		private static (float chance, int minimumLevel, int targetLevel) DetermineMagicFindParameters()
		{
			Fate.DifficultySetup difficultySetup = Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty];
			int effectiveDungeonDepth = GetEffectiveDungeonDepth();
			float num = Player.PlayerChar.EffectValue(EffectType.PercentMagicalDrop) / 100f;
			if (num > 0.75f)
			{
				num = 0.75f;
			}
			int num2 = Mathf.Max(1, effectiveDungeonDepth - 2);
			num2 = (int)((float)num2 * difficultySetup.difficultyMultiplier);
			num2 += difficultySetup.levelBase;
			if (num2 < 1)
			{
				num2 = 1;
			}
			int num3 = UnityEngine.Random.Range(num2, effectiveDungeonDepth + 3);
			if (effectiveDungeonDepth <= 1 && num3 > 2)
			{
				num3 = 2;
			}
			num3 = (int)((float)num3 * difficultySetup.difficultyMultiplier);
			num3 += difficultySetup.levelBase;
			if (num3 < 1)
			{
				num3 = 1;
			}
			return (chance: num, minimumLevel: num2, targetLevel: num3);
		}

		public static Randomizer GenerateFishingRandomizer(int depth, bool itemRepeatEnabled)
		{
			Randomizer randomizer = new Randomizer();
			int num = depth;
			num -= 10;
			if (num < 1)
			{
				num = 1;
			}
			RealmData.RealmId currentRealm = (SingletonBehaviour<Town>.InstanceExists() ? SingletonBehaviour<PlayerStatus>.Instance.TownRealm : SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
			for (int i = 0; i < allItems.Count; i++)
			{
				ItemData itemData = allItems[i];
				if (!itemData.reserved && itemData.takeable && !itemData.autoPickup && itemData.itemType != ItemType.Orb && (itemData.realmData == null || itemData.realmData.Count <= 0 || itemData.realmData.Find((RealmOverrideData rd) => rd.realmId == (int)currentRealm) != null))
				{
					int num2 = ((itemData.minimumFishingDepth != 0) ? itemData.minimumFishingDepth : itemData.minimumDepth);
					int num3 = ((itemData.maximumFishingDepth != 0) ? itemData.maximumFishingDepth : itemData.maximumDepth);
					if (num3 == 0)
					{
						num3 = 32000;
					}
					if ((num2 <= num && num3 >= num) || (itemRepeatEnabled && num2 <= num))
					{
						int num4 = ((itemData.fishingRarity != 0) ? itemData.fishingRarity : itemData.rarity);
						int odds = ((num4 < 1000) ? (1000 - num4) : 1000);
						randomizer.AddChoice(i, odds);
					}
				}
			}
			return randomizer;
		}
	}
	[Serializable]
	public class AttributeSet
	{
		private class AttributeValue
		{
			public int baseValue;

			public int baseModifiers;

			public int modifiers;

			public int multiplier;

			public int BaseValue => baseValue + baseModifiers;

			public AttributeValue(int baseValue)
			{
				this.baseValue = baseValue;
				baseModifiers = 0;
				modifiers = 0;
				multiplier = 0;
			}

			public int GetValue(bool withModifiers = true)
			{
				if (!withModifiers)
				{
					return BaseValue;
				}
				return Mathf.FloorToInt((float)(BaseValue + modifiers) * (1f + (float)multiplier * 0.01f));
			}
		}

		private Dictionary<Attribute, AttributeValue> allAttributes;

		public Action<Attribute, int> onAttributeValueChanged;

		public List<AppliedEffect> activeEffects;

		public int Strength => GetAttribute(Attribute.Strength, allowEffects: true);

		public int Dexterity => GetAttribute(Attribute.Dexterity, allowEffects: true);

		public int Vitality => GetAttribute(Attribute.Vitality, allowEffects: true);

		public int Magic => GetAttribute(Attribute.Magic, allowEffects: true);

		public int AttributeCount => allAttributes.Keys.Count;

		public AttributeSet(Action<Attribute, int> onAttribValueChange)
			: this(0, 0, 0, 0, onAttribValueChange)
		{
		}

		public AttributeSet(int baseStr, int baseDex, int baseVit, int baseMag, Action<Attribute, int> onAttribValueChange)
		{
			allAttributes = new Dictionary<Attribute, AttributeValue>
			{
				{
					Attribute.Strength,
					new AttributeValue(baseStr)
				},
				{
					Attribute.Dexterity,
					new AttributeValue(baseDex)
				},
				{
					Attribute.Vitality,
					new AttributeValue(baseVit)
				},
				{
					Attribute.Magic,
					new AttributeValue(baseMag)
				}
			};
			activeEffects = new List<AppliedEffect>();
			onAttributeValueChanged = onAttribValueChange;
		}

		public AttributeSet(AttributeSave[] attributes, Action<Attribute, int> onAttribValueChange)
		{
			allAttributes = new Dictionary<Attribute, AttributeValue>();
			for (int i = 0; i < attributes.Length; i++)
			{
				allAttributes.Add(attributes[i].attrib, new AttributeValue(attributes[i].baseValue));
			}
			activeEffects = new List<AppliedEffect>();
			onAttributeValueChanged = onAttribValueChange;
		}

		public AttributeSave[] GetSaveData()
		{
			AttributeSave[] array = new AttributeSave[AttributeCount];
			int num = 0;
			foreach (KeyValuePair<Attribute, AttributeValue> allAttribute in allAttributes)
			{
				array[num++] = new AttributeSave
				{
					attrib = allAttribute.Key,
					baseValue = allAttribute.Value.baseValue
				};
			}
			return array;
		}

		public int GetAttribute(Attribute attribute, bool allowEffects, bool addIfNull = true)
		{
			if (allAttributes.TryGetValue(attribute, out var value))
			{
				int num = value.GetValue(allowEffects);
				if (allowEffects && Fate.IsSkill(attribute))
				{
					num += GetAttribute(Attribute.AllSkills, allowEffects: true);
				}
				return num;
			}
			if (addIfNull)
			{
				allAttributes.Add(attribute, new AttributeValue(0));
			}
			return 0;
		}

		public void AddBasePoints(Attribute attribute, int amount)
		{
			if (allAttributes.TryGetValue(attribute, out var value))
			{
				value.baseValue += amount;
				if (value.baseValue < 0)
				{
					value.baseValue = 0;
				}
				if ((attribute == Attribute.Strength || attribute == Attribute.Dexterity || attribute == Attribute.Vitality || attribute == Attribute.Magic) && value.baseValue == 0)
				{
					value.baseValue = 1;
				}
				onAttributeValueChanged?.Invoke(attribute, value.GetValue());
			}
			else
			{
				allAttributes.Add(attribute, new AttributeValue(amount));
				onAttributeValueChanged?.Invoke(attribute, GetAttribute(attribute, allowEffects: true));
			}
		}

		public void SetBasePoints(Attribute attribute, int amount)
		{
			if (allAttributes.TryGetValue(attribute, out var value))
			{
				value.baseValue = amount;
				onAttributeValueChanged?.Invoke(attribute, value.GetValue());
			}
			else
			{
				allAttributes.Add(attribute, new AttributeValue(amount));
				onAttributeValueChanged?.Invoke(attribute, GetAttribute(attribute, allowEffects: true));
			}
		}

		public bool AddEffect(AppliedEffect appliedEffect, bool doCallback = true)
		{
			if (appliedEffect == null || appliedEffect.BuffType == EffectType.None)
			{
				return false;
			}
			AppliedEffect appliedEffect2 = activeEffects.Find((AppliedEffect a) => a == appliedEffect);
			if (appliedEffect2 != null && appliedEffect2.Exclusive && !RemoveEffect(appliedEffect2))
			{
				UnityEngine.Debug.LogWarning("Failed to remove existing effect: " + appliedEffect2.Name);
				return false;
			}
			if (appliedEffect.BuffType == EffectType.RemoveEffect)
			{
				List<AppliedEffect> list = activeEffects.FindAll((AppliedEffect a) => a.Name == appliedEffect.Name);
				bool flag = list != null && list.Count > 0;
				if (flag)
				{
					foreach (AppliedEffect item in list)
					{
						RemoveEffect(item);
					}
				}
				return flag;
			}
			activeEffects.Add(appliedEffect);
			ApplyBuffModifier(appliedEffect.BuffType, appliedEffect.Value, appliedEffect.Permanent && appliedEffect.Exclusive, doCallback);
			return true;
		}

		public bool RemoveEffect(AppliedEffect effectData, bool doCallback = true)
		{
			if (effectData == null || effectData.BuffType == EffectType.None)
			{
				return false;
			}
			AppliedEffect appliedEffect = activeEffects.Find((AppliedEffect a) => a == effectData);
			if (appliedEffect == null)
			{
				UnityEngine.Debug.LogWarning("Effect not found: " + effectData.Name);
				return false;
			}
			if (!activeEffects.Remove(appliedEffect))
			{
				UnityEngine.Debug.LogWarning("Failed to remove existing effect: " + appliedEffect.Name);
				return false;
			}
			ApplyBuffModifier(effectData.BuffType, -effectData.Value, effectData.Permanent && effectData.Exclusive, doCallback);
			return true;
		}

		private void ApplyBuffModifier(EffectType effectType, int change, bool applyToBase, bool doCallback)
		{
			Attribute attribute = EffectTypeToAttribute(effectType);
			if (attribute != 0)
			{
				if (!allAttributes.ContainsKey(attribute))
				{
					allAttributes.Add(attribute, new AttributeValue(0));
				}
				AttributeValue attributeValue = allAttributes[attribute];
				if (attributeValue == null)
				{
					attributeValue = new AttributeValue(0);
					allAttributes[attribute] = attributeValue;
				}
				if (Fate.EffectIsPercent(effectType))
				{
					attributeValue.multiplier += change;
				}
				else if (applyToBase)
				{
					attributeValue.baseModifiers += change;
				}
				else
				{
					attributeValue.modifiers += change;
				}
				if (doCallback)
				{
					onAttributeValueChanged?.Invoke(attribute, GetAttribute(attribute, allowEffects: true));
				}
			}
		}

		private Attribute EffectTypeToAttribute(EffectType eType)
		{
			switch (eType)
			{
			case EffectType.Strength:
			case EffectType.PercentStrength:
				return Attribute.Strength;
			case EffectType.Dexterity:
			case EffectType.PercentDexterity:
				return Attribute.Dexterity;
			case EffectType.Vitality:
			case EffectType.PercentVitality:
				return Attribute.Vitality;
			case EffectType.Magic:
			case EffectType.PercentMagic:
				return Attribute.Magic;
			case EffectType.SkillSword:
				return Attribute.SkillSword;
			case EffectType.SkillClub:
				return Attribute.SkillClub;
			case EffectType.SkillHammer:
				return Attribute.SkillHammer;
			case EffectType.SkillAxe:
				return Attribute.SkillAxe;
			case EffectType.SkillSpear:
				return Attribute.SkillSpear;
			case EffectType.SkillStaff:
				return Attribute.SkillStaff;
			case EffectType.SkillPolearm:
				return Attribute.SkillPolearm;
			case EffectType.SkillBow:
				return Attribute.SkillBow;
			case EffectType.SkillDualWield:
				return Attribute.SkillDualWield;
			case EffectType.SkillShield:
				return Attribute.SkillShield;
			case EffectType.SkillAttackMagic:
				return Attribute.SkillAttackMagic;
			case EffectType.SkillDefenseMagic:
				return Attribute.SkillDefenseMagic;
			case EffectType.SkillCharmMagic:
				return Attribute.SkillCharmMagic;
			case EffectType.AllSkills:
				return Attribute.AllSkills;
			case EffectType.SkillCriticalStrike:
				return Attribute.SkillCriticalStrike;
			case EffectType.SkillSpellCasting:
				return Attribute.SkillSpellcasting;
			default:
				return Attribute.None;
			}
		}

		public Attribute WeaponTypeToSkillAttribute(ItemType eType)
		{
			return eType switch
			{
				ItemType.Sword => Attribute.SkillSword, 
				ItemType.Club => Attribute.SkillClub, 
				ItemType.Hammer => Attribute.SkillHammer, 
				ItemType.EndHammer => Attribute.SkillHammer, 
				ItemType.Axe => Attribute.SkillAxe, 
				ItemType.Spear => Attribute.SkillSpear, 
				ItemType.Staff => Attribute.SkillStaff, 
				ItemType.Polearm => Attribute.SkillPolearm, 
				ItemType.Bow => Attribute.SkillBow, 
				ItemType.Crossbow => Attribute.SkillBow, 
				ItemType.Shield => Attribute.SkillShield, 
				_ => Attribute.None, 
			};
		}

		public EffectType SkillAttributeToSkillEffect(Attribute eType)
		{
			return eType switch
			{
				Attribute.SkillSword => EffectType.SkillSword, 
				Attribute.SkillClub => EffectType.SkillClub, 
				Attribute.SkillHammer => EffectType.SkillHammer, 
				Attribute.SkillAxe => EffectType.SkillAxe, 
				Attribute.SkillSpear => EffectType.SkillSpear, 
				Attribute.SkillStaff => EffectType.SkillStaff, 
				Attribute.SkillPolearm => EffectType.SkillPolearm, 
				Attribute.SkillBow => EffectType.SkillBow, 
				Attribute.SkillShield => EffectType.SkillShield, 
				Attribute.SkillCriticalStrike => EffectType.SkillCriticalStrike, 
				Attribute.SkillSpellcasting => EffectType.SkillSpellCasting, 
				_ => EffectType.None, 
			};
		}
	}
