		public void Init(MonsterData monsterData)
		{
			this.monsterData = monsterData;
			baseLevel = monsterData.baseLevel;
			naturalArmor = monsterData.naturalArmor;
			toHitBonus = monsterData.toHit;
			scale = monsterData.scale.GetValue();
			Level = baseLevel;
			nextLevelExperience = Fate.GetExperienceNeeded(Level);
			experienceReward = monsterData.experience;
			attributes = new AttributeSet(DefaultIfZero(monsterData.strength), DefaultIfZero(monsterData.dexterity), DefaultIfZero(monsterData.vitality), DefaultIfZero(monsterData.magic), OnAttributesChange);
			effects = new Dictionary<ActivationType, List<AppliedEffect>>();
			currentEffectValues = new Dictionary<EffectType, int>();
			damageResists = new Dictionary<DamageType, int>();
			knownSpells = new Dictionary<SpellSphere, List<SpellData>>();
			CharacterName = monsterData.displayName;
			BaseName = CharacterName;
			magicAttackRarity = 1000;
			if (monsterData.effects != null)
			{
				for (int i = 0; i < monsterData.effects.Count; i++)
				{
					monsterData.effects[i].permanent = true;
					AddEffect(monsterData.effects[i], baseLevel, null);
				}
			}
			if (monsterData.damageResists != null)
			{
				for (int j = 0; j < monsterData.damageResists.Count; j++)
				{
					ElementAmount elementAmount = monsterData.damageResists[j];
					if (damageResists.ContainsKey(elementAmount.type))
					{
						damageResists[elementAmount.type] += elementAmount.value;
					}
					else
					{
						damageResists.Add(elementAmount.type, elementAmount.value);
					}
				}
			}
			InitSpells(monsterData.spells, null);
			family = monsterData.family;
			damageResists[DamageType.Undead] = ((family != Tableflip.Family.Undead) ? 100 : 0);
			if (IsBoss)
			{
				damageResists[DamageType.Heroic] = 0;
				fameReward = UnityEngine.Random.Range(Level * 10, Level * 20);
				AddQuestHighlight();
			}
			alignment = monsterData.alignment;
			maxHpBase = Mathf.RoundToInt(monsterData.hpRange.GetValue());
			float num = 1f;
			if (monsterData.hpRange.Max - monsterData.hpRange.Min <= 0f)
			{
				num = (float)maxHpBase - monsterData.hpRange.Min / monsterData.hpRange.Max - monsterData.hpRange.Min;
				if (monsterData.hpRange.Max - monsterData.hpRange.Min == 0f)
				{
					num = 0f;
				}
			}
			num *= monsterData.scale.Max - monsterData.scale.Min;
			myTransform.localScale = Vector3.one * (monsterData.scale.Min + num);
			InternalInit();
			activeWeaponSet = WeaponSet.Primary;
			if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryInitialized)
			{
				GiveDefaultItems();
				return;
			}
			PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
			instance.OnInventoryInit = (Action)Delegate.Combine(instance.OnInventoryInit, new Action(GiveDefaultItems));
			static int DefaultIfZero(int value)
			{
				if (value != 0)
				{
					return value;
				}
				return 16;
			}
			void GiveDefaultItems()
			{
				PlayerUI instance2 = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance2.OnInventoryInit = (Action)Delegate.Remove(instance2.OnInventoryInit, new Action(GiveDefaultItems));
				if (monsterData.family != Tableflip.Family.Nemesis)
				{
					GiveEquipment();
				}
			}
		}

		public void GiveEquipment()
		{
			if (levelData == null || IsPet() || IsSummoned() || isLoadedFromSave)
			{
				return;
			}
			int num = Mathf.CeilToInt((float)Level * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier);
			if (isUnique)
			{
				num += 10;
			}
			int num2 = UnityEngine.Random.Range(0, 100);
			if (num2 < 5)
			{
				gold += UnityEngine.Random.Range(num, 4 * num);
			}
			if (IsMimic())
			{
				gold += UnityEngine.Random.Range(2 * num, 15 * num);
				gold += UnityEngine.Random.Range(2 * num, 15 * num);
				gold += UnityEngine.Random.Range(2 * num, 15 * num);
			}
			num2 = UnityEngine.Random.Range(0, 100);
			if (num2 < 5 || IsMimic())
			{
				Item item = levelData.GenerateTakeableItem();
				if (item != null)
				{
					AddItemToInventory(item, AddItemReason.StartingItems);
					num2 = UnityEngine.Random.Range(0, 100);
					if ((float)num2 * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier > 90f || (isUnique && num2 > 50))
					{
						if ((float)UnityEngine.Random.Range(0, 100) * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier > 80f)
						{
							item.BestowUniquePowers(num, AllowCurse: false, Level);
						}
						else
						{
							item.TryBestowPowers(num, AllowCurse: false, Level);
						}
					}
					if ((float)UnityEngine.Random.Range(0, 100) < 8f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
					{
						item.BestowSockets(AllowUnique: false);
					}
					if ((float)UnityEngine.Random.Range(0, 1000) < 50f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
					{
						item.BestowGrade(SingletonBehaviour<PlayerStatus>.Instance.Difficulty);
					}
				}
			}
			if (isUnique)
			{
				gold += UnityEngine.Random.Range(4 * LevelGenerator.effectiveLevelDepth, 10 * LevelGenerator.effectiveLevelDepth);
				Item item2 = levelData.GenerateRareTakeableItem();
				if (item2 != null)
				{
					AddItemToInventory(item2, AddItemReason.StartingItems);
					if (UnityEngine.Random.Range(0, 100) > 95)
					{
						item2.BestowUniquePowers(num, AllowCurse: false, Level);
					}
					else
					{
						item2.TryBestowPowers(num, AllowCurse: false, Level);
					}
					if (UnityEngine.Random.Range(0, 100) < 15)
					{
						item2.BestowSockets(AllowUnique: false);
					}
					if (UnityEngine.Random.Range(0, 1000) < 50)
					{
						item2.BestowGrade(SingletonBehaviour<PlayerStatus>.Instance.Difficulty);
					}
				}
			}
			int num3 = LevelGenerator.effectiveLevelDepth;
			if (isUnique)
			{
				num3 = (int)((float)num3 * 1.5f);
				num3 += 5;
			}
			if (!monsterData.CanEquip(ItemSlot.RightHand))
			{
				return;
			}
			num2 = UnityEngine.Random.Range(0, 100);
			ItemData itemData = null;
			List<string> preferredWeapons = monsterData.preferredWeapons;
			if (preferredWeapons != null && preferredWeapons.Count > 0 && UnityEngine.Random.Range(0, 1000) < 500)
			{
				int index = UnityEngine.Random.Range(0, monsterData.preferredWeapons.Count);
				foreach (ItemData item4 in LevelGenerator.currentInstance.itemDataManifest)
				{
					if (monsterData.preferredWeapons[index] == item4.displayName)
					{
						itemData = item4;
						break;
					}
				}
				if (itemData != null && (itemData.minimumDepth > num3 || num3 - itemData.minimumDepth > 50))
				{
					itemData = null;
				}
			}
			Item item3 = null;
			if (itemData == null)
			{
				if (isUnique)
				{
					item3 = LevelGenerator.currentInstance.GenerateRareWeaponItem();
				}
				else if (num2 > 70)
				{
					item3 = LevelGenerator.currentInstance.GenerateWeaponItem();
				}
			}
			if (item3 == null && itemData != null)
			{
				item3 = new Item(itemData);
			}
			if (item3 == null)
			{
				return;
			}
			AddItemToInventory(item3, AddItemReason.StartingItems);
			num2 = UnityEngine.Random.Range(0, 100);
			if (num2 > 90 || (isUnique && num2 > 60))
			{
				if (UnityEngine.Random.Range(0, 100) > 90)
				{
					item3.BestowUniquePowers(num, AllowCurse: false, Level);
				}
				else
				{
					item3.TryBestowPowers(num, AllowCurse: false, Level);
				}
			}
			if (UnityEngine.Random.Range(0, 100) < 15)
			{
				item3.BestowSockets(AllowUnique: false);
			}
			if (UnityEngine.Random.Range(0, 1000) < 50)
			{
				item3.BestowGrade(SingletonBehaviour<PlayerStatus>.Instance.Difficulty);
			}
			AttemptAutoEquip(item3);
		}

		public void Init(FateSaveData saveData)
		{
			Init(saveData.playerSaveData, saveData.itemSaveData);
			SingletonBehaviour<PlayerStatus>.Instance.LoadSaveData(saveData);
		}

		public virtual void Init(PlayerSaveData playerSaveData, ItemStorage itemStorage)
		{
			race = playerSaveData.playerRace;
			experience = playerSaveData.experience;
			Level = baseLevel + Fate.GetLevelFromExperience(experience);
			nextLevelExperience = Fate.GetExperienceNeeded(Level);
			if (IsPlayer())
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetLevel(Level);
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetXP(GetPctToNextLevel(), experience, Fate.GetExperienceNeeded(Level));
			}
			fame = playerSaveData.fame;
			fameRank = Fate.GetFameTier(fame);
			unusedSkillPoints = playerSaveData.unallocatedSkillPoints;
			unusedStatPoints = playerSaveData.unallocatedStatPoints;
			if (playerSaveData.attributes == null)
			{
				attributes = new AttributeSet(25, 20, 25, 10, OnAttributesChange);
			}
			else
			{
				attributes = new AttributeSet(playerSaveData.attributes, OnAttributesChange);
			}
			effects = new Dictionary<ActivationType, List<AppliedEffect>>();
			currentEffectValues = new Dictionary<EffectType, int>();
			damageResists = new Dictionary<DamageType, int>();
			knownSpells = new Dictionary<SpellSphere, List<SpellData>>();
			lineage = playerSaveData.lineage;
			RaceData raceData = SingletonBehaviour<FateDB>.Instance.allRaces.Find((RaceData r) => r.race == race);
			if (raceData != null && raceData.bonusEffects != null)
			{
				for (int k = 0; k < raceData.bonusEffects.Length; k++)
				{
					raceData.bonusEffects[k].permanent = true;
					AddEffect(raceData.bonusEffects[k], 1, null);
				}
			}
			if (playerSaveData.activeWeaponSet == WeaponSet.Invalid)
			{
				playerSaveData.activeWeaponSet = WeaponSet.Primary;
				foreach (Item item3 in inventory.FindAll((Item i) => i.InEquipmentSlot && (i.IsInMainHand || i.IsInOffHand)))
				{
					item3.weaponSet = WeaponSet.Primary;
				}
			}
			SetActiveWeaponSet(playerSaveData.activeWeaponSet);
			if (itemStorage != null && itemStorage.items != null)
			{
				int[,] inventoryGridSize = GetInventoryGridSize();
				if (inventoryGridSize != null)
				{
					int length = inventoryGridSize.GetLength(1);
					int length2 = inventoryGridSize.GetLength(0);
					inventorySlotsOccupied = new bool[length, length2];
				}
				List<ItemSaveData> savedItems = itemStorage.items;
				List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
				int j = 0;
				while (j < savedItems.Count)
				{
					ItemData itemData = allItems.Find((ItemData a) => a.displayName == savedItems[j].baseName);
					if (itemData == null)
					{
						UnityEngine.Debug.LogError("Unable to find item info: " + savedItems[j].baseName);
					}
					else
					{
						Item item = new Item(itemData);
						item.ApplyInstance(savedItems[j]);
						if (!AddItemToInventory(item, AddItemReason.LoadFromSave, item.slotIndex))
						{
							item.Drop(base.transform.position, skipSoundAndDropTween: true);
						}
					}
					int num = j + 1;
					j = num;
				}
			}
			InitSpells(playerSaveData.spellsKnown, playerSaveData.activeSpell);
			if (IsPlayer())
			{
				if (inventorySlotsOccupied == null)
				{
					int[,] inventoryGridSize2 = GetInventoryGridSize();
					if (inventoryGridSize2 != null)
					{
						int length3 = inventoryGridSize2.GetLength(1);
						int length4 = inventoryGridSize2.GetLength(0);
						inventorySlotsOccupied = new bool[length3, length4];
					}
				}
				(this as Player).SetIntentionToRun(playerSaveData.intendsToRun);
				if (playerSaveData.giveStartingItems)
				{
					if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryInitialized)
					{
						GiveStartingItems();
					}
					else
					{
						PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
						instance.OnInventoryInit = (Action)Delegate.Combine(instance.OnInventoryInit, new Action(GiveStartingItems));
					}
					playerSaveData.giveStartingItems = false;
					SingletonBehaviour<PlayerStatus>.Instance.giveStartingGold = true;
					SaveData.RequestSave();
				}
			}
			OnEffectsLoad(playerSaveData.effects);
			InternalInit();
			if (playerSaveData.health > 1f)
			{
				hp = playerSaveData.health;
				if (IsPlayer() && HPPercentage() <= 0.3f && !isHeartBeatPlaying)
				{
					SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.Heartbeat);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Heartbeat, randomizePitch: false);
					isHeartBeatPlaying = true;
				}
			}
			stamina = playerSaveData.stamina;
			void GiveStartingItems()
			{
				PlayerUI instance2 = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance2.OnInventoryInit = (Action)Delegate.Remove(instance2.OnInventoryInit, new Action(GiveStartingItems));
				if (raceData == null)
				{
					raceData = SingletonBehaviour<FateDB>.Instance.allRaces.Find((RaceData r) => r.race == Race.Human);
				}
				int l = 0;
				while (l < raceData.startingItems.Length)
				{
					ItemData itemData2 = SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData a) => a.displayName == raceData.startingItems[l]);
					if (itemData2 == null)
					{
						UnityEngine.Debug.LogError("Hero Starting item not found: " + raceData.startingItems[l]);
					}
					else
					{
						Item item2 = new Item(itemData2);
						AddItemToInventory(item2, AddItemReason.StartingItems);
						AttemptAutoEquip(item2);
					}
					int num2 = l + 1;
					l = num2;
				}
				if (SingletonBehaviour<PlayerStatus>.Instance.IsHandlingRetirement)
				{
					SingletonBehaviour<PlayerStatus>.Instance.IsHandlingRetirement = false;
					int level = Level;
					Level += ((lineage != 0) ? 1 : 0);
					if (Level != level)
					{
						LevelUp(level, skipNarration: true);
					}
					experience = Fate.GetExperienceNeeded(Level - 1) + 1;
					nextLevelExperience = Fate.GetExperienceNeeded(Level);
					int num3 = ((lineage != 0) ? Mathf.Min((int)lineage, 10) : 0);
					if (num3 != 0)
					{
						SetFameRank(num3);
					}
					StatsManager.IncrementStat(Stat.DescendantsCreated);
				}
			}
		}

		protected void InternalInit()
		{
			CalculateMaxHP();
			CalculateMaxMana();
			CalculateMaxStamina();
			hp = MaxHP();
			mana = MaxMana();
			stamina = MaxStamina();
			if (effectTickerRoutine == null)
			{
				effectTickerRoutine = StartCoroutine(EffectTicker());
			}
			if (inventorySlotsOccupied == null)
			{
				int[,] inventoryGridSize = GetInventoryGridSize();
				if (inventoryGridSize != null)
				{
					int length = inventoryGridSize.GetLength(1);
					int length2 = inventoryGridSize.GetLength(0);
					inventorySlotsOccupied = new bool[length, length2];
				}
			}
			SetUpRotationConstraint();
			UpdateNavmeshAvoidance();
			hasInitializedInternal = true;
		}

		private void SetUpRotationConstraint()
		{
			constraintSource = default(ConstraintSource);
			constraintSource.weight = 1f;
			if (SingletonBehaviour<Town>.InstanceExists())
			{
				constraintSource.sourceTransform = SingletonBehaviour<Town>.Instance.transform;
				return;
			}
			if (LevelGenerator.currentInstance != null)
			{
				constraintSource.sourceTransform = LevelGenerator.currentInstance.transform;
				return;
			}
			GameObject gameObject = new GameObject("_RotationConstraint_For_" + base.name);
			constraintSource.sourceTransform = gameObject.transform;
			createdConstraint = true;
		}

		private void OnDestroy()
		{
			if (createdConstraint && constraintSource.sourceTransform != null)
			{
				UnityEngine.Object.Destroy(constraintSource.sourceTransform.gameObject);
			}
		}

		public void FillPlayerSaveData(ref PlayerSaveData playerSaveData)
		{
			playerSaveData.health = hp;
			playerSaveData.stamina = stamina;
			playerSaveData.playerRace = race;
			playerSaveData.attributes = attributes.GetSaveData();
			playerSaveData.experience = experience;
			playerSaveData.unallocatedSkillPoints = unusedSkillPoints;
			playerSaveData.unallocatedStatPoints = unusedStatPoints;
			playerSaveData.fame = fame;
			List<AppliedEffect> list = GetEffects();
			playerSaveData.effects = new List<EffectSave>();
			for (int i = 0; i < list.Count; i++)
			{
				playerSaveData.effects.Add(new EffectSave(list[i]));
			}
			playerSaveData.activeSpell = ((activeSpell != null) ? activeSpell.spellName : null);
			playerSaveData.spellsKnown = new List<string>();
			foreach (KeyValuePair<SpellSphere, List<SpellData>> knownSpell in knownSpells)
			{
				for (int j = 0; j < knownSpell.Value.Count; j++)
				{
					playerSaveData.spellsKnown.Add(knownSpell.Value[j].spellName);
				}
			}
			Character pet = GetPet();
			if (pet != null)
			{
				playerSaveData.petHealth = pet.hp;
				playerSaveData.petFleeing = pet.GetAIState() == AIState.Flee;
				playerSaveData.petTransformId = pet.transformId;
				bool flag = false;
				List<AppliedEffect> list2 = pet.GetEffects();
				if (list2 != null)
				{
					foreach (AppliedEffect item in list2)
					{
						if (item.BuffType == EffectType.Transform)
						{
							playerSaveData.petTransformTimeLeft = item.duration;
							flag = true;
							break;
						}
					}
				}
				if (!flag)
				{
					playerSaveData.petTransformTimeLeft = -1000;
				}
			}
			else
			{
				playerSaveData.petHealth = 0f;
				playerSaveData.petFleeing = false;
				playerSaveData.petTransformId = "";
				playerSaveData.petTransformTimeLeft = 0;
			}
		}

		private IEnumerator EffectTicker()
		{
			WaitForSeconds tickWait = new WaitForSeconds(1f);
			while (true)
			{
				yield return tickWait;
				if (!inActiveRange)
				{
					continue;
				}
				List<EffectType> list = new List<EffectType>();
				AppliedEffect appliedEffect = null;
				foreach (KeyValuePair<ActivationType, List<AppliedEffect>> effect in effects)
				{
					for (int i = 0; i < effect.Value.Count; i++)
					{
						AppliedEffect appliedEffect2 = effect.Value[i];
						if (!appliedEffect2.Permanent && appliedEffect2.duration != -1000 && appliedEffect2.duration != -1 && --appliedEffect2.duration <= 0)
						{
							if (appliedEffect2.BuffType == EffectType.Transform)
							{
								AIState aIState = GetAIState();
								if (aIState == AIState.ReturningToTown || aIState == AIState.InTown)
								{
									appliedEffect2.duration++;
									continue;
								}
								RevertTransformation(removeTransformEffect: false);
							}
							if (RemoveEffect(appliedEffect2))
							{
								i--;
							}
						}
						else
						{
							if (!list.Contains(appliedEffect2.BuffType))
							{
								list.Add(appliedEffect2.BuffType);
							}
							if (appliedEffect == null && appliedEffect2.BuffType == EffectType.HPRecharge && appliedEffect2.Value < 0)
							{
								appliedEffect = appliedEffect2;
							}
						}
					}
				}
				if (IsPassedOut())
				{
					continue;
				}
				ModifyMana((float)MaxMana() * 0.03f);
				for (int j = 0; j < list.Count; j++)
				{
					float num = EffectValue(list[j]);
					if (num != 0f)
					{
						float num2 = num * 0.016f;
						switch (list[j])
						{
						case EffectType.HPRecharge:
							ModifyHP(num2);
							break;
						case EffectType.HPPercentRecharge:
							ModifyHP((float)MaxHP() * num2 * 0.01f);
							break;
						case EffectType.ManaRecharge:
							ModifyMana(num2);
							break;
						case EffectType.ManaPercentRecharge:
							ModifyMana((float)MaxMana() * num2 * 0.01f);
							break;
						case EffectType.StaminaRecharge:
							ModifyStamina(num2);
							break;
						}
					}
				}
				myVitals.OnResourcesUpdated();
				if (!IsPet() && hp <= 0f && appliedEffect != null)
				{
					if (appliedEffect.source != null)
					{
						appliedEffect.source.DetectDeath(this, (int)hp);
					}
					myVitals.Die();
				}
			}
		}

		private void OnAttributesChange(Attribute attribute, int newValue)
		{
			switch (attribute)
			{
			case Attribute.Vitality:
				CalculateMaxHP();
				CalculateMaxStamina();
				break;
			case Attribute.Magic:
				CalculateMaxMana();
				break;
			}
		}

		public bool RequirementsMet(Item item)
		{
			if (item.itemRequirements == null)
			{
				return true;
			}
			float itemRequirementMultiplier = Mathf.Clamp01(1f - EffectValue(EffectType.PercentItemRequirements) / 100f);
			for (int i = 0; i < item.itemRequirements.Count; i++)
			{
				AttributeData attributeData = item.itemRequirements[i];
				if (!RequirementMet(attributeData.attribute, attributeData.value, allowEffects: true, itemRequirementMultiplier))
				{
					return false;
				}
			}
			return true;
		}

		public bool RequirementMet(Attribute attribute, int value, bool allowEffects, float itemRequirementMultiplier)
		{
			return attributes.GetAttribute(attribute, allowEffects) >= Mathf.FloorToInt((float)value * itemRequirementMultiplier);
		}

		public bool IsPassedOut()
		{
			return hp <= 0f;
		}

		public virtual void AddEffect(EffectSave savedEffect)
		{
			AppliedEffect appliedEffect = AddEffect(savedEffect.effectData, savedEffect.level, null, savedEffect.itemSlotIndex);
			appliedEffect.duration = savedEffect.duration;
			appliedEffect.sourceSpriteName = savedEffect.sourceSpriteName;
		}

		public virtual AppliedEffect AddEffect(EffectData effect, int sourceLevel, Character source, int itemSlotIndex = -1, bool isSpellEffect = false)
		{
			if (!effects.ContainsKey(effect.activationType) || effects[effect.activationType] == null)
			{
				effects[effect.activationType] = new List<AppliedEffect>();
			}
			if (effect.exclusive)
			{
				AppliedEffect appliedEffect = (string.IsNullOrEmpty(effect.name) ? effects[effect.activationType].Find((AppliedEffect e) => e.BuffType == effect.buffType && e.value == effect.value && e.value2 == effect.value2 && e.value3 == effect.value3) : effects[effect.activationType].Find((AppliedEffect e) => e.Name == effect.name));
				if (appliedEffect != null)
				{
					effects[effect.activationType].Remove(appliedEffect);
					RemovePSEffect(appliedEffect);
				}
			}
			AppliedEffect appliedEffect2 = new AppliedEffect(effect, sourceLevel, source, itemSlotIndex, isSpellEffect);
			if (!string.IsNullOrEmpty(effect.applicationMessage))
			{
				ThatHurt.PopText(myTransform.position, I2Loca.Get(effect.applicationMessage), 1f, ThatHurt.ThatHurtColor.White, 0f);
			}
			int num;
			if (effect.activationType == ActivationType.Usage)
			{
				if (effect.duration != -900)
				{
					num = ((effect.buffType == EffectType.KnockbackEffect) ? 1 : 0);
					if (num == 0)
					{
						goto IL_0183;
					}
				}
				else
				{
					num = 1;
				}
				ApplyInstantEffect(appliedEffect2);
				goto IL_01ad;
			}
			num = 0;
			goto IL_0183;
			IL_01ad:
			if (num == 0)
			{
				if (appliedEffect2.Positive)
				{
					switch (appliedEffect2.BuffType)
					{
					case EffectType.HPRecharge:
						if (string.IsNullOrEmpty(appliedEffect2.sourceSpriteName) && SingletonBehaviour<FateDB>.InstanceExists())
						{
							appliedEffect2.sourceSpriteName = "spellheal";
						}
						break;
					case EffectType.PercentLifeStolen:
						if (string.IsNullOrEmpty(appliedEffect2.sourceSpriteName) && SingletonBehaviour<FateDB>.InstanceExists())
						{
							appliedEffect2.sourceSpriteName = "spelllifedrain";
						}
						break;
					case EffectType.PercentSpeed:
					case EffectType.PercentAttackSpeed:
						if (string.IsNullOrEmpty(appliedEffect2.sourceSpriteName) && SingletonBehaviour<FateDB>.InstanceExists())
						{
							appliedEffect2.sourceSpriteName = "spellhaste";
						}
						break;
					case EffectType.ArmorBonus:
					case EffectType.PercentArmorBonus:
						if (string.IsNullOrEmpty(appliedEffect2.sourceSpriteName) && SingletonBehaviour<FateDB>.InstanceExists())
						{
							appliedEffect2.sourceSpriteName = "spellarmor";
						}
						break;
					}
				}
				else
				{
					switch (appliedEffect2.BuffType)
					{
					case EffectType.HPRecharge:
						if (string.IsNullOrEmpty(appliedEffect2.sourceSpriteName) && SingletonBehaviour<FateDB>.InstanceExists())
						{
							appliedEffect2.sourceSpriteName = "spellskeleton";
						}
						onPoisoned?.Invoke(obj: true);
						poisoned = true;
						if (IsPlayer() && SingletonBehaviour<PlayerUI>.InstanceExists())
						{
							SimpleSingletonBehaviour<PlayerUI>.Instance.SetPoisoned(poisoned: true);
						}
						if (IsPartyMember() && Master() != null && Master() == Player.PlayerChar && hasInitializedInternal)
						{
							SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_ally_Poisoned);
						}
						break;
					case EffectType.PercentLifeStolen:
						if (string.IsNullOrEmpty(appliedEffect2.sourceSpriteName) && SingletonBehaviour<FateDB>.InstanceExists())
						{
							appliedEffect2.sourceSpriteName = "spelllifedrain";
						}
						break;
					case EffectType.PercentSpeed:
						if (string.IsNullOrEmpty(appliedEffect2.sourceSpriteName) && SingletonBehaviour<FateDB>.InstanceExists())
						{
							if (!string.IsNullOrEmpty(appliedEffect2.Name) && appliedEffect2.Name.ToLower().Contains("web"))
							{
								appliedEffect2.sourceSpriteName = "spellweb";
							}
							else
							{
								appliedEffect2.sourceSpriteName = "spellslow";
							}
						}
						break;
					case EffectType.PercentAttackSpeed:
						if (string.IsNullOrEmpty(appliedEffect2.sourceSpriteName) && SingletonBehaviour<FateDB>.InstanceExists())
						{
							appliedEffect2.sourceSpriteName = "spellslow";
						}
						break;
					case EffectType.ArmorBonus:
					case EffectType.PercentArmorBonus:
						if (string.IsNullOrEmpty(appliedEffect2.sourceSpriteName) && SingletonBehaviour<FateDB>.InstanceExists())
						{
							appliedEffect2.sourceSpriteName = "spellfrailty";
						}
						break;
					}
				}
			}
			AddPSEffect(appliedEffect2);
			currentEffectValues[effect.buffType] = (int)CalculateEffectValue(effect.buffType);
			CalculateMaxHP();
			CalculateMaxMana();
			CalculateMaxStamina();
			onEffectApplied?.Invoke(appliedEffect2);
			return appliedEffect2;
			IL_0183:
			effects[effect.activationType].Add(appliedEffect2);
			attributes.AddEffect(appliedEffect2);
			goto IL_01ad;
		}

		protected void AddPSEffect(AppliedEffect effect)
		{
			if (effect == null || effect.BuffType == EffectType.RemoveEffect)
			{
				return;
			}
			GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab(effect.Name);
			if (particlePrefab == null)
			{
				return;
			}
			GameObject gameObject = UnityEngine.Object.Instantiate(particlePrefab, myTransform);
			RotationConstraint component = gameObject.GetComponent<RotationConstraint>();
			if (component != null)
			{
				if (component.sourceCount != 0)
				{
					component.SetSource(0, constraintSource);
				}
				else
				{
					component.AddSource(constraintSource);
				}
				component.constraintActive = true;
			}
			effectChildren.Add(gameObject);
		}

		protected void RemovePSEffect(AppliedEffect effect)
		{
			if (effect == null)
			{
				return;
			}
			for (int i = 0; i < effectChildren.Count; i++)
			{
				if (effectChildren[i] == null)
				{
					UnityEngine.Debug.LogWarning($"Found null entry in effect children list at index {i}");
					effectChildren.RemoveAt(i);
					i--;
				}
			}
			GameObject gameObject = effectChildren.Find((GameObject a) => !string.IsNullOrEmpty(a.name) && a.name.Split('_')[1].Split('(')[0].ToUpper() == effect.Name.ToUpper());
			if (gameObject != null)
			{
				effectChildren.Remove(gameObject);
				UnityEngine.Object.Destroy(gameObject);
			}
		}

		private void ApplyInstantEffect(AppliedEffect effect)
		{
			switch (effect.BuffType)
			{
			case EffectType.Flee:
				if (!IsPlayer() && (effect.DamageType != DamageType.Undead || !damageResists.ContainsKey(DamageType.Undead) || damageResists[DamageType.Undead] < 100) && (effect.DamageType != DamageType.Heroic || !damageResists.ContainsKey(DamageType.Heroic) || damageResists[DamageType.Heroic] < 100) && Level < effect.Value)
				{
					StopPathing();
					SetDestination(UnityEngine.Random.Range(myTransform.position.x - 100f, myTransform.position.x + 100f), UnityEngine.Random.Range(myTransform.position.z - 100f, myTransform.position.z + 100f));
					SetAIState(AIState.Flee);
				}
				break;
			case EffectType.KnockbackEffect:
			{
				Vector3 direction = myTransform.position - effect.source.myTransform.position;
				direction.y = 0f;
				direction.Normalize();
				Knockbacked(direction, effect.Value);
				break;
			}
			case EffectType.HP:
			case EffectType.HPRecharge:
				if (effect.Value < 0)
				{
					myVitals.ApplyDamage(new CharacterVitals.Damage
					{
						damageType = effect.DamageType,
						source = effect.source?.myVitals,
						value = -effect.Value
					}, allowReflection: false);
				}
				else
				{
					ModifyHP(effect.Value);
				}
				break;
			case EffectType.PercentMaxHP:
			case EffectType.HPPercentRecharge:
				ModifyHP((int)((float)MaxHP() * (float)effect.Value * 0.01f));
				break;
			case EffectType.Mana:
			case EffectType.ManaRecharge:
				ModifyMana(effect.Value);
				break;
			case EffectType.PercentMaxMana:
			case EffectType.ManaPercentRecharge:
				ModifyMana((int)((float)MaxMana() * (float)effect.Value * 0.01f));
				break;
			case EffectType.Discover:
				if (levelData != null)
				{
					levelData.DiscoverAll();
				}
				break;
			case EffectType.Dispel:
			{
				for (int l = 0; l < GetPetCount(); l++)
				{
					Character pet2 = GetPet(l);
					if (pet2.IsSummoned())
					{
						pet2.SetLifeDuration(0.01f);
					}
				}
				break;
			}
			case EffectType.RevertTransform:
			{
				AppliedEffect appliedEffect = (IsPet() ? GetTransformationEffect() : ((GetPetCount() > 0) ? GetPet().GetTransformationEffect() : null));
				if (appliedEffect != null)
				{
					appliedEffect.duration = 1;
				}
				break;
			}
			case EffectType.Summon:
			{
				MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData x) => x.displayName == effect.Name);
				if (!(monsterData != null))
				{
					break;
				}
				int value = effect.value;
				int num2 = Fate.MaxSummons - GetPetCount() + 1;
				if (IsPlayer() && num2 < value)
				{
					int num3 = value - num2;
					for (int j = 0; j < num3; j++)
					{
						Character pet = GetPet(1);
						if (pet.IsSummoned())
						{
							pet.Die();
						}
					}
				}
				for (int k = 0; k < value; k++)
				{
					if (GetPetCount() > Fate.MaxSummons)
					{
						continue;
					}
					Vector3 zero = Vector3.zero;
					zero = ((!(levelData != null)) ? myTransform.position : ((!IsShrine()) ? levelData.RandomOpenPosition(myTransform.position, 3f) : levelData.RandomOpenPosition(myTransform.position, 3f, 8f)));
					Character character;
					if (!(LevelGenerator.currentInstance == null))
					{
						LevelGenerator currentInstance = LevelGenerator.currentInstance;
						Vector3? targetLocation = zero;
						Alignment overrideAlignment = alignment;
						character = currentInstance.SpawnMonster(monsterData, targetLocation, null, -1, allowRankUp: false, overrideAlignment);
					}
					else
					{
						character = SingletonBehaviour<Town>.Instance.SpawnMonsterInTown(monsterData, zero);
					}
					Character character2 = character;
					GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("summonMonster");
					if (particlePrefab != null)
					{
						UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab, character2.myTransform.position, Quaternion.identity), 2f);
					}
					if (IsPlayer() || IsPartyMember())
					{
						character2.gameObject.layer = LayerMask.NameToLayer("Player");
					}
					character2.alignment = alignment;
					if (IsShrine())
					{
						character2.TweakToLevel(Mathf.FloorToInt((float)Level * 0.8f) + 1);
					}
					else
					{
						character2.TweakToLevel(effect.value2);
					}
					character2.GiveEquipment();
					character2.allowDropInventory = false;
					string characterName = character2.CharacterName;
					if (int.TryParse(characterName[characterName.Length - 1].ToString(), out var _))
					{
						character2.CharacterName = character2.CharacterName.Substring(0, character2.CharacterName.LastIndexOf('_'));
					}
					character2.SetLifeDuration(effect.value3);
					if (GetAlignment() != Alignment.Evil)
					{
						character2.UpdateGroundMarker(alignment);
					}
					GameObject gameObject = SingletonBehaviour<FateDB>.Instance.spellPrefabs.Find((GameObject p) => p.name.ToUpper() == "P_SUMMON");
					if (gameObject != null)
					{
						SkinnedMeshRenderer componentInChildren = character2.GetComponentInChildren<SkinnedMeshRenderer>(includeInactive: true);
						Vector3 position = character2.transform.position + character2.transform.forward;
						if (componentInChildren != null)
						{
							position += new Vector3(0f, componentInChildren.sharedMesh.bounds.extents.y * 0.75f, 0f);
						}
						else
						{
							position += Vector3.up;
						}
						Spell component = UnityEngine.Object.Instantiate(gameObject, position, Quaternion.identity).GetComponent<Spell>();
						component.Setup(activeSpell, this);
						component.SetTarget(character2);
						component.StartCast();
					}
					AddPet(character2);
				}
				break;
			}
			case EffectType.Rage:
				if (effect.source != null)
				{
					Character source = effect.source;
					int num4 = source.CharacterDamage() + source.RollWeaponDamage();
					num4 += Mathf.CeilToInt(num4 * effect.Value);
					int num5 = num4;
					num4 = ModifyDamage(num4, effect.DamageType, out var resistAmount);
					bool isFullResist = num5 > 0 && num5 == resistAmount;
					bool isPartialResist = num5 > 0 && resistAmount > 0 && resistAmount < num5;
					if (num4 > 0)
					{
						myVitals.ApplyDamage(new CharacterVitals.Damage
						{
							damageType = effect.DamageType,
							source = effect.source?.myVitals,
							value = num4,
							damageResisted = resistAmount,
							isFullResist = isFullResist,
							isPartialResist = isPartialResist
						});
					}
				}
				break;
			case EffectType.Stamina:
			case EffectType.StaminaRecharge:
				ModifyStamina(effect.Value);
				break;
			case EffectType.PercentStamina:
				ModifyStamina((int)((float)MaxStamina() * (float)effect.Value * 0.01f));
				break;
			case EffectType.OpenPortal:
				if (IsPlayer())
				{
					SingletonBehaviour<PortalManager>.Instance.TryCreatePortal(this);
				}
				break;
			case EffectType.RemoveEffect:
			{
				List<AppliedEffect> list = attributes.activeEffects.FindAll((AppliedEffect a) => a.Name == effect.Name);
				if (list == null)
				{
					break;
				}
				foreach (AppliedEffect item in list)
				{
					if (item != null)
					{
						RemoveEffect(item);
					}
				}
				break;
			}
			case EffectType.RecoverPassoutPartial:
			case EffectType.RecoverPassoutFull:
			{
				float num = ((effect.BuffType == EffectType.RecoverPassoutFull) ? 1f : 0.4f);
				if (IsPartyMember() && IsPassedOut())
				{
					ModifyHP((int)((float)MaxHP() * num));
					ClearEffects();
					SetAIState(AIState.Inactive);
				}
				for (int i = 0; i < GetPartyMemberCount(); i++)
				{
					Character partyMember = GetPartyMember(i);
					if (partyMember.IsPassedOut())
					{
						partyMember.ModifyHP((int)((float)MaxHP() * num));
						partyMember.ClearEffects();
						partyMember.SetAIState(AIState.Inactive);
					}
				}
				break;
			}
			}
			myVitals.OnResourcesUpdated();
			if (!IsPet() && hp <= 0f && effect.source != null)
			{
				effect.source.DetectDeath(this, (int)hp);
				myVitals.Die();
			}
		}

		protected void ClearEffects()
		{
			if (effects == null)
			{
				return;
			}
			foreach (KeyValuePair<ActivationType, List<AppliedEffect>> effect in effects)
			{
				for (int i = 0; i < effect.Value.Count; i++)
				{
					AppliedEffect appliedEffect = effect.Value[i];
					if (!appliedEffect.Permanent && !Fate.IsItemSlotInEquipmentSlot(appliedEffect.itemSlotIndex) && RemoveEffect(appliedEffect))
					{
						i--;
					}
				}
			}
		}

		protected void CalculateMaxMana()
		{
			_ = maxHpBase;
			maxManaBase = 2 * attributes.Magic + Level;
			int num = MaxMana();
			if (mana > (float)num)
			{
				mana = num;
			}
		}

		protected void CalculateMaxHP()
		{
			if (IsPlayer() || (IsPet() && HasMaster() && Master().IsPlayer()) || IsPartyMember())
			{
				MaxHP();
				maxHpBase = 4 * attributes.Vitality + 4 * Level + 18;
				int num = MaxHP();
				if (hp > (float)num)
				{
					hp = num;
				}
			}
		}

		protected void CalculateMaxStamina()
		{
			MaxStamina();
			maxStaminaBase = 2 * attributes.Vitality + Level;
			int num = MaxStamina();
			if (stamina > (float)num)
			{
				stamina = num;
			}
		}

		public virtual void TweakToLevel(int newLevel)
		{
			if (newLevel < 1)
			{
				newLevel = 1;
			}
			int num = newLevel - Level;
			if (num < 0)
			{
				num = 0;
			}
			experienceReward += Mathf.RoundToInt((float)experienceReward * 0.08f * (float)num);
			toHitBonus += num * UnityEngine.Random.Range(3, 5);
			naturalArmor += num * 2;
			attributes.AddBasePoints(Attribute.Dexterity, num * 3);
			attributes.AddBasePoints(Attribute.Vitality, num * 3);
			attributes.AddBasePoints(Attribute.Strength, num * 3);
			attributes.AddBasePoints(Attribute.Magic, num * 3);
			attributes.AddBasePoints(Attribute.SkillCharmMagic, num / 3);
			attributes.AddBasePoints(Attribute.SkillDefenseMagic, num / 3);
			attributes.AddBasePoints(Attribute.SkillAttackMagic, num / 3);
			attributes.AddBasePoints(Attribute.SkillSpellcasting, num / 3);
			if (attributes.GetAttribute(Attribute.SkillSpellcasting, allowEffects: false) > 10)
			{
				attributes.SetBasePoints(Attribute.SkillSpellcasting, 10);
			}
			maxHpBase += Mathf.CeilToInt(monsterData.hpRange.Min * (float)num * 0.5f);
			hp = MaxHP();
			Level = newLevel;
			nextLevelExperience = Fate.GetExperienceNeeded(Level);
		}

		public void RandomizeMonsterRank()
		{
			if (monsterData == null)
			{
				UnityEngine.Debug.LogError("Can't randomize rank, monster data is null", this);
			}
			else
			{
				if (monsterData.maximumDepth < 15 || monsterRank != 0)
				{
					return;
				}
				if (UnityEngine.Random.value < 0.02f)
				{
					int num = Mathf.RoundToInt((float)monsterData.rarity * Fate.RankMod[Rank.Legendary].monsterRarityMultiplier);
					if (num >= 1000)
					{
						num = 999;
					}
					if (UnityEngine.Random.Range(0, 1000) <= num)
					{
						monsterRank = Rank.Legendary;
						return;
					}
				}
				if (UnityEngine.Random.value < 0.2f)
				{
					int num2 = Mathf.RoundToInt((float)monsterData.rarity * Fate.RankMod[Rank.Elite].monsterRarityMultiplier);
					if (num2 >= 1000)
					{
						num2 = 999;
					}
					if (UnityEngine.Random.Range(0, 1000) <= num2)
					{
						monsterRank = Rank.Elite;
					}
				}
			}
		}

		public void ApplyMonsterRank(Rank rank)
		{
			UnityEngine.Debug.Log($"Applying rank {rank} to {CharacterName}", this);
			monsterRank = rank;
			AddRankHighlight();
			Fate.RankSetup rankSetup = Fate.RankMod[rank];
			maxHpBase = Mathf.CeilToInt((float)maxHpBase * rankSetup.toHitMultiplier);
			if (maxHpBase < 50)
			{
				maxHpBase = 50;
			}
			hp = MaxHP();
			attributes.SetBasePoints(Attribute.Strength, Mathf.RoundToInt((float)attributes.GetAttribute(Attribute.Strength, allowEffects: false) * rankSetup.powerMultiplier));
			attributes.SetBasePoints(Attribute.Dexterity, Mathf.RoundToInt((float)attributes.GetAttribute(Attribute.Dexterity, allowEffects: false) * rankSetup.powerMultiplier));
			attributes.SetBasePoints(Attribute.Vitality, Mathf.RoundToInt((float)attributes.GetAttribute(Attribute.Vitality, allowEffects: false) * rankSetup.powerMultiplier));
			attributes.SetBasePoints(Attribute.Magic, Mathf.RoundToInt((float)attributes.GetAttribute(Attribute.Magic, allowEffects: false) * rankSetup.powerMultiplier));
			toHitBonus = Mathf.CeilToInt((float)toHitBonus * rankSetup.toHitMultiplier);
			foreach (Attribute value in Enum.GetValues(typeof(Attribute)))
			{
				if (Fate.IsSkill(value))
				{
					attributes.SetBasePoints(value, Mathf.RoundToInt((float)attributes.GetAttribute(value, allowEffects: false) * rankSetup.powerMultiplier));
				}
			}
			if (isLoadedFromSave)
			{
				return;
			}
			float num;
			switch (rank)
			{
			case Rank.Normal:
				num = 0f;
				break;
			case Rank.Elite:
				num = 0.8f + 0.03f * (float)LevelGenerator.effectiveLevelDepth;
				gold += UnityEngine.Random.Range(2 * LevelGenerator.effectiveLevelDepth, 5 * LevelGenerator.effectiveLevelDepth);
				break;
			case Rank.Legendary:
				num = 1.5f + 0.05f * (float)LevelGenerator.effectiveLevelDepth;
				gold += UnityEngine.Random.Range(3 * LevelGenerator.effectiveLevelDepth, 7 * LevelGenerator.effectiveLevelDepth);
				break;
			default:
				throw new NotImplementedException($"Enum value {rank} not implemented");
			}
			while (num > 1f || UnityEngine.Random.value < num)
			{
				num -= 1f;
				int num2 = Mathf.CeilToInt((float)Level * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier);
				switch (rank)
				{
				case Rank.Elite:
					num2 += 3;
					break;
				case Rank.Legendary:
					num2 += 5;
					break;
				}
				Item item = levelData.GenerateRareTakeableItem();
				if (item != null)
				{
					AddItemToInventory(item, AddItemReason.StartingItems);
					if (UnityEngine.Random.Range(0, 100) > 95)
					{
						item.BestowUniquePowers(num2, AllowCurse: false, Level);
					}
					else
					{
						item.TryBestowPowers(num2, AllowCurse: false, Level);
					}
					if (UnityEngine.Random.Range(0, 100) < 15)
					{
						item.BestowSockets(AllowUnique: false);
					}
					if (UnityEngine.Random.Range(0, 1000) < 50)
					{
						item.BestowGrade(SingletonBehaviour<PlayerStatus>.Instance.Difficulty);
					}
				}
			}
		}

		private void AddQuestHighlight()
		{
			if (!(highlightObject != null))
			{
				GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Quest_Highlight");
				highlightObject = UnityEngine.Object.Instantiate(particlePrefab, myTransform);
				highlightObject.transform.localScale = Vector3.one;
			}
		}

		private void AddRankHighlight()
		{
			if (rankHighlightObject != null)
			{
				UnityEngine.Object.Destroy(rankHighlightObject);
				rankHighlightObject = null;
			}
			string text = $"Rank_Highlight_{monsterRank}";
			GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab(text);
			if (particlePrefab == null)
			{
				UnityEngine.Debug.LogError("Could not find particle prefab '" + text + "'");
				return;
			}
			rankHighlightObject = UnityEngine.Object.Instantiate(particlePrefab, myTransform);
			rankHighlightObject.transform.localScale = Vector3.one;
		}

		public void MakeUnique(int level, bool superSized)
		{
			if (!IsBoss)
			{
				CharacterName = SingletonBehaviour<NameGenerator>.Instance.GenerateUniqueName(out var _, out var _, out var _);
			}
			if (!isUnique && Alive())
			{
				AddQuestHighlight();
			}
			isUnique = true;
			if (level <= Level)
			{
				level = Level + 1;
			}
			monsterData.bravery = 1f;
			int num = level - Level;
			Level = level;
			nextLevelExperience = Fate.GetExperienceNeeded(Level);
			experienceReward += (int)((float)experienceReward * 0.75f * (float)num);
			experienceReward *= 2;
			if (experienceReward < 200)
			{
				experienceReward = 200;
			}
			fameReward = UnityEngine.Random.Range(level * 10, level * 20);
			toHitBonus += num * UnityEngine.Random.Range(6, 8);
			naturalArmor += 10;
			naturalArmor += num * 6;
			attributes.AddBasePoints(Attribute.Dexterity, num * 6);
			attributes.AddBasePoints(Attribute.Vitality, num * 6);
			attributes.AddBasePoints(Attribute.Strength, num * 6);
			attributes.AddBasePoints(Attribute.Magic, num * 6);
			attributes.AddBasePoints(Attribute.SkillCharmMagic, (int)((float)num * 0.5f));
			attributes.AddBasePoints(Attribute.SkillDefenseMagic, (int)((float)num * 0.5f));
			attributes.AddBasePoints(Attribute.SkillAttackMagic, (int)((float)num * 0.5f));
			attributes.AddBasePoints(Attribute.SkillSpellcasting, (int)((float)num * 0.5f));
			if (attributes.GetAttribute(Attribute.SkillSpellcasting, allowEffects: false) > 10)
			{
				attributes.SetBasePoints(Attribute.SkillSpellcasting, 10);
			}
			maxHpBase += Mathf.CeilToInt(monsterData.hpRange.Min * 2f);
			maxHpBase += Mathf.CeilToInt(monsterData.hpRange.Min * (float)num * 2f);
			if (maxHpBase < 50)
			{
				maxHpBase = 50;
			}
			hp = MaxHP();
			for (int i = 0; i < 11; i++)
			{
				if (i != 9 && i != 10 && UnityEngine.Random.Range(0, 1000) < 500 && damageResists.TryGetValue((DamageType)i, out var value))
				{
					int num2 = UnityEngine.Random.Range(0, 60);
					if (num2 > value)
					{
						damageResists[(DamageType)i] = num2;
					}
				}
			}
			scale += 0.85f;
			if (superSized)
			{
				scale += 0.2f;
			}
			myTransform.localScale = Vector3.one * scale;
			GetComponent<AudioSource>().priority = 64;
			if (minimapIcon != null)
			{
				minimapIcon.transform.localScale -= new Vector3(minimapIcon.transform.localScale.x / myTransform.lossyScale.x, minimapIcon.transform.localScale.y / myTransform.lossyScale.y, minimapIcon.transform.localScale.z / myTransform.lossyScale.z);
			}
			if (attributes.GetAttribute(Attribute.Magic, allowEffects: false) < 20)
			{
				attributes.SetBasePoints(Attribute.Magic, 20);
			}
			int num3 = UnityEngine.Random.Range(2, 10);
