		public void AwardBigExperience(ulong award, bool fromMaster, bool isLoadSave = false)
		{
			if (IsPlayer())
			{
				ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.GetFormat("PlusExperience", award), 1f, 5f, ThatHurt.ThatHurtColor.Experience, 0f);
			}
			if (HasSpecificPet(this))
			{
				foreach (Character petCharacter in petCharacters)
				{
					if (petCharacter.AvailableForCommand() && petCharacter != this)
					{
						petCharacter.AwardBigExperience(award / 2, fromMaster: true, isLoadSave);
					}
				}
			}
			if (HasPartyMembers())
			{
				foreach (Character partyCharacter in partyCharacters)
				{
					if (partyCharacter.AvailableForCommand() && partyCharacter != this)
					{
						partyCharacter.AwardBigExperience(award / 2, fromMaster: true, isLoadSave);
					}
				}
			}
			if (HasMaster() && !fromMaster)
			{
				Master().AwardBigExperience(award, fromMaster: false, isLoadSave);
				return;
			}
			int level = Level;
			checked
			{
				try
				{
					experience += award;
				}
				catch (OverflowException)
				{
					experience = ulong.MaxValue;
				}
			}
			while (experience > nextLevelExperience)
			{
				Level++;
				nextLevelExperience = Fate.GetExperienceNeeded(Level);
				if (Level >= Fate.MaxLevel)
				{
					break;
				}
			}
			attributes.SetBasePoints(Attribute.Level, Level);
			if (level != Level)
			{
				LevelUp(level, isLoadSave);
			}
			if (IsPlayer())
			{
				if (level != Level)
				{
					SimpleSingletonBehaviour<PlayerUI>.Instance.SetLevel(Level);
					ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.Get("LevelUp"), 1f, 5f, ThatHurt.ThatHurtColor.White, 0f);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.LevelUp, randomizePitch: false);
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_levelup);
				}
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetXP(GetPctToNextLevel(), experience, Fate.GetExperienceNeeded(Level));
			}
		}

