		public float GetPctToNextLevel()
		{
			ulong experienceNeeded = Fate.GetExperienceNeeded(Level - 1);
			ulong num = Fate.GetExperienceNeeded(Level) - experienceNeeded;
			return (float)((double)(experience - experienceNeeded) / (double)num);
		}

		public void AwardFame(uint fame)
		{
			if (fame == 0)
			{
				return;
			}
			if (IsPlayer())
			{
				ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.GetFormat("PlusFame", fame), 1f, 5f, ThatHurt.ThatHurtColor.Experience, 2f);
			}
			if (HasMaster())
			{
				masterCharacter.AwardFame(fame);
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_ally_Fame);
			}
			else if (IsPlayer())
			{
				this.fame += fame;
				int num = fameRank;
				fameRank = Fate.GetFameTier(this.fame);
				if (num != fameRank)
				{
					OnFameRankUp?.Invoke(fameRank);
					unusedSkillPoints += 4 * (fameRank - num);
					ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.GetFormatReplaceTags("FameRankUp", Fate.GetFameName(fameRank)), 1.1f, 5f, ThatHurt.ThatHurtColor.White, 2f);
					attributes.SetBasePoints(Attribute.Renown, fameRank);
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_fame);
				}
			}
		}

		public void SetFameRank(int fameRank)
		{
			fame = Fate.GetFameNeeded(fameRank);
			int num = this.fameRank;
			this.fameRank = fameRank;
			unusedSkillPoints += 4 * (fameRank - num);
			attributes.SetBasePoints(Attribute.Renown, fameRank);
			OnFameRankUp?.Invoke(fameRank);
		}

		protected void LevelUp(int preLevel, bool skipNarration = false)
		{
			if (IsTransformed)
			{
				return;
			}
			int num = Level - preLevel;
			AddUnusedStatPoints(5 * num);
			AddUnusedSkillPoints(2 * num);
			if (masterCharacter != null)
			{
				if (masterCharacter.petCharacters != null && masterCharacter.petCharacters.Contains(this))
				{
					unusedStatPoints += num;
					if (!skipNarration)
					{
						SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_petlevelup);
					}
					for (int i = 0; i < num; i++)
					{
						SpendPoint(Attribute.Strength);
						SpendPoint(Attribute.Strength);
						SpendPoint(Attribute.Dexterity);
						SpendPoint(Attribute.Dexterity);
						SpendPoint(Attribute.Vitality);
						SpendPoint(Attribute.Vitality);
					}
				}
				else if (masterCharacter.partyCharacters != null && masterCharacter.partyCharacters.Contains(this) && !skipNarration)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_ally_levelup);
				}
			}
			CalculateMaxHP();
			CalculateMaxMana();
			CalculateMaxStamina();
			hp = MaxHP();
			mana = MaxMana();
			stamina = MaxStamina();
			if (IsPlayer() && SingletonBehaviour<PlayerStatus>.Instance.Difficulty == Fate.Difficulty.Hardcore)
			{
				StatsManager.SetStat(Stat.HighestHardcoreLevel, Level);
			}
			OnLevelUp?.Invoke(Level);
			if (IsPlayer() && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.LevelUp, out var key))
			{
				SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
			}
		}

		public void SpendPoint(Attribute attribute)
		{
			switch (attribute)
			{
			case Attribute.Strength:
			case Attribute.Dexterity:
			case Attribute.Vitality:
			case Attribute.Magic:
				if (unusedStatPoints > 0)
				{
					unusedStatPoints--;
					attributes.AddBasePoints(attribute, 1);
					if (IsPlayer() || IsPartyMember())
					{
						SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.GivePoint, randomizePitch: false);
					}
				}
				break;
			case Attribute.SkillSword:
			case Attribute.SkillClub:
			case Attribute.SkillHammer:
			case Attribute.SkillAxe:
			case Attribute.SkillSpear:
			case Attribute.SkillStaff:
			case Attribute.SkillPolearm:
			case Attribute.SkillBow:
			case Attribute.SkillCriticalStrike:
			case Attribute.SkillSpellcasting:
			case Attribute.SkillDualWield:
			case Attribute.SkillShield:
			case Attribute.SkillAttackMagic:
			case Attribute.SkillDefenseMagic:
			case Attribute.SkillCharmMagic:
				if (unusedSkillPoints > 0)
				{
					unusedSkillPoints--;
					attributes.AddBasePoints(attribute, 1);
					if (IsPlayer() || IsPartyMember())
					{
						SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.GivePoint, randomizePitch: false);
					}
				}
				break;
			}
		}

		public virtual (bool mainSlot, bool secondarySlot) CanEquip(Item item)
		{
			if (!IsPlayer() && !IsPartyMember())
			{
				if (monsterData == null)
				{
					return (mainSlot: false, secondarySlot: false);
				}
				if (!monsterData.CanEquip(item.itemType))
				{
					return (mainSlot: false, secondarySlot: false);
				}
			}
			if (!RequirementsMet(item))
			{
				return (mainSlot: false, secondarySlot: false);
			}
			if (inventory == null || inventory.IsEmpty() || (SingletonBehaviour<PlayerUI>.InstanceExists() && SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI == null))
			{
				return (mainSlot: true, secondarySlot: false);
			}
			(int, int) equipmentSlots = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetEquipmentSlots(item);
			if (equipmentSlots.Item1 == -1 && equipmentSlots.Item2 == -1)
			{
				return (mainSlot: false, secondarySlot: false);
			}
			(bool, bool) result = (true, equipmentSlots.Item2 != -1);
			if (item.category == ItemCategory.Weapon)
			{
				Item item2 = inventory.Find((Item a) => a.slotIndex == 6);
				Item item3 = inventory.Find((Item a) => a.slotIndex == 7);
				if (item.itemData.IsTwoHanded && (item2 != null || item3 != null))
				{
					return (mainSlot: false, secondarySlot: false);
				}
				if (item2 != null && item2.itemData.IsTwoHanded)
				{
					return (mainSlot: false, secondarySlot: false);
				}
				if (item3 != null && item3.itemData.IsTwoHanded)
				{
					return (mainSlot: false, secondarySlot: false);
				}
			}
			for (int i = 0; i < inventory.Count; i++)
			{
				if (inventory[i].slotIndex != -1)
				{
					if (inventory[i].slotIndex == equipmentSlots.Item1)
					{
						result.Item1 = false;
					}
					if (inventory[i].slotIndex == equipmentSlots.Item2)
					{
						result.Item2 = false;
					}
				}
			}
			return result;
		}

		public bool AttemptAutoEquip(Item item)
		{
			(bool, bool) tuple = CanEquip(item);
			if (tuple.Item1 || tuple.Item2)
			{
				UnityEngine.Debug.Log("Auto equipping: " + item.itemBaseName);
				if (SingletonBehaviour<PlayerUI>.InstanceExists() && SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI != null)
				{
					var (num, num2) = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetEquipmentSlots(item);
					if (item.slotIndex >= 20)
					{
						TrySetItemInGrid(item, state: false);
					}
					item.slotIndex = (tuple.Item1 ? num : num2);
				}
				EquipItem(item, WeaponSet.Primary);
				return true;
			}
			return false;
		}

		protected virtual int[,] GetInventoryGridSize()
		{
			return new int[10, 11];
		}

		public virtual bool CanFitItemInInventoryGrid(Item item, out int foundSlotIndex, int desiredSlot = -1, bool isGlobalIndex = false, bool searchHorizontal = true)
		{
			if (isGlobalIndex)
			{
				desiredSlot -= 20;
				if (desiredSlot < -1)
				{
					desiredSlot = -1;
				}
			}
			foundSlotIndex = -1;
			if (monsterData != null && !IsPet())
			{
				return true;
			}
			int inventoryGridWidth = InventoryGridWidth;
			int inventoryGridHeight = InventoryGridHeight;
			if (Fate.IsItemSlotValid(desiredSlot) && IsSpaceAvailable(desiredSlot / inventoryGridWidth, desiredSlot % inventoryGridWidth, item.slotsTall, item.slotsWide))
			{
				foundSlotIndex = desiredSlot;
				return true;
			}
			if (searchHorizontal)
			{
				for (int i = 0; i < inventoryGridHeight; i++)
				{
					for (int j = 0; j < inventoryGridWidth; j++)
					{
						if (IsSpaceAvailable(i, j, item.slotsTall, item.slotsWide))
						{
							foundSlotIndex = i * inventoryGridWidth + j;
							return true;
						}
					}
				}
			}
			else
			{
				for (int k = 0; k < inventoryGridWidth; k++)
				{
					for (int l = 0; l < inventoryGridHeight; l++)
					{
						if (IsSpaceAvailable(l, k, item.slotsTall, item.slotsWide))
						{
							foundSlotIndex = l * inventoryGridWidth + k;
							return true;
						}
					}
				}
			}
			return false;
		}

		public bool IsSpaceAvailable(int row, int col, int height, int width)
		{
			if (row + height > InventoryGridHeight || col + width > InventoryGridWidth)
			{
				return false;
			}
			for (int i = row; i < row + height; i++)
			{
				for (int j = col; j < col + width; j++)
				{
					if (inventorySlotsOccupied[i, j])
					{
						return false;
					}
				}
			}
			return true;
		}

		public bool AddItemToInventory(Item item, AddItemReason reason, int desiredSlot = -1, bool desiredSlotIsGlobal = false)
		{
			bool num = InternalAddItemToInventory(item, reason, desiredSlot, desiredSlotIsGlobal);
			if (num)
			{
				bool num2 = reason == AddItemReason.Loot || reason == AddItemReason.StartingItems || reason == AddItemReason.LoadFromSave;
				bool flag = IsPlayer() || (IsPet() && Master().IsPlayer()) || IsPartyMember();
				if (num2 && flag)
				{
					Action<Item> onItemEnterPlayerOwnership = SingletonBehaviour<PlayerStatus>.Instance.OnItemEnterPlayerOwnership;
					if (onItemEnterPlayerOwnership == null)
					{
						return num;
					}
					onItemEnterPlayerOwnership(item);
				}
			}
			return num;
		}

		private bool InternalAddItemToInventory(Item item, AddItemReason reason, int desiredSlot = -1, bool desiredSlotIsGlobal = false)
		{
			if (inventory.Contains(item))
			{
				return false;
			}
			if (reason == AddItemReason.LoadFromSave)
			{
				if (Fate.IsItemSlotValid(desiredSlot))
				{
					item.slotIndex = desiredSlot;
					inventory.Add(item);
					if (item.InInventoryGrid)
					{
						if (!TrySetItemInGrid(item, state: true))
						{
							inventory.Remove(item);
							return false;
						}
					}
					else if (item.InEquipmentSlot)
					{
						if (item.IsInMainHand || item.IsInOffHand)
						{
							if (item.weaponSet == activeWeaponSet)
							{
								EquipItem(item, item.weaponSet);
							}
						}
						else
						{
							EquipItem(item, item.weaponSet);
						}
					}
					return true;
				}
				UnityEngine.Debug.LogWarning($"Loading item from save with invalid slot index ({item.slotIndex}). item is {item.itemName}. Attempting to find a new slot.");
			}
			if (Fate.IsItemSlotInEquipmentSlot(desiredSlot) || Fate.IsItemSlotInHotbar(desiredSlot))
			{
				item.slotIndex = desiredSlot;
				inventory.Add(item);
				return true;
			}
			if (CanFitItemInInventoryGrid(item, out var foundSlotIndex, desiredSlot, desiredSlotIsGlobal))
			{
				item.slotIndex = 20 + foundSlotIndex;
				if (!Fate.IsItemSlotInInventoryGrid(item.slotIndex))
				{
					UnityEngine.Debug.LogWarning($"Adding item ({item.itemName}) to inventory grid with bad slot index ({item.slotIndex})");
				}
				TrySetItemInGrid(item, state: true);
				inventory.Add(item);
				if (reason == AddItemReason.Loot && IsPlayer())
				{
					if (item.itemType == ItemType.PetFood)
					{
						StatsManager.OnFishLooted(item.itemName);
					}
					else if (item.itemType == ItemType.Gem)
					{
						StatsManager.OnGemLooted(item.itemData.IconName);
					}
				}
				if (IsPlayer() && reason != AddItemReason.LoadFromSave && reason != 0)
				{
					string key2;
					string key3;
					string key4;
					string key5;
					string key6;
					if (!item.Identified && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.Identify, out var key))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
					}
					else if (item.WritesASpell() && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.Spell, out key2))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key2);
					}
					else if (item.itemType == ItemType.FishingPole && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.Fish, out key3))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key3);
					}
					else if (item.itemType == ItemType.Gem && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.Gem, out key4))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key4);
					}
					else if (item.itemType == ItemType.Tarot && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.FateCardsPickup, out key5))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key5);
					}
					else if (item.IsHeroItem() && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.HeroItem, out key6))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key6);
					}
				}
				return true;
			}
			if (reason != AddItemReason.LoadFromSave)
			{
				if (IsPlayer())
				{
					if (SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.InventoryFull, out var key7))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key7);
					}
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_packfull);
				}
				else if (IsPet())
				{
					if (SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.PetFull, out var key8))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key8);
					}
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_packfull);
				}
			}
			return false;
		}

		public void RemoveItemFromInventory(Item item, RemoveItemReason reason, bool releaseFromGrid = true)
		{
			if (item.equipped)
			{
				UnequipItem(item);
			}
			inventory.Remove(item);
			if (item.InInventoryGrid && releaseFromGrid)
			{
				TrySetItemInGrid(item, state: false);
			}
			if ((IsPlayer() || (IsPet() && HasMaster() && Master().IsPlayer()) || IsPartyMember()) && reason != RemoveItemReason.Transfer)
			{
				SingletonBehaviour<PlayerStatus>.Instance.OnItemExitPlayerOwnership?.Invoke(item);
			}
		}

		public void ItemMovedInInventory(Item item, int newSlot)
		{
			ReleaseInventorySlotsForItem(item);
			item.slotIndex = newSlot;
			ReserveInventorySlotsForItem(item);
		}

		public void ReserveInventorySlotsForItem(Item item)
		{
			TrySetItemInGrid(item, state: true);
		}

		public void ReleaseInventorySlotsForItem(Item item)
		{
			TrySetItemInGrid(item, state: false);
		}

		private bool TrySetItemInGrid(Item item, bool state)
		{
			int num = item.slotIndex - 20;
			if (num < 0)
			{
				UnityEngine.Debug.LogWarning($"Invalid item slot: {item.itemBaseName}: {item.slotIndex}");
				return false;
			}
			int num2 = num / InventoryGridWidth;
			int num3 = num % InventoryGridWidth;
			int length = inventorySlotsOccupied.GetLength(0);
			int length2 = inventorySlotsOccupied.GetLength(1);
			if (num2 < 0 || num3 < 0 || num2 + item.slotsTall > length || num3 + item.slotsWide > length2)
			{
				UnityEngine.Debug.LogWarning($"Item {item.ItemDisplayName} is out of inventory grid range. Item slot index is {item.slotIndex}, item size is (width/height): {item.slotsWide}/{item.slotsTall}");
				return false;
			}
			for (int i = num2; i < num2 + item.slotsTall; i++)
			{
				for (int j = num3; j < num3 + item.slotsWide; j++)
				{
					inventorySlotsOccupied[i, j] = state;
				}
			}
			return true;
		}

		private void LogInventoryGridState()
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < InventoryGridHeight; i++)
			{
				for (int j = 0; j < InventoryGridWidth; j++)
				{
					stringBuilder.Append(inventorySlotsOccupied[i, j] ? "T" : "F");
					stringBuilder.Append(",");
				}
				stringBuilder.AppendLine();
			}
			UnityEngine.Debug.Log(stringBuilder.ToString());
		}

		public bool AddItemToHotbar(Item item, int hotbarSlotIndex, AddItemReason addReason)
		{
			if (item == null)
			{
				UnityEngine.Debug.LogWarning($"Tried to add NULL item to hotbar slot, index {hotbarSlotIndex}");
				return false;
			}
			if (hotbarSlotIndex < 0 || hotbarSlotIndex > 3)
			{
				UnityEngine.Debug.LogWarning($"Tried to add item to hotbar slot with index {hotbarSlotIndex} (0-3 allowed)");
				return false;
			}
			if (!IsHotbarSlotFree(hotbarSlotIndex))
			{
				UnityEngine.Debug.LogWarning($"Tried to addding item to hotbar slot with index {hotbarSlotIndex}, but slot is not free. Not allowing it");
				return false;
			}
			if (inventory.Contains(item))
			{
				if (item.InInventoryGrid)
				{
					ReleaseInventorySlotsForItem(item);
				}
				item.slotIndex = hotbarSlotIndex;
			}
			else if (!AddItemToInventory(item, addReason, hotbarSlotIndex))
			{
				UnityEngine.Debug.LogWarning($"Tried to addding item to hotbar slot with index {hotbarSlotIndex}, but failed to add the item to inventory");
				return false;
			}
			OnHotbarItemAdded?.Invoke(item, hotbarSlotIndex);
			return true;
		}

		public bool IsHotbarSlotFree(int slotIndex)
		{
			slotIndex = slotIndex;
			if (inventory == null)
			{
				return true;
			}
			return inventory.Find((Item item) => item.slotIndex == slotIndex) == null;
		}

		public bool TryGetFirstFreeHotbarSlot(out int slot)
		{
			for (int i = 0; (float)i < 4f; i++)
			{
				if (IsHotbarSlotFree(i))
				{
					slot = i;
					return true;
				}
			}
			slot = -1;
			return false;
		}

		public virtual void EquipItem(Item item, WeaponSet weaponSet)
		{
			if (item.equipped)
			{
				return;
			}
			item.weaponSet = weaponSet;
			if (!inventory.Contains(item))
			{
				UnityEngine.Debug.LogWarning("Equipping item that is not in inventory");
				AddItemToInventory(item, AddItemReason.Transfer);
			}
			if (item.category == ItemCategory.Armor)
			{
				armorBonus += item.Armor();
			}
			if (item.Identified)
			{
				AddEffectsOfEquippedItem(item);
			}
			if (item.IsInMainHand)
			{
				activeWeapon = item;
				equippedWeapons[0] = item;
				if (rightWeaponHandle != null)
				{
					rightWeaponHandle.SetEquipment(item);
				}
				animator.SetBool(GameSettings.Instance.AnimParamIsMelee, item.IsMelee);
			}
			else if (item.IsInOffHand)
			{
				bool num = item.itemType == ItemType.Shield;
				if (!num)
				{
					activeWeapon = item;
					equippedWeapons[1] = item;
				}
				if (leftWeaponHandle != null)
				{
					leftWeaponHandle.SetEquipment(item);
				}
				if (!num)
				{
					animator.SetBool(GameSettings.Instance.AnimParamIsMelee, item.IsMelee);
				}
			}
			item.equipped = true;
			item.onIdentifyStatusChanged = (Action<Item>)Delegate.Combine(item.onIdentifyStatusChanged, new Action<Item>(OnEquippedItemIdentifyStatusChanged));
			item.onEffectsChanged = (Action<Item>)Delegate.Combine(item.onEffectsChanged, new Action<Item>(OnEquippedItemEffectsChanged));
			onEquipmentChanged?.Invoke();
		}

		public void ResetEquipment(Item item)
		{
			if (item.IsInMainHand)
			{
				if (rightWeaponHandle != null)
				{
					rightWeaponHandle.SetEquipment(item);
				}
			}
			else if (item.IsInOffHand && leftWeaponHandle != null)
			{
				leftWeaponHandle.SetEquipment(item);
			}
		}

		private void OnEquippedItemIdentifyStatusChanged(Item equippedItem)
		{
			if (inventory.Contains(equippedItem) && equippedItem.InEquipmentSlot && equippedItem.Identified)
			{
				AddEffectsOfEquippedItem(equippedItem);
			}
		}

		private void OnEquippedItemEffectsChanged(Item item)
		{
			if (inventory.Contains(item) && item.InEquipmentSlot)
			{
				RemoveEffectsOfEquippedItemBySlot(item.slotIndex);
				if (item.Identified)
				{
					AddEffectsOfEquippedItem(item);
				}
			}
		}

		public void AddEffectsOfEquippedItem(Item item)
		{
			if (item.effects.TryGetValue(ActivationType.Passive, out var value))
			{
				for (int i = 0; i < value.Count; i++)
				{
					EffectData effectData = value[i];
					effectData.permanent = true;
					effectData.duration = -1000;
					AddEffect(effectData, 1, null, item.slotIndex);
				}
			}
		}

		private void RemoveEffectsOfEquippedItemBySlot(int slotIndex)
		{
			if (!effects.TryGetValue(ActivationType.Passive, out var value))
			{
				return;
			}
			for (int i = 0; i < value.Count; i++)
			{
				if (value[i].itemSlotIndex == slotIndex)
				{
					RemoveEffect(value[i]);
					i--;
				}
			}
		}

		public virtual void UnequipItem(Item item)
		{
			if (!item.equipped)
			{
				return;
			}
			RemoveEffectsOfEquippedItemBySlot(item.slotIndex);
			if (item.IsInMainHand)
			{
				equippedWeapons[0] = null;
				activeWeapon = GetEquippedWeapon(WeaponHand.OffHand);
				if (activeWeapon != null && activeWeapon.itemType == ItemType.Shield)
				{
					activeWeapon = null;
				}
				if (rightWeaponHandle != null)
				{
					rightWeaponHandle.SetEquipment(null);
				}
				if (activeWeapon == null)
				{
					animator.SetBool(GameSettings.Instance.AnimParamIsMelee, value: true);
				}
			}
			else if (item.IsInOffHand)
			{
				equippedWeapons[1] = null;
				activeWeapon = GetEquippedWeapon(WeaponHand.MainHand);
				if (leftWeaponHandle != null)
				{
					leftWeaponHandle.SetEquipment(null);
				}
				if (activeWeapon == null)
				{
					animator.SetBool(GameSettings.Instance.AnimParamIsMelee, value: true);
				}
			}
			if (item.category == ItemCategory.Armor)
			{
				armorBonus -= item.Armor();
			}
			item.onIdentifyStatusChanged = (Action<Item>)Delegate.Remove(item.onIdentifyStatusChanged, new Action<Item>(OnEquippedItemIdentifyStatusChanged));
			item.onEffectsChanged = (Action<Item>)Delegate.Remove(item.onEffectsChanged, new Action<Item>(OnEquippedItemEffectsChanged));
			item.equipped = false;
			onEquipmentChanged?.Invoke();
		}

		public List<AppliedEffect> GetEffects()
		{
			if (effects == null)
			{
				return null;
			}
			List<AppliedEffect> list = new List<AppliedEffect>();
			foreach (KeyValuePair<ActivationType, List<AppliedEffect>> effect in effects)
			{
				list.AddRange(effect.Value);
			}
			return list;
		}

		public void OnEffectsLoad(List<EffectSave> loadedEffects)
		{
			if (loadedEffects == null || loadedEffects.Count == 0)
			{
				return;
			}
			if (effects == null)
			{
				effects = new Dictionary<ActivationType, List<AppliedEffect>>();
			}
			for (int i = 0; i < loadedEffects.Count; i++)
			{
				if (loadedEffects[i].duration != -1000)
				{
					AddEffect(loadedEffects[i]);
				}
			}
		}

