		public virtual void Init()
		{
			canRun = true;
			allowDropEquipment = true;
			allowDropInventory = true;
			petCharacters = new List<Character>();
			wardCharacters = new List<Character>();
			partyCharacters = null;
			inventory = new List<Item>();
			levelData = LevelGenerator.currentInstance;
			animator = GetComponent<Animator>();
			animatorOverrideController = new AnimatorOverrideController(animator.runtimeAnimatorController);
			animator.runtimeAnimatorController = animatorOverrideController;
			clipOverrides = new AnimationClipOverrides(animatorOverrideController.overridesCount);
			animatorOverrideController.GetOverrides(clipOverrides);
			effectChildren = new List<GameObject>();
			path = GetComponent<NavMeshAgent>();
			myTransform = base.transform;
			myCollider = GetComponent<Collider>();
			myVitals = GetComponent<CharacterVitals>();
			if (IsPlayer())
			{
				baseLevel = 1;
				animator.SetBool(GameSettings.Instance.AnimParamIsMelee, value: true);
				Init(SaveData.CurrentSaveData);
				if (!SingletonBehaviour<TutorialPopupUI>.InstanceExists())
				{
					return;
				}
				UtilityTG.UnityDelay(delegate
				{
					string key2;
					if (SingletonBehaviour<Town>.InstanceExists() && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetWelcomeMessageKey(SingletonBehaviour<PlayerStatus>.Instance.TownRealm, out var key))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
					}
					else if (SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetRandomTip(out key2))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key2);
					}
				});
				return;
			}
			baseLevel = 1;
			if (monsterData != null)
			{
				Init(monsterData);
			}
			else
			{
				attributes = new AttributeSet(16, 16, 16, 16, OnAttributesChange);
				effects = new Dictionary<ActivationType, List<AppliedEffect>>();
				currentEffectValues = new Dictionary<EffectType, int>();
				damageResists = new Dictionary<DamageType, int>();
				knownSpells = new Dictionary<SpellSphere, List<SpellData>>();
				InternalInit();
			}
			if (path != null)
			{
				path.speed = GetFinalMoveSpeed();
			}
		}

		public virtual void InitSpells(List<string> spellKeys, string activeSpellKey)
		{
			if (spellKeys == null)
			{
				return;
			}
			if (!IsPlayer() && !IsPartyMember())
			{
				spellKeys.Shuffle();
			}
			SpellData[] allSpells = SingletonBehaviour<FateDB>.Instance.allSpells;
			for (int i = 0; i < spellKeys.Count; i++)
			{
				string spellKey = spellKeys[i];
				SpellData spellData = allSpells.Find((SpellData sp) => sp.spellName == spellKey);
				if (spellData == null)
				{
					UnityEngine.Debug.LogWarning("Spell not found: " + spellKey);
					continue;
				}
				if (!knownSpells.TryGetValue(spellData.sphereType, out var value) || value == null)
				{
					knownSpells[spellData.sphereType] = new List<SpellData>();
				}
				if ((IsPlayer() || IsPartyMember()) && spellData.sphereType != SpellSphere.Rage && knownSpells[spellData.sphereType].Count >= 6)
				{
					UnityEngine.Debug.LogError("List has more known spells for sphere than allowed: " + spellData.sphereType);
					continue;
				}
				knownSpells[spellData.sphereType].Add(spellData);
				if (spellData.sphereType != SpellSphere.Rage && (spellData.spellName == activeSpellKey || (activeSpell == null && string.IsNullOrEmpty(activeSpellKey))))
				{
					SetActiveSpell(spellData);
				}
			}
			knownSpells[SpellSphere.Rage] = new List<SpellData>();
			for (int j = 0; j < allSpells.Length; j++)
			{
				if (allSpells[j].sphereType == SpellSphere.Rage)
				{
					knownSpells[SpellSphere.Rage].Add(allSpells[j]);
				}
			}
		}

		public void InitSentToTownState(bool petSentToTown, int petSecondsLeftInTown)
		{
			if (petSentToTown)
