				ReturnToTownAI(forced: true);
				SetAIState(AIState.InTown);
				townTimer = petSecondsLeftInTown;
			}
		}

		public virtual void AddSpell(SpellData spell)
		{
			if (!knownSpells.TryGetValue(spell.sphereType, out var value) || value == null)
			{
				knownSpells[spell.sphereType] = new List<SpellData>();
			}
			knownSpells[spell.sphereType].Add(spell);
			if (IsPlayerOwnedInventory)
			{
				StatsManager.IncrementStat(Stat.SpellsLearned);
			}
			if (activeSpell == null && spell.sphereType != SpellSphere.Rage)
			{
				SetActiveSpell(spell);
			}
		}

		public virtual void RemoveSpell(SpellData spell)
		{
			if (knownSpells.TryGetValue(spell.sphereType, out var value) && value != null)
			{
				value.Remove(spell);
				if (activeSpell == spell)
				{
					SetActiveSpell(null);
				}
			}
		}

		public virtual bool SetActiveSpell(SpellData spell)
		{
			if (PerformingCast())
			{
				return false;
			}
			activeSpell = spell;
			if (IsPlayer())
			{
				onActiveSpellChange?.Invoke(activeSpell);
			}
			return true;
		}

		public virtual void WasHitBySpell(SpellData spell, Character caster)
		{
			int spellSphereSkillLevel = caster.GetSpellSphereSkillLevel(spell.sphereType);
			bool flag = false;
			List<EffectData> list = spell.effects;
			if (list == null)
			{
				return;
			}
			for (int i = 0; i < list.Count; i++)
			{
				EffectType buffType = list[i].buffType;
				if (buffType == EffectType.RecoverPassoutFull || buffType == EffectType.RecoverPassoutPartial)
				{
					flag = true;
					break;
				}
			}
			if (flag && (!IsPartyMember() || !IsPassedOut()))
			{
				return;
			}
			for (int j = 0; j < list.Count; j++)
			{
				EffectData effectData = list[j];
				int num = UnityEngine.Random.Range(0, 100);
				if (effectData.chance == 0 || num < effectData.chance)
				{
					AddEffect(effectData, spellSphereSkillLevel, caster, -1, isSpellEffect: true).sourceSpriteName = spell.IconName;
				}
			}
		}

		public virtual void WasHitBySpellPayload(SpellData spell, Character caster)
		{
			int spellSphereSkillLevel = caster.GetSpellSphereSkillLevel(spell.sphereType);
			List<EffectData> payloadEffects = spell.payloadEffects;
			if (payloadEffects == null)
			{
				return;
			}
			for (int i = 0; i < payloadEffects.Count; i++)
			{
				EffectData effectData = payloadEffects[i];
				int num = UnityEngine.Random.Range(0, 100);
				if (effectData.chance == 0 || num < effectData.chance)
				{
					AddEffect(effectData, spellSphereSkillLevel, caster, -1, isSpellEffect: true).sourceSpriteName = spell.IconName;
				}
			}
		}

		public int GetSpellSphereSkillLevel(SpellSphere sphere)
		{
			return sphere switch
			{
				SpellSphere.Attack => (attributes != null) ? attributes.GetAttribute(Attribute.SkillAttackMagic, allowEffects: true) : 0, 
				SpellSphere.Defense => (attributes != null) ? attributes.GetAttribute(Attribute.SkillDefenseMagic, allowEffects: true) : 0, 
				SpellSphere.Charm => (attributes != null) ? attributes.GetAttribute(Attribute.SkillCharmMagic, allowEffects: true) : 0, 
				_ => 0, 
			};
		}

		public virtual bool TryCastCurrentSpell(Vector3? targetPosition = null, Vector3? targetDirection = null, Character targetChar = null, Item targetItem = null)
		{
			if (activeRageSpell != null)
			{
				if (targetChar != null)
				{
					castingTargetPosition = targetChar.myTransform.position;
				}
				else if (targetPosition.HasValue)
				{
					castingTargetPosition = targetPosition.Value;
				}
				if (targetDirection.HasValue)
				{
					castingTargetDirection = targetDirection.Value;
				}
				castingCharacterTraget = targetChar;
				SetTargetItem(targetItem);
				castTimer = activeRageSpell.castTime;
				if (activeRageSpell.sphereType == SpellSphere.Rage)
				{
					CastingVFX("P_RAGECASTING");
				}
				if (castTimer > 0f && !IsShrine())
				{
					Cast();
					SetAIState(AIState.Cast);
				}
				else
				{
					CompleteSpell(targetPosition, targetDirection, targetChar, targetItem, activeRageSpell);
				}
				return true;
			}
			if (activeSpell == null)
			{
				UnityEngine.Debug.Log("No Active Spell");
				return false;
			}
			if (castTimer > 0f)
			{
				return false;
			}
			if (!isGod)
			{
				if (mana < (float)activeSpell.manaCost)
				{
					if (IsPlayer() && !PlayerStatus.IsErrorOnCooldown)
					{
						SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.LowMana, randomizePitch: false);
						SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_mana);
						SingletonBehaviour<PlayerStatus>.Instance.PutErrorOnCooldown();
					}
					return false;
				}
				if (stamina < (float)activeSpell.staminaCost)
				{
					if (IsPlayer())
					{
						SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_stamina);
					}
					return false;
				}
			}
			if (activeSpell.RequiresCharacterTarget() && (targetChar == null || targetChar.GetAlignment() != GetSpellTargetAlignment(activeSpell)))
			{
				if (IsPlayer())
				{
					if (!PlayerStatus.IsErrorOnCooldown)
					{
						ThatHurt.PopText(myTransform.position, I2Loca.Get("SpellRequiresTarget"), 1f, ThatHurt.ThatHurtColor.White, 0f);
						SingletonBehaviour<PlayerStatus>.Instance.PutErrorOnCooldown();
					}
				}
				else
				{
					UnityEngine.Debug.Log(base.name + " tried to cast " + activeSpell.spellName + ". It requires target but no target was supplied.", this);
				}
				return false;
			}
			if (IsPlayer())
			{
				if (activeSpell.targetType == ItemTarget.Item)
				{
					if (targetItem == null)
					{
						SimpleSingletonBehaviour<PlayerUI>.Instance.ShowInventory(PlayerUI.InventoryStateType.Identify);
						SimpleSingletonBehaviour<PlayerUI>.Instance.SetSpellTargetingItem(isTargeting: true);
						return true;
					}
					if (targetItem.Identified)
					{
						return true;
					}
				}
				if (activeSpell.sphereType == SpellSphere.Charm)
				{
					EffectData effectData = activeSpell.effects?.Find((EffectData e) => e.buffType == EffectType.Summon);
					if (effectData != null)
					{
						StatsManager.OnMonsterSummon(effectData.name, requestSave: false);
					}
				}
			}
			if (targetPosition.HasValue)
			{
				castingTargetPosition = targetPosition.Value;
			}
			if (targetDirection.HasValue)
			{
				castingTargetDirection = targetDirection.Value;
			}
			castingCharacterTraget = targetChar;
			SetTargetItem(targetItem);
			castTimer = activeSpell.castTime;
			float num = CalculateSpellCastSpeedMultiplier();
			castTimer *= num;
			if (activeSpell.sphereType == SpellSphere.Attack)
			{
				CastingVFX("P_ATTACKCASTING");
			}
			else if (activeSpell.sphereType == SpellSphere.Defense)
			{
				CastingVFX("P_DEFENSECASTING");
			}
			else if (activeSpell.sphereType == SpellSphere.Charm)
			{
				CastingVFX("P_CHARMCASTING");
			}
			if (castTimer > 0f && !IsShrine())
			{
				Cast();
				SetAIState(AIState.Cast);
			}
			else
			{
				CompleteSpell(targetPosition, targetDirection, targetChar, targetItem);
			}
			return true;
		}

		public float CalculateSpellCastSpeedMultiplier()
		{
			float num = 1f;
			float num2 = 50f / ((float)attributes.GetAttribute(Attribute.SkillSpellcasting, allowEffects: true) * 0.03f + 1f);
			num2 = 50f - num2;
			if (num2 > 50f)
			{
				num2 = 50f;
			}
			num2 /= 50f;
			num2 *= 0.8f;
			num -= num2;
			num *= 1f - EffectValue(EffectType.PercentCastSpeed) / 100f;
			if (num < 0.2f)
			{
				num = 0.2f;
			}
			return num;
		}

		private Alignment GetSpellTargetAlignment(SpellData spellData)
		{
			Alignment alignment = spellData.targetAlignment;
			if (GetAlignment() == Alignment.Evil)
			{
				switch (alignment)
				{
				case Alignment.Good:
					alignment = Alignment.Evil;
					break;
				case Alignment.Evil:
					alignment = Alignment.Good;
					break;
				}
			}
			return alignment;
		}

		private void CastingVFX(string name)
		{
			GameObject gameObject = SingletonBehaviour<FateDB>.Instance.spellPrefabs.Find((GameObject p) => p.name.ToUpper() == name);
			if (!(gameObject != null))
			{
				return;
			}
			if (rightWeaponHandle != null && rightWeaponHandle.CurrentEquipment != null)
			{
				GameObject gameObject2 = UnityEngine.Object.Instantiate(gameObject, rightWeaponHandle.CurrentEquipment.transform);
				MeshRenderer componentInChildren = rightWeaponHandle.CurrentEquipment.GetComponentInChildren<MeshRenderer>(includeInactive: true);
				if (componentInChildren != null)
				{
					gameObject2.transform.localPosition += new Vector3(0f, componentInChildren.localBounds.max.y, 0f);
				}
				UnityEngine.Object.Destroy(gameObject2, castTimer);
			}
			else if (rightWeaponHandle != null)
			{
				UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(gameObject, rightWeaponHandle.transform), castTimer);
			}
			if (leftWeaponHandle != null && leftWeaponHandle.CurrentEquipment != null)
			{
				GameObject gameObject3 = UnityEngine.Object.Instantiate(gameObject, leftWeaponHandle.CurrentEquipment.transform);
				MeshRenderer componentInChildren2 = leftWeaponHandle.CurrentEquipment.GetComponentInChildren<MeshRenderer>(includeInactive: true);
				if (componentInChildren2 != null)
				{
					gameObject3.transform.localPosition += new Vector3(0f, componentInChildren2.localBounds.max.y, 0f);
				}
				UnityEngine.Object.Destroy(gameObject3, castTimer);
			}
			else if (leftWeaponHandle != null)
			{
				UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(gameObject, leftWeaponHandle.transform), castTimer);
			}
		}

		public void SpawnImpactVfxForSpell(SpellData chosenSpell, float duration, Vector3 position, Quaternion rotation, Character targetCharacter)
		{
			ProdigyCamera.Instance.Shake(chosenSpell.shakeRange.GetValue());
			GameObject particleImpactPrefab = chosenSpell.particleImpactPrefab;
			if (particleImpactPrefab != null)
			{
				GameObject gameObject = null;
				Transform transform = null;
				bool flag = false;
				VisualEffect visualEffect = ((chosenSpell.sfx.Count > 0) ? chosenSpell.sfx[0] : ((chosenSpell.payloadSfx.Count > 0) ? chosenSpell.payloadSfx[0] : null));
				if (visualEffect != null)
				{
					switch (visualEffect.sfxType)
					{
					case SFXType.FollowOwner:
						transform = myTransform;
						flag = true;
						break;
					case SFXType.FollowTarget:
						if (targetCharacter != null)
						{
							transform = targetCharacter.myTransform;
						}
						else
						{
							UnityEngine.Debug.LogWarning("Could not set proper follow target for spell vfx, target character is null and it is supposed to follow target");
						}
						flag = true;
						break;
					case SFXType.FollowTargetNoConstraint:
						if (targetCharacter != null)
						{
							transform = targetCharacter.myTransform;
						}
						else
						{
							UnityEngine.Debug.LogWarning("Could not set proper follow target for spell vfx, target character is null and it is supposed to follow target");
						}
						break;
