			else
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClipOnLocation(activeSpell.castSoundName, myVitals.transform.position);
			}
			currentAttack = null;
			attackTimer = 0f;
			if (IsPlayer())
			{
				animator.SetBool("IsCasting", value: true);
			}
			else
			{
				StopPathing();
				animator.SetBool("IsAttacking", value: true);
			}
			reachedCastPoint = false;
			float num = 1f;
			float num2 = 50f / ((float)SkillPoints(Attribute.SkillSpellcasting) * 0.03f + 1f);
			num2 = Mathf.Min(50f - num2, 50f);
			num2 /= 50f;
			num2 *= 0.8f;
			num -= num2;
			num *= 1f - EffectValue(EffectType.PercentCastSpeed) / 100f;
			if (num < 0.2f)
			{
				num = 0.2f;
			}
			castTimer *= num;
		}

		protected RageType GetRageType()
		{
			SelectAttack();
			RageType result = RageType.BareHands;
			if (activeWeapon != null)
			{
				result = Fate.GetRageTypeFromItemType(activeWeapon.itemType);
			}
			currentAttack = null;
			attackTimer = 0f;
			return result;
		}

		public bool CastRageSpell()
		{
			if (eAIState == AIState.Dead || eAIState == AIState.Dying || eAIState == AIState.PassingOut || eAIState == AIState.PassedOut || FishingAny())
			{
				return false;
			}
			if (PerformingCast() || PerformingAttack())
			{
				return false;
			}
			bool flag = false;
			bool flag2 = false;
			if (knownSpells.ContainsKey(SpellSphere.Rage))
			{
				int count = knownSpells[SpellSphere.Rage].Count;
				if (count > 0)
				{
					RageType rageType = GetRageType();
					List<int> list = new List<int>();
					SpellData spellData;
					for (int i = 0; i < count; i++)
					{
						spellData = knownSpells[SpellSphere.Rage][i];
						if (spellData.rageType != rageType)
						{
							continue;
						}
						if (HasSpellCosts(spellData))
						{
							list.Add(i);
							continue;
						}
						if (Stamina() < spellData.staminaCost)
						{
							flag = true;
						}
						if (Mana() < spellData.manaCost)
						{
							flag2 = true;
						}
					}
					spellData = null;
					if (list.Count > 0)
					{
						int index = UnityEngine.Random.Range(0, list.Count - 1);
						spellData = knownSpells[SpellSphere.Rage][list[index]];
					}
					if (spellData != null)
					{
						activeRageSpell = spellData;
						bool num = TryCastCurrentSpell();
						if (!num)
						{
							activeRageSpell = null;
						}
						return num;
					}
				}
			}
			if (flag)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Stamina, randomizePitch: false);
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_stamina);
			}
			else if (flag2)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.LowMana, randomizePitch: false);
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_mana);
			}
			else
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Fail, randomizePitch: false);
			}
			return false;
		}

