		protected string GetWeaponAnimName()
		{
			if (activeWeapon == null)
			{
				return "NONE";
			}
			string[] array = (activeWeapon.IsInMainHand ? activeWeapon.itemData.RightWeaponAnimationId : activeWeapon.itemData.LeftWeaponAnimationId);
			List<string> list = new List<string>();
			for (int i = 0; i < attackAnimations.Length; i++)
			{
				for (int j = 0; j < array.Length; j++)
				{
					if (attackAnimations[i].name.Substring(attackAnimations[i].name.IndexOf("|") + 1).ToUpper() == array[j])
					{
						list.Add(array[j]);
					}
				}
			}
			if (list.Count <= 0)
			{
				return "NONE";
			}
			return list[UnityEngine.Random.Range(0, list.Count)];
		}

		public void SetAttackAnimKey(string currentClip)
		{
			string text = "NONE";
			if (activeRageSpell != null)
			{
				text = GetRageName();
			}
			else if (activeSpell != null && castTimer > 0f)
			{
				text = "Cast";
				if (IsPlayer() && castTimer < 2f)
				{
					text = "FastCast";
				}
			}
			else if (activeWeapon != null)
			{
				text = GetWeaponAnimName();
				if (text == "NONE")
				{
					UnityEngine.Debug.Log("No animation for active weapon: " + activeWeapon.itemBaseName + ", for character " + base.name, this);
				}
			}
			else if (currentAttack != null)
			{
				text = currentAttack.animKey;
			}
			text = text.ToUpper();
			bool flag = false;
			for (int num = 0; num < attackAnimations.Length; num++)
			{
				string text2 = attackAnimations[num].name;
				string text3 = text2;
				int num2 = text2.IndexOf('|') + 1;
				if (!(text3.Substring(num2, text3.Length - num2).ToUpper() == text))
				{
					text3 = text2;
					num2 = text2.IndexOf('_') + 1;
					if (!(text3.Substring(num2, text3.Length - num2).ToUpper() == text))
					{
						goto IL_0134;
					}
				}
				flag = true;
				goto IL_0134;
				IL_0134:
				if (flag)
				{
					AnimationClip animationClip = attackAnimations[num];
					ApplyOverrideClip(currentClip, animationClip);
					if (castTimer > 0f)
					{
						animator.speed = animationClip.length / castTimer;
					}
					else
					{
						float num3;
						if (IsDualWielding)
						{
							int attribute = attributes.GetAttribute(Attribute.SkillDualWield, allowEffects: true);
							float t = Mathf.InverseLerp(0f, 400f, attribute);
							num3 = Mathf.Lerp(0.8f, 2f, t);
						}
						else
						{
							num3 = 0.8f;
						}
						animator.speed = animationClip.length * num3 * attackTimer;
					}
					if (animationClip.length == 0f)
					{
						UnityEngine.Debug.LogWarning("Attack clip " + animationClip.name + " has a length of zero.");
					}
					if (castTimer <= 0f && attackTimer == 0f)
					{
						UnityEngine.Debug.LogWarning("Attack timer was zero when attacking. This is not supposed to happen");
					}
					if (animator.speed < 0.03f)
					{
						animator.speed = 1f;
					}
					else if (animator.speed > 20f)
					{
						animator.speed = 20f;
					}
					break;
				}
			}
			if (!flag)
			{
				UnityEngine.Debug.Log("No animation clip found for: " + text + " in " + base.gameObject.name, this);
			}
		}

