		private void ApplyOverrideClip(string clipName, AnimationClip overrideClip)
		{
			clipOverrides[clipName] = overrideClip;
			animatorOverrideController.ApplyOverrides(clipOverrides);
		}

		protected virtual void Update()
		{
			if (eAIState == AIState.Dead)
			{
				myCollider.enabled = false;
				return;
			}
			existenceTime += Time.deltaTime * 1000f;
			if (IsMonster() && !IsShrine() && !IsPet() && GetDistanceToPlayer() > 3000f && hasUpdatedOnce)
			{
				if (eAIState != 0)
				{
					SetAIState(AIState.Inactive);
					SetTarget(null);
					if (Pathing())
					{
						StopPathing();
					}
				}
				inActiveRange = false;
				return;
			}
			inActiveRange = true;
			isTurning = false;
			if (eAIState == AIState.PassedOut)
			{
				myCollider.enabled = false;
				return;
			}
			UpdateStamina();
			UpdateAI();
			if (hp <= 0f && eAIState != AIState.Dying && eAIState != AIState.Dead && eAIState != AIState.PassingOut && eAIState != AIState.PassedOut)
			{
				if (HasMaster() && masterCharacter.IsPlayer())
				{
					PassOut();
				}
				else
				{
					Die();
				}
			}
			UpdatePathing();
			UpdateTimers();
			hasUpdatedOnce = true;
		}

		protected float GetDistanceToPlayer()
		{
			Player playerChar = Player.PlayerChar;
			if (playerChar == null)
			{
				return float.MaxValue;
			}
			return (playerChar.transform.position - base.transform.position).sqrMagnitude;
		}

		public virtual void UpdateAI()
		{
			SelectAttack();
			fishBiting = false;
			switch (eAIState)
			{
			case AIState.Dying:
				DyingAI();
				break;
			case AIState.Attack:
				AttackAI();
				break;
			case AIState.ReturningToTown:
				ReturnToTownAI();
				break;
			case AIState.Follow:
				FollowAI();
				break;
			case AIState.Hunt:
				HuntAI();
				break;
			case AIState.Cast:
				CastAI();
				break;
			case AIState.Approach:
			case AIState.ScriptApproach:
				ApproachAI();
				break;
			case AIState.OperateItem:
				OperateItemAI();
				break;
			case AIState.GetItem:
			case AIState.SpeakMerchant:
				UnityEngine.Debug.LogWarning($"{base.name}: Unhandled AI state {eAIState}. Setting state to Inactive.");
				SetAIState(AIState.Inactive);
				break;
			case AIState.Fish:
				FishAI();
				break;
			case AIState.PullFish:
				PullFishAI();
				break;
			case AIState.CancelFish:
				CancelFishAI();
				break;
			case AIState.Dead:
			case AIState.CollectReward:
			case AIState.ReceiveQuest:
			case AIState.BuySell:
			case AIState.UniqueIdle:
			case AIState.Flee:
			case AIState.GetRange:
			case AIState.ReceiveFish:
			case AIState.InEvent:
			case AIState.InTown:
			case AIState.SendPetToTown:
			case AIState.Retire:
			case AIState.CompleteRetire:
				break;
			}
		}

