		public virtual void GetItemAI()
		{
			if (droppedItemTarget == null)
			{
				SetAIState(AIState.Inactive);
				return;
			}
			if (HasMaster())
			{
				SetRunning(runningState: true);
			}
			Vector3 vector = droppedItemTarget.GetCenterPosition() - myTransform.position;
			vector.y = 0f;
			float magnitude = vector.magnitude;
			if (magnitude < droppedItemTarget.InteractRange)
			{
				droppedItemTarget.Interact(this);
				droppedItemTarget = null;
				SetAIState(AIState.Inactive);
			}
			else
			{
				if (!(magnitude > path.stoppingDistance) || Pathing())
				{
					return;
				}
				SetDestination(droppedItemTarget.GetCenterPosition().x, droppedItemTarget.GetCenterPosition().z);
				if (!Pathing())
				{
					getItemPathFailedCounter++;
					if (getItemPathFailedCounter >= 3)
					{
						droppedItemTarget = null;
						SetAIState(AIState.Wander);
					}
				}
				else
				{
					getItemPathFailedCounter = 0;
				}
			}
		}

