		public virtual void SetAIState(AIState newState)
		{
			AIState aIState = eAIState;
			if (aIState == newState)
			{
				return;
			}
			eAIState = newState;
			if (newState == AIState.GetItem)
			{
				getItemPathFailedCounter = 0;
			}
			if (newState == AIState.Retire && HasMaster())
			{
				if (this is Ward)
				{
					Master().RemoveWard(this);
				}
				SetMasterCharacter(null);
			}
			if (IsPet() && newState == AIState.Flee && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.PetFlee, out var key))
			{
				SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
			}
			if (debug)
			{
				UnityEngine.Debug.Log($"{this}: AI state changed from {aIState} to {newState}");
			}
		}

		public bool FollowCharacter(Character target)
		{
			if (target == null)
			{
				return false;
			}
			SetTarget(target);
			if (targetCharacter == null)
			{
				return false;
			}
			if (debug)
			{
				UnityEngine.Debug.Log($"{this}: Following target {target.name}");
			}
			Vector3 vector = Physics.ClosestPoint(myTransform.position, targetCharacter.myCollider, targetCharacter.myTransform.position, targetCharacter.myTransform.rotation);
			SetDestination(vector.x, vector.z);
			return true;
		}

