		public void SetDestination(float x, float z)
		{
			if (eAIState == AIState.Dead || eAIState == AIState.Dying || eAIState == AIState.PassingOut || eAIState == AIState.PassedOut || GetFinalMoveSpeed() == 0f || holdPosition)
			{
				StopPathing();
				if (holdPosition)
				{
					Attack();
				}
				finalTargetPosition = new Vector3(x, 0f, z);
			}
			else
			{
				if (!path.isOnNavMesh)
				{
					return;
				}
				timeSincePath = 0f;
				timeSinceAvoidance = 0f;
				path.isStopped = false;
				finalTargetPosition = new Vector3(x, 0f, z);
				if (!path.SetDestination(finalTargetPosition))
				{
					return;
				}
				pathing = path.hasPath || path.pathPending;
				if (!IsPlayer())
				{
					animator.SetBool("IsWalking", value: true);
					if (running)
					{
						animator.SetBool("IsRunning", value: true);
					}
					path.speed = GetFinalMoveSpeed();
				}
			}
		}

		public virtual void TurnTowardPosition(Vector3 targetPosition)
		{
			Vector3 forward = targetPosition.WithY(0f) - myTransform.position.WithY(0f);
			forward.Normalize();
			Quaternion b = Quaternion.LookRotation(forward);
			int num = ((monsterData != null) ? monsterData.turnRate : 20);
			myTransform.rotation = Quaternion.Slerp(myTransform.rotation, b, (float)num * Time.deltaTime);
		}

