		public bool FacingTarget(GameObject target, Item itemTarget)
		{
			if (target == null && itemTarget == null)
			{
				return false;
			}
			Vector3 vector = Vector3.zero;
			if (targetCharacter != null)
			{
				vector = targetCharacter.transform.position - myTransform.position;
			}
			vector.y = 0f;
			vector.Normalize();
			float num = 180f / MathF.PI * Mathf.Atan2(myTransform.forward.x, myTransform.forward.z);
			if (Mathf.Abs(180f / MathF.PI * Mathf.Atan2(vector.x, vector.z) - num) > 30f)
			{
				return false;
			}
			return true;
		}

