		public bool HasSpellCosts(SpellData spell)
		{
			if (Mana() >= spell.manaCost)
			{
				return Stamina() >= spell.staminaCost;
			}
			return false;
		}

		public bool KnowsSpell(SpellData spell)
		{
			if (knownSpells.TryGetValue(spell.sphereType, out var value))
			{
				return value.Contains(spell);
			}
			return false;
		}

		public bool CanAddSpellFromItem(Item item, SpellData spellData, out CantAddSpellReason cantAddReason)
		{
			if (IsPet())
			{
				cantAddReason = CantAddSpellReason.IsPet;
				return false;
			}
			if (!knownSpells.ContainsKey(spellData.sphereType))
			{
				knownSpells.Add(spellData.sphereType, new List<SpellData>());
			}
			if (KnowsSpell(spellData))
			{
				cantAddReason = CantAddSpellReason.KnowsSpell;
				return false;
			}
			if ((IsPlayer() || IsPartyMember()) && knownSpells.TryGetValue(spellData.sphereType, out var value) && value.Count >= 6)
			{
				cantAddReason = CantAddSpellReason.FullSphere;
				return false;
			}
			if (!RequirementsMet(item))
			{
				cantAddReason = CantAddSpellReason.RequirementsNotMet;
				return false;
			}
			cantAddReason = CantAddSpellReason.None;
			return true;
		}

		public Alignment GetAlignment()
