				{
					if (alignment != Alignment.Good)
					{
						return alignment;
					}
					return Alignment.Evil;
				}
				return Alignment.Good;
			}
			return alignment;
		}

		public Alignment GetTargetAlignment()
		{
			if (!IsPlayer() && (!HasMaster() || !Master().IsPlayer()) && EffectValue(EffectType.TurnAlignment) > (float)Level)
			{
				if (alignment != Alignment.Evil)
				{
					if (alignment != Alignment.Good)
					{
						return alignment;
					}
					return Alignment.Good;
				}
				return Alignment.Evil;
			}
			if (alignment != Alignment.Evil)
			{
				if (alignment != Alignment.Good)
				{
					return alignment;
				}
				return Alignment.Evil;
			}
			return Alignment.Good;
		}

