		public void SetMasterCharacter(Character masterChar)
		{
			if (masterChar == null)
			{
				if (masterCharacter != null)
				{
					masterCharacter = null;
					alignment = originalAlignment;
				}
			}
			else
			{
				masterCharacter = masterChar;
				if (masterCharacter.IsPlayer())
				{
					repathPauseTime = 0.5f;
				}
				if (IsSummoned() && masterCharacter.HasEffect(EffectType.RabidSummons))
				{
					alignment = Alignment.Evil;
				}
				else
				{
					alignment = masterCharacter.alignment;
				}
			}
			switch (alignment)
			{
			case Alignment.Good:
				base.gameObject.layer = LayerMask.NameToLayer("Player");
				break;
			case Alignment.Evil:
				base.gameObject.layer = LayerMask.NameToLayer("Player Damagable");
				break;
			}
			SetTarget(null);
			SetTargetItem(null);
		}

