		public void Transform(string monsterName, float duration, bool isLoad)
		{
			if (CharacterName != monsterName)
			{
				MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData x) => x.displayName == monsterName);
				if (monsterData != null)
				{
					transformationDuration = ((duration == -1f) ? (-1000f) : duration);
					ApplyTransformation(monsterData, toNewForm: true, isLoad);
				}
			}
			else if (SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData x) => x.displayName == monsterName) != null)
			{
				transformationDuration = ((duration == -1f) ? (-1000f) : duration);
				bool flag = transformationDuration == -1000f;
				if (effects != null && effects.TryGetValue(ActivationType.Usage, out var value))
				{
					if (flag)
					{
						value.RemoveAll((AppliedEffect e) => e.BuffType == EffectType.Transform);
					}
					else
					{
						AppliedEffect appliedEffect = value.Find((AppliedEffect e) => e.BuffType == EffectType.Transform);
						if (appliedEffect != null)
						{
							appliedEffect.duration = (int)transformationDuration;
						}
						else
						{
							UnityEngine.Debug.LogWarning($"Did not find buff of type {EffectType.Transform} when increasing transformation duration. This is not supposed to happen. Creating a new effect.");
							EffectData effect = new EffectData(EffectType.Transform, positive: true, ActivationType.Usage, (int)transformationDuration, 0, 0f);
							AddEffect(effect, Level, null);
						}
					}
				}
			}
			if (!isLoad)
			{
				StatsManager.IncrementStat(Stat.PetFeed);
			}
		}

		public bool CanRevertTransformation(out MonsterData originalMonsterData)
		{
			if (!IsPet())
			{
				originalMonsterData = null;
				return false;
			}
			originalMonsterData = GetOriginalTransformationMonsterData();
			if (originalMonsterData != null)
			{
				return originalMonsterData != monsterData;
			}
			return false;
		}

		public bool RevertTransformation(bool removeTransformEffect)
		{
			if (CanRevertTransformation(out var originalMonsterData))
			{
				transformationDuration = 0f;
				if (removeTransformEffect)
				{
					AppliedEffect transformationEffect = GetTransformationEffect();
					if (transformationEffect != null)
					{
						RemoveEffect(transformationEffect);
					}
				}
				ApplyTransformation(originalMonsterData, toNewForm: false, isLoad: false);
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_pettransform);
				return true;
			}
			SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
			return false;
		}

		private MonsterData GetOriginalTransformationMonsterData()
		{
			string originalName = BaseName;
			if (HasMaster() && Master().IsPlayer())
			{
				PlayerSaveData playerSaveData = SaveData.CurrentSaveData.playerSaveData;
				if (!string.IsNullOrEmpty(playerSaveData.PetOverrideId))
				{
					originalName = playerSaveData.PetOverrideId;
				}
				else
				{
					originalName = playerSaveData.petMonsterId;
				}
			}
			if (string.IsNullOrEmpty(originalName))
			{
				originalName = "Pet_Cat";
			}
			return SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData x) => x.displayName == originalName);
		}

		private void ApplyTransformation(MonsterData dataToApply, bool toNewForm, bool isLoad)
		{
			if (dataToApply.modelPrefab == null)
			{
				UnityEngine.Debug.LogError("Could not apply transformation for " + CharacterName + ". Monster data to apply has no model prefab.");
				return;
			}
			if (eAIState != AIState.InTown && eAIState != AIState.Hidden && eAIState != AIState.BuySell && eAIState != AIState.SpeakMerchant)
			{
				SetAIState(AIState.Inactive);
			}
			attackTimer = 0f;
			currentAttack = null;
			if (eAIState != AIState.BuySell && eAIState != AIState.SpeakMerchant)
			{
				SetTarget(null);
			}
			if (toNewForm && monsterData == null)
			{
				return;
			}
			if (SingletonBehaviour<PlayerUI>.InstanceExists() && SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryInitialized && SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.gameObject.activeInHierarchy)
			{
				UtilityTG.UnityDelay(delegate
				{
					SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.UpdateInventory(Player.PlayerChar);
				});
			}
			GameObject gameObject = UnityEngine.Object.Instantiate(dataToApply.modelPrefab, myTransform.position, myTransform.rotation);
			if (!isLoad)
			{
				GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("summonMonster");
				if (particlePrefab != null)
				{
					UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab, myTransform.position, Quaternion.identity), 2f);
				}
			}
			gameObject.layer = base.gameObject.layer;
			Pet pet = gameObject.GetComponent<Pet>();
			if (pet == null)
			{
				Monster component = gameObject.GetComponent<Monster>();
				pet = gameObject.AddComponent<Pet>();
				pet.rightWeaponHandle = component.rightWeaponHandle;
				pet.leftWeaponHandle = component.leftWeaponHandle;
				pet.attackAnimations = component.attackAnimations;
				pet.deathAnimations = component.deathAnimations;
				pet.uniqueIdleAnimations = component.uniqueIdleAnimations;
				UnityEngine.Object.Destroy(component);
				gameObject.GetComponent<CharacterVitals>().SetOwner(pet);
			}
			pet.monsterData = dataToApply;
			pet.Init();
			MonsterData originalData = (toNewForm ? GetOriginalTransformationMonsterData() : dataToApply);
			FateDB.PetProfilePicture petProfilePicture = SingletonBehaviour<FateDB>.Instance.PetProfilePictures.Find((FateDB.PetProfilePicture p) => p.family == originalData.family);
			if (petProfilePicture != null)
			{
				pet.profilePicture = (toNewForm ? petProfilePicture.shadowed : petProfilePicture.regular);
			}
			else
			{
				UnityEngine.Debug.LogWarning($"Could not find profile picture for pet with family {dataToApply.family}");
			}
			if (toNewForm && monsterData != null)
			{
				pet.attributes.SetBasePoints(Attribute.Strength, dataToApply.strength);
				pet.attributes.SetBasePoints(Attribute.Dexterity, dataToApply.dexterity);
				pet.attributes.SetBasePoints(Attribute.Vitality, dataToApply.vitality);
				pet.attributes.SetBasePoints(Attribute.Magic, dataToApply.magic);
				pet.toHitBonus = dataToApply.toHit;
				pet.naturalArmor = dataToApply.naturalArmor;
			}
			pet.SetMasterCharacter(Master());
			pet.Master().AddPetAtIndex(pet, 0);
			pet.SetAIState(eAIState);
			pet.TweakToLevel(Level);
			pet.baseLevel = 1;
			pet.experience = experience;
			pet.transformId = (toNewForm ? dataToApply.displayName : null);
			pet.CharacterName = CharacterName;
			pet.BaseName = BaseName;
			pet.alignment = alignment;
			pet.inventory = new List<Item>(inventory);
			pet.effects = effects;
			pet.UpdateGroundMarker(pet.alignment);
			List<AppliedEffect> list = new List<AppliedEffect>();
			foreach (KeyValuePair<ActivationType, List<AppliedEffect>> effect2 in pet.effects)
			{
				foreach (AppliedEffect item in effect2.Value)
				{
					if (item.itemSlotIndex != -1)
					{
						list.Add(item);
					}
				}
			}
			foreach (AppliedEffect item2 in list)
			{
				pet.RemoveEffect(item2);
			}
			foreach (Item item3 in pet.inventory)
			{
				if (item3.InInventoryGrid)
				{
					pet.ReserveInventorySlotsForItem(item3);
				}
				if (item3.equipped && item3.InEquipmentSlot)
				{
					item3.equipped = false;
					pet.EquipItem(item3, WeaponSet.Primary);
				}
			}
			if (toNewForm)
			{
				if (pet.effects != null && pet.effects.TryGetValue(ActivationType.Usage, out var value))
				{
					value.RemoveAll((AppliedEffect e) => e.BuffType == EffectType.Transform);
				}
				if (transformationDuration != -1000f)
				{
					EffectData effect = new EffectData(EffectType.Transform, positive: true, ActivationType.Usage, (int)transformationDuration, 0, 0f);
					pet.AddEffect(effect, Level, null);
				}
			}
			if (LevelGenerator.currentInstance != null && !Master().IsPlayer())
			{
				LevelGenerator.currentInstance.ReplaceActiveCharacter(gameObject, base.gameObject);
			}
			if (IsPet())
			{
				pet.invincible = true;
				Master().RemovePet(this);
			}
			pet.CalculateMaxHP();
			pet.CalculateMaxMana();
			pet.CalculateMaxStamina();
			pet.mana = MaxMana();
			pet.stamina = MaxStamina();
			float healthPct = myVitals.GetHealthPct();
			pet.myVitals.SetHealthPct(healthPct + 0.1f);
			onTransformed?.Invoke(pet);
			UnityEngine.Object.Destroy(base.gameObject);
		}

		public bool InAttackRange()
		{
			if (targetCharacter == null && targetItem == null)
			{
				return false;
			}
			if (currentAttack == null)
			{
				SelectAttack();
				if (currentAttack == null)
				{
					return false;
				}
			}
			float num = AttackRange();
			if (targetCharacter != null)
			{
				if (GetDistanceToTarget(targetCharacter.gameObject) > num)
				{
					return false;
				}
			}
			else if (targetItem != null)
			{
				Vector3 vector = Physics.ClosestPoint(myTransform.position, targetCharacter.myCollider, targetCharacter.myTransform.position, targetCharacter.myTransform.rotation) - myTransform.position;
				vector.y = 0f;
				if (vector.magnitude > num)
				{
					return false;
				}
			}
			return true;
		}

		public float GetDistanceToTarget(GameObject target)
		{
			if (target == null)
			{
				return float.MaxValue;
			}
			Vector3 vector = Physics.ClosestPoint(myTransform.position, target.GetComponent<Collider>(), target.transform.position, target.transform.rotation) - myTransform.position;
			vector.y = 0f;
			return vector.magnitude;
		}

		protected virtual float AttackRange()
		{
			if (currentAttack == null)
			{
				UnityEngine.Debug.LogError(base.name + ": Could not determine attack range, current attack and current weapon is null");
				return 0f;
			}
			float num = currentAttack.attackRadius * 0.3f;
			if (monsterData != null)
			{
				num += (float)monsterData.reachBonus * scale * 0.25f;
			}
			return num;
		}

		public bool TooCloseForAttack()
		{
			if (!IsCurrentTargetValid())
			{
				return false;
			}
			float num = AttackRange();
			if (num < 2f)
			{
				return false;
			}
			Vector3 vector = Physics.ClosestPoint(myTransform.position, targetCharacter.myCollider, targetCharacter.myTransform.position, targetCharacter.myTransform.rotation) - myTransform.position;
			vector.y = 0f;
			if (vector.magnitude < num * 0.85f)
			{
				return true;
			}
			return false;
		}

		public bool InStrikeRange(GameObject target)
		{
			if (currentAttack == null)
			{
				SelectAttack();
				return false;
			}
			if (target != null)
			{
				Character component = target.GetComponent<Character>();
				Vector3 vector = Physics.ClosestPoint(myTransform.position, component.myCollider, component.myTransform.position, component.myTransform.rotation) - myTransform.position;
				vector.y = 0f;
				float magnitude = vector.magnitude;
				float num = target.transform.localScale.magnitude - 1f;
				if (num < 0f)
				{
					num = 0f;
				}
				float num2 = magnitude - num;
				float num3 = myTransform.localScale.magnitude - 1f;
				if (num3 < 0f)
				{
					num3 = 0f;
				}
				float num4 = num2 - num3;
				float num5 = currentAttack.strikeRadius * 0.25f;
				if (activeWeapon != null)
				{
					num5 += activeWeapon.strikeRadius * scale * 0.25f;
				}
				if (num4 > num5)
				{
					return false;
				}
			}
			return true;
		}

		public int RollWeaponDamage()
		{
			bool flag = currentAttack == null;
			if (flag)
			{
				SelectAttack();
				if (currentAttack == null)
				{
					return 0;
				}
			}
			int num = (int)currentAttack.damageRange.GetValue();
			if (activeWeapon == null && Level > baseLevel)
			{
				num = (int)((float)num * ((float)Level - (float)baseLevel + 100f) / 100f);
			}
			num = (int)((float)(num * (attributes.GetAttribute(Attribute.Strength, allowEffects: true) + 100)) / 100f);
			num += Mathf.CeilToInt((float)num * EffectValue(EffectType.PercentDamageBonus) / 100f);
			num += (int)EffectValue(EffectType.DamageBonus);
			if (activeWeapon != null)
			{
				num += SkillPoints(attributes.WeaponTypeToSkillAttribute(activeWeapon.itemType));
				activeWeapon.PlayStrikeSound();
				if (IsDualWielding)
				{
					num = Mathf.RoundToInt((float)num * GetDualWieldDamageMultiplier(activeWeapon.IsInMainHand, withEffects: true));
				}
			}
			if (flag)
			{
				attackTimer = 0f;
			}
			return num;
		}

		public float GetDualWieldDamageMultiplier(bool isMainHand, bool withEffects, int overrideSkill = -1)
		{
			int num = ((overrideSkill != -1) ? overrideSkill : attributes.GetAttribute(Attribute.SkillDualWield, withEffects));
			float num2 = 50f / ((float)num * 0.05f + 1f);
			num2 = 50f - num2;
			if (num2 > 50f)
			{
				num2 = 50f;
			}
			num2 /= 50f;
			num2 *= (isMainHand ? 0.25f : 0.5f);
			return (isMainHand ? 0.75f : 0.5f) + num2;
		}

		public Range GetDamageRangeForStats(bool withEffects)
		{
			bool flag = activeWeapon != null;
			Item item = null;
			AttackData attackData2;
			if (IsDualWielding)
			{
				AttackData attackData = new AttackData(item = GetEquippedWeapon(WeaponHand.MainHand), isInRightHand: true);
				float dualWieldDamageMultiplier = GetDualWieldDamageMultiplier(isMainHand: true, withEffects: true);
				GetDualWieldDamageMultiplier(isMainHand: false, withEffects: true);
				Mathf.CeilToInt((float)Mathf.RoundToInt(attackData.damageRange.GetAverage()) * dualWieldDamageMultiplier);
				attackData.damageRange.Min = attackData.damageRange.Min * dualWieldDamageMultiplier;
				attackData.damageRange.Max = attackData.damageRange.Max * dualWieldDamageMultiplier;
				attackData2 = attackData;
			}
			else if (flag)
			{
				attackData2 = new AttackData(activeWeapon, activeWeapon.IsInMainHand);
				item = activeWeapon;
			}
			else
			{
				if (UnarmedAttacks() <= 0)
				{
					return default(Range);
				}
				attackData2 = UnarmedAttack(0);
			}
			int finalDamage = GetFinalDamage((int)attackData2.damageRange.Min, withEffects, flag ? new ItemType?(item.itemType) : null);
			int finalDamage2 = GetFinalDamage((int)attackData2.damageRange.Max, withEffects, flag ? new ItemType?(item.itemType) : null);
			return new Range(finalDamage, finalDamage2);
		}

		private int GetFinalDamage(int originalDamage, bool withEffects, ItemType? weaponType)
		{
			int num = originalDamage;
			bool hasValue = weaponType.HasValue;
			if (!hasValue && Level > baseLevel)
			{
				num = (int)((float)num * ((float)Level - (float)baseLevel + 100f) / 100f);
			}
			num = (int)((float)(num * (attributes.GetAttribute(Attribute.Strength, allowEffects: true) + 100)) / 100f);
			if (withEffects)
			{
				num += Mathf.CeilToInt((float)num * EffectValue(EffectType.PercentDamageBonus) / 100f);
				num += (int)EffectValue(EffectType.DamageBonus);
			}
			if (hasValue)
			{
				Attribute attribute = attributes.WeaponTypeToSkillAttribute(weaponType.Value);
				if (attribute != 0)
				{
					num += SkillPoints(attribute);
				}
			}
			return num;
		}

		public Range GetDamageRangeForStatsOffhand(bool withEffects)
		{
			if (!IsDualWielding)
			{
				return default(Range);
			}
			bool flag = activeWeapon != null;
			Item equippedWeapon = GetEquippedWeapon(WeaponHand.OffHand);
			AttackData attackData = new AttackData(equippedWeapon, isInRightHand: false);
			GetDualWieldDamageMultiplier(isMainHand: true, withEffects: true);
			float dualWieldDamageMultiplier = GetDualWieldDamageMultiplier(isMainHand: false, withEffects: true);
			Mathf.CeilToInt((float)Mathf.RoundToInt(attackData.damageRange.GetAverage()) * dualWieldDamageMultiplier);
			attackData.damageRange.Min = attackData.damageRange.Min * dualWieldDamageMultiplier;
			attackData.damageRange.Max = attackData.damageRange.Max * dualWieldDamageMultiplier;
			AttackData attackData2 = attackData;
			int finalDamage = GetFinalDamage((int)attackData2.damageRange.Min, withEffects, flag ? new ItemType?(equippedWeapon.itemType) : null);
			int finalDamage2 = GetFinalDamage((int)attackData2.damageRange.Max, withEffects, flag ? new ItemType?(equippedWeapon.itemType) : null);
			return new Range(finalDamage, finalDamage2);
		}

		private bool RemoveEffect(AppliedEffect effect)
		{
			bool result = false;
			foreach (KeyValuePair<ActivationType, List<AppliedEffect>> effect2 in effects)
			{
				if (effect2.Value.Find((AppliedEffect a) => a == effect) != null)
				{
					effect2.Value.Remove(effect);
					attributes.RemoveEffect(effect);
					RemovePSEffect(effect);
					currentEffectValues[effect.BuffType] = (int)CalculateEffectValue(effect.BuffType);
					OnEffectRemoved(effect);
					result = true;
					break;
				}
			}
			return result;
		}

		private void RemoveEffect(EffectData rawEffectData)
		{
			if (!effects.TryGetValue(ActivationType.Passive, out var value))
			{
				return;
			}
			for (int i = 0; i < value.Count; i++)
			{
				if (value[i].BuffType == rawEffectData.buffType && value[i].value == rawEffectData.value)
				{
					RemoveEffect(value[i]);
					break;
				}
			}
		}

		public void RemoveEffect(string name)
		{
			name = name.ToUpper();
			foreach (KeyValuePair<ActivationType, List<AppliedEffect>> effect in effects)
			{
				if (effect.Value != null)
				{
					AppliedEffect appliedEffect = effect.Value.Find((AppliedEffect a) => a.Name == name);
					if (appliedEffect != null)
					{
						effect.Value.Remove(appliedEffect);
						attributes.RemoveEffect(appliedEffect);
						RemovePSEffect(appliedEffect);
						currentEffectValues[appliedEffect.BuffType] = (int)CalculateEffectValue(appliedEffect.BuffType);
						OnEffectRemoved(appliedEffect);
					}
				}
			}
		}

		public void RemoveAllNegativeEffects()
		{
			base.name = base.name.ToUpper();
			foreach (KeyValuePair<ActivationType, List<AppliedEffect>> effect in effects)
			{
				List<AppliedEffect> value = effect.Value;
				if (value == null || value.Count == 0)
				{
					continue;
				}
				List<AppliedEffect> list = null;
				foreach (AppliedEffect item in value)
				{
					if (!item.Permanent && item.duration != 0 && item.duration != -1000 && item.duration != -900 && item.itemSlotIndex == -1 && !item.Positive)
					{
						if (list == null)
						{
							list = new List<AppliedEffect>();
						}
						list.Add(item);
					}
				}
				if (list == null)
				{
					continue;
				}
				foreach (AppliedEffect item2 in list)
				{
					RemoveEffect(item2);
				}
			}
		}

		protected virtual void OnEffectRemoved(AppliedEffect effect)
		{
			if (effect.BuffType == EffectType.HPRecharge && !effect.Positive && effect.DamageType == DamageType.Poison && (!currentEffectValues.ContainsKey(EffectType.HPRecharge) || currentEffectValues[EffectType.HPRecharge] >= 0))
			{
				onPoisoned?.Invoke(obj: false);
				poisoned = false;
			}
			CalculateMaxHP();
			CalculateMaxMana();
			CalculateMaxStamina();
			onEffectRemoved?.Invoke(effect);
		}

		private bool HasEffect(string name)
