			foreach (KeyValuePair<ActivationType, List<AppliedEffect>> effect in effects)
			{
				if (effect.Value != null && effect.Value.Find((AppliedEffect a) => a.Name == name) != null)
				{
					return true;
				}
			}
			return false;
		}

		private float CalculateEffectValue(EffectType type)
		{
			float num = 0f;
			foreach (KeyValuePair<ActivationType, List<AppliedEffect>> effect in effects)
			{
				for (int i = 0; i < effect.Value.Count; i++)
				{
					if (effect.Value[i].BuffType == type)
					{
						num += (float)effect.Value[i].Value;
					}
				}
			}
			return num;
		}

