		public int DamageResistance(DamageType damageType)
		{
			if (damageType == DamageType.Undead || damageType == DamageType.Heroic)
			{
				if (!damageResists.ContainsKey(damageType))
				{
					return 0;
				}
				return damageResists[damageType];
			}
			int num = (int)((float)(damageResists.ContainsKey(damageType) ? damageResists[damageType] : 0) + EffectValue(Fate.ConvertDamageTypeToResistance(damageType)));
			num += (int)EffectValue(EffectType.PercentAllResistances);
			if (num > 100)
			{
				num = 100;
			}
			if (num < -100)
			{
				num = -100;
			}
			return num;
		}

		private void CalculateEffectValues()
		{
			foreach (EffectType value2 in Enum.GetValues(typeof(EffectType)))
			{
				currentEffectValues[value2] = (int)CalculateEffectValue(value2);
				if (Fate.EffectIsMagic(value2) && MathF.Sign(currentEffectValues[value2]) != MathF.Sign(Fate.GetEffectMaximum(value2)) && damageResists.TryGetValue(DamageType.Magic, out var value))
				{
					currentEffectValues[value2] -= (int)((float)value / 100f * (float)currentEffectValues[value2]);
				}
			}
		}

		protected void UpdateHP()
		{
			if (Alive() && invincible && masterCharacter != null)
			{
				ModifyHP(Time.deltaTime * 0.032f);
			}
		}

		protected void UpdateMana()
		{
			if (Alive())
			{
				ModifyMana((float)(MaxMana() / 35) * Time.deltaTime);
				ModifyMana(EffectValue(EffectType.Mana) * Time.deltaTime * 0.16f);
				ModifyMana((float)MaxMana() * EffectValue(EffectType.ManaPercentRecharge) / 100f * Time.deltaTime * 0.16f);
			}
		}

		protected void UpdateStamina()
		{
			if (!Alive() || maxStaminaBase == -1)
			{
				return;
			}
			float num = stamina;
			if (levelData == null || levelData.GetLevelDepth() == 0 || isGod)
			{
				stamina = MaxStamina();
			}
			bool flag = PerformingAttack() || PerformingCast();
			if (Running() && !flag)
			{
				if (Pathing())
				{
					ModifyStamina(-2f * Time.deltaTime);
					if (stamina > 0f)
					{
						ModifyStamina(EffectValue(EffectType.Stamina) * Time.deltaTime * 0.016f);
					}
				}
				else
				{
					ModifyStamina((float)MaxStamina() * 0.1f * Time.deltaTime);
					ModifyStamina(EffectValue(EffectType.Stamina) * Time.deltaTime * 0.016f);
				}
			}
			else if (Pathing() && !flag)
			{
				if (stamina > 0f)
				{
					ModifyStamina((float)MaxStamina() * 0.05f * Time.deltaTime);
					ModifyStamina(EffectValue(EffectType.Stamina) * Time.deltaTime * 0.016f);
				}
			}
			else
			{
				ModifyStamina((float)MaxStamina() * 0.1f * Time.deltaTime);
				ModifyStamina(EffectValue(EffectType.Stamina) * Time.deltaTime * 0.016f);
			}
			bool flag2 = Mathf.Approximately(stamina, 0f);
			if (IsPlayer() && flag2 && num > 0f && !playedStaminaLow)
			{
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_stamina);
				playedStaminaLow = true;
				if (SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.Stamina, out var key))
				{
					SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
				}
			}
			if (flag2 && !HasMaster() && IsPlayer())
			{
				SetRunning(runningState: false);
			}
			if (stamina > (float)(MaxStamina() / 2))
			{
				playedStaminaLow = false;
			}
		}

