		private int ModifyDamage(int damage, DamageType damageType, out int resistAmount)
		{
			float num = EffectValue(EffectType.PercentDamageTaken);
			if (num < -75f)
			{
				num = -75f;
			}
			damage += Mathf.FloorToInt((float)damage * num / 100f);
			damage += Mathf.FloorToInt(EffectValue(EffectType.DamageTaken));
			if (damageType == DamageType.Heroic && IsBoss)
			{
				damage = Mathf.CeilToInt((float)damage * 3f);
			}
			if (damage < 1)
			{
				damage = 1;
			}
			resistAmount = Mathf.CeilToInt((float)DamageResistance(damageType) / 100f * (float)damage);
			damage -= resistAmount;
			if (damage < 0 || isGod)
			{
				damage = 0;
			}
			return damage;
		}

		private bool DetectDeath(Character pTarget, int LastHP)
		{
			if (pTarget == null || LastHP <= 0 || pTarget.hp > 0f)
			{
				return false;
			}
			if (!pTarget.Alive())
			{
				return false;
			}
			AwardExperience(pTarget.experienceReward, fromMaster: false);
			HasMaster();
			if (pTarget.isUnique)
			{
				HasMaster();
			}
			AwardFame((uint)pTarget.fameReward);
			return true;
		}

		public int ApplyDamage(CharacterVitals.Damage damage, bool allowReflection = true, bool skipModify = false)
		{
			if (skipModify)
			{
				ApplyDamage((damage.source != null) ? damage.source.Char : null, damage.value, allowReflection);
				return damage.value;
			}
			int value = damage.value;
			int num = ModifyDamage(damage.value, damage.damageType, out damage.damageResisted);
			damage.isFullResist = value > 0 && value == damage.damageResisted;
			damage.isPartialResist = value > 0 && damage.damageResisted > 0 && damage.damageResisted < value;
			if (UnityEngine.Debug.isDebugBuild && damage.source != null && damage.source.Char.IsPlayer())
			{
				num = (int)((float)num * Player.PlayerChar.debugDamageMult);
			}
			ApplyDamage((damage.source != null) ? damage.source.Char : null, num, allowReflection);
			return num;
		}

		private void ApplyDamage(Character pAttacker, float Damage, bool AllowReflection)
		{
			if (Damage == 0f || !Alive())
			{
				return;
			}
			if (pAttacker != null && pAttacker.IsPlayer())
			{
				pAttacker.ResetCurseTimer();
			}
			else if (IsPlayer() || (HasMaster() && Master().IsPlayer()))
			{
				ResetCurseTimer();
			}
			if (HasMaster() && Master().IsPlayer() && (eAIState == AIState.Hidden || eAIState == AIState.InTown || eAIState == AIState.ReturningToTown))
			{
				ModifyHP(0f);
			}
			else
			{
				ModifyHP((int)(0f - Damage));
			}
			if (pAttacker != null && AllowReflection && hp > 0f)
			{
				RespondToAttack(pAttacker);
			}
			if (AllowReflection && pAttacker != null && pAttacker.Alive() && EffectValue(EffectType.PercentDamageReflected) != 0f)
			{
				int value = Mathf.CeilToInt(Damage * EffectValue(EffectType.PercentDamageReflected) / 100f);
				float num = pAttacker.hp;
				pAttacker.MyVitals.ApplyDamage(new CharacterVitals.Damage
				{
					damageType = DamageType.None,
					source = MyVitals,
					value = value
				}, allowReflection: false, skipModify: true);
				if (pAttacker.Alive() && pAttacker.hp <= 0f && num > 0f)
				{
					DetectDeath(pAttacker, (int)num);
				}
			}
		}

		private void ResetCurseTimer()
		{
		}

		public int ApplyHeal(CharacterVitals.Heal heal)
		{
			int num = Mathf.RoundToInt(hp);
			ModifyHP(heal.value);
			return Mathf.RoundToInt(hp) - num;
		}

		protected void ModifyHP(float change)
		{
			if (isGod && hp < 0f && IsPlayer())
			{
				return;
			}
			float num = hp;
			if ((hp <= 0f && change > 0f && change < (float)MaxHP()) || (alignment == Alignment.Neutral && hp < 0f))
			{
				return;
			}
			hp = Mathf.Clamp(hp + change, 0f, MaxHP());
			if (hp != num)
			{
				myVitals.OnHealthChanged?.Invoke(hp);
			}
			if (invincible && hp < 1f)
			{
				RemoveEffect("POISON");
				if (HasMaster() && Master().HasPet(this))
				{
					hp = 1f;
					if (hp <= 1f && num > 1f && HasMaster() && Master().HasPet(this) && !SingletonBehaviour<Narrator>.Instance.IsPlaying())
					{
						SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_petflee);
					}
				}
				else if (HasMaster() && Master().HasPartyMember(this))
				{
					hp = 0f;
					if (!SingletonBehaviour<Narrator>.Instance.IsPlaying())
					{
						SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_narr_ally_collapsed);
					}
				}
			}
			if (!IsPlayer())
			{
				return;
			}
			if (HPPercentage() < 0.3f && !isHeartBeatPlaying)
			{
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.Heartbeat);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Heartbeat, randomizePitch: false);
				isHeartBeatPlaying = true;
			}
			else if (HPPercentage() > 0.3f || (hp <= 0f && isHeartBeatPlaying))
			{
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.Heartbeat);
				isHeartBeatPlaying = false;
			}
			if (hp < 30f && hp > 0f && num >= 30f)
			{
				SingletonBehaviour<Narrator>.Instance.ForcePlayYourLine(NarratorLines.Narrator_health);
				if (SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.HealthLow, out var key))
				{
					SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
				}
			}
		}

		protected void ModifyMana(float Mana)
		{
			mana = Mathf.Clamp(mana + Mana, 0f, MaxMana());
			myVitals.OnResourcesUpdated();
		}

		protected void ModifyStamina(float Stamina)
		{
			stamina = Mathf.Clamp(stamina + Stamina, 0f, MaxStamina());
		}

