		protected virtual void RespondToAttack(CharacterVitals.Damage attacker)
		{
			if (attacker.source == null || attacker.source == this)
			{
				return;
			}
			for (int i = 0; i < petCharacters.Count; i++)
			{
				if (!(petCharacters[i].Target() == null) || !petCharacters[i].AvailableForCommand())
				{
					continue;
				}
				if (petCharacters[i].TryGetComponent<Pet>(out var component))
				{
					if (petCharacters[i].eAIState == AIState.UniqueIdle)
					{
						component.CancelUniqueIdle();
					}
					component.StopPathing();
					component.SetAIState(AIState.Hunt);
					component.SetTarget(attacker.source.Char);
				}
				else
				{
					petCharacters[i].StopPathing();
					petCharacters[i].SetAIState(AIState.Hunt);
					petCharacters[i].SetTarget(attacker.source.Char);
				}
			}
		}

		public virtual void RespondToAttack(Character attacker)
		{
			if (attacker == null || attacker == this)
			{
				return;
			}
			for (int i = 0; i < petCharacters.Count; i++)
			{
				if (!(petCharacters[i].Target() == null) || !petCharacters[i].AvailableForCommand())
				{
					continue;
				}
				if (petCharacters[i].TryGetComponent<Pet>(out var component))
				{
					if (petCharacters[i].eAIState == AIState.UniqueIdle)
					{
						component.CancelUniqueIdle();
					}
					component.StopPathing();
					component.SetAIState(AIState.Hunt);
					component.SetTarget(attacker);
				}
				else
				{
					petCharacters[i].StopPathing();
					petCharacters[i].SetAIState(AIState.Hunt);
					petCharacters[i].SetTarget(attacker);
				}
			}
		}

		protected virtual void Attack()
		{
			if ((targetCharacter == null && targetItem == null && !holdPosition) || UnarmedAttacks() == 0)
			{
				return;
			}
			if (currentAttack == null)
			{
				SelectAttack();
				if (currentAttack == null)
				{
					return;
				}
			}
			if (!PerformingAttack())
			{
				reachedStrikePoint = false;
				float num = 1f;
				num += EffectValue(EffectType.PercentAttackSpeed) / 100f;
				num *= currentAttack.speed;
				if (num < 0.2f)
				{
					num = 0.2f;
				}
				attackTimer = num;
				animator.SetBool("IsAttacking", value: true);
				if (activeWeapon != null)
				{
					activeWeapon.PlayAttackSound();
				}
			}
		}

		protected virtual void Die()
		{
			if (IsPartyMember())
			{
				UnityEngine.Debug.LogWarning("Die() called on party member. That is not possible. They enter a 'Passed Out' state instead.");
				return;
			}
			if (IsSummoned() && LevelGenerator.currentInstance != null)
			{
				LevelGenerator.currentInstance.RemoveActiveCharacter(base.gameObject);
			}
			if (invincible)
			{
				SetAIState(AIState.Flee);
				return;
			}
			if (IsBoss)
			{
				StatsManager.IncrementStat(Stat.BossesKilled, 1, requestSave: true);
				if (Player.PlayerChar != null && Player.PlayerChar.activeWeapon != null)
				{
					StatsManager.OnBossKilled(Player.PlayerChar.activeWeapon.itemType.ToString());
				}
				SingletonBehaviour<QuestManager>.Instance.UniqueMonsterKilled(this);
			}
			else if (isUnique)
			{
				StatsManager.IncrementStat(Stat.BossesKilled, 1, requestSave: true);
				if (Player.PlayerChar != null && Player.PlayerChar.activeWeapon != null)
				{
					StatsManager.OnBossKilled(Player.PlayerChar.activeWeapon.itemType.ToString());
				}
				SingletonBehaviour<QuestManager>.Instance.UniqueMonsterKilled(this);
			}
			else if (family == Tableflip.Family.Ward)
			{
				Player.PlayerChar.RemoveWard(this);
				SingletonBehaviour<QuestManager>.Instance.WardEscortKilled(monsterData.displayName);
			}
			else if (alignment == Alignment.Evil)
			{
				SingletonBehaviour<QuestManager>.Instance.TargetMonsterKilled(this);
			}
			if (highlightObject != null && highlightObject.TryGetComponent<HighlightPulserScript>(out var component))
			{
				component.ActivateFadeout();
			}
			if (rankHighlightObject != null && rankHighlightObject.TryGetComponent<HighlightPulserScript>(out var component2))
			{
				component2.ActivateFadeout();
			}
			for (int i = 0; i < GetPetCount(); i++)
			{
				if (GetPet(i).IsSummoned())
				{
					GetPet(i).SetLifeDuration(0.01f);
				}
			}
			activeWeapon = null;
			currentAttack = null;
			ClearEffects();
			SetAIState(AIState.Dying);
			animator.SetBool("IsDead", value: true);
			path.enabled = false;
			if (lifeDuration > 0f)
			{
				if (HasMaster())
				{
					Master().RemovePet(this);
				}
				else
				{
					UnityEngine.Debug.LogWarning($"{this} (summon) had no master when dying. That shouldn't happen.");
				}
				GameObject gameObject = SingletonBehaviour<FateDB>.Instance.spellPrefabs.Find((GameObject p) => p.name.ToUpper() == "P_SUMMON");
				if (gameObject != null)
				{
					UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(gameObject, base.transform.position, Quaternion.identity), 5f);
				}
				UnityEngine.Object.Destroy(base.gameObject, 0.1f);
			}
			else if (HasMaster() && !Master().IsPlayer())
			{
				Master().RemovePet(this);
			}
		}

