		protected int UnarmedAttacks()
		{
			if (monsterData == null)
			{
				return 1;
			}
			return monsterData.attacks.Count;
		}

		protected virtual AttackData UnarmedAttack(int index)
		{
			if (index >= monsterData.attacks.Count)
			{
