		public bool PerformingAttack()
		{
			if (currentAttack == null)
			{
				return false;
			}
			if (attackTimer > 0f)
			{
				return true;
			}
			return false;
		}

		public bool PerformingCast()
		{
			if (activeSpell == null && activeRageSpell == null)
			{
				return false;
			}
			if (castTimer > 0f)
			{
				return true;
			}
			return false;
		}

		protected void PerformAttack()
		{
			if (debug)
			{
				UnityEngine.Debug.Log($"{this} attempting to perform attack");
			}
			bool flag = false;
			if (currentAttack == null)
			{
				return;
			}
			Character character = targetCharacter;
			if (character == null && targetItem == null)
			{
				Alignment num = ((monsterData != null) ? monsterData.alignment : GetAlignment());
				Alignment alignment = Alignment.Good;
				if (num == Alignment.Good)
				{
					alignment = Alignment.Evil;
				}
				Character character2 = levelData.FindCharacterWithinView(myTransform, alignment, 0f, 30f, 30f);
				if (character2 != null)
				{
					character = character2;
				}
			}
			if (character == null)
			{
				return;
			}
			Character character3 = null;
			bool flag2 = true;
			bool flag3 = activeWeapon != null && (activeWeapon.itemType == ItemType.Bow || activeWeapon.itemType == ItemType.Crossbow);
			if (flag3)
			{
				EquipmentHandle equipmentHandle = ((leftWeaponHandle != null && leftWeaponHandle.CurrentEquipment != null) ? leftWeaponHandle : ((rightWeaponHandle != null && rightWeaponHandle.CurrentEquipment != null) ? rightWeaponHandle : null));
				flag2 = equipmentHandle != null;
				if (flag2)
				{
					Vector3 position = equipmentHandle.transform.position;
					Vector3 vector = myTransform.position + myTransform.forward;
					if (character != null)
					{
						vector = character.myTransform.position;
					}
					vector.y = Mathf.Min(position.y, 3f);
					Vector3 normalized = (vector - position).normalized;
					LayerMask layerMask = ((GetAlignment() == Alignment.Evil) ? LayerMask.GetMask("Player", "Default", "Walls") : LayerMask.GetMask("Player Damagable", "Default", "Walls"));
					if (Physics.Raycast(position, normalized, out var hitInfo, activeWeapon.strikeRadius * 0.25f, layerMask))
					{
						flag = hitInfo.collider.gameObject.layer == LayerMask.NameToLayer("Default");
						character3 = hitInfo.collider.GetComponent<Character>();
					}
					LineRenderer component = equipmentHandle.CurrentEquipment.GetComponent<LineRenderer>();
					if (component == null)
					{
						if (rangedWeaponLineRendererFallback == null)
						{
							rangedWeaponLineRendererFallback = UnityEngine.Object.Instantiate(SingletonBehaviour<FateDB>.Instance.rangedAttackLineRendererFallbackPrefab, myTransform);
							rangedWeaponLineRendererFallback.transform.position = Vector3.zero;
							rangedWeaponLineRendererFallback.transform.rotation = Quaternion.identity;
							rangedWeaponLineRendererFallback.transform.localScale = Vector3.one;
							rangedWeaponLineRendererFallback.gameObject.name = "_RangedWeaponLineRendererFallback";
						}
						component = rangedWeaponLineRendererFallback;
					}
					component.enabled = true;
					component.positionCount = 2;
					component.SetPosition(0, equipmentHandle.transform.position);
					component.SetPosition(1, (hitInfo.point != default(Vector3)) ? hitInfo.point : vector);
					StartCoroutine(ArrowTrailFadeOut(component));
				}
			}
			else
			{
				character3 = character;
			}
			if (!flag2 || (!flag3 && (!InStrikeRange(character.gameObject) || !FacingTarget(character.gameObject, null))))
			{
				return;
			}
			bool flag4 = false;
			if (character3 != null && !flag && RollAttack(character3))
			{
				flag4 = true;
			}
			if (flag4)
			{
				if (currentAttack != null && TryGetComponent<MonsterSounds>(out var component2))
				{
					component2.PlayStrikeSound(currentAttack.animKey);
				}
			}
			else
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.AttackMiss, randomizePitch: true);
			}
		}

		protected void SwapDualWieldWeaponHand()
		{
			if (IsDualWielding)
			{
				activeWeapon = ((activeWeapon == equippedWeapons[0]) ? equippedWeapons[1] : equippedWeapons[0]);
			}
		}

		public void ToggleActiveWeaponSet()
		{
			SetActiveWeaponSet((activeWeaponSet != WeaponSet.Primary) ? WeaponSet.Primary : WeaponSet.Secondary);
		}

		public void SetActiveWeaponSet(WeaponSet set)
		{
			if (activeWeaponSet == set)
			{
				return;
			}
			foreach (Item item in inventory.FindAll((Item i) => i.equipped && i.weaponSet != set && (i.IsInMainHand || i.IsInOffHand)))
			{
				UnequipItem(item);
			}
			activeWeaponSet = set;
			foreach (Item item2 in inventory.FindAll((Item i) => i.InEquipmentSlot && i.weaponSet == set && (i.IsInMainHand || i.IsInOffHand)))
			{
				EquipItem(item2, set);
			}
			if (IsPlayer())
			{
				animator.SetTrigger(GameSettings.Instance.AnimParamWeaponSetSwap);
			}
			onWeaponSetChanged?.Invoke(set);
		}

		protected IEnumerator ArrowTrailFadeOut(LineRenderer lineRenderer)
		{
			Material lineMaterial = lineRenderer.material;
			float timeElapsed = 0f;
			while (timeElapsed < 0.5f)
			{
				float a = Mathf.Lerp(1f, 0f, timeElapsed / 0.5f);
				lineMaterial.color = new Color(lineMaterial.color.r, lineMaterial.color.g, lineMaterial.color.b, a);
				timeElapsed += Time.deltaTime;
				yield return null;
			}
			if (lineRenderer != null)
			{
				lineRenderer.enabled = false;
			}
		}

		protected virtual bool DelayAttack()
		{
			return false;
		}

		public bool ValidLineOfSight()
		{
			bool result = true;
			if (IsCurrentTargetValid())
			{
				Vector3 position = myTransform.position;
				Vector3 vector = Target().myTransform.position - position;
				Vector3 normalized = vector.normalized;
				float magnitude = vector.magnitude;
				int wallLayerMask = LevelGenerator.WallLayerMask;
				position = Physics.ClosestPoint(Target().myTransform.position, myCollider, myTransform.position, myTransform.rotation);
				position.y = 1f;
				if (Physics.Raycast(position, normalized, out var hitInfo, magnitude, wallLayerMask) && hitInfo.collider.gameObject != Target().gameObject)
				{
					result = false;
				}
			}
			return result;
		}

		public virtual void SelectAttack()
		{
			if (PerformingAttack())
			{
				return;
			}
			currentAttack = null;
			if (DelayAttack())
			{
				return;
			}
			if (activeWeapon != null)
			{
				currentAttack = new AttackData(activeWeapon, activeWeapon.IsInMainHand);
				return;
			}
			Mathf.CeilToInt(1000f - (float)magicAttackRarity);
			if (currentAttack != null || UnarmedAttacks() <= 0)
			{
				return;
			}
			Randomizer randomizer = new Randomizer();
			int num = 0;
			for (int i = 0; i < UnarmedAttacks(); i++)
			{
				AttackData attackData = UnarmedAttack(i);
				int num2 = 1000 - attackData.rarity;
				if (num2 < 0)
				{
					num2 = 0;
				}
				if (num2 > 0)
				{
					randomizer.AddChoice(i, num2);
					num++;
				}
			}
			if (num > 0)
			{
				int random = randomizer.GetRandom();
				if (random >= 0 && random < UnarmedAttacks())
				{
					currentAttack = UnarmedAttack(random);
					currentAttack.animIndex = random;
				}
			}
		}

		public int SkillPoints(Attribute skillType)
		{
			int num = attributes.GetAttribute(skillType, allowEffects: true);
			if (num < 0)
			{
				num = 0;
			}
			return num;
		}

		public bool Blocked()
		{
			if (leftWeaponHandle == null || leftWeaponHandle.CurrentEquipment == null)
			{
				return false;
			}
			if (inventory.Find((Item it) => it.equipped && it.itemType == ItemType.Shield) == null)
			{
				return false;
			}
			float num = 50f / (float)attributes.GetAttribute(Attribute.SkillShield, allowEffects: false);
			num = 50f - num;
			num += EffectValue(EffectType.PercentBlockChance);
			if (num > 50f)
			{
				num = 50f;
			}
			if ((float)UnityEngine.Random.Range(0, 100) < num)
			{
				ThatHurt.PopText(myTransform.position, I2Loca.Get("Blocked"), 1f, 2f, ThatHurt.ThatHurtColor.White, 0f);
				if (UnityEngine.Random.Range(0, 2) == 0)
				{
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.MetalSlash2, randomizePitch: true);
				}
				else
				{
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Block, randomizePitch: true);
				}
				return true;
			}
			return false;
		}

		public void AddUnusedStatPoints(int amount)
		{
			unusedStatPoints += amount;
		}

		public void AddUnusedSkillPoints(int amount)
		{
			unusedSkillPoints += amount;
		}

		private int ToHitBonus(Item weapon)
		{
			int num = toHitBonus;
			if (weapon != null)
			{
				num += SkillPoints(attributes.WeaponTypeToSkillAttribute(weapon.itemType));
			}
			if (currentAttack != null)
			{
				num += currentAttack.toHitBonus;
			}
			return num;
		}

		public int ToHit(bool useBestWeapon = false, bool withEffects = true)
		{
			Item weapon;
			if (useBestWeapon && IsDualWielding)
			{
				Item equippedWeapon = GetEquippedWeapon(WeaponHand.MainHand);
				Item equippedWeapon2 = GetEquippedWeapon(WeaponHand.OffHand);
				weapon = ((equippedWeapon.toHitBonus >= equippedWeapon2.toHitBonus) ? equippedWeapon : equippedWeapon2);
			}
			else
			{
				weapon = activeWeapon;
			}
			int num = 50 + attributes.Dexterity / 2 + ToHitBonus(weapon) + Level;
			if (withEffects)
			{
				num += Mathf.CeilToInt((float)num * EffectValue(EffectType.PercentToHitBonus) / 100f);
				num += (int)EffectValue(EffectType.ToHitBonus);
			}
			return num;
		}

		private int CharacterDamage()
		{
			if (HasMaster() && Master().IsPlayer() && !IsSummoned())
			{
				return Level;
			}
			return 0;
		}

		private int ArmorBonus(bool withEffects = true)
		{
			int num = armorBonus + NaturalArmor();
			if (withEffects)
			{
				num += Mathf.CeilToInt((float)num * EffectValue(EffectType.PercentArmorBonus) / 100f);
				num += (int)EffectValue(EffectType.ArmorBonus);
			}
			return num;
		}

		private int NaturalArmor()
		{
			if (HasMaster() && Master().IsPlayer() && !IsSummoned())
			{
				return naturalArmor + Level * 3;
			}
			return naturalArmor;
		}

		public int AC(bool withEffects = true)
		{
			return ArmorBonus(withEffects) + DexterityBonus();
		}

		private int DexterityBonus()
		{
			return Mathf.RoundToInt((float)attributes.Dexterity * 0.2f);
		}

		protected bool RollAttack(Character target)
		{
			CharacterVitals component = target.GetComponent<CharacterVitals>();
			if (target == null || component == null || component.GetHealth() <= 0f)
			{
				return false;
			}
			if (currentAttack == null)
			{
				return false;
			}
			bool flag = false;
			float num = UnityEngine.Random.Range(0, 100);
			float num2 = 50f / ((float)SkillPoints(Attribute.SkillCriticalStrike) * 0.03f + 1f);
			num2 = 50f - num2;
			if (num2 > 50f)
			{
				num2 = 50f;
			}
			float num3 = UnityEngine.Random.Range(0, 100);
			if (Mathf.CeilToInt(num) == 100 || num3 < num2)
			{
				flag = true;
			}
			float num4 = 100f * ((float)ToHit() / (float)(ToHit() + target.AC()));
			if (num4 < 5f)
			{
				num4 = 5f;
			}
			if (num4 > 95f)
			{
				num4 = 95f;
			}
			if (num <= num4 || (UnityEngine.Debug.isDebugBuild && IsPlayer() && isGod))
			{
				int num5 = CharacterDamage() + RollWeaponDamage();
				if (flag)
				{
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.CriticalAttack, randomizePitch: true);
					num5 += num5;
				}
				DamageType damageType = currentAttack.damageType;
				if (activeWeapon != null)
				{
					damageType = activeWeapon.baseDamageType;
				}
				int num6 = num5;
				num5 = target.ModifyDamage(num5, damageType, out var resistAmount);
				bool isFullResist = num6 > 0 && num6 == resistAmount;
				bool isPartialResist = num6 > 0 && resistAmount > 0 && resistAmount < num6;
				int num7 = 0;
				if (activeWeapon != null)
				{
					foreach (ElementAmount damageBonuse in activeWeapon.damageBonuses)
					{
						int value = damageBonuse.value;
						DamageType type = damageBonuse.type;
						int num8 = Mathf.CeilToInt((float)DamageResistance(type) / 100f * (float)value);
						if (num8 > 0)
						{
							num7 += num8;
						}
						value -= num8;
						if (value < 0)
						{
							value = 0;
						}
						num5 += value;
					}
				}
				resistAmount = num7;
				if (target.Blocked())
				{
					num5 = 0;
				}
				float num9 = num5;
				if (num9 > (float)target.HP())
				{
					num9 = target.HP();
				}
				float num10 = EffectValue(EffectType.PercentLifeStolen);
				Mathf.Clamp(num10, -100f, 100f);
				float num11 = num9 * num10 / 100f;
				if (num11 > 0f)
				{
					ModifyHP(num11);
				}
				else if (num11 < 0f)
				{
					ModifyHP(num11);
				}
				num10 = EffectValue(EffectType.PercentManaStolen);
				Mathf.Clamp(num10, -100f, 100f);
				float num12 = num9 * num10 / 100f;
				if (num12 != 0f)
				{
					ModifyMana(num12);
				}
				int value2 = Mathf.RoundToInt(myVitals.Char.EffectValue(EffectType.PercentPoison));
				value2 = Mathf.Clamp(value2, 0, 100);
				if (UnityEngine.Random.Range(0, 100) < value2)
				{
					EffectData effectData = new EffectData(EffectType.HPRecharge, positive: false, ActivationType.Usage, 10, -5 * num5, 0f);
					effectData.applicationMessage = "EffectMsg_Poisoned";
					effectData.name = "POISON";
					effectData.damageType = DamageType.Poison;
					target.AddEffect(effectData, Level, this);
				}
				float num13 = EffectValue(EffectType.Knockback);
				num13 += currentAttack.EffectValue(ActivationType.Usage, EffectType.Knockback);
				if (activeWeapon != null)
				{
					num13 += activeWeapon.EffectValue(ActivationType.Usage, EffectType.Knockback);
				}
				if (num13 > 0f)
				{
					Vector3 direction = target.myTransform.position - myTransform.position;
					direction.y = 0f;
					direction.Normalize();
					target.Knockbacked(direction, 2f + num13 * 0.1f);
				}
				int num14 = target.HP();
				if (target != null)
				{
					CharacterVitals.Damage data = new CharacterVitals.Damage
					{
						value = num5,
						damageResisted = resistAmount,
						isFullResist = isFullResist,
						isPartialResist = isPartialResist,
						damageType = damageType,
						source = myVitals,
						isCritical = flag
					};
					component.ApplyDamage(data);
				}
				if (target != null && target.HP() <= 0 && num14 > 0)
				{
					DetectDeath(target, num14);
					if (IsPet() && HasMaster() && Master().IsPlayer())
					{
						StatsManager.IncrementStat(Stat.PetKills);
					}
				}
				if (currentAttack != null && num5 > 0)
				{
					if (currentAttack.effectData != null)
					{
						foreach (EffectData effectDatum in currentAttack.effectData)
						{
							if (effectDatum.activationType == ActivationType.Usage)
							{
								int num15 = UnityEngine.Random.Range(0, 100);
								if (effectDatum.buffType != EffectType.Knockback && num15 <= effectDatum.chance && target != null && target.Alive())
								{
									target.AddEffect(effectDatum, 0, this);
								}
							}
						}
					}
					Item item = activeWeapon;
					if (item != null && item.effects?.ContainsKey(ActivationType.Usage) == true)
					{
						foreach (EffectData item2 in activeWeapon.effects[ActivationType.Usage])
						{
							int num16 = UnityEngine.Random.Range(0, 100);
							if (item2.buffType != EffectType.Knockback && num16 <= item2.chance && target != null && target.Alive())
							{
								target.AddEffect(item2, Level, this);
							}
						}
					}
				}
				return true;
			}
			component.Missed();
			return false;
		}

		protected void Knockbacked(Vector3 direction, float speed)
		{
			if (!Alive() || IsShrine())
			{
				return;
			}
			AIState aIState = GetAIState();
			if (aIState == AIState.ReturningToTown || aIState == AIState.InTown || aIState == AIState.Hidden)
			{
				return;
			}
			speed *= Mathf.Clamp01(1f - knockbackProtection);
			knockbackProtection = Mathf.Clamp01(knockbackProtection + 0.2f);
			UnderKnockback = true;
			StopPathing();
			path.updateRotation = false;
			if (IsPlayer())
			{
				SingletonBehaviour<InputBroker>.Instance.BlockMovement(statement: true);
				(this as Player).Push(direction, speed * 75f);
				KnockbackDuration = speed / 2f;
				return;
			}
			path.speed = speed * 2f;
			KnockbackDuration = speed;
			SetAIState(AIState.Inactive);
			Vector3 vector = myTransform.position + direction * speed;
			SetDestination(vector.x, vector.z);
			float num = 1.1f;
			while (path.path.corners.Length > 2 && num < 10f)
			{
				vector = myTransform.position + direction * (speed / num);
				num += 0.1f;
				SetDestination(vector.x, vector.z);
			}
			if (num >= 10f)
			{
				SetDestination(myTransform.position.x, myTransform.position.z);
			}
		}

		protected void KnockBackCheck()
		{
			knockbackProtection = Mathf.MoveTowards(knockbackProtection, 0f, 0.03f * Time.deltaTime);
			if (!UnderKnockback)
			{
				return;
			}
			if (IsPlayer())
			{
				KnockbackDuration -= Time.deltaTime;
				if (Alive())
				{
					path.isStopped = true;
				}
				if (KnockbackDuration <= 0f)
				{
					UnderKnockback = false;
					path.enabled = true;
					SingletonBehaviour<InputBroker>.Instance.BlockMovement(statement: false);
				}
			}
			else
			{
				KnockbackDuration -= Time.deltaTime;
				if (path.isActiveAndEnabled && (path.path.corners.Length > 2 || path.remainingDistance <= 0.01f))
				{
					StopPathing();
				}
				if (KnockbackDuration <= 0f)
				{
					UnderKnockback = false;
					path.updateRotation = true;
				}
			}
		}

		protected void UpdateAttack()
		{
			if (!PerformingAttack())
			{
				breathActive = false;
			}
			else
			{
				_ = currentAttack;
			}
		}

		protected void UpdateCast()
		{
		}

		protected void UpdatePathing()
		{
			if (!path.pathPending && path.isOnNavMesh && path.remainingDistance <= path.stoppingDistance && (!path.hasPath || path.velocity.sqrMagnitude == 0f))
			{
				StopPathing();
			}
		}

		protected void UpdateTimers()
		{
			if (!Alive())
			{
				return;
			}
			timeSinceIdleSound += Time.deltaTime;
			if (timeSinceIdleSound > 100f)
			{
				timeSinceIdleSound = 100f;
			}
			timeSinceUniqueIdle += Time.deltaTime;
			if (timeSinceUniqueIdle > 100f)
			{
				timeSinceUniqueIdle = 100f;
			}
			timeSincePath += 1f * Time.deltaTime;
			if (timeSincePath > 100f)
			{
				timeSincePath = 100f;
			}
			timeSinceAvoidance += 1f * Time.deltaTime;
			if (timeSinceAvoidance > 100f)
			{
				timeSinceAvoidance = 100f;
			}
			if (!(lifeDuration > 0f))
			{
				return;
			}
			lifeDuration -= 1f * Time.deltaTime;
			if (lifeDuration <= 0f)
			{
				GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Dispel");
				if (particlePrefab != null)
				{
					UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab, myTransform.position, Quaternion.identity), 2f);
				}
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.GivePoint, 0f, 0.5f);
				hp = 0f;
				lifeDuration = 0.01f;
				myVitals.Die();
				SetAIState(AIState.Dying);
				if (HasMaster())
				{
					Master().RemovePet(this);
				}
				lifeDuration = 0f;
				UnityEngine.Object.Destroy(base.gameObject, 0.1f);
			}
		}

		protected void UpdateMotion()
		{
		}

		public void SetInvincible(bool setToInvincible = true)
		{
			invincible = setToInvincible;
		}

		public void UpdateNavmeshAvoidance()
		{
			if (!(path != null))
			{
				return;
			}
			if (IsPlayer())
			{
				path.avoidancePriority = 99;
			}
			else if (IsPet() || IsPartyMember() || IsSummoned())
			{
				path.avoidancePriority = 90;
			}
			else if (IsShrine())
			{
				path.avoidancePriority = Mathf.FloorToInt(Fate.NavMeshPrioMonster.Min);
				path.obstacleAvoidanceType = ObstacleAvoidanceType.NoObstacleAvoidance;
			}
			else if (IsMonster())
			{
				if (isUnique)
				{
					path.avoidancePriority = Mathf.FloorToInt(Fate.NavMeshPrioMonster.Min);
					path.obstacleAvoidanceType = ObstacleAvoidanceType.LowQualityObstacleAvoidance;
				}
				else
				{
					int avoidancePriority = Mathf.FloorToInt(Fate.NavMeshPrioMonster.GetValue());
					path.avoidancePriority = avoidancePriority;
				}
			}
			else if (IsNPC())
			{
				int avoidancePriority2 = Mathf.FloorToInt(Fate.NavMeshPrioNPC.GetValue());
				path.avoidancePriority = avoidancePriority2;
				path.obstacleAvoidanceType = ObstacleAvoidanceType.LowQualityObstacleAvoidance;
			}
		}

		public void SetPositionProper(Vector3 pos)
		{
			bool flag = path.enabled;
			path.enabled = false;
			if (myTransform != null)
			{
				myTransform.position = pos;
			}
			else
			{
				base.transform.position = pos;
			}
			path.enabled = flag;
		}
	}
	public class CharacterVitals : MonoBehaviour
	{
		public class Damage
		{
			public CharacterVitals source;

			public int value;

			public int damageResisted;

			public bool isCritical;

			public bool isFullResist;

			public bool isPartialResist;

			public DamageType damageType;

			public void UpdateDmg(int damage)
			{
				value = damage;
			}

			public bool IsFullyResisted()
			{
				return isFullResist;
			}

			public bool IsPartiallyResisted()
			{
				return isPartialResist;
			}
		}

		public class Heal
		{
			public int value;
		}

		[Header("Configuration")]
		[SerializeField]
		protected Character character;

		[SerializeField]
		protected bool TakeNoDamage;

		private static int m_globalLifeIdIndex;

		public Action<Damage> OnKilled;

		public Action OnRevived;

		public Action<Damage> OnDamaged;

		public Action<Heal> OnHealed;

		public Action<int> OnEnergized;

		public Action<int> OnLearned;

		public Action OnVitalsChanged;

		public Action OnExperienceChanged;

		public Action OnMissed;

		public Action<int> OnLevelUp;

		public Action<float> OnHealthChanged;

		public Action<float> OnManaChanged;

		private int m_lifeId;

		private bool m_isDead;

		private AttributeSet Attributes => character.attributes;

		public Character Char => character;

		public int LifeId => m_lifeId;

		public Alignment Alignment => character.GetAlignment();

		public bool IsDead
		{
			get
			{
				return m_isDead;
			}
			protected set
			{
				m_isDead = value;
			}
		}

		protected float Health => character.hp;

		protected float Mana => character.mana;

		private void Reset()
		{
			TakeNoDamage = false;
			character = GetComponent<Character>();
		}

		protected virtual void Awake()
		{
			if (character == null)
			{
				character = GetComponent<Character>();
				if (character == null)
				{
					UnityEngine.Debug.LogError("Vitals must have a Character to work!");
					base.enabled = false;
					return;
				}
			}
			AttributeSet attributes = Attributes;
			attributes.onAttributeValueChanged = (Action<Attribute, int>)Delegate.Combine(attributes.onAttributeValueChanged, new Action<Attribute, int>(OnAttributeValueChanged));
			m_lifeId = GetNextGlobalLifeId();
		}

		private void Start()
		{
			if (Health < 1f && !character.IsPet())
			{
				Die(new Damage());
			}
			OnVitalsChanged?.Invoke();
			OnHealthChanged?.Invoke(Health);
			OnManaChanged?.Invoke(Mana);
			OnExperienceChanged?.Invoke();
		}

		private void OnAttributeValueChanged(Attribute attrib, int newValue)
		{
		}

		private void Die(Damage finalData)
		{
			IsDead = true;
			if (finalData.source != null)
			{
				finalData.source.AddExperience(GetExperienceReward());
				if (finalData.source.Char.IsPlayer() || (finalData.source.Char.HasMaster() && finalData.source.Char.Master().IsPlayer()))
				{
					Player.PlayerChar.KilledEnemy();
					Player.PlayerChar.AwardFame((uint)GetFameReward());
				}
			}
			OnKilled?.Invoke(finalData);
		}

		public void Die()
		{
			IsDead = true;
			OnKilled?.Invoke(new Damage());
		}

		public void Revive()
		{
			IsDead = false;
			OnRevived?.Invoke();
		}

		public int GetExperienceReward()
		{
			return character.GetExperienceReward();
		}

		public int GetFameReward()
		{
			return character.GetFameReward();
		}

		public void OnResourcesUpdated()
		{
			OnHealthChanged?.Invoke(Health);
			OnManaChanged?.Invoke(Mana);
		}

		public float GetHealth()
		{
			return Health;
		}

		public float GetMaxHealth()
		{
			return character.MaxHP();
		}

		public float GetHealthPct()
		{
			return Health / (float)character.MaxHP();
		}

		public float GetMana()
		{
			return Mana;
		}

		public float GetMaxMana()
		{
			return character.MaxMana();
		}

		public float GetManaPct()
		{
			return Mana / (float)character.MaxMana();
		}

		public void AddExperience(int value)
		{
			if (value >= 1)
			{
				character.AwardExperience(value, fromMaster: false);
				OnVitalsChanged?.Invoke();
				OnExperienceChanged?.Invoke();
			}
		}

		public void ApplyDamage(Damage data, bool allowReflection = true, bool skipModify = false)
		{
			if (!IsDead && (!(data.source != null) || data.source.Alignment != Alignment) && (!(data.source != null) || !data.source.character.IsPet() || !data.source.character.Master().IsPlayer() || !(data.source.character.hp <= 1f)))
			{
				data.UpdateDmg(character.ApplyDamage(data, allowReflection, skipModify));
				OnDamaged?.Invoke(data);
				OnHealthChanged?.Invoke(Health);
				if (!(Health > 0f))
				{
					Die(data);
				}
			}
		}

		public void Missed()
		{
			if (!IsDead)
			{
				OnMissed?.Invoke();
			}
		}

		public void ApplyHeal(Heal data)
		{
			if (!IsDead)
			{
				character.ApplyHeal(data);
				OnHealed?.Invoke(data);
				OnHealthChanged?.Invoke(Health);
			}
		}

		public void FullHeal(bool removeNegativeEffects)
		{
			ApplyHeal(new Heal
			{
				value = character.MaxHP()
			});
			ApplyMana(character.MaxMana());
			if (removeNegativeEffects)
			{
				character.RemoveAllNegativeEffects();
			}
			if (character.HasPet())
			{
				Character pet = character.GetPet();
				if (pet != null)
				{
					pet.MyVitals.FullHeal(removeNegativeEffects);
				}
			}
			for (int i = 0; i < character.GetPartyMemberCount(); i++)
			{
				Character partyMember = character.GetPartyMember(i);
				if (partyMember != null)
				{
					partyMember.MyVitals.FullHeal(removeNegativeEffects);
				}
			}
		}

		public void SetHealthPct(float pct)
		{
			character.hp = (float)character.MaxHP() * Mathf.Clamp01(pct);
			OnHealthChanged?.Invoke(Health);
		}

		public virtual void ApplyMana(int amount)
		{
			if (!IsDead)
			{
				character.mana = Mathf.Clamp(character.mana + (float)amount, 0f, character.MaxMana());
				OnEnergized?.Invoke(amount);
				OnManaChanged?.Invoke(Mana);
			}
		}

		public void SetOwner(Character owner)
		{
			character = owner;
		}

		private static int GetNextGlobalLifeId()
		{
			return ++m_globalLifeIdIndex;
		}
	}
	public class ContainerDestroyable : MonoBehaviour
	{
		public GameObject simulatedObject;

		public GameObject destroyedObject;

		private GameObject replacingObject;

		public Action onInitialized;

		public Item Item { get; set; }

		public bool IsDestroyed { get; private set; }

		public int ContainedGold { get; private set; }

		public List<Item> ContainedItems { get; private set; }

		public TrapType TrapType { get; private set; }

		private void OnDestroy()
		{
			if (replacingObject != null)
			{
				UnityEngine.Object.Destroy(replacingObject);
			}
		}

		public void Init(bool state, int amountGold, TrapType typeOfTrap, List<Item> innerItems)
		{
			IsDestroyed = state;
			ContainedGold = amountGold;
			ContainedItems = innerItems;
			TrapType = typeOfTrap;
			if (IsDestroyed)
			{
				base.gameObject.layer = 0;
				if (destroyedObject != null)
				{
					base.gameObject.GetComponent<MeshRenderer>().enabled = false;
					base.gameObject.GetComponent<Collider>().enabled = false;
					replacingObject = UnityEngine.Object.Instantiate(destroyedObject, base.transform.position, base.transform.rotation);
				}
			}
			if (TryGetComponent<NavMeshObstacle>(out var component))
			{
				component.enabled = !IsDestroyed;
			}
			onInitialized?.Invoke();
		}

		public void Destroyed()
		{
			if (IsDestroyed)
			{
				return;
			}
			IsDestroyed = true;
			base.gameObject.layer = 0;
			if (Item.itemBaseName.Contains("Crate"))
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.CrateBreaking, randomizePitch: true);
			}
			if (Item.itemBaseName.Contains("Urn"))
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.UrnBreaking, randomizePitch: true);
			}
			if (Item.itemBaseName.Contains("Barrel"))
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.BarrelBreaking, randomizePitch: true);
			}
			StatsManager.IncrementStat(Stat.BarrelsBroken);
			if (TrapType != 0)
			{
				GameObject gameObject = null;
				List<Character> list = Fate.FindCharactersInArea(base.transform.position, 3f);
				StatsManager.IncrementStat(Stat.TrapsSprung);
				switch (TrapType)
				{
				case TrapType.TrapExplosion:
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Explosion");
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_trap);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ExplosionTrap, randomizePitch: true);
					foreach (Character item in list)
					{
						if (item.Alive() && item.GetAlignment() != Alignment.Neutral && !item.Blocked())
						{
							item.AddEffect(new EffectData(EffectType.HP, positive: false, ActivationType.Usage, -900, -10, 0f), Player.PlayerChar.Level, (item.GetAlignment() == Alignment.Evil) ? Player.PlayerChar : null);
						}
					}
					break;
				case TrapType.TrapPoison:
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("PoisonCrate");
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_trap);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.PoisonTrap, randomizePitch: true);
					foreach (Character item2 in list)
					{
						if (item2.Alive() && item2.GetAlignment() != Alignment.Neutral && !item2.Blocked())
						{
							EffectData effect = new EffectData(EffectType.HPRecharge, positive: false, ActivationType.Usage, 20, -45, 0f)
							{
								applicationMessage = "EffectMsg_Poisoned",
								name = "POISON",
								damageType = DamageType.Poison
							};
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								item2.AddEffect(effect, 1, (item2.GetAlignment() == Alignment.Evil) ? Player.PlayerChar : null);
							}
							else if (item2.MyVitals != null)
							{
								item2.MyVitals.Missed();
							}
						}
					}
					break;
				}
				if (gameObject != null)
				{
					UnityEngine.Object.Instantiate(gameObject, base.transform);
				}
				ThatHurt.PopText(base.transform.position, I2Loca.Get("Trapped"), 1f, ThatHurt.ThatHurtColor.Damage, 0f);
			}
			if (ContainedGold > 0)
			{
				int num = (int)((float)ContainedGold * (Player.PlayerChar.EffectValue(EffectType.PercentGoldDrop) / 100f));
				ActiveLevel.SpawnGoldPile(LevelGenerator.currentInstance.RandomOpenPosition(base.transform.position, 0.5f, 2f), ContainedGold + num);
			}
			if (ContainedItems == null)
			{
				List<Item> list3 = (ContainedItems = new List<Item>());
			}
			ActiveLevel.ApplyMagicFindToInventory(ContainedItems, applyToEquippedItems: true);
			foreach (Item containedItem in ContainedItems)
			{
				if (containedItem.GetItemPrefab() == null)
				{
					UnityEngine.Debug.LogWarning("Missing prefab for the item " + containedItem.itemName);
				}
				else
				{
					containedItem.Drop(LevelGenerator.currentInstance.RandomOpenPosition(base.transform.position, 0.5f, 2f));
				}
			}
			if (simulatedObject != null)
			{
				base.gameObject.GetComponent<MeshRenderer>().enabled = false;
				base.gameObject.GetComponent<Collider>().enabled = false;
				replacingObject = UnityEngine.Object.Instantiate(simulatedObject, base.transform.position, base.transform.rotation);
			}
			if (TryGetComponent<NavMeshObstacle>(out var component))
			{
				component.enabled = false;
			}
		}
	}
	[RequireComponent(typeof(ContainerDestroyable))]
	public class ContainerDestroyableTooltip : InteractableTooltipBase
	{
		private ContainerDestroyable destroyable;

		protected override void Awake()
		{
			base.Awake();
			destroyable = GetComponent<ContainerDestroyable>();
			ContainerDestroyable containerDestroyable = destroyable;
			containerDestroyable.onInitialized = (Action)Delegate.Combine(containerDestroyable.onInitialized, new Action(UpdateTooltip));
		}

		private void OnDestroy()
		{
			if (destroyable != null)
			{
				ContainerDestroyable containerDestroyable = destroyable;
				containerDestroyable.onInitialized = (Action)Delegate.Remove(containerDestroyable.onInitialized, new Action(UpdateTooltip));
			}
		}

		protected override void ShowTooltip()
		{
			if (!destroyable.IsDestroyed)
			{
				tooltipCanvas.gameObject.SetActive(value: true);
			}
			else
			{
				PermanentDisable();
			}
		}

		protected override void UpdateTooltip()
		{
			if (destroyable.Item == null)
			{
				UnityEngine.Debug.LogError($"{this} container destroyable tooltip item is null");
				UnityEngine.Object.Destroy(this);
			}
			else
			{
				tooltipCanvas.SetText(I2Loca.Get(destroyable.Item.ItemDisplayName));
			}
		}
	}
	public class ContainerInteractable : InteractableSceneObject
	{
		public GameObject chestLid;

		public Vector3 lidRotation;

		public float duration = 1f;

		public Action onInitialized;

		public Item Item { get; set; }

		public bool IsOpen { get; private set; }

		public bool IsLocked { get; private set; }

		public int ContainedGold { get; private set; }

		public List<Item> ContainedItems { get; private set; }

		public TrapType TrapType { get; private set; }

		public void Init(bool state, int amountGold, TrapType typeOfTrap, List<Item> innerItems, bool locked)
		{
			IsOpen = state;
			ContainedGold = amountGold;
			ContainedItems = innerItems;
			TrapType = typeOfTrap;
			IsLocked = locked;
			CanInteract = !IsOpen;
			if (!CanInteract)
			{
				MakeUninteractable();
			}
			if (IsOpen && chestLid != null)
			{
				chestLid.transform.localRotation = Quaternion.Euler(lidRotation);
			}
			if (Item != null)
			{
				base.InteractableName = Item.ItemDisplayName;
			}
			else
			{
				UnityEngine.Debug.LogError("ContainerInteractable: Item was null when Init called");
			}
			onInitialized?.Invoke();
		}

		protected void MakeUninteractable()
		{
			CanInteract = false;
			base.gameObject.layer = 0;
			if (TryGetComponent<Collider>(out var component))
			{
				UnityEngine.Object.Destroy(component);
			}
		}

		public override void Interact(Character interactor = null)
		{
			if (IsOpen)
			{
				return;
			}
			if (IsLocked)
			{
				bool flag = false;
				foreach (Item item in Player.PlayerChar.inventory)
				{
					if (item.itemType == ItemType.ChestKey)
					{
						flag = true;
						Player.PlayerChar.RemoveItemFromInventory(item, RemoveItemReason.Consumed);
						break;
					}
				}
				if (!flag)
				{
					ThatHurt.PopText(base.transform.position, I2Loca.Get("Error_NoKeys"), 1f, ThatHurt.ThatHurtColor.Damage, 0f);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Fail, randomizePitch: true);
					return;
				}
				ThatHurt.PopText(base.transform.position, I2Loca.Get("KeyUsed"), 1f, ThatHurt.ThatHurtColor.White, 0f);
				IsLocked = false;
			}
			if (TrapType != 0)
			{
				GameObject gameObject = null;
				switch (TrapType)
				{
				case TrapType.TrapPoison:
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("PoisonCrate");
					foreach (Character item2 in Fate.FindCharactersInArea(base.transform.position, 3f))
					{
						if (item2.Alive() && item2.GetAlignment() != Alignment.Neutral && !item2.Blocked())
						{
							EffectData effect = new EffectData(EffectType.HPRecharge, positive: false, ActivationType.Usage, 20, -45, 0f)
							{
								applicationMessage = "EffectMsg_Poisoned",
								name = "POISON",
								damageType = DamageType.Poison
							};
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								item2.AddEffect(effect, 1, (item2.GetAlignment() == Alignment.Evil) ? Player.PlayerChar : null);
							}
							else if (item2.MyVitals != null)
							{
								item2.MyVitals.Missed();
							}
						}
					}
					break;
				case TrapType.TrapSword:
					if (LevelGenerator.currentInstance != null)
					{
						MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData a) => a.displayName == "Monster_CursedSword");
						LevelGenerator.currentInstance.SpawnMonster(monsterData, LevelGenerator.currentInstance.RandomOpenPosition(base.transform.position, 0.5f), null, -1, allowRankUp: true);
					}
					break;
				}
				if (gameObject != null)
				{
					UnityEngine.Object.Instantiate(gameObject, base.transform);
				}
				ThatHurt.PopText(base.transform.position, I2Loca.Get("Trapped"), 1f, ThatHurt.ThatHurtColor.Damage, 0f);
			}
			IsOpen = true;
			StartCoroutine(RotateToTarget());
			MakeUninteractable();
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ChestOpen, randomizePitch: true);
			StatsManager.IncrementStat(Stat.ChestsOpened);
			if (ContainedGold > 0)
			{
				int num = (int)((float)ContainedGold * (Player.PlayerChar.EffectValue(EffectType.PercentGoldDrop) / 100f));
				ActiveLevel.SpawnGoldPile(LevelGenerator.currentInstance.RandomOpenPosition(base.transform.position, 0.5f, 2f), ContainedGold + num);
			}
			if (ContainedItems == null)
			{
				List<Item> list2 = (ContainedItems = new List<Item>());
			}
			ActiveLevel.ApplyMagicFindToInventory(ContainedItems, applyToEquippedItems: true);
			foreach (Item containedItem in ContainedItems)
			{
				if (containedItem.GetItemPrefab() == null)
				{
					UnityEngine.Debug.LogWarning("Missing prefab for the item " + containedItem.itemName);
				}
				else
				{
					containedItem.Drop(LevelGenerator.currentInstance.RandomOpenPosition(base.transform.position + base.transform.forward, 0.5f, 2f));
				}
			}
		}

		private IEnumerator RotateToTarget()
		{
			if (!(chestLid == null))
			{
				Quaternion startRotation = chestLid.transform.localRotation;
				Quaternion targetRotation = Quaternion.Euler(lidRotation);
				float elipsedTime = 0f;
				while (elipsedTime < duration)
				{
					elipsedTime += Time.deltaTime;
					chestLid.transform.localRotation = Quaternion.Lerp(startRotation, targetRotation, elipsedTime / duration);
					yield return null;
				}
				chestLid.transform.localRotation = targetRotation;
			}
		}
	}
