	public class EnterDungeon : InteractableSceneObject
	{
		public RealmData.RealmId dungeonRealmOverride = RealmData.RealmId.ANY;

		public PortalRequirement requirement;

		private void Start()
		{
			if (dungeonRealmOverride != RealmData.RealmId.ANY)
			{
				RealmData.RealmId realmId = dungeonRealmOverride;
				bool flag = realmId == RealmData.RealmId.Grove || realmId == RealmData.RealmId.Druantia || realmId == RealmData.RealmId.Typhon || realmId == RealmData.RealmId.Ekbatan || realmId == RealmData.RealmId.TempleOfFate || realmId == RealmData.RealmId.Prometheus;
				base.InteractableName = (flag ? I2Loca.GetFormat("Dungeon_Generic", Fate.GetRealmName(dungeonRealmOverride, preferShortName: false)) : Fate.GetRealmName(dungeonRealmOverride, preferShortName: false));
			}
			else
			{
				base.InteractableName = SingletonBehaviour<Town>.Instance.DungeonName;
			}
			InteractableTooltipCanvas componentInChildren = GetComponentInChildren<InteractableTooltipCanvas>(includeInactive: true);
			if (componentInChildren != null)
			{
				componentInChildren.SetText(base.InteractableName);
			}
		}

		public override void Interact(Character interactor = null)
		{
			if (requirement == PortalRequirement.RealmQuest && !SingletonBehaviour<QuestManager>.Instance.CanAccessRealm((dungeonRealmOverride != RealmData.RealmId.ANY) ? dungeonRealmOverride : SingletonBehaviour<PlayerStatus>.Instance.TownRealm))
			{
				SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("EnterDungeon_NoQuest", null);
				return;
			}
			SingletonBehaviour<PromptUI>.Instance.ShowPrompt("Prompt_EnterDungeon", delegate(bool positive)
			{
				if (positive)
				{
					Player.latestStairsUsedWasDown = true;
					Player.isEnteringDungeonFromTownDoor = true;
					if (dungeonRealmOverride != RealmData.RealmId.ANY)
					{
						SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm = dungeonRealmOverride;
					}
					else
					{
						SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm = SingletonBehaviour<PlayerStatus>.Instance.TownRealm;
					}
					SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm).SetLastVisitedDungeonDepth(1);
					SceneLoad.LoadAsync(Scene.Dungeon, save: true);
				}
			});
		}
	}
