	public class EnterPortal : InteractableSceneObject
	{
		public enum PortalType
		{
			Dungeon,
			Static
		}

		public PortalType portalType;

		public PortalRequirement portalRequirement;

		public RealmData.RealmId destinationRealm = RealmData.RealmId.ANY;

		public int destinationSpawnPointIndex;

		public int overrideInteractRange = -1;

		public Action onDestinationSet;

		public int LevelDepth { get; private set; } = -1;


		private void Awake()
		{
			if (portalType == PortalType.Dungeon)
			{
				if (SingletonBehaviour<Town>.InstanceExists())
				{
					base.InteractableName = "Enter Portal";
				}
				else if (LevelGenerator.currentInstance != null)
				{
					base.InteractableName = I2Loca.Get("Prompt_ReturnToTown");
				}
				else
				{
					base.InteractableName = "Enter Portal?";
				}
			}
			else
			{
				base.InteractableName = I2Loca.GetFormat("Prompt_GoTo", Fate.GetRealmName(destinationRealm, preferShortName: false));
			}
			if (overrideInteractRange != -1)
			{
				base.InteractRange = overrideInteractRange;
			}
		}

		public void SetDestination(RealmData.RealmId dungeonRealm)
		{
			destinationRealm = dungeonRealm;
			if (SingletonBehaviour<Town>.InstanceExists() && SingletonBehaviour<PlayerStatus>.InstanceExists())
			{
				RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.TownRealm);
				if (realmSave.portalSave != null && realmSave.portalSave.portalSaves != null)
				{
					PortalSaveData portalSaveData = realmSave.portalSave.portalSaves.Find((PortalSaveData s) => s.dungeonRealm == destinationRealm);
					if (portalSaveData == null)
					{
						UnityEngine.Debug.LogError("Tried to set destination of EnterPortal, but did not find relevant save. Deactivating portal game object.");
						base.gameObject.SetActive(value: false);
						return;
					}
					base.InteractableName = I2Loca.GetFormat("Prompt_ReturnToDungeon", portalSaveData.levelDepth);
					LevelDepth = portalSaveData.levelDepth;
				}
			}
			if (portalType == PortalType.Dungeon && SingletonBehaviour<Town>.InstanceExists())
			{
				base.InteractableName = I2Loca.GetFormat("Prompt_ReturnToDungeon", LevelDepth);
			}
			onDestinationSet?.Invoke();
		}

		public override void Interact(Character interactor = null)
		{
			Fate.SetPause(paused: true);
			SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(base.InteractableName, delegate(bool positive)
			{
				if (positive)
				{
					if (interactor.IsPlayer())
					{
						interactor.SetInvincible();
					}
					if (portalType == PortalType.Dungeon)
					{
						RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.TownRealm);
						PortalSaveData portalSaveData = realmSave.portalSave?.portalSaves?.Find((PortalSaveData s) => s.dungeonRealm == destinationRealm);
						Town.SpawnPointIndex = 0;
						SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_portal);
						SingletonBehaviour<AudioManager>.Instance.StopMusic();
						if (portalSaveData != null && portalSaveData.levelDepth <= 0)
						{
							realmSave.portalSave.portalSaves.Remove(portalSaveData);
							UnityEngine.Debug.LogError($"Portal data has an invalid level depth ({portalSaveData.levelDepth}), this should not happen");
						}
						else if (SingletonBehaviour<Town>.InstanceExists() && portalSaveData != null && portalSaveData.levelDepth > 0)
						{
							RealmSave realmSave2 = SaveData.CurrentSaveData.GetRealmSave(portalSaveData.dungeonRealm);
							DungeonSaveData dungeonSave = realmSave2.GetDungeonSave(portalSaveData.levelDepth);
							if (dungeonSave != null)
							{
								dungeonSave.portalPosition = portalSaveData.dungeonPosition;
							}
							else
							{
								UnityEngine.Debug.LogWarning($"Could not find dungeon floor save data to set portal position for dungeon realm {portalSaveData.dungeonRealm}, floor {portalSaveData.levelDepth}");
							}
							SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm = portalSaveData.dungeonRealm;
							realmSave2.SetLastVisitedDungeonDepth(portalSaveData.levelDepth);
							realmSave.portalSave.portalSaves.Remove(portalSaveData);
							SingletonBehaviour<PortalManager>.Instance.IsUsingTownPortal = true;
							SceneLoad.LoadAsync(Scene.Dungeon, save: true);
						}
						else if (LevelGenerator.currentInstance != null)
						{
							SingletonBehaviour<AudioManager>.Instance.StopMusic(AudioData.AudioClipName.DungeonMusic);
							LevelGenerator.currentInstance.UpdateSaveData(goesDown: false);
							Town.UpdateSpawnIndex(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, Town.EntryMethod.TownPortal);
							StatsManager.IncrementStat(Stat.PortalsUsed);
							if (Player.PlayerChar.hp <= (float)Player.PlayerChar.MaxHP() * 0.1f)
							{
								StatsManager.SetStat(Stat.HealthLostOnTP, 100);
							}
							SceneLoad.LoadAsync(SceneLoad.GetTownScene(SingletonBehaviour<PlayerStatus>.Instance.TownRealm), save: true);
							base.enabled = false;
						}
					}
					else
					{
						bool flag = true;
						if (portalRequirement == PortalRequirement.RealmQuest)
						{
							flag = SingletonBehaviour<QuestManager>.Instance.CanAccessRealm(destinationRealm);
						}
						if (!flag)
						{
							SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("Portal_RealmQuestBlocked", delegate
							{
								Fate.SetPause(paused: false);
							});
						}
						else
						{
							Town.SpawnPointIndex = destinationSpawnPointIndex;
							SceneLoad.LoadAsync(SceneLoad.GetTownScene(destinationRealm), save: true);
						}
					}
				}
				else
				{
					Fate.SetPause(paused: false);
				}
			}, twoButtons: true);
		}
	}
	public class FateStatueInteractable : InteractableSceneObject
