			highlight.SetActive(value: false);
			used = true;
			CanInteract = false;
		}
	}
	public class FishingSpotInteractable : InteractableSceneObject
	{
		private Randomizer townFishingRandomizer;

		private bool pullFish;

		private bool caugthFish;

		private bool fishBite;

		private bool isFirstCast;

		private float timeSinceBite;

		private float lastCueTime;

		private float cooldown = 2f;

		private Coroutine fishingRoutine;

		private RuntimeDenial denial;

		public Transform lookAtObj;

		private float fishingRange;

		private float biteSpeed = 1f;

		private const float pullAnimSpeed = 1.2f;

		private const float pullWaitMultiplier = 5f / 6f;

		private void Start()
		{
			if (SingletonBehaviour<Town>.InstanceExists())
			{
				switch (SingletonBehaviour<Town>.Instance.RealmId)
				{
				case RealmData.RealmId.Grove:
					fishingRange = 2.5f;
					break;
				case RealmData.RealmId.Druantia:
					fishingRange = 3f;
					break;
				case RealmData.RealmId.Typhon:
					fishingRange = 4f;
					break;
				case RealmData.RealmId.Ekbatan:
					fishingRange = 3f;
					break;
				default:
					fishingRange = 2.5f;
					break;
				}
			}
			else
			{
				fishingRange = 4f;
				LevelGenerator currentInstance = LevelGenerator.currentInstance;
				currentInstance.finishedCreation = (Action)Delegate.Combine(currentInstance.finishedCreation, new Action(PerformDungeonReachableCheck));
			}
			base.InteractRange = fishingRange;
			base.InteractableName = I2Loca.Get("FishingInteractable");
		}

		private void PerformDungeonReachableCheck()
		{
			LevelGenerator currentInstance = LevelGenerator.currentInstance;
			currentInstance.finishedCreation = (Action)Delegate.Remove(currentInstance.finishedCreation, new Action(PerformDungeonReachableCheck));
			if (NavMesh.SamplePosition(base.transform.position, out var hit, 10f, -1))
			{
				float magnitude = (base.transform.position - hit.position).magnitude;
				Vector3 normalized = (hit.position.WithY(0f) - base.transform.position.WithY(0f)).normalized;
				bool flag = magnitude > fishingRange;
				bool flag2 = magnitude < fishingRange - 1f;
				if (flag || flag2)
				{
					UnityEngine.Debug.Log(string.Format("Adjusting position of fishing spot {0}. {1}", this, flag ? "It needs to be closer to the edge" : "It needs to be further away from the edge"), this);
					base.transform.position = hit.position.WithY(base.transform.position.y) - normalized * (fishingRange - 1f);
				}
			}
			else
			{
				UnityEngine.Debug.LogWarning("FishingSpotInteractable: Could not adjust position and determine optimal range to fish from", this);
			}
		}

		public override void Interact(Character other)
		{
			if (!Player.PlayerChar.HasItems("Item_FishingPole", 1) || Player.PlayerChar.Fishing())
			{
				if (!Player.PlayerChar.Fishing() && Time.realtimeSinceStartup > lastCueTime + cooldown)
				{
					lastCueTime = Time.realtimeSinceStartup;
					ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.Get("Prompt_FishingPole"), 1.5f, 4f, ThatHurt.ThatHurtColor.White, 0.2f);
				}
				return;
			}
			SimpleSingletonBehaviour<PlayerUI>.Instance.ShowFishingUI();
			Player playerChar = Player.PlayerChar;
			playerChar.SetAIState(AIState.Fish);
			playerChar.SetIsFishing(state: true);
			playerChar.myTransform.LookAt(base.transform.position.WithY(lookAtObj.position.y));
			if (playerChar.TryGetComponent<ProdigyAgent>(out var component))
			{
				if (denial != null)
				{
					component.RemoveDenialById(denial.Id);
				}
				denial = new RuntimeDenial(move: true, rotate: true, fire: true, ability: true, ik: false);
				component.AddDenial(denial);
			}
			isFirstCast = true;
			SimpleSingletonBehaviour<PlayerUI>.Instance.stopFishingButton.onClick.AddListener(StopFishing);
			if (fishingRoutine != null)
			{
				StopCoroutine(fishingRoutine);
			}
			fishingRoutine = StartCoroutine(FishingUpdate(other));
		}

		private IEnumerator FishingUpdate(Character owner)
		{
			while (true)
			{
				if (isFirstCast)
				{
					yield return new WaitForSeconds(2f);
					SimpleSingletonBehaviour<PlayerUI>.Instance.setHookButton.onClick.AddListener(SetHook);
					isFirstCast = false;
				}
				caugthFish = false;
				if (!pullFish)
				{
					if (!fishBite)
					{
						if (UnityEngine.Random.Range(0, 20000) < 32)
						{
							timeSinceBite = 0f;
							biteSpeed = UnityEngine.Random.Range(0.2f, 0.5f);
							fishBite = true;
							Player.PlayerChar.SetFishBiting(state: true);
						}
					}
					else
					{
						timeSinceBite += Time.deltaTime * biteSpeed;
						if (1f - timeSinceBite < 0f)
						{
							fishBite = false;
							Player.PlayerChar.SetFishBiting(state: false);
						}
					}
				}
				if (pullFish && fishBite)
				{
					float num = 1f - timeSinceBite;
					if (num < 0f)
					{
						num = 0f;
					}
					if (num > 0f && num > UnityEngine.Random.Range(0f, 0.4f))
					{
						caugthFish = true;
						Player.PlayerChar.IsFishCaught(isCaught: true);
					}
					else
					{
						ThatHurt.PopText(base.transform.position, I2Loca.Get("Failed"), 1f, ThatHurt.ThatHurtColor.White, 0f);
						Player.PlayerChar.IsFishCaught(isCaught: false);
					}
					if (caugthFish)
					{
						GiveAward(owner);
						caugthFish = false;
						fishBite = false;
						StatsManager.IncrementStat(Stat.FishCaught);
					}
					yield return new WaitForSeconds(4f);
					pullFish = false;
				}
				yield return new WaitForFixedUpdate();
			}
		}

		private IEnumerator PullingFish()
		{
			SimpleSingletonBehaviour<PlayerUI>.Instance.HideFishingUI();
			pullFish = true;
			Player.PlayerChar.SetFishBiting(state: false);
			Player.PlayerChar.SetIsPullingFish(state: true);
			yield return new WaitForSeconds(1.9166666f);
			Player.PlayerChar.HoldFishingLine(isHoldingLine: true);
			yield return new WaitForSeconds(5f / 6f);
			Player.PlayerChar.HoldFishingLine(isHoldingLine: false);
			Player.PlayerChar.SetIsPullingFish(state: false);
			yield return new WaitForSeconds(0.75f);
			Player.PlayerChar.IsFishCaught(isCaught: false);
			pullFish = false;
			CancelFishing();
		}

		private IEnumerator PullingFishPole()
		{
			SimpleSingletonBehaviour<PlayerUI>.Instance.HideFishingUI();
			fishBite = false;
			pullFish = true;
			Player.PlayerChar.SetFishBiting(state: false);
			Player.PlayerChar.SetIsPullingFish(state: true);
			yield return new WaitForSeconds(1.9166666f);
			Player.PlayerChar.HoldFishingLine(isHoldingLine: true);
			yield return new WaitForSeconds(5f / 6f);
			Player.PlayerChar.HoldFishingLine(isHoldingLine: false);
			Player.PlayerChar.IsFishCaught(isCaught: false);
			Player.PlayerChar.SetIsPullingFish(state: false);
			yield return new WaitForSeconds(0.75f);
			pullFish = false;
			CancelFishing();
		}

		private void SetHook()
		{
			if (!pullFish)
			{
				StartCoroutine(PullingFish());
			}
		}

		private void StopFishing()
		{
			if (!pullFish)
			{
				StartCoroutine(PullingFishPole());
			}
		}

		private void CancelFishing()
		{
			if (denial != null && Player.PlayerChar.TryGetComponent<ProdigyAgent>(out var component))
			{
				component.RemoveDenialById(denial.Id);
				denial = null;
			}
			pullFish = false;
			caugthFish = false;
			Player.PlayerChar.SetAIState(AIState.Inactive);
			Player.PlayerChar.SetIsFishing(state: false);
			Player.PlayerChar.SetFishBiting(state: false);
			Player.PlayerChar.SetIsPullingFish(state: false);
			if (fishingRoutine != null)
			{
				StopCoroutine(fishingRoutine);
			}
			fishingRoutine = null;
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.setHookButton.onClick.RemoveListener(SetHook);
				SimpleSingletonBehaviour<PlayerUI>.Instance.stopFishingButton.onClick.RemoveListener(StopFishing);
			}
			InputBlocker.MuteForFrames(6);
		}

		private void OnDestroy()
		{
			if (Player.PlayerChar != null && Player.PlayerChar.Fishing())
			{
				CancelFishing();
			}
			if (LevelGenerator.currentInstance != null)
			{
				LevelGenerator currentInstance = LevelGenerator.currentInstance;
				currentInstance.finishedCreation = (Action)Delegate.Remove(currentInstance.finishedCreation, new Action(PerformDungeonReachableCheck));
			}
		}

		private void GiveAward(Character target)
		{
			string text = null;
			ItemData itemData;
			if (LevelGenerator.currentInstance != null)
			{
				itemData = LevelGenerator.currentInstance.GetFishingItemDataRandom();
			}
			else
			{
				if (townFishingRandomizer == null)
				{
					GenerateRandomizerTown();
				}
				itemData = GetTownFishingItemDataRandom();
			}
			if (itemData != null)
			{
				text = itemData.displayName;
				Item item = new Item(itemData);
				ItemCategory category = item.category;
				if (category == ItemCategory.Weapon || category == ItemCategory.Armor || category == ItemCategory.Jewelry)
				{
					if (UnityEngine.Random.Range(0, 100) < 20)
					{
						item.TryBestowPowers(ActiveLevel.GetCurrentDungeonDepth(), AllowCurse: true, 1);
					}
					if (UnityEngine.Random.Range(0, 100) < 10)
					{
						item.BestowSockets(AllowUnique: false);
					}
				}
				if (!target.AddItemToInventory(item, AddItemReason.Loot))
				{
					item.Drop(target.myTransform.position);
				}
				ThatHurt.PopText(base.transform.position, I2Loca.GetFormatReplaceTags("FishingGreat", I2Loca.Get(itemData.displayName)), 1f, ThatHurt.ThatHurtColor.White, 0f);
			}
			if (!string.IsNullOrEmpty(text) && text == "Item_PerontoCheeseheadoftheEmeraldBay")
			{
				StatsManager.IncrementStat(Stat.CheeseHeadCaught, 1, requestSave: true);
			}
		}

		private ItemData GetTownFishingItemDataRandom()
		{
			int random = townFishingRandomizer.GetRandom();
			if (random == -1)
			{
				UnityEngine.Debug.LogError("Item Data Not Found!\nFound no fishing items to give. Either item data manifest is empty or something is wrong.");
				return null;
			}
			return SingletonBehaviour<FateDB>.Instance.AllItems[random];
		}

		private void GenerateRandomizerTown()
		{
			Fate.DifficultySetup difficultySetup = Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty];
			int currentDungeonDepth = ActiveLevel.GetCurrentDungeonDepth();
			int num = Mathf.CeilToInt((float)currentDungeonDepth * difficultySetup.itemMultiplier);
			_ = 3;
			bool itemRepeatEnabled = false;
			if (currentDungeonDepth >= 10000)
			{
				itemRepeatEnabled = true;
			}
			else if (num >= Mathf.CeilToInt(100f * difficultySetup.itemMultiplier))
			{
				itemRepeatEnabled = true;
			}
			townFishingRandomizer = ActiveLevel.GenerateFishingRandomizer(num, itemRepeatEnabled);
		}
	}
	public class FountainInteractable : InteractableSceneObject
	{
		[SerializeField]
		private string fountainName;

		[SerializeField]
		private EffectData[] fountainEffects;

		[SerializeField]
		private GameObject[] toggledOnInteract;

		private AudioSource audioSource;

		public int fountainIndex = -1;

		public bool IsUsed { get; private set; }

		private void Awake()
		{
			base.InteractRange = 1f;
			base.InteractableName = I2Loca.Get(fountainName);
			audioSource = GetComponent<AudioSource>();
			audioSource.PlayDelayed(1f);
		}

		public void SetAsUsed()
		{
			for (int i = 0; i < toggledOnInteract.Length; i++)
			{
				toggledOnInteract[i].SetActive(value: false);
			}
			base.gameObject.layer = 0;
			if (TryGetComponent<Collider>(out var component))
			{
				component.enabled = false;
			}
			IsUsed = true;
			CanInteract = false;
			audioSource.Stop();
		}

		public override void Interact(Character interactor = null)
		{
			if (!CanInteract)
			{
				return;
			}
			SetAsUsed();
			if (LevelGenerator.currentInstance != null)
			{
				LevelGenerator.currentInstance.OnUsedFountain(fountainIndex);
			}
			audioSource.Stop();
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.PotionUse, randomizePitch: true);
			bool flag = false;
			bool flag2 = false;
			bool flag3 = false;
			bool flag4 = false;
			int levelDepth = LevelGenerator.currentInstance.GetLevelDepth();
			EffectData[] array = fountainEffects;
			foreach (EffectData effectData in array)
			{
				TriggerEffect(interactor, effectData, levelDepth);
				switch (effectData.buffType)
				{
				case EffectType.HP:
				case EffectType.PercentMaxHP:
				case EffectType.HPRecharge:
				{
					flag = true;
					flag2 = effectData.value >= 100;
					GameObject particlePrefab2 = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("HealthRefresh");
					if (particlePrefab2 != null)
					{
						UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab2, base.transform.position, Quaternion.identity), 3f);
					}
					break;
				}
				case EffectType.Mana:
				case EffectType.PercentMaxMana:
				case EffectType.ManaRecharge:
				{
					flag3 = true;
					GameObject particlePrefab3 = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("ManaRefresh");
					if (particlePrefab3 != null)
					{
						UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab3, base.transform.position, Quaternion.identity), 3f);
					}
					break;
				}
				case EffectType.Stamina:
				case EffectType.PercentStamina:
				case EffectType.StaminaRecharge:
				{
					flag4 = true;
					GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("StaminaRefresh");
					if (particlePrefab != null)
					{
						UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab, base.transform.position, Quaternion.identity), 3f);
					}
					break;
				}
				default:
					UnityEngine.Debug.Log(string.Format("{0}: Narrator sound is missing for buff type {1}", "FountainInteractable", effectData.buffType));
					break;
				}
			}
			int num = 0;
			if (flag)
			{
				num++;
			}
			if (flag3)
			{
				num++;
			}
			if (flag4)
			{
				num++;
			}
			NarratorLines lines;
			if (flag2 || flag3 || num > 1)
			{
				lines = NarratorLines.Narrator_refreshed;
			}
			else if (flag)
			{
				lines = NarratorLines.Narrator_healthy;
			}
			else
			{
				if (!flag4)
				{
					return;
				}
				lines = NarratorLines.Narrator_fortified;
			}
			SingletonBehaviour<Narrator>.Instance.PlayYourLine(lines);
		}

		private void TriggerEffect(Character interactor, EffectData effect, int effectLevel)
		{
			switch (effect.target)
			{
			case ItemTarget.User:
			case ItemTarget.Character:
				interactor.AddEffect(effect, effectLevel, null);
				break;
			case ItemTarget.UserAndPetsAndParty:
			{
				interactor.AddEffect(effect, effectLevel, null);
				int petCount = interactor.GetPetCount();
				for (int i = 0; i < petCount; i++)
				{
					Character pet = interactor.GetPet(i);
					if (pet != null)
					{
						pet.AddEffect(effect, effectLevel, null);
					}
				}
				int partyMemberCount = interactor.GetPartyMemberCount();
				for (int j = 0; j < partyMemberCount; j++)
				{
					Character partyMember = interactor.GetPartyMember(j);
					if (partyMember != null)
					{
						partyMember.AddEffect(effect, effectLevel, null);
					}
				}
				break;
			}
			default:
				UnityEngine.Debug.LogWarning($"Tried applying effect with unimplemented target {effect.target}");
				break;
			}
		}
	}
