		public Action onInitialized;

		public int GoldAmount { get; private set; }

		public bool IsEmpty => isEmpty;

		private void Start()
		{
			base.gameObject.layer = LayerMask.NameToLayer("PlayerTrigger");
		}

		public void Init(int totalGold)
		{
			GoldAmount = totalGold;
			isEmpty = false;
			onInitialized?.Invoke();
		}

		private void OnTriggerEnter(Collider other)
		{
			if (!isEmpty && !(other.GetComponent<Player>() == null))
			{
				SingletonBehaviour<PlayerStatus>.Instance.AddGold((uint)GoldAmount);
				StatsManager.IncrementStat(Stat.GoldLooted, GoldAmount);
				string text = ((GoldAmount > 0) ? "+" : "");
				ThatHurt.PopText(base.transform.position, text + I2Loca.GetFormat("GoldPickup", GoldAmount), 1f, ThatHurt.ThatHurtColor.Gold, 0f);
				isEmpty = true;
				UnityEngine.Object.Destroy(base.gameObject);
			}
		}
	}
