	public abstract class InteractableTooltipBase : MonoBehaviour
	{
		[SerializeField]
		protected InteractableTooltipCanvas tooltipCanvas;

		private bool isHovered;

		protected InteractableSceneObject interactable;

		protected virtual bool UpdateTooltipOnStart => true;

		protected virtual bool HandleMouseHover => true;

		protected virtual void Awake()
		{
			tooltipCanvas.gameObject.SetActive(value: false);
			interactable = GetComponent<InteractableSceneObject>();
			tooltipCanvas.SetIsHovered(isHovered: false);
		}

		protected virtual void Start()
		{
			if (UpdateTooltipOnStart)
			{
				UpdateTooltip();
			}
		}

		private void LateUpdate()
		{
			if (isHovered || PlayerUI.ShouldShowItemTooltips)
			{
				ShowTooltip();
			}
			else
			{
				HideTooltip();
			}
		}

		protected virtual void UpdateTooltip()
		{
			tooltipCanvas.SetText(interactable.InteractableName);
		}

		protected virtual void PermanentDisable()
		{
			UnityEngine.Object.Destroy(tooltipCanvas.gameObject);
			UnityEngine.Object.Destroy(this);
		}

		protected virtual void ShowTooltip()
		{
			if (interactable.CanInteract)
			{
				tooltipCanvas.gameObject.SetActive(value: true);
			}
			else
			{
				PermanentDisable();
			}
		}

		protected virtual void HideTooltip()
		{
			tooltipCanvas.gameObject.SetActive(value: false);
		}

		private void OnMouseEnter()
		{
			if (HandleMouseHover)
			{
				SetHovered(isHovered: true);
			}
		}

		private void OnMouseExit()
		{
			if (HandleMouseHover)
			{
				SetHovered(isHovered: false);
			}
		}

		public void SetHovered(bool isHovered)
		{
			this.isHovered = isHovered;
			tooltipCanvas.SetIsHovered(isHovered);
		}
	}
	public class InteractableTooltipCanvas : MonoBehaviour
	{
		[SerializeField]
		private Image background;

		[SerializeField]
		private Color regularBgColor;

		[SerializeField]
		private Color hoveredBgColor;

		[SerializeField]
		protected TextMeshProUGUI text;

		private void Start()
		{
			Vector3 localScale = base.transform.localScale;
			Vector3 lossyScale = base.transform.parent.lossyScale;
			base.transform.localScale = new Vector3(localScale.x / lossyScale.x, localScale.y / lossyScale.y, localScale.z / lossyScale.z);
		}

		public void SetText(string textString)
		{
			text.text = textString;
		}

		public void SetIsHovered(bool isHovered)
		{
			background.color = (isHovered ? hoveredBgColor : regularBgColor);
		}
	}
