		public AudioData.AudioClipName ActiveStepSound
		{
			get
			{
				if (!(activeTemplate == null))
				{
					return activeTemplate.StepSoundData;
				}
				return AudioData.AudioClipName.BasicStep;
			}
		}

		public bool IsCleaning
		{
			get
			{
				if (!isCleaningUpNoiseMeshes)
				{
					return isRemovingObjects;
				}
				return true;
			}
		}

		public Transform GetActiveContainersParent => activeContainersParent.transform;

		public static int WallLayerMask { get; private set; }

		public static string CurrentDungeonName
		{
			get
			{
				if (!SingletonBehaviour<PlayerStatus>.InstanceExists())
				{
					return "";
				}
				if (SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm != SingletonBehaviour<PlayerStatus>.Instance.TownRealm)
				{
					return Fate.GetRealmName(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, preferShortName: false);
				}
				return I2Loca.GetFormat("Dungeon_Generic", Fate.GetRealmName(SingletonBehaviour<PlayerStatus>.Instance.TownRealm, preferShortName: true));
			}
		}

		private int GetAdjustedItemDepth => Mathf.CeilToInt((float)levelDepth * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier);

		public float GetCleanProgress()
		{
			return cleanupNoiseMeshesProgress * 0.5f + removeObjectsProgress * 0.5f;
		}

		public void FillListWithActiveCharacters(ref List<GameObject> list)
		{
			if (activeCharacters != null)
			{
				list.AddRange(activeCharacters);
			}
		}

		private void Start()
		{
			finishedCreation = (Action)Delegate.Combine(finishedCreation, new Action(OnFinishCreation));
			monstersDataManifest = new List<MonsterData>();
			monstersDataManifest.AddRange(SingletonBehaviour<FateDB>.Instance.allMonsters);
			itemDataManifest = new List<ItemData>();
			deepestLevelDepth = StatsManager.GetStat(Stat.DeepestDepth);
			musicClips = new List<AudioClip>();
			audioSource = GetComponent<AudioSource>();
			SingletonBehaviour<AudioManager>.Instance.StopAllSoundFx();
			itemDataManifest.AddRange(SingletonBehaviour<FateDB>.Instance.AllItems);
			if (TryGetComponent<LineRenderer>(out var component))
			{
				component.enabled = false;
			}
			if (generateAtStart)
			{
				goingDeeper = true;
				Create(0f, 0f, SaveData.CurrentSaveData.GetLatestDepth(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm), (int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, goingDeeper, !Player.isEnteringDungeonFromTownDoor && !SingletonBehaviour<PortalManager>.Instance.IsUsingTownPortal);
			}
			if (!editorMode)
			{
				loadProgressFunc = delegate
				{
					float num = 0f;
					num = ((!IsCleaning) ? (num + 0.5f) : (num + GetCleanProgress() / 2f));
					num += progress / 2f;
					return Mathf.Clamp01(num);
				};
				SingletonBehaviour<LoadingScreenUI>.Instance.ShowLoading(fadeIn: false, loadProgressFunc);
			}
		}

		private void OnFinishCreation()
		{
			Player.isEnteringDungeonFromTownDoor = false;
			if (activeDungeon != null && !editorMode)
			{
				SetPlayerPositionInLevel(Player.latestStairsUsedWasDown);
			}
			Fate.SetPause(paused: false);
			SingletonBehaviour<LoadingScreenUI>.Instance.HideLoading(fadeOut: true);
			hasCleanedForQuit = false;
		}

		private void Awake()
		{
			currentInstance = this;
			WallLayerMask = LayerMask.GetMask("Default");
			Application.wantsToQuit += WantsToQuit;
			alwaysNewLevels = false;
			containersAreAllTraps = false;
			generateAtStart = true;
			generateCeiling = true;
			editorMode = false;
			failsafeGeneration = true;
			templateOverride = null;
		}

		private bool WantsToQuit()
		{
			if (!IsCleaning)
			{
				RemoveObjectsOverTime(delegate
				{
					hasCleanedForQuit = true;
					Application.Quit();
				});
			}
			return hasCleanedForQuit;
		}

		private void OnDestroy()
		{
			SaveData.RemovePreSaveMainThreadTask(PreSaveTask);
			currentInstance = null;
			finishedCreation = (Action)Delegate.Remove(finishedCreation, new Action(OnFinishCreation));
			Application.wantsToQuit -= WantsToQuit;
		}

		public void Create(float newWorldLocationX, float newWorldLocationZ, int newLevelDepth, int newLevelRealm, bool goesDown, bool useSavedPosition, bool ignoreSavedState = false)
		{
			if (SingletonBehaviour<FateDB>.Instance.allTemplates == null)
			{
				return;
			}
			SaveData.RemovePreSaveMainThreadTask(PreSaveTask);
			SaveData.AddPreSaveMainThreadTask(PreSaveTask);
			if (!SingletonBehaviour<LoadingScreenUI>.Instance.shown)
			{
				SingletonBehaviour<LoadingScreenUI>.Instance.ShowLoading(fadeIn: false);
			}
			if (newLevelDepth < 1)
			{
				newLevelDepth = 1;
			}
			levelDepth = newLevelDepth;
			levelRealm = newLevelRealm;
			usedMagicAnvil = false;
			usedShrineOfLearning = false;
			usedFateStatue = false;
			effectiveLevelDepth = levelDepth;
			if (Player.PlayerChar != null)
			{
				int num = Player.PlayerChar.Level / 3;
				effectiveLevelDepth += num;
			}
			else if (SaveData.CurrentSaveData?.playerSaveData != null)
			{
				int num2 = Fate.GetLevelFromExperience(SaveData.CurrentSaveData.playerSaveData.experience) / 3;
				effectiveLevelDepth += num2;
			}
			if (deepestLevelDepth < levelDepth)
			{
				deepestLevelDepth = levelDepth;
				StatsManager.SetStat(Stat.DeepestDepth, deepestLevelDepth);
			}
			SimpleSingletonBehaviour<PlayerUI>.Instance.SetLocationText(CurrentDungeonName, I2Loca.GetFormat("Level_x", levelDepth));
			UpdateRandomizers();
			playerSpawnLocation = (goesDown ? SpawnLocation.StairsUp : SpawnLocation.StairsDown);
			if (useSavedPosition)
			{
				playerSpawnLocation = SpawnLocation.SavedLocation;
			}
			if (LoadSaveData())
			{
				return;
			}
			if (useSeed)
			{
				currentSeed = seed;
				UnityEngine.Random.InitState(seed);
			}
			else
			{
				System.Random random = new System.Random();
				randomSavedSeed = random.Next();
				currentSeed = randomSavedSeed;
				UnityEngine.Random.InitState(randomSavedSeed);
			}
			if (templateOverride != null)
			{
				activeTemplateIndex = 0;
				activeTemplate = templateOverride;
			}
			if (SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm == RealmData.RealmId.Prometheus && prometheusDungeons != null && prometheusDungeons.Count > 0)
			{
				int dungeonIndex = 0;
				if (levelDepth < 5)
				{
					dungeonIndex = 0;
				}
				else if (levelDepth < 10)
				{
					dungeonIndex = 1;
				}
				else if (levelDepth < 15)
				{
					dungeonIndex = 2;
				}
				else if (levelDepth < 41)
				{
					dungeonIndex = 3;
				}
				else
				{
					dungeonIndex = UnityEngine.Random.Range(0, 4);
				}
				activeTemplateIndex = SingletonBehaviour<FateDB>.Instance.allTemplates.FindIndex((TemplateData t) => (object)t == prometheusDungeons[dungeonIndex]);
				activeTemplate = SingletonBehaviour<FateDB>.Instance.allTemplates[activeTemplateIndex];
				UnityEngine.Debug.Log($"active template index for {activeTemplate} is {activeTemplateIndex}.");
			}
			else
			{
				int i = 0;
				List<TemplateData> list = SingletonBehaviour<FateDB>.Instance.allTemplates.Where((TemplateData t) => t != null && t.realmId == SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
				if (list.Count == 0)
				{
					UnityEngine.Debug.LogWarning("Realm has no valid templates, defaulting: " + SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
					list.Add(SingletonBehaviour<FateDB>.Instance.allTemplates[0]);
				}
				for (; i < maximumTemplates; i++)
				{
					activeTemplate = list.GetRandomEntry();
					if (activeTemplate != null)
					{
						activeTemplateIndex = Array.IndexOf(SingletonBehaviour<FateDB>.Instance.allTemplates, activeTemplate);
						break;
					}
				}
			}
			worldLocationX = newWorldLocationX;
			worldLocationZ = newWorldLocationZ;
			if (activeGameObjectsParent == null)
			{
				activeGameObjectsParent = new GameObject("DungeonObjectsHolder");
			}
			creationSeed = UnityEngine.Random.state;
			UnityEngine.Debug.Log($"Create called with creation seed: {currentSeed}, depth is {levelDepth}, template is {activeTemplate.name}");
			activeDungeon = new MazeCreation(activeTemplate, worldLocationX, worldLocationZ);
			if (combinedObject != null)
			{
				UnityEngine.Object.Destroy(combinedObject);
			}
			CreateFloor();
			CreateWalls();
			CreateProps();
			if (useNoise)
			{
				StartCoroutine(ApplyNoiseToStaticMeshes(delegate
				{
					if (navMeshSurface == null)
					{
						navMeshSurface = (NavMeshSurface)new GameObject().AddComponent(typeof(NavMeshSurface));
					}
					navMeshSurface.BuildNavMesh();
					if (failsafeGeneration)
					{
						NavMeshPath navMeshPath2 = new NavMeshPath();
						bool flag2 = false;
						if (NavMesh.CalculatePath(activeDungeon.GetPlayerSpawnPointUp(), activeDungeon.GetPlayerSpawnPointDown(), 1, navMeshPath2) && navMeshPath2.status == NavMeshPathStatus.PathComplete)
						{
							flag2 = true;
						}
						if (!flag2)
						{
							UnityEngine.Debug.Log("Replacing unsolvable dungeon");
							if (useSeed)
							{
								seed++;
							}
							ReplaceDungeon(newWorldLocationX, newWorldLocationZ, newLevelDepth, newLevelRealm, goesDown, useSavedPosition, ignoreSavedState: false, skipSave: true);
							return;
						}
					}
					FinishCreate();
				}));
			}
			else
			{
				if (navMeshSurface == null)
				{
					navMeshSurface = (NavMeshSurface)new GameObject().AddComponent(typeof(NavMeshSurface));
				}
				navMeshSurface.BuildNavMesh();
				if (failsafeGeneration)
				{
					NavMeshPath navMeshPath = new NavMeshPath();
					bool flag = false;
					if (NavMesh.CalculatePath(activeDungeon.GetPlayerSpawnPointUp(), activeDungeon.GetPlayerSpawnPointDown(), 1, navMeshPath) && navMeshPath.status == NavMeshPathStatus.PathComplete)
					{
						flag = true;
					}
					if (!flag)
					{
						UnityEngine.Debug.Log("Replacing unsolvable dungeon");
						if (useSeed)
						{
							seed++;
						}
						ReplaceDungeon(newWorldLocationX, newWorldLocationZ, newLevelDepth, newLevelRealm, goesDown, useSavedPosition, ignoreSavedState: false, skipSave: true);
						return;
					}
				}
				FinishCreate();
			}
			PlayDungeonMusic();
		}

		private void FinishCreate()
		{
			GenerateRandomMonsters();
			if (activeContainersParent == null)
			{
				activeContainersParent = new GameObject("ContainerObjectsHolder");
			}
			GenerateRandomItems();
			navMeshSurface.BuildNavMesh();
			if (useNoise)
			{
				CombineFloorMeshes();
			}
			StartCoroutine(DoGenerateQuests());
			finishedCreation?.Invoke();
			if (!editorMode)
			{
				SaveData.RequestSave();
			}
		}

		private IEnumerator DoGenerateQuests()
		{
			while (!SingletonBehaviour<PlayerUI>.InstanceExists() || !SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryInitialized || !SingletonBehaviour<QuestManager>.InstanceExists() || !SingletonBehaviour<QuestManager>.Instance.HasLoaded)
			{
				yield return null;
			}
			GenerateQuests();
		}

		private IEnumerator DoValidateQuestsPostLoad()
		{
			while (!SingletonBehaviour<PlayerUI>.InstanceExists() || !SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryInitialized || !SingletonBehaviour<QuestManager>.InstanceExists() || !SingletonBehaviour<QuestManager>.Instance.HasLoaded)
			{
				yield return null;
			}
			ValidateQuestsPostLoad();
		}

		public bool LoadSaveData()
		{
			if (SaveData.CurrentSaveData == null || SaveData.CurrentSaveData.realmSaveData == null)
			{
				return false;
			}
			RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (realmSave.dungeonSave == null)
			{
				return false;
			}
			if (realmSave.dungeonSave.dungeons == null)
			{
				return false;
			}
			DungeonSaveData saveData = realmSave.GetDungeonSave(levelDepth);
			if (saveData == null)
			{
				return false;
			}
			if (activeGameObjectsParent == null)
			{
				activeGameObjectsParent = new GameObject("DungeonObjectsHolder");
			}
			if (activeContainersParent == null)
			{
				activeContainersParent = new GameObject("ContainerObjectsHolder");
			}
			if (activeCharacters == null)
			{
				activeCharacters = new List<GameObject>();
			}
			activeTemplateIndex = saveData.templateIndex;
			if (templateOverride != null)
			{
				activeTemplate = templateOverride;
			}
			else
			{
				activeTemplate = SingletonBehaviour<FateDB>.Instance.allTemplates[activeTemplateIndex];
			}
			worldLocationX = saveData.worldLocationX;
			worldLocationZ = saveData.worldLocationZ;
			if (Player.isComingFromMenu)
			{
				playerSpawnLocation = SpawnLocation.SavedLocation;
			}
			else if (SingletonBehaviour<PortalManager>.Instance.IsUsingTownPortal)
			{
				playerSpawnLocation = SpawnLocation.TownPortalLocation;
			}
			if (SingletonBehaviour<PortalManager>.Instance.IsUsingTownPortal)
			{
				SingletonBehaviour<PortalManager>.Instance.IsUsingTownPortal = false;
			}
			PlayDungeonMusic();
			UnityEngine.Random.state = saveData.savedSeed;
			creationSeed = saveData.savedSeed;
			UnityEngine.Debug.Log($"Loading dungeon level with creation seed: {creationSeed.GetHashCode()}, depth is {levelDepth}, template is {activeTemplate.name}");
			activeDungeon = new MazeCreation(activeTemplate, worldLocationX, worldLocationZ);
			if (combinedObject != null)
			{
				UnityEngine.Object.Destroy(combinedObject);
			}
			CreateFloor();
			CreateWalls();
			usedMagicAnvil = saveData.usedMagicAnvil;
			usedShrineOfLearning = saveData.usedShrineOfLearning;
			usedFateStatue = saveData.usedFateStatue;
			usedFountainIndexes = new List<int>(saveData.usedFountainIndexes);
			CreateProps();
			if (useNoise)
			{
				StartCoroutine(ApplyNoiseToStaticMeshes(delegate
				{
					if (navMeshSurface == null)
					{
						navMeshSurface = (NavMeshSurface)new GameObject().AddComponent(typeof(NavMeshSurface));
					}
					navMeshSurface.BuildNavMesh();
					CombineFloorMeshes();
					FinishLoadSave(saveData);
				}));
			}
			else
			{
				if (navMeshSurface == null)
				{
					navMeshSurface = (NavMeshSurface)new GameObject().AddComponent(typeof(NavMeshSurface));
				}
				navMeshSurface.BuildNavMesh();
				FinishLoadSave(saveData);
			}
			return true;
		}

		private void FinishLoadSave(DungeonSaveData saveData)
		{
			bool flag = false;
			for (int i = 0; i < saveData.monsters.Count; i++)
			{
				MonsterData monsterData = FindMonsterDataByName(saveData.monsters[i].key);
				if (monsterData == null)
				{
					GameObject merchantPrefab = SingletonBehaviour<FateDB>.Instance.GetMerchantPrefab(saveData.monsters[i].merchantType, (RealmData.RealmId)levelRealm);
					if (merchantPrefab != null)
					{
						activeCharacters.Add(SpawnMerchant(merchantPrefab, saveData.monsters[i].position));
					}
					continue;
				}
				GameObject gameObject = SpawnEntity(monsterData.modelPrefab, saveData.monsters[i].position, monsterData, allowRankUp: false, fromSave: true);
				activeCharacters.Add(gameObject);
				gameObject.transform.rotation = saveData.monsters[i].rotation;
				if (!gameObject.TryGetComponent<Character>(out var component))
				{
					continue;
				}
				OutfitCharacter(component, saveData.monsters[i].isUnique, saveData.monsters[i].overrideLevel, saveData.monsters[i].rank);
				component.CharacterName = saveData.monsters[i].displayName;
				if (!component.isUnique)
				{
					gameObject.transform.localScale = saveData.monsters[i].scale;
				}
				component.hp = saveData.monsters[i].health;
				foreach (EffectSave effect in saveData.monsters[i].effects)
				{
					component.AddEffect(effect);
				}
				if (saveData.monsters[i].state == AIState.Dying || saveData.monsters[i].state == AIState.Dead)
				{
					(component as Monster).UnRegisterKilled();
					(component as Monster).loadedAsDead = true;
					component.MyVitals.Die();
					Animator component2 = component.GetComponent<Animator>();
					int stateNameHash = Animator.StringToHash("Dead");
					component2.Play(stateNameHash, 0, 10f);
				}
				else
				{
					component.SetAIState(saveData.monsters[i].state);
				}
				if (component.Alive())
				{
					if (saveData.monsters[i].disallowEquipmentDrops)
					{
						component.allowDropEquipment = false;
					}
					ItemSaveData qItem = saveData.monsters[i].questItem;
					if (qItem != null && !string.IsNullOrEmpty(qItem.baseName))
					{
						ItemData itemData = SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData id) => id.displayName == qItem.baseName);
						if (itemData != null)
						{
							Item item = new Item(itemData);
							item.ApplyInstance(qItem);
							component.AddItemToInventory(item, AddItemReason.LoadFromSave, item.slotIndex);
							component.allowDropInventory = true;
							if (item.InEquipmentSlot)
							{
								component.allowDropEquipment = true;
							}
							if (item.IsHeroItem())
							{
								flag = true;
							}
						}
					}
				}
				MonsterSaveData monsterSaveData = saveData.monsters[i];
				if (monsterSaveData.inventory != null)
				{
					foreach (ItemSaveData itemSave2 in monsterSaveData.inventory)
					{
						Item item2 = new Item(SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData id) => id.displayName == itemSave2.baseName));
						item2.ApplyInstance(itemSave2);
						component.AddItemToInventory(item2, AddItemReason.LoadFromSave, item2.slotIndex);
						if (item2.InEquipmentSlot)
						{
							component.AttemptAutoEquip(item2);
						}
					}
					if (monsterSaveData.inventory.Count > 0)
					{
						component.allowDropInventory = true;
					}
				}
				if (component is Ward)
				{
					StartCoroutine(HookupWardToQuest(component as Ward));
				}
			}
			ReattachPetsPostLoad();
			if (flag)
			{
				StartCoroutine(PopStatueTextAfterPlayerSpawn());
			}
			foreach (ContainerSaveData containerSave in saveData.containers)
			{
				ItemData itemData2 = null;
				if (containerSave != null && !string.IsNullOrEmpty(containerSave.containerItemId))
				{
					itemData2 = SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData a) => a.displayName == containerSave.containerItemId);
					if (itemData2 == null)
					{
						UnityEngine.Debug.LogError("Unable to find item info: " + containerSave.containerItemId);
						continue;
					}
				}
				if (!string.IsNullOrEmpty(containerSave.containerItemId))
				{
					GameObject containerPrefab = SingletonBehaviour<FateDB>.Instance.GetContainerPrefab(containerSave.containerItemId);
					if (containerPrefab != null)
					{
						GameObject gameObject2 = UnityEngine.Object.Instantiate(containerPrefab, containerSave.position, containerSave.rotation, activeContainersParent.transform);
						List<Item> list = (containerSave.isValid ? new List<Item>() : null);
						if (containerSave.isValid && containerSave.containedItems != null)
						{
							foreach (ItemSaveData itemSave in containerSave.containedItems)
							{
								ItemData itemData3 = SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData a) => a.displayName == itemSave.baseName);
								if (itemData3 == null)
								{
									UnityEngine.Debug.LogError("Unable to find item info: " + itemSave.baseName);
									continue;
								}
								Item item3 = new Item(itemData3);
								item3.ApplyInstance(itemSave);
								list.Add(item3);
							}
						}
						ContainerDestroyable component4;
						if (gameObject2.TryGetComponent<ContainerInteractable>(out var component3))
						{
							component3.Item = new Item(itemData2);
							component3.Init(!containerSave.isValid, containerSave.containedGold, containerSave.trapType, list, containerSave.isLocked);
						}
						else if (gameObject2.TryGetComponent<ContainerDestroyable>(out component4))
						{
							component4.Item = new Item(itemData2);
							component4.Init(!containerSave.isValid, containerSave.containedGold, containerSave.trapType, list);
						}
						else
						{
							UnityEngine.Debug.LogWarning("Prefab does not contain a needed script, ContainerInteractable/Destroyable is missing from " + containerSave.containerItemId, gameObject2);
						}
					}
					else
					{
						UnityEngine.Debug.LogWarning("Did not find a prefab for " + containerSave.containerItemId);
					}
				}
				else
				{
					ActiveLevel.SpawnGoldPile(containerSave.position, containerSave.containedGold);
				}
			}
			StartCoroutine(DoValidateQuestsPostLoad());
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.OnInventoryInit = (Action)Delegate.Combine(instance.OnInventoryInit, new Action(LoadDroppedItems));
			}
			finishedCreation?.Invoke();
		}

		private void ReattachPetsPostLoad()
		{
			for (int i = 0; i < activeCharacters.Count; i++)
			{
				if (!activeCharacters[i].TryGetComponent<Character>(out var masterCharacter) || !masterCharacter.Alive() || masterCharacter.monsterData == null || masterCharacter.monsterData.minions == null || masterCharacter.monsterData.minions.Count == 0)
				{
					continue;
				}
				for (int j = 0; j < masterCharacter.monsterData.minions.Count; j++)
				{
					MinionData minionData = masterCharacter.monsterData.minions[j];
					if (string.IsNullOrEmpty(minionData.name))
					{
						continue;
					}
					List<GameObject> list = activeCharacters.FindAll(delegate(GameObject go)
					{
						if (!go.TryGetComponent<Character>(out var component2))
						{
							return false;
						}
						if (component2.monsterData == null)
						{
							return false;
						}
						return !(minionData.name != component2.monsterData.displayName) && (masterCharacter.myTransform.position - component2.myTransform.position).sqrMagnitude < 400f;
					});
					if (list == null || list.Count == 0)
					{
						continue;
					}
					foreach (GameObject item in list)
					{
						if (item.TryGetComponent<Character>(out var component))
						{
							masterCharacter.AddPet(component);
						}
					}
				}
			}
		}

		private IEnumerator HookupWardToQuest(Ward wardChar)
		{
			while (!SingletonBehaviour<QuestManager>.InstanceExists() || !SingletonBehaviour<QuestManager>.Instance.HasLoaded)
			{
				yield return null;
			}
			bool flag = false;
			Quest realmQuest = SingletonBehaviour<QuestManager>.Instance.GetRealmQuest(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (realmQuest != null && realmQuest.QuestType == QuestData.QuestType.EscortOut && realmQuest.questWard != null && realmQuest.questWard.uniqueName == wardChar.CharacterName)
			{
				wardChar.SetQuest(realmQuest);
			}
			else
			{
				List<Quest> quests = SingletonBehaviour<QuestManager>.Instance.GetQuests((int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
				if (quests == null || quests.Count == 0)
				{
					UnityEngine.Debug.LogWarning("Ward spawned from savedata but no active quest for dungeon: " + wardChar.CharacterName);
					RemoveActiveCharacter(wardChar.gameObject);
					UnityEngine.Object.Destroy(wardChar.gameObject);
				}
				else
				{
					bool flag2 = false;
					for (int i = 0; i < quests.Count; i++)
					{
						Quest quest = quests[i];
						if ((quest.Status == Quest.QuestStatus.Accepted || quest.Status == Quest.QuestStatus.InProgress) && (quest.QuestType == QuestData.QuestType.EscortIn || quest.QuestType == QuestData.QuestType.Herd || quest.QuestType == QuestData.QuestType.EscortOut) && quest.questWard != null && (quest.QuestType != QuestData.QuestType.EscortIn || !(quest.questWard.uniqueName != wardChar.CharacterName)) && (quest.QuestType != QuestData.QuestType.Herd || !(quest.questWard.monsterDataId != wardChar.monsterData.displayName)))
						{
							flag2 = true;
							wardChar.SetQuest(quest);
							flag = quest.QuestType == QuestData.QuestType.EscortIn;
						}
					}
					if (!flag2)
					{
						UnityEngine.Debug.LogWarning("Ward spawned from savedata but no active quest found: " + wardChar.CharacterName);
						RemoveActiveCharacter(wardChar.gameObject);
						UnityEngine.Object.Destroy(wardChar.gameObject);
					}
				}
			}
			if (flag)
			{
				if (Player.PlayerChar != null)
				{
					wardChar.SetMasterCharacter(Player.PlayerChar);
					wardChar.transform.position = Player.PlayerChar.GetClosePosition(Player.PlayerChar.myTransform.position, 0.35f, 2f, 100);
					Player.PlayerChar.AddWard(wardChar);
				}
				else
				{
					StartCoroutine(DoWardWaitForPlayerMaster(wardChar));
				}
			}
		}

		private IEnumerator PopStatueTextAfterPlayerSpawn()
		{
			while (Player.PlayerChar == null)
			{
				yield return null;
			}
			yield return new WaitForSeconds(0.3f);
			if (Player.PlayerChar != null)
			{
				ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.GetReplaceTags("Msg_StatueItem"), 1.2f, ThatHurt.ThatHurtColor.White, 0f);
			}
		}

		private void LoadDroppedItems()
		{
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.OnInventoryInit = (Action)Delegate.Remove(instance.OnInventoryInit, new Action(LoadDroppedItems));
			}
			RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (realmSave == null)
			{
				return;
			}
			DungeonSaveData dungeonSave = realmSave.GetDungeonSave(levelDepth);
			if (dungeonSave == null || dungeonSave.droppedItems == null)
			{
				return;
			}
			foreach (DroppedItemSaveData droppedItem in dungeonSave.droppedItems)
			{
				ItemData itemData = SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData a) => a.displayName == droppedItem.item.baseName);
				if (itemData == null)
				{
					UnityEngine.Debug.LogError("Unable to find item info: " + droppedItem.item.baseName);
					continue;
				}
				Item item = new Item(itemData);
				item.ApplyInstance(droppedItem.item);
				AddDroppedItem(item.Drop(droppedItem.position, skipSoundAndDropTween: true));
			}
		}

		public void PreSaveTask(FateSaveData fateSaveData)
		{
			if (activeDungeon == null || SaveData.CurrentSaveSlot.saveState != 0)
			{
				return;
			}
			RealmSave realmSave = fateSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (realmSave.dungeonSave == null)
			{
				realmSave.dungeonSave = new DungeonStorage();
			}
			if (realmSave.dungeonSave.dungeons == null)
			{
				realmSave.dungeonSave.dungeons = new List<DungeonSaveData>();
			}
