		public void RemoveObjectsOverTime(Action onDone = null)
		{
			StartCoroutine(DoRemoveObjectsOverTime(onDone));
		}

		private IEnumerator DoRemoveObjectsOverTime(Action onDone = null)
		{
			CleanupNoiseMeshes(null);
			while (isCleaningUpNoiseMeshes)
			{
				yield return null;
			}
			SaveData.RemovePreSaveMainThreadTask(PreSaveTask);
			isRemovingObjects = true;
			removeObjectsProgress = 0f;
			List<UnityEngine.Object> objectsToRemove = new List<UnityEngine.Object>();
			if (activeGameObjectsParent != null)
			{
				foreach (Transform item in activeGameObjectsParent.transform)
				{
					if (!(item == null))
					{
						objectsToRemove.Add(item.gameObject);
					}
				}
			}
			UnityEngine.Debug.Log(string.Format("{0}: Removing walls and floors, objects to remove: {1}", "LevelGenerator", objectsToRemove.Count));
			int counter = 0;
			int i = 0;
			while (i < objectsToRemove.Count)
			{
				UnityEngine.Object.Destroy(objectsToRemove[i]);
				int num = counter + 1;
				counter = num;
				if (counter >= 400)
				{
					counter = 0;
					removeObjectsProgress = Mathf.Clamp01((float)i / (float)objectsToRemove.Count);
					Resources.UnloadUnusedAssets();
					GC.Collect();
					yield return null;
				}
				num = i + 1;
				i = num;
			}
			removeObjectsProgress = 1f;
			isRemovingObjects = false;
			UnityEngine.Debug.Log("LevelGenerator: Removal of walls and floors complete");
			onDone?.Invoke();
		}

		public bool AddDroppedItem(DroppedItem droppedItem)
		{
			if (droppedItem == null)
			{
				return false;
			}
			if (droppedItems == null)
			{
				droppedItems = new List<DroppedItem>();
			}
			if (droppedItems.Contains(droppedItem))
			{
				return false;
			}
			droppedItems.Add(droppedItem);
			return true;
		}

		public bool RemoveDroppedItem(DroppedItem droppedItem)
		{
			if (droppedItem == null || droppedItems == null)
			{
				return false;
			}
			if (droppedItems.Contains(droppedItem))
			{
				droppedItems.Remove(droppedItem);
				return true;
			}
			return false;
		}

