		private MonsterData FindMonsterDataByName(string name)
		{
			if (string.IsNullOrEmpty(name))
			{
				return null;
			}
			string text = name.ToUpper();
			for (int i = 0; i < SingletonBehaviour<FateDB>.Instance.allMonsters.Length; i++)
			{
				if (SingletonBehaviour<FateDB>.Instance.allMonsters[i].displayName.ToUpper() == text)
				{
					return SingletonBehaviour<FateDB>.Instance.allMonsters[i];
				}
			}
			return null;
		}

		private void GenerateQuests()
		{
			List<Quest> list = new List<Quest>();
			List<Quest> quests = SingletonBehaviour<QuestManager>.Instance.GetQuests((int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (quests != null)
			{
				list = new List<Quest>(quests);
			}
			Quest realmQuest = SingletonBehaviour<QuestManager>.Instance.GetRealmQuest(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (realmQuest != null)
			{
				list.Add(realmQuest);
			}
			List<Quest> hiddenQuests = SingletonBehaviour<QuestManager>.Instance.GetHiddenQuests();
			if (hiddenQuests != null)
			{
				list.AddRange(hiddenQuests);
			}
			if (list == null)
			{
				return;
			}
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i] == null || (list[i].Status != Quest.QuestStatus.Accepted && list[i].Status != Quest.QuestStatus.InProgress))
				{
					continue;
				}
				switch (list[i].QuestType)
				{
				case QuestData.QuestType.KillMonster:
					GenerateQuestUniqueMonster(list[i].uniqueQuestMonster, allowRankUp: true);
					break;
				case QuestData.QuestType.KillMonsters:
					GenerateQuestMonsters(list[i]);
					break;
				case QuestData.QuestType.MonsterItem:
					GenerateQuestMonsterItem(list[i]);
					break;
				case QuestData.QuestType.FindItem:
					GenerateQuestFindItem(list[i]);
					break;
				case QuestData.QuestType.KillArmy:
					GenerateQuestKillArmy(list[i]);
					break;
				case QuestData.QuestType.ArmyItem:
					GenerateQuestArmyItem(list[i]);
					break;
				case QuestData.QuestType.EscortIn:
					GenerateQuestWards(list[i], inProgress: true);
					list[i].OnNewLevelDepth(levelDepth);
					break;
				case QuestData.QuestType.EscortOut:
					GenerateQuestUniqueMonster(list[i].uniqueQuestMonster, allowRankUp: false);
					break;
				case QuestData.QuestType.Herd:
					if (list[i].Status == Quest.QuestStatus.Accepted)
					{
						GenerateQuestWards(list[i]);
					}
					break;
				case QuestData.QuestType.Deluge:
					GenerateShrine(list[i]);
					break;
				case QuestData.QuestType.Defend:
					GenerateShrine(list[i]);
					break;
				case QuestData.QuestType.RealmBoss:
					if (list[i].realmQuestData.targetRealm == RealmData.RealmId.HauntedPalace && list[i].Status == Quest.QuestStatus.InProgress && list[i].questMonsters != null && list[i].questMonsters.Count > 0)
					{
						GenerateTkalaBoss(list[i].questMonsters[1], list[i].questMonsters[0].targetDepth);
						return;
					}
					GenerateQuestUniqueMonster(list[i].uniqueQuestMonster, allowRankUp: false);
					break;
				case QuestData.QuestType.MasterQuest:
					GenerateQuestKillArmy(list[i]);
					break;
				case QuestData.QuestType.HeroItem:
					if (GenerateQuestMonsterItem(list[i]))
					{
						StartCoroutine(PopStatueTextAfterPlayerSpawn());
					}
					break;
				}
			}
		}

		private void ValidateQuestsPostLoad()
		{
			List<Quest> list = new List<Quest>();
			List<Quest> quests = SingletonBehaviour<QuestManager>.Instance.GetQuests((int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (quests != null)
			{
				list = new List<Quest>(quests);
			}
			Quest realmQuest = SingletonBehaviour<QuestManager>.Instance.GetRealmQuest(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (realmQuest != null)
			{
				list.Add(realmQuest);
			}
			List<Quest> hiddenQuests = SingletonBehaviour<QuestManager>.Instance.GetHiddenQuests();
			if (hiddenQuests != null)
			{
				list.AddRange(hiddenQuests);
			}
			if (list == null)
			{
				return;
			}
			for (int i = 0; i < list.Count; i++)
			{
				Quest quest = list[i];
				if (quest == null || (quest.Status != Quest.QuestStatus.Accepted && quest.Status != Quest.QuestStatus.InProgress))
				{
					continue;
				}
				switch (quest.QuestType)
				{
				case QuestData.QuestType.KillMonster:
				case QuestData.QuestType.RealmBoss:
					if (quest.uniqueQuestMonster == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: unique monster is null");
					}
					else
					{
						if (quest.uniqueQuestMonster.targetDepth != levelDepth)
						{
							break;
						}
						bool flag4 = false;
						foreach (GameObject activeCharacter in activeCharacters)
						{
							if (activeCharacter.TryGetComponent<Monster>(out var component6) && component6.Alive() && component6.CharacterName == quest.uniqueQuestMonster.uniqueName)
							{
								flag4 = true;
								break;
							}
						}
						if (!flag4)
						{
							UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: No monster found on depth {levelDepth}, spawning one ({quest.uniqueQuestMonster.uniqueName})");
							GenerateQuestUniqueMonster(quest.uniqueQuestMonster, allowRankUp: true);
						}
					}
					break;
				case QuestData.QuestType.KillMonsters:
				{
					if (quest.questMonsters == null || quest.questMonsters.Count == 0)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: list of monsters is null or empty when validating quest");
						break;
					}
					Quest.MonsterTemplate monsterTemplate = quest.questMonsters[0];
					if (monsterTemplate.targetDepth != levelDepth)
					{
						break;
					}
					int num3 = 0;
					foreach (GameObject activeCharacter2 in activeCharacters)
					{
						if (activeCharacter2.TryGetComponent<Monster>(out var component7) && component7.Alive() && component7.monsterData.displayName == monsterTemplate.monsterDataId)
						{
							num3++;
						}
					}
					int num4 = quest.TargetCount - num3;
					if (num4 > 0)
					{
						UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: Did not find enough monster of type {monsterTemplate.monsterDataId} on depth {levelDepth}, spawning {num4} more");
						GenerateQuestMonsters(quest, num4);
					}
					break;
				}
				case QuestData.QuestType.FindItem:
					if (quest.questItem == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: item is null");
					}
					else
					{
						if (quest.questItem.targetDepth != levelDepth || SingletonBehaviour<QuestManager>.Instance.IsKnownPlayerItem(quest.questItem.itemSaveData))
						{
							break;
						}
						bool flag5 = false;
						foreach (DroppedItem droppedItem in droppedItems)
						{
							Item item4 = droppedItem.Item;
							if (item4 != null && quest.questItem.itemSaveData.MatchesItem(item4))
							{
								flag5 = true;
								break;
							}
						}
						if (!flag5)
						{
							foreach (Transform item5 in activeContainersParent.transform)
							{
								if (flag5)
								{
									break;
								}
								if (!item5.TryGetComponent<ContainerInteractable>(out var component9) || component9.ContainedItems == null)
								{
									continue;
								}
								foreach (Item containedItem in component9.ContainedItems)
								{
									if (quest.questItem.itemSaveData.MatchesItem(containedItem))
									{
										flag5 = true;
										break;
									}
								}
							}
						}
						if (!flag5)
						{
							UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: No quest item found on depth {levelDepth}, spawning one ({quest.questItem.itemSaveData.ItemDisplayName})");
							GenerateQuestFindItem(quest);
						}
					}
					break;
				case QuestData.QuestType.MonsterItem:
				{
					if (quest.uniqueQuestMonster == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: unique monster is null");
						break;
					}
					Quest.ItemTemplate targetItem = quest.uniqueQuestMonster.targetItem;
					if (targetItem == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: item is null");
					}
					else
					{
						if (quest.uniqueQuestMonster.targetDepth != levelDepth || SingletonBehaviour<QuestManager>.Instance.IsKnownPlayerItem(targetItem.itemSaveData))
						{
							break;
						}
						bool flag3 = false;
						foreach (GameObject activeCharacter3 in activeCharacters)
						{
							if (flag3)
							{
								break;
							}
							if (!activeCharacter3.TryGetComponent<Monster>(out var component4) || !component4.Alive() || !component4.isUnique || component4.inventory == null)
							{
								continue;
							}
							foreach (Item item6 in component4.inventory)
							{
								if (item6 != null && targetItem.itemSaveData.MatchesItem(item6))
								{
									flag3 = true;
									break;
								}
							}
						}
						if (!flag3)
						{
							foreach (DroppedItem droppedItem2 in droppedItems)
							{
								Item item2 = droppedItem2.Item;
								if (item2 != null && targetItem.itemSaveData.MatchesItem(item2))
								{
									flag3 = true;
									break;
								}
							}
						}
						if (!flag3)
						{
							foreach (GameObject activeCharacter4 in activeCharacters)
							{
								if (flag3)
								{
									break;
								}
								if (activeCharacter4.TryGetComponent<Monster>(out var component5) && component5.Alive() && component5.isUnique && component5.inventory != null && component5.CharacterName == quest.uniqueQuestMonster.uniqueName)
								{
									UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: No quest item found on depth {levelDepth}, but found the unique monster, spawning the item ({targetItem.itemSaveData.ItemDisplayName}) in it's inventory");
									Item item3 = new Item(SingletonBehaviour<FateDB>.Instance.FindItemData((ItemData a) => a.displayName == targetItem.itemSaveData.baseName));
									item3.ApplyInstance(targetItem.itemSaveData);
									item3.SetIdentified(newValue: true);
									component5.AddItemToInventory(item3, AddItemReason.Loot);
									component5.allowDropInventory = true;
									component5.AttemptAutoEquip(item3);
									flag3 = true;
									break;
								}
							}
						}
						if (!flag3)
						{
							UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: No quest item found on depth {levelDepth}, spawning one ({targetItem.itemSaveData.ItemDisplayName})");
							GenerateQuestMonsterItem(quest);
						}
					}
					break;
				}
				case QuestData.QuestType.ArmyItem:
				{
					if (quest.uniqueQuestMonster == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: unique monster is null");
						break;
					}
					if (quest.MinionData == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: minion data is null");
						break;
					}
					Quest.ItemTemplate targetItem2 = quest.uniqueQuestMonster.targetItem;
					if (targetItem2 == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: target item is null");
					}
					else
					{
						if (quest.uniqueQuestMonster.targetDepth != levelDepth || SingletonBehaviour<QuestManager>.Instance.IsKnownPlayerItem(quest.uniqueQuestMonster.targetItem.itemSaveData))
						{
							break;
						}
						bool flag2 = false;
						foreach (GameObject activeCharacter5 in activeCharacters)
						{
							if (flag2)
							{
								break;
							}
							if (!activeCharacter5.TryGetComponent<Monster>(out var component2) || !component2.Alive() || !component2.isUnique || component2.inventory == null)
							{
								continue;
							}
							foreach (Item item7 in component2.inventory)
							{
								if (item7 != null && targetItem2.itemSaveData.MatchesItem(item7))
								{
									flag2 = true;
									break;
								}
							}
						}
						if (!flag2)
						{
							foreach (DroppedItem droppedItem3 in droppedItems)
							{
								Item item = droppedItem3.Item;
								if (item != null && targetItem2.itemSaveData.MatchesItem(item))
								{
									flag2 = true;
									break;
								}
							}
						}
						int num = 0;
						string text = ((quest.MinionData != null) ? quest.MinionData.displayName : "N/A");
						foreach (GameObject activeCharacter6 in activeCharacters)
						{
							if (activeCharacter6.TryGetComponent<Monster>(out var component3) && component3.Alive() && component3.monsterData.displayName == text)
							{
								num++;
							}
						}
						int num2 = quest.TargetCount - num - 1;
						if (!flag2 || num2 > 0)
						{
							if (!flag2)
							{
								UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: No quest item found on depth {levelDepth}, spawning one ({targetItem2.itemSaveData.ItemDisplayName})");
							}
							if (num2 > 0)
							{
								UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: Did not find enough minion monsters of type {text} on depth {levelDepth}, spawning {num2} more");
							}
							GenerateQuestArmyItem(quest, flag2, num2);
						}
					}
					break;
				}
				case QuestData.QuestType.KillArmy:
				case QuestData.QuestType.MasterQuest:
					if (quest.uniqueQuestMonster == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: unique monster is null");
					}
					else if (quest.MinionData == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: data is null");
					}
					else
					{
						if (quest.uniqueQuestMonster.targetDepth != levelDepth)
						{
							break;
						}
						bool flag6 = false;
						foreach (GameObject activeCharacter7 in activeCharacters)
						{
							if (activeCharacter7.TryGetComponent<Monster>(out var component10) && component10.Alive() && component10.CharacterName == quest.uniqueQuestMonster.uniqueName)
							{
								flag6 = true;
								break;
							}
						}
						int num7 = 0;
						string text2 = ((quest.MinionData != null) ? quest.MinionData.displayName : null);
						foreach (GameObject activeCharacter8 in activeCharacters)
						{
							if (activeCharacter8.TryGetComponent<Monster>(out var component11) && component11.Alive() && component11.monsterData.displayName == text2)
							{
								num7++;
							}
						}
						int num8 = quest.TargetCount - num7 - 1;
						if (!flag6 || num8 > 0)
						{
							if (!flag6)
							{
								UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: No quest item found on depth {levelDepth}, spawning one ({quest.uniqueQuestMonster.uniqueName})");
							}
							if (num8 > 0)
							{
								UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: Did not find enough minion monsters of type {text2} on depth {levelDepth}, spawning {num8} more");
							}
							GenerateQuestKillArmy(quest, !flag6, num8);
						}
					}
					break;
				case QuestData.QuestType.EscortIn:
					if (quest.questWard == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: ward is null");
						break;
					}
					GenerateQuestWards(quest, inProgress: true);
					quest.OnNewLevelDepth(levelDepth);
					break;
				case QuestData.QuestType.Herd:
					if (quest.questWard == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: ward is null");
					}
					else
					{
						if (quest.questWard.targetDepth != levelDepth)
						{
							break;
						}
						int num5 = 0;
						foreach (GameObject activeCharacter9 in activeCharacters)
						{
							if (activeCharacter9.TryGetComponent<Ward>(out var component8) && component8.connectedQuest == quest)
							{
								num5++;
							}
						}
						int num6 = quest.TargetCount - num5;
						if (num6 > 0)
						{
							UnityEngine.Debug.Log($"Validation of quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: Did not find enough herd monsters of type {quest.questWard.monsterDataId} on depth {levelDepth}, spawning {num6} more");
							GenerateQuestWards(quest, inProgress: false, num6);
						}
					}
					break;
				case QuestData.QuestType.Deluge:
				case QuestData.QuestType.Defend:
					if (quest.uniqueQuestMonster == null)
					{
						UnityEngine.Debug.LogError($"Quest {string.Format(quest.QuestName, quest.QuestGiverName)} of type {quest.QuestType}: shrine (unique monster) is null");
					}
					else
					{
						if (quest.uniqueQuestMonster.targetDepth != levelDepth)
						{
							break;
						}
						bool flag = false;
						foreach (GameObject activeCharacter10 in activeCharacters)
						{
							if (activeCharacter10.TryGetComponent<Shrine>(out var component) && component.CharacterName == quest.uniqueQuestMonster.uniqueName)
							{
								component.ConnectToQuest(quest);
								flag = true;
								break;
							}
						}
						if (!flag)
						{
							GenerateShrine(quest);
						}
					}
					break;
				}
			}
			onQuestValidationComplete?.Invoke();
		}

		private void CreateFloor()
		{
			floorCollection = new List<GameObject>();
			CreateFloorLayer();
			CreateCeilingLayer();
		}

		private void CreateFloorLayer()
		{
			if (activeTemplate.floorDictionary == null)
			{
				activeTemplate.UpdateFloorDictionary();
			}
			for (int i = 0; i < activeDungeon.GetMazeWidth(); i++)
			{
				for (int j = 0; j < activeDungeon.GetMazeHeight(); j++)
				{
					Vector3 positionFromCellPosition = activeDungeon.GetPositionFromCellPosition(i, j);
					positionFromCellPosition.y = 0f;
					bool flag = false;
					GameObject gameObject = UnityEngine.Object.Instantiate(openCellNWIcon, activeGameObjectsParent.transform);
					GameObject gameObject2 = UnityEngine.Object.Instantiate(openCellNEIcon, activeGameObjectsParent.transform);
					GameObject gameObject3 = UnityEngine.Object.Instantiate(openCellSWIcon, activeGameObjectsParent.transform);
					GameObject gameObject4 = UnityEngine.Object.Instantiate(openCellSEIcon, activeGameObjectsParent.transform);
					gameObject.transform.position += positionFromCellPosition;
					gameObject2.transform.position += positionFromCellPosition;
					gameObject3.transform.position += positionFromCellPosition;
					gameObject4.transform.position += positionFromCellPosition;
					bool flag2 = false;
					if (activeDungeon.IsCliff(i + 1, j) && activeDungeon.IsCliff(i, j + 1) && ((activeDungeon.WallTypeSW(i + 1, j) == WallTypes.SWCornerJoin && activeDungeon.WallTypeNE(i, j + 1) == WallTypes.NECornerJoin) || (activeDungeon.WallTypeSW(i, j + 1) == WallTypes.SWCornerJoin && activeDungeon.WallTypeNE(i + 1, j) == WallTypes.NECornerJoin)))
					{
						flag = true;
						bool num = activeDungeon.WallType(i + 1, j) == 1 || activeDungeon.WallType(i, j + 1) == 1;
						if (gameObject4 != null)
						{
							UnityEngine.Object.Destroy(gameObject4);
						}
						Quaternion rotation = new Quaternion
						{
							eulerAngles = new Vector3(90f, 0f, 0f)
						};
						GameObject gameObject5;
						if (num)
						{
							flag2 = true;
							gameObject5 = innerCornerWallSEIcon;
						}
						else
						{
							gameObject5 = cornerWallSEIcon;
							Quaternion quaternion = default(Quaternion);
							quaternion.eulerAngles = new Vector3(90f, 180f, 0f);
							rotation = quaternion;
						}
						UnityEngine.Object.Instantiate(gameObject5, gameObject5.transform.position + positionFromCellPosition, rotation, activeGameObjectsParent.transform);
					}
					if (activeDungeon.IsCliff(i - 1, j) && activeDungeon.IsCliff(i, j + 1) && ((activeDungeon.WallTypeSE(i - 1, j) == WallTypes.SECornerJoin && activeDungeon.WallTypeNW(i, j + 1) == WallTypes.NWCornerJoin) || (activeDungeon.WallTypeSE(i, j + 1) == WallTypes.SECornerJoin && activeDungeon.WallTypeNW(i - 1, j) == WallTypes.NWCornerJoin)))
					{
						flag = true;
						bool num2 = activeDungeon.WallType(i - 1, j) == 1 || activeDungeon.WallType(i, j + 1) == 1;
						if (gameObject3 != null)
						{
							UnityEngine.Object.Destroy(gameObject3);
						}
						Quaternion rotation2 = new Quaternion
						{
							eulerAngles = new Vector3(90f, 0f, 0f)
						};
						GameObject gameObject5;
						if (num2)
						{
							flag2 = true;
							gameObject5 = innerCornerWallSWIcon;
						}
						else
						{
							gameObject5 = cornerWallSWIcon;
							Quaternion quaternion = default(Quaternion);
							quaternion.eulerAngles = new Vector3(90f, 180f, 0f);
							rotation2 = quaternion;
						}
						UnityEngine.Object.Instantiate(gameObject5, gameObject5.transform.position + positionFromCellPosition, rotation2, activeGameObjectsParent.transform);
					}
					if (activeDungeon.IsCliff(i + 1, j) && activeDungeon.IsCliff(i, j - 1) && ((activeDungeon.WallTypeNW(i + 1, j) == WallTypes.NWCornerJoin && activeDungeon.WallTypeSE(i, j - 1) == WallTypes.SECornerJoin) || (activeDungeon.WallTypeNW(i, j - 1) == WallTypes.NWCornerJoin && activeDungeon.WallTypeSE(i + 1, j) == WallTypes.SECornerJoin)))
					{
						flag = true;
						bool num3 = activeDungeon.WallType(i + 1, j) == 1 || activeDungeon.WallType(i, j - 1) == 1;
						if (gameObject2 != null)
						{
							UnityEngine.Object.Destroy(gameObject2);
						}
						Quaternion rotation3 = new Quaternion
						{
							eulerAngles = new Vector3(90f, 0f, 0f)
						};
						GameObject gameObject5;
						if (num3)
						{
							flag2 = true;
							gameObject5 = innerCornerWallNEIcon;
						}
						else
						{
							gameObject5 = cornerWallNEIcon;
							Quaternion quaternion = default(Quaternion);
							quaternion.eulerAngles = new Vector3(90f, 180f, 0f);
							rotation3 = quaternion;
						}
						UnityEngine.Object.Instantiate(gameObject5, gameObject5.transform.position + positionFromCellPosition, rotation3, activeGameObjectsParent.transform);
					}
					if (activeDungeon.IsCliff(i - 1, j) && activeDungeon.IsCliff(i, j - 1) && ((activeDungeon.WallTypeSW(i - 1, j) == WallTypes.SWCornerJoin && activeDungeon.WallTypeNE(i, j - 1) == WallTypes.NECornerJoin) || (activeDungeon.WallTypeSW(i, j - 1) == WallTypes.SWCornerJoin && activeDungeon.WallTypeNE(i - 1, j) == WallTypes.NECornerJoin)))
					{
						flag = true;
						bool num4 = activeDungeon.WallType(i - 1, j) == 1 || activeDungeon.WallType(i, j - 1) == 1;
						if (gameObject != null)
						{
							UnityEngine.Object.Destroy(gameObject);
						}
						Quaternion rotation4 = new Quaternion
						{
							eulerAngles = new Vector3(90f, 0f, 0f)
						};
						GameObject gameObject5;
						if (num4)
						{
							flag2 = true;
							gameObject5 = innerCornerWallNWIcon;
						}
						else
						{
							gameObject5 = cornerWallNWIcon;
							Quaternion quaternion = default(Quaternion);
							quaternion.eulerAngles = new Vector3(90f, 180f, 0f);
							rotation4 = quaternion;
						}
						UnityEngine.Object.Instantiate(gameObject5, gameObject5.transform.position + positionFromCellPosition, rotation4, activeGameObjectsParent.transform);
					}
					CellTypes cellTypes = activeDungeon.CellType(i, j);
					GameObject gameObject6 = null;
					switch (cellTypes)
					{
					case CellTypes.Room:
					case CellTypes.Hall:
						if (activeDungeon.IsCliff(i, j))
						{
							flag = true;
							gameObject6 = ((!(activeTemplate.newFloorSplitPrefab != null)) ? UnityEngine.Object.Instantiate(activeTemplate.floorDictionary[cellTypes][true], positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform) : UnityEngine.Object.Instantiate(activeTemplate.newFloorSplitPrefab, positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform));
							Transform[] componentsInChildren = gameObject6.GetComponentsInChildren<Transform>();
							WallTypes wallTypes = activeDungeon.WallTypeNW(i, j);
							if (wallTypes != 0 && wallTypes != WallTypes.NWSolid)
							{
								componentsInChildren[1].gameObject.SetActive(value: false);
								UnityEngine.Object.Destroy(gameObject);
							}
							wallTypes = activeDungeon.WallTypeNE(i, j);
							if (wallTypes != 0 && wallTypes != WallTypes.NESolid)
							{
								componentsInChildren[2].gameObject.SetActive(value: false);
								UnityEngine.Object.Destroy(gameObject2);
							}
							wallTypes = activeDungeon.WallTypeSW(i, j);
							if (wallTypes != 0 && wallTypes != WallTypes.SWSolid)
							{
								componentsInChildren[3].gameObject.SetActive(value: false);
								UnityEngine.Object.Destroy(gameObject3);
							}
							wallTypes = activeDungeon.WallTypeSE(i, j);
							if (wallTypes != 0 && wallTypes != WallTypes.SESolid)
							{
								componentsInChildren[4].gameObject.SetActive(value: false);
								UnityEngine.Object.Destroy(gameObject4);
							}
						}
						else
						{
							gameObject6 = ((!(activeTemplate.newFloorPrefab != null)) ? UnityEngine.Object.Instantiate(activeTemplate.floorDictionary[cellTypes][false], positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform) : UnityEngine.Object.Instantiate(activeTemplate.newFloorPrefab, positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform));
						}
						break;
					case CellTypes.Pit:
					{
						MazeCreation.PitsData pitDataFromCellPosition = activeDungeon.GetPitDataFromCellPosition(i, j);
						if (!pitDataFromCellPosition.floorCreated)
						{
							pitDataFromCellPosition.floorCreated = true;
							activeDungeon.UpdatePitData(pitDataFromCellPosition, i, j);
							gameObject6 = ((!(activeTemplate.newFloorPrefab != null)) ? UnityEngine.Object.Instantiate(activeTemplate.floorDictionary[cellTypes][false], positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform) : UnityEngine.Object.Instantiate(activeTemplate.newFloorPrefab, positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform));
							gameObject6.transform.position = activeDungeon.GetPositionFromCellPosition(pitDataFromCellPosition.pitX, pitDataFromCellPosition.pitY);
							gameObject6.transform.position = new Vector3(gameObject6.transform.position.x + (float)pitDataFromCellPosition.pitWidth * 2f - 2f, gameObject6.transform.position.y, gameObject6.transform.position.z - (float)pitDataFromCellPosition.pitHeight * 2f + 2f);
							gameObject6.transform.localScale = new Vector3(pitDataFromCellPosition.pitWidth - 1, 1f, pitDataFromCellPosition.pitHeight - 1);
						}
						if (activeTemplate.waterLampPrefab != null)
						{
							UnityEngine.Object.Instantiate(activeTemplate.waterLampPrefab, positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform);
						}
						break;
					}
					case CellTypes.StairwellDown:
						gameObject6 = ((!(activeTemplate.newFloorPrefab != null)) ? UnityEngine.Object.Instantiate(activeTemplate.floorDictionary[cellTypes][false], positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform) : UnityEngine.Object.Instantiate(activeTemplate.newFloorPrefab, positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform));
						gameObject6.transform.localScale = new Vector3(2f, 1f, 2f);
						break;
					case CellTypes.RoomWall:
					case CellTypes.Solid:
					case CellTypes.NSDoor:
					case CellTypes.EWDoor:
					case CellTypes.StairwellUp:
						gameObject6 = ((!(activeTemplate.newFloorPrefab != null)) ? UnityEngine.Object.Instantiate(activeTemplate.floorDictionary[cellTypes][false], positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform) : UnityEngine.Object.Instantiate(activeTemplate.newFloorPrefab, positionFromCellPosition, Quaternion.identity, activeGameObjectsParent.transform));
						break;
					}
					if (gameObject6 != null && activeTemplate.floorMaterials != null && activeTemplate.floorMaterials.Count > 0)
					{
						if (gameObject6.TryGetComponent<MeshRenderer>(out var component))
						{
							component.SetMaterials(activeTemplate.floorMaterials);
						}
						else
						{
							MeshRenderer[] componentsInChildren2 = gameObject6.GetComponentsInChildren<MeshRenderer>();
							if (componentsInChildren2 != null && componentsInChildren2.Length != 0)
							{
								MeshRenderer[] array = componentsInChildren2;
								for (int k = 0; k < array.Length; k++)
								{
									array[k].SetMaterials(activeTemplate.floorMaterials);
								}
							}
						}
					}
					if (gameObject6 != null)
					{
						floorCollection.Add(gameObject6);
						foreach (Transform item in gameObject6.transform)
						{
							if (item.gameObject.activeSelf)
							{
								floorCollection.Add(item.gameObject);
							}
						}
					}
					if (!flag || flag2)
					{
						UnityEngine.Object.Destroy(gameObject);
						UnityEngine.Object.Destroy(gameObject2);
						UnityEngine.Object.Destroy(gameObject3);
						UnityEngine.Object.Destroy(gameObject4);
						switch (activeDungeon.CellType(i, j))
						{
						case CellTypes.Room:
						case CellTypes.Hall:
						case CellTypes.NSDoor:
						case CellTypes.EWDoor:
						case CellTypes.StairwellUp:
							UnityEngine.Object.Instantiate(openCellIcon, activeGameObjectsParent.transform, worldPositionStays: true).transform.position = positionFromCellPosition;
							break;
						}
					}
				}
			}
		}

		private void CombineFloorMeshes()
		{
			float tolerance = 0.001f;
			Dictionary<Vector3, List<Vector3>> dictionary = new Dictionary<Vector3, List<Vector3>>(new Vector3Comparer(tolerance));
			foreach (GameObject item2 in floorCollection)
			{
				MeshFilter componentInChildren = item2.GetComponentInChildren<MeshFilter>();
				if (componentInChildren == null)
				{
					continue;
				}
				Mesh sharedMesh = componentInChildren.sharedMesh;
				if (sharedMesh == null)
				{
					continue;
				}
				Vector3[] vertices = sharedMesh.vertices;
				Vector3[] normals = sharedMesh.normals;
				Matrix4x4 localToWorldMatrix = componentInChildren.transform.localToWorldMatrix;
				for (int i = 0; i < vertices.Length; i++)
				{
					Vector3 vector = localToWorldMatrix.MultiplyPoint3x4(vertices[i]);
					Vector3 item = localToWorldMatrix.MultiplyVector(normals[i]);
					Vector3 key = QuantizeVector3(vector, tolerance);
					if (!dictionary.ContainsKey(key))
					{
						dictionary[key] = new List<Vector3>();
					}
					dictionary[key].Add(item);
				}
			}
			foreach (GameObject item3 in floorCollection)
			{
				MeshFilter componentInChildren2 = item3.GetComponentInChildren<MeshFilter>();
				if (componentInChildren2 == null)
				{
					continue;
				}
				Mesh sharedMesh2 = componentInChildren2.sharedMesh;
				if (sharedMesh2 == null)
				{
					continue;
				}
				Vector3[] vertices2 = sharedMesh2.vertices;
				Vector3[] array = new Vector3[vertices2.Length];
				Matrix4x4 localToWorldMatrix2 = componentInChildren2.transform.localToWorldMatrix;
				Matrix4x4 worldToLocalMatrix = componentInChildren2.transform.worldToLocalMatrix;
				for (int j = 0; j < vertices2.Length; j++)
				{
					Vector3 key2 = QuantizeVector3(localToWorldMatrix2.MultiplyPoint3x4(vertices2[j]), tolerance);
					if (!dictionary.TryGetValue(key2, out var value))
					{
						continue;
					}
					Vector3 zero = Vector3.zero;
					foreach (Vector3 item4 in value)
					{
						zero += item4;
					}
					zero.Normalize();
					array[j] = worldToLocalMatrix.MultiplyVector(zero).normalized;
				}
				sharedMesh2.normals = array;
				MeshCollider componentInChildren3 = item3.GetComponentInChildren<MeshCollider>();
				if (componentInChildren3 != null)
				{
					componentInChildren3.sharedMesh = null;
					componentInChildren3.sharedMesh = sharedMesh2;
				}
			}
			UnityEngine.Debug.Log("Smoothing complete across all floor meshes.");
		}

		private static Vector3 QuantizeVector3(Vector3 vector, float tolerance)
		{
			return new Vector3(Mathf.Round(vector.x / tolerance) * tolerance, Mathf.Round(vector.y / tolerance) * tolerance, Mathf.Round(vector.z / tolerance) * tolerance);
		}

		private Mesh RemoveDuplicateVertices(Mesh mesh)
		{
			Vector3[] vertices = mesh.vertices;
			int[] triangles = mesh.triangles;
			Vector3[] normals = mesh.normals;
			Vector2[] uv = mesh.uv;
			List<Vector3> list = new List<Vector3>();
			List<Vector3> list2 = new List<Vector3>();
			List<Vector2> list3 = new List<Vector2>();
			List<int> list4 = new List<int>();
			Dictionary<Vector3, int> dictionary = new Dictionary<Vector3, int>();
			float num = 0.001f;
			for (int i = 0; i < triangles.Length; i++)
			{
				Vector3 vector = vertices[triangles[i]];
				Vector3 item = normals[triangles[i]];
				Vector2 item2 = uv[triangles[i]];
				bool flag = false;
				foreach (KeyValuePair<Vector3, int> item3 in dictionary)
				{
					if (Vector3.Distance(item3.Key, vector) <= num)
					{
						int value = item3.Value;
						list4.Add(value);
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					int value = list.Count;
					list.Add(vector);
					list2.Add(item);
					list3.Add(item2);
					dictionary[vector] = value;
					list4.Add(value);
				}
			}
			mesh.Clear();
			mesh.vertices = list.ToArray();
			mesh.normals = list2.ToArray();
			mesh.uv = list3.ToArray();
			mesh.triangles = list4.ToArray();
			mesh.RecalculateBounds();
			return mesh;
		}

