		private void CreateWalls()
		{
			for (int i = 0; i < activeDungeon.GetMazeWidth(); i++)
			{
				for (int j = 0; j < activeDungeon.GetMazeHeight(); j++)
				{
					Vector3 positionFromCellPosition = activeDungeon.GetPositionFromCellPosition(i, j);
					activeDungeon.CellHeight(i, j);
					if (activeDungeon.IsCliff(i, j))
					{
						int num = activeDungeon.WallType(i, j);
						WallTypes wallTypes = activeDungeon.WallTypeNW(i, j);
						if (num > 0)
						{
							num = 1;
						}
						int subWallTypeIndex = 0;
						if (activeDungeon.IsFlat(i, j) && !IsNearThisCellType(i, j, CellTypes.StairwellUp, 1) && !IsNearThisCellType(i, j, CellTypes.NSDoor, 1) && !IsNearThisCellType(i, j, CellTypes.EWDoor, 1))
						{
							subWallTypeIndex = UnityEngine.Random.Range(0, activeTemplate.WallTemplates(num, wallTypes));
						}
						if (wallTypes != 0 && wallTypes != WallTypes.NWSolid)
						{
							AddWall(num, wallTypes, subWallTypeIndex, positionFromCellPosition);
						}
						wallTypes = activeDungeon.WallTypeNE(i, j);
						if (wallTypes != 0 && wallTypes != WallTypes.NESolid)
						{
							AddWall(num, wallTypes, subWallTypeIndex, positionFromCellPosition);
						}
						wallTypes = activeDungeon.WallTypeSW(i, j);
						if (wallTypes != 0 && wallTypes != WallTypes.SWSolid)
						{
							AddWall(num, wallTypes, subWallTypeIndex, positionFromCellPosition);
						}
						wallTypes = activeDungeon.WallTypeSE(i, j);
						if (wallTypes != 0 && wallTypes != WallTypes.SESolid)
						{
							AddWall(num, wallTypes, subWallTypeIndex, positionFromCellPosition);
						}
					}
				}
			}
			activeGameObjectsParent.AddComponent<SmoothSeams>();
		}

		private void AddWall(int WallsetIndex, WallTypes WallType, int SubWallTypeIndex, Vector3 Location)
		{
			if (WallsetIndex >= activeTemplate.wallSets.Count || WallsetIndex < 0)
			{
				WallsetIndex = 0;
			}
			GameObject gameObject = activeTemplate.wallSets[WallsetIndex].wallTypes[(int)WallType].walls[SubWallTypeIndex];
			if (gameObject == null)
			{
				UnityEngine.Debug.LogWarning("Gameobject is null: SubWallTypeIndex = " + SubWallTypeIndex + " : WallType = " + WallType.ToString() + " : WallsetIndex = " + WallsetIndex);
				return;
			}
			Location += gameObject.transform.position;
			Vector3 vector = Vector3.zero;
			switch (WallType)
			{
			case WallTypes.NWCorner:
			{
				GameObject gameObject2;
				if (WallsetIndex == 1)
				{
					gameObject2 = innerCornerWallSEIcon;
					vector = new Vector3(-2f, 0f, 2f);
				}
				else
				{
					gameObject2 = cornerWallNWIcon;
				}
				UnityEngine.Object.Instantiate(gameObject2, gameObject2.transform.position + Location + vector, gameObject2.transform.rotation, activeGameObjectsParent.transform);
				break;
			}
			case WallTypes.SWCorner:
