		private void CreateProps()
		{
			List<RuntimePropData> props = activeDungeon.GetProps();
			if (props == null)
			{
				return;
			}
			int num = 0;
			for (int i = 0; i < props.Count; i++)
			{
				RuntimePropData runtimePropData = props[i];
				float num2 = runtimePropData.baseRotation;
				if (runtimePropData.rotateable)
				{
					num2 += UnityEngine.Random.Range(0f, 360f);
				}
				float num3 = UnityEngine.Random.Range(0f, runtimePropData.scaleVariation);
				num3 += 1f;
				Vector3 position = activeDungeon.GetPositionFromCellPosition(runtimePropData.cellX, runtimePropData.cellY);
				position.y = activeTemplate.tileHeight * (float)activeDungeon.CellHeight(runtimePropData.cellX, runtimePropData.cellY) + FloorHeight(position.x, position.z);
				position += runtimePropData.randomOffset;
				if (runtimePropData.isStairsUp)
				{
					position.y = 0f;
				}
				float radius = 1.5f;
				if (runtimePropData.modelPrefab.TryGetComponent<MeshRenderer>(out var component))
				{
					radius = Mathf.Max(component.bounds.size.x, component.bounds.size.z) * 1.2f;
				}
				if (!runtimePropData.isStairsUp && !runtimePropData.isStairsDown && !runtimePropData.locations.Contains(PropLocation.NSDoor) && !runtimePropData.locations.Contains(PropLocation.EWDoor) && !runtimePropData.hasPlacementRay && !ValidatePosition(ref position, radius))
				{
					continue;
				}
				GameObject gameObject = UnityEngine.Object.Instantiate(runtimePropData.modelPrefab, activeGameObjectsParent.transform, worldPositionStays: true);
				gameObject.transform.localScale *= num3;
				if (runtimePropData.hasPlacementRay)
				{
					Vector3 origin = position;
					origin.y = runtimePropData.rayHeight;
					Vector3 directionRay = runtimePropData.directionRay;
					directionRay.Normalize();
					origin -= directionRay * 2.5f;
					int layerMask = 16384;
					if (Physics.Raycast(origin, directionRay, out var hitInfo, 15f, layerMask))
					{
						MeshFilter component2 = gameObject.GetComponent<MeshFilter>();
						Vector3 point = hitInfo.point;
						point -= directionRay * component2.mesh.bounds.center.x;
						point -= directionRay * runtimePropData.rayPlacementOffset;
						point.y = position.y;
						position = point;
					}
					else if (Physics.Raycast(origin, directionRay, out hitInfo, 15f))
					{
						MeshFilter component3 = gameObject.GetComponent<MeshFilter>();
						Vector3 point2 = hitInfo.point;
						point2 -= directionRay * component3.mesh.bounds.center.x;
						point2 -= directionRay * runtimePropData.rayPlacementOffset;
						point2.y = position.y;
						position = point2;
					}
					else
					{
						position += new Vector3(runtimePropData.directionRay.x, 0f, runtimePropData.directionRay.z);
					}
				}
				gameObject.transform.SetPositionAndRotation(position, Quaternion.Euler(0f, num2 + 180f, 0f));
				if (runtimePropData.rotateable)
				{
					gameObject.transform.Rotate(new Vector3(0f, 1f, 0f), num2);
				}
				if (runtimePropData.locations.Contains(PropLocation.Water))
				{
					MazeCreation.PitsData pitDataFromCellPosition = activeDungeon.GetPitDataFromCellPosition(runtimePropData.cellX, runtimePropData.cellY);
					gameObject.transform.position = activeDungeon.GetPositionFromCellPosition(pitDataFromCellPosition.pitX, pitDataFromCellPosition.pitY);
					gameObject.transform.position = new Vector3(gameObject.transform.position.x + (float)pitDataFromCellPosition.pitWidth * 2f - 2f, position.y, gameObject.transform.position.z - (float)pitDataFromCellPosition.pitHeight * 2f + 2f);
					gameObject.transform.localScale = new Vector3(pitDataFromCellPosition.pitWidth - 1, 1f, pitDataFromCellPosition.pitHeight - 1);
				}
				if (usedMagicAnvil && gameObject.name.Contains("MagicAnvil"))
				{
					if (gameObject.TryGetComponent<MagicAnvilInteractable>(out var component4))
					{
						component4.SetUsed();
					}
					else
					{
						MagicAnvilInteractable componentInChildren = gameObject.GetComponentInChildren<MagicAnvilInteractable>();
						if (componentInChildren != null)
						{
							componentInChildren.SetUsed();
						}
					}
				}
				if (usedShrineOfLearning && gameObject.name.Contains("ShrineOfLearning"))
				{
					if (gameObject.TryGetComponent<ShrineOfLearningInteractable>(out var component5))
					{
						component5.SetUsed();
					}
					else
					{
						ShrineOfLearningInteractable componentInChildren2 = gameObject.GetComponentInChildren<ShrineOfLearningInteractable>();
						if (componentInChildren2 != null)
						{
							componentInChildren2.SetUsed();
						}
					}
				}
				if (usedFateStatue && gameObject.name.Contains("FateStatue"))
				{
					if (gameObject.TryGetComponent<FateStatueInteractable>(out var component6))
					{
						component6.SetUsed();
					}
					else
					{
						FateStatueInteractable componentInChildren3 = gameObject.GetComponentInChildren<FateStatueInteractable>();
						if (componentInChildren3 != null)
						{
							componentInChildren3.SetUsed();
						}
					}
				}
				if (gameObject.TryGetComponent<FountainInteractable>(out var component7))
				{
					component7.fountainIndex = num++;
					if (usedFountainIndexes != null && usedFountainIndexes.Contains(component7.fountainIndex))
					{
						component7.SetAsUsed();
					}
				}
			}
		}

		private void GenerateRandomItems()
		{
			int num = activeDungeon.GetMazeWidth() * activeDungeon.GetMazeHeight();
			if (UnityEngine.Random.Range(0, 100) < 75)
			{
				UnityEngine.Random.Range(1, 3);
			}
			int num2 = effectiveLevelDepth;
			num2 = Mathf.CeilToInt((float)num2 * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].difficultyMultiplier);
			num2 += Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].levelBase;
			if (num2 < 1)
			{
				num2 = 1;
			}
			int num3 = UnityEngine.Random.Range(num / 40, num / 30);
			for (int i = 0; i < num3; i++)
			{
				Vector3 vector = ((UnityEngine.Random.Range(0, 100) >= 70) ? RandomOpenPosition() : RandomOpenPositionNearWall());
				int num4 = UnityEngine.Random.Range(0, 100);
				int num5 = 1;
				bool flag = false;
				Item item;
				if (num4 < 80)
				{
					flag = true;
					item = GenerateBarrelItem();
					num5 = UnityEngine.Random.Range(1, 3);
				}
				else
				{
					item = GenerateContainerItem();
					if (UnityEngine.Random.Range(0, 100) < 50)
					{
						vector = RandomOpenPosition();
					}
				}
				TrapType typeOfTrap = TrapType.TrapNone;
				int num6 = 0;
				for (int j = 0; j < num5; j++)
				{
					if (flag)
					{
						item = GenerateBarrelItem();
					}
					if (item == null)
					{
						continue;
					}
					List<Item> list = new List<Item>();
					if (item.itemType == ItemType.Container)
					{
						if (num2 > 2 && UnityEngine.Random.Range(0, 100) < 10)
						{
							typeOfTrap = ((UnityEngine.Random.Range(0, 100) < 80) ? TrapType.TrapExplosion : TrapType.TrapPoison);
						}
						int num7 = UnityEngine.Random.Range(0, 2);
						for (int k = 0; k < num7; k++)
						{
							num4 = UnityEngine.Random.Range(0, 100);
							if (num4 < 15)
							{
								num6 += UnityEngine.Random.Range(num2, 4 * num2);
							}
							else if (num4 < 25)
							{
								list.Add(GenerateTakeableItem());
								if ((float)num4 * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier > 92f)
								{
									list[list.Count - 1].TryBestowPowers(num2, AllowCurse: true, num2);
								}
								if ((float)UnityEngine.Random.Range(0, 1000) < 3f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
								{
									list[list.Count - 1].BestowGrade(SingletonBehaviour<PlayerStatus>.Instance.Difficulty);
								}
							}
						}
					}
					else
					{
						if (num2 > 2 && item.itemType != ItemType.WeaponRack && UnityEngine.Random.Range(0, 100) < 6)
						{
							typeOfTrap = ((UnityEngine.Random.Range(0, 100) >= 80) ? TrapType.TrapPoison : TrapType.TrapSword);
						}
						int maxExclusive = 0;
						int minInclusive = 0;
						int num8 = num2;
						switch (item.itemType)
						{
						case ItemType.WeaponRack:
							minInclusive = 1;
							maxExclusive = 2;
							break;
						case ItemType.ChestSmall:
							maxExclusive = 1;
							break;
						case ItemType.ChestMedium:
							maxExclusive = 2;
							break;
						case ItemType.ChestLarge:
							minInclusive = 2;
							maxExclusive = 5;
							num8 += 2;
							break;
						case ItemType.ChestSmallLocked:
							minInclusive = 2;
							maxExclusive = 3;
							num8 += 3;
							break;
						case ItemType.ChestMediumLocked:
							minInclusive = 2;
							maxExclusive = 4;
							num8 += 3;
							break;
						case ItemType.ChestLargeLocked:
							minInclusive = 4;
							maxExclusive = 7;
							num8 += 6;
							break;
						}
						int num9 = UnityEngine.Random.Range(minInclusive, maxExclusive);
						bool flag2 = false;
						if (num9 == 0 && item.itemType != ItemType.WeaponRack)
						{
							num9 = 1;
							flag2 = true;
						}
						for (int l = 0; l < num9; l++)
						{
							num4 = UnityEngine.Random.Range(0, 100);
							if (item.itemType != ItemType.WeaponRack && (flag2 || num4 < 20))
							{
								num6 += UnityEngine.Random.Range(num8, 4 * num8);
								continue;
							}
							if (item.itemType == ItemType.WeaponRack)
							{
								list.Add(GenerateWeaponItem());
							}
							else
							{
								list.Add(GenerateTakeableItem());
							}
							if (list[list.Count - 1] == null)
							{
								continue;
							}
							if ((float)num4 * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier > 86f)
							{
								if ((float)num4 * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier > 98f)
								{
									list[list.Count - 1].BestowUniquePowers(num8, AllowCurse: false, num8);
								}
								else
								{
									list[list.Count - 1].TryBestowPowers(num8, AllowCurse: true, num8);
								}
							}
							if ((float)UnityEngine.Random.Range(0, 1000) < 50f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
							{
								list[list.Count - 1].BestowGrade(SingletonBehaviour<PlayerStatus>.Instance.Difficulty);
							}
							if ((float)UnityEngine.Random.Range(0, 100) < 12f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
							{
								list[list.Count - 1].BestowSockets(AllowUnique: false);
							}
						}
					}
					GameObject containerPrefab = SingletonBehaviour<FateDB>.Instance.GetContainerPrefab(item.itemBaseName);
					if (containerPrefab != null)
					{
						if (flag)
						{
							vector = RandomOpenPosition(vector, 2f, 8f);
						}
						containerPrefab = UnityEngine.Object.Instantiate(containerPrefab, vector, default(Quaternion), activeContainersParent.transform);
						containerPrefab.transform.Rotate(new Vector3(0f, 1f, 0f), UnityEngine.Random.Range(0f, 360f));
						bool locked = item.itemType == ItemType.ChestSmallLocked || item.itemType == ItemType.ChestMediumLocked || item.itemType == ItemType.ChestLargeLocked;
						ContainerDestroyable component2;
						if (containerPrefab.TryGetComponent<ContainerInteractable>(out var component))
						{
							component.Item = item;
							component.Init(state: false, num6, typeOfTrap, list, locked);
						}
						else if (containerPrefab.TryGetComponent<ContainerDestroyable>(out component2))
						{
							component2.Item = item;
							component2.Init(state: false, num6, typeOfTrap, list);
						}
						else
						{
							UnityEngine.Debug.LogWarning("Prefab does not contain a needed script, ContainerInteractable/Destroyable is missing from " + item.itemName);
						}
					}
					else
					{
						UnityEngine.Debug.LogWarning("Did not find a prefab for " + item.itemName);
					}
				}
			}
			int num10 = UnityEngine.Random.Range(0, 10);
			for (int m = 0; m < num10; m++)
			{
				ActiveLevel.SpawnGoldPile(RandomOpenPosition(), Mathf.Max(1, UnityEngine.Random.Range(num2, 4 * num2)));
			}
			StartCoroutine(SpawnDroppedPotions());
			for (int n = 0; n < activeDungeon.Rooms(); n++)
			{
				if (activeDungeon.RoomExits(n) >= 2 || activeDungeon.RoomWidth(n) >= 7 || activeDungeon.RoomHeight(n) >= 7 || UnityEngine.Random.Range(0, 100) >= 70)
				{
					continue;
				}
				for (int num11 = 0; num11 < activeDungeon.GetMazeHeight(); num11++)
				{
					for (int num12 = 0; num12 < activeDungeon.GetMazeWidth(); num12++)
					{
						if (UnityEngine.Random.Range(0, 100) >= 70)
						{
							continue;
						}
						CellTypes cellTypes = activeDungeon.CellType(num12, num11);
						if (cellTypes == CellTypes.EWDoor || cellTypes == CellTypes.NSDoor || activeDungeon.RoomIndexData(num12, num11) != n || activeDungeon.CellHeight(num12, num11) != 0)
						{
							continue;
						}
						Vector3 positionFromCellPosition = activeDungeon.GetPositionFromCellPosition(num12, num11);
						if (UnityEngine.Random.Range(0, 100) < 40)
						{
							bool flag3 = false;
							if ((float)UnityEngine.Random.Range(0, 1000) < 10f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
							{
								flag3 = true;
							}
							int random = monsterRandomizer.GetRandom();
							if (flag3)
							{
								random = uniqueMonsterRandomizer.GetRandom();
							}
							if (random != -1 && monstersDataManifest[random].alignment == Alignment.Evil)
							{
								activeCharacters.Add(SpawnEntity(monstersDataManifest[random].modelPrefab, RandomOpenPosition(positionFromCellPosition, 0f, 15f), monstersDataManifest[random], allowRankUp: true));
								List<GameObject> list2 = activeCharacters;
								Character component3 = list2[list2.Count - 1].GetComponent<Character>();
								OutfitCharacter(component3, flag3, -1, component3.GetMonsterRank);
								AttemptGenerateMinions(monstersDataManifest[random], component3);
								if (UnityEngine.Random.Range(0, 100) < 50 && !component3.isUnique)
								{
									component3.allowDropEquipment = false;
								}
							}
						}
						num10 = UnityEngine.Random.Range(0, 4);
						for (int num13 = 0; num13 < num10; num13++)
						{
							ActiveLevel.SpawnGoldPile(RandomOpenPosition(positionFromCellPosition, 1f, 6f), Mathf.Max(1, UnityEngine.Random.Range(2 * num2, 8 * num2)));
						}
						if (UnityEngine.Random.Range(0, 100) >= 50)
						{
							continue;
						}
						Item item2 = GenerateContainerItem();
						List<Item> list3 = new List<Item>();
						int num14 = 0;
						int num15 = UnityEngine.Random.Range(1, 3);
						for (int num16 = 0; num16 < num15; num16++)
						{
							int num17 = UnityEngine.Random.Range(0, 100);
							if (num17 < 75 && item2.itemType != ItemType.WeaponRack)
							{
								num14 += UnityEngine.Random.Range(num2, 4 * num2);
								continue;
							}
							if (item2.itemType == ItemType.WeaponRack)
							{
								list3.Add(GenerateWeaponItem());
							}
							else
							{
								list3.Add(GenerateTakeableItem());
							}
							if (list3[list3.Count - 1] != null && (float)num17 > 65f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
							{
								if ((float)num17 > 95f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
								{
									list3[list3.Count - 1].BestowUniquePowers(num2, AllowCurse: false, num2);
								}
								else
								{
									list3[list3.Count - 1].TryBestowPowers(num2, AllowCurse: false, num2);
								}
								if ((float)UnityEngine.Random.Range(0, 100) < 17f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
								{
									list3[list3.Count - 1].BestowSockets(AllowUnique: false);
								}
								if ((float)UnityEngine.Random.Range(0, 1000) < 30f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].itemMultiplier)
								{
									list3[list3.Count - 1].BestowGrade(SingletonBehaviour<PlayerStatus>.Instance.Difficulty);
								}
							}
						}
						GameObject containerPrefab2 = SingletonBehaviour<FateDB>.Instance.GetContainerPrefab(item2.itemBaseName);
						if (containerPrefab2 != null)
						{
							bool locked2 = item2.itemType == ItemType.ChestSmallLocked || item2.itemType == ItemType.ChestMediumLocked || item2.itemType == ItemType.ChestLargeLocked;
							containerPrefab2 = UnityEngine.Object.Instantiate(containerPrefab2, positionFromCellPosition, default(Quaternion), activeContainersParent.transform);
							if (containerPrefab2.TryGetComponent<ContainerInteractable>(out var component4))
							{
								component4.Item = item2;
								component4.Init(state: false, num14, TrapType.TrapNone, list3, locked2);
							}
							else
							{
								UnityEngine.Debug.LogWarning("Prefab does not contain a needed script, ContainerInteractable is missing from " + item2.itemName);
							}
						}
						else
						{
							UnityEngine.Debug.LogWarning("Did not find a prefab for " + item2.itemBaseName);
						}
					}
				}
			}
		}

		private IEnumerator SpawnDroppedPotions()
		{
			while (!SingletonBehaviour<PlayerUI>.InstanceExists() || !SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryInitialized)
			{
				yield return null;
			}
			yield return null;
			int num = UnityEngine.Random.Range(2, 6);
			for (int i = 0; i < num; i++)
			{
				Item item = GeneratePotionItem();
				DroppedItem droppedItemGO = FateDB.GetDroppedItemGO();
				droppedItemGO.transform.SetParent(GetActiveContainersParent);
				Vector3 vector = RandomOpenPosition();
				droppedItemGO.Drop(item, vector, vector, skipSoundAndDropTween: true);
			}
		}

		private void GenerateRandomMonsters()
		{
			if (activeCharacters == null)
			{
				activeCharacters = new List<GameObject>();
			}
			if (monsterPrefab != null)
			{
				Vector3 vector = PositionNearStairsUp();
				Vector3 vector2 = RandomOpenPosition();
				int num = 0;
				while ((vector2 - vector).magnitude > 10f && num < 100)
				{
					vector2 = RandomOpenPosition();
					num++;
				}
				GameObject gameObject = SpawnEntity(monsterPrefab.modelPrefab, vector2, monsterPrefab, allowRankUp: true);
				Character component = gameObject.GetComponent<Character>();
				activeCharacters.Add(gameObject);
				OutfitCharacter(component, isUnique: false, -1, component.GetMonsterRank);
			}
			if (UnityEngine.Random.Range(0, 100) < 30)
			{
				GameObject merchantPrefab = SingletonBehaviour<FateDB>.Instance.GetMerchantPrefab(MerchantType.Traveling, (RealmData.RealmId)levelRealm);
				if (merchantPrefab != null)
				{
					activeCharacters.Add(SpawnMerchant(merchantPrefab, RandomOpenPositionInRoom()));
				}
			}
			if (UnityEngine.Random.Range(0, 100) <= 20)
			{
				GameObject merchantPrefab2 = SingletonBehaviour<FateDB>.Instance.GetMerchantPrefab(MerchantType.Fish, (RealmData.RealmId)levelRealm);
				if (merchantPrefab2 != null)
				{
					activeCharacters.Add(SpawnMerchant(merchantPrefab2, RandomOpenPositionInRoom()));
				}
			}
			Vector3 vector3 = PositionNearStairsUp();
			vector3.y = 0f;
			int num2 = activeDungeon.GetMazeWidth() * activeDungeon.GetMazeHeight();
			int num3 = UnityEngine.Random.Range(num2 / 30, num2 / 20);
			if (num3 < 0)
			{
				num3 = 0;
			}
			num3 = Mathf.RoundToInt(num3 * monsterRatio / 100);
			for (int i = 0; i < num3; i++)
			{
				bool flag = false;
				if ((float)UnityEngine.Random.Range(0, 1000) < 10f * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].appearanceMultiplier)
				{
					flag = true;
				}
				int num4 = monsterRandomizer.GetRandom();
				if (flag)
				{
					int random = uniqueMonsterRandomizer.GetRandom();
					if (random != -1)
					{
						num4 = random;
					}
				}
				if (num4 == -1 || monstersDataManifest[num4].alignment != Alignment.Evil)
				{
					continue;
				}
				MonsterData monsterData = monstersDataManifest[num4];
				int num5 = 1;
				if (UnityEngine.Random.Range(0, 100) < 10 && (monsterData.minions == null || monsterData.minions.Count == 0 || monsterData.minions[0].range.Max == 0f) && !flag)
				{
					num5 = UnityEngine.Random.Range(2, 4);
				}
				Vector3 vector4 = RandomOpenPosition();
				int num6 = 0;
				while ((vector4 - vector3).magnitude < 24f && num6 < 1000)
				{
					vector4 = RandomOpenPosition();
					num6++;
				}
				for (int j = 0; j < num5; j++)
				{
					Character component2 = SpawnEntity(monstersDataManifest[num4].modelPrefab, RandomOpenPosition(vector4, 0f, 15f), monstersDataManifest[num4], allowRankUp: true).GetComponent<Character>();
					activeCharacters.Add(component2.gameObject);
					if (component2 == null)
					{
						UnityEngine.Debug.LogError("Character script missing from prefab : " + monstersDataManifest[num4].modelPrefab.name);
						continue;
					}
					OutfitCharacter(component2, flag, -1, component2.GetMonsterRank);
					i += AttemptGenerateMinions(monstersDataManifest[num4], component2);
					if (UnityEngine.Random.Range(0, 100) < 60 && !component2.isUnique)
					{
						component2.allowDropEquipment = false;
					}
				}
			}
		}

		public void AddMonsterToActiveMonsters(Monster monster)
		{
			activeCharacters.AddUnique(monster.gameObject);
