		public bool HasActiveCharacterWith(Predicate<Character> predicate)
		{
			if (activeCharacters == null)
			{
				return false;
			}
			foreach (GameObject activeCharacter in activeCharacters)
			{
				if (!(activeCharacter == null) && activeCharacter.TryGetComponent<Character>(out var component) && predicate(component))
				{
					return true;
				}
			}
			return false;
		}

		public bool HasDroppedItemWith(Predicate<Item> predicate)
		{
			if (droppedItems == null)
			{
				return false;
			}
			foreach (DroppedItem droppedItem in droppedItems)
			{
				if (droppedItem.Item != null && predicate(droppedItem.Item))
				{
					return true;
				}
			}
			return false;
		}

		private GameObject SpawnMerchant(GameObject prefab, Vector3 targetPos)
		{
			GameObject obj = UnityEngine.Object.Instantiate(prefab, targetPos, Quaternion.identity);
			Merchant component = obj.GetComponent<Merchant>();
			if (component != null)
			{
				if (SingletonBehaviour<MerchantData>.InstanceExists() && (SingletonBehaviour<MerchantData>.Instance.DepthUpdatedOn == effectiveLevelDepth || SingletonBehaviour<MerchantData>.Instance.DepthUpdatedOn == -1))
				{
					SingletonBehaviour<MerchantData>.Instance.UpdateRandomizerTables();
				}
				component.GenerateItemInventory();
			}
			return obj;
		}

		private GameObject SpawnEntity(GameObject prefab, Vector3 targetPos, MonsterData monsterData, bool allowRankUp, bool fromSave = false, Alignment overrideAlignment = Alignment.None)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(prefab, targetPos, Quaternion.identity);
			Character component = gameObject.GetComponent<Character>();
			if (component != null)
			{
				if (monsterData == null)
				{
					UnityEngine.Debug.LogError("No MonsterData provided!");
					return null;
				}
				component.monsterData = monsterData;
				component.isLoadedFromSave = fromSave;
				component.Init();
				component.SetPositionProper(targetPos);
				if (!string.IsNullOrEmpty(component.CharacterName))
				{
					string characterName = component.CharacterName;
					if (int.TryParse(characterName[characterName.Length - 1].ToString(), out var _))
					{
						component.CharacterName = component.CharacterName.Substring(0, component.CharacterName.LastIndexOf('_'));
					}
				}
				if (allowRankUp)
				{
					component.RandomizeMonsterRank();
				}
				GameObject minimapIcon = UnityEngine.Object.Instantiate((((overrideAlignment != 0) ? overrideAlignment : component.GetAlignment()) == Alignment.Evil) ? monsterIcon : friendlyIcon, component.transform);
				component.SetMinimapIcon(minimapIcon);
			}
			return gameObject;
		}

		public int AttemptGenerateMinions(MonsterData monsterData, Character master)
		{
			int num = 0;
			if (monsterData != null && monsterData.minions != null && monsterData.minions.Count > 0)
			{
				for (int i = 0; i < monsterData.minions.Count; i++)
				{
					MinionData minionData = monsterData.minions[i];
					int num2 = (int)minionData.range.GetValue();
					if (string.IsNullOrEmpty(minionData.name))
					{
						continue;
					}
					string[] array = minionData.name.Split('_');
					if (array == null || array.Length < 2)
					{
						continue;
					}
					string text = array[1];
					int monsterDataIndexByName = GetMonsterDataIndexByName(text);
					if (monsterDataIndexByName != -1)
					{
						for (int j = 0; j < num2; j++)
						{
							num++;
							Character component = SpawnEntity(monstersDataManifest[monsterDataIndexByName].modelPrefab, RandomOpenPosition(master.myTransform.position, 1f, 3f), monstersDataManifest[monsterDataIndexByName], allowRankUp: false).GetComponent<Character>();
							activeCharacters.Add(component.gameObject);
							OutfitCharacter(component, isUnique: false, master.MinionLevel(), component.GetMonsterRank);
							master.AddPet(component);
							component.allowDropInventory = false;
							component.allowDropEquipment = false;
						}
					}
				}
			}
			return num;
		}

