		public bool GenerateQuestMonsterItem(Quest quest)
		{
			if (quest.RealmId != SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm)
			{
				return false;
			}
			Quest.MonsterTemplate monsterTemplate = null;
			MonsterData monsterData = null;
			Quest.ItemTemplate itemTemplate = null;
			if (quest.QuestType == QuestData.QuestType.HeroItem)
			{
				bool flag = false;
				foreach (Quest.MonsterTemplate questMonster in quest.questMonsters)
				{
					if (questMonster.targetDepth == levelDepth)
					{
						flag = true;
						monsterTemplate = questMonster;
						itemTemplate = questMonster.targetItem;
						foreach (MonsterData item2 in monstersDataManifest)
						{
							if (item2.displayName == questMonster.monsterDataId)
							{
								monsterData = item2;
								break;
							}
						}
					}
					if (flag)
					{
						break;
					}
				}
				if (!flag)
				{
					return false;
				}
			}
			else
			{
				if (quest.uniqueQuestMonster == null || quest.uniqueQuestMonster.targetDepth != levelDepth || quest.uniqueQuestMonster.targetRealm != SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm)
				{
					return false;
				}
				monsterTemplate = quest.uniqueQuestMonster;
				itemTemplate = quest.uniqueQuestMonster.targetItem;
				foreach (MonsterData item3 in monstersDataManifest)
				{
					if (quest.uniqueQuestMonster.monsterDataId == item3.displayName)
					{
						monsterData = item3;
						break;
					}
				}
			}
			if (monsterData == null || monsterData.modelPrefab == null)
			{
				UnityEngine.Debug.LogError("Chosen unique monster does not have a model prefab, monster display name is " + monsterTemplate.monsterDataId + ", quest is " + string.Format(quest.QuestName, quest.QuestGiverName));
				return false;
			}
			if (itemTemplate == null)
			{
				UnityEngine.Debug.LogError("Chosen unique monster does not have a target item, quest is " + string.Format(quest.QuestName, quest.QuestGiverName));
				return false;
			}
			Vector3 vector = PositionNearStairsUp();
			vector.y = 0f;
			Vector3 vector2 = RandomOpenPosition();
			int num = 0;
			while ((vector2 - vector).magnitude < 10.5f && num < 1000)
			{
				vector2 = RandomOpenPosition();
				num++;
			}
			activeCharacters.Add(SpawnEntity(monsterData.modelPrefab, vector2, monsterData, allowRankUp: true));
			List<GameObject> list = activeCharacters;
			Character component = list[list.Count - 1].GetComponent<Character>();
			component.CharacterName = monsterTemplate.uniqueName;
			OutfitCharacter(component, isUnique: true, monsterTemplate.overrideLevel, component.GetMonsterRank);
			AttemptGenerateMinions(monsterData, component);
			Item item = new Item(SingletonBehaviour<FateDB>.Instance.FindItemData((ItemData a) => a.displayName == itemTemplate.itemSaveData.baseName));
			item.ApplyInstance(itemTemplate.itemSaveData);
			item.SetIdentified(newValue: true);
			component.AddItemToInventory(item, AddItemReason.Loot);
			component.allowDropInventory = true;
			component.AttemptAutoEquip(item);
			return true;
		}

