			if (quest.questMonsters == null || quest.questMonsters.Count == 0)
			{
				return;
			}
			Quest.MonsterTemplate monsterTemplate = quest.questMonsters[0];
			if (monsterTemplate.targetDepth != levelDepth || monsterTemplate.targetRealm != SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm)
			{
				return;
			}
			foreach (MonsterData item in monstersDataManifest)
			{
				if (monsterTemplate.monsterDataId == item.displayName)
				{
					monsterData = item;
					break;
				}
			}
			if (monsterData == null || monsterData.modelPrefab == null)
			{
				return;
			}
			int num = ((countOverride != -1) ? countOverride : quest.TargetCount);
			for (int i = 0; i < num; i++)
			{
				Vector3 vector = PositionNearStairsUp();
				vector.y = 0f;
				Vector3 vector2 = RandomOpenPosition();
				int num2 = 0;
				while ((vector2 - vector).magnitude < 10.5f && num2 < 1000)
				{
					vector2 = RandomOpenPosition();
					num2++;
				}
				activeCharacters.Add(SpawnEntity(monsterData.modelPrefab, vector2, monsterData, allowRankUp: true));
				List<GameObject> list = activeCharacters;
				Character component = list[list.Count - 1].GetComponent<Character>();
				OutfitCharacter(component, isUnique: false, monsterTemplate.overrideLevel, component.GetMonsterRank);
				AttemptGenerateMinions(monsterData, component);
			}
		}

		public void GenerateQuestKillArmy(Quest quest, bool spawnUniqueMonster = true, int minionCountOverride = -1)
		{
			MonsterData monsterData = null;
			if (quest == null || quest.uniqueQuestMonster == null || quest.uniqueQuestMonster.targetDepth != levelDepth || quest.uniqueQuestMonster.targetRealm != SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm)
			{
				return;
			}
			foreach (MonsterData item in monstersDataManifest)
			{
				if (quest.uniqueQuestMonster.monsterDataId == item.displayName)
				{
					monsterData = item;
					break;
				}
			}
			if (monsterData == null || monsterData.modelPrefab == null)
			{
				UnityEngine.Debug.LogError("Chosen unique monster does not have a model prefab");
				return;
			}
			Vector3 vector = PositionNearStairsUp();
			vector.y = 0f;
			Vector3 vector2 = RandomOpenPosition();
			int num = 0;
			while ((vector2 - vector).magnitude < 10.5f && num < 1000)
			{
				vector2 = RandomOpenPosition();
				num++;
			}
			Character character = null;
			if (spawnUniqueMonster)
			{
				character = SpawnEntity(monsterData.modelPrefab, vector2, monsterData, allowRankUp: true).GetComponent<Character>();
				activeCharacters.Add(character.gameObject);
				character.CharacterName = quest.uniqueQuestMonster.uniqueName;
				OutfitCharacter(character, isUnique: true, quest.uniqueQuestMonster.overrideLevel, character.GetMonsterRank);
			}
			else
			{
				foreach (GameObject activeCharacter in activeCharacters)
				{
					if (activeCharacter.TryGetComponent<Monster>(out var component) && component.Alive() && component.isUnique && component.CharacterName == quest.uniqueQuestMonster.uniqueName)
					{
						character = component;
						break;
					}
				}
			}
			int num2 = ((minionCountOverride != -1) ? minionCountOverride : (quest.TargetCount - 1));
			if (!(quest.MinionData != null) || num2 <= 0)
			{
				return;
			}
			for (int i = 0; i < num2; i++)
			{
				int levelCap;
				if (character != null)
				{
					levelCap = character.MinionLevel();
				}
				else
				{
					float num3 = UnityEngine.Random.Range(0.5f, 0.8f);
					levelCap = (int)((float)quest.uniqueQuestMonster.overrideLevel * num3);
				}
				Character pet = SpawnMonster(quest.MinionData, RandomOpenPosition(vector2, 5f), quest.QuestType == QuestData.QuestType.MasterQuest, levelCap, quest.QuestType == QuestData.QuestType.MasterQuest);
				if (character != null)
				{
					character.AddPet(pet);
				}
			}
		}

		public void GenerateQuestArmyItem(Quest quest, bool skipQuestMonsterOverride = false, int minionCountOverride = -1)
		{
			MonsterData monsterData = null;
			if (quest == null || quest.uniqueQuestMonster == null || quest.uniqueQuestMonster.targetDepth != levelDepth || quest.uniqueQuestMonster.targetRealm != SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm)
			{
				return;
			}
			foreach (MonsterData item2 in monstersDataManifest)
			{
				if (quest.uniqueQuestMonster.monsterDataId == item2.displayName)
				{
					monsterData = item2;
					break;
				}
			}
			if (monsterData == null || monsterData.modelPrefab == null)
			{
				UnityEngine.Debug.LogError("Chosen unique monster does not have a model prefab");
				return;
			}
			Vector3 vector = PositionNearStairsUp();
			vector.y = 0f;
			Vector3 vector2 = RandomOpenPosition();
			int num = 0;
			while ((vector2 - vector).magnitude < 10.5f && num < 1000)
			{
				vector2 = RandomOpenPosition();
				num++;
			}
			Character character = null;
			if (!skipQuestMonsterOverride)
			{
				character = SpawnEntity(monsterData.modelPrefab, vector2, monsterData, allowRankUp: true).GetComponent<Character>();
				activeCharacters.Add(character.gameObject);
				OutfitCharacter(character, isUnique: true, quest.uniqueQuestMonster.overrideLevel, character.GetMonsterRank);
				character.CharacterName = quest.uniqueQuestMonster.uniqueName;
				if (quest.uniqueQuestMonster.targetItem == null)
				{
					UnityEngine.Debug.LogError("Chosen unique monster does not have a target item");
					return;
				}
				ItemSaveData isd = quest.uniqueQuestMonster.targetItem.itemSaveData;
				Item item = new Item(SingletonBehaviour<FateDB>.Instance.FindItemData((ItemData a) => a.displayName == isd.baseName));
				item.ApplyInstance(isd);
				item.SetIdentified(newValue: true);
				character.AddItemToInventory(item, AddItemReason.Loot);
				character.allowDropInventory = true;
				character.AttemptAutoEquip(item);
			}
			else
			{
				foreach (GameObject activeCharacter in activeCharacters)
				{
					if (activeCharacter.TryGetComponent<Monster>(out var component) && component.Alive() && component.isUnique && component.CharacterName == quest.uniqueQuestMonster.uniqueName)
					{
						character = component;
						break;
					}
				}
			}
			int num2 = ((minionCountOverride != -1) ? minionCountOverride : (quest.TargetCount - 1));
			if (!(quest.MinionData != null) || num2 <= 0)
			{
				return;
			}
			for (int i = 0; i < num2; i++)
			{
				int levelCap;
				if (character != null)
				{
					levelCap = character.MinionLevel();
				}
				else
				{
					float num3 = UnityEngine.Random.Range(0.5f, 0.8f);
					levelCap = (int)((float)quest.uniqueQuestMonster.overrideLevel * num3);
				}
				Character pet = SpawnMonster(quest.MinionData, RandomOpenPosition(vector2, 5f), false, levelCap);
				if (character != null)
				{
					character.AddPet(pet);
				}
			}
		}

		public void GenerateQuestWards(Quest quest, bool inProgress = false, int countOverride = -1)
		{
			if (quest == null || quest.questWard == null)
			{
				return;
			}
			MonsterData monsterData = null;
			Quest.MonsterTemplate questWard = quest.questWard;
			if (!inProgress && (questWard.targetDepth != levelDepth || questWard.targetRealm != SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm))
			{
				return;
			}
			foreach (MonsterData item in monstersDataManifest)
			{
				if (questWard.monsterDataId == item.displayName)
				{
					monsterData = item;
					break;
				}
			}
			if (monsterData == null || monsterData.modelPrefab == null)
			{
				return;
			}
			int num = ((countOverride != -1) ? countOverride : Mathf.Max(quest.TargetCount, 1));
			for (int i = 0; i < num; i++)
			{
				Vector3 vector;
				if (inProgress)
				{
					vector = ((SaveData.CurrentSaveData?.realmSaveData == null) ? ((!goingDeeper) ? activeDungeon.GetPlayerSpawnPointDown() : activeDungeon.GetPlayerSpawnPointUp()) : (SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm).GetDungeonSave(levelDepth)?.savedPlayerPosition ?? activeDungeon.GetPlayerSpawnPointUp()));
				}
				else
				{
					Vector3 vector2 = PositionNearStairsUp();
					vector2.y = 0f;
					vector = RandomOpenPosition();
					int num2 = 0;
					while ((vector - vector2).magnitude < 10.5f && num2 < 1000)
					{
						vector = RandomOpenPosition();
						num2++;
					}
				}
				activeCharacters.Add(SpawnEntity(monsterData.modelPrefab, vector, monsterData, allowRankUp: false));
				List<GameObject> list = activeCharacters;
				Ward component = list[list.Count - 1].GetComponent<Ward>();
				component.CharacterName = questWard.uniqueName;
				if (inProgress)
				{
					component.SetAIState(AIState.Follow);
				}
				if (quest.QuestType == QuestData.QuestType.EscortIn && questWard.targetDepth == levelDepth)
				{
					component.SetAIState(AIState.Retire);
				}
				else if (quest.QuestType == QuestData.QuestType.Herd)
				{
					component.SetAIState(AIState.Wander);
				}
				else if (Player.PlayerChar != null)
				{
					component.SetMasterCharacter(Player.PlayerChar);
				}
				else
				{
					List<GameObject> list2 = activeCharacters;
					StartCoroutine(DoWardWaitForPlayerMaster(list2[list2.Count - 1].GetComponent<Ward>()));
				}
				component.SetQuest(quest);
				OutfitCharacter(component, isUnique: false, questWard.overrideLevel, component.GetMonsterRank);
				StartCoroutine(HookupWardToQuest(component));
			}
		}

		public void GenerateShrine(Quest quest)
		{
			MonsterData monsterData = null;
			Quest.MonsterTemplate uniqueQuestMonster = quest.uniqueQuestMonster;
			if (uniqueQuestMonster.targetDepth != levelDepth || uniqueQuestMonster.targetRealm != SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm)
			{
				return;
			}
			foreach (MonsterData item in monstersDataManifest)
			{
				if (uniqueQuestMonster.monsterDataId == item.displayName)
				{
					monsterData = item;
					break;
				}
			}
			if (!(monsterData == null) && !(monsterData.modelPrefab == null))
			{
				Vector3 vector = PositionNearStairsUp();
				vector.y = 0f;
				Vector3 vector2 = RandomOpenPosition();
				int num = 0;
				while ((vector2 - vector).magnitude < 10.5f && num < 1000)
				{
					vector2 = RandomOpenPosition();
					num++;
				}
				activeCharacters.Add(SpawnEntity(monsterData.modelPrefab, vector2, monsterData, allowRankUp: false));
