		public Character SpawnMonster(MonsterData monsterData, Vector3? targetLocation = null, bool? isUnique = null, int levelCap = -1, bool allowRankUp = false, Alignment overrideAlignment = Alignment.None)
		{
			if (monsterData == null || monsterData.modelPrefab == null)
			{
				UnityEngine.Debug.LogError("Chosen unique monster does not have a model prefab");
				return null;
			}
			bool valueOrDefault = isUnique.GetValueOrDefault();
			Vector3 vector;
			if (targetLocation.HasValue)
			{
				vector = targetLocation.Value;
			}
			else
			{
				Vector3 vector2 = PositionNearStairsUp();
				vector2.y = 0f;
				vector = RandomOpenPosition();
				int num = 0;
				while ((vector - vector2).magnitude < 24f && num < 1000)
				{
					vector = RandomOpenPosition();
					num++;
				}
			}
			Character component = SpawnEntity(monsterData.modelPrefab, RandomOpenPosition(vector, 7f, 13f), monsterData, allowRankUp, fromSave: false, overrideAlignment).GetComponent<Character>();
			activeCharacters.Add(component.gameObject);
			OutfitCharacter(component, valueOrDefault, levelCap, component.GetMonsterRank);
			List<GameObject> list = activeCharacters;
			return list[list.Count - 1].GetComponent<Character>();
		}

		public IEnumerator DoWardWaitForPlayerMaster(Ward ward)
		{
			if (ward == null)
			{
				UnityEngine.Debug.LogError("Ward is null");
				yield break;
			}
			while (Player.PlayerChar == null)
			{
				yield return new WaitForSeconds(1f);
			}
			ward.SetPositionProper(Player.PlayerChar.GetClosePosition(Player.PlayerChar.myTransform.position, 0.35f, 2f, 100));
			if (ward.Alive())
			{
				AIState aIState = ward.GetAIState();
				if (aIState != AIState.Retire && aIState != AIState.CompleteRetire)
				{
					ward.SetMasterCharacter(Player.PlayerChar);
					Player.PlayerChar.AddWard(ward);
				}
			}
		}

		public void OutfitCharacter(Character character, bool isUnique, int levelCap, Rank rank)
		{
			int num = levelCap;
			if (num < 0)
			{
				int num2 = effectiveLevelDepth - 2;
				if (num2 < 1)
				{
					num2 = 1;
				}
				num = UnityEngine.Random.Range(num2, effectiveLevelDepth);
				if (SingletonBehaviour<PlayerStatus>.Instance != null)
				{
					num = Mathf.CeilToInt((float)num * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].difficultyMultiplier);
					num += Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].levelBase;
				}
				else
				{
					num = Mathf.CeilToInt((float)num * 1f);
					num = num;
				}
				if (num < 1)
				{
					num = 1;
				}
			}
			if (rank != 0)
			{
				character.ApplyMonsterRank(rank);
			}
			if (isUnique)
			{
				float num3 = 0.02f;
				bool superSized = UnityEngine.Random.value < num3;
				character.MakeUnique(num, superSized);
			}
			else
			{
				character.TweakToLevel(num);
			}
		}

		public void SetPlayerPositionInLevel(bool downStairs = true)
		{
			if (activeDungeon == null)
			{
				return;
			}
			if (playerSpawn == null)
			{
				GameObject[] rootGameObjects = base.gameObject.scene.GetRootGameObjects();
				foreach (GameObject gameObject in rootGameObjects)
				{
					if (gameObject.name == "Player" && gameObject.activeSelf)
					{
						playerSpawn = gameObject.GetComponentInChildren<PlayerSpawn>().gameObject;
						break;
					}
				}
				if (playerSpawn == null)
				{
					return;
				}
			}
			Vector3 vector = ((!downStairs) ? activeDungeon.GetPlayerSpawnPointDown() : activeDungeon.GetPlayerSpawnPointUp());
			SpawnLocation spawnLocation = playerSpawnLocation;
			if (spawnLocation == SpawnLocation.SavedLocation || spawnLocation == SpawnLocation.TownPortalLocation)
			{
				DungeonSaveData dungeonSave = SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm).GetDungeonSave(levelDepth);
				if (dungeonSave != null)
				{
					Vector3 vector2;
					switch (playerSpawnLocation)
					{
					case SpawnLocation.SavedLocation:
						vector2 = dungeonSave.savedPlayerPosition;
						break;
					case SpawnLocation.TownPortalLocation:
					{
						vector2 = dungeonSave.portalPosition;
						GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("TownPortal_Closing");
						if (particlePrefab != null)
						{
							UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab, vector2, Quaternion.identity), 4f);
						}
						break;
					}
					default:
						throw new Exception($"Unhandled enum value {playerSpawnLocation} when trying to determine player spawn location");
					}
					if (NavMesh.SamplePosition(vector2, out var hit, 1f, 1))
					{
						vector = hit.position;
					}
					else
					{
						UnityEngine.Debug.LogError($"Failed to find navmesh-adjusted spawn point, attempted location is {playerSpawnLocation}");
					}
				}
			}
			vector.y = 1f;
			if (petData != null)
			{
				StartCoroutine(SpawnPetTest(vector));
			}
			if (playerTemplate == null)
			{
				playerSpawn.transform.position = vector;
				playerTemplate = playerSpawn.GetComponent<PlayerSpawn>().SpawnPlayer();
			}
			else
			{
				playerTemplate.transform.position = vector;
				playerTemplate.GetComponent<ProdigyPlayer>().RequestRespawn(vector);
			}
		}

		public IEnumerator SpawnPetTest(Vector3 spawnPoint)
		{
			yield return new WaitForSeconds(1f);
			Character component = UnityEngine.Object.Instantiate(petData.modelPrefab, spawnPoint, Quaternion.identity).GetComponent<Character>();
			component.monsterData = petData;
			component.Init();
			Player.PlayerChar.AddPet(component);
		}

		public void Remove()
		{
			if (activeGameObjectsParent == null)
			{
				return;
			}
			UnityEngine.Object.Destroy(activeGameObjectsParent);
			UnityEngine.Object.Destroy(activeContainersParent);
			if (activeCharacters != null)
			{
				foreach (GameObject activeCharacter in activeCharacters)
				{
					UnityEngine.Object.Destroy(activeCharacter);
				}
			}
			if (droppedItems != null)
			{
				foreach (DroppedItem droppedItem in droppedItems)
				{
					droppedItem.Remove();
				}
			}
			activeGameObjectsParent = null;
			activeCharacters = null;
			droppedItems = null;
			activeDungeon = null;
			if (navMeshSurface != null)
			{
				StartCoroutine(UpdateNavMeshInDungeon());
			}
		}

		private IEnumerator UpdateNavMeshInDungeon()
		{
			yield return new WaitForSecondsRealtime(0.01f);
			navMeshSurface.BuildNavMesh();
		}

		private IEnumerator WaitToCreate(float newWorldLocationX, float newWorldLocationZ, int newLevelDepth, int newLevelRealm, bool goesDown, bool useSavedPosition, bool ignoreSavedState)
		{
			cleanupNoiseMeshesProgress = 0f;
			removeObjectsProgress = 0f;
			progress = 0f;
			CleanupNoiseMeshes(null);
			RemoveObjectsOverTime();
			while (IsCleaning)
			{
				yield return null;
			}
			yield return new WaitForSecondsRealtime(0.01f);
			Create(newWorldLocationX, newWorldLocationZ, newLevelDepth, newLevelRealm, goesDown, useSavedPosition, ignoreSavedState);
		}

		public void ReplaceDungeon(float newWorldLocationX, float newWorldLocationZ, int newLevelDepth, int newLevelRealm, bool goesDown, bool useSavedPosition, bool ignoreSavedState = false, bool skipSave = false)
		{
			if (activeGameObjectsParent == null)
			{
				return;
			}
			goingDeeper = goesDown;
			SingletonBehaviour<LoadingScreenUI>.Instance.ShowLoading(fadeIn: false, loadProgressFunc);
			if (!editorMode)
			{
				UpdateSaveData(goesDown);
				if (skipSave)
				{
					if (playerTemplate != null)
					{
						playerTemplate.GetComponent<ProdigyPlayer>().RequestDestruction(skipSave);
					}
					ResumeReplaceDungeon(newWorldLocationX, newWorldLocationZ, newLevelDepth, newLevelRealm, goesDown, useSavedPosition, ignoreSavedState);
					return;
				}
				SaveData.RequestSave(delegate
				{
					if (playerTemplate != null)
					{
						playerTemplate.GetComponent<ProdigyPlayer>().RequestDestruction(skipSave);
					}
					ResumeReplaceDungeon(newWorldLocationX, newWorldLocationZ, newLevelDepth, newLevelRealm, goesDown, useSavedPosition, ignoreSavedState);
				});
			}
			else
			{
				ResumeReplaceDungeon(newWorldLocationX, newWorldLocationZ, newLevelDepth, newLevelRealm, goesDown, useSavedPosition, ignoreSavedState);
			}
		}

		private void ResumeReplaceDungeon(float newWorldLocationX, float newWorldLocationZ, int newLevelDepth, int newLevelRealm, bool goesDown, bool useSavedPosition, bool ignoreSavedState)
		{
			UnityEngine.Object.Destroy(activeContainersParent);
			if (activeCharacters != null)
			{
				foreach (GameObject activeCharacter in activeCharacters)
				{
					UnityEngine.Object.Destroy(activeCharacter);
				}
			}
			if (droppedItems != null)
			{
				foreach (DroppedItem droppedItem in droppedItems)
				{
					droppedItem.Remove();
				}
			}
			activeContainersParent = null;
			activeCharacters = null;
			droppedItems = null;
			activeDungeon = null;
			StartCoroutine(WaitToCreate(newWorldLocationX, newWorldLocationZ, newLevelDepth, newLevelRealm, goesDown, useSavedPosition, ignoreSavedState));
		}

