		public void ReplaceActiveCharacter(GameObject newObject, GameObject oldObject)
		{
			for (int i = 0; i < activeCharacters.Count; i++)
			{
				if (activeCharacters[i] == oldObject)
				{
					activeCharacters[i] = newObject;
					List<GameObject> list = activeCharacters;
					if (list[list.Count - 1].GetComponent<Character>().GetAlignment() == Alignment.Evil)
					{
						GameObject original = monsterIcon;
						List<GameObject> list2 = activeCharacters;
						GameObject minimapIcon = UnityEngine.Object.Instantiate(original, list2[list2.Count - 1].transform);
						List<GameObject> list3 = activeCharacters;
						list3[list3.Count - 1].GetComponent<Character>().SetMinimapIcon(minimapIcon);
					}
					break;
				}
			}
