		public Character FindCharacterWithinView(Transform transformation, Alignment alignment, float motionRadius, float coneRadius, float radius)
		{
			if (activeCharacters == null)
			{
				return null;
			}
			int num = (1 << LayerMask.NameToLayer("Player")) | (1 << LayerMask.NameToLayer("Player Damagable"));
			num = ~num;
			foreach (GameObject activeCharacter in activeCharacters)
			{
				if (activeCharacter.TryGetComponent<Character>(out var component) && CheckValidLineSight(component, alignment, transformation, motionRadius, coneRadius, radius, num))
				{
					return component;
				}
			}
			if (playerAvatar == null)
			{
				if (playerTemplate == null || !playerTemplate.TryGetComponent<ProdigyPlayer>(out var component2) || component2.RuntimeAvatar == null)
				{
					return null;
				}
				playerAvatar = component2.RuntimeAvatar.gameObject;
				if (playerAvatar == null)
				{
					return null;
				}
			}
			Character component3 = playerAvatar.GetComponent<Character>();
			if (component3 == null)
			{
				return null;
			}
			for (int i = 0; i < component3.GetPetCount(); i++)
			{
				Character pet = component3.GetPet(i);
				if (CheckValidLineSight(pet, alignment, transformation, motionRadius, coneRadius, radius, num))
				{
					if (pet.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
					{
						return pet.Master();
					}
					return pet;
				}
			}
			if (!playerAvatar.GetComponent<CharacterVitals>().IsDead && alignment == Alignment.Good && CheckValidLineSight(component3, alignment, transformation, motionRadius, coneRadius, radius, num))
			{
				return component3;
			}
			return null;
		}

		private bool CheckValidLineSight(Character character, Alignment alignment, Transform ownerTransform, float motionRadius, float coneRadius, float radius, int layerMask)
		{
			if (character.GetAlignment() == Alignment.Neutral)
			{
				return false;
			}
			if (!character.Alive() || character.GetAlignment() != alignment || character.IsPetNearDeath())
			{
				return false;
			}
			if (character.IsMimic() && character.DisplayedAsItem())
			{
				return false;
			}
			Vector3 vector = character.transform.position - ownerTransform.position;
			vector.y = 0f;
			float magnitude = vector.magnitude;
			bool flag = false;
			if (magnitude <= motionRadius)
			{
				flag = true;
			}
			if (MathF.Abs((float)(180.0 / Math.PI * Math.Atan2(vector.x, vector.z))) > coneRadius && magnitude <= radius)
			{
				flag = true;
			}
			if (!flag)
			{
				return false;
			}
			Vector3 position = ownerTransform.position;
			Vector3 normalized = (character.transform.position - position).normalized;
			position.y = 1f;
			RaycastHit hitInfo;
			return !Physics.Raycast(position, normalized, out hitInfo, magnitude, WallLayerMask);
		}

		public Vector3 PositionNearStairsUp()
		{
			for (int i = 0; i < activeDungeon.GetMazeWidth(); i++)
			{
				for (int j = 0; j < activeDungeon.GetMazeHeight(); j++)
				{
					if (activeDungeon.CellType(i, j) == CellTypes.StairwellUp)
					{
						return activeDungeon.GetPositionFromCellPosition(i, j);
					}
				}
			}
			return RandomOpenPosition();
		}

		public bool IsNearThisCellType(int X, int Y, CellTypes cellType, int range)
		{
			for (int i = 1; i <= range; i++)
			{
				if (activeDungeon.CellType(X + i, Y) == cellType || activeDungeon.CellType(X - i, Y) == cellType || activeDungeon.CellType(X, Y + i) == cellType || activeDungeon.CellType(X, Y - i) == cellType || activeDungeon.CellType(X + i, Y + i) == cellType || activeDungeon.CellType(X - i, Y - i) == cellType || activeDungeon.CellType(X + i, Y - i) == cellType || activeDungeon.CellType(X - i, Y + i) == cellType)
				{
					return true;
				}
			}
			return false;
		}

		public Vector3 PositionNearStairsDown()
		{
			for (int i = 0; i < activeDungeon.GetMazeWidth(); i++)
			{
				for (int j = 0; j < activeDungeon.GetMazeHeight(); j++)
				{
					if (activeDungeon.CellType(i, j) == CellTypes.StairwellDown)
					{
						if (activeDungeon.CellOpenIgnoreDoors(i - 1, j))
						{
							return activeDungeon.GetPositionFromCellPosition(i - 1, j);
						}
						if (activeDungeon.CellOpenIgnoreDoors(i + 1, j))
						{
							return activeDungeon.GetPositionFromCellPosition(i + 1, j);
						}
						if (activeDungeon.CellOpenIgnoreDoors(i, j - 1))
						{
							return activeDungeon.GetPositionFromCellPosition(i, j - 1);
						}
						if (activeDungeon.CellOpenIgnoreDoors(i, j + 1))
						{
							return activeDungeon.GetPositionFromCellPosition(i, j + 1);
						}
					}
				}
			}
			return RandomOpenPosition();
		}

		public Vector3 RandomOpenPositionNearWall()
		{
			int num = 0;
			int layerMask = (1 << LayerMask.NameToLayer("Player Damagable")) | (1 << LayerMask.NameToLayer("Player Interactable"));
			bool flag = false;
			float tileWidth = activeTemplate.tileWidth;
			while (!flag && num < 1000)
			{
				Vector3 vector = new Vector3(UnityEngine.Random.Range(0f, (float)activeDungeon.GetMazeWidth() * tileWidth), 0f, UnityEngine.Random.Range(0f, (float)activeDungeon.GetMazeHeight() * (0f - tileWidth)));
				CellTypes cellTypes = PositionType(vector);
				if ((cellTypes == CellTypes.Room || cellTypes == CellTypes.Hall) && (cellTypes == CellTypes.Hall || PositionType(vector + new Vector3(0f, 0f, tileWidth)) == CellTypes.RoomWall || PositionType(vector + new Vector3(0f, 0f, 0f - tileWidth)) == CellTypes.RoomWall || PositionType(vector + new Vector3(0f - tileWidth, 0f, 0f)) == CellTypes.RoomWall || PositionType(vector + new Vector3(tileWidth, 0f, 0f)) == CellTypes.RoomWall) && cellTypes != CellTypes.NSDoor && cellTypes != CellTypes.EWDoor && cellTypes != CellTypes.StairwellUp && NavMesh.SamplePosition(vector, out var hit, 1f, 1))
				{
					if (!Physics.SphereCast(hit.position + Vector3.up * 4f, 0.5f, Vector3.down, out var _, 5f, layerMask, QueryTriggerInteraction.Collide))
					{
						return hit.position;
					}
					num++;
				}
			}
			return RandomOpenPosition();
		}

