				CellTypes cellTypes = PositionType(vector);
				if (cellTypes == CellTypes.Room && (PositionType(vector + new Vector3(0f, 0f, tileWidth)) == CellTypes.Room || PositionType(vector + new Vector3(0f, 0f, 0f - tileWidth)) == CellTypes.Room || PositionType(vector + new Vector3(0f - tileWidth, 0f, 0f)) == CellTypes.Room || PositionType(vector + new Vector3(tileWidth, 0f, 0f)) == CellTypes.Room) && cellTypes != CellTypes.NSDoor && cellTypes != CellTypes.EWDoor && cellTypes != CellTypes.StairwellUp && NavMesh.SamplePosition(vector, out var hit, 1f, 1))
				{
					if (!Physics.SphereCast(hit.position + Vector3.up * 4f, 0.5f, Vector3.down, out var _, 5f, layerMask, QueryTriggerInteraction.Collide))
