		public Vector3 RandomOpenPosition()
		{
			int num = 0;
			int layerMask = (1 << LayerMask.NameToLayer("Player Damagable")) | (1 << LayerMask.NameToLayer("Player Interactable"));
			bool flag = false;
			while (!flag && num < 1000)
			{
				Vector3 vector = new Vector3(UnityEngine.Random.Range(0f, (float)activeDungeon.GetMazeWidth() * activeTemplate.tileWidth), 0f, UnityEngine.Random.Range(0f, (float)activeDungeon.GetMazeHeight() * (0f - activeTemplate.tileWidth)));
				MazeCreation.CellData cellData = PositionCellData(vector);
				if (cellData.cellType == CellTypes.NSDoor || cellData.cellType == CellTypes.EWDoor || cellData.cellType == CellTypes.StairwellUp || !NavMesh.SamplePosition(vector, out var hit, 1f, 1))
				{
					continue;
				}
				if (Physics.SphereCast(hit.position + Vector3.up * 4f, 0.5f, Vector3.down, out var _, 5f, layerMask, QueryTriggerInteraction.Collide))
				{
					num++;
					continue;
				}
				if (cellData.roomIndexData == -1)
				{
					return hit.position;
				}
				if (!activeDungeon.IsRoomNotFull(cellData.roomIndexData))
				{
					continue;
				}
				activeDungeon.AddCharToRoomCount(cellData.roomIndexData);
				return hit.position;
			}
			return Vector3.zero;
		}

		public bool ValidatePosition(ref Vector3 position, float radius)
		{
			int num = 0;
			int layerMask = (1 << LayerMask.NameToLayer("Player Damagable")) | (1 << LayerMask.NameToLayer("Player Interactable")) | (1 << LayerMask.NameToLayer("NavMeshBlocker")) | (1 << LayerMask.NameToLayer("Water")) | (1 << LayerMask.NameToLayer("Default"));
			while (num < 1000)
			{
				float maxInclusive = 2f;
				Vector3 vector = position;
				Vector3 vector2 = new Vector3(UnityEngine.Random.Range(0f, maxInclusive), 0f, UnityEngine.Random.Range(0f, maxInclusive));
				if (Mathf.Approximately(vector2.magnitude, 0f))
				{
					num++;
					continue;
				}
				vector += vector2;
				if (Physics.SphereCast(vector + Vector3.up * 8f, radius, Vector3.down, out var _, 10f, layerMask, QueryTriggerInteraction.Collide))
				{
					num++;
					continue;
				}
				position = vector;
				return true;
			}
			return false;
		}

		public Vector3 RandomOpenPosition(Vector3 startPosition, float radius)
		{
			return RandomOpenPosition(startPosition, 0f, radius);
		}

		public Vector3 RandomOpenPosition(Vector3 startPosition, float minimumRadius, float maximumRadius)
		{
			int num = 0;
			int layerMask = (1 << LayerMask.NameToLayer("Player Damagable")) | (1 << LayerMask.NameToLayer("Player Interactable")) | (1 << LayerMask.NameToLayer("NavMeshBlocker"));
			while (num < 1000)
			{
				Vector3 onUnitSphere = UnityEngine.Random.onUnitSphere;
				onUnitSphere.y = 0f;
				if (Mathf.Approximately(onUnitSphere.magnitude, 0f))
				{
					num++;
					continue;
				}
				Vector3 vector = onUnitSphere.normalized * UnityEngine.Random.Range(minimumRadius, maximumRadius);
				if (NavMesh.SamplePosition(startPosition + vector, out var hit, 1f, 1))
				{
					if (!Physics.SphereCast(hit.position + Vector3.up * 4f, 0.5f, Vector3.down, out var _, 5f, layerMask, QueryTriggerInteraction.Collide))
					{
						return hit.position;
					}
					num++;
				}
				else
				{
					num++;
				}
			}
			return startPosition;
		}

		public bool AddItemToRandomContainer(Item item)
		{
			if (activeContainersParent == null)
			{
				return false;
			}
			bool flag = false;
			bool flag2 = false;
			int num = 0;
			while (!flag)
			{
				ContainerInteractable[] componentsInChildren = activeContainersParent.GetComponentsInChildren<ContainerInteractable>();
				foreach (ContainerInteractable containerInteractable in componentsInChildren)
				{
					if (!containerInteractable.IsOpen)
					{
						if (UnityEngine.Random.Range(0, 100) < 10 || flag2)
						{
							containerInteractable.ContainedItems.Add(item);
							return true;
						}
						num++;
					}
				}
				if (num == 0)
				{
					return false;
				}
				flag2 = true;
			}
			return false;
		}

