		private void UpdateRandomizers()
		{
			monsterRandomizer = new Randomizer();
			uniqueMonsterRandomizer = new Randomizer();
			takeableItemRandomizer = new Randomizer();
			rareTakeableitemRandomizer = new Randomizer();
			orbRandomizer = new Randomizer();
			potionRandomizer = new Randomizer();
			jewelryRandomizer = new Randomizer();
			gemRandomizer = new Randomizer();
			rareGemRandomizer = new Randomizer();
			weaponRandomizer = new Randomizer();
			rareWeaponRandomizer = new Randomizer();
			fishingRandomizer = new Randomizer();
			barrelRandomizer = new Randomizer();
			containerRandomizer = new Randomizer();
			int getAdjustedItemDepth = GetAdjustedItemDepth;
			int num = Mathf.CeilToInt((float)levelDepth * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].appearanceMultiplier);
			bool flag = false;
			bool flag2 = false;
			if (levelDepth >= 99)
			{
				flag = true;
			}
			if (num >= 99)
			{
				flag2 = true;
			}
			if (prefabList == null)
			{
				prefabList = new List<List<GameObject>>();
			}
			if (prefabList.Count < SingletonBehaviour<FateDB>.Instance.allTemplates.Length)
			{
				while (prefabList.Count < SingletonBehaviour<FateDB>.Instance.allTemplates.Length)
				{
					prefabList.Add(new List<GameObject>());
				}
			}
			for (int i = 0; i < monstersDataManifest.Count; i++)
			{
				bool flag3 = false;
				MonsterData monsterData = monstersDataManifest[i];
				if (!monsterData.ValidForRealm(levelRealm) || monsterData.modelPrefab == null)
				{
					continue;
				}
				if (monsterData.modelPrefab.GetComponent<Monster>() == null)
				{
					UnityEngine.Debug.LogError("Prefab set but no Monster Component found: " + monsterData.displayName, monsterData);
				}
				else
				{
					if (monsterData.reserved)
					{
						continue;
					}
					if (monsterData.alignment == Alignment.Evil && ((monsterData.minimumDepth <= num && monsterData.maximumDepth >= num) || (flag2 && monsterData.minimumDepth <= num)))
					{
						int num2 = 1000 - monsterData.rarity;
						if (num2 > 0)
						{
							monsterRandomizer.AddChoice(i, num2);
							prefabList[activeTemplateIndex].Add(monsterData.modelPrefab);
							flag3 = true;
						}
					}
					if (monsterData.alignment != Alignment.Evil || ((monsterData.minimumDepth - 1 > num || monsterData.maximumDepth - 2 < num) && (!flag2 || monsterData.minimumDepth - 1 > num)))
					{
						continue;
					}
					int num3 = 1000 - monsterData.rarity;
					if (num3 > 0)
					{
						uniqueMonsterRandomizer.AddChoice(i, num3);
						if (!flag3)
						{
							prefabList[activeTemplateIndex].Add(monsterData.modelPrefab);
						}
					}
				}
			}
			for (int i = 0; i < itemDataManifest.Count; i++)
			{
				if (itemDataManifest[i].takeable && !itemDataManifest[i].reserved)
				{
					if ((itemDataManifest[i].minimumDepth <= getAdjustedItemDepth && (itemDataManifest[i].maximumDepth >= getAdjustedItemDepth || itemDataManifest[i].maximumDepth == 0)) || (flag && itemDataManifest[i].minimumDepth <= getAdjustedItemDepth))
					{
						int num4 = 1000 - itemDataManifest[i].rarity;
						if (num4 > 0)
						{
							if (itemDataManifest[i].itemType == ItemType.Orb)
							{
								orbRandomizer.AddChoice(i, num4);
							}
							else
							{
								takeableItemRandomizer.AddChoice(i, num4);
								rareTakeableitemRandomizer.AddChoice(i, num4);
								if (itemDataManifest[i].itemType == ItemType.Gem || itemDataManifest[i].ItemCategory == ItemCategory.Jewelry)
								{
									jewelryRandomizer.AddChoice(i, num4);
								}
								if (itemDataManifest[i].itemType == ItemType.Gem)
								{
									gemRandomizer.AddChoice(i, num4);
									num4 = 1000 - (int)((float)itemDataManifest[i].rarity / 2f);
									if (num4 > 0)
									{
										rareGemRandomizer.AddChoice(i, num4);
									}
								}
								if (itemDataManifest[i].itemType == ItemType.Potion && itemDataManifest[i].uses == 1)
								{
									potionRandomizer.AddChoice(i, num4);
								}
							}
						}
					}
					else if ((itemDataManifest[i].minimumDepth - 11 <= getAdjustedItemDepth && (itemDataManifest[i].maximumDepth >= getAdjustedItemDepth || itemDataManifest[i].maximumDepth == 0)) || (flag && itemDataManifest[i].minimumDepth - 11 <= getAdjustedItemDepth))
					{
						int num5 = 1000 - itemDataManifest[i].rarity;
						if (num5 > 0)
						{
							rareTakeableitemRandomizer.AddChoice(i, num5);
						}
						if (itemDataManifest[i].itemType == ItemType.Gem)
						{
							num5 = 1000 - (int)((float)itemDataManifest[i].rarity / 2f);
							if (num5 > 0)
							{
								rareGemRandomizer.AddChoice(i, num5);
							}
						}
					}
				}
				if (itemDataManifest[i].ItemCategory == ItemCategory.Weapon && !itemDataManifest[i].reserved)
				{
					if ((itemDataManifest[i].minimumDepth <= getAdjustedItemDepth && (itemDataManifest[i].maximumDepth >= getAdjustedItemDepth || itemDataManifest[i].maximumDepth == 0)) || (flag && itemDataManifest[i].minimumDepth <= getAdjustedItemDepth))
					{
						int num6 = 1000 - itemDataManifest[i].rarity;
						if (num6 > 0)
						{
							weaponRandomizer.AddChoice(i, num6);
							rareWeaponRandomizer.AddChoice(i, num6);
						}
					}
					else if ((itemDataManifest[i].minimumDepth - 5 <= getAdjustedItemDepth && (itemDataManifest[i].maximumDepth - 5 >= getAdjustedItemDepth || itemDataManifest[i].maximumDepth == 0)) || (flag && itemDataManifest[i].minimumDepth - 5 <= getAdjustedItemDepth))
					{
						int num7 = 1000 - itemDataManifest[i].rarity;
						if (num7 > 0)
						{
							rareWeaponRandomizer.AddChoice(i, num7);
						}
					}
				}
				if (itemDataManifest[i].ItemCategory != ItemCategory.Container || itemDataManifest[i].reserved || ((itemDataManifest[i].itemType == ItemType.ChestSmallLocked || itemDataManifest[i].itemType == ItemType.ChestMediumLocked || itemDataManifest[i].itemType == ItemType.ChestLargeLocked) && SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm != RealmData.RealmId.HauntedPalace && SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm != RealmData.RealmId.CavernsLivingFire && SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm != RealmData.RealmId.Ekbatan && SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm != RealmData.RealmId.TkalaCrypt) || ((itemDataManifest[i].minimumDepth > getAdjustedItemDepth || (itemDataManifest[i].maximumDepth < getAdjustedItemDepth && itemDataManifest[i].maximumDepth != 0)) && (!flag || itemDataManifest[i].minimumDepth > getAdjustedItemDepth)))
				{
					continue;
				}
				int num8 = 1000 - itemDataManifest[i].rarity;
				if (num8 > 0)
				{
					if (itemDataManifest[i].itemType == ItemType.Container)
					{
						barrelRandomizer.AddChoice(i, num8);
					}
					else
					{
						containerRandomizer.AddChoice(i, num8);
					}
				}
			}
			int depth = ((getAdjustedItemDepth <= 3) ? 3 : getAdjustedItemDepth);
			fishingRandomizer = ActiveLevel.GenerateFishingRandomizer(depth, flag);
		}

		private ItemData GetRandomItemData(Randomizer randomizer)
		{
			int random = randomizer.GetRandom();
			if (random == -1)
			{
				UnityEngine.Debug.LogError("ItemData not found! Problem with the randomizer, probably it has no entries.");
				return null;
			}
			return itemDataManifest[random];
		}

