		private CellTypes PositionType(Vector3 position)
		{
			int num = (int)Math.Floor(position.x / activeTemplate.tileWidth);
			int num2 = (int)Math.Floor((0f - position.z) / activeTemplate.tileWidth);
			if (num < 0 || num2 < 0 || num >= activeDungeon.GetMazeWidth() || num2 >= activeDungeon.GetMazeHeight())
			{
				return CellTypes.Solid;
			}
			return activeDungeon.CellType(num, num2);
		}

		private MazeCreation.CellData PositionCellData(Vector3 position)
		{
			int num = (int)Math.Floor(position.x / activeTemplate.tileWidth);
			int num2 = (int)Math.Floor((0f - position.z) / activeTemplate.tileWidth);
			if (num < 0 || num2 < 0 || num >= activeDungeon.GetMazeWidth() || num2 >= activeDungeon.GetMazeHeight())
			{
				return default(MazeCreation.CellData);
			}
			return activeDungeon.GetCellDataFromPosition(num, num2);
		}

		private float FloorHeight(float WorldSpaceX, float WorldSpaceY)
		{
			if (Physics.Raycast(direction: new Vector3(0f, -1f, 0f), origin: new Vector3(WorldSpaceX, 100f, WorldSpaceY), hitInfo: out var hitInfo, maxDistance: 100f))
			{
				return hitInfo.point.y;
			}
			return 0f;
		}

		public void PlayDungeonMusic()
		{
			SingletonBehaviour<AudioManager>.Instance.StopMusic();
			musicClips = activeTemplate.musicClips;
			if (musicClips == null || musicClips.Count <= 0)
			{
				return;
			}
			int index = UnityEngine.Random.Range(0, musicClips.Count);
			if (audioSource.isPlaying)
			{
				if (audioSource.clip == musicClips[index])
				{
					return;
				}
				audioSource.clip = musicClips[index];
				audioSource.Play();
			}
			else
			{
				audioSource.clip = musicClips[index];
				audioSource.Play();
			}
			if (activeTemplate.AmbientSoundData != 0)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAmbiance(activeTemplate.AmbientSoundData);
			}
		}

		public void StopDungeonMusic()
		{
			audioSource.Stop();
			SingletonBehaviour<AudioManager>.Instance.StopAudioClip(activeTemplate.AmbientSoundData);
		}

		private IEnumerator ApplyNoiseToStaticMeshes(Action onDone)
		{
			CleanupNoiseMeshes(null);
			while (isCleaningUpNoiseMeshes)
			{
				yield return null;
			}
			progress = 0f;
			MeshFilter[] meshFilters = UnityEngine.Object.FindObjectsOfType<MeshFilter>();
			int filterPerFrame = 50;
			for (int i = 0; i < meshFilters.Length; i++)
			{
				MeshFilter filter = meshFilters[i];
				if (filter == null)
				{
					continue;
				}
				filterPerFrame--;
				if (filterPerFrame <= 0)
				{
					filterPerFrame = 50;
					yield return null;
				}
				progress = Mathf.Clamp((float)i / (float)meshFilters.Length, 0f, 1f);
				if (filter == null || filter == null)
				{
					continue;
				}
				Mesh sharedMesh = filter.sharedMesh;
				if (!(sharedMesh == null) && sharedMesh.isReadable && sharedMesh.vertexCount != 0)
				{
					Mesh mesh = UnityEngine.Object.Instantiate(sharedMesh);
					runtimeMeshes.Add(mesh);
					filter.mesh = mesh;
					Vector3[] vertices = mesh.vertices;
					Vector3[] vertices2 = mesh.vertices;
					ComputeBuffer computeBuffer = new ComputeBuffer(vertices.Length, 12);
					ComputeBuffer computeBuffer2 = new ComputeBuffer(vertices2.Length, 12);
					computeBuffer.SetData(vertices);
					computeBuffer2.SetData(vertices2);
					int kernelIndex = heightNoiseComputeShader.FindKernel("ApplyHeightNoise");
					heightNoiseComputeShader.SetBuffer(kernelIndex, "vertices", computeBuffer);
					heightNoiseComputeShader.SetBuffer(kernelIndex, "initialVertices", computeBuffer2);
					heightNoiseComputeShader.SetInt("vertCount", vertices.Length);
					heightNoiseComputeShader.SetFloat("maxHeight", maxHeight);
					heightNoiseComputeShader.SetFloat("minHeight", minHeight);
					heightNoiseComputeShader.SetFloat("noiseFrequency", noiseFrequency);
					heightNoiseComputeShader.SetFloat("noiseAmplitude", noiseAmplitude);
					Matrix4x4 localToWorldMatrix = filter.transform.localToWorldMatrix;
					Matrix4x4 worldToLocalMatrix = filter.transform.worldToLocalMatrix;
					heightNoiseComputeShader.SetMatrix("objectToWorld", localToWorldMatrix);
					heightNoiseComputeShader.SetMatrix("worldToObject", worldToLocalMatrix);
					int threadGroupsX = Mathf.CeilToInt((float)vertices.Length / 256f);
					heightNoiseComputeShader.Dispatch(kernelIndex, threadGroupsX, 1, 1);
					computeBuffer.GetData(vertices);
					mesh.vertices = vertices;
					mesh.RecalculateNormals();
					computeBuffer.Release();
					computeBuffer2.Release();
					MeshCollider component = filter.GetComponent<MeshCollider>();
					if (component != null)
					{
						component.sharedMesh = null;
						component.sharedMesh = mesh;
					}
				}
			}
			onDone();
		}

		private void CleanupNoiseMeshes(Action onDone)
		{
			StartCoroutine(DoCleanupNoiseMeshes(onDone));
		}

		private IEnumerator DoCleanupNoiseMeshes(Action onDone)
		{
			if (isCleaningUpNoiseMeshes)
			{
				yield break;
			}
			isCleaningUpNoiseMeshes = true;
			cleanupNoiseMeshesProgress = 0f;
			int counter = 0;
			int i = 0;
			while (i < runtimeMeshes.Count)
			{
				UnityEngine.Object.Destroy(runtimeMeshes[i]);
				int num = counter + 1;
				counter = num;
				if (counter >= 300)
				{
					counter = 0;
					cleanupNoiseMeshesProgress = Mathf.Clamp01((float)i / (float)runtimeMeshes.Count);
					yield return null;
				}
				num = i + 1;
				i = num;
			}
			runtimeMeshes.Clear();
			isCleaningUpNoiseMeshes = false;
			cleanupNoiseMeshesProgress = 1f;
			onDone?.Invoke();
		}
	}
	public class MagicAnvilInteractable : InteractableSceneObject
	{
		private bool used;

		private AudioSource audioSource;

		public ParticleSystem chargedParticles;

		private void Awake()
		{
			base.InteractableName = I2Loca.Get("Item_MagicAnvil");
			audioSource = GetComponentInParent<AudioSource>();
		}

		private void OnDestroy()
		{
			UnSubscribe();
		}

		public override void Interact(Character interactor = null)
		{
			if (!used)
			{
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_temptfate);
				ItemSelectionUI itemSelection = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.itemSelection;
				itemSelection.onUsed = (Action)Delegate.Combine(itemSelection.onUsed, new Action(OnUsed));
				ItemSelectionUI itemSelection2 = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.itemSelection;
				itemSelection2.onCancel = (Action)Delegate.Combine(itemSelection2.onCancel, new Action(OnCancel));
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.onClosedTabs = (Action)Delegate.Combine(instance.onClosedTabs, new Action(OnCancel));
				SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.SetItemSelectType(MerchantType.MagicAnvil);
				SimpleSingletonBehaviour<PlayerUI>.Instance.ShowInventory(PlayerUI.InventoryStateType.ItemSelect);
			}
		}

		public void SetUsed()
		{
			audioSource.Stop();
			used = true;
			if (chargedParticles != null)
			{
				chargedParticles.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
			}
			CanInteract = false;
		}

		private void OnUsed()
		{
			audioSource.Stop();
			used = true;
			if (chargedParticles != null)
			{
				chargedParticles.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
			}
			LevelGenerator.currentInstance.OnUsedMagicAnvil();
			UnSubscribe();
			CanInteract = false;
		}

		private void OnCancel()
		{
			UnSubscribe();
		}

		private void UnSubscribe()
		{
			if (SingletonBehaviour<PlayerUI>.InstanceExists() && SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI != null)
				{
					ItemSelectionUI itemSelection = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.itemSelection;
					itemSelection.onUsed = (Action)Delegate.Remove(itemSelection.onUsed, new Action(OnUsed));
					ItemSelectionUI itemSelection2 = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.itemSelection;
					itemSelection2.onCancel = (Action)Delegate.Remove(itemSelection2.onCancel, new Action(OnCancel));
				}
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.onClosedTabs = (Action)Delegate.Remove(instance.onClosedTabs, new Action(OnCancel));
			}
		}
	}
