	public class MazeCreation
	{
		public struct CellData
		{
			public short cellheightData;

			public short wallTypeData;

			public int terrainTypeData;

			public int roomIndexData;

			public int pitIndexData;

			public float heightData;

			public float xOffsetData;

			public float yOffsetData;

			public bool cellHasWater;

			public bool cellIsFishable;

			public bool cellHasCollideableProp;

			public bool cellVisited;

			public CellTypes cellType;
		}

		public struct RoomData
		{
			public bool roomIsolated;

			public int roomX;

			public int roomY;

			public int roomWidth;

			public int roomHeight;

			public int roomExits;

			public int roomCharLimit;

			public int roomCharCount;
		}

		public struct PitsData
		{
			public int pitX;

			public int pitY;

			public int pitWidth;

			public int pitHeight;

			public bool waterFilled;

			public bool waterFree;

			public bool floorCreated;
		}

		private TemplateData template;

		private float distributionModifier;

		private float worldLocationX;

		private float worldLocationZ;

		private int mazeWidth;

		private int mazeHeight;

		private int sparseness;

		private int roundedness;

		private int connectedness;

		private int twistiness;

		private int rooms;

		private int minimumRoomWidth;

		private int maximumRoomWidth;

		private int minimumRoomHeight;

		private int maximumRoomHeight;

		private int pits;

		private int minimumPitWidth;

		private int maximumPitWidth;

		private int minimumPitHeight;

		private int maximumPitHeight;

		private int cellsVisited;

		private short terrainTypes;

		private float heightDistortion;

		private float xyDistortion;

		private List<CellData> cells;

		private List<RoomData> roomsData;

		private List<PitsData> pitsData;

		private List<RuntimePropData> propsData;

		private Vector3 playerSpawnPointDown;

		private Vector3 playerSpawnPointUp;

		private int stairsMinDistanceToEdge = 3;

		public MazeCreation()
		{
		}

		public MazeCreation(TemplateData chosenTemplate, float mazeLocationX, float mazeLocationZ)
		{
			template = chosenTemplate;
			worldLocationX = mazeLocationX;
			worldLocationZ = mazeLocationZ;
			distributionModifier = 2f;
			if (template == null)
			{
				mazeWidth = 32;
				mazeHeight = 32;
				heightDistortion = 0f;
				xyDistortion = 0f;
				twistiness = 600;
				connectedness = 1000;
				sparseness = 5;
				roundedness = 0;
				minimumRoomWidth = 3;
				maximumRoomWidth = 8;
				minimumRoomHeight = 3;
				maximumRoomHeight = 9;
				minimumPitWidth = 2;
				maximumPitWidth = 6;
				minimumPitHeight = 2;
				maximumPitHeight = 6;
				rooms = 8;
				pits = 8;
				terrainTypes = 0;
			}
			else
			{
				mazeWidth = UnityEngine.Random.Range(template.minimumWidth, template.maximumWidth);
				mazeHeight = UnityEngine.Random.Range(template.minimumHeight, template.maximumHeight);
				heightDistortion = template.heightDistortion;
				xyDistortion = template.XYDistortion;
				twistiness = UnityEngine.Random.Range(template.minimumTwistiness, template.maximumTwistiness);
				connectedness = UnityEngine.Random.Range(template.minimumConnectedness, template.maximumConnectedness);
				sparseness = UnityEngine.Random.Range(template.minimumSparseness, template.maximumSparseness);
				roundedness = UnityEngine.Random.Range(template.minimumRoundedness, template.maximumRoundedness);
				minimumRoomWidth = template.minimumRoomWidth;
				maximumRoomWidth = template.maximumRoomWidth;
				minimumRoomHeight = template.minimumRoomHeight;
				maximumRoomHeight = template.maximumRoomHeight;
				minimumPitWidth = 2;
				maximumPitWidth = 6;
				minimumPitHeight = 2;
				maximumPitHeight = 6;
				rooms = UnityEngine.Random.Range(template.minimumRooms, template.maximumRooms);
				pits = UnityEngine.Random.Range(template.minimumPits, template.maximumPits);
				terrainTypes = 0;
				if (minimumRoomWidth < 3)
				{
					minimumRoomWidth = 3;
				}
				if (maximumRoomWidth > mazeWidth - 4)
				{
					maximumRoomWidth = mazeWidth - 4;
				}
				if (minimumRoomHeight < 3)
				{
					minimumRoomHeight = 3;
				}
				if (maximumRoomHeight > mazeHeight - 4)
				{
					maximumRoomHeight = mazeHeight - 4;
				}
			}
			cellsVisited = 0;
			roomsData = new List<RoomData>();
			pitsData = new List<PitsData>();
			cells = new List<CellData>();
			propsData = new List<RuntimePropData>();
			playerSpawnPointDown = default(Vector3);
			playerSpawnPointUp = default(Vector3);
			for (int i = 0; i < mazeWidth * mazeHeight; i++)
			{
				cells.Add(new CellData
				{
					pitIndexData = -1,
					roomIndexData = -1
				});
			}
			Generate();
		}

		public Vector3 GetPlayerSpawnPointDown()
		{
			return playerSpawnPointDown;
		}

		public Vector3 GetPlayerSpawnPointUp()
		{
			return playerSpawnPointUp;
		}

		public Vector3 GetPositionFromCellPosition(int X, int Y)
		{
			return new Vector3(worldLocationX + (float)X * template.tileWidth + template.tileWidth * 0.5f, 0f, worldLocationZ + (float)Y * (0f - template.tileWidth) - template.tileWidth * 0.5f);
		}

		public Vector2Int GetCellIndexFromPosition(int X, int Z)
		{
			return new Vector2Int((int)(((float)X - worldLocationX - template.tileWidth * 0.5f) / template.tileWidth), (int)(((float)Z - worldLocationZ + template.tileWidth * 0.5f) / (0f - template.tileWidth)));
		}

		public CellData GetCellDataFromPosition(int X, int Y)
		{
			if (X < 0)
			{
				X = 0;
			}
			else if (X >= mazeWidth)
			{
				X = mazeWidth - 1;
			}
			if (Y < 0)
			{
				Y = 0;
			}
			else if (Y >= mazeHeight)
			{
				Y = mazeHeight - 1;
			}
			return cells[X + Y * mazeWidth];
		}

		public bool IsRoomNotFull(int roomIndex)
		{
			if (roomIndex >= roomsData.Count)
			{
				return false;
			}
			return roomsData[roomIndex].roomCharCount < roomsData[roomIndex].roomCharLimit;
		}

		public int RoomExits(int roomIndex)
		{
			if (roomIndex >= roomsData.Count)
			{
				return 0;
			}
			return roomsData[roomIndex].roomExits;
		}

		public int RoomWidth(int roomIndex)
		{
			if (roomIndex >= roomsData.Count)
			{
				return 0;
			}
			return roomsData[roomIndex].roomWidth;
		}

		public int RoomHeight(int roomIndex)
		{
			if (roomIndex >= roomsData.Count)
			{
				return 0;
			}
			return roomsData[roomIndex].roomHeight;
		}

		public void AddCharToRoomCount(int roomIndex)
		{
			if (roomIndex < roomsData.Count)
			{
				RoomData value = roomsData[roomIndex];
				value.roomCharCount++;
				roomsData[roomIndex] = value;
			}
		}

		public PitsData GetPitDataFromCellPosition(int X, int Y)
		{
			CellData cellDataFromPosition = GetCellDataFromPosition(X, Y);
			if (cellDataFromPosition.pitIndexData != -1)
			{
				return pitsData[cellDataFromPosition.pitIndexData];
			}
			PitsData result = default(PitsData);
			result.pitHeight = -1;
			result.pitWidth = -1;
			return result;
		}

		public void UpdatePitData(PitsData newData, int X, int Y)
		{
			CellData cellDataFromPosition = GetCellDataFromPosition(X, Y);
			if (cellDataFromPosition.pitIndexData != -1)
			{
				pitsData[cellDataFromPosition.pitIndexData] = newData;
			}
		}

		public int GetMazeWidth()
		{
			return mazeWidth;
		}

		public int GetMazeHeight()
		{
			return mazeHeight;
		}

		public List<RuntimePropData> GetProps()
		{
			return propsData;
		}

		private void Generate()
		{
			FillMaze(1);
			for (int i = 0; i < mazeWidth; i++)
			{
				VisitCell(i, 0);
				VisitCell(i, mazeHeight - 1);
			}
			for (int i = 0; i < mazeHeight; i++)
			{
				VisitCell(0, i);
				VisitCell(mazeWidth - 1, i);
			}
			GenerateCorridors();
			Sparsify();
			if (template.useExtraGeneration)
			{
				ConnectDeadEnds();
			}
			GenerateRooms(rooms);
			CountRoomsExits();
			for (int i = 0; i < Rooms(); i++)
			{
				if (roomsData[i].roomExits == 0 && !roomsData[i].roomIsolated)
				{
					RoomData roomData = default(RoomData);
					roomData = roomsData[i];
					roomData.roomIsolated = true;
					roomsData[i] = roomData;
				}
			}
			ConnectIsolatedRooms();
			ConnectDeadEnds();
			GeneratePits(pits);
			VerifyWalls();
			PlugHoles();
			GenerateExits();
			SetWallBorders();
			CountRoomsExits();
			if (template.useExtraGeneration)
			{
				for (int i = 0; i < Rooms(); i++)
				{
					if (roomsData[i].roomExits == 0 && !roomsData[i].roomIsolated)
					{
						RoomData roomData2 = default(RoomData);
						roomData2 = roomsData[i];
						roomData2.roomIsolated = true;
						roomsData[i] = roomData2;
					}
				}
				ConnectIsolatedRooms();
				ConnectDeadEnds();
			}
			GenerateDoors();
			GenerateProps();
		}

		private void GenerateProps()
		{
			template.ResetCounters();
			for (int i = 1; i < mazeWidth - 1; i++)
			{
				for (int j = 1; j < mazeHeight - 1; j++)
				{
					CellTypes cellTypes = CellType(i, j);
					if (!CellOpenIgnoreDoors(i, j) && !HasWater(i, j) && cellTypes != CellTypes.Pit)
					{
						continue;
					}
					bool flag = true;
					PropLocation propLocation = PropLocation.Room;
					PropLocation propLocation2 = PropLocation.Anywhere;
					CellData cellDataFromPosition = GetCellDataFromPosition(i, j);
					switch (cellTypes)
					{
					case CellTypes.Pit:
						if (!IsCliff(i, j) && CellHeight(i, j) < 0)
						{
							if (cellDataFromPosition.pitIndexData < 0 || cellDataFromPosition.pitIndexData >= pitsData.Count)
							{
								UnityEngine.Debug.LogError($"Critical error! Cell pit index data out of range! index is {cellDataFromPosition.pitIndexData}, pit data count is {pitsData.Count}. This can mess up the maze generation completely. Template is {template.name}, seed is {LevelGenerator.currentInstance.currentSeed}", template);
								continue;
							}
							if (!pitsData[cellDataFromPosition.pitIndexData].waterFree && template.hasWater && !pitsData[cellDataFromPosition.pitIndexData].waterFilled && HasWater(i, j))
							{
								propLocation = PropLocation.Water;
								if (UnityEngine.Random.Range(0, 10) > 2)
								{
									flag = false;
								}
							}
							else if (!pitsData[cellDataFromPosition.pitIndexData].waterFilled)
							{
								if (!pitsData[cellDataFromPosition.pitIndexData].waterFree)
								{
									PitsData value = pitsData[cellDataFromPosition.pitIndexData];
									value.waterFree = true;
									pitsData[cellDataFromPosition.pitIndexData] = value;
								}
								propLocation = PropLocation.Pit;
								if (UnityEngine.Random.Range(0, 10) > 5)
								{
									flag = false;
								}
							}
						}
						else
						{
							flag = false;
						}
						break;
					case CellTypes.NSDoor:
						propLocation = PropLocation.NSDoor;
						break;
					case CellTypes.EWDoor:
						propLocation = PropLocation.EWDoor;
						break;
					case CellTypes.Room:
						propLocation = PropLocation.Room;
						if (CellType(i, j + 1) == CellTypes.RoomWall)
						{
							propLocation = PropLocation.SouthWall;
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								propLocation2 = PropLocation.SouthTorch;
							}
						}
						if (CellType(i + 1, j) == CellTypes.RoomWall)
						{
							propLocation = PropLocation.EastWall;
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								propLocation2 = PropLocation.EastTorch;
							}
						}
						if (CellType(i - 1, j) == CellTypes.RoomWall)
						{
							propLocation = PropLocation.WestWall;
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								propLocation2 = PropLocation.WestTorch;
							}
						}
						if (CellType(i, j - 1) == CellTypes.RoomWall)
						{
							propLocation = PropLocation.NorthWall;
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								propLocation2 = PropLocation.NorthTorch;
							}
						}
						if (UnityEngine.Random.Range(0, 100) <= 70)
						{
							flag = false;
						}
						if (CellType(i - 1, j) == CellTypes.EWDoor || CellType(i + 1, j) == CellTypes.EWDoor || CellType(i, j - 1) == CellTypes.NSDoor || CellType(i, j + 1) == CellTypes.NSDoor)
						{
							flag = false;
						}
						if (CellType(i - 1, j) == CellTypes.StairwellUp || CellType(i + 1, j) == CellTypes.StairwellUp || CellType(i, j - 1) == CellTypes.StairwellUp || CellType(i, j + 1) == CellTypes.StairwellUp)
						{
							flag = false;
						}
						if (CellType(i - 1, j) == CellTypes.StairwellDown || CellType(i + 1, j) == CellTypes.StairwellDown || CellType(i, j - 1) == CellTypes.StairwellDown || CellType(i, j + 1) == CellTypes.StairwellDown)
						{
							flag = false;
						}
						if (IsCliff(i, j) && propLocation == PropLocation.Room)
						{
							flag = false;
						}
						break;
					case CellTypes.Hall:
						propLocation = PropLocation.Hall;
						if (CellType(i, j + 1) == CellTypes.Solid)
						{
							propLocation = PropLocation.SouthHallWall;
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								propLocation2 = PropLocation.SouthTorch;
							}
						}
						if (CellType(i + 1, j) == CellTypes.Solid)
						{
							propLocation = PropLocation.EastHallWall;
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								propLocation2 = PropLocation.EastTorch;
							}
						}
						if (CellType(i, j - 1) == CellTypes.Solid)
						{
							propLocation = PropLocation.NorthHallWall;
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								propLocation2 = PropLocation.NorthTorch;
							}
						}
						if (CellType(i - 1, j) == CellTypes.Solid)
						{
							propLocation = PropLocation.WestHallWall;
							if (UnityEngine.Random.Range(0, 100) < 50)
							{
								propLocation2 = PropLocation.WestTorch;
							}
						}
						if (UnityEngine.Random.Range(0, 100) <= 50)
						{
							flag = false;
						}
						if (CellType(i - 1, j) == CellTypes.EWDoor || CellType(i + 1, j) == CellTypes.EWDoor || CellType(i, j - 1) == CellTypes.NSDoor || CellType(i, j + 1) == CellTypes.NSDoor)
						{
							flag = false;
						}
