		private void FillMaze(short Value)
		{
			cellsVisited = 0;
			for (int i = 0; i < mazeWidth; i++)
			{
				for (int j = 0; j < mazeHeight; j++)
				{
					SetFloorHeight(i, j, (UnityEngine.Random.Range(0f, 1000f) / 1000f - 0.5f) * heightDistortion);
					SetOffset(i, j, (UnityEngine.Random.Range(0f, 1000f) - 0.5f) * xyDistortion, (UnityEngine.Random.Range(0f, 1000f) - 0.5f) * xyDistortion);
					SetCellHeight(i, j, Value);
					int num = template.RandomTerrain();
					if (num >= terrainTypes)
					{
						num = 0;
					}
					SetTerrainType(i, j, num);
					SetWallType(i, j, 0);
					UnVisitCell(i, j);
					SetCellType(i, j, CellTypes.Solid);
					SetHasWater(i, j, Value: false);
					SetIsFishable(i, j, Value: false);
					SetHasCollideableProp(i, j, Value: false);
					SetRoomIndexData(i, j, -1);
				}
			}
		}

