		private void SetWallBorders()
		{
			for (int i = 0; i < template.floorTiles.Count; i++)
			{
				for (int j = 0; j < mazeWidth; j++)
				{
					for (int k = 0; k < mazeHeight; k++)
					{
						if (IsCliff(j, k) && WallType(j, k) == i && CellHeight(j, k) <= 0)
						{
							SetWallBorder(j, k, (short)template.TileGroundLayers(i));
						}
					}
				}
			}
		}

		private void SetWallBorder(int X, int Y, short TerrainType)
		{
			CellHeight(X, Y);
			SetTerrainType(X, Y, TerrainType);
			SetTerrainType(X - 1, Y, TerrainType);
			SetTerrainType(X + 1, Y, TerrainType);
			SetTerrainType(X, Y - 1, TerrainType);
			SetTerrainType(X, Y + 1, TerrainType);
		}

		private void GenerateCorridors()
		{
			int X = 0;
			int Y = 0;
			SelectRandomUnvisitedCell(ref X, ref Y);
			VisitCell(X, Y);
			SetCellHeight(X, Y, 0);
			SetCellType(X, Y, CellTypes.Hall);
			VisitCell(X, Y - 1);
			VisitCell(X, Y + 1);
			VisitCell(X - 1, Y);
			VisitCell(X + 1, Y);
			int num = UnityEngine.Random.Range(0, 4);
			if (num > 3)
			{
				num = 3;
			}
			int num2 = 0;
			while (cellsVisited < mazeWidth * mazeHeight - 4 && num2 < 10000)
			{
				if (cellsVisited > mazeWidth * mazeHeight - 20)
				{
					num2++;
				}
				int X2 = 0;
				int Y2 = 0;
				if (UnityEngine.Random.Range(0, 1000) < twistiness)
				{
					num = UnityEngine.Random.Range(0, 4);
					if (num > 3)
					{
						num = 3;
					}
				}
				bool flag = false;
				List<bool> list = new List<bool>();
				for (int i = 0; i < 4; i++)
				{
					list.Add(item: false);
				}
				int num3 = 0;
				while (!flag)
				{
					if (list[0] && list[1] && list[2] && list[3])
					{
						SelectRandomCell(ref X2, ref Y2, 0);
						break;
					}
					X2 = X;
					Y2 = Y;
					if (list[num])
					{
						num = UnityEngine.Random.Range(0, 4);
						int num4 = 0;
						while (num < list.Count && list[num])
						{
							num4++;
							num = ((num4 <= 500) ? UnityEngine.Random.Range(0, 4) : (num + 1));
						}
						if (num > 3)
						{
							num = 3;
						}
						num3++;
						if (num3 > 1000)
						{
							SelectRandomCell(ref X2, ref Y2, 0);
							break;
						}
					}
					else
					{
						list[num] = true;
						switch (num)
						{
						case 0:
							Y2--;
							break;
						case 2:
							X2++;
							break;
						case 1:
							Y2++;
							break;
						case 3:
							X2--;
							break;
						}
					}
					flag = true;
					if (X2 < 1 || Y2 < 1 || X2 >= mazeWidth - 1 || Y2 >= mazeHeight - 1)
					{
						flag = false;
						continue;
					}
					if (CellHeight(X2, Y2) == 0)
					{
						flag = false;
					}
					if (flag && (X2 - 1 != X || Y2 != Y) && CellHeight(X2 - 1, Y2) == 0)
					{
						flag = false;
					}
					if (flag && (X2 + 1 != X || Y2 != Y) && CellHeight(X2 + 1, Y2) == 0)
					{
						flag = false;
					}
					if (flag && (X2 != X || Y2 - 1 != Y) && CellHeight(X2, Y2 - 1) == 0)
					{
						flag = false;
					}
					if (flag && (X2 != X || Y2 + 1 != Y) && CellHeight(X2, Y2 + 1) == 0)
					{
						flag = false;
					}
				}
				X = X2;
				Y = Y2;
				SetCellHeight(X2, Y2, 0);
				SetCellType(X2, Y2, CellTypes.Hall);
				VisitCell(X2, Y2);
				VisitCell(X2, Y2 - 1);
				VisitCell(X2, Y2 + 1);
				VisitCell(X2 - 1, Y2);
				VisitCell(X2 + 1, Y2);
				VisitCell(X2 - 1, Y2 - 1);
				VisitCell(X2 - 1, Y2 + 1);
				VisitCell(X2 + 1, Y2 - 1);
				VisitCell(X2 + 1, Y2 + 1);
			}
		}

		private void Sparsify()
		{
			int num = 0;
			for (int i = 0; i < mazeWidth; i++)
			{
				for (int j = 0; j < mazeHeight; j++)
				{
					if (CellHeight(i, j) == 0)
					{
						num++;
					}
				}
			}
			for (int k = 0; k < sparseness; k++)
			{
				for (int l = 0; l < mazeWidth; l++)
				{
					for (int m = 0; m < mazeHeight; m++)
					{
						if (CountExits(l, m) == 1 && CellType(l, m) != 0 && num > 100)
						{
							num--;
							SetCellHeight(l, m, 1);
							SetCellType(l, m, CellTypes.Solid);
						}
					}
				}
			}
		}

		private void PlugHoles()
		{
			for (int i = 0; i < mazeWidth; i++)
			{
				for (int j = 0; j < mazeHeight; j++)
				{
					int num = CountExits(i, j);
					if (CellHeight(i, j) == 0 && CellHeight(i - 1, j) < 0 && CellHeight(i + 1, j) < 0 && CellHeight(i, j - 1) < 0 && CellHeight(i, j + 1) < 0)
					{
						SetCellHeight(i, j, -1);
						SetCellType(i, j, CellTypes.Pit);
						SetHasWater(i, j, template.hasWater);
						SetHasWater(i - 1, j, template.hasWater);
						SetHasWater(i + 1, j, template.hasWater);
						SetHasWater(i, j - 1, template.hasWater);
						SetHasWater(i, j + 1, template.hasWater);
						SetHasWater(i - 1, j - 1, template.hasWater);
						SetHasWater(i + 1, j - 1, template.hasWater);
						SetHasWater(i - 1, j + 1, template.hasWater);
						SetHasWater(i + 1, j + 1, template.hasWater);
					}
					if (num == 0 && CellHeight(i, j) == 0)
					{
						SetCellHeight(i, j, 1);
						SetCellType(i, j, CellTypes.Solid);
					}
					else if (num == 1 && CellHeight(i, j) == 0 && CellHeight(i - 1, j) > 0 && CellHeight(i + 1, j) > 0 && CellHeight(i, j - 1) > 0 && CellHeight(i, j + 1) > 0)
					{
						SetCellHeight(i, j, 1);
						SetCellType(i, j, CellTypes.Solid);
					}
				}
			}
		}

		private void RaiseRoof()
		{
			for (int i = 0; i < mazeWidth; i++)
			{
				for (int j = 0; j < mazeHeight; j++)
				{
					if (CellHeight(i, j) == 1 && CellHeight(i - 1, j) >= 1 && CellHeight(i + 1, j) >= 1 && CellHeight(i, j - 1) >= 1 && CellHeight(i, j + 1) >= 1 && CellHeight(i - 1, j - 1) >= 1 && CellHeight(i + 1, j - 1) >= 1 && CellHeight(i - 1, j + 1) >= 1 && CellHeight(i + 1, j + 1) >= 1)
					{
						SetCellHeight(i, j, 2);
					}
					else if (CellHeight(i, j) == -1 && CellHeight(i - 1, j) <= -1 && CellHeight(i + 1, j) <= -1 && CellHeight(i, j - 1) <= -1 && CellHeight(i, j + 1) <= -1 && CellHeight(i - 1, j - 1) <= -1 && CellHeight(i + 1, j - 1) <= -1 && CellHeight(i - 1, j + 1) <= -1 && CellHeight(i + 1, j + 1) <= -1)
					{
						SetCellHeight(i, j, -2);
					}
				}
			}
		}

		private int CountExits(int X, int Y)
		{
			int num = 0;
			if (CellHeight(X, Y) == 0)
			{
				if (CellHeight(X, Y - 1) == 0)
				{
					num++;
				}
				if (CellHeight(X, Y + 1) == 0)
				{
					num++;
				}
				if (CellHeight(X - 1, Y) == 0)
				{
					num++;
				}
				if (CellHeight(X + 1, Y) == 0)
				{
					num++;
				}
				if (num == 0)
				{
					if (CellHeight(X - 1, Y - 1) == 0)
					{
						num = 1;
					}
					if (CellHeight(X + 1, Y - 1) == 0)
					{
						num = 1;
					}
					if (CellHeight(X - 1, Y + 1) == 0)
					{
						num = 1;
					}
					if (CellHeight(X + 1, Y + 1) == 0)
					{
						num = 1;
					}
				}
			}
			return num;
		}

		private int CountHallWayExits(int X, int Y)
		{
			int num = 0;
			if (CellHeight(X, Y) == 0)
			{
				if (CellHeight(X, Y - 1) == 0 && CellType(X, Y) == CellTypes.Hall)
				{
					num++;
				}
				if (CellHeight(X, Y + 1) == 0 && CellType(X, Y) == CellTypes.Hall)
				{
					num++;
				}
				if (CellHeight(X - 1, Y) == 0 && CellType(X, Y) == CellTypes.Hall)
				{
					num++;
				}
				if (CellHeight(X + 1, Y) == 0 && CellType(X, Y) == CellTypes.Hall)
				{
					num++;
				}
			}
			return num;
		}

		private void ConnectDeadEnds()
		{
			int num = UnityEngine.Random.Range(0, 4);
			int num2 = num;
			for (int i = 1; i < mazeWidth - 1; i++)
			{
				for (int j = 1; j < mazeHeight - 1; j++)
				{
					if (CountExits(i, j) != 1 || CellType(i, j) != CellTypes.Hall || UnityEngine.Random.Range(0, 1000) >= connectedness)
					{
						continue;
					}
					int num3 = i;
					int num4 = j;
					bool flag = false;
					while (!flag)
					{
						if (UnityEngine.Random.Range(0, 1000) < twistiness)
						{
							num = UnityEngine.Random.Range(0, 4);
							while ((num2 == 0 && num == 1) || (num2 == 1 && num == 0) || (num2 == 2 && num == 3) || (num2 == 3 && num == 2))
							{
								num = UnityEngine.Random.Range(0, 4);
							}
							num2 = num;
						}
						bool flag2 = false;
						while (!flag2)
						{
							int num5 = num3;
							int num6 = num4;
							switch (num)
							{
							case 0:
								num4--;
								break;
							case 2:
								num3++;
								break;
							case 1:
								num4++;
								break;
							case 3:
								num3--;
								break;
							}
							flag2 = true;
							if (num3 < 1 || num4 < 1 || num3 >= mazeWidth - 1 || num4 >= mazeHeight - 1)
							{
								num = UnityEngine.Random.Range(0, 4);
								while ((num2 == 0 && num == 1) || (num2 == 1 && num == 0) || (num2 == 2 && num == 3) || (num2 == 3 && num == 2))
								{
									num = UnityEngine.Random.Range(0, 4);
								}
								num2 = num;
								num3 = num5;
								num4 = num6;
								flag2 = false;
							}
						}
						if (CellHeight(num3, num4) == 0 && CountHallWayExits(num3, num4) > 1)
						{
							flag = true;
						}
						if (CellHeight(num3, num4) != 0)
						{
							SetCellHeight(num3, num4, 0);
							SetCellType(num3, num4, CellTypes.Hall);
						}
					}
				}
			}
		}

		private void CountRoomsExits()
		{
			for (int i = 0; i < Rooms(); i++)
			{
				int num = 0;
				for (int j = 0; j < mazeHeight; j++)
				{
					for (int k = 0; k < mazeWidth; k++)
					{
						if (CellHeight(k, j) == 0 && RoomIndexData(k, j) == i)
						{
							if (CellHeight(k, j - 1) == 0 && CellType(k, j - 1) == CellTypes.Hall)
							{
								num++;
							}
							if (CellHeight(k, j + 1) == 0 && CellType(k, j + 1) == CellTypes.Hall)
							{
								num++;
							}
							if (CellHeight(k - 1, j) == 0 && CellType(k - 1, j) == CellTypes.Hall)
							{
								num++;
							}
							if (CellHeight(k + 1, j) == 0 && CellType(k + 1, j) == CellTypes.Hall)
							{
								num++;
							}
						}
					}
				}
				RoomData roomData = default(RoomData);
				roomData = roomsData[i];
				roomData.roomExits = num;
				roomsData[i] = roomData;
			}
		}

		private void ConnectIsolatedRooms()
		{
			for (int i = 0; i < roomsData.Count; i++)
			{
				if (!roomsData[i].roomIsolated)
				{
					continue;
				}
				int num = -1;
				for (int j = 0; j < roomsData.Count; j++)
				{
					if (j != i && !roomsData[j].roomIsolated && UnityEngine.Random.Range(0, 1000) < 100)
					{
						num = j;
					}
				}
				if (num != -1)
				{
					int num2 = roomsData[i].roomX;
					int num3 = roomsData[i].roomY;
					bool flag = false;
					while (!flag)
					{
						if (num2 < roomsData[num].roomX)
						{
							num2++;
						}
						else if (num2 > roomsData[num].roomX)
						{
							num2--;
						}
						else if (num3 < roomsData[num].roomY)
						{
							num3++;
						}
						else if (num3 > roomsData[num].roomY)
						{
							num3--;
						}
						if (CellHeight(num2, num3) == 0 && RoomIndexData(num2, num3) != i && (CellType(num2, num3) == CellTypes.Hall || RoomIndexData(num2, num3) >= 0))
						{
							flag = true;
							if (RoomIndexData(num2, num3) != -1 && roomsData[RoomIndexData(num2, num3)].roomIsolated)
							{
								flag = false;
							}
						}
						if (num2 == roomsData[num].roomX && num3 == roomsData[num].roomY)
						{
							flag = true;
						}
						if (flag)
						{
							RoomData roomData = default(RoomData);
							roomData = roomsData[i];
							roomData.roomIsolated = false;
							roomsData[i] = roomData;
						}
						if (CellHeight(num2, num3) != 0 && (CellType(num2, num3) == CellTypes.Solid || CellType(num2, num3) == CellTypes.RoomWall))
						{
							SetCellType(num2, num3, CellTypes.Hall);
						}
						SetCellHeight(num2, num3, 0);
					}
					continue;
				}
				int num4 = roomsData[i].roomX;
				int num5 = roomsData[i].roomY;
				int X = 0;
				int Y = 0;
				SelectRandomCell(ref X, ref Y, 0);
				bool flag2 = false;
				while (!flag2)
				{
					if (num4 < X)
					{
						num4++;
					}
					else if (num4 > X)
					{
						num4--;
					}
					else if (num5 < Y)
					{
						num5++;
					}
					else if (num5 > Y)
					{
						num5--;
					}
					if (CellHeight(num4, num5) == 0 && RoomIndexData(num4, num5) != i && (CellType(num4, num5) == CellTypes.Hall || RoomIndexData(num4, num5) >= 0) && CountExits(num4, num5) > 1)
					{
						flag2 = true;
						if (RoomIndexData(num4, num5) != -1 && roomsData[RoomIndexData(num4, num5)].roomIsolated)
						{
							flag2 = false;
						}
					}
					if (num4 == X && num5 == Y)
					{
						if (CountHallWayExits(num4, num5) > 1)
						{
							flag2 = true;
						}
						else
						{
							SelectRandomCell(ref X, ref Y, 0);
						}
					}
					if (flag2)
					{
						RoomData roomData2 = default(RoomData);
						roomData2 = roomsData[i];
						roomData2.roomIsolated = false;
						roomsData[i] = roomData2;
					}
					if (CellHeight(num4, num5) != 0 && (CellType(num4, num5) == CellTypes.Solid || CellType(num4, num5) == CellTypes.RoomWall))
					{
						SetCellType(num4, num5, CellTypes.Hall);
					}
					SetCellHeight(num4, num5, 0);
				}
			}
		}

		private void VerifyWalls()
		{
			for (int i = 0; i < mazeWidth; i++)
			{
				for (int j = 0; j < mazeHeight; j++)
				{
					if (CellHeight(i, j) == 0 && CellType(i, j) == CellTypes.RoomWall)
					{
						SetCellType(i, j, CellTypes.Room);
					}
				}
			}
		}

		private void GenerateDoors()
		{
			for (int i = 0; i < mazeWidth; i++)
			{
				for (int j = 0; j < mazeHeight; j++)
				{
					if (CellHeight(i, j) != 0)
					{
						continue;
					}
					if (CellHeight(i - 1, j) == 0 && CellHeight(i + 1, j) == 0 && CellHeight(i, j - 1) > 0 && CellHeight(i, j + 1) > 0)
					{
						if ((CellType(i - 1, j) == CellTypes.Room || CellType(i + 1, j) == CellTypes.Room) && CellType(i - 1, j) != CellTypes.EWDoor && CellType(i + 1, j) != CellTypes.EWDoor)
						{
							SetCellType(i, j, CellTypes.EWDoor);
						}
					}
					else if (CellHeight(i, j - 1) == 0 && CellHeight(i, j + 1) == 0 && CellHeight(i - 1, j) > 0 && CellHeight(i + 1, j) > 0 && (CellType(i, j - 1) == CellTypes.Room || CellType(i, j + 1) == CellTypes.Room) && CellType(i, j - 1) != CellTypes.NSDoor && CellType(i, j + 1) != CellTypes.NSDoor)
					{
						SetCellType(i, j, CellTypes.NSDoor);
					}
				}
			}
		}

		private void GenerateRooms(int Rooms)
		{
			for (int i = 0; i < Rooms; i++)
			{
				int bestX = 1;
				int bestY = 1;
				int num = 99999999;
				int num2 = UnityEngine.Random.Range(minimumRoomWidth, maximumRoomWidth + 1);
				int num3 = UnityEngine.Random.Range(minimumRoomHeight, maximumRoomHeight + 1);
				int num4 = UnityEngine.Random.Range(0, 1000);
				int num5 = 0;
				if (num4 < 500)
				{
					num5 = 0;
				}
				else if (num4 < 750)
				{
					num5 = 1;
				}
				else
				{
					num5 = 2;
					if (num2 < 5)
					{
						num2 = 5;
					}
					if (num3 < 5)
					{
						num3 = 5;
					}
				}
				for (int j = 1; j < mazeWidth - 1 - num2; j++)
				{
					for (int k = 1; k < mazeHeight - 1 - num3; k++)
					{
						int num6 = CalculateScoreForRoom(j, k, num2, num3);
						if (num6 < num && num6 != -999)
						{
							bestX = j;
							bestY = k;
							num = num6;
						}
					}
				}
				switch (num5)
				{
				case 0:
					GenerateRoom(bestX, bestY, num2, num3);
					break;
				case 1:
					GenerateOvalRoom(bestX, bestY, num2, num3);
					break;
				default:
					GenerateRingRoom(bestX, bestY, num2, num3);
					break;
				}
			}
		}

		private void GenerateRoom(int BestX, int BestY, int Width, int Height)
		{
			bool roomIsolated = true;
			int roomX = BestX + Width / 2;
			int roomY = BestY + Height / 2;
			bool flag = UnityEngine.Random.Range(0, 100) < 70;
			int num = 0;
			for (int i = BestX - 1; i < BestX + Width + 2; i++)
			{
				for (int j = BestY - 1; j < BestY + Height + 2; j++)
				{
					if (i >= BestX && i < BestX + Width && j >= BestY && j < BestY + Height && CellType(i, j) == CellTypes.Hall)
					{
						roomIsolated = false;
					}
					if (CellType(i, j) == CellTypes.Room)
					{
						num = WallType(i, j);
						break;
					}
				}
			}
			for (int i = BestX - 1; i < BestX + Width + 2; i++)
			{
				for (int k = BestY - 1; k < BestY + Height + 2; k++)
				{
					if (CellType(i, k) != 0)
					{
						SetWallType(i, k, (short)num);
					}
				}
			}
			for (int i = BestX - 1; i < BestX + Width + 2; i++)
			{
				for (int l = BestY - 1; l < BestY + Height + 2; l++)
				{
					if ((i == BestX - 1 || i == BestX + Width + 1 || l == BestY - 1 || l == BestY + Height + 1) && CellType(i, l) != 0 && CellHeight(i, l) > 0)
					{
						SetCellType(i, l, CellTypes.RoomWall);
					}
				}
			}
			for (int i = BestX; i < BestX + Width; i++)
			{
				for (int m = BestY; m < BestY + Height; m++)
				{
					SetCellHeight(i, m, 0);
					SetCellType(i, m, CellTypes.Room);
					if (flag && (m == BestY || m == BestY + Height - 1 || i == BestX || i == BestX + Width - 1) && CellType(i - 1, m) != CellTypes.Hall && CellType(i + 1, m) != CellTypes.Hall && CellType(i, m - 1) != CellTypes.Hall && CellType(i, m + 1) != CellTypes.Hall && (RoomIndexData(i, m) < 0 || RoomIndexData(i, m) == roomsData.Count) && ((i % 2 == 0 && m % 2 != 0) || (i % 2 != 0 && m % 2 == 0)))
					{
						SetCellHeight(i, m, 1);
						SetCellType(i, m, CellTypes.RoomWall);
					}
					SetRoomIndexData(i, m, roomsData.Count);
				}
			}
			if (flag)
			{
				if (CellHeight(BestX, BestY + Height - 1) == 0 && CellHeight(BestX, BestY + Height - 2) != 0 && CellHeight(BestX + 1, BestY + Height - 1) != 0)
				{
					SetCellHeight(BestX, BestY + Height - 2, 0);
					SetCellType(BestX, BestY + Height - 2, CellTypes.Room);
				}
				if (CellHeight(BestX + Width - 1, BestY + Height - 1) == 0 && CellHeight(BestX + Width - 1, BestY + Height - 2) != 0 && CellHeight(BestX + Width - 2, BestY + Height - 1) != 0)
				{
					SetCellHeight(BestX + Width - 1, BestY + Height - 2, 0);
					SetCellType(BestX + Width - 1, BestY + Height - 2, CellTypes.Room);
				}
				if (CellHeight(BestX, BestY) == 0 && CellHeight(BestX, BestY + 1) != 0 && CellHeight(BestX + 1, BestY) != 0)
				{
					SetCellHeight(BestX, BestY + 1, 0);
					SetCellType(BestX, BestY + 1, CellTypes.Room);
				}
				if (CellHeight(BestX + Width - 1, BestY) == 0 && CellHeight(BestX + Width - 1, BestY + 1) != 0 && CellHeight(BestX + Width - 2, BestY) != 0)
				{
					SetCellHeight(BestX + Width - 1, BestY + 1, 0);
					SetCellType(BestX + Width - 1, BestY + 1, CellTypes.Room);
				}
			}
			RoomData item = default(RoomData);
			item.roomIsolated = roomIsolated;
			item.roomX = roomX;
			item.roomY = roomY;
			item.roomWidth = Width;
			item.roomHeight = Height;
			item.roomExits = 0;
			item.roomCharLimit = Mathf.RoundToInt((float)(Width + Height) / distributionModifier);
			item.roomCharCount = 0;
			roomsData.Add(item);
		}

		private void GenerateOvalRoom(int BestX, int BestY, int Width, int Height)
		{
			bool roomIsolated = true;
			int roomX = BestX + Width / 2;
			int roomY = BestY + Height / 2;
			int num = 0;
			float num2 = ((float)Width - 2f) * ((float)Width - 2f);
			float num3 = ((float)Height - 2.5f) * ((float)Height - 2.5f);
			float num4 = (float)(BestX + BestX + Width - 1) / 2f;
			float num5 = (float)(BestY + BestY + Height - 1) / 2f;
			for (int i = BestX - 1; i < BestX + Width + 2; i++)
			{
				for (int j = BestY - 1; j < BestY + Height + 2; j++)
				{
					if (((float)i - num4) * ((float)i - num4) * 100f / num2 + ((float)j - num5) * ((float)j - num5) * 100f / num3 < 50f && CellType(i, j) == CellTypes.Hall)
					{
						roomIsolated = false;
					}
					if (CellType(i, j) == CellTypes.Room)
					{
						num = WallType(i, j);
						break;
					}
				}
			}
			for (int i = BestX - 1; i < BestX + Width + 2; i++)
			{
				for (int k = BestY - 1; k < BestY + Height + 2; k++)
				{
					if (((float)i - num4) * ((float)i - num4) * 100f / num2 + ((float)k - num5) * ((float)k - num5) * 100f / num3 < 50f && CellType(i, k) != 0)
					{
						SetWallType(i, k, (short)num);
					}
				}
			}
			for (int i = BestX - 1; i < BestX + Width + 2; i++)
			{
				for (int l = BestY - 1; l < BestY + Height + 2; l++)
				{
					if (((float)i - num4) * ((float)i - num4) * 100f / num2 + ((float)l - num5) * ((float)l - num5) * 100f / num3 >= 50f && CellType(i, l) != 0 && CellHeight(i, l) > 0)
					{
						SetCellType(i, l, CellTypes.RoomWall);
					}
				}
			}
			for (int i = BestX; i < BestX + Width; i++)
			{
				for (int m = BestY; m < BestY + Height; m++)
				{
					if (((float)i - num4) * ((float)i - num4) * 100f / num2 + ((float)m - num5) * ((float)m - num5) * 100f / num3 < 50f)
					{
						SetRoomIndexData(i, m, roomsData.Count);
						SetCellHeight(i, m, 0);
						SetCellType(i, m, CellTypes.Room);
					}
				}
			}
			RoomData item = default(RoomData);
			item.roomIsolated = roomIsolated;
			item.roomX = roomX;
			item.roomY = roomY;
			item.roomWidth = Width;
			item.roomHeight = Height;
			item.roomExits = 0;
			item.roomCharLimit = Mathf.RoundToInt((float)(Width + Height) / distributionModifier);
			item.roomCharCount = 0;
			roomsData.Add(item);
		}

		private void GenerateRingRoom(int BestX, int BestY, int Width, int Height)
		{
			bool roomIsolated = true;
			int roomX = BestX + Width / 2;
			int roomY = BestY + Height / 2;
			int num = 0;
			float num2 = ((float)Width - 2f) * ((float)Width - 2f);
			float num3 = ((float)Height - 2.5f) * ((float)Height - 2.5f);
			float num4 = (float)(BestX + BestX + Width - 1) / 2f;
			float num5 = (float)(BestY + BestY + Height - 1) / 2f;
			for (int i = BestX - 1; i < BestX + Width + 2; i++)
			{
				for (int j = BestY - 1; j < BestY + Height + 2; j++)
				{
					if (((float)i - num4) * ((float)i - num4) * 100f / num2 + ((float)j - num5) * ((float)j - num5) * 100f / num3 < 50f && CellType(i, j) == CellTypes.Hall)
					{
						roomIsolated = false;
					}
					if (CellType(i, j) == CellTypes.Room)
					{
						num = WallType(i, j);
						break;
					}
				}
			}
			for (int i = BestX - 1; i < BestX + Width + 2; i++)
			{
				for (int k = BestY - 1; k < BestY + Height + 2; k++)
				{
					if (((float)i - num4) * ((float)i - num4) * 100f / num2 + ((float)k - num5) * ((float)k - num5) * 100f / num3 < 50f && CellType(i, k) != 0)
					{
						SetWallType(i, k, (short)num);
					}
				}
			}
			for (int i = BestX - 1; i < BestX + Width + 2; i++)
			{
				for (int l = BestY - 1; l < BestY + Height + 2; l++)
				{
					if (((float)i - num4) * ((float)i - num4) * 100f / num2 + ((float)l - num5) * ((float)l - num5) * 100f / num3 >= 50f && CellType(i, l) != 0 && CellHeight(i, l) > 0)
					{
						SetCellType(i, l, CellTypes.RoomWall);
					}
				}
			}
			for (int i = BestX; i < BestX + Width; i++)
			{
				for (int m = BestY; m < BestY + Height; m++)
				{
					float num6 = ((float)i - num4) * ((float)i - num4) * 100f / num2 + ((float)m - num5) * ((float)m - num5) * 100f / num3;
					if (num6 < 10f)
					{
						SetCellHeight(i, m, 1);
						SetCellType(i, m, CellTypes.Solid);
					}
					else if (num6 < 50f)
					{
						roomX = i;
						roomY = m;
						SetRoomIndexData(i, m, roomsData.Count);
						SetCellHeight(i, m, 0);
						SetCellType(i, m, CellTypes.Room);
					}
				}
			}
			RoomData item = default(RoomData);
			item.roomIsolated = roomIsolated;
			item.roomX = roomX;
			item.roomY = roomY;
			item.roomWidth = Width;
			item.roomHeight = Height;
			item.roomExits = 0;
			item.roomCharLimit = Mathf.RoundToInt((float)(Width + Height) / distributionModifier);
			item.roomCharCount = 0;
			roomsData.Add(item);
		}

		private int CalculateScoreForRoom(int X, int Y, int Width, int Height)
		{
			int num = 0;
			bool flag = false;
			bool flag2 = false;
			for (int i = X; i < X + Width; i++)
			{
				for (int j = Y; j < Y + Height; j++)
				{
					if (!flag && CellType(i, j) == CellTypes.Hall)
					{
						flag = true;
					}
					if (CellHeight(i, j) == 0)
					{
						num += 100;
					}
					if (CellHeight(i, j - 1) == 0)
					{
						num += 100;
					}
					if (CellHeight(i, j + 1) == 0)
					{
						num += 100;
					}
					if (CellHeight(i - 1, j) == 0)
					{
						num += 100;
					}
					if (CellHeight(i + 1, j) == 0)
					{
						num += 100;
					}
					if (CellHeight(i, j) == 1)
					{
						num -= 500;
					}
					if (CellType(i, j) == CellTypes.Room)
					{
						num += 200;
						flag2 = true;
					}
					if (CellType(i, j) == CellTypes.RoomWall)
					{
						num += 200;
						flag2 = true;
					}
				}
			}
			if (!flag && !flag2)
			{
				num = -999;
			}
			return num;
		}

		private void GeneratePits(int Pits)
		{
			for (int i = 0; i < Pits; i++)
			{
				int num = 1;
				int num2 = 1;
				int num3 = 9999999;
				int num4 = UnityEngine.Random.Range(minimumPitWidth, maximumPitWidth + 1);
				int num5 = UnityEngine.Random.Range(minimumPitHeight, maximumPitHeight + 1);
				for (int j = 1; j < mazeWidth - 1 - num4; j++)
				{
					for (int k = 1; k < mazeHeight - 1 - num5; k++)
					{
						int num6 = CalculateScoreForPit(j, k, num4, num5);
						if (num6 < num3)
						{
							num = j;
							num2 = k;
							num3 = num6;
						}
					}
				}
				pitsData.Add(new PitsData
				{
					pitWidth = num4,
					pitHeight = num5,
					pitX = num,
					pitY = num2
				});
				GeneratePit(num, num2, num4, num5);
			}
		}

		private void GeneratePit(int BestX, int BestY, int Width, int Height)
		{
			bool flag = UnityEngine.Random.Range(0, 100) < 50;
			bool value = false;
			if (template.hasWater)
			{
				value = true;
			}
			int num = 0;
			if (template.floorTiles.Count > 1)
			{
				num = 1;
			}
			int value2 = template.TileGroundLayers(1);
			for (int i = BestX + 1; i < BestX + Width - 1; i++)
			{
				for (int j = BestY + 1; j < BestY + Height - 1; j++)
				{
					if (CellType(i, j) == CellTypes.RoomWall)
					{
						continue;
					}
					SetCellHeight(i, j, -1);
					SetCellType(i, j, CellTypes.Pit);
					SetCellPitIndex(i, j, pitsData.Count - 1);
					if (!flag)
					{
						continue;
					}
					if (j == BestY + 1 || j == BestY + Height - 2)
					{
						if (i % 2 == 0)
						{
							SetCellHeight(i, j, 0);
							SetCellType(i, j, CellTypes.Room);
						}
					}
					else if ((i == BestX + 1 || i == BestX + Width - 2) && j % 2 == 0)
					{
						SetCellHeight(i, j, 0);
						SetCellType(i, j, CellTypes.Room);
					}
				}
			}
			for (int i = BestX; i < BestX + Width; i++)
			{
				for (int j = BestY; j < BestY + Height; j++)
				{
					if (CellHeight(i, j) > 0 || CellType(i, j) == CellTypes.Hall)
					{
						SetCellHeight(i, j, 0);
						SetCellType(i, j, CellTypes.Room);
					}
					SetWallType(i, j, (short)num);
				}
			}
			for (int i = BestX - 1; i < BestX + Width; i++)
			{
				for (int j = BestY - 1; j < BestY + Height; j++)
				{
					if (CellHeight(i, j) < 0 || (CellHeight(i, j) <= 0 && IsCliff(i, j)))
					{
						SetHasWater(i, j, value);
					}
				}
			}
			for (int i = BestX + 1; i < BestX + Width; i++)
			{
				for (int j = BestY + 1; j < BestY + Height; j++)
				{
					SetTerrainType(i, j, value2);
				}
			}
			for (int i = BestX; i <= BestX + Width; i++)
			{
				for (int j = BestY; j <= BestY + Height; j++)
				{
					SetFloorHeight(i, j, 0f);
				}
			}
		}

		private int CalculateScoreForPit(int X, int Y, int Width, int Height)
		{
			int num = 0;
			for (int i = X; i < X + Width; i++)
			{
				for (int j = Y; j < Y + Height; j++)
				{
					if (GetCellDataFromPosition(i, j).pitIndexData != -1)
					{
						num += 500;
					}
					if (CellHeight(i, j) == 0)
					{
						num -= 3;
					}
					if (CellHeight(i, j - 1) == 0)
					{
						num--;
					}
					if (CellHeight(i, j + 1) == 0)
					{
						num--;
					}
					if (CellHeight(i - 1, j) == 0)
					{
						num--;
					}
					if (CellHeight(i + 1, j) == 0)
					{
						num--;
					}
					if (CellHeight(i, j) > 0)
					{
						num += 100;
					}
					if (CellHeight(i, j) < 0)
					{
						num += 300;
					}
					if (CellType(i, j) == CellTypes.Room)
					{
						num -= 200;
					}
					if (CellType(i, j) == CellTypes.RoomWall)
					{
						num += 100;
					}
				}
			}
			return num;
		}

		private void SetCellPitIndex(int X, int Y, int Index)
		{
			if (X >= 0 && Y >= 0 && X < mazeWidth && Y < mazeHeight && X + Y * mazeWidth < cells.Count)
			{
				CellData value = cells[X + Y * mazeWidth];
				value.pitIndexData = Index;
				cells[X + Y * mazeWidth] = value;
			}
		}

		private void SetFloorHeight(int X, int Y, float Value)
		{
			if (X >= 0 && Y >= 0 && X < mazeWidth && Y < mazeHeight && X + Y * mazeWidth < cells.Count)
			{
				CellData value = cells[X + Y * mazeWidth];
				value.heightData = Value;
				cells[X + Y * mazeWidth] = value;
			}
		}

		private void SetOffset(int X, int Y, float XOffset, float YOffset)
		{
			if (X >= 0 && Y >= 0 && X < mazeWidth && Y < mazeHeight && X + Y * mazeWidth < cells.Count)
			{
				CellData value = cells[X + Y * mazeWidth];
				value.xOffsetData = XOffset;
				value.yOffsetData = YOffset;
				cells[X + Y * mazeWidth] = value;
			}
		}

		public bool IsCliff(int X, int Y)
		{
			if (X < 0 || Y < 0 || X >= mazeWidth || Y >= mazeHeight || X + Y * mazeWidth >= cells.Count)
			{
				return false;
			}
			WallTypes wallTypes = WallTypeNW(X, Y);
			if (wallTypes != 0 && wallTypes != WallTypes.NWSolid)
			{
				return true;
			}
			wallTypes = WallTypeNE(X, Y);
			if (wallTypes != 0 && wallTypes != WallTypes.NESolid)
			{
				return true;
			}
			wallTypes = WallTypeSW(X, Y);
			if (wallTypes != 0 && wallTypes != WallTypes.SWSolid)
			{
				return true;
			}
			wallTypes = WallTypeSE(X, Y);
			if (wallTypes != 0 && wallTypes != WallTypes.SESolid)
			{
				return true;
			}
			return false;
		}

		public bool IsFlat(int X, int Y)
		{
			WallTypes wallTypes = WallTypeNW(X, Y);
			if (wallTypes == WallTypes.NWCorner || wallTypes == WallTypes.NWCornerJoin || wallTypes == WallTypes.NWInnerCorner)
			{
				return false;
			}
			wallTypes = WallTypeNE(X, Y);
			if (wallTypes == WallTypes.NECorner || wallTypes == WallTypes.NECornerJoin || wallTypes == WallTypes.NEInnerCorner)
			{
				return false;
			}
			wallTypes = WallTypeSW(X, Y);
			if (wallTypes == WallTypes.SWCorner || wallTypes == WallTypes.SWCornerJoin || wallTypes == WallTypes.SWInnerCorner)
			{
				return false;
			}
			wallTypes = WallTypeSE(X, Y);
			if (wallTypes == WallTypes.SECorner || wallTypes == WallTypes.SECornerJoin || wallTypes == WallTypes.SEInnerCorner)
			{
				return false;
			}
			return true;
		}

		public bool IsDiagonal(int X, int Y)
		{
			if (WallTypeNW(X, Y) == WallTypes.NWCornerJoin)
			{
				return true;
			}
			if (WallTypeNE(X, Y) == WallTypes.NECornerJoin)
			{
				return true;
			}
			if (WallTypeSW(X, Y) == WallTypes.SWCornerJoin)
			{
				return true;
			}
			if (WallTypeSE(X, Y) == WallTypes.SECornerJoin)
			{
				return true;
			}
			return false;
		}

