		public WallTypes WallTypeNW(int X, int Y)
		{
			short num = CellHeight(X, Y);
			short num2 = CellHeight(X, Y - 1);
			short num3 = CellHeight(X - 1, Y);
			short num4 = CellHeight(X - 1, Y - 1);
			WallTypes result = WallTypes.Open;
			if (num2 < num && num3 < num && num4 == num)
			{
				result = WallTypes.NWCornerJoin;
			}
			else if (num2 < num && num3 < num && num4 < num)
			{
				result = WallTypes.NWCorner;
			}
			else if (num2 == num && num3 == num && num4 < num)
			{
				result = WallTypes.NWInnerCorner;
			}
			else if (num2 == num && num3 == num && num4 == num)
			{
				result = WallTypes.NWSolid;
			}
			else if (num2 < num && num3 == num && num4 == num)
			{
				result = WallTypes.NWHorizontal;
			}
			else if (num2 < num && num3 == num)
			{
				result = WallTypes.NWHorizontal;
			}
			else if (num2 == num && num3 < num && num4 == num)
			{
				result = WallTypes.NWVertical;
			}
			else if (num2 == num && num3 < num)
			{
				result = WallTypes.NWVertical;
			}
			return result;
		}

