		private bool SelectRandomUnvisitedCell(ref int X, ref int Y)
		{
			int num = 0;
			int num2 = 0;
			bool flag = false;
			if (cellsVisited >= mazeWidth * mazeHeight)
			{
				return false;
			}
			while (!flag)
			{
				num = UnityEngine.Random.Range(1, mazeWidth - 1);
				num2 = UnityEngine.Random.Range(1, mazeHeight - 1);
				if (!CellVisited(num, num2) && CellHeight(num - 1, num2) != 0 && CellHeight(num + 1, num2) != 0 && CellHeight(num, num2 - 1) != 0 && CellHeight(num, num2 + 1) != 0)
				{
					flag = true;
				}
			}
			if (flag)
			{
				X = num;
				Y = num2;
				return true;
			}
			return false;
		}

		private bool SelectRandomCell(ref int X, ref int Y, short height)
		{
			int num = 0;
			int num2 = 0;
			bool flag = false;
			bool flag2 = false;
			for (int i = 1; i < mazeWidth - 1; i++)
			{
				for (int j = 1; j < mazeHeight - 1; j++)
				{
					if (CellHeight(i, j) == height)
					{
						flag2 = true;
						break;
					}
				}
				if (flag2)
				{
					break;
				}
			}
			if (!flag2)
			{
				num = UnityEngine.Random.Range(1, mazeWidth - 1);
				num2 = UnityEngine.Random.Range(1, mazeHeight - 1);
				flag = true;
			}
			while (!flag)
			{
				num = UnityEngine.Random.Range(1, mazeWidth - 1);
				num2 = UnityEngine.Random.Range(1, mazeHeight - 1);
				if (CellHeight(num, num2) == height)
				{
					flag = true;
				}
			}
			if (flag)
			{
				X = num;
				Y = num2;
				return true;
			}
			return false;
		}

		private bool ValidCell(int X, int Y)
		{
			if (X < 0 || Y < 0 || X >= mazeWidth || Y >= mazeHeight || X + Y * mazeWidth >= cells.Count)
			{
				return false;
