			{
				return false;
			}
			return cells[X + Y * mazeWidth].cellHasWater;
		}
	}
	public class MoveUpOrDownDungeon : InteractableSceneObject
	{
		public bool goesDown;

		private int levelDepth;

		private Collider myCollider;

		private void Start()
		{
			levelDepth = LevelGenerator.currentInstance.GetLevelDepth();
			myCollider = GetComponent<Collider>();
			base.InteractableName = I2Loca.Get(goesDown ? "StairsDown" : "StairsUp");
			base.InteractRange = 4f;
			if (GetComponentInChildren<MiniMapIconUI>() == null && LevelGenerator.currentInstance != null)
			{
				GameObject obj = new GameObject("_MiniMapIcon");
				obj.layer = LayerMask.NameToLayer("Minimap");
				obj.transform.SetParent(base.transform);
				obj.transform.localPosition = Vector3.zero;
				obj.transform.localScale = Vector3.one * 2f;
				obj.transform.rotation = Quaternion.Euler(new Vector3(90f, 0f, 315f));
				obj.AddComponent<MiniMapIconUI>();
				obj.AddComponent<SpriteRenderer>().sprite = (goesDown ? LevelGenerator.currentInstance.dungeonStairsDownIcon : LevelGenerator.currentInstance.dungeonStairsUpIcon);
			}
		}

		public override Vector3 GetCenterPosition()
		{
			return myCollider.bounds.center;
		}

		public override void Interact(Character other)
		{
			Fate.SetPause(paused: true);
			if (goesDown)
			{
				if (!SingletonBehaviour<QuestManager>.Instance.CanAccessLevelInDungeon(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, levelDepth + 1))
				{
					SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("Stairs_Blocked", null);
					return;
				}
				SingletonBehaviour<PromptUI>.Instance.ShowPrompt("Prompt_DescendStairs", delegate(bool positive)
				{
					if (positive)
					{
						if (other.IsPlayer())
						{
							other.SetInvincible();
						}
						levelDepth++;
						GenerateNextLevel();
						if (levelDepth == 35)
						{
							StatsManager.OnDungeonLevel35Reached(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm.ToString());
						}
					}
					else
					{
						Fate.SetPause(paused: false);
					}
				});
				return;
			}
			if (levelDepth - 1 < 1)
			{
				SingletonBehaviour<PromptUI>.Instance.ShowPrompt("Prompt_ExitDungeon", delegate(bool positive)
				{
					if (positive)
					{
						if (other.IsPlayer())
						{
							other.SetInvincible();
						}
						SingletonBehaviour<AudioManager>.Instance.StopMusic();
						levelDepth--;
						LevelGenerator.currentInstance.SetLevelDepth(levelDepth);
						LevelGenerator.currentInstance.UpdateSaveData(goesDown);
						Town.UpdateSpawnIndex(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, Town.EntryMethod.Stairs);
						SceneLoad.LoadAsync(SceneLoad.GetTownScene(SingletonBehaviour<PlayerStatus>.Instance.TownRealm), save: true);
						SingletonBehaviour<AudioManager>.Instance.StopMusic();
					}
					else
					{
						Fate.SetPause(paused: false);
					}
				});
				return;
			}
			SingletonBehaviour<PromptUI>.Instance.ShowPrompt("Prompt_AscendStairs", delegate(bool positive)
			{
				if (positive)
				{
					if (other.IsPlayer())
					{
						other.SetInvincible();
					}
					levelDepth--;
					GenerateNextLevel();
				}
				else
				{
					Fate.SetPause(paused: false);
				}
			});
		}

		private void GenerateNextLevel()
		{
			Player.latestStairsUsedWasDown = goesDown;
			if (LevelGenerator.currentInstance.HasActiveDungeon())
			{
				LevelGenerator.currentInstance.ReplaceDungeon(0f, 0f, levelDepth, (int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, goesDown, useSavedPosition: false);
			}
			else
			{
				LevelGenerator.currentInstance.Create(0f, 0f, levelDepth, (int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, goesDown, useSavedPosition: false);
			}
		}
	}
	[RequireComponent(typeof(OrbTrigger))]
	public class OrbTooltip : InteractableTooltipBase
	{
		[SerializeField]
		private InteractableTooltipHoverRelay hoverRelay;

		private OrbTrigger orbTrigger;

		protected override bool HandleMouseHover => false;

		protected override bool UpdateTooltipOnStart => false;

		protected override void Awake()
		{
			interactable = null;
			orbTrigger = GetComponent<OrbTrigger>();
			OrbTrigger obj = orbTrigger;
			obj.onInitialized = (Action)Delegate.Combine(obj.onInitialized, new Action(UpdateTooltip));
			tooltipCanvas.gameObject.SetActive(value: false);
			tooltipCanvas.SetIsHovered(isHovered: false);
		}

		protected override void UpdateTooltip()
		{
			tooltipCanvas.SetText(orbTrigger.Item.ItemDisplayName);
		}

		protected override void ShowTooltip()
		{
			if (orbTrigger.HasTriggered)
			{
				PermanentDisable();
			}
			else
			{
				tooltipCanvas.gameObject.SetActive(value: true);
			}
		}

		protected override void PermanentDisable()
		{
			UnityEngine.Object.Destroy(hoverRelay.gameObject);
			base.PermanentDisable();
		}
	}
	public class OrbTrigger : MonoBehaviour
	{
		[Serializable]
		public struct OrbVisual
		{
			public Material meshMaterial;

			public GameObject particleEffect;
		}

		[SerializeField]
		private MeshRenderer meshRenderer;

		[Header("Drop")]
		[SerializeField]
		private AnimationCurve posCurve;

		[SerializeField]
		private AnimationCurve heightCurve;

		[SerializeField]
		private Range dropDistance = new Range(1, 5);

		[Header("Floating")]
		[SerializeField]
		private Transform floatParent;

		[SerializeField]
		private float floatInterval = 3f;

		[SerializeField]
		private float floatStrength = 1f;

		[SerializeField]
		private AnimationCurve floatCurve;

		[Header("Visuals")]
		[SerializeField]
		private OrbVisual nullVisual;

		[SerializeField]
		private OrbVisual healVisual;

		[SerializeField]
		private OrbVisual manaVisual;

		[SerializeField]
		private OrbVisual staminaVisual;

		[SerializeField]
		private OrbVisual poisonVisual;

		private Transform myTransform;

		private bool isDropping;

		private OrbType orbType;

		public Action onInitialized;

		private const float tweenDuration = 0.5f;

		public Item Item { get; private set; }

		public bool HasTriggered { get; private set; }

		private void Start()
		{
			if (LevelGenerator.currentInstance == null)
			{
				UnityEngine.Debug.LogError("OrbTrigger spawned without a dungeon, that is not allowed.");
				UnityEngine.Object.Destroy(base.gameObject);
				return;
			}
			base.gameObject.layer = LayerMask.NameToLayer("PlayerTrigger");
			Vector3 targetLocation = LevelGenerator.currentInstance.RandomOpenPosition(myTransform.position, dropDistance.Min, dropDistance.Max);
			StartCoroutine(DoDropBounce(myTransform.position, targetLocation, 0.5f));
			StartCoroutine(DoFloat());
		}

		private IEnumerator DoDropBounce(Vector3 startPos, Vector3 targetLocation, float duration)
		{
			isDropping = true;
			float time = 0f;
			while (true)
			{
				float num;
				time = (num = time + Time.deltaTime);
				if (!(num < duration))
				{
					break;
				}
				float time2 = Mathf.Clamp01(time / duration);
				float t = posCurve.Evaluate(time2);
				float num2 = heightCurve.Evaluate(time2);
				myTransform.position = Vector3.Lerp(startPos, targetLocation, t).WithY(targetLocation.y + num2 * 2.5f);
				yield return null;
			}
			myTransform.position = targetLocation;
			isDropping = false;
		}

		private IEnumerator DoFloat()
		{
			if (Mathf.Approximately(floatInterval, 0f))
			{
				yield break;
			}
			float originalHeight = floatParent.localPosition.y;
			float time = 0f;
			while (true)
			{
				time = (time + Time.deltaTime) % floatInterval;
				float time2 = time / floatInterval;
				float num = floatCurve.Evaluate(time2);
				floatParent.localPosition = floatParent.localPosition.WithY(originalHeight + num * floatStrength);
				yield return null;
			}
		}

		public void Init(Item item)
		{
			myTransform = base.transform;
			Item = item;
			isDropping = true;
			orbType = IdentifyOrbType(item);
			OrbVisual orbVisual = GetOrbVisual(orbType);
			meshRenderer.material = orbVisual.meshMaterial;
			orbVisual.particleEffect.SetActive(value: true);
			HasTriggered = false;
			onInitialized?.Invoke();
		}

		private OrbType IdentifyOrbType(Item item)
		{
			if (item.effects == null || item.effects.Count == 0)
			{
				return OrbType.Null;
			}
			if (item.effects.TryGetValue(ActivationType.Usage, out var value))
			{
				foreach (EffectData item2 in value)
				{
					EffectType buffType = item2.buffType;
					if (buffType == EffectType.HPPercentRecharge || buffType == EffectType.HPRecharge)
					{
						return (item2.value < 0) ? OrbType.Poison : OrbType.Healing;
					}
					if (item2.buffType == EffectType.ManaPercentRecharge)
					{
						return OrbType.Mana;
					}
					if (item2.buffType == EffectType.StaminaRecharge)
					{
						return OrbType.Stamina;
					}
				}
			}
			return OrbType.Invalid;
		}

		private OrbVisual GetOrbVisual(OrbType orbType)
		{
			return orbType switch
			{
				OrbType.Null => nullVisual, 
				OrbType.Healing => healVisual, 
				OrbType.Mana => manaVisual, 
				OrbType.Stamina => staminaVisual, 
				OrbType.Poison => poisonVisual, 
				_ => throw new Exception($"Unhandled enum value {orbType}"), 
			};
		}

		private void OnTriggerEnter(Collider other)
		{
			TryCollision(other);
		}

		private void OnTriggerStay(Collider other)
		{
			TryCollision(other);
		}

		private void TryCollision(Collider other)
		{
			if (HasTriggered || isDropping)
			{
				return;
			}
			Player component = other.GetComponent<Player>();
			if (component == null)
			{
				return;
			}
			if (Item.effects != null && Item.effects.TryGetValue(ActivationType.Usage, out var value))
			{
				foreach (EffectData item in value)
				{
					component.AddEffect(item, 1, null);
				}
			}
			ParticleSystem[] componentsInChildren = GetComponentsInChildren<ParticleSystem>(includeInactive: false);
			if (componentsInChildren != null)
			{
				ParticleSystem[] array = componentsInChildren;
				for (int i = 0; i < array.Length; i++)
				{
					array[i].Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
				}
			}
			meshRenderer.enabled = false;
			Item.PlayTakeSound();
			HasTriggered = true;
			UnityEngine.Object.Destroy(base.gameObject, 3f);
		}
	}
