	public class ShrineOfLearningInteractable : InteractableSceneObject
	{
		private bool used;

		private AudioSource audioSource;

		public GameObject[] candleFire;

		public GameObject candleLight;

		public GameObject highlight;

		private void Awake()
		{
			base.InteractableName = I2Loca.Get("Item_ShrineofLearning");
			audioSource = GetComponentInParent<AudioSource>();
		}

		public override void Interact(Character interactor = null)
		{
			if (used)
			{
				return;
			}
			SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_temptfate);
			bool prePauseState = Fate.isPaused;
			Fate.SetPause(paused: true);
			SingletonBehaviour<PromptUI>.Instance.ShowPrompt("ShrineOfLearningConfirm", delegate(bool positive)
			{
				if (positive)
				{
					used = true;
					audioSource.Stop();
					GameObject[] array = candleFire;
					for (int i = 0; i < array.Length; i++)
					{
						array[i].SetActive(value: false);
					}
					candleLight.SetActive(value: false);
					highlight.SetActive(value: false);
					int num = UnityEngine.Random.Range(0, 100);
					string text = "";
					string text2 = "";
					if (num < 75)
					{
						int num2 = UnityEngine.Random.Range(1, 3);
						if (UnityEngine.Random.Range(0, 100) < 20)
						{
							num2 *= -1;
						}
						switch (UnityEngine.Random.Range(0, 3))
						{
						case 0:
							text = "\b" + I2Loca.Get("Strength") + "\b";
							Player.PlayerChar.attributes.AddBasePoints(Attribute.Strength, num2);
							break;
						case 1:
							text = "\b" + I2Loca.Get("Dexterity") + "\b";
							Player.PlayerChar.attributes.AddBasePoints(Attribute.Dexterity, num2);
							break;
						case 2:
							text = "\b" + I2Loca.Get("Vitality") + "\b";
							Player.PlayerChar.attributes.AddBasePoints(Attribute.Vitality, num2);
							break;
						case 3:
							text = "\b" + I2Loca.Get("Magic") + "\b";
							Player.PlayerChar.attributes.AddBasePoints(Attribute.Magic, num2);
							break;
						}
						if (num2 > 0)
						{
							text2 = I2Loca.GetMultiLineFormat("ShrineOfLearning_PointsRaised", text, num2.ToString());
							SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_fategood);
						}
						else
						{
							text2 = I2Loca.GetMultiLineFormat("ShrineOfLearning_PointsReduced", text, num2.ToString());
						}
					}
					else
					{
						int num2 = UnityEngine.Random.Range(1, 3);
						if (UnityEngine.Random.Range(0, 100) < 20)
						{
							num2 = num2;
						}
						int num3 = UnityEngine.Random.Range(8, 23);
						if (Player.PlayerChar.attributes.GetAttribute((Attribute)num3, allowEffects: false) == 0)
						{
							num2 = 0;
						}
						Player.PlayerChar.attributes.AddBasePoints((Attribute)num3, num2);
						Attribute attribute = (Attribute)num3;
						text = I2Loca.GetFormat(attribute.ToString());
						text2 = ((num2 > 0) ? I2Loca.GetMultiLineFormat("ShrineOfLearning_PointsRaised", text, num2.ToString()) : ((num2 >= 0) ? I2Loca.GetMultiLineFormat("NothingHappens") : I2Loca.GetMultiLineFormat("ShrineOfLearning_PointsReduced", text, num2.ToString())));
					}
					SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton(text2, delegate
					{
						Fate.SetPause(prePauseState);
					});
					LevelGenerator.currentInstance.OnUsedShrineOfLearning();
					CanInteract = false;
				}
				else
				{
					Fate.SetPause(prePauseState);
				}
			}, "Yes", "Leave");
		}

		public void SetUsed()
		{
			used = true;
			CanInteract = false;
			audioSource.Stop();
			highlight.SetActive(value: false);
			candleLight.SetActive(value: false);
			GameObject[] array = candleFire;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: false);
			}
		}
	}
