	public class TkalaAnvilInteractable : InteractableSceneObject
	{
		private const string anvilKey = "Anvil_AnvilofDemons";

		public ItemData urnItemData;

		public ItemData hammerItemData;

		public MonsterData tkalaMonsterData;

		public GameObject idleParticles;

		public ParticleSystem activeParticles;

		public ParticleSystem onUseParticles;

		private Quest relevantQuest;

		private void Awake()
		{
			if (SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm != RealmData.RealmId.HauntedPalace)
			{
				UnityEngine.Debug.LogError("TkalaAnvil spawned in wrong realm! " + SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
				UnityEngine.Object.Destroy(base.gameObject);
				return;
			}
			base.InteractableName = I2Loca.Get("Anvil_AnvilofDemons");
			CanInteract = true;
			idleParticles.SetActive(value: false);
			activeParticles.gameObject.SetActive(value: false);
			onUseParticles.gameObject.SetActive(value: false);
			StartCoroutine(DoQuestCheck());
		}

		private IEnumerator DoQuestCheck()
		{
			if (!SingletonBehaviour<QuestManager>.InstanceExists() || !SingletonBehaviour<QuestManager>.Instance.HasLoaded)
			{
				yield return null;
			}
			relevantQuest = SingletonBehaviour<QuestManager>.Instance.GetRealmQuest(RealmData.RealmId.HauntedPalace);
			if (relevantQuest == null || relevantQuest.QuestType != QuestData.QuestType.RealmBoss || relevantQuest.Status != Quest.QuestStatus.Accepted)
			{
				UnityEngine.Debug.LogError("Deactivating TkalaAnvil because the realm quest is not active or does not allow the use of the anvil any longer");
				UnityEngine.Object.Destroy(base.gameObject);
				yield break;
			}
			bool flag = false;
			if (LevelGenerator.currentInstance.HasDroppedItemWith((Item item) => item.itemType == ItemType.EndHammer))
			{
				flag = true;
			}
			if (!flag && Player.PlayerChar.HasItems(hammerItemData.displayName, 1))
			{
				flag = true;
			}
			if (!flag && SaveData.CurrentSaveData.stashStorage != null && SaveData.CurrentSaveData.stashStorage.items != null)
			{
				foreach (ItemSaveData item in SaveData.CurrentSaveData.stashStorage.items)
				{
					if (item.baseName == hammerItemData.displayName)
					{
						flag = true;
						break;
					}
				}
			}
			if (!flag)
			{
				UnityEngine.Debug.Log("found no quest hammer, spawning backup");
				new Item(hammerItemData).Drop(base.transform.position);
			}
			bool flag2 = false;
			if (LevelGenerator.currentInstance.HasDroppedItemWith((Item item) => item.itemType == ItemType.EndUrn))
			{
				flag2 = true;
			}
			if (!flag2 && Player.PlayerChar.HasItems(urnItemData.displayName, 1))
			{
				flag2 = true;
			}
			if (!flag2 && SaveData.CurrentSaveData.stashStorage != null && SaveData.CurrentSaveData.stashStorage.items != null)
			{
				foreach (ItemSaveData item2 in SaveData.CurrentSaveData.stashStorage.items)
				{
					if (item2.baseName == urnItemData.displayName)
					{
						flag2 = true;
						break;
					}
				}
			}
			if (!flag2)
			{
				UnityEngine.Debug.Log("found no quest urn, spawning backup");
				new Item(urnItemData).Drop(base.transform.position);
			}
		}

		public override void Interact(Character interactor = null)
		{
			ItemSelectionUI itemSelection = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.itemSelection;
			itemSelection.onUsed = (Action)Delegate.Combine(itemSelection.onUsed, new Action(OnUsed));
			ItemSelectionUI itemSelection2 = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.itemSelection;
			itemSelection2.onCancel = (Action)Delegate.Combine(itemSelection2.onCancel, new Action(OnCancel));
			PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
			instance.onClosedTabs = (Action)Delegate.Combine(instance.onClosedTabs, new Action(OnCancel));
			SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.SetItemSelectTkalaAnvil(urnItemData, hammerItemData);
			SimpleSingletonBehaviour<PlayerUI>.Instance.ShowInventory(PlayerUI.InventoryStateType.ItemSelect);
			idleParticles.SetActive(value: false);
			activeParticles.gameObject.SetActive(value: true);
		}

		private void UnSubscribe()
		{
			if (SingletonBehaviour<PlayerUI>.InstanceExists() && SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI != null)
				{
					ItemSelectionUI itemSelection = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.itemSelection;
					itemSelection.onUsed = (Action)Delegate.Remove(itemSelection.onUsed, new Action(OnUsed));
					ItemSelectionUI itemSelection2 = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.itemSelection;
					itemSelection2.onCancel = (Action)Delegate.Remove(itemSelection2.onCancel, new Action(OnCancel));
				}
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.onClosedTabs = (Action)Delegate.Remove(instance.onClosedTabs, new Action(OnCancel));
			}
		}

		private void OnUsed()
		{
			UnSubscribe();
			CanInteract = false;
			relevantQuest.Status = Quest.QuestStatus.InProgress;
			activeParticles.gameObject.SetActive(value: false);
			StartCoroutine(UtilityTG.DelayedInvoke(0.2f, delegate
			{
				onUseParticles.gameObject.SetActive(value: true);
				onUseParticles.Play();
			}));
		}

		private void OnCancel()
		{
			UnSubscribe();
		}
	}
	public class EndGameGraphicsContainer : MonoBehaviour
	{
		[SerializeField]
		private GameObject ashParticle;

		[SerializeField]
		private GameObject sunLight;

		[SerializeField]
		private Color sunColor;

		[Header("Fountains")]
		[SerializeField]
		private Material waterFountainMaterial;

		[SerializeField]
		private GameObject waterFountain;

		[SerializeField]
		private Material smallWaterFountainMaterial;

		[SerializeField]
		private GameObject smallWaterFountain;

		[SerializeField]
		private GameObject fireParticle;

		[Header("Lighting/Environment settings")]
		[SerializeField]
		private Material skyboxMaterial;

		[SerializeField]
		private Color skyColor;

		[SerializeField]
		private Color equatorColor;

		[SerializeField]
		private Color groundColor;

		[Header("Minimap")]
		[SerializeField]
		private GameObject layer1;

		[SerializeField]
		private Material materialLayer1;

		[SerializeField]
		private GameObject layer2;

		[SerializeField]
		private Material materialLayer2;

		private IEnumerator Start()
		{
			while (!SingletonBehaviour<QuestManager>.InstanceExists() || !SingletonBehaviour<QuestManager>.Instance.HasLoaded)
			{
				yield return null;
			}
			if (SingletonBehaviour<QuestManager>.Instance.HasFlag("PROMETHEUS"))
			{
				SetToWonMode();
				yield break;
			}
			Quest.QuestStatus? questStatus = SingletonBehaviour<QuestManager>.Instance.GetRealmQuest(RealmData.RealmId.Prometheus)?.Status;
			if (questStatus.HasValue)
			{
				Quest.QuestStatus value = questStatus.Value;
				if (value == Quest.QuestStatus.Completed || value == Quest.QuestStatus.Claimed)
				{
					SetToWonMode();
				}
			}
		}

		public void SetToWonMode()
		{
			if (ashParticle != null)
			{
				ashParticle.SetActive(value: false);
			}
			if (fireParticle != null)
			{
				fireParticle.SetActive(value: true);
			}
			if (sunLight != null)
			{
				Light component = sunLight.GetComponent<Light>();
				if (component != null)
				{
					component.color = sunColor;
				}
			}
			ApplyMaterialToElement(waterFountain, waterFountainMaterial, 2);
			ApplyMaterialToElement(smallWaterFountain, smallWaterFountainMaterial, 1);
			RenderSettings.skybox = skyboxMaterial;
			RenderSettings.ambientSkyColor = skyColor;
			RenderSettings.ambientEquatorColor = equatorColor;
			RenderSettings.ambientGroundColor = groundColor;
			ApplyMaterialToElement(layer1, materialLayer1, 0);
			ApplyMaterialToElement(layer2, materialLayer2, 0);
		}

		private void ApplyMaterialToElement(GameObject target, Material mat, int index)
		{
			if (!(target == null) && !(mat == null))
			{
				Renderer component = target.GetComponent<Renderer>();
				if (component != null && component.sharedMaterials.Length > index)
				{
					Material[] sharedMaterials = component.sharedMaterials;
					sharedMaterials[index] = mat;
					component.sharedMaterials = sharedMaterials;
				}
			}
		}
	}
