		public static string IntToRoman(int num)
		{
			if (num == 0)
			{
				return "";
			}
			num = Mathf.Clamp(num, 0, 3999);
			string[] array = new string[5] { "", "M", "MM", "MMM", "MMM" };
			string[] array2 = new string[10] { "", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM" };
			string[] array3 = new string[10] { "", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC" };
			string[] array4 = new string[10] { "", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX" };
			return array[num / 1000] + array2[num % 1000 / 100] + array3[num % 100 / 10] + array4[num % 10];
		}

		public static int GetMaxPartyMembersByLevel(int playerLevel)
		{
			if (playerLevel < 10)
			{
				return 0;
			}
			if (playerLevel < 20)
			{
				return 1;
			}
			if (playerLevel < 30)
			{
				return 2;
			}
			return 3;
		}

		public static List<Character> FindCharactersInArea(Vector3 position, float range)
		{
			List<Character> list = new List<Character>();
			if (LevelGenerator.currentInstance != null)
			{
				List<GameObject> list2 = new List<GameObject>();
				LevelGenerator.currentInstance.FillListWithActiveCharacters(ref list2);
				foreach (GameObject item in list2)
				{
					if (item.TryGetComponent<Character>(out var component) && DistanceCheck(position, component.myTransform.position, range))
					{
						list.Add(component);
					}
				}
			}
			Player playerChar = Player.PlayerChar;
			if (playerChar == null)
			{
				return list;
			}
			if (DistanceCheck(position, playerChar.myTransform.position, range))
			{
				list.Add(playerChar);
			}
			for (int i = 0; i < playerChar.GetPetCount(); i++)
			{
				Character pet = playerChar.GetPet(i);
				if (DistanceCheck(position, pet.myTransform.position, range))
				{
					list.Add(pet);
				}
			}
			for (int j = 0; j < playerChar.GetPartyMemberCount(); j++)
			{
				Character partyMember = playerChar.GetPartyMember(j);
				if (DistanceCheck(position, partyMember.myTransform.position, range))
				{
					list.Add(partyMember);
				}
				for (int k = 0; k < partyMember.GetPetCount(); k++)
				{
					Character pet2 = partyMember.GetPet(j);
					if (DistanceCheck(position, pet2.myTransform.position, range))
					{
						list.Add(partyMember);
					}
				}
			}
			return list;
		}

		public static bool DistanceCheck(Vector3 from, Vector3 to, float range)
		{
			return (to - from).magnitude <= range;
		}

