			case EffectType.PercentLifeStolen:
				return 8;
			case EffectType.PercentStrength:
			case EffectType.PercentDexterity:
			case EffectType.PercentVitality:
			case EffectType.PercentMagic:
			case EffectType.PercentMaxMana:
			case EffectType.PercentMaxHP:
			case EffectType.PercentArmorBonus:
			case EffectType.PercentToHitBonus:
			case EffectType.PercentDamageBonus:
			case EffectType.PercentDamage:
				return 50;
			case EffectType.SkillSword:
			case EffectType.SkillClub:
			case EffectType.SkillHammer:
