			case EffectType.AllSkills:
			case EffectType.PercentCastSpeed:
			case EffectType.SkillCriticalStrike:
			case EffectType.SkillSpellCasting:
				return 20;
			case EffectType.PercentGoldDrop:
				return 100;
			case EffectType.DamageTaken:
				return -10;
			case EffectType.PercentDamageTaken:
				return -30;
			case EffectType.RealmPortal:
			case EffectType.Defense:
				return 2;
			default:
