		public static ulong GetExperienceNeeded(int Level)
		{
			if (Level == 0)
			{
				return 0uL;
			}
			if (Level < ExperienceForLevel.Length)
			{
				return ExperienceForLevel[Level];
			}
			if (Level > MaxLevel)
			{
				return GetExperienceNeeded(MaxLevel);
			}
			ulong num = ExperienceForLevel[^1];
			double num2 = Math.Pow(1.01, Level - (ExperienceForLevel.Length - 1));
			return (ulong)((double)num * num2);
		}

		public static int GetLevelFromExperience(ulong experience)
		{
			if (experience > ExperienceForLevel[^1])
			{
				int i = ExperienceForLevel.Length - 1;
				if (experience > GetExperienceNeeded(MaxLevel))
				{
					return MaxLevel;
				}
				if (experience > GetExperienceNeeded(500))
				{
					i = ((experience <= GetExperienceNeeded(750)) ? 500 : 750);
				}
				for (; experience > GetExperienceNeeded(i); i++)
				{
				}
				return i - 1;
			}
			if (experience <= ExperienceForLevel[0])
			{
				return 0;
			}
			for (int j = 1; j < ExperienceForLevel.Length; j++)
			{
				if (experience <= ExperienceForLevel[j])
				{
					return j - 1;
				}
			}
			return 0;
		}

		public static string GetFameName(int fameRank)
		{
			if (fameRank >= FamePerTier.Length)
