			}
			return I2Loca.Get("Fame" + fameRank);
		}

		public static uint GetFameNeeded(int rank)
		{
			if (rank <= 0)
			{
				return 0u;
			}
			if (rank < FamePerTier.Length)
			{
				return FamePerTier[rank];
			}
			return FamePerTier[^1];
		}

		public static int GetFameTier(uint fame)
		{
			if (fame > FamePerTier[^1])
			{
				return FamePerTier.Length - 1;
			}
			for (int i = 0; i < FamePerTier.Length; i++)
			{
				if (fame <= FamePerTier[i])
				{
					return i;
				}
			}
			return 0;
		}

