	public static class FateSpellHelpers
	{
		public static void PerformSingleTargetSpellImpact(SpellData spellData, Character caster, Alignment targetAlignment, Character characterTarget = null)
		{
			if (characterTarget == null)
			{
				UnityEngine.Debug.LogError("PerformSingleTargetSpellImpact: Character target is null");
				return;
			}
			if (caster.HasMaster())
			{
				caster.Master();
			}
			if (!characterTarget.Alive())
			{
				return;
			}
			if (targetAlignment == characterTarget.GetAlignment())
			{
				characterTarget.WasHitBySpellPayload(spellData, caster);
				if (!characterTarget.Alive())
				{
					return;
				}
				characterTarget.WasHitBySpell(spellData, caster);
			}
			if (characterTarget.GetAlignment() != caster.GetAlignment())
			{
				characterTarget.RespondToAttack(caster);
			}
		}

		public static void PerformAreaSpellImpact(Vector3 position, SpellData spellData, Character caster, Alignment targetAlignment, Character characterTarget = null)
		{
			Character character = (caster.HasMaster() ? caster.Master() : caster);
			foreach (Character item in Fate.FindCharactersInArea(position, (float)spellData.range * 0.25f))
			{
				if (!item.Alive())
				{
					continue;
				}
				if (characterTarget == null)
				{
					switch (spellData.targetType)
					{
					case ItemTarget.Character:
					case ItemTarget.CharacterArea:
					case ItemTarget.CharacterPets:
					case ItemTarget.CharacterAndPets:
						UnityEngine.Debug.LogError($"Could not cast spell {spellData.spellName}, with target type {spellData.targetType}, no character target supplied");
						return;
					}
				}
				bool flag = false;
				switch (spellData.targetType)
				{
				case ItemTarget.Area:
				case ItemTarget.CharacterArea:
				case ItemTarget.UserArea:
					flag = true;
					break;
				case ItemTarget.Character:
					flag = item == characterTarget;
					break;
				case ItemTarget.CharacterPets:
					flag = characterTarget.HasPet(item);
					break;
				case ItemTarget.CharacterAndPets:
					flag = item == characterTarget || characterTarget.HasPet(item);
					break;
				case ItemTarget.User:
					flag = item == caster;
					break;
				case ItemTarget.UserPets:
					flag = caster.HasPet(item);
					break;
				case ItemTarget.UserAndPets:
					flag = item == caster || caster.HasPet(item);
					break;
				case ItemTarget.UserAndPetsAndParty:
					flag = item == caster || caster.HasPet(item) || caster.HasPartyMember(item);
					break;
				case ItemTarget.UserAndParty:
					flag = item == caster || caster.HasPartyMember(item);
					break;
				case ItemTarget.UserParty:
					flag = caster.HasPartyMember(item);
					break;
				case ItemTarget.MasterOrUserPets:
					flag = character.HasPet(item);
					break;
				case ItemTarget.MasterOrUser:
					flag = item == character;
					break;
				case ItemTarget.MasterOrUserAndPets:
					flag = item == character || character.HasPet(item);
					break;
				case ItemTarget.MasterOrUserAndPetsAndParty:
					flag = item == character || character.HasPet(item) || character.HasPartyMember(item);
					break;
				case ItemTarget.MasterOrUserAndParty:
					flag = item == character || character.HasPartyMember(item);
					break;
				case ItemTarget.MasterOrUserParty:
					flag = character.HasPartyMember(item);
					break;
				}
				if (flag)
				{
					if (targetAlignment == item.GetAlignment())
					{
						item.WasHitBySpellPayload(spellData, caster);
						item.WasHitBySpell(spellData, caster);
					}
					if (item.GetAlignment() != caster.GetAlignment())
					{
						item.RespondToAttack(caster);
					}
				}
			}
			bool num = spellData.payloadEffects.Find((EffectData x) => x.buffType == EffectType.HPRecharge && x.value < 0) != null || spellData.effects.Find((EffectData x) => x.buffType == EffectType.HPRecharge && x.value < 0) != null;
			bool flag2 = spellData.sphereType == SpellSphere.Rage;
			if (!(num || flag2))
			{
				return;
			}
			Collider[] array = Physics.OverlapSphere(position, (float)spellData.range * 0.25f, LayerMask.GetMask("Player Damagable"));
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].TryGetComponent<ContainerDestroyable>(out var component))
				{
					component.Destroyed();
				}
			}
		}
	}
