	public class DroppedItem : InteractableSceneObject
	{
		[SerializeField]
		private DroppedItemNameplate nameplate;

		[SerializeField]
		private AnimationCurve posCurve;

		[SerializeField]
		private AnimationCurve heightCurve;

		private GameObject currentItem;

		private bool isHovered;

		private const float tweenDuration = 0.5f;

		public Item Item { get; private set; }

		private void Awake()
		{
			base.InteractRange = 1f;
			base.InteractionPriority = 1;
		}

		public void SetItem(Item item)
		{
			if (currentItem != null)
			{
				UnityEngine.Object.Destroy(currentItem);
			}
			Item = item;
			Item.slotIndex = -1;
			nameplate.SetToItem(item);
			UtilityTG.UIForceRebuildLayout(base.gameObject);
			currentItem = UnityEngine.Object.Instantiate(item.GetItemPrefab(), base.transform);
			currentItem.transform.localPosition = Vector3.zero;
			Equipment component = currentItem.GetComponent<Equipment>();
			if (component != null)
			{
				component.SetDropped();
			}
			base.gameObject.SetActive(value: true);
		}

		public void Drop(Item item, Vector3 startPos, Vector3 targetLocation, bool skipSoundAndDropTween)
		{
			base.transform.localScale = Vector3.one;
			SetItem(item);
			float num = 0.5f * UnityEngine.Random.Range(0.9f, 1.1f);
			if (!skipSoundAndDropTween)
			{
				item.PlayLandSound(Mathf.Max(num - 0.2f, 0f));
			}
			if (LevelGenerator.currentInstance != null)
			{
				LevelGenerator.currentInstance.AddDroppedItem(this);
			}
			else if (SingletonBehaviour<Town>.InstanceExists())
			{
				base.transform.SetParent(SingletonBehaviour<Town>.Instance.GetActiveContainersParent);
			}
			targetLocation = ActiveLevel.AdjustPositionToNavMesh(targetLocation, startPos, performObstructionTest: true);
			if (skipSoundAndDropTween)
			{
				base.transform.position = targetLocation;
				currentItem.transform.rotation = Quaternion.identity;
			}
			else
			{
				StartCoroutine(DoDropBounce(startPos, targetLocation, num));
			}
		}

		private IEnumerator DoDropBounce(Vector3 startPos, Vector3 targetLocation, float duration)
		{
			Transform parentTransform = base.transform;
			parentTransform.position = startPos;
			Transform meshTransform = currentItem.transform;
			List<float> rotationFlips = new List<float> { 0.75f, 0.9f };
			float rotationSpeed = 1500f;
			float pitchMult = UnityEngine.Random.Range(-1, 1);
			float yawMult = UnityEngine.Random.Range(-1, 1);
			float rollMult = UnityEngine.Random.Range(-1, 1);
			float time = 0f;
			while (true)
			{
				float num;
				time = (num = time + Time.deltaTime);
				if (!(num < duration))
				{
					break;
				}
				float num2 = Mathf.Clamp01(time / duration);
				float t = posCurve.Evaluate(num2);
				float num3 = heightCurve.Evaluate(num2);
				parentTransform.position = Vector3.Lerp(startPos, targetLocation, t).WithY(targetLocation.y + num3 * 2.5f);
				if (rotationFlips.Count > 0 && num2 > rotationFlips[0])
				{
					pitchMult = UnityEngine.Random.Range(-1, 1);
					yawMult = UnityEngine.Random.Range(-1, 1);
					rollMult = UnityEngine.Random.Range(-1, 1);
					rotationFlips.RemoveAt(0);
				}
				meshTransform.Rotate(Vector3.up, rotationSpeed * yawMult * Time.deltaTime, Space.Self);
				meshTransform.Rotate(Vector3.right, rotationSpeed * pitchMult * Time.deltaTime, Space.Self);
				meshTransform.Rotate(Vector3.forward, rotationSpeed * rollMult * Time.deltaTime, Space.Self);
				yield return null;
			}
			parentTransform.position = targetLocation;
			meshTransform.rotation = Quaternion.identity;
		}

		public override void Interact(Character interactor = null)
		{
			bool flag = interactor.inventory.Contains(Item);
			Item.slotIndex = -1;
			bool flag2 = false;
			if (!flag)
			{
				if (interactor.IsPlayer() && Item.itemType == ItemType.Potion && interactor.TryGetFirstFreeHotbarSlot(out var slot) && interactor.AddItemToHotbar(Item, slot, AddItemReason.Loot))
				{
					flag2 = true;
				}
				if (!flag2)
				{
					flag2 = interactor.AddItemToInventory(Item, AddItemReason.Loot);
				}
			}
			if (LevelGenerator.currentInstance != null)
			{
				LevelGenerator.currentInstance.RemoveDroppedItem(this);
				Item.PlayTakeSound();
			}
			else if (SingletonBehaviour<Town>.InstanceExists())
			{
				bool flag3 = false;
				foreach (Transform item in SingletonBehaviour<Town>.Instance.GetActiveContainersParent)
				{
					if (item == base.transform)
					{
						flag3 = true;
						break;
					}
				}
				if (flag3)
				{
					base.transform.SetParent(null);
				}
			}
			if (!flag2 && !flag)
			{
				Item.Drop(interactor.myTransform.position);
			}
			else
			{
				Item.PlayTakeSound();
			}
			UnityEngine.Object.Destroy(base.gameObject);
		}

		public void Remove()
		{
			base.transform.SetParent(null);
			UnityEngine.Object.Destroy(base.gameObject);
		}

		private void LateUpdate()
		{
			nameplate.gameObject.SetActive(isHovered || PlayerUI.ShouldShowItemTooltips);
		}

		private void OnMouseEnter()
		{
			SetHovered(isHovered: true);
		}

		private void OnMouseExit()
		{
			SetHovered(isHovered: false);
		}

		public void SetHovered(bool isHovered)
		{
			this.isHovered = isHovered;
			nameplate.SetIsHovered(isHovered);
		}

		public override void InteractionSelect(Character interactor)
		{
			base.InteractionSelect(interactor);
			SetHovered(isHovered: true);
		}

		public override void InteractionDeselect(Character interactor = null)
		{
			base.InteractionDeselect(interactor);
			SetHovered(isHovered: false);
		}
	}
	public class DroppedItemNameplate : MonoBehaviour
	{
