		private Image nameBackdrop;

		private VisualSetting currentVisualSetting;

		public void SetToItem(Item item)
		{
			UpdateVisualSetting(item);
			itemNameText.text = item.ItemDisplayName;
			itemNameText.color = currentVisualSetting.textColorNormal;
			nameBackdrop.sprite = currentVisualSetting.backdropSpriteNormal;
			nameBackdrop.color = currentVisualSetting.backdropColorNormal;
			SetIsHovered(isHovered: false);
		}

		private void UpdateVisualSetting(Item item)
		{
			bool hasSpecialEffects = item.HasSpecialEffects;
			if (item.isArtifact)
			{
				currentVisualSetting = artifactVisuals;
			}
			else if (item.isUnique)
			{
				currentVisualSetting = uniqueVisuals;
			}
			else if (hasSpecialEffects)
			{
				currentVisualSetting = hasBonusesVisuals;
			}
			else
			{
				currentVisualSetting = basicVisuals;
			}
		}

		public void SetIsHovered(bool isHovered)
		{
			if (isHovered)
			{
				nameBackdrop.sprite = currentVisualSetting.backdropSpriteHover;
				nameBackdrop.color = currentVisualSetting.backdropColorHover;
				itemNameText.color = currentVisualSetting.textColorHover;
			}
			else
			{
				nameBackdrop.sprite = currentVisualSetting.backdropSpriteNormal;
				nameBackdrop.color = currentVisualSetting.backdropColorNormal;
				itemNameText.color = currentVisualSetting.textColorNormal;
			}
		}
	}
	public class Equipment : MonoBehaviour
	{
		public Transform weapon;

		[Space(10f)]
		public Transform mainHandle;

		public Transform offHandle;

		public Transform droppedHandle;

		private Vector3 originalPosition;

		private Vector3 originalScale;

		private Quaternion originalRotation;

		private bool hasInitialized;

		private bool isDropped;

		private void Init()
		{
			originalPosition = weapon.localPosition;
			originalRotation = weapon.localRotation;
			originalScale = weapon.localScale;
			hasInitialized = true;
		}

		public void SetMainHand()
		{
			isDropped = false;
			SetNewParent(mainHandle);
		}

		public void SetOffHand()
		{
			isDropped = false;
			SetNewParent(offHandle);
		}

		public void SetDropped()
		{
			isDropped = true;
			SetNewParent(droppedHandle);
		}

		public void SetNewParent(Transform handle)
		{
			if (!hasInitialized)
			{
				Init();
			}
			if (handle == null)
			{
				weapon.SetParent(base.transform);
				weapon.SetLocalPositionAndRotation(originalPosition, originalRotation);
				weapon.localScale = Vector3.one;
				return;
			}
			weapon.SetParent(handle);
			weapon.SetLocalPositionAndRotation(Vector3.zero, Quaternion.identity);
			if (isDropped)
			{
				weapon.localScale = new Vector3(originalScale.x / handle.transform.lossyScale.x * 0.3f, originalScale.y / handle.transform.lossyScale.y * 0.3f, originalScale.z / handle.transform.lossyScale.z * 0.3f);
			}
			else
			{
				weapon.localScale = new Vector3(originalScale.x / handle.transform.lossyScale.x, originalScale.y / handle.transform.lossyScale.y, originalScale.z / handle.transform.lossyScale.z);
			}
		}
	}
	public class EquipmentHandle : MonoBehaviour
	{
		[Range(0f, 3f)]
		public float scaleMultiplier = 1f;

		public GameObject CurrentEquipment { get; private set; }

		public void SetEquipment(Item item)
		{
			if (item == null)
			{
				if (CurrentEquipment != null)
				{
					UnityEngine.Object.Destroy(CurrentEquipment);
				}
				return;
			}
			if (CurrentEquipment != null)
			{
				UnityEngine.Object.Destroy(CurrentEquipment);
			}
			CurrentEquipment = UnityEngine.Object.Instantiate(item.GetItemPrefab(), base.transform);
			CurrentEquipment.layer = LayerMask.NameToLayer("Player");
			MeshRenderer componentInChildren = CurrentEquipment.GetComponentInChildren<MeshRenderer>();
			if (componentInChildren != null)
			{
				componentInChildren.gameObject.layer = LayerMask.NameToLayer("Player");
			}
			GameObject gameObject = null;
			if (item.damageBonuses != null && SingletonBehaviour<FateDB>.InstanceExists())
			{
				foreach (ElementAmount damageBonuse in item.damageBonuses)
				{
					if (damageBonuse.value > 0)
					{
						switch (damageBonuse.type)
						{
						case DamageType.Crushing:
						case DamageType.Slashing:
						case DamageType.Piercing:
							gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_Crushing");
							break;
						case DamageType.Fire:
							gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_Fire");
							break;
						case DamageType.Electric:
							gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_Electric");
							break;
						case DamageType.Ice:
							gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_Ice");
							break;
						case DamageType.Poison:
							gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_Poison");
							break;
						case DamageType.Undead:
							gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_Undead");
							break;
						default:
							continue;
						}
						if (gameObject != null)
						{
							UnityEngine.Object.Instantiate(gameObject, CurrentEquipment.transform);
						}
					}
				}
			}
			if (SingletonBehaviour<FateDB>.InstanceExists())
			{
				gameObject = null;
				if (item.refId.Contains("GrimReaper"))
				{
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_GrimReaper");
				}
				else
				{
					switch (item.refId)
					{
					case "DemonStaff":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_DemonStaff");
						break;
					case "EmpireStaff":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_EmpireStaff");
						break;
					case "GreatClaymore":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_GreatClaymore");
						break;
					case "LightMallet":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_LightMallet");
						break;
					case "LightSabre":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_LightSabre");
						break;
					case "LightSword":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_LightSword");
						break;
					case "SkullStaff":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_SkullStaff");
						break;
					case "Songblade":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_SongBlade");
						break;
					case "TalonAxe":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_TalonAxe");
						break;
					case "Valorblade":
						gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_ValorBlade");
						break;
					}
				}
				if (gameObject != null)
				{
					UnityEngine.Object.Instantiate(gameObject, CurrentEquipment.transform);
				}
			}
			base.transform.localScale = Vector3.one * scaleMultiplier;
			CurrentEquipment.transform.SetLocalPositionAndRotation(Vector3.zero, Quaternion.identity);
			Equipment component = CurrentEquipment.GetComponent<Equipment>();
			if (item.IsInMainHand)
			{
				component.SetMainHand();
			}
			else if (item.IsInOffHand)
			{
				component.SetOffHand();
			}
		}

		public void SetEquipmentActive(bool state)
		{
			if (!(CurrentEquipment == null))
			{
				CurrentEquipment.SetActive(state);
			}
		}

		public void SetEquipment(string itemKey, bool rightHand)
		{
			if (string.IsNullOrEmpty(itemKey))
			{
				if (CurrentEquipment != null)
				{
					UnityEngine.Object.Destroy(CurrentEquipment);
				}
				return;
			}
			if (CurrentEquipment != null)
			{
				UnityEngine.Object.Destroy(CurrentEquipment);
			}
			string exactName = itemKey.Replace("Item_", "");
			GameObject itemPrefabExact = SingletonBehaviour<FateDB>.Instance.GetItemPrefabExact(exactName);
			if (!(itemPrefabExact == null))
			{
				CurrentEquipment = UnityEngine.Object.Instantiate(itemPrefabExact, base.transform);
				base.transform.localScale = Vector3.one * scaleMultiplier;
				CurrentEquipment.transform.SetLocalPositionAndRotation(Vector3.zero, Quaternion.identity);
				MeshRenderer componentInChildren = CurrentEquipment.GetComponentInChildren<MeshRenderer>();
				if (componentInChildren != null)
				{
					componentInChildren.gameObject.layer = LayerMask.NameToLayer("Player");
				}
				Equipment component = CurrentEquipment.GetComponent<Equipment>();
				if (rightHand)
				{
					component.SetMainHand();
				}
				else
				{
					component.SetOffHand();
				}
			}
		}

