							gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_Undead");
							break;
						default:
							continue;
						}
						if (gameObject != null)
						{
							UnityEngine.Object.Instantiate(gameObject, CurrentEquipment.transform);
						}
					}
				}
			}
			if (string.IsNullOrEmpty(aRefID))
			{
				return;
			}
			gameObject = null;
			if (aRefID.Contains("GrimReaper"))
			{
				gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_GrimReaper");
			}
			else
			{
				switch (aRefID)
				{
				case "DemonStaff":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_DemonStaff");
					break;
				case "EmpireStaff":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_EmpireStaff");
					break;
				case "GreatClaymore":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_GreatClaymore");
					break;
				case "LightMallet":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_LightMallet");
					break;
				case "LightSabre":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_LightSabre");
					break;
				case "LightSword":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_LightSword");
					break;
				case "SkullStaff":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_SkullStaff");
					break;
				case "Songblade":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_SongBlade");
					break;
				case "TalonAxe":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_TalonAxe");
					break;
				case "Valorblade":
					gameObject = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Weapon_ValorBlade");
