	public class Item : IComparable<Item>
	{
		private struct NameMod
		{
			public EffectType effect;

			public int tier;

			public bool isPositive;

			public bool IsValid => effect != EffectType.None;
		}

		public bool takeable;

		public bool canInteract;

		public bool operatable;

		public bool useable;

		public bool lockedForSelling;

		public bool nameIdentified;

		public bool defaultMagical;

		public bool isUnique;

		public bool isArtifact;

		public bool isQuestItem;

		public bool autoPickup;

		public bool forcePickupHold;

		public int healAmount;

		public int manaAmount;

		public int staminaAmount;

		public int toHitBonus;

		public int activationRadius;

		public int deactivationRadius;

		public int baseSoundVolume;

		public int baseSoundRadius;

		public int slotsWide;

		public int slotsTall;

		public int slotIndex;

		public WeaponSet weaponSet;

		public bool equipped;

		public int baseLevel;

		public int sockets;

		public int uses;

		public int originalUses;

		public int value;

		public int tarotLevel;

		public float gambleMultiplier;

		public float armorBonus;

		public HeroType heroType;

		public string itemName;

		public string itemBaseName;

		public List<string> nameDamagePrefixKeys;

		public string namePrefixKey;

		public string uniqueNamePrefixKey1;

		public string uniqueNamePrefixKey2;

		public int uniqueNameSplitterIndex;

		public string nameSuffixKey;

		public string refId;

		public ItemGrade grade;

		public Rank rank;

		public TrapType trapType;

		public ItemType itemType;

		public ItemTarget itemTarget;

		public ItemCategory category;

		public TarotFlavor tarotFlavor;

		public DamageType baseDamageType;

		public List<AttributeData> itemRequirements;

		public List<Item> sockedtedItems;

		public List<ElementAmount> damageBonuses;

		public Dictionary<ActivationType, List<EffectData>> effects;

		public Sprite sprite;

		public GameObject physicalObject;

		public ItemData itemData;

		public Action<Item> onIdentifyStatusChanged;

		public Action<Item> onLockedForSellingChanged;

		public Action<Item> onEffectsChanged;

		public Action<Item> onNameChanged;

		public Action<int> onUseCountChanged;

		public float minimumDamage
		{
			get
			{
				int num = Mathf.CeilToInt(itemData.damageRange.Max * (Fate.GradeBonuses[grade] / 100f));
				if (grade > ItemGrade.Normal && num < 1)
				{
					num = 1;
				}
				return Mathf.FloorToInt((itemData.damageRange.Min + (float)num) * Fate.RankMod[rank].powerMultiplier);
			}
		}

		public float maximumDamage
		{
			get
			{
				int num = Mathf.CeilToInt(itemData.damageRange.Max * (Fate.GradeBonuses[grade] / 100f));
				if (grade > ItemGrade.Normal && num < 1)
				{
					num = 1;
				}
				return Mathf.FloorToInt((itemData.damageRange.Max + (float)num) * Fate.RankMod[rank].powerMultiplier);
			}
		}

		public float maxArmorBonus => itemData.armorRange.Max;

		public float attackRadius => itemData.attackRadius;

		public float strikeRadius => itemData.strikeRadius;

		public string useDescription => itemData.description;

		public bool Identified { get; private set; }

		public bool HasPowers
		{
			get
			{
				if (effects == null || !effects.ContainsKey(ActivationType.Passive) || effects[ActivationType.Passive].Count <= 0)
				{
					if (damageBonuses != null)
					{
						return damageBonuses.Count > 0;
					}
					return false;
				}
				return true;
			}
		}

		public string ItemDisplayName
		{
			get
			{
				string text = null;
				if (!Identified || isArtifact || IsHeroItem())
				{
					text = I2Loca.Get(itemBaseName);
				}
				else
				{
					bool flag = I2Loca.GetCurrentLanguageCode() == "es-ES";
					text = "";
					text += I2Loca.Get(itemBaseName);
					if (nameDamagePrefixKeys != null)
					{
						if (!flag)
						{
							foreach (string nameDamagePrefixKey in nameDamagePrefixKeys)
							{
								if (!text.Contains(nameDamagePrefixKey))
								{
									text = I2Loca.Get(nameDamagePrefixKey) + " " + text;
								}
							}
						}
						else
						{
							foreach (string nameDamagePrefixKey2 in nameDamagePrefixKeys)
							{
								if (!text.Contains(nameDamagePrefixKey2))
								{
									text = text + " " + I2Loca.Get(nameDamagePrefixKey2);
								}
							}
						}
					}
					if (isUnique)
					{
						if (string.IsNullOrEmpty(uniqueNamePrefixKey1) || string.IsNullOrEmpty(uniqueNamePrefixKey2))
						{
							UnityEngine.Debug.LogError("Unique item " + itemBaseName + " has null or empty unique name key(s) (key1: " + uniqueNamePrefixKey1 + ", key2: " + uniqueNamePrefixKey2 + ")");
						}
						else
						{
							string text2 = ((uniqueNameSplitterIndex == 0) ? "" : "'");
							string text3 = ((!flag) ? (I2Loca.Get(uniqueNamePrefixKey1) + text2 + I2Loca.Get(uniqueNamePrefixKey2)) : ((uniqueNameSplitterIndex == 1) ? (I2Loca.Get(uniqueNamePrefixKey2) + I2Loca.Get(uniqueNamePrefixKey1)) : (I2Loca.Get(uniqueNamePrefixKey2) + " " + I2Loca.Get(uniqueNamePrefixKey1))));
							text = I2Loca.GetIgnoreLinebreaksFormat("ItemUniqueNamePrefix", text3, text);
						}
					}
					else if (!string.IsNullOrEmpty(namePrefixKey))
					{
						text = ((!flag) ? (I2Loca.Get(namePrefixKey) + " " + text) : (text + " " + I2Loca.Get(namePrefixKey)));
					}
					if (!string.IsNullOrEmpty(nameSuffixKey))
					{
						text = text + " " + I2Loca.GetFormat("ItemUniqueNameSuffix", I2Loca.Get(nameSuffixKey));
					}
				}
				if (grade != 0)
				{
					text = "<style=C1>" + I2Loca.Get(grade.ToString()) + "</style> " + text;
				}
				if (rank != 0)
				{
					text = I2Loca.GetFormat($"ItemRankPrefix_{rank}", text);
				}
				return text;
			}
		}

		public bool Container => category == ItemCategory.Container;

		public bool IsMelee
		{
			get
			{
				if (category == ItemCategory.Weapon && itemType != ItemType.Bow)
				{
					return itemType != ItemType.Crossbow;
				}
				return false;
			}
		}

		public bool IsInMainHand
		{
			get
			{
				if (slotIndex == 6)
				{
					return category == ItemCategory.Weapon;
				}
				return false;
			}
		}

		public bool IsInOffHand
		{
			get
			{
				if (slotIndex == 7)
				{
					if (category != ItemCategory.Weapon)
					{
						return itemType == ItemType.Shield;
					}
					return true;
				}
				return false;
			}
		}

		public bool IsSlotValid => Fate.IsItemSlotValid(slotIndex);

		public bool InHotbarSlot => Fate.IsItemSlotInHotbar(slotIndex);

		public bool InEquipmentSlot => Fate.IsItemSlotInEquipmentSlot(slotIndex);

		public bool InInventoryGrid => Fate.IsItemSlotInInventoryGrid(slotIndex);

		public bool HasSpecialEffects
		{
			get
			{
				if (damageBonuses == null || damageBonuses.Count <= 0)
				{
					if (effects != null && effects.ContainsKey(ActivationType.Passive))
					{
						return effects[ActivationType.Passive].Count > 0;
					}
					return false;
				}
				return true;
			}
		}

		public bool HasUnlimitedUses
		{
			get
			{
				if (itemData.usable)
				{
					return uses == -9999;
				}
				return true;
			}
		}

		public int CompareTo(Item other)
		{
			if (other == null)
			{
				return 1;
			}
			if (category > other.category)
			{
				return 1;
			}
			if (category < other.category)
			{
				return -1;
			}
			if (slotsTall > other.slotsTall)
			{
				return 1;
			}
			if (slotsTall < other.slotsTall)
			{
				return -1;
			}
			if (itemType > other.itemType)
			{
				return 1;
			}
			if (itemType < other.itemType)
			{
				return -1;
			}
			if ((isUnique || other.isUnique) && isUnique != other.isUnique)
			{
				if (!isUnique)
				{
					return -1;
				}
				return 1;
			}
			return itemBaseName.CompareTo(other.itemBaseName);
		}

		public GameObject GetItemPrefab()
		{
			string path = itemData.displayName.Replace("Item_", "");
			return SingletonBehaviour<FateDB>.Instance.GetItemPrefab(this, path);
		}

		public Item()
		{
			operatable = false;
			takeable = true;
			canInteract = false;
			healAmount = 0;
			useable = false;
			equipped = false;
			grade = ItemGrade.Normal;
			rank = Rank.Normal;
			toHitBonus = 0;
			activationRadius = 16;
			deactivationRadius = 16;
			baseSoundVolume = 255;
			baseSoundRadius = 32;
			armorBonus = 0f;
			slotsWide = 1;
			slotsTall = 1;
			slotIndex = -1;
			baseLevel = 1;
			sockets = 0;
			heroType = HeroType.None;
			gambleMultiplier = UnityEngine.Random.Range(0.05f, 0.9f);
			uses = -9999;
			originalUses = -9999;
			defaultMagical = false;
			Identified = false;
			nameIdentified = false;
			trapType = TrapType.TrapNone;
			itemType = ItemType.None;
			itemTarget = ItemTarget.None;
			baseDamageType = DamageType.Slashing;
			category = ItemCategory.Blank;
			isUnique = false;
			isArtifact = false;
			itemName = null;
			refId = null;
			itemBaseName = null;
			namePrefixKey = null;
			value = 0;
			autoPickup = false;
			tarotFlavor = TarotFlavor.None;
			tarotLevel = 0;
			forcePickupHold = false;
			itemRequirements = new List<AttributeData>();
			sockedtedItems = new List<Item>();
			damageBonuses = new List<ElementAmount>();
			effects = new Dictionary<ActivationType, List<EffectData>>();
		}

		public Item(ItemData pItem)
		{
			if (pItem == null)
			{
				UnityEngine.Debug.LogError("Calling Item constructor with null ItemData");
				return;
			}
			itemData = pItem;
			sprite = null;
			itemName = null;
			operatable = false;
			takeable = true;
			canInteract = false;
			healAmount = 0;
			useable = false;
			isUnique = false;
			isArtifact = false;
			equipped = false;
			rank = Rank.Normal;
			toHitBonus = 0;
