			}
			for (int j = 0; j < pItem.damageBonuses.Count; j++)
			{
				AddDamageBonus(pItem.damageBonuses[j].type, pItem.damageBonuses[j].value);
			}
			isArtifact = (isUnique = pItem.artifact);
			Identified = pItem.identified;
			if (!isArtifact && !isUnique)
