				{
					text += "_color";
				}
				SetSprite(text);
			}
			sockets = pItem.sockets;
			if (sockets > slotsTall)
			{
				sockets = slotsTall;
			}
			autoPickup = pItem.autoPickup;
			forcePickupHold = pItem.forcePickupHold;
			CalculateHealManaStamina();
		}

