		private void SetSprite(string iconName)
		{
			slotsTall = itemData.preCalcSize.y;
			slotsWide = itemData.preCalcSize.x;
			try
			{
				sprite = SingletonBehaviour<FateDB>.Instance.spriteStash.Find((Sprite spr) => spr.name.ToLower() == iconName.ToLower());
			}
			catch (Exception)
			{
				UnityEngine.Debug.LogError("Exception finding sprite for icon " + iconName + " in item " + itemBaseName);
			}
		}

		private void CalculateIdentifyLevel()
		{
			int num = 1;
			foreach (KeyValuePair<ActivationType, List<EffectData>> effect in effects)
			{
				for (int i = 0; i < effect.Value.Count; i++)
				{
					int num2 = effect.Value[i].value;
					int effectMaximum = Fate.GetEffectMaximum(effect.Value[i].buffType);
					num2 = ((effectMaximum > 0) ? ((int)((float)num2 / (float)effectMaximum * 40f)) : 0);
					if (num2 == int.MinValue)
					{
						num2 = -2147483647;
					}
					if (num2 > 100)
					{
						num2 = 100;
					}
					if (num2 == int.MinValue)
					{
						num2++;
					}
					if (Mathf.Abs(num2) > num)
					{
						num = Mathf.Abs(num2);
					}
				}
			}
			baseLevel = num;
		}

		public bool PlayerIdentify(bool updateStats = true, bool playSound = true)
		{
			if (Identified)
			{
				return false;
			}
			SetIdentified(newValue: true);
			if (updateStats)
			{
				StatsManager.IncrementStat(Stat.ItemsIdentified);
			}
			if (playSound)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Identify, randomizePitch: true);
			}
			return true;
		}

		public void SetIdentified(bool newValue)
		{
