		public void DeleteContainedItems()
		{
			if (sockedtedItems != null)
			{
				RemoveContainedEffects();
				sockedtedItems.Clear();
			}
		}

		public void RemoveContainedEffects()
		{
			if (sockedtedItems == null)
			{
				return;
			}
			foreach (Item sockedtedItem in sockedtedItems)
			{
				if (!sockedtedItem.effects.TryGetValue(ActivationType.Passive, out var list) || list == null)
				{
					continue;
				}
				foreach (EffectData item in list)
				{
					if (item.buffType == EffectType.AddDamageType)
					{
						DamageType damageType = FateParseHelper.ParseEnum<DamageType>(item.name);
						if (category != ItemCategory.Weapon)
						{
							EffectData effectData = new EffectData(item);
							effectData.buffType = Fate.ConvertDamageTypeToResistance(damageType);
							effectData.value *= 4;
							RemoveEffect(effectData);
						}
						else if (item.value != 0)
						{
							RemoveDamageBonus(damageType, item.value);
						}
					}
					else
					{
						RemoveEffect(item);
					}
				}
			}
		}

		public void ApplyContainedEffects()
		{
			if (sockedtedItems == null)
			{
				return;
			}
			foreach (Item sockedtedItem in sockedtedItems)
			{
				if (!sockedtedItem.effects.TryGetValue(ActivationType.Passive, out var list))
				{
					continue;
				}
				foreach (EffectData item in list)
				{
					if (item.buffType == EffectType.AddDamageType)
					{
						DamageType damageType = FateParseHelper.ParseEnum<DamageType>(item.name);
						if (category != ItemCategory.Weapon)
						{
							EffectData effectData = new EffectData(item);
							effectData.buffType = Fate.ConvertDamageTypeToResistance(damageType);
							effectData.value *= 4;
							AddEffect(effectData);
						}
						else if (item.value != 0)
						{
							AddDamageBonus(damageType, item.value);
						}
					}
					else
					{
						AddEffect(item);
					}
				}
			}
		}

		public ItemSaveData GetItemSave()
		{
			ItemSaveData itemSaveData = new ItemSaveData();
			FillInstance(itemSaveData);
			return itemSaveData;
		}

		public void FillInstance(ItemSaveData pInstance)
		{
			pInstance.armorBonus = armorBonus;
			pInstance.slotIndex = slotIndex;
			pInstance.weaponSet = weaponSet;
			pInstance.refId = refId;
			pInstance.baseName = itemBaseName;
			pInstance.nameDamagePrefixes = nameDamagePrefixKeys;
			pInstance.uniqueNamePrefixKey1 = uniqueNamePrefixKey1;
			pInstance.uniqueNamePrefixKey2 = uniqueNamePrefixKey2;
			pInstance.namePrefix = namePrefixKey;
			pInstance.nameSuffix = nameSuffixKey;
			pInstance.name = itemName;
			pInstance.splitterIndex = uniqueNameSplitterIndex;
			pInstance.value = value;
			pInstance.trapType = trapType;
			pInstance.uses = uses;
			pInstance.originalUses = originalUses;
			pInstance.rank = rank;
			pInstance.grade = grade;
			pInstance.unique = isUnique;
			pInstance.artifact = isArtifact;
			pInstance.isQuestItem = isQuestItem;
			pInstance.lockedForSelling = lockedForSelling;
			pInstance.identified = Identified;
			pInstance.sockets = sockets;
			pInstance.heroType = heroType;
			pInstance.damageBonuses = damageBonuses;
			pInstance.tarotFlavor = tarotFlavor;
			pInstance.tarotLevel = tarotLevel;
			if (effects != null && effects.Count > 0)
			{
				List<AppliedEffect> list = GetEffects();
				pInstance.effects = new List<EffectSave>();
				foreach (AppliedEffect item in list)
				{
					pInstance.effects.Add(new EffectSave(item));
				}
			}
			if (sockedtedItems != null && sockedtedItems.Count > 0)
			{
				pInstance.internalItems = new List<ItemSaveData>();
				for (int i = 0; i < sockedtedItems.Count; i++)
				{
					ItemSaveData itemSaveData = new ItemSaveData();
					sockedtedItems[i].FillInstance(itemSaveData);
					pInstance.internalItems.Add(itemSaveData);
				}
			}
		}

		public List<AppliedEffect> GetEffects()
		{
			if (effects == null)
			{
				return null;
			}
			List<EffectData> list = new List<EffectData>();
			foreach (KeyValuePair<ActivationType, List<EffectData>> effect in effects)
			{
				list.AddRange(effect.Value);
			}
			List<AppliedEffect> list2 = new List<AppliedEffect>();
			foreach (EffectData item in list)
			{
				list2.Add(new AppliedEffect(item, 1, null, slotIndex));
			}
			return list2;
		}

		public float EffectValue(ActivationType activationType, EffectType effectType)
		{
			if (effects == null || !effects.ContainsKey(activationType) || effects[activationType].IsEmpty())
			{
				return 0f;
			}
			EffectData effectData = effects[activationType].Find((EffectData a) => a.buffType == effectType);
			if (effectData == null)
			{
				return 0f;
			}
			return activationType switch
			{
				ActivationType.Usage => effectData.value, 
				ActivationType.Passive => effectData.chance, 
				_ => 0f, 
			};
		}

		public virtual void AddEffect(EffectSave savedEffect)
		{
			AddEffect(savedEffect.effectData, savedEffect.level).duration = savedEffect.duration;
		}

		public virtual EffectData AddEffect(EffectData effect, int sourceLevel)
		{
			if (!effects.ContainsKey(effect.activationType) || effects[effect.activationType] == null)
			{
				effects[effect.activationType] = new List<EffectData>();
			}
			if (effect.exclusive)
			{
				EffectData effectData = effects[effect.activationType].Find((EffectData e) => e == effect);
				if (effectData != null)
				{
					RemoveEffect(effectData);
				}
			}
			else if (effect.permanent || effect.duration == -1000)
			{
				EffectData effectData2 = effects[effect.activationType].Find((EffectData e) => e == effect);
				if (effectData2 != null)
				{
					effectData2.value += effect.value;
					effectData2.value2 += effect.value2;
					effectData2.value3 += effect.value3;
					return effectData2;
				}
			}
			effects[effect.activationType].Add(new EffectData(effect));
			onEffectsChanged?.Invoke(this);
			return effect;
		}

		public void ApplyInstance(ItemSaveData pInstance)
		{
			ClearEffects();
			refId = pInstance.refId;
			itemBaseName = pInstance.baseName;
			nameDamagePrefixKeys = pInstance.nameDamagePrefixes;
			uniqueNamePrefixKey1 = pInstance.uniqueNamePrefixKey1;
			uniqueNamePrefixKey2 = pInstance.uniqueNamePrefixKey2;
			namePrefixKey = pInstance.namePrefix;
			nameSuffixKey = pInstance.nameSuffix;
			uniqueNameSplitterIndex = pInstance.splitterIndex;
			itemName = pInstance.name;
			armorBonus = pInstance.armorBonus;
			uses = pInstance.uses;
			value = pInstance.value;
			if (pInstance.originalUses != -9997)
			{
				originalUses = pInstance.originalUses;
			}
			isUnique = pInstance.unique;
			isArtifact = pInstance.artifact;
			isQuestItem = pInstance.isQuestItem;
			lockedForSelling = pInstance.lockedForSelling;
			rank = pInstance.rank;
			grade = pInstance.grade;
			SetTrapType(pInstance.trapType);
			Identified = pInstance.identified;
			sockets = pInstance.sockets;
			heroType = pInstance.heroType;
			slotIndex = pInstance.slotIndex;
			weaponSet = pInstance.weaponSet;
			damageBonuses = pInstance.damageBonuses;
			tarotFlavor = pInstance.tarotFlavor;
			tarotLevel = pInstance.tarotLevel;
			effects = new Dictionary<ActivationType, List<EffectData>>();
			if (pInstance.effects != null)
			{
				foreach (EffectSave effect in pInstance.effects)
				{
					AddEffect(effect);
				}
			}
			CalculateIdentifyLevel();
			if (pInstance.internalItems != null)
			{
				for (int i = 0; i < pInstance.internalItems.Count; i++)
				{
					ItemSaveData item = pInstance.internalItems[i];
					if (item.refId == "Gold")
					{
						AddGoldItem(item.value);
						continue;
					}
					Item item2 = new Item(SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData a) => a.displayName == item.baseName));
					item2.ApplyInstance(item);
					if (sockedtedItems == null)
					{
						sockedtedItems = new List<Item>();
					}
					sockedtedItems.Add(item2);
				}
			}
			CalculateHealManaStamina();
		}

		private void ClearEffects()
		{
			effects.Clear();
			CalculateHealManaStamina();
			onEffectsChanged?.Invoke(this);
		}

		public int Armor()
		{
			float num = ((grade != 0) ? maxArmorBonus : armorBonus);
			float num2 = Mathf.Ceil(num * Fate.GradeBonuses[grade] / 100f);
			if (grade != 0 && num2 < 1f)
			{
				num2 = 1f;
			}
			return Mathf.FloorToInt((num + num2) * Fate.RankMod[rank].powerMultiplier);
		}

		public uint GetPurchaseValueByMerchant(MerchantType merchantType)
		{
			switch (merchantType)
			{
			case MerchantType.Goods:
			case MerchantType.Traveling:
			case MerchantType.Magic:
			case MerchantType.Fish:
			case MerchantType.Jeweler:
			case MerchantType.BreakGems:
			case MerchantType.Trader:
			case MerchantType.Weapons:
			case MerchantType.BreakWeapons:
			case MerchantType.Armor:
			case MerchantType.Potions:
			case MerchantType.Curator:
			case MerchantType.WeaponsArmor:
			case MerchantType.Enchanter:
			case MerchantType.Healer:
			case MerchantType.Minstrel:
			case MerchantType.Identifier:
			case MerchantType.Recruiter:
			case MerchantType.Tarot:
			case MerchantType.Quiz:
				return PurchaseValue();
			case MerchantType.Gambler:
				return GambleValue();
			case MerchantType.Stash:
			case MerchantType.Hero:
				return 0u;
			default:
				UnityEngine.Debug.LogError($"Bad merchant type when trying to get purchase value of item: {merchantType}");
				return uint.MaxValue;
			}
		}

		private uint PurchaseValue()
		{
			int num = value;
			int num2 = (effects.ContainsKey(ActivationType.Passive) ? effects[ActivationType.Passive].Count : 0);
			int num3 = 0;
			for (int i = 0; i < num2; i++)
			{
				if (!Mathf.Approximately(Effect(ActivationType.Passive, i).priceMultiplier, 0f))
				{
					num3++;
				}
			}
			if (num3 > 0)
			{
				num *= num3;
				if (num < 1000)
				{
					num /= 10;
					num += 1000;
				}
			}
			for (int j = 0; j < num2; j++)
			{
				num += Mathf.FloorToInt((float)value * effects[ActivationType.Passive][j].priceMultiplier);
			}
			for (int k = 0; k < damageBonuses.Count; k++)
			{
				num += Mathf.FloorToInt((float)value * (float)damageBonuses[k].value / 10f);
			}
			num += sockets * 500;
			num += (int)(0.5f * ((float)num * (float)sockets));
			num += Mathf.FloorToInt((float)num * Fate.GradeBonuses[grade] / 20f);
			if (originalUses != -9999)
			{
				num = (int)((float)uses / (float)originalUses * (float)num);
			}
			return (uint)num;
		}

		public uint SellValue()
		{
			if (!Identified && effects.TryGetValue(ActivationType.Passive, out var list) && list.Count > 0)
			{
				return (uint)value / 8u;
			}
			return PurchaseValue() / 8;
		}

		public uint EnchantValue()
		{
			uint num = PurchaseValue() / 4;
			if (num < 1000)
			{
				num = 1000u;
			}
			if (category == ItemCategory.Jewelry && num < 10000)
			{
				num = 10000u;
			}
			return num;
		}

		private uint GambleValue()
		{
			return (uint)((float)PurchaseValue() * gambleMultiplier);
		}

		private void RemoveEffect(EffectData effectData)
		{
			if (effectData.activationType == ActivationType.Passive && effects.TryGetValue(ActivationType.Passive, out var list))
			{
				EffectData effectData2 = list.Find((EffectData a) => a.buffType == effectData.buffType);
				if (effectData2 != null)
				{
					effectData2.value -= effectData.value;
					if (effectData2.value == 0)
					{
						list.Remove(effectData2);
					}
				}
			}
			CalculateHealManaStamina();
			onEffectsChanged?.Invoke(this);
		}

		private void CalculateHealManaStamina()
		{
			healAmount = 0;
			manaAmount = 0;
			staminaAmount = 0;
			foreach (KeyValuePair<ActivationType, List<EffectData>> effect in effects)
			{
				if (effect.Value == null)
				{
					continue;
				}
				for (int i = 0; i < effect.Value.Count; i++)
				{
					EffectData effectData = effect.Value[i];
					if (effectData.buffType == EffectType.HP)
					{
						healAmount += effectData.value;
					}
					if (effectData.buffType == EffectType.Mana)
					{
						manaAmount += effectData.value;
					}
					if (effectData.buffType == EffectType.Stamina)
					{
						staminaAmount += effectData.value;
					}
				}
			}
		}

		private void AddEffect(EffectData pEffect)
		{
			if (!effects.ContainsKey(pEffect.activationType))
			{
				effects.Add(pEffect.activationType, new List<EffectData>());
			}
			else if (effects[pEffect.activationType] == null)
			{
				effects[pEffect.activationType] = new List<EffectData>();
			}
			EffectData effectData = effects[pEffect.activationType].Find((EffectData a) => a.buffType == pEffect.buffType);
			if (effectData != null)
			{
				effectData.value += pEffect.value;
			}
			else
			{
				effects[pEffect.activationType].Add(new EffectData(pEffect));
			}
			CalculateHealManaStamina();
			onEffectsChanged?.Invoke(this);
		}

		public void BestowGrade(Fate.Difficulty Difficulty)
		{
			if ((category != ItemCategory.Weapon && category != ItemCategory.Armor) || grade != 0)
			{
				return;
			}
			switch (Difficulty)
			{
			case Fate.Difficulty.Adventurer:
				grade = ItemGrade.Superior;
				break;
			case Fate.Difficulty.Hero:
				grade = ItemGrade.Superior;
				if (UnityEngine.Random.value < 0.25f)
				{
					grade = ItemGrade.Exceptional;
				}
				break;
			case Fate.Difficulty.Legend:
				grade = ItemGrade.Superior;
				if (UnityEngine.Random.value < 0.3f)
				{
					grade = ItemGrade.Exceptional;
				}
				else if (UnityEngine.Random.value < 0.5f)
				{
					grade = ItemGrade.Flawless;
				}
				break;
			case Fate.Difficulty.Page:
				break;
			}
		}

		public bool IsHeroItem()
		{
			return heroType != HeroType.None;
