		private void DetermineName()
		{
			if (isArtifact || IsHeroItem())
			{
				return;
			}
			ItemCategory itemCategory = category;
			if (itemCategory != ItemCategory.Weapon && itemCategory != ItemCategory.Armor && itemCategory != ItemCategory.Jewelry)
			{
				return;
			}
			float num = -1f;
			float num2 = -1f;
			NameMod mod = default(NameMod);
			NameMod mod2 = default(NameMod);
			if (effects.TryGetValue(ActivationType.Passive, out var list) && list != null)
			{
				foreach (EffectData item2 in list)
				{
					bool flag = false;
					bool flag2 = false;
					if (item2.buffType <= EffectType.SkillCharmMagic)
					{
						flag = true;
						flag2 = true;
					}
					else if ((item2.buffType >= EffectType.PercentStrength && item2.buffType <= EffectType.PercentAllResistances) || item2.buffType == EffectType.PercentPoisonResistance)
					{
						flag = true;
						flag2 = false;
					}
					if (flag && flag2 && ((float)Mathf.Abs(item2.value) > num || num == -1f))
					{
						float num3 = item2.value;
						if (MathF.Sign(num3) == MathF.Sign(Fate.GetEffectMaximum(item2.buffType)))
						{
							int effectMaximum = Fate.GetEffectMaximum(item2.buffType);
							int num4 = (int)Mathf.Floor(((effectMaximum > 0) ? Mathf.Abs(num3 / (float)effectMaximum) : 0f) * 5f);
							if (num4 >= 5)
							{
								num4 = 4;
							}
							if (Mathf.Abs(num3) > num)
							{
								num = num3;
								NameMod nameMod = default(NameMod);
								nameMod.effect = item2.buffType;
								nameMod.tier = num4;
								nameMod.isPositive = true;
								mod = nameMod;
							}
						}
						else
						{
							float num5 = 0f;
							if (Fate.GetEffectMinimum(item2.buffType) != 0)
							{
								num5 = ((Fate.GetEffectMaximum(item2.buffType) > 0) ? Mathf.Abs(num3 / (float)Fate.GetEffectMinimum(item2.buffType)) : 0f);
							}
							int num6 = (int)Mathf.Floor(num5 * 2f);
							if (num6 >= 2)
							{
								num6 = 1;
							}
							if (Mathf.Abs(num3) > num)
							{
								num = num3;
								NameMod nameMod = default(NameMod);
								nameMod.effect = item2.buffType;
								nameMod.tier = num6;
								nameMod.isPositive = false;
								mod = nameMod;
							}
						}
					}
					if (!flag || flag2 || (!((float)item2.value > num2) && num2 != -1f))
					{
						continue;
					}
					float num7 = item2.value;
					if (MathF.Sign(num7) == MathF.Sign(Fate.GetEffectMaximum(item2.buffType)))
					{
						int num8 = (int)Mathf.Floor(Mathf.Abs(num7 / (float)Fate.GetEffectMaximum(item2.buffType)) * 5f);
						if (num8 >= 5)
						{
							num8 = 4;
						}
						if (Mathf.Abs(num7) > num2)
						{
							num2 = num7;
							NameMod nameMod = default(NameMod);
							nameMod.effect = item2.buffType;
							nameMod.tier = num8;
							nameMod.isPositive = true;
							mod2 = nameMod;
						}
						continue;
					}
					float num9 = 0f;
					if (Fate.GetEffectMinimum(item2.buffType) != 0)
					{
						num9 = Mathf.Abs(num7 / (float)Fate.GetEffectMinimum(item2.buffType));
					}
					int num10 = (int)Mathf.Floor(num9 * 2f);
					if (num10 >= 2)
					{
						num10 = 1;
					}
					if (Mathf.Abs(num7) > num2)
					{
						num2 = num7;
						NameMod nameMod = default(NameMod);
						nameMod.effect = item2.buffType;
						nameMod.tier = num10;
						nameMod.isPositive = false;
						mod2 = nameMod;
					}
				}
			}
			nameDamagePrefixKeys?.Clear();
			if (!isUnique)
			{
				for (int i = 0; i < damageBonuses.Count; i++)
				{
					ElementAmount elementAmount = damageBonuses[i];
					if (ItemNaming_IsValidDamageType(elementAmount.type))
					{
						if (nameDamagePrefixKeys == null)
						{
							nameDamagePrefixKeys = new List<string>();
						}
						string item = $"ItemPrefix{elementAmount.type}Damage";
						if (!nameDamagePrefixKeys.Contains(item))
						{
							nameDamagePrefixKeys.Add($"ItemPrefix{elementAmount.type}Damage");
						}
					}
				}
			}
			namePrefixKey = ((!isUnique && mod.IsValid) ? (namePrefixKey = GetEffectNameMod(prefix: true, mod)) : null);
			nameSuffixKey = (mod2.IsValid ? (nameSuffixKey = GetEffectNameMod(prefix: false, mod2)) : null);
			onNameChanged?.Invoke(this);
		}

		private static bool ItemNaming_IsValidEffectForPositiveValue(EffectType effect)
		{
			switch (effect)
			{
			case EffectType.Strength:
			case EffectType.Dexterity:
			case EffectType.Vitality:
			case EffectType.Magic:
			case EffectType.Mana:
			case EffectType.HP:
			case EffectType.Stamina:
			case EffectType.ArmorBonus:
			case EffectType.ToHitBonus:
			case EffectType.DamageBonus:
			case EffectType.DamageTaken:
			case EffectType.SkillSword:
			case EffectType.SkillClub:
			case EffectType.SkillHammer:
			case EffectType.SkillAxe:
			case EffectType.SkillSpear:
			case EffectType.SkillStaff:
			case EffectType.SkillPolearm:
			case EffectType.SkillBow:
			case EffectType.SkillDualWield:
			case EffectType.SkillShield:
			case EffectType.SkillAttackMagic:
			case EffectType.SkillDefenseMagic:
			case EffectType.SkillCharmMagic:
			case EffectType.PercentStrength:
			case EffectType.PercentDexterity:
			case EffectType.PercentVitality:
			case EffectType.PercentMagic:
			case EffectType.PercentMaxMana:
			case EffectType.PercentMaxHP:
			case EffectType.PercentStamina:
			case EffectType.PercentSpeed:
			case EffectType.PercentAttackSpeed:
			case EffectType.PercentArmorBonus:
			case EffectType.PercentToHitBonus:
			case EffectType.PercentDamageBonus:
			case EffectType.PercentDamageTaken:
			case EffectType.PercentMagicalDrop:
			case EffectType.PercentGoldDrop:
			case EffectType.PercentCastSpeed:
			case EffectType.PercentLifeStolen:
			case EffectType.PercentManaStolen:
			case EffectType.PercentDamageReflected:
			case EffectType.PercentBlockChance:
			case EffectType.PercentItemRequirements:
				return true;
			default:
				return false;
			}
		}

		private static bool ItemNaming_IsValidEffectForNegativeValue(EffectType effect)
		{
			if ((uint)(effect - 1) <= 10u || (uint)(effect - 27) <= 20u)
			{
				return true;
			}
			return false;
		}

		private static bool ItemNaming_IsValidWeaponSkillEffect(EffectType effect)
		{
			if ((uint)(effect - 13) <= 12u)
			{
				return true;
			}
			return false;
		}

		private static bool ItemNaming_IsValidDamageType(DamageType damageType)
		{
			if ((uint)(damageType - 5) <= 2u || damageType == DamageType.Undead)
			{
				return true;
			}
			return false;
		}

		private static bool ItemNaming_IsResistanceEffect(EffectType effect)
		{
			if ((uint)(effect - 48) <= 7u || effect == EffectType.PercentPoisonResistance)
			{
				return true;
			}
			return false;
		}

		private static string GetEffectNameMod(bool prefix, NameMod mod)
		{
			if (ItemNaming_IsResistanceEffect(mod.effect))
			{
				if (!prefix)
				{
					if (!mod.isPositive)
					{
						return "SuffixNegativeGenericPercentResistance";
					}
					return "SuffixGenericPercentResistance";
				}
				return null;
			}
			if (!(mod.isPositive ? ItemNaming_IsValidEffectForPositiveValue(mod.effect) : ItemNaming_IsValidEffectForNegativeValue(mod.effect)))
			{
				return null;
			}
			if (ItemNaming_IsValidWeaponSkillEffect(mod.effect))
			{
				if (prefix)
				{
					return $"Prefix{mod.tier + 1}WeaponSkill";
				}
				return null;
			}
			return string.Format("{0}{1}{2}{3}", prefix ? "Prefix" : "Suffix", mod.tier + 1, mod.isPositive ? "" : "Negative", Fate.GetEffectName(mod.effect));
		}

		private int AffectingEffects(ActivationType activationType, Character pUser)
		{
			int num = 0;
			for (int i = 0; i < effects[activationType].Count; i++)
			{
				if (effects[activationType][i].AffectsCharacter(pUser))
				{
					num++;
				}
			}
			return num;
		}

		private float EffectValue(ActivationType activationType, EffectType Type, Character pUser)
		{
			float num = 0f;
			for (int i = 0; i < effects[activationType].Count; i++)
			{
				EffectData effectData = effects[activationType][i];
				if (effectData.buffType == Type && effectData.AffectsCharacter(pUser))
				{
					num += (float)effectData.value;
				}
			}
			return num;
		}

		private bool IsCursed(Character pUser)
		{
			if (effects.TryGetValue(ActivationType.Passive, out var list))
			{
				for (int i = 0; i < list.Count; i++)
				{
					if (list[i].AffectsCharacter(pUser) && !list[i].IsPositive)
					{
						return true;
					}
				}
			}
			return false;
		}

		private EffectData Effect(ActivationType ActivationType, int Index)
		{
			return effects[ActivationType][Index];
		}

		private string EffectText(ActivationType activationType, Character pUser)
		{
			if (!effects.TryGetValue(activationType, out var list) || list == null || list.Count == 0)
			{
				return null;
			}
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i].buffType != 0)
				{
					if (i != 0)
					{
						stringBuilder.AppendLine();
					}
					int num = list[i].value;
					_ = list[i].IsPositive;
					Mathf.Abs(num);
					Fate.EffectIsPercent(list[i].buffType);
				}
			}
			return stringBuilder.ToString();
		}

		private void SetTrapType(TrapType TrapType)
		{
			trapType = TrapType;
			switch (TrapType)
			{
			case TrapType.TrapSword:
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_trap);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.SwordTrap, randomizePitch: true);
				break;
			default:
				UnityEngine.Debug.Log("A trap was set and it has no sound");
				break;
			case TrapType.TrapNone:
			case TrapType.TrapExplosion:
			case TrapType.TrapPoison:
				break;
			}
		}

		public DroppedItem Drop(Vector3 worldPosStart, bool skipSoundAndDropTween = false)
		{
			equipped = false;
			slotIndex = -1;
			Vector3 vector = worldPosStart;
			if (!skipSoundAndDropTween)
			{
				if (SceneLoad.CurrentScene == Scene.Dungeon)
				{
					vector = LevelGenerator.currentInstance.RandomOpenPosition(worldPosStart, 1f, 3f);
				}
				else
				{
					vector = worldPosStart + Vector3.up + (Vector3)UnityEngine.Random.insideUnitCircle.normalized * 3f;
					Ray ray = new Ray(vector, Vector3.down);
					int num = 100;
					bool flag = false;
					while (!flag && num > 0)
					{
						num--;
						if (Physics.Raycast(ray, out var hitInfo, 50f, LayerMask.GetMask("Player Walkable")) && NavMesh.SamplePosition(hitInfo.point, out var hit, 0.5f, -1))
						{
							vector = hit.position;
							flag = true;
							break;
						}
						Vector2 insideUnitCircle = UnityEngine.Random.insideUnitCircle;
						ray.origin = worldPosStart + Vector3.up + new Vector3(insideUnitCircle.x, 0f, insideUnitCircle.y).normalized * 3f;
					}
					if (!flag)
					{
						vector = worldPosStart;
					}
				}
			}
			DroppedItem droppedItemGO = FateDB.GetDroppedItemGO();
			droppedItemGO.Drop(this, worldPosStart, vector, skipSoundAndDropTween);
			if (!skipSoundAndDropTween)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Fall, randomizePitch: true);
			}
			return droppedItemGO;
		}

		public void Use(Character pUser, Character pTarget)
		{
			if (uses != -9999)
			{
				uses--;
				onUseCountChanged?.Invoke(uses);
			}
			if (effects.TryGetValue(ActivationType.Usage, out var list))
			{
				for (int i = 0; i < list.Count; i++)
				{
					EffectData effectData = list[i];
					if (effectData.AffectsCharacter(pUser))
					{
						pTarget.AddEffect(effectData, pUser.Level, null);
					}
				}
			}
			PlayUseSound();
		}

		public void Use(Character pUser, Item pTarget)
		{
			if (effects.TryGetValue(ActivationType.Usage, out var list))
			{
				for (int i = 0; i < list.Count; i++)
				{
					EffectData effectData = list[i];
					if (effectData.AffectsCharacter(pUser) && effectData.buffType == EffectType.Identify)
					{
						pTarget.SetIdentified(newValue: true);
						StatsManager.IncrementStat(Stat.ItemsIdentified);
					}
				}
			}
			if (uses != -9999)
			{
				uses--;
				onUseCountChanged?.Invoke(uses);
			}
		}

		public bool CanUse(Character pUser, Character pTarget)
		{
			if (effects.TryGetValue(ActivationType.Usage, out var list))
			{
				for (int i = 0; i < list.Count; i++)
				{
					EffectData eff = list[i];
					if (!eff.AffectsCharacter(pTarget))
					{
						continue;
					}
					switch (eff.buffType)
					{
					case EffectType.WriteSpell:
					{
						SpellData spellData = SingletonBehaviour<FateDB>.Instance.allSpells.Find((SpellData sp) => sp.spellName == eff.name);
						if (spellData == null)
						{
							return false;
						}
						if (!pTarget.CanAddSpellFromItem(this, spellData, out var cantAddReason))
						{
							SingletonBehaviour<Narrator>.Instance.PlayYourLine((cantAddReason == CantAddSpellReason.RequirementsNotMet) ? NarratorLines.Narrator_lowpower : NarratorLines.Narrator_impossible);
							return false;
						}
						break;
					}
					case EffectType.RecoverPassoutPartial:
					case EffectType.RecoverPassoutFull:
					{
						bool result = false;
						if (pTarget.IsPartyMember() && pTarget.IsPassedOut())
						{
							result = true;
						}
						for (int j = 0; j < pTarget.GetPartyMemberCount(); j++)
						{
							if (pTarget.GetPartyMember(j).IsPassedOut())
							{
								result = true;
								break;
							}
						}
						return result;
					}
					}
				}
			}
			return true;
		}

		public bool CanUseOnItem(Item pTarget, Character pUser)
		{
			bool result = false;
			if (effects.TryGetValue(ActivationType.Usage, out var list))
			{
				for (int i = 0; i < list.Count; i++)
				{
					if (list[i].AffectsCharacter(pUser) && list[i].buffType == EffectType.Identify)
					{
						int num;
						if (!pTarget.Identified)
						{
							List<EffectData> list2 = pTarget.effects[ActivationType.Passive];
							num = (((list2 != null && list2.Count > 0) || pTarget.damageBonuses.Count > 0) ? 1 : 0);
						}
						else
						{
							num = 0;
						}
						result = (byte)num != 0;
					}
				}
			}
			return result;
		}

