		public Item SocketItem(Item item)
		{
			if (item == null || item.itemType != ItemType.Gem)
			{
				UnityEngine.Debug.LogWarning("Tried to socket " + ((item != null) ? item.itemBaseName : "NULL") + " into " + itemBaseName + ". Not allowing it because item to socket is null or non-gem item");
				return null;
			}
			RemoveContainedEffects();
			if (sockedtedItems == null)
			{
				sockedtedItems = new List<Item>();
			}
			sockedtedItems.Add(item);
			ApplyContainedEffects();
			return item;
		}

		private void RemoveItem(Item pItem)
		{
			sockedtedItems.Remove(pItem);
		}

