					if (list[i].buffType == EffectType.WriteSpell)
					{
						return true;
					}
				}
			}
			return false;
		}

		private void AddDamageBonus(DamageType damageType, int value)
		{
			ElementAmount elementAmount = damageBonuses.Find((ElementAmount a) => a.type == damageType);
			if (elementAmount != null)
			{
				elementAmount.value += value;
			}
			else
			{
				elementAmount = new ElementAmount
				{
					type = damageType,
					value = value
				};
				damageBonuses.Add(elementAmount);
			}
			onEffectsChanged?.Invoke(this);
		}

		private void RemoveDamageBonus(DamageType damageType, int value)
		{
			ElementAmount elementAmount = damageBonuses.Find((ElementAmount a) => a.type == damageType);
			if (elementAmount != null)
			{
				elementAmount.value -= value;
				if (elementAmount.value <= 0)
				{
					damageBonuses.Remove(elementAmount);
				}
				onEffectsChanged?.Invoke(this);
			}
		}

