	public class Merchant : NPC
	{
		[Header("Merchant")]
		public MerchantType merchantType;

		public ParticleSystem successParticle;

		private uint serviceCost;

		public void DoGreeting(string baseMsg)
		{
			string text = I2Loca.GetMultiLineReplaceTags(baseMsg);
			bool twoButtons = true;
			string positiveOverride = null;
			switch (merchantType)
			{
			case MerchantType.Minstrel:
			{
				int num = Player.PlayerChar.fameRank;
				uint fameNeeded = Player.PlayerChar.fame;
				if (Player.PlayerChar.fameRank >= Fate.MaxFame)
				{
					text = I2Loca.GetReplaceTags("MinstrelFameMax");
					twoButtons = false;
					serviceCost = 0u;
					break;
				}
				serviceCost = Fate.GetFameNeeded(num + 2) * 5;
				if (fameNeeded < Fate.GetFameNeeded(num))
				{
					fameNeeded = Fate.GetFameNeeded(num);
				}
				float num2 = fameNeeded;
				num2 -= (float)Fate.GetFameNeeded(num);
				num2 /= (float)(Fate.GetFameNeeded(num + 1) - Fate.GetFameNeeded(num));
				serviceCost -= (uint)(num2 * (float)serviceCost);
				text += I2Loca.GetMultiLineReplaceTagsFormat("MinstrelPrompt", serviceCost.ToString(), Fate.GetFameName(num + 1), (num + 1).ToString());
				break;
			}
			case MerchantType.Identifier:
				text = I2Loca.Get("NPC_GreetingMsg_ShaztheIdentifier");
				serviceCost = GetIdentifyCostForInventory(Player.PlayerChar.inventory);
				if (serviceCost == 0)
				{
					twoButtons = false;
					positiveOverride = I2Loca.Get("OK");
					break;
				}
				text += string.Format("{0}{1} : {2}{3}{4}", Environment.NewLine, I2Loca.Get("Cost"), "<style=C1>", serviceCost, "</style>");
				break;
			}
			bool inDungeon = LevelGenerator.currentInstance != null;
			if (inDungeon)
			{
				Fate.SetPause(paused: true);
			}
			SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(text, delegate(bool positive)
			{
				if (inDungeon)
				{
					Fate.SetPause(paused: false);
				}
				if (positive)
				{
					OnInteract();
				}
			}, twoButtons, positiveOverride);
		}

		public uint GetIdentifyCostForInventory(List<Item> targetInv)
		{
			if (targetInv == null || targetInv.Count == 0)
			{
				return 0u;
			}
			uint identifyCost = 0u;
			targetInv.ForEach(delegate(Item item)
			{
				if (!item.Identified)
				{
					identifyCost += 100u;
				}
			});
			return identifyCost;
		}

		public void OnInteract()
		{
			MerchantType merchantType = this.merchantType;
			if (merchantType <= MerchantType.Potions)
			{
				switch (merchantType)
				{
				case MerchantType.BreakGems:
				case MerchantType.BreakWeapons:
					break;
				case MerchantType.Goods:
				case MerchantType.Traveling:
				case MerchantType.Magic:
				case MerchantType.Fish:
				case MerchantType.Jeweler:
				case MerchantType.Trader:
				case MerchantType.Weapons:
				case MerchantType.Gambler:
				case MerchantType.Armor:
				case MerchantType.Potions:
					goto IL_0304;
				default:
					return;
				}
			}
			else if (merchantType <= MerchantType.Minstrel)
			{
				if (merchantType <= MerchantType.WeaponsArmor)
				{
					if (merchantType == MerchantType.Curator || merchantType != MerchantType.WeaponsArmor)
					{
						return;
					}
					goto IL_0304;
				}
				switch (merchantType)
				{
				default:
					return;
				case MerchantType.Enchanter:
					break;
				case MerchantType.Minstrel:
					if (serviceCost == 0)
					{
						return;
					}
					if (SingletonBehaviour<PlayerStatus>.Instance.gold >= serviceCost)
					{
						SingletonBehaviour<PlayerStatus>.Instance.RemoveGold(serviceCost);
						Player.PlayerChar.AwardFame(Fate.GetFameNeeded(Player.PlayerChar.fameRank + 1) - Player.PlayerChar.fame);
						if (successParticle != null)
						{
							successParticle.Play();
						}
					}
					else
					{
						ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.Get("ErrorMsg_NotEnoughGold"), 1.5f, 4f, ThatHurt.ThatHurtColor.White, 0.2f);
						SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_lowgold);
					}
					return;
				case MerchantType.Healer:
				{
					Player.PlayerChar.MyVitals.FullHeal(removeNegativeEffects: true);
					ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.Get("HealerUse"), 1.5f, 3.5f, ThatHurt.ThatHurtColor.Healing, 0.2f);
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_healthy);
					GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("HealthRefresh");
					if (particlePrefab != null)
					{
						UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab, base.transform.position, Quaternion.identity), 3f);
					}
					return;
				}
				}
			}
			else
			{
				if (merchantType <= MerchantType.Recruiter)
				{
					switch (merchantType)
					{
					case MerchantType.Identifier:
						if (serviceCost != 0)
						{
							if (SingletonBehaviour<PlayerStatus>.Instance.gold >= serviceCost)
							{
								SingletonBehaviour<PlayerStatus>.Instance.RemoveGold(serviceCost);
								IdentifyAllInInventory(Player.PlayerChar.inventory, Player.PlayerChar);
							}
							else
							{
								ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.Get("ErrorMsg_NotEnoughGold"), 1.5f, 4f, ThatHurt.ThatHurtColor.White, 0.2f);
								SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_lowgold);
							}
						}
						break;
					case MerchantType.Recruiter:
						SimpleSingletonBehaviour<PlayerUI>.Instance.ShowRecruitUI();
						break;
					}
					return;
				}
				switch (merchantType)
				{
				default:
					_ = 16777216;
					return;
				case MerchantType.Tarot:
					break;
				case MerchantType.Quiz:
					return;
				}
			}
			SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.SetItemSelectType(this.merchantType);
			SimpleSingletonBehaviour<PlayerUI>.Instance.ShowInventory(PlayerUI.InventoryStateType.ItemSelect);
			return;
			IL_0304:
			SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.SetMerchant(this);
			SimpleSingletonBehaviour<PlayerUI>.Instance.ShowInventory(PlayerUI.InventoryStateType.Shop);
		}

		public int IdentifyAllInInventory(List<Item> inventory, Character instigator)
		{
			int identifyCount = 0;
			inventory.ForEach(delegate(Item item)
			{
				if (item.PlayerIdentify(updateStats: false, playSound: false))
				{
					int num = identifyCount + 1;
					identifyCount = num;
				}
			});
			if (identifyCount > 0)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Identify, randomizePitch: true);
				StatsManager.IncrementStat(Stat.ItemsIdentified, identifyCount);
			}
			if (successParticle != null)
			{
				successParticle.Play();
			}
			ThatHurt.PopText(instigator.myTransform.position, I2Loca.Get("IdentifierUse"), 1.5f, 3.5f, ThatHurt.ThatHurtColor.Healing, 0.2f);
			return identifyCount;
		}

