		private void OnDestroy()
		{
			switch (merchantType)
			{
			case MerchantType.Goods:
			case MerchantType.Traveling:
			case MerchantType.Magic:
			case MerchantType.Fish:
			case MerchantType.Jeweler:
			case MerchantType.Weapons:
			case MerchantType.Gambler:
			case MerchantType.Armor:
			case MerchantType.Potions:
			case MerchantType.WeaponsArmor:
				MerchantData.onDataUpdated = (Action)Delegate.Remove(MerchantData.onDataUpdated, new Action(GenerateItemInventory));
				break;
			}
		}

		public void GenerateItemInventory()
		{
			if (!Fate.DifficultyMod.TryGetValue(SingletonBehaviour<PlayerStatus>.Instance.Difficulty, out var value))
