				return;
			}
			int num = ((LevelGenerator.currentInstance != null) ? ActiveLevel.GetCurrentDungeonDepth() : ActiveLevel.DigGreedilyAfterDeepestDepthReached());
			int num2 = Mathf.CeilToInt((float)num * value.itemMultiplier);
			List<Item> list = new List<Item>();
			if (merchantType.HasFlag(MerchantType.Fish))
			{
				list.Add(new Item(SingletonBehaviour<MerchantData>.Instance.FindRandomItemByType(ItemType.FishingPole) ?? throw new ArgumentNullException("FishingPole", $"Item type {ItemType.FishingPole} was not found in item manifest, update list or call for a programmer.")));
