						UnityEngine.Debug.Log(i + " fish null");
					}
					else
					{
						list.Add(new Item(itemData));
					}
				}
			}
			if (merchantType.HasFlag(MerchantType.Traveling) || merchantType.HasFlag(MerchantType.Goods))
			{
				list.Add(new Item(SingletonBehaviour<MerchantData>.Instance.FindRandomItemByType(ItemType.FishingPole) ?? throw new ArgumentNullException("FishingPole", $"Item type {ItemType.FishingPole} was not found in item manifest, update list or call for a programmer.")));
				for (int j = 0; j < 8; j++)
				{
					list.Add(new Item(SingletonBehaviour<MerchantData>.Instance.FindRandomItemByType(ItemType.Potion) ?? throw new ArgumentNullException("Potion", $"Item type {ItemType.Potion} was not found in item manifest, update list or call for a programmer.")));
				}
				for (int j = 0; j < 4; j++)
				{
					list.Add(new Item(SingletonBehaviour<MerchantData>.Instance.FindRandomItemByType(ItemType.Scroll) ?? throw new ArgumentNullException("Scroll", $"Item type {ItemType.Scroll} was not found in item manifest, update list or call for a programmer.")));
				}
				list.Add(new Item(SingletonBehaviour<MerchantData>.Instance.GetTownPortalScollItem()));
				for (int j = 0; j < 2; j++)
				{
					list.Add(new Item(SingletonBehaviour<MerchantData>.Instance.FindRandomItemByType(ItemType.Book) ?? throw new ArgumentNullException("Book", $"Item type {ItemType.Book} was not found in item menifest, update list or call for a programmer.")));
				}
			}
			if (merchantType.HasFlag(MerchantType.Magic) || merchantType.HasFlag(MerchantType.Jeweler))
			{
				for (int k = 0; k < 6; k++)
				{
					list.Add(new Item(SingletonBehaviour<MerchantData>.Instance.FindRandomItemByType(ItemType.Gem)));
				}
			}
			int num3 = UnityEngine.Random.Range(50, 60);
			switch (merchantType)
			{
			case MerchantType.Weapons:
			case MerchantType.Gambler:
			case MerchantType.Armor:
			case MerchantType.WeaponsArmor:
				num3 = UnityEngine.Random.Range(18, 24);
				break;
			case MerchantType.Fish:
				num3 = 0;
				break;
			}
			for (int l = 0; l < num3; l++)
			{
				int num4 = UnityEngine.Random.Range(0, 100);
				ItemData itemData2 = SingletonBehaviour<MerchantData>.Instance.FindRandomItemByType(merchantType);
				if (itemData2 == null)
				{
					UnityEngine.Debug.LogWarning(base.CharacterName + " is a " + merchantType.ToString() + " merchant and failed to find a item for it's inventory");
					break;
				}
				int num5 = 40;
				int num6 = 10;
				int num7 = 15;
				switch (merchantType)
				{
				case MerchantType.Gambler:
					num6 = 70;
					num5 = 100;
					num7 = 25;
					break;
				case MerchantType.Goods:
					num5 = 20;
					num6 = 1;
					break;
				case MerchantType.Weapons:
				case MerchantType.Armor:
				case MerchantType.WeaponsArmor:
					num5 = 20;
					num6 = 5;
					break;
				case MerchantType.Jeweler:
					num5 = 50;
					num6 = 20;
					num7 = 25;
					break;
				}
				Item item = new Item(itemData2);
				ActiveLevel.TryRankUpItem(item, num2);
				list.Add(item);
				if (num4 <= num5)
				{
					int num8 = num2;
					int num9 = num2 * 5;
					if (num9 > num2 + 20)
					{
						num9 = num2 + 20;
					}
					if (num2 == 0)
					{
						num8 = 1;
						num9 = 30;
					}
					if (merchantType == MerchantType.Gambler)
					{
						num8 = 20;
						if (num > num8)
						{
							num8 = num;
						}
						num9 = 70 + num;
					}
					if (num4 < num6)
					{
						item.BestowUniquePowers(num, AllowCurse: false, UnityEngine.Random.Range(num8, num9));
					}
					else
					{
						item.TryBestowPowers(num, merchantType == MerchantType.Gambler, UnityEngine.Random.Range(num8, num9));
					}
					if (merchantType == MerchantType.Gambler)
					{
						item.SetIdentified(newValue: false);
						if (!item.effects.ContainsKey(ActivationType.Passive))
						{
							item.effects[ActivationType.Passive] = new List<EffectData>();
						}
						while (item.effects[ActivationType.Passive].Count == 0 && item.damageBonuses.Count == 0)
						{
							item.TryBestowPowers(num, AllowCurse: true, UnityEngine.Random.Range(num8, num9));
						}
					}
					else
					{
						item.SetIdentified(newValue: true);
					}
				}
				if (UnityEngine.Random.Range(0, 100) < num7 && !item.isUnique)
				{
					item.BestowSockets(AllowUnique: false);
				}
				if (UnityEngine.Random.Range(0, 1000) < 100)
				{
					item.BestowGrade(SingletonBehaviour<PlayerStatus>.Instance.Difficulty);
				}
			}
			foreach (Item item2 in list)
			{
				item2.slotIndex = -1;
			}
			list.Sort();
			inventory.Clear();
			foreach (Item item3 in list)
			{
				AddItemToInventory(item3, AddItemReason.StartingItems);
			}
		}
	}
