	public class AttackAnimationState : StateMachineBehaviour
	{
		public override void OnStateEnter(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			if (animator.GetNextAnimatorClipInfo(layerIndex).Length != 0)
			{
				animator.GetComponent<Character>().SetAttackAnimKey(animator.GetNextAnimatorClipInfo(layerIndex)[0].clip.name);
			}
			else
			{
				animator.GetComponent<Character>().SetAttackAnimKey(animator.GetCurrentAnimatorClipInfo(layerIndex)[0].clip.name);
			}
		}
	}
	public class DeathAnimationState : StateMachineBehaviour
	{
		public override void OnStateEnter(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			if (animator.GetNextAnimatorClipInfo(0).Length != 0)
			{
				animator.GetComponent<Character>().SetDeathAnimKey(animator.GetNextAnimatorClipInfo(0)[0].clip.name);
			}
			else
			{
				animator.GetComponent<Character>().SetDeathAnimKey(animator.GetCurrentAnimatorClipInfo(0)[0].clip.name);
			}
		}
	}
	public class Monster : Character
	{
		private MonsterSounds m_monsterSounds;

		public bool loadedAsDead;

		private bool hasPlayedUniqueIdleSound;

		private bool hasChangedAgentPrio;

		private int initialAgentPrio;

		protected GameObject activeGroundMarker;

		protected Alignment activeGroundMarkerAlignment;

		private CharacterCustomizationDefaults charCustom;

		private IEnumerator NemesisPlayerWaitRoutine()
		{
			while (Player.PlayerChar == null)
			{
				yield return null;
			}
			Player playerChar = Player.PlayerChar;
			playerChar.onEquipmentChanged = (Action)Delegate.Combine(playerChar.onEquipmentChanged, new Action(MatchPlayer));
			Player playerChar2 = Player.PlayerChar;
			playerChar2.onWeaponSetChanged = (Action<WeaponSet>)Delegate.Combine(playerChar2.onWeaponSetChanged, new Action<WeaponSet>(base.SetActiveWeaponSet));
			MatchPlayer();
		}

		private void MatchPlayer()
		{
			for (int i = 0; i < inventory.Count; i++)
			{
				if (inventory[i].InEquipmentSlot)
				{
					UnequipItem(inventory[i]);
				}
			}
			charCustom.SetHelmet(null);
			charCustom.SetGloves(null);
			charCustom.SetBoots(null);
			charCustom.SetUpper(null);
			charCustom.SetBack(null);
			inventory = new List<Item>();
			if (Player.PlayerChar == null)
			{
				return;
			}
			int num = maxHpBase;
			AttributeSet attributeSet = Player.PlayerChar.attributes;
			foreach (Attribute value in Enum.GetValues(typeof(Attribute)))
			{
				attributes.SetBasePoints(value, attributeSet.GetAttribute(value, allowEffects: false, addIfNull: false));
			}
			base.Level = Player.PlayerChar.Level;
			nextLevelExperience = Fate.GetExperienceNeeded(base.Level);
			CalculateMaxHP();
			CalculateMaxMana();
			CalculateMaxStamina();
			int num2 = maxHpBase - num;
			if (num2 > 0)
			{
				ModifyHP(num2);
			}
			SetActiveWeaponSet(Player.PlayerChar.GetActiveWeaponSet);
			Dictionary<SpellSphere, List<SpellData>> dictionary = Player.PlayerChar.knownSpells;
			knownSpells = new Dictionary<SpellSphere, List<SpellData>>();
			activeSpell = null;
			foreach (KeyValuePair<SpellSphere, List<SpellData>> item2 in dictionary)
			{
				for (int j = 0; j < item2.Value.Count; j++)
				{
					AddSpell(item2.Value[j]);
				}
			}
			foreach (Item item3 in Player.PlayerChar.inventory.FindAll((Item itm) => itm.equipped))
			{
				Item item = new Item(item3);
				item.equipped = false;
				AddItemToInventory(item, AddItemReason.Loot, item3.slotIndex, desiredSlotIsGlobal: true);
				EquipItem(item, item3.weaponSet);
				switch (item.itemType)
				{
				case ItemType.Helmet:
					charCustom.SetHelmet(item.itemData.displayName);
					break;
				case ItemType.Gloves:
					charCustom.SetGloves(item.itemData.displayName);
					break;
				case ItemType.Boots:
					charCustom.SetBoots(item.itemData.displayName);
					break;
				case ItemType.Shirt:
					charCustom.SetUpper(item.itemData.displayName);
					break;
				case ItemType.Back:
					charCustom.SetBack(item.itemData.displayName);
					break;
				}
			}
		}

		public override void Init()
		{
			base.Init();
			CharacterVitals characterVitals = myVitals;
			characterVitals.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Combine(characterVitals.OnKilled, new Action<CharacterVitals.Damage>(OnVitalsKilled));
			CharacterVitals characterVitals2 = myVitals;
			characterVitals2.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Combine(characterVitals2.OnDamaged, new Action<CharacterVitals.Damage>(RespondToAttack));
			m_monsterSounds = GetComponent<MonsterSounds>();
			initialAgentPrio = path.avoidancePriority;
			if (!IsShrine() && !loadedAsDead)
			{
				if (IsPet() && HasMaster() && Master().IsPlayer())
				{
					return;
				}
				SkinnedMeshRenderer[] componentsInChildren = GetComponentsInChildren<SkinnedMeshRenderer>(includeInactive: true);
				for (int i = 0; i < componentsInChildren.Length; i++)
				{
					componentsInChildren[i].gameObject.layer = LayerMask.NameToLayer("NPC");
				}
				UpdateGroundMarker(GetAlignment());
			}
			if (family != Tableflip.Family.Nemesis || loadedAsDead)
			{
				return;
			}
			allowDropEquipment = true;
			allowDropInventory = true;
			charCustom = GetComponent<CharacterCustomizationDefaults>();
			if (charCustom == null)
			{
				UnityEngine.Debug.LogError("Component CharacterCustomizationDefaults missing on Nemesis class enemy: " + monsterData?.displayName);
				return;
			}
			charCustom.IsNemesis = true;
			if (monsterData.minions != null && monsterData.minions.Count > 0)
			{
				LevelGenerator.currentInstance.AttemptGenerateMinions(monsterData, this);
			}
			if (Player.PlayerChar != null)
			{
				Player playerChar = Player.PlayerChar;
				playerChar.onEquipmentChanged = (Action)Delegate.Combine(playerChar.onEquipmentChanged, new Action(MatchPlayer));
				Player playerChar2 = Player.PlayerChar;
				playerChar2.onWeaponSetChanged = (Action<WeaponSet>)Delegate.Combine(playerChar2.onWeaponSetChanged, new Action<WeaponSet>(base.SetActiveWeaponSet));
				MatchPlayer();
			}
			else
			{
				StartCoroutine(NemesisPlayerWaitRoutine());
			}
		}

		public void UnRegisterKilled()
		{
			CharacterVitals characterVitals = myVitals;
			characterVitals.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals.OnKilled, new Action<CharacterVitals.Damage>(OnVitalsKilled));
		}

		private void OnVitalsKilled(CharacterVitals.Damage finalDamage)
		{
			Die();
		}

		protected override void Die()
		{
			RemoveGroundMarker();
			if (!Alive())
			{
				return;
			}
			if (loadedAsDead)
			{
				if (invincible)
				{
					SetAIState(AIState.Flee);
					return;
				}
				for (int i = 0; i < GetPetCount(); i++)
				{
					if (GetPet(i).IsSummoned())
					{
						GetPet(i).SetLifeDuration(0.01f);
					}
				}
				base.attackTimer = 0f;
				base.activeWeapon = null;
				currentAttack = null;
				ClearEffects();
				SetAIState(AIState.Dying);
				animator.SetBool("IsDead", value: true);
				path.enabled = false;
				if (lifeDuration > 0f)
				{
					if (HasMaster())
					{
						Master().RemovePet(this);
					}
					UnityEngine.Object.Destroy(base.gameObject, 0.1f);
				}
			}
			else
			{
				base.Die();
				if (allowDropInventory && inventory != null)
				{
					Player playerChar = Player.PlayerChar;
					if (family != Tableflip.Family.Ward && family != Tableflip.Family.Herd && UnityEngine.Random.value < 0.05f)
					{
						int num = UnityEngine.Random.Range(1, 4) * base.Level;
						if (playerChar != null)
						{
							num = (int)((float)num * (1f + playerChar.EffectValue(EffectType.PercentGoldDrop) / 100f));
						}
						ActiveLevel.SpawnGoldPile(LevelGenerator.currentInstance.RandomOpenPosition(myTransform.position, 0.5f, 2f), num);
					}
					if (IsMimic())
					{
						for (int j = 0; j < 3; j++)
						{
							int num2 = UnityEngine.Random.Range(2, 15) * base.Level;
							if (playerChar != null)
							{
								num2 = (int)((float)num2 * (1f + playerChar.EffectValue(EffectType.PercentGoldDrop) / 100f));
							}
							ActiveLevel.SpawnGoldPile(LevelGenerator.currentInstance.RandomOpenPosition(myTransform.position, 0.5f, 2f), num2);
						}
					}
					ActiveLevel.ApplyMagicFindToInventory(inventory, allowDropEquipment);
					for (int k = 0; k < inventory.Count; k++)
					{
						Item item = inventory[k];
						bool inEquipmentSlot = item.InEquipmentSlot;
						if (!inEquipmentSlot || (inEquipmentSlot && allowDropEquipment))
						{
							if (inEquipmentSlot)
							{
								UnequipItem(item);
							}
							item.Drop(myTransform.position);
							inventory.RemoveAt(k--);
						}
					}
				}
				if (family == Tableflip.Family.Nemesis && Player.PlayerChar != null)
				{
					Player playerChar2 = Player.PlayerChar;
					playerChar2.onEquipmentChanged = (Action)Delegate.Remove(playerChar2.onEquipmentChanged, new Action(MatchPlayer));
					Player playerChar3 = Player.PlayerChar;
					playerChar3.onWeaponSetChanged = (Action<WeaponSet>)Delegate.Remove(playerChar3.onWeaponSetChanged, new Action<WeaponSet>(base.SetActiveWeaponSet));
				}
				if (!IsSummoned() && !IsShrine())
				{
					TrySpawnOrbs();
				}
			}
			if (inventory != null)
			{
				inventory.Clear();
			}
			if (m_monsterSounds != null && !loadedAsDead)
			{
				m_monsterSounds.PlayDeathSound();
			}
			if (minimapIcon != null && alignment == Alignment.Evil)
			{
				minimapIcon.color = new Color(0.5f, 0.5f, 0.5f);
			}
		}

		public override void RemoveGroundMarker()
		{
			if (activeGroundMarker != null)
			{
				UnityEngine.Object.Destroy(activeGroundMarker);
				activeGroundMarker = null;
			}
			activeGroundMarkerAlignment = Alignment.None;
		}

		public override void UpdateGroundMarker(Alignment alignment)
		{
			if (activeGroundMarkerAlignment != alignment)
			{
				if (activeGroundMarker != null)
				{
					RemoveGroundMarker();
				}
				switch (alignment)
				{
				case Alignment.Good:
					activeGroundMarker = UnityEngine.Object.Instantiate(SingletonBehaviour<FateDB>.Instance.allyGroundMarkerPrefab, base.transform);
					SetActiveGroundMarkerScale();
					break;
				case Alignment.Evil:
					activeGroundMarker = UnityEngine.Object.Instantiate(SingletonBehaviour<FateDB>.Instance.enemyGroundMarkerPrefab, base.transform);
					SetActiveGroundMarkerScale();
					break;
				case Alignment.Neutral:
					activeGroundMarker = UnityEngine.Object.Instantiate(SingletonBehaviour<FateDB>.Instance.npcGroundMarkerPrefab, base.transform);
					SetActiveGroundMarkerScale();
					break;
				default:
					activeGroundMarker = null;
					break;
				}
				activeGroundMarkerAlignment = alignment;
			}
		}

		private void SetActiveGroundMarkerScale()
		{
			if (activeGroundMarker != null)
			{
				activeGroundMarker.transform.localScale = new Vector3(activeGroundMarker.transform.localScale.x / base.transform.lossyScale.x, activeGroundMarker.transform.localScale.y / base.transform.lossyScale.y, activeGroundMarker.transform.localScale.z / base.transform.lossyScale.z);
			}
		}

		private void TrySpawnOrbs()
		{
			if (Fate.CurrentFateVer != Fate.FateVer.CursedKing || IsPet() || IsSummoned() || IsShrine() || !(LevelGenerator.currentInstance != null))
			{
				return;
			}
			int num = 0;
			for (int i = 0; i < 3; i++)
			{
				if (!(UnityEngine.Random.value < 0.333f))
				{
					break;
				}
				num++;
			}
			if (base.IsBoss)
			{
				num += 10;
			}
			else if (isUnique)
			{
				num += 3;
			}
			if (num > 0)
			{
				StartCoroutine(DoSpawnOrbs(num));
			}
		}

		private IEnumerator DoSpawnOrbs(int count)
		{
			int i = 0;
			while (i < count)
			{
				yield return new WaitForSeconds(UnityEngine.Random.Range(0.01f, 0.1f));
				LevelGenerator.currentInstance.SpawnOrb(myTransform.position);
				int num = i + 1;
				i = num;
			}
		}

		public override bool IsMonster()
		{
			return true;
		}

		public override bool CanFitItemInInventoryGrid(Item item, out int foundSlotIndex, int desiredSlot = -1, bool isGlobalIndex = false, bool searchHorizontal = true)
		{
			foundSlotIndex = 20;
			return true;
		}

		protected bool OriginalCanFitItemInInventoryGrid(Item item, out int foundSlotIndex, int desiredSlot = -1, bool isGlobalIndex = false, bool searchHorizontal = true)
		{
			return base.CanFitItemInInventoryGrid(item, out foundSlotIndex, desiredSlot, isGlobalIndex, searchHorizontal);
		}

		protected virtual void OnDestroy()
		{
			if (myVitals != null)
			{
				CharacterVitals characterVitals = myVitals;
				characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(RespondToAttack));
			}
			if (family == Tableflip.Family.Nemesis && Player.PlayerChar != null)
			{
				Player playerChar = Player.PlayerChar;
				playerChar.onEquipmentChanged = (Action)Delegate.Remove(playerChar.onEquipmentChanged, new Action(MatchPlayer));
				Player playerChar2 = Player.PlayerChar;
				playerChar2.onWeaponSetChanged = (Action<WeaponSet>)Delegate.Remove(playerChar2.onWeaponSetChanged, new Action<WeaponSet>(base.SetActiveWeaponSet));
			}
		}

		protected override void Update()
		{
			base.Update();
		}

		public override void UpdateAI()
		{
			if (monsterData == null)
			{
				return;
			}
			KnockBackCheck();
			if (Alive() && base.UnderKnockback)
			{
				return;
			}
			if (Target() != null && !Target().Alive())
			{
				SetTarget(null);
			}
			if (Target() != null || currentAttack == null)
			{
				SelectAttack();
			}
			if (!animator.GetBool("IsWalking"))
			{
				animator.GetBool("IsRunning");
			}
			switch (eAIState)
			{
			case AIState.Dying:
				DyingAI();
				break;
			case AIState.Inactive:
				SetAIState(AIState.Wander);
				break;
			case AIState.Wander:
				WanderAI();
				break;
			case AIState.Flee:
			case AIState.PassingOut:
			case AIState.PassedOut:
				SetAIState(AIState.Flee);
				FleeAI();
				break;
			case AIState.GetRange:
				GetRangeAI();
				break;
			case AIState.Attack:
				AttackAI();
				break;
			case AIState.Approach:
			case AIState.ScriptApproach:
				ApproachAI();
				break;
			case AIState.Follow:
				FollowAI();
				break;
			case AIState.Hunt:
				HuntAI();
				break;
			case AIState.Cast:
				CastAI();
				break;
			case AIState.UniqueIdle:
				UniqueIdleAI();
				break;
			}
			if (!IsMimic())
			{
				return;
			}
			AIState aIState = GetAIState();
			if (aIState == AIState.Wander || aIState == AIState.UniqueIdle || aIState == AIState.Inactive)
			{
				displayedAsItem = true;
				if (minimapIcon != null)
				{
					minimapIcon.enabled = false;
				}
			}
			else
			{
				displayedAsItem = false;
				if (minimapIcon != null)
				{
					minimapIcon.enabled = true;
				}
			}
		}

		public override void AttackAI()
		{
			if (targetItem != null)
			{
				SetTargetItem(null);
			}
			if (!IsCurrentTargetValid() || IsPetNearDeath() || !Target().AvailableForCommand())
			{
				SetAIState(AIState.Wander);
				SetTarget(null);
				return;
			}
			if (Target().GetAlignment() == GetAlignment() || Target().GetAlignment() == Alignment.Neutral)
			{
				SetAIState(AIState.Inactive);
				SetTarget(null);
				return;
			}
			if (currentAttack == null)
			{
				SelectAttack();
				if (currentAttack == null && monsterData.tacticType != TacticType.Shrine)
				{
					return;
				}
			}
			Vector3 vector = targetCharacter.transform.position - myTransform.position;
			vector.y = 0f;
			float magnitude = vector.magnitude;
			if (monsterData.tacticType == TacticType.CowardlyMage)
			{
				if (Pathing())
				{
					return;
				}
				if (magnitude < (float)monsterData.attentionRadius * 0.25f * 0.4f && UnityEngine.Random.Range(0, 100) < 40 && !PerformingAttack())
				{
					Vector3 vector2 = levelData.RandomOpenPosition(targetCharacter.transform.position, (float)monsterData.attentionRadius * 0.25f * 0.25f, (float)monsterData.attentionRadius * 0.25f * 0.6f);
					SetDestination(vector2.x, vector2.z);
					return;
				}
			}
			if (magnitude >= (float)monsterData.followRadius * 0.25f && !HasMaster())
			{
				StopPathing();
				SetAIState(AIState.Wander);
				SetTarget(null);
				return;
			}
			if (HP() < MaxHP() / 2)
			{
				SelectHealSpell();
				if (activeSpell != null && UnityEngine.Random.Range(0, 1000) < 5 && HasSpellCosts(activeSpell))
				{
					Character targetChar = this;
					TryCastCurrentSpell(null, null, targetChar);
					return;
				}
			}
			SelectAttackSpell();
			if (activeSpell != null && UnityEngine.Random.Range(0, 1000) < 2 && HasSpellCosts(activeSpell))
			{
				Character targetChar = Target();
				TryCastCurrentSpell(null, null, targetChar);
				return;
			}
			SelectDefenseSpell();
			if (activeSpell != null && UnityEngine.Random.Range(0, 1000) < 2 && HasSpellCosts(activeSpell))
			{
				Character targetChar = this;
				TryCastCurrentSpell(null, null, targetChar);
				return;
			}
			if (GetPetCount() < 1)
			{
				SelectSummonSpell();
				if (activeSpell != null && UnityEngine.Random.Range(0, 2000) < 2 && HasSpellCosts(activeSpell))
				{
					TryCastCurrentSpell();
					return;
				}
			}
			if (IsCurrentTargetValid() && (Target().GetPetCount() > 1 || Target().IsSummoned()))
			{
				SelectBanishSpell();
				if (activeSpell != null && UnityEngine.Random.Range(0, 2000) < 5)
				{
					if (Target().IsSummoned() && Target().HasMaster())
					{
						SetTarget(Target().Master());
					}
					if (!IsCurrentTargetValid())
					{
						return;
					}
					if (HasSpellCosts(activeSpell))
					{
						Character targetChar = Target();
						TryCastCurrentSpell(null, null, targetChar);
						return;
					}
				}
			}
			if (!InAttackRange() || !ValidLineOfSight())
			{
				if (!PerformingAttack())
				{
					SetAIState(AIState.Hunt);
					if (!IsPet() && hasChangedAgentPrio)
					{
						path.avoidancePriority = initialAgentPrio;
						hasChangedAgentPrio = false;
					}
				}
				return;
			}
			TurnTowardPosition(targetCharacter.transform.position);
			if (PerformingAttack())
			{
				return;
			}
			if (UnityEngine.Random.Range(0, 100) < 40 && timeSincePath > 1f && targetCharacter != null && TooCloseForAttack())
			{
				SetAIState(AIState.GetRange);
				float num = AttackRange();
				Vector3 vector3 = levelData.RandomOpenPosition(targetCharacter.transform.position, num, num * 1.25f);
				SetDestination(vector3.x, vector3.z);
			}
			else if (FacingTarget())
			{
				SelectAttack();
				Attack();
				if (m_monsterSounds != null)
				{
					m_monsterSounds.PlayAttackSound(currentAttack.ToString(), base.HasWeapon);
				}
				else
				{
					UnityEngine.Debug.Log("monster Sounds component is missing for " + base.gameObject.name);
				}
				if (!IsPet() && !hasChangedAgentPrio)
				{
					path.avoidancePriority = Mathf.FloorToInt(Fate.NavMeshPrioMonster.Min);
					hasChangedAgentPrio = true;
				}
			}
		}

		public void SelectHealSpell()
		{
			SetActiveSpell(null);
			if (knownSpells == null || knownSpells.IsEmpty() || !knownSpells.ContainsKey(SpellSphere.Defense))
			{
				return;
			}
			List<SpellData> list = knownSpells[SpellSphere.Defense];
			if (list == null)
			{
				return;
			}
			foreach (SpellData item in list)
			{
				if (item == null)
				{
					continue;
				}
				bool flag = true;
				if (item.requirements != null)
				{
					foreach (AttributeData requirement in item.requirements)
					{
						if (attributes.GetAttribute(requirement.attribute, allowEffects: true) < requirement.value)
						{
							flag = false;
							break;
						}
					}
				}
				if (item.IsHealSpell() && flag && levelData.GetLevelDepth() > item.minimumDepth && UnityEngine.Random.Range(0, 1000) < 200)
				{
					SetActiveSpell(item);
					break;
				}
			}
		}

