		public virtual void WanderAI()
		{
			running = false;
			if (UnityEngine.Random.Range(0, 1000) < 100 && GetAlignment() != Alignment.Neutral && !IsPetNearDeath() && levelData != null)
			{
				Alignment alignment = Alignment.Good;
				if (GetAlignment() == Alignment.Good)
				{
					alignment = Alignment.Evil;
					UpdateGroundMarker(GetAlignment());
				}
				float radius = (float)monsterData.attentionRadius * 0.25f;
				if (HasMaster())
				{
					radius = 8.75f;
				}
				Character character = levelData.FindCharacterWithinView(myTransform, alignment, (float)monsterData.motionRadius * 0.25f, (float)monsterData.viewRadius * 0.25f, radius);
				if (HasMaster() && character == null)
				{
					character = levelData.FindCharacterWithinView(Master().transform, alignment, (float)monsterData.motionRadius * 0.25f, (float)monsterData.viewRadius * 0.25f, radius);
				}
				if (HasMaster() && character != null)
				{
					Vector3 vector = Master().transform.position - character.transform.position;
					vector.y = 0f;
					if (vector.magnitude > 8.75f)
					{
						character = null;
					}
				}
				if (character != null)
				{
					if (character.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
					{
						character = character.Master();
					}
					StopPathing();
					SetAIState(AIState.Hunt);
					SetTarget(character);
					if (timeSinceIdleSound > 0.5f && UnityEngine.Random.value < 0.8f && m_monsterSounds != null)
					{
						m_monsterSounds.PlayRoarSound();
					}
					return;
				}
			}
			if (GetFinalMoveSpeed() == 0f)
			{
				return;
			}
			if (!Pathing() && UnityEngine.Random.Range(0, 1000) < 2)
			{
				if (HasMaster())
				{
					float num = 4.5f;
					SetDestination(UnityEngine.Random.Range(Master().transform.position.x - num, Master().transform.position.x + num), UnityEngine.Random.Range(Master().transform.position.z - num, Master().transform.position.z + num));
				}
				else
				{
					SetDestination(UnityEngine.Random.Range(myTransform.position.x - 100f, myTransform.position.x + 100f), UnityEngine.Random.Range(myTransform.position.z - 100f, myTransform.position.z + 100f));
				}
			}
			if (HasMaster())
			{
				Alignment alignment2 = Alignment.Good;
				if (GetAlignment() == Alignment.Good)
				{
					alignment2 = Alignment.Evil;
					UpdateGroundMarker(GetAlignment());
				}
				SetRunning(Master().Running());
				if (Master().stamina < 1f)
				{
					SetRunning(runningState: false);
				}
				Vector3 vector2;
				float magnitude;
				if (Master().Target() != null && Master().Target().GetAlignment() == alignment2 && !IsPetNearDeath())
				{
					vector2 = Master().transform.position - Master().Target().transform.position;
					vector2.y = 0f;
					magnitude = vector2.magnitude;
					if (magnitude <= 5f)
					{
						SetTarget(Master().Target());
						SetAIState(AIState.Hunt);
						return;
					}
				}
				vector2 = Master().transform.position - myTransform.position;
				vector2.y = 0f;
				magnitude = vector2.magnitude;
				if (magnitude > 7f)
				{
					SetRunning(runningState: true);
				}
				else if (magnitude <= 5f && !Master().Pathing())
				{
					SetRunning(runningState: false);
				}
				if (LevelGenerator.currentInstance != null && magnitude > 16f && levelData != null)
				{
					float time = Time.time;
					if (time - teleportTime > 3f)
					{
						path.enabled = false;
						myTransform.position = levelData.RandomOpenPosition(Master().myTransform.position, 1f);
						path.enabled = true;
						teleportTime = time;
					}
				}
				if (IsPetNearDeath())
				{
					SetRunning(runningState: true);
				}
				if (UnityEngine.Random.Range(0, 1000) < 100 || IsPetNearDeath())
				{
					vector2 = ((!Pathing()) ? (Master().transform.position - base.transform.position) : (Master().transform.position - finalTargetPosition));
					vector2.y = 0f;
					magnitude = vector2.magnitude;
					if ((IsPetNearDeath() && !Pathing()) || (magnitude > 5f && timeSincePath > 0.25f))
					{
						SetRunning(runningState: true);
						float num2 = 4.5f;
						SetDestination(UnityEngine.Random.Range(Master().transform.position.x - num2, Master().transform.position.x + num2), UnityEngine.Random.Range(Master().transform.position.z - num2, Master().transform.position.z + num2));
					}
				}
			}
			if (!Pathing() && eAIState == AIState.Wander && UnityEngine.Random.Range(0, 1000) < 2 && uniqueIdleAnimations.Length != 0)
			{
				StopPathing();
				hasPlayedUniqueIdleSound = false;
				animator.SetBool("IsUniqueIdle", value: true);
				SetAIState(AIState.UniqueIdle);
				CharacterVitals characterVitals = myVitals;
				characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Combine(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(CancelUniqueIdle));
				timeSinceIdleSound = 0f;
				timeSinceUniqueIdle = 0f;
			}
		}

		public void FleeAI()
		{
			SetTarget(null, resetAttackSpeed: false);
			SetRunning(runningState: true);
			if (!Pathing())
			{
				if (UnityEngine.Random.Range(0, 100) < 50)
				{
					SetAIState(AIState.Wander);
				}
				if (HasMaster())
				{
					float num = 10f;
					SetDestination(UnityEngine.Random.Range(Master().transform.position.x - num, Master().transform.position.x + num), UnityEngine.Random.Range(Master().transform.position.z - num, Master().transform.position.z + num));
				}
				else
				{
					SetDestination(UnityEngine.Random.Range(myTransform.position.x - 100f, myTransform.position.x + 100f), UnityEngine.Random.Range(myTransform.position.z - 100f, myTransform.position.z + 100f));
				}
			}
		}

		public void GetRangeAI()
		{
			SetRunning(runningState: true);
			if (!Pathing())
			{
				if (targetCharacter != null && !TooCloseForAttack())
				{
					SetAIState(AIState.Attack);
				}
				else
				{
					SetAIState(AIState.Wander);
				}
			}
		}

		public override void HuntAI()
		{
			if (!IsCurrentTargetValid() || IsPetNearDeath())
			{
				SetAIState(AIState.Wander);
				SetTarget(null);
				return;
			}
			if (Target().GetAlignment() == GetAlignment() || Target().GetAlignment() == Alignment.Neutral)
			{
				SetAIState(AIState.Inactive);
				SetTarget(null);
				return;
			}
			SetRunning(runningState: true);
			Vector3 vector = Target().transform.position - myTransform.position;
			vector.y = 0f;
			if (vector.magnitude >= (float)monsterData.followRadius * 0.25f && !HasMaster())
			{
				StopPathing();
				SetAIState(AIState.Wander);
				SetTarget(null);
				return;
			}
			bool flag = ValidLineOfSight();
			if (monsterData.tacticType != TacticType.Shrine)
			{
				if (monsterData.tacticType == TacticType.CowardlyMage || monsterData.tacticType == TacticType.Mage)
				{
					if (timeSincePath > 1f)
					{
						vector = Target().transform.position - finalTargetPosition;
						vector.y = 0f;
						if (vector.magnitude >= (float)monsterData.attentionRadius * 0.25f * 0.6f || UnityEngine.Random.Range(0, 100) < 1)
						{
							Vector3 vector2 = levelData.RandomOpenPosition(Target().transform.position, (float)monsterData.attentionRadius * 0.25f * 0.25f, (float)monsterData.attentionRadius * 0.25f * 0.6f);
							SetDestination(vector2.x, vector2.z);
							if (!Pathing())
							{
								SetTarget(null);
								SetAIState(AIState.Wander);
							}
						}
					}
				}
				else if ((!InAttackRange() || !flag) && timeSincePath > 1f)
				{
					if (!Pathing())
					{
						if (!FollowCharacter(Target()))
						{
							SetTarget(null);
							SetAIState(AIState.Wander);
							return;
						}
					}
					else
					{
						vector = Target().transform.position - finalTargetPosition;
						vector.y = 0f;
						if (vector.magnitude >= 4f)
						{
							FollowCharacter(Target());
						}
					}
				}
			}
			if (HP() < MaxHP() / 2)
			{
				SelectHealSpell();
				if (activeSpell != null && UnityEngine.Random.Range(0, 1000) < 5 && HasSpellCosts(activeSpell))
				{
					Character targetChar = this;
					TryCastCurrentSpell(null, null, targetChar);
					return;
				}
			}
			for (int i = 0; i < GetPetCount(); i++)
			{
				if (GetPet(i).HP() < GetPet(i).MaxHP() / 2)
				{
					SelectHealMinionSpell();
					if (activeSpell != null && UnityEngine.Random.Range(0, 1000) < 5 && HasSpellCosts(activeSpell))
					{
						Character targetChar = GetPet(i);
						TryCastCurrentSpell(null, null, targetChar);
						return;
					}
				}
			}
			int num = 2;
			if (monsterData.tacticType == TacticType.CowardlyMage)
			{
				num = 100;
			}
			SelectAttackSpell();
			if (activeSpell != null && UnityEngine.Random.Range(0, 1000) < num && HasSpellCosts(activeSpell))
			{
				Character targetChar = Target();
				TryCastCurrentSpell(null, null, targetChar);
				return;
			}
			int num2 = 2;
			if (monsterData.tacticType == TacticType.CowardlyMage)
			{
				num2 = 100;
			}
			SelectDefenseSpell();
			if (activeSpell != null && UnityEngine.Random.Range(0, 1000) < num2 && HasSpellCosts(activeSpell))
			{
				Character targetChar = this;
				TryCastCurrentSpell(null, null, targetChar);
				return;
			}
			if (GetPetCount() < 1)
			{
				SelectSummonSpell();
				if (activeSpell != null && UnityEngine.Random.Range(0, 2000) < 2 && HasSpellCosts(activeSpell))
				{
					TryCastCurrentSpell();
					return;
				}
			}
			if (IsCurrentTargetValid() && (Target().GetPetCount() > 1 || Target().IsSummoned()))
			{
				SelectBanishSpell();
				if (activeSpell != null && UnityEngine.Random.Range(0, 2000) < 5)
				{
					if (Target().IsSummoned() && Target().HasMaster())
					{
						SetTarget(Target().Master());
					}
					if (!IsCurrentTargetValid())
					{
						return;
					}
					if (HasSpellCosts(activeSpell))
					{
						Character targetChar = Target();
						TryCastCurrentSpell(null, null, targetChar);
						return;
					}
				}
			}
			if (InAttackRange() && flag)
			{
				SetAIState(AIState.Attack);
				StopPathing();
			}
			else if (HasMaster() && Target() != null)
			{
				vector = Master().transform.position - Target().transform.position;
				vector.y = 0f;
				if (vector.magnitude > 8.75f)
				{
					SetTarget(null);
					SetAIState(AIState.Wander);
				}
			}
		}

		public void UniqueIdleAI()
		{
			if (!Alive())
			{
				return;
			}
			if (HasMaster() && !Master().FishingAny())
			{
				Vector3 vector = Master().transform.position - myTransform.position;
				vector.y = 0f;
				if (vector.magnitude > 5f)
				{
					CancelUniqueIdle();
				}
			}
			if (m_monsterSounds != null && !hasPlayedUniqueIdleSound)
			{
				animator.SetBool("IsUniqueIdle", value: true);
				m_monsterSounds.PlayUniqueIdleSound();
				hasPlayedUniqueIdleSound = true;
			}
			if (IsMonster() && Target() != null)
			{
				CancelUniqueIdle();
			}
		}

		public override void RespondToAttack(Character attacker)
		{
			base.RespondToAttack(attacker);
			if (!Alive() || attacker == null || attacker == this || GetAIState() == AIState.Flee)
			{
				return;
			}
			if (GetAIState() == AIState.UniqueIdle)
			{
				CancelUniqueIdle();
			}
			if (MaxHP() > 0 && hp / (float)MaxHP() < 1f - monsterData.bravery && UnityEngine.Random.Range(0, 100) < 50)
			{
				SetAIState(AIState.Flee);
			}
			else
			{
				if (!attacker.Alive() || attacker.GetAlignment() == GetAlignment() || attacker.GetAlignment() == Alignment.Neutral)
				{
					return;
				}
				if (!IsCurrentTargetValid())
				{
					if (!PerformingCast())
					{
						SetAIState(AIState.Hunt);
						if (attacker.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							SetTarget(attacker.Master());
						}
						else
						{
							SetTarget(attacker);
						}
					}
				}
				else
				{
					if (PerformingAttack() || PerformingCast())
					{
						return;
					}
					if (UnityEngine.Random.Range(0, 1000) < 50)
					{
						SetAIState(AIState.Attack);
						if (attacker.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							SetTarget(attacker.Master());
						}
						else
						{
							SetTarget(attacker);
						}
					}
					else if (GetAIState() == AIState.Inactive || GetAIState() == AIState.Wander)
					{
						SetAIState(AIState.Attack);
						if (attacker.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							SetTarget(attacker.Master());
						}
						else
						{
							SetTarget(attacker);
						}
					}
				}
			}
		}

		protected override void RespondToAttack(CharacterVitals.Damage attacker)
		{
			if (!(attacker.source == null))
			{
				RespondToAttack(attacker.source.Char);
			}
		}

		protected override bool DelayAttack()
		{
			return false;
		}

		public void AnimCallbackAttackDone()
		{
			if (Alive())
			{
				animator.SetBool("IsAttacking", value: false);
				animator.speed = 1f;
				if (base.castTimer > 0f && !reachedCastPoint)
				{
					base.castTimer = 0f;
					reachedCastPoint = true;
					Character targetChar = Target();
					CompleteSpell(null, null, targetChar);
				}
				if (base.attackTimer > 0f && !reachedStrikePoint)
				{
					base.attackTimer = 0f;
					reachedStrikePoint = true;
					PerformAttack();
					SwapDualWieldWeaponHand();
				}
			}
		}

		public void AnimCallbackUniqueDone()
		{
			if (Alive())
			{
				CancelUniqueIdle();
			}
		}

		public void CancelUniqueIdle(CharacterVitals.Damage damage)
		{
			CancelUniqueIdle();
		}

		public void CancelUniqueIdle()
		{
			animator.SetBool("IsUniqueIdle", value: false);
			bool flag = true;
			AIState aIState = GetAIState();
			if (aIState == AIState.ReturningToTown || aIState == AIState.InTown)
			{
				flag = false;
			}
			if (flag)
			{
				SetAIState(AIState.Wander);
			}
			CharacterVitals characterVitals = myVitals;
			characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(CancelUniqueIdle));
		}

		public void AnimCallbackStep()
		{
			if (Alive())
			{
				m_monsterSounds.PlayStepSound();
			}
		}
	}
	public class MonsterSounds : MonoBehaviour
	{
		[Serializable]
		public class AttackSound
		{
			public string key;

			public List<AudioClip> attackSounds;

			public List<AudioClip> strikeSounds;

			public List<AudioClip> missSounds;
		}

		public List<AttackSound> attackSounds;

		public AudioClip[] armedAttackSounds;

		public AudioClip[] deathSounds;

		public AudioClip[] idleSounds;

		public AudioClip[] stepSounds;

		public AudioClip[] roarSounds;

		public AudioClip[] uniqueIdleSounds;

		private AudioSource audioSource;

		private void Awake()
		{
			audioSource = GetComponent<AudioSource>();
		}

		public void PlayIdleSound()
		{
			if (idleSounds != null && idleSounds.Length != 0)
			{
				PlayClip(idleSounds.GetRandomEntry());
			}
		}

		public void PlayUniqueIdleSound()
		{
			if (uniqueIdleSounds != null && uniqueIdleSounds.Length != 0)
			{
				PlayClip(uniqueIdleSounds.GetRandomEntry());
			}
		}

		public void PlayRoarSound()
		{
			if (roarSounds != null && roarSounds.Length != 0)
			{
				PlayClip(roarSounds.GetRandomEntry());
			}
		}

		public void PlayDeathSound()
		{
			if (deathSounds != null && deathSounds.Length != 0)
			{
				PlayClip(deathSounds.GetRandomEntry());
			}
		}

		public void PlayAttackSound(string attackKey, bool isArmed, bool missed = false)
		{
			if (isArmed && armedAttackSounds != null && armedAttackSounds.Length != 0)
			{
				PlayClip(armedAttackSounds.GetRandomEntry());
			}
			else
			{
				if (attackSounds == null || attackSounds.Count == 0)
				{
					return;
				}
				AttackSound attackSound = attackSounds[0];
				for (int i = 0; i < attackSounds.Count; i++)
				{
					if (attackSounds[i].key.ToUpper() == attackKey.ToUpper())
					{
						attackSound = attackSounds[i];
						break;
					}
				}
				if (missed && attackSound.missSounds != null && attackSound.missSounds.Count > 0)
				{
					PlayClip(attackSound.missSounds.GetRandomEntry());
				}
				else
				{
					PlayClip(attackSound.attackSounds.GetRandomEntry());
				}
			}
		}

		public void PlayStrikeSound(string attackKey)
		{
			if (attackSounds == null || attackSounds.Count == 0)
			{
				return;
			}
			for (int i = 0; i < attackSounds.Count; i++)
			{
				if (attackSounds[i].key.ToUpper() == attackKey.ToUpper())
				{
					PlayClip(attackSounds[i].strikeSounds.GetRandomEntry());
					break;
				}
			}
		}

		public void PlayStepSound()
		{
			if (stepSounds != null && stepSounds.Length != 0)
			{
				PlayClip(stepSounds.GetRandomEntry());
			}
		}

		private void PlayClip(AudioClip clip)
		{
			audioSource.clip = clip;
			if (!audioSource.isPlaying)
			{
				audioSource.Play();
			}
		}
	}
