	public class NameGenerator : SingletonBehaviour<NameGenerator>
	{
		private int prefixCount = 80;

		private int suffixCount = 56;

		private int prefix2Count = 32;

		private int suffix2Count = 23;

		private int titleCount = 80;

		private int namePrefixCount = 61;

		private int nameSuffixCount = 38;

		private bool isSpanish;

		protected override void Init()
		{
			isSpanish = I2Loca.GetCurrentLanguageCode() == "es-ES";
		}

		public string GenerateUniqueName(out string prefix2, out string suffix2, out string title)
		{
			prefix2 = I2Loca.Get("NamePrefix2_" + UnityEngine.Random.Range(1, prefix2Count).ToString("D2"));
			suffix2 = I2Loca.Get("NameSuffix2_" + UnityEngine.Random.Range(1, suffix2Count).ToString("D2"));
			title = "";
			string term = I2Loca.Get("NameTitle_" + UnityEngine.Random.Range(1, titleCount).ToString("D2"));
			if (UnityEngine.Random.value < 0.5f)
			{
				prefix2 = GeneratePhonicName();
				suffix2 = "";
				title = "";
				return prefix2;
			}
			if (UnityEngine.Random.value < 0.3f)
			{
				LocalizationManager.TryGetTranslation(term, out var Translation);
				title = Translation;
			}
			if (!string.IsNullOrEmpty(title))
			{
				if (!isSpanish)
				{
					return I2Loca.GetFormat("PlayerTitle", prefix2 + suffix2, title);
				}
				if (!string.IsNullOrEmpty(suffix2))
				{
					return I2Loca.GetFormat("PlayerTitle", suffix2 + " " + prefix2, title);
				}
				return I2Loca.GetFormat("PlayerTitle", suffix2 + prefix2, title);
			}
			if (!isSpanish)
			{
				return prefix2 + suffix2;
			}
			return suffix2 + " " + prefix2;
		}

		public string GenerateShrineName()
		{
			string prefix;
			string suffix;
			string title;
			return I2Loca.GetFormat("ShrineName", GenerateUniqueName(out prefix, out suffix, out title));
		}

		public string GenerateSimpleName(out string prefixKey, out string suffixKey, out int splitterTypeIndex)
		{
			if (UnityEngine.Random.value < 0.5f)
			{
				prefixKey = "NamePrefix_" + UnityEngine.Random.Range(1, prefixCount).ToString("D2");
				suffixKey = "NameSuffix_" + UnityEngine.Random.Range(1, suffixCount).ToString("D2");
				if (UnityEngine.Random.value < 0.2f)
				{
					splitterTypeIndex = 1;
				}
				else
				{
					splitterTypeIndex = 0;
				}
			}
			else
			{
				prefixKey = "NamePrefix2_" + UnityEngine.Random.Range(1, prefix2Count).ToString("D2");
				suffixKey = "NameSuffix2_" + UnityEngine.Random.Range(1, suffix2Count).ToString("D2");
				splitterTypeIndex = 0;
			}
			return I2Loca.Get(prefixKey) + "'" + I2Loca.Get(suffixKey);
		}

		public string GeneratePhonicName()
		{
			string text = I2Loca.Get("PlayerName_Prefix_" + UnityEngine.Random.Range(1, namePrefixCount).ToString("D3"));
			string text2 = I2Loca.Get("PlayerName_Suffix_" + UnityEngine.Random.Range(1, nameSuffixCount).ToString("D3"));
			if (UnityEngine.Random.value < 0.3f)
			{
				return text;
			}
			if (UnityEngine.Random.value < 0.2f)
			{
				return text + "'" + text2;
			}
			return text + text2;
		}
	}
	public class NPC : Character
	{
		[Header("NPC")]
		[SerializeField]
		private bool canMove;

		[SerializeField]
		private GameObject[] patrolPoints;

		private Quaternion originalRotation;

		private Vector3[] patrolPath;

		private bool isBeingInteractedWith;

		private int patrolPathIndex;

		private bool isPlayerClose;

		private bool isPlayerVeryClose;

		private float playerInProximityDistance = 25f;

		private float playerInProximityVeryCloseDistance = 2f;

		private float playerProximityTimer;

		private bool usingReversePath;

		private Coroutine stareRoutine;

		protected NpcVoiceLines npcVoiceLines;

		private const float playerProximityCheckInterval = 0.3f;

		private const float stareDuration = 2f;

		private bool IsStaring => stareRoutine != null;

		public override void Init()
		{
			base.Init();
			npcVoiceLines = GetComponent<NpcVoiceLines>();
			hp = 1f;
			invincible = true;
			originalRotation = base.transform.rotation;
			playerProximityTimer = UnityEngine.Random.Range(0f, 0.3f);
			if (canMove && patrolPoints.Length != 0)
			{
				SetAIState(AIState.Patrol);
				patrolPath = new Vector3[patrolPoints.Length];
				for (int i = 0; i < patrolPoints.Length; i++)
				{
					patrolPath[i] = patrolPoints[i].transform.position;
				}
				patrolPathIndex = 0;
				PathToPoint(patrolPath[patrolPathIndex]);
			}
			else
			{
				SetAIState(AIState.Inactive);
			}
		}

		public override bool IsNPC()
		{
			return true;
		}

		protected override void Update()
		{
			if (!isBeingInteractedWith)
			{
				if (canMove)
				{
					base.Update();
				}
				playerProximityTimer += Time.deltaTime;
				if (playerProximityTimer > 0.3f)
				{
					playerProximityTimer -= 0.3f;
					PerformPlayerProximityCheck();
				}
			}
		}

		public override void UpdateAI()
		{
			if (!isBeingInteractedWith)
			{
				AIState aIState = eAIState;
				if (aIState != 0 && aIState == AIState.Patrol && (myTransform.position.WithY(0f) - patrolPath[patrolPathIndex].WithY(0f)).sqrMagnitude < 0.5f)
				{
					PathToNextPartolPoint();
				}
			}
		}

		private void PathToNextPartolPoint()
		{
			if (usingReversePath)
			{
				patrolPathIndex--;
				if (patrolPathIndex < 0)
				{
					patrolPathIndex = patrolPath.Length - 1;
				}
			}
			else
			{
				patrolPathIndex = (patrolPathIndex + 1) % patrolPath.Length;
			}
			PathToPoint(patrolPath[patrolPathIndex]);
		}

		private void PathToPoint(Vector3 point)
		{
			SetDestination(point.x, point.z);
			if (!pathing)
			{
				UnityEngine.Debug.LogWarning($"Patrol path: Setting agent destination failed for {this}. Path length is {patrolPath.Length}. Movespeed is {GetFinalMoveSpeed()}. Patrol path index {patrolPathIndex}, point world position {point}.", this);
			}
		}

		private void PerformPlayerProximityCheck()
		{
			float num = GetDistanceToPlayer();
			if (isPlayerClose)
			{
				num -= 0.1f;
			}
			bool isClose = num < playerInProximityDistance;
			bool isVeryClose = num < playerInProximityVeryCloseDistance;
			SetPlayerIsClose(isClose, isVeryClose);
		}

		private void SetPlayerIsClose(bool isClose, bool isVeryClose)
		{
			if (isVeryClose && isPlayerVeryClose != isVeryClose && canMove && eAIState == AIState.Patrol)
			{
				ReversePath();
				PathToNextPartolPoint();
				isPlayerVeryClose = isVeryClose;
				return;
			}
			isPlayerVeryClose = isVeryClose;
			if (isClose == isPlayerClose)
			{
				return;
			}
			if (isClose)
			{
				if (canMove)
				{
					eAIState = AIState.Inactive;
					StopPathing();
					BeginStaring();
				}
				else
				{
					TweenRotation(originalRotation, 0.4f);
				}
			}
			else
			{
				if (IsStaring)
				{
					StopCoroutine(stareRoutine);
					StopTweenRotation();
				}
				if (canMove)
				{
					eAIState = AIState.Patrol;
					ResumePath();
				}
				else
				{
					TweenRotation(originalRotation, 0.4f);
				}
			}
			isPlayerClose = isClose;
		}

		private void BeginStaring()
		{
			if (stareRoutine != null)
			{
				StopCoroutine(stareRoutine);
			}
			stareRoutine = StartCoroutine(DoStare());
		}

		private IEnumerator DoStare()
		{
			Quaternion targetRotation = Quaternion.LookRotation((Player.PlayerChar.transform.position - base.transform.position).WithY(0f));
			TweenRotation(targetRotation, 0.3f);
			yield return new WaitForSeconds(2f);
			if (canMove && !isBeingInteractedWith)
			{
				eAIState = AIState.Patrol;
				ResumePath();
			}
			else
			{
				TweenRotation(originalRotation, 0.4f);
			}
			stareRoutine = null;
		}

		private void ReversePath()
		{
			usingReversePath = !usingReversePath;
		}

		private void ResumePath()
		{
			Vector3 vector = patrolPath[patrolPathIndex];
			SetDestination(vector.x, vector.z);
		}

		public override void HandleInteractedWith(Character interactor)
		{
			float distanceToPlayer = GetDistanceToPlayer();
			if (playerInProximityDistance < distanceToPlayer)
			{
				playerInProximityDistance = distanceToPlayer + 0.1f;
			}
			if (canMove)
			{
				SetAIState(AIState.Inactive);
				StopPathing();
			}
			Quaternion targetRotation = Quaternion.LookRotation((interactor.transform.position - base.transform.position).WithY(0f));
			TweenRotation(targetRotation, 0.15f);
			if (!(this is Merchant))
			{
				isBeingInteractedWith = true;
			}
		}

		public override void HandleInteractionComplete(Character interactor)
		{
			isBeingInteractedWith = false;
			if (canMove)
			{
				SetAIState(AIState.Patrol);
				ResumePath();
			}
		}
	}
	public class NPCModifier : MonoBehaviour
	{
		private Merchant merchant;

		private NpcVoiceLines NPC;

		public bool isBongo;

		public bool isSplinshins;

		private void Start()
		{
			merchant = GetComponent<Merchant>();
			NPC = GetComponent<NpcVoiceLines>();
			if (Fate.CurrentFateVer == Fate.FateVer.UndiscoveredRealms)
			{
				if (isBongo)
				{
					merchant.merchantType = MerchantType.Fish;
					NPC.thisNpc = NpcGreetings.BongoFate2;
				}
				return;
			}
			if (isBongo)
			{
				merchant.merchantType = MerchantType.Enchanter;
				NPC.thisNpc = NpcGreetings.Bongo;
			}
			if (isSplinshins)
			{
				base.gameObject.SetActive(value: false);
			}
		}
	}
