		private static ItemSaveData GetRandomItemSaveData(MerchantType merchantType)
		{
			ItemData itemData = SingletonBehaviour<MerchantData>.Instance.FindRandomItemByType(merchantType);
			if (itemData == null)
			{
				return null;
			}
			Item item = new Item(itemData);
			ItemSaveData itemSaveData = new ItemSaveData();
			item.FillInstance(itemSaveData);
			return itemSaveData;
		}

		public static FateSaveData GenerateRandomSaveData()
		{
			FateSaveData fateSaveData = new FateSaveData();
			PlayerSaveData playerSaveData = new PlayerSaveData();
			int level = Player.PlayerChar.Level;
			int num = Mathf.Max(1, level + UnityEngine.Random.Range(-2, 2));
			int num2 = 1;
			playerSaveData.experience = Fate.GetExperienceNeeded(num);
			playerSaveData.playerName = SingletonBehaviour<NameGenerator>.Instance.GeneratePhonicName();
			playerSaveData.health = 1f;
			playerSaveData.stamina = 1f;
			Fate.GetLevelFromExperience(playerSaveData.experience);
			int maxExclusive = 5;
			if (UnityEngine.Random.value < 0.3f)
			{
				playerSaveData.playerRace = Race.Human;
			}
			else
			{
				playerSaveData.playerRace = (Race)(UnityEngine.Random.Range(0, maxExclusive) + 1);
			}
			CharacterCustomizationDefaults.RaceSetup raceSetup = Player.PlayerChar.GetComponentInChildren<CharacterCustomizationDefaults>().raceSetups.Find((CharacterCustomizationDefaults.RaceSetup s) => s.targetRace == playerSaveData.playerRace);
			if (raceSetup != null)
			{
				playerSaveData.headIndex = UnityEngine.Random.Range(0, raceSetup.head.overrides.Count);
				playerSaveData.hairIndex = UnityEngine.Random.Range(0, raceSetup.hair.overrides.Count);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Could not determine player character race setup when generating a random save data");
				playerSaveData.headIndex = 0;
				playerSaveData.hairIndex = 0;
			}
			int num3 = (int)Player.PlayerChar.fame;
			int num4 = Mathf.Clamp((int)((float)num3 * 0.05f), 0, 100000);
			playerSaveData.fame = (uint)(num3 + UnityEngine.Random.Range(-num4, num4));
			playerSaveData.unallocatedStatPoints = 0;
			playerSaveData.unallocatedSkillPoints = 0;
			List<Attribute> list = new List<Attribute>();
			for (int i = 0; i < 23; i++)
			{
				Attribute attribute = (Attribute)i;
				if (attribute != 0 && attribute != Attribute.AllSkills)
				{
					list.Add(attribute);
				}
			}
			playerSaveData.attributes = new AttributeSave[list.Count];
			int num5 = 0;
			foreach (Attribute item in list)
			{
				int baseValue = 0;
				switch (item)
				{
				case Attribute.Strength:
					baseValue = 25;
					break;
				case Attribute.Dexterity:
					baseValue = 20;
					break;
				case Attribute.Vitality:
					baseValue = 25;
					break;
				case Attribute.Magic:
					baseValue = 10;
					break;
				case Attribute.Level:
					baseValue = num;
					break;
				case Attribute.Renown:
					baseValue = Fate.GetFameTier(playerSaveData.fame);
					break;
				case Attribute.Lineage:
					baseValue = 0;
					break;
				case Attribute.SkillSword:
				case Attribute.SkillClub:
				case Attribute.SkillHammer:
				case Attribute.SkillAxe:
				case Attribute.SkillSpear:
				case Attribute.SkillStaff:
				case Attribute.SkillPolearm:
				case Attribute.SkillBow:
				case Attribute.SkillCriticalStrike:
				case Attribute.SkillSpellcasting:
				case Attribute.SkillDualWield:
				case Attribute.SkillShield:
				case Attribute.SkillAttackMagic:
				case Attribute.SkillDefenseMagic:
				case Attribute.SkillCharmMagic:
					baseValue = 0;
					break;
				default:
					UnityEngine.Debug.LogWarning($"Unaccounted attribute {item}");
					break;
				}
				playerSaveData.attributes[num5++] = new AttributeSave
				{
					attrib = item,
					baseValue = baseValue
				};
			}
			playerSaveData.gold = 0uL;
			playerSaveData.difficulty = Fate.Difficulty.Page;
			int num6 = num - num2;
			int num7 = 2 * num6;
			int num8 = UnityEngine.Random.Range(2, 4);
			List<Attribute> list2 = new List<Attribute>();
			for (int j = 0; j < num8; j++)
			{
				list2.Add((Attribute)UnityEngine.Random.Range(8, 23));
			}
			while (num7 > 0)
			{
				Attribute randomAttribute = list2.GetRandomEntry();
				playerSaveData.attributes.Find((AttributeSave x) => x.attrib == randomAttribute).baseValue++;
				num7--;
			}
			int num9 = 5 * num6;
			int num10 = 4;
			int num11 = UnityEngine.Random.Range(0, 4);
			while (num9 > 0)
			{
				int num12 = UnityEngine.Random.Range(0, num10 + 1);
				if (num12 >= num10)
				{
					num12 = num11;
				}
				Attribute attributeToIncrease = Attribute.None;
				switch (num12)
				{
				case 0:
					attributeToIncrease = Attribute.Strength;
					break;
				case 1:
					attributeToIncrease = Attribute.Dexterity;
					break;
				case 2:
					attributeToIncrease = Attribute.Vitality;
					break;
				case 3:
					attributeToIncrease = Attribute.Magic;
					break;
				}
				playerSaveData.attributes.Find((AttributeSave x) => x.attrib == attributeToIncrease).baseValue++;
				num9--;
			}
			ItemStorage itemStorage = new ItemStorage
			{
				items = new List<ItemSaveData>()
			};
			List<MerchantType> list3 = new List<MerchantType> { MerchantType.Weapons };
			for (int k = 0; k < 10; k++)
			{
				if (UnityEngine.Random.value < 0.2f)
				{
					list3.Add(MerchantType.WeaponsArmor);
				}
			}
			for (int l = 0; l < 10; l++)
			{
				if (UnityEngine.Random.value < 0.2f)
				{
					list3.Add(MerchantType.Goods);
				}
			}
			for (int m = 0; m < list3.Count; m++)
			{
				ItemSaveData randomItemSaveData = GetRandomItemSaveData(list3[m]);
				if (randomItemSaveData != null)
				{
					itemStorage.items.Add(randomItemSaveData);
				}
			}
			fateSaveData.playerSaveData = playerSaveData;
			fateSaveData.itemSaveData = itemStorage;
			return fateSaveData;
		}

		public void SetTactics(Tactics newTactics)
		{
			Tactics currentTactics = CurrentTactics;
			if (currentTactics != newTactics)
			{
				CurrentTactics = newTactics;
				onTacticsChanged?.Invoke(CurrentTactics);
				if (debug)
				{
					UnityEngine.Debug.Log($"{this}: Tactics changed from {currentTactics} to {newTactics}");
				}
			}
		}

		public override void SetAIState(AIState newState)
		{
			AIState aIState = eAIState;
			if ((aIState == AIState.PassingOut || aIState == AIState.PassedOut) && newState != AIState.PassingOut && newState != AIState.PassedOut)
			{
				animator.SetBool("IsDead", value: false);
				myVitals.Revive();
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_narr_ally_recovered);
			}
			base.SetAIState(newState);
		}

		public override void UpdateAI()
		{
			KnockBackCheck();
			if (!Alive() || !base.UnderKnockback)
			{
				if (!IsCurrentTargetValid())
				{
					SetTarget(null);
				}
				if (Target() != null && currentAttack == null)
				{
					SelectAttack();
				}
				switch (eAIState)
				{
				case AIState.Dying:
					DyingAI();
					break;
				case AIState.OperateItem:
					OperateItemAI();
					break;
				case AIState.Inactive:
					SetAIState(AIState.Wander);
					break;
				case AIState.ReturningToTown:
					ReturnToTownAI();
					break;
				case AIState.Wander:
					WanderAI();
					break;
				case AIState.PassingOut:
					PassingOutAI();
					break;
				case AIState.PassedOut:
					PassedOutAI();
					break;
				case AIState.Flee:
					FleeAI();
					break;
				case AIState.GetRange:
					GetRangeAI();
					break;
				case AIState.Attack:
					AttackAI();
					break;
				case AIState.Approach:
				case AIState.ScriptApproach:
					ApproachAI();
					break;
				case AIState.Follow:
					FollowAI();
					break;
				case AIState.Hunt:
					HuntAI();
					break;
				case AIState.GetItem:
					GetItemAI();
					break;
				case AIState.Cast:
					CastAI();
					break;
				default:
					UnityEngine.Debug.LogWarning($"{base.name}: Unhandled AI state {eAIState}. Setting state to Inactive.");
					SetAIState(AIState.Inactive);
					break;
				}
			}
		}

		private void WanderAI()
		{
			if (GetFinalMoveSpeed() == 0f || PartyAI())
			{
				return;
			}
			SetRunning(runningState: false);
			if (levelData != null && UnityEngine.Random.value < 0.1f && GetAlignment() != Alignment.Neutral && !IsPetNearDeath())
			{
				Alignment alignment = Alignment.Good;
				if (GetAlignment() == Alignment.Good)
				{
					alignment = Alignment.Evil;
				}
				float radius = attentionRadius;
				if (HasMaster())
				{
					radius = 8.75f;
				}
				if (CurrentTactics != Tactics.Defensive)
				{
					float num = viewRadius;
					num = ((CurrentTactics != Tactics.Aggressive) ? (num * 0.5f) : (num * 1.2f));
					Character character = levelData.FindCharacterWithinView(myTransform, alignment, motionRadius, num, radius);
					if (HasMaster() && character == null)
					{
						if (Master().GetAIState() == AIState.Attack || Master().GetAIState() == AIState.Hunt)
						{
							character = Master().Target();
						}
						if (!character)
						{
							character = levelData.FindCharacterWithinView(Master().myTransform, alignment, motionRadius, num, radius);
						}
					}
					if (HasMaster() && character != null)
					{
						Fate.GetDeltaAndDistance(Master().myTransform.position, character.myTransform.position, out var _, out var distance);
						if (distance > 8.75f)
						{
							character = null;
						}
					}
					if (HasMaster() && character == null && CurrentTactics == Tactics.Aggressive)
					{
						float num2 = float.MaxValue;
						for (int i = 0; i < Master().GetPartyMemberCount(); i++)
						{
							Character partyMember = Master().GetPartyMember(i);
							if (partyMember.GetAIState() == AIState.Hunt || partyMember.GetAIState() == AIState.Attack)
							{
								Fate.GetDeltaAndDistance(partyMember.myTransform.position, myTransform.position, out var _, out var distance2);
								if (distance2 < num2)
								{
									num2 = distance2;
									character = partyMember.Target();
								}
							}
						}
					}
					if (character != null)
					{
						if (character.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							character = character.Master();
						}
						StopPathing();
						SetAIState(AIState.Hunt);
						if (IsValidTarget(character))
						{
							SetTarget(character);
						}
						return;
					}
				}
			}
			int num3 = 2;
			float num4 = 5f;
			switch (CurrentTactics)
			{
			case Tactics.Aggressive:
				num4 = 5f;
				num3 = 4;
				break;
			case Tactics.Support:
				num4 = 2.5f;
				num3 = 1;
				break;
			case Tactics.Defensive:
				num4 = 1.25f;
				num3 = 0;
				break;
			}
			if ((bool)Master() && Master().FishingAny())
			{
				num3 = 0;
				num4 = 20f;
				if (Target() == null)
				{
					StopPathing();
				}
			}
			if (!Pathing() && UnityEngine.Random.value < (float)num3 * 0.001f && HasMaster())
			{
				float num5 = num4;
				Vector3 position = Master().myTransform.position;
				SetDestination(UnityEngine.Random.Range(position.x - num5, position.x + num5), UnityEngine.Random.Range(position.z - num5, position.z + num5));
			}
			if (HasMaster())
			{
				Alignment alignment2 = Alignment.Good;
				if (GetAlignment() == Alignment.Good)
				{
					alignment2 = Alignment.Evil;
				}
				SetRunning(Master().Running());
				if (Master().StaminaFloat() < 1f)
				{
					SetRunning(runningState: false);
				}
				if (Master().Target() != null && Master().Target().GetAlignment() == alignment2 && !IsPetNearDeath() && CurrentTactics != Tactics.Defensive)
				{
					Fate.GetDeltaAndDistance(Master().myTransform.position, Master().Target().myTransform.position, out var _, out var distance3);
					if (distance3 <= 5f)
					{
						if (IsValidTarget(Master().Target()))
						{
							SetTarget(Master().Target());
							SetAIState(AIState.Hunt);
						}
						return;
					}
				}
				Fate.GetDeltaAndDistance(Master().myTransform.position, myTransform.position, out var diffVector4, out var distance4);
				if (distance4 > 7f)
				{
					SetRunning(runningState: true);
				}
				else if (distance4 <= 5f && !Master().Pathing())
				{
					SetRunning(runningState: false);
				}
				if (levelData != null && distance4 > 16f)
				{
					float time = Time.time;
					if (time - teleportTime > 3f)
					{
						path.enabled = false;
						myTransform.position = levelData.RandomOpenPosition(Master().myTransform.position, 1f);
						path.enabled = true;
						teleportTime = time;
						WanderCloseToPlayer();
					}
				}
				if (IsPetNearDeath())
				{
					SetRunning(runningState: true);
				}
				if (UnityEngine.Random.value < 0.1f || IsPetNearDeath())
				{
					diffVector4 = ((!Pathing()) ? ((Master().myTransform.position - myTransform.position) * 0.37776f) : ((Master().myTransform.position - finalTargetPosition) * 0.37776f));
					diffVector4.y = 0f;
					distance4 = diffVector4.magnitude;
					if ((IsPetNearDeath() && !Pathing()) || (distance4 > num4 && timeSincePath > 0.25f))
					{
						SetRunning(runningState: true);
						float num6 = num4 * 0.9f;
						SetDestination(UnityEngine.Random.Range(Master().myTransform.position.x - num6, Master().myTransform.position.x + num6), UnityEngine.Random.Range(Master().myTransform.position.z - num6, Master().myTransform.position.z + num6));
					}
				}
			}
			if (!Pathing() && eAIState == AIState.Wander && UnityEngine.Random.Range(0, 1000) < 2 && uniqueIdleAnimations.Length != 0)
			{
				StopPathing();
				animator.SetBool("IsUniqueIdle", value: true);
				SetAIState(AIState.UniqueIdle);
			}
		}

		private void WanderCloseToPlayer()
		{
			float num = 2.5f;
			Vector3 position = Master().myTransform.position;
			SetDestination(UnityEngine.Random.Range(position.x - num, position.x + num), UnityEngine.Random.Range(position.z - num, position.z + num));
		}

		private bool PartyAI()
		{
			if (Time.time - lastTacticsActionTime < 2f)
			{
				return false;
			}
			bool flag = true;
			switch (CurrentTactics)
			{
			case Tactics.Aggressive:
				if (!DoAggroAction() && !DoSupportAction() && !DoDefensiveAction())
				{
					flag = false;
				}
				break;
			case Tactics.Support:
				if (!DoSupportAction() && !DoAggroAction() && !DoDefensiveAction())
				{
					flag = false;
				}
				break;
			case Tactics.Defensive:
				if (!DoDefensiveAction() && !DoSupportAction() && !DoAggroAction())
				{
					flag = false;
				}
				break;
			}
			if (flag)
			{
				lastTacticsActionTime = Time.time;
			}
			return flag;
		}

		protected override void Update()
		{
			base.Update();
			if (eAIState == AIState.PassedOut)
			{
				RecoverFromPassOut(toClearEffects: true);
			}
		}

		public override void AttackAI()
		{
			if (targetItem != null)
			{
				SetTargetItem(null);
			}
			if (Target() == null || !Target().Alive() || !Target().AvailableForCommand())
			{
				SetAIState(AIState.Wander);
				SetTarget(null);
				return;
			}
			if (Target().GetAlignment() == GetAlignment() || Target().GetAlignment() == Alignment.Neutral)
			{
				SetAIState(AIState.Inactive);
				SetTarget(null);
				return;
			}
			if (currentAttack == null)
			{
				SelectAttack();
				if (currentAttack == null)
				{
					return;
				}
			}
			if (PartyAI())
			{
				return;
			}
			Fate.GetDeltaAndDistance(Target().myTransform.position, myTransform.position, out var diffVector, out var distance);
			if (IsAnArcher())
			{
				if (Pathing())
				{
					return;
				}
				if (distance < AttackRange() / 2f * 0.4f && UnityEngine.Random.Range(0, 100) < 40 && !PerformingAttack())
				{
					Vector3 vector = myTransform.position + new Vector3(diffVector.x * 0.25f, 0f, diffVector.z * 0.25f);
					SetDestination(vector.x, vector.z);
					return;
				}
			}
			if (!HasMaster() && distance >= followRadius)
			{
				StopPathing();
				SetAIState(AIState.Wander);
				SetTarget(null);
				return;
			}
			if (HPPercentage() < 0.5f)
			{
				SelectHealSpell();
				if (activeSpell != null && UnityEngine.Random.value < 0.005f && HasSpellCosts(activeSpell))
				{
					Character targetChar = this;
					TryCastCurrentSpell(null, null, targetChar);
					return;
				}
			}
			SelectAttackSpell();
			if (activeSpell != null && UnityEngine.Random.value < 0.002f && HasSpellCosts(activeSpell))
			{
				Character targetChar = targetCharacter;
				TryCastCurrentSpell(null, null, targetChar);
				return;
			}
			SelectDefenseSpell();
			if (activeSpell != null && UnityEngine.Random.value < 0.002f && HasSpellCosts(activeSpell))
			{
				Character targetChar = this;
				TryCastCurrentSpell(null, null, targetChar);
				return;
			}
			if (GetPetCount() < 1)
			{
				SelectSummonSpell();
				if (activeSpell != null && UnityEngine.Random.value < 0.001f && HasSpellCosts(activeSpell))
				{
					Character targetChar = this;
					TryCastCurrentSpell(null, null, targetChar);
					return;
				}
			}
			if (Target().GetPetCount() > 1 || Target().IsSummoned())
			{
				SelectBanishSpell();
				if (activeSpell != null && UnityEngine.Random.value < 0.0025f)
				{
					if (Target().IsSummoned() && Target().HasMaster())
					{
						SetTarget(Target().Master());
					}
					if (Target() == null)
					{
						return;
					}
					if (HasSpellCosts(activeSpell))
					{
						Character targetChar = targetCharacter;
						TryCastCurrentSpell(null, null, targetChar);
						return;
					}
				}
			}
			if (InAttackRange() && ValidLineOfSight())
			{
				if (Target() != null)
				{
					TurnTowardPosition(Target().myTransform.position);
					if (!PerformingAttack())
					{
						if (UnityEngine.Random.Range(0, 100) < 40 && timeSincePath > 1f && Target() != null && TooCloseForAttack())
						{
							SetAIState(AIState.GetRange);
							float num = AttackRange();
							Vector3 vector2 = new Vector3(UnityEngine.Random.Range(0f - num, num), 0f, UnityEngine.Random.Range(0f - num, num));
							Vector3 vector3 = Target().myTransform.position + vector2;
							SetDestination(vector3.x, vector3.z);
						}
						else if (FacingTarget())
						{
							Attack();
						}
					}
				}
				if (HasMaster() && !PerformingAttack())
				{
					Fate.GetDeltaAndDistance(masterCharacter.myTransform.position, myTransform.position, out var _, out var distance2);
					if (distance2 > 8.75f)
					{
						SetTarget(null, resetAttackSpeed: false);
						SetAIState(AIState.Wander);
					}
				}
			}
			else if (!PerformingAttack())
			{
				SetAIState(AIState.Hunt);
			}
		}

		private void SelectAttackSpell()
		{
			SetActiveSpell(null);
			if (knownSpells == null || knownSpells.IsEmpty() || !knownSpells.ContainsKey(SpellSphere.Attack))
			{
				return;
			}
			List<SpellData> list = knownSpells[SpellSphere.Attack];
			if (list == null)
			{
				return;
			}
			foreach (SpellData item in list)
			{
				if (!(item == null) && UnityEngine.Random.Range(0, 1000) < 200)
				{
					SetActiveSpell(item);
					break;
				}
			}
		}

