		private Item DetermineBestPotion(Character target, AIEffect effects)
		{
			int num = 0;
			switch (effects)
			{
			case AIEffect.Heal:
				num = target.MaxHP() - target.HP();
				break;
			case AIEffect.Mana:
				num = target.MaxMana() - target.Mana();
				break;
			case AIEffect.Stamina:
				num = target.MaxStamina() - target.Stamina();
				break;
			}
			Item result = null;
			float num2 = 100000f;
			if (inventory != null)
			{
				foreach (Item item in inventory)
				{
					if (item.itemType != ItemType.Potion)
					{
						continue;
					}
					float num3 = 0f;
					switch (effects)
					{
					case AIEffect.Heal:
						num3 = item.healAmount;
						break;
					case AIEffect.Mana:
						num3 = item.manaAmount;
						break;
					case AIEffect.Stamina:
						num3 = item.staminaAmount;
						break;
					}
					if (num3 > 0f)
					{
						if (num3 > (float)num)
						{
							num3 *= 1.5f;
						}
						if (num3 < (float)(num / 2))
						{
							num3 *= 1.25f;
						}
						if (num3 < num2)
						{
							num2 = num3;
							result = item;
						}
					}
				}
			}
			return result;
		}

		protected override void Attack()
		{
			if (!PerformingAttack())
			{
				if (base.activeWeapon != null)
				{
					currentAttack = new AttackData(base.activeWeapon, base.activeWeapon.IsInMainHand);
				}
				else
				{
					currentAttack = playerUnarmedAttack;
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.AttackMiss, randomizePitch: true);
				}
				float num = 1f;
				num += EffectValue(EffectType.PercentAttackSpeed) / 100f;
				num *= currentAttack.speed;
				if (num < 0.2f)
				{
					num = 0.2f;
				}
				base.attackTimer = num;
				reachedStrikePoint = false;
				animator.SetBool("IsAttacking", value: true);
			}
		}

		protected override AttackData UnarmedAttack(int _)
		{
			return playerUnarmedAttack;
		}

		public virtual void AnimCallbackAttackOccur(int id)
		{
		}

		public void AnimCallbackAttackEnd()
		{
			animator.SetBool("IsAttacking", value: false);
			animator.speed = 1f;
			if (base.castTimer > 0f && !reachedCastPoint)
			{
				base.castTimer = 0f;
				reachedCastPoint = true;
				Character targetChar = Target();
				CompleteSpell(null, null, targetChar);
			}
			if (base.attackTimer > 0f && !reachedStrikePoint)
			{
				base.attackTimer = 0f;
				reachedStrikePoint = true;
				PerformAttack();
				animator.SetBool("IsAttacking", value: false);
				SwapDualWieldWeaponHand();
			}
			currentAttack = null;
		}

		public void OnStep()
		{
			if (Time.realtimeSinceStartup > lastStep + stepCooldown)
			{
				lastStep = Time.realtimeSinceStartup;
				if (LevelGenerator.currentInstance == null)
				{
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.BasicStep, base.transform.position, 0.15f, 0.3f);
				}
				else
				{
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(LevelGenerator.currentInstance.ActiveStepSound, base.transform.position, 0.15f, 0.3f);
				}
			}
		}

		private void SelectHealMinionSpell()
		{
			SetActiveSpell(null);
			if (knownSpells == null || knownSpells.IsEmpty() || !knownSpells.ContainsKey(SpellSphere.Defense))
			{
				return;
			}
			List<SpellData> list = knownSpells[SpellSphere.Defense];
			if (list == null)
			{
				return;
			}
			foreach (SpellData item in list)
			{
				if (!(item == null) && item.IsHealSpell() && item.RequiresCharacterTarget() && UnityEngine.Random.Range(0, 1000) < 200)
				{
					SetActiveSpell(item);
					break;
				}
			}
		}

		public override void HuntAI()
		{
			if (Target() == null || !Target().Alive() || IsPetNearDeath() || Target().IsPetNearDeath())
			{
				SetAIState(AIState.Wander);
				SetTarget(null);
				return;
			}
			if (Target().GetAlignment() == GetAlignment() || Target().GetAlignment() == Alignment.Neutral)
			{
				SetAIState(AIState.Inactive);
				SetTarget(null);
				return;
			}
			SetRunning(runningState: true);
			Fate.GetDeltaAndDistance(myTransform.position, Target().myTransform.position, out var diffVector, out var distance);
			if (distance >= followRadius && !HasMaster())
			{
				StopPathing();
				SetAIState(AIState.Wander);
				SetTarget(null);
				return;
			}
			bool flag = InAttackRange();
			bool flag2 = ValidLineOfSight();
			if ((!flag || !flag2) && timeSincePath > 1f)
			{
				if (!Pathing())
				{
					FollowCharacter(Target());
				}
				else
				{
					Fate.GetDeltaAndDistance(finalTargetPosition, Target().myTransform.position, out diffVector, out distance);
					if (distance >= 16f)
					{
						FollowCharacter(Target());
					}
				}
				if (!Pathing())
				{
					SetTarget(null);
					SetAIState(AIState.Wander);
					return;
				}
			}
			if (HPPercentage() < 0.5f)
			{
				SelectHealSpell();
				if (activeSpell != null && UnityEngine.Random.value < 0.005f && HasSpellCosts(activeSpell))
				{
					Character targetChar = this;
					TryCastCurrentSpell(null, null, targetChar);
					return;
				}
			}
			for (int i = 0; i < GetPetCount(); i++)
			{
				Character pet = GetPet(i);
				if (pet.HPPercentage() < 0.5f)
				{
					SelectHealMinionSpell();
					if (activeSpell != null && UnityEngine.Random.value < 0.005f && HasSpellCosts(activeSpell))
					{
						Character targetChar = pet;
						TryCastCurrentSpell(null, null, targetChar);
						return;
					}
				}
			}
			float num = 0.002f;
			SelectAttackSpell();
			if (activeSpell != null && UnityEngine.Random.value < num && HasSpellCosts(activeSpell))
			{
				Character targetChar = Target();
				TryCastCurrentSpell(null, null, targetChar);
				return;
			}
			float num2 = 0.002f;
			SelectDefenseSpell();
			if (activeSpell != null && UnityEngine.Random.value < num2 && HasSpellCosts(activeSpell))
			{
				Character targetChar = this;
				TryCastCurrentSpell(null, null, targetChar);
				return;
			}
			if (GetPetCount() < 1)
			{
				SelectSummonSpell();
				if (activeSpell != null && UnityEngine.Random.value < 0.002f && HasSpellCosts(activeSpell))
				{
					TryCastCurrentSpell();
					return;
				}
			}
			if (Target() != null && (Target().GetPetCount() > 1 || Target().IsSummoned()))
			{
				SelectBanishSpell();
				if (activeSpell != null && UnityEngine.Random.value < 0.005f)
				{
					if (Target().IsSummoned() && Target().HasMaster())
					{
						SetTarget(Target().Master());
					}
					if (Target() == null)
					{
						return;
					}
					if (HasSpellCosts(activeSpell))
					{
						Character targetChar = Target();
						TryCastCurrentSpell(null, null, targetChar);
						return;
					}
				}
			}
			if (flag && flag2)
			{
				SetAIState(AIState.Attack);
				StopPathing();
			}
			else if (HasMaster() && Target() != null)
			{
				Vector3 vector = Master().myTransform.position - Target().myTransform.position;
				vector.y = 0f;
				if (vector.magnitude * 0.25f > 8.75f)
				{
					SetTarget(null);
					SetAIState(AIState.Wander);
				}
			}
		}

		private void FleeAI()
		{
			SetTarget(null, resetAttackSpeed: false);
			SetRunning(runningState: true);
			if (!Pathing())
			{
				if (UnityEngine.Random.Range(0, 100) < 50)
				{
					SetAIState(AIState.Wander);
				}
				if (HasMaster())
				{
					float num = 10f;
					Vector3 vector = Master().myTransform.position + new Vector3(UnityEngine.Random.Range((0f - num) * 0.37776f, num * 0.37776f), 0f, UnityEngine.Random.Range((0f - num) * 0.37776f, num * 0.37776f));
					SetDestination(vector.x, vector.z);
				}
				else
				{
					Vector3 vector2 = myTransform.position + new Vector3(UnityEngine.Random.Range(-37.776f, 37.776f), 0f, UnityEngine.Random.Range(-37.776f, 37.776f));
					SetDestination(vector2.x, vector2.z);
				}
			}
		}

		public override void PassOut()
		{
			ClearEffects();
			ClearState();
			if (timeToRevive > 0f && eAIState != AIState.PassedOut)
			{
				SetAIState(AIState.PassedOut);
			}
			else if (Mathf.Approximately(timeToRevive, 0f) && eAIState != AIState.PassingOut)
			{
				SetAIState(AIState.PassingOut);
			}
			animator.SetBool("IsDead", value: true);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.MaleDeath, randomizePitch: true);
		}

		private void ClearState()
		{
			SetTarget(null);
			SetTargetItem(null);
			castingCharacterTraget = null;
			targetItem = null;
			base.activeWeapon = null;
			currentAttack = null;
			base.castTimer = 0f;
			base.attackTimer = 0f;
			timeSinceAvoidance = 10f;
			timeSincePath = 10f;
			StopPathing();
			SetAIState(AIState.Inactive);
		}

		public override void PassingOutAI()
		{
			CompletePassOut();
		}

		private void CompletePassOut()
		{
			if (eAIState == AIState.PassingOut)
			{
				if ((bool)Master())
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_narr_ally_collapsed);
				}
				SetAIState(AIState.PassedOut);
				if (Mathf.Approximately(timeToRevive, 0f))
				{
					timeToRevive = Mathf.Clamp(100 + (attributes.Strength + attributes.Dexterity + attributes.Magic) / 3 - attributes.Vitality, 30, 300);
				}
			}
		}

		private void PassedOutAI()
		{
			if (!IsPassedOut())
			{
				SetAIState(AIState.Inactive);
				return;
			}
			SetTarget(null, resetAttackSpeed: false);
			SetRunning(runningState: false);
		}

		private void GetRangeAI()
		{
			SetRunning(runningState: true);
			if (!Pathing())
			{
				if (targetCharacter != null && !TooCloseForAttack())
				{
					SetAIState(AIState.Attack);
				}
				else
				{
					SetAIState(AIState.Wander);
				}
			}
		}

		private void UniqueIdleAI()
		{
			if (!Alive())
			{
				return;
			}
			SetAIState(AIState.Wander);
			if (HasMaster())
			{
				Fate.GetDeltaAndDistance(Master().myTransform.position, myTransform.position, out var _, out var distance);
				if (distance > 5f)
				{
					SetAIState(AIState.Wander);
				}
			}
		}

		protected override void RespondToAttack(CharacterVitals.Damage attacker)
		{
			if (!Alive() || GetAIState() == AIState.ReturningToTown || attacker.source == null || attacker.source == this || GetAIState() == AIState.Flee)
			{
				return;
			}
			if (IsPetNearDeath())
			{
				SetAIState(AIState.Flee);
			}
			else
			{
				if (!attacker.source.Char.Alive() || attacker.source.Char.GetAlignment() == GetAlignment() || attacker.source.Char.GetAlignment() == Alignment.Neutral)
				{
					return;
				}
				if (Target() == null)
				{
					if (!PerformingCast() && attacker.source.Char.Alive())
					{
						SetAIState(AIState.Hunt);
						if (attacker.source.Char.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							SetTarget(attacker.source.Char.Master());
						}
						else
						{
							SetTarget(attacker.source.Char);
						}
					}
				}
				else
				{
					if (PerformingAttack() || PerformingCast())
					{
						return;
					}
					if (UnityEngine.Random.Range(0, 1000) < 50)
					{
						SetAIState(AIState.Attack);
						if (attacker.source.Char.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							SetTarget(attacker.source.Char.Master());
						}
						else
						{
							SetTarget(attacker.source.Char);
						}
					}
					else if (GetAIState() == AIState.Inactive || GetAIState() == AIState.Wander)
					{
						SetAIState(AIState.Attack);
						if (attacker.source.Char.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							SetTarget(attacker.source.Char.Master());
						}
						else
						{
							SetTarget(attacker.source.Char);
						}
					}
				}
			}
		}

		public override void RespondToAttack(Character attacker)
		{
			if (!Alive() || eAIState == AIState.InTown || eAIState == AIState.Hidden || eAIState == AIState.ReturningToTown || attacker == null || attacker == this || eAIState == AIState.Flee || eAIState == AIState.PassingOut || eAIState == AIState.PassedOut)
			{
				return;
			}
			if (MaxHP() > 0 && HP() <= 0)
			{
				PassOut();
			}
			else
			{
				if (!attacker.Alive() || attacker.GetAlignment() == GetAlignment() || attacker.GetAlignment() == Alignment.Neutral)
				{
					return;
				}
				if (Target() == null)
				{
					if (PerformingCast() || !attacker.Alive())
					{
						return;
					}
					_ = eAIState;
					_ = 14;
					SetAIState(AIState.Hunt);
					if (attacker.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
					{
						if (IsValidTarget(attacker.Master()))
						{
							SetTarget(attacker.Master());
						}
					}
					else if (IsValidTarget(attacker))
					{
						SetTarget(attacker);
					}
				}
				else
				{
					if (PerformingAttack() || PerformingCast())
					{
						return;
					}
					if (UnityEngine.Random.value < 0.05f)
					{
						SetAIState(AIState.Attack);
						if (attacker.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							if (IsValidTarget(attacker.Master()))
							{
								SetTarget(attacker.Master());
							}
						}
						else if (IsValidTarget(attacker))
						{
							SetTarget(attacker);
						}
					}
					else
					{
						if (eAIState != 0 && eAIState != AIState.Wander)
						{
							return;
						}
						SetAIState(AIState.Attack);
						if (attacker.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							if (IsValidTarget(attacker.Master()))
							{
								SetTarget(attacker.Master());
							}
						}
						else if (IsValidTarget(attacker))
						{
							SetTarget(attacker);
						}
					}
				}
			}
		}

		private bool DoDefensiveAction()
		{
			bool flag = eAIState == AIState.Attack || eAIState == AIState.Hunt;
			bool flag2 = CurrentTactics == Tactics.Defensive;
			int num = UnityEngine.Random.Range(0, 1000);
			switch (CurrentTactics)
			{
			case Tactics.Aggressive:
				return false;
			case Tactics.Support:
				if (flag && num > 10)
				{
					return false;
				}
				if (!flag && num > 30)
				{
					return false;
				}
				break;
			case Tactics.Defensive:
				if (flag && num > 500)
				{
					return false;
				}
				break;
			}
			float num2 = 0f;
			float num3 = 0f;
			float num4 = 0f;
			Character target = null;
			float num5 = 0f;
			if ((bool)Master())
			{
				num2 = Master().HPPercentage() - 0.1f;
				target = Master();
			}
			for (int i = 0; i < Master().GetPartyMemberCount(); i++)
			{
				Character partyMember = Master().GetPartyMember(i);
				num5 = partyMember.HPPercentage();
				if (num5 < num2)
				{
					num2 = num5;
					target = partyMember;
				}
			}
			if (!flag2 && flag)
			{
				num2 *= 1.5f;
			}
			if (num2 < 0f)
			{
				num2 = 0f;
			}
			if (num2 > 1f)
			{
				num2 = 1f;
			}
			bool flag3 = true;
			if (num2 > 0.65f)
			{
				flag3 = false;
			}
			if (num2 <= 0f)
			{
				flag3 = false;
			}
			if (!flag3)
			{
				return false;
			}
			int num6 = CountHealPotions();
			num3 = ((num6 < 2) ? (flag2 ? 0.4f : 0.25f) : ((num6 >= 5) ? 1f : (flag2 ? 0.8f : 0.5f)));
			if ((num3 + num4) / 2f / num2 > 0.5f && num3 > num4)
			{
				Item item = DetermineBestPotion(target, AIEffect.Heal);
				if (item != null)
				{
					PerformItemUse(item, target);
				}
				return true;
			}
			return false;
		}

		private int CountHealPotions()
		{
			int num = 0;
			if (inventory != null)
			{
				foreach (Item item in inventory)
				{
					if (item.itemType == ItemType.Potion && item.healAmount > 0)
					{
						num++;
					}
				}
			}
			return num;
		}

		private bool DoSupportAction()
		{
			if ((eAIState != AIState.Attack && eAIState != AIState.Hunt) || !Target())
			{
				return false;
			}
			bool flag = false;
			if (CurrentTactics == Tactics.Support)
			{
				flag = UnityEngine.Random.value < 0.001f;
				if (Mana() == MaxMana())
				{
					flag = true;
				}
			}
			else if (CurrentTactics == Tactics.Defensive)
			{
				flag = UnityEngine.Random.value < 0.0001f;
			}
			if (flag)
			{
				SpellData spellData = activeSpell;
				SelectDefenseSpell();
				if (activeSpell != null && HasSpellCosts(activeSpell))
				{
					Character targetChar = Target();
					TryCastCurrentSpell(null, null, targetChar);
					return true;
				}
				SetActiveSpell(spellData);
			}
			if (CurrentTactics == Tactics.Support)
			{
				Character character = null;
				float num = 100f;
				Character character2 = null;
				float num2 = 100f;
				if ((bool)Master() && (double)Master().ManaPercentage() < 0.35)
				{
					character = Master();
					num = Master().ManaPercentage();
				}
				if ((bool)Master() && (double)Master().StaminaPercentage() < 0.35)
				{
					character2 = Master();
					num2 = Master().StaminaPercentage();
				}
				for (int i = 0; i < Master().GetPartyMemberCount(); i++)
				{
					if (Master().GetPartyMember(i).ManaPercentage() < num)
					{
						character = Master().GetPartyMember(i);
						num = character.ManaPercentage();
					}
					if (Master().GetPartyMember(i).StaminaPercentage() < num2)
					{
						character2 = Master().GetPartyMember(i);
						num2 = character2.StaminaPercentage();
					}
				}
				if ((bool)character && UnityEngine.Random.value < 0.05f)
				{
					Item item = DetermineBestPotion(character, AIEffect.Mana);
					if (item != null)
					{
						PerformItemUse(item, character);
						return true;
					}
				}
				if ((bool)character2 && UnityEngine.Random.value < 0.05f)
				{
					Item item2 = DetermineBestPotion(character, AIEffect.Stamina);
					if (item2 != null)
					{
						PerformItemUse(item2, character);
						return true;
					}
				}
			}
			return false;
		}

		private bool DoAggroAction()
		{
			bool num = eAIState == AIState.Attack && (bool)Target();
			_ = CurrentTactics;
			if (!num)
			{
				return false;
			}
			Target().HPPercentage();
			return false;
		}

		protected override bool DelayAttack()
		{
			if (Family() == Tableflip.Family.Nemesis)
			{
				return timeSinceFamilyAI > 3f;
			}
			return false;
		}

		private bool IsValidTarget(Character potentialTarget)
		{
			if (IsPet() && potentialTarget.Family() == Tableflip.Family.Nemesis)
			{
				return false;
			}
			Alignment alignment = potentialTarget.GetAlignment();
			bool flag = alignment == Alignment.Good || alignment == Alignment.Evil;
			if (potentialTarget.Alive() && flag)
			{
				return potentialTarget.GetAlignment() != GetAlignment();
			}
			return false;
		}

		private void PerformItemUse(Item item, Character targetCharacter)
		{
			if (item.itemTarget == ItemTarget.User && item.CanUse(this, targetCharacter))
			{
				item.Use(this, targetCharacter);
				if (item.useable && !item.HasUnlimitedUses && item.uses <= 0)
				{
					RemoveItemFromInventory(item, RemoveItemReason.Consumed);
				}
			}
		}

		private bool IsAnArcher()
		{
			Item equippedWeapon = GetEquippedWeapon(WeaponHand.MainHand);
			if (equippedWeapon != null)
			{
				return !equippedWeapon.IsMelee;
			}
			Item equippedWeapon2 = GetEquippedWeapon(WeaponHand.OffHand);
			if (equippedWeapon2 != null)
			{
				return !equippedWeapon2.IsMelee;
			}
			return false;
		}

		private void RecoverFromPassOut(bool toClearEffects, bool recoverForce = false)
		{
			if (recoverForce && eAIState == AIState.PassedOut)
			{
				timeToRevive = 0f;
			}
			timeToRevive -= Time.deltaTime;
			if (!(timeToRevive <= 0f))
			{
				return;
			}
			timeToRevive = 0f;
			if (eAIState == AIState.PassedOut)
			{
				if (toClearEffects)
				{
					ClearEffects();
				}
				ModifyHP(1f);
				SetAIState(AIState.Inactive);
				hp = 1f;
			}
		}
	}
	public class Pet : Monster
	{
		[HideInInspector]
		public Texture2D profilePicture;

		private const float petRunMultiplier = 1.5f;

		private int frameCount;

		private int speakMerchantPathFailedCounter;

		private bool firstTimerUpdate = true;

		public override bool IsPlayerOwnedInventory => true;

		public override float GetBaseRunningSpeed => base.GetBaseRunningSpeed * 1.5f;

		public override void Init()
		{
			base.Init();
			invincible = true;
			allowDropInventory = false;
		}

		protected override void Update()
		{
			UpdateHP();
			base.Update();
		}

		public override void PassOut()
		{
			SetAIState(AIState.Flee);
		}

		protected override int[,] GetInventoryGridSize()
		{
			return new int[10, 8];
		}

		public override bool IsPet()
