		}

		public override void TweakToLevel(int newLevel)
		{
			int level = base.Level;
			int num = newLevel - level;
			base.Level = newLevel;
			nextLevelExperience = Fate.GetExperienceNeeded(base.Level);
			if (num >= 0)
			{
				LevelUp(level, skipNarration: true);
			}
		}

		public override bool CanEnterAIState(AIState newState)
		{
			if (newState == AIState.GetItem || newState == AIState.SpeakMerchant)
			{
				AIState aIState = eAIState;
				if (aIState == AIState.ReturningToTown || aIState == AIState.InTown || aIState == AIState.Dead || aIState == AIState.Dying || aIState == AIState.Flee)
				{
					return false;
				}
				return true;
			}
			return true;
		}

		public override void SetAIState(AIState newState)
		{
			base.SetAIState(newState);
			if (newState == AIState.SpeakMerchant)
			{
				speakMerchantPathFailedCounter = 0;
			}
		}

		public override void UpdateAI()
		{
			if (monsterData == null)
			{
				return;
			}
			KnockBackCheck();
			if (!Alive() || !base.UnderKnockback)
			{
				if (Target() != null && !Target().Alive())
				{
					SetTarget(null);
				}
				if (Target() != null || currentAttack == null)
				{
					SelectAttack();
				}
				switch (eAIState)
				{
				case AIState.Dying:
					DyingAI();
					break;
				case AIState.Inactive:
					SetAIState(AIState.Wander);
					break;
				case AIState.Wander:
					WanderAI();
					break;
				case AIState.PassingOut:
				case AIState.PassedOut:
					SetAIState(AIState.Flee);
					break;
				case AIState.Flee:
					FleeAI();
					break;
				case AIState.GetRange:
					GetRangeAI();
					break;
				case AIState.Attack:
					AttackAI();
					break;
				case AIState.Approach:
				case AIState.ScriptApproach:
					ApproachAI();
					break;
				case AIState.Follow:
					FollowAI();
					break;
				case AIState.Hunt:
					HuntAI();
					break;
				case AIState.GetItem:
					GetItemAI();
					break;
				case AIState.SpeakMerchant:
					SpeakMerchantAI();
					break;
				case AIState.Cast:
					CastAI();
					break;
				case AIState.UniqueIdle:
					UniqueIdleAI();
					break;
				case AIState.ReturningToTown:
					ReturnToTownAI();
					break;
				case AIState.InTown:
					UpdateTownTimer();
					break;
				case AIState.Dead:
				case AIState.OperateItem:
				case AIState.CollectReward:
				case AIState.ReceiveQuest:
				case AIState.BuySell:
				case AIState.Fish:
				case AIState.PullFish:
				case AIState.CancelFish:
				case AIState.ReceiveFish:
				case AIState.InEvent:
				case AIState.SendPetToTown:
				case AIState.Retire:
				case AIState.CompleteRetire:
				case AIState.Dispel:
					break;
				}
			}
		}

		public override void ReturnToTownAI(bool forced = false)
		{
			if (!Pathing() || forced)
			{
				SkinnedMeshRenderer componentInChildren = GetComponentInChildren<SkinnedMeshRenderer>();
				if (componentInChildren != null)
				{
					componentInChildren.enabled = false;
				}
				hp = MaxHP();
				RemoveEffect("POISON");
				SetAIState(AIState.InTown);
				CreatureParticleSystem component = GetComponent<CreatureParticleSystem>();
				if (component != null)
				{
					component.DisableAll();
				}
				if (minimapIcon != null)
				{
					minimapIcon.enabled = false;
				}
				if (activeGroundMarker != null)
				{
					activeGroundMarker.SetActive(value: false);
				}
			}
			else
			{
				UpdateTownTimer();
			}
		}

		public override void GetItemAI()
		{
			base.GetItemAI();
		}

		public void SpeakMerchantAI()
		{
			if (!IsPet() || merchantTarget == null)
			{
				SetAIState(AIState.Inactive);
				return;
			}
			SetRunning(runningState: true);
			Vector3 vector = merchantTarget.GetCenterPosition() - myTransform.position;
			vector.y = 0f;
			float magnitude = vector.magnitude;
			if (magnitude < merchantTarget.InteractRange)
			{
				if (merchantTarget.GetMerchantType == MerchantType.Identifier)
				{
					uint identifyCostForInventory = merchantTarget.MerchChar.GetIdentifyCostForInventory(inventory);
					if (SingletonBehaviour<PlayerStatus>.Instance.CanAfford(identifyCostForInventory))
					{
						SingletonBehaviour<PlayerStatus>.Instance.RemoveGold(identifyCostForInventory);
						merchantTarget.MerchChar.IdentifyAllInInventory(inventory, this);
					}
				}
				else
				{
					uint num = SellAllItems();
					if (num != 0)
					{
						ThatHurt.PopText(base.transform.position, "+" + I2Loca.GetFormat("GoldPickup", num), 1f, ThatHurt.ThatHurtColor.Gold, 0f);
					}
					else
					{
						SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Fail, randomizePitch: false);
					}
				}
				merchantTarget = null;
				SetAIState(AIState.Inactive);
			}
			else
			{
				if (!(magnitude > path.stoppingDistance) || Pathing())
				{
					return;
				}
				SetDestination(merchantTarget.GetCenterPosition().x, merchantTarget.GetCenterPosition().z);
				if (!Pathing())
				{
					speakMerchantPathFailedCounter++;
					if (speakMerchantPathFailedCounter >= 3)
					{
						merchantTarget = null;
						SetAIState(AIState.Wander);
					}
				}
				else
				{
					speakMerchantPathFailedCounter = 0;
				}
			}
		}

		protected void UpdateTownTimer()
		{
			if (firstTimerUpdate)
			{
				firstTimerUpdate = false;
				return;
			}
			base.townTimer -= Time.deltaTime;
			if (!(base.townTimer <= 0f) && !(levelData == null) && levelData.GetLevelDepth() != 0)
			{
				return;
			}
			base.townTimer = 0f;
			SetAIState(AIState.Wander);
			if (minimapIcon != null)
			{
				minimapIcon.enabled = true;
			}
			if (activeGroundMarker != null)
			{
				activeGroundMarker.SetActive(value: true);
			}
			if (levelData != null)
			{
				myTransform.position = levelData.RandomOpenPosition(Master().myTransform.position, 25f, 40f);
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_petreturn);
			}
			SkinnedMeshRenderer componentInChildren = GetComponentInChildren<SkinnedMeshRenderer>();
			if (componentInChildren != null)
			{
				componentInChildren.enabled = true;
			}
			CreatureParticleSystem component = GetComponent<CreatureParticleSystem>();
			if (component != null)
			{
				component.ReEnable();
			}
			uint num = SellAllItems();
			bool flag = num != 0;
			if (HasMaster() && Master().IsPlayer() && !Master().Alive())
			{
				return;
			}
			Fate.SetPause(paused: true);
			if (PromptUI.IsPromptActive)
			{
				return;
			}
			GameObject previouslySelectedGO = UtilityTG.GetSelected();
			if (flag)
			{
				SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetMultiLineReplaceTagsFormat("PetReturn_Sold_" + ((levelData != null) ? "Dungeon" : "Town"), num.ToString()), delegate
				{
					if (previouslySelectedGO != null)
					{
						UtilityTG.UnityDelay(delegate
						{
							UtilityTG.SetSelected(previouslySelectedGO);
						});
					}
					Fate.SetPause(paused: false);
				}, twoButtons: false, I2Loca.Get("OK"));
				return;
			}
			SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetReplaceTags("PetReturn_NoSell_" + ((levelData != null) ? "Dungeon" : "Town")), delegate
			{
				if (previouslySelectedGO != null)
				{
					UtilityTG.UnityDelay(delegate
					{
						UtilityTG.SetSelected(previouslySelectedGO);
					});
				}
				Fate.SetPause(paused: false);
			}, twoButtons: false, I2Loca.Get("OK"));
		}

		private uint SellAllItems()
		{
			uint num = 0u;
			for (int i = 0; i < inventory.Count; i++)
			{
				Item item = inventory[i];
				if (!item.itemData.notSellable && !item.equipped && !item.InEquipmentSlot && !item.IsHeroItem() && item.itemType != ItemType.Tarot && !item.isQuestItem && !item.lockedForSelling)
				{
					SingletonBehaviour<PlayerStatus>.Instance.AddGold(item.SellValue());
					num += item.SellValue();
					RemoveItemFromInventory(item, RemoveItemReason.Sell);
					i--;
				}
			}
			return num;
		}

		public override void WanderAI()
		{
			running = false;
			if (HasMaster() && Master().FishingAny() && Target() == null)
			{
				StopPathing();
				TriggerUniqueIdle(0.2f);
				return;
			}
			if (LevelGenerator.currentInstance != null && UnityEngine.Random.Range(0, 1000) < 100 && GetAlignment() != Alignment.Neutral && !IsPetNearDeath())
			{
				Alignment alignment = Alignment.Good;
				if (GetAlignment() == Alignment.Good)
				{
					alignment = Alignment.Evil;
				}
				float radius = (float)monsterData.attentionRadius * 0.25f;
				if (HasMaster())
				{
					radius = 8.75f;
				}
				Character character = levelData.FindCharacterWithinView(myTransform, alignment, (float)monsterData.motionRadius * 0.25f, (float)monsterData.viewRadius * 0.25f, radius);
				if (HasMaster() && character == null)
				{
					character = levelData.FindCharacterWithinView(Master().transform, alignment, (float)monsterData.motionRadius * 0.25f, (float)monsterData.viewRadius * 0.25f, radius);
				}
				if (HasMaster() && character != null)
				{
					Vector3 vector = Master().transform.position - character.transform.position;
					vector.y = 0f;
					if (vector.magnitude > 8.75f)
					{
						character = null;
					}
				}
				if (character != null)
				{
					if (character.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
					{
						character = character.Master();
					}
					StopPathing();
					SetAIState(AIState.Hunt);
					SetTarget(character);
					return;
				}
			}
			if (GetFinalMoveSpeed() == 0f)
			{
				return;
			}
			if (!Pathing() && UnityEngine.Random.Range(0, 1000) < 2)
			{
				if (HasMaster())
				{
					float num = 4.5f;
					SetDestination(UnityEngine.Random.Range(Master().transform.position.x - num, Master().transform.position.x + num), UnityEngine.Random.Range(Master().transform.position.z - num, Master().transform.position.z + num));
				}
				else
				{
					SetDestination(UnityEngine.Random.Range(myTransform.position.x - 100f, myTransform.position.x + 100f), UnityEngine.Random.Range(myTransform.position.z - 100f, myTransform.position.z + 100f));
				}
			}
			if (HasMaster())
			{
				Alignment alignment2 = Alignment.Good;
				if (GetAlignment() == Alignment.Good)
				{
					alignment2 = Alignment.Evil;
				}
				SetRunning(Master().Running());
				if (Master().stamina < 1f)
				{
					SetRunning(runningState: false);
				}
				Vector3 vector2;
				float magnitude;
				if (Master().Target() != null && Master().Target().GetAlignment() == alignment2 && Master().Target().Alive() && !Master().Target().DisplayedAsItem() && !IsPetNearDeath())
				{
					vector2 = Master().transform.position - Master().Target().transform.position;
					vector2.y = 0f;
					magnitude = vector2.magnitude;
					if (magnitude <= 5f)
					{
						SetTarget(Master().Target());
						SetAIState(AIState.Hunt);
						return;
					}
				}
				vector2 = Master().transform.position - myTransform.position;
				vector2.y = 0f;
				magnitude = vector2.magnitude;
				if (magnitude > 7f)
				{
					SetRunning(runningState: true);
				}
				else if (magnitude <= 5f && !Master().Pathing())
				{
					SetRunning(runningState: false);
				}
				if (LevelGenerator.currentInstance != null && magnitude > 16f)
				{
					float time = Time.time;
					if (time - teleportTime > 3f)
					{
						path.enabled = false;
						myTransform.position = levelData.RandomOpenPosition(Master().myTransform.position, 1f);
						path.enabled = true;
						teleportTime = time;
					}
				}
				if (IsPetNearDeath())
				{
					SetRunning(runningState: true);
				}
				if (UnityEngine.Random.Range(0, 1000) < 100 || IsPetNearDeath())
				{
					vector2 = ((!Pathing()) ? (Master().transform.position - base.transform.position) : (Master().transform.position - finalTargetPosition));
					vector2.y = 0f;
					magnitude = vector2.magnitude;
					if ((IsPetNearDeath() && !Pathing()) || (magnitude > 5f && timeSincePath > 0.25f))
					{
						SetRunning(runningState: true);
						float num2 = 4.5f;
						SetDestination(UnityEngine.Random.Range(Master().transform.position.x - num2, Master().transform.position.x + num2), UnityEngine.Random.Range(Master().transform.position.z - num2, Master().transform.position.z + num2));
					}
				}
			}
			if (!Pathing() && eAIState == AIState.Wander)
			{
				TriggerUniqueIdle(0.2f);
			}
		}

		private void TriggerUniqueIdle(float chance = 1f)
		{
			if (UnityEngine.Random.Range(0, 1000000) <= frameCount++ && uniqueIdleAnimations.Length != 0)
			{
				if (Pathing())
				{
					StopPathing();
				}
				animator.SetBool("IsUniqueIdle", value: true);
				SetAIState(AIState.UniqueIdle);
				frameCount = 0;
				CharacterVitals characterVitals = myVitals;
				characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Combine(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(base.CancelUniqueIdle));
			}
		}

		protected override void RespondToAttack(CharacterVitals.Damage attacker)
		{
			if (!Alive() || GetAIState() == AIState.ReturningToTown || attacker.source == null || attacker.source == this || GetAIState() == AIState.Flee)
			{
				return;
			}
			if (GetAIState() == AIState.UniqueIdle)
			{
				CancelUniqueIdle();
			}
			if (MaxHP() > 0 && hp / (float)MaxHP() < 1f - monsterData.bravery && UnityEngine.Random.Range(0, 100) < 50)
			{
				SetAIState(AIState.Flee);
			}
			else if (IsPetNearDeath())
			{
				SetAIState(AIState.Flee);
			}
			else
			{
				if (!attacker.source.Char.Alive() || attacker.source.Char.GetAlignment() == GetAlignment() || attacker.source.Char.GetAlignment() == Alignment.Neutral)
				{
					return;
				}
				if (Target() == null)
				{
					if (!PerformingCast() && attacker.source.Char.Alive())
					{
						SetAIState(AIState.Hunt);
						if (attacker.source.Char.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							SetTarget(attacker.source.Char.Master());
						}
						else
						{
							SetTarget(attacker.source.Char);
						}
					}
				}
				else
				{
					if (PerformingAttack() || PerformingCast())
					{
						return;
					}
					if (UnityEngine.Random.Range(0, 1000) < 50)
					{
						SetAIState(AIState.Attack);
						if (attacker.source.Char.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							SetTarget(attacker.source.Char.Master());
						}
						else
						{
							SetTarget(attacker.source.Char);
						}
					}
					else if (GetAIState() == AIState.Inactive || GetAIState() == AIState.Wander)
					{
						SetAIState(AIState.Attack);
						if (attacker.source.Char.HasMaster() && UnityEngine.Random.Range(0, 100) < 10)
						{
							SetTarget(attacker.source.Char.Master());
						}
						else
						{
							SetTarget(attacker.source.Char);
						}
					}
				}
			}
		}
	}
