	public class Player : Character
	{
		private const int SecondsForCurseProc = 60;

		public static bool isComingFromMenu;

		public static bool isEnteringDungeonFromTownDoor;

		public static bool latestStairsUsedWasDown;

		public static Player PlayerChar;

		[SerializeField]
		private CharacterCustomizationDefaults charCustom;

		[SerializeField]
		private FishingPole fishingPole;

		[SerializeField]
		private GameObject fishingFeedback;

		[SerializeField]
		private Texture2D defaultProfilePicture;

		[SerializeField]
		private LayerMask rangedHitLayerMask;

		[SerializeField]
		private LineRenderer backupRangedWeaponLineRenderer;

		public float debugDamageMult = 1f;

		public GameObject petMinimapIcon;

		public ParticleSystem levelupParticle;

		private bool intendsToRun;

		private bool killTimeActive;

		private bool fastestKill;

		private bool isUniqueIdlePlaying;

		private bool canPlayAttackSound = true;

		private bool hasInitialized;

		private float stepCooldown = 0.22f;

		private float lastStep = -1f;

		private int curseTimer;

		private float cursePct;

		private Coroutine uniqueIdleCoroutine;

		private ProdigyAgentLocomotion prodigyLocomotion;

		private Texture2D profilePicture;

		private AttackData playerUnarmedAttack;

		private Dictionary<Character, GameObject> petsMinimapIcons;

		private RaycastHit[] autoAimHits = new RaycastHit[8];

		public Action onPartyChanged;

		public Action onSummonsChanged;

		public new Action onEquipmentChanged;

		public Action<Texture2D> onProfilePictureChanged;

		public Texture2D GetProfilePicture
		{
			get
			{
				if (!(profilePicture != null))
				{
					return defaultProfilePicture;
				}
				return profilePicture;
			}
		}

		public bool IntendsToRun => intendsToRun;

		public override bool IsPlayerOwnedInventory => true;

		public List<SpellData> ActiveSpellWheel { get; private set; }

		public Character ShiftLootTarget { get; set; }

		public DroppedItem DroppedItemInRange { get; set; }

		public MerchantInteractable MerchantInRange { get; set; }

		private IEnumerator TimeCounter()
		{
			WaitForSeconds wait = new WaitForSeconds(1f);
			while (base.gameObject.activeInHierarchy)
			{
				yield return wait;
				StatsManager.IncrementStat(Stat.SecondsPlayed);
				SaveData.CurrentSaveSlot.secondsPlayed++;
			}
		}

		private IEnumerator CurseCounter()
		{
			while (!SingletonBehaviour<QuestManager>.Instance.HasLoaded)
			{
				yield return null;
			}
			if (!SingletonBehaviour<QuestManager>.Instance.IsInCursedLevel())
			{
				yield break;
			}
			WaitForSeconds wait = new WaitForSeconds(1f);
			WaitForSeconds curseCooldown = new WaitForSeconds(300f);
			while (base.gameObject.activeInHierarchy)
			{
				yield return wait;
				curseTimer++;
				if (curseTimer < 15)
				{
					cursePct += 0.001f;
				}
				else if (curseTimer < 30)
				{
					cursePct += 0.01f;
				}
				else
				{
					cursePct += 0.1f;
				}
				if (!(cursePct > 90f))
				{
					continue;
				}
				if (SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.PreCurse, out var key))
				{
					SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(I2Loca.Get(key));
				}
				if (cursePct > 100f)
				{
					cursePct = 0f;
					ResetCurseTimer();
					SingletonBehaviour<QuestManager>.Instance.ProcCurse();
					if (SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.Curse, out var key2))
					{
						SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(I2Loca.Get(key2));
					}
					yield return curseCooldown;
				}
			}
		}

		private void ResetCurseTimer()
		{
			curseTimer = 0;
		}

		public override bool IsPlayer()
		{
			return true;
		}

		private void Awake()
		{
			prodigyLocomotion = GetComponent<ProdigyAgentLocomotion>();
			ActiveSpellWheel = new List<SpellData>();
			Init();
			StartCoroutine(TimeCounter());
			if (Fate.CurrentFateVer == Fate.FateVer.CursedKing)
			{
				StartCoroutine(CurseCounter());
			}
			OnLevelUp = (Action<int>)Delegate.Combine(OnLevelUp, (Action<int>)delegate
			{
				levelupParticle.Play();
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.Heartbeat);
				isHeartBeatPlaying = false;
			});
			OnFameRankUp = (Action<int>)Delegate.Combine(OnFameRankUp, (Action<int>)delegate
			{
				levelupParticle.Play();
			});
			if (TryGetComponent<ProfilePictureCamera>(out var component))
			{
				ProfilePictureCamera profilePictureCamera = component;
				profilePictureCamera.onPictureTaken = (Action<Texture2D>)Delegate.Combine(profilePictureCamera.onPictureTaken, new Action<Texture2D>(SetProfilePicture));
			}
			onEquipmentChanged = (Action)Delegate.Combine(onEquipmentChanged, new Action(UpdateProfilePicture));
			UpdateProfilePicture();
		}

		private void Start()
		{
			if (!isComingFromMenu)
			{
				return;
			}
			PlayerSaveData playerSaveData = SaveData.CurrentSaveData?.playerSaveData;
			if (playerSaveData != null)
			{
				if (playerSaveData.posInLastScene != Vector3.zero)
				{
					TeleportToPosition(playerSaveData.posInLastScene);
				}
				if (playerSaveData.rotInLastScene != Vector3.zero)
				{
					myTransform.rotation = Quaternion.Euler(playerSaveData.rotInLastScene);
				}
				isComingFromMenu = false;
			}
		}

		public override void Init()
		{
			base.Init();
			partyCharacters = new List<Character>();
			petsMinimapIcons = new Dictionary<Character, GameObject>();
			alignment = Alignment.Good;
			PlayerChar = this;
			base.CharacterName = SaveData.CurrentSaveData.playerSaveData.PlayerName;
			killTimeActive = false;
			fastestKill = false;
			toHitBonus = 20;
			naturalArmor = 10;
			playerUnarmedAttack = new AttackData
			{
				animIndex = 0,
				animKey = "PUNCH",
				attackRadius = 8f,
				damageRange = new Range
				{
					Min = 1f,
					Max = 2f
				},
				damageType = DamageType.Crushing,
				speed = Fate.AttackSpeedValues[Speed.Fastest],
				strikeRadius = 10f
			};
			SaveData.AddPreSaveMainThreadTask(FlushPlayerSave);
			CharacterVitals characterVitals = myVitals;
			characterVitals.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Combine(characterVitals.OnKilled, (Action<CharacterVitals.Damage>)delegate
			{
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_die);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.MaleDeath, randomizePitch: true);
				StatsManager.IncrementStat(Stat.Deaths);
				Die();
			});
			CharacterVitals characterVitals2 = myVitals;
			characterVitals2.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Combine(characterVitals2.OnDamaged, new Action<CharacterVitals.Damage>(RespondToAttack));
			InitSpawnPet();
			InitSpawnSummons();
			InitSpawnPartyMembers();
			if (lineage != 0 && StatsManager.GetStat(Stat.DescendantsCreated) == 0)
			{
				StatsManager.IncrementStat(Stat.DescendantsCreated);
			}
			if (LevelGenerator.currentInstance == null)
			{
				switch (SingletonBehaviour<Town>.Instance.RealmId)
				{
				case RealmData.RealmId.Grove:
					SingletonBehaviour<Town>.Instance.stepSound = AudioData.AudioClipName.BasicStep;
					break;
				case RealmData.RealmId.Druantia:
					SingletonBehaviour<Town>.Instance.stepSound = AudioData.AudioClipName.StepDruantiaMoss;
					break;
				case RealmData.RealmId.Typhon:
					SingletonBehaviour<Town>.Instance.stepSound = AudioData.AudioClipName.StepTyphonSnow;
					break;
				case RealmData.RealmId.TempleOfFate:
					SingletonBehaviour<Town>.Instance.stepSound = AudioData.AudioClipName.StepTyphonBasement;
					break;
				case RealmData.RealmId.Ekbatan:
					SingletonBehaviour<Town>.Instance.stepSound = AudioData.AudioClipName.BasicStep;
					break;
				case RealmData.RealmId.Prometheus:
					SingletonBehaviour<Town>.Instance.stepSound = AudioData.AudioClipName.StepTyphonCastle;
					break;
				default:
					SingletonBehaviour<Town>.Instance.stepSound = AudioData.AudioClipName.BasicStep;
					break;
				}
			}
			hasInitialized = true;
		}

		public override void Init(PlayerSaveData playerSaveData, ItemStorage itemStorage)
		{
			if (playerSaveData != null)
			{
				PlayerSaveData playerSaveData2 = SaveData.CurrentSaveData.playerSaveData;
				charCustom.SetGender(playerSaveData2.male);
				charCustom.SetRace(playerSaveData2.playerRace);
				charCustom.SetHair(playerSaveData2.hairIndex);
				charCustom.SetHead(playerSaveData2.headIndex);
			}
			else
			{
				charCustom.SetGender(male: true);
				charCustom.SetRace(Race.Human);
			}
			base.Init(playerSaveData, itemStorage);
			UnityEngine.Debug.Log("Player items ready");
			if (playerSaveData == null || playerSaveData.spellWheel == null)
			{
				return;
			}
			SpellData[] allSpells = SingletonBehaviour<FateDB>.Instance.allSpells;
			ActiveSpellWheel = new List<SpellData>();
			int i;
			for (i = 0; i < playerSaveData.spellWheel.Count; i++)
			{
				if (playerSaveData.spellWheel[i] == "NONE")
				{
					ActiveSpellWheel.Add(null);
					continue;
				}
				SpellData spellData = allSpells.Find((SpellData s) => s.spellName == playerSaveData.spellWheel[i]);
				if (spellData == null)
				{
					UnityEngine.Debug.LogError("Spell not found: " + playerSaveData.spellWheel[i]);
				}
				else if (!knownSpells.ContainsKey(spellData.sphereType) || !knownSpells[spellData.sphereType].Contains(spellData))
				{
					UnityEngine.Debug.LogError("Spell in SpellWheel not known: " + playerSaveData.spellWheel[i]);
				}
				else
				{
					ActiveSpellWheel.Add(spellData);
				}
			}
		}

		private void InitSpawnPet(bool hasConfirmedPet = false)
		{
			PlayerSaveData playerSaveData = SaveData.CurrentSaveData.playerSaveData;
			if (playerSaveData == null)
			{
				UnityEngine.Debug.LogError("Could not spawn pet, player save data is null");
				return;
			}
			string petId = playerSaveData.petMonsterId ?? "Pet_Cat";
			if (string.IsNullOrEmpty(petId))
			{
				petId = "Pet_Cat";
			}
			MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData x) => x.displayName == petId);
			if (monsterData == null)
			{
				return;
			}
			if (!hasConfirmedPet)
			{
				var (flag, dlc) = SingletonBehaviour<DLCManager>.Instance.IsDLCPet(monsterData);
				if (flag)
				{
					SingletonBehaviour<DLCManager>.Instance.HasEntitlement(dlc, delegate(bool hasEntitlement)
					{
						if (!hasEntitlement)
						{
							playerSaveData.PetOverrideId = "Pet_Terrier";
						}
						InitSpawnPet(hasConfirmedPet: true);
					});
					return;
				}
			}
			string overridePetId = playerSaveData.PetOverrideId;
			if (!string.IsNullOrEmpty(overridePetId))
			{
				monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData x) => x.displayName == overridePetId);
			}
			Character component = UnityEngine.Object.Instantiate(monsterData.modelPrefab, GetClosePosition(myTransform.position, 0.35f, 2f, 100), myTransform.rotation).GetComponent<Character>();
			component.SetMasterCharacter(this);
			component.monsterData = monsterData;
			component.Init();
			component.CharacterName = playerSaveData.petName;
			component.InitSpells(playerSaveData.petSpellsKnown, playerSaveData.petActiveSpell);
			ItemStorage petItemSave = SaveData.CurrentSaveData.petItemSaveData;
			if (petItemSave != null && petItemSave.items != null)
			{
				List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
				int i = 0;
				while (i < petItemSave.items.Count)
				{
					ItemSaveData itemSaveData = petItemSave.items[i];
					ItemData itemData = allItems.Find((ItemData a) => a.displayName == petItemSave.items[i].baseName);
					if (itemData == null)
					{
						UnityEngine.Debug.LogError("Unable to find item info: " + petItemSave.items[i].baseName);
					}
					else
					{
						Item item = new Item(itemData);
						item.ApplyInstance(petItemSave.items[i]);
						component.AddItemToInventory(item, AddItemReason.LoadFromSave, itemSaveData.slotIndex);
					}
					int num = i + 1;
					i = num;
				}
			}
			AddPet(component);
			component.AwardBigExperience(playerSaveData.petExperience, fromMaster: true, isLoadSave: true);
			string petTransformId = playerSaveData.petTransformId;
			if (!string.IsNullOrEmpty(petTransformId) && petId != petTransformId)
			{
				component.Transform(petTransformId, playerSaveData.petTransformTimeLeft, isLoad: true);
			}
			component = GetPet();
			component.InitSentToTownState(playerSaveData.petSentToTown, playerSaveData.petSecondsLeftInTown);
			if (playerSaveData.petFleeing)
			{
				component.hp = 0f;
			}
			else if (playerSaveData.petHealth > 0f)
			{
				component.hp = Mathf.Min(playerSaveData.petHealth, component.MaxHP());
			}
			ShiftLootTarget = component;
		}

		private void InitSpawnPartyMembers()
		{
			if (SaveData.CurrentSaveData.partySaveDatas == null)
			{
				return;
			}
			foreach (PartyMemberSaveData partySaveData in SaveData.CurrentSaveData.partySaveDatas)
			{
				SummonPartyMember(partySaveData.playerSaveData, partySaveData.itemStorage, partySaveData.uniqueSaveId, partySaveData.tacticsMode);
			}
		}

		private void InitSpawnSummons()
		{
			if (SaveData.CurrentSaveData.summonSaveData == null || SaveData.CurrentSaveData.summonSaveData.summons == null)
			{
				return;
			}
			string summonKey;
			foreach (SummonSaveData summon in SaveData.CurrentSaveData.summonSaveData.summons)
			{
				summonKey = summon.summonId;
				MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData x) => x.displayName == summonKey);
				if (!(monsterData == null))
				{
					Vector3 closePosition = GetClosePosition(myTransform.position, 0.35f, 3f, 30);
					GameObject obj = UnityEngine.Object.Instantiate(monsterData.modelPrefab, closePosition, myTransform.rotation);
					obj.layer = LayerMask.NameToLayer("Player");
					Character component = obj.GetComponent<Character>();
					component.monsterData = monsterData;
					component.Init();
					component.TweakToLevel(summon.level);
					component.GiveEquipment();
					component.allowDropInventory = false;
					string characterName = component.CharacterName;
					if (int.TryParse(characterName[characterName.Length - 1].ToString(), out var _))
					{
						component.CharacterName = component.CharacterName.Substring(0, component.CharacterName.LastIndexOf('_'));
					}
					component.SetLifeDuration(summon.lifeDuration);
					component.hp = summon.health;
					component.SetPositionProper(closePosition);
					component.UpdateGroundMarker(component.GetAlignment());
					AddPet(component);
				}
			}
		}

		public Vector3 GetClosePosition(Vector3 targetPosition, float minDistance, float radius, int attempts)
		{
			Vector3 vector = targetPosition + new Vector3(UnityEngine.Random.Range(0f - radius, radius), 0f, UnityEngine.Random.Range(0f - radius, radius));
			NavMeshHit hit;
			bool flag = NavMesh.SamplePosition(vector, out hit, 1f, 1);
			while (!flag && --attempts > 0)
			{
				vector = targetPosition + new Vector3(UnityEngine.Random.Range(0f - radius, radius), 0f, UnityEngine.Random.Range(0f - radius, radius));
				flag = NavMesh.SamplePosition(vector, out hit, 1f, 1);
				if (flag && Vector3.Distance(vector, targetPosition) < minDistance)
				{
					flag = false;
				}
			}
			if (!flag)
			{
				UnityEngine.Debug.Log("No open positions found, defaulting position to player");
				vector = myTransform.position;
			}
			return vector;
		}

