		public override void AddPet(Character pet)
		{
			base.AddPet(pet);
			OnPetAdded(pet);
		}

		public override void AddPetAtIndex(Character pet, int index)
		{
			if (pet == null)
			{
				UnityEngine.Debug.LogError("Tried to add pet to " + base.CharacterName + ", but the pet was null.");
			}
			else if (!HasPet(pet))
			{
				petCharacters.Insert(index, pet);
				pet.SetMasterCharacter(this);
				OnPetAdded(pet);
			}
		}

		private void OnPetAdded(Character pet)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(petMinimapIcon, pet.transform);
			gameObject.transform.localScale *= pet.transform.localScale.x;
			petsMinimapIcons.Add(pet, gameObject);
			pet.UpdateNavmeshAvoidance();
			pet.SetMinimapIcon(gameObject);
			if (pet.IsSummoned())
			{
				onSummonsChanged?.Invoke();
			}
		}

		public override void RemovePet(Character pet)
		{
			base.RemovePet(pet);
			if (petsMinimapIcons.ContainsKey(pet))
			{
				UnityEngine.Object.Destroy(petsMinimapIcons[pet]);
				petsMinimapIcons.Remove(pet);
			}
			if (pet.IsSummoned())
			{
				onSummonsChanged?.Invoke();
			}
		}

		public void HidePlayersPetsAndPartyMembers(bool aBoolean)
		{
			foreach (Character petCharacter in petCharacters)
			{
				petCharacter.gameObject.SetActive(aBoolean);
			}
			if (partyCharacters == null)
			{
				return;
			}
			foreach (Character partyCharacter in partyCharacters)
			{
				partyCharacter.gameObject.SetActive(aBoolean);
			}
		}

		public override void AddSpell(SpellData spell)
		{
			base.AddSpell(spell);
			for (int i = 0; i < ActiveSpellWheel.Count; i++)
			{
				if (ActiveSpellWheel[i] == null)
				{
					ActiveSpellWheel[i] = spell;
					return;
				}
			}
			if (ActiveSpellWheel.Count < 6)
			{
				ActiveSpellWheel.Add(spell);
			}
		}

		public override void RemoveSpell(SpellData spell)
		{
			base.RemoveSpell(spell);
			int num = ActiveSpellWheel.FindIndex((SpellData sp) => sp == spell);
			if (num != -1)
			{
				if (num == ActiveSpellWheel.Count - 1)
				{
					ActiveSpellWheel.RemoveAt(num);
				}
				else
				{
					ActiveSpellWheel[num] = null;
				}
			}
		}

		public void SetSpellWheelSpell(int slot, SpellData spell)
		{
			for (int i = ActiveSpellWheel.Count; i <= slot; i++)
			{
				ActiveSpellWheel.Add(null);
			}
			ActiveSpellWheel[slot] = spell;
			ResetCurseTimer();
		}

		public bool InAttackRange(GameObject target)
		{
			if (target == null)
			{
				return false;
			}
			bool result = true;
			bool num = currentAttack != null;
			if (!num)
			{
				SelectAttack();
			}
			if (target != null)
			{
				float distanceToTarget = GetDistanceToTarget(target);
				float num2 = target.transform.localScale.magnitude * 0.25f;
				if (num2 < 0f)
				{
					num2 = 0f;
				}
				distanceToTarget -= num2;
				float num3 = myTransform.localScale.magnitude * 0.25f;
				if (num3 < 0f)
				{
					num3 = 0f;
				}
				distanceToTarget -= num3;
				if (currentAttack != null)
				{
					float num4 = currentAttack.attackRadius * 0.25f;
					if (currentAttack.attackRadius < 20f)
					{
						num4 *= 0.1f;
					}
					if (distanceToTarget > num4)
					{
						result = false;
					}
				}
				else
				{
					result = false;
				}
			}
			if (!num)
			{
				base.attackTimer = 0f;
				currentAttack = null;
			}
			return result;
		}

		protected override AttackData UnarmedAttack(int index)
		{
			if (index != 0)
			{
				return null;
			}
			return playerUnarmedAttack;
		}

		public void StartAttack()
		{
			animator.SetFloat("MoveMag", 0f);
			animator.SetBool(GameSettings.Instance.AnimParamIsAttacking, value: true);
			if (base.activeWeapon != null && canPlayAttackSound)
			{
				canPlayAttackSound = false;
				base.activeWeapon.PlayAttackSound();
			}
			ResetPlayerUniqueIdle();
			ResetCurseTimer();
		}

		public void AttackDone()
		{
			animator.speed = 1f;
			animator.SetFloat("MoveMag", 0f);
			animator.SetBool("IsCasting", value: false);
		}

		public override void SelectAttack()
		{
			if (!PerformingCast() && !PerformingAttack())
			{
				currentAttack = null;
				if (base.activeWeapon != null)
				{
					currentAttack = new AttackData(base.activeWeapon, base.activeWeapon.IsInMainHand);
				}
				else
				{
					currentAttack = playerUnarmedAttack;
				}
				float num = 1f;
				num += EffectValue(EffectType.PercentAttackSpeed) / 100f;
				num *= currentAttack.speed;
				if (num < 0.2f)
				{
					num = 0.2f;
				}
				base.attackTimer = num;
				reachedStrikePoint = false;
			}
		}

		public void AttackFrameReached()
		{
			ResetCurseTimer();
			if (base.castTimer > 0f)
			{
				base.castTimer = 0f;
				reachedCastPoint = true;
				CompleteSpell(castingTargetPosition, castingTargetDirection, castingCharacterTraget, null, activeRageSpell);
				StatsManager.IncrementStat(Stat.SpellsCast);
				animator.SetBool("IsAttacking", value: false);
				animator.SetBool("IsCasting", value: false);
				return;
			}
			if (currentAttack == null && Alive())
			{
				UnityEngine.Debug.LogWarning("AttackFrameReached called and current attack is null");
			}
			if (base.attackTimer > 0f && !reachedStrikePoint)
			{
				PerformHitSweep();
				SwapDualWieldWeaponHand();
				base.attackTimer = 0f;
				reachedStrikePoint = true;
				currentAttack = null;
				canPlayAttackSound = true;
			}
			animator.SetBool("IsAttacking", value: false);
		}

		private void PerformHitSweep()
		{
			if (currentAttack == null)
			{
				UnityEngine.Debug.LogWarning("Player: Current attack was null when performing hit sweep");
			}
			else
			{
				if (activeRageSpell != null || base.castTimer > 0f)
				{
					return;
				}
				if (base.activeWeapon == null || base.activeWeapon.IsMelee)
				{
					float num = currentAttack.strikeRadius * 0.25f * 1.5f;
					if (num > 3.5f)
					{
						num = 3.5f;
					}
					RaycastHit[] array = Targetter.ConeSweepAll(myTransform.position, myTransform.forward, GameSettings.Instance.MeleeHitMask, num, num, 60f, ScanSorting.Undefined, debug: true, 0.3f);
					new Vector3(currentAttack.GetDamage(), 0f, 0f);
					List<CharacterVitals> list = new List<CharacterVitals>();
					for (int i = 0; i < array.Length; i++)
					{
						RaycastHit raycastHit = array[i];
						CharacterVitals component = raycastHit.transform.GetComponent<CharacterVitals>();
						if (component != null)
						{
							list.Add(component);
						}
						if (component == null && raycastHit.transform.TryGetComponent<ContainerDestroyable>(out var component2))
						{
							component2.Destroyed();
						}
					}
					Collider[] array2 = Physics.OverlapSphere(myTransform.position, 0.3f, GameSettings.Instance.MeleeHitMask);
					if (array2 != null)
					{
						Collider[] array3 = array2;
						for (int j = 0; j < array3.Length; j++)
						{
							if (array3[j].transform.TryGetComponent<CharacterVitals>(out var component3) && !list.Contains(component3))
							{
								list.Add(component3);
							}
						}
					}
					{
						foreach (CharacterVitals item in list)
						{
							if (!(item == null) && item.Alignment != GetAlignment())
							{
								bool num2 = RollAttack(item.Char);
								if (!num2)
								{
									SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.AttackMiss, randomizePitch: true);
								}
								if (num2 && base.activeWeapon != null)
								{
									base.activeWeapon.PlayStrikeSound();
								}
								if (num2 && base.activeWeapon == null)
								{
									SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.LightFlesh, randomizePitch: true);
								}
							}
						}
						return;
					}
				}
				if (base.activeWeapon == null || (base.activeWeapon.itemType != ItemType.Bow && base.activeWeapon.itemType != ItemType.Crossbow))
				{
					return;
				}
				EquipmentHandle equipmentHandle = ((leftWeaponHandle != null && leftWeaponHandle.CurrentEquipment != null) ? leftWeaponHandle : ((rightWeaponHandle != null && rightWeaponHandle.CurrentEquipment != null) ? rightWeaponHandle : null));
				if (equipmentHandle != null)
				{
					if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free && Physics.SphereCastNonAlloc(myTransform.position + myTransform.forward * 2f, 2f, myTransform.forward, autoAimHits, base.activeWeapon.strikeRadius * 0.25f, rangedHitLayerMask) > 0 && autoAimHits != null)
					{
						float num3 = float.MaxValue;
						Transform transform = null;
						RaycastHit[] array4 = autoAimHits;
						for (int j = 0; j < array4.Length; j++)
						{
							RaycastHit raycastHit2 = array4[j];
							if (!(raycastHit2.collider == null) && (!raycastHit2.transform.TryGetComponent<ContainerDestroyable>(out var component4) || !component4.IsDestroyed) && (!raycastHit2.transform.TryGetComponent<Character>(out var component5) || component5.Alive()))
							{
								float distance = raycastHit2.distance;
								if (component4 == null && component5 == null && distance < num3)
								{
									num3 = distance;
									transform = null;
								}
								else if (distance < num3)
								{
									num3 = distance;
									transform = raycastHit2.transform;
								}
							}
						}
						if (transform != null)
						{
							myTransform.forward = (transform.position - myTransform.position).WithY(0f).normalized;
						}
					}
					Vector3 vector = myTransform.position + myTransform.forward * 0.4f + Vector3.up * 0.8f;
					Vector3? vector2 = null;
					bool flag = false;
					Vector3 normalized = myTransform.forward.normalized;
					SetTarget(null, resetAttackSpeed: false);
					if (Physics.Raycast(vector, normalized, out var hitInfo, base.activeWeapon.strikeRadius * 0.25f, rangedHitLayerMask))
					{
						ContainerDestroyable component7;
						if (hitInfo.collider.gameObject.TryGetComponent<Character>(out var component6))
						{
							SetTarget(component6);
						}
						else if (hitInfo.collider.gameObject.TryGetComponent<ContainerDestroyable>(out component7))
						{
							component7.Destroyed();
						}
						else
						{
							flag = true;
						}
						vector2 = hitInfo.point;
					}
					Collider[] array5 = Physics.OverlapSphere(myTransform.position, 0.3f, GameSettings.Instance.MeleeHitMask);
					if (array5 != null)
					{
						Collider[] array3 = array5;
						foreach (Collider collider in array3)
						{
							if (collider.transform.TryGetComponent<Character>(out var component8))
							{
								SetTarget(component8);
								vector2 = component8.myTransform.position;
								flag = false;
							}
							if (component8 == null && collider.transform.TryGetComponent<ContainerDestroyable>(out var component9))
							{
								component9.Destroyed();
							}
						}
					}
					bool flag2 = true;
					if (Target() != null && Target().GetAlignment() != GetAlignment())
					{
						bool flag3 = false;
						if (!flag)
						{
							flag2 = RollAttack(Target());
							if (flag2)
							{
								flag3 = true;
							}
						}
						if (flag3 && !flag)
						{
							base.activeWeapon.PlayStrikeSound();
						}
						else
						{
							SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.AttackMiss, randomizePitch: true);
						}
					}
					LineRenderer component10 = equipmentHandle.CurrentEquipment.GetComponent<LineRenderer>();
					if (component10 == null)
					{
						UnityEngine.Debug.LogWarning("Ranged weapon '" + base.activeWeapon.itemName + "' has no line renderer. Using players own fallback.");
						component10 = backupRangedWeaponLineRenderer;
					}
					component10.positionCount = 2;
					Vector3 position = ((!vector2.HasValue) ? (vector + base.activeWeapon.strikeRadius * 0.25f * normalized) : ((!flag2) ? (vector + base.activeWeapon.strikeRadius * 0.25f * normalized + UnityEngine.Random.onUnitSphere) : vector2.Value));
					component10.enabled = true;
					component10.SetPosition(0, equipmentHandle.transform.position);
					component10.SetPosition(1, position);
					StartCoroutine(ArrowTrailFadeOut(component10));
				}
				else
				{
					UnityEngine.Debug.LogError("Weapon handle is null when performing hit sweep with a ranged weapon");
				}
			}
		}

		private void OnDestroy()
		{
			StopAllCoroutines();
			SaveData.RemovePreSaveMainThreadTask(FlushPlayerSave);
			CharacterVitals characterVitals = myVitals;
			characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(RespondToAttack));
			for (int i = 0; i < petCharacters.Count; i++)
			{
				if (!(petCharacters[i] == null) && !(petCharacters[i].gameObject == null))
				{
					UnityEngine.Object.Destroy(petCharacters[i].gameObject);
				}
			}
			petCharacters.Clear();
			for (int j = 0; j < partyCharacters.Count; j++)
			{
				Character character = partyCharacters[j];
				if (!(character == null) && !(character.gameObject == null))
				{
					UnityEngine.Object.Destroy(character.gameObject);
				}
			}
			partyCharacters.Clear();
		}

		private IEnumerator KillTime(float time)
		{
			killTimeActive = true;
			fastestKill = true;
			yield return new WaitForSeconds(0.5f);
			fastestKill = false;
			yield return new WaitForSeconds(time - 0.5f);
			killTimeActive = false;
		}

		public void KilledEnemy()
		{
			if (!killTimeActive)
			{
				StartCoroutine(KillTime(10f));
				StatsManager.SetStat(Stat.FastestFiveKills, 1);
				StatsManager.SetStat(Stat.FastestTenKills, 1);
			}
			else
			{
				if (fastestKill)
				{
					StatsManager.IncrementStat(Stat.FastestFiveKills);
				}
				StatsManager.IncrementStat(Stat.FastestTenKills);
			}
			StatsManager.IncrementStat(Stat.EnemiesDefeated);
		}

		public void ForceFlushSave()
		{
			FlushPlayerSave(SaveData.CurrentSaveData);
		}

		private void FlushPlayerSave(FateSaveData saveData)
		{
			if (SaveData.CurrentSaveSlot.saveState != 0 || !SingletonBehaviour<PlayerStatus>.InstanceExists())
			{
				return;
			}
			if (saveData.playerSaveData == null)
			{
				saveData.playerSaveData = new PlayerSaveData();
			}
			SingletonBehaviour<PlayerStatus>.Instance.PreSave(saveData);
			FillPlayerSaveData(ref saveData.playerSaveData);
			PlayerSaveData playerSaveData = saveData.playerSaveData;
			playerSaveData.lastScene = SceneLoad.CurrentScene;
			playerSaveData.lastDungeonRealm = SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm;
			playerSaveData.posInLastScene = myTransform.position;
			playerSaveData.rotInLastScene = myTransform.rotation.eulerAngles;
			playerSaveData.intendsToRun = intendsToRun;
			playerSaveData.lineage = lineage;
			playerSaveData.activeWeaponSet = activeWeaponSet;
			if (petCharacters != null && petCharacters.Count > 0)
			{
				Character character = petCharacters[0];
				playerSaveData.petSpellsKnown = new List<string>();
				playerSaveData.petExperience = character.experience;
				playerSaveData.petActiveSpell = ((character.activeSpell != null) ? character.activeSpell.spellName : null);
				foreach (KeyValuePair<SpellSphere, List<SpellData>> knownSpell in character.knownSpells)
				{
					for (int i = 0; i < knownSpell.Value.Count; i++)
					{
						playerSaveData.petSpellsKnown.Add(knownSpell.Value[i].spellName);
					}
				}
				if (character.inventory != null)
				{
					saveData.petItemSaveData = new ItemStorage
					{
						items = new List<ItemSaveData>()
					};
					for (int j = 0; j < character.inventory.Count; j++)
					{
						ItemSaveData itemSaveData = new ItemSaveData();
						character.inventory[j].FillInstance(itemSaveData);
						saveData.petItemSaveData.items.Add(itemSaveData);
					}
				}
				playerSaveData.petTransformId = character.transformId;
				bool flag = false;
				List<AppliedEffect> list = character.GetEffects();
				if (list != null)
				{
					foreach (AppliedEffect item in list)
					{
						if (item.BuffType == EffectType.Transform)
						{
							playerSaveData.petTransformTimeLeft = item.duration;
							flag = true;
							break;
						}
					}
				}
				if (!flag)
				{
					playerSaveData.petTransformTimeLeft = -1000;
				}
				AIState aIState = character.GetAIState();
				playerSaveData.petSentToTown = aIState == AIState.ReturningToTown || aIState == AIState.InTown;
				playerSaveData.petSecondsLeftInTown = Mathf.RoundToInt(character.townTimer);
				playerSaveData.petHealth = character.hp;
				playerSaveData.petFleeing = character.GetAIState() == AIState.Flee;
				saveData.summonSaveData = new SummonStorage
				{
					summons = new List<SummonSaveData>()
				};
				foreach (Character petCharacter in petCharacters)
				{
					if (petCharacter.IsSummoned() && petCharacter.Alive())
					{
						saveData.summonSaveData.summons.Add(new SummonSaveData
						{
							summonId = petCharacter.monsterData.displayName,
							level = petCharacter.Level,
							health = petCharacter.HP(),
							lifeDuration = petCharacter.GetLifeDuration()
						});
					}
				}
			}
			if (partyCharacters != null)
			{
				saveData.partySaveDatas = new List<PartyMemberSaveData>();
				foreach (Character partyCharacter in partyCharacters)
				{
					PartyMember partyMember = partyCharacter as PartyMember;
					PartyMemberSaveData partyMemberSaveData = new PartyMemberSaveData();
					partyMemberSaveData.uniqueSaveId = partyMember.saveUniqueId;
					partyMemberSaveData.tacticsMode = partyMember.CurrentTactics;
					partyMemberSaveData.playerSaveData = new PlayerSaveData();
					partyMemberSaveData.playerSaveData.playerName = partyMember.playerName;
					partyMemberSaveData.playerSaveData.playerRace = partyMember.Race;
					partyMemberSaveData.playerSaveData.hairIndex = partyMember.hairIndex;
					partyMemberSaveData.playerSaveData.headIndex = partyMember.headIndex;
					partyMember.FillPlayerSaveData(ref partyMemberSaveData.playerSaveData);
					partyMemberSaveData.itemStorage = new ItemStorage();
					partyMemberSaveData.itemStorage.items = new List<ItemSaveData>();
					foreach (Item item2 in partyMember.inventory)
					{
						ItemSaveData itemSaveData2 = new ItemSaveData();
						item2.FillInstance(itemSaveData2);
						partyMemberSaveData.itemStorage.items.Add(itemSaveData2);
					}
					saveData.partySaveDatas.Add(partyMemberSaveData);
				}
			}
			saveData.itemSaveData = new ItemStorage
			{
				items = new List<ItemSaveData>()
			};
			for (int k = 0; k < inventory.Count; k++)
			{
				ItemSaveData itemSaveData3 = new ItemSaveData();
				inventory[k].FillInstance(itemSaveData3);
				saveData.itemSaveData.items.Add(itemSaveData3);
			}
			if (ActiveSpellWheel.Count > 0)
			{
				playerSaveData.spellWheel = new List<string>();
				for (int l = 0; l < ActiveSpellWheel.Count; l++)
				{
					playerSaveData.spellWheel.Add((ActiveSpellWheel[l] == null) ? "NONE" : ActiveSpellWheel[l].spellName);
				}
			}
		}

		public override void EquipItem(Item item, WeaponSet weaponSet)
		{
			base.EquipItem(item, weaponSet);
			switch (item.itemType)
			{
			case ItemType.Helmet:
				charCustom.SetHelmet(item.itemData.displayName);
				break;
			case ItemType.Gloves:
				charCustom.SetGloves(item.itemData.displayName);
				break;
			case ItemType.Boots:
				charCustom.SetBoots(item.itemData.displayName);
				break;
			case ItemType.Shirt:
				charCustom.SetUpper(item.itemData.displayName);
				break;
			case ItemType.Back:
				charCustom.SetBack(item.itemData.displayName);
				break;
			}
			ResetCurseTimer();
			onEquipmentChanged?.Invoke();
		}

		public override void UnequipItem(Item item)
		{
			base.UnequipItem(item);
			switch (item.itemType)
			{
			case ItemType.Helmet:
				charCustom.SetHelmet(null);
				break;
			case ItemType.Gloves:
				charCustom.SetGloves(null);
				break;
			case ItemType.Boots:
				charCustom.SetBoots(null);
				break;
			case ItemType.Shirt:
				charCustom.SetUpper(null);
				break;
			case ItemType.Back:
				charCustom.SetBack(null);
				break;
			}
			ResetCurseTimer();
			onEquipmentChanged?.Invoke();
		}

		private void OnStep(string anim)
		{
			float minVolume;
			float maxVolume;
			if (PlayerChar.running)
			{
				minVolume = 0.3f;
				maxVolume = 0.5f;
			}
			else
			{
				minVolume = 0.15f;
				maxVolume = 0.25f;
			}
			if (!(Time.realtimeSinceStartup > lastStep + stepCooldown))
			{
				return;
			}
			lastStep = Time.realtimeSinceStartup;
			StatsManager.IncrementStat(Stat.StepsTaken);
			ResetCurseTimer();
			if (LevelGenerator.currentInstance == null)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(SingletonBehaviour<Town>.Instance.stepSound, minVolume, maxVolume, randomizePitch: true);
				if (animator.GetFloat("MoveMag") <= 0f)
				{
					SingletonBehaviour<AudioManager>.Instance.StopAudioClip(SingletonBehaviour<Town>.Instance.stepSound);
				}
			}
			else
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(LevelGenerator.currentInstance.ActiveStepSound, minVolume, maxVolume, randomizePitch: true);
				if (animator.GetFloat("MoveMag") <= 0f)
				{
					SingletonBehaviour<AudioManager>.Instance.StopAudioClip(LevelGenerator.currentInstance.ActiveStepSound);
				}
			}
		}

		public bool TryBuyItem(Character merchant, Item item, MerchantType merchantType, int desiredSlot = -1)
		{
			uint purchaseValueByMerchant = item.GetPurchaseValueByMerchant(merchantType);
			if (!SingletonBehaviour<PlayerStatus>.Instance.CanAfford(purchaseValueByMerchant))
			{
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_lowgold);
				return false;
			}
			merchant.ReleaseInventorySlotsForItem(item);
			if (!AddItemToInventory(item, AddItemReason.Loot, desiredSlot, desiredSlotIsGlobal: true))
			{
				merchant.ReserveInventorySlotsForItem(item);
				return false;
			}
			merchant.RemoveItemFromInventory(item, RemoveItemReason.Sell, releaseFromGrid: false);
			SingletonBehaviour<PlayerStatus>.Instance.RemoveGold(purchaseValueByMerchant);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.CoinPickup, randomizePitch: true);
			if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.ActiveMerchantType == MerchantType.Gambler)
			{
				StatsManager.IncrementStat(Stat.Gambles);
			}
			if (!item.Identified && merchantType == MerchantType.Gambler)
			{
				item.SetIdentified(newValue: true);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Identify, randomizePitch: true);
			}
			return true;
		}

		public bool TrySellItem(Item item)
		{
			if (item.itemData.notSellable || item.itemType == ItemType.Tarot || item.IsHeroItem())
			{
				return false;
			}
			if (!inventory.Contains(item))
			{
				return false;
			}
			item.lockedForSelling = false;
			RemoveItemFromInventory(item, RemoveItemReason.Sell);
			SingletonBehaviour<PlayerStatus>.Instance.AddGold(item.SellValue());
			StatsManager.IncrementStat(Stat.ItemsSold);
			return true;
		}

		public bool TryMoveItem(Item item)
		{
			if (!inventory.Contains(item))
			{
				return false;
			}
			RemoveItemFromInventory(item, RemoveItemReason.Transfer);
			return true;
		}

		public override AppliedEffect AddEffect(EffectData effect, int sourceLevel, Character source, int itemSlotIndex = -1, bool isSpellEffect = false)
		{
			AppliedEffect appliedEffect = base.AddEffect(effect, sourceLevel, source, itemSlotIndex, isSpellEffect);
			if (appliedEffect.BuffType == EffectType.HPRecharge && !appliedEffect.Positive && appliedEffect.DamageType == DamageType.Poison)
			{
				onPoisoned?.Invoke(obj: true);
				poisoned = true;
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetPoisoned(poisoned: true);
				if (hasInitialized && !SingletonBehaviour<Narrator>.Instance.IsPlaying())
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_poison);
				}
			}
			return appliedEffect;
		}

		protected override void OnEffectRemoved(AppliedEffect effect)
		{
			base.OnEffectRemoved(effect);
			if (effect.BuffType == EffectType.HPRecharge && !effect.Positive && (effect.DamageType == DamageType.Poison || effect.DamageType == DamageType.Magic) && (!currentEffectValues.ContainsKey(EffectType.HPRecharge) || currentEffectValues[EffectType.HPRecharge] >= 0))
			{
				poisoned = false;
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetPoisoned(poisoned: false);
			}
		}

