		{
			return prodigyLocomotion.IsMoving;
		}

		public void Push(Vector3 direction, float strength)
		{
			prodigyLocomotion.Push(direction * strength);
		}

		protected override void Update()
		{
			if (UnityEngine.Debug.isDebugBuild && Input.GetKey(KeyCode.LeftControl) && Input.GetKey(KeyCode.LeftShift))
			{
				if (Input.GetKeyDown(KeyCode.Z))
				{
					isGod = !isGod;
					ThatHurt.PopText(base.transform.position, isGod ? "Godmode: On" : "Godmode: Off", 1f, ThatHurt.ThatHurtColor.White, 0f);
				}
				if (Input.GetKeyDown(KeyCode.X))
				{
					debugDamageMult = (Mathf.Approximately(debugDamageMult, 1f) ? 100f : 1f);
					ThatHurt.PopText(base.transform.position, "Damage Multiplier: " + debugDamageMult.ToString("n1"), 1f, ThatHurt.ThatHurtColor.White, 0f);
				}
				if (Input.GetKeyDown(KeyCode.W))
				{
					ModifyHP(0f - hp + 1f);
				}
				if (Input.GetKeyDown(KeyCode.Q))
				{
					GetPet().gameObject.SetActive(!GetPet().gameObject.activeInHierarchy);
				}
				if (Input.GetKeyDown(KeyCode.R))
				{
					Character pet = GetPet();
					pet.hp = (float)pet.MaxHP() * 0.2f;
				}
			}
			SetRunning(intendsToRun);
			UpdateStamina();
			KnockBackCheck();
			if (!SimpleSingletonBehaviour<PlayerUI>.Instance.IsFishing)
			{
				if (!PerformingAttack() && timeSinceUniqueIdle >= 10f)
				{
					TryPlayUniqueIdle();
				}
				if (Pathing())
				{
					ResetPlayerUniqueIdle();
					timeSincePath = 0f;
				}
			}
			else
			{
				ResetPlayerUniqueIdle();
				ResetCurseTimer();
			}
			UpdateTimers();
		}

		public void TeleportToPosition(Vector3 position)
		{
			SetPositionProper(position);
			int petCount = GetPetCount();
			for (int i = 0; i < petCount; i++)
			{
				GetPet(i).SetPositionProper(GetClosePosition(position, 0.35f, 2f, 100));
			}
			int partyMemberCount = GetPartyMemberCount();
			for (int j = 0; j < partyMemberCount; j++)
			{
				GetPartyMember(j).SetPositionProper(GetClosePosition(position, 0.35f, 2f, 100));
			}
			int wardCount = GetWardCount();
			for (int k = 0; k < wardCount; k++)
			{
				GetWard(k).SetPositionProper(GetClosePosition(position, 0.35f, 2f, 100));
			}
		}

