		public bool TryRecruitPartyMember(PlayerSaveData characterSaveData, ItemStorage itemStorage, uint uniqueSaveId, uint cost)
		{
			if (Fate.CurrentFateVer != Fate.FateVer.CursedKing)
			{
				UnityEngine.Debug.LogWarning("Cannot recruit party members except for in Fate 4.");
				return false;
			}
			if (partyCharacters.Count >= Fate.GetMaxPartyMembersByLevel(base.Level))
			{
				return false;
			}
			if (!SingletonBehaviour<PlayerStatus>.Instance.CanAfford(cost))
			{
				return false;
			}
			SingletonBehaviour<PlayerStatus>.Instance.RemoveGold(cost);
			if (characterSaveData.health <= 0f)
			{
				characterSaveData.health = 1f;
			}
			PartyMember partyMember = SummonPartyMember(characterSaveData, itemStorage, uniqueSaveId, PartyMember.Tactics.Support);
			if (partyMember != null && uniqueSaveId == 0)
			{
				List<Item> list = new List<Item>(partyMember.inventory);
				bool num = partyMember.attributes.GetAttribute(Attribute.SkillBow, allowEffects: false) > 8;
				bool flag = partyMember.attributes.GetAttribute(Attribute.SkillDualWield, allowEffects: false) > 8;
				if (num)
				{
					list.Sort(delegate(Item a, Item b)
					{
						if (a.IsMelee == b.IsMelee)
						{
							return 0;
						}
						return (!a.IsMelee) ? 1 : (-1);
					});
				}
				else if (flag)
				{
					list.Sort(delegate(Item a, Item b)
					{
						if (a.itemData.IsTwoHanded == b.itemData.IsTwoHanded)
						{
							return 0;
						}
						return a.itemData.IsTwoHanded ? 1 : (-1);
					});
				}
				partyMember.inventory.Clear();
				foreach (Item item in list)
				{
					partyMember.AddItemToInventory(item, AddItemReason.StartingItems);
					partyMember.AttemptAutoEquip(item);
				}
			}
			if (partyMember != null)
			{
				partyMember.MyVitals.FullHeal(removeNegativeEffects: true);
			}
			StatsManager.IncrementStat(Stat.AlliesRecruited);
			SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_narr_ally_joined);
			return true;
		}

		private PartyMember SummonPartyMember(PlayerSaveData characterSaveData, ItemStorage itemStorage, uint uniqueSaveId, PartyMember.Tactics tactics)
		{
			if (Fate.CurrentFateVer != Fate.FateVer.CursedKing)
			{
				return null;
			}
			Vector3 closePosition = GetClosePosition(myTransform.position, 0.35f, 3f, 20);
			PartyMember component = UnityEngine.Object.Instantiate(SingletonBehaviour<FateDB>.Instance.partyMemberPrefab, closePosition, myTransform.rotation).GetComponent<PartyMember>();
			component.partyMemberIndex = partyCharacters.Count;
			component.name = string.Format("PartyMember_{0}_{1}", partyCharacters.Count, string.IsNullOrEmpty(characterSaveData.playerName) ? "NoName" : characterSaveData.playerName);
			component.saveUniqueId = uniqueSaveId;
			component.SetMasterCharacter(this);
			component.Init(characterSaveData, itemStorage);
			component.SetTactics(tactics);
			component.hp = characterSaveData.health;
			if (component.hp <= 0f)
			{
				component.MyVitals.Die();
				component.SetAIState(AIState.PassedOut);
			}
			component.SetPositionProper(closePosition);
			partyCharacters.Add(component);
			onPartyChanged?.Invoke();
			return component;
		}

		public void DismissPartyMember(Character character)
		{
			if (partyCharacters.Remove(character))
			{
				UnityEngine.Object.Destroy(character.gameObject);
				onPartyChanged?.Invoke();
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_narr_ally_left);
			}
		}

		public void SetIntentionToRun(bool intendsToRun)
		{
			this.intendsToRun = intendsToRun;
		}

		private void TryPlayUniqueIdle()
		{
			if (uniqueIdleCoroutine == null && !isUniqueIdlePlaying)
			{
				uniqueIdleCoroutine = StartCoroutine(PlayUniqueIdleAnim());
			}
			timeSinceUniqueIdle = 0f;
		}

		private IEnumerator PlayUniqueIdleAnim()
		{
			isUniqueIdlePlaying = true;
			animator.SetInteger("UniqueIdleIndex", UnityEngine.Random.Range(1, 3));
			yield return new WaitForSeconds(1f);
			yield return new WaitUntil(() => !IsInState("Unique Idle"));
			ResetPlayerUniqueIdle();
		}

		private void ResetPlayerUniqueIdle()
		{
			if (uniqueIdleCoroutine != null)
			{
				StopCoroutine(uniqueIdleCoroutine);
			}
			animator.SetInteger("UniqueIdleIndex", 0);
			timeSinceUniqueIdle = 0f;
			uniqueIdleCoroutine = null;
			isUniqueIdlePlaying = false;
		}

		private bool IsInState(string stateName)
		{
			return animator.GetCurrentAnimatorStateInfo(0).IsName(stateName);
		}
	}
	public class Stash : InteractableSceneObject
	{
		public GameObject chestLid;

		public Vector3 lidRotation;

		public float duration = 1f;

		private List<Item> items;

		private bool[,] inventorySlotsOccupied;

		private Quaternion fromRotation;

		private Quaternion endRotation;

		public int InventoryGridWidth
		{
			get
			{
				if (inventorySlotsOccupied == null)
				{
					return 0;
				}
				return inventorySlotsOccupied.GetLength(1);
			}
		}

		public int InventoryGridHeight
		{
			get
			{
				if (inventorySlotsOccupied == null)
				{
					return 0;
				}
				return inventorySlotsOccupied.GetLength(0);
			}
		}

		private void Start()
		{
			items = new List<Item>();
			if (chestLid != null)
			{
				fromRotation = chestLid.transform.localRotation;
				endRotation = Quaternion.Euler(lidRotation);
			}
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.OnInventoryInit = (Action)Delegate.Combine(instance.OnInventoryInit, new Action(OnInventoryInit));
			}
			int[,] array = new int[10, 11];
			if (array != null)
			{
				int length = array.GetLength(1);
				int length2 = array.GetLength(0);
				inventorySlotsOccupied = new bool[length, length2];
			}
		}

		private void OnDestroy()
		{
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI != null)
				{
					InventoryUI inventoryUI = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI;
					inventoryUI.onRemoveItemFromStash = (Action<Item>)Delegate.Remove(inventoryUI.onRemoveItemFromStash, new Action<Item>(OnItemMovedFromStash));
				}
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.OnInventoryInit = (Action)Delegate.Remove(instance.OnInventoryInit, new Action(OnInventoryInit));
			}
			SaveData.RemovePreSaveMainThreadTask(FlushStashSave);
		}

		private void OnInventoryInit()
		{
			SaveData.AddPreSaveMainThreadTask(FlushStashSave);
			InventoryUI inventoryUI = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI;
			inventoryUI.onRemoveItemFromStash = (Action<Item>)Delegate.Combine(inventoryUI.onRemoveItemFromStash, new Action<Item>(OnItemMovedFromStash));
			if (SaveData.CurrentSaveData == null)
			{
				return;
			}
			ItemStorage stashStorage = SaveData.CurrentSaveData.stashStorage;
			if (stashStorage == null || stashStorage.items == null)
			{
				return;
			}
			List<ItemSaveData> savedItems = stashStorage.items;
			List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
			int i = 0;
			while (i < savedItems.Count)
			{
				ItemData itemData = allItems.Find((ItemData a) => a.displayName == savedItems[i].baseName);
				if (itemData == null)
				{
					UnityEngine.Debug.LogError("Unable to find item info: " + savedItems[i].baseName);
				}
				else
				{
					Item item = new Item(itemData);
					item.ApplyInstance(savedItems[i]);
					OnItemMovedToStash(item, (item.slotIndex >= 20) ? (item.slotIndex - 20) : (-1));
				}
				int num = i + 1;
				i = num;
			}
		}

		public override void Interact(Character interactor = null)
		{
			PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
			instance.onClosedTabs = (Action)Delegate.Combine(instance.onClosedTabs, new Action(OnClosedUI));
			InventoryUI inventoryUI = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI;
			inventoryUI.onAddItemToStash = (Action<Item, int>)Delegate.Combine(inventoryUI.onAddItemToStash, new Action<Item, int>(OnItemMovedToStash));
			InventoryUI inventoryUI2 = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI;
			inventoryUI2.onItemMovedInStash = (Action<Item, int>)Delegate.Combine(inventoryUI2.onItemMovedInStash, new Action<Item, int>(OnItemMovedInStash));
			StartCoroutine(RotateToTarget());
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ChestOpen, randomizePitch: true);
			SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.SetStash(items);
			SimpleSingletonBehaviour<PlayerUI>.Instance.ShowInventory(PlayerUI.InventoryStateType.Shop);
		}

		private void FlushStashSave(FateSaveData saveData)
		{
			if (SaveData.CurrentSaveSlot.saveState == SaveSlotState.Normal)
			{
				saveData.stashStorage = new ItemStorage
				{
					items = new List<ItemSaveData>()
				};
				for (int i = 0; i < items.Count; i++)
				{
					ItemSaveData itemSaveData = new ItemSaveData();
					items[i].FillInstance(itemSaveData);
					saveData.stashStorage.items.Add(itemSaveData);
				}
			}
		}

		private void OnClosedUI()
		{
			PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
			instance.onClosedTabs = (Action)Delegate.Remove(instance.onClosedTabs, new Action(OnClosedUI));
			InventoryUI inventoryUI = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI;
			inventoryUI.onAddItemToStash = (Action<Item, int>)Delegate.Remove(inventoryUI.onAddItemToStash, new Action<Item, int>(OnItemMovedToStash));
			InventoryUI inventoryUI2 = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI;
			inventoryUI2.onItemMovedInStash = (Action<Item, int>)Delegate.Remove(inventoryUI2.onItemMovedInStash, new Action<Item, int>(OnItemMovedInStash));
			StartCoroutine(RotateToTarget());
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ChestOpen, randomizePitch: true);
		}

		public void OnItemMovedToStash(Item item, int desiredSlot = -1)
		{
			if (CanFitItem(item, out var foundSlotIndex, desiredSlot))
			{
				item.slotIndex = 20 + foundSlotIndex;
				SetItemInGrid(item, state: true);
				if (!items.Contains(item))
				{
					items.Add(item);
				}
			}
			else
			{
				item.Drop(base.transform.position);
			}
		}

		public void OnItemMovedFromStash(Item item)
		{
			if (items.Contains(item))
			{
				items.Remove(item);
				SetItemInGrid(item, state: false);
			}
		}

		public void OnItemMovedInStash(Item item, int newSlot)
		{
			SetItemInGrid(item, state: false);
			item.slotIndex = newSlot;
			SetItemInGrid(item, state: true);
		}

		public bool CanFitItem(Item item, out int foundSlotIndex, int desiredSlot = -1, bool searchHorizontal = true)
		{
			foundSlotIndex = -1;
			bool[,] array = inventorySlotsOccupied;
			int length = array.GetLength(1);
			int length2 = array.GetLength(0);
			if (desiredSlot != -1 && IsSpaceAvailable(desiredSlot / length, desiredSlot % length, item.slotsTall, item.slotsWide))
			{
				foundSlotIndex = desiredSlot;
				return true;
			}
			if (searchHorizontal)
			{
				for (int i = 0; i < length2; i++)
				{
					for (int j = 0; j < length; j++)
					{
						if (IsSpaceAvailable(i, j, item.slotsTall, item.slotsWide))
						{
							foundSlotIndex = i * length + j;
							return true;
						}
					}
				}
			}
			else
			{
				for (int k = 0; k < length; k++)
				{
					for (int l = 0; l < length2; l++)
					{
						if (IsSpaceAvailable(l, k, item.slotsTall, item.slotsWide))
						{
							foundSlotIndex = l * length + k;
							return true;
						}
					}
				}
			}
			return false;
		}

		public void ReserveInventorySlotsForItem(Item item)
		{
			SetItemInGrid(item, state: true);
		}

		public void ReleaseInventorySlotsForItem(Item item)
		{
			SetItemInGrid(item, state: false);
		}

		public bool IsSpaceAvailable(int row, int col, int height, int width)
		{
			if (row + height > inventorySlotsOccupied.GetLength(0) || col + width > inventorySlotsOccupied.GetLength(1))
			{
				return false;
			}
			for (int i = row; i < row + height; i++)
			{
				for (int j = col; j < col + width; j++)
				{
					if (inventorySlotsOccupied[i, j])
					{
						return false;
					}
				}
			}
			return true;
		}

		private void SetItemInGrid(Item item, bool state)
		{
			int num = item.slotIndex - 20;
			if (num < 0)
			{
				UnityEngine.Debug.LogWarning($"Invalid item slot: {item.itemBaseName}: {item.slotIndex}");
				return;
			}
			int num2 = num / inventorySlotsOccupied.GetLength(1);
			int num3 = num % inventorySlotsOccupied.GetLength(1);
			for (int i = num2; i < num2 + item.slotsTall; i++)
			{
				for (int j = num3; j < num3 + item.slotsWide; j++)
				{
					inventorySlotsOccupied[i, j] = state;
				}
			}
		}

		public bool HasItem(ItemSaveData itemSaveData, out Item item)
		{
			item = items.Find((Item i) => itemSaveData.MatchesItem(i));
			return item != null;
		}

		public void SortItemList()
		{
			items.Sort();
		}

		public List<Item> GetItems()
		{
			return items;
		}

		private IEnumerator RotateToTarget()
		{
			if (!(chestLid == null))
			{
				Quaternion startRotation = fromRotation;
				Quaternion targetRotation = endRotation;
				endRotation = startRotation;
				fromRotation = targetRotation;
				float elipsedTime = 0f;
				while (elipsedTime < duration)
				{
					elipsedTime += Time.unscaledDeltaTime;
					chestLid.transform.localRotation = Quaternion.Lerp(startRotation, targetRotation, elipsedTime / duration);
					yield return null;
				}
				chestLid.transform.localRotation = targetRotation;
			}
		}
	}
	public class PlayerSpawn : MonoBehaviour
	{
