	public class PlayerStatus : SingletonBehaviour<PlayerStatus>
	{
		public Action<ulong> OnGoldChanged;

		public bool giveStartingGold;

		private const float errorInterval = 0.5f;

		private TutorialStatus tutorialStatus;

		public Action<Item> OnItemEnterPlayerOwnership;

		public Action<Item> OnItemExitPlayerOwnership;

		protected override bool DontDestroy => true;

		public ulong gold { get; private set; }

		public bool IsHandlingRetirement { get; set; }

		public Item HeirloomItem { get; set; }

		public static float errorCooldown { get; private set; }

		public static bool IsErrorOnCooldown => errorCooldown > 0f;

		public Fate.Difficulty Difficulty { get; private set; } = Fate.Difficulty.Adventurer;


		public TutorialStatus TutorialStatus => tutorialStatus;

		public RealmData.RealmId TownRealm { get; set; }

		public RealmData.RealmId DungeonRealm { get; set; }

		public void PutErrorOnCooldown()
		{
			errorCooldown = 0.5f;
		}

		public void LostHardcoreStatus()
		{
			if (Difficulty == Fate.Difficulty.Hardcore)
			{
				Difficulty = Fate.Difficulty.Legend;
				SaveData.CurrentSaveData.playerSaveData.difficulty = Fate.Difficulty.Legend;
				SaveData.RequestSave();
			}
		}

		protected override void Init()
		{
			base.Init();
			tutorialStatus = new TutorialStatus();
			tutorialStatus.Init(SaveData.CurrentSaveData);
		}

		public bool CanAfford(int cost)
		{
			if (cost <= 0)
			{
				return true;
			}
			return CanAfford((uint)cost);
		}

		public bool CanAfford(uint cost)
		{
			return gold >= cost;
		}

		public void AddGold(uint amount)
		{
			gold += amount;
			OnGoldChanged?.Invoke(gold);
		}

		public void RemoveGold(uint amount)
		{
			checked
			{
				try
				{
					gold -= amount;
				}
				catch (OverflowException)
				{
					gold = 0uL;
				}
				OnGoldChanged?.Invoke(gold);
			}
		}

		public void RemoveGold(ulong amount)
		{
			gold -= amount;
			OnGoldChanged?.Invoke(gold);
		}

		public void RemoveQuestItem(ItemSaveData targetItem)
		{
			bool flag = FindAndRemove(Player.PlayerChar);
			if (!flag)
			{
				flag = FindAndRemove(Player.PlayerChar.GetPet());
			}
			if (!flag && Fate.CurrentFateVer == Fate.FateVer.CursedKing)
			{
				for (int i = 0; i < Player.PlayerChar.GetPartyMemberCount(); i++)
				{
					flag = FindAndRemove(Player.PlayerChar.GetPartyMember(i));
					if (flag)
					{
						break;
					}
				}
			}
			if (!flag)
			{
				if (SingletonBehaviour<Town>.InstanceExists())
				{
					Stash stash = UnityEngine.Object.FindFirstObjectByType<Stash>();
					if (stash != null && stash.HasItem(targetItem, out var item))
					{
						stash.OnItemMovedFromStash(item);
						flag = true;
					}
				}
				else
				{
					ItemStorage stashStorage = SaveData.CurrentSaveData.stashStorage;
					if (stashStorage != null && stashStorage.items != null)
					{
						ItemSaveData itemSaveData = stashStorage.items.Find((ItemSaveData isd) => isd.MatchesOtherSave(targetItem));
						if (itemSaveData != null)
						{
							stashStorage.items.Remove(itemSaveData);
							flag = true;
						}
					}
				}
			}
			if (!flag)
			{
				UnityEngine.Debug.LogError("Failed to find Quest Item in any player connected inventory: " + targetItem.name);
			}
			bool FindAndRemove(Character targetChar)
			{
				if (targetChar == null || targetChar.inventory == null)
				{
					return false;
				}
				Item item2 = targetChar.inventory.Find((Item itm) => targetItem.MatchesItem(itm));
				if (item2 != null)
				{
					targetChar.RemoveItemFromInventory(item2, RemoveItemReason.System);
					return true;
				}
				return false;
			}
		}

		public void PreSave(FateSaveData fateSaveData)
		{
			FillSaveData(fateSaveData);
		}

		private void FillSaveData(FateSaveData saveData)
		{
			saveData.playerSaveData.gold = gold;
			saveData.playerSaveData.difficulty = Difficulty;
			tutorialStatus.FlushSave(saveData);
		}

		public void LoadSaveData(FateSaveData saveData)
		{
			gold = saveData.playerSaveData.gold;
			Difficulty = saveData.playerSaveData.difficulty;
			if (giveStartingGold)
			{
				AddGold(250u);
				giveStartingGold = false;
			}
			tutorialStatus.LoadSave(saveData);
		}

		private void Update()
		{
			if (errorCooldown > 0f)
			{
				errorCooldown -= Time.unscaledDeltaTime;
				if (errorCooldown < 0f)
				{
					errorCooldown = 0f;
				}
			}
		}
	}
	public class PortalManager : SingletonBehaviour<PortalManager>
	{
		private Dictionary<RealmData.RealmId, GameObject> activePortals;

		private GameObject activeDungeonPortal;

		protected override bool DontDestroy => true;

		public bool IsUsingTownPortal { get; set; }

		protected override void Init()
		{
			ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Combine(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
			activePortals = new Dictionary<RealmData.RealmId, GameObject>();
		}

		private void OnDestroy()
		{
			ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Remove(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
		}

		private void OnAvatarSpawn(ProdigyPlayer player, ProdigyAgent agent)
		{
			if (SaveData.CurrentSaveData?.realmSaveData?.realms == null)
			{
				return;
			}
			if (SingletonBehaviour<Town>.InstanceExists())
			{
				RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.TownRealm);
				if (realmSave.portalSave == null || realmSave.portalSave.portalSaves == null)
				{
					return;
				}
				for (int i = 0; i < realmSave.portalSave.portalSaves.Count; i++)
				{
					PortalSaveData portalSaveData = realmSave.portalSave.portalSaves[i];
					if (portalSaveData != null && portalSaveData.levelDepth != -1)
					{
						if (portalSaveData.dungeonRealm == RealmData.RealmId.ANY)
						{
							UnityEngine.Debug.LogError("Trying to spawn portal with realm ANY");
						}
						else if (activePortals.ContainsKey(portalSaveData.dungeonRealm))
						{
							activePortals[portalSaveData.dungeonRealm] = SingletonBehaviour<Town>.Instance.SpawnPortal(portalSaveData.dungeonRealm);
						}
						else
						{
							activePortals.Add(portalSaveData.dungeonRealm, SingletonBehaviour<Town>.Instance.SpawnPortal(portalSaveData.dungeonRealm));
						}
					}
				}
			}
			else
			{
				if (!(LevelGenerator.currentInstance != null))
				{
					return;
				}
				RealmSave realmSave2 = SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.TownRealm);
				if (realmSave2.portalSave == null || realmSave2.portalSave.portalSaves == null)
				{
					RemoveCurrentActivePortal();
					return;
				}
				PortalSaveData portalSaveData2 = realmSave2.portalSave.portalSaves.Find((PortalSaveData s) => s.dungeonRealm == SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
				if (portalSaveData2 == null || portalSaveData2.levelDepth == -1)
				{
					RemoveCurrentActivePortal();
				}
				else if (portalSaveData2.levelDepth == LevelGenerator.currentInstance.GetLevelDepth())
				{
					activeDungeonPortal = UnityEngine.Object.Instantiate(SingletonBehaviour<FateDB>.Instance.portalPrefab, ActiveLevel.AdjustPositionToNavMesh(portalSaveData2.dungeonPosition, portalSaveData2.dungeonPosition, performObstructionTest: false), Quaternion.identity);
				}
				else
				{
					RemoveCurrentActivePortal();
				}
			}
		}

		public bool TryCreatePortal(Character user)
		{
			if (SingletonBehaviour<Town>.InstanceExists())
			{
				return false;
			}
			if (!user.IsPlayer() && !user.IsPartyMember())
			{
				UnityEngine.Debug.LogWarning("Non-player/non ally character (" + user.CharacterName + ") attempted to create town portal. Not allowing it.");
				return false;
			}
			Vector3 intendedPosition = user.myTransform.position + user.myTransform.forward * 2f;
			GameObject gameObject = UnityEngine.Object.Instantiate(SingletonBehaviour<FateDB>.Instance.portalPrefab, ActiveLevel.AdjustPositionToNavMesh(intendedPosition, user.myTransform.position, performObstructionTest: true), Quaternion.identity);
			RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(Fate.GetDungeonTownRealm(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm));
			RealmSave realmSave2 = realmSave;
			if (realmSave2.portalSave == null)
			{
				realmSave2.portalSave = new PortalSave
				{
					portalSaves = new List<PortalSaveData>()
				};
			}
			if (realmSave.portalSave.portalSaves == null)
			{
				realmSave.portalSave.portalSaves = new List<PortalSaveData>();
			}
			PortalSaveData item = new PortalSaveData
			{
				levelDepth = LevelGenerator.currentInstance.GetLevelDepth(),
				dungeonPosition = gameObject.transform.position,
				dungeonRealm = SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm
			};
			PortalSaveData portalSaveData = realmSave.portalSave.portalSaves.Find((PortalSaveData s) => s.dungeonRealm == SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (portalSaveData != null)
			{
				portalSaveData.levelDepth = LevelGenerator.currentInstance.GetLevelDepth();
				portalSaveData.dungeonPosition = gameObject.transform.position;
			}
			else
			{
				realmSave.portalSave.portalSaves.Add(item);
			}
			IsUsingTownPortal = false;
			SetPortal(gameObject);
			return true;
		}

		public void RemoveCurrentActivePortal()
		{
			SetPortal(null);
		}

		public void SetPortal(GameObject portal)
		{
			if (activeDungeonPortal != null)
			{
				UnityEngine.Object.Destroy(activeDungeonPortal);
			}
			activeDungeonPortal = portal;
		}
	}
	public class ProfilePictureCamera : MonoBehaviour
	{
		private static bool isTakingPicture;

		[SerializeField]
		private Camera faceCamera;

		[SerializeField]
		private GameObject cameraLightsParent;

		[SerializeField]
		private RenderTexture renderTexture;

		public Action<Texture2D> onPictureTaken;

		private Texture2D mostRecentTexture;

		private void Awake()
		{
			faceCamera.clearFlags = CameraClearFlags.Color;
		}

		private void OnDestroy()
		{
			if (mostRecentTexture != null)
			{
				UnityEngine.Object.Destroy(mostRecentTexture);
			}
		}

		public void TakePicture()
		{
			StartCoroutine(DoTakePicture());
		}

		private IEnumerator DoTakePicture()
		{
			while (isTakingPicture)
			{
				yield return null;
			}
			isTakingPicture = true;
			faceCamera.gameObject.SetActive(value: true);
			yield return new WaitForEndOfFrame();
			List<SkinnedMeshRenderer> list = new List<SkinnedMeshRenderer>();
			Dictionary<SkinnedMeshRenderer, int> dictionary = new Dictionary<SkinnedMeshRenderer, int>();
			SkinnedMeshRenderer[] componentsInChildren = GetComponentsInChildren<SkinnedMeshRenderer>();
			foreach (SkinnedMeshRenderer skinnedMeshRenderer in componentsInChildren)
			{
				if (skinnedMeshRenderer.enabled && skinnedMeshRenderer.gameObject.activeInHierarchy)
				{
					list.Add(skinnedMeshRenderer);
					dictionary.Add(skinnedMeshRenderer, skinnedMeshRenderer.gameObject.layer);
					skinnedMeshRenderer.gameObject.layer = LayerMask.NameToLayer("ProfilePicture");
				}
			}
			cameraLightsParent.SetActive(value: true);
			RenderTexture active = RenderTexture.active;
			RenderTexture.active = faceCamera.targetTexture;
			faceCamera.Render();
			if (faceCamera.targetTexture == null)
			{
				faceCamera.enabled = false;
				UnityEngine.Debug.LogError("Could not take profile picture, render texture is null", this);
				componentsInChildren = GetComponentsInChildren<SkinnedMeshRenderer>();
				foreach (SkinnedMeshRenderer skinnedMeshRenderer2 in componentsInChildren)
				{
					skinnedMeshRenderer2.gameObject.layer = dictionary[skinnedMeshRenderer2];
				}
				isTakingPicture = false;
				yield break;
			}
			if (mostRecentTexture != null)
			{
				UnityEngine.Object.Destroy(mostRecentTexture);
			}
			Texture2D texture2D = new Texture2D(faceCamera.targetTexture.width, faceCamera.targetTexture.height, TextureFormat.ARGB32, mipChain: false);
			texture2D.ReadPixels(new Rect(0f, 0f, faceCamera.targetTexture.width, faceCamera.targetTexture.height), 0, 0);
			texture2D.Apply();
			mostRecentTexture = texture2D;
			GL.Clear(clearDepth: true, clearColor: true, Color.clear);
			RenderTexture.active = active;
			renderTexture.Release();
			componentsInChildren = GetComponentsInChildren<SkinnedMeshRenderer>();
			foreach (SkinnedMeshRenderer skinnedMeshRenderer3 in componentsInChildren)
			{
				skinnedMeshRenderer3.gameObject.layer = dictionary[skinnedMeshRenderer3];
			}
			cameraLightsParent.SetActive(value: false);
			faceCamera.gameObject.SetActive(value: false);
			onPictureTaken?.Invoke(texture2D);
			isTakingPicture = false;
		}
	}
