	public class ExclamationMark : MonoBehaviour
	{
		public enum MarkType
		{
			Default,
			QuestActive,
			QuestAvailable
		}

		public Texture defaultTex;

		public Texture questAvailableTex;

		private Vector3 originalScale;

		private MeshRenderer mr;

		public void Start()
		{
			originalScale = base.transform.localScale;
			base.transform.localScale = new Vector3(originalScale.x / base.transform.parent.lossyScale.x, originalScale.y / base.transform.parent.lossyScale.y, originalScale.z / base.transform.parent.lossyScale.z);
		}

		public void SetExclamationTexture(MarkType markType)
		{
			if (mr == null)
			{
				mr = GetComponent<MeshRenderer>();
			}
			Material material = mr.material;
			material.mainTexture = markType switch
			{
				MarkType.QuestAvailable => questAvailableTex, 
				MarkType.QuestActive => questAvailableTex, 
				_ => defaultTex, 
			};
			mr.material.color = ((markType == MarkType.QuestActive) ? new Color(1f, 1f, 1f, 0f) : Color.white);
		}
	}
	public class HeroStatueCharacter : Character
	{
		[SerializeField]
		private CharacterCustomizationDefaults charCustom;

		[SerializeField]
		private GameObject exclamationMark;

		private HeroType heroType;

		private Quest hiddenQuest;

		private bool isInitializing;

		public HeroType HeroType => heroType;

		private void Awake()
		{
			Init();
		}

		public override void Init()
		{
			isInitializing = true;
			base.Init();
			hp = 1f;
			invincible = true;
			alignment = Alignment.Neutral;
			attributes.AddBasePoints(Attribute.Strength, 1000);
			attributes.AddBasePoints(Attribute.Dexterity, 1000);
			attributes.AddBasePoints(Attribute.Vitality, 1000);
			attributes.AddBasePoints(Attribute.Magic, 1000);
			charCustom.SetGender(male: true);
			charCustom.SetRace(Race.Human);
			SetAIState(AIState.Inactive);
			SetActiveWeaponSet(WeaponSet.Primary);
			FateSaveData currentSaveData = SaveData.CurrentSaveData;
			if (currentSaveData != null)
			{
				List<ItemSaveData> list = null;
				if (heroType == HeroType.Druantia && currentSaveData.druantiaHeroData != null)
				{
					list = currentSaveData.druantiaHeroData.items.items;
				}
				else if (heroType == HeroType.Typhon && currentSaveData.typhonHeroData != null)
				{
					list = currentSaveData.typhonHeroData.items.items;
				}
				if (list != null)
				{
					List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
					foreach (ItemSaveData itemSave in list)
					{
						ItemData itemData = allItems.Find((ItemData a) => a.displayName == itemSave.baseName);
						if (itemData == null)
						{
							UnityEngine.Debug.LogError("Unable to find item info: " + itemSave.baseName);
							continue;
						}
						Item item = new Item(itemData);
						item.ApplyInstance(itemSave);
						AddItemToInventory(item, AddItemReason.LoadFromSave, item.slotIndex);
					}
				}
			}
			ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Combine(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
			isInitializing = false;
		}

		private void OnDestroy()
		{
			ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Remove(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
		}

		private void OnAvatarSpawn(ProdigyPlayer player, ProdigyAgent agent)
		{
			foreach (Quest hiddenQuest in SingletonBehaviour<QuestManager>.Instance.GetHiddenQuests())
			{
				if (hiddenQuest.heroItemType == heroType)
				{
					this.hiddenQuest = hiddenQuest;
					break;
				}
			}
			PerformPlayerHasItemCheck();
		}

		private void PerformPlayerHasItemCheck()
		{
			bool active = false;
			List<Item> list = new List<Item>();
			Player playerChar = Player.PlayerChar;
			list.AddRange(playerChar.inventory);
			Character pet = playerChar.GetPet();
			if (pet != null)
			{
				list.AddRange(pet.inventory);
			}
			for (int i = 0; i < playerChar.GetPartyMemberCount(); i++)
			{
				Character partyMember = playerChar.GetPartyMember(i);
				list.AddRange(partyMember.inventory);
			}
			foreach (Item item in list)
			{
				if (item.heroType != heroType)
				{
					continue;
				}
				bool flag = false;
				foreach (Item item2 in inventory)
				{
					if (item2.itemName == item.itemName)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					active = true;
					break;
				}
			}
			exclamationMark.SetActive(active);
		}

		private void OnEnable()
		{
			SaveData.AddPreSaveMainThreadTask(SaveHeroInventory);
		}

		private void OnDisable()
		{
			SaveData.RemovePreSaveMainThreadTask(SaveHeroInventory);
		}

		public void SetHeroType(HeroType type)
		{
			heroType = type;
			base.CharacterName = I2Loca.Get((heroType == HeroType.Druantia) ? "Monster_StatueofDruantiaHero" : "Monster_StatueofTyphonHero");
		}

		public override (bool mainSlot, bool secondarySlot) CanEquip(Item item)
		{
			if (item.heroType != heroType)
			{
				return (mainSlot: false, secondarySlot: false);
			}
			return base.CanEquip(item);
		}

		public override void EquipItem(Item item, WeaponSet weaponSet)
		{
			base.EquipItem(item, weaponSet);
			switch (item.itemType)
			{
			case ItemType.Helmet:
				charCustom.SetHelmet(item.itemData.displayName);
				break;
			case ItemType.Gloves:
				charCustom.SetGloves(item.itemData.displayName);
				break;
			case ItemType.Boots:
				charCustom.SetBoots(item.itemData.displayName);
				break;
			case ItemType.Shirt:
				charCustom.SetUpper(item.itemData.displayName);
				break;
			case ItemType.Back:
				charCustom.SetBack(item.itemData.displayName);
				break;
			}
			if (isInitializing)
			{
				return;
			}
			int num = 0;
			foreach (Item item2 in inventory)
			{
				if (item2.InEquipmentSlot)
				{
					num++;
				}
			}
			if (!hiddenQuest.Completed)
			{
				SingletonBehaviour<QuestManager>.Instance.OnItemEquippedInHeroStatue(heroType, num);
				if (hiddenQuest.Completed)
				{
					for (int i = 0; i < 5; i++)
					{
						new Item(SingletonBehaviour<MerchantData>.Instance.FindRandomHeroReward()).Drop(myTransform.position);
					}
				}
			}
			SaveData.RequestSave();
			UtilityTG.UnityDelay(PerformPlayerHasItemCheck);
		}

		private void SaveHeroInventory(FateSaveData saveData)
		{
			if (SaveData.CurrentSaveSlot.saveState != 0)
			{
				return;
			}
			List<ItemSaveData> list = null;
			if (heroType == HeroType.Druantia)
			{
				if (saveData.druantiaHeroData == null)
				{
					saveData.druantiaHeroData = new HeroStatueData
					{
						items = new ItemStorage
						{
							items = new List<ItemSaveData>()
						}
					};
				}
				list = saveData.druantiaHeroData.items.items;
			}
			else if (heroType == HeroType.Typhon)
			{
				if (saveData.typhonHeroData == null)
				{
					saveData.typhonHeroData = new HeroStatueData
					{
						items = new ItemStorage
						{
							items = new List<ItemSaveData>()
						}
					};
				}
				list = saveData.typhonHeroData.items.items;
			}
			if (list == null)
			{
				return;
			}
			list.Clear();
			foreach (Item item in inventory)
			{
				ItemSaveData itemSaveData = new ItemSaveData();
				item.FillInstance(itemSaveData);
				list.Add(itemSaveData);
			}
		}

		protected override void Update()
		{
		}

		public override void UpdateAI()
		{
		}
	}
	[RequireComponent(typeof(HeroStatueCharacter))]
	public class HeroStatueInteractable : InteractableSceneObject
	{
		[SerializeField]
		private HeroType heroType;

		protected HeroStatueCharacter heroCharacter;

		private void Awake()
		{
			heroCharacter = GetComponent<HeroStatueCharacter>();
			heroCharacter.SetHeroType(heroType);
