	public class Quest
	{
		public enum QuestStatus
		{
			None,
			Accepted,
			InProgress,
			Failed,
			Completed,
			Claimed,
			Abandoned
		}

		[Serializable]
		public class MonsterTemplate
		{
			public string monsterDataId;

			public string uniqueName;

			public string baseName;

			public Family family;

			public int overrideLevel;

			public int targetDepth;

			public RealmData.RealmId targetRealm;

			public ItemTemplate targetItem;

			public string BaseName => I2Loca.Get(baseName);
		}

		[Serializable]
		public class ItemTemplate
		{
			public ItemSaveData itemSaveData;

			public int itemLevel;

			public int targetDepth;

			public RealmData.RealmId targetRealm;
		}

		public QuestData baseQuestData;

		public RealmQuest realmQuestData;

		private const string questTitleDefault = "Quest_DefaultTitle";

		public MonsterTemplate uniqueQuestMonster;

		public MonsterTemplate questWard;

		public List<MonsterTemplate> questMonsters;

		public ItemTemplate questItem;

		public HeroType heroItemType;

		public QuestData.QuestType QuestType { get; private set; }

		public QuestStatus Status { get; set; }

		public int QuestId { get; private set; }

		public RealmData.RealmId RealmId { get; private set; }

		public string QuestName { get; private set; }

		public string QuestGiverName { get; private set; }

		public string QuestGiverDisplayName => I2Loca.Get("NPC_" + QuestGiverName);

		public string MonsterId { get; private set; }

		public string TargetId => realmQuestData?.target;

		public string ProgressFlag => realmQuestData?.progressFlag;

		public int TargetDepth
		{
			get
			{
				if (questWard != null && questWard.targetDepth != 0)
				{
					return questWard.targetDepth;
				}
				if (uniqueQuestMonster != null && uniqueQuestMonster.targetDepth != 0)
				{
					return uniqueQuestMonster.targetDepth;
				}
				if (questItem != null && questItem.targetDepth != 0)
				{
					return questItem.targetDepth;
				}
				if (questMonsters != null && questMonsters.Count > 0)
				{
					return questMonsters[0].targetDepth;
				}
				return 0;
			}
		}

		public int TargetCount { get; private set; }

		public int OriginalTargetCount { get; private set; }

		public MonsterData MinionData { get; private set; }

		public int GoldReward { get; private set; }

		public int FameReward { get; private set; }

		public int XPReward { get; private set; }

		public Item ItemReward { get; private set; }

		public bool hasPlayedCompleteSound { get; private set; }

		public bool Completed => Status == QuestStatus.Completed;

		public int QuestLevel { get; private set; }

		public Quest(QuestData questData, RealmData.RealmId realmId, string questGiver)
		{
			baseQuestData = questData;
			QuestType = questData.questType;
			QuestId = questData.questId;
			QuestName = I2Loca.Get(string.IsNullOrEmpty(questData.titleKey) ? "Quest_DefaultTitle" : questData.titleKey);
			RealmId = realmId;
			QuestGiverName = questGiver;
			RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(RealmId);
			int i = realmSave.latestDungeonDepth;
			if (realmSave.dungeonSave != null && realmSave.dungeonSave.latestDepths != null)
			{
				for (; realmSave.dungeonSave.latestDepths.Contains(i); i++)
				{
				}
			}
			GenerateObjective(i);
		}

		public Quest(RealmQuest realmQuestData, RealmData.RealmId realmId, string questGiver)
		{
			this.realmQuestData = realmQuestData;
			QuestType = realmQuestData.questType;
			QuestId = realmQuestData.id;
			QuestName = I2Loca.Get((!string.IsNullOrEmpty(realmQuestData.title)) ? realmQuestData.title : "Quest_DefaultTitle");
			RealmId = realmId;
			QuestGiverName = questGiver;
			MonsterId = realmQuestData.monster;
			heroItemType = realmQuestData.heroItemType;
			if (realmQuestData.hidden)
			{
				Status = QuestStatus.InProgress;
			}
			if (QuestType == QuestData.QuestType.HeroItem)
			{
				HeroType heroType = heroItemType;
				if (heroType == HeroType.Druantia || heroType == HeroType.Typhon)
				{
					TargetCount = 6;
				}
			}
			GenerateObjective(realmQuestData.depth);
		}

		public Quest(QuestSaveData questSave, RealmData.RealmId realmId, bool isRealmQuest)
		{
			RealmId = realmId;
			QuestId = questSave.questId;
			Status = questSave.status;
			QuestGiverName = questSave.questgiver;
			GoldReward = questSave.goldReward;
			XPReward = questSave.xpReward;
			FameReward = questSave.fameReward;
			heroItemType = questSave.heroType;
			QuestLevel = questSave.questLevel;
			questItem = questSave.questItem;
			hasPlayedCompleteSound = questSave.hasPlayedCompleteSound;
			if (isRealmQuest)
			{
				realmQuestData = SingletonBehaviour<FateDB>.Instance.realmQuests.Find((RealmQuest q) => q.targetRealm == realmId && q.id == questSave.questId);
				QuestName = I2Loca.Get((!string.IsNullOrEmpty(realmQuestData.title)) ? realmQuestData.title : "Quest_DefaultTitle");
				QuestType = realmQuestData.questType;
			}
			else
			{
				baseQuestData = SingletonBehaviour<FateDB>.Instance.GetQuestDatas().Find((QuestData q) => q.questId == questSave.questId);
				QuestName = I2Loca.Get(string.IsNullOrEmpty(baseQuestData.titleKey) ? "Quest_DefaultTitle" : baseQuestData.titleKey);
				QuestType = baseQuestData.questType;
			}
			if (questSave.targetCount > 0)
			{
				TargetCount = questSave.targetCount;
			}
			OriginalTargetCount = questSave.originalTargetCount;
			if (questSave.monsterInfo != null)
			{
				bool flag = RealmId == RealmData.RealmId.HauntedPalace && QuestType == QuestData.QuestType.RealmBoss;
				if (questSave.monsterInfo.Length == 1 || flag)
				{
					uniqueQuestMonster = questSave.monsterInfo[0];
					questMonsters = new List<MonsterTemplate>(questSave.monsterInfo);
				}
				else
				{
					questMonsters = new List<MonsterTemplate>(questSave.monsterInfo);
				}
			}
			questWard = questSave.wardInfo;
			if (!string.IsNullOrEmpty(questSave.minionMonsterId))
			{
				MinionData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData md) => md.displayName == questSave.minionMonsterId);
			}
			if (QuestType == QuestData.QuestType.HeroItem)
			{
				HeroType heroType = heroItemType;
				if (heroType == HeroType.Druantia || heroType == HeroType.Typhon)
				{
					TargetCount = 6;
				}
			}
			if (questItem != null && questItem.itemSaveData != null && !string.IsNullOrEmpty(questItem.itemSaveData.baseName))
			{
				QuestData.QuestType questType = QuestType;
				if ((questType == QuestData.QuestType.ArmyItem || questType == QuestData.QuestType.MonsterItem || questType == QuestData.QuestType.FindItem) && SingletonBehaviour<QuestManager>.Instance.IsKnownPlayerItem(questItem.itemSaveData))
				{
					Status = QuestStatus.Completed;
				}
			}
			if (questSave.rewardItem != null && !string.IsNullOrEmpty(questSave.rewardItem.baseName))
			{
				ItemData itemData = SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData itm) => itm.displayName == questSave.rewardItem.baseName);
				if (itemData == null)
				{
					UnityEngine.Debug.LogError("Item not found: " + questSave.rewardItem.baseName);
					return;
				}
				ItemReward = new Item(itemData);
				ItemReward.ApplyInstance(questSave.rewardItem);
				ItemReward.SetIdentified(newValue: true);
			}
		}

		public void OnUniqueMonsterKilled(Character monster)
		{
			if (LevelGenerator.currentInstance == null)
			{
				UnityEngine.Debug.LogError("Level generator current instance is null when killing unique monster (" + monster.CharacterName + ")", monster);
				return;
			}
			bool flag = realmQuestData != null && realmQuestData.targetRealm == RealmData.RealmId.HauntedPalace && QuestType == QuestData.QuestType.RealmBoss;
			if ((Status != QuestStatus.Accepted && (!flag || Status != QuestStatus.InProgress)) || uniqueQuestMonster.targetDepth != LevelGenerator.currentInstance.GetLevelDepth() || uniqueQuestMonster == null || (!(uniqueQuestMonster.uniqueName == monster.CharacterName) && (!flag || !(monster.CharacterName == questMonsters[1].uniqueName))))
			{
				return;
			}
			if (QuestType == QuestData.QuestType.KillMonster)
			{
				Status = QuestStatus.Completed;
				UnityEngine.Debug.Log("Quest Completed!");
				if (!hasPlayedCompleteSound)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
					hasPlayedCompleteSound = true;
				}
			}
			else if (QuestType == QuestData.QuestType.EscortOut)
			{
				Status = QuestStatus.InProgress;
				UnityEngine.Debug.Log("Spawning Escort Ward");
				LevelGenerator.currentInstance.GenerateQuestWards(this, inProgress: true);
			}
			else if (QuestType == QuestData.QuestType.RealmBoss || QuestType == QuestData.QuestType.MasterQuest)
			{
				Status = QuestStatus.Completed;
				if (!hasPlayedCompleteSound)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
					hasPlayedCompleteSound = true;
				}
			}
			else
			{
				if (QuestType != QuestData.QuestType.KillArmy)
				{
					return;
				}
				if (uniqueQuestMonster.uniqueName == monster.CharacterName)
				{
					int targetCount = TargetCount - 1;
					TargetCount = targetCount;
				}
				if (TargetCount <= 0)
				{
					Status = QuestStatus.Completed;
					UnityEngine.Debug.Log("Quest Completed!");
					if (!hasPlayedCompleteSound)
					{
						SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
						hasPlayedCompleteSound = true;
					}
				}
			}
		}

		public void OnTargetMonsterKilled(Character monster)
		{
			if (LevelGenerator.currentInstance == null)
			{
				UnityEngine.Debug.LogError("Level generator current instance is null when killing unique monster (" + monster.CharacterName + ")", monster);
			}
			else
			{
				if (Status != QuestStatus.Accepted)
				{
					return;
				}
				int levelDepth = LevelGenerator.currentInstance.GetLevelDepth();
				if (QuestType == QuestData.QuestType.KillMonsters)
				{
					for (int i = 0; i < questMonsters.Count; i++)
					{
						MonsterTemplate monsterTemplate = questMonsters[i];
						if (monsterTemplate.targetDepth == levelDepth && monsterTemplate.monsterDataId == monster.monsterData.displayName)
						{
							int targetCount = TargetCount - 1;
							TargetCount = targetCount;
							break;
						}
					}
					if (TargetCount <= 0)
					{
						Status = QuestStatus.Completed;
						UnityEngine.Debug.Log("Quest Completed!");
						if (!hasPlayedCompleteSound)
						{
							SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
							hasPlayedCompleteSound = true;
						}
					}
				}
				else
				{
					if (QuestType != QuestData.QuestType.KillArmy || uniqueQuestMonster.targetDepth != levelDepth)
					{
						return;
					}
					if (uniqueQuestMonster.uniqueName == monster.CharacterName)
					{
						int targetCount = TargetCount - 1;
						TargetCount = targetCount;
					}
					else if (MinionData != null && MinionData.displayName == monster.BaseName)
					{
						int targetCount = TargetCount - 1;
						TargetCount = targetCount;
					}
					if (TargetCount <= 0)
					{
						Status = QuestStatus.Completed;
						UnityEngine.Debug.Log("Quest Completed!");
						if (!hasPlayedCompleteSound)
						{
							SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
							hasPlayedCompleteSound = true;
						}
					}
				}
			}
		}

		public void OnWardEscortKilled(string wardId)
		{
			if ((Status == QuestStatus.Accepted || Status == QuestStatus.InProgress) && questWard.monsterDataId == wardId)
			{
				UnityEngine.Debug.LogWarning($"{QuestGiverName}'s quest of type {QuestType}: Ward dead, this should not happen");
			}
		}

		public void OnWardInteracted(Ward ward)
		{
			string text = ((QuestType == QuestData.QuestType.EscortIn) ? ward.CharacterName : ward.monsterData.displayName);
			if (Status != QuestStatus.Accepted || !(questWard.monsterDataId == text))
			{
				return;
			}
			int targetCount = TargetCount - 1;
			TargetCount = targetCount;
			if (TargetCount <= 0)
			{
				TargetCount = 0;
				Status = QuestStatus.Completed;
				UnityEngine.Debug.Log("Quest Completed!");
				if (!hasPlayedCompleteSound)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
					hasPlayedCompleteSound = true;
				}
			}
		}

		public void OnShrineDestroyed(string shrineId)
		{
			if ((Status == QuestStatus.InProgress || Status == QuestStatus.Accepted) && !(uniqueQuestMonster.uniqueName != shrineId) && QuestType == QuestData.QuestType.Deluge)
			{
				Status = QuestStatus.Completed;
				UnityEngine.Debug.Log("Quest Completed!");
				if (!hasPlayedCompleteSound)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
					hasPlayedCompleteSound = true;
				}
			}
		}

		public void OnShrineSurvived(string shrineId)
		{
			if ((Status == QuestStatus.InProgress || Status == QuestStatus.Accepted) && !(uniqueQuestMonster.uniqueName != shrineId) && QuestType == QuestData.QuestType.Defend)
			{
				Status = QuestStatus.Completed;
				UnityEngine.Debug.Log("Quest Completed!");
				if (!hasPlayedCompleteSound)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
