		public void OnNewLevelDepth(int depth)
		{
			if (Status == QuestStatus.Accepted && questWard != null && questWard.targetDepth == depth)
			{
				Status = QuestStatus.Completed;
				UnityEngine.Debug.Log("Quest Completed!");
				if (!hasPlayedCompleteSound)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
					hasPlayedCompleteSound = true;
				}
			}
		}

		public void OnItemLooted(Item item)
		{
			if (Status != QuestStatus.Accepted && Status != QuestStatus.InProgress)
			{
				return;
			}
			if (uniqueQuestMonster != null && uniqueQuestMonster.targetItem != null && uniqueQuestMonster.targetItem.itemSaveData.MatchesItem(item))
			{
				Status = QuestStatus.Completed;
				if (!hasPlayedCompleteSound)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
					hasPlayedCompleteSound = true;
				}
			}
			if (questItem != null && questItem.itemSaveData.MatchesItem(item))
			{
				Status = QuestStatus.Completed;
				if (!hasPlayedCompleteSound)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
					hasPlayedCompleteSound = true;
				}
			}
			if (questMonsters == null || questMonsters.Count <= 0)
			{
				return;
			}
			MonsterTemplate monsterTemplate = questMonsters.Find((MonsterTemplate m) => m.targetItem != null);
			if (monsterTemplate != null && monsterTemplate.targetItem.itemSaveData.MatchesItem(item))
			{
				Status = QuestStatus.Completed;
				if (!hasPlayedCompleteSound)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_questcomplete);
					hasPlayedCompleteSound = true;
				}
			}
		}

		public void OnItemLost(Item item)
		{
			if (Status != QuestStatus.Completed)
			{
				return;
			}
			if (uniqueQuestMonster != null && uniqueQuestMonster.targetItem != null && uniqueQuestMonster.targetItem.itemSaveData.MatchesItem(item))
			{
				Status = QuestStatus.Accepted;
			}
			if (questItem != null && questItem.itemSaveData.MatchesItem(item))
			{
				Status = QuestStatus.Accepted;
			}
			if (questMonsters != null && questMonsters.Count > 0)
			{
				MonsterTemplate monsterTemplate = questMonsters.Find((MonsterTemplate m) => m.targetItem != null);
				if (monsterTemplate != null && monsterTemplate.targetItem.itemSaveData.MatchesItem(item))
				{
					Status = QuestStatus.Accepted;
				}
			}
		}

		public void OnItemPreEnchantment(Item item)
		{
			if (!item.isQuestItem || Status != QuestStatus.Completed)
			{
				return;
			}
			if (uniqueQuestMonster != null && uniqueQuestMonster.targetItem != null && uniqueQuestMonster.targetItem.itemSaveData.MatchesItem(item))
			{
				Status = QuestStatus.Failed;
			}
			if (questItem != null && questItem.itemSaveData.MatchesItem(item))
			{
				Status = QuestStatus.Failed;
			}
			if (questMonsters != null && questMonsters.Count > 0)
			{
				MonsterTemplate monsterTemplate = questMonsters.Find((MonsterTemplate m) => m.targetItem != null);
				if (monsterTemplate != null && monsterTemplate.targetItem.itemSaveData.MatchesItem(item))
				{
					Status = QuestStatus.Failed;
				}
			}
		}

