		public void ClaimRewards()
		{
			if (Status == QuestStatus.Completed)
			{
				SingletonBehaviour<PlayerStatus>.Instance.AddGold((uint)GoldReward);
				Player.PlayerChar.AwardExperience(XPReward, fromMaster: false);
				Player.PlayerChar.AwardFame((uint)FameReward);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Reward, randomizePitch: false);
				if (ItemReward != null && !Player.PlayerChar.AddItemToInventory(ItemReward, AddItemReason.Loot))
				{
					ItemReward.Drop(Player.PlayerChar.myTransform.position);
				}
				if (questItem != null && questItem.itemSaveData != null && !string.IsNullOrEmpty(questItem.itemSaveData.baseName))
				{
					SingletonBehaviour<PlayerStatus>.Instance.RemoveQuestItem(questItem.itemSaveData);
				}
				if (uniqueQuestMonster != null && uniqueQuestMonster.targetItem != null && uniqueQuestMonster.targetItem.itemSaveData != null && !string.IsNullOrEmpty(uniqueQuestMonster.targetItem.itemSaveData.baseName) && (!(realmQuestData != null) || realmQuestData.removeQItemOnComplete))
				{
					SingletonBehaviour<PlayerStatus>.Instance.RemoveQuestItem(uniqueQuestMonster.targetItem.itemSaveData);
				}
				Status = QuestStatus.Claimed;
				if (realmQuestData != null)
				{
					StatsManager.IncrementStat(Stat.RealmQuests);
				}
				else
				{
					StatsManager.IncrementStat(Stat.SideQuests);
				}
			}
		}

