					return I2Loca.GetFormat(QuestType.ToString() + "_InProgress", uniqueQuestMonster.uniqueName, I2Loca.Get(uniqueQuestMonster.BaseName), uniqueQuestMonster.targetDepth);
				}
				if (QuestType == QuestData.QuestType.MasterQuest)
				{
					return I2Loca.GetFormat("KillArmy_InProgress", I2Loca.Get(uniqueQuestMonster.BaseName));
				}
				if (QuestType == QuestData.QuestType.Progress)
				{
					return I2Loca.GetFormatReplaceTags("MasterQuest_Locked", SingletonBehaviour<QuestManager>.Instance.GetRealmNeededStringForMQ(new List<string> { ProgressFlag }));
				}
			}
			return QuestType switch
			{
				QuestData.QuestType.KillMonster => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", I2Loca.Get(uniqueQuestMonster.uniqueName)), 
				QuestData.QuestType.KillMonsters => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", I2Loca.Get(questMonsters[0].baseName)), 
				QuestData.QuestType.MonsterItem => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", uniqueQuestMonster.targetItem.itemSaveData.ItemDisplayName), 
				QuestData.QuestType.FindItem => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", questItem.itemSaveData.ItemDisplayName), 
				QuestData.QuestType.KillArmy => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", I2Loca.Get(uniqueQuestMonster.uniqueName)), 
				QuestData.QuestType.ArmyItem => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", I2Loca.Get(uniqueQuestMonster.uniqueName), uniqueQuestMonster.targetItem.itemSaveData.ItemDisplayName), 
				QuestData.QuestType.EscortIn => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", I2Loca.Get(questWard.uniqueName), questWard.targetDepth), 
				QuestData.QuestType.EscortOut => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", I2Loca.Get(uniqueQuestMonster.uniqueName)), 
				QuestData.QuestType.Herd => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", TargetCount, I2Loca.Get(questWard.monsterDataId)), 
				QuestData.QuestType.Deluge => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", uniqueQuestMonster.uniqueName, uniqueQuestMonster.targetDepth), 
				QuestData.QuestType.Defend => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", uniqueQuestMonster.uniqueName, uniqueQuestMonster.targetDepth), 
				QuestData.QuestType.RealmBoss => I2Loca.GetFormat(QuestType.ToString() + "_InProgress", uniqueQuestMonster.uniqueName, I2Loca.Get(uniqueQuestMonster.BaseName), uniqueQuestMonster.targetDepth), 
				_ => I2Loca.Get(QuestType.ToString() + "_InProgress"), 
			};
		}

