			{
				if (QuestType == QuestData.QuestType.MasterQuest)
				{
					return I2Loca.GetFormatReplaceTags("RealmBoss_ShortDesc", I2Loca.Get(uniqueQuestMonster.BaseName), I2Loca.Get(MinionData.displayName), uniqueQuestMonster.targetDepth);
				}
				if (QuestType == QuestData.QuestType.RealmBoss && realmQuestData.targetRealm != RealmData.RealmId.HauntedPalace)
				{
					return I2Loca.GetFormatReplaceTags("KillMonster_ShortDesc", uniqueQuestMonster.uniqueName, I2Loca.Get(uniqueQuestMonster.BaseName), uniqueQuestMonster.targetDepth) + ((Fate.CurrentFateVer == Fate.FateVer.Original) ? I2Loca.GetMultiLineReplaceTags("Quest_DungeonHint") : "");
