				QuestData.QuestType.FindItem => I2Loca.GetFormatReplaceTags(QuestType.ToString() + "_ShortDesc", questItem.itemSaveData.ItemDisplayName, TargetDepth), 
				QuestData.QuestType.KillArmy => I2Loca.GetFormatReplaceTags(QuestType.ToString() + "_ShortDesc", I2Loca.Get(uniqueQuestMonster.uniqueName), I2Loca.Get(uniqueQuestMonster.baseName), I2Loca.Get(MinionData.displayName), uniqueQuestMonster.targetDepth), 
				QuestData.QuestType.ArmyItem => I2Loca.GetFormatReplaceTags(QuestType.ToString() + "_ShortDesc", I2Loca.Get(uniqueQuestMonster.uniqueName), I2Loca.Get(uniqueQuestMonster.baseName), I2Loca.Get(MinionData.displayName), uniqueQuestMonster.targetDepth, uniqueQuestMonster.targetItem.itemSaveData.ItemDisplayName), 
				QuestData.QuestType.EscortIn => I2Loca.GetFormatReplaceTags(QuestType.ToString() + "_ShortDesc", questWard.uniqueName, questWard.targetDepth, Fate.GetRealmName(questWard.targetRealm, preferShortName: true)), 
				QuestData.QuestType.EscortOut => I2Loca.GetFormatReplaceTags(QuestType.ToString() + "_ShortDesc", uniqueQuestMonster.uniqueName, Fate.GetRealmName(uniqueQuestMonster.targetRealm, preferShortName: true), uniqueQuestMonster.targetDepth, I2Loca.Get(uniqueQuestMonster.baseName)), 
				QuestData.QuestType.Herd => I2Loca.GetFormatReplaceTags(QuestType.ToString() + "_ShortDesc", TargetCount, I2Loca.Get(questWard.monsterDataId), questWard.targetDepth), 
				QuestData.QuestType.Deluge => I2Loca.GetFormatReplaceTags(QuestType.ToString() + "_ShortDesc", uniqueQuestMonster.uniqueName, uniqueQuestMonster.targetDepth), 
				QuestData.QuestType.Defend => I2Loca.GetFormatReplaceTags(QuestType.ToString() + "_ShortDesc", uniqueQuestMonster.uniqueName, uniqueQuestMonster.targetDepth, Fate.GetRealmName(uniqueQuestMonster.targetRealm, preferShortName: true)), 
				QuestData.QuestType.RealmBoss => I2Loca.GetFormatReplaceTags(QuestType.ToString() + "_ShortDesc", uniqueQuestMonster.uniqueName, realmQuestData.monster, realmQuestData.depth), 
				_ => I2Loca.Get(QuestType.ToString() + "_ShortDesc"), 
			};
		}

		public string GetCompleteText()
		{
			string text = GetBaseDesc();
			if (ItemReward != null)
			{
				text += "\n";
				text += I2Loca.GetFormatReplaceTags("Quest_ItemRewardClaim", ItemReward.ItemDisplayName);
			}
			return text;
			string GetBaseDesc()
			{
				if (realmQuestData != null && !string.IsNullOrEmpty(realmQuestData.completeDesc))
				{
					return I2Loca.Get(realmQuestData.completeDesc);
				}
				switch (QuestType)
				{
				case QuestData.QuestType.KillMonster:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", uniqueQuestMonster.uniqueName, XPReward, FameReward, GoldReward);
				case QuestData.QuestType.KillMonsters:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", XPReward, FameReward, GoldReward);
				case QuestData.QuestType.MonsterItem:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", uniqueQuestMonster.targetItem.itemSaveData.ItemDisplayName, XPReward, FameReward, GoldReward);
				case QuestData.QuestType.FindItem:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", questItem.itemSaveData.ItemDisplayName, XPReward, FameReward, GoldReward);
				case QuestData.QuestType.KillArmy:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", uniqueQuestMonster.uniqueName, XPReward, FameReward, GoldReward);
				case QuestData.QuestType.ArmyItem:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", uniqueQuestMonster.targetItem.itemSaveData.ItemDisplayName, uniqueQuestMonster.uniqueName, XPReward, FameReward, GoldReward);
				case QuestData.QuestType.EscortIn:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", questWard.uniqueName, questWard.targetDepth);
				case QuestData.QuestType.EscortOut:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", uniqueQuestMonster.uniqueName);
				case QuestData.QuestType.Herd:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", OriginalTargetCount, I2Loca.Get(questWard.monsterDataId));
				case QuestData.QuestType.Deluge:
					return I2Loca.GetMultiLineReplaceTagsFormat(QuestType.ToString() + "_Complete", uniqueQuestMonster.uniqueName, XPReward, FameReward, GoldReward);
				case QuestData.QuestType.Defend:
					return I2Loca.GetMultiLineFormat(QuestType.ToString() + "_Complete", uniqueQuestMonster.uniqueName, XPReward, FameReward, GoldReward);
				case QuestData.QuestType.Progress:
					return I2Loca.GetMultiLineFormat("RealmBoss_Complete", I2Loca.Get(realmQuestData?.monster), XPReward, FameReward, GoldReward);
				case QuestData.QuestType.RealmBoss:
				{
					Fate.FateVer currentFateVer = Fate.CurrentFateVer;
					if (currentFateVer == Fate.FateVer.UndiscoveredRealms || currentFateVer == Fate.FateVer.TraitorSoul)
					{
						return I2Loca.GetMultiLineReplaceTagsFormat("RealmQuest_Complete", uniqueQuestMonster.uniqueName, XPReward, FameReward, GoldReward);
					}
					if (RealmId == RealmData.RealmId.HauntedPalace)
					{
						return I2Loca.GetMultiLineFormat(QuestType.ToString() + "_Complete", I2Loca.Get(realmQuestData.target), XPReward, FameReward, GoldReward);
					}
					return I2Loca.GetMultiLineFormat(QuestType.ToString() + "_Complete", uniqueQuestMonster.uniqueName, XPReward, FameReward, GoldReward);
				}
				case QuestData.QuestType.MasterQuest:
					return I2Loca.GetMultiLineFormat("RealmBoss_Complete", I2Loca.Get(uniqueQuestMonster.BaseName), XPReward, FameReward, GoldReward);
				default:
					return I2Loca.Get(QuestType.ToString() + "_Complete");
				}
			}
		}

		public string GetQuestDescription()
		{
			string text = null;
			if (realmQuestData != null)
			{
				switch (QuestType)
				{
				case QuestData.QuestType.RealmBoss:
				{
					RealmData.RealmId realmId = RealmId;
					text = ((realmId != 0 && (uint)(realmId - 1) <= 1u) ? I2Loca.GetFormatReplaceTags(realmQuestData.questTemplate, I2Loca.GetFormat("PlayerTitle", uniqueQuestMonster.uniqueName, I2Loca.Get(uniqueQuestMonster.baseName)), TargetDepth.ToStringOrdinal(I2Loca.GetCurrentLanguageCode()), Fate.GetRealmName(uniqueQuestMonster.targetRealm, preferShortName: false)) : I2Loca.GetFormatReplaceTags(realmQuestData.questTemplate, uniqueQuestMonster.BaseName, uniqueQuestMonster.uniqueName, TargetDepth.ToStringOrdinal(I2Loca.GetCurrentLanguageCode())));
					break;
				}
				case QuestData.QuestType.KillMonster:
					text = I2Loca.GetFormatReplaceTags(realmQuestData.questTemplate, uniqueQuestMonster.targetDepth);
					break;
				case QuestData.QuestType.MasterQuest:
					text = I2Loca.GetFormatReplaceTags(realmQuestData.questTemplate, uniqueQuestMonster.BaseName, uniqueQuestMonster.targetDepth);
					break;
				case QuestData.QuestType.EscortOut:
					text = I2Loca.GetFormatReplaceTags(realmQuestData.questTemplate, uniqueQuestMonster.targetDepth);
					break;
				case QuestData.QuestType.MonsterItem:
				case QuestData.QuestType.Progress:
					text = I2Loca.GetReplaceTags(realmQuestData.questTemplate);
					break;
				default:
					text = I2Loca.Get(baseQuestData.shortDescription);
					break;
				}
			}
			else
			{
				bool shortDescOrdinalFloor = baseQuestData.shortDescOrdinalFloor;
				switch (QuestType)
				{
				case QuestData.QuestType.KillMonster:
					text = I2Loca.GetFormatReplaceTags(baseQuestData.shortDescription, uniqueQuestMonster.uniqueName, shortDescOrdinalFloor ? uniqueQuestMonster.targetDepth.ToStringOrdinal(I2Loca.GetCurrentLanguageCode()) : ((object)uniqueQuestMonster.targetDepth), Fate.GetRealmName(uniqueQuestMonster.targetRealm, preferShortName: false), I2Loca.Get(uniqueQuestMonster.baseName));
					break;
				case QuestData.QuestType.KillMonsters:
					text = I2Loca.GetFormatReplaceTags(baseQuestData.shortDescription, I2Loca.Get(questMonsters[0].baseName), shortDescOrdinalFloor ? questMonsters[0].targetDepth.ToStringOrdinal(I2Loca.GetCurrentLanguageCode()) : ((object)questMonsters[0].targetDepth), Fate.GetRealmName(questMonsters[0].targetRealm, preferShortName: false), TargetCount);
					break;
				case QuestData.QuestType.MonsterItem:
