					UnityEngine.Debug.LogError("No item index returned from QuestManager::GetRandomRewardItemIndex");
				}
				else
				{
					ItemData pItem = SingletonBehaviour<FateDB>.Instance.AllItems[num6];
					ItemReward = new Item(pItem);
					while (!ItemReward.HasPowers)
					{
						ItemReward.TryBestowPowers(level, AllowCurse: false, minimumLevel);
					}
					if (UnityEngine.Random.value < 0.2f)
					{
						ItemReward.BestowUniquePowers(level, AllowCurse: false, minimumLevel);
					}
					if (UnityEngine.Random.value < 0.1f)
					{
						ItemReward.BestowSockets(AllowUnique: false);
					}
					if (UnityEngine.Random.value < 0.1f)
					{
						ItemReward.BestowGrade(SingletonBehaviour<PlayerStatus>.Instance.Difficulty);
					}
					ItemReward.SetIdentified(newValue: true);
				}
			}
			if (flag)
			{
				Randomizer randomizer = new Randomizer();
				List<MonsterData> list2 = SingletonBehaviour<FateDB>.Instance.allMonsters.Where((MonsterData m) => m.ValidForRealm((int)RealmId) && !m.reserved && m.alignment == Alignment.Evil && m.family != Family.Herd && m.family != Family.MasterBoss && m.family != Family.Ward && m.walkingSpeed > 0);
				for (int j = 0; j < list2.Count; j++)
				{
					MonsterData monsterData17 = list2[j];
					if ((monsterData17.minions == null || monsterData17.minions.Count <= 0) && monsterData17.baseLevel <= QuestLevel && TargetDepth >= monsterData17.minimumDepth && TargetDepth <= monsterData17.maximumDepth)
					{
						int num7 = 1000 - monsterData17.rarity;
						if (num7 < 0)
						{
							num7 = 0;
						}
						if (num7 > 0)
						{
							randomizer.AddChoice(j, num7);
						}
					}
				}
				if (randomizer.Count == 0)
				{
					for (int k = 0; k < list2.Count; k++)
					{
						MonsterData monsterData18 = list2[k];
						if (monsterData18.minions == null || monsterData18.minions.Count <= 0)
						{
							int num8 = 1000 - monsterData18.rarity;
							if (num8 < 0)
							{
								num8 = 0;
							}
							if (num8 > 0)
							{
								randomizer.AddChoice(k, num8);
							}
						}
					}
				}
				int random = randomizer.GetRandom();
				if (random != -1)
				{
					MinionData = list2[random];
				}
				else
				{
					MinionData = null;
				}
			}
			else
			{
				MinionData = null;
			}
		}

		private ItemData GetRandomEquippable()
		{
			return SingletonBehaviour<FateDB>.Instance.AllItems.FindAll((ItemData i) => !i.reserved && i.takeable)?.FindAll((ItemData a) => a.ItemCategory == ItemCategory.Weapon || a.ItemCategory == ItemCategory.Armor || a.ItemCategory == ItemCategory.Jewelry)?.GetRandomEntry();
		}

		private ItemSaveData GenerateQuestItem(int itemLevel, ItemData overrideItemData = null)
		{
			if (overrideItemData == null)
			{
				overrideItemData = GetRandomEquippable();
			}
			Item item = new Item(overrideItemData);
			item.SetIdentified(newValue: true);
			item.BestowUniquePowers(itemLevel, AllowCurse: false, 1);
			item.baseLevel = itemLevel;
			item.isQuestItem = true;
			return item.GetItemSave();
		}

		public MonsterData PickARandomMonster(QuestData.QuestType questType, int adjustedMonsterDepth, int realm, bool monsterRepeatEnabled)
		{
			Randomizer randomizer = new Randomizer();
			for (int i = 0; i < SingletonBehaviour<FateDB>.Instance.allMonsters.Length; i++)
			{
				MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters[i];
				if (!monsterData.reserved && monsterData.ValidForRealm(realm) && !(monsterData.modelPrefab == null) && monsterData.alignment == Alignment.Evil && monsterData.walkingSpeed > 0 && monsterData.family != Family.Herd && monsterData.family != Family.Ward && ((questType != QuestData.QuestType.MasterQuest && questType != QuestData.QuestType.RealmBoss) || monsterData.baseLevel >= 26) && ((monsterData.minimumDepth - 2 <= adjustedMonsterDepth && monsterData.maximumDepth - 3 >= adjustedMonsterDepth) || (monsterRepeatEnabled && monsterData.minimumDepth <= adjustedMonsterDepth)))
				{
					int num = Mathf.Max(1000 - monsterData.rarity, 0);
					if (num > 0)
					{
						randomizer.AddChoice(i, num);
					}
				}
			}
			int num2 = randomizer.GetRandom();
			if (num2 == -1)
			{
				num2 = 0;
			}
			return SingletonBehaviour<FateDB>.Instance.allMonsters[num2];
		}

