	public class QuestGiver : NPC
	{
		[Header("Quest Giver")]
		public QuestData questData;

		public GameObject normalIcon;

		public GameObject doneIcon;

		public GameObject noQuestIcon;

		public ExclamationMark exclamationMark;

		public Vector3 iconScale;

		private GameObject spawnedIcon;

		private Camera mainCamera;

		public Quest Quest { get; private set; }

		public override void Init()
		{
			base.Init();
			isQuestGiver = true;
			base.CharacterName = npcVoiceLines.thisNpc.ToString();
			alignment = Alignment.Good;
			mainCamera = Camera.main;
		}

		private void Awake()
		{
			Init();
		}

		private IEnumerator Start()
		{
			while (Player.PlayerChar == null)
			{
				yield return null;
			}
			QuestManager.OnQuestAccepted = (Action<Quest>)Delegate.Remove(QuestManager.OnQuestAccepted, new Action<Quest>(OnQuestAccepted));
			QuestManager.OnQuestAccepted = (Action<Quest>)Delegate.Combine(QuestManager.OnQuestAccepted, new Action<Quest>(OnQuestAccepted));
			QuestManager.OnQuestCanceled = (Action<Quest>)Delegate.Remove(QuestManager.OnQuestCanceled, new Action<Quest>(OnQuestCanceled));
			QuestManager.OnQuestCanceled = (Action<Quest>)Delegate.Combine(QuestManager.OnQuestCanceled, new Action<Quest>(OnQuestCanceled));
			GenerateNewQuest();
			SetIcon();
		}

		private void OnDestroy()
		{
			QuestManager.OnQuestAccepted = (Action<Quest>)Delegate.Remove(QuestManager.OnQuestAccepted, new Action<Quest>(OnQuestAccepted));
			QuestManager.OnQuestCanceled = (Action<Quest>)Delegate.Remove(QuestManager.OnQuestCanceled, new Action<Quest>(OnQuestCanceled));
		}

		public void ClearQuest()
		{
			Quest = null;
			SetIcon();
		}

		private void OnQuestAccepted(Quest quest)
		{
			if (quest.realmQuestData != null && Quest != null && SingletonBehaviour<QuestManager>.Instance.CanAccessRealm(Quest.RealmId))
			{
				SetIcon();
			}
		}

		private void OnQuestCanceled(Quest quest)
		{
			if (quest.realmQuestData != null && Quest != null && SingletonBehaviour<QuestManager>.Instance.CanAccessRealm(Quest.RealmId))
			{
				SetIcon();
			}
			SetIcon();
		}

		public void SetIcon()
		{
			if (spawnedIcon != null)
			{
				UnityEngine.Object.Destroy(spawnedIcon);
			}
			switch ((Quest != null) ? Quest.Status : SingletonBehaviour<QuestManager>.Instance.GetQuestStatus((int)SingletonBehaviour<PlayerStatus>.Instance.TownRealm, base.CharacterName))
			{
			case Quest.QuestStatus.None:
				if (Quest != null && SingletonBehaviour<QuestManager>.Instance.CanAccessRealm(Quest.RealmId))
				{
					exclamationMark.SetExclamationTexture(ExclamationMark.MarkType.QuestAvailable);
					exclamationMark.gameObject.SetActive(value: true);
					spawnedIcon = UnityEngine.Object.Instantiate(normalIcon, base.transform.position, Quaternion.Euler(115f, mainCamera.transform.eulerAngles.y, 0f), base.transform);
				}
				else
				{
					exclamationMark.gameObject.SetActive(value: false);
				}
				break;
			case Quest.QuestStatus.Accepted:
			case Quest.QuestStatus.InProgress:
				exclamationMark.SetExclamationTexture(ExclamationMark.MarkType.QuestActive);
				exclamationMark.gameObject.SetActive(value: true);
				spawnedIcon = UnityEngine.Object.Instantiate(noQuestIcon, base.transform.position, Quaternion.Euler(135f, mainCamera.transform.eulerAngles.y, 0f), base.transform);
				break;
			case Quest.QuestStatus.Completed:
				exclamationMark.SetExclamationTexture(ExclamationMark.MarkType.Default);
				exclamationMark.gameObject.SetActive(value: true);
				spawnedIcon = UnityEngine.Object.Instantiate(doneIcon, base.transform.position, Quaternion.Euler(135f, mainCamera.transform.eulerAngles.y, 0f), base.transform);
				break;
			case Quest.QuestStatus.Abandoned:
				exclamationMark.gameObject.SetActive(value: false);
				spawnedIcon = UnityEngine.Object.Instantiate(noQuestIcon, base.transform.position, Quaternion.Euler(135f, mainCamera.transform.eulerAngles.y, 0f), base.transform);
				break;
			default:
				exclamationMark.gameObject.SetActive(value: false);
				break;
			}
		}

		public void GenerateNewQuest()
		{
			if (SaveData.CurrentSaveData == null)
			{
				UnityEngine.Debug.LogWarning("Current save data is null when trying to generate new quest");
				return;
			}
			Quest = SingletonBehaviour<QuestManager>.Instance.GetQuestForQuestGiver(base.CharacterName);
			SetIcon();
		}

		private void AnimCallbackStep()
		{
		}
	}
	public class QuestInteractable : InteractableSceneObject
	{
		private RealmQuestGiver realmquestCharacter;

		protected QuestGiver character;

		private NpcVoiceLines _npcVoiceLines;

		private void Start()
		{
			if (!TryGetComponent<RealmQuestGiver>(out realmquestCharacter) && !TryGetComponent<QuestGiver>(out character))
			{
				throw new ArgumentNullException(base.name, "NPC merchant has QuestInteractable but no QuestGiver script");
			}
			_npcVoiceLines = GetComponent<NpcVoiceLines>();
			base.InteractableName = "NPC_" + ((realmquestCharacter != null) ? realmquestCharacter.CharacterName : character.CharacterName);
		}

		public override void Interact(Character interactor = null)
		{
			Quest relevantQuest = null;
			if (realmquestCharacter != null)
			{
				if (realmquestCharacter.hasInitialGreeting && !SaveData.CurrentSaveData.HasDoneInitialGreeting())
				{
					SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton(_npcVoiceLines.thisNpc.ToString() + "_InitialGreeting", HandleInteractionComplete);
					if (Fate.CurrentFateVer == Fate.FateVer.CursedKing)
					{
						_npcVoiceLines.PlayRealmQuestLine(Quest.QuestStatus.None, isSilentBegin: false, isSilentEnd: false);
					}
					if (Fate.CurrentFateVer == Fate.FateVer.UndiscoveredRealms || Fate.CurrentFateVer == Fate.FateVer.TraitorSoul)
					{
						_npcVoiceLines.PlayYourLine();
					}
					realmquestCharacter.hasInitialGreeting = false;
					if (SaveData.CurrentSaveData.questSaveData == null)
					{
						SaveData.CurrentSaveData.questSaveData = new QuestStorage
						{
							hasDoneInitialGreeting = true
						};
					}
					else
					{
						SaveData.CurrentSaveData.questSaveData.hasDoneInitialGreeting = true;
					}
					realmquestCharacter.SetIcon();
					return;
				}
				realmquestCharacter.HandleInteractedWith(interactor);
				if (realmquestCharacter.ActiveQuest == null)
				{
					realmquestCharacter.ResolveRealmQuest();
				}
				relevantQuest = realmquestCharacter.ActiveQuest;
				(bool, List<string>) tuple = realmquestCharacter.IsQuestLocked();
				if (relevantQuest == null || relevantQuest.Status == Quest.QuestStatus.Claimed || tuple.Item1)
				{
					if (!realmquestCharacter.HasDoneAllQuests() || tuple.Item1)
					{
						SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(realmquestCharacter.GetLockedText(), delegate
						{
							HandleInteractionComplete();
						}, twoButtons: false, "OK");
						return;
					}
					switch (realmquestCharacter.postQuestBehavior)
					{
					case RealmQuestGiver.PostQuestBehavior.Greeting:
						SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("NPC_GreetingMsg_RealmQuestDone", HandleInteractionComplete);
						break;
					case RealmQuestGiver.PostQuestBehavior.Retire:
					{
						string bodyKey = "NPC_GreetingMsg_Bremen_Retirement";
						SingletonBehaviour<PromptUI>.Instance.ShowPrompt(bodyKey, delegate(bool b)
						{
							if (b)
							{
								SingletonBehaviour<StoryUI>.Instance.DoStory(SingletonBehaviour<FateDB>.Instance.GetGameRetireStory(Fate.CurrentFateVer), delegate
								{
									SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.SetItemSelectRetire();
									SimpleSingletonBehaviour<PlayerUI>.Instance.ShowInventory(PlayerUI.InventoryStateType.ItemSelect);
								});
							}
							HandleInteractionComplete();
						});
						break;
					}
					}
					if (Fate.CurrentFateVer != Fate.FateVer.CursedKing && realmquestCharacter == null)
					{
						_npcVoiceLines.PlayYourLine();
					}
					return;
				}
			}
			else
			{
				character.HandleInteractedWith(interactor);
				if (character.Quest == null)
				{
					character.GenerateNewQuest();
				}
				relevantQuest = character.Quest;
			}
			if (relevantQuest != null && (relevantQuest.realmQuestData != null || SingletonBehaviour<QuestManager>.Instance.CanAccessRealm(relevantQuest.RealmId)))
			{
				if (relevantQuest.realmQuestData != null && relevantQuest.realmQuestData.hidden && relevantQuest.Status != 0)
				{
					string bodyKey2 = "NPC_GreetingMsg_" + _npcVoiceLines.thisNpc;
					SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton(bodyKey2, HandleInteractionComplete);
					return;
				}
				switch (relevantQuest.Status)
				{
				case Quest.QuestStatus.None:
					if (realmquestCharacter == null && SingletonBehaviour<QuestManager>.Instance.IsQuestLogFull(relevantQuest.RealmId))
					{
						SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("QuestLogFull", HandleInteractionComplete);
						break;
					}
					if (realmquestCharacter != null && Fate.CurrentFateVer == Fate.FateVer.CursedKing)
					{
						_npcVoiceLines.PlayRealmQuestLine(relevantQuest.Status, relevantQuest.realmQuestData.isSilentBeginQuest, relevantQuest.realmQuestData.isSilentCompleteQuest);
					}
					SingletonBehaviour<PromptUI>.Instance.ShowPrompt(relevantQuest.GetQuestDescription(), delegate(bool positive)
					{
						if (positive)
						{
							string questGiver = ((realmquestCharacter != null) ? realmquestCharacter.CharacterName : character.CharacterName);
							SingletonBehaviour<QuestManager>.Instance.AcceptQuest(relevantQuest, questGiver);
							if (realmquestCharacter != null)
							{
								realmquestCharacter.SetIcon();
							}
							else
							{
								character.SetIcon();
							}
						}
						HandleInteractionComplete();
					});
					break;
				case Quest.QuestStatus.Accepted:
				case Quest.QuestStatus.InProgress:
					SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton(relevantQuest.GetInProgressText(), HandleInteractionComplete);
					break;
				case Quest.QuestStatus.Failed:
					HandleInteractionComplete();
					break;
				case Quest.QuestStatus.Completed:
					if (realmquestCharacter != null && Fate.CurrentFateVer == Fate.FateVer.CursedKing)
					{
						_npcVoiceLines.PlayRealmQuestLine(relevantQuest.Status, relevantQuest.realmQuestData.isSilentBeginQuest, relevantQuest.realmQuestData.isSilentCompleteQuest);
					}
					SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton(relevantQuest.GetCompleteText(), delegate
					{
						if (realmquestCharacter != null)
						{
							SingletonBehaviour<QuestManager>.Instance.ClaimRealmQuestRewards(relevantQuest);
							realmquestCharacter.ResolveRealmQuest();
						}
						else
						{
							SingletonBehaviour<QuestManager>.Instance.ClaimRewards(character.CharacterName);
							character.ClearQuest();
							character.GenerateNewQuest();
						}
						HandleInteractionComplete();
					});
					break;
				case Quest.QuestStatus.Claimed:
				case Quest.QuestStatus.Abandoned:
					SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("QuestNoQuest", HandleInteractionComplete);
					character.SetIcon();
					break;
				}
			}
			else
			{
				SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("QuestNoQuest", HandleInteractionComplete);
			}
			if (Fate.CurrentFateVer != Fate.FateVer.CursedKing || (Fate.CurrentFateVer == Fate.FateVer.CursedKing && realmquestCharacter == null && relevantQuest.Status == Quest.QuestStatus.None))
			{
				_npcVoiceLines.PlayYourLine();
			}
		}

		private void HandleInteractionComplete()
		{
			if (realmquestCharacter != null)
			{
				realmquestCharacter.HandleInteractionComplete(Player.PlayerChar);
				if (Fate.CurrentFateVer == Fate.FateVer.CursedKing && _npcVoiceLines.audioSource.isPlaying)
				{
					_npcVoiceLines.audioSource.Stop();
				}
			}
			else
			{
				character.HandleInteractionComplete(Player.PlayerChar);
			}
		}
	}
	public class QuestManager : SingletonBehaviour<QuestManager>
	{
		public static Action<Quest> OnQuestClaimed;

		public static Action<Quest> OnQuestAccepted;

		public static Action<Quest> OnQuestCanceled;

		public static Action<string> OnQuestFlag;

		private Dictionary<int, List<Quest>> allSideQuests;

		private Dictionary<int, Quest> realmQuests;

		private List<Quest> hiddenQuests;

		private List<string> unlockedQuestFlags;

		private Dictionary<int, int> realmQuestsComplete;

		private List<QuestData> questPool;

		private List<Item> knownPlayerOwnedQuestItems;

		private List<int> availableDungeons;

		private uint activeSaveSlotId;

		private Randomizer questItemRandomizer;

		private RealmData.RealmId realmRandomizedFor;

		private int playerLevelRandomizedFor;

		protected override bool DontDestroy => true;

		private RealmData.RealmId ActiveTownRealm => SingletonBehaviour<PlayerStatus>.Instance.TownRealm;

		public bool HasLoaded { get; private set; }

		public bool IsKnownPlayerItem(ItemSaveData itemSaveData)
		{
			for (int i = 0; i < knownPlayerOwnedQuestItems.Count; i++)
			{
				if (itemSaveData.MatchesItem(knownPlayerOwnedQuestItems[i]))
				{
					return true;
				}
			}
			return false;
		}

		protected override void Init()
		{
			allSideQuests = new Dictionary<int, List<Quest>>();
			realmQuests = new Dictionary<int, Quest>();
			realmQuestsComplete = new Dictionary<int, int>();
			hiddenQuests = new List<Quest>();
			unlockedQuestFlags = new List<string>();
			availableDungeons = new List<int>();
			knownPlayerOwnedQuestItems = new List<Item>();
			realmRandomizedFor = RealmData.RealmId.ANY;
			playerLevelRandomizedFor = -1;
			StartCoroutine(DoDelayedAddOfSaveTask());
			ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Combine(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
			ProdigyPlayer.OnAvatarRemoved = (Action)Delegate.Combine(ProdigyPlayer.OnAvatarRemoved, new Action(OnAvatarRemoved));
			PlayerStatus instance = SingletonBehaviour<PlayerStatus>.Instance;
			instance.OnItemEnterPlayerOwnership = (Action<Item>)Delegate.Combine(instance.OnItemEnterPlayerOwnership, new Action<Item>(OnItemEnteredPlayerControl));
			PlayerStatus instance2 = SingletonBehaviour<PlayerStatus>.Instance;
			instance2.OnItemExitPlayerOwnership = (Action<Item>)Delegate.Combine(instance2.OnItemExitPlayerOwnership, new Action<Item>(OnItemExitedPlayerControl));
		}

		public void ResetDataForNewGame()
		{
			allSideQuests = new Dictionary<int, List<Quest>>();
			realmQuests = new Dictionary<int, Quest>();
			realmQuestsComplete = new Dictionary<int, int>();
			hiddenQuests = new List<Quest>();
			unlockedQuestFlags = new List<string>();
			availableDungeons = new List<int>();
			knownPlayerOwnedQuestItems = new List<Item>();
			realmRandomizedFor = RealmData.RealmId.ANY;
			playerLevelRandomizedFor = -1;
			activeSaveSlotId = ((SaveData.CurrentSaveSlot != null) ? SaveData.CurrentSaveSlot.uniqueId : 0u);
		}

		private void OnAvatarSpawn(ProdigyPlayer pp, ProdigyAgent pa)
		{
			LoadSave();
		}

		private void OnAvatarRemoved()
		{
			HasLoaded = false;
		}

		private void BuildRandomizer()
		{
			questItemRandomizer = new Randomizer();
			List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
			int townrealmId = (int)SingletonBehaviour<PlayerStatus>.Instance.TownRealm;
			int level = Player.PlayerChar.Level;
			for (int i = 0; i < allItems.Count; i++)
			{
				ItemData itemData = allItems[i];
				int rarity = itemData.rarity;
				int minimumDepth = itemData.minimumDepth;
				int maximumDepth = itemData.maximumDepth;
				if (itemData.reserved)
				{
					continue;
				}
				if (itemData.realmData != null && itemData.realmData.Count > 0)
				{
					RealmOverrideData realmOverrideData = itemData.realmData.Find((RealmOverrideData rod) => rod.realmId == townrealmId);
					if (realmOverrideData != null)
					{
						rarity = realmOverrideData.rarity;
						minimumDepth = realmOverrideData.minimumDepth;
						maximumDepth = realmOverrideData.maximumDepth;
					}
				}
				ItemCategory itemCategory = itemData.ItemCategory;
				if ((itemCategory == ItemCategory.Jewelry || itemCategory == ItemCategory.Weapon || itemCategory == ItemCategory.Armor) && (((float)minimumDepth * 0.5f - 1.5f <= (float)level && (float)maximumDepth * 0.5f - 4f >= (float)level) || UnityEngine.Random.value < 0.1f))
				{
					int num = 1000 - rarity;
					if (num < 0)
					{
						num = 0;
					}
					if (num > 0)
					{
						questItemRandomizer.AddChoice(i, num);
					}
				}
			}
			realmRandomizedFor = ActiveTownRealm;
			playerLevelRandomizedFor = level;
		}

