		{
			return questItemRandomizer.GetRandom();
		}

		private IEnumerator DoDelayedAddOfSaveTask()
		{
			while (!SaveData.HasInitialized)
			{
				yield return null;
			}
			SaveData.AddPreSaveMainThreadTask(FlushSave);
		}

		public void ResetQuests()
		{
			if (allSideQuests != null)
			{
				allSideQuests.Clear();
			}
			if (realmQuests != null)
			{
				realmQuests.Clear();
			}
		}

		public bool IsInCursedLevel()
		{
			if (!HasLoaded || LevelGenerator.currentInstance == null)
			{
				return false;
			}
			Quest realmQuestActiveTownRealm = GetRealmQuestActiveTownRealm();
			if (realmQuestActiveTownRealm == null || realmQuestActiveTownRealm.realmQuestData == null)
			{
				return false;
			}
			if (realmQuestActiveTownRealm.RealmId != SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm)
			{
				return false;
			}
			return realmQuestActiveTownRealm.realmQuestData.cursed;
		}

		public void ProcCurse()
		{
			Quest realmQuestActiveTownRealm = GetRealmQuestActiveTownRealm();
			if (realmQuestActiveTownRealm == null || realmQuestActiveTownRealm.realmQuestData == null || !realmQuestActiveTownRealm.realmQuestData.cursed)
			{
				return;
			}
			if (LevelGenerator.currentInstance == null)
			{
				UnityEngine.Debug.LogWarning("Curse proc with no active dungeon!");
				return;
			}
			MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData md) => md.family == Family.Curse && md.ValidForRealm((int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm));
			if (monsterData == null)
			{
				UnityEngine.Debug.LogWarning("Curse proc but no valid Curse monsters!");
			}
			else
			{
				LevelGenerator.currentInstance.SpawnMonster(monsterData, Player.PlayerChar.myTransform.position);
			}
		}

		public bool HasCompleted(RealmQuest[] realmQuests)
		{
			if (realmQuests == null)
			{
				return true;
			}
			if (unlockedQuestFlags == null)
			{
				return false;
			}
			bool result = true;
			for (int i = 0; i < realmQuests.Length; i++)
			{
				for (int j = 0; j < realmQuests[i].keysToProgress.Count; j++)
				{
					if (!unlockedQuestFlags.Contains(realmQuests[i].keysToProgress[j]))
					{
						result = false;
						i = realmQuests.Length;
						break;
					}
				}
			}
			return result;
		}

		public bool HasFlags(List<string> flags)
		{
			if (flags == null || flags.Count == 0)
			{
				return true;
			}
			if (unlockedQuestFlags == null)
			{
				return false;
			}
			bool result = true;
			for (int i = 0; i < flags.Count; i++)
			{
				if (!unlockedQuestFlags.Contains(flags[i]))
				{
					result = false;
					break;
				}
			}
			return result;
		}

		public bool HasFlag(string flag)
		{
			if (string.IsNullOrEmpty(flag))
			{
				return true;
			}
			if (unlockedQuestFlags == null)
			{
				return false;
			}
			return unlockedQuestFlags.Contains(flag);
		}

		public Quest GetNextOrActiveRealmQuest(RealmQuest[] allrealmquests, string questgiverId, RealmData.RealmId targetRealm)
		{
			int key = (int)targetRealm;
			if (realmQuests.TryGetValue(key, out var value) && value != null)
			{
				if (string.IsNullOrEmpty(value.QuestGiverName) && !string.IsNullOrEmpty(questgiverId))
				{
					value.AssignQuestToGiver(questgiverId);
					if (value.realmQuestData.autoAccepted)
					{
						value.Status = Quest.QuestStatus.Accepted;
					}
					return value;
				}
				if (value.Status != Quest.QuestStatus.Claimed)
				{
					return value;
				}
			}
			List<RealmQuest> list = new List<RealmQuest>(allrealmquests);
			list.Sort((RealmQuest a, RealmQuest b) => a.id.CompareTo(b.id));
			int num = (realmQuestsComplete.ContainsKey(key) ? realmQuestsComplete[key] : (-1));
			int num2 = ((Player.PlayerChar != null) ? Player.PlayerChar.Level : Fate.GetLevelFromExperience((SaveData.CurrentSaveData.playerSaveData?.experience).GetValueOrDefault()));
			(SaveData.CurrentSaveData.playerSaveData?.playerRace).GetValueOrDefault(Race.Human);
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i].id <= num)
				{
					continue;
				}
				RealmQuest realmQuest = list[i];
				if (num2 < realmQuest.minLevel || (realmQuest.raceReq != 0 && realmQuest.raceReq != Player.PlayerChar.Race))
				{
					continue;
				}
				if (realmQuest.keysRequired != null)
				{
					bool flag = true;
					for (int j = 0; j < realmQuest.keysRequired.Count; j++)
					{
						if (!unlockedQuestFlags.Contains(realmQuest.keysRequired[j]))
						{
							flag = false;
							break;
						}
					}
					if (!flag)
					{
						continue;
					}
				}
				Quest quest = GenerateQuest(realmQuest);
				if (!string.IsNullOrEmpty(questgiverId))
				{
					quest.AssignQuestToGiver(questgiverId);
					if (realmQuest.autoAccepted)
					{
						quest.Status = Quest.QuestStatus.Accepted;
					}
				}
				realmQuests[key] = quest;
				return quest;
			}
			UnityEngine.Debug.Log("No eligible realmquest for realm: " + targetRealm);
			return null;
		}

		public bool IsQuestLogFull(RealmData.RealmId targetRealm)
		{
			List<Quest> quests = GetQuests((int)targetRealm);
			if (quests == null)
			{
				return false;
			}
			int num = 0;
			for (int i = 0; i < quests.Count; i++)
			{
				if (quests[i] != null && quests[i].Status != 0)
				{
					num++;
				}
			}
			return num >= 3;
		}

