		public bool CanAccessLevelInDungeon(RealmData.RealmId dungeonRealm, int targetDepth)
		{
			List<RealmQuest> list = SingletonBehaviour<FateDB>.Instance.realmQuests.Where((RealmQuest rq) => (rq.targetGame == Fate.FateVer.All || rq.targetGame == Fate.CurrentFateVer) && rq.targetRealm == dungeonRealm && rq.block != 0 && !rq.hidden);
			int key = (int)dungeonRealm;
			Quest quest = (realmQuests.ContainsKey(key) ? realmQuests[key] : null);
			List<Quest> list2 = hiddenQuests.Where((Quest hq) => hq.RealmId == dungeonRealm && hq.realmQuestData != null && hq.realmQuestData.block != 0);
			if (list.Count == 0 && list2.Count == 0)
			{
				return true;
			}
			for (int i = 0; i < list2.Count; i++)
			{
				Quest.QuestStatus status = list2[i].Status;
				if ((status == Quest.QuestStatus.Accepted || status == Quest.QuestStatus.InProgress) && targetDepth >= list2[i].realmQuestData.block)
				{
					return false;
				}
			}
			int num = (realmQuestsComplete.ContainsKey((int)dungeonRealm) ? realmQuestsComplete[(int)dungeonRealm] : (-1));
			for (int j = 0; j < list.Count; j++)
			{
				if (list[j].id > num && (list[j].raceReq == Race.None || list[j].raceReq == Player.PlayerChar.Race) && targetDepth >= list[j].block)
				{
					if (quest == null)
					{
						return false;
					}
					if (quest.Status < Quest.QuestStatus.Accepted)
					{
						return false;
					}
				}
			}
			return true;
		}

		public bool CanAccessRealm(RealmData.RealmId realmId)
		{
			Quest realmQuest = GetRealmQuest(realmId);
			switch (realmId)
			{
			case RealmData.RealmId.Druantia:
			case RealmData.RealmId.Typhon:
			case RealmData.RealmId.TempleOfFate:
			case RealmData.RealmId.ChamberOfTrials:
			case RealmData.RealmId.Prometheus:
			case RealmData.RealmId.CavernsLivingFire:
			case RealmData.RealmId.TkalaCrypt:
			case RealmData.RealmId.HauntedPalace:
				if ((realmQuest != null && realmQuest.Status != 0) || (unlockedQuestFlags != null && unlockedQuestFlags.Contains(GetRealmUnlockKey(realmId))))
				{
					return true;
				}
				return false;
			default:
				return true;
			}
		}

		public string GetRealmUnlockKey(RealmData.RealmId realmId)
		{
			return realmId switch
			{
				RealmData.RealmId.Druantia => "DRUANTIA", 
				RealmData.RealmId.Typhon => "TYPHON", 
				RealmData.RealmId.ChamberOfTrials => "CHAMBER", 
				RealmData.RealmId.CavernsLivingFire => "VOLCANO", 
				RealmData.RealmId.TkalaCrypt => "TOMB", 
				RealmData.RealmId.HauntedPalace => "HAMMERGOD", 
				RealmData.RealmId.TempleOfFate => "TEMPLE", 
				RealmData.RealmId.Prometheus => "PROMETHEUS", 
				_ => null, 
			};
		}

		public Quest GetRealmQuest(RealmData.RealmId realmId)
		{
			if (!realmQuests.ContainsKey((int)realmId))
			{
				return null;
			}
			return realmQuests[(int)realmId];
		}

		public List<Quest> GetRealmQuests(Predicate<Quest> predicate)
		{
			List<Quest> list = new List<Quest>();
			foreach (KeyValuePair<int, Quest> realmQuest in realmQuests)
			{
				Quest value = realmQuest.Value;
				if (value != null && predicate(value))
				{
					list.Add(value);
				}
			}
			return list;
		}

		public List<Quest> GetAllRealmQuests()
		{
			List<Quest> list = new List<Quest>();
			foreach (KeyValuePair<int, Quest> realmQuest in realmQuests)
			{
				Quest value = realmQuest.Value;
				if (value != null)
				{
					list.Add(value);
				}
			}
			return list;
		}

		public Quest GetRealmQuestActiveTownRealm()
		{
			if (Fate.CurrentFateVer == Fate.FateVer.CursedKing)
			{
				foreach (KeyValuePair<int, Quest> realmQuest in realmQuests)
				{
					if (realmQuest.Value != null)
					{
						Quest.QuestStatus status = realmQuest.Value.Status;
						if ((status == Quest.QuestStatus.Accepted || status == Quest.QuestStatus.InProgress || status == Quest.QuestStatus.Completed) && realmQuest.Value.QuestType != QuestData.QuestType.Progress)
						{
							return realmQuest.Value;
						}
					}
				}
			}
			return GetRealmQuest(ActiveTownRealm);
		}

		public List<Quest> GetQuests(int realmId)
		{
			if (!allSideQuests.ContainsKey(realmId))
			{
				allSideQuests.Add(realmId, new List<Quest>());
			}
			return allSideQuests[realmId];
		}

		public List<Quest> GetQuests(Predicate<Quest> predicate)
		{
			List<Quest> list = new List<Quest>();
			foreach (KeyValuePair<int, List<Quest>> allSideQuest in allSideQuests)
			{
				List<Quest> value = allSideQuest.Value;
				if (value == null)
				{
					continue;
				}
				foreach (Quest item in value)
				{
					if (item != null && predicate(item))
					{
						list.Add(item);
					}
				}
			}
			return list;
		}

		public List<Quest> GetAllQuests()
		{
			List<Quest> list = new List<Quest>();
			foreach (KeyValuePair<int, List<Quest>> allSideQuest in allSideQuests)
			{
				_ = allSideQuest.Key;
				List<Quest> value = allSideQuest.Value;
				list.AddRange(value);
			}
			return list;
		}

		public List<Quest> GetHiddenQuests()
		{
			if (hiddenQuests == null)
			{
				return null;
			}
			return hiddenQuests;
		}

		public Quest.QuestStatus GetQuestStatus(int realm, string questGiver)
		{
			List<Quest> quests = GetQuests(realm);
			Quest realmQuest = GetRealmQuest((RealmData.RealmId)realm);
			if (realmQuest != null && realmQuest.QuestGiverName == questGiver)
			{
				return realmQuest.Status;
			}
			return quests.Find((Quest a) => a != null && a.QuestGiverName == questGiver)?.Status ?? Quest.QuestStatus.None;
		}

		public Quest.QuestStatus GetQuestStatusActiveTownRealm(string questGiver)
		{
			return GetQuestStatus((int)ActiveTownRealm, questGiver);
		}

		private void OnItemEnteredPlayerControl(Item item)
		{
			if (item.isQuestItem)
			{
				knownPlayerOwnedQuestItems.AddUnique(item);
			}
			foreach (Quest allQuest in GetAllQuests())
			{
				if (allQuest != null)
				{
					QuestData.QuestType questType = allQuest.QuestType;
					if ((uint)(questType - 2) <= 1u || questType == QuestData.QuestType.ArmyItem || questType == QuestData.QuestType.HeroItem)
					{
						allQuest.OnItemLooted(item);
					}
				}
			}
			foreach (Quest allRealmQuest in GetAllRealmQuests())
			{
				QuestData.QuestType questType = allRealmQuest.QuestType;
				if ((uint)(questType - 2) <= 1u || questType == QuestData.QuestType.ArmyItem || questType == QuestData.QuestType.HeroItem)
				{
					allRealmQuest.OnItemLooted(item);
				}
			}
		}

		private void OnItemExitedPlayerControl(Item item)
		{
			if (item.isQuestItem)
			{
				knownPlayerOwnedQuestItems.Remove(item);
			}
			foreach (Quest allQuest in GetAllQuests())
			{
				if (allQuest != null)
				{
					QuestData.QuestType questType = allQuest.QuestType;
					if ((uint)(questType - 2) <= 1u || questType == QuestData.QuestType.ArmyItem || questType == QuestData.QuestType.HeroItem)
					{
						allQuest.OnItemLost(item);
					}
				}
			}
			foreach (Quest allRealmQuest in GetAllRealmQuests())
			{
				QuestData.QuestType questType = allRealmQuest.QuestType;
				if ((uint)(questType - 2) <= 1u || questType == QuestData.QuestType.ArmyItem || questType == QuestData.QuestType.HeroItem)
				{
					allRealmQuest.OnItemLost(item);
				}
			}
		}

		public void OnQuestItemPreEnchantment(Item item)
		{
			if (!item.isQuestItem)
			{
				return;
			}
			knownPlayerOwnedQuestItems.Remove(item);
			foreach (Quest allQuest in GetAllQuests())
			{
				if (allQuest != null)
				{
					QuestData.QuestType questType = allQuest.QuestType;
					if ((uint)(questType - 2) <= 1u || questType == QuestData.QuestType.ArmyItem || questType == QuestData.QuestType.HeroItem)
					{
						allQuest.OnItemPreEnchantment(item);
					}
				}
			}
			foreach (Quest allRealmQuest in GetAllRealmQuests())
			{
				QuestData.QuestType questType = allRealmQuest.QuestType;
				if ((uint)(questType - 2) <= 1u || questType == QuestData.QuestType.ArmyItem || questType == QuestData.QuestType.HeroItem)
				{
					allRealmQuest.OnItemPreEnchantment(item);
				}
			}
			item.isQuestItem = false;
		}

		public void UniqueMonsterKilled(Character monster)
		{
			RealmData.RealmId realmId = ((LevelGenerator.currentInstance != null) ? SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm : ActiveTownRealm);
			GetRealmQuest(realmId)?.OnUniqueMonsterKilled(monster);
			List<Quest> quests = GetQuests((int)realmId);
			if (quests == null)
			{
				return;
			}
			foreach (Quest item in quests)
			{
				if (item != null && (item.QuestType == QuestData.QuestType.KillMonster || item.QuestType == QuestData.QuestType.EscortOut || item.QuestType == QuestData.QuestType.KillArmy))
				{
					item.OnUniqueMonsterKilled(monster);
				}
			}
		}

		public void TargetMonsterKilled(Character monster)
		{
			RealmData.RealmId realmId = ((LevelGenerator.currentInstance != null) ? SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm : ActiveTownRealm);
			foreach (Quest quest in GetQuests((int)realmId))
			{
				if (quest != null && (quest.QuestType == QuestData.QuestType.KillMonsters || quest.QuestType == QuestData.QuestType.KillArmy))
				{
					quest.OnTargetMonsterKilled(monster);
				}
			}
			Quest realmQuest = GetRealmQuest(realmId);
			if (realmQuest != null && realmQuest.QuestType == QuestData.QuestType.KillMonsters)
			{
				realmQuest.OnTargetMonsterKilled(monster);
			}
		}

