		public void ReachedTown()
		{
			foreach (Quest item in GetQuestsActiveTownRealm())
			{
				if (item != null && item.QuestType == QuestData.QuestType.EscortOut)
				{
					item.OnReachedTown();
				}
			}
			Quest realmQuestActiveTownRealm = GetRealmQuestActiveTownRealm();
			if (realmQuestActiveTownRealm != null && realmQuestActiveTownRealm.QuestType == QuestData.QuestType.EscortOut)
			{
				realmQuestActiveTownRealm.OnReachedTown();
			}
			if (realmRandomizedFor != ActiveTownRealm || Player.PlayerChar.Level != playerLevelRandomizedFor)
			{
				BuildRandomizer();
			}
		}

		public void OnUrnOfTkalaDestroyed()
		{
			if (!(LevelGenerator.currentInstance == null))
			{
				Quest realmQuest = GetRealmQuest(RealmData.RealmId.HauntedPalace);
				if (realmQuest != null && realmQuest.QuestType == QuestData.QuestType.RealmBoss && realmQuest.Status == Quest.QuestStatus.Accepted)
				{
					realmQuest.Status = Quest.QuestStatus.InProgress;
					ProdigyCamera.Instance.Shake(0.5f);
					Character character = LevelGenerator.currentInstance.GenerateTkalaBoss(realmQuest.questMonsters[1], realmQuest.questMonsters[0].targetDepth);
					Vector3 position = UnityEngine.Object.FindFirstObjectByType<TkalaAnvilInteractable>().transform.position;
					character.myTransform.position = LevelGenerator.currentInstance.RandomOpenPosition(position, 2f);
				}
			}
		}

		public void OnItemEquippedInHeroStatue(HeroType heroType, int filledItemCount)
		{
			foreach (Quest hiddenQuest in GetHiddenQuests())
			{
				if (hiddenQuest.QuestType == QuestData.QuestType.HeroItem && heroType == hiddenQuest.heroItemType)
				{
					hiddenQuest.OnItemEquippedOnStatue(heroType, filledItemCount);
				}
			}
		}

		public void ClaimRewards(string questGiver)
		{
			Quest questForQuestGiver = GetQuestForQuestGiver(questGiver, generateIfNotFound: false);
			if (questForQuestGiver != null && questForQuestGiver.Status == Quest.QuestStatus.Completed)
			{
				questForQuestGiver.ClaimRewards();
				RemoveQuest(questForQuestGiver);
				OnQuestClaimed?.Invoke(questForQuestGiver);
			}
		}

		private void RemoveQuest(Quest quest)
		{
			foreach (KeyValuePair<int, List<Quest>> allSideQuest in allSideQuests)
			{
				if (allSideQuest.Value != null && allSideQuest.Value.IndexOf(quest) != -1)
				{
					allSideQuest.Value.Remove(quest);
					break;
				}
			}
		}

		public void ClaimRealmQuestRewards(Quest realmQuest)
		{
			if (realmQuest.Status != Quest.QuestStatus.Completed)
			{
				UnityEngine.Debug.LogError($"Tried to claim rewards of a realm quest with incorrect status {realmQuest.Status}. Not allowing it");
				return;
			}
			realmQuest.ClaimRewards();
			int realmId = (int)realmQuest.RealmId;
			if (!realmQuestsComplete.ContainsKey(realmId))
			{
				realmQuestsComplete.Add(realmId, realmQuest.QuestId);
			}
			else
			{
				realmQuestsComplete[realmId] = Mathf.Max(realmQuestsComplete[realmId], realmQuest.QuestId);
			}
			if (realmQuest.realmQuestData.keysToProgress != null)
			{
				for (int i = 0; i < realmQuest.realmQuestData.keysToProgress.Count; i++)
				{
					string text = realmQuest.realmQuestData.keysToProgress[i];
					unlockedQuestFlags.AddUnique(text);
					OnQuestFlagGranted(text);
				}
			}
			if (realmQuests.TryGetValue(realmId, out var value) && value == realmQuest)
			{
				realmQuests.Remove(realmId);
			}
		}

		public bool HasCompletedCampaign()
		{
			switch (Fate.CurrentFateVer)
			{
			case Fate.FateVer.Original:
				return HasFlag("GROVE");
			case Fate.FateVer.UndiscoveredRealms:
			case Fate.FateVer.TraitorSoul:
				return HasFlag("TEMPLE");
			case Fate.FateVer.CursedKing:
				return HasFlag("EKBATAN");
			default:
				return false;
			}
		}

		public string GetRealmNeededStringForMQ(List<string> progressKeysNeeded)
		{
			List<string> list = new List<string>();
			if (unlockedQuestFlags == null || unlockedQuestFlags.Count == 0)
			{
				list.AddRange(progressKeysNeeded);
				if (list.Contains("TKALASDEAD"))
				{
					list.AddUnique("VOLCANO");
					list.AddUnique("TOMB");
					list.AddUnique("HAMMERGOD");
					list.Remove("TKALASDEAD");
				}
			}
			else
			{
				for (int i = 0; i < progressKeysNeeded.Count; i++)
				{
					if (unlockedQuestFlags.Contains(progressKeysNeeded[i]))
					{
						continue;
					}
					if (progressKeysNeeded[i] == "TKALASDEAD")
					{
						if (!unlockedQuestFlags.Contains("VOLCANO"))
						{
							list.AddUnique("VOLCANO");
						}
						if (!unlockedQuestFlags.Contains("TOMB"))
						{
							list.AddUnique("TOMB");
						}
						list.AddUnique("HAMMERGOD");
					}
					else
					{
						list.AddUnique(progressKeysNeeded[i]);
					}
				}
			}
			if (list.Count == 0)
			{
				return null;
			}
			switch (list.GetRandomEntry())
			{
			case "DRUANTIA":
				return Fate.GetRealmName(RealmData.RealmId.Druantia, preferShortName: false);
			case "TYPHON":
				return Fate.GetRealmName(RealmData.RealmId.Typhon, preferShortName: false);
			case "VOLCANO":
				return Fate.GetRealmName(RealmData.RealmId.CavernsLivingFire, preferShortName: false);
			case "TOMB":
				return Fate.GetRealmName(RealmData.RealmId.TkalaCrypt, preferShortName: false);
			case "HAMMERGOD":
				return Fate.GetRealmName(RealmData.RealmId.HauntedPalace, preferShortName: false);
			case "FINALTRIAL":
			case "THIRDTRIAL":
				return Fate.GetRealmName(RealmData.RealmId.ChamberOfTrials, preferShortName: false);
			default:
				return null;
			}
		}

		public Quest GetQuestForQuestGiver(string questGiver, bool generateIfNotFound = true)
		{
			foreach (KeyValuePair<int, List<Quest>> allSideQuest in allSideQuests)
			{
				if (allSideQuest.Value != null)
				{
					Quest quest = allSideQuest.Value.Find((Quest q) => q != null && q.QuestGiverName == questGiver);
					if (quest != null)
					{
						return quest;
					}
				}
			}
			if (!generateIfNotFound)
			{
				return null;
			}
			if (questPool == null || questPool.Count == 0)
			{
				if (!SingletonBehaviour<FateDB>.InstanceExists())
				{
					return null;
				}
				UnityEngine.Debug.LogWarning("Quest pool was null or empty, refilling from FateDB");
				questPool = new List<QuestData>(SingletonBehaviour<FateDB>.Instance.GetQuestDatas());
			}
			return GenerateQuest(questPool.GetRandomEntry());
		}

		public void AcceptQuest(Quest quest, string questGiver)
		{
			if (quest.realmQuestData != null)
			{
				quest.AssignQuestToGiver(questGiver);
				quest.Status = Quest.QuestStatus.Accepted;
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Quest, randomizePitch: false);
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_newquest);
				if (SingletonBehaviour<Town>.Instance != null)
				{
					OnQuestAccepted?.Invoke(quest);
				}
				if (quest.realmQuestData != null && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.RealmQuest, out var key))
				{
					SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
				}
				if (quest.QuestType == QuestData.QuestType.Progress && HasFlag(quest.ProgressFlag))
				{
					quest.Status = Quest.QuestStatus.Completed;
				}
				return;
			}
			int realmId = (int)quest.RealmId;
			if (!allSideQuests.ContainsKey(realmId) || allSideQuests[realmId] == null)
			{
				allSideQuests[realmId] = new List<Quest>();
			}
			List<Quest> list = allSideQuests[realmId];
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i] == quest)
				{
					list[i].AssignQuestToGiver(questGiver);
					list[i].Status = Quest.QuestStatus.Accepted;
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Quest, randomizePitch: false);
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_newquest);
					if (SingletonBehaviour<Town>.Instance != null)
					{
						OnQuestAccepted?.Invoke(list[i]);
					}
					return;
				}
			}
			list.Add(quest);
			quest.AssignQuestToGiver(questGiver);
			quest.Status = Quest.QuestStatus.Accepted;
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Quest, randomizePitch: false);
			SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_newquest);
			if (SingletonBehaviour<Town>.Instance != null)
			{
				OnQuestAccepted?.Invoke(quest);
			}
		}

		public void CancelQuest(Quest quest)
		{
			List<Quest> quests = GetQuests((int)quest.RealmId);
			for (int i = 0; i < quests.Count; i++)
			{
				if (quests[i] == quest)
				{
					quests[i].Status = Quest.QuestStatus.Abandoned;
					OnQuestCanceled?.Invoke(quests[i]);
				}
			}
			if (quest.questItem != null && knownPlayerOwnedQuestItems != null)
			{
				foreach (Item knownPlayerOwnedQuestItem in knownPlayerOwnedQuestItems)
				{
					if (quest.questItem != null && quest.questItem.itemSaveData != null && quest.questItem.itemSaveData.MatchesItem(knownPlayerOwnedQuestItem))
					{
						knownPlayerOwnedQuestItem.isQuestItem = false;
					}
					else if (quest.uniqueQuestMonster != null && quest.uniqueQuestMonster.targetItem != null && quest.uniqueQuestMonster.targetItem.itemSaveData != null && quest.uniqueQuestMonster.targetItem.itemSaveData.MatchesItem(knownPlayerOwnedQuestItem))
					{
						knownPlayerOwnedQuestItem.isQuestItem = false;
					}
					else if (quest.questMonsters != null && quest.questMonsters.Count > 0)
					{
						Quest.MonsterTemplate monsterTemplate = quest.questMonsters.Find((Quest.MonsterTemplate m) => m.targetItem != null);
						if (monsterTemplate != null && monsterTemplate.targetItem != null && monsterTemplate.targetItem.itemSaveData != null && monsterTemplate.targetItem.itemSaveData.MatchesItem(knownPlayerOwnedQuestItem))
						{
							knownPlayerOwnedQuestItem.isQuestItem = false;
						}
					}
				}
			}
			quests.Remove(quest);
		}

		public void GrantQuestFlag(string flag)
		{
			unlockedQuestFlags.AddUnique(flag);
			OnQuestFlagGranted(flag);
		}

		private void OnQuestFlagGranted(string newFlag)
		{
			foreach (Quest hiddenQuest in hiddenQuests)
			{
				if (hiddenQuest.Status == Quest.QuestStatus.Completed || hiddenQuest.ProgressFlag != newFlag)
				{
					continue;
				}
				hiddenQuest.Status = Quest.QuestStatus.Completed;
				if (hiddenQuest.realmQuestData.keysToProgress != null)
				{
					for (int i = 0; i < hiddenQuest.realmQuestData.keysToProgress.Count; i++)
					{
						string text = hiddenQuest.realmQuestData.keysToProgress[i];
						unlockedQuestFlags.AddUnique(text);
						OnQuestFlagGranted(text);
					}
				}
			}
			foreach (KeyValuePair<int, Quest> realmQuest in realmQuests)
			{
				if (realmQuest.Value != null && realmQuest.Value.QuestType == QuestData.QuestType.Progress && (realmQuest.Value.Status == Quest.QuestStatus.Accepted || realmQuest.Value.Status == Quest.QuestStatus.InProgress) && string.Equals(realmQuest.Value.ProgressFlag, newFlag, StringComparison.OrdinalIgnoreCase))
				{
					realmQuest.Value.Status = Quest.QuestStatus.Completed;
				}
			}
			OnQuestFlag?.Invoke(newFlag);
		}

		public void OnQuestHubEntered(int realmId)
		{
			if (questItemRandomizer == null)
			{
				BuildRandomizer();
			}
			questPool = new List<QuestData>(SingletonBehaviour<FateDB>.Instance.GetQuestDatas());
			List<Quest> quests = GetQuests(realmId);
			if (quests != null)
			{
				for (int j = 0; j < quests.Count; j++)
				{
					Quest quest = quests[j];
					if (quest != null)
					{
						QuestData questData = questPool.Find((QuestData q) => q.questId == quest.QuestId);
						if (questData != null)
						{
							questPool.Remove(questData);
						}
					}
				}
			}
			if (realmId == 10)
			{
				availableDungeons = new List<int>();
				availableDungeons.Add(11);
				if (unlockedQuestFlags.Contains("VOLCANO"))
				{
					availableDungeons.Add(12);
				}
				if (unlockedQuestFlags.Contains("TOMB"))
				{
					availableDungeons.Add(13);
				}
				if (unlockedQuestFlags.Contains("EKBATAN"))
				{
					availableDungeons.Add(10);
				}
			}
			else
			{
				availableDungeons = new List<int>();
				availableDungeons.Add(realmId);
			}
			List<RealmQuest> allHidden = SingletonBehaviour<FateDB>.Instance.realmQuests.Where((RealmQuest rq) => rq.hidden);
			if (allHidden == null || allHidden.Count <= 0)
			{
				return;
			}
			if (hiddenQuests == null)
			{
				hiddenQuests = new List<Quest>();
			}
			int i = 0;
			while (i < allHidden.Count)
			{
				if (hiddenQuests.Find((Quest q) => q.realmQuestData == allHidden[i]) == null)
				{
					hiddenQuests.Add(GenerateQuest(allHidden[i]));
				}
				int num = i + 1;
				i = num;
			}
		}

		private int GetAvailableRealmForSideQuest()
		{
			if (availableDungeons == null)
			{
				return (int)ActiveTownRealm;
			}
			if (availableDungeons.Count == 1)
			{
				return availableDungeons[0];
			}
			List<int> list = new List<int>();
			for (int i = 0; i < availableDungeons.Count; i++)
			{
				if (!IsQuestLogFull((RealmData.RealmId)availableDungeons[i]))
				{
					list.Add(availableDungeons[i]);
				}
			}
			if (list.Count == 0)
			{
				return availableDungeons[0];
			}
			return list.GetRandomEntry();
		}

		private Quest GenerateQuest(QuestData questData)
		{
			questPool.Remove(questData);
			int availableRealmForSideQuest = GetAvailableRealmForSideQuest();
			return new Quest(questData, (RealmData.RealmId)availableRealmForSideQuest, null);
		}

		private Quest GenerateQuest(RealmQuest realmQuestData)
		{
			return new Quest(realmQuestData, realmQuestData.targetRealm, null);
		}

		private void LoadSave()
		{
			QuestStorage questSaveData = SaveData.CurrentSaveData.questSaveData;
			allSideQuests = new Dictionary<int, List<Quest>>();
			realmQuests = new Dictionary<int, Quest>();
			hiddenQuests = new List<Quest>();
			unlockedQuestFlags = new List<string>();
			realmQuestsComplete = new Dictionary<int, int>();
			if (questSaveData == null)
			{
				activeSaveSlotId = SaveData.CurrentSaveSlot.uniqueId;
				HasLoaded = true;
				return;
			}
			if (questSaveData.questRealms != null)
			{
				for (int i = 0; i < questSaveData.questRealms.Count; i++)
				{
					QuestSaveRealm questSaveRealm = questSaveData.questRealms[i];
					int realmId = questSaveRealm.realmId;
					allSideQuests[realmId] = new List<Quest>();
					if (questSaveRealm.questSaves != null)
					{
						for (int j = 0; j < questSaveRealm.questSaves.Count; j++)
						{
							if (!string.IsNullOrEmpty(questSaveRealm.questSaves[j].questgiver))
							{
								allSideQuests[questSaveRealm.realmId].Add(new Quest(questSaveRealm.questSaves[j], (RealmData.RealmId)realmId, isRealmQuest: false));
							}
						}
					}
					if (questSaveRealm.activeRealmQuest != null && !string.IsNullOrEmpty(questSaveRealm.activeRealmQuest.questgiver))
					{
						realmQuests[realmId] = new Quest(questSaveRealm.activeRealmQuest, (RealmData.RealmId)realmId, isRealmQuest: true);
					}
					realmQuestsComplete[realmId] = questSaveRealm.realmQuestProgress;
				}
			}
			if (questSaveData.hiddenQuestSaves != null)
			{
				foreach (QuestSaveData hiddenQuestSafe in questSaveData.hiddenQuestSaves)
				{
					if (hiddenQuestSafe.status != 0)
					{
						hiddenQuests.Add(new Quest(hiddenQuestSafe, (RealmData.RealmId)hiddenQuestSafe.hiddenQuestRealmId, isRealmQuest: true));
					}
				}
			}
			if (!string.IsNullOrEmpty(questSaveData.questflags))
			{
				unlockedQuestFlags = new List<string>(questSaveData.questflags.Split(','));
			}
			activeSaveSlotId = SaveData.CurrentSaveSlot.uniqueId;
			HasLoaded = true;
		}

		private void OnDestroy()
		{
			SaveData.RemovePreSaveMainThreadTask(FlushSave);
			ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Remove(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
			if (SingletonBehaviour<PlayerStatus>.InstanceExists())
			{
				PlayerStatus instance = SingletonBehaviour<PlayerStatus>.Instance;
				instance.OnItemEnterPlayerOwnership = (Action<Item>)Delegate.Remove(instance.OnItemEnterPlayerOwnership, new Action<Item>(OnItemEnteredPlayerControl));
				PlayerStatus instance2 = SingletonBehaviour<PlayerStatus>.Instance;
				instance2.OnItemExitPlayerOwnership = (Action<Item>)Delegate.Remove(instance2.OnItemExitPlayerOwnership, new Action<Item>(OnItemExitedPlayerControl));
			}
		}

		private void FlushSave(FateSaveData saveData)
		{
			if (SaveData.CurrentSaveSlot == null || SaveData.CurrentSaveSlot.saveState != 0 || activeSaveSlotId != SaveData.CurrentSaveSlot.uniqueId)
			{
				return;
			}
			List<QuestSaveRealm> list = new List<QuestSaveRealm>();
			foreach (KeyValuePair<int, List<Quest>> allSideQuest in allSideQuests)
			{
				List<QuestSaveData> list2 = new List<QuestSaveData>();
				for (int i = 0; i < allSideQuest.Value.Count; i++)
				{
					if (allSideQuest.Value[i] != null)
					{
						Quest quest = allSideQuest.Value[i];
						QuestSaveData questSaveData = new QuestSaveData
						{
							status = quest.Status,
							questId = quest.QuestId,
							questgiver = quest.QuestGiverName,
							questLevel = quest.QuestLevel,
							goldReward = quest.GoldReward,
							xpReward = quest.XPReward,
							fameReward = quest.FameReward,
							heroType = quest.heroItemType,
							questItem = quest.questItem,
							targetCount = quest.TargetCount,
							originalTargetCount = quest.OriginalTargetCount,
							minionMonsterId = ((quest.MinionData != null) ? quest.MinionData.displayName : null),
							wardInfo = quest.questWard,
							rewardItem = quest.ItemReward?.GetItemSave(),
							hasPlayedCompleteSound = quest.hasPlayedCompleteSound
						};
						if (quest.uniqueQuestMonster != null && (quest.questMonsters == null || quest.questMonsters.Count == 0))
						{
							questSaveData.monsterInfo = new Quest.MonsterTemplate[1] { quest.uniqueQuestMonster };
						}
						else if (quest.questMonsters != null && quest.questMonsters.Count > 0)
						{
							questSaveData.monsterInfo = quest.questMonsters.ToArray();
						}
						list2.Add(questSaveData);
					}
				}
				QuestSaveRealm item = new QuestSaveRealm
				{
					questSaves = list2,
					realmId = allSideQuest.Key,
					realmQuestProgress = -1
				};
				list.Add(item);
			}
			foreach (KeyValuePair<int, Quest> kvp2 in realmQuests)
			{
				int realmQuestProgress = (realmQuestsComplete.ContainsKey(kvp2.Key) ? realmQuestsComplete[kvp2.Key] : (-1));
				QuestSaveRealm questSaveRealm = list.Find((QuestSaveRealm a) => a.realmId == kvp2.Key);
				if (questSaveRealm != null)
				{
					questSaveRealm.realmQuestProgress = realmQuestProgress;
				}
				else
				{
					questSaveRealm = new QuestSaveRealm
					{
						realmId = kvp2.Key,
						realmQuestProgress = realmQuestProgress,
						questSaves = null
					};
					list.Add(questSaveRealm);
				}
				Quest quest2 = (realmQuests.ContainsKey(kvp2.Key) ? realmQuests[kvp2.Key] : null);
				if (quest2 != null)
				{
					questSaveRealm.activeRealmQuest = new QuestSaveData
					{
						status = quest2.Status,
						questId = quest2.QuestId,
						questgiver = quest2.QuestGiverName,
						questLevel = quest2.QuestLevel,
						goldReward = quest2.GoldReward,
						xpReward = quest2.XPReward,
						fameReward = quest2.FameReward,
						heroType = quest2.heroItemType,
						questItem = quest2.questItem,
						targetCount = quest2.TargetCount,
						originalTargetCount = quest2.OriginalTargetCount,
						minionMonsterId = ((quest2.MinionData != null) ? quest2.MinionData.displayName : null),
						wardInfo = quest2.questWard,
						rewardItem = quest2.ItemReward?.GetItemSave(),
						monsterInfo = ((quest2.questMonsters != null && quest2.questMonsters.Count != 0) ? quest2.questMonsters.ToArray() : new Quest.MonsterTemplate[1] { quest2.uniqueQuestMonster }),
						hasPlayedCompleteSound = quest2.hasPlayedCompleteSound
					};
				}
			}
			foreach (KeyValuePair<int, int> kvp in realmQuestsComplete)
			{
				int value = kvp.Value;
				QuestSaveRealm questSaveRealm2 = list.Find((QuestSaveRealm a) => a.realmId == kvp.Key);
				if (questSaveRealm2 != null)
				{
					questSaveRealm2.realmQuestProgress = value;
					continue;
				}
				questSaveRealm2 = new QuestSaveRealm
				{
					realmId = kvp.Key,
					realmQuestProgress = value,
					questSaves = null
				};
				list.Add(questSaveRealm2);
			}
			List<QuestSaveData> list3 = null;
			if (hiddenQuests != null && hiddenQuests.Count > 0)
			{
				list3 = new List<QuestSaveData>();
				foreach (Quest hiddenQuest in hiddenQuests)
				{
					QuestSaveData questSaveData2 = new QuestSaveData
					{
						status = hiddenQuest.Status,
						questId = hiddenQuest.QuestId,
						questgiver = hiddenQuest.QuestGiverName,
						questLevel = hiddenQuest.QuestLevel,
						goldReward = hiddenQuest.GoldReward,
						xpReward = hiddenQuest.XPReward,
						fameReward = hiddenQuest.FameReward,
						heroType = hiddenQuest.heroItemType,
						targetCount = hiddenQuest.TargetCount,
						originalTargetCount = hiddenQuest.OriginalTargetCount,
						minionMonsterId = ((hiddenQuest.MinionData != null) ? hiddenQuest.MinionData.displayName : null),
						wardInfo = hiddenQuest.questWard,
						rewardItem = hiddenQuest.ItemReward?.GetItemSave(),
						hiddenQuestRealmId = (int)hiddenQuest.RealmId,
						hasPlayedCompleteSound = hiddenQuest.hasPlayedCompleteSound
					};
					if (hiddenQuest.uniqueQuestMonster != null)
					{
						questSaveData2.monsterInfo = new Quest.MonsterTemplate[1] { hiddenQuest.uniqueQuestMonster };
					}
					else if (hiddenQuest.questMonsters != null && hiddenQuest.questMonsters.Count > 0)
					{
						questSaveData2.monsterInfo = hiddenQuest.questMonsters.ToArray();
					}
					list3.Add(questSaveData2);
				}
			}
			if (saveData.questSaveData == null)
			{
				saveData.questSaveData = new QuestStorage
				{
					questRealms = list,
					hiddenQuestSaves = list3,
					questflags = string.Join(",", unlockedQuestFlags)
				};
			}
			else
			{
				saveData.questSaveData.questRealms = list;
				saveData.questSaveData.hiddenQuestSaves = list3;
				saveData.questSaveData.questflags = string.Join(",", unlockedQuestFlags);
			}
		}
	}
	public class RealmQuestGiver : Character
	{
		public enum PostQuestBehavior
		{
			Nothing,
			Greeting,
			Retire
		}

		public RealmQuest[] realmQuests;

		public GameObject normalIcon;

		public GameObject doneIcon;

		public GameObject noQuestIcon;

		public ExclamationMark exclamationMark;

		public bool hasInitialGreeting;

		public string overrideLockedMessageKey;

		public PostQuestBehavior postQuestBehavior;

		private GameObject spawnedIcon;

		private Camera mainCamera;

		private NpcVoiceLines npcVoiceLines;

		public Quest ActiveQuest { get; private set; }

		public override void Init()
		{
			base.Init();
			isQuestGiver = true;
			invincible = true;
			base.CharacterName = npcVoiceLines.thisNpc.ToString();
			alignment = Alignment.Good;
			mainCamera = Camera.main;
			SetIcon();
		}

		private void Awake()
		{
			npcVoiceLines = GetComponent<NpcVoiceLines>();
			Init();
		}

		private IEnumerator Start()
		{
			while (Player.PlayerChar == null || !SingletonBehaviour<QuestManager>.InstanceExists() || !SingletonBehaviour<QuestManager>.Instance.HasLoaded)
			{
				yield return null;
			}
			ResolveRealmQuest();
		}

		private void OnEnable()
		{
			if (!(Player.PlayerChar == null) && SingletonBehaviour<QuestManager>.InstanceExists() && SingletonBehaviour<QuestManager>.Instance.HasLoaded && ActiveQuest == null)
			{
				ResolveRealmQuest();
			}
		}

		public string GetLockedText()
		{
			(bool, List<string>) tuple = IsQuestLocked();
			if (!string.IsNullOrEmpty(overrideLockedMessageKey))
			{
				return I2Loca.GetReplaceTags(overrideLockedMessageKey);
			}
			return I2Loca.GetFormatReplaceTags("MasterQuest_Locked", SingletonBehaviour<QuestManager>.Instance.GetRealmNeededStringForMQ(tuple.Item2));
		}

		public void ResolveRealmQuest()
		{
			if (realmQuests != null && realmQuests.Length != 0)
			{
				ActiveQuest = SingletonBehaviour<QuestManager>.Instance.GetNextOrActiveRealmQuest(realmQuests, base.CharacterName, realmQuests[0].targetRealm);
				SetIcon();
			}
		}

		public bool HasDoneAllQuests()
		{
			if (realmQuests == null || realmQuests.Length == 0)
			{
				return true;
			}
			return SingletonBehaviour<QuestManager>.Instance.HasCompleted(realmQuests);
		}

		public (bool locked, List<string> keysReq) IsQuestLocked()
		{
			if (ActiveQuest != null)
			{
				if (ActiveQuest.Status == Quest.QuestStatus.None && !SingletonBehaviour<QuestManager>.Instance.HasFlags(ActiveQuest.realmQuestData.keysRequired))
				{
					return (locked: true, keysReq: ActiveQuest.realmQuestData.keysRequired);
				}
				return (locked: false, keysReq: null);
			}
			if (realmQuests != null && realmQuests.Length != 0)
			{
				for (int i = 0; i < realmQuests.Length; i++)
				{
					if (!SingletonBehaviour<QuestManager>.Instance.HasFlags(realmQuests[i].keysRequired))
					{
						return (locked: true, keysReq: realmQuests[i].keysRequired);
					}
				}
			}
			return (locked: false, keysReq: null);
		}

		public void SetIcon()
		{
			if (spawnedIcon != null)
			{
				UnityEngine.Object.Destroy(spawnedIcon);
			}
			if (SaveData.CurrentSaveData == null)
			{
				return;
			}
			if (hasInitialGreeting && !SaveData.CurrentSaveData.HasDoneInitialGreeting())
			{
				exclamationMark.SetExclamationTexture(ExclamationMark.MarkType.QuestAvailable);
				exclamationMark.gameObject.SetActive(value: true);
				return;
			}
			RealmData.RealmId realm = ((realmQuests != null && realmQuests.Length != 0) ? realmQuests[0].targetRealm : SingletonBehaviour<PlayerStatus>.Instance.TownRealm);
			switch ((ActiveQuest != null) ? ActiveQuest.Status : SingletonBehaviour<QuestManager>.Instance.GetQuestStatus((int)realm, base.CharacterName))
			{
			case Quest.QuestStatus.None:
				if (ActiveQuest != null && SingletonBehaviour<QuestManager>.Instance.HasFlags(ActiveQuest.realmQuestData.keysRequired))
				{
					exclamationMark.SetExclamationTexture(ExclamationMark.MarkType.QuestAvailable);
					exclamationMark.gameObject.SetActive(value: true);
					spawnedIcon = UnityEngine.Object.Instantiate(normalIcon, base.transform.position, Quaternion.Euler(115f, mainCamera.transform.eulerAngles.y, 0f), base.transform);
				}
				else
				{
					exclamationMark.gameObject.SetActive(value: false);
				}
				break;
			case Quest.QuestStatus.Accepted:
			case Quest.QuestStatus.InProgress:
				exclamationMark.SetExclamationTexture(ExclamationMark.MarkType.QuestActive);
				exclamationMark.gameObject.SetActive(value: true);
				spawnedIcon = UnityEngine.Object.Instantiate(noQuestIcon, base.transform.position, Quaternion.Euler(135f, mainCamera.transform.eulerAngles.y, 0f), base.transform);
				break;
			case Quest.QuestStatus.Completed:
				exclamationMark.SetExclamationTexture(ExclamationMark.MarkType.Default);
				exclamationMark.gameObject.SetActive(value: true);
				spawnedIcon = UnityEngine.Object.Instantiate(doneIcon, base.transform.position, Quaternion.Euler(135f, mainCamera.transform.eulerAngles.y, 0f), base.transform);
				break;
			default:
				exclamationMark.gameObject.SetActive(value: false);
				break;
			}
		}

		protected override void Update()
		{
		}

		public override void UpdateAI()
		{
		}
	}
	public class Shrine : Monster
	{
		public TextMeshProUGUI timerText;

		public GameObject timerParent;

		[SerializeField]
		private bool isEvil;

		[SerializeField]
		private Collider interactCollider;

		[SerializeField]
		private GameObject wholeGO;

		[SerializeField]
		private GameObject brokenGO;

		[SerializeField]
		private Rigidbody[] brokenRigidBodies;

		[SerializeField]
		private GameObject navMeshBlocker;

		public Quest ConnectedQuest { get; private set; }

		public override void Init()
		{
			base.Init();
			alignment = Alignment.Neutral;
			invincible = true;
			base.gameObject.layer = LayerMask.NameToLayer("Default");
			interactCollider.enabled = false;
			timerParent.SetActive(value: false);
			if (navMeshBlocker != null)
			{
				navMeshBlocker.SetActive(value: false);
			}
			if (TryGetComponent<ShrineInteractable>(out var component))
			{
				component.MakeInteractable(interactable: false);
			}
			LevelGenerator.onQuestValidationComplete = (Action)Delegate.Combine(LevelGenerator.onQuestValidationComplete, new Action(OnQuestValidationComplete));
		}

		public void ConnectToQuest(Quest quest)
		{
			ConnectedQuest = quest;
			isEvil = quest.QuestType == QuestData.QuestType.Deluge;
			alignment = Alignment.Neutral;
			invincible = true;
			base.gameObject.layer = (quest.Completed ? LayerMask.NameToLayer("Default") : LayerMask.NameToLayer("Player Interactable"));
			interactCollider.enabled = !quest.Completed;
			if (TryGetComponent<ShrineInteractable>(out var component))
			{
				component.MakeInteractable(!quest.Completed);
			}
			if (navMeshBlocker != null)
			{
				navMeshBlocker.SetActive(value: true);
			}
		}

		private void OnQuestValidationComplete()
		{
			if (ConnectedQuest == null && isEvil)
			{
				InstantBreak();
			}
			if (navMeshBlocker != null)
			{
				navMeshBlocker.SetActive(value: false);
			}
		}

		private void InstantBreak()
		{
			if (wholeGO != null)
			{
				wholeGO.SetActive(value: false);
			}
			if (brokenGO != null)
			{
				brokenGO.SetActive(value: true);
				Rigidbody[] array = brokenRigidBodies;
				for (int i = 0; i < array.Length; i++)
				{
					array[i].gameObject.SetActive(value: false);
				}
			}
		}

		protected override void OnDestroy()
		{
			CharacterVitals characterVitals = myVitals;
			characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(RespondToAttack));
			LevelGenerator.onQuestValidationComplete = (Action)Delegate.Remove(LevelGenerator.onQuestValidationComplete, new Action(OnQuestValidationComplete));
		}

		public override void UpdateAI()
		{
			if (eAIState == AIState.InEvent)
			{
				InEventAI();
			}
		}

		private void InEventAI()
		{
			if (GetPetCount() < Fate.MaxSummons)
			{
				mana = MaxMana();
				base.castTimer = 0f;
				SelectSummonSpell();
				if (activeSpell != null && HasSpellCosts(activeSpell))
				{
					TryCastCurrentSpell();
				}
			}
		}

		public override void SetAIState(AIState newState)
		{
			if (newState != AIState.InEvent && newState != 0 && newState != AIState.Dying && newState != AIState.Dead)
			{
				return;
			}
			base.SetAIState(newState);
			if (ConnectedQuest != null)
			{
				switch (newState)
				{
				case AIState.InEvent:
					AwakenShrine();
					break;
				case AIState.Inactive:
					ResetShrineToIdle();
					break;
				}
			}
		}

		private void ResetShrineToIdle()
		{
			if (!Alive())
			{
				base.MyVitals.Revive();
			}
			hp = MaxHP();
			StopAllCoroutines();
			timerParent.SetActive(value: false);
			if (ConnectedQuest.Status != Quest.QuestStatus.Completed)
			{
				bool wasPaused = Fate.isPaused;
				Fate.SetPause(paused: true);
				GameObject previouslySelectedGO = UtilityTG.GetSelected();
				if (ConnectedQuest != null && ConnectedQuest.QuestType == QuestData.QuestType.Defend)
				{
					SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetFormatReplaceTags("ShrineDefend_Failed", ConnectedQuest.uniqueQuestMonster.uniqueName), delegate
					{
						if (previouslySelectedGO != null)
						{
							UtilityTG.UnityDelay(delegate
							{
								UtilityTG.SetSelected(previouslySelectedGO);
							});
						}
						Fate.SetPause(wasPaused);
					}, twoButtons: false, I2Loca.Get("OK"));
				}
			}
			alignment = Alignment.Neutral;
			invincible = true;
			interactCollider.enabled = true;
			base.gameObject.layer = LayerMask.NameToLayer("Player Interactable");
			if (TryGetComponent<ShrineInteractable>(out var component))
			{
				component.MakeInteractable(interactable: true);
			}
		}

		public void AwakenShrine()
		{
			StopAllCoroutines();
			bool flag = ConnectedQuest.QuestType == QuestData.QuestType.Defend;
			if (flag)
			{
				timerParent.SetActive(value: true);
				StartCoroutine(DoSurvive());
			}
			alignment = (flag ? Alignment.Good : Alignment.Evil);
			invincible = false;
			base.gameObject.layer = (flag ? LayerMask.NameToLayer("Player") : LayerMask.NameToLayer("Player Damagable"));
			if (!flag)
			{
				SingletonBehaviour<InputBroker>.Instance.SetHighlightedTarget(null);
			}
		}

		protected override void RespondToAttack(CharacterVitals.Damage attacker)
		{
		}

		protected IEnumerator DoSurvive()
		{
			TimeSpan aliveTime = TimeSpan.FromSeconds(30.0);
			TimeSpan oneSecond = TimeSpan.FromSeconds(1.0);
			WaitForSeconds secondWait = new WaitForSeconds(1f);
			timerText.text = aliveTime.ToString("mm':'ss");
			while (aliveTime.TotalSeconds > 0.0)
			{
				yield return secondWait;
				aliveTime = aliveTime.Subtract(oneSecond);
				timerText.text = aliveTime.ToString("mm':'ss");
			}
			ConnectedQuest.OnShrineSurvived(base.CharacterName);
			if (ConnectedQuest.QuestType == QuestData.QuestType.Defend)
			{
				SetAIState(AIState.Inactive);
				StopAllCoroutines();
				alignment = Alignment.Neutral;
				invincible = true;
				interactCollider.enabled = false;
				base.gameObject.layer = LayerMask.NameToLayer("Default");
				if (TryGetComponent<ShrineInteractable>(out var component))
				{
					component.MakeInteractable(interactable: false);
				}
			}
			else
			{
				SetAIState(AIState.Inactive);
			}
			timerParent.SetActive(value: false);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Heal, randomizePitch: true);
			GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Charm");
			if (particlePrefab != null)
			{
				UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab, base.transform.position, Quaternion.identity), 1f);
			}
		}

		protected override void Die()
		{
			if (isEvil)
			{
				if (loadedAsDead)
				{
					InstantBreak();
					SetAIState(AIState.Dead);
				}
				else
				{
					base.Die();
					RunDestroyedVisuals();
					SetAIState(AIState.Dead);
				}
			}
			else
			{
				SetAIState(AIState.Inactive);
			}
			if (SingletonBehaviour<QuestManager>.InstanceExists())
			{
				SingletonBehaviour<QuestManager>.Instance.ShrineDestroyed(base.CharacterName);
			}
		}

		public void RunDestroyedVisuals()
		{
			if (!isEvil)
			{
				return;
			}
			StopAllCoroutines();
			timerParent.SetActive(value: false);
			alignment = Alignment.Neutral;
			invincible = true;
			interactCollider.enabled = false;
			GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("Explosion");
			if (particlePrefab != null)
			{
				UnityEngine.Object.Instantiate(particlePrefab, myTransform.position, Quaternion.identity);
			}
			if (wholeGO != null)
			{
				wholeGO.SetActive(value: false);
			}
			if (brokenGO != null)
			{
				brokenGO.SetActive(value: true);
				Rigidbody[] array = brokenRigidBodies;
				for (int i = 0; i < array.Length; i++)
				{
					array[i].AddExplosionForce(1f, base.transform.position, 3f);
				}
			}
		}
	}
