	public class Ward : Monster
	{
		public Quest connectedQuest;

		public void SetQuest(Quest quest)
		{
			connectedQuest = quest;
			if (TryGetComponent<WardInteractable>(out var component))
			{
				component.OnQuestSet(quest);
			}
			if (quest.QuestType == QuestData.QuestType.Herd)
			{
				base.CharacterName = I2Loca.Get(quest.questWard.monsterDataId);
			}
		}

		public override void Init()
		{
			base.Init();
			maxHpBase = 4 * attributes.Vitality + 4 * base.Level + 18;
			hp = MaxHP();
			alignment = Alignment.Neutral;
			invincible = true;
			QuestManager.OnQuestCanceled = (Action<Quest>)Delegate.Combine(QuestManager.OnQuestCanceled, new Action<Quest>(FailedQuest));
		}

		protected override void OnDestroy()
		{
			if (myVitals != null)
			{
				CharacterVitals characterVitals = myVitals;
				characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(RespondToAttack));
			}
			QuestManager.OnQuestCanceled = (Action<Quest>)Delegate.Remove(QuestManager.OnQuestCanceled, new Action<Quest>(FailedQuest));
		}

		public override void UpdateAI()
		{
			if (monsterData == null)
			{
				return;
			}
			KnockBackCheck();
			if (!Alive() || !base.UnderKnockback)
			{
				if (Target() != null && !Target().Alive())
				{
					SetTarget(null);
				}
				if (Target() != null || currentAttack == null)
				{
					SelectAttack();
				}
				switch (eAIState)
				{
				case AIState.Dying:
					DyingAI();
					break;
				case AIState.Inactive:
					alignment = Alignment.Neutral;
					invincible = true;
					base.gameObject.layer = 6;
					SetAIState(AIState.InEvent);
					break;
				case AIState.Wander:
					WanderAI();
					break;
				case AIState.Flee:
				case AIState.PassingOut:
				case AIState.PassedOut:
					SetAIState(AIState.Flee);
					FleeAI();
					break;
				case AIState.GetRange:
					GetRangeAI();
					break;
				case AIState.Attack:
					AttackAI();
					break;
				case AIState.Follow:
					FollowAI();
					break;
				case AIState.Hunt:
					HuntAI();
					break;
				case AIState.UniqueIdle:
					UniqueIdleAI();
					break;
				case AIState.InEvent:
					InEventAI();
					break;
				case AIState.Retire:
					RetireAI();
					break;
				}
			}
		}

		public void InEventAI()
		{
			if (alignment == Alignment.Good || alignment == Alignment.Evil)
			{
				alignment = Alignment.Neutral;
			}
		}

		public override void FollowAI()
		{
			bool flag = false;
			if (HasMaster() && Master().FishingAny() && Pathing() && Target() == null)
			{
				flag = true;
				StopPathing();
			}
			running = false;
			if (GetFinalMoveSpeed() == 0f)
			{
				return;
			}
			if (!Pathing() && UnityEngine.Random.Range(0, 1000) < 2 && HasMaster() && !flag)
			{
				float num = 4.5f;
				SetDestination(UnityEngine.Random.Range(Master().transform.position.x - num, Master().transform.position.x + num), UnityEngine.Random.Range(Master().transform.position.z - num, Master().transform.position.z + num));
			}
			if (!HasMaster() || GetAlignment() == Alignment.Neutral)
			{
				return;
			}
			SetRunning(Master().Running());
			if (Master().stamina < 1f)
			{
				SetRunning(runningState: false);
			}
			Vector3 vector = Master().transform.position - myTransform.position;
			vector.y = 0f;
			float magnitude = vector.magnitude;
			if (magnitude > 7f)
			{
				SetRunning(runningState: true);
			}
			else if (magnitude <= 5f && !Master().Pathing())
			{
				SetRunning(runningState: false);
			}
			if (UnityEngine.Random.Range(0, 1000) < 100 || IsPetNearDeath())
			{
				vector = ((!Pathing()) ? (Master().transform.position - base.transform.position) : (Master().transform.position - finalTargetPosition));
				vector.y = 0f;
				magnitude = vector.magnitude;
				if ((IsPetNearDeath() && !Pathing()) || (magnitude > 5f && timeSincePath > 0.25f))
				{
					SetRunning(runningState: true);
					float num2 = 4.5f;
					SetDestination(UnityEngine.Random.Range(Master().transform.position.x - num2, Master().transform.position.x + num2), UnityEngine.Random.Range(Master().transform.position.z - num2, Master().transform.position.z + num2));
				}
			}
		}

		public void RetireAI()
		{
			if (Pathing())
			{
				return;
			}
			if (LevelGenerator.currentInstance != null)
			{
				Vector3 vector = LevelGenerator.currentInstance.PositionNearStairsUp();
				vector.y = 0f;
				Vector3 vector2 = LevelGenerator.currentInstance.RandomOpenPosition();
				int num = 0;
				while ((vector2 - vector).magnitude < 24f && num < 100)
				{
					vector2 = LevelGenerator.currentInstance.RandomOpenPosition();
					num++;
				}
				SetDestination(vector2.x, vector2.z);
			}
			else
			{
				SetDestination(UnityEngine.Random.Range(myTransform.position.x - 100f, myTransform.position.x + 100f), UnityEngine.Random.Range(myTransform.position.z - 100f, myTransform.position.z + 100f));
			}
			StartCoroutine(FinishRetirement());
		}

		protected override void RespondToAttack(CharacterVitals.Damage attacker)
		{
			_ = eAIState;
			_ = 21;
		}

		public IEnumerator FinishRetirement()
		{
			yield return new WaitForSeconds(10f);
			if (LevelGenerator.currentInstance != null)
			{
				LevelGenerator.currentInstance.RemoveActiveCharacter(base.gameObject);
			}
			UnityEngine.Object.Destroy(base.gameObject);
		}

		public void FailedQuest(Quest quest)
		{
			SetAIState(AIState.Retire);
		}
	}
	public class WardInteractable : InteractableSceneObject
	{
		protected Ward ward;

		private void Start()
		{
			if (!TryGetComponent<Ward>(out ward))
			{
				throw new ArgumentNullException(base.name, "The Monster has WardInteractable but no Ward script");
			}
			base.InteractableName = ward.CharacterName;
		}

		public void OnQuestSet(Quest quest)
		{
			if (ward == null)
			{
				ward = GetComponent<Ward>();
			}
			if (quest.QuestType == QuestData.QuestType.EscortIn || ward.GetAIState() == AIState.Follow || ward.GetAIState() == AIState.Retire)
			{
				base.enabled = false;
				base.gameObject.layer = 3;
				CanInteract = false;
			}
			else
			{
				base.gameObject.layer = 6;
				CanInteract = true;
			}
		}

		public override void Interact(Character interactor = null)
		{
			if (ward.connectedQuest.QuestType == QuestData.QuestType.EscortOut)
			{
				ward.HandleInteractedWith(interactor);
				ward.SetMasterCharacter(Player.PlayerChar);
				ward.SetAIState(AIState.Follow);
				ward.connectedQuest.Status = Quest.QuestStatus.InProgress;
				base.enabled = false;
			}
			else if (ward.connectedQuest.QuestType == QuestData.QuestType.Herd)
			{
				ward.connectedQuest.OnWardInteracted(ward);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClipOnLocation(AudioData.AudioClipName.FishPoleThrow, ward.transform.localPosition);
				GameObject particlePrefab = SingletonBehaviour<FateDB>.Instance.GetParticlePrefab("summonMonster");
				if (particlePrefab != null)
				{
					UnityEngine.Object.Destroy(UnityEngine.Object.Instantiate(particlePrefab, ward.myTransform.position, Quaternion.identity), 2f);
				}
				if (LevelGenerator.currentInstance != null)
				{
					LevelGenerator.currentInstance.RemoveActiveCharacter(ward.gameObject);
				}
				UnityEngine.Object.Destroy(ward.gameObject);
				SimpleSingletonBehaviour<PlayerUI>.Instance.HideTarget();
			}
		}
	}
	public class Spell : MonoBehaviour
	{
		private Transform myTransform;

		private Transform targetTransform;

		private Vector3 targetPosition;

		private Vector3 targetDirection;

		private SpellData spellData;

		private Character caster;

		private bool casting;

		private float baseRange;

		private float duration;

		private Alignment targetAlignment;

		public void Setup(SpellData spellData, Character caster, float duration = 0f)
		{
			this.spellData = spellData;
			this.caster = caster;
			this.duration = duration;
			ParticleSystem componentInChildren = GetComponentInChildren<ParticleSystem>();
			if (componentInChildren != null)
			{
				ParticleSystem.MainModule main = componentInChildren.main;
				main.loop = true;
				this.duration = Mathf.Max(this.duration, main.duration);
			}
			this.duration = Mathf.Max(this.duration, 1f);
			myTransform = base.transform;
			SphereCollider component = GetComponent<SphereCollider>();
			if (component != null)
			{
				baseRange = component.radius;
			}
			switch (spellData.targetAlignment)
			{
			case Alignment.Good:
			case Alignment.Neutral:
				targetAlignment = caster.GetAlignment();
				break;
			case Alignment.None:
			case Alignment.Evil:
			{
				Alignment alignment = caster.GetAlignment();
				switch (alignment)
				{
				case Alignment.Evil:
					targetAlignment = Alignment.Good;
					break;
				case Alignment.Good:
					targetAlignment = Alignment.Evil;
					break;
				default:
					UnityEngine.Debug.LogError("Unhandled cast alignment: Caster: " + alignment.ToString() + " Spell: " + spellData.targetAlignment);
					break;
				}
				break;
			}
			case Alignment.All:
				targetAlignment = Alignment.All;
				break;
			}
		}

		public void SetTarget(Character target)
		{
			targetTransform = target.myTransform;
			targetPosition = targetTransform.position;
			targetDirection = (targetPosition - myTransform.position).normalized;
		}

		public void SetTarget(Vector3 pos)
		{
			targetPosition = pos;
			targetDirection = (targetPosition - myTransform.position).normalized;
		}

		public void StartCast()
		{
			casting = true;
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(spellData.castSoundName, randomizePitch: true);
			if (spellData.sfx == null)
			{
				UnityEngine.Debug.LogWarning("No sfx found for " + spellData.spellName);
				UnityEngine.Object.Destroy(base.gameObject, 0.5f);
				return;
			}
			ItemTarget targetType = spellData.targetType;
			if ((uint)(targetType - 19) <= 1u)
			{
				UnityEngine.Debug.LogError("Projectiles should no longer be handled by this class");
			}
			else
			{
				StartCoroutine(SpellLifeDuration());
			}
		}

		private IEnumerator SpellLifeDuration()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(spellData.successSoundName, 0.3f);
			float maxLife = duration;
			while (maxLife > 0f)
			{
				maxLife -= Time.deltaTime;
				yield return null;
			}
			ParticleSystem componentInChildren = GetComponentInChildren<ParticleSystem>();
			if (componentInChildren != null)
			{
				componentInChildren.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
				UnityEngine.Object.Destroy(base.gameObject, 0.5f);
			}
			else
			{
				UnityEngine.Object.Destroy(base.gameObject, 0.1f);
			}
			casting = false;
		}

		private void OnDrawGizmos()
		{
			if (casting && spellData != null)
			{
				Gizmos.DrawSphere(myTransform.position, baseRange + (float)spellData.range * 0.25f);
			}
		}

		private void OnTriggerEnter(Collider other)
		{
		}
	}
