	public class SpellArea : MonoBehaviour
	{
		private Transform myTransform;

		private SpellAreaData data;

		private float lifeTime;

		public void Setup(SpellAreaData data)
		{
			myTransform = base.transform;
			float num = 0f;
			ParticleSystem[] componentsInChildren = GetComponentsInChildren<ParticleSystem>();
			if (componentsInChildren != null)
			{
				ParticleSystem[] array = componentsInChildren;
				for (int i = 0; i < array.Length; i++)
				{
					ParticleSystem.MainModule main = array[i].main;
					float num2 = (main.loop ? 5f : main.duration);
					if (num2 > num)
					{
						num = num2;
					}
				}
			}
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClipOnLocation(data.spellData.successSoundName, myTransform.position);
			lifeTime = Mathf.Max(data.lifeTime, num);
			lifeTime = Mathf.Max(lifeTime, 1f);
			FateSpellHelpers.PerformAreaSpellImpact(myTransform.position, data.spellData, data.caster, data.targetAlignment, data.targetCharacter);
			ProdigyCamera.Instance.Shake(data.spellData.shakeRange.GetValue());
			StartCoroutine(DoLifeTime(lifeTime));
