			{
				ParticleSystem[] array = componentsInChildren;
				for (int i = 0; i < array.Length; i++)
				{
					array[i].Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
				}
			}
			Renderer[] componentsInChildren2 = GetComponentsInChildren<Renderer>();
			if (componentsInChildren2 != null)
			{
				Renderer[] array2 = componentsInChildren2;
				for (int i = 0; i < array2.Length; i++)
				{
					array2[i].enabled = false;
				}
			}
			UnityEngine.Object.Destroy(base.gameObject, 0.5f);
		}
	}
	public struct SpellProjectileData
	{
		public SpellData spellData;

		public Character caster;

		public Alignment targetAlignment;

		public float lifeTime;

		public float spellDuration;

		public float moveSpeed;

		public float turnRate;

		public Vector3? direction;

		public Vector3? targetPoint;

		public Character targetCharacter;

		public bool followTarget;

		public bool performImpactWhenTimedOut;
	}
	public class SpellProjectile : MonoBehaviour
	{
		private int hitMask;

		private SpellProjectileData data;

		private Transform myTransform;

		private Collider[] hits = new Collider[8];

		public const float collisionRadius = 0.5f;

		private const float targetPointHitRadius = 0.5f;

		private bool chaseEnemy;

		private int seekMask;

		public void Setup(SpellProjectileData data, bool chaserBehaviour = false)
		{
			chaseEnemy = chaserBehaviour;
			myTransform = base.transform;
			if (data.spellData.castSoundName != 0)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(data.spellData.castSoundName, randomizePitch: true);
			}
			_ = data.followTarget;
			this.data = data;
			hitMask = ((data.caster.GetAlignment() == Alignment.Good) ? LayerMask.GetMask("Player Damagable", "Default", "NavMeshBlocker") : LayerMask.GetMask("Player", "Default", "NavMeshBlocker"));
			if (chaseEnemy)
			{
				seekMask = ((data.caster.GetAlignment() == Alignment.Good) ? LayerMask.GetMask("Player Damagable") : LayerMask.GetMask("Player"));
				StartCoroutine(DoLifeTime(data.lifeTime));
				StartCoroutine(DoChaseBehaviour());
				return;
			}
			StartCoroutine(DoLifeTime(data.lifeTime));
			if (data.targetPoint.HasValue)
			{
				StartCoroutine(DoTravelToTargetPoint(data.targetPoint.Value));
			}
			else if (data.targetCharacter != null)
			{
				if (data.followTarget)
				{
					StartCoroutine(DoFollowTarget());
				}
				else if (data.direction.HasValue)
				{
					StartCoroutine(DoTravelInDirection(data.direction.Value));
				}
				else
				{
					StartCoroutine(DoTravelInDirection(data.targetCharacter.myTransform.position - data.caster.myTransform.position));
				}
			}
			else if (data.direction.HasValue)
			{
				StartCoroutine(DoTravelInDirection(data.direction.Value));
			}
			else
			{
				UnityEngine.Debug.LogError(data.spellData.spellName + ": Spell projectile could not determine movement type");
				StopAllCoroutines();
				UnityEngine.Object.Destroy(base.gameObject, 0.5f);
			}
		}

		private IEnumerator DoLifeTime(float lifeTime)
		{
			float deathTime = Time.time + lifeTime;
			if (data.spellData.successSoundName != 0)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(data.spellData.successSoundName, randomizePitch: true);
			}
			while (Time.time < deathTime)
			{
				yield return null;
			}
			if (data.performImpactWhenTimedOut)
			{
				PerformImpact();
			}
			DestroySelf();
		}

		private IEnumerator DoFollowTarget()
		{
			while (!(data.targetCharacter == null))
			{
				Vector3 normalized = (data.targetCharacter.myTransform.position - myTransform.position).normalized;
				myTransform.position += data.moveSpeed * Time.deltaTime * normalized;
				if (PerformCollisionCheck())
				{
					break;
				}
				yield return null;
			}
			PerformImpact();
			DestroySelf();
		}

		private IEnumerator DoChaseBehaviour()
		{
			while (true)
			{
				Vector3 vector = Vector3.zero;
				if (data.targetCharacter != null && data.targetCharacter.Alive())
				{
					vector = data.targetCharacter.myTransform.position;
					data.direction = (vector - myTransform.position).normalized;
				}
				else
				{
					Physics.OverlapSphereNonAlloc(myTransform.position, 5f, hits, seekMask, QueryTriggerInteraction.Ignore);
					bool flag = false;
					Collider[] array = hits;
					foreach (Collider collider in array)
					{
						if (!(collider == null) && collider.gameObject.TryGetComponent<Character>(out var component) && component.Alive())
						{
							data.targetCharacter = component;
							vector = data.targetCharacter.myTransform.position;
							data.direction = (vector - myTransform.position).normalized;
							flag = true;
							break;
						}
					}
					Array.Clear(hits, 0, hits.Length);
					if (!flag)
					{
						vector = myTransform.position + data.direction.Value * 5f;
					}
				}
				float maxRadiansDelta = data.turnRate * Time.deltaTime;
				Vector3 normalized = (vector - myTransform.position).WithY(0f).normalized;
				Vector3 vector2 = Vector3.RotateTowards(myTransform.forward, normalized, maxRadiansDelta, 0f);
				base.transform.rotation = Quaternion.LookRotation(vector2);
				data.direction = vector2;
				myTransform.position += data.moveSpeed * Time.deltaTime * myTransform.forward;
				if (Vector3.Distance(myTransform.position, vector) < 0.5f)
				{
					myTransform.position = vector;
					break;
				}
				if (PerformCollisionCheck())
				{
					break;
				}
				yield return null;
			}
			PerformImpact();
			DestroySelf();
		}

		private IEnumerator DoTravelToTargetPoint(Vector3 targetPoint)
		{
			while (true)
			{
				Vector3 normalized = (targetPoint - myTransform.position).normalized;
				myTransform.position += data.moveSpeed * Time.deltaTime * normalized;
				if (Vector3.Distance(myTransform.position, targetPoint) < 0.5f)
				{
					myTransform.position = targetPoint;
					break;
				}
				if (PerformCollisionCheck())
				{
					break;
				}
				yield return null;
			}
			PerformImpact();
			DestroySelf();
		}

		private IEnumerator DoTravelInDirection(Vector3 direction)
		{
			direction.Normalize();
			while (true)
			{
				myTransform.position += data.moveSpeed * Time.deltaTime * direction;
				if (PerformCollisionCheck())
				{
					break;
				}
				yield return null;
			}
			PerformImpact();
			DestroySelf();
		}

		private bool PerformCollisionCheck()
		{
			Physics.OverlapBoxNonAlloc(myTransform.position, Vector3.one * 0.5f, hits, Quaternion.identity, hitMask);
			Collider[] array = hits;
			foreach (Collider collider in array)
			{
				if (collider == null)
				{
					continue;
				}
				if (collider.gameObject.TryGetComponent<Character>(out var component))
				{
					if (component.GetAlignment() == data.targetAlignment)
					{
						return true;
					}
					continue;
				}
				if (collider.gameObject.TryGetComponent<OpenGateOnTrigger>(out var component2))
				{
					if (!component2.IsDoorOpen)
					{
						return true;
					}
					continue;
				}
				if (collider.gameObject.TryGetComponent<RotateOnTrigger>(out var component3))
				{
					if (!component3.IsDoorOpen)
					{
						return true;
					}
					continue;
				}
				return true;
			}
			return false;
		}

		private void PerformImpact()
		{
			GameObject gameObject = null;
			if (data.spellData.particleImpactPrefab != null)
			{
				gameObject = UnityEngine.Object.Instantiate(data.spellData.particleImpactPrefab, myTransform.position, Quaternion.identity);
			}
			if (data.spellData.strikeSoundName != 0)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClipOnLocation(data.spellData.strikeSoundName, myTransform.position);
			}
			if (gameObject == null)
			{
				UnityEngine.Debug.LogWarning("No impact particle prefab found for " + data.spellData.spellName);
				gameObject = new GameObject("SpellImpact_" + data.spellData.spellName);
			}
			if (data.spellData.range == 0)
			{
				SpellVfxAutoDestroy spellVfxAutoDestroy = gameObject.GetComponent<SpellVfxAutoDestroy>();
				if (spellVfxAutoDestroy == null)
				{
					spellVfxAutoDestroy = gameObject.AddComponent<SpellVfxAutoDestroy>();
				}
				spellVfxAutoDestroy.SetLifeTime(5f);
				Character character = null;
				Collider[] array = hits;
				foreach (Collider collider in array)
				{
					if (!(collider == null))
					{
						if (character == null)
						{
							character = collider.GetComponent<Character>();
						}
						if (collider.gameObject.TryGetComponent<ContainerDestroyable>(out var component))
						{
							component.Destroyed();
						}
					}
				}
				ProdigyCamera.Instance.Shake(data.spellData.shakeRange.GetValue());
				if (character != null)
				{
					FateSpellHelpers.PerformSingleTargetSpellImpact(data.spellData, data.caster, data.targetAlignment, character);
				}
			}
			else
			{
				SpellArea spellArea = gameObject.GetComponent<SpellArea>();
				if (spellArea == null)
				{
					spellArea = gameObject.AddComponent<SpellArea>();
				}
				spellArea.Setup(new SpellAreaData
				{
					spellData = data.spellData,
					caster = data.caster,
					targetCharacter = data.targetCharacter,
					targetAlignment = data.targetAlignment,
					lifeTime = data.spellDuration
				});
			}
		}

		private void DestroySelf()
		{
			StopAllCoroutines();
			ParticleSystem[] componentsInChildren = GetComponentsInChildren<ParticleSystem>();
			if (componentsInChildren != null)
			{
				ParticleSystem[] array = componentsInChildren;
				for (int i = 0; i < array.Length; i++)
				{
					array[i].Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
				}
			}
			Renderer[] componentsInChildren2 = GetComponentsInChildren<Renderer>();
			if (componentsInChildren2 != null)
			{
				Renderer[] array2 = componentsInChildren2;
				for (int i = 0; i < array2.Length; i++)
				{
					array2[i].enabled = false;
				}
			}
			UnityEngine.Object.Destroy(base.gameObject, 0.5f);
		}
	}
