	public class Town : SingletonBehaviour<Town>
	{
		public enum EntryMethod
		{
			None,
			Stairs,
			TownPortal,
			RealmPortal
		}

		public static int SpawnPointIndex;

		private const string defaultDungeonName = "Dungeon_Generic";

		public RealmData realmData;

		public PlayerSpawn playerSpawner;

		public Transform[] possibleSpawnPoints;

		[SerializeField]
		private Transform activeContainersParent;

		[SerializeField]
		private string dungeonName;

		public AudioData.AudioClipName stepSound;

		private AudioSource audioSource;

		protected override bool DontDestroy => false;

		public RealmData.RealmId RealmId => realmData.realmId;

		public Transform GetActiveContainersParent => activeContainersParent;

		public string DungeonName
		{
			get
			{
				if (!string.IsNullOrEmpty(dungeonName))
				{
					return I2Loca.Get(dungeonName);
				}
				return I2Loca.GetFormat("Dungeon_Generic", Fate.GetRealmName(RealmId, preferShortName: true));
			}
		}

		public string TownName => Fate.GetRealmName(RealmId, preferShortName: false);

		protected override void Init()
		{
			ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Combine(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
			SingletonBehaviour<PlayerStatus>.Instance.TownRealm = RealmId;
			if (activeContainersParent == null)
			{
				UnityEngine.Debug.LogWarning("Active containers parent not set. Creating one as a backup.");
				GameObject gameObject = new GameObject("_ActiveContainersParent");
				gameObject.transform.SetParent(base.transform);
				gameObject.transform.SetLocalPositionAndRotation(Vector3.zero, Quaternion.identity);
				activeContainersParent = gameObject.transform;
			}
			SaveData.AddPreSaveMainThreadTask(PreSave);
			if (SingletonBehaviour<AudioManager>.InstanceExists())
			{
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.StopAllSoundFx();
			}
			QuestManager.OnQuestAccepted = (Action<Quest>)Delegate.Combine(QuestManager.OnQuestAccepted, new Action<Quest>(QuestAccepted));
		}

		private void Start()
		{
			if (SpawnPointIndex < 0 || SpawnPointIndex >= possibleSpawnPoints.Length)
			{
				UnityEngine.Debug.LogError($"Spawn point index is out of range. Spawn point array is {possibleSpawnPoints.Length} long, index is {SpawnPointIndex}. Setting spawn point index to 0.");
				SpawnPointIndex = 0;
			}
			Vector3 spawnPos = possibleSpawnPoints[SpawnPointIndex].position;
			if (NavMesh.SamplePosition(spawnPos, out var hit, 10f, -1))
			{
				spawnPos = hit.position;
			}
			else
			{
				UnityEngine.Debug.LogError($"Player spawn: Could not find valid nav mesh point based on world position {spawnPos} in, SceneLoad.Current scene is {SceneLoad.CurrentScene}");
			}
			PlayerSaveData playerSaveData;
			if (Player.isComingFromMenu)
			{
				playerSaveData = SaveData.CurrentSaveData.playerSaveData;
				if (playerSaveData.lastScene != 0 && playerSaveData.lastScene != SceneLoad.CurrentScene)
				{
					RealmData.RealmId realmId = Fate.GetRealmFromScene(playerSaveData.lastScene);
					if (realmId == RealmData.RealmId.ANY)
					{
						realmId = playerSaveData.lastDungeonRealm;
					}
					if (realmId == RealmData.RealmId.ANY)
					{
						NormalEnterTown(comingFromMenu: true);
						return;
					}
					(bool, Fate.DLC) dLCInfoForRealm = SingletonBehaviour<DLCManager>.Instance.GetDLCInfoForRealm(realmId);
					if (dLCInfoForRealm.Item1)
					{
						bool wasComingFromMenu = Player.isComingFromMenu;
						SingletonBehaviour<DLCManager>.Instance.HasEntitlement(dLCInfoForRealm.Item2, delegate(bool hasEntitlement)
						{
							if (hasEntitlement)
							{
								ShuttlePlayerToLastScene();
							}
							else
							{
								playerSaveData.lastDungeonRealm = RealmData.RealmId.ANY;
								playerSaveData.lastScene = SceneLoad.CurrentScene;
								spawnPos = possibleSpawnPoints[0].position;
								playerSaveData.posInLastScene = spawnPos;
								NormalEnterTown(wasComingFromMenu);
							}
						});
					}
					else
					{
						ShuttlePlayerToLastScene();
					}
					return;
				}
			}
			NormalEnterTown(Player.isComingFromMenu);
			void NormalEnterTown(bool comingFromMenu)
			{
				SingletonBehaviour<DLCManager>.Instance.OnEnteredTown(RealmId, comingFromMenu, delegate
				{
					playerSpawner.SpawnPlayer(spawnPos);
					SingletonBehaviour<LoadingScreenUI>.Instance.HideLoading(fadeOut: true);
					SingletonBehaviour<SystemOverlay>.Instance.FadeToClear(null, ignoreIfAlreadyClear: true);
					if (SingletonBehaviour<PlayerUI>.InstanceExists())
					{
						SimpleSingletonBehaviour<PlayerUI>.Instance.SetLocationText(TownName);
						if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryInitialized)
						{
							LoadDroppedItems();
						}
						else
						{
							PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
							instance.OnInventoryInit = (Action)Delegate.Combine(instance.OnInventoryInit, new Action(LoadDroppedItems));
						}
					}
					audioSource = GetComponent<AudioSource>();
					if ((Fate.CurrentFateVer == Fate.FateVer.UndiscoveredRealms && SingletonBehaviour<PlayerStatus>.Instance.TownRealm == RealmData.RealmId.TempleOfFate) || SingletonBehaviour<PlayerStatus>.Instance.TownRealm == RealmData.RealmId.Grove)
					{
						if (audioSource != null)
						{
							audioSource.Stop();
						}
						SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.MusicTempleFate2, stopOthers: true);
					}
				});
			}
			void ShuttlePlayerToLastScene()
			{
				SingletonBehaviour<LoadingScreenUI>.Instance.ShowLoading(fadeIn: false);
				SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm = playerSaveData.lastDungeonRealm;
				SingletonBehaviour<PlayerStatus>.Instance.TownRealm = Fate.GetDungeonTownRealm(playerSaveData.lastDungeonRealm);
				SceneLoad.LoadAsync(playerSaveData.lastScene, save: false, withLoadingScreen: false, delegate
				{
					SingletonBehaviour<LoadingScreenUI>.Instance.HideLoading(fadeOut: true);
				});
			}
		}

		private void LoadDroppedItems()
		{
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.OnInventoryInit = (Action)Delegate.Remove(instance.OnInventoryInit, new Action(LoadDroppedItems));
			}
			RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(RealmId);
			if (realmSave == null || realmSave.droppedItems == null)
			{
				return;
			}
			foreach (DroppedItemSaveData droppedItemSave in realmSave.droppedItems)
			{
				ItemData itemData = SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData a) => a.displayName == droppedItemSave.item.baseName);
				if (itemData == null)
				{
					UnityEngine.Debug.LogError("Unable to find item info: " + droppedItemSave.item.baseName);
					continue;
				}
				Item item = new Item(itemData);
				item.ApplyInstance(droppedItemSave.item);
				DroppedItem droppedItemGO = FateDB.GetDroppedItemGO();
				droppedItemGO.transform.SetParent(GetActiveContainersParent);
				droppedItemGO.Drop(item, droppedItemSave.position, droppedItemSave.position, skipSoundAndDropTween: true);
			}
		}

		private void QuestAccepted(Quest quest)
		{
			if (quest.QuestType == QuestData.QuestType.EscortIn)
			{
				SpawnWard(quest);
			}
		}

		private void OnDestroy()
		{
			SaveData.RemovePreSaveMainThreadTask(PreSave);
			ProdigyPlayer.OnAvatarSet = (Action<ProdigyPlayer, ProdigyAgent>)Delegate.Remove(ProdigyPlayer.OnAvatarSet, new Action<ProdigyPlayer, ProdigyAgent>(OnAvatarSpawn));
			QuestManager.OnQuestAccepted = (Action<Quest>)Delegate.Remove(QuestManager.OnQuestAccepted, new Action<Quest>(QuestAccepted));
		}

		private void OnAvatarSpawn(ProdigyPlayer player, ProdigyAgent agent)
		{
			Fate.SetPause(paused: false);
			SingletonBehaviour<QuestManager>.Instance.ReachedTown();
			SingletonBehaviour<QuestManager>.Instance.OnQuestHubEntered((int)RealmId);
			List<Quest> allQuests = SingletonBehaviour<QuestManager>.Instance.GetAllQuests();
			for (int i = 0; i < allQuests.Count; i++)
			{
				if (allQuests[i] != null && ((allQuests[i].Status == Quest.QuestStatus.InProgress && allQuests[i].QuestType == QuestData.QuestType.EscortOut) || (allQuests[i].Status == Quest.QuestStatus.Accepted && allQuests[i].QuestType == QuestData.QuestType.EscortIn)))
				{
					SpawnWard(allQuests[i]);
				}
			}
			SingletonBehaviour<MerchantData>.Instance.UpdateRandomizerTables();
			StartCoroutine(AssertUnstuck(agent.GetComponent<NavMeshAgent>()));
		}

		private IEnumerator AssertUnstuck(NavMeshAgent targetAgent)
		{
			if (targetAgent == null)
			{
				yield break;
			}
			float graceTimer = 5f;
			while (graceTimer > 0f)
			{
				graceTimer -= Time.deltaTime;
				yield return null;
				if (targetAgent.isOnNavMesh)
				{
					yield break;
				}
			}
			UnityEngine.Debug.Log("Agent considered stuck, teleporting to Town center");
			Player.PlayerChar.TeleportToPosition(possibleSpawnPoints[0].position);
			SaveData.CurrentSaveData.playerSaveData.posInLastScene = possibleSpawnPoints[0].position;
		}

		private void SpawnWard(Quest quest)
		{
			if (quest == null || quest.questWard == null)
			{
				return;
			}
			Quest.MonsterTemplate questWard = quest.questWard;
			MonsterData monsterData = null;
			if (Fate.CurrentFateVer != Fate.FateVer.CursedKing && questWard.targetRealm != SingletonBehaviour<PlayerStatus>.Instance.TownRealm)
			{
				return;
			}
			MonsterData[] allMonsters = SingletonBehaviour<FateDB>.Instance.allMonsters;
			foreach (MonsterData monsterData2 in allMonsters)
			{
				if (questWard.monsterDataId == monsterData2.displayName)
				{
					monsterData = monsterData2;
					break;
				}
			}
			if (!(monsterData == null) && !(monsterData.modelPrefab == null))
			{
				Vector3 closePosition = Player.PlayerChar.GetClosePosition(Player.PlayerChar.myTransform.position, 0.35f, 2f, 100);
				Character component = UnityEngine.Object.Instantiate(monsterData.modelPrefab, closePosition, Quaternion.identity).GetComponent<Character>();
				component.monsterData = monsterData;
				if (!(component is Ward))
				{
					UnityEngine.Debug.LogError($"Ward prefab {monsterData.modelPrefab} has no 'Ward' component. Please correct the prefab. Quest data is {quest.baseQuestData.name}", quest.baseQuestData);
				}
				(component as Ward).SetQuest(quest);
				component.Init();
				component.CharacterName = questWard.uniqueName;
				component.SetAIState(AIState.Follow);
				component.SetMasterCharacter(Player.PlayerChar);
			}
		}

		public Character SpawnMonsterInTown(MonsterData monsterData, Vector3? targetLocation = null, int levelCap = -1)
		{
			if (monsterData == null || monsterData.modelPrefab == null)
			{
				UnityEngine.Debug.LogError("Chosen unique monster does not have a model prefab");
				return null;
			}
			GameObject obj = UnityEngine.Object.Instantiate(position: (!targetLocation.HasValue) ? Player.PlayerChar.GetClosePosition(Player.PlayerChar.myTransform.position, 0.35f, 2f, 100) : targetLocation.Value, original: monsterData.modelPrefab, rotation: Quaternion.identity);
			if (obj.TryGetComponent<Character>(out var component))
			{
				component.monsterData = monsterData;
				component.Init();
			}
			return obj.GetComponent<Character>();
		}

		private void PreSave(FateSaveData save)
		{
			if (SaveData.CurrentSaveSlot.saveState != 0)
			{
				return;
			}
			if (save.playerSaveData == null)
			{
				save.playerSaveData = new PlayerSaveData();
			}
			if (save.realmSaveData == null)
			{
				save.realmSaveData = new RealmStorage
				{
					realms = new List<RealmSave>()
				};
				save.realmSaveData.realms.Add(new RealmSave
				{
					dungeonSave = new DungeonStorage(),
					realm = RealmId
				});
			}
			if (save.realmSaveData.realms == null)
			{
				save.realmSaveData.realms = new List<RealmSave>();
			}
			RealmSave realmSave = save.realmSaveData.realms.Find((RealmSave a) => a.realm == RealmId);
			if (realmSave != null)
			{
				RealmSave realmSave2 = realmSave;
				if (realmSave2.droppedItems == null)
				{
					realmSave2.droppedItems = new List<DroppedItemSaveData>();
				}
			}
			else
			{
				realmSave = new RealmSave
				{
					dungeonSave = new DungeonStorage(),
					realm = RealmId,
					droppedItems = new List<DroppedItemSaveData>()
				};
				save.realmSaveData.realms.Add(realmSave);
			}
			realmSave.droppedItems.Clear();
			for (int i = 0; i < activeContainersParent.childCount; i++)
			{
				Transform child = activeContainersParent.GetChild(i);
				if (child.gameObject.activeSelf && child.TryGetComponent<DroppedItem>(out var component))
				{
					DroppedItemSaveData droppedItemSaveData = new DroppedItemSaveData
					{
						item = new ItemSaveData(),
						position = child.position
					};
					component.Item.FillInstance(droppedItemSaveData.item);
					realmSave.droppedItems.Add(droppedItemSaveData);
				}
			}
		}

		private IEnumerator PeriodicSave()
		{
			WaitForSeconds wait = new WaitForSeconds(10f);
			while (base.gameObject.activeInHierarchy)
			{
				yield return wait;
				SaveData.RequestSave();
			}
		}

		public GameObject SpawnPortal(RealmData.RealmId targetDungeonRealm)
		{
			int num = GetPortalSpawnPoint(targetDungeonRealm);
			if (possibleSpawnPoints.Length <= num)
			{
				UnityEngine.Debug.LogError($"No Spawn Point available for realm {targetDungeonRealm} defaulting to 0");
				num = 0;
			}
			Vector3 position = possibleSpawnPoints[num].position;
			GameObject obj = UnityEngine.Object.Instantiate(SingletonBehaviour<FateDB>.Instance.portalPrefab, ActiveLevel.AdjustPositionToNavMesh(position, position, performObstructionTest: false), Quaternion.identity);
			if (obj.TryGetComponent<EnterPortal>(out var component))
			{
				component.SetDestination(targetDungeonRealm);
			}
			return obj;
		}

		private int GetPortalSpawnPoint(RealmData.RealmId dungeonRealm)
		{
			return dungeonRealm switch
			{
				RealmData.RealmId.CavernsLivingFire => 3, 
				RealmData.RealmId.TkalaCrypt => 7, 
				RealmData.RealmId.HauntedPalace => 5, 
				RealmData.RealmId.ChamberOfTrials => 3, 
				_ => 1, 
			};
		}

		public static void UpdateSpawnIndex(RealmData.RealmId fromRealm, EntryMethod entryMethod)
		{
			switch (entryMethod)
			{
			case EntryMethod.RealmPortal:
				SpawnPointIndex = 0;
				return;
			case EntryMethod.None:
				SpawnPointIndex = 0;
				return;
			}
			switch (fromRealm)
			{
			case RealmData.RealmId.Grove:
			case RealmData.RealmId.Druantia:
			case RealmData.RealmId.Typhon:
			case RealmData.RealmId.TempleOfFate:
			case RealmData.RealmId.Prometheus:
			case RealmData.RealmId.Ekbatan:
				SpawnPointIndex = ((entryMethod == EntryMethod.TownPortal) ? 1 : 2);
				break;
			case RealmData.RealmId.ChamberOfTrials:
				SpawnPointIndex = ((entryMethod == EntryMethod.TownPortal) ? 3 : 4);
				break;
			case RealmData.RealmId.CavernsLivingFire:
				SpawnPointIndex = ((entryMethod == EntryMethod.TownPortal) ? 3 : 4);
				break;
			case RealmData.RealmId.HauntedPalace:
				SpawnPointIndex = ((entryMethod == EntryMethod.TownPortal) ? 5 : 6);
				break;
			case RealmData.RealmId.TkalaCrypt:
				SpawnPointIndex = ((entryMethod == EntryMethod.TownPortal) ? 7 : 8);
				break;
			default:
				UnityEngine.Debug.LogWarning($"Potentially strange travel: from {fromRealm} to {SingletonBehaviour<Town>.Instance.RealmId} method: {entryMethod}");
				SpawnPointIndex = 0;
				break;
			}
		}
	}
