		private List<string> generalTipKeys;

		private Dictionary<TutorialTipType, string> contextualTipKeys;

		private bool hasSeenWelcomeMessage;

		private List<int> seenGeneralTips;

		private List<TutorialTipType> seenContextualTips;

		private bool hasInitialized;

		public bool HasSeenWelcomeMessage => hasSeenWelcomeMessage;

		public void Init(FateSaveData saveData)
		{
			if (!hasInitialized)
			{
				GenerateKeys();
				seenGeneralTips = new List<int>();
				seenContextualTips = new List<TutorialTipType>();
				LoadSave(saveData);
				hasInitialized = true;
			}
		}

		private void GenerateKeys()
		{
			generalTipKeys = new List<string>();
			for (int i = 0; i < 115; i++)
			{
				generalTipKeys.Add("TIP_" + (i + 1).ToString("000"));
			}
			contextualTipKeys = new Dictionary<TutorialTipType, string>();
			foreach (TutorialTipType value in Enum.GetValues(typeof(TutorialTipType)))
			{
				if (value != 0 && value != TutorialTipType.General)
				{
					contextualTipKeys.Add(value, $"ContextTip_{value}");
				}
			}
		}

		public void LoadSave(FateSaveData saveData)
		{
			if (saveData != null && saveData.tutorialSaveData != null)
			{
				hasSeenWelcomeMessage = saveData.tutorialSaveData.hasSeenWelcomeMessage;
				if (saveData.tutorialSaveData.seenGeneralTips != null)
				{
					seenGeneralTips.Clear();
					seenGeneralTips.AddRange(saveData.tutorialSaveData.seenGeneralTips);
				}
				if (saveData.tutorialSaveData.seenContextualTips != null)
				{
					seenContextualTips.Clear();
					seenContextualTips.AddRange(saveData.tutorialSaveData.seenContextualTips);
				}
			}
		}

		public void FlushSave(FateSaveData saveData)
		{
			if (saveData.tutorialSaveData == null)
			{
				saveData.tutorialSaveData = new TutorialSaveData();
			}
			saveData.tutorialSaveData.hasSeenWelcomeMessage = hasSeenWelcomeMessage;
			if (seenGeneralTips != null && seenGeneralTips.Count > 0)
			{
				if (saveData.tutorialSaveData.seenGeneralTips == null)
				{
					saveData.tutorialSaveData.seenGeneralTips = new List<int>();
				}
				else
				{
					saveData.tutorialSaveData.seenGeneralTips.Clear();
				}
				saveData.tutorialSaveData.seenGeneralTips.AddRange(seenGeneralTips);
			}
			if (seenContextualTips != null && seenContextualTips.Count > 0)
			{
				if (saveData.tutorialSaveData.seenContextualTips == null)
				{
					saveData.tutorialSaveData.seenContextualTips = new List<TutorialTipType>();
				}
				else
				{
					saveData.tutorialSaveData.seenContextualTips.Clear();
				}
				saveData.tutorialSaveData.seenContextualTips.AddRange(seenContextualTips);
			}
		}

		public bool TryGetWelcomeMessageKey(RealmData.RealmId townRealm, out string key)
		{
			if (!SaveData.SettingsSave.displayTips || hasSeenWelcomeMessage)
			{
				key = null;
				return false;
			}
			if (townRealm != 0 && townRealm != RealmData.RealmId.TempleOfFate && townRealm != RealmData.RealmId.Ekbatan)
			{
				key = null;
				return false;
			}
			hasSeenWelcomeMessage = true;
			key = $"ContextTip_Welcome_{townRealm}";
			return true;
		}

		public bool TryGetRandomTip(out string key)
		{
			if (!SaveData.SettingsSave.displayTips)
			{
				key = null;
				return false;
			}
			List<int> list = new List<int>();
			for (int i = 0; i < generalTipKeys.Count; i++)
			{
				if (!seenGeneralTips.Contains(i) && !blockedGeneralTips.Contains(i) && !GeneralIndexIsBlockedByGameVersion(i))
				{
					list.Add(i);
				}
			}
			if (list.Count == 0)
			{
				key = null;
				return false;
			}
			int index = UnityEngine.Random.Range(0, list.Count);
			int num = list[index];
			key = generalTipKeys[num];
			seenGeneralTips.Add(num);
			return true;
		}

		private bool GeneralIndexIsBlockedByGameVersion(int index)
		{
			GameExclusiveGeneralTip[] array = gameExclusiveGeneralTips;
			for (int i = 0; i < array.Length; i++)
			{
				GameExclusiveGeneralTip gameExclusiveGeneralTip = array[i];
				if (!gameExclusiveGeneralTip.gameVersions.Contains(Fate.CurrentFateVer) && gameExclusiveGeneralTip.tipIndex == index)
				{
					return true;
				}
			}
			return false;
		}

		public bool TryGetContextualTip(TutorialTipType tipType, out string key)
		{
			if (Player.PlayerChar == null || !Player.PlayerChar.Alive())
			{
				key = null;
				return false;
			}
			if (!SaveData.SettingsSave.displayTips || seenContextualTips.Contains(tipType) || blockedContextualTips.Contains(tipType))
			{
				key = null;
				return false;
			}
			key = contextualTipKeys[tipType];
			seenContextualTips.Add(tipType);
			return true;
		}
	}
