	public class CreatureParticleSystem : MonoBehaviour
	{
		[Tooltip("Plays until death")]
		public ParticleSystem pPassiveSystem;

		[Tooltip("More passives.")]
		public List<ParticleSystem> pPassiveList;

		[Tooltip("Play particle effect on death")]
		public ParticleSystem pOnDeathSystem;

		[Tooltip("Upon animation event AttackTrigger with corresponding index int, Play particle effect.")]
		public List<ParticleSystem> pPartEvents;

		public List<Animator> pParticleAnims;

		private void Start()
		{
			if (TryGetComponent<Monster>(out var component) && component.loadedAsDead)
			{
				DisableAll();
			}
		}

		public void DeathEffectTrigger()
		{
			if (pPassiveSystem != null)
			{
				pPassiveSystem.Stop(withChildren: true);
			}
			if (pPassiveList != null)
			{
				foreach (ParticleSystem pPassive in pPassiveList)
				{
					pPassive.Stop(withChildren: true);
				}
			}
			if (pOnDeathSystem != null)
			{
				pOnDeathSystem.Play(withChildren: true);
			}
		}

		public void AttackTrigger(int anIndex)
		{
			if (pPartEvents.IsValidIndex(anIndex))
			{
				pPartEvents[anIndex].Play();
			}
		}

		public void DisableAll()
		{
			if (pPassiveSystem != null)
			{
				pPassiveSystem.gameObject.SetActive(value: false);
			}
			foreach (ParticleSystem pPassive in pPassiveList)
			{
				pPassive.Stop(withChildren: true);
				pPassive.gameObject.SetActive(value: false);
			}
			if (pOnDeathSystem != null)
			{
				pOnDeathSystem.gameObject.SetActive(value: false);
			}
			foreach (ParticleSystem pPartEvent in pPartEvents)
			{
				pPartEvent.Stop(withChildren: true);
				pPartEvent.gameObject.SetActive(value: false);
			}
		}

		public void ReEnable()
		{
			if (pPassiveSystem != null)
			{
				pPassiveSystem.gameObject.SetActive(value: true);
			}
			foreach (ParticleSystem pPassive in pPassiveList)
			{
				pPassive.gameObject.SetActive(value: true);
				pPassive.Play(withChildren: true);
			}
			if (pOnDeathSystem != null)
			{
				pOnDeathSystem.gameObject.SetActive(value: true);
			}
			foreach (ParticleSystem pPartEvent in pPartEvents)
			{
				pPartEvent.gameObject.SetActive(value: true);
			}
		}
	}
