	public class HighlightPulserScript : MonoBehaviour
	{
		private float startAngle;

		[SerializeField]
		private float frequency = 5f;

		[SerializeField]
		private float amplitude = 15f;

		private Light lightComp;

		private void Start()
		{
			Monster componentInParent = base.gameObject.GetComponentInParent<Monster>();
			lightComp = GetComponent<Light>();
			startAngle = lightComp.spotAngle;
			if (componentInParent != null && componentInParent.loadedAsDead)
			{
				base.gameObject.SetActive(value: false);
			}
		}

		private void Update()
		{
			float spotAngle = startAngle + Mathf.Sin(Time.time * frequency) * amplitude;
			lightComp.spotAngle = spotAngle;
		}

		public void ActivateFadeout()
		{
			if (lightComp != null)
			{
				StartCoroutine(LightFader());
			}
		}

		private IEnumerator LightFader()
		{
			float fadeTime = 1.25f;
			float timer = 0f;
			if (!(lightComp == null))
			{
				float lightIntensity = lightComp.intensity;
				while (timer < fadeTime)
				{
					float num = Mathf.Clamp01(1f - timer / fadeTime);
					lightComp.intensity = lightIntensity * num;
					timer += Time.deltaTime;
					yield return null;
				}
				base.gameObject.SetActive(value: false);
				yield return null;
			}
		}
	}
	public class OpenGateOnTrigger : MonoBehaviour
	{
		public GameObject objectToMove;

		public Collider triggerObject;

		public Vector3 moveValue1;

		public Vector3 moveValue2;

		public float moveSpeed = 2f;

		public LayerMask triggerLayers;

		private AudioSource audioSource;

		public AudioClip doorOpenSound;

		public AudioClip doorShutSound;

		private Vector3 targetMove;

		private int objectsInTrigger;

		public bool IsDoorOpen { get; private set; }

		private void Start()
		{
			audioSource = GetComponent<AudioSource>();
			if (audioSource == null)
			{
				UnityEngine.Debug.LogWarning(base.gameObject.name + " is missing audioSource component");
			}
			if (objectToMove != null)
			{
				targetMove = objectToMove.transform.localPosition.normalized;
			}
			base.gameObject.layer = LayerMask.NameToLayer("Trigger");
		}

		private void OnTriggerEnter(Collider other)
		{
			if (((1 << other.gameObject.layer) & (int)triggerLayers) != 0)
			{
				objectsInTrigger++;
				targetMove = moveValue1;
				if (!IsDoorOpen && audioSource != null && doorOpenSound != null)
				{
					audioSource.PlayOneShot(doorOpenSound);
				}
				IsDoorOpen = true;
			}
		}

		private void OnTriggerExit(Collider other)
		{
			if (((1 << other.gameObject.layer) & (int)triggerLayers) == 0)
			{
				return;
			}
			objectsInTrigger--;
			if (objectsInTrigger <= 0)
			{
				targetMove = moveValue2;
				objectsInTrigger = 0;
				if (audioSource != null && doorShutSound != null)
				{
					audioSource.PlayOneShot(doorShutSound);
				}
				IsDoorOpen = false;
			}
		}

		private void Update()
		{
			if (!(objectToMove == null))
			{
				objectToMove.transform.localPosition = Vector3.MoveTowards(objectToMove.transform.localPosition, targetMove, moveSpeed * Time.deltaTime);
			}
		}
	}
