	public class SmoothSeams : MonoBehaviour
	{
		public class Vector3EqualityComparer : IEqualityComparer<Vector3>
		{
			private readonly float threshold;

			public Vector3EqualityComparer(float threshold)
			{
				this.threshold = threshold;
			}

			public bool Equals(Vector3 v1, Vector3 v2)
			{
				return Vector3.SqrMagnitude(v1 - v2) < threshold * threshold;
			}

			public int GetHashCode(Vector3 v)
			{
				return 0;
			}
		}

		private float weldThreshold = 0.02f;

		private string targetTag = "Smooth";

		public void SmoothNormals()
		{
			MeshFilter[] componentsInChildren = GetComponentsInChildren<MeshFilter>();
			List<MeshFilter> list = new List<MeshFilter>();
			MeshFilter[] array = componentsInChildren;
			foreach (MeshFilter meshFilter in array)
			{
				if (meshFilter.gameObject.CompareTag(targetTag) || meshFilter.transform.parent.CompareTag(targetTag))
				{
					list.Add(meshFilter);
				}
			}
			Dictionary<Vector3, List<Vector3>> dictionary = new Dictionary<Vector3, List<Vector3>>(new Vector3EqualityComparer(weldThreshold));
			foreach (MeshFilter item in list)
			{
				Mesh mesh = item.mesh;
				Vector3[] vertices = mesh.vertices;
				Vector3[] normals = mesh.normals;
				Transform transform = item.transform;
				for (int j = 0; j < vertices.Length; j++)
				{
					Vector3 key = transform.TransformPoint(vertices[j]);
					if (!dictionary.ContainsKey(key))
					{
						dictionary[key] = new List<Vector3>();
					}
					dictionary[key].Add(transform.TransformDirection(normals[j]));
				}
			}
			Dictionary<Vector3, Vector3> dictionary2 = new Dictionary<Vector3, Vector3>(new Vector3EqualityComparer(weldThreshold));
			foreach (KeyValuePair<Vector3, List<Vector3>> item2 in dictionary)
			{
				Vector3 zero = Vector3.zero;
				foreach (Vector3 item3 in item2.Value)
				{
					zero += item3;
				}
				dictionary2[item2.Key] = zero.normalized;
			}
			foreach (MeshFilter item4 in list)
			{
				Mesh mesh2 = item4.mesh;
				Vector3[] vertices2 = mesh2.vertices;
				Vector3[] array2 = new Vector3[vertices2.Length];
				Transform transform2 = item4.transform;
				for (int k = 0; k < vertices2.Length; k++)
				{
					Vector3 key2 = transform2.TransformPoint(vertices2[k]);
					array2[k] = transform2.InverseTransformDirection(dictionary2[key2]);
				}
				mesh2.normals = array2;
			}
		}

		private void Awake()
		{
			SmoothNormals();
		}
	}
	public class SpotlightAnimation : MonoBehaviour
	{
		public Vector3 minRotationRange;

		public Vector3 maxRotationRange;

		public float lerpDuration = 2f;

		private Quaternion startRotation;

		private Quaternion endRotation;

		private float lerpTimer;

		private Light spotLight;

		private void Start()
		{
			spotLight = GetComponent<Light>();
			SetNewTargetRotations();
		}

		private void Update()
		{
			lerpTimer += Time.deltaTime;
			float t = lerpTimer / lerpDuration;
			base.transform.rotation = Quaternion.Lerp(startRotation, endRotation, t);
			if (lerpTimer >= lerpDuration)
			{
				lerpTimer = 0f;
				SetNewTargetRotations();
			}
			spotLight.innerSpotAngle = 90f + 10f * Mathf.Sin(Time.time);
			spotLight.spotAngle = 120f + 10f * Mathf.Sin(Time.time);
		}

		private void SetNewTargetRotations()
		{
			new Vector3(UnityEngine.Random.Range(minRotationRange.x, maxRotationRange.x), UnityEngine.Random.Range(minRotationRange.y, maxRotationRange.y), UnityEngine.Random.Range(minRotationRange.z, maxRotationRange.z));
			Vector3 euler = new Vector3(UnityEngine.Random.Range(minRotationRange.x, maxRotationRange.x), UnityEngine.Random.Range(minRotationRange.y, maxRotationRange.y), UnityEngine.Random.Range(minRotationRange.z, maxRotationRange.z));
			startRotation = base.transform.rotation;
			endRotation = Quaternion.Euler(euler);
		}
	}
