	public class ErebosSound2D : MonoBehaviour
	{
		private AudioSource deathAudioSource;

		[SerializeField]
		private AudioSource greetAudioSource;

		private Monster monster;

		private bool hasPlayedGreet;

		[SerializeField]
		private AudioClip germanClip;

		[SerializeField]
		private AudioClip frenchClip;

		[SerializeField]
		private AudioClip spanishClip;

		[SerializeField]
		private AudioClip englishClip;

		private string language;

		private void Start()
		{
			deathAudioSource = GetComponent<AudioSource>();
			monster = GetComponent<Monster>();
			if (!monster.loadedAsDead && !monster.MyVitals.IsDead)
			{
				StartCoroutine(DoDeathSoundCheck());
				StartCoroutine(PlayGreetSound());
			}
			language = LocalizationManager.CurrentLanguage;
			switch (language)
			{
			case "German":
				greetAudioSource.clip = germanClip;
				break;
			case "French":
				greetAudioSource.clip = frenchClip;
				break;
			case "Spanish":
				greetAudioSource.clip = spanishClip;
				break;
			default:
				greetAudioSource.clip = englishClip;
				break;
			}
		}

		private IEnumerator DoDeathSoundCheck()
		{
			while (!monster.MyVitals.IsDead)
			{
				yield return null;
			}
			if (deathAudioSource.spatialBlend > 0f)
			{
				deathAudioSource.spatialBlend = 0f;
				deathAudioSource.volume = 1f;
			}
		}

		private IEnumerator PlayGreetSound()
		{
			while (monster.Target() == null && !monster.loadedAsDead && !monster.MyVitals.IsDead)
			{
				yield return null;
			}
			if (!hasPlayedGreet)
			{
				greetAudioSource.Play();
				hasPlayedGreet = true;
			}
		}
	}
	public class Narrator : SingletonBehaviour<Narrator>
	{
		private NarratorAudioclips m_narratorAudioclips;

		private string currentLanguage;

		private List<NarratorLists> linesList;

		public AudioSource audioSource;

		protected override bool DontDestroy => true;

		protected override void Init()
		{
			audioSource = GetComponent<AudioSource>();
			ChangeNarratorLanguage(LocalizationManager.CurrentLanguageCode);
			I2Loca.OnLanguageChanged = (Action<string>)Delegate.Combine(I2Loca.OnLanguageChanged, new Action<string>(OnLanguageChanged));
		}

		private void OnDestroy()
		{
			I2Loca.OnLanguageChanged = (Action<string>)Delegate.Remove(I2Loca.OnLanguageChanged, new Action<string>(OnLanguageChanged));
		}

		private void OnLanguageChanged(string newLanguageCode)
		{
			ChangeNarratorLanguage(newLanguageCode);
		}

		public void ChangeNarratorLanguage(string language)
		{
			if (!(language == currentLanguage))
			{
				NarratorAudioclips narratorAudioclips = Resources.Load<NarratorAudioclips>("Narrator_" + language);
				if (narratorAudioclips == null)
				{
					narratorAudioclips = Resources.Load<NarratorAudioclips>("Narrator_en");
				}
				if (m_narratorAudioclips != null)
				{
					Resources.UnloadAsset(m_narratorAudioclips);
				}
				m_narratorAudioclips = narratorAudioclips;
				currentLanguage = language;
				AddSoundsToNarrator();
			}
		}

		public List<NarratorLists> AddSoundsToNarrator()
		{
			linesList = m_narratorAudioclips.narratorClipsList;
			return linesList;
		}

		public void PlayYourLine(NarratorLines lines)
		{
			NarratorLists narratorLists = linesList.Find((NarratorLists e) => e.narratorLines == lines);
			if (narratorLists != null && narratorLists.clips.Count > 0)
			{
				audioSource.clip = narratorLists.clips.GetRandomEntry();
				audioSource.PlayDelayed(0.5f);
			}
		}

		public void ForcePlayYourLine(NarratorLines lines)
		{
			NarratorLists narratorLists = linesList.Find((NarratorLists e) => e.narratorLines == lines);
			if (narratorLists != null && narratorLists.clips.Count > 0)
			{
				audioSource.ignoreListenerPause = true;
				audioSource.clip = narratorLists.clips.GetRandomEntry();
				audioSource.Play();
			}
		}

		public AudioClip CurrentStoryAudioclip(NarratorLines lines)
		{
			NarratorLists narratorLists = linesList.Find((NarratorLists e) => e.narratorLines == lines);
			if (lines == NarratorLines.Narrator_Story_None)
			{
				return null;
			}
			if (narratorLists == null || narratorLists.clips.Count == 0)
			{
				UnityEngine.Debug.LogWarning("Line missing: " + lines);
				return null;
			}
			return narratorLists.clips[0];
		}

		public void StopAudio()
		{
			audioSource.Stop();
		}

		public bool IsPlaying()
		{
			return audioSource.isPlaying;
		}
	}
