	public class NpcVoiceLines : MonoBehaviour
	{
		public NpcGreetings thisNpc;

		public AudioSource audioSource;

		public List<AudioClip> voiceLines = new List<AudioClip>();

		private int randomCue;

		private float lastCueTime = -1f;

		private float cooldown = 5f;

		private void Start()
		{
			audioSource = GetComponent<AudioSource>();
			GetVoiceLines(SingletonBehaviour<VoiceDataManager>.Instance.CurrentVoiceData);
			VoiceDataManager instance = SingletonBehaviour<VoiceDataManager>.Instance;
			instance.OnVoiceDataChanged = (Action<VoiceData>)Delegate.Combine(instance.OnVoiceDataChanged, new Action<VoiceData>(OnVoiceData));
		}

		private void OnDestroy()
		{
			if (SingletonBehaviour<VoiceDataManager>.InstanceExists())
			{
				VoiceDataManager instance = SingletonBehaviour<VoiceDataManager>.Instance;
				instance.OnVoiceDataChanged = (Action<VoiceData>)Delegate.Remove(instance.OnVoiceDataChanged, new Action<VoiceData>(OnVoiceData));
			}
		}

		private void OnVoiceData(VoiceData voiceData)
		{
			GetVoiceLines(voiceData);
		}

		public void PlayYourLine()
		{
			if (voiceLines != null && voiceLines.Count != 0 && Time.realtimeSinceStartup > lastCueTime + cooldown)
			{
				lastCueTime = Time.realtimeSinceStartup;
				randomCue = UnityEngine.Random.Range(0, voiceLines.Count);
				audioSource.PlayOneShot(voiceLines[randomCue]);
			}
		}

		public void PlayRealmQuestLine(Quest.QuestStatus status, bool isSilentBegin, bool isSilentEnd)
		{
			if (voiceLines == null || voiceLines.Count == 0 || !(Time.realtimeSinceStartup > lastCueTime + cooldown))
			{
				return;
			}
			lastCueTime = Time.realtimeSinceStartup;
			switch (status)
			{
			case Quest.QuestStatus.None:
				audioSource.clip = voiceLines[0];
				if (!isSilentBegin)
				{
					audioSource.Play();
				}
				break;
			case Quest.QuestStatus.Completed:
				audioSource.clip = voiceLines[1];
				if (!isSilentEnd)
				{
					audioSource.Play();
				}
				break;
			}
		}

		private void GetVoiceLines(VoiceData voiceData)
		{
			if (voiceLines == null)
			{
				UnityEngine.Debug.Log("voicelines not found for " + voiceData);
			}
			else if (voiceData != null)
			{
				voiceLines = voiceData.NpcVoiceOf(thisNpc)?.audioCues;
			}
		}
	}
