	public class VoiceDataManager : SingletonBehaviour<VoiceDataManager>
	{
		private VoiceData voiceData;

		public string currentLanguage;

		public Action<VoiceData> OnVoiceDataChanged;

		public VoiceData CurrentVoiceData => voiceData;

		protected override void Init()
		{
			currentLanguage = LocalizationManager.CurrentLanguageCode;
			ChangeVoiceDataBase(currentLanguage);
			I2Loca.OnLanguageChanged = (Action<string>)Delegate.Combine(I2Loca.OnLanguageChanged, new Action<string>(OnLanguageChanged));
		}

		private void OnDestroy()
		{
			I2Loca.OnLanguageChanged = (Action<string>)Delegate.Remove(I2Loca.OnLanguageChanged, new Action<string>(OnLanguageChanged));
		}

		private void OnLanguageChanged(string newLangCode)
		{
			ChangeVoiceDataBase(newLangCode);
		}

		public void ChangeVoiceDataBase(string currentLang)
		{
			string text = SingletonBehaviour<PlayerStatus>.Instance.TownRealm.ToString();
			string text2 = "VoiceData" + text + "_" + currentLang;
			VoiceData voiceData = Resources.Load<VoiceData>(text2);
			if (voiceData == null)
			{
				UnityEngine.Debug.Log("current language not found: " + text2);
				text2 = "VoiceData" + text + "_en";
				voiceData = Resources.Load<VoiceData>(text2);
			}
			OnVoiceDataChanged?.Invoke(voiceData);
			if (this.voiceData != null)
			{
				Resources.UnloadAsset(this.voiceData);
			}
			this.voiceData = voiceData;
		}
	}
	[CreateAssetMenu(menuName = "FATE/Achievement")]
	public class AchievementConfig : ScriptableObject
	{
		public enum ComparisonTarget
		{
			HigherOrEqual,
			LowerOrEqual
		}

		[Serializable]
		public class AchievementTier : IComparable<AchievementTier>
		{
			public int value;

			[Header("Console Indices")]
			[Tooltip("Platinum is index 0, get values from TRP file (PS4) or UDS Management Site (PS5)")]
			public int playstationIndex;

			[Tooltip("Get indices from Microsoft Partner Center")]
			public int xboxIndex;

			public int NativeIndex => xboxIndex;

			public int CompareTo(AchievementTier other)
			{
				return value.CompareTo(other.value);
			}

			public static bool operator >(AchievementTier operand1, AchievementTier operand2)
			{
				return operand1.CompareTo(operand2) > 0;
			}

			public static bool operator <(AchievementTier operand1, AchievementTier operand2)
			{
				return operand1.CompareTo(operand2) < 0;
			}

			public static bool operator >=(AchievementTier operand1, AchievementTier operand2)
			{
				return !(operand1 < operand2);
			}

			public static bool operator <=(AchievementTier operand1, AchievementTier operand2)
			{
				return !(operand1 > operand2);
			}
		}

		private class AchievementTierEqualityComparer : IEqualityComparer<AchievementTier>
		{
			public bool Equals(AchievementTier x, AchievementTier y)
			{
				return x.value == y.value;
			}

			public int GetHashCode(AchievementTier obj)
			{
				return obj.value.GetHashCode();
			}
		}

		[Header("Achievement Settings")]
		[SerializeField]
		private Stat m_TrackedStat;

		[SerializeField]
		private AchievementTier[] m_Tiers = new AchievementTier[1];

		public ComparisonTarget unlocksOn;

		private static AchievementTierEqualityComparer s_AchievementTierEqualityComparer = new AchievementTierEqualityComparer();

		public Stat TrackedStat => m_TrackedStat;

		public AchievementTier[] Tiers => m_Tiers;
	}
