	public class AchievementManager : MonoBehaviour
	{
		[SerializeField]
		private AchievementConfig[] achievementData;

		private List<int> nativeAchievementsGranted;

		private IAchievements achievements = new SteamAchievements();

		private void Start()
		{
			StatsManager.onStatUpdated = (Action<Stat, int, bool>)Delegate.Combine(StatsManager.onStatUpdated, new Action<Stat, int, bool>(OnStatUpdated));
			achievements.AddAchievementListener(OnAchievementGranted);
			nativeAchievementsGranted = new List<int>();
			StartCoroutine(achievements.Initialize());
		}

		private void OnPlayersChanged()
		{
			nativeAchievementsGranted = new List<int>();
		}

		private void OnAchievementGranted(int nativeIndex)
		{
			nativeAchievementsGranted.Add(nativeIndex);
		}

		private void OnDestroy()
		{
			StatsManager.onStatUpdated = (Action<Stat, int, bool>)Delegate.Remove(StatsManager.onStatUpdated, new Action<Stat, int, bool>(OnStatUpdated));
			achievements.RemoveAchievementListener(OnAchievementGranted);
		}

		private void OnStatUpdated(Stat stat, int newValue, bool requestSave = false)
		{
			AchievementConfig[] array = achievementData;
			foreach (AchievementConfig achievementConfig in array)
			{
				if (achievementConfig.TrackedStat != stat)
				{
					continue;
				}
				AchievementConfig.AchievementTier[] tiers = achievementConfig.Tiers;
				for (int j = 0; j < tiers.Length; j++)
				{
					if (achievementConfig.unlocksOn == AchievementConfig.ComparisonTarget.HigherOrEqual)
					{
						if (newValue >= tiers[j].value)
						{
							GrantAchievement(tiers[j].NativeIndex);
						}
						else
						{
							UpdateAchievement(tiers[j].NativeIndex, (uint)((float)newValue / (float)tiers[j].value * 100f));
						}
					}
					else if (achievementConfig.unlocksOn == AchievementConfig.ComparisonTarget.LowerOrEqual && newValue <= tiers[j].value)
					{
						GrantAchievement(tiers[j].NativeIndex);
					}
				}
			}
		}

		private void GrantAchievement(int nativeIndex)
		{
			achievements.UnlockAchievement(nativeIndex);
		}

		private void UpdateAchievement(int nativeIndex, uint progress)
		{
		}
	}
	public class DLCManager : SingletonBehaviour<DLCManager>
	{
		public (bool isDlc, Fate.DLC dlc) GetDLCInfoForRealm(RealmData.RealmId targetRealm)
		{
			if (targetRealm == RealmData.RealmId.Prometheus)
			{
				return (isDlc: true, dlc: Fate.DLC.Prometheus);
			}
			return (isDlc: false, dlc: Fate.DLC.Invalid);
		}

		protected override void Init()
		{
		}

		public void HasEntitlement(Fate.DLC dlc, Action<bool> onDone)
		{
			PlatformManager.HasEntitlement(dlc, onDone);
		}

		public void OnEnteredTown(RealmData.RealmId townRealm, bool isComingFromMenu, Action onDLCKringsakerDone)
		{
			var (flag, targetDlc) = GetDLCInfoForRealm(townRealm);
			if (!flag)
			{
				onDLCKringsakerDone?.Invoke();
			}
			else if (!isComingFromMenu)
			{
				FateDB.DLCSetup dLCSetup = SingletonBehaviour<FateDB>.Instance.dlcs.Find((FateDB.DLCSetup d) => d.targetRealm == townRealm && d.playStoryOnEntry);
				if (dLCSetup == null)
				{
					onDLCKringsakerDone?.Invoke();
					return;
				}
				DLCSave savedata = SaveData.CurrentSaveData.GetDLCSave(targetDlc);
				if (savedata.hasPlayedStory)
				{
					onDLCKringsakerDone?.Invoke();
					return;
				}
				SingletonBehaviour<StoryUI>.Instance.DoStory(dLCSetup.introStory, delegate
				{
					savedata.hasPlayedStory = true;
					SaveData.RequestSave();
					onDLCKringsakerDone?.Invoke();
				});
			}
			else
			{
				onDLCKringsakerDone?.Invoke();
			}
		}

		public (bool, Fate.DLC) IsDLCPet(MonsterData monsterData)
		{
			FateDB.DLCSetup dLCSetup = SingletonBehaviour<FateDB>.Instance.dlcs.Find((FateDB.DLCSetup d) => (d.dlcPets != null && d.dlcPets.Find((MonsterData m) => m == monsterData) != null) ? true : false);
			return (dLCSetup != null, dLCSetup?.targetDLC ?? Fate.DLC.Invalid);
		}
	}
