	public static class StatsManager
	{
		[Serializable]
		public class StatData
		{
			public Stat statType;

			public int value;

			public StatData(Stat stat)
			{
				statType = stat;
				value = 0;
			}

			public void Increment(int count)
			{
				value += count;
			}

			public void Set(int value)
			{
				this.value = value;
			}

			public override string ToString()
			{
				return $"{statType}: {value}";
			}
		}

		[Serializable]
		public class PlayerStatSaveData
		{
			[Serializable]
			public class BossKill
			{
				public string weaponId;

				public int count;
			}

			public List<StatData> playerStats;

			public List<string> uniqueFishCaught;

			public List<string> uniqueGemsLooted;

			public List<string> uniqueDungeonsCleared;

			public List<string> uniqueSummons;

			public List<string> uniqueWeaponClasses;

			public List<BossKill> bossKillCounter;
		}

		private const string k_StatSaveKey = "PlayerStats";

		public static Action<Stat, int, bool> onStatUpdated;

		public static List<StatData> currentStats => playerSimpleStats;

		private static PlayerStatSaveData s_PlayerStatSave => SaveData.StatSave;

		private static List<StatData> playerSimpleStats => s_PlayerStatSave.playerStats;

		public static bool hasInitialized { get; private set; }

		private static void Setup()
		{
			if (s_PlayerStatSave == null)
			{
				SaveData.StatSave = new PlayerStatSaveData();
			}
			if (s_PlayerStatSave.playerStats == null)
			{
				s_PlayerStatSave.playerStats = new List<StatData>();
			}
			onStatUpdated = (Action<Stat, int, bool>)Delegate.Combine(onStatUpdated, new Action<Stat, int, bool>(OnStatUpdate));
			hasInitialized = true;
		}

		private static void OnStatUpdate(Stat stat, int count, bool requestSave = false)
		{
			if (requestSave)
			{
				SaveData.RequestSave();
			}
		}

		public static int IncrementStat(Stat stat, int count = 1, bool requestSave = false)
		{
			if (!hasInitialized)
			{
				Setup();
			}
			int num = FindStat(stat);
			if (num == -1)
			{
				num = AddStat(stat);
			}
			playerSimpleStats[num].Increment(count);
			onStatUpdated?.Invoke(stat, playerSimpleStats[num].value, requestSave);
			return playerSimpleStats[num].value;
		}

		public static void SetStat(Stat stat, int value, bool requestSave = false)
		{
			if (!hasInitialized)
			{
				Setup();
			}
			int num = FindStat(stat);
			if (num == -1)
			{
				num = AddStat(stat);
			}
			playerSimpleStats[num].Set(value);
			onStatUpdated?.Invoke(stat, value, requestSave);
		}

		public static int GetStat(Stat stat)
		{
			if (!hasInitialized)
			{
				Setup();
			}
			int num = FindStat(stat);
			if (num == -1)
			{
				return 0;
			}
			return playerSimpleStats[num].value;
		}

		public static void OnFishLooted(string fishId, bool requestSave = true)
		{
			if (!hasInitialized)
			{
				Setup();
			}
			AssertListAndAddUnique(ref s_PlayerStatSave.uniqueFishCaught, fishId, Stat.UniqueFishCaught, requestSave);
		}

		public static void OnGemLooted(string gemId, bool requestSave = true)
		{
			if (!hasInitialized)
			{
				Setup();
			}
			AssertListAndAddUnique(ref s_PlayerStatSave.uniqueGemsLooted, gemId, Stat.UniqueGemsLooted, requestSave);
		}

		public static void OnDungeonLevel35Reached(string dungeonId, bool requestSave = true)
		{
			if (!hasInitialized)
			{
				Setup();
			}
			AssertListAndAddUnique(ref s_PlayerStatSave.uniqueDungeonsCleared, dungeonId, Stat.DungeonsCompleted, requestSave);
		}

		public static void OnMonsterSummon(string monsterId, bool requestSave = true)
		{
			if (!hasInitialized)
			{
				Setup();
			}
			AssertListAndAddUnique(ref s_PlayerStatSave.uniqueSummons, monsterId, Stat.MonsterSummons, requestSave);
		}

		public static void OnBossKilled(string weaponId)
		{
			if (s_PlayerStatSave.bossKillCounter == null)
			{
				s_PlayerStatSave.bossKillCounter = new List<PlayerStatSaveData.BossKill>();
			}
			PlayerStatSaveData.BossKill bossKill = s_PlayerStatSave.bossKillCounter.Find((PlayerStatSaveData.BossKill a) => a.weaponId == weaponId);
			if (bossKill != null)
			{
				if (++bossKill.count != 10)
				{
					return;
				}
				int num = 0;
				for (int i = 0; i < s_PlayerStatSave.bossKillCounter.Count; i++)
				{
					if (s_PlayerStatSave.bossKillCounter[i].count >= 10)
					{
						num++;
					}
				}
				SetStat(Stat.BossKillWithWeapon, num);
			}
			else
			{
				s_PlayerStatSave.bossKillCounter.Add(new PlayerStatSaveData.BossKill
				{
					weaponId = weaponId,
					count = 1
				});
			}
		}

		private static int FindStat(Stat stat)
		{
			return playerSimpleStats.FindIndex((StatData s) => s.statType == stat);
		}

		private static int AddStat(Stat stat)
		{
			playerSimpleStats.Add(new StatData(stat));
			return playerSimpleStats.Count - 1;
		}

		private static void AssertListAndAddUnique<T>(ref List<T> list, T uniqueId, Stat callbackStat, bool requestSave = true) where T : IComparable
		{
			if (list == null)
			{
				list = new List<T>();
			}
			if (!list.Contains(uniqueId))
			{
				list.Add(uniqueId);
				SetStat(callbackStat, list.Count, requestSave);
			}
		}
	}
	public class CursorManager : SingletonBehaviour<CursorManager>
	{
		public enum CursorState
		{
			Physical,
			Virtual,
			None
		}

		public enum CursorMode
		{
			Standard,
			ItemTarget,
			SpellAssign
		}

		[Header("Textures")]
		public Sprite virtualCursorTexture;

		public Sprite virtualCursorTexture_itemSelect;

		public Sprite systemCursorTexture;

		public Sprite systemCursorTexture_itemSelect;

		public Sprite systemCursorTexture_spellAssign;

		[Header("Sizes")]
		public Vector2 virtualCursorSize = new Vector2(64f, 64f);

		public Vector2 physicalCursorSize = new Vector2(128f, 128f);

		[Header("Tooltip")]
		public CursorTooltip cursorTooltip;

		[Header("GameObjects")]
		[SerializeField]
		private RectTransform cursorRT;

		[SerializeField]
		private Image cursorRTImage;

		private float canvasScaleFactor;

		private bool wantsVirtualActive;

		public RectTransform VirtualCursor => cursorRT;

		public bool VirtualCursorActive
		{
			get
			{
				return wantsVirtualActive;
			}
			set
			{
				SetVirtualCursorActive(value);
			}
		}

		public CursorState CurrentCursor { get; private set; }

		public CursorMode CurrentMode { get; private set; }

		private void UpdateCursorState(CursorState newState)
		{
			int num;
			switch (newState)
			{
			case CursorState.None:
				SetCursorVisible(state: false);
				SingletonBehaviour<InputBroker>.Instance.OnVirtualCursorActive(newState: false);
				CurrentCursor = CursorState.None;
				return;
			case CursorState.Virtual:
				num = ((SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior != InputBroker.InputBehavior.ClickToMove) ? 1 : 0);
				break;
			default:
				num = 0;
				break;
			}
			bool flag = (byte)num != 0;
			CurrentCursor = newState;
			SetMode(CurrentMode);
			SetCursorVisible(state: true);
			cursorRT.sizeDelta = (flag ? virtualCursorSize : physicalCursorSize);
			cursorRT.pivot = (flag ? new Vector2(0.5f, 0.5f) : new Vector2(0f, 1f));
			SingletonBehaviour<InputBroker>.Instance.OnVirtualCursorActive(flag);
		}

		public void SetCursorVisible(bool state)
		{
			cursorRT.gameObject.SetActive(state);
			Cursor.visible = false;
			Cursor.lockState = ((!state) ? CursorLockMode.Locked : CursorLockMode.Confined);
		}

		public void SetMode(CursorMode newMode)
		{
			if (CurrentCursor == CursorState.Virtual && SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior != InputBroker.InputBehavior.ClickToMove)
			{
				cursorRTImage.sprite = ((newMode == CursorMode.ItemTarget) ? virtualCursorTexture_itemSelect : virtualCursorTexture);
				return;
			}
			Image image = cursorRTImage;
			image.sprite = newMode switch
			{
				CursorMode.ItemTarget => systemCursorTexture_itemSelect, 
				CursorMode.SpellAssign => systemCursorTexture_spellAssign, 
				_ => systemCursorTexture, 
			};
		}

		private IEnumerator Start()
		{
			yield return null;
			yield return null;
			InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
			instance.OnInputBehaviorChanged = (Action<InputBroker.InputBehavior>)Delegate.Combine(instance.OnInputBehaviorChanged, new Action<InputBroker.InputBehavior>(OnInputBehaviorChange));
			UpdateCursorState((SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior != InputBroker.InputBehavior.ClickToMove) ? CursorState.None : CursorState.Physical);
			Game.OnInputTick = (Action)Delegate.Combine(Game.OnInputTick, new Action(InputTick));
			canvasScaleFactor = GetComponentInParent<Canvas>().scaleFactor;
			ScreenInfo.OnScreenResolutionChanged = (Action<int, int>)Delegate.Combine(ScreenInfo.OnScreenResolutionChanged, new Action<int, int>(OnResolutionChanged));
			Cursor.visible = false;
		}

		private void OnApplicationFocus(bool focus)
		{
			Cursor.visible = !focus;
		}

		private void OnResolutionChanged(int newW, int newH)
		{
			Canvas.ForceUpdateCanvases();
			canvasScaleFactor = GetComponentInParent<Canvas>().scaleFactor;
		}

		private void InputTick()
		{
			if (CurrentCursor == CursorState.Physical || SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove)
			{
				cursorRT.position = Input.mousePosition;
			}
			else
			{
				if (CurrentCursor == CursorState.None)
				{
					return;
				}
				Cleverous.Prodigy.PlayerInput input = SingletonBehaviour<InputBroker>.Instance.GetInput();
				if (input.MoveRaw != Vector3.zero)
				{
					Vector3 vector = (float)Screen.width * 0.5f * Time.unscaledDeltaTime * input.MoveRaw * (1f + (float)SaveData.SettingsSave.mouseSenseOverride * 0.25f);
					Vector3 vector2 = cursorRT.position + vector;
					vector2 = new Vector3(Mathf.Clamp(vector2.x, cursorRT.sizeDelta.x * 0.5f, Screen.width), Mathf.Clamp(vector2.y, cursorRT.sizeDelta.y * 0.5f, Screen.height), 0f);
					cursorRT.position = vector2;
				}
				PointerEventData pointerEventData = new PointerEventData(EventSystem.current);
				pointerEventData.position = new Vector2(cursorRT.anchoredPosition.x * canvasScaleFactor, cursorRT.anchoredPosition.y * canvasScaleFactor);
				List<RaycastResult> list = new List<RaycastResult>();
				EventSystem.current.RaycastAll(pointerEventData, list);
				bool flag = false;
				for (int i = 0; i < list.Count; i++)
				{
					Selectable componentInParent = list[i].gameObject.GetComponentInParent<Selectable>();
					if (componentInParent != null)
					{
						flag = true;
						if (UtilityTG.GetSelected() != componentInParent.gameObject)
						{
							UtilityTG.SetSelected(componentInParent.gameObject);
						}
						break;
					}
				}
				if (!flag && UtilityTG.GetSelected() != null)
				{
					UtilityTG.SetSelected(null);
				}
			}
		}

		private void OnDestroy()
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
				instance.OnInputBehaviorChanged = (Action<InputBroker.InputBehavior>)Delegate.Remove(instance.OnInputBehaviorChanged, new Action<InputBroker.InputBehavior>(OnInputBehaviorChange));
			}
			Game.OnInputTick = (Action)Delegate.Remove(Game.OnInputTick, new Action(InputTick));
			ScreenInfo.OnScreenResolutionChanged = (Action<int, int>)Delegate.Remove(ScreenInfo.OnScreenResolutionChanged, new Action<int, int>(OnResolutionChanged));
		}

		public void SetVirtualCursorActive(bool state)
		{
			UpdateCursorState(state ? CursorState.Virtual : ((SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior != InputBroker.InputBehavior.ClickToMove) ? CursorState.None : CursorState.Physical));
			wantsVirtualActive = state;
		}

		private void OnInputBehaviorChange(InputBroker.InputBehavior inputBehavior)
		{
			UpdateCursorState((inputBehavior != InputBroker.InputBehavior.ClickToMove) ? (wantsVirtualActive ? CursorState.Virtual : CursorState.None) : CursorState.Physical);
			if (inputBehavior == InputBroker.InputBehavior.Free)
			{
				Vector2 vector = new Vector2((float)Screen.width * 0.5f, (float)Screen.height * 0.5f);
				if (Mouse.current != null)
				{
					Mouse.current.WarpCursorPosition(vector);
				}
				cursorRT.anchoredPosition = vector;
			}
		}
	}
