	public class PlayerManager : SingletonBehaviour<PlayerManager>
	{
		public enum SpawnResult
		{
			Failed,
			Spawned,
			Moved
		}

		public static Action<Player> OnPlayerSpawn;

		[SerializeField]
		private Player playerPrefab;

		private Player activePlayer;

		public SpawnResult RequestPlayerSpawn(Vector3 position, Quaternion rotation, bool forceRespawn = false)
		{
			if (playerPrefab == null)
			{
				return SpawnResult.Failed;
			}
			if (activePlayer != null)
			{
				if (!forceRespawn)
				{
					activePlayer.TeleportToPosition(position);
					activePlayer.myTransform.rotation = rotation;
					OnPlayerSpawn?.Invoke(activePlayer);
					return SpawnResult.Moved;
				}
				UnityEngine.Object.Destroy(activePlayer.gameObject);
			}
			activePlayer = UnityEngine.Object.Instantiate(playerPrefab);
			activePlayer.TeleportToPosition(position);
			activePlayer.myTransform.rotation = rotation;
			OnPlayerSpawn?.Invoke(activePlayer);
			return SpawnResult.Spawned;
		}
	}
	public class PostProcessSettingsHelper : MonoBehaviour
	{
		private Volume myPPVolume;

		private void Awake()
		{
			myPPVolume = GetComponent<Volume>();
			if (SaveData.SettingsSave != null)
			{
				float brightnessOverride = SaveData.SettingsSave.brightnessOverride;
				if (!Mathf.Approximately(brightnessOverride, 0f))
				{
					SetBrightness(brightnessOverride);
				}
			}
			SaveData.OnBrightnessChanged = (Action<float>)Delegate.Combine(SaveData.OnBrightnessChanged, new Action<float>(SetBrightness));
		}

		private void OnDestroy()
		{
			SaveData.OnBrightnessChanged = (Action<float>)Delegate.Remove(SaveData.OnBrightnessChanged, new Action<float>(SetBrightness));
		}

		private void SetBrightness(float value)
		{
			value = Mathf.Clamp(value, -1f, 1f);
			float w = MathTG.Remap(Mathf.Clamp01(value), 0f, 1f, 0f, 0.25f);
			float w2 = MathTG.Remap(value, -1f, 1f, -0.5f, 1f);
			if (myPPVolume.profile.TryGet<LiftGammaGain>(out var component))
			{
				component.gamma.Override(new Vector4(1f, 1f, 1f, w));
				component.gain.Override(new Vector4(1f, 1f, 1f, w2));
			}
		}
	}
