	[Serializable]
	public class ItemSaveData
	{
		public int slotIndex;

		public WeaponSet weaponSet;

		public string refId;

		public string baseName;

		public List<string> nameDamagePrefixes;

		public string uniqueNamePrefixKey1;

		public string uniqueNamePrefixKey2;

		public string namePrefix;

		public string nameSuffix;

		public string name;

		public int splitterIndex;

		public int uses;

		public int originalUses;

		public bool unique;

		public bool artifact;

		public bool isQuestItem;

		public bool lockedForSelling;

		public TrapType trapType;

		public bool identified;

		public int sockets;

		public HeroType heroType;

		public int value;

		public float armorBonus;

		public Rank rank;

		public ItemGrade grade;

		public TarotFlavor tarotFlavor;

		public int tarotLevel;

		public List<ElementAmount> damageBonuses;

		public List<EffectSave> effects;

		[SerializeReference]
		public List<ItemSaveData> internalItems;

		public bool forcePickupHold;

		public string ItemDisplayName
		{
			get
			{
				string text = null;
				if (!identified || artifact || heroType != 0)
				{
					text = I2Loca.Get(baseName);
				}
				else
				{
					text = "";
					if (nameDamagePrefixes != null)
					{
						foreach (string nameDamagePrefix in nameDamagePrefixes)
						{
							text = text + I2Loca.Get(nameDamagePrefix) + " " + text;
						}
					}
					text += I2Loca.Get(baseName);
					if (unique)
					{
						if (string.IsNullOrEmpty(uniqueNamePrefixKey1) || string.IsNullOrEmpty(uniqueNamePrefixKey2))
						{
							UnityEngine.Debug.LogError("Unique item " + baseName + " has null or empty unique name key(s) (key1: " + uniqueNamePrefixKey1 + ", key2: " + uniqueNamePrefixKey2 + ")");
						}
						else
						{
							string text2 = ((splitterIndex == 0) ? "" : "'");
							text = I2Loca.GetIgnoreLinebreaksFormat("ItemUniqueNamePrefix", I2Loca.Get(uniqueNamePrefixKey1) + text2 + I2Loca.Get(uniqueNamePrefixKey2), text);
						}
					}
					else if (!string.IsNullOrEmpty(namePrefix))
					{
						text = I2Loca.Get(namePrefix) + " " + text;
					}
					if (!string.IsNullOrEmpty(nameSuffix))
					{
						text = text + " " + I2Loca.GetFormat("ItemUniqueNameSuffix", I2Loca.Get(nameSuffix));
					}
				}
				if (grade != 0)
				{
					text = "<style=C1>" + I2Loca.Get(grade.ToString()) + "</style> " + text;
				}
				if (rank != 0)
				{
					text = I2Loca.GetFormat($"ItemRankPrefix_{rank}", text);
				}
				return text;
			}
		}

		public bool MatchesItem(Item item)
		{
			if (refId != item.refId || baseName != item.itemBaseName || uniqueNamePrefixKey1 != item.uniqueNamePrefixKey1 || uniqueNamePrefixKey2 != item.uniqueNamePrefixKey2 || namePrefix != item.namePrefixKey || nameSuffix != item.nameSuffixKey || name != item.itemName)
			{
				return false;
			}
			if (item.isQuestItem != isQuestItem || item.isUnique != unique || item.isArtifact != artifact)
			{
				return false;
			}
			return true;
		}

		public bool MatchesOtherSave(ItemSaveData other)
		{
			if (refId != other.refId || baseName != other.baseName || nameDamagePrefixes != other.nameDamagePrefixes || uniqueNamePrefixKey2 != other.uniqueNamePrefixKey2 || namePrefix != other.namePrefix || nameSuffix != other.nameSuffix || name != other.name)
			{
				return false;
			}
			if (other.isQuestItem != isQuestItem || other.unique != unique || other.artifact != artifact)
			{
				return false;
			}
			return true;
		}

		public ItemSaveData CreatePartyMemberCopy()
		{
			ItemSaveData itemSaveData = new ItemSaveData
			{
				slotIndex = slotIndex,
				weaponSet = weaponSet,
				refId = refId,
				baseName = baseName,
				uniqueNamePrefixKey1 = uniqueNamePrefixKey1,
				uniqueNamePrefixKey2 = uniqueNamePrefixKey2,
				namePrefix = namePrefix,
				nameSuffix = nameSuffix,
				name = name,
				splitterIndex = splitterIndex,
				nameDamagePrefixes = ((nameDamagePrefixes != null) ? new List<string>(nameDamagePrefixes) : null),
				uses = uses,
				originalUses = originalUses,
				unique = unique,
				artifact = artifact,
				isQuestItem = isQuestItem,
				trapType = trapType,
				identified = identified,
				sockets = sockets,
				heroType = heroType,
				value = value,
				armorBonus = armorBonus,
				rank = rank,
				grade = grade,
				tarotFlavor = tarotFlavor,
				tarotLevel = tarotLevel,
				lockedForSelling = false,
				forcePickupHold = false,
				damageBonuses = damageBonuses?.Select((ElementAmount e) => e.Clone()).ToList(),
				effects = effects?.Select((EffectSave e) => e.Clone()).ToList()
			};
			if (internalItems != null)
			{
				itemSaveData.internalItems = new List<ItemSaveData>();
				foreach (ItemSaveData internalItem in internalItems)
				{
					if (internalItem != null)
					{
						itemSaveData.internalItems.Add(internalItem.CreatePartyMemberCopy());
					}
				}
			}
			return itemSaveData;
		}
	}
