	[Serializable]
	public class RealmSave
	{
		public RealmData.RealmId realm;

		public DungeonStorage dungeonSave;

		public PortalSave portalSave;

		public List<DroppedItemSaveData> droppedItems;

		public int latestDungeonDepth;

		public int maxDepthReached;

		public DungeonSaveData GetDungeonSave(int depth)
		{
			ValidateDungeonSaves();
			if (dungeonSave == null)
			{
				dungeonSave = new DungeonStorage();
			}
			if (dungeonSave.dungeons == null)
			{
				dungeonSave = new DungeonStorage
				{
					dungeons = new List<DungeonSaveData>(),
					latestDepths = new List<int>()
				};
			}
			return dungeonSave.dungeons.Find((DungeonSaveData d) => d.depth == depth);
		}

		public void SetDungeonSave(int depth, DungeonSaveData dungeonSaveData)
		{
			ValidateDungeonSaves();
			if (dungeonSave == null)
			{
				dungeonSave = new DungeonStorage();
			}
			if (dungeonSave.dungeons == null)
			{
				dungeonSave = new DungeonStorage
				{
					dungeons = new List<DungeonSaveData>(),
					latestDepths = new List<int>()
				};
			}
			DungeonSaveData item = dungeonSave.dungeons.Find((DungeonSaveData save) => save.depth == depth);
			dungeonSave.dungeons.Remove(item);
			if (dungeonSaveData != null)
			{
				dungeonSave.dungeons.Add(dungeonSaveData);
			}
		}

		private void ValidateDungeonSaves()
		{
			if (dungeonSave == null || dungeonSave.dungeons == null)
			{
				return;
			}
			RealmData.RealmId dungeonTownRealm = Fate.GetDungeonTownRealm(realm);
			RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(dungeonTownRealm);
			if (realmSave == null)
			{
				return;
			}
			int num = -1;
			if (realmSave.portalSave != null && realmSave.portalSave.portalSaves != null)
			{
				foreach (PortalSaveData portalSafe in realmSave.portalSave.portalSaves)
				{
					if (portalSafe.dungeonRealm == SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm)
					{
						num = portalSafe.levelDepth;
						break;
					}
				}
			}
			for (int i = 0; i < dungeonSave.dungeons.Count; i++)
			{
				DungeonSaveData dungeonSaveData = dungeonSave.dungeons[i];
				if ((num == -1 || dungeonSaveData.depth != num) && !dungeonSave.latestDepths.Contains(dungeonSaveData.depth))
				{
					UnityEngine.Debug.Log($"Removing dungeon save for depth {dungeonSaveData.depth}");
					dungeonSave.dungeons.RemoveAt(i--);
				}
			}
			string text = "";
			for (int j = 0; j < dungeonSave.latestDepths.Count; j++)
			{
				if (j != 0)
				{
					text += ", ";
				}
				text += dungeonSave.latestDepths[j];
			}
			UnityEngine.Debug.Log($"Validating dungeon saves for {realm}. portal depth: {num}, latest depths: {text}");
		}

		public void SetLastVisitedDungeonDepth(int depth)
		{
			if (dungeonSave == null)
			{
				dungeonSave = new DungeonStorage();
			}
			if (dungeonSave.dungeons == null)
			{
				dungeonSave = new DungeonStorage
				{
					dungeons = new List<DungeonSaveData>(),
					latestDepths = new List<int>()
				};
			}
			if (dungeonSave.latestDepths.Count > 0)
			{
				if (latestDungeonDepth != depth)
				{
					if (dungeonSave.latestDepths.Count >= 3)
					{
						dungeonSave.latestDepths.RemoveAt(0);
					}
					dungeonSave.latestDepths.Add(depth);
				}
			}
			else
			{
				dungeonSave.latestDepths.Add(depth);
			}
			latestDungeonDepth = depth;
		}
	}
