	public class FateSaveData
	{
		public RealmStorage realmSaveData;

		public PlayerSaveData playerSaveData;

		public TutorialSaveData tutorialSaveData;

		public ItemStorage itemSaveData;

		public ItemStorage petItemSaveData;

		public ItemStorage stashStorage;

		public QuestStorage questSaveData;

		public SummonStorage summonSaveData;

		public HeroStatueData druantiaHeroData;

		public HeroStatueData typhonHeroData;

		public List<PartyMemberSaveData> partySaveDatas;

		public DLCStorage dlcSaveData;

		public RealmSave GetRealmSave(RealmData.RealmId targetRealm)
		{
			if (realmSaveData == null)
			{
				realmSaveData = new RealmStorage
				{
					realms = new List<RealmSave>()
				};
			}
			if (realmSaveData.realms == null)
			{
				realmSaveData.realms = new List<RealmSave>();
			}
			RealmSave realmSave = realmSaveData.realms.Find((RealmSave r) => r.realm == targetRealm);
			if (realmSave == null)
			{
				realmSave = new RealmSave
				{
					dungeonSave = new DungeonStorage(),
					realm = targetRealm
				};
				realmSaveData.realms.Add(realmSave);
			}
			return realmSave;
		}

		public DLCSave GetDLCSave(Fate.DLC targetDlc)
		{
			if (dlcSaveData == null)
			{
				dlcSaveData = new DLCStorage
				{
					dlcs = new List<DLCSave>()
				};
			}
			if (dlcSaveData.dlcs == null)
			{
				dlcSaveData.dlcs = new List<DLCSave>();
			}
			DLCSave dLCSave = dlcSaveData.dlcs.Find((DLCSave d) => d.targetDlc == targetDlc);
			if (dLCSave == null)
			{
				dLCSave = new DLCSave
				{
					targetDlc = targetDlc
				};
				dlcSaveData.dlcs.Add(dLCSave);
			}
			return dLCSave;
		}

		public int GetLatestDepth(RealmData.RealmId targetRealm)
		{
			RealmSave realmSave = GetRealmSave(targetRealm);
			if (realmSave == null)
			{
				UnityEngine.Debug.LogWarning($"No realm save for {targetRealm} exists, therefore no latest dungeon depth can be gotten. Returning -1");
				return -1;
			}
			int latestDungeonDepth = realmSave.latestDungeonDepth;
			if (latestDungeonDepth == -1)
			{
				UnityEngine.Debug.LogWarning($"Invalid latest dungeon depth found for realm {targetRealm}: {latestDungeonDepth}");
			}
			return latestDungeonDepth;
		}

