		public static void Init(Action onDone)
		{
			CoroutineSlave.StartCoroutine(InitRoutine(onDone));
		}

		private static IEnumerator InitRoutine(Action onDone)
		{
			if (!HasInitialized)
			{
				preSaveActions = new List<Action<FateSaveData>>();
				preSaveMainThreadActions = null;
				temporaryTaskList = new List<Task>();
				saveIsWaitingForMoreActions = false;
				isLoading = false;
				isSaving = false;
				SingletonBehaviour<SaveManager>.AssertInstance();
				while (!SaveManager.HasInitialized)
				{
					yield return new WaitForSeconds(0.1f);
				}
				HasInitialized = true;
				Load(onDone);
			}
		}

		public static void AddPreSaveTask(Action<FateSaveData> action)
		{
			if (preSaveActions == null)
			{
				UnityEngine.Debug.LogWarning("AddPreSaveTask called without proper SaveData Initialization. Did you run the game from a scene other than Startup/MainMenu?");
			}
			else
			{
				preSaveActions.Add(action);
			}
		}

		public static void RemovePreSaveTask(Action<FateSaveData> action)
		{
			if (preSaveActions == null)
			{
				UnityEngine.Debug.LogWarning("RemovePreSaveTask called without proper SaveData Initialization. Did you run the game from a scene other than Startup/MainMenu?");
			}
			else
			{
				preSaveActions.Remove(action);
			}
		}

		public static void AddPreSaveMainThreadTask(Action<FateSaveData> action)
		{
			preSaveMainThreadActions = (Action<FateSaveData>)Delegate.Combine(preSaveMainThreadActions, action);
		}

		public static void RemovePreSaveMainThreadTask(Action<FateSaveData> action)
		{
			preSaveMainThreadActions = (Action<FateSaveData>)Delegate.Remove(preSaveMainThreadActions, action);
		}

		public static SaveSlot GetActiveSaveSlotForGame(Fate.FateVer fateVer, bool trySetIfInvalid)
		{
			int num = (int)fateVer;
			int index = currentSaveSlotIndices[num];
			if (SaveSlots.IsValidIndex(index) && SaveSlots[index].targetGame == fateVer)
			{
				return SaveSlots[index];
			}
			if (trySetIfInvalid)
			{
				int num2 = SaveSlots.FindIndex((SaveSlot s) => s.targetGame == fateVer);
				if (num2 != -1)
				{
					currentSaveSlotIndices[num] = num2;
					return SaveSlots[num2];
				}
			}
			return null;
		}

