		public static void CreateNewSaveSlotFromImport(string jsonData)
		{
			SaveSlot saveSlot = JsonUtility.FromJson<SaveSlot>(jsonData);
			saveSlot.uniqueId = GenerateUniqueID();
			saveSlot.saveDataVersion = 4;
			saveSlot.saveData.questSaveData = null;
			saveSlot.saveData.realmSaveData = null;
			saveSlot.saveData.summonSaveData = null;
			if (saveSlot.saveData.tutorialSaveData != null)
			{
				saveSlot.saveData.tutorialSaveData.hasSeenWelcomeMessage = false;
			}
			saveSlot.targetGame = Fate.CurrentFateVer;
			if (saveSlot.saveData.playerSaveData == null)
			{
				saveSlot.saveData.playerSaveData = new PlayerSaveData();
			}
			saveSlot.saveData.druantiaHeroData.items = new ItemStorage();
			saveSlot.saveData.typhonHeroData.items = new ItemStorage();
			PlayerSaveData playerSaveData = saveSlot.saveData.playerSaveData;
			playerSaveData.giveStartingItems = false;
			playerSaveData.health = 0f;
			playerSaveData.petSentToTown = false;
			playerSaveData.petFleeing = false;
			playerSaveData.petHealth = 0f;
			playerSaveData.petSecondsLeftInTown = 0;
			playerSaveData.intendsToRun = true;
			playerSaveData.effects = null;
			playerSaveData.lastDungeonRealm = RealmData.RealmId.ANY;
			playerSaveData.lastScene = Scene.Startup;
			playerSaveData.posInLastScene = default(Vector3);
			RemoveForbiddenItems(ref saveSlot.saveData.itemSaveData);
			RemoveForbiddenItems(ref saveSlot.saveData.petItemSaveData);
			RemoveForbiddenItems(ref saveSlot.saveData.stashStorage);
			saveSlot.saveState = SaveSlotState.Normal;
			SaveSlots.Add(saveSlot);
			currentSaveSlotIndices[(int)Fate.CurrentFateVer] = SaveSlots.Count - 1;
			OnActiveSaveSlotChanged?.Invoke(CurrentSaveSlot);
			static void RemoveForbiddenItems(ref ItemStorage targetItemStorage)
			{
				ItemDisallows disallowsByGame = SingletonBehaviour<FateDB>.Instance.GetDisallowsByGame(Fate.CurrentFateVer);
				if (disallowsByGame != null && (disallowsByGame.disallowedTypes != null || disallowsByGame.disallowedItemDatas != null))
				{
					List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
					for (int num = targetItemStorage.items.Count - 1; num > 0; num--)
					{
						string basename = targetItemStorage.items[num].baseName;
						ItemData itemData = allItems.Find((ItemData a) => a.displayName == basename);
						if (itemData == null)
						{
							targetItemStorage.items.RemoveAt(num);
						}
						else if (disallowsByGame.disallowedTypes != null && disallowsByGame.disallowedTypes.FindIndex((ItemType p) => p == itemData.itemType) != -1)
						{
							targetItemStorage.items.RemoveAt(num);
						}
						else if (disallowsByGame.disallowedItemDatas != null && disallowsByGame.disallowedItemDatas.FindIndex((ItemData p) => p == itemData) != -1)
						{
							targetItemStorage.items.RemoveAt(num);
						}
					}
				}
			}
		}

		public static void CreateNewSaveSlotFromRetirement(string oldSaveJson, NewgameUI.CharacterCreation creationInfo)
		{
			SaveSlot saveSlot = JsonUtility.FromJson<SaveSlot>(oldSaveJson);
			saveSlot.uniqueId = GenerateUniqueID();
			saveSlot.saveDataVersion = 4;
			TutorialSaveData tutorialSaveData = saveSlot.saveData.tutorialSaveData;
			uint valueOrDefault = (saveSlot.saveData.playerSaveData?.lineage).GetValueOrDefault(0u);
			saveSlot.saveData = new FateSaveData
			{
				tutorialSaveData = tutorialSaveData
			};
			if (saveSlot.saveData.tutorialSaveData != null)
			{
				saveSlot.saveData.tutorialSaveData.hasSeenWelcomeMessage = false;
			}
			saveSlot.saveData.itemSaveData = new ItemStorage
			{
				items = new List<ItemSaveData>()
			};
			if (SingletonBehaviour<PlayerStatus>.Instance.HeirloomItem != null)
			{
				ItemSaveData itemSaveData = new ItemSaveData();
				SingletonBehaviour<PlayerStatus>.Instance.HeirloomItem.FillInstance(itemSaveData);
				saveSlot.saveData.itemSaveData.items.Add(itemSaveData);
				SingletonBehaviour<PlayerStatus>.Instance.HeirloomItem = null;
			}
			saveSlot.saveState = SaveSlotState.Normal;
			PlayerSaveData playerSaveData = new PlayerSaveData();
			playerSaveData.male = creationInfo.male;
			playerSaveData.difficulty = creationInfo.difficulty;
			playerSaveData.playerRace = creationInfo.race;
			playerSaveData.hairIndex = creationInfo.hairIndex;
			playerSaveData.headIndex = creationInfo.headIndex;
			playerSaveData.playerName = creationInfo.playerName;
			playerSaveData.petName = creationInfo.petName;
			playerSaveData.petMonsterId = creationInfo.petMonsterId;
			playerSaveData.petTransformId = null;
			playerSaveData.petTransformTimeLeft = 0;
			playerSaveData.petExperience = 0uL;
			playerSaveData.giveStartingItems = true;
			playerSaveData.intendsToRun = true;
			playerSaveData.lineage = valueOrDefault + 1;
			saveSlot.saveData.playerSaveData = playerSaveData;
			saveSlot.secondsPlayed = 0;
			SaveSlots.Add(saveSlot);
			currentSaveSlotIndices[(int)Fate.CurrentFateVer] = SaveSlots.Count - 1;
			OnActiveSaveSlotChanged?.Invoke(CurrentSaveSlot);
		}

