		private static uint GenerateUniqueID()
		{
			List<uint> list = new List<uint>();
			foreach (SaveSlot saveSlot in SaveSlots)
			{
				if (saveSlot.IsUniqueIDValid)
				{
					list.Add(saveSlot.uniqueId);
				}
			}
			uint num;
			do
			{
				num = (uint)(UnityEngine.Random.value * 4.2949673E+09f);
			}
			while (num == 0 || list.Contains(num));
			return num;
		}

