				OnActiveSaveSlotChanged?.Invoke(CurrentSaveSlot);
			}
		}

		public static void DeleteGameRequested()
		{
			SaveSlots.Remove(CurrentSaveSlot);
			currentSaveSlotIndices[(int)Fate.CurrentFateVer] = 0;
			AssertSaveData();
			RequestSave();
		}

		public static void RequestSave(Action onDone = null)
		{
			if (!HasLoaded)
			{
				UnityEngine.Debug.LogError("Save request before load has ever happened, this would overwrite the savedata, canceling.");
			}
			else if (isSaving)
			{
				pendingSaveCallbacks = (Action)Delegate.Combine(pendingSaveCallbacks, onDone);
			}
			else
			{
				CoroutineSlave.StartCoroutine(Save(onDone));
			}
		}

		public static void Load(Action callback = null)
		{
			pendingLoadCallbacks = (Action)Delegate.Combine(pendingLoadCallbacks, callback);
			if (!isLoading)
			{
				CoroutineSlave.StartCoroutine(InternalLoad());
			}
		}

		private static IEnumerator InternalLoad()
		{
			UnityEngine.Debug.Log("Starting Load");
			isLoading = true;
			float time = Time.realtimeSinceStartup;
			yield return SaveManager.LoadAsync(saveName).ContinueWith(delegate(Task<(bool isSuccess, byte[] data)> antecedent)
			{
				ParseSave(antecedent.Result.data);
				AssertSaveData();
				float num = Time.realtimeSinceStartup - time;
				isLoading = false;
				HasLoaded = true;
				UnityEngine.Debug.LogFormat("Loaded data (took {0:0.##} ms)", num * 1000f);
				pendingLoadCallbacks?.Invoke();
				pendingLoadCallbacks = null;
			}, TaskScheduler.FromCurrentSynchronizationContext());
		}

		private static void ParseSave(byte[] data)
		{
			if (data != null)
			{
				string @string = Encoding.UTF8.GetString(data);
				SaveSerialized saveSerialized = null;
				try
				{
					saveSerialized = JsonUtility.FromJson<SaveSerialized>(@string);
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
				if (saveSerialized == null)
				{
					LastPlayedFate = null;
					return;
				}
				SaveSlots = new List<SaveSlot>(saveSerialized.saveSlots);
				currentSaveSlotIndices = saveSerialized.activeSlotsPerGame;
				StatSave = saveSerialized.playerStats;
				SettingsSave = saveSerialized.settings;
				LastPlayedFate = saveSerialized.lastPlayedVersion;
			}
		}

		private static void AssertSaveData()
		{
			if (SaveSlots == null)
			{
				SaveSlots = new List<SaveSlot>();
			}
			if (currentSaveSlotIndices == null)
			{
				currentSaveSlotIndices = new int[4] { -1, -1, -1, -1 };
			}
			if (SaveSlots.Count >= 1)
			{
				for (int i = 0; i < currentSaveSlotIndices.Length; i++)
				{
					int num = currentSaveSlotIndices[i];
					Fate.FateVer idxVersion = (Fate.FateVer)i;
					if (!SaveSlots.IsValidIndex(num) || SaveSlots[num].targetGame != idxVersion)
					{
						int num2 = SaveSlots.FindIndex((SaveSlot s) => s.targetGame == idxVersion);
						if (num2 != -1)
						{
							currentSaveSlotIndices[i] = num2;
						}
						else if (num != -1)
						{
							currentSaveSlotIndices[i] = -1;
						}
					}
				}
				foreach (SaveSlot saveSlot in SaveSlots)
				{
					if (!saveSlot.IsUniqueIDValid)
					{
						saveSlot.uniqueId = GenerateUniqueID();
						UnityEngine.Debug.Log("Found invalid save slot unique ID (player name '" + saveSlot.saveData.playerSaveData.playerName + "'), giving it one.");
					}
					if (!saveSlot.IsSaveDataVersionValid)
					{
						saveSlot.saveDataVersion = 4;
						UnityEngine.Debug.Log("Save slot (player name '" + saveSlot.saveData.playerSaveData.playerName + "') had invalid save data version, setting it to current version.");
					}
					else
					{
						if (saveSlot.saveDataVersion >= 4)
						{
							continue;
						}
						UnityEngine.Debug.Log(string.Format("{0}: Found save slot (player name '{1}') with old save data version. Current version is {2}, save version is {3}", "FateSaveData", saveSlot.saveData.playerSaveData.playerName, 4, saveSlot.saveDataVersion));
						try
						{
							if (saveSlot.saveDataVersion < 1)
							{
								UnityEngine.Debug.Log("FateSaveData: Found save data with older version than 1. Nuking dungeon data.");
								foreach (RealmSave realm in saveSlot.saveData.realmSaveData.realms)
								{
									realm.portalSave = null;
									realm.dungeonSave.dungeons = null;
								}
								saveSlot.saveData.playerSaveData.posInLastScene = Vector3.zero;
								saveSlot.saveData.playerSaveData.rotInLastScene = Vector3.zero;
								if (saveSlot.saveData.playerSaveData.lastScene == Scene.Dungeon)
								{
									switch (saveSlot.targetGame)
									{
									case Fate.FateVer.Original:
										saveSlot.saveData.playerSaveData.lastScene = Scene.Town_Grove;
										break;
									case Fate.FateVer.UndiscoveredRealms:
										saveSlot.saveData.playerSaveData.lastScene = Scene.Town_Temple_Fate2;
										break;
									case Fate.FateVer.TraitorSoul:
										saveSlot.saveData.playerSaveData.lastScene = Scene.Town_Temple;
										break;
									case Fate.FateVer.CursedKing:
										saveSlot.saveData.playerSaveData.lastScene = Scene.Town_Ekbatan;
										break;
									}
								}
							}
							if (saveSlot.saveDataVersion < 2)
							{
								UnityEngine.Debug.Log("FateSaveData: Found save data with older version than 2. Resetting slot for Item_Pick in all item storages.");
								if (saveSlot.saveData.itemSaveData != null && saveSlot.saveData.itemSaveData.items != null)
								{
									foreach (ItemSaveData item in saveSlot.saveData.itemSaveData.items)
									{
										if (IsPick(item))
										{
											item.slotIndex = -1;
										}
									}
								}
								if (saveSlot.saveData.petItemSaveData != null && saveSlot.saveData.petItemSaveData.items != null)
								{
									foreach (ItemSaveData item2 in saveSlot.saveData.petItemSaveData.items)
									{
										if (IsPick(item2))
										{
											item2.slotIndex = -1;
										}
									}
								}
								if (saveSlot.saveData.partySaveDatas != null)
								{
									foreach (PartyMemberSaveData partySaveData in saveSlot.saveData.partySaveDatas)
									{
										if (partySaveData.itemStorage == null || partySaveData.itemStorage.items == null)
										{
											continue;
										}
										foreach (ItemSaveData item3 in partySaveData.itemStorage.items)
										{
											if (IsPick(item3))
											{
												item3.slotIndex = -1;
											}
										}
									}
								}
								if (saveSlot.saveData.stashStorage != null && saveSlot.saveData.stashStorage.items != null)
								{
									foreach (ItemSaveData item4 in saveSlot.saveData.stashStorage.items)
									{
										if (IsPick(item4))
										{
											item4.slotIndex = -1;
										}
									}
								}
							}
							if (saveSlot.saveDataVersion < 3)
							{
								if (saveSlot.saveData.questSaveData != null && saveSlot.saveData.questSaveData.questRealms != null)
								{
									QuestSaveRealm questSaveRealm = saveSlot.saveData.questSaveData.questRealms.Find((QuestSaveRealm r) => r.realmId == 4);
									if (questSaveRealm != null && questSaveRealm.realmQuestProgress == 0)
									{
										questSaveRealm.realmQuestProgress = -1;
									}
								}
								UnityEngine.Debug.Log("FateSaveData: Found save data with older version than 3. Resetting slot for Item_Brittlescowl in all item storages.");
								if (saveSlot.saveData.itemSaveData != null && saveSlot.saveData.itemSaveData.items != null)
								{
									foreach (ItemSaveData item5 in saveSlot.saveData.itemSaveData.items)
									{
										if (IsBrittlescowl(item5))
										{
											item5.slotIndex = -1;
										}
									}
								}
								if (saveSlot.saveData.petItemSaveData != null && saveSlot.saveData.petItemSaveData.items != null)
								{
									foreach (ItemSaveData item6 in saveSlot.saveData.petItemSaveData.items)
									{
										if (IsBrittlescowl(item6))
										{
											item6.slotIndex = -1;
										}
									}
								}
								if (saveSlot.saveData.partySaveDatas != null)
								{
									foreach (PartyMemberSaveData partySaveData2 in saveSlot.saveData.partySaveDatas)
									{
										if (partySaveData2.itemStorage == null || partySaveData2.itemStorage.items == null)
										{
											continue;
										}
										foreach (ItemSaveData item7 in partySaveData2.itemStorage.items)
										{
											if (IsBrittlescowl(item7))
											{
												item7.slotIndex = -1;
											}
										}
									}
								}
								if (saveSlot.saveData.stashStorage != null && saveSlot.saveData.stashStorage.items != null)
								{
									foreach (ItemSaveData item8 in saveSlot.saveData.stashStorage.items)
									{
										if (IsBrittlescowl(item8))
										{
											item8.slotIndex = -1;
										}
									}
								}
							}
							if (saveSlot.saveDataVersion < 4 && saveSlot.saveData.playerSaveData != null)
							{
								int levelFromExperience = Fate.GetLevelFromExperience(saveSlot.saveData.playerSaveData.experience);
								if (levelFromExperience > 199)
								{
									int num3 = levelFromExperience - 199;
									saveSlot.saveData.playerSaveData.unallocatedSkillPoints += 2 * num3;
									saveSlot.saveData.playerSaveData.unallocatedStatPoints += 5 * num3;
									UnityEngine.Debug.Log("Old version level delta: " + num3);
								}
							}
						}
						catch (Exception ex)
						{
							UnityEngine.Debug.LogError($"Exception happened when attempting to correct old save slot, from version {saveSlot.saveDataVersion} to {4}. Exception message: {ex.Message}, {ex.StackTrace}");
						}
						saveSlot.saveDataVersion = 4;
					}
				}
			}
			if (StatSave == null)
			{
				StatSave = new StatsManager.PlayerStatSaveData();
			}
			if (SettingsSave == null)
			{
				SettingsSave = new SettingsSave();
			}
			static bool IsBrittlescowl(ItemSaveData item)
			{
				if (item.baseName == "Item_Brittlescowl")
				{
					return Fate.IsItemSlotInInventoryGrid(item.slotIndex);
				}
				return false;
			}
			static bool IsPick(ItemSaveData item)
			{
				if (item.baseName == "Item_Pick")
				{
					return Fate.IsItemSlotInInventoryGrid(item.slotIndex);
				}
				return false;
			}
		}

		private static IEnumerator Save(Action callback = null)
		{
			if (!HasInitialized)
			{
				yield break;
			}
			yield return new WaitWhile(() => isSaving);
			if (saveIsWaitingForMoreActions)
			{
				UnityEngine.Debug.Log("Additional save request - bundling with pending");
				pendingSaveCallbacks = (Action)Delegate.Combine(pendingSaveCallbacks, callback);
				yield break;
			}
			pendingSaveCallbacks = callback;
			saveIsWaitingForMoreActions = true;
			yield return new WaitForSecondsRealtime(1f);
			saveIsWaitingForMoreActions = false;
			isSaving = true;
			try
			{
				preSaveMainThreadActions?.Invoke(CurrentSaveData);
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogErrorFormat("Exception running pre-save task: {0}\n{1}", ex.Message, ex);
			}
			if (preSaveActions.Count > 0)
			{
				temporaryTaskList.Clear();
				for (int j = 0; j < preSaveActions.Count; j++)
				{
					int i = j;
					temporaryTaskList.Add(Task.Run(delegate
					{
						try
						{
							preSaveActions[i](CurrentSaveData);
						}
						catch (Exception ex2)
						{
							UnityEngine.Debug.LogErrorFormat("Exception running pre-save task: {0}\n{1}", ex2.Message, ex2);
						}
					}));
				}
				Task waitTask = Task.WhenAll(temporaryTaskList);
				while (!waitTask.IsCompleted)
				{
					yield return null;
				}
			}
			SaveSerialized obj = new SaveSerialized
			{
				activeSlotsPerGame = currentSaveSlotIndices,
				saveSlots = SaveSlots.ToArray(),
				playerStats = StatSave,
				lastPlayedVersion = Fate.CurrentFateVer,
				settings = SettingsSave
			};
			LastPlayedFate = Fate.CurrentFateVer;
			string s = JsonUtility.ToJson(obj);
			float startTime = Time.realtimeSinceStartup;
			yield return SaveManager.SaveAsync(saveName, Encoding.UTF8.GetBytes(s));
			isSaving = false;
			float num = Time.realtimeSinceStartup - startTime;
			UnityEngine.Debug.LogFormat("Saved data (took {0:0.##} ms)", num * 1000f);
			if (pendingSaveCallbacks != null)
			{
				pendingSaveCallbacks();
				pendingSaveCallbacks = null;
			}
		}
	}
	public class Startup : MonoBehaviour
	{
		[SerializeField]
		private UniversalRendererData[] rendererDatas;

		public string forceLanguageCode = "ja";

		private void Awake()
		{
			UtilityTG.EnsureCoroutineSlave();
		}

		private void Start()
		{
			SingletonBehaviour<LoadingScreenUI>.Instance.SetToDefault();
			SingletonBehaviour<LoadingScreenUI>.Instance.ShowLoading(fadeIn: false);
			PlatformManager.OnPlatformInitialized = (Action)Delegate.Combine(PlatformManager.OnPlatformInitialized, (Action)delegate
			{
				try
				{
					SaveData.Init(delegate
					{
						string text = ((UnityEngine.Debug.isDebugBuild && !string.IsNullOrEmpty(forceLanguageCode)) ? forceLanguageCode : SaveData.SettingsSave.overrideLanguageCode);
						if (string.IsNullOrEmpty(text))
						{
							text = PlatformManager.GetPlatformLanguage();
							if (string.IsNullOrEmpty(text))
							{
								UnityEngine.Debug.Log("Got nothing from GetPlatformLanguage, defaulting to en");
								text = "en";
							}
						}
						I2Loca.SetLanguageFromCode(text);
						SceneLoad.LoadAsync(Scene.Engagement, save: false, withLoadingScreen: false);
						SettingsSave settingsSave = SaveData.SettingsSave;
						if (settingsSave != null)
						{
							if (SingletonBehaviour<AudioManager>.InstanceExists())
							{
								SingletonBehaviour<AudioManager>.Instance.SetEffectsVol(settingsSave.soundVolume);
								SingletonBehaviour<AudioManager>.Instance.SetMusicVol(settingsSave.musicVolume);
								SingletonBehaviour<AudioManager>.Instance.SetVoiceVol(settingsSave.voiceVolume);
							}
							else
							{
								UnityEngine.Debug.LogWarning("AudioManager doesn't exist or hasn't been loaded yet.");
							}
							UpdateAmbientOcclusion();
						}
					});
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
				SingletonBehaviour<NameGenerator>.AssertInstance();
			});
			SingletonBehaviour<PlatformManager>.AssertInstance();
		}

		private void UpdateAmbientOcclusion()
		{
			if (SaveData.SettingsSave == null)
			{
				UnityEngine.Debug.LogWarning("Could not set ambient occlusion because settings save is null");
				return;
			}
			UniversalRendererData[] array = rendererDatas;
			foreach (UniversalRendererData universalRendererData in array)
			{
				ScriptableRendererFeature scriptableRendererFeature = universalRendererData.rendererFeatures.Find((ScriptableRendererFeature x) => x.GetType().FullName == "UnityEngine.Rendering.Universal.ScreenSpaceAmbientOcclusion");
				if (scriptableRendererFeature != null)
				{
					scriptableRendererFeature.SetActive(SaveData.SettingsSave.ambientOcclusion);
				}
				else
				{
					UnityEngine.Debug.LogWarning("Rederer data " + universalRendererData.name + " is missing the SSAO render feature\t.");
				}
			}
		}
	}
	public class ClickInterceptUI : MonoBehaviour, IPointerEnterHandler, IEventSystemHandler, IPointerExitHandler
	{
		private bool blocking;

		public void OnPointerEnter(PointerEventData eventData)
		{
			if (!blocking)
			{
				InputBlocker.uiBlockers++;
			}
			blocking = true;
		}

		public void OnPointerExit(PointerEventData eventData)
		{
			if (blocking)
			{
				InputBlocker.uiBlockers--;
			}
			blocking = false;
		}

		private void OnDisable()
		{
			if (blocking)
			{
				InputBlocker.uiBlockers--;
			}
			blocking = false;
		}
	}
	public class DemoOverlay : SingletonBehaviour<DemoOverlay>
	{
		public static readonly TimeSpan DemoTime = new TimeSpan(0, 12, 0);

		public static string DemoReplacementText = "FATE: Reawakened is currently in development. This demo has some features and options disabled. Please enjoy this gameplay experience";

		public static bool EndingDemo = false;

		private TimeSpan currentTimeLeft;

		public GameObject timerParent;

		public TextMeshProUGUI timerText;

		public GameObject winScreenGO;

		public CanvasGroup winHeaderCG;

		public GameObject controllerParent;

		public Button controllerStartButton;

		private Action onControllerScreenDone;

		private Coroutine timerRoutine;

		protected override bool DontDestroy => true;

		public TimeSpan TimeRemaining => currentTimeLeft;

		public bool TimerRunning
		{
			get
			{
				if (timerRoutine != null)
				{
					return currentTimeLeft.TotalSeconds > 1.0;
				}
				return false;
			}
		}

		public static void EndDemo(bool firstShow, bool beatTheDragon = false)
		{
			EndingDemo = true;
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				SingletonBehaviour<InputBroker>.Instance.gameObject.SetActive(value: false);
			}
			SingletonBehaviour<PromptUI>.Instance.ForceClosePrompt();
			SimpleSingletonBehaviour<PlayerUI>.Instance.CloseTabs();
			SaveData.ClearCurrentSave();
			SingletonBehaviour<DemoOverlay>.Instance.HideTimer();
			SingletonBehaviour<DemoOverlay>.Instance.ResetTimer();
			SingletonBehaviour<QuestManager>.Instance.ResetQuests();
			SingletonBehaviour<FateChoiceUI>.Instance.Demo_FirstShow = firstShow;
			SingletonBehaviour<AudioManager>.Instance.StopMusic(AudioData.AudioClipName.DungeonMusic);
			if (beatTheDragon)
			{
				SingletonBehaviour<DemoOverlay>.Instance.winHeaderCG.alpha = 0f;
				SingletonBehaviour<DemoOverlay>.Instance.winScreenGO.SetActive(value: true);
				SingletonBehaviour<SystemOverlay>.Instance.FadeToBlack(delegate
				{
					TweenTG.TweenTo(SingletonBehaviour<DemoOverlay>.Instance.winHeaderCG, 1f, 2f);
					SingletonBehaviour<DemoOverlay>.Instance.StartCoroutine(UtilityTG.DelayedInvoke(8f, delegate
					{
						TweenTG.TweenTo(SingletonBehaviour<DemoOverlay>.Instance.winHeaderCG, 0f, 1f);
					}));
					SingletonBehaviour<DemoOverlay>.Instance.StartCoroutine(UtilityTG.DelayedInvoke(10f, delegate
					{
						SingletonBehaviour<DemoOverlay>.Instance.winScreenGO.SetActive(value: false);
						SceneLoad.LoadMainMenuCurrentGame(saveFirst: false, delegate
						{
							SingletonBehaviour<SystemOverlay>.Instance.FadeToClear(delegate
							{
								EndingDemo = false;
							}, ignoreIfAlreadyClear: false);
						});
					}));
				});
				return;
			}
			SingletonBehaviour<DemoOverlay>.Instance.winScreenGO.SetActive(value: false);
			SingletonBehaviour<SystemOverlay>.Instance.FadeToBlack(delegate
			{
				SceneLoad.LoadMainMenuCurrentGame(saveFirst: false, delegate
				{
					SingletonBehaviour<SystemOverlay>.Instance.FadeToClear(delegate
					{
						EndingDemo = false;
					}, ignoreIfAlreadyClear: false);
				});
			});
		}

		protected override void Init()
		{
			ResetTimer();
			HideTimer();
			controllerStartButton.onClick.AddListener(OnControllerStartButton);
		}

		public void ShowControllerScreen(Action onDone)
		{
			controllerParent.SetActive(value: true);
			onControllerScreenDone = onDone;
		}

		private void OnControllerStartButton()
		{
			controllerParent.SetActive(value: false);
			onControllerScreenDone?.Invoke();
			onControllerScreenDone = null;
		}

		public void ResetTimer()
		{
			currentTimeLeft = DemoTime;
			if (timerRoutine != null)
			{
				StopCoroutine(timerRoutine);
				timerRoutine = null;
			}
		}

		public void ShowTimer()
		{
			timerParent.SetActive(value: true);
			timerText.text = currentTimeLeft.ToString("mm':'ss");
		}

		public void HideTimer()
		{
			if (timerRoutine != null)
			{
				StopCoroutine(timerRoutine);
				timerRoutine = null;
			}
			timerParent.SetActive(value: false);
		}

		public void StartTimer()
		{
			if (timerRoutine != null)
			{
				StopCoroutine(timerRoutine);
			}
			timerRoutine = StartCoroutine(Timer());
		}

		private IEnumerator Timer()
		{
			TimeSpan second = new TimeSpan(0, 0, 1);
			WaitForSeconds secondWait = new WaitForSeconds(1f);
			while (currentTimeLeft.TotalSeconds > 0.0)
			{
				currentTimeLeft = currentTimeLeft.Subtract(second);
				timerText.text = currentTimeLeft.ToString("mm':'ss");
				yield return secondWait;
			}
			UnityEngine.Debug.Log("Timer End");
			EndDemo(firstShow: false);
		}
	}
