		private void OnDisable()
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
				instance.OnInputBehaviorChanged = (Action<InputBroker.InputBehavior>)Delegate.Remove(instance.OnInputBehaviorChanged, new Action<InputBroker.InputBehavior>(OnInputBehaviourChanged));
			}
		}

		private void OnInputBehaviourChanged(InputBroker.InputBehavior behavior)
		{
			UtilityTG.UIForceRebuildLayout(base.gameObject);
		}

		public void Show(Mode mode)
		{
			showing = true;
			SetMode(mode);
			base.gameObject.SetActive(value: true);
			UtilityTG.UIForceRebuildLayout(base.gameObject);
		}

		public void Hide()
		{
			showing = false;
			base.gameObject.SetActive(value: false);
		}

		private void SetMode(Mode mode)
		{
			string text2;
			switch (mode)
			{
			case Mode.Identify:
				MouseControlText.text = I2Loca.GetMultiLineFormat("IDS_STRING828", "<style=C1>" + I2Loca.Get("Item_DescriptionIdentify") + "</style>");
				text2 = I2Loca.Get("Item_DescriptionIdentify");
				ShowCancel(show: true);
				break;
			case Mode.SocketGem:
				text2 = (MouseControlText.text = I2Loca.Get("Tooltip_SocketUninstalled"));
				ShowCancel(show: true);
				break;
			case Mode.AssignToSpellWheel:
				text2 = (MouseControlText.text = I2Loca.Get("AssignSpellHintGamepad"));
				ShowCancel(show: true);
				break;
			default:
				throw new ArgumentException($"Mode {mode} not implemented");
			}
			TextMeshProUGUI[] gamepadControlTexts = GamepadControlTexts;
			for (int i = 0; i < gamepadControlTexts.Length; i++)
			{
				gamepadControlTexts[i].text = text2;
			}
		}

		private void ShowCancel(bool show)
		{
			GameObject[] array = cancelParents;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(show);
			}
		}

		private void LateUpdate()
		{
			myTransform.position = SingletonBehaviour<CursorManager>.Instance.VirtualCursor.position;
		}
	}
