			FateChoiceToggle fateChoiceToggle8 = secondOption;
			fateChoiceToggle8.onSubmit = (Action<int>)Delegate.Combine(fateChoiceToggle8.onSubmit, new Action<int>(OnChoiceSubmitted));
			FateChoiceToggle fateChoiceToggle9 = thirdOption;
			fateChoiceToggle9.onSubmit = (Action<int>)Delegate.Combine(fateChoiceToggle9.onSubmit, new Action<int>(OnChoiceSubmitted));
			InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
			instance.OnMenuCancelPerformed = (Action)Delegate.Combine(instance.OnMenuCancelPerformed, new Action(OnQuitPerformed));
		}

		private void OnDestroy()
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
				instance.OnMenuCancelPerformed = (Action)Delegate.Remove(instance.OnMenuCancelPerformed, new Action(OnQuitPerformed));
			}
		}

		private void OnChoiceDeselected()
		{
			if (!resetCharacterOnDeselect)
			{
				return;
			}
			UtilityTG.UnityDelay(delegate
			{
				if (SingletonBehaviour<InputBroker>.InstanceExists() && SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove && !firstOption.IsHoveredOrSelected && !secondOption.IsHoveredOrSelected && !thirdOption.IsHoveredOrSelected)
				{
					fateAnimator.SetInteger("Selections", 0);
				}
			});
		}

		private void OnChoiceSelected(int index)
		{
			fateAnimator.SetInteger("Selections", index + 1);
		}

		private void OnChoiceSubmitted(int index)
		{
			SingletonBehaviour<PromptUI>.Instance.ShowPrompt("SureAboutThat", delegate(bool positive)
			{
				SingletonBehaviour<AudioManager>.Instance.ForcePlayAudioClip(AudioData.AudioClipName.ButtonBasic);
				if (!positive)
				{
					firstOption.isOn = false;
					secondOption.isOn = false;
					thirdOption.isOn = false;
					if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove)
					{
						UtilityTG.SetSelected(defaultSelection.gameObject);
					}
				}
				else
				{
					SingletonBehaviour<Narrator>.Instance.ForcePlayYourLine(NarratorLines.Narrator_choice);
					int choiceIndex = index;
					fateAnimator.SetBool("SelectionAccepted", value: true);
					ChangeFatesParticles(index);
					base.gameObject.SetActive(value: false);
					fadeCanvas.gameObject.SetActive(value: true);
					float num = loadSceneDelay - 0.05f;
					TweenTG.Tween(fadeCanvas, 0f, 1f, 0f - num, Easing.Mode.SineOut);
					UtilityTG.StartCoroutine(UtilityTG.DelayedInvoke(loadSceneDelay, delegate
					{
						switch (choiceIndex)
						{
						case 0:
							OnFirstChoice();
							break;
						case 1:
							OnSecondChoice();
							break;
						case 2:
							OnThirdChoice();
							break;
						default:
							UnityEngine.Debug.LogError("Could not determine fate choice");
							break;
						}
						TweenTG.Tween(fadeCanvas, 1f, 0f, -2f, Easing.Mode.SineOut, delegate
						{
							fadeCanvas.gameObject.SetActive(value: false);
						});
					}));
				}
			});
		}

		public void ShowFateChoice(Action<bool> onDone)
		{
			base.gameObject.SetActive(value: true);
			ShowQuitButtonInputHints(SingletonBehaviour<PlayerStatus>.Instance.Difficulty != Fate.Difficulty.Hardcore);
			onFinish = onDone;
			if (SingletonBehaviour<PlayerStatus>.Instance.Difficulty == Fate.Difficulty.Hardcore)
			{
				firstOption.Setup(0, I2Loca.Get("HardcoreChoice1"));
				secondOption.Setup(1, I2Loca.Get("HardcoreChoice2"));
				thirdOption.Setup(2, I2Loca.Get("HardcoreChoice3"));
			}
			else
			{
				expCost = Math.Min((Fate.GetExperienceNeeded(Player.PlayerChar.Level) - Fate.GetExperienceNeeded(Player.PlayerChar.Level - 1)) / 10, Player.PlayerChar.experience);
				fameCost = Math.Min((Fate.GetFameNeeded(Player.PlayerChar.fameRank) - Fate.GetFameNeeded(Player.PlayerChar.fameRank - 1)) / 10, Player.PlayerChar.fame);
				goldCost = ((SingletonBehaviour<PlayerStatus>.Instance.gold < 10) ? SingletonBehaviour<PlayerStatus>.Instance.gold : (SingletonBehaviour<PlayerStatus>.Instance.gold / 10));
				firstOption.Setup(0, I2Loca.GetFormatReplaceTags("FateChoice_CurrentLocation", expCost, fameCost));
				secondOption.Setup(1, I2Loca.GetFormatReplaceTags("FateChoice_TransportNearbyLevel", goldCost));
				thirdOption.Setup(2, I2Loca.GetFormatReplaceTags("FateChoice_TransportTown", SingletonBehaviour<PlayerStatus>.Instance.TownRealm.ToString()));
			}
			Fate.SetPause(paused: true);
			ProdigyCamera.GameCamera.enabled = false;
			SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.Heartbeat);
			Player.PlayerChar.isHeartBeatPlaying = false;
			SingletonBehaviour<Narrator>.Instance.ForcePlayYourLine(NarratorLines.Narrator_choosefate);
			SingletonBehaviour<AudioManager>.Instance.ForcePlayMusic(AudioData.AudioClipName.FateChoiceMusic, stopOthers: true);
		}

		private void ShowQuitButtonInputHints(bool show)
		{
			GameObject[] array = quitButtonInputHints;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(show);
			}
		}

		private void OnEnable()
		{
			hasSelected = false;
			UtilityTG.UnityDelay(delegate
			{
				if (defaultSelection != null)
				{
					UtilityTG.SetSelected(defaultSelection.gameObject);
				}
				hasSelected = true;
			});
			fateAnimator.SetInteger("Selections", 0);
			fateAnimator.SetBool("SelectionAccepted", value: false);
			fateAnimator.Rebind();
			fateAnimator.Update(0f);
			rightSmoke.SetActive(value: false);
			rightFire.SetActive(value: true);
			leftSmoke.SetActive(value: false);
			leftFire.SetActive(value: true);
		}

		private void ChangeFatesParticles(int index)
		{
			if (index != 2)
			{
				rightSmoke.SetActive(value: true);
				rightFire.SetActive(value: false);
			}
			else
			{
				leftSmoke.SetActive(value: true);
				leftFire.SetActive(value: false);
			}
		}

		private void OnFirstChoice()
		{
			Fate.SetPause(paused: false);
			if (SingletonBehaviour<PlayerStatus>.Instance.Difficulty == Fate.Difficulty.Hardcore)
			{
				SaveData.SetSaveSlotDead(SaveData.CurrentSaveSlot);
				onFinish?.Invoke(obj: false);
				SingletonBehaviour<AudioManager>.Instance.StopMusic(AudioData.AudioClipName.DungeonMusic);
				SceneLoad.LoadMainMenuCurrentGame(saveFirst: false, delegate
				{
					Fate.SetPause(paused: false);
				});
				SingletonBehaviour<AudioManager>.Instance.ForceStopMusic(AudioData.AudioClipName.FateChoiceMusic);
				return;
			}
			ProdigyCamera.GameCamera.enabled = true;
			Player.PlayerChar.hp = Player.PlayerChar.MaxHP();
			Player.PlayerChar.experience -= expCost;
			Player.PlayerChar.fame -= fameCost;
			StatsManager.IncrementStat(Stat.FateChosen);
			onFinish?.Invoke(obj: true);
			if (LevelGenerator.currentInstance != null)
			{
				SaveData.CurrentSaveData.playerSaveData.posInLastScene = Player.PlayerChar.myTransform.position;
				SaveData.CurrentSaveData.playerSaveData.rotInLastScene = Player.PlayerChar.myTransform.rotation.eulerAngles;
				SingletonBehaviour<AudioManager>.Instance.ForceStopMusic(AudioData.AudioClipName.FateChoiceMusic);
				LevelGenerator.currentInstance.PlayDungeonMusic();
				LevelGenerator.currentInstance.ReplaceDungeon(0f, 0f, LevelGenerator.currentInstance.GetLevelDepth(), (int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, goesDown: false, useSavedPosition: true);
			}
			else
			{
				SingletonBehaviour<AudioManager>.Instance.ForceStopMusic(AudioData.AudioClipName.FateChoiceMusic);
				SceneLoad.LoadAsync(SceneLoad.GetTownScene(SingletonBehaviour<PlayerStatus>.Instance.TownRealm), save: true);
			}
		}

		private void OnSecondChoice()
		{
			Fate.SetPause(paused: false);
			if (SingletonBehaviour<PlayerStatus>.Instance.Difficulty == Fate.Difficulty.Hardcore)
			{
				SingletonBehaviour<AudioManager>.Instance.ForceStopMusic(AudioData.AudioClipName.FateChoiceMusic);
				onFinish?.Invoke(obj: false);
				SceneLoad.LoadAsync(SceneLoad.GetTownScene(Fate.CurrentFateVer), save: false, withLoadingScreen: true, delegate
				{
					SaveData.HardcoreRestart(SaveData.CurrentSaveSlot);
				});
				return;
			}
			ProdigyCamera.GameCamera.enabled = true;
			Player.PlayerChar.hp = Player.PlayerChar.MaxHP();
			SingletonBehaviour<PlayerStatus>.Instance.RemoveGold((uint)goldCost);
			StatsManager.IncrementStat(Stat.FateChosen);
			onFinish?.Invoke(obj: true);
			if (LevelGenerator.currentInstance != null)
			{
				int newLevelDepth = Math.Max(UnityEngine.Random.Range(LevelGenerator.currentInstance.GetLevelDepth() - 2, LevelGenerator.currentInstance.GetLevelDepth()), 1);
				LevelGenerator.currentInstance.ReplaceDungeon(0f, 0f, newLevelDepth, (int)SingletonBehaviour<PlayerStatus>.Instance.TownRealm, goesDown: true, useSavedPosition: false);
				SingletonBehaviour<AudioManager>.Instance.ForceStopMusic(AudioData.AudioClipName.FateChoiceMusic);
				LevelGenerator.currentInstance.PlayDungeonMusic();
			}
			else
			{
				SingletonBehaviour<AudioManager>.Instance.ForceStopMusic(AudioData.AudioClipName.FateChoiceMusic);
				SceneLoad.LoadAsync(SceneLoad.GetTownScene(SingletonBehaviour<PlayerStatus>.Instance.TownRealm), save: true);
			}
		}

		private void OnThirdChoice()
		{
			Fate.SetPause(paused: false);
			if (SingletonBehaviour<PlayerStatus>.Instance.Difficulty == Fate.Difficulty.Hardcore)
			{
				ProdigyCamera.GameCamera.enabled = true;
				Player.PlayerChar.hp = Player.PlayerChar.MaxHP();
				StatsManager.IncrementStat(Stat.FateChosen);
				SingletonBehaviour<PlayerStatus>.Instance.LostHardcoreStatus();
				SaveData.CurrentSaveSlot.saveState = SaveSlotState.Normal;
				onFinish?.Invoke(obj: true);
				if (LevelGenerator.currentInstance != null)
				{
					LevelGenerator.currentInstance.ReplaceDungeon(0f, 0f, LevelGenerator.currentInstance.GetLevelDepth(), (int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, goesDown: false, useSavedPosition: true, ignoreSavedState: false, skipSave: true);
					SingletonBehaviour<AudioManager>.Instance.ForceStopMusic(AudioData.AudioClipName.FateChoiceMusic);
					LevelGenerator.currentInstance.PlayDungeonMusic();
				}
				else
				{
					SingletonBehaviour<AudioManager>.Instance.ForceStopMusic(AudioData.AudioClipName.FateChoiceMusic);
					SceneLoad.LoadAsync(SceneLoad.GetTownScene(SingletonBehaviour<PlayerStatus>.Instance.TownRealm), save: true);
				}
				return;
			}
			ProdigyCamera.GameCamera.enabled = true;
			Player.PlayerChar.hp = Player.PlayerChar.MaxHP();
			int goldAmount;
			try
			{
				goldAmount = checked((int)SingletonBehaviour<PlayerStatus>.Instance.gold);
			}
			catch (OverflowException)
			{
				goldAmount = 1;
				UnityEngine.Debug.LogWarning("ulong to int overflow, we may need to rework the gold system in increment, level generator etc");
			}
			if (LevelGenerator.currentInstance != null)
			{
				ActiveLevel.SpawnGoldPile(LevelGenerator.currentInstance.RandomOpenPosition(Player.PlayerChar.myTransform.position, 1f, 2f), goldAmount);
				SingletonBehaviour<PlayerStatus>.Instance.RemoveGold(SingletonBehaviour<PlayerStatus>.Instance.gold);
				SingletonBehaviour<AudioManager>.Instance.ForceStopMusic(AudioData.AudioClipName.FateChoiceMusic);
				LevelGenerator.currentInstance.PlayDungeonMusic();
			}
			StatsManager.IncrementStat(Stat.FateChosen);
			onFinish?.Invoke(obj: true);
			SingletonBehaviour<AudioManager>.Instance.StopMusic(AudioData.AudioClipName.DungeonMusic);
			SceneLoad.LoadAsync(SceneLoad.GetTownScene(SingletonBehaviour<PlayerStatus>.Instance.TownRealm), save: true);
		}

		private void OnQuitPerformed()
		{
			if (!base.gameObject.activeInHierarchy || !hasSelected || PromptUI.IsPromptActive || SingletonBehaviour<PlayerStatus>.Instance.Difficulty == Fate.Difficulty.Hardcore)
			{
				return;
			}
			SingletonBehaviour<PromptUI>.Instance.ShowPrompt(I2Loca.Get("QuitPrompt"), delegate(bool positive)
			{
				if (positive)
				{
					onFinish?.Invoke(obj: false);
					SingletonBehaviour<AudioManager>.Instance.StopMusic(AudioData.AudioClipName.DungeonMusic);
					SceneLoad.LoadMainMenuCurrentGame(saveFirst: false, delegate
					{
						Fate.SetPause(paused: false);
					});
					SingletonBehaviour<AudioManager>.Instance.StopMusic();
					base.gameObject.SetActive(value: false);
				}
				else if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free)
				{
					GameObject selected = UtilityTG.GetSelected();
					if (selected == null || !selected.activeInHierarchy)
					{
						UtilityTG.SetSelected(defaultSelection.gameObject);
					}
				}
			});
		}
	}
	public class FateChoiceToggle : Toggle
	{
		[SerializeField]
		private Image bgImage;

		[SerializeField]
		private Sprite activeBgSprite;

		[SerializeField]
		private Sprite idleBgSprite;

		[SerializeField]
		private Color activeBgColor;

		[SerializeField]
		private Color idleBgColor;

		[SerializeField]
		private GameObject isOnMarker;

		[SerializeField]
		private TextMeshProUGUI choiceIndexText;

		[SerializeField]
		private TextMeshProUGUI choiceText;

		private int choiceIndex;

		private bool isSelected;

		private bool isHovered;

		public Action<int> onSubmit;

		public Action<int> onSelected;

		public Action onDeselectedOrUnhovered;

		public bool IsHoveredOrSelected
		{
			get
			{
				if (!isHovered)
				{
					return isSelected;
				}
				return true;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			Init();
		}

		private void Init()
		{
			onValueChanged.AddListener(OnValueChanged);
			UpdateVisualState();
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			isHovered = false;
			isSelected = false;
			base.isOn = false;
			UpdateVisualState();
		}

		private void OnValueChanged(bool newValue)
		{
			UpdateVisualState();
		}

		public void Setup(int choiceIndex, string text)
		{
			this.choiceIndex = choiceIndex;
			choiceIndexText.text = (choiceIndex + 1).ToString();
			choiceText.text = text;
		}

		private void UpdateVisualState()
		{
			isOnMarker.SetActive(base.isOn);
			bool flag = isHovered || isSelected;
			bgImage.sprite = (flag ? activeBgSprite : idleBgSprite);
			bgImage.color = (flag ? activeBgColor : idleBgColor);
		}

		public override void OnPointerClick(PointerEventData eventData)
		{
			base.OnPointerClick(eventData);
			PostSubmit();
		}

		public override void OnSubmit(BaseEventData eventData)
		{
			base.OnSubmit(eventData);
			PostSubmit();
		}

		private void PostSubmit()
		{
			UpdateVisualState();
			onSubmit?.Invoke(choiceIndex);
		}

		public override void OnSelect(BaseEventData eventData)
		{
			base.OnSelect(eventData);
			isSelected = true;
			UpdateVisualState();
			onSelected?.Invoke(choiceIndex);
		}

		public override void OnDeselect(BaseEventData eventData)
		{
			base.OnDeselect(eventData);
			isSelected = false;
			UpdateVisualState();
			onDeselectedOrUnhovered?.Invoke();
		}

		public override void OnPointerEnter(PointerEventData eventData)
		{
			base.OnPointerEnter(eventData);
			isHovered = true;
			UpdateVisualState();
			onSelected?.Invoke(choiceIndex);
		}

		public override void OnPointerExit(PointerEventData eventData)
		{
			base.OnPointerExit(eventData);
			isHovered = false;
			UpdateVisualState();
			onDeselectedOrUnhovered?.Invoke();
		}
	}
	public class HealthBar : MonoBehaviour
	{
		public Image normalBar;

		public Image poisonedBar;

		public RectTransform highlight;

		public RectTransform poisonedHighlight;

		public TextMeshProUGUI remainingText;

		private void Awake()
		{
			poisonedBar.gameObject.SetActive(value: false);
			normalBar.gameObject.SetActive(value: true);
			if (highlight != null)
			{
				highlight.gameObject.SetActive(value: true);
				poisonedHighlight.gameObject.SetActive(value: false);
			}
			SetHealth(1f);
		}

		public void SetHealth(float percent)
		{
			poisonedBar.fillAmount = percent;
			normalBar.fillAmount = percent;
			if (highlight != null)
			{
				highlight.anchorMin = new Vector2(highlight.anchorMin.x, percent);
				highlight.anchorMax = new Vector2(highlight.anchorMax.x, percent);
				highlight.anchoredPosition = Vector2.zero;
				poisonedHighlight.anchorMin = highlight.anchorMin;
				poisonedHighlight.anchorMax = highlight.anchorMax;
				poisonedHighlight.anchoredPosition = Vector2.zero;
			}
		}

		public void SetRemaining(int remaining)
		{
			remainingText.text = remaining.ToString();
		}

		public void SetPoisoned(bool poisoned)
		{
			poisonedBar.gameObject.SetActive(poisoned);
			normalBar.gameObject.SetActive(!poisoned);
			if (highlight != null)
			{
				poisonedHighlight.gameObject.SetActive(poisoned);
				highlight.gameObject.SetActive(!poisoned);
			}
		}
	}
	public class HealthOnlyBar : MonoBehaviour
	{
		[SerializeField]
		public enum FillType
		{
			Center,
			Right,
			Left
		}

		public RectTransform hpBarFill;

		public FillType fillType;

		private CharacterVitals activeVitals;

		private RectTransform myRectTransform;

		private void Awake()
		{
			myRectTransform = GetComponent<RectTransform>();
		}

		public void Show(CharacterVitals vitals)
		{
			if (activeVitals != null)
			{
				CharacterVitals characterVitals = activeVitals;
				characterVitals.OnHealthChanged = (Action<float>)Delegate.Remove(characterVitals.OnHealthChanged, new Action<float>(OnHealthChanged));
			}
			activeVitals = vitals;
			CharacterVitals characterVitals2 = activeVitals;
			characterVitals2.OnHealthChanged = (Action<float>)Delegate.Combine(characterVitals2.OnHealthChanged, new Action<float>(OnHealthChanged));
			switch (fillType)
			{
			case FillType.Center:
				hpBarFill.localScale = new Vector3(activeVitals.GetHealthPct(), 1f, 1f);
				break;
			case FillType.Right:
				hpBarFill.offsetMax = new Vector2(myRectTransform.rect.width * activeVitals.GetHealthPct() - myRectTransform.rect.width, hpBarFill.offsetMax.y);
				break;
			case FillType.Left:
				hpBarFill.offsetMin = new Vector2(myRectTransform.rect.width * activeVitals.GetHealthPct() - myRectTransform.rect.width, hpBarFill.offsetMin.y);
				break;
			}
		}

		private void OnHealthChanged(float health)
		{
			switch (fillType)
			{
			case FillType.Center:
				hpBarFill.localScale = new Vector3(activeVitals.GetHealthPct(), 1f, 1f);
				break;
			case FillType.Right:
				hpBarFill.offsetMax = new Vector2(myRectTransform.rect.width * activeVitals.GetHealthPct() - myRectTransform.rect.width, hpBarFill.offsetMax.y);
				break;
			case FillType.Left:
				hpBarFill.offsetMin = new Vector2(myRectTransform.rect.width * activeVitals.GetHealthPct() - myRectTransform.rect.width, hpBarFill.offsetMin.y);
				break;
			}
		}
	}
	public class HeroStatueUI : MonoBehaviour
	{
		[SerializeField]
		public TextMeshProUGUI headerText;

		[SerializeField]
		private EquipmentSlotUI[] equipmentSlots;

		[SerializeField]
		public Image buttonGlow;

		[SerializeField]
		public Button curiousButton;

		[SerializeField]
		public ItemData druantiaReward;

		[SerializeField]
		public ItemData typhonReward;

		private HeroStatueCharacter heroCharacter;

		private bool allSlotsFilled;

		private void Awake()
		{
			EquipmentSlotUI[] array = equipmentSlots;
			foreach (EquipmentSlotUI obj in array)
			{
				obj.onItemSet = (Action<ItemUI>)Delegate.Combine(obj.onItemSet, new Action<ItemUI>(OnItemUISet));
			}
			curiousButton.onClick.AddListener(delegate
			{
				if (allSlotsFilled)
				{
					SimpleSingletonBehaviour<PlayerUI>.Instance.CloseTabs();
					new Item((heroCharacter.HeroType == HeroType.Druantia) ? druantiaReward : typhonReward).Drop(heroCharacter.myTransform.position);
				}
				else
				{
					SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("HeroStatuePlaque", null);
				}
			});
		}

		public void SetCharacter(HeroStatueCharacter character)
		{
			heroCharacter = character;
			headerText.text = I2Loca.Get((heroCharacter.HeroType == HeroType.Druantia) ? "Monster_StatueofDruantiaHero" : "Monster_StatueofTyphonHero");
			List<Item> list = heroCharacter.inventory.FindAll((Item item) => item.slotIndex >= 6 && item.slotIndex < 20);
			EquipmentSlotUI[] array = equipmentSlots;
			foreach (EquipmentSlotUI slot in array)
			{
				slot.owner = heroCharacter;
				slot.SetToHeroType(heroCharacter.HeroType);
				Item item2 = list.Find((Item item) => item.slotIndex == slot.globalIndex);
				if (item2 != null)
				{
					ItemUI @object = InventoryUI.itemPool.GetObject();
					@object.Init();
					@object.SetOwner(heroCharacter);
					@object.SetItem(item2, new Vector2(64f, 64f));
					@object.SetParent(slot.transform);
					@object.SetSlots(slot);
					@object.gameObject.SetActive(value: true);
					if (!slot.TrySetItem(@object))
					{
						UnityEngine.Debug.LogError("HeroStatueUI: Failed setting up equipment for " + character.CharacterName + "!");
					}
				}
			}
			UpdateItemSlotsFilledCount();
		}

		private void OnItemUISet(ItemUI itemUI)
		{
			UpdateItemSlotsFilledCount();
		}

		private void UpdateItemSlotsFilledCount()
		{
			int num = 0;
			EquipmentSlotUI[] array = equipmentSlots;
			foreach (EquipmentSlotUI equipmentSlotUI in array)
			{
				if (!equipmentSlotUI.IsOpen && equipmentSlotUI.GetCurrentItemUI != null)
				{
					num++;
				}
			}
			allSlotsFilled = num == equipmentSlots.Length;
			buttonGlow.enabled = allSlotsFilled;
		}
	}
	public class EnchantSlotUI : ItemSlotUI
	{
		[SerializeField]
		private int slotIndex;

		[HideInInspector]
		public Character owner;

		public ItemData questItemLock;

		public Action<ItemUI, int> onSlotEquipped;

		[HideInInspector]
		public Vector2 cellSize;

		public override Character Owner => owner;

		public override SlotType GetSlotType()
		{
			return SlotType.EquipSlot;
		}

		public override bool SupportsItem(Item item)
		{
			if (questItemLock != null)
			{
				return item.itemData.displayName == questItemLock.displayName;
			}
			return base.SupportsItem(item);
		}

		public override bool TrySetItem(ItemUI item)
		{
			itemHandle = item;
			if (item != null)
			{
				RectTransform rectTransform = item.RectTransform;
				rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
				rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
				rectTransform.pivot = new Vector2(0.5f, 0.5f);
				rectTransform.anchoredPosition = Vector2.zero;
				BoxCollider2D boxCol = item.BoxCol;
				boxCol.size = rectTransform.sizeDelta * 0.85f;
				boxCol.offset = Vector2.zero;
			}
			if (!IsOpen)
			{
				onSlotEquipped?.Invoke(itemHandle, slotIndex);
			}
			else
			{
				onSlotEquipped?.Invoke(null, slotIndex);
			}
			onItemSet?.Invoke(item);
			SetHover(!IsOpen);
			return true;
		}
	}
	public class EquipmentSlotUI : ItemSlotUI
	{
		[SerializeField]
		private GameObject placeholderIcon;

		public EquipmentSlotUI pairedSlot;

		[SerializeField]
		private bool isWeaponSetSlot;

		[SerializeField]
		private Image setMarker;

		[SerializeField]
		private Sprite primarySetSprite;

		[SerializeField]
		private Sprite secondarySetSprite;

		private WeaponSet weaponSetSlot;

		[HideInInspector]
		public Character owner;

		public ItemUI GetCurrentItemUI => itemHandle;

		public bool IsWeaponSetSlot => isWeaponSetSlot;

		public WeaponSet WeaponSetSlot => weaponSetSlot;

		public override Character Owner => owner;

		public override bool IsOpen
		{
			get
			{
				if (pairedSlot != null && pairedSlot.itemHandle != null && pairedSlot.itemHandle.currentItem.itemData.IsTwoHanded)
				{
					return false;
				}
				return base.IsOpen;
			}
		}

		public override SlotType GetSlotType()
		{
			return SlotType.EquipSlot;
		}

		public override bool SupportsItem(Item item)
		{
			bool flag = base.SupportsItem(item);
			if (flag && item.category == ItemCategory.Weapon && item.itemData.IsTwoHanded && pairedSlot != null && !pairedSlot.IsOpen)
			{
				return false;
			}
			return flag;
		}

		public bool OriginalSupportsItem(Item item)
		{
			return base.SupportsItem(item);
		}

		public override void ForceClear()
		{
			base.ForceClear();
			placeholderIcon.SetActive(value: true);
		}

		public override bool TrySetItem(ItemUI item)
		{
			if (itemHandle != null && item != null && itemHandle != item)
			{
				if (item.Owner != null && item.currentItem != null && item.currentItem.equipped)
				{
					item.Owner.UnequipItem(item.currentItem);
				}
				InventoryGrid gridByCharacter = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetGridByCharacter(Owner);
				if (!(gridByCharacter != null) || !gridByCharacter.Owner.CanFitItemInInventoryGrid(item.currentItem, out var foundSlotIndex))
				{
					return false;
				}
				item.currentItem.weaponSet = WeaponSet.Invalid;
				item.currentItem.slotIndex = foundSlotIndex + 20;
				gridByCharacter.AddItemHandleToGrid(itemHandle);
			}
			itemHandle = item;
			placeholderIcon.SetActive(itemHandle == null || itemHandle.currentItem == null);
			if (item != null)
			{
				RectTransform rectTransform = item.RectTransform;
				rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
				rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
				rectTransform.pivot = new Vector2(0.5f, 0.5f);
				rectTransform.anchoredPosition = Vector2.zero;
				BoxCollider2D boxCol = item.BoxCol;
				boxCol.size = rectTransform.sizeDelta * 0.85f;
				boxCol.offset = Vector2.zero;
			}
			onItemSet?.Invoke(item);
			return true;
		}

		public override void SetHover(bool hovered)
		{
		}

		public void SetWeaponSetSlot(WeaponSet set)
		{
			weaponSetSlot = set;
			setMarker.sprite = ((weaponSetSlot == WeaponSet.Primary) ? primarySetSprite : secondarySetSprite);
		}
	}
