	public class InventoryGrid : MonoBehaviour
	{
		public GridLayoutGroup inventoryGrid;

		public Vector2Int inventorySize;

		public ItemSlotUI inventorySlotTemplate;

		private int slotOffset;

		private List<ItemSlotUI> gridSlots;

		private bool hasInitialized;

		public Character Owner { get; private set; }

		public Stash Stash { get; private set; }

		public bool IsStash { get; private set; }

		public bool HasInitialized => hasInitialized;

		public GameObject GetFirstItem()
		{
			for (int i = 0; i < gridSlots.Count; i++)
			{
				if (gridSlots[i].itemHandle != null)
				{
					return gridSlots[i].itemHandle.gameObject;
				}
			}
			return null;
		}

		private void Init()
		{
			if (!hasInitialized)
			{
				gridSlots = new List<ItemSlotUI> { inventorySlotTemplate };
				gridSlots.AssertComponentCount(inventorySize.x * inventorySize.y);
				slotOffset = 20;
				for (int i = 0; i < gridSlots.Count; i++)
				{
					gridSlots[i].parentGrid = this;
					gridSlots[i].SetHover(hovered: false);
					gridSlots[i].gameObject.SetActive(value: true);
					gridSlots[i].gridBasedIndex = i;
					gridSlots[i].globalIndex = slotOffset + i;
				}
				hasInitialized = true;
			}
		}

		public void InitGrid(Character owner, Stash stash = null)
		{
			Owner = owner;
			Stash = stash;
			IsStash = stash != null;
			Init();
		}

		public void SetOwner(Character owner)
		{
			if (Owner != owner)
			{
				ClearGrid();
			}
			Owner = owner;
		}

		public void FillGrid(List<Item> items, bool dropItemsThatDontFit)
		{
			if (gridSlots == null)
			{
				UnityEngine.Debug.LogError("Grid slots is null when filling grid");
				return;
			}
			for (int i = 0; i < items.Count; i++)
			{
				Item item = items[i];
				if (item == null)
				{
					UnityEngine.Debug.LogError("Found a null item when filling grid");
				}
				else
				{
					if (item.InEquipmentSlot || item.InHotbarSlot)
					{
						continue;
					}
					if (!item.IsSlotValid || !item.InInventoryGrid || item.slotIndex - slotOffset > gridSlots.Count)
					{
						UnityEngine.Debug.LogWarning($"Attempting to add item ({item.itemName}) outside of this grid range: Item slot index is {item.slotIndex}. This grid start index-end index: {slotOffset}-{slotOffset + gridSlots.Count}");
						continue;
					}
					if (item.slotIndex == -1)
					{
						if (!Owner.CanFitItemInInventoryGrid(item, out var foundSlotIndex))
						{
							UnityEngine.Debug.Log($"Removing item {item.itemName} from {Owner} because it did not fit in the inventory grid");
							items.RemoveAt(i--);
							if (dropItemsThatDontFit)
							{
								item.Drop(Owner.myTransform.position);
							}
							continue;
						}
						Owner.AddItemToInventory(item, AddItemReason.Transfer, foundSlotIndex);
					}
					AddItem(item);
				}
			}
		}

		public void ClearGrid()
		{
			if (gridSlots == null)
			{
				UnityEngine.Debug.LogError("Grid slots is null when clearing grid");
				return;
			}
			foreach (ItemSlotUI gridSlot in gridSlots)
			{
				if (gridSlot.itemHandle != null)
				{
					gridSlot.itemHandle.gameObject.SetActive(value: false);
				}
				gridSlot.TrySetItem(null);
			}
		}

		public bool AddItem(Item item)
		{
			if (item.slotIndex < 0)
			{
				UnityEngine.Debug.LogError($"Could not add item {item.itemName} to inventory grid, slot index invalid ({item.slotIndex})");
				return false;
			}
			ItemSlotUI[] array = FindSlots(item.slotIndex - slotOffset, item.slotsWide, item.slotsTall);
			if (array == null || array.Length == 0)
			{
				UnityEngine.Debug.LogError("Could not add item " + item.itemName + " to inventory grid, FindSlots returned null or an empty array");
				return false;
			}
			ItemSlotUI[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				if (array2[i] == null)
				{
					UnityEngine.Debug.LogError($"Null slot in inventory grid found when adding item {item.itemName}. Slot index {item.slotIndex}, item width {item.slotsWide}, height {item.slotsTall}");
					return false;
				}
			}
			ItemUI @object = InventoryUI.itemPool.GetObject();
			@object.Init();
			if (!IsStash && Owner == null)
			{
				UnityEngine.Debug.Log("Owner less item into a slot.");
			}
			@object.SetOwner(Owner);
			@object.SetItem(item, inventoryGrid.cellSize);
			@object.SetSlots(array);
			@object.SetParent(array[0].transform);
			@object.gameObject.SetActive(value: true);
			for (int j = 0; j < array.Length; j++)
			{
				array[j].ForceClear();
				array[j].TrySetItem(@object);
			}
			return true;
		}

		public bool AddItemHandleToGrid(ItemUI itemHandle)
		{
			if (itemHandle.currentItem == null || itemHandle.currentItem.slotIndex == -1)
			{
				UnityEngine.Debug.LogWarning("Could not add item handle for item " + ((itemHandle.currentItem != null) ? itemHandle.currentItem.itemName : "No Item") + ". Either the item is null or the slot index is invalid");
				return false;
			}
			Vector2Int itemSize = itemHandle.itemSize;
			for (int i = 0; i < gridSlots.Count; i++)
			{
				if (gridSlots[i].globalIndex != itemHandle.currentItem.slotIndex)
				{
					continue;
				}
				ItemSlotUI[] array = FindSlots(i, itemSize.x, itemSize.y);
				if (array != null && array.Length >= itemSize.x * itemSize.y)
				{
					if (!array[0].gameObject.activeInHierarchy)
					{
						itemHandle.gameObject.SetActive(value: false);
						return false;
					}
					itemHandle.SetSlots(array);
					itemHandle.SetParent(array[0].transform);
					itemHandle.SetOwner(Owner);
					for (int j = 0; j < array.Length; j++)
					{
						array[j].ForceClear();
						array[j].TrySetItem(itemHandle);
					}
					return true;
				}
			}
			return false;
		}

		private ItemSlotUI[] FindSlots(int startIndex, int sizeX, int sizeY)
		{
			ItemSlotUI[] array = new ItemSlotUI[sizeX * sizeY];
			int num = startIndex % inventorySize.x;
			int num2 = startIndex / inventorySize.x;
			if (num + sizeX - 1 >= inventorySize.x || num2 + sizeY - 1 >= inventorySize.y)
			{
				return null;
			}
			for (int i = 0; i < sizeY; i++)
			{
				int num3 = (num2 + i) * inventorySize.x;
				for (int j = 0; j < sizeX && gridSlots.IsValidIndex(num + j + num3); j++)
				{
					array[i * sizeX + j] = gridSlots[num + j + num3];
				}
			}
			return array;
		}

		public void RunActionOnAllItemUIs(Action<ItemUI> action)
		{
			foreach (ItemSlotUI gridSlot in gridSlots)
			{
				if (!gridSlot.IsOpen && gridSlot.itemHandle != null)
				{
					action(gridSlot.itemHandle);
				}
			}
		}
	}
