		public void Init()
		{
			if (hasInitialized)
			{
				return;
			}
			GameObject gameObject = new GameObject("_ItemPool");
			gameObject.transform.SetParent(base.transform);
			itemPool = new GameObjectCollection<ItemUI>(UnityEngine.Object.Instantiate(itemTemplate, Vector3.zero, Quaternion.identity, gameObject.transform).gameObject, 20, GameObjectCollectionObjectState.INACTIVE, activateOnGet: false);
			backButton.onClick.AddListener(SimpleSingletonBehaviour<PlayerUI>.Instance.CloseTabs);
			petSellButton.onClick.AddListener(delegate
			{
				Character pet2 = Player.PlayerChar.GetPet();
				if (pet2 != null)
				{
					Pet pet = pet2 as Pet;
					if (LevelGenerator.currentInstance == null)
					{
						SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton(I2Loca.Get("PetAlreadyInTown"), null);
					}
					else
					{
						AIState petAiState = pet.GetAIState();
						bool canSendPetHome = pet.Alive() && petAiState != AIState.InTown && petAiState != AIState.ReturningToTown && petAiState != AIState.Flee && petAiState != AIState.PassedOut && petAiState != AIState.PassingOut;
						if (canSendPetHome)
						{
							SingletonBehaviour<PromptUI>.Instance.ShowPrompt(I2Loca.GetReplaceTags("SendPetConfirm"), delegate(bool confirmed)
							{
								if (confirmed)
								{
									canSendPetHome = pet.Alive() && petAiState != AIState.InTown && petAiState != AIState.ReturningToTown && petAiState != AIState.Flee && petAiState != AIState.PassedOut && petAiState != AIState.PassingOut;
									if (!canSendPetHome)
									{
										SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
									}
									else
									{
										if (petAiState == AIState.UniqueIdle)
										{
											pet.CancelUniqueIdle();
										}
										pet.ReturnToTown();
										SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.UpdateInventory(Player.PlayerChar);
									}
								}
							});
						}
					}
				}
			});
			InitInventory(playerInventory, Player.PlayerChar);
			InitInventory(petInventory, Player.PlayerChar.GetPet());
			if (dropSlots != null)
			{
				ItemSlotDropUI[] array = dropSlots;
				for (int i = 0; i < array.Length; i++)
				{
					array[i].owner = Player.PlayerChar;
				}
			}
			PartyCharacterInScreenUI[] array2 = characterButtons;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].onClicked = delegate(Character character)
				{
					UpdateInventory(character);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				};
			}
			PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
			instance.onItemTargetingChanged = (Action)Delegate.Combine(instance.onItemTargetingChanged, new Action(OnItemTargetingChanged));
			SetToInputBrokerBehavior(SingletonBehaviour<InputBroker>.InstanceExists() ? SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior : InputBroker.InputBehavior.Free);
			InputBroker instance2 = SingletonBehaviour<InputBroker>.Instance;
			instance2.OnInputModeChanged = (Action<InputBroker.InputMode>)Delegate.Combine(instance2.OnInputModeChanged, new Action<InputBroker.InputMode>(OnInputModeChanged));
			OnInputModeChanged(SingletonBehaviour<InputBroker>.Instance.ActiveInputMode);
			hasInitialized = true;
		}

		private void OnInputModeChanged(InputBroker.InputMode mode)
		{
			if (interactAction != null)
			{
				interactAction.performed -= InteractAction_performed;
			}
			switch (mode)
			{
			case InputBroker.InputMode.Menu:
				interactAction = SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.RightClick;
				break;
			case InputBroker.InputMode.Game:
				interactAction = SingletonBehaviour<InputBroker>.Instance.Inputs.CharacterInputs.RightClick;
				break;
			default:
				interactAction = null;
				break;
			}
			if (interactAction != null)
			{
				interactAction.performed += InteractAction_performed;
			}
		}

		private void OnDestroy()
		{
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.onItemTargetingChanged = (Action)Delegate.Remove(instance.onItemTargetingChanged, new Action(OnItemTargetingChanged));
			}
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance2 = SingletonBehaviour<InputBroker>.Instance;
				instance2.OnInputModeChanged = (Action<InputBroker.InputMode>)Delegate.Remove(instance2.OnInputModeChanged, new Action<InputBroker.InputMode>(OnInputModeChanged));
			}
			if (interactAction != null)
			{
				interactAction.performed -= InteractAction_performed;
				interactAction = null;
			}
		}

		private void OnItemTargetingChanged()
		{
			bool isAnythingTargetingItem = SimpleSingletonBehaviour<PlayerUI>.Instance.IsAnythingTargetingItem;
			inputHintsRegular.SetActive(!isAnythingTargetingItem);
			inputHintsItemSelect.SetActive(isAnythingTargetingItem);
			if (isAnythingTargetingItem)
			{
				inputHintItemSelectInteractText.text = I2Loca.Get((SimpleSingletonBehaviour<PlayerUI>.Instance.IsSpellTargetingItem || (SimpleSingletonBehaviour<PlayerUI>.Instance.IsItemTargetingItem && SimpleSingletonBehaviour<PlayerUI>.Instance.itemTargetingItem.currentItem.itemType != ItemType.Gem)) ? "Item_DescriptionIdentify" : "Tooltip_SocketUninstalled");
				LayoutRebuilder.ForceRebuildLayoutImmediate(inputHintItemSelectInteractText.GetComponentInParent<LayoutGroup>(includeInactive: true).transform as RectTransform);
			}
		}

		public void SetToInputBrokerBehavior(InputBroker.InputBehavior inputBehavior)
		{
			bool flag = inputBehavior == InputBroker.InputBehavior.ClickToMove;
			sortGamepadParent.SetActive(!flag);
			playerInventory.sortButton.gameObject.SetActive(flag);
			GetSetupByCharacter(leftSideInventoryChar)?.sortButton.gameObject.SetActive(flag);
		}

		private void InitInventory(InventorySetup inventory, Character owner)
		{
			inventory.grid.InitGrid(owner);
			inventory.ownerNameText.text = owner.CharacterName;
			for (int i = 0; i < inventory.equipmentSlots.Length; i++)
			{
				inventory.equipmentSlots[i].owner = owner;
				if (inventory.equipmentSlots[i].globalIndex == 0)
				{
					inventory.equipmentSlots[i].globalIndex = 6 + i;
				}
				else if (inventory.equipmentSlots[i].globalIndex < 6 || inventory.equipmentSlots[i].globalIndex >= 20)
				{
					UnityEngine.Debug.LogWarning($"{inventory.equipmentSlots[i].name}: Found equipment slot with bad global index: {inventory.equipmentSlots[i].globalIndex}. It's not within [EquipmentStartIndex <-> InventoryStartIndex] range.", inventory.equipmentSlots[i]);
				}
			}
			if (inventory.rightSideStatsButton != null)
			{
				inventory.rightSideStatsButton.onClick.AddListener(ToggleRightSideStats);
			}
			inventory.sortButton.onClick.AddListener(owner.IsPlayer() ? new UnityAction(AutoSortInventoryRightSide) : new UnityAction(AutoSortInventoryLeftSide));
			inventory.UpdateSortDirectionMarker();
		}

		private void InteractAction_performed(InputAction.CallbackContext obj)
		{
			if (heldItem != null)
			{
				heldItem.CancelItemMove();
				heldItem = null;
			}
			else if (activeItem != null && activeItem.currentItem != null && interactAction.WasPressedThisFrame())
			{
				activeItem.OnInteract();
			}
		}

		public EquipmentSlotUI GetEquipUISlotByGlobalIndex(int globalIndex)
		{
			EquipmentSlotUI[] equipmentSlots = playerInventory.equipmentSlots;
			for (int i = 0; i < equipmentSlots.Length; i++)
			{
				if (equipmentSlots[i].globalIndex == globalIndex)
				{
					return equipmentSlots[i];
				}
			}
			return null;
		}

		public (int main, int secondary) GetEquipmentSlots(Item item)
		{
			EquipmentSlotUI[] equipmentSlots = playerInventory.equipmentSlots;
			(int, int) result = (-1, -1);
			for (int i = 0; i < equipmentSlots.Length; i++)
			{
				if (equipmentSlots[i].SupportsItem(item))
				{
					if (result.Item1 != -1)
					{
						result.Item2 = equipmentSlots[i].globalIndex;
					}
					else
					{
						result.Item1 = equipmentSlots[i].globalIndex;
					}
				}
			}
			return result;
		}

