		private InventorySetup GetInventorySetup(Character target)
		{
			if (target.IsPlayer())
			{
				return playerInventory;
			}
			if (Player.PlayerChar.HasPartyMember(target))
			{
				return partyInventory;
			}
			if (target.IsPet())
			{
				return petInventory;
			}
			return null;
		}

		public void ToggleInventoryOwner()
		{
			int num = allInventoryHavers.FindIndex((Character c) => c == leftSideInventoryChar);
			if (num >= allInventoryHavers.Count - 1)
			{
				UpdateInventory(allInventoryHavers[0]);
			}
			else
			{
				UpdateInventory(allInventoryHavers[num + 1]);
			}
		}

		public void UpdateInventory(Character invChar, bool setSelectedCharacter = true, bool playerChangeLeftSide = true)
		{
			if (invChar.IsPet())
			{
				AIState aIState = invChar.GetAIState();
				if (aIState == AIState.InTown || aIState == AIState.ReturningToTown)
				{
					UpdateInventory(Player.PlayerChar);
					return;
				}
			}
			if (invChar.IsPlayer())
			{
				SetRightSideInventory();
				if (playerChangeLeftSide && leftSideState == LeftSideState.Inventory)
				{
					SetLeftSideStats();
				}
			}
			else
			{
				SetLeftSideInventory(invChar);
				leftSideInventoryChar = invChar;
				if (rightStats.gameObject.activeSelf)
				{
					SetRightSideStats(invChar);
				}
			}
			if (setSelectedCharacter)
			{
				for (int i = 0; i < characterButtons.Length; i++)
				{
					PartyCharacterInScreenUI obj = characterButtons[i];
					bool flag = obj.CurrentCharacter == invChar;
					obj.ShowSelectedVisuals(flag);
					if (flag)
					{
						PlayerUI.LatestSelectedMemberIndex = i;
					}
				}
			}
			InventorySetup targetSetup = GetInventorySetup(invChar);
			if (!targetSetup.grid.HasInitialized)
			{
				InitInventory(targetSetup, invChar);
			}
			EquipmentSlotUI[] setSlots;
			if (invChar.IsPlayer() || invChar.IsPartyMember())
			{
				setSlots = targetSetup.weaponSetToggling.setSlots;
				for (int j = 0; j < setSlots.Length; j++)
				{
					setSlots[j].SetWeaponSetSlot(invChar.GetActiveWeaponSet);
				}
				targetSetup.weaponSetToggling.primaryToggle.onValueChanged.RemoveAllListeners();
				targetSetup.weaponSetToggling.primaryToggle.onValueChanged.AddListener(delegate(bool isOn)
				{
					if (isOn)
					{
						invChar.SetActiveWeaponSet(WeaponSet.Primary);
						EquipmentSlotUI[] setSlots3 = targetSetup.weaponSetToggling.setSlots;
						for (int m = 0; m < setSlots3.Length; m++)
						{
							setSlots3[m].SetWeaponSetSlot(WeaponSet.Primary);
						}
						UpdateWeaponSetSlots();
					}
				});
				targetSetup.weaponSetToggling.secondaryToggle.onValueChanged.RemoveAllListeners();
				targetSetup.weaponSetToggling.secondaryToggle.onValueChanged.AddListener(delegate(bool isOn)
				{
					if (isOn)
					{
						invChar.SetActiveWeaponSet(WeaponSet.Secondary);
						EquipmentSlotUI[] setSlots2 = targetSetup.weaponSetToggling.setSlots;
						for (int l = 0; l < setSlots2.Length; l++)
						{
							setSlots2[l].SetWeaponSetSlot(WeaponSet.Secondary);
						}
						UpdateWeaponSetSlots();
					}
				});
			}
			targetSetup.grid.ClearGrid();
			EquipmentSlotUI[] equipmentSlots = targetSetup.equipmentSlots;
			setSlots = equipmentSlots;
			foreach (EquipmentSlotUI equipmentSlotUI in setSlots)
			{
				if (equipmentSlotUI.itemHandle != null)
				{
					equipmentSlotUI.itemHandle.gameObject.SetActive(value: false);
				}
				equipmentSlotUI.TrySetItem(null);
			}
			List<Item> list = invChar.inventory.FindAll((Item item) => item.slotIndex >= 6 && item.slotIndex < 20);
			if (list != null)
			{
				foreach (EquipmentSlotUI slot in equipmentSlots)
				{
					slot.owner = invChar;
					Item item2 = list.Find(delegate(Item item)
					{
						bool flag2 = !slot.IsWeaponSetSlot || item.weaponSet == slot.WeaponSetSlot;
						return item.slotIndex == slot.globalIndex && flag2;
					});
					if (item2 != null)
					{
						ItemUI @object = itemPool.GetObject();
						@object.Init();
						@object.SetOwner(invChar);
						@object.SetItem(item2, targetSetup.grid.inventoryGrid.cellSize);
						@object.SetParent(slot.transform);
						@object.SetSlots(slot);
						@object.gameObject.SetActive(value: true);
						if (!slot.TrySetItem(@object))
						{
							UnityEngine.Debug.LogError("Failed setting up equipment!");
						}
					}
				}
			}
			targetSetup.grid.SetOwner(invChar);
			targetSetup.grid.FillGrid(invChar.inventory, dropItemsThatDontFit: true);
			targetSetup.ownerNameText.text = invChar.CharacterName;
			statsParent.SetCharacter(invChar);
			UtilityTG.UnityDelay(delegate
			{
				if (invChar.IsPlayer() || invChar.IsPartyMember())
				{
					if (invChar.GetActiveWeaponSet == WeaponSet.Primary)
					{
						targetSetup.weaponSetToggling.primaryToggle.isOn = true;
					}
					else if (invChar.GetActiveWeaponSet == WeaponSet.Secondary)
					{
						targetSetup.weaponSetToggling.secondaryToggle.isOn = true;
					}
				}
			});
			bool active = SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove;
			targetSetup.sortButton.gameObject.SetActive(active);
			targetSetup.UpdateSortDirectionMarker();
			if (invChar.IsPet() && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.PetInventory, out var key))
			{
				SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
			}
		}

		private void ToggleWeaponSetInputPerformed()
		{
			if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior != 0)
			{
				if (heldItem != null)
				{
					heldItem.CancelItemMove();
					heldItem = null;
				}
				if (draggedItemUI != null)
				{
					draggedItemUI.CancelItemMove();
					draggedItemUI = null;
				}
				Player playerChar = Player.PlayerChar;
				playerChar.ToggleActiveWeaponSet();
				InventorySetup setupByCharacter = GetSetupByCharacter(playerChar);
				EquipmentSlotUI[] setSlots = setupByCharacter.weaponSetToggling.setSlots;
				for (int i = 0; i < setSlots.Length; i++)
				{
					setSlots[i].SetWeaponSetSlot(playerChar.GetActiveWeaponSet);
				}
				if (playerChar.GetActiveWeaponSet == WeaponSet.Primary)
				{
					setupByCharacter.weaponSetToggling.primaryToggle.isOn = true;
				}
				else if (playerChar.GetActiveWeaponSet == WeaponSet.Secondary)
				{
					setupByCharacter.weaponSetToggling.secondaryToggle.isOn = true;
				}
			}
		}

		public void UpdateWeaponSetSlots()
		{
			UpdateWeaponSetSlotsForCharacter(Player.PlayerChar);
			UpdateWeaponSetSlotsForCharacter(leftSideInventoryChar);
		}

		private void UpdateWeaponSetSlotsForCharacter(Character character)
		{
			if (character == null)
			{
				return;
			}
			InventorySetup inventorySetup = GetInventorySetup(character);
			_ = inventorySetup.equipmentSlots;
			List<Item> list = character.inventory.FindAll((Item item) => item.slotIndex >= 6 && item.slotIndex < 20);
			if (list == null)
			{
				return;
			}
			EquipmentSlotUI[] setSlots = inventorySetup.weaponSetToggling.setSlots;
			foreach (EquipmentSlotUI slot in setSlots)
			{
				if (slot.itemHandle != null)
				{
					slot.itemHandle.gameObject.SetActive(value: false);
					slot.ForceClear();
				}
				Item item2 = list.Find((Item item) => item.slotIndex == slot.globalIndex && item.weaponSet == slot.WeaponSetSlot);
				if (item2 != null)
				{
					ItemUI @object = itemPool.GetObject();
					@object.Init();
					@object.SetOwner(character);
					@object.SetItem(item2, inventorySetup.grid.inventoryGrid.cellSize);
					@object.SetParent(slot.transform);
					@object.SetSlots(slot);
					@object.gameObject.SetActive(value: true);
					if (!slot.TrySetItem(@object))
					{
						UnityEngine.Debug.LogError("Failed setting up equipment!");
					}
				}
			}
		}

		private void OnEnable()
		{
			UpdateCharacterButtons();
			InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
			instance.OnInventorySortPerformed = (Action)Delegate.Combine(instance.OnInventorySortPerformed, new Action(AutoSortInventoryGamepad));
			InputBroker instance2 = SingletonBehaviour<InputBroker>.Instance;
			instance2.OnMenuCycleWeaponPerformed = (Action)Delegate.Combine(instance2.OnMenuCycleWeaponPerformed, new Action(ToggleWeaponSetInputPerformed));
			Player playerChar = Player.PlayerChar;
			playerChar.onPartyChanged = (Action)Delegate.Combine(playerChar.onPartyChanged, new Action(UpdateCharacterButtons));
		}

		private void UpdateCharacterButtons()
		{
			allInventoryHavers = new List<Character>
			{
				Player.PlayerChar,
				Player.PlayerChar.GetPet()
			};
			if (Fate.CurrentFateVer == Fate.FateVer.CursedKing)
			{
				for (int i = 0; i < Player.PlayerChar.GetPartyMemberCount(); i++)
				{
					allInventoryHavers.Add(Player.PlayerChar.GetPartyMember(i));
				}
			}
			for (int j = 0; j < characterButtons.Length; j++)
			{
				Character character = ((allInventoryHavers.Count > j) ? allInventoryHavers[j] : null);
				PartyCharacterInScreenUI obj = characterButtons[j];
				obj.SetChar(character);
				obj.GetComponentInChildren<ItemSlotPartyRelayUI>().relayTarget = character;
			}
			Character latestSelectedCharacterInParty = PlayerUI.GetLatestSelectedCharacterInParty();
			if (latestSelectedCharacterInParty.IsPlayer())
			{
				UpdateInventory(latestSelectedCharacterInParty);
				return;
			}
			UpdateInventory(Player.PlayerChar);
			UpdateInventory(latestSelectedCharacterInParty);
		}

		private void OnDisable()
		{
			if (SimpleSingletonBehaviour<PlayerUI>.Instance.IsItemTargetingItem)
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetItemTargetingItem(null);
			}
			if (SimpleSingletonBehaviour<PlayerUI>.Instance.IsSpellTargetingItem)
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetSpellTargetingItem(isTargeting: false);
			}
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
				instance.OnInventorySortPerformed = (Action)Delegate.Remove(instance.OnInventorySortPerformed, new Action(AutoSortInventoryGamepad));
				InputBroker instance2 = SingletonBehaviour<InputBroker>.Instance;
				instance2.OnMenuCycleWeaponPerformed = (Action)Delegate.Remove(instance2.OnMenuCycleWeaponPerformed, new Action(ToggleWeaponSetInputPerformed));
			}
			if (Player.PlayerChar != null)
			{
				Player playerChar = Player.PlayerChar;
				playerChar.onPartyChanged = (Action)Delegate.Remove(playerChar.onPartyChanged, new Action(UpdateCharacterButtons));
			}
			if (heldItem != null)
			{
				if (heldItem.currentItem.InInventoryGrid)
				{
					heldItem.Owner.ReserveInventorySlotsForItem(heldItem.currentItem);
				}
				heldItem.gameObject.SetActive(value: false);
				heldItem = null;
			}
			if (draggedItemUI != null)
			{
				if (draggedItemUI.currentItem.InInventoryGrid)
				{
					draggedItemUI.Owner.ReserveInventorySlotsForItem(draggedItemUI.currentItem);
				}
				draggedItemUI.gameObject.SetActive(value: false);
				draggedItemUI = null;
			}
			SetLeftSideStats();
		}

		public bool OnMenuButtonRelay()
		{
			if (SimpleSingletonBehaviour<PlayerUI>.Instance.IsAnythingTargetingItem)
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetItemTargetingItem(null);
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetSpellTargetingItem(isTargeting: false);
				return true;
			}
			if (heldItem != null)
			{
				heldItem.CancelItemMove();
				heldItem = null;
				return true;
			}
			return false;
		}

