		public InventorySetup GetSetupByCharacter(Character character)
		{
			if (character == null)
			{
				return null;
			}
			if (character.IsPlayer())
			{
				return playerInventory;
			}
			if (character.IsPet())
			{
				return petInventory;
			}
			if (character.IsPartyMember())
			{
				return partyInventory;
			}
			return null;
		}

		public bool TryInteractEquipItemUI(ItemUI itemUI)
		{
			if (Time.frameCount == lastSuccessfulInteractEquipFrame)
			{
				return false;
			}
			InventorySetup setupByCharacter = GetSetupByCharacter(itemUI.Owner);
			if (setupByCharacter == null)
			{
				return false;
			}
			InventoryGrid grid = setupByCharacter.grid;
			if (!grid.gameObject.activeInHierarchy)
			{
				return false;
			}
			if (itemUI.currentItem.slotIndex < 20 || !itemUI.Owner.RequirementsMet(itemUI.currentItem))
			{
				return false;
			}
			bool flag = false;
			bool flag2 = itemUI.currentItem.category == ItemCategory.Weapon || itemUI.currentItem.itemType == ItemType.Shield;
			bool isTwoHanded = itemUI.currentItem.itemData.IsTwoHanded;
			EquipmentSlotUI equipmentSlotUI = null;
			EquipmentSlotUI[] equipmentSlots = setupByCharacter.equipmentSlots;
			foreach (EquipmentSlotUI equipmentSlotUI2 in equipmentSlots)
			{
				if (equipmentSlotUI2.owner != itemUI.Owner || equipmentSlotUI2 == equipmentSlotUI || (equipmentSlotUI2.IsWeaponSetSlot && equipmentSlotUI2.owner.GetActiveWeaponSet != equipmentSlotUI2.WeaponSetSlot))
				{
					continue;
				}
				if (flag2)
				{
					EquipmentSlotUI equipmentSlotUI3 = equipmentSlotUI2;
					equipmentSlotUI = equipmentSlotUI2.pairedSlot;
					if (equipmentSlotUI == null)
					{
						continue;
					}
					bool flag3 = equipmentSlotUI3.SupportsItemType(itemUI.currentItem.itemType);
					bool flag4 = equipmentSlotUI.SupportsItemType(itemUI.currentItem.itemType);
					if (!flag3 && !flag4)
					{
						continue;
					}
					List<EquipmentSlotUI> list = new List<EquipmentSlotUI>();
					List<ItemUI> list2 = new List<ItemUI>();
					ItemUI itemUI2 = ((!equipmentSlotUI3.IsOpen) ? equipmentSlotUI3.GetCurrentItemUI : null);
					ItemUI itemUI3 = ((!equipmentSlotUI.IsOpen) ? equipmentSlotUI.GetCurrentItemUI : null);
					if (itemUI2 != null)
					{
						list.Add(equipmentSlotUI3);
					}
					if (itemUI3 != null)
					{
						list.Add(equipmentSlotUI);
					}
					EquipmentSlotUI equipmentSlotUI4 = null;
					bool flag5 = (itemUI2 != null && itemUI2.currentItem.itemData.IsTwoHanded) || (itemUI3 != null && itemUI3.currentItem.itemData.IsTwoHanded);
					if (isTwoHanded)
					{
						foreach (EquipmentSlotUI item in list)
						{
							PreReturnEquippedItemToInventory(item, out var itemUI4);
							list2.Add(itemUI4);
						}
						equipmentSlotUI4 = (flag3 ? equipmentSlotUI3 : equipmentSlotUI);
					}
					else if (flag5)
					{
						ItemUI itemUI5 = null;
						if (itemUI2 != null)
						{
							PreReturnEquippedItemToInventory(equipmentSlotUI3, out itemUI5);
						}
						else
						{
							PreReturnEquippedItemToInventory(equipmentSlotUI, out itemUI5);
						}
						list2.Add(itemUI5);
						equipmentSlotUI4 = (flag3 ? equipmentSlotUI3 : equipmentSlotUI);
					}
					else
					{
						if (flag3 && flag4)
						{
							equipmentSlotUI4 = equipmentSlotUI3;
							if (itemUI2 != null && itemUI3 == null)
							{
								equipmentSlotUI4 = equipmentSlotUI;
							}
						}
						else
						{
							equipmentSlotUI4 = (flag3 ? equipmentSlotUI3 : equipmentSlotUI);
						}
						if (!equipmentSlotUI4.IsOpen && equipmentSlotUI4.GetCurrentItemUI != null)
						{
							PreReturnEquippedItemToInventory(equipmentSlotUI4, out var itemUI6);
							list2.Add(itemUI6);
						}
					}
					PlaceInventoryItemInEquipmentSlot(equipmentSlotUI4, itemUI, out var desiredSlotIndex2);
					foreach (ItemUI item2 in list2)
					{
						PostReturnEquippedItemToInventory(item2, desiredSlotIndex2);
						desiredSlotIndex2 = -1;
					}
					flag = true;
					break;
				}
				if (equipmentSlotUI2.SupportsItemType(itemUI.currentItem.itemType))
				{
					bool num = !equipmentSlotUI2.IsOpen && equipmentSlotUI2.GetCurrentItemUI != null;
					bool flag6 = equipmentSlotUI2.pairedSlot == null || (!equipmentSlotUI2.pairedSlot.IsOpen && equipmentSlotUI2.pairedSlot.GetCurrentItemUI != null);
					EquipmentSlotUI equipmentSlotUI5 = ((num && !flag6) ? equipmentSlotUI2.pairedSlot : equipmentSlotUI2);
					ItemUI itemUI7 = null;
					if (!equipmentSlotUI5.IsOpen && equipmentSlotUI5.GetCurrentItemUI != null)
					{
						PreReturnEquippedItemToInventory(equipmentSlotUI5, out itemUI7);
					}
					PlaceInventoryItemInEquipmentSlot(equipmentSlotUI5, itemUI, out var desiredSlotIndex3);
					if (itemUI7 != null)
					{
						PostReturnEquippedItemToInventory(itemUI7, desiredSlotIndex3);
					}
					flag = true;
					break;
				}
			}
			if (flag && activeItem == itemUI)
			{
				activeItem = null;
			}
			lastSuccessfulInteractEquipFrame = Time.frameCount;
			return flag;
			static void PlaceInventoryItemInEquipmentSlot(EquipmentSlotUI slot, ItemUI itemUI, out int desiredSlotIndex)
			{
				desiredSlotIndex = itemUI.currentItem.slotIndex - 20;
				itemUI.Owner.ReleaseInventorySlotsForItem(itemUI.currentItem);
				itemUI.UndockCurrentSlots();
				itemUI.SetSlots(slot);
				itemUI.AttemptItemDrop(slot.transform);
			}
			void PostReturnEquippedItemToInventory(ItemUI itemUI, int desiredSlot = -1)
			{
				if (itemUI.Owner.CanFitItemInInventoryGrid(itemUI.currentItem, out var foundSlotIndex, desiredSlot))
				{
					itemUI.currentItem.slotIndex = 20 + foundSlotIndex;
					itemUI.Owner.ReserveInventorySlotsForItem(itemUI.currentItem);
					if (!grid.AddItemHandleToGrid(itemUI))
					{
						UnityEngine.Debug.LogWarning("Failed to add item handle to grid, item " + itemUI.currentItem.itemName);
					}
				}
				else
				{
					itemUI.Owner.RemoveItemFromInventory(itemUI.currentItem, RemoveItemReason.Drop);
					itemUI.currentItem.Drop(Player.PlayerChar.myTransform.position);
					itemUI.ForceClearCurrentSlots();
					itemUI.gameObject.SetActive(value: false);
				}
			}
			static void PreReturnEquippedItemToInventory(EquipmentSlotUI slot, out ItemUI itemUI)
			{
				itemUI = slot.GetCurrentItemUI;
				itemUI.Owner.UnequipItem(itemUI.currentItem);
				itemUI.ForceClearCurrentSlots();
				slot.ForceClear();
			}
		}

		public bool TryDropItemUIOnEquipmentSlot(ItemUI itemUI, EquipmentSlotUI equipSlot)
		{
			if (Time.frameCount == lastSuccessfulInteractEquipFrame)
			{
				return false;
			}
			Character itemOwner = itemUI.Owner;
			InventorySetup setupByCharacter = GetSetupByCharacter(itemOwner);
			if (setupByCharacter == null)
			{
				return false;
			}
			InventoryGrid itemOwnerGrid = setupByCharacter.grid;
			if (!itemOwnerGrid.gameObject.activeInHierarchy)
			{
				return false;
			}
			Character slotOwner = equipSlot.Owner;
			if (!slotOwner.RequirementsMet(itemUI.currentItem))
			{
				return false;
			}
			bool flag = false;
			bool num = itemUI.currentItem.category == ItemCategory.Weapon || itemUI.currentItem.itemType == ItemType.Shield;
			bool isTwoHanded = itemUI.currentItem.itemData.IsTwoHanded;
			bool sameOwner = setupByCharacter.equipmentSlots.Contains(equipSlot);
			if (!sameOwner)
			{
				GetSetupByCharacter(slotOwner);
			}
			bool flag2 = itemUI.currentItem.slotIndex >= 6 && itemUI.currentItem.slotIndex < 20;
			if (num)
			{
				EquipmentSlotUI pairedSlot = equipSlot.pairedSlot;
				if (pairedSlot == null)
				{
					return false;
				}
				bool flag3 = equipSlot.OriginalSupportsItem(itemUI.currentItem);
				bool flag4 = pairedSlot.OriginalSupportsItem(itemUI.currentItem);
				if (equipSlot.RequiresHeroItem && !equipSlot.IsOpen && equipSlot.GetCurrentItemUI != null && equipSlot.GetCurrentItemUI.currentItem.IsHeroItem())
				{
					flag3 = false;
				}
				if (pairedSlot.RequiresHeroItem && !pairedSlot.IsOpen && pairedSlot.GetCurrentItemUI != null && pairedSlot.GetCurrentItemUI.currentItem.IsHeroItem())
				{
					flag4 = false;
				}
				if (!flag3 && !flag4)
				{
					return false;
				}
				List<EquipmentSlotUI> list = new List<EquipmentSlotUI>();
				List<ItemUI> list2 = new List<ItemUI>();
				ItemUI itemUI2 = ((!equipSlot.IsOpen) ? equipSlot.GetCurrentItemUI : null);
				ItemUI itemUI3 = ((!pairedSlot.IsOpen) ? pairedSlot.GetCurrentItemUI : null);
				if (itemUI2 != null)
				{
					list.Add(equipSlot);
				}
				if (itemUI3 != null)
				{
					list.Add(pairedSlot);
				}
				if (itemUI2 == itemUI)
				{
					return false;
				}
				EquipmentSlotUI equipmentSlotUI = null;
				bool flag5 = (itemUI2 != null && itemUI2.currentItem.itemData.IsTwoHanded) || (itemUI3 != null && itemUI3.currentItem.itemData.IsTwoHanded);
				if (isTwoHanded)
				{
					foreach (EquipmentSlotUI item in list)
					{
						RemoveEquippedItemFromSlot(item, out var itemUI4);
						list2.Add(itemUI4);
					}
					equipmentSlotUI = (flag3 ? equipSlot : pairedSlot);
				}
				else if (flag5)
				{
					ItemUI itemUI5 = null;
					if (itemUI2 != null)
					{
						RemoveEquippedItemFromSlot(equipSlot, out itemUI5);
					}
					else
					{
						RemoveEquippedItemFromSlot(pairedSlot, out itemUI5);
					}
					list2.Add(itemUI5);
					equipmentSlotUI = (flag3 ? equipSlot : pairedSlot);
				}
				else
				{
					equipmentSlotUI = ((!(flag3 && flag4)) ? (flag3 ? equipSlot : pairedSlot) : equipSlot);
					if (flag2)
					{
						if (!flag3)
						{
							return false;
						}
						if (itemUI2 != null && !pairedSlot.SupportsItemType(itemUI2.currentItem.itemType))
						{
							return false;
						}
						if (itemUI2 != null)
						{
							RemoveEquippedItemFromSlot(equipSlot, out var _);
						}
						EquipItemInSlot(itemUI, equipSlot);
						if (itemUI2 != null)
						{
							EquipItemInSlot(itemUI2, pairedSlot);
						}
						return true;
					}
					if (!equipmentSlotUI.IsOpen && equipmentSlotUI.GetCurrentItemUI != null)
					{
						RemoveEquippedItemFromSlot(equipmentSlotUI, out var itemUI7);
						list2.Add(itemUI7);
					}
				}
				PlaceInventoryItemInEquipmentSlot(equipmentSlotUI, itemUI, out var desiredSlotIndex2);
				foreach (ItemUI item2 in list2)
				{
					PostReturnEquippedItemToInventory(item2, desiredSlotIndex2);
					desiredSlotIndex2 = -1;
				}
				flag = true;
			}
			else if (equipSlot.OriginalSupportsItem(itemUI.currentItem))
			{
				bool flag6 = !equipSlot.IsOpen && equipSlot.GetCurrentItemUI != null;
				bool flag7 = equipSlot.pairedSlot == null || (!equipSlot.pairedSlot.IsOpen && equipSlot.pairedSlot.GetCurrentItemUI != null);
				EquipmentSlotUI equipmentSlotUI2 = equipSlot;
				if (equipmentSlotUI2.RequiresHeroItem && flag6 && equipSlot.GetCurrentItemUI.currentItem.IsHeroItem())
				{
					return false;
				}
				ItemUI itemUI8 = null;
				if (flag2)
				{
					if (!equipmentSlotUI2.IsOpen && equipmentSlotUI2.GetCurrentItemUI != null)
					{
						RemoveEquippedItemFromSlot(equipmentSlotUI2, out itemUI8);
					}
					EquipItemInSlot(itemUI, equipmentSlotUI2);
					if (itemUI8 != null)
					{
						if (equipmentSlotUI2.pairedSlot != null)
						{
							EquipItemInSlot(itemUI8, equipmentSlotUI2.pairedSlot);
						}
						else
						{
							PostReturnEquippedItemToInventory(itemUI8);
						}
					}
					return true;
				}
				equipmentSlotUI2 = ((flag6 && !flag7) ? equipSlot.pairedSlot : equipSlot);
				if (!equipmentSlotUI2.IsOpen && equipmentSlotUI2.GetCurrentItemUI != null)
				{
					RemoveEquippedItemFromSlot(equipmentSlotUI2, out itemUI8);
				}
				PlaceInventoryItemInEquipmentSlot(equipmentSlotUI2, itemUI, out var desiredSlotIndex3);
				if (itemUI8 != null)
				{
					PostReturnEquippedItemToInventory(itemUI8, desiredSlotIndex3);
				}
				flag = true;
			}
			if (flag && activeItem == itemUI)
			{
				activeItem = null;
			}
			return flag;
			static void EquipItemInSlot(ItemUI itemUI, EquipmentSlotUI slot)
			{
				itemUI.SetSlots(slot);
				itemUI.AttemptItemDrop(slot.transform);
			}
			static void PlaceInventoryItemInEquipmentSlot(EquipmentSlotUI slot, ItemUI itemUI, out int desiredSlotIndex)
			{
				if (itemUI.currentItem.slotIndex >= 20)
				{
					desiredSlotIndex = itemUI.currentItem.slotIndex - 20;
				}
				else
				{
					desiredSlotIndex = -1;
				}
				itemUI.Owner.ReleaseInventorySlotsForItem(itemUI.currentItem);
				itemUI.UndockCurrentSlots();
				itemUI.SetSlots(slot);
				itemUI.AttemptItemDrop(slot.transform);
			}
			void PostReturnEquippedItemToInventory(ItemUI itemUI, int desiredSlot = -1)
			{
				int foundSlotIndex;
				if (!sameOwner)
				{
					slotOwner.RemoveItemFromInventory(itemUI.currentItem, RemoveItemReason.Transfer);
					if (itemOwner.AddItemToInventory(itemUI.currentItem, AddItemReason.Transfer))
					{
						if (!itemOwnerGrid.AddItemHandleToGrid(itemUI))
						{
							UnityEngine.Debug.LogWarning("Failed to add item handle to grid, item " + itemUI.currentItem.itemName);
						}
					}
					else
					{
						itemUI.currentItem.Drop(slotOwner.myTransform.position);
					}
				}
				else if (itemUI.Owner.CanFitItemInInventoryGrid(itemUI.currentItem, out foundSlotIndex, desiredSlot))
				{
					itemUI.currentItem.slotIndex = 20 + foundSlotIndex;
					itemUI.Owner.ReserveInventorySlotsForItem(itemUI.currentItem);
					if (!itemOwnerGrid.AddItemHandleToGrid(itemUI))
					{
						UnityEngine.Debug.LogWarning("Failed to add item handle to grid, item " + itemUI.currentItem.itemName);
					}
				}
				else
				{
					itemUI.Owner.RemoveItemFromInventory(itemUI.currentItem, RemoveItemReason.Drop);
					itemUI.currentItem.Drop(Player.PlayerChar.myTransform.position);
					itemUI.ForceClearCurrentSlots();
					itemUI.gameObject.SetActive(value: false);
				}
			}
			static void RemoveEquippedItemFromSlot(EquipmentSlotUI slot, out ItemUI itemUI)
			{
				itemUI = slot.GetCurrentItemUI;
				itemUI.Owner.UnequipItem(itemUI.currentItem);
				itemUI.ForceClearCurrentSlots();
				slot.ForceClear();
			}
		}

		private void AutoSortInventoryGamepad()
		{
			if (leftSideInventoryChar != null)
			{
				GetSetupByCharacter(leftSideInventoryChar).sortHorizontally = playerInventory.sortHorizontally;
				AutoSortInventoryForCharacter(leftSideInventoryChar, playAudio: false);
			}
			else if (ShopOpen && shopUI.gameObject.activeInHierarchy && shopUI.GetStashIsOpen)
			{
				AutoSortInventoryForStash(toggleSortDirection: false, playAudio: false);
			}
			InventorySetup inventorySetup = GetInventorySetup(Player.PlayerChar);
			if (inventorySetup != null && inventorySetup.grid != null && inventorySetup.grid.gameObject.activeInHierarchy)
			{
				AutoSortInventoryForCharacter(Player.PlayerChar);
			}
		}

		private void AutoSortInventoryRightSide()
		{
			AutoSortInventoryForCharacter(Player.PlayerChar);
		}

		private void AutoSortInventoryLeftSide()
		{
			AutoSortInventoryForCharacter(leftSideInventoryChar);
		}

		private void AutoSortInventoryForCharacter(Character character, bool playAudio = true)
		{
			if (character == null)
			{
				return;
			}
			InventorySetup setupByCharacter = GetSetupByCharacter(character);
			if (setupByCharacter == null)
			{
				return;
			}
			InventoryGrid grid = setupByCharacter.grid;
			if (heldItem != null)
			{
				heldItem.CancelItemMove();
				heldItem = null;
			}
			if (draggedItemUI != null)
			{
				draggedItemUI.CancelItemMove();
				draggedItemUI = null;
			}
			if (activeItem != null)
			{
				activeItem = null;
			}
			grid.ClearGrid();
			Character owner = grid.Owner;
			owner.inventory.Sort();
			List<Item> list = owner.inventory.FindAll((Item item) => item.InInventoryGrid);
			list.Sort(delegate(Item a, Item b)
			{
				int num = a.slotsTall + a.slotsWide;
				int num2 = b.slotsTall + b.slotsWide;
				if (num < num2)
				{
					return 1;
				}
				return (num != num2) ? (-1) : 0;
			});
			foreach (Item item in list)
			{
				owner.ReleaseInventorySlotsForItem(item);
			}
			foreach (Item item2 in list)
			{
				if (owner.CanFitItemInInventoryGrid(item2, out var foundSlotIndex, -1, isGlobalIndex: false, setupByCharacter.sortHorizontally))
				{
					item2.slotIndex = foundSlotIndex + 20;
					owner.ReserveInventorySlotsForItem(item2);
					grid.AddItem(item2);
				}
				else
				{
					owner.RemoveItemFromInventory(item2, RemoveItemReason.Drop);
					item2.Drop(character.myTransform.position);
				}
			}
			setupByCharacter.sortHorizontally = !setupByCharacter.sortHorizontally;
			setupByCharacter.UpdateSortDirectionMarker();
			if (playAudio)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			}
		}

		public void AutoSortInventoryForStash(bool toggleSortDirection = false, bool playAudio = true)
		{
			Stash getStash = shopUI.GetStash;
			if (getStash == null)
			{
				UnityEngine.Debug.LogWarning("Tried to sort stash but shopUI.GetStash is null");
				return;
			}
			InventorySetup inventorySetup = GetInventorySetup(Player.PlayerChar);
			if (inventorySetup == null)
			{
				UnityEngine.Debug.LogError("Could not retrieve player inventory setup when auto sorting stash, it's needed for knowing if to sort horizontally or vertically");
				return;
			}
			if (heldItem != null)
			{
				heldItem.CancelItemMove();
				heldItem = null;
			}
			if (draggedItemUI != null)
			{
				draggedItemUI.CancelItemMove();
				draggedItemUI = null;
			}
			if (activeItem != null)
			{
				activeItem = null;
			}
			InventoryGrid getGrid = shopUI.GetGrid;
			getGrid.ClearGrid();
			getStash.SortItemList();
			List<Item> items = getStash.GetItems();
			items.Sort(delegate(Item a, Item b)
			{
				int num = a.slotsTall + a.slotsWide;
				int num2 = b.slotsTall + b.slotsWide;
				if (num < num2)
				{
					return 1;
				}
				return (num != num2) ? (-1) : 0;
			});
			foreach (Item item in items)
			{
				getStash.ReleaseInventorySlotsForItem(item);
			}
			foreach (Item item2 in items)
			{
				if (getStash.CanFitItem(item2, out var foundSlotIndex, -1, inventorySetup.sortHorizontally))
				{
					item2.slotIndex = foundSlotIndex + 20;
					getStash.ReserveInventorySlotsForItem(item2);
					getGrid.AddItem(item2);
				}
				else
				{
					getStash.OnItemMovedFromStash(item2);
					item2.Drop(getStash.transform.position);
				}
			}
			if (toggleSortDirection)
			{
				inventorySetup.sortHorizontally = !inventorySetup.sortHorizontally;
				inventorySetup.UpdateSortDirectionMarker();
			}
			if (playAudio)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			}
		}

		public void OnGoldChanged(ulong newAmount)
		{
			if (ShopOpen)
			{
				shopUI.GetGrid.RunActionOnAllItemUIs(delegate(ItemUI itemUI)
				{
					itemUI.UpdateAvailableMarker();
				});
			}
		}
	}
