	public class ItemSlotPartyRelayUI : ItemSlotUI
	{
		public Character relayTarget;

		public override SlotType GetSlotType()
		{
			return SlotType.RelaySlot;
		}

		public override void SetHover(bool hovered)
		{
		}

		public override bool TrySetItem(ItemUI item)
		{
			if (relayTarget == item.Owner)
			{
				return false;
			}
			if (relayTarget.IsPet())
			{
				AIState aIState = relayTarget.GetAIState();
				if (aIState == AIState.InTown || aIState == AIState.ReturningToTown)
				{
					return false;
				}
			}
			if (relayTarget.AddItemToInventory(item.currentItem, AddItemReason.Transfer))
			{
				UnityEngine.Debug.Log("Relay added to inventory of: " + relayTarget.CharacterName);
				return true;
			}
			return false;
		}

		public override bool SupportsItem(Item item)
		{
			return true;
		}
	}
	public class ItemSlotUI : MonoBehaviour
	{
		public enum SlotType
		{
			GridSlot,
			EquipSlot,
			HotbarSlot,
			RelaySlot,
			DropSlot
		}

		[SerializeField]
		protected ItemType[] itemRestriction;

		protected bool requiresHeroItem;

		protected HeroType allowedHeroType;

		public Image itemBg;

		public ItemUI itemHandle;

		public InventoryGrid parentGrid;

		public int gridBasedIndex;

		public int globalIndex;

		public Action<ItemUI> onItemSet;

		public virtual Character Owner
		{
			get
			{
				if (!(parentGrid != null))
				{
					return null;
				}
				return parentGrid.Owner;
			}
		}

		public virtual bool IsOpen => itemHandle == null;

		public virtual bool IsStashSlot
		{
			get
			{
				if (parentGrid != null)
				{
					return parentGrid.IsStash;
				}
				return false;
			}
		}

		public bool RequiresHeroItem => requiresHeroItem;

		public virtual SlotType GetSlotType()
		{
			return SlotType.GridSlot;
		}

		private void Awake()
		{
			if (itemBg != null)
			{
				itemBg.color = Color.clear;
			}
			_ = requiresHeroItem;
		}

		private void OnDisable()
		{
			itemHandle = null;
		}

		public virtual bool SupportsItem(Item item)
		{
			if (requiresHeroItem && item.heroType != allowedHeroType)
			{
				return false;
			}
			return SupportsItemType(item.itemType);
		}

		public bool SupportsItemType(ItemType itemType)
		{
			ItemType[] array = itemRestriction;
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i] == itemType)
				{
					return true;
				}
			}
			return false;
		}

		public virtual void ForceClear()
		{
			itemHandle = null;
		}

		public virtual bool TrySetItem(ItemUI item)
		{
			itemHandle = item;
			if (item != null)
			{
				RectTransform rectTransform = item.RectTransform;
				rectTransform.anchorMin = new Vector2(0f, 1f);
				rectTransform.anchorMax = new Vector2(0f, 1f);
				rectTransform.pivot = new Vector2(0f, 1f);
				rectTransform.anchoredPosition = Vector2.zero;
				BoxCollider2D boxCol = item.BoxCol;
				boxCol.size = rectTransform.sizeDelta * 0.85f;
				boxCol.offset = new Vector2(rectTransform.sizeDelta.x * 0.5f, rectTransform.sizeDelta.y * -0.5f);
			}
			onItemSet?.Invoke(item);
			SetHover(!IsOpen);
			return true;
		}

		public virtual void SetHover(bool hovered)
		{
		}

		public void SetToHeroType(HeroType heroType)
		{
			requiresHeroItem = true;
			allowedHeroType = heroType;
		}
	}
