		public void Init()
		{
			if (hasInitialized)
			{
				return;
			}
			parentCanvas = GetComponentInParent<Canvas>(includeInactive: false);
			rectTransform = GetComponent<RectTransform>();
			boxCol = GetComponent<BoxCollider2D>();
			itemSize = new Vector2Int(1, 1);
			activeSlots = new List<ItemSlotUI>();
			currentCollidingSlots = new List<ItemSlotUI>();
			previousSlots = new List<ItemSlotUI>();
			socketSlots = new List<ItemSocketUI>();
			selectIndicator.SetActive(value: false);
			SetSocketsVisualState(SocketsVisualState.PartiallyHidden);
			notAvailableIndicator.SetActive(value: false);
			rarityIndicator.gameObject.SetActive(value: false);
			hasInitialized = true;
			ItemSocketUI[] componentsInChildren = GetComponentsInChildren<ItemSocketUI>(includeInactive: true);
			if (componentsInChildren != null)
			{
				ItemSocketUI[] array = componentsInChildren;
				foreach (ItemSocketUI item in array)
				{
					socketSlots.Add(item);
					List<ItemSocketUI> list = socketSlots;
					list[list.Count - 1].gameObject.SetActive(value: false);
				}
			}
		}

		protected override void OnDisable()
		{
			UndockCurrentSlots();
			InventoryUI.itemPool?.ReturnInUseObject(this);
			if (socketSlots != null)
			{
				for (int i = 0; i < socketSlots.Count; i++)
				{
					socketSlots[i].gameObject.SetActive(value: false);
				}
			}
			if (currentItem != null)
			{
				Item item = currentItem;
				item.onIdentifyStatusChanged = (Action<Item>)Delegate.Remove(item.onIdentifyStatusChanged, new Action<Item>(UpdateIdentificationStatus));
				Item item2 = currentItem;
				item2.onLockedForSellingChanged = (Action<Item>)Delegate.Remove(item2.onLockedForSellingChanged, new Action<Item>(UpdateLockedForSelling));
				Item item3 = currentItem;
				item3.onEffectsChanged = (Action<Item>)Delegate.Remove(item3.onEffectsChanged, new Action<Item>(OnItemChanged));
				Item item4 = currentItem;
				item4.onNameChanged = (Action<Item>)Delegate.Remove(item4.onNameChanged, new Action<Item>(OnItemChanged));
				currentItem = null;
			}
			selectIndicator?.SetActive(value: false);
			SetSocketsVisualState(SocketsVisualState.PartiallyHidden);
			if (InventoryUI.activeItem == this)
			{
				InventoryUI.activeItem = null;
			}
			base.OnDisable();
		}

		protected override void OnEnable()
		{
			if (currentItem != null)
			{
				UpdateLockedForSelling(currentItem);
				UpdateIdentificationStatus(currentItem);
				Item item = currentItem;
				item.onIdentifyStatusChanged = (Action<Item>)Delegate.Combine(item.onIdentifyStatusChanged, new Action<Item>(UpdateIdentificationStatus));
				Item item2 = currentItem;
				item2.onLockedForSellingChanged = (Action<Item>)Delegate.Combine(item2.onLockedForSellingChanged, new Action<Item>(UpdateLockedForSelling));
				Item item3 = currentItem;
				item3.onEffectsChanged = (Action<Item>)Delegate.Combine(item3.onEffectsChanged, new Action<Item>(OnItemChanged));
				Item item4 = currentItem;
				item4.onNameChanged = (Action<Item>)Delegate.Combine(item4.onNameChanged, new Action<Item>(OnItemChanged));
			}
			base.OnEnable();
		}

		public void UpdateSockets()
		{
			if (currentItem != null && socketSlots != null)
			{
				for (int i = 0; i < socketSlots.Count; i++)
				{
					ItemSocketUI itemSocketUI = socketSlots[i];
					bool flag = currentItem.sockets > i;
					itemSocketUI.gameObject.SetActive(flag);
					Item toGem = ((flag && currentItem.sockedtedItems != null && i < currentItem.sockedtedItems.Count) ? currentItem.sockedtedItems[i] : null);
					itemSocketUI.SetToGem(toGem);
				}
				if (currentItem.equipped && currentItem.category == ItemCategory.Weapon && currentOwner != null && currentItem.weaponSet == currentOwner.GetActiveWeaponSet)
				{
					currentOwner.ResetEquipment(currentItem);
				}
			}
		}

		public void SetOwner(Character owner)
		{
			currentOwner = owner;
			UpdateRarityMarker();
			UpdateAvailableMarker();
			UpdateLockedForSelling(currentItem);
		}

		public void SetItem(Item item, Vector2 cellSize)
		{
			Item item2 = currentItem;
			if (item2 != null)
			{
				item2.onIdentifyStatusChanged = (Action<Item>)Delegate.Remove(item2.onIdentifyStatusChanged, new Action<Item>(UpdateIdentificationStatus));
				item2.onLockedForSellingChanged = (Action<Item>)Delegate.Remove(item2.onLockedForSellingChanged, new Action<Item>(UpdateLockedForSelling));
				item2.onEffectsChanged = (Action<Item>)Delegate.Remove(item2.onEffectsChanged, new Action<Item>(OnItemChanged));
				item2.onNameChanged = (Action<Item>)Delegate.Remove(item2.onNameChanged, new Action<Item>(OnItemChanged));
				item2.onUseCountChanged = (Action<int>)Delegate.Remove(item2.onUseCountChanged, new Action<int>(OnUsesChanged));
			}
			currentItem = item;
			itemSize = new Vector2Int(item.slotsWide, item.slotsTall);
			itemImage.sprite = ((item.sprite != null) ? item.sprite : itemImage.sprite);
			Vector2 sizeDelta = itemSize * cellSize;
			rectTransform.anchoredPosition = Vector2.zero;
			rectTransform.sizeDelta = sizeDelta;
			rectTransform.localScale = Vector3.one;
			UpdateSockets();
			SetInteractable(interactable: true);
			UpdateLockedForSelling(currentItem);
			UpdateIdentificationStatus(currentItem);
			Item item3 = currentItem;
			item3.onIdentifyStatusChanged = (Action<Item>)Delegate.Combine(item3.onIdentifyStatusChanged, new Action<Item>(UpdateIdentificationStatus));
			Item item4 = currentItem;
			item4.onLockedForSellingChanged = (Action<Item>)Delegate.Combine(item4.onLockedForSellingChanged, new Action<Item>(UpdateLockedForSelling));
			Item item5 = currentItem;
			item5.onEffectsChanged = (Action<Item>)Delegate.Combine(item5.onEffectsChanged, new Action<Item>(OnItemChanged));
			Item item6 = currentItem;
			item6.onNameChanged = (Action<Item>)Delegate.Combine(item6.onNameChanged, new Action<Item>(OnItemChanged));
			Item item7 = currentItem;
			item7.onUseCountChanged = (Action<int>)Delegate.Combine(item7.onUseCountChanged, new Action<int>(OnUsesChanged));
			heroItemIndicator.SetActive(item.IsHeroItem() && item.heroType != HeroType.Ekbatan);
			UpdateQuestIndicator();
			UpdateRarityMarker();
			UpdateAvailableMarker();
			UpdateUses();
			bool flag = item.itemType != ItemType.Gem && item.grade != ItemGrade.Normal;
			bool flag2 = item.rank != Rank.Normal;
			highGradeIndicator.SetActive(flag);
			highRankIndicator.SetActive(flag2);
			rankGradeParent.SetActive(flag || flag2);
			base.gameObject.SetActive(value: true);
		}

		public void UpdateQuestIndicator()
		{
			if (currentItem == null)
			{
				return;
			}
			bool flag = currentItem.IsHeroItem() && currentItem.heroType != HeroType.Ekbatan;
			GameObject obj = questItemIndicator;
			int active;
			if (!flag)
			{
				if (!currentItem.isQuestItem)
				{
					ItemType itemType = currentItem.itemType;
					active = ((itemType == ItemType.EndUrn || itemType == ItemType.EndHammer) ? 1 : 0);
				}
				else
				{
					active = 1;
				}
			}
			else
			{
				active = 0;
			}
			obj.SetActive((byte)active != 0);
		}

		private void OnItemChanged(Item item)
		{
			if (currentItem == item)
			{
				UpdateRarityMarker();
				UpdateQuestIndicator();
			}
		}

		private void UpdateRarityMarker()
		{
			if (currentItem == null)
			{
				return;
			}
			if (!currentItem.ShowRarityToPlayer(Owner))
			{
				rarityIndicator.gameObject.SetActive(value: false);
				return;
			}
			if (currentItem.isArtifact)
			{
				rarityIndicator.color = rarityColorArtifact;
			}
			else if (currentItem.isUnique)
			{
				rarityIndicator.color = rarityColorUnique;
			}
			else if (currentItem.HasSpecialEffects)
			{
				rarityIndicator.color = rarityColorHasBonuses;
			}
			rarityIndicator.gameObject.SetActive(currentItem.HasSpecialEffects);
		}

		public void UpdateAvailableMarker()
		{
			if (currentItem != null)
			{
				Merchant merchant = ((Owner != null) ? (Owner as Merchant) : null);
				if (!(merchant != null) || !SingletonBehaviour<PlayerStatus>.InstanceExists())
				{
					notAvailableIndicator.SetActive(value: false);
				}
				else
				{
					notAvailableIndicator.SetActive(!SingletonBehaviour<PlayerStatus>.Instance.CanAfford(currentItem.GetPurchaseValueByMerchant(merchant.merchantType)));
				}
			}
		}

		public void UpdateIdentificationStatus(Item item)
		{
			if (currentItem != null && item == currentItem)
			{
				unidentifiedIndicator.SetActive(!currentItem.Identified);
			}
		}

		public void UpdateLockedForSelling(Item item)
		{
			if (currentItem != null && item == currentItem)
			{
				GameObject[] array = lockedForSellingIndicators;
				for (int i = 0; i < array.Length; i++)
				{
					array[i].SetActive(currentItem.lockedForSelling);
				}
			}
		}

		public void SetSlots(ItemSlotUI[] slots)
		{
			if (activeSlots != null)
			{
				foreach (ItemSlotUI activeSlot in activeSlots)
				{
					activeSlot.ForceClear();
				}
			}
			activeSlots = new List<ItemSlotUI>(slots);
		}

		public void SetSlots(ItemSlotUI slot)
		{
			if (activeSlots != null)
			{
				foreach (ItemSlotUI activeSlot in activeSlots)
				{
					activeSlot.ForceClear();
				}
			}
			activeSlots = new List<ItemSlotUI> { slot };
		}

		public void SetParent(Transform parent)
		{
			rectTransform.SetParent(parent);
			rectTransform.anchoredPosition = Vector2.zero;
			rectTransform.localScale = Vector3.one;
		}

		public void SetInteractable(bool interactable)
		{
			base.interactable = interactable;
			GetComponent<BoxCollider2D>().enabled = interactable;
			GetComponent<CanvasGroup>().interactable = interactable;
			GetComponent<CanvasGroup>().blocksRaycasts = interactable;
			selectIndicator.SetActive(value: false);
			SetSocketsVisualState(SocketsVisualState.PartiallyHidden);
			OnIsTargetingItem(isTargetingItem: false);
		}

		public void OnInteract()
		{
			if (InventoryUI.heldItem != null || InventoryUI.draggedItemUI != null || !(currentOwner != null) || !currentOwner.IsPlayerOwnedInventory || SimpleSingletonBehaviour<PlayerUI>.Instance.IsAnythingTargetingItem)
			{
				return;
			}
			List<Character> list = new List<Character> { currentOwner };
			bool flag = false;
			bool flag2 = false;
			if (currentItem.effects.TryGetValue(ActivationType.Usage, out var value))
			{
				for (int i = 0; i < value.Count; i++)
				{
					EffectData effectData = value[i];
					EffectType buffType = effectData.buffType;
					if (buffType == EffectType.RecoverPassoutFull || buffType == EffectType.RecoverPassoutPartial)
					{
						flag = true;
						break;
					}
					buffType = effectData.buffType;
					if (buffType == EffectType.Transform || buffType == EffectType.RevertTransform)
					{
						flag2 = true;
						break;
					}
				}
				if (flag)
				{
					if (!currentOwner.IsPartyMember() || !currentOwner.IsPassedOut())
					{
						list.Remove(currentOwner);
					}
					for (int j = 0; j < currentOwner.GetPartyMemberCount(); j++)
					{
						Character partyMember = currentOwner.GetPartyMember(j);
						if (partyMember.IsPassedOut())
						{
							list.Add(partyMember);
						}
					}
				}
				else if (flag2)
				{
					if (!currentOwner.IsPet())
					{
						list.Remove(currentOwner);
					}
					Character pet = currentOwner.GetPet();
					if (pet != null)
					{
						list.Add(pet);
					}
				}
			}
			if (value != null && value.Count > 0 && currentItem.useable && currentItem.uses > 0 && currentOwner.RequirementsMet(currentItem) && currentItem.CanUse(currentOwner, currentOwner))
			{
				bool flag3 = false;
				foreach (Character item in list)
				{
					for (int k = 0; k < value.Count; k++)
					{
						EffectData effect = value[k];
						if (effect.buffType == EffectType.Transform)
						{
							if (!item.IsPartyMember() && item.HasPet())
							{
								Character pet2 = item.GetPet();
								AIState aIState = pet2.GetAIState();
								if (aIState == AIState.ReturningToTown || aIState == AIState.InTown)
								{
									SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
									flag3 = false;
									break;
								}
								if (Owner == item)
								{
									item.onTransformed = (Action<Character>)Delegate.Combine(item.onTransformed, new Action<Character>(SetOwner));
								}
								SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_pettransform);
								pet2.Transform(value[k].name, effect.permanent ? (-1000) : value[k].value, isLoad: false);
								flag3 = true;
							}
							else if (item.IsPet() && item.HasMaster() && item.Master().IsPlayer())
							{
								AIState aIState = item.GetAIState();
								if (aIState == AIState.ReturningToTown || aIState == AIState.InTown)
								{
									SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
									flag3 = false;
									break;
								}
								if (Owner == item)
								{
									item.onTransformed = (Action<Character>)Delegate.Combine(item.onTransformed, new Action<Character>(SetOwner));
								}
								SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_pettransform);
								item.Transform(value[k].name, effect.permanent ? (-1000) : value[k].value, isLoad: false);
								flag3 = true;
							}
							continue;
						}
						if (effect.buffType == EffectType.RevertTransform)
						{
							Character character = null;
							if (!item.IsPartyMember() && item.HasPet())
							{
								character = currentOwner.GetPet();
							}
							else if (item.IsPet() && item.HasMaster() && item.Master().IsPlayer())
							{
								character = item;
							}
							if (character != null)
							{
								AIState aIState = character.GetAIState();
								if (aIState == AIState.ReturningToTown || aIState == AIState.InTown)
								{
									SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
									flag3 = false;
									break;
								}
								if (!character.CanRevertTransformation(out var _))
								{
									flag3 = false;
									break;
								}
								if (Owner == character)
								{
									Character character2 = character;
									character2.onTransformed = (Action<Character>)Delegate.Combine(character2.onTransformed, new Action<Character>(SetOwner));
								}
								flag3 = true;
								character.RevertTransformation(removeTransformEffect: true);
							}
							continue;
						}
						if (effect.buffType == EffectType.WriteSpell)
						{
							item.AddSpell(SingletonBehaviour<FateDB>.Instance.allSpells.Find((SpellData sp) => sp.spellName == effect.name));
							SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_newspell);
							flag3 = true;
							if (item.IsPlayer() && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.WriteSpell, out var key))
							{
								SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
							}
							continue;
						}
						if (effect.buffType == EffectType.OpenPortal)
						{
							if (LevelGenerator.currentInstance == null)
							{
								UnityEngine.Debug.Log("No portal opening in town");
							}
							else if (SingletonBehaviour<PortalManager>.Instance.TryCreatePortal(item))
							{
								flag3 = true;
							}
							continue;
						}
						if (effect.buffType == EffectType.RealmPortal)
						{
							Fate.SetPause(paused: true);
							RealmData.RealmId destinationRealm = (RealmData.RealmId)effect.value;
							SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetMultiLineFormat("Question_GoTo", I2Loca.Get("RealmName_" + destinationRealm)), delegate(bool confirm)
							{
								if (!confirm)
								{
									if (SimpleSingletonBehaviour<PlayerUI>.Instance.CurrentScreenTab == UITabs.TabType.None)
									{
										Fate.SetPause(paused: false);
									}
								}
								else
								{
									Fate.FateVer currentFateVer = Fate.CurrentFateVer;
									if (currentFateVer != Fate.FateVer.UndiscoveredRealms && currentFateVer != Fate.FateVer.TraitorSoul)
									{
										SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
										if (SimpleSingletonBehaviour<PlayerUI>.Instance.CurrentScreenTab == UITabs.TabType.None)
										{
											Fate.SetPause(paused: false);
										}
									}
									else
									{
										bool num = SingletonBehaviour<Town>.InstanceExists();
										bool flag4 = LevelGenerator.currentInstance != null;
										if (num && SingletonBehaviour<PlayerStatus>.Instance.TownRealm == destinationRealm)
										{
											SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
											if (SimpleSingletonBehaviour<PlayerUI>.Instance.CurrentScreenTab == UITabs.TabType.None)
											{
												Fate.SetPause(paused: false);
											}
										}
										else
										{
											Player.PlayerChar.SetInvincible();
											currentItem.PlayUseSound();
											if (currentItem.uses >= 2 && InventoryUI.activeItem == this)
											{
												OnSelect(null);
											}
											else
											{
												OnDeselect(null);
											}
											SpendUses();
											SimpleSingletonBehaviour<PlayerUI>.Instance.CloseTabs();
											if (flag4)
											{
												SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_portal);
												SingletonBehaviour<AudioManager>.Instance.StopMusic(AudioData.AudioClipName.DungeonMusic);
												LevelGenerator.currentInstance.UpdateSaveData(goesDown: false);
											}
											Town.UpdateSpawnIndex(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, Town.EntryMethod.RealmPortal);
											SceneLoad.LoadAsync(SceneLoad.GetTownScene(destinationRealm), save: true);
											StatsManager.IncrementStat(Stat.PortalsUsed);
											if (Player.PlayerChar.hp <= (float)Player.PlayerChar.MaxHP() * 0.1f)
											{
												StatsManager.SetStat(Stat.HealthLostOnTP, 100);
											}
										}
									}
								}
							}, twoButtons: true);
							return;
						}
						if (effect.buffType == EffectType.Identify)
						{
							flag3 = false;
							continue;
						}
						item.AddEffect(effect, 1, null);
						flag3 = true;
					}
				}
				if (flag3)
				{
					if (currentItem.itemType == ItemType.Potion)
					{
						StatsManager.IncrementStat(Stat.PotionsUsed);
					}
					currentItem.PlayUseSound();
					if (currentItem.uses == 1)
					{
						OnDeselect(null);
					}
					SpendUses();
					if (currentItem == null || (currentItem.uses > 1 && InventoryUI.activeItem == this))
					{
						OnSelect(null);
					}
					return;
				}
			}
			else if (currentItem.IsEquippableType() && SimpleSingletonBehaviour<PlayerUI>.Instance.TryInteractEquipItemUI(this))
			{
				return;
			}
			if (currentItem.itemTarget == ItemTarget.Item)
			{
				if (SimpleSingletonBehaviour<PlayerUI>.Instance.CurrentScreenTab != UITabs.TabType.Inventory && !SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.gameObject.activeInHierarchy)
				{
					SimpleSingletonBehaviour<PlayerUI>.Instance.ShowInventory(PlayerUI.InventoryStateType.Stats);
				}
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetItemTargetingItem(this);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			}
		}

		private void SpendUses(int amount = 1, bool isInInventory = true)
		{
			if (currentItem.HasUnlimitedUses)
			{
				return;
			}
			currentItem.uses -= amount;
			currentItem.onUseCountChanged?.Invoke(currentItem.uses);
			if (currentItem.uses > 0)
			{
				return;
			}
			if (InventoryUI.activeItem == this)
			{
				InventoryUI.activeItem = null;
			}
			if (currentOwner.inventory.Contains(currentItem))
			{
				currentOwner.RemoveItemFromInventory(currentItem, RemoveItemReason.Consumed);
			}
			else if (currentOwner.HasPet())
			{
				Character pet = currentOwner.GetPet();
				if (pet.inventory.Contains(currentItem))
				{
					pet.RemoveItemFromInventory(currentItem, RemoveItemReason.Consumed);
				}
			}
			Item spentItem = currentItem;
			int num = (spentItem.InHotbarSlot ? currentItem.slotIndex : (-1));
			bool num2 = currentOwner.IsPlayer() && spentItem.itemType == ItemType.Potion && num >= 0 && (float)num < 4f;
			ForceClearCurrentSlots();
			base.gameObject.SetActive(value: false);
			if (!num2)
			{
				return;
			}
			Item otherItemOfSameType = Player.PlayerChar.inventory.Find((Item potentialItem) => potentialItem.itemType == ItemType.Potion && potentialItem.itemBaseName == spentItem.itemBaseName && Fate.IsItemSlotInInventoryGrid(potentialItem.slotIndex));
			if (otherItemOfSameType == null)
			{
				return;
			}
			InventoryGrid gridByCharacter = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetGridByCharacter(Player.PlayerChar);
			if (gridByCharacter != null && gridByCharacter.gameObject.activeInHierarchy)
			{
				gridByCharacter.RunActionOnAllItemUIs(delegate(ItemUI itemUI)
				{
					if (itemUI.currentItem == otherItemOfSameType)
					{
						itemUI.gameObject.SetActive(value: false);
					}
				});
			}
			Player.PlayerChar.AddItemToHotbar(otherItemOfSameType, num, AddItemReason.Transfer);
		}

		public void OnBeginDrag(PointerEventData eventData)
		{
			if (SimpleSingletonBehaviour<PlayerUI>.Instance.IsAnythingTargetingItem || eventData == null || eventData.button != 0 || !holdAndDragAllowed || (currentItem.InEquipmentSlot && !currentOwner.IsPlayerOwnedInventory))
			{
				return;
			}
			InventoryUI.draggedItemUI = this;
			startParent = base.transform.parent;
			canvasGroup.alpha = 0.5f;
			canvasGroup.blocksRaycasts = false;
			if (activeSlots.Count > 0 && Fate.IsItemSlotInInventoryGrid(activeSlots[0].globalIndex))
			{
				Character owner = activeSlots[0].Owner;
				if (owner != null)
				{
					owner.ReleaseInventorySlotsForItem(currentItem);
				}
				else
				{
					Stash stash = (activeSlots[0].IsStashSlot ? activeSlots[0].parentGrid.Stash : null);
					if (stash != null)
					{
						stash.ReleaseInventorySlotsForItem(currentItem);
					}
					else
					{
						UnityEngine.Debug.LogWarning("Tried to release inventory indexed item (" + currentItem.itemName + ") from owner/stash but neither owner nor stash found");
					}
				}
			}
			UndockCurrentSlots(revertDisabledSlots: false);
			base.transform.SetParent(parentCanvas.transform);
			base.transform.SetAsLastSibling();
			RectTransform obj = rectTransform;
			RectTransform obj2 = rectTransform;
			Vector2 vector2 = (rectTransform.pivot = new Vector2(0.5f, 0.5f));
			Vector2 anchorMin = (obj2.anchorMax = vector2);
			obj.anchorMin = anchorMin;
			rectTransform.anchoredPosition = Vector2.zero;
			BoxCollider2D boxCollider2D = BoxCol;
			boxCollider2D.size = rectTransform.sizeDelta * 0.85f;
			boxCollider2D.offset = Vector2.zero;
		}

		public void OnDrag(PointerEventData eventData)
		{
			if (!(InventoryUI.draggedItemUI != this))
			{
				base.transform.position = eventData.position + new Vector2(0f, 5f);
			}
		}

		public void OnEndDrag(PointerEventData eventData)
		{
			if (InventoryUI.draggedItemUI != this)
			{
				return;
			}
			InventoryUI.draggedItemUI = null;
			canvasGroup.alpha = 1f;
			canvasGroup.blocksRaycasts = true;
			currentItem.PlayLandSound();
