		public void AttemptItemDrop(Transform startParent)
		{
			bool flag = false;
			bool flag2 = false;
			bool flag3 = previousSlots != null && previousSlots.Count > 0 && previousSlots[0].parentGrid != null && previousSlots[0].parentGrid.IsStash;
			ItemSlotUI itemSlotUI = activeSlots[0];
			Character owner = itemSlotUI.Owner;
			if (owner != currentOwner)
			{
				if (currentOwner != null && currentOwner.IsPlayer())
				{
					ItemSlotUI itemSlotUI2 = currentCollidingSlots.Find((ItemSlotUI a) => a.parentGrid != null && a.parentGrid.Owner != currentOwner);
					if (itemSlotUI2 != null)
					{
						if (itemSlotUI2.parentGrid.IsStash && Player.PlayerChar.TryMoveItem(currentItem))
						{
							SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.AddItemToStash(currentItem, itemSlotUI.gridBasedIndex);
							flag = true;
						}
						else if (itemSlotUI2.parentGrid.Owner.IsPlayerOwnedInventory)
						{
							Owner.RemoveItemFromInventory(currentItem, RemoveItemReason.Transfer);
							itemSlotUI2.parentGrid.Owner.AddItemToInventory(currentItem, AddItemReason.Transfer, itemSlotUI.globalIndex, desiredSlotIsGlobal: true);
							flag = true;
						}
						currentItem.PlayLandSound();
					}
					else
					{
						Character character = currentOwner;
						if (itemSlotUI.TrySetItem(this))
						{
							character.RemoveItemFromInventory(currentItem, RemoveItemReason.Transfer);
							if (owner != null)
							{
								owner.AddItemToInventory(currentItem, AddItemReason.Loot, itemSlotUI.globalIndex, desiredSlotIsGlobal: true);
							}
							flag = true;
						}
					}
				}
				else if (owner != null && owner.IsPlayer())
				{
					MerchantType activeMerchantType = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.ActiveMerchantType;
					if (Owner != null && Owner.IsPlayerOwnedInventory)
					{
						currentOwner.RemoveItemFromInventory(currentItem, RemoveItemReason.Transfer);
						if (owner != null)
						{
							owner.AddItemToInventory(currentItem, AddItemReason.Loot, itemSlotUI.globalIndex, desiredSlotIsGlobal: true);
						}
						flag = true;
					}
					else if (!flag3 && Player.PlayerChar.TryBuyItem(Owner, currentItem, activeMerchantType, itemSlotUI.globalIndex))
					{
						flag = true;
						if (activeMerchantType == MerchantType.None || activeMerchantType == MerchantType.All)
						{
							UnityEngine.Debug.LogError($"Bad merhant type when purchasing item {activeMerchantType}");
						}
					}
					else if (flag3)
					{
						SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.RemoveItemFromStash(currentItem);
						Player.PlayerChar.AddItemToInventory(currentItem, AddItemReason.Transfer, itemSlotUI.globalIndex, desiredSlotIsGlobal: true);
						flag = true;
					}
				}
			}
			else if (owner != null && owner == currentOwner && currentItem.slotIndex >= 20 && activeSlots[0].globalIndex >= 20)
			{
				owner.ItemMovedInInventory(currentItem, activeSlots[0].globalIndex);
				flag = true;
			}
			else if (currentOwner != null && currentOwner.IsPlayer() && flag3 && activeSlots[0].parentGrid.IsStash)
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.onItemMovedInStash(currentItem, activeSlots[0].globalIndex);
				flag = true;
			}
			else if (!currentItem.InInventoryGrid && Fate.IsItemSlotInInventoryGrid(itemSlotUI.globalIndex))
			{
				if (currentItem.InEquipmentSlot)
				{
					Owner.UnequipItem(currentItem);
				}
				flag = true;
				flag2 = true;
			}
			else if (currentItem.InInventoryGrid && !Fate.IsItemSlotInInventoryGrid(itemSlotUI.globalIndex))
			{
				currentOwner.ReleaseInventorySlotsForItem(currentItem);
				flag = true;
			}
			else if (!currentItem.InInventoryGrid && !Fate.IsItemSlotInInventoryGrid(itemSlotUI.globalIndex))
			{
				flag = true;
			}
			else if (activeSlots[0].IsStashSlot)
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.ItemMovedInStash(currentItem, activeSlots[0].globalIndex);
				flag = true;
			}
			if (flag)
			{
				DockToActiveSlots(startParent, autoEquipped: false);
				if (flag2)
				{
					currentOwner.ReserveInventorySlotsForItem(currentItem);
				}
			}
			else
			{
				ReturnToOriginalSpot();
			}
		}

		public void ReturnToOriginalSpot()
		{
			activeSlots = new List<ItemSlotUI>(previousSlots);
			currentItem.PlayLandSound();
			ItemSlotUI component = activeSlots[0].GetComponent<ItemSlotUI>();
			if (Fate.IsItemSlotInInventoryGrid(component.globalIndex))
			{
				int num = component.globalIndex - 20;
				int foundSlotIndex;
				if (component.IsStashSlot)
				{
					Stash stash = component.parentGrid.Stash;
					bool flag = stash.CanFitItem(currentItem, out foundSlotIndex, num);
					if (currentItem.slotIndex == component.globalIndex)
					{
						flag = true;
						foundSlotIndex = num;
					}
					if (flag)
					{
						currentItem.slotIndex = 20 + foundSlotIndex;
						stash.ReserveInventorySlotsForItem(currentItem);
						if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.gameObject.activeInHierarchy)
						{
							component.parentGrid.AddItemHandleToGrid(this);
							return;
						}
						stash.OnItemMovedFromStash(currentItem);
						currentItem.Drop(stash.transform.position);
						ForceClearCurrentSlots();
						base.gameObject.SetActive(value: false);
					}
				}
				else
				{
					if (!(Owner != null))
					{
						return;
					}
					bool flag2 = Owner.CanFitItemInInventoryGrid(currentItem, out foundSlotIndex, num);
					if (currentItem.slotIndex == component.globalIndex)
					{
						flag2 = true;
						foundSlotIndex = num;
					}
					if (flag2)
					{
						currentItem.slotIndex = 20 + foundSlotIndex;
						Owner.ReserveInventorySlotsForItem(currentItem);
						if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.gameObject.activeInHierarchy)
						{
							component.parentGrid.AddItemHandleToGrid(this);
							return;
						}
						Owner.RemoveItemFromInventory(currentItem, RemoveItemReason.Drop);
						currentItem.Drop(Player.PlayerChar.myTransform.position);
						ForceClearCurrentSlots();
						base.gameObject.SetActive(value: false);
					}
				}
			}
			else
			{
				DockToActiveSlots(startParent, autoEquipped: false);
			}
		}

		public void CancelItemMove()
		{
			canvasGroup.alpha = 1f;
			canvasGroup.blocksRaycasts = true;
			activeSlots = new List<ItemSlotUI>(previousSlots);
			DockToActiveSlots(startParent, autoEquipped: false);
		}

		public void RevertSlot()
		{
			if (activeSlots != null && activeSlots.Count > 0)
			{
				activeSlots[0].TrySetItem(null);
			}
			ItemSlotUI component = startParent.GetComponent<ItemSlotUI>();
			int desiredSlot = ((component != null && Fate.IsItemSlotInInventoryGrid(component.globalIndex)) ? (component.globalIndex - 20) : (-1));
			if (Owner.CanFitItemInInventoryGrid(currentItem, out var foundSlotIndex, desiredSlot))
			{
				currentItem.slotIndex = 20 + foundSlotIndex;
				Owner.ReserveInventorySlotsForItem(currentItem);
				InventoryGrid gridByCharacter = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetGridByCharacter(Owner);
				if (gridByCharacter != null && gridByCharacter.gameObject.activeInHierarchy)
				{
					gridByCharacter.AddItemHandleToGrid(this);
					return;
				}
				Owner.RemoveItemFromInventory(currentItem, RemoveItemReason.Drop);
				currentItem.Drop(Player.PlayerChar.myTransform.position);
				ForceClearCurrentSlots();
				base.gameObject.SetActive(value: false);
			}
		}

		public void RevertDisabledSlot()
		{
			if (activeSlots != null && activeSlots.Count > 0)
			{
				activeSlots[0].TrySetItem(null);
			}
			ItemSlotUI component = startParent.GetComponent<ItemSlotUI>();
			if (component is EquipmentSlotUI && component.IsOpen && component.itemHandle == null)
			{
				var (flag, flag2) = Player.PlayerChar.CanEquip(currentItem);
				int foundSlotIndex;
				if (flag && flag2)
				{
					currentItem.slotIndex = component.globalIndex;
					Player.PlayerChar.EquipItem(currentItem, currentItem.weaponSet);
				}
				else if (Owner.CanFitItemInInventoryGrid(currentItem, out foundSlotIndex))
				{
					currentItem.slotIndex = foundSlotIndex + 20;
					Owner.ReserveInventorySlotsForItem(currentItem);
					InventoryGrid gridByCharacter = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetGridByCharacter(Owner);
					if (gridByCharacter != null && gridByCharacter.gameObject.activeInHierarchy)
					{
						gridByCharacter.AddItemHandleToGrid(this);
					}
				}
				else
				{
					if (Owner.inventory.Contains(currentItem))
					{
						Owner.RemoveItemFromInventory(currentItem, RemoveItemReason.Drop);
					}
					ForceClearCurrentSlots();
					currentItem.Drop(Player.PlayerChar.myTransform.position);
				}
				return;
			}
			int desiredSlot = ((component != null && Fate.IsItemSlotInInventoryGrid(component.globalIndex)) ? (component.globalIndex - 20) : (-1));
			if (Owner.CanFitItemInInventoryGrid(currentItem, out var foundSlotIndex2, desiredSlot))
			{
				currentItem.slotIndex = foundSlotIndex2 + 20;
				Owner.ReserveInventorySlotsForItem(currentItem);
				InventoryGrid gridByCharacter2 = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetGridByCharacter(Owner);
				if (gridByCharacter2 != null && gridByCharacter2.gameObject.activeInHierarchy)
				{
					gridByCharacter2.AddItemHandleToGrid(this);
				}
			}
			else
			{
				if (Owner.inventory.Contains(currentItem))
				{
					Owner.RemoveItemFromInventory(currentItem, RemoveItemReason.Drop);
				}
				ForceClearCurrentSlots();
				currentItem.Drop(Player.PlayerChar.myTransform.position);
			}
		}

		private void OnTriggerEnter2D(Collider2D col)
		{
			ItemSlotUI component = col.GetComponent<ItemSlotUI>();
			if (!(component == null) && !currentCollidingSlots.Contains(component))
			{
				currentCollidingSlots.Add(component);
				component.SetHover(hovered: true);
			}
		}

		private void OnTriggerStay2D(Collider2D col)
		{
		}

		private void OnTriggerExit2D(Collider2D col)
		{
			ItemSlotUI component = col.GetComponent<ItemSlotUI>();
			if (!(component == null) && currentCollidingSlots.Contains(component))
			{
				component.SetHover(hovered: false);
				currentCollidingSlots.Remove(component);
			}
		}

		public void DockToActiveSlots(Transform newParent, bool autoEquipped)
		{
			Character character = activeSlots[0].Owner ?? activeSlots[0].parentGrid?.Owner;
			if (character != null && previousSlots != null && previousSlots.Count > 0 && previousSlots[0] is EquipmentSlotUI)
			{
				character.UnequipItem(currentItem);
				previousSlots.Clear();
			}
			if (!autoEquipped)
			{
				currentItem.slotIndex = activeSlots[0].globalIndex;
				if (activeSlots[0] is EquipmentSlotUI equipmentSlotUI)
				{
					character = equipmentSlotUI.owner;
					character.EquipItem(currentItem, (!equipmentSlotUI.IsWeaponSetSlot) ? WeaponSet.Primary : equipmentSlotUI.WeaponSetSlot);
					currentItem.PlayLandSound();
				}
			}
			if (character == null && (activeSlots[0] is HotbarSlotUI || activeSlots[0] is EnchantSlotUI))
			{
				character = Player.PlayerChar;
			}
			SetOwner(character);
			if (activeSlots[0] is HotbarSlotUI hotbarSlotUI)
			{
				SetItem(currentItem, hotbarSlotUI.cellSize);
			}
			else if (!(activeSlots[0] is EquipmentSlotUI) && !(activeSlots[0] is EnchantSlotUI))
			{
				SetItem(currentItem, activeSlots[0].parentGrid.inventoryGrid.cellSize);
			}
			SetParent(newParent);
			foreach (ItemSlotUI activeSlot in activeSlots)
			{
				activeSlot.TrySetItem(this);
			}
			if (InventoryUI.heldItem == this)
			{
				InventoryUI.heldItem = null;
			}
		}

		public void UndockCurrentSlots(bool revertDisabledSlots = true)
		{
			currentCollidingSlots?.Clear();
			previousSlots?.Clear();
			if (activeSlots == null)
			{
				return;
			}
			foreach (ItemSlotUI activeSlot in activeSlots)
			{
				if (revertDisabledSlots && activeSlot is EnchantSlotUI && currentItem.slotIndex == activeSlot.globalIndex && InventoryUI.draggedItemUI != this && InventoryUI.heldItem != this)
				{
					RevertDisabledSlot();
				}
				activeSlot.TrySetItem(null);
				previousSlots.Add(activeSlot);
			}
			activeSlots = null;
		}

		public void ForceClearCurrentSlots()
		{
			currentCollidingSlots?.Clear();
			previousSlots?.Clear();
			if (activeSlots != null)
			{
				foreach (ItemSlotUI activeSlot in activeSlots)
				{
					activeSlot.ForceClear();
				}
			}
			activeSlots = null;
		}

		public override void OnSelect(BaseEventData eventData)
		{
			if (currentItem != null)
			{
				if (!SimpleSingletonBehaviour<PlayerUI>.Instance.IsAnythingTargetingItem)
				{
					bool shopOpen = InventoryUI.ShopOpen && !SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.shopUI.GetGrid.IsStash;
					SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.ShowTooltip(currentItem, shopOpen, currentOwner);
				}
				selectIndicator.SetActive(value: true);
				SetSocketsVisualState(SocketsVisualState.Shown);
				InventoryUI.activeItem = this;
				base.OnSelect(eventData);
			}
		}

		public override void OnDeselect(BaseEventData eventData)
		{
			SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.HideTooltip();
			selectIndicator.SetActive(value: false);
			SetSocketsVisualState(SocketsVisualState.PartiallyHidden);
			if (InventoryUI.activeItem == this)
			{
				InventoryUI.activeItem = null;
			}
			base.OnDeselect(eventData);
		}

		public void SetSocketsVisualState(SocketsVisualState state)
		{
			if (activeSlots == null)
			{
				return;
			}
			float alpha = ((state == SocketsVisualState.PartiallyHidden) ? slotFadeOutAlpha : 1f);
			foreach (ItemSocketUI socketSlot in socketSlots)
			{
				if (socketSlot.TryGetComponent<Image>(out var component))
				{
					component.color = component.color.WithAlpha(alpha);
				}
			}
		}

		public void OnIsTargetingItem(bool isTargetingItem)
		{
			if ((bool)itemTargetingIndicator)
			{
				itemTargetingIndicator.SetActive(isTargetingItem);
			}
		}

		public override void OnPointerEnter(PointerEventData eventData)
		{
			Select();
			base.OnPointerEnter(eventData);
		}

		public override void OnMove(AxisEventData eventData)
		{
			base.OnMove(eventData);
		}

		public override void OnPointerExit(PointerEventData eventData)
		{
			UtilityTG.SetSelected(null);
			base.OnPointerExit(eventData);
		}

		public override void OnPointerDown(PointerEventData eventData)
		{
			if (eventData.button != 0)
			{
				return;
			}
			if (SimpleSingletonBehaviour<PlayerUI>.Instance.IsAnythingTargetingItem)
			{
				holdAndDragAllowed = false;
				if (!currentOwner.IsPlayerOwnedInventory)
				{
					return;
				}
				if (SimpleSingletonBehaviour<PlayerUI>.Instance.IsSpellTargetingItem)
				{
					Player playerChar = Player.PlayerChar;
					Item targetItem = currentItem;
					playerChar.TryCastCurrentSpell(null, null, null, targetItem);
					SimpleSingletonBehaviour<PlayerUI>.Instance.SetSpellTargetingItem(isTargeting: false);
					return;
				}
				if (SimpleSingletonBehaviour<PlayerUI>.Instance.IsItemTargetingItem && SimpleSingletonBehaviour<PlayerUI>.Instance.itemTargetingItem != this)
				{
					bool flag = SimpleSingletonBehaviour<PlayerUI>.Instance.itemTargetingItem.currentItem.itemType == ItemType.Gem;
					bool flag2 = false;
					if (SimpleSingletonBehaviour<PlayerUI>.Instance.itemTargetingItem.currentItem.effects.TryGetValue(ActivationType.Usage, out var value))
					{
						foreach (EffectData item in value)
						{
							if (item.buffType == EffectType.Identify)
							{
								flag2 = true;
								break;
							}
						}
					}
					if (flag)
					{
						if (currentItem.sockets > 0 && (currentItem.sockedtedItems == null || currentItem.sockedtedItems.Count < currentItem.sockets))
						{
							currentItem.SocketItem(SimpleSingletonBehaviour<PlayerUI>.Instance.itemTargetingItem.currentItem);
							UpdateSockets();
							SimpleSingletonBehaviour<PlayerUI>.Instance.itemTargetingItem.currentOwner.RemoveItemFromInventory(SimpleSingletonBehaviour<PlayerUI>.Instance.itemTargetingItem.currentItem, RemoveItemReason.Consumed);
							SimpleSingletonBehaviour<PlayerUI>.Instance.itemTargetingItem.gameObject.SetActive(value: false);
							SimpleSingletonBehaviour<PlayerUI>.Instance.SetItemTargetingItem(null);
						}
						else
						{
							SimpleSingletonBehaviour<PlayerUI>.Instance.SetItemTargetingItem(null);
							currentItem.PlayLandSound();
						}
					}
					else if (flag2 && !currentItem.Identified)
					{
						currentItem.PlayerIdentify();
						SimpleSingletonBehaviour<PlayerUI>.Instance.itemTargetingItem.SpendUses();
						SimpleSingletonBehaviour<PlayerUI>.Instance.SetItemTargetingItem(null);
					}
				}
			}
			currentItem.PlayTakeSound();
		}

		public override void OnPointerUp(PointerEventData eventData)
		{
			if (!holdAndDragAllowed)
			{
				holdAndDragAllowed = true;
				holdAndDragAllowedFrame = Time.frameCount;
			}
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			if (SingletonBehaviour<InputBroker>.Instance.HoldingQuickMoveItems)
			{
				if (InventoryUI.ShopOpen)
				{
					InventoryGrid grid = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.playerInventory.grid;
					InventoryGrid getGrid = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.shopUI.GetGrid;
					if (Owner == Player.PlayerChar)
					{
						if (getGrid.IsStash)
						{
							if (Player.PlayerChar.TryMoveItem(currentItem))
							{
								SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.AddItemToStash(currentItem);
								if (currentItem.IsSlotValid && getGrid.gameObject.activeInHierarchy)
								{
									SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.shopUI.GetGrid.AddItemHandleToGrid(this);
								}
								else
								{
									ForceClearCurrentSlots();
									base.gameObject.SetActive(value: false);
								}
							}
							SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.HideTooltip();
						}
						else if (Player.PlayerChar.TrySellItem(currentItem))
						{
							if (SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetActiveMerchant.AddItemToInventory(currentItem, AddItemReason.Loot))
							{
								if (getGrid.gameObject.activeInHierarchy)
								{
									SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.shopUI.GetGrid.AddItemHandleToGrid(this);
								}
							}
							else
							{
								ForceClearCurrentSlots();
								base.gameObject.SetActive(value: false);
							}
							SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.HideTooltip();
						}
					}
					else if (getGrid.IsStash)
					{
						SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.RemoveItemFromStash(currentItem);
						if (currentItem.itemType == ItemType.Potion && Player.PlayerChar.TryGetFirstFreeHotbarSlot(out var slot))
						{
							Item item = currentItem;
							base.gameObject.SetActive(value: false);
							Player.PlayerChar.AddItemToHotbar(item, slot, AddItemReason.Transfer);
						}
						else if (Player.PlayerChar.AddItemToInventory(currentItem, AddItemReason.Transfer))
						{
							if (grid.gameObject.activeInHierarchy)
							{
								grid.AddItemHandleToGrid(this);
							}
						}
						else
						{
							currentItem.Drop(Player.PlayerChar.myTransform.position);
							ForceClearCurrentSlots();
							base.gameObject.SetActive(value: false);
						}
						SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.HideTooltip();
					}
					else if (Player.PlayerChar.TryBuyItem(SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetActiveMerchant, currentItem, SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.ActiveMerchantType))
					{
						if (currentItem.itemType == ItemType.Potion && Player.PlayerChar.TryGetFirstFreeHotbarSlot(out var slot2))
						{
							Item item2 = currentItem;
							base.gameObject.SetActive(value: false);
							Player.PlayerChar.AddItemToHotbar(item2, slot2, AddItemReason.Transfer);
						}
						else if (grid.gameObject.activeInHierarchy)
						{
							grid.AddItemHandleToGrid(this);
						}
						SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.HideTooltip();
					}
				}
				else
				{
					InventoryGrid grid2 = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.playerInventory.grid;
					InventoryGrid leftSideCharacterGrid = SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.GetLeftSideCharacterGrid();
					if (!grid2.gameObject.activeInHierarchy || !(leftSideCharacterGrid != null) || !leftSideCharacterGrid.gameObject.activeInHierarchy)
					{
						return;
					}
					InventoryGrid inventoryGrid = ((((Owner == Player.PlayerChar) ? grid2 : leftSideCharacterGrid) == grid2) ? leftSideCharacterGrid : grid2);
					if (inventoryGrid.Owner.CanFitItemInInventoryGrid(currentItem, out var _))
					{
						Owner.RemoveItemFromInventory(currentItem, RemoveItemReason.Transfer);
						inventoryGrid.Owner.AddItemToInventory(currentItem, AddItemReason.Transfer);
						inventoryGrid.AddItemHandleToGrid(this);
					}
					else
					{
						Owner.ReserveInventorySlotsForItem(currentItem);
					}
				}
				InventoryUI.activeItem = null;
			}
			else if (SingletonBehaviour<InputBroker>.Instance.HoldingLockItemsForSelling)
			{
				if (Owner == null || Owner.IsPlayerOwnedInventory)
				{
					currentItem.ToggleLockedForSelling();
					OnSelect(null);
				}
			}
			else if (SimpleSingletonBehaviour<PlayerUI>.Instance.IsAnythingTargetingItem)
			{
				OnPointerDown(eventData);
			}
			else if (eventData == null || eventData.button != 0 || !holdAndDragAllowed || Time.frameCount < holdAndDragAllowedFrame + 2)
			{
				OnPointerUp(eventData);
			}
			else
			{
				if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove || (currentItem.InEquipmentSlot && !currentOwner.IsPlayerOwnedInventory))
				{
					return;
				}
				startParent = base.transform.parent;
				canvasGroup.alpha = 0.5f;
				canvasGroup.blocksRaycasts = false;
				if (activeSlots.Count > 0 && Fate.IsItemSlotInInventoryGrid(activeSlots[0].globalIndex))
				{
					Character owner = activeSlots[0].Owner;
					if (owner != null)
					{
						owner.ReleaseInventorySlotsForItem(currentItem);
					}
					else
					{
						Stash stash = (activeSlots[0].IsStashSlot ? activeSlots[0].parentGrid.Stash : null);
						if (stash != null)
						{
							stash.ReleaseInventorySlotsForItem(currentItem);
						}
					}
				}
				UndockCurrentSlots(revertDisabledSlots: false);
				base.transform.SetParent(parentCanvas.transform);
				base.transform.SetAsLastSibling();
				if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free)
				{
					base.transform.SetParent(SingletonBehaviour<CursorManager>.Instance.VirtualCursor.transform);
				}
				else
				{
					base.transform.SetParent(parentCanvas.transform);
				}
				base.transform.SetAsLastSibling();
				RectTransform obj = rectTransform;
				RectTransform obj2 = rectTransform;
				Vector2 vector2 = (rectTransform.pivot = new Vector2(0.5f, 0.5f));
				Vector2 anchorMin = (obj2.anchorMax = vector2);
				obj.anchorMin = anchorMin;
				rectTransform.anchoredPosition = Vector2.zero;
				BoxCollider2D boxCollider2D = BoxCol;
				boxCollider2D.size = rectTransform.sizeDelta * 0.85f;
				boxCollider2D.offset = Vector2.zero;
				InventoryUI.heldItem = this;
			}
		}

		private void UpdateUses()
		{
			bool flag = currentItem != null && currentItem.useable && currentItem.originalUses > 1 && currentItem.uses > 0 && currentItem.uses != -9999;
			useCountParent.SetActive(flag);
			if (flag)
			{
				useCountText.text = currentItem.uses.ToString();
			}
		}

		private void OnUsesChanged(int _)
		{
			UpdateUses();
		}
	}
	public class ShopUI : MonoBehaviour
	{
		[SerializeField]
		private InventoryGrid shopGrid;

		[SerializeField]
		private TextMeshProUGUI headerText;

		[SerializeField]
		private Button sortButtonGO;

		private bool stashIsOpen;

		private Stash stash;

		public InventoryGrid GetGrid => shopGrid;

		public Stash GetStash => stash;

		public bool GetStashIsOpen => stashIsOpen;

		private void Start()
		{
			sortButtonGO.onClick.AddListener(OnAutoSortStashInput);
		}

		private void OnAutoSortStashInput()
		{
			if (stashIsOpen)
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.AutoSortInventoryForStash(toggleSortDirection: true);
			}
		}

		private void OnEnable()
		{
			InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
			instance.OnInputBehaviorChanged = (Action<InputBroker.InputBehavior>)Delegate.Combine(instance.OnInputBehaviorChanged, new Action<InputBroker.InputBehavior>(OnInputBehaviourChanged));
		}

		private void OnDisable()
		{
			InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
			instance.OnInputBehaviorChanged = (Action<InputBroker.InputBehavior>)Delegate.Remove(instance.OnInputBehaviorChanged, new Action<InputBroker.InputBehavior>(OnInputBehaviourChanged));
		}

		private void OnInputBehaviourChanged(InputBroker.InputBehavior behavior)
		{
			if (stashIsOpen)
			{
				sortButtonGO.gameObject.SetActive(behavior == InputBroker.InputBehavior.ClickToMove);
			}
		}

		public void SetupShop(Character shopOwner)
		{
			UpdateName("Shop");
			stashIsOpen = false;
			shopGrid.InitGrid(shopOwner);
			shopGrid.FillGrid(shopOwner.inventory, dropItemsThatDontFit: false);
			sortButtonGO.gameObject.SetActive(value: false);
		}

		public void SetupStash(List<Item> items)
		{
			UpdateName("Inventory_StorageTrunk");
			stashIsOpen = true;
			stash = UnityEngine.Object.FindFirstObjectByType<Stash>();
			shopGrid.InitGrid(null, stash);
			shopGrid.FillGrid(items, dropItemsThatDontFit: true);
			if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove)
			{
				sortButtonGO.gameObject.SetActive(value: true);
			}
		}

		private void UpdateName(string newName)
		{
			if (!(headerText == null))
			{
				string text = I2Loca.Get(newName);
				if (text == "")
				{
					headerText.text = newName;
				}
				headerText.text = text;
			}
		}
	}
