		private void OnDisable()
		{
			if (chosenItem != null && chosenItem.currentItem != null && chosenItem.currentItem.slotIndex == enchantSlot.globalIndex)
			{
				chosenItem.RevertDisabledSlot();
			}
			enchantSlot.TrySetItem(null);
			chosenItem = null;
			for (int i = 0; i < chosenTarotItems.Length; i++)
			{
				ItemUI itemUI = chosenTarotItems[i];
				EnchantSlotUI enchantSlotUI = tarotCardSlots[i];
				if (itemUI != null && itemUI.currentItem.slotIndex == enchantSlotUI.globalIndex)
				{
					itemUI.RevertDisabledSlot();
				}
			}
			chosenTarotItems = new ItemUI[3];
			EnchantSlotUI[] array = tarotCardSlots;
			for (int j = 0; j < array.Length; j++)
			{
				array[j].TrySetItem(null);
			}
			enchantSlot.questItemLock = null;
		}

		private void Awake()
		{
			EnchantSlotUI enchantSlotUI = enchantSlot;
			enchantSlotUI.onSlotEquipped = (Action<ItemUI, int>)Delegate.Combine(enchantSlotUI.onSlotEquipped, new Action<ItemUI, int>(OnSlotEquipped));
			EnchantSlotUI[] array = tarotCardSlots;
			foreach (EnchantSlotUI obj in array)
			{
				obj.onSlotEquipped = (Action<ItemUI, int>)Delegate.Combine(obj.onSlotEquipped, new Action<ItemUI, int>(OnSlotEquipped));
			}
			positiveButton.onClick.AddListener(OnPositiveButton);
			negativeButton.onClick.AddListener(OnNegativeButton);
		}

		private void OnDestroy()
		{
			EnchantSlotUI enchantSlotUI = enchantSlot;
			enchantSlotUI.onSlotEquipped = (Action<ItemUI, int>)Delegate.Remove(enchantSlotUI.onSlotEquipped, new Action<ItemUI, int>(OnSlotEquipped));
			EnchantSlotUI[] array = tarotCardSlots;
			foreach (EnchantSlotUI obj in array)
			{
				obj.onSlotEquipped = (Action<ItemUI, int>)Delegate.Remove(obj.onSlotEquipped, new Action<ItemUI, int>(OnSlotEquipped));
			}
		}

		private void OnPositiveButton()
		{
			switch (selectionType)
			{
			case SelectionType.Retire:
			{
				UnityEngine.Debug.Log("Retire with item: " + chosenItem.currentItem.ItemDisplayName);
				ItemCategory category = chosenItem.currentItem.category;
				if (category == ItemCategory.Weapon || category == ItemCategory.Armor || category == ItemCategory.Jewelry)
				{
					if (chosenItem.currentItem.effects != null)
					{
						foreach (KeyValuePair<ActivationType, List<EffectData>> effect in chosenItem.currentItem.effects)
						{
							if (effect.Value != null)
							{
								for (int i = 0; i < effect.Value.Count; i++)
								{
									effect.Value[i].value += Mathf.CeilToInt((float)effect.Value[i].value * 0.25f);
								}
							}
						}
					}
					if (chosenItem.currentItem.damageBonuses != null)
					{
						for (int j = 0; j < chosenItem.currentItem.damageBonuses.Count; j++)
						{
							chosenItem.currentItem.damageBonuses[j].value += Mathf.CeilToInt((float)chosenItem.currentItem.damageBonuses[j].value * 0.25f);
						}
					}
				}
				category = chosenItem.currentItem.category;
				if ((category == ItemCategory.Weapon || category == ItemCategory.Armor) && chosenItem.currentItem.grade < ItemGrade.Flawless)
				{
					chosenItem.currentItem.grade++;
				}
				SingletonBehaviour<PlayerStatus>.Instance.HeirloomItem = chosenItem.currentItem;
				SingletonBehaviour<PlayerStatus>.Instance.IsHandlingRetirement = true;
				SimpleSingletonBehaviour<PlayerUI>.Instance.CloseTabs();
				SingletonBehaviour<InputBroker>.Instance.DisableAllInput();
				SceneLoad.LoadMainMenuCurrentGame(saveFirst: false, delegate
				{
					SingletonBehaviour<InputBroker>.Instance.EnableAllInput();
				});
				break;
			}
			case SelectionType.TkalaAnvil:
			{
				if (!Player.PlayerChar.HasItems(endHammerItemData.displayName, 1) || !(chosenItem != null) || chosenItem.currentItem == null || chosenItem.currentItem.itemType != ItemType.EndUrn)
				{
					break;
				}
				Quest realmQuest = SingletonBehaviour<QuestManager>.Instance.GetRealmQuest(RealmData.RealmId.HauntedPalace);
				if (realmQuest != null && realmQuest.QuestType == QuestData.QuestType.RealmBoss && realmQuest.Status != Quest.QuestStatus.InProgress)
				{
					Player.PlayerChar.RemoveItemFromInventory(chosenItem.currentItem, RemoveItemReason.Consumed);
					chosenItem.ForceClearCurrentSlots();
					chosenItem.gameObject.SetActive(value: false);
					chosenItem = null;
					enchantSlot.TrySetItem(null);
					Item item2 = Player.PlayerChar.inventory.Find((Item item) => item.itemType == ItemType.EndHammer);
					if (item2 != null)
					{
						Player.PlayerChar.RemoveItemFromInventory(item2, RemoveItemReason.Consumed);
					}
					else
					{
						UnityEngine.Debug.LogError("Could not find 'hammer of the gods' in player inventory when attempting to remove it");
					}
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.UrnBreaking, randomizePitch: true);
					SingletonBehaviour<QuestManager>.Instance.OnUrnOfTkalaDestroyed();
					SimpleSingletonBehaviour<PlayerUI>.Instance.CloseTabs();
				}
				break;
			}
			default:
				switch (activeMerchantType)
				{
				case MerchantType.BreakGems:
					OnBreakGemsClick();
					break;
				case MerchantType.BreakWeapons:
					OnBreakWeaponsClick();
					break;
				case MerchantType.Enchanter:
					OnEnchantClick();
					break;
				case MerchantType.MagicAnvil:
					used = true;
					OnMagicAnvilEnchant();
					break;
				case MerchantType.Tarot:
					used = true;
					OnTarotTransform();
					break;
				}
				positiveButton.interactable = SingletonBehaviour<PlayerStatus>.Instance.gold >= goldCost;
				if (used)
				{
					positiveButton.interactable = false;
				}
				onUsed?.Invoke();
				break;
			}
		}

		private void OnNegativeButton()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
			OnCancel();
		}

		private void OnBreakWeaponsClick()
		{
			if (chosenItem == null)
			{
				return;
			}
			if (chosenItem.currentItem.sockedtedItems == null || chosenItem.currentItem.sockedtedItems.Count == 0)
			{
				descriptionText.text = I2Loca.GetReplaceTags("Error_NoGems");
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
				return;
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine(I2Loca.GetFormatReplaceTags("BreakWeapons_Success", I2Loca.Get(chosenItem.currentItem.itemName)));
			string text = "";
			for (int i = 0; i < chosenItem.currentItem.sockedtedItems.Count; i++)
			{
				Item item = chosenItem.currentItem.sockedtedItems[i];
				Player.PlayerChar.AddItemToInventory(chosenItem.currentItem.sockedtedItems[i], AddItemReason.Loot);
				SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.playerInventory.grid.AddItem(item);
				if (i != 0)
				{
					text += ", ";
				}
				text = text + "<style=C1>" + I2Loca.Get(chosenItem.currentItem.sockedtedItems[i].itemName) + "</style>";
			}
			stringBuilder.AppendLine(text);
			Player.PlayerChar.RemoveItemFromInventory(chosenItem.currentItem, RemoveItemReason.Consumed);
			chosenItem.ForceClearCurrentSlots();
			chosenItem.gameObject.SetActive(value: false);
			chosenItem = null;
			enchantSlot.TrySetItem(null);
			descriptionText.text = stringBuilder.ToString();
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnBreakGemsClick()
		{
			if (!(chosenItem == null))
			{
				if (chosenItem.currentItem.sockedtedItems == null || chosenItem.currentItem.sockedtedItems.Count == 0)
				{
					descriptionText.text = I2Loca.GetReplaceTags("Error_NoGems");
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
					return;
				}
				chosenItem.currentItem.RemoveContainedEffects();
				chosenItem.currentItem.sockedtedItems = new List<Item>();
				chosenItem.UpdateSockets();
				enchantSlot.TrySetItem(null);
				descriptionText.text = I2Loca.GetReplaceTags("BreakGems_Success");
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				chosenItem.RevertSlot();
				chosenItem = null;
			}
		}

		private void OnEnchantClick()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			bool flag = true;
			if (!(chosenItem != null))
			{
				return;
			}
			SingletonBehaviour<PlayerStatus>.Instance.RemoveGold(goldCost);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.CoinPickup, randomizePitch: true);
			chosenItem.RevertSlot();
			enchantSlot.TrySetItem(null);
			if (chosenItem.currentItem.isUnique)
			{
				int num = UnityEngine.Random.Range(0, 1000);
				if (chosenItem.currentItem.sockets < chosenItem.currentItem.slotsTall && num < 200)
				{
					BestowSockets("Enchant_Socket");
				}
				else
				{
					num = UnityEngine.Random.Range(0, 1000);
					if (num < 500)
					{
						flag = TryBestowPowers("Enchant_ExtraEnchant", "Enchant_NoResult");
					}
					else
					{
						flag = false;
						num = UnityEngine.Random.Range(0, 1000);
						if (num < 60)
						{
							chosenItem.currentItem.RemovePowers();
							descriptionText.text = I2Loca.GetFormatReplaceTags("Enchant_RemovePowers", chosenItem.currentItem.ItemDisplayName);
						}
						else
						{
							descriptionText.text = I2Loca.GetFormatReplaceTags("Enchant_NoResult", chosenItem.currentItem.ItemDisplayName);
						}
					}
				}
			}
			else
			{
				int num = UnityEngine.Random.Range(0, 1000);
				if (chosenItem.currentItem.sockets < chosenItem.currentItem.slotsTall && num < 200)
				{
					BestowSockets("Enchant_Socket");
				}
				else
				{
					num = UnityEngine.Random.Range(0, 1000);
					if (num < 500)
					{
						flag = TryBestowPowers("Enchant_ExtraEnchant", "Enchant_NoResult");
					}
					else
					{
						num = UnityEngine.Random.Range(0, 1000);
						if (num < 250)
						{
							BestowUniquePowers("Enchant_Unique");
						}
						else
						{
							flag = false;
							num = UnityEngine.Random.Range(0, 1000);
							if (num <= 60)
							{
								chosenItem.currentItem.RemovePowers();
								descriptionText.text = I2Loca.GetFormatReplaceTags("Enchant_RemovePowers", chosenItem.currentItem.ItemDisplayName);
							}
							else
							{
								descriptionText.text = I2Loca.GetFormatReplaceTags("Enchant_NoResult", chosenItem.currentItem.ItemDisplayName);
							}
						}
					}
				}
			}
			chosenItem = null;
			if (flag)
			{
				StatsManager.IncrementStat(Stat.Enchants);
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_fategood);
			}
		}

		private void OnMagicAnvilEnchant()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			if (chosenItem != null)
			{
				chosenItem.RevertSlot();
				enchantSlot.TrySetItem(null);
				bool flag;
				if (chosenItem.currentItem.category != ItemCategory.Weapon && chosenItem.currentItem.category != ItemCategory.Armor && chosenItem.currentItem.category != ItemCategory.Jewelry)
				{
					descriptionText.text = I2Loca.GetFormatReplaceTags("MagicAnvil_NoResult", chosenItem.currentItem.ItemDisplayName);
					flag = false;
				}
				else if (chosenItem.currentItem.sockets < chosenItem.currentItem.slotsTall && UnityEngine.Random.Range(0, 100) < 20)
				{
					BestowSockets("MagicAnvil_Socket");
					flag = true;
				}
				else if (!chosenItem.currentItem.isArtifact && UnityEngine.Random.Range(0, 100) < 50)
				{
					flag = TryBestowPowers("MagicAnvil_ExtraEnchant", "MagicAnvil_NoResult");
				}
				else if (!chosenItem.currentItem.isUnique && UnityEngine.Random.Range(0, 100) < 25)
				{
					BestowUniquePowers("MagicAnvil_Unique");
					flag = true;
				}
				else if (UnityEngine.Random.Range(0, 100) < 6 && chosenItem.currentItem.effects != null && chosenItem.currentItem.effects.ContainsKey(ActivationType.Passive))
				{
					chosenItem.currentItem.RemovePowers();
					descriptionText.text = I2Loca.GetFormatReplaceTags("MagicAnvil_RemovePowers", chosenItem.currentItem.ItemDisplayName);
					flag = false;
				}
				else
				{
					descriptionText.text = I2Loca.GetFormatReplaceTags("MagicAnvil_NoResult", chosenItem.currentItem.ItemDisplayName);
					flag = false;
				}
				if (flag)
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_fategood);
				}
				StatsManager.IncrementStat(Stat.MagicAnvilUses);
				chosenItem = null;
			}
		}

		private void OnTarotTransform()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			int num = 0;
			ItemUI[] array = chosenTarotItems;
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i] != null)
				{
					num++;
				}
			}
			if (num >= 3)
			{
				if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free)
				{
					SingletonBehaviour<CursorManager>.Instance.SetVirtualCursorActive(state: false);
				}
				Fate.FateVer currentFateVer = Fate.CurrentFateVer;
				if (currentFateVer == Fate.FateVer.TraitorSoul || currentFateVer == Fate.FateVer.UndiscoveredRealms)
				{
					PerformTarotTransformFate2or3();
				}
				else if (Fate.CurrentFateVer == Fate.FateVer.CursedKing)
				{
					PerformTarotTransformFate4();
				}
				SimpleSingletonBehaviour<PlayerUI>.Instance.CloseTabs();
			}
		}

		private void PerformTarotTransformFate2or3()
		{
			int num = 0;
			float num2 = 1f;
			for (int i = 0; i < 3; i++)
			{
				num += chosenTarotItems[i].currentItem.value;
				for (int j = i; j < 3; j++)
				{
					if (i != j && chosenTarotItems[i].currentItem.itemName == chosenTarotItems[j].currentItem.itemName)
					{
						num2 += 1f;
					}
				}
			}
			int num3 = (int)Mathf.Ceil((float)num * num2);
			if (num3 < 5000)
			{
				ActiveLevel.SpawnGoldPile(Player.PlayerChar.myTransform.position, num3);
			}
			else if (num3 < 10000)
			{
				GiveTarotItemReward(TarotItemRewardType.Gem);
			}
			else
			{
				GiveTarotItemReward(TarotItemRewardType.RareGem);
			}
			if (num3 > 12500)
			{
				GiveTarotItemReward(TarotItemRewardType.Jewelry);
			}
			DestroyChosenTarotCards();
			SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton(I2Loca.Get("TarotTransform"), delegate
			{
				SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Game);
			}, I2Loca.Get("OK"));
		}

		private void GiveTarotItemReward(TarotItemRewardType rewardType)
		{
			Randomizer randomizer = new Randomizer();
			List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
			for (int i = 0; i < allItems.Count; i++)
			{
				ItemData itemData = allItems[i];
				if (!itemData.takeable || itemData.reserved)
				{
					continue;
				}
				int num = 1000 - itemData.rarity;
				if (num <= 0)
				{
					continue;
				}
				switch (rewardType)
				{
				case TarotItemRewardType.Gem:
					if (itemData.itemType == ItemType.Gem)
					{
						randomizer.AddChoice(i, num);
					}
					break;
				case TarotItemRewardType.RareGem:
					if (itemData.itemType == ItemType.Gem && (itemData.minimumDepth > 3 || num < 99))
					{
						randomizer.AddChoice(i, num);
					}
					break;
				case TarotItemRewardType.Jewelry:
				{
					ItemType itemType = itemData.itemType;
					if (itemType == ItemType.Ring || itemType == ItemType.Earring || itemType == ItemType.Necklace)
					{
						randomizer.AddChoice(i, num);
					}
					break;
				}
				}
			}
			int random = randomizer.GetRandom();
			if (random == -1)
			{
				UnityEngine.Debug.LogError($"Found no suitable item as a tarot reward, reward type {rewardType}");
			}
			Item item = new Item(allItems[random]);
			if (!Player.PlayerChar.AddItemToInventory(item, AddItemReason.Loot))
			{
				item.Drop(Player.PlayerChar.myTransform.position);
			}
		}

		private void PerformTarotTransformFate4()
		{
			int num = 0;
			float num2 = 1f;
			HashSet<TarotFlavor> hashSet = new HashSet<TarotFlavor>();
			HashSet<int> hashSet2 = new HashSet<int>();
			ItemUI[] array = chosenTarotItems;
			foreach (ItemUI itemUI in array)
			{
				num += itemUI.currentItem.tarotLevel;
				hashSet2.Add(itemUI.currentItem.tarotLevel);
				hashSet.Add(itemUI.currentItem.tarotFlavor);
			}
			bool flag = hashSet.Count == 1;
			bool flag2 = hashSet.Count == 3;
			bool flag3 = hashSet2.Count == 1;
			bool flag4 = hashSet2.Count == 2;
			if (flag)
			{
				num2 *= 1.5f;
			}
			else if (flag2)
			{
				num2 *= 1.25f;
			}
			if (flag3)
			{
				num2 *= 1.5f;
			}
			else if (flag4)
			{
				num2 *= 1.2f;
			}
			float num3 = num2 * (float)num;
			int num4 = Mathf.FloorToInt(num3 / 5f);
			int num5 = Mathf.FloorToInt(num3 / 10f);
			if (num3 >= 30f)
			{
				num4 += 2;
				num5++;
			}
			else if (Mathf.Approximately(num3, 1.5f))
			{
				num4 += 4;
				num5 += 2;
			}
			else if (Mathf.Approximately(num3, 21f))
			{
				num4 += 4;
				num5 += 2;
			}
			if (flag2 && flag3)
			{
				num4 += 4;
				num5 += 2;
			}
			num4 = Mathf.Max(num4, 1);
			num5 = Mathf.Max(num5, 1);
			Player.PlayerChar.AddUnusedStatPoints(num4);
			Player.PlayerChar.AddUnusedSkillPoints(num5);
			DestroyChosenTarotCards();
			SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton(I2Loca.Get("TarotTransform"), delegate
			{
				SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Game);
			}, I2Loca.Get("OK"));
		}

		private void DestroyChosenTarotCards()
		{
			ItemUI[] array = chosenTarotItems;
			foreach (ItemUI itemUI in array)
			{
				if (!(itemUI == null))
				{
					Player.PlayerChar.RemoveItemFromInventory(itemUI.currentItem, RemoveItemReason.Consumed);
					itemUI.gameObject.SetActive(value: false);
				}
			}
			chosenTarotItems = new ItemUI[3];
			EnchantSlotUI[] array2 = tarotCardSlots;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].TrySetItem(null);
			}
		}

		private void BestowSockets(string formatKey)
		{
			chosenItem.currentItem.BestowSockets(AllowUnique: true);
			chosenItem.currentItem.SetIdentified(newValue: true);
			descriptionText.text = I2Loca.GetFormatReplaceTags(formatKey, chosenItem.currentItem.ItemDisplayName);
			chosenItem.UpdateSockets();
		}

		private bool TryBestowPowers(string successKey, string failKey)
		{
			int num = Mathf.CeilToInt((float)Player.PlayerChar.Level * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].difficultyMultiplier);
			num += Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].levelBase;
			bool flag = chosenItem.currentItem.TryBestowPowers(num, AllowCurse: true);
			chosenItem.currentItem.SetIdentified(newValue: true);
			if (flag)
			{
				descriptionText.text = I2Loca.GetFormatReplaceTags(successKey, chosenItem.currentItem.ItemDisplayName);
			}
			else
			{
				descriptionText.text = I2Loca.GetFormatReplaceTags(failKey, chosenItem.currentItem.ItemDisplayName);
			}
			return flag;
		}

		private void BestowUniquePowers(string formatKey)
		{
			int num = Mathf.CeilToInt((float)Player.PlayerChar.Level * Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].difficultyMultiplier);
			num += Fate.DifficultyMod[SingletonBehaviour<PlayerStatus>.Instance.Difficulty].levelBase;
			chosenItem.currentItem.BestowUniquePowers(num, AllowCurse: true);
			chosenItem.currentItem.SetIdentified(newValue: true);
			descriptionText.text = I2Loca.GetFormatReplaceTags(formatKey, chosenItem.currentItem.ItemDisplayName);
		}

		private void OnCancel()
		{
			if (chosenItem != null)
			{
				chosenItem.RevertSlot();
				enchantSlot.TrySetItem(null);
				chosenItem = null;
			}
			ItemUI[] array = chosenTarotItems;
			foreach (ItemUI itemUI in array)
			{
				if (itemUI != null)
				{
					itemUI.RevertSlot();
				}
			}
			chosenTarotItems = new ItemUI[3];
			EnchantSlotUI[] array2 = tarotCardSlots;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].TrySetItem(null);
			}
			enchantSlot.questItemLock = null;
			onCancel?.Invoke();
			SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.SetLeftSideStats();
		}

		private void OnSlotEquipped(ItemUI item, int slotIndex)
		{
			if (activeMerchantType == MerchantType.Tarot)
			{
				if (chosenTarotItems[slotIndex] == item)
				{
					return;
				}
				chosenTarotItems[slotIndex] = item;
				int num = 0;
				ItemUI[] array = chosenTarotItems;
				for (int i = 0; i < array.Length; i++)
				{
					if (array[i] != null)
					{
						num++;
					}
				}
				positiveButton.interactable = num == 3;
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
				return;
			}
			if (selectionType == SelectionType.TkalaAnvil)
			{
				if (Player.PlayerChar.HasItems(endHammerItemData.displayName, 1))
				{
					positiveButton.interactable = true;
				}
				else
				{
					positiveButton.interactable = false;
					errorText.text = I2Loca.GetFormatReplaceTags("GenericNeed", I2Loca.Get(endHammerItemData.displayName));
				}
				chosenItem = item;
				return;
			}
			chosenItem = ((item == null) ? chosenItem : item);
			if (item == null)
			{
				positiveButton.interactable = false;
				errorText.text = "";
				if (activeMerchantType == MerchantType.Enchanter)
				{
					descriptionText.text = I2Loca.GetMultiLineReplaceTags("EnchantGuide");
				}
				else if (activeMerchantType == MerchantType.MagicAnvil)
				{
					descriptionText.text = I2Loca.GetMultiLineReplaceTags("MagicAnvil_Guide");
				}
			}
			else if (activeMerchantType == MerchantType.Enchanter)
			{
				goldCost = item.currentItem.EnchantValue();
				descriptionText.text = I2Loca.GetMultiLineReplaceTags("EnchantGuide") + "\n" + I2Loca.GetMultiLineReplaceTagsFormat("EnchantCost", goldCost.ToString());
				List<EffectData> value;
				bool flag = chosenItem.currentItem.effects != null && chosenItem.currentItem.effects.TryGetValue(ActivationType.Passive, out value) && value.Count >= 25;
				bool flag2 = !item.currentItem.IsHeroItem() && SingletonBehaviour<PlayerStatus>.Instance.CanAfford(goldCost) && !flag;
				positiveButton.interactable = flag2;
				if (flag2)
				{
					errorText.text = "";
				}
				else if (item.currentItem.IsHeroItem())
				{
					errorText.text = I2Loca.Get("ProbablyShouldNotDoThat");
				}
				else if (flag)
				{
					errorText.text = I2Loca.GetFormatReplaceTags("EnchantItemTooPowerful", item.currentItem.ItemDisplayName);
				}
				else if (!SingletonBehaviour<PlayerStatus>.Instance.CanAfford(goldCost))
				{
					errorText.text = I2Loca.GetReplaceTags("ErrorMsg_NotEnoughGold");
				}
				else
				{
					UnityEngine.Debug.LogWarning("Cannot echant item but no error text to display");
					errorText.text = "";
				}
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
			}
			else if (activeMerchantType == MerchantType.MagicAnvil)
			{
				descriptionText.text = I2Loca.GetMultiLineReplaceTags("MagicAnvil_Guide");
				bool flag3 = !used && !item.currentItem.IsHeroItem();
				positiveButton.interactable = flag3;
				errorText.text = (flag3 ? "" : (item.currentItem.IsHeroItem() ? I2Loca.Get("ProbablyShouldNotDoThat") : I2Loca.GetReplaceTags("ErrorMsg_AlreadyUsed")));
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
			}
			else if (activeMerchantType == MerchantType.BreakGems || activeMerchantType == MerchantType.BreakWeapons)
			{
				positiveButton.interactable = chosenItem.currentItem.sockedtedItems != null && chosenItem.currentItem.sockedtedItems.Count > 0;
				errorText.text = (positiveButton.interactable ? "" : I2Loca.GetReplaceTags("Error_NoGems"));
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ItemMoveBreakOrEnchanterSlot, randomizePitch: true);
			}
			else if (selectionType == SelectionType.Retire)
			{
				positiveButton.interactable = true;
			}
		}
	}
