	public class MinimapFogGridUI : SingletonBehaviour<MinimapFogGridUI>
	{
		private List<bool> visibility;

		private Mesh mesh;

		private int sizeX;

		private int sizeY;

		private bool removeFog;

		private IEnumerator Start()
		{
			SaveData.AddPreSaveMainThreadTask(FlushFogSave);
			yield return new WaitForRealSeconds(0.2f);
			Generate();
			if (LevelGenerator.currentInstance != null)
			{
				LevelGenerator currentInstance = LevelGenerator.currentInstance;
				currentInstance.finishedCreation = (Action)Delegate.Combine(currentInstance.finishedCreation, new Action(Generate));
				LevelGenerator currentInstance2 = LevelGenerator.currentInstance;
				currentInstance2.discoverAll = (Action)Delegate.Combine(currentInstance2.discoverAll, new Action(DiscoverAll));
			}
		}

		private void OnDestroy()
		{
			SaveData.RemovePreSaveMainThreadTask(FlushFogSave);
			if (LevelGenerator.currentInstance != null)
			{
				LevelGenerator currentInstance = LevelGenerator.currentInstance;
				currentInstance.finishedCreation = (Action)Delegate.Remove(currentInstance.finishedCreation, new Action(Generate));
				LevelGenerator currentInstance2 = LevelGenerator.currentInstance;
				currentInstance2.discoverAll = (Action)Delegate.Remove(currentInstance2.discoverAll, new Action(DiscoverAll));
			}
			CleanupExistingMesh();
		}

		private void CleanupExistingMesh()
		{
			if (mesh != null)
			{
				UnityEngine.Object.Destroy(mesh);
				mesh = null;
			}
		}

		private void Update()
		{
			if (visibility == null || LevelGenerator.currentInstance == null || removeFog || !(mesh != null) || !(Player.PlayerChar != null))
			{
				return;
			}
			MazeCreation maze = LevelGenerator.currentInstance.GetMaze();
			if (maze == null)
			{
				return;
			}
			Vector2Int cellIndexFromPosition = maze.GetCellIndexFromPosition((int)Player.PlayerChar.myTransform.position.x, (int)Player.PlayerChar.myTransform.position.z);
			int num = cellIndexFromPosition.x + cellIndexFromPosition.y * sizeX;
			List<int> list = new List<int>();
			for (int i = cellIndexFromPosition.y - 2; i < cellIndexFromPosition.y + 3; i++)
			{
				for (int j = cellIndexFromPosition.x - 2; j < cellIndexFromPosition.x + 3; j++)
				{
					num = j + i * sizeX;
					if (num < visibility.Count && num >= 0 && !visibility[num])
					{
						list.Add(num);
					}
				}
			}
			if (!list.IsEmpty())
			{
				UpdateFogMesh(list);
			}
		}

		private void UpdateFogMesh(List<int> indexes)
		{
			if (!(mesh != null))
			{
				return;
			}
			foreach (int index in indexes)
			{
				visibility[index] = true;
			}
			int[] array = new int[sizeX * sizeY * 6];
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			while (num3 < sizeY)
			{
				int num4 = 0;
				while (num4 < sizeX)
				{
					if (!visibility[num4 + num3 * sizeX])
					{
						array[num] = num2;
						array[num + 3] = (array[num + 2] = num2 + 1);
						array[num + 4] = (array[num + 1] = num2 + sizeX + 1);
						array[num + 5] = num2 + sizeX + 2;
					}
					num4++;
					num += 6;
					num2++;
				}
				num3++;
				num2++;
			}
			mesh.triangles = array;
			mesh.RecalculateNormals();
		}

		private void Generate()
		{
			if (LevelGenerator.currentInstance == null)
			{
				return;
			}
			MazeCreation maze = LevelGenerator.currentInstance.GetMaze();
			if (maze == null)
			{
				return;
			}
			removeFog = false;
			CleanupExistingMesh();
			GetComponent<MeshFilter>().mesh = (mesh = new Mesh());
			mesh.name = "Procedural Fog Grid";
			sizeX = maze.GetMazeWidth();
			sizeY = maze.GetMazeHeight();
			Vector3[] array = new Vector3[(sizeX + 1) * (sizeY + 1)];
			Vector2[] array2 = new Vector2[array.Length];
			Vector4[] array3 = new Vector4[array.Length];
			Vector4 vector = new Vector4(1f, 0f, 0f, -1f);
			visibility = new List<bool>((sizeX + 1) * (sizeY + 1));
			int num = 0;
			for (int i = 0; i <= sizeY; i++)
			{
				int num2 = 0;
				while (num2 <= sizeX)
				{
					array[num] = maze.GetPositionFromCellPosition(num2, i);
					array2[num] = new Vector2((float)num2 / (float)sizeX, (float)i / (float)sizeY);
					array3[num] = vector;
					visibility.Add(item: false);
					num2++;
					num++;
				}
			}
			mesh.vertices = array;
			mesh.uv = array2;
			mesh.tangents = array3;
			if (SaveData.CurrentSaveData != null)
			{
				RealmSave realmSave = SaveData.CurrentSaveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
				int levelDepth = LevelGenerator.currentInstance.GetLevelDepth();
				DungeonSaveData dungeonSave = realmSave.GetDungeonSave(levelDepth);
				if (dungeonSave != null && dungeonSave.fogSaves != null)
				{
					foreach (FogSaveData fogSafe in dungeonSave.fogSaves)
					{
						if (fogSafe.cellIndex == -1 || fogSafe.cellIndex >= visibility.Count)
						{
							removeFog = true;
							CleanupExistingMesh();
							mesh = new Mesh();
							mesh.name = "Removed Fog";
							return;
						}
						visibility[fogSafe.cellIndex] = true;
					}
				}
			}
			int[] array4 = new int[sizeX * sizeY * 6];
			int num3 = 0;
			int num4 = 0;
			int num5 = 0;
			while (num5 < sizeY)
			{
				int num6 = 0;
				while (num6 < sizeX)
				{
					if (!visibility[num6 + num5 * sizeX])
					{
						array4[num3] = num4;
						array4[num3 + 3] = (array4[num3 + 2] = num4 + 1);
						array4[num3 + 4] = (array4[num3 + 1] = num4 + sizeX + 1);
						array4[num3 + 5] = num4 + sizeX + 2;
					}
					num6++;
					num3 += 6;
					num4++;
				}
				num5++;
				num4++;
			}
			mesh.triangles = array4;
			mesh.RecalculateNormals();
		}

		public void DiscoverAll()
		{
			removeFog = true;
			CleanupExistingMesh();
			GetComponent<MeshFilter>().mesh = (mesh = new Mesh());
			mesh.name = "Removed Fog";
			mesh.RecalculateNormals();
		}

		public void ManualSave()
		{
			FlushFogSave(SaveData.CurrentSaveData);
		}

		private void FlushFogSave(FateSaveData saveData)
		{
			if (SaveData.CurrentSaveSlot.saveState != 0 || saveData == null)
			{
				return;
			}
			RealmSave realmSave = saveData.GetRealmSave(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
			if (realmSave == null)
			{
				return;
			}
			int levelDepth = LevelGenerator.currentInstance.GetLevelDepth();
			DungeonSaveData dungeonSave = realmSave.GetDungeonSave(levelDepth);
			if (dungeonSave == null)
			{
				return;
			}
			dungeonSave.fogSaves = new List<FogSaveData>();
			List<FogSaveData> fogSaves = dungeonSave.fogSaves;
			if (removeFog)
			{
				fogSaves.Add(new FogSaveData
				{
					cellIndex = -1
				});
			}
			else
			{
				if (visibility == null)
				{
					return;
				}
				for (int i = 0; i < visibility.Count; i++)
				{
					if (visibility[i])
					{
						fogSaves.Add(new FogSaveData
						{
							cellIndex = i
						});
					}
				}
			}
		}
	}
	public class MiniMapIconUI : MonoBehaviour
	{
		public bool isCamera;

		public bool fixedRotation = true;

		private const float zoomPercentageOne = 1.5f;

		private const float zoomPercentageTwo = 2.5f;

		private const float zoomPercentageThree = 3.5f;

		private Camera ortographicCamera;

		private float savedSize;

		private Quaternion savedRotation;

		private Vector3 savedScale;

		private void Awake()
		{
			if (isCamera)
			{
				ortographicCamera = base.gameObject.GetComponent<Camera>();
				savedSize = ortographicCamera.orthographicSize;
			}
			savedRotation = base.transform.rotation;
			savedScale = (base.transform.localScale /= base.transform.parent.localScale.x);
			if (!isCamera)
			{
				savedRotation = Quaternion.Euler(115f, Camera.main.transform.eulerAngles.y, 0f);
			}
		}

		private void Start()
		{
			OnMapZoomLevelChanged(SimpleSingletonBehaviour<PlayerUI>.Instance.GetMinimapZoomLevel);
			PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
			instance.OnMinimapZoomLevelChanged = (Action<int>)Delegate.Combine(instance.OnMinimapZoomLevelChanged, new Action<int>(OnMapZoomLevelChanged));
		}

		private void OnDestroy()
		{
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				PlayerUI instance = SimpleSingletonBehaviour<PlayerUI>.Instance;
				instance.OnMinimapZoomLevelChanged = (Action<int>)Delegate.Remove(instance.OnMinimapZoomLevelChanged, new Action<int>(OnMapZoomLevelChanged));
			}
		}

		private void LateUpdate()
		{
			if (fixedRotation)
			{
				base.transform.rotation = savedRotation;
			}
		}

		private void OnMapZoomLevelChanged(int amount)
		{
			if (isCamera)
			{
				switch (amount)
				{
				case 0:
					ortographicCamera.orthographicSize = savedSize;
					break;
				case 1:
					ortographicCamera.orthographicSize = savedSize * 1.5f;
					break;
				case 2:
					ortographicCamera.orthographicSize = savedSize * 2.5f;
					break;
				case 3:
					ortographicCamera.orthographicSize = savedSize * 3.5f;
					break;
				case 4:
					break;
				}
			}
			else
			{
				switch (amount)
				{
				case 0:
					base.transform.localScale = savedScale;
					break;
				case 1:
					base.transform.localScale = savedScale * 1.5f;
					break;
				case 2:
					base.transform.localScale = savedScale * 2.5f;
					break;
				case 3:
					base.transform.localScale = savedScale * 3.5f;
					break;
				case 4:
					break;
				}
			}
		}
	}
	public class OptionsTabs : MonoBehaviour
	{
		public enum TabType
		{
			Controller = 0,
			Journal = 1,
			Options = 2,
			None = -1
		}

		[Serializable]
		public struct Tab
		{
			public TabType tabType;

			public Button tabButton;

			public TextMeshProUGUI tabText;

			public string tabLocaKey;

			public GameObject tabScreen;
		}

		[SerializeField]
		private Tab[] tabs;

		[SerializeField]
		private Color textColorActiveTab;

		private Color textColorDefaultTab;

		private TabType currentTab = TabType.None;

		public TabType CurrentTab => currentTab;

		public void Init()
		{
			textColorDefaultTab = tabs[0].tabText.color;
			SetTab(TabType.None);
			for (int i = 0; i < tabs.Length; i++)
			{
				int index = i;
				tabs[index].tabButton.onClick.AddListener(delegate
				{
					SetTab(tabs[index].tabType);
				});
			}
		}

		private void SetTextSelected(TextMeshProUGUI text, string baseText, bool selected)
		{
			if (selected)
			{
				text.color = textColorActiveTab;
				text.text = "<size=25>" + baseText;
			}
			else
			{
				text.color = textColorDefaultTab;
				text.text = baseText;
			}
		}

		public void SetTab(TabType tabType)
		{
			for (int i = 0; i < tabs.Length; i++)
			{
				Tab tab = tabs[i];
				tab.tabScreen.SetActive(tab.tabType == tabType);
				SetTextSelected(tab.tabText, I2Loca.Get(tab.tabLocaKey), tab.tabType == tabType);
			}
			currentTab = tabType;
			base.gameObject.SetActive(tabType != TabType.None);
		}

		public void NextTab()
		{
			switch (currentTab)
			{
			case TabType.Controller:
				SetTab(TabType.Journal);
				break;
			case TabType.Journal:
				SetTab(TabType.Options);
				break;
			case TabType.Options:
				SetTab(TabType.Controller);
				break;
			}
		}

		public void PreviousTab()
		{
			switch (currentTab)
			{
			case TabType.Controller:
				SetTab(TabType.Options);
				break;
			case TabType.Journal:
				SetTab(TabType.Controller);
				break;
			case TabType.Options:
				SetTab(TabType.Journal);
				break;
			}
		}
	}
	public class PartyCharacterInScreenUI : MonoBehaviour
	{
		[SerializeField]
		private RawImage profilePictureImage;

		public Button button;

		public TextMeshProUGUI nameText;

		public Image hpMeter;

		public Image manaMeter;

		public Sprite hpRedSprite;

		public Sprite hpGreenSprite;

		public GameObject[] toggledOnSelect;

		public Action<Character> onClicked;

		public Character CurrentCharacter { get; private set; }

		private void Awake()
		{
			button.onClick.AddListener(OnClicked);
		}

		private void OnDestroy()
		{
			if (CurrentCharacter != null)
			{
				CharacterVitals myVitals = CurrentCharacter.MyVitals;
				myVitals.OnHealthChanged = (Action<float>)Delegate.Remove(myVitals.OnHealthChanged, new Action<float>(OnHealthChanged));
				CharacterVitals myVitals2 = CurrentCharacter.MyVitals;
				myVitals2.OnManaChanged = (Action<float>)Delegate.Remove(myVitals2.OnManaChanged, new Action<float>(OnManaChanged));
				Character currentCharacter = CurrentCharacter;
				currentCharacter.onPoisoned = (Action<bool>)Delegate.Remove(currentCharacter.onPoisoned, new Action<bool>(SetPoisoned));
				Character currentCharacter2 = CurrentCharacter;
				currentCharacter2.onTransformed = (Action<Character>)Delegate.Remove(currentCharacter2.onTransformed, new Action<Character>(SetChar));
				if ((CurrentCharacter.IsPartyMember() || CurrentCharacter.IsPlayer()) && CurrentCharacter.TryGetComponent<ProfilePictureCamera>(out var component))
				{
					ProfilePictureCamera profilePictureCamera = component;
					profilePictureCamera.onPictureTaken = (Action<Texture2D>)Delegate.Remove(profilePictureCamera.onPictureTaken, new Action<Texture2D>(UpdateProfilePicture));
					if (CurrentCharacter.IsPartyMember())
					{
						Character currentCharacter3 = CurrentCharacter;
						currentCharacter3.onEquipmentChanged = (Action)Delegate.Remove(currentCharacter3.onEquipmentChanged, new Action(component.TakePicture));
					}
				}
			}
			CurrentCharacter = null;
		}

		public void ShowSelectedVisuals(bool selected)
		{
			GameObject[] array = toggledOnSelect;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(selected);
			}
		}

		public void SetChar(Character newCharacter)
		{
			Character currentCharacter = CurrentCharacter;
			if (currentCharacter != null)
			{
				CharacterVitals myVitals = currentCharacter.MyVitals;
				myVitals.OnHealthChanged = (Action<float>)Delegate.Remove(myVitals.OnHealthChanged, new Action<float>(OnHealthChanged));
				CharacterVitals myVitals2 = currentCharacter.MyVitals;
				myVitals2.OnManaChanged = (Action<float>)Delegate.Remove(myVitals2.OnManaChanged, new Action<float>(OnManaChanged));
				currentCharacter.onPoisoned = (Action<bool>)Delegate.Remove(currentCharacter.onPoisoned, new Action<bool>(SetPoisoned));
				currentCharacter.onTransformed = (Action<Character>)Delegate.Remove(currentCharacter.onTransformed, new Action<Character>(SetChar));
				if ((currentCharacter.IsPartyMember() || currentCharacter.IsPlayer()) && currentCharacter.TryGetComponent<ProfilePictureCamera>(out var component))
				{
					ProfilePictureCamera profilePictureCamera = component;
					profilePictureCamera.onPictureTaken = (Action<Texture2D>)Delegate.Remove(profilePictureCamera.onPictureTaken, new Action<Texture2D>(UpdateProfilePicture));
					if (currentCharacter.IsPartyMember())
					{
						currentCharacter.onEquipmentChanged = (Action)Delegate.Remove(currentCharacter.onEquipmentChanged, new Action(component.TakePicture));
					}
				}
			}
			CurrentCharacter = newCharacter;
			if (CurrentCharacter != null)
			{
				manaMeter.gameObject.SetActive(!CurrentCharacter.IsPet());
				CharacterVitals myVitals3 = CurrentCharacter.MyVitals;
				myVitals3.OnHealthChanged = (Action<float>)Delegate.Combine(myVitals3.OnHealthChanged, new Action<float>(OnHealthChanged));
				CharacterVitals myVitals4 = CurrentCharacter.MyVitals;
				myVitals4.OnManaChanged = (Action<float>)Delegate.Combine(myVitals4.OnManaChanged, new Action<float>(OnManaChanged));
				Character currentCharacter2 = CurrentCharacter;
				currentCharacter2.onPoisoned = (Action<bool>)Delegate.Combine(currentCharacter2.onPoisoned, new Action<bool>(SetPoisoned));
				Character currentCharacter3 = CurrentCharacter;
				currentCharacter3.onTransformed = (Action<Character>)Delegate.Combine(currentCharacter3.onTransformed, new Action<Character>(SetChar));
				OnHealthChanged(CurrentCharacter.HP());
				OnManaChanged(CurrentCharacter.Mana());
				SetPoisoned(CurrentCharacter.GetPoisoned);
				if (CurrentCharacter.IsPartyMember() || CurrentCharacter.IsPlayer())
				{
					if (CurrentCharacter.TryGetComponent<ProfilePictureCamera>(out var component2))
					{
						ProfilePictureCamera profilePictureCamera2 = component2;
						profilePictureCamera2.onPictureTaken = (Action<Texture2D>)Delegate.Combine(profilePictureCamera2.onPictureTaken, new Action<Texture2D>(UpdateProfilePicture));
					}
					if (CurrentCharacter.IsPlayer())
					{
						UpdateProfilePicture((CurrentCharacter as Player).GetProfilePicture);
					}
					else if (CurrentCharacter.IsPartyMember())
					{
						UpdateProfilePicture((CurrentCharacter as PartyMember).GetProfilePicture);
					}
				}
				else if (CurrentCharacter.IsPet())
				{
					UpdateProfilePicture((CurrentCharacter as Pet).profilePicture);
				}
				nameText.text = CurrentCharacter.CharacterName;
				base.gameObject.SetActive(value: true);
			}
			else
			{
				base.gameObject.SetActive(value: false);
			}
		}

		private void UpdateProfilePicture(Texture2D texture2D)
		{
			profilePictureImage.texture = texture2D;
		}

		private void OnClicked()
		{
			onClicked?.Invoke(CurrentCharacter);
		}

		private void OnHealthChanged(float _)
		{
			UpdateMeter(CurrentCharacter.HPPercentage(), hpMeter);
		}

		private void OnManaChanged(float _)
		{
			UpdateMeter(CurrentCharacter.ManaPercentage(), manaMeter);
		}

		private void SetPoisoned(bool poisoned)
		{
			hpMeter.sprite = (poisoned ? hpGreenSprite : hpRedSprite);
		}

		private void UpdateMeter(float value, Image meter)
		{
			meter.fillAmount = Mathf.Clamp01(value) * 0.5f;
		}
	}
	public abstract class PartyCharacterUI : Selectable, IPointerClickHandler, IEventSystemHandler, IPointerEnterHandler, IPointerExitHandler
	{
		[Header("Meters")]
		[SerializeField]
		private Image hpMeter;

		[SerializeField]
		private Image manaMeter;

		[SerializeField]
		private Sprite hpRedSprite;

		[SerializeField]
		private Sprite hpGreenSprite;

		[SerializeField]
		private TextMeshProUGUI nameText;

		[SerializeField]
		protected Image controllerButtonFeedbackImage;

		[SerializeField]
		protected Animator keyboardMouseAnimator;

		[SerializeField]
		protected RawImage profilePictureImage;

		[SerializeField]
		private GameObject potionImageGO;

		[SerializeField]
		private GameObject lootImageGO;

		[SerializeField]
		private GameObject consoleButtonsParent;

		[SerializeField]
		private Animation homeAnim;

		[SerializeField]
		private Animation tacticAnim;

		[SerializeField]
		private Animation lootAnim;

		[SerializeField]
		private Animation healAnim;

		protected Character character;

		protected bool isHovered;

		protected bool isKeyboardMouseMode;

		public Character GetCharacter => character;

		protected override void Awake()
		{
			consoleButtonsParent.SetActive(value: false);
			base.Awake();
		}

		public void SetLootIconVisible(bool state)
		{
			if (!isKeyboardMouseMode)
			{
				lootImageGO.SetActive(value: false);
				return;
			}
			lootImageGO.SetActive(state);
			potionImageGO.SetActive(!state && isHovered);
		}

		protected void SetToCharacter(Character newCharacter)
		{
			Character character = this.character;
			if (character != null)
			{
				CharacterVitals myVitals = character.MyVitals;
				myVitals.OnHealthChanged = (Action<float>)Delegate.Remove(myVitals.OnHealthChanged, new Action<float>(OnHealthChanged));
				CharacterVitals myVitals2 = character.MyVitals;
				myVitals2.OnManaChanged = (Action<float>)Delegate.Remove(myVitals2.OnManaChanged, new Action<float>(OnManaChanged));
				character.onPoisoned = (Action<bool>)Delegate.Remove(character.onPoisoned, new Action<bool>(SetPoisoned));
			}
			this.character = newCharacter;
			if (this.character != null)
			{
				CharacterVitals myVitals3 = this.character.MyVitals;
				myVitals3.OnHealthChanged = (Action<float>)Delegate.Combine(myVitals3.OnHealthChanged, new Action<float>(OnHealthChanged));
				CharacterVitals myVitals4 = this.character.MyVitals;
				myVitals4.OnManaChanged = (Action<float>)Delegate.Combine(myVitals4.OnManaChanged, new Action<float>(OnManaChanged));
				Character obj = this.character;
				obj.onPoisoned = (Action<bool>)Delegate.Combine(obj.onPoisoned, new Action<bool>(SetPoisoned));
				OnHealthChanged(this.character.HP());
				OnManaChanged(this.character.Mana());
				SetPoisoned(this.character.GetPoisoned);
				nameText.text = this.character.CharacterName;
				Show();
			}
			else
			{
				Hide();
			}
		}

		public void Show()
		{
			base.gameObject.SetActive(value: true);
			keyboardMouseAnimator.SetTrigger("Normal");
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				OnInputBehaviorChange(SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior);
			}
		}

		public void Hide()
		{
			base.gameObject.SetActive(value: false);
			isHovered = false;
			keyboardMouseAnimator.SetTrigger("Normal");
		}

		private void OnHealthChanged(float _)
		{
			UpdateMeter(character.HPPercentage(), hpMeter);
		}

		private void OnManaChanged(float _)
		{
			UpdateMeter(character.ManaPercentage(), manaMeter);
		}

		private void SetPoisoned(bool poisoned)
		{
			hpMeter.sprite = (poisoned ? hpGreenSprite : hpRedSprite);
		}

		private void UpdateMeter(float value, Image meter)
		{
			meter.fillAmount = Mathf.Clamp01(value) * 0.5f;
		}

		public virtual void OnInputBehaviorChange(InputBroker.InputBehavior inputBehavior)
		{
			isKeyboardMouseMode = inputBehavior == InputBroker.InputBehavior.ClickToMove;
		}

		public virtual void OnFaceButton(PartyUI.ButtonType buttonType)
		{
			Animation animation = buttonType switch
			{
				PartyUI.ButtonType.PetHome => homeAnim, 
				PartyUI.ButtonType.Heal => healAnim, 
				PartyUI.ButtonType.Tactics => tacticAnim, 
				PartyUI.ButtonType.Loot => lootAnim, 
				_ => null, 
			};
			if (animation != null && animation.gameObject.activeInHierarchy)
			{
				if (animation.isPlaying)
				{
					animation.Stop();
				}
				animation.Play(PlayMode.StopAll);
			}
		}

		public override void OnSelect(BaseEventData eventData)
		{
			consoleButtonsParent.SetActive(!isKeyboardMouseMode);
			if (isKeyboardMouseMode)
			{
				StartCoroutine(UtilityTG.DelayedInvoke(0.2f, delegate
				{
					UtilityTG.SetSelected(null);
				}));
			}
			base.OnSelect(eventData);
		}

		protected void OriginalOnSelect(BaseEventData eventData)
		{
			base.OnSelect(eventData);
		}

		public override void OnDeselect(BaseEventData eventData)
		{
			consoleButtonsParent.SetActive(value: false);
			base.OnDeselect(eventData);
		}

		public virtual void HealWithRandomPotion()
		{
			if (character == null || Mathf.Approximately(character.MyVitals.GetHealthPct(), 1f))
			{
				return;
			}
			Player playerChar = Player.PlayerChar;
			if (playerChar == null)
			{
				return;
			}
			List<Item> list = new List<Item>();
			foreach (Item item in playerChar.inventory)
			{
				if (item.itemType != ItemType.Potion || item.slotIndex < 20)
				{
					continue;
				}
				bool flag = false;
				if (item.effects.TryGetValue(ActivationType.Usage, out var value))
				{
					foreach (EffectData item2 in value)
					{
						if (item2.buffType == EffectType.HPRecharge || item2.buffType == EffectType.PercentMaxHP)
						{
							flag = true;
							break;
						}
					}
				}
				if (flag)
				{
					list.Add(item);
				}
			}
			if (list.Count > 0)
			{
				Item randomEntry = list.GetRandomEntry();
				randomEntry.Use(Player.PlayerChar, character);
				if (randomEntry.useable && !randomEntry.HasUnlimitedUses && randomEntry.uses <= 0)
				{
					playerChar.RemoveItemFromInventory(randomEntry, RemoveItemReason.Consumed);
				}
			}
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			if (isKeyboardMouseMode)
			{
				if (Input.GetKey(KeyCode.LeftShift))
				{
					Player.PlayerChar.ShiftLootTarget = GetCharacter;
				}
				else
				{
					HealWithRandomPotion();
				}
				keyboardMouseAnimator.SetTrigger("Pressed");
			}
		}

		public override void OnPointerEnter(PointerEventData eventData)
		{
			bool key = Input.GetKey(KeyCode.LeftShift);
			potionImageGO.SetActive(!key);
			isHovered = true;
			keyboardMouseAnimator.SetTrigger("Highlighted");
			base.OnPointerEnter(eventData);
		}

		public override void OnPointerExit(PointerEventData eventData)
		{
			potionImageGO.SetActive(value: false);
			isHovered = false;
			keyboardMouseAnimator.SetTrigger("Normal");
			base.OnPointerExit(eventData);
		}
	}
	public class PartyMemberUI : PartyCharacterUI
	{
		[Header("Party Member")]
		[SerializeField]
		private Image[] tacticsIcons;

		[SerializeField]
		private Sprite supportTacticsSprite;

		[SerializeField]
		private Sprite defensiveTacticsSprite;

		[SerializeField]
		private Sprite aggressiveTacticsSprite;

		[SerializeField]
		private Button keyboardMouseTacticsButton;

		[SerializeField]
		private Button healPotionButton;

		private PartyMember partyMember;

		public void SetToPartyMember(PartyMember newPartyMember)
		{
			SetToCharacter(newPartyMember);
			PartyMember partyMember = this.partyMember;
			if (partyMember != null)
			{
				partyMember.onTacticsChanged = (Action<PartyMember.Tactics>)Delegate.Remove(partyMember.onTacticsChanged, new Action<PartyMember.Tactics>(OnTacticsChanged));
				if (partyMember.TryGetComponent<ProfilePictureCamera>(out var component))
				{
					ProfilePictureCamera profilePictureCamera = component;
					profilePictureCamera.onPictureTaken = (Action<Texture2D>)Delegate.Remove(profilePictureCamera.onPictureTaken, new Action<Texture2D>(UpdateProfilePicture));
				}
			}
			this.partyMember = newPartyMember;
			if (this.partyMember != null)
			{
				PartyMember obj = this.partyMember;
				obj.onTacticsChanged = (Action<PartyMember.Tactics>)Delegate.Combine(obj.onTacticsChanged, new Action<PartyMember.Tactics>(OnTacticsChanged));
				if (this.partyMember.TryGetComponent<ProfilePictureCamera>(out var component2))
				{
					ProfilePictureCamera profilePictureCamera2 = component2;
					profilePictureCamera2.onPictureTaken = (Action<Texture2D>)Delegate.Combine(profilePictureCamera2.onPictureTaken, new Action<Texture2D>(UpdateProfilePicture));
				}
				OnTacticsChanged(this.partyMember.CurrentTactics);
				UpdateProfilePicture(this.partyMember.GetProfilePicture);
			}
		}

		public override void OnFaceButton(PartyUI.ButtonType buttonType)
		{
			base.OnFaceButton(buttonType);
			switch (buttonType)
			{
			case PartyUI.ButtonType.Heal:
				HealWithRandomPotion();
				break;
			case PartyUI.ButtonType.Tactics:
				ToggleTactic();
				break;
			case PartyUI.ButtonType.Loot:
				if (Player.PlayerChar.DroppedItemInRange != null && partyMember.CanEnterAIState(AIState.GetItem))
				{
					partyMember.SetTargetDroppedItem(Player.PlayerChar.DroppedItemInRange);
					partyMember.SetAIState(AIState.GetItem);
				}
				break;
			case PartyUI.ButtonType.PetHome:
				break;
			}
		}

		public void ToggleTactic()
		{
			switch (partyMember.CurrentTactics)
			{
			case PartyMember.Tactics.Support:
				partyMember.SetTactics(PartyMember.Tactics.Defensive);
				break;
			case PartyMember.Tactics.Defensive:
				partyMember.SetTactics(PartyMember.Tactics.Aggressive);
				break;
			case PartyMember.Tactics.Aggressive:
				partyMember.SetTactics(PartyMember.Tactics.Support);
				break;
			}
		}

		private void OnTacticsChanged(PartyMember.Tactics newTactics)
		{
			Image[] array = tacticsIcons;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].sprite = GetTacticsSprite(newTactics);
			}
		}

		private void UpdateProfilePicture(Texture2D texture2D)
		{
			profilePictureImage.texture = texture2D;
		}

		private Sprite GetTacticsSprite(PartyMember.Tactics tactics)
		{
			return tactics switch
			{
				PartyMember.Tactics.Support => supportTacticsSprite, 
				PartyMember.Tactics.Defensive => defensiveTacticsSprite, 
				PartyMember.Tactics.Aggressive => aggressiveTacticsSprite, 
				_ => null, 
			};
		}

		public override void OnInputBehaviorChange(InputBroker.InputBehavior inputBehavior)
		{
			bool flag = inputBehavior == InputBroker.InputBehavior.ClickToMove;
			healPotionButton.gameObject.SetActive(!flag);
			keyboardMouseTacticsButton.interactable = flag;
			base.OnInputBehaviorChange(inputBehavior);
		}
	}
	public class PartyPetUI : PartyCharacterUI
	{
		private enum SellingState
		{
			NotSellingItems,
			AwaySellingItems
		}

		[SerializeField]
		private GameObject keyboardMouseFrame;

		[SerializeField]
		private GameObject controllerFrame;

		[SerializeField]
		private Button keyboardMouseHomeButton;

		[SerializeField]
		private Button controllerSendHomeButton;

		[SerializeField]
		private GameObject notInTownParent;

		[SerializeField]
		private GameObject inTownParent;

		[SerializeField]
		private TextMeshProUGUI inTownTimerText;

		[SerializeField]
		private TextMeshProUGUI transformTimerText;

		private Pet pet;

		private SellingState currentInTownState;

		private void LateUpdate()
		{
			if (!(pet == null))
			{
				AIState aIState = pet.GetAIState();
				bool flag = aIState == AIState.InTown || aIState == AIState.ReturningToTown;
				if (flag && currentInTownState != SellingState.AwaySellingItems)
				{
					SetInTownState(SellingState.AwaySellingItems);
				}
				else if (!flag && currentInTownState == SellingState.AwaySellingItems)
				{
					SetInTownState(SellingState.NotSellingItems);
				}
				if (currentInTownState == SellingState.AwaySellingItems)
				{
					UpdateTownTimer(pet.townTimer);
				}
				else if (pet.IsTransformed)
				{
					UpdateTransformTimer();
				}
			}
		}

		protected override void OnDestroy()
		{
			if (pet != null)
			{
				Pet obj = pet;
				obj.onTransformed = (Action<Character>)Delegate.Remove(obj.onTransformed, new Action<Character>(OnPetTransformation));
			}
			pet = null;
			base.OnDestroy();
		}

		private void UpdateTownTimer(float timer)
		{
			TimeSpan timeSpan = TimeSpan.FromSeconds(timer);
			inTownTimerText.text = timeSpan.ToString("mm':'ss");
		}

		public override void OnFaceButton(PartyUI.ButtonType buttonType)
		{
			base.OnFaceButton(buttonType);
			switch (buttonType)
			{
			case PartyUI.ButtonType.PetHome:
				OnSendPetHomeButtonPressed();
				break;
			case PartyUI.ButtonType.Heal:
				HealWithRandomPotion();
				break;
			case PartyUI.ButtonType.Loot:
				if (Player.PlayerChar.DroppedItemInRange != null && pet.CanEnterAIState(AIState.GetItem))
				{
					pet.SetTargetDroppedItem(Player.PlayerChar.DroppedItemInRange);
					pet.SetAIState(AIState.GetItem);
				}
				else
				{
					if (!(Player.PlayerChar.MerchantInRange != null) || !pet.CanEnterAIState(AIState.SpeakMerchant))
					{
						break;
					}
					MerchantType getMerchantType = Player.PlayerChar.MerchantInRange.GetMerchantType;
					if (getMerchantType != MerchantType.Armor && getMerchantType != MerchantType.Magic && getMerchantType != MerchantType.Fish && getMerchantType != MerchantType.Gambler && getMerchantType != MerchantType.Goods && getMerchantType != MerchantType.Jeweler && getMerchantType != MerchantType.Potions && getMerchantType != MerchantType.Trader && getMerchantType != MerchantType.Traveling && getMerchantType != MerchantType.Weapons && getMerchantType != MerchantType.WeaponsArmor)
					{
						break;
					}
					Fate.SetPause(paused: true);
					SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetFormatReplaceTags("PetSellMerchant", I2Loca.Get(Player.PlayerChar.MerchantInRange.InteractableName)), delegate(bool confirmed)
					{
						if (confirmed)
						{
							pet.SetTargetMerchant(Player.PlayerChar.MerchantInRange);
							pet.SetAIState(AIState.SpeakMerchant);
						}
						Fate.SetPause(paused: false);
						if (SingletonBehaviour<InputBroker>.Instance.HoldingPetAndAlly)
						{
							UtilityTG.UnityDelay(delegate
							{
								UtilityTG.SetSelected(base.gameObject);
							});
						}
						else
						{
							SimpleSingletonBehaviour<PlayerUI>.Instance.ForceReleasePetAllyFocus(deselectCurrentUI: true);
						}
					}, twoButtons: true);
				}
				break;
			case PartyUI.ButtonType.Tactics:
				break;
			}
		}

		private void UpdateTransformTimer()
		{
			AppliedEffect transformationEffect = pet.GetTransformationEffect();
			bool flag = transformationEffect != null && !transformationEffect.Permanent;
			transformTimerText.gameObject.SetActive(flag);
			if (flag)
			{
				TimeSpan timeSpan = TimeSpan.FromSeconds(transformationEffect.duration);
				transformTimerText.text = timeSpan.ToString("mm':'ss");
			}
		}

		public override void OnSelect(BaseEventData eventData)
		{
			if (pet != null)
			{
				AIState aIState = pet.GetAIState();
				if (aIState == AIState.ReturningToTown || aIState == AIState.InTown)
				{
					OriginalOnSelect(eventData);
					return;
				}
			}
			base.OnSelect(eventData);
		}

		public void SetToPet(Pet newPet)
		{
			Pet pet = this.pet;
			if (pet != null)
			{
				pet.onTransformed = (Action<Character>)Delegate.Remove(pet.onTransformed, new Action<Character>(OnPetTransformation));
			}
			SetToCharacter(newPet);
			this.pet = newPet;
			if (this.pet != null)
			{
				Pet obj = this.pet;
				obj.onTransformed = (Action<Character>)Delegate.Combine(obj.onTransformed, new Action<Character>(OnPetTransformation));
				profilePictureImage.texture = this.pet.profilePicture;
				if (!this.pet.IsTransformed)
				{
					transformTimerText.gameObject.SetActive(value: false);
				}
			}
		}

		private void OnPetTransformation(Character newPetCharacter)
		{
			SetToPet(newPetCharacter as Pet);
		}

		private void SetInTownState(SellingState newState)
		{
			if (currentInTownState != newState)
			{
				currentInTownState = newState;
				bool flag = currentInTownState == SellingState.AwaySellingItems;
				notInTownParent.SetActive(!flag);
				inTownParent.SetActive(flag);
				if (flag)
				{
					keyboardMouseFrame.SetActive(value: false);
					keyboardMouseHomeButton.gameObject.SetActive(value: false);
					controllerFrame.SetActive(value: true);
					OnSelect(null);
				}
				else if (SingletonBehaviour<InputBroker>.InstanceExists())
				{
					OnInputBehaviorChange(SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior);
				}
			}
		}

		public void OnSendPetHomeButtonPressed()
		{
			if (pet == null)
			{
				return;
			}
			if (LevelGenerator.currentInstance == null)
			{
				UtilityTG.UnityDelay(delegate
				{
					UtilityTG.SetSelected(null);
					Fate.SetPause(paused: true);
					SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton(I2Loca.Get("PetAlreadyInTown"), delegate
					{
						if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free && SingletonBehaviour<InputBroker>.Instance.HoldingPetAndAlly)
						{
							UtilityTG.UnityDelay(delegate
							{
								UtilityTG.SetSelected(base.gameObject);
							});
						}
						Fate.SetPause(paused: false);
					});
				});
				return;
			}
			AIState petAiState = pet.GetAIState();
			bool canSendPetHome = pet.Alive() && petAiState != AIState.InTown && petAiState != AIState.ReturningToTown && petAiState != AIState.Flee && petAiState != AIState.PassedOut && petAiState != AIState.PassingOut;
			if (!canSendPetHome)
			{
				return;
			}
			UtilityTG.UnityDelay(delegate
			{
				UtilityTG.SetSelected(null);
				Fate.SetPause(paused: true);
				SingletonBehaviour<PromptUI>.Instance.ShowPrompt(I2Loca.GetReplaceTags("SendPetConfirm"), delegate(bool confirmed)
				{
					Fate.SetPause(paused: false);
					if (!confirmed)
					{
						if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free && SingletonBehaviour<InputBroker>.Instance.HoldingPetAndAlly)
						{
							UtilityTG.UnityDelay(delegate
							{
								UtilityTG.SetSelected(base.gameObject);
							});
						}
					}
					else
					{
						canSendPetHome = pet.Alive() && petAiState != AIState.InTown && petAiState != AIState.ReturningToTown && petAiState != AIState.Flee && petAiState != AIState.PassedOut && petAiState != AIState.PassingOut;
						if (!canSendPetHome)
						{
							SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
							if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free && SingletonBehaviour<InputBroker>.Instance.HoldingPetAndAlly)
							{
								UtilityTG.UnityDelay(delegate
								{
									UtilityTG.SetSelected(base.gameObject);
								});
							}
						}
						else
						{
							if (petAiState == AIState.UniqueIdle)
							{
								pet.CancelUniqueIdle();
							}
							pet.ReturnToTown();
							if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free && SingletonBehaviour<InputBroker>.Instance.HoldingPetAndAlly)
							{
								UtilityTG.UnityDelay(delegate
								{
									UtilityTG.SetSelected(base.gameObject);
								});
							}
						}
					}
				});
			});
		}

		public override void OnInputBehaviorChange(InputBroker.InputBehavior inputBehavior)
		{
			bool flag = inputBehavior == InputBroker.InputBehavior.ClickToMove;
			keyboardMouseFrame.SetActive(flag);
			keyboardMouseHomeButton.gameObject.SetActive(flag);
			controllerFrame.SetActive(!flag);
			base.OnInputBehaviorChange(inputBehavior);
		}
	}
	public class PartySelectable : Selectable
	{
	}
	public class PartyUI : MonoBehaviour
	{
		public enum ButtonType
		{
			PetHome,
			Heal,
			Tactics,
			Loot
		}

		[SerializeField]
		private UiBlockingPanel controllerInputBlocker;

		[SerializeField]
		private PartyPetUI petUI;

		[SerializeField]
		private PartyMemberUI[] partyMemberUIs;

		private Player player;

		protected virtual void Update()
		{
			if (Input.GetKey(KeyCode.LeftShift))
			{
				Character shiftLootTarget = Player.PlayerChar.ShiftLootTarget;
				petUI.SetLootIconVisible(shiftLootTarget == petUI.GetCharacter);
				PartyMemberUI[] array = partyMemberUIs;
				foreach (PartyMemberUI partyMemberUI in array)
				{
					partyMemberUI.SetLootIconVisible(shiftLootTarget == partyMemberUI.GetCharacter);
				}
			}
			else
			{
				petUI.SetLootIconVisible(state: false);
				PartyMemberUI[] array = partyMemberUIs;
				for (int i = 0; i < array.Length; i++)
				{
					array[i].SetLootIconVisible(state: false);
				}
			}
		}

		public void SetPlayer(Player newPlayer)
		{
			Player player = this.player;
			if (player != null)
			{
				player.onPartyChanged = (Action)Delegate.Remove(player.onPartyChanged, new Action(UpdatePartyMembers));
			}
			this.player = newPlayer;
			if (this.player != null)
			{
				newPlayer.onPartyChanged = (Action)Delegate.Combine(newPlayer.onPartyChanged, new Action(UpdatePartyMembers));
				UpdatePartyMembers();
			}
			else
			{
				petUI.Hide();
				PartyMemberUI[] array = partyMemberUIs;
				for (int i = 0; i < array.Length; i++)
				{
					array[i].Hide();
				}
			}
			OnInputBehaviorChange(SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior);
		}

		private void UpdatePartyMembers()
		{
			petUI.SetToPet(player.GetPet() as Pet);
			for (int i = 0; i < partyMemberUIs.Length; i++)
			{
				partyMemberUIs[i].SetToPartyMember(player.GetPartyMember(i) as PartyMember);
			}
		}

		public void OnInputBehaviorChange(InputBroker.InputBehavior inputBehavior)
		{
			petUI.OnInputBehaviorChange(inputBehavior);
			for (int i = 0; i < partyMemberUIs.Length; i++)
			{
				partyMemberUIs[i].OnInputBehaviorChange(inputBehavior);
			}
		}

		public void OnFaceButton(ButtonType buttonType)
		{
			GameObject selected = UtilityTG.GetSelected();
			if (selected == petUI.gameObject)
			{
				if (buttonType != ButtonType.Tactics)
				{
					petUI.OnFaceButton(buttonType);
				}
				return;
			}
			for (int i = 0; i < partyMemberUIs.Length; i++)
			{
				if (selected == partyMemberUIs[i].gameObject)
				{
					if (buttonType != 0)
					{
						partyMemberUIs[i].OnFaceButton(buttonType);
					}
					break;
				}
			}
		}

		public void PetAndAllyFocusChanged(bool isHolding)
		{
			if (!Player.PlayerChar.Fishing() && (!isHolding || (!InputBlocker.Blocked && !Fate.isPaused)))
			{
				controllerInputBlocker.gameObject.SetActive(isHolding);
				if (isHolding)
				{
					UtilityTG.SetSelected(petUI.gameObject);
				}
				else if (!InputBlocker.Blocked && !Fate.isPaused)
				{
					UtilityTG.SetSelected(null);
				}
			}
		}

		public void ForceUnFocus(bool deselectCurrentUI)
		{
			controllerInputBlocker.gameObject.SetActive(value: false);
			if (deselectCurrentUI)
			{
				UtilityTG.SetSelected(null);
			}
		}
	}
