		public static Character GetLatestSelectedCharacterInParty()
		{
			if (LatestSelectedMemberIndex == 0)
			{
				return Player.PlayerChar;
			}
			if (LatestSelectedMemberIndex == 1)
			{
				return Player.PlayerChar.GetPet();
			}
			if (LatestSelectedMemberIndex > 1)
			{
				Character partyMember = Player.PlayerChar.GetPartyMember(LatestSelectedMemberIndex - 2);
				if (partyMember == null)
				{
					LatestSelectedMemberIndex = 0;
				}
				if (!(partyMember != null))
				{
					return Player.PlayerChar;
				}
				return partyMember;
			}
			UnityEngine.Debug.LogWarning("Bad index when trying to get character in party. Defaulting to player");
			return Player.PlayerChar;
		}

