		private void Cancel_Performed(InputAction.CallbackContext obj)
		{
			if (Time.frameCount > itemTargetingSelectedFrame + 2 && IsAnythingTargetingItem)
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetItemTargetingItem(null);
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetSpellTargetingItem(isTargeting: false);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
			}
			else
			{
				if (PromptUI.IsPromptActive || TutorialPopupUI.IsShown)
				{
					return;
				}
				if (uiTabs.CurrentTab != UITabs.TabType.None)
				{
					switch (uiTabs.CurrentTab)
					{
					case UITabs.TabType.Spellbook:
						if (SpellbookUI.OnMenuButtonRelay())
						{
							return;
						}
						break;
					case UITabs.TabType.Inventory:
						if (InventoryUI.OnMenuButtonRelay())
						{
							return;
						}
						break;
					}
					CloseTabs();
				}
				else if (recruitUI.isActiveAndEnabled)
				{
					recruitUI.Hide();
				}
			}
		}

		private void OnDisable()
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
				instance.OnInputBehaviorChanged = (Action<InputBroker.InputBehavior>)Delegate.Remove(instance.OnInputBehaviorChanged, new Action<InputBroker.InputBehavior>(OnInputBehaviorChange));
				InputBroker instance2 = SingletonBehaviour<InputBroker>.Instance;
				instance2.OnMenuButtonPerformed = (Action)Delegate.Remove(instance2.OnMenuButtonPerformed, new Action(OnMenuButton));
			}
		}

		private void OnMenuButton()
		{
			partyUI.ForceUnFocus(deselectCurrentUI: false);
			if (PromptUI.IsPromptActive || FateChoiceUI.FateChoiceActive || IsFishing || TutorialPopupUI.IsShown)
			{
				return;
			}
			if (recruitUI.isActiveAndEnabled)
			{
				UtilityTG.UnityDelay(recruitUI.Hide);
			}
			else if (uiTabs.CurrentTab != UITabs.TabType.None)
			{
				switch (uiTabs.CurrentTab)
				{
				case UITabs.TabType.Inventory:
					if (InventoryUI.OnMenuButtonRelay())
					{
						return;
					}
					break;
				case UITabs.TabType.Spellbook:
					if (SpellbookUI.OnMenuButtonRelay())
					{
						return;
					}
					break;
				}
				CloseTabs();
			}
			else if (InputBlocker.Blocked)
			{
				if (SingletonBehaviour<PauseUI>.Instance.gameObject.activeInHierarchy)
				{
					SingletonBehaviour<CursorManager>.Instance.SetVirtualCursorActive(state: false);
					SingletonBehaviour<PauseUI>.Instance.OnMenuButton();
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
					if (!SingletonBehaviour<PauseUI>.Instance.gameObject.activeInHierarchy)
					{
						SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Game);
					}
				}
			}
			else
			{
				SingletonBehaviour<CursorManager>.Instance.SetVirtualCursorActive(state: false);
				SingletonBehaviour<PauseUI>.Instance.OnMenuButton();
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Menu);
			}
		}

