		private void OnResolutionChanged(int newW, int newH)
		{
			Canvas.ForceUpdateCanvases();
			canvasScaleFactor = GetComponent<Canvas>().scaleFactor;
		}

		private void LateUpdate()
		{
			if (Time.frameCount > itemTargetingSelectedFrame + 2 && IsAnythingTargetingItem && SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove && Mouse.current != null && Mouse.current.rightButton.wasPressedThisFrame)
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetItemTargetingItem(null);
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetSpellTargetingItem(isTargeting: false);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
			}
			if (avatarIsSet)
			{
				SetStamina(playerChar.StaminaPercentage(), Mathf.FloorToInt(playerChar.stamina), playerChar.MaxStamina());
			}
		}

		private void OnInputTick()
		{
			if (SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Submit.WasPerformedThisFrame())
			{
				if (InventoryUI != null && InventoryUI.gameObject != null && InventoryUI.gameObject.activeInHierarchy && InventoryUI.heldItem != null)
				{
					InventoryUI.draggedItemUI = InventoryUI.heldItem;
					InventoryUI.heldItem.OnEndDrag(null);
					InventoryUI.heldItem = null;
					return;
				}
				GameObject currentSelectedGameObject = EventSystem.current.currentSelectedGameObject;
				if (currentSelectedGameObject != null)
				{
					UtilityTG.SimulateButtonClick(currentSelectedGameObject);
				}
			}
			if (PromptUI.IsPromptActive || TutorialPopupUI.IsShown)
			{
				return;
			}
			if (uiTabs.CurrentTab == UITabs.TabType.None)
			{
				if (SingletonBehaviour<InputBroker>.Instance.HoldingPetAndAlly)
				{
					if (SingletonBehaviour<InputBroker>.Instance.Rage)
					{
						bool flag = PlatformFlag.GetCurrentPlatformAsFlag() == PlatformFlag.Flag.NintendoSwitch;
						partyUI.OnFaceButton(flag ? PartyUI.ButtonType.Heal : PartyUI.ButtonType.Loot);
					}
					else if (SingletonBehaviour<InputBroker>.Instance.Interact)
					{
						bool flag2 = PlatformFlag.GetCurrentPlatformAsFlag() == PlatformFlag.Flag.NintendoSwitch;
						partyUI.OnFaceButton((!flag2) ? PartyUI.ButtonType.Heal : PartyUI.ButtonType.Loot);
					}
					else if (SingletonBehaviour<InputBroker>.Instance.Inputs.CharacterInputs.Fire1.WasPressedThisFrame())
					{
						partyUI.OnFaceButton(PartyUI.ButtonType.PetHome);
					}
					else if (SingletonBehaviour<InputBroker>.Instance.Inputs.CharacterInputs.Fire2.WasPressedThisFrame())
					{
						partyUI.OnFaceButton(PartyUI.ButtonType.Tactics);
					}
				}
				return;
			}
			Cleverous.Prodigy.PlayerInput input = SingletonBehaviour<InputBroker>.Instance.GetInput();
			if (leftToggleAction == null || rightToggleAction == null)
			{
				leftToggleAction = SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.LeftToggle;
				rightToggleAction = SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.RightToggle;
				leftToggleAction.Enable();
				rightToggleAction.Enable();
			}
			if (leftToggleAction.WasPerformedThisFrame())
			{
				uiTabs.PreviousTab();
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			}
			else if (rightToggleAction.WasPerformedThisFrame())
			{
				uiTabs.NextTab();
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			}
			if (input.AltInteract)
			{
				OnAltInteract();
			}
		}

		private void OnAltInteract()
		{
			if (uiTabs.CurrentTab == UITabs.TabType.Inventory)
			{
				if (IsAnythingTargetingItem)
				{
					return;
				}
				GameObject currentSelectedGameObject = EventSystem.current.currentSelectedGameObject;
				if (!(currentSelectedGameObject != null))
				{
					return;
				}
				ItemUI componentInParent = currentSelectedGameObject.GetComponentInParent<ItemUI>();
				if (componentInParent != null && componentInParent.Owner.IsPlayerOwnedInventory)
				{
					if (componentInParent == itemTargetingItem)
					{
						SetItemTargetingItem(null);
					}
					componentInParent.Owner.RemoveItemFromInventory(componentInParent.currentItem, RemoveItemReason.Drop);
					componentInParent.currentItem.Drop(componentInParent.Owner.myTransform.position + new Vector3(UnityEngine.Random.Range(-1.5f, 1.5f), 0f, UnityEngine.Random.Range(-1.5f, 1.5f)));
					componentInParent.gameObject.SetActive(value: false);
					Tooltip.HideTooltip();
				}
			}
			else if (uiTabs.CurrentTab == UITabs.TabType.Spellbook)
			{
				SpellbookUI.OnAltInteract();
			}
		}

		private void OnInputBehaviorChange(InputBroker.InputBehavior inputBehavior)
		{
			if (InventoryUI.draggedItemUI != null)
			{
				InventoryUI.draggedItemUI.CancelItemMove();
				InventoryUI.draggedItemUI = null;
			}
			if (InventoryUI.heldItem != null)
			{
				InventoryUI.heldItem.CancelItemMove();
				InventoryUI.heldItem = null;
			}
			partyUI.OnInputBehaviorChange(inputBehavior);
			InventoryUI.SetToInputBrokerBehavior(inputBehavior);
			if (recruitUI.isActiveAndEnabled)
			{
				recruitUI.OnInputBehaviorChange(inputBehavior);
			}
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				_ = uiTabs.CurrentTab;
				_ = -1;
			}
		}

		private void OnGoldChanged(ulong newAmount)
		{
			if (CurrentScreenTab == UITabs.TabType.Inventory)
			{
				InventoryUI.OnGoldChanged(newAmount);
			}
			goldText.text = newAmount.ToString();
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.CoinPickup, randomizePitch: true);
		}

		private void OnAvatarSet(ProdigyPlayer player, ProdigyAgent agent)
		{
			currentAgent = agent;
			CharacterVitals vitals = currentAgent.Vitals;
			vitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Combine(vitals.OnDamaged, new Action<CharacterVitals.Damage>(Vitals_OnDamaged));
			CharacterVitals vitals2 = currentAgent.Vitals;
			vitals2.OnHealed = (Action<CharacterVitals.Heal>)Delegate.Combine(vitals2.OnHealed, new Action<CharacterVitals.Heal>(Vitals_OnHealed));
			CharacterVitals vitals3 = currentAgent.Vitals;
			vitals3.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Combine(vitals3.OnKilled, new Action<CharacterVitals.Damage>(Vitals_OnKilled));
			CharacterVitals vitals4 = currentAgent.Vitals;
			vitals4.OnHealthChanged = (Action<float>)Delegate.Combine(vitals4.OnHealthChanged, new Action<float>(Vitals_OnHealthChanged));
			CharacterVitals vitals5 = currentAgent.Vitals;
			vitals5.OnManaChanged = (Action<float>)Delegate.Combine(vitals5.OnManaChanged, new Action<float>(Vitals_OnManaChanged));
			uiTabs.Init();
			PlayerStatus instance = SingletonBehaviour<PlayerStatus>.Instance;
			instance.OnGoldChanged = (Action<ulong>)Delegate.Remove(instance.OnGoldChanged, new Action<ulong>(OnGoldChanged));
			PlayerStatus instance2 = SingletonBehaviour<PlayerStatus>.Instance;
			instance2.OnGoldChanged = (Action<ulong>)Delegate.Combine(instance2.OnGoldChanged, new Action<ulong>(OnGoldChanged));
			goldText.text = SingletonBehaviour<PlayerStatus>.Instance.gold.ToString();
			playerChar = Player.PlayerChar;
			SetLevel(playerChar.Level);
			SetXP(playerChar.GetPctToNextLevel(), playerChar.experience, Fate.GetExperienceNeeded(playerChar.Level));
			Player player2 = playerChar;
			player2.onActiveSpellChange = (Action<SpellData>)Delegate.Combine(player2.onActiveSpellChange, new Action<SpellData>(ActiveSpellChanged));
			Player player3 = playerChar;
			player3.onEffectApplied = (Action<AppliedEffect>)Delegate.Combine(player3.onEffectApplied, new Action<AppliedEffect>(OnPlayerEffectAddedOrRemoved));
			Player player4 = playerChar;
			player4.onEffectRemoved = (Action<AppliedEffect>)Delegate.Combine(player4.onEffectRemoved, new Action<AppliedEffect>(OnPlayerEffectAddedOrRemoved));
			ActiveSpellChanged(playerChar.activeSpell);
			for (int i = 0; i < hotBarSlots.Length; i++)
			{
				hotBarSlots[i].owner = playerChar;
				hotBarSlots[i].globalIndex = i;
				if (hotBarSlots[i].itemHandle != null)
				{
