		private void ActiveSpellChanged(SpellData newSpell)
		{
			activeSpellTooltip.spellData = newSpell;
			if (newSpell == null)
			{
				activeSpellIcon.gameObject.SetActive(value: false);
				return;
			}
			Sprite sprite = SingletonBehaviour<FateDB>.Instance.spriteStash.Find((Sprite sp) => sp.name == newSpell.IconName);
			if (sprite == null)
			{
				UnityEngine.Debug.LogError("No sprite found for spell: " + newSpell.spellName);
			}
			activeSpellIcon.sprite = sprite;
			activeSpellIcon.gameObject.SetActive(value: true);
		}

		private void UpdateHotBar()
		{
			List<Item> list = playerChar.inventory.FindAll((Item item) => item.slotIndex >= 0 && item.slotIndex < hotBarSlots.Length);
			if (list == null)
			{
				return;
			}
			for (int i = 0; i < hotBarSlots.Length; i++)
			{
				HotbarSlotUI slot = hotBarSlots[i];
				if (slot.itemHandle != null)
				{
					slot.itemHandle.gameObject.SetActive(value: false);
					slot.ForceClear();
				}
				Item item2 = list.Find((Item item) => item.slotIndex == slot.globalIndex);
				if (item2 != null)
				{
					ItemUI @object = InventoryUI.itemPool.GetObject();
					@object.Init();
					@object.SetOwner(playerChar);
					@object.SetItem(item2, slot.cellSize);
					@object.SetParent(slot.transform);
					@object.SetSlots(slot);
					@object.gameObject.SetActive(value: true);
					if (!slot.TrySetItem(@object))
					{
						UnityEngine.Debug.LogError("Failed setting up the hotbar!");
					}
				}
			}
		}

