		private void Vitals_OnKilled(CharacterVitals.Damage damage)
		{
			SetHealth(0f, 0, 0);
			SetUIActive(state: false);
			SaveData.CurrentSaveData.playerSaveData.posInLastScene = Player.PlayerChar.myTransform.position;
			SaveData.CurrentSaveData.playerSaveData.rotInLastScene = Player.PlayerChar.myTransform.rotation.eulerAngles;
			SaveData.CurrentSaveData.playerSaveData.lastScene = SceneLoad.CurrentScene;
			SingletonBehaviour<InputBroker>.Instance.DisableAllInput();
			if (SingletonBehaviour<PlayerStatus>.Instance.Difficulty == Fate.Difficulty.Hardcore)
			{
				SaveData.CurrentSaveSlot.saveState = SaveSlotState.Dead;
				SaveData.RequestSave(delegate
				{
					FadeToFate();
				});
			}
			else
			{
				FadeToFate();
			}
			void FadeToFate()
			{
				UtilityTG.StartCoroutine(UtilityTG.DelayedInvoke(2f, delegate
				{
					SingletonBehaviour<SystemOverlay>.Instance.FadeToBlack(delegate
					{
						SingletonBehaviour<SystemOverlay>.Instance.FadeToClear(delegate
						{
							SingletonBehaviour<InputBroker>.Instance.EnableAllInput();
							SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Menu);
						}, ignoreIfAlreadyClear: false, 1f);
						SingletonBehaviour<FateChoiceUI>.Instance.ShowFatePrompt(delegate(bool positive)
						{
							if (positive)
							{
								SetUIActive(state: true);
							}
						});
					});
				}));
			}
		}

		private void OnPlayerEffectAddedOrRemoved(AppliedEffect effect)
		{
			switch (effect.BuffType)
			{
			case EffectType.Vitality:
			case EffectType.HP:
			case EffectType.PercentVitality:
			case EffectType.PercentMaxHP:
				UpdateHealthBar();
				break;
			case EffectType.Magic:
			case EffectType.Mana:
			case EffectType.PercentMagic:
			case EffectType.PercentMaxMana:
				UpdateManaBar();
				break;
			case EffectType.Stamina:
			case EffectType.PercentStamina:
				UpdateStaminaBar();
				break;
			}
		}

