		public void InitTabs(UITabs.Tab[] tabs)
		{
			for (int i = 0; i < tabs.Length; i++)
			{
				UITabs.Tab tab = tabs[i];
				switch (tab.tabType)
				{
				case UITabs.TabType.StatsSkills:
					MainStatsUI = tab.tabScreen.GetComponentInChildren<StatsUI>(includeInactive: true);
					break;
				case UITabs.TabType.Inventory:
					InventoryUI = tab.tabScreen.GetComponent<InventoryUI>();
					InventoryStatsUI = InventoryUI.statsParent;
					InventoryUI.Init();
					InventoryInitialized = true;
					OnInventoryInit?.Invoke();
					InventoryUI.gameObject.SetActive(value: true);
					InventoryUI.gameObject.SetActive(value: false);
					break;
				case UITabs.TabType.Spellbook:
					SpellbookUI = tab.tabScreen.GetComponent<SpellbookUI>();
					break;
				case UITabs.TabType.Quests:
					QuestUI = tab.tabScreen.GetComponent<QuestUI>();
					break;
				}
			}
			UITabs uITabs = uiTabs;
			uITabs.onTabChanged = (Action<UITabs.TabType, UITabs.TabType>)Delegate.Remove(uITabs.onTabChanged, new Action<UITabs.TabType, UITabs.TabType>(OnTabChanged));
			UITabs uITabs2 = uiTabs;
			uITabs2.onTabChanged = (Action<UITabs.TabType, UITabs.TabType>)Delegate.Combine(uITabs2.onTabChanged, new Action<UITabs.TabType, UITabs.TabType>(OnTabChanged));
		}

		private void OnTabChanged(UITabs.TabType _, UITabs.TabType newTab)
		{
			Tooltip.HideTooltip();
			if (newTab == UITabs.TabType.StatsSkills)
			{
