		public void SetItemTargetingItem(ItemUI itemUI)
		{
			ItemUI itemUI2 = itemTargetingItem;
			if (itemUI == itemUI2)
			{
				itemTargetingSelectedFrame = Time.frameCount;
				return;
			}
			if ((bool)itemUI2)
			{
				itemUI2.OnIsTargetingItem(isTargetingItem: false);
			}
			itemTargetingItem = itemUI;
			if (IsItemTargetingItem)
			{
				SetSpellTargetingItem(isTargeting: false);
				itemTargetingItem.OnIsTargetingItem(isTargetingItem: true);
				itemTargetingSelectedFrame = Time.frameCount;
			}
			UpdateItemSelectFeedback();
		}

		public void SetSpellTargetingItem(bool isTargeting)
		{
			if (IsSpellTargetingItem == isTargeting)
			{
				itemTargetingSelectedFrame = Time.frameCount;
				return;
			}
			IsSpellTargetingItem = isTargeting;
			if (IsSpellTargetingItem)
			{
				SetItemTargetingItem(null);
				itemTargetingSelectedFrame = Time.frameCount;
			}
			UpdateItemSelectFeedback();
		}

		private void UpdateItemSelectFeedback()
		{
			bool isAnythingTargetingItem = IsAnythingTargetingItem;
			SingletonBehaviour<CursorManager>.Instance.SetMode(isAnythingTargetingItem ? CursorManager.CursorMode.ItemTarget : CursorManager.CursorMode.Standard);
			if (IsSpellTargetingItem)
			{
				SingletonBehaviour<CursorTooltip>.Instance.Show(CursorTooltip.Mode.Identify);
			}
			else if (IsItemTargetingItem)
			{
				SingletonBehaviour<CursorTooltip>.Instance.Show((itemTargetingItem.currentItem.itemType == ItemType.Gem) ? CursorTooltip.Mode.SocketGem : CursorTooltip.Mode.Identify);
			}
			else
			{
				SingletonBehaviour<CursorTooltip>.Instance.Hide();
			}
			onItemTargetingChanged?.Invoke();
		}

