		private void ScreenTabButtonClicked(UITabs.TabType tab)
		{
			if (PauseUI.IsShown || IsFishing || PromptUI.IsPromptActive || TutorialPopupUI.IsShown)
			{
				return;
			}
			if (uiTabs.CurrentTab != UITabs.TabType.None)
			{
				if (uiTabs.CurrentTab != tab)
				{
					if (tab == UITabs.TabType.Inventory)
					{
						ShowInventory(InventoryStateType.Stats);
					}
					else
					{
						uiTabs.SetTab(tab);
					}
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				}
				else
				{
					CloseTabs();
				}
			}
			else if (!InputBlocker.Blocked)
			{
				if (tab == UITabs.TabType.Inventory)
				{
					ShowInventory(InventoryStateType.Stats);
				}
				else
				{
					uiTabs.SetTab(tab);
				}
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				blockerGO.SetActive(value: true);
			}
		}

