			}
		}

		private void SetMinimapZoomLevel(int level, bool playClickSound)
		{
			if (level > 4)
			{
				level = 0;
			}
			switch (level)
			{
			case 0:
				minimapUI.SetActive(value: true);
				break;
			case 4:
				minimapUI.SetActive(value: false);
				break;
			}
			if (minimapZoomLevel != level)
			{
				if (playClickSound && SingletonBehaviour<AudioManager>.InstanceExists())
				{
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				}
				if (SaveData.CurrentSaveData != null)
				{
					SaveData.CurrentSaveData.playerSaveData.lastMinimapZoomLevel = level;
				}
				minimapZoomLevel = level;
				OnMinimapZoomLevelChanged?.Invoke(minimapZoomLevel);
			}
		}

		private void HotbarOneInteracted()
		{
			HotbarInteractedByIndex(0);
		}

		private void HotbarTwoInteracted()
		{
			HotbarInteractedByIndex(1);
		}

		private void HotbarThreeInteracted()
		{
			HotbarInteractedByIndex(2);
		}

		private void HotbarFourInteracted()
		{
			HotbarInteractedByIndex(3);
		}

		private void HotbarInteractedByIndex(int index)
		{
			if (index < 0 || (float)index >= 4f)
			{
				UnityEngine.Debug.LogWarning($"Bad hotbar index {index}, allowed is {0}-{3f}");
			}
			else
			{
				if (Fate.isPaused || InputBlocker.Blocked || SingletonBehaviour<InputBroker>.Instance.HoldingPetAndAlly)
				{
					return;
				}
				HotbarSlotUI hotbarSlotUI = hotBarSlots[index];
				if (hotbarSlotUI.gameObject.activeInHierarchy)
				{
					if (hotbarSlotUI.itemHandle != null)
					{
						hotbarSlotUI.itemHandle.OnInteract();
					}
					hotbarSlotUI.DoClickEffect();
				}
			}
		}

		private void OnHotbarItemAdded(Item item, int slot)
		{
			if (item != null)
			{
				UpdateHotBar();
			}
		}

		private void PetAndAllyFocusChanged(bool isHolding)
		{
			if (!(Player.PlayerChar == null))
			{
				partyUI.PetAndAllyFocusChanged(isHolding);
				if (isHolding && uiTabs.CurrentTab == UITabs.TabType.Inventory)
				{
					InventoryUI.ToggleInventoryOwner();
				}
			}
		}

		private void SpellWheelFocusChanged(bool isHolding)
		{
			if (uiTabs.CurrentTab != UITabs.TabType.None)
			{
				return;
			}
			if (IsFishing)
			{
				if (!spellWheelUI.IsTweening && spellWheelUI.gameObject.activeInHierarchy)
				{
					spellWheelUI.SetActive(active: false);
				}
			}
			else
			{
				spellWheelUI.SetActive(isHolding);
			}
		}

		public void SetHealth(float percent, int currentHealth, int maxHealth)
		{
			healthBar.SetHealth(percent);
			healthBar.SetRemaining(currentHealth);
			hpBarTooltip.descRaw = $"{currentHealth}/{maxHealth}";
		}

		public void SetPoisoned(bool poisoned)
		{
			healthBar.SetPoisoned(poisoned);
		}

		public void SetMana(float percent, int currentMana, int maxMana)
		{
			manaBar.SetFill(percent);
			manaBar.SetRemaining(currentMana);
			manaBarTooltip.descRaw = $"{currentMana}/{maxMana}";
		}

		public void SetStamina(float percent, int currentStamina, int maxStamina)
		{
			staminaBar.fillAmount = percent;
			staminaBarTooltip.descRaw = $"{currentStamina}/{maxStamina}";
		}

		public void SetXP(float percent, ulong currentXP, ulong XPforNextLevel)
		{
			xpBar.fillAmount = percent;
			xpLeftText.text = $"{Mathf.FloorToInt(Mathf.Clamp01(percent) * 100f)}%";
			experienceBarTooltip.descRaw = $"{currentXP}/{XPforNextLevel}";
		}

		public void SetLevel(int level)
		{
			levelText.text = "<color=#EADECD>Lvl</color> " + level;
			levelTooltip.descRaw = level.ToString();
		}

		public bool TryInteractEquipItemUI(ItemUI itemUI)
		{
			if (uiTabs.CurrentTab != UITabs.TabType.Inventory)
			{
				return false;
			}
			return InventoryUI.TryInteractEquipItemUI(itemUI);
		}

		public bool TryDropItemUIOnEquipmentSlot(ItemUI itemUI, EquipmentSlotUI equipSlot)
		{
			if (uiTabs.CurrentTab != UITabs.TabType.Inventory)
			{
				return false;
			}
			return InventoryUI.TryDropItemUIOnEquipmentSlot(itemUI, equipSlot);
		}
	}
	public class QuestEntryUI : MonoBehaviour
	{
		public TextMeshProUGUI questDescription;

		public Button questButton;

		public Button cancelButton;

		public GameObject[] objectsToToggle;

		public TextMeshProUGUI depthText;

		public GameObject completeIndicator;

		public GameObject failedIndicator;

		public void Setup(Quest quest, Action onQuestClicked, Action onCancelClicked = null)
		{
			string text = string.Format(quest.QuestName, quest.QuestGiverDisplayName);
			bool flag = quest.Status == Quest.QuestStatus.Completed || quest.Status == Quest.QuestStatus.Claimed;
			bool flag2 = quest.Status == Quest.QuestStatus.Failed;
			if (flag)
			{
				questDescription.text = string.Format(I2Loca.Get("QuestComplete"), text);
			}
			else if (flag2)
			{
				questDescription.text = text + " - " + I2Loca.Get("Failed");
			}
			else
			{
				questDescription.text = text;
			}
			depthText.text = "<style=C1>" + I2Loca.GetFormat("Level_x", quest.TargetDepth) + "</style>";
			depthText.gameObject.SetActive(quest.TargetDepth != 0 && !flag && !flag2);
			questButton.onClick.RemoveAllListeners();
			questButton.onClick.AddListener(delegate
			{
				onQuestClicked();
			});
			if (cancelButton != null)
			{
				cancelButton.onClick.RemoveAllListeners();
				if (onCancelClicked != null)
				{
					cancelButton.onClick.AddListener(delegate
					{
						onCancelClicked();
					});
				}
			}
			completeIndicator.SetActive(flag);
			failedIndicator.SetActive(flag2);
			ToggleObjects(toState: true);
		}

		public void SetEmpty()
		{
			ToggleObjects(toState: false);
			questButton.onClick.RemoveAllListeners();
			completeIndicator.SetActive(value: false);
			failedIndicator.SetActive(value: false);
			depthText.gameObject.SetActive(value: false);
		}

		private void ToggleObjects(bool toState)
		{
			for (int i = 0; i < objectsToToggle.Length; i++)
			{
				objectsToToggle[i].SetActive(toState);
			}
		}
	}
