		private void SetActiveQuest(Quest quest)
		{
			descriptionText.text = quest.GetShortDesc();
			if (quest.Completed)
			{
				descriptionText.text += I2Loca.GetMultiLineReplaceTagsFormat("QuestCompleteLong", quest.QuestGiverDisplayName);
			}
			goldText.text = quest.GoldReward.ToString();
			expText.text = quest.XPReward.ToString();
			fameText.text = quest.FameReward.ToString();
			if (quest.ItemReward == null)
			{
				itemParent.SetActive(value: false);
				return;
			}
			itemText.text = "<style=C1>" + quest.ItemReward.ItemDisplayName + "</style>";
			itemParent.SetActive(value: true);
		}

		private void ClearActiveQuest()
		{
			descriptionText.text = "";
			goldText.text = "-";
			expText.text = "-";
			fameText.text = "-";
			itemParent.SetActive(value: false);
		}

		private Sprite GetQuestRealmSprite(RealmData.RealmId activeTownRealm)
		{
			switch (activeTownRealm)
			{
			case RealmData.RealmId.Grove:
				return groveSprite;
			case RealmData.RealmId.Druantia:
				return druantiaSprite;
			case RealmData.RealmId.Typhon:
				return typhonSprite;
			case RealmData.RealmId.TempleOfFate:
			case RealmData.RealmId.ChamberOfTrials:
				if (Fate.CurrentFateVer == Fate.FateVer.UndiscoveredRealms)
				{
					return templeFate2Sprite;
				}
				return templeSprite;
			case RealmData.RealmId.Ekbatan:
				return ekbatanSprite;
			case RealmData.RealmId.CavernsLivingFire:
				return cavernsSprite;
			case RealmData.RealmId.TkalaCrypt:
				return cryptSprite;
			case RealmData.RealmId.HauntedPalace:
				return palaceSprite;
			case RealmData.RealmId.Prometheus:
				return prometheusSprite;
			default:
				return groveSprite;
			}
		}

		private bool RealmArrowsShouldBeActive()
		{
			return Fate.CurrentFateVer != Fate.FateVer.Original;
		}

		private void OnEnable()
		{
			RealmData.RealmId realm = ((activeRealm != RealmData.RealmId.ANY) ? activeRealm : ((!(LevelGenerator.currentInstance != null)) ? SingletonBehaviour<PlayerStatus>.Instance.TownRealm : SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm));
			BuildQuestUIForRealm(realm);
			realmLeftButton.gameObject.SetActive(RealmArrowsShouldBeActive());
			realmRightButton.gameObject.SetActive(RealmArrowsShouldBeActive());
		}

		private void BuildQuestUIForRealm(RealmData.RealmId realm)
		{
			realmNameText.text = Fate.GetRealmName(realm, preferShortName: false);
			realmImage.sprite = GetQuestRealmSprite(realm);
			List<Quest> quests = SingletonBehaviour<QuestManager>.Instance.GetQuests((int)realm);
			Quest quest2 = null;
			GameObject initialSelectedGO = null;
			int num = 0;
			Quest mq = SingletonBehaviour<QuestManager>.Instance.GetRealmQuest(realm);
			if (mq != null && mq.Status != 0)
			{
				mainQuest.Setup(mq, delegate
				{
					SetActiveQuest(mq);
				});
				quest2 = mq;
				initialSelectedGO = mainQuest.gameObject;
			}
			else
			{
				mainQuest.SetEmpty();
			}
			for (int i = 0; i < quests.Count; i++)
			{
				Quest quest = quests[i];
				if (quest != null && !string.IsNullOrEmpty(quest.QuestGiverName) && quest.Status != 0)
				{
					sideQuests[num++].Setup(quest, delegate
					{
						SetActiveQuest(quest);
					}, delegate
					{
						OnCancelClicked(quest);
					});
					if (quest2 == null)
					{
						quest2 = quest;
						QuestEntryUI questEntryUI = sideQuests[num - 1];
						initialSelectedGO = questEntryUI.gameObject;
					}
				}
			}
			for (int j = num; j < sideQuests.Length; j++)
			{
				sideQuests[j].SetEmpty();
			}
			if (quest2 == null)
			{
				ClearActiveQuest();
			}
			else
			{
				SetActiveQuest(quest2);
				UtilityTG.UnityDelay(delegate
				{
					UtilityTG.SetSelected(initialSelectedGO);
				});
			}
			activeRealm = realm;
		}

		private void OnCancelClicked(Quest quest)
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetFormat("Prompt_CancelQuest", string.Format(quest.QuestName, quest.QuestGiverDisplayName)), delegate(bool positive)
			{
				if (positive)
				{
					SingletonBehaviour<QuestManager>.Instance.CancelQuest(quest);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
					OnEnable();
				}
				else
				{
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				}
			}, twoButtons: true);
		}
	}
	public class RecruitEntryUI : MonoBehaviour, ISelectHandler, IEventSystemHandler
	{
		[Serializable]
		public struct PreviewSprites
		{
			public Sprite bodyA;

			public Sprite bodyB;
		}

		private Selectable _selectable;

		[SerializeField]
		private TextMeshProUGUI nameText;

		[SerializeField]
		private TextMeshProUGUI costText;

		[Header("Portrait")]
		[SerializeField]
		private Image portrait;

		[SerializeField]
		private PreviewSprites spritesHuman;

		[SerializeField]
		private PreviewSprites spritesElf;

		[SerializeField]
		private PreviewSprites spritesOrc;

		[SerializeField]
		private PreviewSprites spritesCogger;

		[SerializeField]
		private PreviewSprites spritesImp;

		private uint cost;

		private PartyMemberSaveData save;

		public Action<RecruitEntryUI> onSelected;

		public Action<RecruitEntryUI> onClicked;

		public Selectable GetSelectable
		{
			get
			{
				if (_selectable == null)
				{
					_selectable = GetComponentInChildren<Selectable>(includeInactive: true);
				}
				return _selectable;
			}
			private set
			{
				_selectable = value;
			}
		}

		public uint GetCost => cost;

		public PartyMemberSaveData GetSave => save;

		public void Set(PartyMemberSaveData save, uint cost)
		{
			this.save = save;
			this.cost = cost;
			nameText.text = save.playerSaveData.PlayerName;
			costText.text = I2Loca.GetMultiLineFormat("GPAmount", cost.ToString());
			portrait.sprite = GetSprite(save);
		}

		private Sprite GetSprite(PartyMemberSaveData save)
		{
			PreviewSprites previewSprites;
			switch (save.playerSaveData.playerRace)
			{
			case Race.Human:
				previewSprites = spritesHuman;
				break;
			case Race.ShadowElf:
				previewSprites = spritesElf;
				break;
			case Race.HalfOrc:
				previewSprites = spritesOrc;
				break;
			case Race.Cogger:
				previewSprites = spritesCogger;
				break;
			case Race.Imp:
				previewSprites = spritesImp;
				break;
			default:
				previewSprites = default(PreviewSprites);
				UnityEngine.Debug.Log($"Invalid race ({save.playerSaveData.playerRace}) when determining sprite for {save.playerSaveData.playerName}");
				break;
			}
			if (!save.playerSaveData.male)
			{
				return previewSprites.bodyB;
			}
			return previewSprites.bodyA;
		}

		public void Select()
		{
			if (UtilityTG.GetSelected() != base.gameObject)
			{
				UtilityTG.SetSelected(base.gameObject);
			}
			onSelected?.Invoke(this);
		}

		public void Clicked()
		{
			onClicked?.Invoke(this);
		}

		public void OnSelect(BaseEventData eventData)
		{
			Select();
		}
	}
