			{
				PartyMember partyMember = Player.PlayerChar.GetPartyMember(i) as PartyMember;
				if ((bool)partyMember && partyMember.saveUniqueId != 0)
				{
					list.Add(partyMember.saveUniqueId);
				}
			}
			List<SaveData.SaveSlot> list2 = new List<SaveData.SaveSlot>();
			for (int j = 0; j < SaveData.SaveSlots.Count; j++)
			{
				SaveData.SaveSlot saveSlot = SaveData.SaveSlots[j];
				if (saveSlot.IsUniqueIDValid && saveSlot.uniqueId != SaveData.CurrentSaveSlot.uniqueId && saveSlot.saveState == SaveSlotState.Normal && !list.Contains(saveSlot.uniqueId))
				{
					list2.Add(SaveData.SaveSlots[j]);
				}
			}
			for (int k = 0; k < maxMercsFromSaves; k++)
			{
				if (list2.Count == 0)
				{
					break;
				}
				SaveData.SaveSlot randomEntry = list2.GetRandomEntry();
				FateSaveData saveData = randomEntry.saveData;
				mercenaries.Add(new PartyMemberSaveData
				{
					playerSaveData = saveData.playerSaveData.CreatePartyMemberCopy(),
					itemStorage = saveData.itemSaveData.Clone(),
					uniqueSaveId = randomEntry.uniqueId,
					tacticsMode = PartyMember.Tactics.Support
				});
				list2.Remove(randomEntry);
				num++;
			}
			int num2 = generateMercCount - num;
			for (int l = 0; l < num2; l++)
			{
				FateSaveData fateSaveData = PartyMember.GenerateRandomSaveData();
				mercenaries.Add(new PartyMemberSaveData
				{
					playerSaveData = fateSaveData.playerSaveData,
					itemStorage = fateSaveData.itemSaveData,
					uniqueSaveId = 0u,
					tacticsMode = PartyMember.Tactics.Support
				});
			}
			mercenaries.Shuffle();
		}

		public void Show()
		{
			if (mercenaries.Count == 0)
			{
				GenerateMercenaries();
			}
			rightFrameInfoParent.SetActive(mercenaries.Count > 0);
			RefreshRecruitEntries();
			OnInputBehaviorChange(SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior);
			SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Menu);
			base.gameObject.SetActive(value: true);
			if (SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.Recruiter, out var key))
			{
				SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
			}
		}

		private void RefreshRecruitEntries()
		{
			if (recruitEntries == null)
			{
				recruitEntries = new List<RecruitEntryUI> { recruitEntryTemplate };
			}
			int count = mercenaries.Count;
			recruitEntries.AssertComponentCount(count);
			for (int i = 0; i < count; i++)
			{
				PartyMemberSaveData partyMemberSaveData = mercenaries[i];
				RecruitEntryUI recruitEntryUI = recruitEntries[i];
				recruitEntryUI.Set(partyMemberSaveData, GetRecruitCostOfCharacter(partyMemberSaveData));
				recruitEntryUI.gameObject.SetActive(value: true);
				Selectable getSelectable = recruitEntryUI.GetSelectable;
				if (getSelectable != null)
				{
					Selectable selectOnUp = ((i > 0) ? recruitEntries[i - 1].GetSelectable : null);
					Selectable selectOnDown = ((i < count - 1) ? recruitEntries[i + 1].GetSelectable : null);
					Navigation navigation = getSelectable.navigation;
					navigation.mode = Navigation.Mode.Explicit;
					navigation.selectOnUp = selectOnUp;
					navigation.selectOnDown = selectOnDown;
					getSelectable.navigation = navigation;
				}
				recruitEntryUI.onSelected = OnSelectionChanged;
				recruitEntryUI.onClicked = OnRecruitClicked;
			}
			if (mercenaries.Count > 0)
			{
				UtilityTG.UnityDelay(recruitEntries[0].Select);
			}
		}

		public void Hide()
		{
			OnSelectionChanged(null);
			base.gameObject.SetActive(value: false);
			SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Game);
		}

		private void UpdateStats()
		{
			if (selectedRecruitEntry == null)
			{
				return;
			}
			AttributeSave[] attributes = selectedRecruitEntry.GetSave.playerSaveData.attributes;
			int num = 4;
			for (int i = 0; i < num; i++)
			{
				Attribute attribute2 = (Attribute)(i + 1);
				AllySkillEntry allySkillEntry = baseAttributeEntries[i];
				AttributeSave attributeSave = attributes.Find((AttributeSave attribSave) => attribSave.attrib == attribute2);
				if (attributeSave != null)
				{
					allySkillEntry.Set(attributeSave.attrib, attributeSave.baseValue);
				}
			}
			int firstSkillIndex = 8;
			int lastSkillIndex = 22;
			List<AttributeSave> list = attributes.Where(delegate(AttributeSave x)
			{
				int attrib = (int)x.attrib;
				return attrib >= firstSkillIndex && attrib <= lastSkillIndex;
			});
			List<Attribute> list2 = new List<Attribute>();
			for (int j = firstSkillIndex; j <= lastSkillIndex; j++)
			{
				list2.Add((Attribute)j);
			}
			foreach (Attribute attribute in list2)
			{
				if (list.Find((AttributeSave x) => x.attrib == attribute) == null)
				{
					list.Add(new AttributeSave
					{
						attrib = attribute,
						baseValue = 0
					});
				}
			}
			list.Shuffle();
			list.Sort((AttributeSave a, AttributeSave b) => b.baseValue.CompareTo(a.baseValue));
			for (int k = 0; k < topSkillEntries.Length && k < list.Count; k++)
			{
				AttributeSave attributeSave2 = list[k];
				topSkillEntries[k].Set(attributeSave2.attrib, attributeSave2.baseValue);
			}
		}

		private void OnSelectionChanged(RecruitEntryUI entry)
		{
			selectedRecruitEntry = entry;
			bool flag = entry != null;
			rightFrameInfoParent.SetActive(flag);
			if (flag)
			{
				PartyMemberSaveData getSave = selectedRecruitEntry.GetSave;
				nameAndFameHeaderText.text = I2Loca.GetMultiLineFormat("PlayerTitle", getSave.playerSaveData.PlayerName, I2Loca.Get($"Fame{Fate.GetFameTier(getSave.playerSaveData.fame)}"));
				int num = 1 + Fate.GetLevelFromExperience(getSave.playerSaveData.experience);
				levelText.text = num.ToString();
				fameRankText.text = Fate.GetFameTier(getSave.playerSaveData.fame).ToString();
				raceText.text = I2Loca.Get(getSave.playerSaveData.playerRace.ToString());
				int num2 = 18 + 4 * getSave.playerSaveData.attributes.Find((AttributeSave x) => x.attrib == Attribute.Vitality).baseValue + 4 * num;
				lifeText.text = num2.ToString();
				int num3 = 0;
				for (int i = 0; i < getSave.itemStorage.items.Count; i++)
				{
					num3 += getSave.itemStorage.items[i].value / 8;
				}
				equipmentValueText.text = num3.ToString();
				bodyTypeText.text = I2Loca.Get(getSave.playerSaveData.male ? "BodytypeA" : "BodytypeB");
				recruitCostText.text = I2Loca.GetMultiLineFormat("GPAmount", selectedRecruitEntry.GetCost);
				UpdateStats();
			}
		}

		private void OnRecruitClicked(RecruitEntryUI entry)
		{
			OnSelectionChanged(entry);
			if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free && selectedRecruitEntry == entry)
			{
				UtilityTG.UnityDelay(TryRecruitCurrentSelection);
			}
		}

		public void TryRecruitCurrentSelection()
		{
			if (selectedRecruitEntry == null)
			{
				return;
			}
			UtilityTG.SetSelected(null);
			IsPromptOpen = true;
			int partyMemberCount = Player.PlayerChar.GetPartyMemberCount();
			if (partyMemberCount >= Fate.GetMaxPartyMembersByLevel(Player.PlayerChar.Level))
			{
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
				SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton((partyMemberCount >= 3) ? "PartyLimitReached" : "PartyLimitLowLevel", ReturnFromPrompt);
				return;
			}
			if (!SingletonBehaviour<PlayerStatus>.Instance.CanAfford(selectedRecruitEntry.GetCost))
			{
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_lowgold);
				SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("RecruitCostNoGold", ReturnFromPrompt);
				return;
			}
			PartyMemberSaveData getSave = selectedRecruitEntry.GetSave;
			string text = I2Loca.Get("Recruit") + " " + getSave.playerSaveData.PlayerName;
			if (selectedRecruitEntry.GetCost != 0)
			{
				text = text + " for " + I2Loca.GetMultiLineFormat("GPAmount", selectedRecruitEntry.GetCost.ToString());
			}
			text += "?";
			SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(text, delegate(bool confirm)
			{
				if (!confirm)
				{
					ReturnFromPrompt();
				}
				else
				{
					IsPromptOpen = false;
					PartyMemberSaveData getSave2 = selectedRecruitEntry.GetSave;
					Player.PlayerChar.TryRecruitPartyMember(getSave2.playerSaveData, getSave2.itemStorage, getSave2.uniqueSaveId, selectedRecruitEntry.GetCost);
					RemoveRecruitEntry(selectedRecruitEntry);
				}
			}, twoButtons: true);
		}

		private void ReturnFromPrompt()
		{
			IsPromptOpen = false;
			if (selectedRecruitEntry != null)
			{
				UtilityTG.UnityDelay(selectedRecruitEntry.Select);
			}
			else if (mercenaries.Count > 0)
			{
				UtilityTG.UnityDelay(recruitEntries[0].Select);
			}
		}

		private void RemoveRecruitEntry(RecruitEntryUI recruitUI)
		{
			if (selectedRecruitEntry == recruitUI)
			{
				selectedRecruitEntry = null;
			}
			mercenaries.Remove(recruitUI.GetSave);
			RefreshRecruitEntries();
		}

		private uint GetRecruitCostOfCharacter(PartyMemberSaveData saveData)
		{
			float num = 1f;
			int levelFromExperience = Fate.GetLevelFromExperience(saveData.playerSaveData.experience);
			int fameTier = Fate.GetFameTier(saveData.playerSaveData.fame);
			num *= Mathf.Pow(1.02f, levelFromExperience + fameTier);
			num = (Mathf.Pow(num, 1.5f) - 1f) * 10000f + num * (float)(levelFromExperience + fameTier) * 1000f;
			if (num < 1000f)
			{
				num = 1000f;
			}
			int num2 = 0;
			for (int i = 0; i < saveData.itemStorage.items.Count; i++)
			{
				num2 += saveData.itemStorage.items[i].value / 8;
			}
			return (uint)num + (uint)num2;
		}

		public void OnInputBehaviorChange(InputBroker.InputBehavior inputBehavior)
		{
			bool flag = inputBehavior == InputBroker.InputBehavior.Free;
			recruitButton.gameObject.SetActive(!flag);
			closeButton.gameObject.SetActive(!flag);
			controllerHotkeys.gameObject.SetActive(flag);
			if (flag && (selectedRecruitEntry == null || selectedRecruitEntry.gameObject != EventSystem.current.currentSelectedGameObject) && mercenaries.Count > 0)
			{
				recruitEntries[0].Select();
			}
		}
	}
