	public class SkillsUI : MonoBehaviour
	{
		[SerializeField]
		private GameObject pointsIndicator;

		[SerializeField]
		private TextMeshProUGUI pointsText;

		[SerializeField]
		private StatButton entryTemplate;

		[SerializeField]
		private Button backButton;

		private List<StatButton> skillEntries;

		private Character currentChar;

		private InputAction interactAction;

		private void Awake()
		{
			backButton.onClick.AddListener(SimpleSingletonBehaviour<PlayerUI>.Instance.CloseTabs);
		}

		private void OnDestroy()
		{
			if (currentChar != null)
			{
				SetCharacter(null);
			}
		}

		public void UpdateSkills()
		{
			if (currentChar == null)
			{
				return;
			}
			if (currentChar.IsPet())
			{
				HideAll();
				return;
			}
			if (skillEntries == null)
			{
				skillEntries = new List<StatButton> { entryTemplate };
			}
			int num = 15;
			skillEntries.AssertComponentCount(num);
			for (int i = 0; i < num; i++)
			{
				Attribute attribute = (Attribute)(8 + i);
				StatButton statButton = skillEntries[i];
				statButton.Setup(attribute, AttributeDetail.None, currentChar, allowPointSpend: true);
				statButton.gameObject.SetActive(value: true);
			}
			UpdatePointsIndicator();
		}

		private void UpdatePointsIndicator()
		{
			int unusedSkillPoints = currentChar.UnusedSkillPoints;
			pointsIndicator.SetActive(unusedSkillPoints > 0);
			pointsText.text = unusedSkillPoints.ToString();
		}

		private void OnEnable()
		{
			if (currentChar == null)
			{
				SetCharacter(Player.PlayerChar);
			}
			else
			{
				SetCharacter(currentChar);
			}
		}

		public void SetCharacter(Character character)
		{
			if (currentChar == character)
			{
				UpdateSkills();
				return;
			}
			if (currentChar != null)
			{
				AttributeSet attributes = currentChar.attributes;
				attributes.onAttributeValueChanged = (Action<Attribute, int>)Delegate.Remove(attributes.onAttributeValueChanged, new Action<Attribute, int>(OnCharacterAttributeChanged));
			}
			currentChar = character;
			if (currentChar != null)
			{
				AttributeSet attributes2 = currentChar.attributes;
				attributes2.onAttributeValueChanged = (Action<Attribute, int>)Delegate.Combine(attributes2.onAttributeValueChanged, new Action<Attribute, int>(OnCharacterAttributeChanged));
				UpdateSkills();
			}
			else
			{
				HideAll();
			}
		}

		private void HideAll()
		{
			if (skillEntries != null)
			{
				foreach (StatButton skillEntry in skillEntries)
				{
					skillEntry.gameObject.SetActive(value: false);
				}
			}
			pointsIndicator.SetActive(value: false);
		}

		private void OnCharacterAttributeChanged(Attribute attribute, int arg2)
		{
			UpdatePointsIndicator();
		}
	}
	public class SpellbookRadialUI : UIGenericPanel
	{
		[SerializeField]
		private SpellSlot[] spellSlots;

		private SpellSlot initialSelected;

		private bool isClosing;

		protected override void OnTweenInBegin()
		{
			InputBlocker.uiBlockers++;
			base.OnTweenInBegin();
			SpellData getActiveSpell = Player.PlayerChar.GetActiveSpell;
			List<SpellData> activeSpellWheel = Player.PlayerChar.ActiveSpellWheel;
			for (int i = 0; i < spellSlots.Length; i++)
			{
				if (i >= activeSpellWheel.Count || activeSpellWheel[i] == null)
				{
					spellSlots[i].SetClear();
					continue;
				}
				SpellData spell = activeSpellWheel[i];
				if (spell == getActiveSpell)
				{
					initialSelected = spellSlots[i];
				}
				spellSlots[i].Setup(spell, delegate
				{
					if (!Player.PlayerChar.SetActiveSpell(spell))
					{
						SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
					}
				});
			}
		}

		protected override void OnTweenInComplete()
		{
			base.OnTweenInComplete();
			isClosing = false;
		}

		protected override IEnumerator TweenInPanel()
		{
			yield return TweenTG.Tween(base.transform, TransformVector3.LocalScale, Vector3.zero, Vector3.one, -0.2f, Easing.Mode.QuadOut);
		}

		protected override IEnumerator TweenOutPanel()
		{
			int id = TweenTG.Tween(base.transform, TransformVector3.LocalScale, Vector3.one, Vector3.zero, -0.1f);
			yield return new WaitForTween(id);
		}

		protected override void OnTweenOutBegin()
		{
			isClosing = true;
			base.OnTweenOutBegin();
			InputBlocker.uiBlockers--;
			SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.HideTooltip();
		}

		private void Update()
		{
			if (!isClosing && SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior != InputBroker.InputBehavior.ClickToMove && !(SingletonBehaviour<InputBroker>.Instance.LookRaw.magnitude < 0.1f))
			{
				int radialMenuIndex = GetRadialMenuIndex(SingletonBehaviour<InputBroker>.Instance.LookRaw);
				UtilityTG.SetSelected(spellSlots[radialMenuIndex].gameObject);
				if (spellSlots[radialMenuIndex].ActiveSpell != null && !Player.PlayerChar.SetActiveSpell(spellSlots[radialMenuIndex].ActiveSpell))
				{
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
				}
			}
		}

		private int GetRadialMenuIndex(Vector2 input)
		{
			Vector2 normalized = new Vector2(0f - input.x, input.y).normalized;
			float num = Mathf.Atan2(normalized.y, normalized.x) * 57.29578f - 60f;
			if (num < 0f)
			{
				num += 360f;
			}
			int num2 = spellSlots.Length;
			float num3 = 360f / (float)num2;
			return (int)(num / num3);
		}

		private float GetArrowRotationAngle(int slotIndex)
		{
			int num = 6;
			float num2 = 360f / (float)num;
			return (20f + ((float)slotIndex * num2 + num2 / 2f)) % 360f;
		}
	}
	public class SpellbookUI : MonoBehaviour
	{
		public SpellSlot[] attackSlots;

		public SpellSlot[] defenceSlots;

		public SpellSlot[] charmSlots;

		public SpellSlot[] quickSlots;

		public SpellSlot[] allSlots;

		public SpellSlot activeSpellSlot;

		public Button backButton;

		[SerializeField]
		private GameObject leftSideWheel;

		[SerializeField]
		private GameObject leftSideEmpty;

		[SerializeField]
		private GameObject activeSpellContent;

		[SerializeField]
		private PartyCharacterInScreenUI[] characterButtons;

		[SerializeField]
		private GameObject[] playerOnlyHints;

		[SerializeField]
		private GameObject inputHintsRegular;

		[SerializeField]
		private GameObject inputHintsAssigning;

		private SpellData spellBeingAssigned;

		private Character currentCharacter;

		private void Awake()
		{
			Init();
		}

		private void Init()
		{
			backButton.onClick.AddListener(delegate
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.CloseTabs();
			});
			PartyCharacterInScreenUI[] array = characterButtons;
			foreach (PartyCharacterInScreenUI obj in array)
			{
				obj.onClicked = (Action<Character>)Delegate.Combine(obj.onClicked, (Action<Character>)delegate(Character character)
				{
					SetCharacter(character);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				});
			}
			int num = 0;
			allSlots = new SpellSlot[18];
			SpellSlot[] array2 = attackSlots;
			foreach (SpellSlot spellSlot in array2)
			{
				allSlots[num++] = spellSlot;
			}
			array2 = defenceSlots;
			foreach (SpellSlot spellSlot2 in array2)
			{
				allSlots[num++] = spellSlot2;
			}
			array2 = charmSlots;
			foreach (SpellSlot spellSlot3 in array2)
			{
				allSlots[num++] = spellSlot3;
			}
		}

		private void UpdateCharacterButtonList()
		{
			Player playerChar = Player.PlayerChar;
			characterButtons[0].SetChar(playerChar);
			characterButtons[1].SetChar(playerChar.GetPet());
			for (int i = 2; i < characterButtons.Length; i++)
			{
				bool flag = i - 2 < playerChar.GetPartyMemberCount();
				PartyCharacterInScreenUI partyCharacterInScreenUI = characterButtons[i];
				partyCharacterInScreenUI.gameObject.SetActive(flag);
				if (flag)
				{
					partyCharacterInScreenUI.SetChar(playerChar.GetPartyMember(i - 2));
				}
			}
		}

		private void OnEnable()
		{
			UpdateCharacterButtonList();
			SetCharacter(PlayerUI.GetLatestSelectedCharacterInParty());
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.RightClick.performed += RightClickPerformed;
			inputHintsRegular.SetActive(value: true);
			inputHintsAssigning.SetActive(value: false);
		}

		private void OnDisable()
		{
			ClearAssigningSpell();
			if (SingletonBehaviour<CursorManager>.InstanceExists())
			{
				SingletonBehaviour<CursorManager>.Instance.SetMode(CursorManager.CursorMode.Standard);
			}
			if (SingletonBehaviour<CursorTooltip>.InstanceExists())
			{
				SingletonBehaviour<CursorTooltip>.Instance.Hide();
			}
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.RightClick.performed -= RightClickPerformed;
			}
		}

		private void RightClickPerformed(InputAction.CallbackContext context)
		{
			if (!currentCharacter.IsPlayer() || !SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.RightClick.WasPerformedThisFrame())
			{
				return;
			}
			GameObject selected = UtilityTG.GetSelected();
			SpellSlot spellSlot = ((selected == null) ? null : selected.GetComponentInParent<SpellSlot>());
			if (!quickSlots.Contains(spellSlot))
			{
				if (selected != null && spellSlot != null && spellSlot.ActiveSpell != null)
				{
					BeginAssigningSpell(spellSlot);
					return;
				}
				ClearAssigningSpell();
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
			}
		}

		private void BeginAssigningSpell(SpellSlot slot)
		{
			ClearAssigningFeedbackFromAllSlots();
			HighlightQuickSlots(highlight: true);
			slot.ShowAssignMarker(show: true);
			spellBeingAssigned = slot.ActiveSpell;
			SingletonBehaviour<CursorManager>.Instance.SetMode(CursorManager.CursorMode.SpellAssign);
			SingletonBehaviour<CursorTooltip>.Instance.Show(CursorTooltip.Mode.AssignToSpellWheel);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			inputHintsRegular.SetActive(value: false);
			inputHintsAssigning.SetActive(value: true);
		}

		private void ClearAssigningFeedbackFromAllSlots()
		{
			activeSpellSlot.ShowAssignMarker(show: false);
			SpellSlot[] array = allSlots;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].ShowAssignMarker(show: false);
			}
		}

		private void HighlightQuickSlots(bool highlight)
		{
			SpellSlot[] array = quickSlots;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].ShowAssignMarker(highlight);
			}
		}

		private void ClearAssigningSpell()
		{
			HighlightQuickSlots(highlight: false);
			ClearAssigningFeedbackFromAllSlots();
			spellBeingAssigned = null;
			SingletonBehaviour<CursorManager>.Instance.SetMode(CursorManager.CursorMode.Standard);
			SingletonBehaviour<CursorTooltip>.Instance.Hide();
			inputHintsRegular.SetActive(value: true);
			inputHintsAssigning.SetActive(value: false);
		}

		public bool OnMenuButtonRelay()
		{
			if (spellBeingAssigned != null)
			{
				ClearAssigningSpell();
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
				return true;
			}
			return false;
		}

		public void OnAltInteract()
		{
			if (currentCharacter.IsPet())
			{
				return;
			}
			GameObject selected = UtilityTG.GetSelected();
			if (!(selected != null))
			{
				return;
			}
			SpellSlot spellSlot = selected.GetComponentInParent<SpellSlot>();
			if (currentCharacter.IsPlayer())
			{
				int num = quickSlots.FindIndex((SpellSlot sp) => sp == spellSlot);
				if (num != -1)
				{
					spellSlot.SetClear();
					spellSlot.SetOnSlotClicked(delegate
					{
						OnQuickSlotClicked(spellSlot);
					});
					Player.PlayerChar.SetSpellWheelSpell(num, null);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
				}
				else if (spellSlot != null && spellSlot.ActiveSpell != null)
				{
					PromptRemoveSpell(spellSlot.ActiveSpell);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				}
			}
			else
			{
				PromptRemoveSpell(spellSlot.ActiveSpell);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			}
		}

		public void SetCharacter(Character character)
		{
			if (character.IsPet())
			{
				SetCharacter(Player.PlayerChar);
				return;
			}
			ClearAssigningSpell();
			currentCharacter = character;
			for (int i = 0; i < characterButtons.Length; i++)
			{
				PartyCharacterInScreenUI obj = characterButtons[i];
				bool flag = obj.CurrentCharacter == character;
				obj.ShowSelectedVisuals(flag);
				if (flag)
				{
					PlayerUI.LatestSelectedMemberIndex = i;
				}
			}
			bool flag2 = character.IsPlayer();
			activeSpellContent.SetActive(flag2);
			leftSideWheel.SetActive(flag2);
			leftSideEmpty.SetActive(!flag2);
			ShowAssignHints(flag2);
			UpdateSpells();
		}

		private void ShowAssignHints(bool show)
		{
			GameObject[] array = playerOnlyHints;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(show);
			}
		}

		private void UpdateSpells()
		{
			Dictionary<SpellSphere, List<SpellData>> knownSpells = currentCharacter.knownSpells;
			List<SpellSlot> list = new List<SpellSlot>(attackSlots);
			list.AddRange(defenceSlots);
			list.AddRange(charmSlots);
			foreach (KeyValuePair<SpellSphere, List<SpellData>> item in knownSpells)
			{
				if (item.Value == null || item.Key == SpellSphere.Rage)
				{
					continue;
				}
				SpellSlot[] array = item.Key switch
				{
					SpellSphere.Attack => attackSlots, 
					SpellSphere.Defense => defenceSlots, 
					SpellSphere.Charm => charmSlots, 
					_ => null, 
				};
				for (int i = 0; i < 6; i++)
				{
					if (item.Value.Count > i)
					{
						SpellData spell = item.Value[i];
						array[i].Setup(spell, delegate
						{
							OnSpellClicked(spell);
						});
						list.Remove(array[i]);
					}
				}
			}
			for (int j = 0; j < list.Count; j++)
			{
				list[j].SetClear();
			}
			if (!currentCharacter.IsPlayer())
			{
				return;
			}
			if (Player.PlayerChar.activeSpell == null || Player.PlayerChar.activeSpell.sphereType == SpellSphere.Rage)
			{
				activeSpellSlot.SetClear();
			}
			else
			{
				activeSpellSlot.Setup(Player.PlayerChar.activeSpell, null);
			}
			List<SpellData> activeSpellWheel = Player.PlayerChar.ActiveSpellWheel;
			for (int k = 0; k < quickSlots.Length; k++)
			{
				SpellData spellData = ((activeSpellWheel.Count > k) ? activeSpellWheel[k] : null);
				SpellSlot slot = quickSlots[k];
				quickSlots[k].Setup(spellData, delegate
				{
					OnQuickSlotClicked(slot);
				});
			}
		}

		private void OnSpellClicked(SpellData spell)
		{
			if (Input.GetKey(KeyCode.LeftControl))
			{
				PromptRemoveSpell(spell);
			}
			else if (currentCharacter.IsPlayer())
			{
				if (Player.PlayerChar.SetActiveSpell(spell))
				{
					activeSpellSlot.Setup(spell, null);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.GivePoint, randomizePitch: false);
				}
				else
				{
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Fail, randomizePitch: false);
					SingletonBehaviour<Narrator>.Instance.PlayYourLine(NarratorLines.Narrator_impossible);
				}
			}
		}

		private void OnQuickSlotClicked(SpellSlot slot)
		{
			if (Input.GetKey(KeyCode.LeftControl))
			{
				slot.SetClear();
				slot.SetOnSlotClicked(delegate
				{
					OnQuickSlotClicked(slot);
				});
				Player.PlayerChar.SetSpellWheelSpell(quickSlots.FindIndex((SpellSlot sl) => sl == slot), null);
			}
			else if (spellBeingAssigned != null)
			{
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.GivePoint, randomizePitch: false);
				slot.SetSpell(spellBeingAssigned);
				Player.PlayerChar.SetSpellWheelSpell(quickSlots.FindIndex((SpellSlot sl) => sl == slot), spellBeingAssigned);
				ClearAssigningSpell();
			}
		}

		private void PromptRemoveSpell(SpellData spell)
		{
			ClearAssigningSpell();
			string body = I2Loca.Get("RemoveSpellHintGamepad") + Environment.NewLine + I2Loca.Get(spell.spellName);
			SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(body, delegate(bool positive)
			{
				if (positive)
				{
					if (activeSpellSlot.ActiveSpell == spell)
					{
						activeSpellSlot.SetClear();
					}
					currentCharacter.RemoveSpell(spell);
					SpellSlot[] array = spell.sphereType switch
					{
						SpellSphere.Attack => attackSlots, 
						SpellSphere.Defense => defenceSlots, 
						SpellSphere.Charm => charmSlots, 
						_ => null, 
					};
					for (int i = 0; i < array.Length; i++)
					{
						if (array[i].ActiveSpell == spell)
						{
							array[i].SetClear();
						}
					}
					if (currentCharacter.IsPlayer())
					{
						for (int j = 0; j < quickSlots.Length; j++)
						{
							SpellSlot quickSlot = quickSlots[j];
							if (quickSlot.ActiveSpell == spell)
							{
								quickSlot.SetClear();
								quickSlot.SetOnSlotClicked(delegate
								{
									OnQuickSlotClicked(quickSlot);
								});
								Player.PlayerChar.SetSpellWheelSpell(j, null);
							}
						}
					}
					SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.HideTooltip();
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.GivePoint, randomizePitch: false);
				}
			}, twoButtons: true);
		}
	}
	public class SpellSlot : MonoBehaviour, ISelectHandler, IEventSystemHandler, IDeselectHandler, IPointerClickHandler, IPointerEnterHandler, IPointerExitHandler
	{
		public Image slotIcon;

		public GameObject assignMarker;

		public Action onClick;

		public GameObject[] selectedToggles;

		public SpellData ActiveSpell { get; private set; }

		public void OnDeselect(BaseEventData eventData)
		{
			GameObject[] array = selectedToggles;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: false);
			}
		}

		public void OnSelect(BaseEventData eventData)
		{
			GameObject[] array = selectedToggles;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: true);
			}
		}

		private void OnEnable()
		{
			GameObject[] array = selectedToggles;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: false);
			}
		}

		public void SetClear()
		{
			slotIcon.gameObject.SetActive(value: false);
			onClick = null;
			GetComponent<SpellTooltipOnSelect>().spellData = null;
		}

		public void SetSpell(SpellData spellData)
		{
			ActiveSpell = spellData;
			Sprite sprite = SingletonBehaviour<FateDB>.Instance.spriteStash.Find((Sprite sp) => sp.name == spellData.IconName);
			if (sprite == null)
			{
				UnityEngine.Debug.LogError("No Sprite for spell: " + spellData.spellName);
			}
			slotIcon.sprite = sprite;
			slotIcon.gameObject.SetActive(value: true);
			GetComponent<SpellTooltipOnSelect>().spellData = spellData;
		}

		public void Setup(SpellData spellData, Action onSpellSlotClicked)
		{
			if (spellData == null)
			{
				SetClear();
			}
			else
			{
				SetSpell(spellData);
			}
			onClick = onSpellSlotClicked;
		}

		public void SetOnSlotClicked(Action onSpellSlotClicked)
		{
			onClick = onSpellSlotClicked;
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			onClick?.Invoke();
		}

		public void OnPointerEnter(PointerEventData eventData)
		{
			UtilityTG.SetSelected(base.gameObject);
		}

		public void OnPointerExit(PointerEventData eventData)
		{
			UtilityTG.SetSelected(null);
		}

		public void ShowAssignMarker(bool show)
		{
			if (!(assignMarker == null))
			{
				assignMarker.SetActive(show);
			}
		}
	}
	public class StatButton : MonoBehaviour
	{
		public enum Type
		{
			Stat,
			Skill,
			AttributeDetail
		}

		[SerializeField]
		private Button button;

		[SerializeField]
		private TextMeshProUGUI labelText;

		[SerializeField]
		private TextMeshProUGUI valueText;

		[SerializeField]
		private SkillTooltipOnSelect tooltip;

		[SerializeField]
		private Image overlayImage;

		[SerializeField]
		private Sprite overlaySpriteGood;

		[SerializeField]
		private Sprite overlaySpriteBad;

		[SerializeField]
		private GameObject spendPointIndicator;

		private bool hasInitialized;

		private Attribute attribute;

		private AttributeDetail attributeDetail;

		private Character character;

		private Type type;

		private bool allowPointSpend;

		private void Init()
		{
			if (!hasInitialized)
			{
				if (allowPointSpend && attribute != 0)
				{
					button.onClick.AddListener(TrySpendStatPoint);
				}
				spendPointIndicator.SetActive(value: false);
				hasInitialized = true;
			}
		}

		private void OnDestroy()
		{
			if (character != null)
			{
				Character obj = character;
				obj.onEquipmentChanged = (Action)Delegate.Remove(obj.onEquipmentChanged, new Action(OnCharacterEquipmentChanged));
				AttributeSet attributes = character.attributes;
				attributes.onAttributeValueChanged = (Action<Attribute, int>)Delegate.Remove(attributes.onAttributeValueChanged, new Action<Attribute, int>(OnCharacterAttributeChanged));
				Character obj2 = character;
				obj2.onEffectApplied = (Action<AppliedEffect>)Delegate.Remove(obj2.onEffectApplied, new Action<AppliedEffect>(OnAppliedEffect));
				Character obj3 = character;
				obj3.onEffectRemoved = (Action<AppliedEffect>)Delegate.Remove(obj3.onEffectRemoved, new Action<AppliedEffect>(OnAppliedEffect));
				character = null;
			}
		}

		private void TrySpendStatPoint()
		{
			if (type == Type.Stat)
			{
				if (character.UnusedStatPoint > 0)
				{
					character.SpendPoint(attribute);
					tooltip.ShowTooltip();
				}
			}
			else if (type == Type.Skill && character.UnusedSkillPoints > 0)
			{
				character.SpendPoint(attribute);
				tooltip.ShowTooltip();
			}
		}

		public void Setup(Attribute attribute, AttributeDetail attributeDetail, Character character, bool allowPointSpend)
		{
			Character character2 = this.character;
			if (character2 != null)
			{
				character2.onEquipmentChanged = (Action)Delegate.Remove(character2.onEquipmentChanged, new Action(OnCharacterEquipmentChanged));
				AttributeSet attributes = character2.attributes;
				attributes.onAttributeValueChanged = (Action<Attribute, int>)Delegate.Remove(attributes.onAttributeValueChanged, new Action<Attribute, int>(OnCharacterAttributeChanged));
			}
			this.attribute = attribute;
			this.attributeDetail = attributeDetail;
			this.character = character;
			tooltip.attribute = attribute;
			tooltip.attributeDetail = attributeDetail;
			tooltip.character = character;
			type = ((attributeDetail == AttributeDetail.None) ? Type.Skill : Type.AttributeDetail);
			if ((uint)(attribute - 1) <= 3u)
			{
				type = Type.Stat;
			}
			this.allowPointSpend = allowPointSpend;
			Init();
			UpdateAll();
			if (character != null)
			{
				character.onEquipmentChanged = (Action)Delegate.Combine(character.onEquipmentChanged, new Action(OnCharacterEquipmentChanged));
				AttributeSet attributes2 = character.attributes;
				attributes2.onAttributeValueChanged = (Action<Attribute, int>)Delegate.Combine(attributes2.onAttributeValueChanged, new Action<Attribute, int>(OnCharacterAttributeChanged));
				character.onEffectApplied = (Action<AppliedEffect>)Delegate.Combine(character.onEffectApplied, new Action<AppliedEffect>(OnAppliedEffect));
				character.onEffectRemoved = (Action<AppliedEffect>)Delegate.Combine(character.onEffectRemoved, new Action<AppliedEffect>(OnAppliedEffect));
			}
		}

		private void UpdateAll()
		{
			if (attributeDetail != 0)
			{
				if (attributeDetail == AttributeDetail.DamageRange2)
				{
					bool isDualWielding = character.IsDualWielding;
					base.gameObject.SetActive(isDualWielding);
					if (!isDualWielding)
					{
						return;
					}
				}
				if (attributeDetail == AttributeDetail.Dodge)
				{
					labelText.text = I2Loca.Get("Defense");
				}
				else
				{
					labelText.text = I2Loca.Get($"{attributeDetail}");
				}
				int num2;
				int num;
				switch (attributeDetail)
				{
				case AttributeDetail.DamageRange:
				{
					Range damageRangeForStats = character.GetDamageRangeForStats(withEffects: false);
					Range damageRangeForStats2 = character.GetDamageRangeForStats(withEffects: true);
					num2 = (int)damageRangeForStats2.GetAverage();
					num = (int)damageRangeForStats.GetAverage();
					valueText.text = damageRangeForStats2.ToString();
					break;
				}
				case AttributeDetail.DamageRange2:
				{
					Range damageRangeForStatsOffhand = character.GetDamageRangeForStatsOffhand(withEffects: false);
					Range damageRangeForStatsOffhand2 = character.GetDamageRangeForStatsOffhand(withEffects: true);
					num2 = (int)damageRangeForStatsOffhand2.GetAverage();
					num = (int)damageRangeForStatsOffhand.GetAverage();
					valueText.text = damageRangeForStatsOffhand2.ToString();
					break;
				}
				case AttributeDetail.AttackRating:
					num = character.ToHit(useBestWeapon: true, withEffects: false);
					num2 = character.ToHit(useBestWeapon: true);
					valueText.text = num2.ToString();
					break;
				case AttributeDetail.Dodge:
					num = character.AC(withEffects: false);
					num2 = character.AC();
					valueText.text = num2.ToString();
					break;
				case AttributeDetail.Stamina:
					num = character.MaxStamina(withEffects: false);
					num2 = character.MaxStamina();
					valueText.text = num2.ToString();
					break;
				case AttributeDetail.HP:
					num = character.MaxHP(withEffects: false);
					num2 = character.MaxHP();
					valueText.text = num2.ToString();
					break;
				case AttributeDetail.Mana:
					num = character.MaxMana(withEffects: false);
					num2 = character.MaxMana();
					valueText.text = num2.ToString();
					break;
				default:
					throw new Exception($"Unhandled enum value {attributeDetail}");
				}
				int num3 = num2 - num;
				if (num3 == 0)
				{
					overlayImage.color = Color.clear;
				}
				else
				{
					overlayImage.color = Color.white;
					overlayImage.sprite = ((num3 > 0) ? overlaySpriteGood : overlaySpriteBad);
				}
			}
			else
			{
				labelText.text = I2Loca.Get($"{this.attribute}");
				Attribute attribute = this.attribute;
				if ((uint)(attribute - 1) > 3u && (uint)(attribute - 8) > 14u)
				{
					throw new Exception($"Unhandled enum value {this.attribute}");
				}
				string text = character.attributes.GetAttribute(this.attribute, allowEffects: true).ToString();
				valueText.text = text;
				int num4 = character.attributes.GetAttribute(this.attribute, allowEffects: false);
				int num5 = character.attributes.GetAttribute(this.attribute, allowEffects: true) - num4;
				if (num5 == 0)
				{
					overlayImage.color = Color.clear;
				}
				else
				{
					overlayImage.color = Color.white;
					overlayImage.sprite = ((num5 > 0) ? overlaySpriteGood : overlaySpriteBad);
				}
			}
			UpdatePointsIndicator();
		}

		private void UpdatePointsIndicator()
		{
			if (type != Type.AttributeDetail && allowPointSpend)
			{
				spendPointIndicator.SetActive((type == Type.Stat) ? (character.UnusedStatPoint > 0) : (character.UnusedSkillPoints > 0));
			}
		}

		private void OnCharacterEquipmentChanged()
		{
			UpdateAll();
		}

		private void OnCharacterAttributeChanged(Attribute attribute, int arg2)
		{
			UpdateAll();
		}

		private void OnAppliedEffect(AppliedEffect effect)
		{
			UpdateAll();
		}
	}
	public class StatsAndSkillsScreenUI : MonoBehaviour
	{
		[SerializeField]
		private StatsUI statsUI;

		[SerializeField]
		private SkillsUI skillsUI;

		[SerializeField]
		private PartyCharacterInScreenUI[] characterButtons;

		[SerializeField]
		private GameObject rightSidePlayerOrAllySkills;

		[SerializeField]
		private GameObject rightSidePetSkills;

		private bool hasInitialized;

		private void Awake()
		{
			Init();
		}

		private void Init()
		{
			if (hasInitialized)
			{
				return;
			}
			PartyCharacterInScreenUI[] array = characterButtons;
			foreach (PartyCharacterInScreenUI obj in array)
			{
				obj.onClicked = (Action<Character>)Delegate.Combine(obj.onClicked, (Action<Character>)delegate(Character character)
				{
					SetCharacter(character);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				});
			}
			hasInitialized = true;
		}

		private void OnEnable()
		{
			UpdateCharacterButtonList();
			Player playerChar = Player.PlayerChar;
			playerChar.onPartyChanged = (Action)Delegate.Combine(playerChar.onPartyChanged, new Action(UpdateCharacterButtonList));
		}

		private void OnDisable()
		{
			if (Player.PlayerChar != null)
			{
				Player playerChar = Player.PlayerChar;
				playerChar.onPartyChanged = (Action)Delegate.Remove(playerChar.onPartyChanged, new Action(UpdateCharacterButtonList));
			}
		}

		private void UpdateCharacterButtonList()
		{
			Player playerChar = Player.PlayerChar;
			characterButtons[0].SetChar(playerChar);
			characterButtons[1].SetChar(playerChar.GetPet());
			for (int i = 2; i < characterButtons.Length; i++)
			{
				bool flag = i - 2 < playerChar.GetPartyMemberCount();
				PartyCharacterInScreenUI partyCharacterInScreenUI = characterButtons[i];
				partyCharacterInScreenUI.gameObject.SetActive(flag);
				if (flag)
				{
					partyCharacterInScreenUI.SetChar(playerChar.GetPartyMember(i - 2));
				}
			}
			SetCharacter(PlayerUI.GetLatestSelectedCharacterInParty());
		}

		public void SetCharacter(Character character)
		{
			statsUI.SetCharacter(character);
			skillsUI.SetCharacter(character);
			for (int i = 0; i < characterButtons.Length; i++)
			{
				PartyCharacterInScreenUI obj = characterButtons[i];
				bool flag = obj.CurrentCharacter == character;
				obj.ShowSelectedVisuals(flag);
				if (flag)
				{
					PlayerUI.LatestSelectedMemberIndex = i;
				}
			}
			bool flag2 = character.IsPet();
			rightSidePetSkills.SetActive(flag2);
			rightSidePlayerOrAllySkills.SetActive(!flag2);
		}
	}
