			auraTemplate.gameObject.SetActive(value: false);
			if (!allowPointSpend)
			{
				pointsIndicator.SetActive(value: false);
			}
			dismissButton.onClick.AddListener(delegate
			{
				SingletonBehaviour<PromptUI>.Instance.ShowPrompt("DismissPromptBody", delegate(bool positive)
				{
					if (positive)
					{
						Player.PlayerChar.DismissPartyMember(currentChar);
					}
				});
			});
			hasInitialized = true;
		}

		private void OnDestroy()
		{
			if (currentChar != null)
			{
				SetCharacter(null);
			}
		}

		private void TrySpendStatPoint(Attribute targetAttribute)
		{
			if (Player.PlayerChar.UnusedStatPoint > 0)
			{
				Player.PlayerChar.SpendPoint(targetAttribute);
				UpdateStats();
			}
		}

		public void UpdateStats()
		{
			if (!(currentChar == null))
			{
				levelText.text = currentChar.Level.ToString();
				expText.text = currentChar.experience.ToString();
				nextLvlText.text = Fate.GetExperienceNeeded(currentChar.Level).ToString();
				if (currentChar.IsPet())
				{
					fameParent.SetActive(value: false);
				}
				else
				{
					fameParent.SetActive(value: true);
					renownText.text = Fate.GetFameName(currentChar.fameRank);
					fameText.text = currentChar.fame.ToString();
					nextFameText.text = Fate.GetFameNeeded(currentChar.fameRank + 1).ToString();
				}
				strButton.Setup(Attribute.Strength, AttributeDetail.None, currentChar, allowPointSpend);
				dexButton.Setup(Attribute.Dexterity, AttributeDetail.None, currentChar, allowPointSpend);
				vitButton.Setup(Attribute.Vitality, AttributeDetail.None, currentChar, allowPointSpend);
				magicButton.Setup(Attribute.Magic, AttributeDetail.None, currentChar, allowPointSpend);
				dmgButton.Setup(Attribute.None, AttributeDetail.DamageRange, currentChar, allowPointSpend);
				dmgOffhandButton.Setup(Attribute.None, AttributeDetail.DamageRange2, currentChar, allowPointSpend);
				attackButton.Setup(Attribute.None, AttributeDetail.AttackRating, currentChar, allowPointSpend);
				defenseButton.Setup(Attribute.None, AttributeDetail.Dodge, currentChar, allowPointSpend);
				hpButton.Setup(Attribute.None, AttributeDetail.HP, currentChar, allowPointSpend);
				staminaButton.Setup(Attribute.None, AttributeDetail.Stamina, currentChar, allowPointSpend);
				manaButton.Setup(Attribute.None, AttributeDetail.Mana, currentChar, allowPointSpend);
				UpdatePointsIndicator();
			}
		}

		private void UpdatePointsIndicator()
		{
			int unusedStatPoint = currentChar.UnusedStatPoint;
			pointsIndicator.SetActive(unusedStatPoint > 0);
			pointsText.text = unusedStatPoint.ToString();
		}

		private void OnEnable()
		{
			if (currentChar == null)
			{
				SetCharacter(Player.PlayerChar);
			}
		}

		private void UpdateAuras()
		{
			if (currentChar == null)
			{
				return;
			}
			List<AppliedEffect> effects = currentChar.GetEffects();
			if (effects != null)
			{
				effects = effects.FindAll((AppliedEffect e) => !string.IsNullOrEmpty(e.sourceSpriteName) && !e.Permanent && e.itemSlotIndex == -1);
				if (effects != null && effects.Count > 0)
				{
					activeAuras.AssertComponentCount(effects.Count);
					int i = 0;
					while (i < effects.Count)
					{
						AppliedEffect appliedEffect = effects[i];
						AuraUI auraUI = activeAuras[i];
						Sprite sprite = SingletonBehaviour<FateDB>.Instance.spriteStash.Find((Sprite s) => s.name == effects[i].sourceSpriteName);
						auraUI.Setup(sprite, null, appliedEffect.sourceEffect.GenerateTooltipString(EffectData.TooltipSource.Spell, appliedEffect.level), appliedEffect.duration);
						auraUI.gameObject.SetActive(value: true);
						int num = i + 1;
						i = num;
					}
				}
				else
				{
					if (activeAuras == null)
					{
						return;
					}
					foreach (AuraUI activeAura in activeAuras)
					{
						activeAura.gameObject.SetActive(value: false);
					}
				}
			}
			else
			{
				if (activeAuras == null)
				{
					return;
				}
				foreach (AuraUI activeAura2 in activeAuras)
				{
					activeAura2.gameObject.SetActive(value: false);
				}
			}
		}

		private void OnDisable()
		{
			SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.HideTooltip();
		}

		public void SetCharacter(Character character)
		{
			Init();
			if (currentChar == character)
			{
				UpdateStats();
				UpdateAuras();
				return;
			}
			if (currentChar != null)
			{
				AttributeSet attributes = currentChar.attributes;
				attributes.onAttributeValueChanged = (Action<Attribute, int>)Delegate.Remove(attributes.onAttributeValueChanged, new Action<Attribute, int>(OnCharacterAttributeChanged));
				Character character2 = currentChar;
				character2.onEffectApplied = (Action<AppliedEffect>)Delegate.Remove(character2.onEffectApplied, new Action<AppliedEffect>(OnEffectsChanged));
				Character character3 = currentChar;
				character3.onEffectRemoved = (Action<AppliedEffect>)Delegate.Remove(character3.onEffectRemoved, new Action<AppliedEffect>(OnEffectsChanged));
			}
			currentChar = character;
			UpdateStats();
			if (currentChar != null)
			{
				AttributeSet attributes2 = currentChar.attributes;
				attributes2.onAttributeValueChanged = (Action<Attribute, int>)Delegate.Combine(attributes2.onAttributeValueChanged, new Action<Attribute, int>(OnCharacterAttributeChanged));
				Character character4 = currentChar;
				character4.onEffectApplied = (Action<AppliedEffect>)Delegate.Combine(character4.onEffectApplied, new Action<AppliedEffect>(OnEffectsChanged));
				Character character5 = currentChar;
				character5.onEffectRemoved = (Action<AppliedEffect>)Delegate.Combine(character5.onEffectRemoved, new Action<AppliedEffect>(OnEffectsChanged));
				if (currentChar.IsPlayer() && currentChar.UnusedStatPoint > 0 && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.LevelUp2, out var key))
				{
					SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
				}
				dismissButton.gameObject.SetActive(currentChar.IsPartyMember());
			}
			UpdateAuras();
		}

		private void OnCharacterAttributeChanged(Attribute attribute, int arg2)
		{
			UpdatePointsIndicator();
		}

		private void OnEffectsChanged(AppliedEffect _)
		{
			if (base.gameObject.activeInHierarchy)
			{
				UpdateAuras();
			}
		}
	}
	public class SummonUI : MonoBehaviour
	{
		[SerializeField]
		private TextMeshProUGUI headerText;

		[SerializeField]
		private GameObject middleImage;

		[SerializeField]
		private GameObject[] summonsUI;

		private Player player;

		private int count;

		private void Start()
		{
			GameObject[] array = summonsUI;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: false);
			}
		}

		public void SetPlayer(Player newPlayer)
		{
			Player player = this.player;
			if (player != null)
			{
				player.onSummonsChanged = (Action)Delegate.Remove(player.onSummonsChanged, new Action(UpdateSummons));
			}
			this.player = newPlayer;
			if (this.player != null)
			{
				newPlayer.onSummonsChanged = (Action)Delegate.Combine(newPlayer.onSummonsChanged, new Action(UpdateSummons));
				UpdateSummons();
				return;
			}
			GameObject[] array = summonsUI;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: false);
			}
		}

		private void UpdateSummons()
		{
			if (player == null)
			{
				return;
			}
			GameObject[] array = summonsUI;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].SetActive(value: false);
			}
			StopAllCoroutines();
			headerText.text = "Summons 0/" + Fate.MaxSummons;
			headerText.gameObject.SetActive(value: false);
			middleImage.SetActive(value: false);
			count = 0;
			for (int j = 0; j < player.GetPetCount(); j++)
			{
				if (player.GetPet(j).IsSummoned())
				{
					SetUI(player.GetPet(j));
				}
			}
			RectTransform obj = base.transform as RectTransform;
			obj.anchoredPosition = obj.anchoredPosition.WithY(10f + 45f * (float)count);
		}

		private void SetUI(Character summon)
		{
			count++;
			headerText.text = "Summons " + count + "/" + Fate.MaxSummons;
			headerText.gameObject.SetActive(value: true);
			middleImage.SetActive(value: true);
			GameObject[] array = summonsUI;
			foreach (GameObject gameObject in array)
			{
				if (!gameObject.activeSelf)
				{
					gameObject.SetActive(value: true);
					TextMeshProUGUI[] componentsInChildren = gameObject.GetComponentsInChildren<TextMeshProUGUI>();
					if (componentsInChildren != null && componentsInChildren.Length > 1)
					{
						componentsInChildren[0].text = I2Loca.Get(summon.CharacterName);
						StartCoroutine(UpdateLifeDuration(componentsInChildren[1], summon));
					}
					HealthOnlyBar componentInChildren = gameObject.GetComponentInChildren<HealthOnlyBar>();
					if (componentInChildren != null)
					{
						componentInChildren.Show(summon.MyVitals);
					}
					break;
				}
			}
		}

		private IEnumerator UpdateLifeDuration(TextMeshProUGUI textToUpdate, Character summonToFollow)
		{
			while (true)
			{
				TimeSpan timeSpan = TimeSpan.FromSeconds(summonToFollow.GetLifeDuration());
				textToUpdate.text = $"{timeSpan.Minutes:D2}:{timeSpan.Seconds:D2}";
				yield return null;
			}
		}
	}
	public class TargetBar : MonoBehaviour
	{
		private const float Timeout = 2f;

		public RectTransform hpBarParentRT;

		public RectTransform hpBarFill;

		public RectTransform poisonBarFill;

		public TextMeshProUGUI nameText;

		public TextMeshProUGUI levelText;

		public TextMeshProUGUI resistanceTemplate;

		public GameObject enemyOnlyParent;

		public GameObject bossIndicator;

		public Color normalNameColor;

		public Color bossNameColor;

		[Header("Ranked Up")]
		public GameObject rankedUpIndicator;

		public TextMeshProUGUI rankText;

		public Image rankImage;

		public Sprite eliteSprite;

		public Sprite legendarySprite;

		public Color eliteColor;

		public Color legendaryColor;

		private CharacterVitals activeVitals;

		private List<TextMeshProUGUI> resistanceTexts;

		public void Show(CharacterVitals vitals)
		{
			if (activeVitals != null)
			{
				CharacterVitals characterVitals = activeVitals;
				characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(OnDamaged));
				CharacterVitals characterVitals2 = activeVitals;
				characterVitals2.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals2.OnKilled, new Action<CharacterVitals.Damage>(OnKilled));
				Character @char = activeVitals.Char;
				@char.onPoisoned = (Action<bool>)Delegate.Remove(@char.onPoisoned, new Action<bool>(SetPoisoned));
			}
			activeVitals = vitals;
			enemyOnlyParent.SetActive(!vitals.Char.Invincible && vitals.Alignment == Alignment.Evil);
			CharacterVitals characterVitals3 = activeVitals;
			characterVitals3.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Combine(characterVitals3.OnDamaged, new Action<CharacterVitals.Damage>(OnDamaged));
			CharacterVitals characterVitals4 = activeVitals;
			characterVitals4.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Combine(characterVitals4.OnKilled, new Action<CharacterVitals.Damage>(OnKilled));
			Character char2 = activeVitals.Char;
			char2.onPoisoned = (Action<bool>)Delegate.Combine(char2.onPoisoned, new Action<bool>(SetPoisoned));
			SetPoisoned(activeVitals.Char.GetPoisoned);
			nameText.text = I2Loca.Get(vitals.Char.CharacterName);
			bool flag = vitals.Char.IsBoss || vitals.Char.isUnique;
			hpBarParentRT.localScale = (flag ? new Vector3(1.2f, 1f, 1f) : Vector3.one);
			bossIndicator.SetActive(flag);
			nameText.color = (flag ? bossNameColor : normalNameColor);
			levelText.text = I2Loca.GetFormat("Level_x", vitals.Char.Level);
			hpBarFill.localScale = new Vector3(activeVitals.GetHealthPct(), 1f, 1f);
			poisonBarFill.localScale = new Vector3(activeVitals.GetHealthPct(), 1f, 1f);
			Rank getMonsterRank = vitals.Char.GetMonsterRank;
			bool flag2 = getMonsterRank != Rank.Normal;
			rankedUpIndicator.SetActive(flag2);
			if (flag2)
			{
				rankText.text = I2Loca.Get(getMonsterRank.ToString());
				rankText.color = ((getMonsterRank == Rank.Elite) ? eliteColor : legendaryColor);
				rankImage.sprite = ((getMonsterRank == Rank.Elite) ? eliteSprite : legendarySprite);
			}
			ShowResistances(vitals.Char);
			InternalShow();
		}

		private void ShowResistances(Character character)
		{
			if (resistanceTexts == null)
			{
				resistanceTexts = new List<TextMeshProUGUI> { resistanceTemplate };
				resistanceTemplate.gameObject.SetActive(value: false);
			}
			Dictionary<DamageType, int> dictionary = new Dictionary<DamageType, int>();
			foreach (DamageType value2 in Enum.GetValues(typeof(DamageType)))
			{
				if (value2 != DamageType.Count && value2 != 0 && value2 != DamageType.Heroic && value2 != DamageType.Undead)
				{
					int num = character.DamageResistance(value2);
					if (num != 0)
					{
						dictionary.Add(value2, num);
					}
				}
			}
			bool isBoss = character.IsBoss;
			bool flag = character.Family() == Family.Undead;
			if (isBoss)
			{
				dictionary.Add(DamageType.Heroic, -Mathf.CeilToInt(300f));
			}
			int num2 = dictionary.Count;
			if (flag)
			{
				num2++;
			}
			resistanceTexts.AssertComponentCount(num2);
			for (int i = 0; i < resistanceTexts.Count; i++)
			{
				resistanceTexts[i].gameObject.SetActive(i < num2);
			}
			int num3 = 0;
			if (flag)
			{
				resistanceTexts[0].text = I2Loca.Get("Undead");
				num3++;
			}
			foreach (KeyValuePair<DamageType, int> item in dictionary)
			{
				DamageType key = item.Key;
				int value = item.Value;
				bool flag2 = value < 0;
				resistanceTexts[num3].text = $"{Mathf.Abs(value)}% {(flag2 ? Fate.GetWeaknessString(key) : Fate.GetResistanceString(key))}";
				if (key == DamageType.Heroic)
				{
					resistanceTexts[num3].text = (flag2 ? Fate.GetWeaknessString(key) : Fate.GetResistanceString(key)) ?? "";
				}
				num3++;
			}
		}

		private void HideResistances()
		{
			if (resistanceTexts == null)
			{
				return;
			}
			foreach (TextMeshProUGUI resistanceText in resistanceTexts)
			{
				resistanceText.gameObject.SetActive(value: false);
			}
		}

		public void Show(string targetName)
		{
			if (activeVitals != null)
			{
				CharacterVitals characterVitals = activeVitals;
				characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(OnDamaged));
				CharacterVitals characterVitals2 = activeVitals;
				characterVitals2.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals2.OnKilled, new Action<CharacterVitals.Damage>(OnKilled));
			}
			HideResistances();
			activeVitals = null;
			enemyOnlyParent.SetActive(value: false);
			nameText.text = targetName;
			InternalShow();
		}

		private void InternalShow()
		{
			base.gameObject.SetActive(value: true);
		}

		public void Hide()
		{
			if (activeVitals != null)
			{
				CharacterVitals characterVitals = activeVitals;
				characterVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals.OnDamaged, new Action<CharacterVitals.Damage>(OnDamaged));
				CharacterVitals characterVitals2 = activeVitals;
				characterVitals2.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Remove(characterVitals2.OnKilled, new Action<CharacterVitals.Damage>(OnKilled));
				Character @char = activeVitals.Char;
				@char.onPoisoned = (Action<bool>)Delegate.Remove(@char.onPoisoned, new Action<bool>(SetPoisoned));
			}
			base.gameObject.SetActive(value: false);
		}

		private void OnDamaged(CharacterVitals.Damage damage)
		{
			hpBarFill.localScale = new Vector3(activeVitals.GetHealthPct(), 1f, 1f);
			poisonBarFill.localScale = new Vector3(activeVitals.GetHealthPct(), 1f, 1f);
		}

		private void OnKilled(CharacterVitals.Damage damage)
		{
			Hide();
		}

		private void SetPoisoned(bool poisoned)
		{
			hpBarFill.gameObject.SetActive(!poisoned);
			poisonBarFill.gameObject.SetActive(poisoned);
		}
	}
