	public class UITabs : MonoBehaviour
	{
		public enum TabType
		{
			StatsSkills = 0,
			Inventory = 1,
			Spellbook = 2,
			Quests = 3,
			None = -1
		}

		[Serializable]
		public struct Tab
		{
			public TabType tabType;

			public Button tabButton;

			public TextMeshProUGUI tabText;

			public string tabLocaKey;

			public GameObject tabScreen;
		}

		[SerializeField]
		private Tab[] tabs;

		[SerializeField]
		private Color textColorActiveTab;

		private Color textColorDefaultTab;

		private TabType currentTab = TabType.None;

		public Action<TabType, TabType> onTabChanged;

		public TabType CurrentTab => currentTab;

		public void Init()
		{
			textColorDefaultTab = tabs[0].tabText.color;
			SimpleSingletonBehaviour<PlayerUI>.Instance.InitTabs(tabs);
			SetTab(TabType.None);
			for (int i = 0; i < tabs.Length; i++)
			{
				int index = i;
				tabs[index].tabButton.onClick.AddListener(delegate
				{
					SetTab(tabs[index].tabType);
					SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				});
			}
		}

		private void SetTextSelected(TextMeshProUGUI text, string baseText, bool selected)
		{
			if (selected)
			{
				text.color = textColorActiveTab;
				text.text = baseText;
				text.fontSizeMax = 25f;
			}
			else
			{
				text.color = textColorDefaultTab;
				text.text = baseText;
				text.fontSizeMax = 22f;
			}
		}

		public void SetTab(TabType tabType)
		{
			TabType tabType2 = currentTab;
			if (!base.gameObject.activeInHierarchy)
			{
				PlayerUI.LatestSelectedMemberIndex = 0;
			}
			if (tabType == TabType.Inventory && SingletonBehaviour<PlayerStatus>.Instance.TutorialStatus.TryGetContextualTip(TutorialTipType.Inventory, out var key))
			{
				SingletonBehaviour<TutorialPopupUI>.Instance.ShowTip(key);
			}
			for (int i = 0; i < tabs.Length; i++)
			{
				Tab tab = tabs[i];
				tab.tabScreen.SetActive(tab.tabType == tabType);
				SetTextSelected(tab.tabText, I2Loca.Get(tab.tabLocaKey), tab.tabType == tabType);
			}
			currentTab = tabType;
			base.gameObject.SetActive(tabType != TabType.None);
			if (tabType == TabType.None)
			{
				if (SingletonBehaviour<PlayerUI>.InstanceExists())
				{
					SimpleSingletonBehaviour<PlayerUI>.Instance.Tooltip.HideTooltip();
					if (SingletonBehaviour<CursorManager>.InstanceExists())
					{
						SingletonBehaviour<CursorManager>.Instance.SetVirtualCursorActive(state: false);
					}
				}
				Fate.SetPause(paused: false);
			}
			else
			{
				SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Menu);
				if (SingletonBehaviour<PlayerUI>.InstanceExists() && SingletonBehaviour<CursorManager>.InstanceExists())
				{
					SingletonBehaviour<CursorManager>.Instance.SetVirtualCursorActive(state: true);
				}
				Fate.SetPause(paused: true);
			}
			if (tabType2 != tabType)
			{
				onTabChanged?.Invoke(tabType2, currentTab);
			}
		}

		public void NextTab()
		{
			switch (currentTab)
			{
			case TabType.StatsSkills:
				SetTab(TabType.Inventory);
				break;
			case TabType.Inventory:
				SetTab(TabType.Spellbook);
				break;
			case TabType.Spellbook:
				SetTab(TabType.Quests);
				break;
			case TabType.Quests:
				SetTab(TabType.StatsSkills);
				break;
			}
		}

		public void PreviousTab()
		{
			switch (currentTab)
			{
			case TabType.StatsSkills:
				SetTab(TabType.Quests);
				break;
			case TabType.Inventory:
				SetTab(TabType.StatsSkills);
				break;
			case TabType.Spellbook:
				SetTab(TabType.Inventory);
				break;
			case TabType.Quests:
				SetTab(TabType.Spellbook);
				break;
			}
		}
	}
	public class InputHintUI : SingletonBehaviour<InputHintUI>
	{
		[Flags]
		public enum Hint
		{
			Interact = 1,
			Back = 2
		}

		[SerializeField]
		private TextMeshProUGUI inputHintText;

		private const string spacing = "   ";

		protected override void Awake()
		{
			base.Awake();
			HideInputHint();
		}

		public void SetInputHint(Hint hintFlags)
		{
			IEnumerable<Enum> flags = GetFlags(hintFlags);
			StringBuilder stringBuilder = new StringBuilder();
			foreach (Enum item in flags)
			{
				stringBuilder.Append(item.ToString());
				stringBuilder.Append("   ");
			}
			inputHintText.text = stringBuilder.ToString().TrimEnd();
		}

		public void HideInputHint()
		{
			inputHintText.text = "";
		}

		private static IEnumerable<Enum> GetFlags(Enum input)
		{
			foreach (Enum value in Enum.GetValues(input.GetType()))
			{
				if (input.HasFlag(value))
				{
					yield return value;
				}
			}
		}
	}
