	public class JournalUI : MonoBehaviour
	{
		[SerializeField]
		private JournalEntry entryTemplate;

		[SerializeField]
		private Button backButton;

		private List<JournalEntry> entries;

		private readonly List<Stat> shownStats = new List<Stat>
		{
			Stat.SecondsPlayed,
			Stat.StepsTaken,
			Stat.GoldLooted,
			Stat.SideQuests,
			Stat.DeepestDepth,
			Stat.Deaths,
			Stat.EnemiesDefeated,
			Stat.BossesKilled,
			Stat.SpellsCast,
			Stat.ChestsOpened,
			Stat.TrapsSprung,
			Stat.BarrelsBroken,
			Stat.PotionsUsed,
			Stat.PortalsUsed,
			Stat.FishCaught,
			Stat.Gambles
		};

		private void Awake()
		{
			entries = new List<JournalEntry>();
			entries.Add(entryTemplate);
			entries.AssertComponentCount(shownStats.Count);
			entries[0].SetDividerActive(state: false);
			backButton.onClick.AddListener(OnBackButton);
		}

		private void OnEnable()
		{
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed += Cancel_performed;
			for (int i = 0; i < shownStats.Count; i++)
			{
				if (shownStats[i] == Stat.SecondsPlayed)
				{
					TimeSpan timeSpan = TimeSpan.FromSeconds(StatsManager.GetStat(Stat.SecondsPlayed));
					entries[i].Setup(Fate.GetJournalStatName(shownStats[i]), I2Loca.GetFormat("PlayTimeFormat", (int)timeSpan.TotalHours, timeSpan.Minutes, timeSpan.Seconds));
				}
				else
				{
					entries[i].Setup(Fate.GetJournalStatName(shownStats[i]), StatsManager.GetStat(shownStats[i]).ToString());
				}
				entries[i].gameObject.SetActive(value: true);
			}
		}

		private void OnDisable()
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed -= Cancel_performed;
			}
		}

		private void Cancel_performed(InputAction.CallbackContext context)
		{
			if (context.performed)
			{
				OnBackButton();
			}
		}

		private void OnBackButton()
		{
			if (SingletonBehaviour<PauseUI>.InstanceExists())
			{
				SingletonBehaviour<PauseUI>.Instance.OnMenuButton();
			}
		}
	}
	public class LoadingScreenUI : SingletonBehaviour<LoadingScreenUI>
	{
		[Serializable]
		public class RealmSpriteSetup
		{
			public RealmData.RealmId townRealm;

			public Sprite sprite;
		}

		public CanvasGroup canvasGroup;

		public Image mainImage;

		public Image monsterImage;

		public Transform loadingBar;

		public TextMeshProUGUI tooltipText;

		public Sprite defaultMainSprite;

		public Sprite[] monsterOptions;

		public string[] tooltipOptions;

		public RealmSpriteSetup[] mainSpriteSetup;

		public RealmSpriteSetup fate2TempleSpriteOverride;

		public int tipCount;

		public bool shown;

		private int runningTweenId = -1;

		private Func<float> progressFunction;

		private float currentTime;

		protected override bool DontDestroy => true;

		protected override void Awake()
		{
			base.Awake();
		}

		private void Update()
		{
			if (progressFunction != null)
			{
				loadingBar.localScale = new Vector3(progressFunction(), 1f, 1f);
			}
		}

		public void SetTownRealm(RealmData.RealmId realm)
		{
			RealmSpriteSetup realmSpriteSetup = ((Fate.CurrentFateVer != Fate.FateVer.UndiscoveredRealms || realm != RealmData.RealmId.TempleOfFate) ? mainSpriteSetup.Find((RealmSpriteSetup m) => m.townRealm == realm) : fate2TempleSpriteOverride);
			if (realmSpriteSetup == null)
			{
				SetToDefault();
				return;
			}
			mainImage.sprite = realmSpriteSetup.sprite;
			monsterImage.gameObject.SetActive(value: false);
		}

		public void SetToDefault()
		{
			mainImage.sprite = defaultMainSprite;
			monsterImage.sprite = monsterOptions.GetRandomEntry();
			monsterImage.gameObject.SetActive(value: true);
		}

		public void ShowLoading(bool fadeIn, Func<float> progressFunc = null)
		{
			TweenTG.Stop(runningTweenId);
			shown = true;
			if (fadeIn)
			{
				base.gameObject.SetActive(value: true);
				runningTweenId = TweenTG.Tween(canvasGroup, 0f, 1f, -0.2f, Easing.Mode.QuarticIn);
			}
			else
			{
				canvasGroup.alpha = 1f;
				base.gameObject.SetActive(value: true);
				runningTweenId = -1;
			}
			tooltipText.text = I2Loca.GetReplaceTags(tooltipOptions.GetRandomEntry());
			loadingBar.localScale = new Vector3(0f, 1f, 1f);
			if (progressFunc == null)
			{
				currentTime = 0f;
				progressFunction = () => Mathf.Min(Easing.QuartEaseIn(currentTime += Time.unscaledDeltaTime, 0f, 1f, 3f), 1f);
			}
			else
			{
				currentTime = progressFunc();
				progressFunction = progressFunc;
			}
		}

		public void HideLoading(bool fadeOut)
		{
			TweenTG.Stop(runningTweenId);
			shown = false;
			if (fadeOut)
			{
				runningTweenId = TweenTG.TweenTo(canvasGroup, 0f, -0.4f, Easing.Mode.QuinticOut, delegate
				{
					base.gameObject.SetActive(value: false);
				});
			}
			else
			{
				base.gameObject.SetActive(value: false);
				canvasGroup.alpha = 0f;
				runningTweenId = -1;
			}
		}

		private string GetTipString()
		{
			return "TIP_" + UnityEngine.Random.Range(1, tipCount + 1).ToString("000");
		}
	}
	public class CharacterCustomization : MonoBehaviour
	{
		public InputFieldRelay nameInputField;

		public Button randomNameBtn;

		public Button raceLeftBtn;

		public Button raceRightBtn;

		public Button bodyLeftBtn;

		public Button bodyRightBtn;

		public Button hairLeftBtn;

		public Button hairRightBtn;

		public Button faceLeftBtn;

		public Button faceRightBtn;

		public Button randomFeaturesBtn;

		public TextMeshProUGUI bodyText;

		public TextMeshProUGUI raceText;

		public TextMeshProUGUI hairText;

		public TextMeshProUGUI faceText;

		public Selectable raceSelectable;

		public Selectable bodyTypeSelectable;

		public Selectable hairSelectable;

		public Selectable faceSelectable;

		public Animation nameErrorAnim;

		private int currRaceIndex;

		private int currHairIndex;

		private int currFaceIndex;

		private int headCount;

		private int hairCount;

		private int previousInputSign;

		private bool isMale = true;

		private bool hasInitialized;

		private NewgameUI newgamePanel;

		private void Awake()
		{
			Init();
			ResetToNewGameState();
		}

		private void Init()
		{
			if (hasInitialized)
			{
				return;
			}
			newgamePanel = NewgameUI.GetPanel();
			InputFieldRelay inputFieldRelay = nameInputField;
			inputFieldRelay.onInputFieldDone = (Action<string>)Delegate.Combine(inputFieldRelay.onInputFieldDone, (Action<string>)delegate(string newname)
			{
				newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation c)
				{
					c.playerName = newname;
				});
			});
			raceLeftBtn.onClick.AddListener(OnRaceLeft);
			raceRightBtn.onClick.AddListener(OnRaceRight);
			bodyLeftBtn.onClick.AddListener(OnBodyLeft);
			bodyRightBtn.onClick.AddListener(OnBodyRight);
			hairLeftBtn.onClick.AddListener(OnHairLeft);
			hairRightBtn.onClick.AddListener(OnHairRight);
			faceLeftBtn.onClick.AddListener(OnFaceLeft);
			faceRightBtn.onClick.AddListener(OnFaceRight);
			randomNameBtn.onClick.AddListener(OnRandomNameBtn);
			randomFeaturesBtn.onClick.AddListener(OnRandomFeaturesBtn);
			hasInitialized = true;
		}

		public void ResetToNewGameState()
		{
			if (!hasInitialized)
			{
				Init();
			}
			if (SingletonBehaviour<PlayerStatus>.Instance.IsHandlingRetirement && SaveData.CurrentSaveData != null)
			{
				PlayerSaveData playerSave = SaveData.CurrentSaveData.playerSaveData;
				SetRace((int)playerSave.playerRace);
				SetBody(playerSave.male, resetHairAndFace: true);
				SetFace(playerSave.headIndex);
				SetHair(playerSave.hairIndex);
				nameInputField.InputField.text = playerSave.playerName;
				newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation c)
				{
					c.playerName = playerSave.playerName;
				});
			}
			else
			{
				SetRace(currRaceIndex);
				SetBody(isMale, resetHairAndFace: true);
				SetFace(currFaceIndex);
				SetHair(currHairIndex);
				nameInputField.InputField.text = "";
			}
		}

		private void OnEnable()
		{
			((InputSystemUIInputModule)EventSystem.current.currentInputModule).move.action.performed += Action_performed;
			Race race = (Race)currRaceIndex;
			NewgameUI newgameUI = newgamePanel;
			string title = I2Loca.Get(race.ToString());
			Race race2 = (Race)currRaceIndex;
			newgameUI.SetDescription(title, I2Loca.Get(race2.ToString() + "Description"));
			headCount = SingletonBehaviour<MenuPlayer>.Instance.HeadCount;
			hairCount = SingletonBehaviour<MenuPlayer>.Instance.HairCount;
			SetRace(currRaceIndex);
			SetBody(isMale, resetHairAndFace: false);
			SetFace(currFaceIndex);
			SetHair(currHairIndex);
		}

		private void OnDisable()
		{
			if (EventSystem.current != null)
			{
				((InputSystemUIInputModule)EventSystem.current.currentInputModule).move.action.performed -= Action_performed;
			}
		}

		public bool CanContinue()
		{
			if (string.IsNullOrEmpty(nameInputField.InputField.text))
			{
				nameErrorAnim.Play(PlayMode.StopAll);
				return false;
			}
			return true;
		}

		private void Action_performed(InputAction.CallbackContext obj)
		{
			Vector2 vector = obj.ReadValue<Vector2>();
			if (Mathf.Approximately(vector.x, 0f))
			{
				previousInputSign = 0;
			}
			else
			{
				if (Math.Sign(vector.x) == previousInputSign)
				{
					return;
				}
				Selectable selectable = EventSystem.current.currentSelectedGameObject?.GetComponent<Selectable>();
				if (selectable == null)
				{
					return;
				}
				if (vector.x < -0.25f)
				{
					previousInputSign = -1;
					if (selectable == raceSelectable)
					{
						OnRaceLeft();
					}
					else if (selectable == hairSelectable)
					{
						OnHairLeft();
					}
					else if (selectable == faceSelectable)
					{
						OnFaceLeft();
					}
					else if (selectable == bodyTypeSelectable)
					{
						OnBodyLeft();
					}
				}
				else if (vector.x > 0.25f)
				{
					previousInputSign = 1;
					if (selectable == raceSelectable)
					{
						OnRaceRight();
					}
					else if (selectable == hairSelectable)
					{
						OnHairRight();
					}
					else if (selectable == faceSelectable)
					{
						OnFaceRight();
					}
					else if (selectable == bodyTypeSelectable)
					{
						OnBodyRight();
					}
				}
			}
		}

		private void OnRandomNameBtn()
		{
			nameInputField.InputField.text = SingletonBehaviour<NameGenerator>.Instance.GeneratePhonicName();
			newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation creation)
			{
				creation.playerName = nameInputField.InputField.text;
			});
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnRandomFeaturesBtn()
		{
			SetHair(UnityEngine.Random.Range(0, hairCount));
			SetFace(UnityEngine.Random.Range(0, headCount));
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnRaceLeft()
		{
			SetRace((currRaceIndex <= 1) ? 5 : (currRaceIndex - 1));
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			headCount = SingletonBehaviour<MenuPlayer>.Instance.HeadCount;
			hairCount = SingletonBehaviour<MenuPlayer>.Instance.HairCount;
			SetHair(0);
			SetFace(0);
		}

		private void OnRaceRight()
		{
			SetRace((currRaceIndex >= 5) ? 1 : (currRaceIndex + 1));
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			headCount = SingletonBehaviour<MenuPlayer>.Instance.HeadCount;
			hairCount = SingletonBehaviour<MenuPlayer>.Instance.HairCount;
			SetHair(0);
			SetFace(0);
		}

		private void OnBodyLeft()
		{
			SetBody(!isMale, resetHairAndFace: true);
		}

		private void OnBodyRight()
		{
			SetBody(!isMale, resetHairAndFace: true);
		}

		private void SetBody(bool male, bool resetHairAndFace)
		{
			isMale = male;
			SingletonBehaviour<MenuPlayer>.Instance.SetBodytype(isMale);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			headCount = SingletonBehaviour<MenuPlayer>.Instance.HeadCount;
			hairCount = SingletonBehaviour<MenuPlayer>.Instance.HairCount;
			if (resetHairAndFace)
			{
				SetHair(0);
				SetFace(0);
			}
			else
			{
				SetHair(currHairIndex);
				SetFace(currFaceIndex);
			}
			bodyText.text = I2Loca.Get(isMale ? "BodytypeA" : "BodytypeB");
			newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation c)
			{
				c.male = isMale;
			});
		}

		private void OnHairLeft()
		{
			SetHair((currHairIndex <= 0) ? (hairCount - 1) : (currHairIndex - 1));
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnHairRight()
		{
			SetHair((currHairIndex < hairCount - 1) ? (currHairIndex + 1) : 0);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnFaceLeft()
		{
			SetFace((currFaceIndex <= 0) ? (headCount - 1) : (currFaceIndex - 1));
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnFaceRight()
		{
			SetFace((currFaceIndex < headCount - 1) ? (currFaceIndex + 1) : 0);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void SetRace(int index)
		{
			if (index == 0)
			{
				index = 1;
			}
			currRaceIndex = index;
			Race newRace = (Race)currRaceIndex;
			raceText.text = I2Loca.Get(newRace.ToString());
			newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation c)
			{
				c.race = newRace;
			});
			SingletonBehaviour<MenuPlayer>.Instance.SetRace(newRace);
			NewgameUI newgameUI = newgamePanel;
			string title = I2Loca.Get(raceText.text);
			Race race = (Race)currRaceIndex;
			newgameUI.SetDescription(title, I2Loca.Get(race.ToString() + "Description"));
		}

		private void SetHair(int index)
		{
			currHairIndex = index;
			hairText.text = I2Loca.GetFormat("Hairstyle", currHairIndex + 1);
			newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation c)
			{
				c.hairIndex = currHairIndex;
			});
			SingletonBehaviour<MenuPlayer>.Instance.SetHair(index);
		}

		private void SetFace(int index)
		{
			currFaceIndex = index;
			faceText.text = I2Loca.GetFormat("Face", currFaceIndex + 1);
			newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation c)
			{
				c.headIndex = currFaceIndex;
			});
			SingletonBehaviour<MenuPlayer>.Instance.SetHead(index);
		}
	}
	public class ContinueUI : UIGenericPanel
	{
		public Button continueButton;

		public Button importButton;

		public Button deleteButton;

		public Button backButton;

		public SaveSlotEntry template;

		public GameObject mainParent;

		public GameObject importParent;

		public Button importBackBtn;

		public Button importConfirmBtn;

		public SaveSlotEntry importEntryTemplate;

		private SaveData.SaveSlot currentSelectedSlot;

		private SaveData.SaveSlot currentImportTarget;

		private GameObject currentSelectedParent;

		private List<SaveSlotEntry> entries;

		private List<SaveSlotEntry> importEntries;

		private void Awake()
		{
			entries = new List<SaveSlotEntry>();
			entries.Add(template);
			template.gameObject.SetActive(value: false);
			importEntries = new List<SaveSlotEntry>();
			importEntries.Add(importEntryTemplate);
			importEntryTemplate.gameObject.SetActive(value: false);
			backButton.onClick.AddListener(delegate
			{
				MainMenuUI.OnSubPanelBackButton();
			});
			continueButton.onClick.AddListener(OnContinueButton);
			deleteButton.onClick.AddListener(OnDeleteButton);
			importButton.onClick.AddListener(OnImportButton);
			importBackBtn.onClick.AddListener(OnImportBackButton);
			importConfirmBtn.onClick.AddListener(OnImportConfirmButton);
		}

		private void OnEnable()
		{
			if (SaveData.SaveSlots == null)
			{
				UnityEngine.Debug.Log("Continue opened with no savedata???");
				return;
			}
			currentSelectedSlot = SaveData.CurrentSaveSlot;
			List<SaveData.SaveSlot> list = SaveData.SaveSlots.FindAll((SaveData.SaveSlot s) => s.targetGame == Fate.CurrentFateVer);
			continueButton.interactable = list != null && list.Count > 0 && currentSelectedSlot.saveState == SaveSlotState.Normal;
			deleteButton.interactable = list != null && list.Count > 0;
			Toggle selectedToggle = null;
			if (list != null)
			{
				entries.AssertComponentCount(list.Count);
				for (int i = 0; i < list.Count; i++)
				{
					SaveData.SaveSlot saveSlot = list[i];
					entries[i].SetSaveInfo(saveSlot);
					entries[i].gameObject.SetActive(value: true);
					entries[i].onToggleValueChanged = OnToggled;
					if (currentSelectedSlot == saveSlot)
					{
						selectedToggle = entries[i].toggle;
					}
				}
				if (selectedToggle != null)
				{
					selectedToggle.isOn = true;
				}
			}
			List<SaveData.SaveSlot> list2 = SaveData.SaveSlots.FindAll((SaveData.SaveSlot s) => s.targetGame < Fate.CurrentFateVer && s.saveState == SaveSlotState.Normal);
			importButton.interactable = list2 != null && list2.Count > 0;
			currentImportTarget = null;
			UtilityTG.UnityDelay(delegate
			{
				if (selectedToggle != null && selectedToggle.gameObject.activeInHierarchy)
				{
					UtilityTG.SetSelected(selectedToggle.gameObject);
				}
				else
				{
					UtilityTG.SetSelected(backButton.gameObject);
				}
			});
			mainParent.SetActive(value: true);
			importParent.SetActive(value: false);
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed -= Cancel_performed;
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed += Cancel_performed;
		}

		private void Cancel_performed(InputAction.CallbackContext obj)
		{
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed -= Cancel_performed;
			MainMenuUI.OnSubPanelBackButton();
		}

		private void OnToggled(SaveData.SaveSlot entry, GameObject entryGO, bool isOn)
		{
			if (isOn)
			{
				SaveData.SaveSlot saveSlot = currentSelectedSlot;
				currentSelectedSlot = entry;
				SaveData.SetSelectedSlot(entry);
				SingletonBehaviour<MenuPlayer>.Instance.LoadSaveCharacter(entry);
				currentSelectedParent = entryGO;
				continueButton.interactable = entry.saveState == SaveSlotState.Normal;
				if (continueButton.interactable && saveSlot == currentSelectedSlot && SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free)
				{
					UtilityTG.SetSelected(continueButton.gameObject);
				}
			}
		}

		private void OnImportToggled(SaveData.SaveSlot entry, GameObject entryGO, bool isOn)
		{
			if (isOn)
			{
				currentImportTarget = entry;
				SingletonBehaviour<MenuPlayer>.Instance.LoadSaveCharacter(entry);
			}
		}

		private void OnImportButton()
		{
			if (SaveData.SaveSlots.CountIf((SaveData.SaveSlot slot) => slot.targetGame == Fate.CurrentFateVer && slot.saveState == SaveSlotState.Normal) >= SaveData.MaxSaveSlotsPerGame)
			{
				SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetFormat("ErrorMsg_MaxSaveSlots", Fate.GetCurrentFateName()), null, twoButtons: false, "OK");
				return;
			}
			importParent.SetActive(value: true);
			mainParent.SetActive(value: false);
			UtilityTG.SetSelected(importBackBtn.gameObject);
			List<SaveData.SaveSlot> list = SaveData.SaveSlots.FindAll((SaveData.SaveSlot s) => s.targetGame < Fate.CurrentFateVer && s.saveState == SaveSlotState.Normal);
			importEntries.AssertComponentCount(list.Count);
			for (int i = 0; i < list.Count; i++)
			{
				SaveSlotEntry saveSlotEntry = importEntries[i];
				saveSlotEntry.SetSaveInfo(list[i]);
				saveSlotEntry.gameObject.SetActive(value: true);
				saveSlotEntry.onToggleValueChanged = OnImportToggled;
			}
			if (list.Count > 0)
			{
				OnImportToggled(list[0], importEntries[0].gameObject, isOn: true);
			}
		}

		private void OnImportBackButton()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			importParent.SetActive(value: false);
			mainParent.SetActive(value: true);
			UtilityTG.SetSelected(backButton.gameObject);
			if (currentSelectedSlot != null)
			{
				SingletonBehaviour<MenuPlayer>.Instance.LoadSaveCharacter(currentSelectedSlot);
			}
			else
			{
				SingletonBehaviour<MenuPlayer>.Instance.SetDefaultState();
			}
		}

		private void OnImportConfirmButton()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			SingletonBehaviour<PromptUI>.Instance.ShowPrompt("ImportConfirm", delegate(bool positive)
			{
				if (positive)
				{
					SaveData.CreateNewSaveSlotFromImport(JsonUtility.ToJson(currentImportTarget));
					UtilityTG.SetSelected(null);
					MainMenuUI.NewGameRequested();
				}
			});
		}

		private void OnContinueButton()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed -= Cancel_performed;
			MainMenuUI.ContinueRequested();
		}

		private void OnDeleteButton()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetFormatReplaceTags("DeletePromptBody", currentSelectedSlot.saveData.playerSaveData.PlayerName), delegate(bool confirm)
			{
				if (confirm)
				{
					SaveData.DeleteGameRequested();
					currentSelectedParent.SetActive(value: false);
					if (entries.CountIf((SaveSlotEntry e) => e.gameObject.activeInHierarchy) == 0)
					{
						if (!importButton.interactable)
						{
							MainMenuUI.OnSubPanelBackButton();
						}
						else
						{
							continueButton.interactable = false;
							deleteButton.interactable = false;
							UtilityTG.SetSelected(backButton.gameObject);
							SingletonBehaviour<MenuPlayer>.Instance.SetDefaultState();
							currentSelectedSlot = null;
						}
					}
					else
					{
						entries.Find((SaveSlotEntry e) => e.gameObject.activeInHierarchy).toggle.isOn = true;
					}
				}
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			}, twoButtons: true, "Delete", "Cancel");
		}
	}
