			SingletonBehaviour<LoadingScreenUI>.Instance.HideLoading(fadeOut: true);
			SingletonBehaviour<InputBroker>.Instance.EnableAllInput();
			SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Menu);
		}

		private void OnAnyKey()
		{
			if (SingletonBehaviour<InputBroker>.Instance.Inputs.Persistent.Menu.WasPerformedThisFrame() || SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.WasPerformedThisFrame())
			{
				return;
