					formatReplaceTags = formatReplaceTags + "\n" + I2Loca.GetFormat("Level_x", Fate.GetLevelFromExperience(activeSaveSlotForGame.saveData.playerSaveData.experience) + 1);
					entry.characterText.text = formatReplaceTags;
