		private void SettCharacterCustomization(CharacterCustomizationDefaults _character, FateSaveData saveData)
		{
			_character.SetHelmet(null);
			_character.SetGloves(null);
			_character.SetUpper(null);
			_character.SetBack(null);
			_character.SetRightHand(null);
			_character.SetLeftHand(null);
			if (saveData?.playerSaveData == null)
			{
				return;
			}
			PlayerSaveData playerSaveData = saveData.playerSaveData;
			if (playerSaveData.playerRace == Race.None)
			{
				return;
			}
			SetBodytype(playerSaveData.male, _character);
			SetRace(playerSaveData.playerRace, _character);
			SetHead(playerSaveData.headIndex, _character);
			SetHair(playerSaveData.hairIndex, _character);
			List<ItemSaveData> list = saveData.itemSaveData?.items;
			if (list == null)
			{
				return;
			}
			List<ItemSaveData> equipment = list.FindAll((ItemSaveData i) => Fate.IsItemSlotInEquipmentSlot(i.slotIndex));
			if (equipment == null)
			{
				return;
			}
			List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
			int j = 0;
			while (j < equipment.Count)
			{
				ItemData itemData = allItems.Find((ItemData itm) => itm.displayName == equipment[j].baseName);
				if (!(itemData == null) && ((itemData.ItemCategory != ItemCategory.Weapon && itemData.itemType != ItemType.Shield) || equipment[j].weaponSet == saveData.playerSaveData.activeWeaponSet))
				{
					switch (itemData.itemType)
					{
					case ItemType.Sword:
					case ItemType.Club:
					case ItemType.Shield:
					case ItemType.Spear:
					case ItemType.Bow:
					case ItemType.Polearm:
					case ItemType.Axe:
					case ItemType.Hammer:
					case ItemType.Staff:
					case ItemType.Crossbow:
						if (equipment[j].slotIndex == 6)
						{
							_character.SetRightHand(itemData.displayName);
						}
						else
						{
							_character.SetLeftHand(itemData.displayName);
						}
						break;
					case ItemType.Helmet:
						_character.SetHelmet(itemData.displayName);
						break;
					case ItemType.Gloves:
						_character.SetGloves(itemData.displayName);
						break;
					case ItemType.Boots:
						_character.SetBoots(itemData.displayName);
						break;
					case ItemType.Shirt:
						_character.SetUpper(itemData.displayName);
						break;
					case ItemType.Back:
						_character.SetBack(itemData.displayName);
						break;
					}
				}
				int num = j + 1;
				j = num;
			}
		}

		public void SetHead(int headIndex, CharacterCustomizationDefaults _character)
		{
			_character.SetHead(headIndex);
		}

		public void SetHair(int hairIndex, CharacterCustomizationDefaults _character)
		{
			_character.SetHair(hairIndex);
		}

		public void SetRace(Race race, CharacterCustomizationDefaults _character)
		{
			_character.SetRace(race);
		}

		public void SetBodytype(bool male, CharacterCustomizationDefaults _character)
		{
			_character.SetGender(male);
		}
	}
	public class GameSelectable : Selectable, IPointerClickHandler, IEventSystemHandler, ISubmitHandler
	{
		public Action onSelect;

		public Action onDeselect;

		public Action onClicked;

		private bool deselectFired;

		protected override void DoStateTransition(SelectionState state, bool instant)
		{
			if (state == SelectionState.Normal && !deselectFired)
			{
				onDeselect?.Invoke();
				deselectFired = true;
			}
			base.DoStateTransition(state, instant);
		}

		public override void OnSelect(BaseEventData eventData)
		{
			base.OnSelect(eventData);
			onSelect?.Invoke();
			deselectFired = false;
		}

		public override void OnDeselect(BaseEventData eventData)
		{
			base.OnDeselect(eventData);
			if (!deselectFired)
			{
				onDeselect?.Invoke();
				deselectFired = true;
			}
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			onClicked?.Invoke();
		}

		public override void OnPointerEnter(PointerEventData eventData)
		{
			base.OnPointerEnter(eventData);
			onSelect?.Invoke();
			deselectFired = false;
		}

		public override void OnPointerExit(PointerEventData eventData)
		{
			base.OnPointerExit(eventData);
			if (!deselectFired)
			{
				onDeselect?.Invoke();
				deselectFired = true;
			}
		}

		public void OnSubmit(BaseEventData eventData)
		{
			onClicked?.Invoke();
		}
	}
	public class LanguageSelect : MonoBehaviour
	{
		[Serializable]
		public struct LanguageToggle
		{
			public Toggle toggle;

			public string languageCode;
		}

		public LanguageToggle[] toggles;

		public OptionsUI optionsUI;

		private void Awake()
		{
			string text = "";
			string text2 = ((!string.IsNullOrEmpty(text)) ? text : SaveData.SettingsSave.overrideLanguageCode);
			if (string.IsNullOrEmpty(text2))
			{
				text2 = PlatformManager.GetPlatformLanguage();
				if (string.IsNullOrEmpty(text2))
				{
					UnityEngine.Debug.Log("Got nothing from GetPlatformLanguage, defaulting to en");
					text2 = "en";
				}
			}
			for (int i = 0; i < toggles.Length; i++)
			{
				if (toggles[i].languageCode == text2)
				{
					UnityEngine.Debug.Log(i + " Toggel " + toggles[i].languageCode + " == " + text2);
					toggles[i].toggle.isOn = true;
				}
			}
			for (int j = 0; j < toggles.Length; j++)
			{
				string code = toggles[j].languageCode;
				toggles[j].toggle.onValueChanged.AddListener(delegate(bool b)
				{
					if (b)
					{
						SetLanguage(code);
					}
				});
			}
		}

		private void SetLanguage(string code)
		{
			List<string> allLanguagesCode = LocalizationManager.GetAllLanguagesCode();
			if (allLanguagesCode.Contains(code))
			{
				UnityEngine.Debug.Log("Set language: " + code);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
				I2Loca.SetLanguageFromCode(code);
				SaveData.SetSettings(delegate(SettingsSave settings)
				{
					settings.overrideLanguageCode = code;
				});
				optionsUI.SetLanguage();
			}
			else
			{
				UnityEngine.Debug.Log("Language not found: " + code + " all languages: " + string.Join(", ", allLanguagesCode));
			}
		}
	}
