			SingletonBehaviour<InputBroker>.Instance.EnableAllInput();
			SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Menu);
			SingletonBehaviour<InputBroker>.Instance.CorrectPs4JapaneseButtons();
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Submit.performed += Submit_performed;
			ValidateContinueButton();
			fateLogo.SetActive(value: true);
			if (SingletonBehaviour<PlayerStatus>.Instance.IsHandlingRetirement)
			{
				SetState(MenuState.CharacterCreation);
			}
			switch (Fate.CurrentFateVer)
			{
			case Fate.FateVer.Original:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.IntroFate1, stopOthers: true);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.IntroAmbientWoods, randomizePitch: false);
				break;
			case Fate.FateVer.UndiscoveredRealms:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.IntroFate2, stopOthers: true);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.AmbientCastle, randomizePitch: false);
				break;
			case Fate.FateVer.TraitorSoul:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.IntroFate3, stopOthers: true);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.AmbientCastle, randomizePitch: false);
				break;
			case Fate.FateVer.CursedKing:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.IntroFate4, stopOthers: true);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.AmbientEkbatan, randomizePitch: false);
				break;
			default:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.IntroFate1, stopOthers: true);
				break;
			}
		}

