		private void ValidateContinueButton()
		{
			List<SaveData.SaveSlot> list = SaveData.SaveSlots.FindAll((SaveData.SaveSlot s) => s.targetGame == Fate.CurrentFateVer);
			bool flag = list != null && list.Count > 0;
			List<SaveData.SaveSlot> list2 = SaveData.SaveSlots.FindAll((SaveData.SaveSlot s) => s.targetGame < Fate.CurrentFateVer && s.saveState == SaveSlotState.Normal);
			bool flag2 = list2 != null && list2.Count > 0;
			firstSelectedObject = ((flag || flag2) ? continueButton.gameObject : newgameButton.gameObject);
			if (EventSystem.current.currentSelectedGameObject != firstSelectedObject)
			{
				EventSystem.current.SetSelectedGameObject(firstSelectedObject);
			}
			continueButton.interactable = flag || flag2;
		}

