			base.gameObject.SetActive(value: false);
			fateLogo.SetActive(value: false);
		}

		private static IEnumerator ContinueGameRoutine(bool loadAfter)
		{
			SingletonBehaviour<QuestManager>.AssertInstance();
			yield return null;
			if (loadAfter)
			{
				Player.isComingFromMenu = true;
				SceneLoad.LoadAsync(SceneLoad.GetTownScene(Fate.CurrentFateVer), save: false, withLoadingScreen: false);
			}
		}

		private void OnNewgameButton()
		{
			if (SaveData.SaveSlots.CountIf((SaveData.SaveSlot slot) => slot.targetGame == Fate.CurrentFateVer && slot.saveState == SaveSlotState.Normal) >= SaveData.MaxSaveSlotsPerGame)
			{
				SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetFormat("ErrorMsg_MaxSaveSlots", Fate.GetCurrentFateName()), null, twoButtons: false, "OK");
			}
			else
			{
				SetState(MenuState.CharacterCreation);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			}
		}

		private void OnOptionsButton()
		{
			SetState(MenuState.Options);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnCreditsButton()
		{
			SetState(MenuState.Credits);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnHelpButton()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnQuitButton()
		{
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			SingletonBehaviour<LoadingScreenUI>.Instance.SetToDefault();
			SingletonBehaviour<LoadingScreenUI>.Instance.ShowLoading(fadeIn: true);
			SceneLoad.LoadAsync(Scene.GameSelect, save: false, withLoadingScreen: false);
			switch (Fate.CurrentFateVer)
			{
			case Fate.FateVer.Original:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.IntroAmbientWoods);
				break;
			case Fate.FateVer.UndiscoveredRealms:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.AmbientCastle);
				break;
			case Fate.FateVer.TraitorSoul:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.AmbientCastle);
				break;
			case Fate.FateVer.CursedKing:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.AmbientEkbatan);
				break;
			default:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				break;
			}
		}

		public static UIGenericPanel GetPanel(MenuState targetState)
		{
			return targetState switch
			{
				MenuState.Options => Instance.optionsPanel, 
				MenuState.Credits => Instance.creditsPanel, 
				MenuState.Help => null, 
				MenuState.CharacterCreation => Instance.newgamePanel, 
				MenuState.Continue => Instance.continuePanel, 
				_ => null, 
			};
		}

		protected override void EnterState(MenuState state)
		{
			fateLogo.SetActive(state == MenuState.Main);
			for (int i = 0; i < cameraTransitions.Length; i++)
			{
				if (cameraTransitions[i].targetState == state)
				{
					if (TweenTG.ValidID(tweenId))
					{
						TweenTG.Stop(tweenId);
					}
					tweenId = TweenTG.TweenTo(cameraTransform, TransformVector3.Position, cameraTransitions[i].targetTform.position, 0.5f, Easing.Mode.ExpoOut);
				}
			}
			if (state == MenuState.Main)
			{
				if (SaveData.CurrentSaveData?.playerSaveData != null)
				{
					SingletonBehaviour<MenuPlayer>.Instance.LoadSaveCharacter(SaveData.CurrentSaveSlot);
				}
				else
				{
					SingletonBehaviour<MenuPlayer>.Instance.SetDefaultState();
				}
			}
		}

		public static bool OnSubPanelBackButton()
		{
			if (Instance != null)
			{
				if (!Instance.gameObject.activeSelf)
				{
					Instance.gameObject.SetActive(value: true);
				}
				Instance.ValidateContinueButton();
				Instance.SetState(MenuState.Main);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
				Instance.fateLogo.SetActive(value: true);
				return true;
			}
			return false;
		}

		public static void ContinueRequested()
		{
			SingletonBehaviour<PortalManager>.Instance.IsUsingTownPortal = false;
			InputSystemUIInputModule inputSystemUIInputModule = (InputSystemUIInputModule)EventSystem.current.currentInputModule;
			if (inputSystemUIInputModule != null)
			{
				inputSystemUIInputModule.actionsAsset.Disable();
			}
			SingletonBehaviour<InputBroker>.Instance.DisableAllInput();
			switch (Fate.CurrentFateVer)
			{
			case Fate.FateVer.Original:
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.IntroAmbientWoods);
				SingletonBehaviour<LoadingScreenUI>.Instance.SetTownRealm(RealmData.RealmId.Grove);
				break;
			case Fate.FateVer.UndiscoveredRealms:
			case Fate.FateVer.TraitorSoul:
			{
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.AmbientCastle);
				RealmData.RealmId townRealm = RealmData.RealmId.TempleOfFate;
				if (SaveData.CurrentSaveData.playerSaveData.lastScene == Scene.Dungeon)
				{
					townRealm = SaveData.CurrentSaveData.playerSaveData.lastDungeonRealm switch
					{
						RealmData.RealmId.Druantia => RealmData.RealmId.Druantia, 
						RealmData.RealmId.Typhon => RealmData.RealmId.Typhon, 
						RealmData.RealmId.Prometheus => RealmData.RealmId.Prometheus, 
						_ => RealmData.RealmId.TempleOfFate, 
					};
				}
				else
				{
					switch (SaveData.CurrentSaveData.playerSaveData.lastScene)
					{
					case Scene.Town_Druantia:
						townRealm = RealmData.RealmId.Druantia;
						break;
					case Scene.Town_Typhon:
						townRealm = RealmData.RealmId.Typhon;
						break;
					case Scene.Town_Prometheus:
						townRealm = RealmData.RealmId.Prometheus;
						break;
					}
				}
				SingletonBehaviour<LoadingScreenUI>.Instance.SetTownRealm(townRealm);
				break;
			}
			case Fate.FateVer.CursedKing:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.AmbientEkbatan);
				SingletonBehaviour<LoadingScreenUI>.Instance.SetTownRealm(RealmData.RealmId.Ekbatan);
				break;
			}
			if (SaveData.CurrentSaveData.playerSaveData.lastScene == Scene.Dungeon)
			{
				SingletonBehaviour<LoadingScreenUI>.Instance.SetToDefault();
			}
			SingletonBehaviour<SystemOverlay>.Instance.FadeToLoadingScreen(delegate
			{
				UtilityTG.StartCoroutine(ContinueGameRoutine(loadAfter: true));
			});
		}

		public static void NewGameRequested()
		{
			SingletonBehaviour<QuestManager>.AssertInstance();
			if (Fate.CurrentFateVer == Fate.FateVer.Original)
			{
				SingletonBehaviour<QuestManager>.Instance.ResetDataForNewGame();
				SingletonBehaviour<QuestManager>.Instance.GetNextOrActiveRealmQuest(SingletonBehaviour<FateDB>.Instance.realmQuests.Where((RealmQuest rq) => rq.targetRealm == RealmData.RealmId.Grove).ToArray(), "Bremen", RealmData.RealmId.Grove);
			}
			SingletonBehaviour<StoryUI>.Instance.DoStory(SingletonBehaviour<FateDB>.Instance.GetGameIntro(Fate.CurrentFateVer), delegate
			{
				InputSystemUIInputModule inputSystemUIInputModule = (InputSystemUIInputModule)EventSystem.current.currentInputModule;
				if (inputSystemUIInputModule != null)
				{
					inputSystemUIInputModule.actionsAsset.Disable();
				}
				Player.isComingFromMenu = false;
				SingletonBehaviour<PortalManager>.Instance.IsUsingTownPortal = false;
				Town.SpawnPointIndex = 0;
				SceneLoad.LoadAsync(SceneLoad.GetTownScene(Fate.CurrentFateVer), save: true, withLoadingScreen: true, null, fadeIn: false);
			});
		}
	}
	public class MenuPlayer : SingletonBehaviour<MenuPlayer>
	{
		[SerializeField]
		private CharacterCustomizationDefaults characterSetup;

		[SerializeField]
		private Transform petLocation;

		[SerializeField]
		private GameObject petGO;

		public bool isUniqueIdlePlaying;

		private Coroutine uniqueIdleCoroutine;

		private Animator anim;

		public float timeSinceUniqueIdle;

		public int HeadCount => characterSetup.GetHeadCount();

		public int HairCount => characterSetup.GetHairCount();

		private void Start()
		{
			if (petGO != null)
			{
				UnityEngine.Object.Destroy(petGO);
				petGO = null;
			}
			if (SaveData.CurrentSaveData?.playerSaveData != null)
			{
				LoadSaveCharacter(SaveData.CurrentSaveSlot);
			}
			else
			{
				SetDefaultState();
			}
			anim = GetComponentInChildren<Animator>(includeInactive: true);
			if (anim != null)
			{
				anim.SetFloat("IdleSpeed", UnityEngine.Random.Range(0.75f, 1.25f));
				anim.SetFloat("IdleOffset", UnityEngine.Random.Range(0f, 0.5f));
			}
		}

		private void Update()
		{
			if (timeSinceUniqueIdle >= 10f)
			{
				TryPlayUniqueIdle();
			}
			timeSinceUniqueIdle += Time.deltaTime;
			if (timeSinceUniqueIdle > 100f)
			{
				timeSinceUniqueIdle = 100f;
			}
		}

		private void TryPlayUniqueIdle()
		{
			if (uniqueIdleCoroutine == null && !isUniqueIdlePlaying)
			{
				uniqueIdleCoroutine = StartCoroutine(PlayUniqueIdleAnim());
			}
			timeSinceUniqueIdle = 0f;
		}

		private IEnumerator PlayUniqueIdleAnim()
		{
			isUniqueIdlePlaying = true;
			anim.SetInteger("UniqueIdleIndex", UnityEngine.Random.Range(1, 3));
			yield return new WaitForSeconds(1f);
			yield return new WaitUntil(() => !IsInState("Unique Idle"));
			ResetPlayerUniqueIdle();
		}

		private void ResetPlayerUniqueIdle()
		{
			if (uniqueIdleCoroutine != null)
			{
				StopCoroutine(uniqueIdleCoroutine);
			}
			anim.SetInteger("UniqueIdleIndex", 0);
			timeSinceUniqueIdle = 0f;
			uniqueIdleCoroutine = null;
			isUniqueIdlePlaying = false;
		}

		private bool IsInState(string stateName)
		{
			return anim.GetCurrentAnimatorStateInfo(0).IsName(stateName);
		}

		public void SetDefaultState()
		{
			SetBodytype(male: true);
			SetRace(Race.Human);
			SetHead(0);
			SetHair(0);
			characterSetup.SetHelmet(null);
			characterSetup.SetGloves(null);
			characterSetup.SetUpper(null);
			characterSetup.SetBack(null);
			characterSetup.SetLeftHand(null);
			characterSetup.SetRightHand(null);
			SpawnPet("Pet_Terrier", dlcCheck: false);
		}

		public void LoadSaveCharacter(SaveData.SaveSlot targetSlot)
		{
			characterSetup.SetHelmet(null);
			characterSetup.SetGloves(null);
			characterSetup.SetUpper(null);
			characterSetup.SetBack(null);
			characterSetup.SetLeftHand(null);
			characterSetup.SetRightHand(null);
			if (targetSlot.saveData?.playerSaveData == null)
			{
				return;
			}
			PlayerSaveData playerSaveData = targetSlot.saveData.playerSaveData;
			SetBodytype(playerSaveData.male);
			SetRace(playerSaveData.playerRace);
			SetHead(playerSaveData.headIndex);
			SetHair(playerSaveData.hairIndex);
			if (!SingletonBehaviour<PlayerStatus>.Instance.IsHandlingRetirement)
			{
				List<ItemSaveData> list = targetSlot.saveData.itemSaveData?.items;
				if (list != null)
				{
					List<ItemSaveData> equipment = list.FindAll((ItemSaveData i) => Fate.IsItemSlotInEquipmentSlot(i.slotIndex));
					if (equipment == null)
					{
						return;
					}
					List<ItemData> allItems = SingletonBehaviour<FateDB>.Instance.AllItems;
					int j = 0;
					while (j < equipment.Count)
					{
						ItemData itemData = allItems.Find((ItemData itm) => itm.displayName == equipment[j].baseName);
						if (!(itemData == null) && ((itemData.ItemCategory != ItemCategory.Weapon && itemData.itemType != ItemType.Shield) || equipment[j].weaponSet == targetSlot.saveData.playerSaveData.activeWeaponSet))
						{
							switch (itemData.itemType)
							{
							case ItemType.Sword:
							case ItemType.Club:
							case ItemType.Shield:
							case ItemType.Spear:
							case ItemType.Bow:
							case ItemType.Polearm:
							case ItemType.Axe:
							case ItemType.Hammer:
							case ItemType.Staff:
							case ItemType.Crossbow:
							{
								List<ElementAmount> damageBonuses = equipment[j].damageBonuses;
								string refId = itemData.refId;
								if (equipment[j].slotIndex == 6)
								{
									characterSetup.SetRightHand(itemData.displayName, damageBonuses, refId);
								}
								else
								{
									characterSetup.SetLeftHand(itemData.displayName, damageBonuses, refId);
								}
								break;
							}
							case ItemType.Helmet:
								characterSetup.SetHelmet(itemData.displayName);
								break;
							case ItemType.Gloves:
								characterSetup.SetGloves(itemData.displayName);
								break;
							case ItemType.Boots:
								characterSetup.SetBoots(itemData.displayName);
								break;
							case ItemType.Shirt:
								characterSetup.SetUpper(itemData.displayName);
								break;
							case ItemType.Back:
								characterSetup.SetBack(itemData.displayName);
								break;
							}
						}
						int num = j + 1;
						j = num;
					}
				}
			}
			string petId = (string.IsNullOrEmpty(playerSaveData.petMonsterId) ? "Pet_Terrier" : playerSaveData.petMonsterId);
			if (!string.IsNullOrEmpty(playerSaveData.petTransformId))
			{
				petId = playerSaveData.petTransformId;
			}
			SpawnPet(petId, dlcCheck: true);
		}

		public void SpawnPet(string petId, bool dlcCheck)
		{
			if (string.IsNullOrEmpty(petId))
			{
				UnityEngine.Debug.LogError("MenuPlayer: Tried spawning pet with invalid id: " + petId);
				return;
			}
			MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData md) => md.displayName == petId);
			if (monsterData == null)
			{
				UnityEngine.Debug.LogError("MenuPlayer: Tried spawning pet, but did not find monster data. id: " + petId);
				return;
			}
			if (dlcCheck)
			{
				var (flag, dlc) = SingletonBehaviour<DLCManager>.Instance.IsDLCPet(monsterData);
				if (flag)
				{
					SingletonBehaviour<DLCManager>.Instance.HasEntitlement(dlc, delegate(bool hasEntitlement)
					{
						if (!hasEntitlement)
						{
							SpawnPet("Pet_Terrier", dlcCheck: false);
						}
						else
						{
							SpawnPet(petId, dlcCheck: false);
						}
					});
					return;
				}
			}
			if (petGO != null)
			{
				UnityEngine.Object.Destroy(petGO);
				petGO = null;
			}
			monsterData.modelPrefab.SetActive(value: false);
			GameObject gameObject = UnityEngine.Object.Instantiate(monsterData.modelPrefab);
			gameObject.TryRemoveComponent<Pet>();
			gameObject.TryRemoveComponent<Monster>();
			gameObject.TryRemoveComponent<NavMeshAgent>();
			gameObject.TryRemoveComponent<CharacterVitals>();
			gameObject.TryRemoveComponent<ThatHurtTrigger>();
			gameObject.TryRemoveComponent<MonsterSounds>();
			gameObject.TryRemoveComponent<AudioSource>();
			gameObject.SetActive(value: true);
			monsterData.modelPrefab.SetActive(value: true);
			Vector3 vector = new Vector3(1.2f, 0f, -0.4f);
			bool flag2 = monsterData.alignment != Alignment.Good;
			gameObject.transform.position = (flag2 ? (petLocation.position + vector) : petLocation.position);
			gameObject.transform.rotation = petLocation.rotation;
			gameObject.transform.localScale = Vector3.one * monsterData.scale.Min;
			petGO = gameObject;
		}

		public void SetHead(int headIndex)
		{
			characterSetup.SetHead(headIndex);
		}

		public void SetHair(int hairIndex)
		{
			characterSetup.SetHair(hairIndex);
		}

		public void SetRace(Race race)
		{
			characterSetup.SetRace(race);
		}

		public void SetBodytype(bool male)
		{
			characterSetup.SetGender(male);
		}
	}
	public class NewgameUI : UIGenericPanel
	{
		public class CharacterCreation
		{
			public Fate.Difficulty difficulty;

			public bool male;

			public string playerName;

			public Race race;

			public int hairIndex;

			public int headIndex;

			public string petName;

			public string petMonsterId;
		}

		public enum CreationStep
		{
			None,
			Difficulty,
			Player,
			Pet
		}

		public Button continueButton;

		public Button backButton;

		[SerializeField]
		private GameObject difficultyParent;

		[SerializeField]
		private CharacterCustomization playerParent;

		[SerializeField]
		private PetCustomization petParent;

		[SerializeField]
		private GameObject descriptionParent;

		[SerializeField]
		private TextMeshProUGUI descTitleText;

		[SerializeField]
		private TextMeshProUGUI descBodyText;

		[SerializeField]
		private TextMeshProUGUI headerText;

		[SerializeField]
		private StoryData introStory;

		private CreationStep currentStep;

		private CharacterCreation currentCharacter;

		public static NewgameUI GetPanel()
		{
			return (NewgameUI)MainMenuUI.GetPanel(MenuState.CharacterCreation);
		}

		protected override void InitPanel()
		{
			base.InitPanel();
			continueButton.onClick.AddListener(OnContinueButton);
			backButton.onClick.AddListener(OnBackButton);
		}

		private void Awake()
		{
			difficultyParent.SetActive(value: false);
			playerParent.gameObject.SetActive(value: false);
			petParent.gameObject.SetActive(value: false);
		}

		private void OnDisable()
		{
			difficultyParent.SetActive(value: false);
			playerParent.gameObject.SetActive(value: false);
			petParent.gameObject.SetActive(value: false);
		}

		private void OnContinueButton()
		{
			switch (currentStep)
			{
			case CreationStep.Difficulty:
				SetStep(CreationStep.Player);
				break;
			case CreationStep.Player:
				if (playerParent.CanContinue())
				{
					SetStep(CreationStep.Pet);
				}
				break;
			case CreationStep.Pet:
				if (petParent.CanContinue())
				{
					StartGame();
				}
				break;
			}
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnBackButton()
		{
			switch (currentStep)
			{
			case CreationStep.Difficulty:
				if (!SingletonBehaviour<PlayerStatus>.Instance.IsHandlingRetirement)
				{
					MainMenuUI.OnSubPanelBackButton();
				}
				break;
			case CreationStep.Player:
				SetStep(CreationStep.Difficulty);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
				break;
			case CreationStep.Pet:
				SetStep(CreationStep.Player);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBack, randomizePitch: false);
				break;
			}
		}

		protected override void OnTweenInBegin()
		{
			base.OnTweenInBegin();
			currentCharacter = new CharacterCreation();
			currentCharacter.male = true;
			SingletonBehaviour<MenuPlayer>.Instance.SetDefaultState();
			playerParent.ResetToNewGameState();
			petParent.ResetToNewGame();
			currentStep = CreationStep.None;
			SetStep(CreationStep.Difficulty);
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed -= Cancel_performed;
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed += Cancel_performed;
		}

		protected override void OnTweenOutComplete()
		{
			base.OnTweenOutComplete();
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed -= Cancel_performed;
		}

		private void Cancel_performed(InputAction.CallbackContext obj)
		{
			OnBackButton();
		}

		public void SetCharChoice(Action<CharacterCreation> setAction)
		{
			setAction(currentCharacter);
		}

		public void SetDescription(string title, string body)
		{
			descTitleText.text = title;
			descBodyText.text = body;
			descriptionParent.SetActive(!string.IsNullOrEmpty(title));
		}

		private void StartGame()
		{
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed -= Cancel_performed;
			if (SingletonBehaviour<PlayerStatus>.Instance.IsHandlingRetirement)
			{
				SaveData.SaveSlot currentSaveSlot = SaveData.CurrentSaveSlot;
				SaveData.CreateNewSaveSlotFromRetirement(JsonUtility.ToJson(currentSaveSlot), currentCharacter);
				SaveData.SetSaveSlotRetired(currentSaveSlot);
			}
			else
			{
				SaveData.CreateNewSaveSlot(currentCharacter);
			}
			MainMenuUI.NewGameRequested();
			base.gameObject.SetActive(value: false);
		}

		private IEnumerator SplashWait()
		{
			InputSystemUIInputModule inputModule = (InputSystemUIInputModule)EventSystem.current.currentInputModule;
			if (inputModule != null)
			{
				inputModule.actionsAsset.Disable();
			}
			SplashScreen.Begin();
			SplashScreen.Draw();
			while (!SplashScreen.isFinished)
			{
				yield return null;
			}
			if (inputModule != null)
			{
				inputModule.actionsAsset.Enable();
			}
		}

		private void SetStep(CreationStep targetStep)
		{
			bool flag = false;
			switch (targetStep)
			{
			case CreationStep.Difficulty:
				if (currentStep == CreationStep.None || currentStep == CreationStep.Player)
				{
					flag = true;
				}
				break;
			case CreationStep.Player:
				if (currentStep == CreationStep.Difficulty || currentStep == CreationStep.Pet)
				{
					flag = true;
				}
				break;
			case CreationStep.Pet:
				if (currentStep == CreationStep.Player)
				{
					flag = true;
				}
				break;
			}
			if (flag)
			{
				currentStep = targetStep;
				difficultyParent.SetActive(currentStep == CreationStep.Difficulty);
				playerParent.gameObject.SetActive(currentStep == CreationStep.Player);
				petParent.gameObject.SetActive(currentStep == CreationStep.Pet);
				switch (currentStep)
				{
				case CreationStep.Difficulty:
					headerText.text = I2Loca.Get("SelectDifficulty");
					backButton.interactable = !SingletonBehaviour<PlayerStatus>.Instance.IsHandlingRetirement;
					break;
				case CreationStep.Player:
					headerText.text = I2Loca.Get("ChooseHero");
					backButton.interactable = true;
					break;
				case CreationStep.Pet:
					headerText.text = I2Loca.Get("ChoosePet");
					backButton.interactable = true;
					break;
				}
				GameObject selected = UtilityTG.GetSelected();
				if (selected != continueButton.gameObject && selected != backButton.gameObject)
				{
					UtilityTG.UnityDelay(delegate
					{
						UtilityTG.SetSelected(continueButton.gameObject);
					});
				}
			}
			else
			{
				UnityEngine.Debug.LogError($"Wrong order of states attempted: to {targetStep} from {currentStep}");
			}
		}
	}
