						if (scriptableRendererFeature != null)
						{
							scriptableRendererFeature.SetActive(SaveData.SettingsSave.ambientOcclusion);
						}
						else
						{
							UnityEngine.Debug.LogWarning("Could not set ambient occlusion in rederer data " + universalRendererData.name + ". Did not find the render feature.");
						}
					}
					Screen.fullScreen = fullScreen;
				}
			});
			fullscreenToggle.SetIsOnWithoutNotify(Screen.fullScreen);
			fullscreenToggle.onValueChanged.AddListener(SetFullScreen);
			senseSlider.onValueChanged.AddListener(OnSenseSlider);
			musicSlider.onValueChanged.AddListener(OnMusicSlider);
			soundSlider.onValueChanged.AddListener(OnSoundSlider);
			voiceSlider.onValueChanged.AddListener(OnVoiceSlider);
			brightnessSlider.onValueChanged.AddListener(OnBrightnessSlider);
			dontChange = true;
			List<string> list = new List<string>();
