		private void UpdateResolutionOptions()
		{
			screenResolutions = new List<Resolution>(Screen.resolutions);
			resolutionDropdown.ClearOptions();
			int num = -1;
			Dictionary<string, Resolution> dictionary = new Dictionary<string, Resolution>();
			for (int i = 0; i < screenResolutions.Count; i++)
			{
				Resolution resolution = screenResolutions[i];
				bool flag = IsResolutionCurrent(resolution);
				if (flag)
				{
					num = i;
				}
				string key = resolution.width + "x" + screenResolutions[i].height;
				if (dictionary.ContainsKey(key))
				{
					if (flag || (!flag && resolution.refreshRateRatio.value > dictionary[key].refreshRateRatio.value))
					{
						int index = i - 1;
						if (!IsResolutionCurrent(screenResolutions[index]))
						{
							dictionary[key] = resolution;
						}
					}
				}
				else
				{
					dictionary.Add(key, resolution);
				}
			}
			List<string> list = new List<string>();
			foreach (KeyValuePair<string, Resolution> item2 in dictionary)
			{
				Resolution value = item2.Value;
				string item = $"{value.width}x{value.height} {(int)value.refreshRateRatio.value} Hz";
				if (IsResolutionCurrent(value))
				{
					num = list.Count;
				}
				list.Add(item);
			}
			screenResolutions = new List<Resolution>(dictionary.Values);
			resolutionDropdown.AddOptions(list);
			if (num == -1)
			{
				num = 0;
			}
			dontChange = true;
			resolutionDropdown.value = num;
			dontChange = false;
			resolutionDropdown.gameObject.SetActive(screenResolutions != null && screenResolutions.Count > 0);
		}

		private bool IsResolutionCurrent(Resolution resolution)
		{
			if (resolution.height == Screen.height && resolution.width == Screen.width)
			{
				return (int)resolution.refreshRateRatio.value == (int)Screen.currentResolution.refreshRateRatio.value;
			}
			return false;
		}

		private void OnEnable()
		{
			UpdateResolutionOptions();
			if (SaveData.HasLoaded)
			{
				shouldSave = false;
				SettingsSave settingsSave = SaveData.SettingsSave;
				tipsToggle.SetIsOnWithoutNotify(settingsSave.displayTips);
				screenshakeToggle.SetIsOnWithoutNotify(settingsSave.screenShake);
				showItemsToggle.SetIsOnWithoutNotify(settingsSave.showItems);
				senseSlider.SetValueWithoutNotify(settingsSave.mouseSenseOverride);
				senseText.text = settingsSave.mouseSenseOverride.ToString();
				musicSlider.SetValueWithoutNotify(settingsSave.musicVolume);
				musicText.text = $"{Mathf.RoundToInt(settingsSave.musicVolume * 100f):0}";
				soundSlider.SetValueWithoutNotify(settingsSave.soundVolume);
				soundText.text = $"{Mathf.RoundToInt(settingsSave.soundVolume * 100f):0}";
				voiceSlider.SetValueWithoutNotify(settingsSave.voiceVolume);
				voiceText.text = $"{Mathf.RoundToInt(settingsSave.voiceVolume * 100f):0}";
				brightnessSlider.SetValueWithoutNotify(settingsSave.brightnessOverride);
				brightnessText.text = $"{settingsSave.brightnessOverride:F1}";
				SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed += Cancel_performed;
				if (!SceneLoad.IsInMainMenuScene)
				{
					UtilityTG.SetSelected(firstSelectedObject);
				}
				dontChange = true;
				if (QualitySettings.vSyncCount == 1)
				{
					vsyncToggle.isOn = true;
				}
				else
				{
					vsyncToggle.isOn = false;
				}
				if (QualitySettings.antiAliasing == 0)
				{
					qualityAALevelDropdown.value = 0;
				}
				else if (QualitySettings.antiAliasing == 2)
				{
					qualityAALevelDropdown.value = 1;
				}
				else if (QualitySettings.antiAliasing == 4)
				{
					qualityAALevelDropdown.value = 2;
				}
				else if (QualitySettings.antiAliasing == 8)
				{
					qualityAALevelDropdown.value = 3;
				}
				qualityLevelDropdown.value = QualitySettings.GetQualityLevel();
				dontChange = false;
			}
		}

