	public class PetCustomization : MonoBehaviour
	{
		[Serializable]
		public class PetSetup
		{
			public GameObject gameObject;

			public MonsterData monsterData;
		}

		public InputFieldRelay nameInputField;

		public Button randomNameBtn;

		public Button petLeftBtn;

		public Button petRightBtn;

		public TextMeshProUGUI petText;

		public Selectable petSelectable;

		public List<MonsterData> petChoices;

		public Animation nameErrorAnim;

		private MenuPlayer menuPlayer;

		private int currentPetIndex;

		private int previousInputSign;

		private NewgameUI newgamePanel;

		private bool hasInitialized;

		private void Awake()
		{
			Init();
		}

		private void Init()
		{
			if (hasInitialized)
			{
				return;
			}
			menuPlayer = UnityEngine.Object.FindFirstObjectByType<MenuPlayer>();
			newgamePanel = NewgameUI.GetPanel();
			InputFieldRelay inputFieldRelay = nameInputField;
			inputFieldRelay.onInputFieldDone = (Action<string>)Delegate.Combine(inputFieldRelay.onInputFieldDone, (Action<string>)delegate(string petname)
			{
				newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation creation)
				{
					creation.petName = petname;
				});
			});
			petLeftBtn.onClick.AddListener(OnPetLeft);
			petRightBtn.onClick.AddListener(OnPetRight);
			randomNameBtn.onClick.AddListener(OnRandomNameClicked);
			hasInitialized = true;
		}

		private void OnRandomNameClicked()
		{
			nameInputField.InputField.text = SingletonBehaviour<NameGenerator>.Instance.GeneratePhonicName();
			newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation creation)
			{
				creation.petName = nameInputField.InputField.text;
			});
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnEnable()
		{
			if (!hasInitialized)
			{
				Init();
			}
			newgamePanel.SetDescription("Pet Customization", "Choose your pet");
			SetPetActive(0);
			((InputSystemUIInputModule)EventSystem.current.currentInputModule).move.action.performed += Action_performed;
			PlatformManager.HasEntitlement(Fate.DLC.Prometheus, delegate(bool hasEntitlement)
			{
				if (!hasEntitlement)
				{
					for (int num = petChoices.Count - 1; num >= 0; num--)
					{
						var (flag, dLC) = SingletonBehaviour<DLCManager>.Instance.IsDLCPet(petChoices[num]);
						if (flag && dLC == Fate.DLC.Prometheus)
						{
							petChoices.RemoveAt(num);
						}
					}
				}
			});
		}

		private void OnDisable()
		{
			if (EventSystem.current != null)
			{
				((InputSystemUIInputModule)EventSystem.current.currentInputModule).move.action.performed -= Action_performed;
			}
		}

		public void ResetToNewGame()
		{
			if (!hasInitialized)
			{
				Init();
			}
			SetPetActive(0);
			nameInputField.InputField.text = "";
		}

		public bool CanContinue()
		{
			if (string.IsNullOrEmpty(nameInputField.InputField.text))
			{
				nameErrorAnim.Play(PlayMode.StopAll);
				return false;
			}
			return true;
		}

		private void Action_performed(InputAction.CallbackContext obj)
		{
			Vector2 vector = obj.ReadValue<Vector2>();
			if (Mathf.Approximately(vector.x, 0f))
			{
				previousInputSign = 0;
			}
			else
			{
				if (Math.Sign(vector.x) == previousInputSign)
				{
					return;
				}
				Selectable selectable = EventSystem.current.currentSelectedGameObject?.GetComponent<Selectable>();
				if (selectable == null)
				{
					return;
				}
				if (vector.x < -0.25f)
				{
					previousInputSign = -1;
					if (selectable == petSelectable)
					{
						OnPetLeft();
					}
				}
				else if (vector.x > 0.25f)
				{
					previousInputSign = 1;
					if (selectable == petSelectable)
					{
						OnPetRight();
					}
				}
			}
		}

		private void OnPetLeft()
		{
			SetPetActive((currentPetIndex <= 0) ? (petChoices.Count - 1) : (currentPetIndex - 1));
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnPetRight()
		{
			SetPetActive((currentPetIndex < petChoices.Count - 1) ? (currentPetIndex + 1) : 0);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void SetPetActive(int index)
		{
			currentPetIndex = index;
			int i = 0;
			while (i < petChoices.Count)
			{
				if (i == index)
				{
					petText.text = I2Loca.Get(petChoices[i].displayName);
					newgamePanel.SetCharChoice(delegate(NewgameUI.CharacterCreation creation)
					{
						creation.petMonsterId = petChoices[i].displayName;
					});
					newgamePanel.SetDescription(petText.text, I2Loca.Get(petChoices[i].displayName + "Description"));
					menuPlayer.SpawnPet(petChoices[i].displayName, dlcCheck: false);
				}
				int num = i + 1;
				i = num;
			}
		}
	}
	public class SaveSlotEntry : MonoBehaviour
	{
		public Toggle toggle;

		public TextMeshProUGUI nameText;

		public TextMeshProUGUI timeText;

		public TextMeshProUGUI levelText;

		public TextMeshProUGUI diffText;

		public TextMeshProUGUI sourceGameText;

		public GameObject retiredParent;

		public GameObject deadParent;

		public Sprite unplayableSprite;

		public Sprite defaultSprite;

		public Image bgImage;

		[Space]
		[Header("Locked/Dead SpriteState")]
		public SpriteState unplayableSpriteState;

		[Space]
		[Header("Default SpriteState")]
		public SpriteState defaultSpriteState;

		public Action<SaveData.SaveSlot, GameObject, bool> onToggleValueChanged;

		private SaveData.SaveSlot slotInfo;

		private void Awake()
		{
			toggle.onValueChanged.AddListener(OnToggle);
		}

		private void OnDestroy()
		{
			toggle.onValueChanged.RemoveListener(OnToggle);
		}

		private void OnToggle(bool value)
		{
			onToggleValueChanged?.Invoke(slotInfo, base.gameObject, value);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		public void SetSaveInfo(SaveData.SaveSlot saveData)
		{
			slotInfo = saveData;
			try
			{
				nameText.text = I2Loca.GetFormat("PlayerTitle", saveData.saveData.playerSaveData.PlayerName, Fate.GetFameName(Fate.GetFameTier(saveData.saveData.playerSaveData.fame)));
				levelText.text = I2Loca.GetFormat("Level_x", Fate.GetLevelFromExperience(saveData.saveData.playerSaveData.experience) + 1);
				TimeSpan timeSpan = TimeSpan.FromSeconds(saveData.secondsPlayed);
				timeText.text = I2Loca.GetFormat("PlayTimeFormat", (int)timeSpan.TotalHours, timeSpan.Minutes, timeSpan.Seconds);
				diffText.text = I2Loca.GetFormatReplaceTags("DifficultyIndicator", I2Loca.Get(saveData.saveData.playerSaveData.difficulty.ToString()));
				if (sourceGameText != null)
				{
					sourceGameText.text = Fate.GetGameName(saveData.targetGame);
				}
				bgImage.sprite = ((saveData.saveState == SaveSlotState.Normal) ? defaultSprite : unplayableSprite);
				if (saveData.saveState == SaveSlotState.Normal)
				{
					toggle.spriteState = defaultSpriteState;
				}
				else
				{
					toggle.spriteState = unplayableSpriteState;
				}
				if (retiredParent != null)
				{
					retiredParent.SetActive(saveData.saveState == SaveSlotState.Retired);
				}
				if (deadParent != null)
				{
					deadParent.SetActive(saveData.saveState == SaveSlotState.Dead);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}
	public class PauseUI : SingletonBehaviour<PauseUI>
	{
		[SerializeField]
		private Button saveQuitButton;

		[SerializeField]
		private Button optionsButton;

		[SerializeField]
		private Button resumeButton;

		[SerializeField]
		private UIGenericPanel optionsParent;

		[SerializeField]
		private GameObject controllerParent;

		[SerializeField]
		private Button controllerBackBtn;

		[SerializeField]
		private OptionsTabs optionTabs;

		[SerializeField]
		private GameObject cheatsParent;

		[SerializeField]
		private Toggle cheatsToggle;

		private InputAction leftToggleAction;

		private InputAction rightToggleAction;

		private bool selfActive;

		protected override bool DontDestroy => false;

		public static bool IsShown => SingletonBehaviour<PauseUI>.Instance.gameObject.activeSelf;

		protected override void Awake()
		{
			saveQuitButton.onClick.AddListener(OnSaveAndQuitButton);
			optionsButton.onClick.AddListener(OnOptionsButton);
			resumeButton.onClick.AddListener(OnResumeButton);
			controllerBackBtn.onClick.AddListener(delegate
			{
				optionTabs.SetTab(OptionsTabs.TabType.None);
				optionTabs.gameObject.SetActive(value: false);
				UtilityTG.SetSelected(optionsButton.gameObject);
			});
			optionTabs.Init();
			cheatsParent.SetActive(Fate.DebugMenuEnabled);
			if (Fate.DebugMenuEnabled && cheatsToggle != null)
			{
				Navigation navigation = saveQuitButton.navigation;
				navigation.selectOnLeft = cheatsToggle;
				saveQuitButton.navigation = navigation;
				navigation = optionsButton.navigation;
				navigation.selectOnLeft = cheatsToggle;
				optionsButton.navigation = navigation;
				navigation = resumeButton.navigation;
				navigation.selectOnLeft = cheatsToggle;
				resumeButton.navigation = navigation;
			}
			base.Awake();
		}

		private void Start()
		{
			base.gameObject.SetActive(value: false);
			selfActive = false;
		}

		private void Update()
		{
			if (leftToggleAction != null && rightToggleAction != null)
			{
				if (leftToggleAction.WasPerformedThisFrame())
				{
					optionTabs.PreviousTab();
				}
				else if (rightToggleAction.WasPerformedThisFrame())
				{
					optionTabs.NextTab();
				}
			}
		}

		private void OnEnable()
		{
			if (!(EventSystem.current == null) && !(EventSystem.current.currentInputModule == null))
			{
				SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed += Cancel_performed;
				if (leftToggleAction == null || rightToggleAction == null)
				{
					leftToggleAction = SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.LeftToggle;
					rightToggleAction = SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.RightToggle;
					leftToggleAction.Enable();
					rightToggleAction.Enable();
				}
			}
		}

		private void OnDisable()
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Cancel.performed -= Cancel_performed;
			}
		}

		private void Cancel_performed(InputAction.CallbackContext context)
		{
		}

		public void OnMenuButton()
		{
			if (selfActive)
			{
				if (optionTabs.CurrentTab != OptionsTabs.TabType.None)
				{
					optionTabs.SetTab(OptionsTabs.TabType.None);
					optionTabs.gameObject.SetActive(value: false);
					UtilityTG.SetSelected(optionsButton.gameObject);
				}
				else
				{
					base.gameObject.SetActive(value: false);
					selfActive = false;
					Fate.SetPause(paused: false);
				}
			}
			else
			{
				base.gameObject.SetActive(value: true);
				selfActive = true;
				Fate.SetPause(paused: true);
				UtilityTG.SetSelected(resumeButton.gameObject);
				optionTabs.gameObject.SetActive(value: false);
				SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			}
		}

		private void OnSaveAndQuitButton()
		{
			base.gameObject.SetActive(value: false);
			Fate.SetPause(paused: true);
			SingletonBehaviour<AudioManager>.Instance.StopMusic();
			if (Player.PlayerChar.isHeartBeatPlaying)
			{
				SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.Heartbeat);
				Player.PlayerChar.isHeartBeatPlaying = false;
			}
			if (LevelGenerator.currentInstance != null)
			{
				LevelGenerator.currentInstance.UpdateSaveData(goesDown: false);
			}
			SceneLoad.LoadMainMenuCurrentGame(saveFirst: true, delegate
			{
				Fate.SetPause(paused: false);
			});
			InputBlocker.MuteForFrames(60);
		}

		private void OnOptionsButton()
		{
			optionTabs.gameObject.SetActive(value: true);
			optionTabs.SetTab(OptionsTabs.TabType.Options);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnResumeButton()
		{
			base.gameObject.SetActive(value: false);
			selfActive = false;
			Fate.SetPause(paused: false);
			SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Game);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}
	}
	public class PromptUI : SingletonBehaviour<PromptUI>
	{
		[SerializeField]
		private Button positiveButton;

		[SerializeField]
		private Button negativeButton;

		[SerializeField]
		private TextMeshProUGUI bodyText;

		[SerializeField]
		private TextMeshProUGUI positiveButtonText;

		[SerializeField]
		private TextMeshProUGUI negativeButtonText;

		[SerializeField]
		private UiBlockingPanel uiBlockPanel;

		private const string positiveDefaultKey = "Yes";

		private const string negativeDefaultKey = "No";

		private const string singleButtonDefault = "OK";

		private Action<bool> onPromptResolve;

		private GameObject prePromptSelected;

		private bool prePromptCursorActive;

		private InputBroker.InputMode prePromptInputMode;

		protected override bool DontDestroy => true;

		public static bool IsPromptActive { get; private set; }

		protected override void Awake()
		{
			base.Awake();
			positiveButton.onClick.AddListener(OnButtonPositive);
			negativeButton.onClick.AddListener(OnButtonNegative);
		}

		private void Start()
		{
			base.gameObject.SetActive(value: false);
			IsPromptActive = false;
		}

		public void ForceClosePrompt()
		{
			onPromptResolve = null;
			base.gameObject.SetActive(value: false);
			IsPromptActive = false;
		}

		public void ShowPromptRaw(string body, Action<bool> onDone, bool twoButtons, string positiveOverride = null, string negativeOverride = null)
		{
			bodyText.text = body;
			positiveButtonText.text = I2Loca.Get(positiveOverride ?? "Yes");
			negativeButtonText.text = I2Loca.Get(negativeOverride ?? "No");
			negativeButton.gameObject.SetActive(twoButtons);
			onPromptResolve = delegate
			{
				OnPromptResolve();
			};
			if (onDone != null)
			{
				onPromptResolve = (Action<bool>)Delegate.Combine(onPromptResolve, onDone);
			}
			prePromptInputMode = SingletonBehaviour<InputBroker>.Instance.ActiveInputMode;
			SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Menu);
			SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Submit.Disable();
			UtilityTG.UnityDelay(SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Submit.Enable);
			base.gameObject.SetActive(value: true);
			UtilityTG.UIForceRebuildLayout(base.gameObject);
			prePromptSelected = EventSystem.current.currentSelectedGameObject;
			if (SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				prePromptCursorActive = SingletonBehaviour<CursorManager>.Instance.VirtualCursorActive;
				if (prePromptCursorActive)
				{
					SingletonBehaviour<CursorManager>.Instance.SetVirtualCursorActive(state: false);
				}
			}
			UtilityTG.SetSelected(positiveButton.gameObject);
			IsPromptActive = true;
		}

		public void ShowPrompt(string bodyKey, Action<bool> onDone, string positiveOverride = "Yes", string negativeOverride = "No")
		{
			ShowPromptRaw(I2Loca.GetMultiLineReplaceTags(bodyKey), onDone, twoButtons: true, positiveOverride, negativeOverride);
		}

		public void ShowPromptSingleButton(string bodyKey, Action onDone, string buttonOverride = "OK")
		{
			ShowPromptRaw(I2Loca.GetMultiLineReplaceTags(bodyKey), delegate
			{
				onDone?.Invoke();
			}, twoButtons: false, buttonOverride);
		}

		private void OnPromptResolve()
		{
			base.gameObject.SetActive(value: false);
			if (prePromptSelected != null && prePromptSelected.activeInHierarchy)
			{
				UtilityTG.SetSelected(prePromptSelected);
				prePromptSelected = null;
			}
			if (prePromptCursorActive && SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				SingletonBehaviour<CursorManager>.Instance.SetVirtualCursorActive(state: true);
			}
			InputBlocker.MuteForFrames(6);
			IsPromptActive = false;
			SingletonBehaviour<InputBroker>.Instance.SetInputMode(prePromptInputMode);
		}

		private void OnButtonPositive()
		{
			onPromptResolve?.Invoke(obj: true);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		private void OnButtonNegative()
		{
			onPromptResolve?.Invoke(obj: false);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}
	}
