	public class StoryUI : SingletonBehaviour<StoryUI>
	{
		private const float defaultPageTime = 40f;

		public Image storyImage;

		public TextMeshProUGUI mainText;

		public Button continueButton;

		public AudioSource narrationAudio;

		public CanvasGroup imageCG;

		public CanvasGroup mainCG;

		private RectTransform textRT;

		private StoryData currentStory;

		private bool skipRequested;

		private Coroutine storyRoutine;

		private Action onCurrStoryDone;

		private TweenTGGroup tweenGroup = new TweenTGGroup();

		protected override bool DontDestroy => true;

		protected override void Init()
		{
			continueButton.onClick.AddListener(OnContinueButton);
			textRT = mainText.GetComponent<RectTransform>();
			base.gameObject.SetActive(value: false);
		}

		private void OnContinueButton()
		{
			skipRequested = true;
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
		}

		public void DoStory(StoryData storyData, Action onStoryDone)
		{
			SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Menu);
			currentStory = storyData;
			onCurrStoryDone = onStoryDone;
			if (storyRoutine != null)
			{
				StopCoroutine(storyRoutine);
			}
			base.gameObject.SetActive(value: true);
			storyRoutine = StartCoroutine(RunStory());
			UtilityTG.UnityDelay(delegate
			{
				UtilityTG.SetSelected(continueButton.gameObject);
			});
		}

		private IEnumerator RunStory()
		{
			if (currentStory == null || currentStory.pages == null)
			{
				UnityEngine.Debug.LogError("Invalid/Missing Story to Run");
				yield break;
			}
			StoryData.Page[] pages = currentStory.pages;
			Coroutine imgRoutine = null;
			switch (Fate.CurrentFateVer)
			{
			case Fate.FateVer.Original:
				SingletonBehaviour<AudioManager>.Instance.StopMusic();
				break;
			case Fate.FateVer.UndiscoveredRealms:
				SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.AmbientTempleOfFate, stopOthers: true);
				break;
			case Fate.FateVer.TraitorSoul:
				SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.AmbientTempleOfFate, stopOthers: true);
				break;
			case Fate.FateVer.CursedKing:
				SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.StepTyphonSnow, stopOthers: true);
				break;
			default:
				SingletonBehaviour<AudioManager>.Instance.PlayMusic(AudioData.AudioClipName.IntroFate1, stopOthers: true);
				break;
			}
			int num;
			for (int i = 0; i < pages.Length; num = i + 1, i = num)
			{
				StoryData.Page page = pages[i];
				SingletonBehaviour<Narrator>.Instance.StopAudio();
				SingletonBehaviour<Narrator>.Instance.PlayYourLine(page.narratorEnum);
				if (page.textProvidedByRealmQuest)
				{
					Quest realmQuestActiveTownRealm = SingletonBehaviour<QuestManager>.Instance.GetRealmQuestActiveTownRealm();
					if (realmQuestActiveTownRealm == null)
					{
						UnityEngine.Debug.LogError("TextProvidedByRealmQuest checked but no RealmQuest provided: " + currentStory.name);
						continue;
					}
					mainText.text = realmQuestActiveTownRealm.GetQuestDescription();
				}
				else
				{
					mainText.text = I2Loca.GetMultiLineReplaceTags(page.text);
				}
				LayoutRebuilder.ForceRebuildLayoutImmediate(textRT);
				Vector2 textGoalPos;
				if (page.textScrolling)
				{
					textRT.anchorMin = Vector2.zero;
					textRT.anchorMax = Vector2.right;
					textRT.anchoredPosition = new Vector2(textRT.anchoredPosition.x, 0f);
					textGoalPos = new Vector2(textRT.anchoredPosition.x, textRT.sizeDelta.y);
				}
				else
				{
					textRT.anchorMin = Vector2.up;
					textRT.anchorMax = Vector2.one;
					textRT.anchoredPosition = new Vector2(textRT.anchoredPosition.x, 0f);
					textGoalPos = textRT.anchoredPosition;
				}
				Vector2 textStartPos = textRT.anchoredPosition;
				float time2 = ((SingletonBehaviour<Narrator>.Instance.CurrentStoryAudioclip(page.narratorEnum) != null) ? SingletonBehaviour<Narrator>.Instance.CurrentStoryAudioclip(page.narratorEnum).length : 40f);
				imgRoutine = StartCoroutine(ImageRoutine(page.mainSprites, page.textScrolling ? time2 : (time2 * 0.5f)));
				mainCG.alpha = 1f;
				if (page.textScrolling)
				{
					time2 = Mathf.Max(time2 + -15f, 0.1f);
					float animDoneTime = time2;
					while (time2 > 0f)
					{
						time2 -= Time.unscaledDeltaTime;
						float t = Mathf.Clamp01(1f - time2 / animDoneTime);
						textRT.anchoredPosition = Vector2.Lerp(textStartPos, textGoalPos, t);
						if (skipRequested)
						{
							time2 = 0.1f;
						}
						skipRequested = false;
						yield return null;
					}
					if (imgRoutine != null)
					{
						StopCoroutine(imgRoutine);
						imgRoutine = null;
						tweenGroup.Stop();
						storyImage.sprite = page.mainSprites[^1];
						imageCG.alpha = 1f;
					}
				}
				while (!skipRequested)
				{
					yield return null;
				}
				if (!page.textScrolling && imgRoutine != null)
				{
					StopCoroutine(imgRoutine);
					imgRoutine = null;
					tweenGroup.Stop();
					storyImage.sprite = page.mainSprites[^1];
					imageCG.alpha = 1f;
				}
				if (i < pages.Length - 1)
				{
					float fadeTimer = 1f;
					while (fadeTimer > 0f)
					{
						float alpha = fadeTimer / 1f;
						mainCG.alpha = alpha;
						fadeTimer -= Time.unscaledDeltaTime;
						yield return null;
					}
				}
				skipRequested = false;
			}
			SingletonBehaviour<SystemOverlay>.Instance.FadeToBlack(delegate
			{
				onCurrStoryDone?.Invoke();
				storyRoutine = null;
				imgRoutine = null;
				tweenGroup.Stop();
				SingletonBehaviour<Narrator>.Instance.StopAudio();
				switch (Fate.CurrentFateVer)
				{
				case Fate.FateVer.Original:
					SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.IntroAmbientWoods);
					break;
				case Fate.FateVer.UndiscoveredRealms:
					SingletonBehaviour<AudioManager>.Instance.StopMusic();
					SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.AmbientCastle);
					break;
				case Fate.FateVer.TraitorSoul:
					SingletonBehaviour<AudioManager>.Instance.StopMusic();
					SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.AmbientCastle);
					break;
				case Fate.FateVer.CursedKing:
					SingletonBehaviour<AudioManager>.Instance.StopMusic();
					SingletonBehaviour<AudioManager>.Instance.StopAudioClip(AudioData.AudioClipName.AmbientEkbatan);
					break;
				}
				base.gameObject.SetActive(value: false);
				SingletonBehaviour<SystemOverlay>.Instance.DisableFadeScreen();
			}, 1f);
		}

		private IEnumerator ImageRoutine(Sprite[] sprites, float pageDuration)
		{
			float duration = 0f;
			int spriteCount = sprites.Length;
			imageCG.alpha = 0f;
			int currSpriteIndex = 0;
			float fadeTime = 0.5f;
			SetImage(currSpriteIndex, fadeOut: false);
			while (duration < pageDuration)
			{
				duration += Time.deltaTime;
				int num = Mathf.Min(Mathf.FloorToInt(duration / pageDuration * (float)spriteCount), spriteCount - 1);
				if (num != currSpriteIndex)
				{
					currSpriteIndex = num;
					SetImage(currSpriteIndex, fadeOut: true);
				}
				yield return null;
			}
			void SetImage(int index, bool fadeOut)
			{
				tweenGroup.Stop();
				if (fadeOut)
				{
					tweenGroup.Add(TweenTG.Tween(imageCG, 1f, 0f, 0f - fadeTime, Easing.Mode.Linear, delegate
					{
						storyImage.sprite = sprites[index];
						tweenGroup.Add(TweenTG.TweenTo(imageCG, 1f, 0f - fadeTime));
					}));
				}
				else
				{
					storyImage.sprite = sprites[index];
					tweenGroup.Add(TweenTG.Tween(imageCG, 0f, 1f, 0f - fadeTime));
				}
			}
		}
	}
	public class SystemOverlay : SingletonBehaviour<SystemOverlay>
	{
		[SerializeField]
		private CanvasGroup fadeCG;

		private int fadeOutTweenId = -1;

		private int fadeInTweenId = -1;

		protected override bool DontDestroy => true;

		public void FadeToBlack(Action onDone, float overrideDuration = 2.5f)
		{
			if (TweenTG.ValidID(fadeOutTweenId))
			{
				TweenTG.Stop(fadeOutTweenId);
			}
			SingletonBehaviour<SystemOverlay>.Instance.fadeCG.blocksRaycasts = true;
			fadeOutTweenId = TweenTG.Tween(SingletonBehaviour<SystemOverlay>.Instance.fadeCG, 0f, 1f, 0f - Mathf.Abs(overrideDuration), Easing.Mode.Linear, onDone);
		}

		public void FadeToClear(Action onDone, bool ignoreIfAlreadyClear, float overrideDuration = 2f)
		{
			if (TweenTG.ValidID(fadeInTweenId))
			{
				TweenTG.Stop(fadeInTweenId);
			}
			if (ignoreIfAlreadyClear && Mathf.Approximately(fadeCG.alpha, 0f))
			{
				fadeCG.alpha = 0f;
				fadeCG.blocksRaycasts = false;
				onDone?.Invoke();
			}
			else
			{
				onDone = (Action)Delegate.Combine(onDone, (Action)delegate
				{
					fadeCG.blocksRaycasts = false;
				});
				fadeInTweenId = TweenTG.Tween(fadeCG, 1f, 0f, 0f - Mathf.Abs(overrideDuration), Easing.Mode.Linear, onDone);
			}
		}

		public void FadeToLoadingScreen(Action onDone, float overrideDuration = 1f)
		{
			FadeToBlack(delegate
			{
				SingletonBehaviour<LoadingScreenUI>.Instance.ShowLoading(fadeIn: false);
				FadeToClear(delegate
				{
					onDone?.Invoke();
				}, ignoreIfAlreadyClear: false, 0.25f);
			}, overrideDuration);
		}

		public void DisableFadeScreen()
		{
			if (TweenTG.ValidID(fadeInTweenId))
			{
				TweenTG.Stop(fadeInTweenId);
			}
			if (TweenTG.ValidID(fadeOutTweenId))
			{
				TweenTG.Stop(fadeOutTweenId);
			}
			fadeCG.alpha = 0f;
			fadeCG.blocksRaycasts = false;
		}
	}
	public class TooltipUI : MonoBehaviour
	{
		private struct Row
		{
			public string text;

			public bool showBackground;

			public Color color;
		}

		[SerializeField]
		private TextMeshProUGUI titleText;

		[SerializeField]
		private TooltipUIEntry entryTemplate;

		[SerializeField]
		private CanvasGroup canvasGroup;

		[Header("Colors")]
		[SerializeField]
		private Color greenColor;

		[SerializeField]
		private Color redColor;

		[SerializeField]
		private Color blueColor;

		[SerializeField]
		private Color yellowColor;

		[SerializeField]
		private Color tealColor;

		[SerializeField]
		private Color purpleColor;

		[SerializeField]
		private Color greyColor;

		[SerializeField]
		private float itemNameAlphaOverride;

		private List<TooltipUIEntry> entries;

		private bool hasInitialized;

		private void Awake()
		{
			if (!hasInitialized)
			{
				Init();
				HideTooltip();
			}
		}

		public void Init()
		{
			if (!hasInitialized)
			{
				entries = new List<TooltipUIEntry> { entryTemplate };
				hasInitialized = true;
			}
		}

		public void HideTooltip()
		{
			titleText.text = "";
			entries.AssertComponentCount(0);
			canvasGroup.alpha = 0f;
		}

		public void ShowTooltip(Item targetItem, bool shopOpen = false, Character owner = null)
		{
			if (targetItem == null)
			{
				UnityEngine.Debug.LogError("Tried to display tooltip of item that is null");
				return;
			}
			titleText.gameObject.SetActive(value: false);
			List<Row> rows = new List<Row>();
			if (shopOpen && owner != null)
			{
				if (owner.IsPlayer())
				{
					if (!targetItem.itemData.notSellable && targetItem.itemType != ItemType.Tarot)
					{
						rows.Add(new Row
						{
							text = I2Loca.GetFormat("Tooltip_SellPrice", targetItem.SellValue()),
							showBackground = true,
							color = yellowColor
						});
					}
				}
				else
				{
					uint purchaseValueByMerchant = targetItem.GetPurchaseValueByMerchant(SimpleSingletonBehaviour<PlayerUI>.Instance.InventoryUI.ActiveMerchantType);
					bool flag = purchaseValueByMerchant <= SingletonBehaviour<PlayerStatus>.Instance.gold;
					rows.Add(new Row
					{
						text = I2Loca.GetFormat("Tooltip_BuyPrice", purchaseValueByMerchant),
						showBackground = !flag,
						color = redColor
					});
				}
			}
			bool flag2 = targetItem.ShowRarityToPlayer(owner);
			Color color = (targetItem.isArtifact ? yellowColor : ((!targetItem.isUnique) ? purpleColor : tealColor));
			color.a = itemNameAlphaOverride;
			rows.Add(new Row
			{
				text = targetItem.ItemDisplayName,
				showBackground = (targetItem.HasSpecialEffects && flag2),
				color = color
			});
			if (targetItem.sockets > 0)
			{
				int num = ((targetItem.sockedtedItems == null) ? targetItem.sockets : (targetItem.sockets - targetItem.sockedtedItems.Count));
				if (num > 0)
				{
					string text = ((num == 1) ? I2Loca.Get("Tooltip_SingleSocket") : I2Loca.GetFormat("Tooltip_MultiSocket", num));
					rows.Add(new Row
					{
						text = text,
						showBackground = true,
						color = greyColor
					});
				}
			}
			if (targetItem.category == ItemCategory.Weapon)
			{
				if (targetItem.itemData.IsTwoHanded)
				{
					rows.Add(new Row
					{
						text = I2Loca.Get("TwoHanded"),
						showBackground = false
					});
				}
				rows.Add(new Row
				{
					text = Fate.GetDamageTypeString(targetItem.baseDamageType),
					showBackground = false
				});
			}
			if (flag2)
			{
				for (int i = 0; i < targetItem.damageBonuses.Count; i++)
				{
					ElementAmount elementAmount = targetItem.damageBonuses[i];
					if (elementAmount.value != 0)
					{
						char c = ((elementAmount.value > 0) ? '+' : '-');
						rows.Add(new Row
						{
							text = $"{c}{elementAmount.value} {Fate.GetDamageTypeString(elementAmount.type)}",
							showBackground = true,
							color = purpleColor
						});
					}
				}
			}
			if (targetItem.category == ItemCategory.Weapon)
			{
				rows.Add(new Row
				{
					text = I2Loca.GetFormat("Tooltip_AttackDamage", $"{targetItem.minimumDamage}-{targetItem.maximumDamage}"),
					showBackground = false
				});
				rows.Add(new Row
				{
					text = Fate.GetItemTypeClassString(targetItem.itemType) + " - " + I2Loca.Get(targetItem.itemData.speed.ToString()),
					showBackground = false
				});
			}
			else if (targetItem.category == ItemCategory.Armor || targetItem.category == ItemCategory.Jewelry)
			{
				rows.Add(new Row
				{
					text = Fate.GetItemTypeClassString(targetItem.itemType),
					showBackground = false
				});
				if (targetItem.category == ItemCategory.Armor)
				{
					rows.Add(new Row
					{
						text = I2Loca.GetFormat("Tooltip_Defense", targetItem.Armor()),
						showBackground = false
					});
				}
			}
			SpellData spellData = null;
			if (!targetItem.Identified)
			{
				if (flag2)
				{
					rows.Add(new Row
					{
						text = I2Loca.GetMultiLineFormat("Tooltip_Unidentified", targetItem.baseLevel),
						showBackground = true,
						color = blueColor
					});
				}
			}
			else if (targetItem.itemType == ItemType.Gem)
			{
				rows.Add(new Row
				{
					text = I2Loca.Get("Tooltip_SocketUninstalled"),
					showBackground = true,
					color = greyColor
				});
				if (targetItem.effects.TryGetValue(ActivationType.Passive, out var value))
				{
					for (int j = 0; j < value.Count; j++)
					{
						EffectData effectData2 = value[j];
						if (effectData2.buffType == EffectType.AddDamageType)
						{
							DamageType damageType = FateParseHelper.ParseEnum<DamageType>(effectData2.name);
							rows.Add(new Row
							{
								text = I2Loca.GetIgnoreLinebreaksFormat("Tooltip_GemAddsToWeapon", effectData2.value, I2Loca.Get($"DamageType_{damageType}")),
								showBackground = true,
								color = purpleColor
							});
							EffectType resistType = Fate.ConvertDamageTypeToResistance(damageType);
							rows.Add(new Row
							{
								text = I2Loca.GetIgnoreLinebreaksFormat("Tooltip_GemAddsToArmor", effectData2.value * 4, Fate.GetResistanceString(resistType)),
								showBackground = true,
								color = purpleColor
							});
						}
						else
						{
							rows.Add(new Row
							{
								text = I2Loca.GetFormat("Tooltip_GemWhenInstalled", I2Loca.GetIgnoreLinebreaksFormat("Tooltip_GemAdds", effectData2.value, effectData2.GenerateTooltipString(EffectData.TooltipSource.Gem))),
								showBackground = true,
								color = (effectData2.IsPositive ? purpleColor : redColor)
							});
						}
					}
				}
			}
			else
			{
				foreach (KeyValuePair<ActivationType, List<EffectData>> effect in targetItem.effects)
				{
					for (int k = 0; k < effect.Value.Count; k++)
					{
						EffectData effectData = effect.Value[k];
						if (effectData.buffType == EffectType.WriteSpell)
						{
							spellData = SingletonBehaviour<FateDB>.Instance.allSpells.Find((SpellData sp) => sp.spellName == effectData.name);
						}
						if (effectData.buffType == EffectType.RevertTransform)
						{
							rows.Add(new Row
							{
								text = effectData.GenerateTooltipString(EffectData.TooltipSource.Item),
								showBackground = true,
								color = purpleColor
							});
							continue;
						}
						EffectType buffType = effectData.buffType;
						if (buffType == EffectType.AttackBonus_DEPRECATED || buffType == EffectType.PercentLifeRecovery_DEPRECATED || buffType == EffectType.PercentReducedItemRequirements_DEPRECATED)
						{
							continue;
						}
						buffType = effectData.buffType;
						if (buffType == EffectType.EndgameUrn || buffType == EffectType.EndgameHammer)
						{
							rows.Add(new Row
							{
								text = I2Loca.Get("MainQuestItem"),
								showBackground = true,
								color = purpleColor
							});
						}
						else
						{
							if (effectData.value == 0 && effectData.value2 == 0)
							{
								continue;
							}
							if (effectData.buffType == EffectType.RealmPortal)
							{
								RealmData.RealmId value2 = (RealmData.RealmId)effectData.value;
								rows.Add(new Row
								{
									text = I2Loca.Get($"SpellDescription_{value2}Portal"),
									showBackground = true,
									color = purpleColor
								});
								continue;
							}
							rows.Add(new Row
							{
								text = effectData.GenerateTooltipString(EffectData.TooltipSource.Item),
								showBackground = true,
								color = (effectData.IsPositive ? purpleColor : redColor)
							});
							if (effectData.buffType == EffectType.Transform)
							{
								Character pet = Player.PlayerChar.GetPet();
								int strength = pet.monsterData.strength;
								int dexterity = pet.monsterData.dexterity;
								int vitality = pet.monsterData.vitality;
								int magic = pet.monsterData.magic;
								int naturalArmor = pet.monsterData.naturalArmor;
								MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData d) => d.displayName == effectData.name);
								int strength2 = monsterData.strength;
								int dexterity2 = monsterData.dexterity;
								int vitality2 = monsterData.vitality;
								int magic2 = monsterData.magic;
								int naturalArmor2 = monsterData.naturalArmor;
								AddTransformStatRow(ref rows, "Strength", strength, strength2);
								AddTransformStatRow(ref rows, "Dexterity", dexterity, dexterity2);
								AddTransformStatRow(ref rows, "Vitality", vitality, vitality2);
								AddTransformStatRow(ref rows, "Magic", magic, magic2);
								AddTransformStatRow(ref rows, "Armor", naturalArmor, naturalArmor2);
							}
						}
					}
				}
			}
			if (spellData != null)
			{
				Color color2 = spellData.sphereType switch
				{
					SpellSphere.Attack => redColor, 
					SpellSphere.Defense => blueColor, 
					SpellSphere.Charm => greenColor, 
					_ => Color.clear, 
				};
				rows.Add(new Row
				{
					text = I2Loca.Get($"TooltipSphere{spellData.sphereType}Magic"),
					showBackground = true,
					color = color2
				});
			}
			if (targetItem.useable)
			{
				rows.Add(new Row
				{
					text = I2Loca.GetFormat("Tooltip_Uses", targetItem.uses),
					showBackground = false
				});
			}
			if ((targetItem.useable || targetItem.itemType == ItemType.Gem) && !SimpleSingletonBehaviour<PlayerUI>.Instance.IsAnythingTargetingItem && owner != null && owner.IsPlayerOwnedInventory)
			{
				bool num2 = SingletonBehaviour<Town>.InstanceExists();
				bool flag3 = targetItem.effects != null && targetItem.effects.ContainsKey(ActivationType.Usage) && targetItem.effects[ActivationType.Usage].Find((EffectData e) => e.buffType == EffectType.OpenPortal) != null;
				if (num2 && flag3)
				{
					rows.Add(new Row
					{
						text = I2Loca.Get("<style=C1>") + I2Loca.Get("Tooltip_NotUsableInTown") + I2Loca.Get("</style>"),
						showBackground = true,
						color = blueColor
					});
				}
				else if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove)
				{
					rows.Add(new Row
					{
						text = I2Loca.Get("<style=C1>") + I2Loca.GetMultiLine("Tooltip_RightClickToUse") + I2Loca.Get("</style>"),
						showBackground = true,
						color = blueColor
					});
				}
			}
			Character character = ((owner != null && owner.IsPlayerOwnedInventory) ? owner : Player.PlayerChar);
			for (int l = 0; l < targetItem.itemRequirements.Count; l++)
			{
				AttributeData attributeData = targetItem.itemRequirements[l];
				float num3 = Mathf.Clamp01(1f - character.EffectValue(EffectType.PercentItemRequirements) / 100f);
				Color color3 = (character.RequirementMet(attributeData.attribute, attributeData.value, allowEffects: true, num3) ? greenColor : redColor);
				rows.Add(new Row
				{
					text = attributeData.ToRequirementString(num3),
					showBackground = true,
					color = color3
				});
			}
			if (spellData != null)
			{
				if (character.KnowsSpell(spellData))
				{
					rows.Add(new Row
					{
						text = I2Loca.GetIgnoreLinebreaks("Tooltip_AlreadyLearnedSpell"),
						showBackground = true,
						color = redColor
					});
				}
				if (spellData.IsSummonSpell())
				{
					rows.Add(new Row
					{
						text = I2Loca.GetMultiLineReplaceTagsFormat(spellData.description, Fate.MaxSummons),
						showBackground = false
					});
				}
				else if (spellData.IsPortalSpell() && spellData.sphereType == SpellSphere.Charm)
				{
					rows.Add(new Row
					{
						text = I2Loca.GetMultiLineReplaceTagsFormat(spellData.description, I2Loca.Get($"RealmName_{SingletonBehaviour<PlayerStatus>.Instance.TownRealm}")),
						showBackground = false
					});
				}
				else
				{
					rows.Add(new Row
					{
						text = I2Loca.GetMultiLineReplaceTags(spellData.description),
						showBackground = false
					});
				}
			}
			if (targetItem.lockedForSelling)
			{
				rows.Add(new Row
				{
					text = I2Loca.Get("Tooltip_LockedForSelling"),
					showBackground = false
				});
			}
			entries.AssertComponentCount(rows.Count);
			for (int m = 0; m < rows.Count; m++)
			{
				Row row = rows[m];
				entries[m].Set(row.text, row.showBackground, row.color);
				entries[m].gameObject.SetActive(value: true);
			}
			canvasGroup.alpha = 1f;
			UtilityTG.UIForceRebuildLayout(base.gameObject);
		}

		public void ShowTooltip(SpellData spellData)
		{
			List<Row> list = new List<Row>();
			titleText.gameObject.SetActive(value: false);
			list.Add(new Row
			{
				text = I2Loca.Get(spellData.spellName),
				showBackground = true,
				color = purpleColor
			});
			Color clear;
			switch (spellData.sphereType)
			{
			case SpellSphere.Attack:
				clear = redColor;
				break;
			case SpellSphere.Defense:
				clear = blueColor;
				break;
			case SpellSphere.Charm:
				clear = greenColor;
				break;
			default:
				clear = Color.clear;
				UnityEngine.Debug.LogWarning($"Bad spell sphere {spellData.sphereType}");
				break;
			}
			list.Add(new Row
			{
				text = I2Loca.Get("TooltipSphere" + spellData.sphereType.ToString() + "Magic"),
				showBackground = true,
				color = clear
			});
			string text = null;
			switch (spellData.targetType)
			{
			case ItemTarget.User:
			case ItemTarget.MasterOrUser:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetCaster");
				break;
			case ItemTarget.Character:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetCreature");
				break;
			case ItemTarget.Area:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetArea");
				break;
			case ItemTarget.Item:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetItem");
				break;
			case ItemTarget.CharacterArea:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetCreatureArea");
				break;
			case ItemTarget.UserArea:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetCasterArea");
				break;
			case ItemTarget.UserPets:
			case ItemTarget.UserParty:
			case ItemTarget.MasterOrUserPets:
			case ItemTarget.MasterOrUserParty:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetCastersMinions");
				break;
			case ItemTarget.CharacterPets:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetCreaturesMinions");
				break;
			case ItemTarget.UserAndPets:
			case ItemTarget.UserAndPetsAndParty:
			case ItemTarget.UserAndParty:
			case ItemTarget.MasterOrUserAndPets:
			case ItemTarget.MasterOrUserAndPetsAndParty:
			case ItemTarget.MasterOrUserAndParty:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetCasterAndMinions");
				break;
			case ItemTarget.CharacterAndPets:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetCreatureAndMinions");
				break;
			case ItemTarget.Projectile:
			case ItemTarget.ProjectileMult:
				text = I2Loca.GetIgnoreLinebreaks("TooltipTargetProjectile");
				break;
			}
			if (text != null)
			{
				list.Add(new Row
				{
					text = I2Loca.GetIgnoreLinebreaks("TooltipTarget") + " " + text,
					showBackground = false
				});
			}
			float num = spellData.castTime * Player.PlayerChar.CalculateSpellCastSpeedMultiplier();
			list.Add(new Row
			{
				text = I2Loca.GetIgnoreLinebreaksFormat("TooltipCastingTime", num.ToString(".0")),
				showBackground = false
			});
			list.Add(new Row
			{
				text = string.Format("{0} {1}", I2Loca.GetIgnoreLinebreaksFormat("TooltipManaCost"), spellData.manaCost),
				showBackground = true,
				color = blueColor
			});
			List<EffectData> list2 = new List<EffectData>();
			list2.AddRange(spellData.effects);
			list2.AddRange(spellData.payloadEffects);
			int num2 = 0;
			switch (spellData.sphereType)
			{
			case SpellSphere.Attack:
				num2 = Player.PlayerChar.attributes.GetAttribute(Attribute.SkillAttackMagic, allowEffects: true);
				break;
			case SpellSphere.Defense:
				num2 = Player.PlayerChar.attributes.GetAttribute(Attribute.SkillDefenseMagic, allowEffects: true);
				break;
			case SpellSphere.Charm:
				num2 = Player.PlayerChar.attributes.GetAttribute(Attribute.SkillCharmMagic, allowEffects: true);
				break;
			}
			int num3 = -1;
			foreach (EffectData item in list2)
			{
				if ((item.value == 0 && item.value2 == 0) || item.buffType == EffectType.AttackBonus_DEPRECATED)
				{
					continue;
				}
				if (item == list2[0] || num3 != item.duration)
				{
					if (item.duration == -900)
					{
						list.Add(new Row
						{
							text = I2Loca.GetIgnoreLinebreaks("TooltipInstantEffect"),
							showBackground = false
						});
					}
					else
					{
						list.Add(new Row
						{
							text = I2Loca.GetIgnoreLinebreaksFormat("TooltipDuration", item.duration + (int)(item.durationBonus * (float)num2)),
							showBackground = false
						});
					}
				}
				num3 = item.duration;
				string text2 = ((item.chance == 0 || item.chance == 100) ? "" : (I2Loca.GetIgnoreLinebreaksFormat(spellData.payloadEffects.Contains(item) ? "TooltipChanceTo" : "TooltipChanceOf", item.chance) + " "));
				list.Add(new Row
				{
					text = text2 + item.GenerateTooltipString(EffectData.TooltipSource.Spell, num2, isSpellEffect: true),
					showBackground = true,
					color = purpleColor
				});
			}
			for (int i = 0; i < spellData.requirements.Count; i++)
			{
				AttributeData attributeData = spellData.requirements[i];
				float num4 = Mathf.Clamp01(1f - Player.PlayerChar.EffectValue(EffectType.PercentItemRequirements) / 100f);
				Color color = (Player.PlayerChar.RequirementMet(attributeData.attribute, attributeData.value, allowEffects: true, num4) ? greenColor : redColor);
				list.Add(new Row
				{
					text = attributeData.ToRequirementString(num4),
					showBackground = true,
					color = color
				});
			}
			if (spellData.IsPortalSpell() && spellData.sphereType == SpellSphere.Charm)
			{
				_ = spellData.effects[0];
				list.Add(new Row
				{
					text = I2Loca.GetMultiLineFormat(spellData.description, I2Loca.Get($"RealmName_{SingletonBehaviour<PlayerStatus>.Instance.TownRealm}")),
					showBackground = false
				});
			}
			else if (spellData.IsSummonSpell())
			{
				list.Add(new Row
				{
					text = I2Loca.GetMultiLineReplaceTagsFormat(spellData.description, Fate.MaxSummons),
					showBackground = false
				});
			}
			else
			{
				list.Add(new Row
				{
					text = I2Loca.GetMultiLineReplaceTags(spellData.description),
					showBackground = false
				});
			}
			entries.AssertComponentCount(list.Count);
			for (int j = 0; j < list.Count; j++)
			{
				Row row = list[j];
				entries[j].Set(row.text, row.showBackground, row.color);
				entries[j].gameObject.SetActive(value: true);
			}
			canvasGroup.alpha = 1f;
			UtilityTG.UIForceRebuildLayout(base.gameObject);
		}

		public void ShowTooltip(Attribute attribute, AttributeDetail attributeDetail, Character character)
		{
			List<Row> list = new List<Row>();
			if (attributeDetail == AttributeDetail.None)
			{
				titleText.text = I2Loca.Get(attribute.ToString());
				titleText.gameObject.SetActive(value: true);
				int attribute2 = character.attributes.GetAttribute(attribute, allowEffects: false);
				int attribute3 = character.attributes.GetAttribute(attribute, allowEffects: true);
				bool flag = attribute2 != attribute3;
				bool flag2 = attribute3 > attribute2;
				string text = string.Format("{0}{1}", flag2 ? "+" : "", attribute3 - attribute2);
				list.Add(new Row
				{
					text = I2Loca.Get(string.Format("{0}{1}", attribute2, flag ? text : "")),
					showBackground = flag,
					color = (flag2 ? greenColor : redColor)
				});
				list.Add(new Row
				{
					text = I2Loca.GetReplaceTags($"Desc{attribute}")
				});
				if (attribute == Attribute.SkillSword || attribute == Attribute.SkillClub || attribute == Attribute.SkillHammer || attribute == Attribute.SkillAxe || attribute == Attribute.SkillSpear || attribute == Attribute.SkillStaff || attribute == Attribute.SkillPolearm || attribute == Attribute.SkillBow)
				{
					list.Add(new Row
					{
						text = I2Loca.GetReplaceTags("SkillTooltipWeapons")
					});
				}
				if (attribute == Attribute.SkillCriticalStrike)
				{
					float num = 50f / ((float)character.SkillPoints(Attribute.SkillCriticalStrike) * 0.03f + 1f);
					num = 50f - num;
					if (num > 50f)
					{
						num = 50f;
					}
					float num2 = 50f / ((float)(character.SkillPoints(Attribute.SkillCriticalStrike) + 1) * 0.03f + 1f);
					num2 = 50f - num2;
					if (num2 > 50f)
					{
						num2 = 50f;
					}
					list.Add(new Row
					{
						text = I2Loca.GetMultiLineReplaceTagsFormat("SkillTooltipCriticalStrike", num.ToString("0.#####"), num2.ToString("0.#####"))
					});
				}
				if (attribute == Attribute.SkillShield)
				{
					float num3 = 50f / ((float)character.SkillPoints(Attribute.SkillShield) * 0.03f + 1f);
					num3 = 50f - num3;
					if (num3 > 50f)
					{
						num3 = 50f;
					}
					float num4 = 50f / ((float)(character.SkillPoints(Attribute.SkillShield) + 1) * 0.03f + 1f);
					num4 = 50f - num4;
					if (num4 > 50f)
					{
						num4 = 50f;
					}
					list.Add(new Row
					{
						text = I2Loca.GetFormatReplaceTags("SkillTooltipShield", num3.ToString("0.#####"), num4.ToString("0.#####"))
					});
				}
				if (attribute == Attribute.SkillSpellcasting)
				{
					float num5 = 50f / ((float)character.SkillPoints(Attribute.SkillSpellcasting) * 0.03f + 1f);
					num5 = 50f - num5;
					if (num5 > 50f)
					{
						num5 = 50f;
					}
					num5 /= 50f;
					num5 *= 80f;
					float num6 = 50f / ((float)(character.SkillPoints(Attribute.SkillSpellcasting) + 1) * 0.03f + 1f);
					num6 = 50f - num6;
					if (num6 > 50f)
					{
						num6 = 50f;
					}
					num6 /= 50f;
					num6 *= 80f;
					list.Add(new Row
					{
						text = I2Loca.GetFormatReplaceTags("SkillTooltipSpellcasting", num5.ToString("0.#####"), num6.ToString("0.#####"))
					});
				}
				if (attribute == Attribute.SkillDualWield)
				{
					float dualWieldDamageMultiplier = character.GetDualWieldDamageMultiplier(isMainHand: true, withEffects: true);
					dualWieldDamageMultiplier *= 100f;
					float dualWieldDamageMultiplier2 = character.GetDualWieldDamageMultiplier(isMainHand: true, withEffects: true, character.SkillPoints(Attribute.SkillDualWield) + 1);
					dualWieldDamageMultiplier2 *= 100f;
					float dualWieldDamageMultiplier3 = character.GetDualWieldDamageMultiplier(isMainHand: false, withEffects: true);
					dualWieldDamageMultiplier3 *= 100f;
					float dualWieldDamageMultiplier4 = character.GetDualWieldDamageMultiplier(isMainHand: false, withEffects: true, character.SkillPoints(Attribute.SkillDualWield) + 1);
					dualWieldDamageMultiplier4 *= 100f;
					list.Add(new Row
					{
						text = I2Loca.GetMultiLineReplaceTagsFormat("SkillTooltipDualWield", dualWieldDamageMultiplier.ToString("0.#####"), dualWieldDamageMultiplier2.ToString("0.#####"), dualWieldDamageMultiplier3.ToString("0.#####"), dualWieldDamageMultiplier4.ToString("0.#####"))
					});
				}
			}
			else
			{
				titleText.gameObject.SetActive(value: false);
				switch (attributeDetail)
				{
				case AttributeDetail.DamageRange:
				{
					Range damageRangeForStats = character.GetDamageRangeForStats(withEffects: false);
					int num9 = (int)(character.GetDamageRangeForStats(withEffects: true).GetAverage() - damageRangeForStats.GetAverage());
					bool flag5 = num9 != 0;
					bool flag6 = num9 > 0;
					string baseString2 = string.Format("{0}{1}", flag6 ? "+" : "", num9);
					list.Add(new Row
					{
						text = I2Loca.Get(string.Format("{0}-{1} {2}", (int)damageRangeForStats.Min, (int)damageRangeForStats.Max, flag5 ? I2Loca.ReplaceTags(baseString2) : "")),
						showBackground = flag5,
						color = (flag6 ? greenColor : redColor)
					});
					break;
				}
				case AttributeDetail.DamageRange2:
				{
					Range damageRangeForStatsOffhand = character.GetDamageRangeForStatsOffhand(withEffects: false);
					int num10 = (int)(character.GetDamageRangeForStatsOffhand(withEffects: true).GetAverage() - damageRangeForStatsOffhand.GetAverage());
					bool flag7 = num10 != 0;
					bool flag8 = num10 > 0;
					string baseString3 = string.Format("{0}{1}", flag8 ? "+" : "", num10);
					list.Add(new Row
					{
						text = I2Loca.Get(string.Format("{0}-{1} {2}", (int)damageRangeForStatsOffhand.Min, (int)damageRangeForStatsOffhand.Max, flag7 ? I2Loca.ReplaceTags(baseString3) : "")),
						showBackground = flag7,
						color = (flag8 ? greenColor : redColor)
					});
					break;
				}
				case AttributeDetail.AttackRating:
				{
					int num15 = character.ToHit(useBestWeapon: true, withEffects: false);
					int num16 = character.ToHit(useBestWeapon: true) - num15;
					bool flag13 = num16 != 0;
					bool flag14 = num16 > 0;
					string baseString6 = string.Format("{0}{1}", flag14 ? "+" : "", num16);
					list.Add(new Row
					{
						text = I2Loca.Get(string.Format("{0}{1}", num15, flag13 ? I2Loca.ReplaceTags(baseString6) : "")),
						showBackground = flag13,
						color = (flag14 ? greenColor : redColor)
					});
					break;
				}
				case AttributeDetail.Dodge:
				{
					int num13 = character.AC(withEffects: false);
					int num14 = character.AC() - num13;
					bool flag11 = num14 != 0;
					bool flag12 = num14 > 0;
					string baseString5 = string.Format("{0}{1}", flag12 ? "+" : "", num14);
					list.Add(new Row
					{
						text = I2Loca.Get(string.Format("{0}{1}", num13, flag11 ? I2Loca.ReplaceTags(baseString5) : "")),
						showBackground = flag11,
						color = (flag12 ? greenColor : redColor)
					});
					break;
				}
				case AttributeDetail.Stamina:
				{
					int num11 = character.MaxStamina(withEffects: false);
					int num12 = character.MaxStamina() - num11;
					bool flag9 = num12 != 0;
					bool flag10 = num12 > 0;
					string baseString4 = string.Format("{0}{1}", flag10 ? "+" : "", num12);
					list.Add(new Row
					{
						text = I2Loca.Get(string.Format("{0}{1}", num11, flag9 ? I2Loca.ReplaceTags(baseString4) : "")),
						showBackground = flag9,
						color = (flag10 ? greenColor : redColor)
					});
					break;
				}
				case AttributeDetail.HP:
				{
					int num17 = character.MaxHP(withEffects: false);
					int num18 = character.MaxHP() - num17;
					bool flag15 = num18 != 0;
					bool flag16 = num18 > 0;
					string baseString7 = string.Format("{0}{1}", flag16 ? "+" : "", num18);
					list.Add(new Row
					{
						text = I2Loca.Get(string.Format("{0}{1}", num17, flag15 ? I2Loca.ReplaceTags(baseString7) : "")),
						showBackground = flag15,
						color = (flag16 ? greenColor : redColor)
					});
					break;
				}
				case AttributeDetail.Mana:
				{
					int num7 = character.MaxMana(withEffects: false);
					int num8 = character.MaxMana() - num7;
					bool flag3 = num8 != 0;
					bool flag4 = num8 > 0;
					string baseString = string.Format("{0}{1}", flag4 ? "+" : "", num8);
					list.Add(new Row
					{
						text = I2Loca.Get(string.Format("{0}{1}", num7, flag3 ? I2Loca.ReplaceTags(baseString) : "")),
						showBackground = flag3,
						color = (flag4 ? greenColor : redColor)
					});
					break;
				}
				default:
					throw new Exception($"Unhandled enum type {attributeDetail}");
				}
				string key = ((attributeDetail == AttributeDetail.DamageRange2) ? "DescDamageRange" : $"Desc{attributeDetail}");
				list.Add(new Row
				{
					text = I2Loca.GetReplaceTags(key)
				});
			}
			entries.AssertComponentCount(list.Count);
			for (int i = 0; i < list.Count; i++)
			{
				Row row = list[i];
				entries[i].Set(row.text, row.showBackground, row.color);
				entries[i].gameObject.SetActive(value: true);
			}
			canvasGroup.alpha = 1f;
			UtilityTG.UIForceRebuildLayout(base.gameObject);
		}

		private void AddTransformStatRow(ref List<Row> rows, string statString, int currentStat, int transformStat)
		{
			int num = transformStat - currentStat;
			bool flag = num >= 0;
			rows.Add(new Row
			{
				text = I2Loca.GetIgnoreLinebreaksReplaceTagsFormat("Tooltip_" + statString + (flag ? "Improved" : "Reduced"), num),
				showBackground = true,
				color = (flag ? greenColor : redColor)
			});
		}

		public void ShowTooltip(string title, string description)
		{
			bool flag = !string.IsNullOrEmpty(title);
			bool flag2 = !string.IsNullOrEmpty(description);
			if (!flag && !flag2)
			{
				HideTooltip();
				return;
			}
			if (flag)
			{
				titleText.text = title;
			}
			titleText.gameObject.SetActive(flag);
			if (flag2)
			{
				entries.AssertComponentCount(1);
				entries[0].Set(description, showBackground: false);
				entries[0].gameObject.SetActive(value: true);
			}
			else
			{
				foreach (TooltipUIEntry entry in entries)
				{
					entry.gameObject.SetActive(value: false);
				}
			}
			canvasGroup.alpha = 1f;
			UtilityTG.UIForceRebuildLayout(base.gameObject);
		}
	}
