	public class TutorialPopupUI : SingletonBehaviour<TutorialPopupUI>
	{
		[SerializeField]
		private Button confirmButton;

		[SerializeField]
		private Toggle displayTipsToggle;

		[SerializeField]
		private GameObject headerParent;

		[SerializeField]
		private TextMeshProUGUI headerText;

		[SerializeField]
		private TextMeshProUGUI bodyText;

		[SerializeField]
		private UiBlockingPanel uiBlockPanel;

		private Queue<string> queuedTips;

		private bool preWasPaused;

		private GameObject prePromptSelected;

		private bool prePromptCursorActive;

		private InputBroker.InputMode prePromptInputMode;

		protected override bool DontDestroy => true;

		public static bool IsShown { get; private set; }

		protected override void Init()
		{
			base.Init();
			queuedTips = new Queue<string>();
			confirmButton.onClick.AddListener(OnConfirmButtonClicked);
			displayTipsToggle.onValueChanged.AddListener(OnDisplayTipsToggled);
		}

		private void Start()
		{
			base.gameObject.SetActive(value: false);
			IsShown = false;
		}

		public void ForceClosePrompt()
		{
			base.gameObject.SetActive(value: false);
			IsShown = false;
		}

		public void ShowTip(string localizationKey)
		{
			UtilityTG.UnityDelay(delegate
			{
				ShowTipInternal(localizationKey, isFromQueue: false);
			});
		}

		private void ShowTipInternal(string localizationKey, bool isFromQueue)
		{
			if (!SaveData.SettingsSave.displayTips)
			{
				UnityEngine.Debug.LogWarning("Tried to show tip with loca key " + localizationKey + ", but not allowed because display tips setting is false. This should not happen.");
				return;
			}
			if (!isFromQueue && IsShown)
			{
				queuedTips.Enqueue(localizationKey);
				return;
			}
			string[] array = I2Loca.GetMultiLineReplaceTags(localizationKey).Split(':');
			string text;
			if (array.Length > 1)
			{
				headerText.text = array[0];
				text = array[1];
				if (array.Length > 2)
				{
					for (int i = 2; i < array.Length; i++)
					{
						text = text + ":" + array[i];
					}
				}
			}
			else
			{
				text = array[0];
			}
			headerParent.SetActive(value: false);
			bodyText.text = text;
			displayTipsToggle.isOn = true;
			if (!isFromQueue)
			{
				prePromptInputMode = SingletonBehaviour<InputBroker>.Instance.ActiveInputMode;
				SingletonBehaviour<InputBroker>.Instance.SetInputMode(InputBroker.InputMode.Menu);
				SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Submit.Disable();
				UtilityTG.UnityDelay(SingletonBehaviour<InputBroker>.Instance.Inputs.Menu.Submit.Enable);
				base.gameObject.SetActive(value: true);
				prePromptSelected = EventSystem.current.currentSelectedGameObject;
				if (SingletonBehaviour<PlayerUI>.InstanceExists())
				{
					prePromptCursorActive = SingletonBehaviour<CursorManager>.Instance.VirtualCursorActive;
					if (prePromptCursorActive)
					{
						SingletonBehaviour<CursorManager>.Instance.SetVirtualCursorActive(state: false);
					}
				}
				preWasPaused = Fate.isPaused;
			}
			UtilityTG.UIForceRebuildLayout(base.gameObject);
			UtilityTG.SetSelected(confirmButton.gameObject);
			Fate.SetPause(paused: true);
			IsShown = true;
		}

		private void OnConfirmButtonClicked()
		{
			if (queuedTips.Count > 0)
			{
				ShowTipInternal(queuedTips.Dequeue(), isFromQueue: true);
				return;
			}
			base.gameObject.SetActive(value: false);
			if (prePromptSelected != null && prePromptSelected.activeInHierarchy)
			{
				UtilityTG.SetSelected(prePromptSelected);
				prePromptSelected = null;
			}
			if (prePromptCursorActive && SingletonBehaviour<PlayerUI>.InstanceExists())
			{
				SingletonBehaviour<CursorManager>.Instance.SetVirtualCursorActive(state: true);
			}
			InputBlocker.MuteForFrames(6);
			IsShown = false;
			SingletonBehaviour<InputBroker>.Instance.SetInputMode(prePromptInputMode);
			SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.ButtonBasic, randomizePitch: false);
			Fate.SetPause(preWasPaused);
		}

		private void OnDisplayTipsToggled(bool isOn)
		{
			SaveData.SettingsSave.displayTips = isOn;
		}
	}
	public class InputFieldRelay : MonoBehaviour
	{
		public Action onInputFieldRequested;

		public Action<string> onInputFieldDone;

		private Callback<FloatingGamepadTextInputDismissed_t> floatingGamepadTextInputDismissedCallback;

		[SerializeField]
		private GameObject inputHintGO;

		private Button relayButton;

		private TMP_InputField inputField;

		private bool expectingEndEdit;

		public TMP_InputField InputField
		{
			get
			{
				if (inputField == null)
				{
					inputField = GetComponentInChildren<TMP_InputField>(includeInactive: true);
				}
				return inputField;
			}
		}

		private void Awake()
		{
			relayButton = GetComponent<Button>();
		}

		private void EvaluateInputHintGO()
		{
			if (!(inputHintGO == null))
			{
				inputHintGO.SetActive(value: true);
			}
		}

		private void OnInputFieldSelected(string activeText)
		{
			if (inputHintGO != null)
			{
				inputHintGO.SetActive(value: false);
			}
		}

		private void OnEnable()
		{
			relayButton.onClick.AddListener(OnRelayButtonClicked);
			inputField.onEndEdit.AddListener(OnInputFieldEndEdit);
			inputField.onSelect.AddListener(OnInputFieldSelected);
			if (SteamManager.Instance != null && SteamManager.Instance.IsSteamRunningOnSteamDeck())
			{
				floatingGamepadTextInputDismissedCallback = Callback<FloatingGamepadTextInputDismissed_t>.Create(OnFloatingGamepadTextInputDismissed);
			}
			EvaluateInputHintGO();
		}

		private void OnDisable()
		{
			relayButton.onClick.RemoveListener(OnRelayButtonClicked);
			inputField.onEndEdit.RemoveListener(OnInputFieldEndEdit);
			inputField.onSelect.RemoveListener(OnInputFieldSelected);
		}

		private void OnRelayButtonClicked()
		{
			onInputFieldRequested?.Invoke();
			expectingEndEdit = true;
			UtilityTG.SetSelected(inputField.gameObject);
			EvaluateInputHintGO();
			if (SteamManager.Instance != null && SteamManager.Instance.IsSteamRunningOnSteamDeck())
			{
				SteamManager.Instance.ShowFloatingGamepadTextInput();
			}
			else if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free)
			{
				StartCoroutine(UtilityTG.DelayedInvoke(0.01f, delegate
				{
					UtilityTG.SetSelected(relayButton.gameObject);
				}));
			}
		}

		private void OnInputFieldEndEdit(string text)
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists() && (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior != 0 || expectingEndEdit))
			{
				expectingEndEdit = false;
				onInputFieldDone?.Invoke(text);
				StartCoroutine(UtilityTG.DelayedInvoke(0.01f, delegate
				{
					UtilityTG.SetSelected(relayButton.gameObject);
				}));
				EvaluateInputHintGO();
			}
		}

		private void OnFloatingGamepadTextInputDismissed(FloatingGamepadTextInputDismissed_t callback)
		{
			if (expectingEndEdit)
			{
				expectingEndEdit = false;
				StartCoroutine(UtilityTG.DelayedInvoke(0.01f, delegate
				{
					UtilityTG.SetSelected(relayButton.gameObject);
				}));
				EvaluateInputHintGO();
			}
		}
	}
