	public class AnimationClipOverrides : List<KeyValuePair<AnimationClip, AnimationClip>>
	{
		public AnimationClip this[string name]
		{
			get
			{
				return Find((KeyValuePair<AnimationClip, AnimationClip> x) => x.Key.name.Equals(name)).Value;
			}
			set
			{
				int num = FindIndex((KeyValuePair<AnimationClip, AnimationClip> x) => x.Key.name.Equals(name));
				if (num != -1)
				{
					base[num] = new KeyValuePair<AnimationClip, AnimationClip>(base[num].Key, value);
					return;
				}
				for (int i = 0; i < base.Count; i++)
				{
					if (!(base[i].Value == null) && base[i].Value.name.Equals(name))
					{
						base[i] = new KeyValuePair<AnimationClip, AnimationClip>(base[i].Key, value);
						break;
					}
				}
			}
		}

		public AnimationClipOverrides(int capacity)
			: base(capacity)
		{
		}
	}
	[RequireComponent(typeof(ScrollRect))]
	public class AutoScrollRect : MonoBehaviour
	{
		[SerializeField]
		[Tooltip("Sets the speed to move the scrollbar")]
		private float scrollSpeed = 10f;

		[SerializeField]
		public bool isUnityDropDown;

		private ScrollRect scrollRect;

		private RectTransform viewportTransform;

		private RectTransform contentTransform;

		private RectTransform selectedTransform;

		private void Awake()
		{
			InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
			instance.OnInputBehaviorChanged = (Action<InputBroker.InputBehavior>)Delegate.Combine(instance.OnInputBehaviorChanged, new Action<InputBroker.InputBehavior>(OnInputBehaviorChange));
			OnInputBehaviorChange(SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior);
			scrollRect = GetComponent<ScrollRect>();
			viewportTransform = scrollRect.viewport;
			contentTransform = scrollRect.content;
		}

		private void OnDestroy()
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
				instance.OnInputBehaviorChanged = (Action<InputBroker.InputBehavior>)Delegate.Remove(instance.OnInputBehaviorChanged, new Action<InputBroker.InputBehavior>(OnInputBehaviorChange));
			}
		}

		private void OnInputBehaviorChange(InputBroker.InputBehavior inputBehavior)
		{
			base.enabled = inputBehavior == InputBroker.InputBehavior.Free;
		}

		private void Update()
		{
			UpdateScrollToSelected();
		}

		private void UpdateScrollToSelected()
		{
			GameObject currentSelectedGameObject = EventSystem.current.currentSelectedGameObject;
			if (!(currentSelectedGameObject == null) && !(currentSelectedGameObject.transform.parent != contentTransform.transform))
			{
				selectedTransform = currentSelectedGameObject.GetComponent<RectTransform>();
				_ = viewportTransform.lossyScale;
				Vector3 vector = viewportTransform.localPosition - selectedTransform.localPosition;
				float num = contentTransform.rect.height - viewportTransform.rect.height;
				bool flag = scrollRect.GetComponent<RectTransform>().pivot.y < 0.99f;
				float num2 = contentTransform.rect.height - vector.y;
				float num3 = scrollRect.normalizedPosition.y * num;
				float num4 = num3 - selectedTransform.rect.height / 2f;
				if (!flag)
				{
					num4 += viewportTransform.rect.height;
				}
				float num5 = num3 + selectedTransform.rect.height / 2f;
				if (flag)
				{
					num5 -= viewportTransform.rect.height;
				}
				bool flag2 = num2 > num4;
				bool flag3 = num2 < num5;
				_ = scrollRect.normalizedPosition;
				if (flag2)
				{
					float num6 = num2 - num4;
					float y = (num3 + num6) / num;
					scrollRect.normalizedPosition = Vector2.Lerp(scrollRect.normalizedPosition, new Vector2(0f, y), scrollSpeed * Time.unscaledDeltaTime);
				}
				else if (flag3)
				{
					float num7 = num2 - num5;
					float y2 = (num3 + num7) / num;
					scrollRect.normalizedPosition = Vector2.Lerp(scrollRect.normalizedPosition, new Vector2(0f, y2), scrollSpeed * Time.unscaledDeltaTime);
				}
			}
		}
	}
	public class CharacterTest : MonoBehaviour
	{
		public FateDB itemDB;

		public CharacterCustomizationDefaults playerChar;

		private Dictionary<ItemType, List<string>> itemsByType;

		private Dictionary<Race, (int, int)> currentHairHead;

		private Dictionary<Race, (int, int)> hairHeadCountMale;

		private Dictionary<Race, (int, int)> hairHeadCountFemale;

		private Race currentRace;

		private bool isMale;

		private void Awake()
		{
			itemsByType = new Dictionary<ItemType, List<string>>();
			currentHairHead = new Dictionary<Race, (int, int)>();
			hairHeadCountMale = new Dictionary<Race, (int, int)>();
			hairHeadCountFemale = new Dictionary<Race, (int, int)>();
			currentRace = Race.Human;
			isMale = true;
			Fate.CurrentFateVer = Fate.FateVer.CursedKing;
			foreach (ItemData allItem in itemDB.AllItems)
			{
				if (!(allItem == null))
				{
					if (!itemsByType.ContainsKey(allItem.itemType))
					{
						itemsByType.Add(allItem.itemType, new List<string>());
					}
					itemsByType[allItem.itemType].Add(allItem.displayName);
				}
			}
			playerChar.SetRace(currentRace);
			for (int i = 0; i < 5; i++)
			{
				Race race = (Race)(1 + i);
				CharacterCustomizationDefaults.RaceSetup raceSetup = playerChar.raceSetups.Find((CharacterCustomizationDefaults.RaceSetup r) => r.targetRace == race);
				hairHeadCountMale.Add(race, (raceSetup.hair.MaleOverrideCount, raceSetup.head.MaleOverrideCount));
				hairHeadCountFemale.Add(race, (raceSetup.hair.FemaleOverrideCount, raceSetup.head.FemaleOverrideCount));
			}
		}

		private string GetRandomItemId(ItemType itemType)
		{
			return itemsByType[itemType]?.GetRandomEntry();
		}

		private void Update()
		{
			if (Input.GetKeyDown(KeyCode.A))
			{
				playerChar.SetBack(GetRandomItemId(ItemType.Back));
				playerChar.SetBoots(GetRandomItemId(ItemType.Boots));
				playerChar.SetGloves(GetRandomItemId(ItemType.Gloves));
				playerChar.SetUpper(GetRandomItemId(ItemType.Shirt));
				playerChar.SetHelmet(GetRandomItemId(ItemType.Helmet));
			}
			if (Input.GetKeyDown(KeyCode.R))
			{
				currentRace = ((currentRace == Race.Imp) ? Race.Human : (currentRace + 1));
				if (!currentHairHead.ContainsKey(currentRace))
				{
					currentHairHead.Add(currentRace, (0, 0));
				}
				currentHairHead[currentRace] = (0, 0);
				playerChar.SetRace(currentRace);
			}
			if (Input.GetKeyDown(KeyCode.G))
			{
				isMale = !isMale;
				currentHairHead[currentRace] = (0, 0);
				playerChar.SetGender(isMale);
			}
			if (Input.GetKeyDown(KeyCode.Alpha1))
			{
				if (!currentHairHead.ContainsKey(currentRace))
				{
					currentHairHead.Add(currentRace, (0, 0));
				}
				(int, int) value = currentHairHead[currentRace];
				int item = value.Item1;
				int num = (isMale ? hairHeadCountMale[currentRace].Item1 : hairHeadCountFemale[currentRace].Item1);
				int num2 = ((item + 1 < num) ? (item + 1) : 0);
				playerChar.SetHead(num2);
				value.Item1 = num2;
				currentHairHead[currentRace] = value;
			}
			if (Input.GetKeyDown(KeyCode.Alpha2))
			{
				if (!currentHairHead.ContainsKey(currentRace))
				{
					currentHairHead.Add(currentRace, (0, 0));
				}
				(int, int) value2 = currentHairHead[currentRace];
				int item2 = value2.Item2;
				int num3 = (isMale ? hairHeadCountMale[currentRace].Item2 : hairHeadCountFemale[currentRace].Item2);
				int num4 = ((item2 + 1 < num3) ? (item2 + 1) : 0);
				playerChar.SetHair(num4);
				value2.Item2 = num4;
				currentHairHead[currentRace] = value2;
			}
		}
	}
	public class Cheats : MonoBehaviour
	{
		public Toggle toggle;

