		}

		public void OnCompleteQuestsButton()
		{
			List<Quest> questsActiveTownRealm = SingletonBehaviour<QuestManager>.Instance.GetQuestsActiveTownRealm();
			if (questsActiveTownRealm != null)
			{
				for (int i = 0; i < questsActiveTownRealm.Count; i++)
				{
					if (questsActiveTownRealm[i] != null && questsActiveTownRealm[i].Status != Quest.QuestStatus.Claimed)
					{
						questsActiveTownRealm[i].Status = Quest.QuestStatus.Completed;
					}
				}
			}
			if (LevelGenerator.currentInstance != null && Fate.CurrentFateVer == Fate.FateVer.CursedKing)
			{
				questsActiveTownRealm = SingletonBehaviour<QuestManager>.Instance.GetQuests((int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm);
				if (questsActiveTownRealm != null)
				{
					for (int j = 0; j < questsActiveTownRealm.Count; j++)
					{
						if (questsActiveTownRealm[j] != null && questsActiveTownRealm[j].Status != Quest.QuestStatus.Claimed)
						{
							questsActiveTownRealm[j].Status = Quest.QuestStatus.Completed;
						}
					}
				}
			}
			if (SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm == RealmData.RealmId.ChamberOfTrials)
			{
				Quest realmQuest = SingletonBehaviour<QuestManager>.Instance.GetRealmQuest(RealmData.RealmId.ChamberOfTrials);
				if (realmQuest != null && realmQuest.Status != Quest.QuestStatus.Claimed)
				{
					realmQuest.Status = Quest.QuestStatus.Completed;
				}
			}
			Quest realmQuestActiveTownRealm = SingletonBehaviour<QuestManager>.Instance.GetRealmQuestActiveTownRealm();
			if (realmQuestActiveTownRealm != null && realmQuestActiveTownRealm.Status != Quest.QuestStatus.Claimed)
			{
				realmQuestActiveTownRealm.Status = Quest.QuestStatus.Completed;
			}
		}

		public void OnDownALevelButton()
		{
			if (!(LevelGenerator.currentInstance == null) && !locked)
			{
				GenerateNextLevel(goesDown: true);
			}
		}

		public void OnUpALevelButton()
		{
			if (LevelGenerator.currentInstance == null || locked)
			{
				return;
			}
			int levelDepth = LevelGenerator.currentInstance.GetLevelDepth();
			if (levelDepth == 1)
			{
				locked = true;
				Fate.SetPause(paused: false);
				StartCoroutine(UtilityTG.DelayedInvoke(1.5f, delegate
				{
					Fate.SetPause(paused: true);
					locked = false;
				}));
				levelDepth--;
				LevelGenerator.currentInstance.SetLevelDepth(levelDepth);
				LevelGenerator.currentInstance.UpdateSaveData(goesDown: false);
				Town.UpdateSpawnIndex(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, Town.EntryMethod.Stairs);
				SceneLoad.LoadAsync(SceneLoad.GetTownScene(SingletonBehaviour<PlayerStatus>.Instance.TownRealm), save: true);
			}
			else
			{
				GenerateNextLevel(goesDown: false);
			}
		}

		private void GenerateNextLevel(bool goesDown)
		{
			int num = LevelGenerator.currentInstance.GetLevelDepth() + (goesDown ? 1 : (-1));
			if (!string.IsNullOrEmpty(inputField.text) && int.TryParse(inputField.text, out var result))
			{
				num = result;
			}
			if (LevelGenerator.currentInstance.HasActiveDungeon())
			{
				LevelGenerator.currentInstance.ReplaceDungeon(0f, 0f, num, (int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, goesDown, useSavedPosition: false);
			}
			else
			{
				LevelGenerator.currentInstance.Create(0f, 0f, num, (int)SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm, goesDown, useSavedPosition: false);
			}
			if (goesDown && num == 35)
			{
				StatsManager.OnDungeonLevel35Reached(SingletonBehaviour<PlayerStatus>.Instance.DungeonRealm.ToString());
			}
			locked = true;
			Fate.SetPause(paused: false);
			StartCoroutine(UtilityTG.DelayedInvoke(1.5f, delegate
			{
				Fate.SetPause(paused: true);
				locked = false;
			}));
		}

		public void OnExpButton()
		{
			int num = 1;
			if (string.IsNullOrEmpty(inputFieldValue))
			{
				inputFieldValue = inputField.text;
			}
			if (!string.IsNullOrEmpty(inputFieldValue))
			{
				num = int.Parse(inputFieldValue);
			}
			int award;
			try
			{
				award = checked((int)(Fate.GetExperienceNeeded(Player.PlayerChar.Level + num - 1) - Player.PlayerChar.experience) + 1);
			}
			catch
			{
				award = int.MaxValue;
				UnityEngine.Debug.Log("int max reached");
			}
			Player.PlayerChar.AwardExperience(award, fromMaster: false);
		}

		public void OnFameButton()
		{
			Player.PlayerChar.AwardFame(Fate.GetFameNeeded(Player.PlayerChar.fameRank + 1) - Player.PlayerChar.fame);
		}

		public void OnRecruitRandomPartyMember()
		{
			FateSaveData fateSaveData = PartyMember.GenerateRandomSaveData();
			Player.PlayerChar.TryRecruitPartyMember(fateSaveData.playerSaveData, fateSaveData.itemSaveData, 0u, 0u);
		}

		public void OnRecruitRandomSavePartyMember()
		{
			List<uint> list = new List<uint>();
			int partyMemberCount = Player.PlayerChar.GetPartyMemberCount();
			for (int i = 0; i < partyMemberCount; i++)
			{
				PartyMember partyMember = Player.PlayerChar.GetPartyMember(i) as PartyMember;
				if ((bool)partyMember && partyMember.saveUniqueId != 0)
				{
					list.Add(partyMember.saveUniqueId);
				}
			}
			List<SaveData.SaveSlot> list2 = new List<SaveData.SaveSlot>();
			for (int j = 0; j < SaveData.SaveSlots.Count; j++)
			{
				SaveData.SaveSlot saveSlot = SaveData.SaveSlots[j];
				if (saveSlot.IsUniqueIDValid && saveSlot.uniqueId != SaveData.CurrentSaveSlot.uniqueId && !list.Contains(saveSlot.uniqueId))
				{
					list2.Add(SaveData.SaveSlots[j]);
				}
			}
			if (list2.Count == 0)
			{
				UnityEngine.Debug.LogError("Can't add party member from saves, no valid save found");
				return;
			}
			SaveData.SaveSlot randomEntry = list2.GetRandomEntry();
			FateSaveData saveData = randomEntry.saveData;
			Player.PlayerChar.TryRecruitPartyMember(saveData.playerSaveData, saveData.itemSaveData, randomEntry.uniqueId, 0u);
		}

		public void DismissRandomPartyMember()
		{
			int partyMemberCount = Player.PlayerChar.GetPartyMemberCount();
			if (partyMemberCount > 0)
			{
				Player.PlayerChar.DismissPartyMember(Player.PlayerChar.GetPartyMember(UnityEngine.Random.Range(0, partyMemberCount)));
			}
		}

		public void SpawnItem()
		{
			if (string.IsNullOrEmpty(inputFieldValue))
			{
				inputFieldValue = inputField.text;
				if (string.IsNullOrEmpty(inputFieldValue))
				{
					return;
				}
			}
			string val = inputFieldValue.ToLower();
			ItemData itemData = SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData itm) => itm.displayName.ToLower() == val);
			if (itemData == null)
			{
				itemData = SingletonBehaviour<FateDB>.Instance.AllItems.Find((ItemData itm) => I2Loca.Get(itm.displayName).ToLower() == val);
				if (itemData == null)
				{
					UnityEngine.Debug.LogError("Item not found: " + inputFieldValue);
					return;
				}
			}
			new Item(itemData).Drop(Player.PlayerChar.myTransform.position);
		}

		public void SpawnMonster()
		{
			if (LevelGenerator.currentInstance == null)
			{
				UnityEngine.Debug.LogError("Can only spawn monsters in dungeon");
				return;
			}
			if (string.IsNullOrEmpty(inputFieldValue))
			{
				inputFieldValue = inputField.text;
				if (string.IsNullOrEmpty(inputFieldValue))
				{
					return;
				}
			}
			string val = inputFieldValue.ToLower();
			MonsterData monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData m) => m.displayName.ToLower() == val);
			if (monsterData == null)
			{
				monsterData = SingletonBehaviour<FateDB>.Instance.allMonsters.Find((MonsterData m) => I2Loca.Get(m.displayName).ToLower() == val);
				if (monsterData == null)
				{
					UnityEngine.Debug.LogError("Monster not found: " + inputFieldValue);
					return;
				}
			}
			LevelGenerator.currentInstance.SpawnMonster(monsterData, Player.PlayerChar.myTransform.position + new Vector3(UnityEngine.Random.Range(-2, 2), 0f, UnityEngine.Random.Range(-2, 2)), null, -1, allowRankUp: true);
		}
	}
