	[CreateAssetMenu(fileName = "GamepadIcons", menuName = "Tableflip/Gamepad Icons")]
	public class GamepadIcons : ScriptableObject
	{
		public enum ButtonType
		{
			None,
			ButtonSouth,
			ButtonNorth,
			ButtonEast,
			ButtonWest,
			StartButton,
			SelectButton,
			LeftTrigger,
			RightTrigger,
			LeftShoulder,
			RightShoulder,
			Dpad,
			DpadUp,
			DpadDown,
			DpadLeft,
			DpadRight,
			LeftStick,
			RightStick,
			LeftStickPress,
			RightStickPress,
			SubmitButton,
			CancelButton
		}

		public Sprite buttonSouth;

		public Sprite buttonNorth;

		public Sprite buttonEast;

		public Sprite buttonWest;

		public Sprite startButton;

		public Sprite selectButton;

		public Sprite leftTrigger;

		public Sprite rightTrigger;

		public Sprite leftShoulder;

		public Sprite rightShoulder;

		public Sprite dpad;

		public Sprite dpadUp;

		public Sprite dpadDown;

		public Sprite dpadLeft;

		public Sprite dpadRight;

		public Sprite leftStick;

		public Sprite rightStick;

		public Sprite leftStickPress;

		public Sprite rightStickPress;

		public Sprite GetSprite(string buttonString)
		{
			return GetSprite(StringToButtonType(buttonString));
		}

		public Sprite GetSprite(ButtonType buttonType)
		{
			switch (buttonType)
			{
			case ButtonType.ButtonSouth:
				return buttonSouth;
			case ButtonType.ButtonNorth:
				return buttonNorth;
			case ButtonType.ButtonEast:
				return buttonEast;
			case ButtonType.ButtonWest:
				return buttonWest;
			case ButtonType.StartButton:
				return startButton;
			case ButtonType.SelectButton:
				return selectButton;
			case ButtonType.LeftTrigger:
				return leftTrigger;
			case ButtonType.RightTrigger:
				return rightTrigger;
			case ButtonType.LeftShoulder:
				return leftShoulder;
			case ButtonType.RightShoulder:
				return rightShoulder;
			case ButtonType.Dpad:
				return dpad;
			case ButtonType.DpadUp:
				return dpadUp;
			case ButtonType.DpadDown:
				return dpadDown;
			case ButtonType.DpadLeft:
				return dpadLeft;
			case ButtonType.DpadRight:
				return dpadRight;
			case ButtonType.LeftStick:
				return leftStick;
			case ButtonType.RightStick:
				return rightStick;
			case ButtonType.LeftStickPress:
				return leftStickPress;
			case ButtonType.RightStickPress:
				return rightStickPress;
			case ButtonType.SubmitButton:
				if (PlatformFlag.GetCurrentPlatformAsFlag() != PlatformFlag.Flag.NintendoSwitch)
				{
					return buttonSouth;
				}
				return buttonEast;
			case ButtonType.CancelButton:
				if (PlatformFlag.GetCurrentPlatformAsFlag() != PlatformFlag.Flag.NintendoSwitch)
				{
					return buttonEast;
				}
				return buttonSouth;
			default:
				UnityEngine.Debug.LogWarning($"Sprite for button type not found {buttonType}");
				return null;
			}
		}

		private ButtonType StringToButtonType(string stringValue)
		{
			switch (stringValue)
			{
			case "buttonSouth":
				return ButtonType.ButtonSouth;
			case "buttonNorth":
				return ButtonType.ButtonNorth;
			case "buttonEast":
				return ButtonType.ButtonEast;
			case "buttonWest":
				return ButtonType.ButtonWest;
			case "start":
				return ButtonType.StartButton;
			case "select":
				return ButtonType.SelectButton;
			case "leftTrigger":
				return ButtonType.LeftTrigger;
			case "rightTrigger":
				return ButtonType.RightTrigger;
			case "leftShoulder":
				return ButtonType.LeftShoulder;
			case "rightShoulder":
				return ButtonType.RightShoulder;
			case "dpad":
				return ButtonType.Dpad;
			case "dpad/up":
				return ButtonType.DpadUp;
			case "dpad/down":
				return ButtonType.DpadDown;
			case "dpad/left":
				return ButtonType.DpadLeft;
			case "dpad/right":
				return ButtonType.DpadRight;
			case "leftStick":
				return ButtonType.LeftStick;
			case "rightStick":
				return ButtonType.RightStick;
			case "leftStickPress":
				return ButtonType.LeftStickPress;
			case "rightStickPress":
				return ButtonType.RightStickPress;
			default:
				UnityEngine.Debug.LogWarning("Could not convert string to button type " + stringValue);
				return ButtonType.None;
			}
		}
	}
	public static class I2Loca
	{
		public const string TagReplaceB = "<style=C1>";

		public const string TagReplaceBClose = "</style>";

		public static Action<string> OnLanguageChanged;

		public static void SetLanguage(string language)
		{
			LocalizationManager.SetLanguageAndCode(language, LocalizationManager.GetLanguageCode(language), RememberLanguage: true, Force: true);
			UnityEngine.Debug.Log("Language set: " + language);
			OnLanguageChanged?.Invoke(LocalizationManager.CurrentLanguageCode);
		}

		public static void SetLanguageFromCode(string langCode)
		{
			SetLanguage(LocalizationManager.GetLanguageFromCode(langCode));
		}

		public static string GetCurrentLanguage()
		{
			return LocalizationManager.CurrentLanguage;
		}

		public static string GetCurrentLanguageCode()
		{
			return LocalizationManager.CurrentLanguageCode;
		}

		public static string Get(string key)
		{
			return LocalizationManager.GetTranslation(key);
		}

		public static string Get(string key, string overrideLanguage)
		{
			return LocalizationManager.GetTranslation(key, FixForRTL: true, 0, ignoreRTLnumbers: true, applyParameters: false, null, overrideLanguage);
		}

		public static string GetReplaceTags(string key)
		{
			return ReplaceTags(Get(key));
		}

		public static string GetFormat(string key, params object[] args)
		{
			return string.Format(Get(key), args);
		}

		public static string GetFormatReplaceTags(string key, params object[] args)
		{
			return ReplaceTags(GetFormat(key, args));
		}

		public static string GetMultiLine(string key)
		{
			return Get(key).Replace("\\n", "\n");
		}

		public static string GetMultiLine(string key, string overrideLanguage)
		{
			return Get(key, overrideLanguage).Replace("\\n", "\n");
		}

		public static string GetMultiLineFormat(string key, params object[] args)
		{
			return string.Format(GetMultiLine(key), args);
		}

		public static string GetMultiLineReplaceTags(string key)
		{
			return ReplaceTags(GetMultiLine(key));
		}

		public static string GetMultiLineReplaceTagsFormat(string key, params object[] args)
		{
			return ReplaceTags(GetMultiLineFormat(key, args));
		}

		public static string GetIgnoreLinebreaks(string key)
		{
			return Get(key).Replace("\\n", "");
		}

		public static string GetIgnoreLinebreaks(string key, string overrideLanguage)
		{
			return Get(key, overrideLanguage).Replace("\\n", "");
		}

		public static string GetIgnoreLinebreaksFormat(string key, params object[] args)
		{
			return string.Format(GetIgnoreLinebreaks(key), args);
		}

		public static string GetIgnoreLinebreaksReplaceTags(string key)
		{
			return ReplaceTags(GetIgnoreLinebreaks(key));
		}

		public static string GetIgnoreLinebreaksReplaceTagsFormat(string key, params object[] args)
		{
			return ReplaceTags(GetIgnoreLinebreaksFormat(key, args));
		}

		public static string ReplaceTags(string baseString)
		{
			return baseString.Replace("<b>", "<style=C1>").Replace("</b>", "</style>");
		}
	}
	public class I2SimpleKey : MonoBehaviour
	{
		public string locaKey;

		[Tooltip("If the value has <b> tags it will replace these with our tag")]
		public bool replaceTags;

		[Tooltip("If the value has \\n in it")]
		public bool isMultiLine;

		[Tooltip("If the value has \\n in it, checking this will remove them")]
		public bool forceRemoveMultiLine;

		private void OnEnable()
		{
			UpdateText();
		}

		private void UpdateText()
		{
			TMP_Text component = GetComponent<TMP_Text>();
			if (component != null)
			{
				if (forceRemoveMultiLine)
				{
					isMultiLine = true;
					string text = GetText().Replace("\n", " ");
					component.text = text;
				}
				else
				{
					component.text = GetText();
				}
			}
		}

		private string GetText()
		{
			if (replaceTags)
			{
				if (isMultiLine)
				{
					return I2Loca.GetMultiLineReplaceTags(locaKey);
				}
				return I2Loca.GetReplaceTags(locaKey);
			}
			if (isMultiLine)
			{
				return I2Loca.GetMultiLine(locaKey);
			}
			return I2Loca.Get(locaKey);
		}
	}
	public static class InputBlocker
	{
		private static List<UiBlockingPanel> BlockingUiPanels;

		public static int uiBlockers;

		private static int mutedFrames;

		private static Coroutine muteRoutine;

		public static bool Blocked
		{
			get
			{
				if (!AnyBlockingUiMenuIsOpen && uiBlockers <= 0 && mutedFrames <= 0)
				{
					return InventoryUI.IsDraggingItem;
				}
				return true;
			}
		}

		public static bool AnyBlockingUiMenuIsOpen
		{
			get
			{
				if (BlockingUiPanels != null)
				{
					return BlockingUiPanels.Any((UiBlockingPanel x) => x.GetIsBlocking());
				}
				return false;
			}
		}

		public static int BlockingMenuCount
		{
			get
			{
				if (BlockingUiPanels != null)
				{
					return BlockingUiPanels.CountIf((UiBlockingPanel x) => x.GetIsBlocking());
				}
				return 0;
			}
		}

		public static bool IsSpecificMenuBlocking(UiBlockingPanel menu)
		{
			if (BlockingUiPanels != null)
			{
				return BlockingUiPanels.Contains(menu);
			}
			return false;
		}

		public static void RegisterBlockingPanel(UiBlockingPanel p)
		{
			if (BlockingUiPanels == null)
			{
				BlockingUiPanels = new List<UiBlockingPanel>();
			}
			BlockingUiPanels.Add(p);
		}

		public static void DeregisterBlockingPanel(UiBlockingPanel p)
		{
			BlockingUiPanels.Remove(p);
		}

		public static void MuteForFrames(int frames)
		{
			mutedFrames += frames;
			if (muteRoutine == null)
			{
				muteRoutine = UtilityTG.StartCoroutine(MuteCounter());
			}
		}

		private static IEnumerator MuteCounter()
		{
			while (mutedFrames > 0)
			{
				yield return null;
				mutedFrames--;
			}
			muteRoutine = null;
		}
	}
