	public class MarketingCamera : MonoBehaviour
	{
		public Transform cameraTransform;

		public float rotationSpeed = 250f;

		private void Start()
		{
			UnityEngine.Object.Destroy(this);
		}

		private void Update()
		{
			if (Input.GetMouseButton(2))
			{
				float angle = Input.GetAxis("Mouse X") * rotationSpeed * Time.deltaTime;
				float num = Input.GetAxis("Mouse Y") * rotationSpeed * Time.deltaTime;
				base.transform.Rotate(Vector3.up, angle, Space.World);
