		private PCGamepadSetups setups;

		[SerializeField]
		private GamepadIcons.ButtonType buttonType;

		private void Awake()
		{
			RuntimePlatform platform = Application.platform;
			if (platform != RuntimePlatform.WindowsPlayer && platform != RuntimePlatform.WindowsEditor)
			{
				return;
			}
			Sprite buttonSprite = setups.GetButtonSprite(buttonType);
			if (buttonSprite == null)
			{
				UnityEngine.Debug.LogError("Got null when trying to find platform dependant sprite");
				return;
			}
			GetComponent<Image>().sprite = buttonSprite;
			if (TryGetComponent<AspectRatioFitter>(out var component))
			{
				Rect textureRect = buttonSprite.textureRect;
				component.aspectRatio = textureRect.height / textureRect.width;
			}
		}
