	[CreateAssetMenu(fileName = "PCGamepadSetups", menuName = "Tableflip/PC Gamepad Setups")]
	public class PCGamepadSetups : ScriptableObject
	{
		[Serializable]
		public class Setup
		{
			public bool isSteamDeck;

			public string gamepadName;

			public GamepadIcons icons;
		}

		[SerializeField]
		private Setup[] setups = new Setup[0];

		[SerializeField]
		public GamepadIcons backupIcons;

		public Sprite GetButtonSprite(GamepadIcons.ButtonType buttonType)
		{
			string text = null;
			bool flag = false;
			foreach (UnityEngine.InputSystem.PlayerInput item in UnityEngine.InputSystem.PlayerInput.all)
			{
				using (ReadOnlyArray<InputDevice>.Enumerator enumerator2 = item.devices.GetEnumerator())
				{
					if (enumerator2.MoveNext())
					{
						text = enumerator2.Current.name;
						flag = true;
					}
				}
				if (flag)
				{
					break;
				}
			}
			if (flag && !string.IsNullOrEmpty(text))
			{
				for (int i = 0; i < setups.Length; i++)
				{
					Setup setup = setups[i];
					if (text.ToUpper().Contains(setup.gamepadName.ToUpper()))
					{
						return setup.icons.GetSprite(buttonType);
					}
				}
			}
			if (SteamManager.Instance != null && SteamManager.Instance.IsSteamRunningOnSteamDeck() && !flag)
			{
				for (int j = 0; j < setups.Length; j++)
				{
					Setup setup2 = setups[j];
					if (setup2.isSteamDeck)
					{
						return setup2.icons.GetSprite(buttonType);
					}
				}
			}
			return backupIcons.GetSprite(buttonType);
		}
	}
