	public class RotationOscillate : MonoBehaviour
	{
		public Vector3 minimumRotation;

		public Vector3 maximumRotation;

		public float speed;

		private Transform myTransform;

		private Quaternion startRot;

		private void Start()
		{
			myTransform = base.transform;
			startRot = myTransform.rotation;
		}

		private void Update()
		{
			Vector3 euler = Vector3.Lerp(minimumRotation, maximumRotation, Mathf.Abs(Mathf.Sin(speed * Time.time)));
			myTransform.rotation = startRot * Quaternion.Euler(euler);
		}
	}
