	public static class SceneLoad
	{
		public static Action<Scene> OnSceneLoaded;

		public static Scene CurrentScene;

		public static bool IsInMainMenuScene
		{
			get
			{
				Scene currentScene = CurrentScene;
				return currentScene == Scene.MainMenu_Grove || currentScene == Scene.MainMenu_Temple2 || currentScene == Scene.MainMenu_Temple3 || currentScene == Scene.MainMenu_Ekbatan;
			}
		}

		public static void LoadAsync(Scene scene, bool save, bool withLoadingScreen = true, Action onDone = null, bool fadeIn = true, bool fadeOut = true)
		{
			if (withLoadingScreen && SingletonBehaviour<LoadingScreenUI>.InstanceExists())
			{
				switch (scene)
				{
				case Scene.Town_Grove:
					SingletonBehaviour<LoadingScreenUI>.Instance.SetTownRealm(RealmData.RealmId.Grove);
					break;
				case Scene.Town_Temple:
				case Scene.Town_Temple_Fate2:
					SingletonBehaviour<LoadingScreenUI>.Instance.SetTownRealm(RealmData.RealmId.TempleOfFate);
					break;
				case Scene.Town_Druantia:
					SingletonBehaviour<LoadingScreenUI>.Instance.SetTownRealm(RealmData.RealmId.Druantia);
					break;
				case Scene.Town_Typhon:
					SingletonBehaviour<LoadingScreenUI>.Instance.SetTownRealm(RealmData.RealmId.Typhon);
					break;
				case Scene.Town_Ekbatan:
					SingletonBehaviour<LoadingScreenUI>.Instance.SetTownRealm(RealmData.RealmId.Ekbatan);
					break;
				case Scene.Town_Prometheus:
					SingletonBehaviour<LoadingScreenUI>.Instance.SetTownRealm(RealmData.RealmId.Prometheus);
					break;
				default:
					SingletonBehaviour<LoadingScreenUI>.Instance.SetToDefault();
					break;
				}
			}
			LoadAsync((int)scene, save, withLoadingScreen, onDone, fadeIn, fadeOut);
		}

		public static void LoadAsync(int sceneIndex, bool save, bool withLoadingScreen = true, Action onDone = null, bool fadeIn = true, bool fadeOut = true)
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				SingletonBehaviour<InputBroker>.Instance.DisableAllInput();
			}
			UnityEngine.AsyncOperation loadOp = null;
			bool cleanDungeon = LevelGenerator.currentInstance != null;
			if (withLoadingScreen && SingletonBehaviour<LoadingScreenUI>.InstanceExists())
			{
				SingletonBehaviour<LoadingScreenUI>.Instance.ShowLoading(fadeIn, GetLoadProgress);
			}
			if (cleanDungeon && !withLoadingScreen)
			{
				UnityEngine.Debug.Log("You are loading another scene from dungeon without loading screen. That will reveal the cleanup process. It is recommendeded to go WITH loading screen.");
			}
			if (save)
			{
				try
				{
					SaveData.RequestSave(delegate
					{
						if (cleanDungeon)
						{
							LevelGenerator.currentInstance.RemoveObjectsOverTime(delegate
							{
								StartLoadingScene(alreadyShowingLoading: true);
							});
						}
						else
						{
							StartLoadingScene(alreadyShowingLoading: true);
						}
					});
					return;
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogError("Exception caught (no rethrow) while running save in SceneLoad: " + ex.Message + "\n" + ex.StackTrace);
					StartLoadingScene(withLoadingScreen);
					return;
				}
			}
			StartLoadingScene(withLoadingScreen);
			float GetLoadProgress()
			{
				if (cleanDungeon && LevelGenerator.currentInstance != null && LevelGenerator.currentInstance.IsCleaning)
				{
					return LevelGenerator.currentInstance.GetCleanProgress() * 0.5f;
				}
				if (loadOp == null)
				{
					if (!cleanDungeon)
					{
						return 0f;
					}
					return 0.5f;
				}
				if (!cleanDungeon)
				{
					return loadOp.progress;
				}
				return 0.5f + 0.5f * loadOp.progress;
			}
			void StartLoadingScene(bool alreadyShowingLoading)
			{
				loadOp = SceneManager.LoadSceneAsync(sceneIndex);
				if (loadOp == null)
				{
					UnityEngine.Debug.LogWarning("SceneLoad failed");
				}
				else
				{
					loadOp.allowSceneActivation = true;
					if (withLoadingScreen && SingletonBehaviour<LoadingScreenUI>.InstanceExists())
					{
						loadOp.completed += delegate
						{
							if (SingletonBehaviour<LoadingScreenUI>.InstanceExists())
							{
								SingletonBehaviour<LoadingScreenUI>.Instance.HideLoading(fadeOut);
							}
						};
						if (!alreadyShowingLoading)
						{
							SingletonBehaviour<LoadingScreenUI>.Instance.ShowLoading(fadeIn, GetLoadProgress);
						}
					}
					loadOp.completed += delegate
					{
						onDone?.Invoke();
						try
						{
							Scene obj = (CurrentScene = (Scene)sceneIndex);
							OnSceneLoaded?.Invoke(obj);
						}
						catch (InvalidCastException exception)
						{
							UnityEngine.Debug.LogException(exception);
						}
					};
				}
			}
		}

		public static void LoadMainMenuCurrentGame(bool saveFirst, Action onLoaded, bool showLoading = true)
		{
			Scene scene = Scene.MainMenu_Grove;
			switch (Fate.CurrentFateVer)
			{
			case Fate.FateVer.Original:
				scene = Scene.MainMenu_Grove;
				break;
			case Fate.FateVer.UndiscoveredRealms:
				scene = Scene.MainMenu_Temple2;
				break;
			case Fate.FateVer.TraitorSoul:
				scene = Scene.MainMenu_Temple3;
				break;
			case Fate.FateVer.CursedKing:
				scene = Scene.MainMenu_Ekbatan;
				break;
			}
			LoadAsync(scene, saveFirst, showLoading, onLoaded);
		}

		public static Scene GetTownScene(RealmData.RealmId realm)
		{
			switch (realm)
			{
			case RealmData.RealmId.Grove:
				return Scene.Town_Grove;
			case RealmData.RealmId.Druantia:
				return Scene.Town_Druantia;
			case RealmData.RealmId.Typhon:
				return Scene.Town_Typhon;
			case RealmData.RealmId.TempleOfFate:
				if (Fate.CurrentFateVer != Fate.FateVer.TraitorSoul)
				{
					return Scene.Town_Temple_Fate2;
				}
				return Scene.Town_Temple;
			case RealmData.RealmId.Ekbatan:
				return Scene.Town_Ekbatan;
			case RealmData.RealmId.Prometheus:
				return Scene.Town_Prometheus;
			default:
				UnityEngine.Debug.Log("No Town Scene found: " + realm);
				return Scene.Town_Grove;
			}
		}

		public static Scene GetTownScene(Fate.FateVer fateVersion)
		{
			return fateVersion switch
			{
				Fate.FateVer.Original => Scene.Town_Grove, 
				Fate.FateVer.UndiscoveredRealms => Scene.Town_Temple_Fate2, 
				Fate.FateVer.TraitorSoul => Scene.Town_Temple, 
				Fate.FateVer.CursedKing => Scene.Town_Ekbatan, 
				_ => Scene.Town_Grove, 
			};
		}
	}
	public class SceneSpecificGameObjectToggle : MonoBehaviour
	{
		public Scene[] activeInScene;

		private void Awake()
		{
			SceneLoad.OnSceneLoaded = (Action<Scene>)Delegate.Combine(SceneLoad.OnSceneLoaded, new Action<Scene>(OnSceneLoad));
			bool active = false;
			for (int i = 0; i < activeInScene.Length; i++)
			{
				if (activeInScene[i] == SceneLoad.CurrentScene)
				{
					active = true;
					break;
				}
			}
			base.gameObject.SetActive(active);
		}

		private void OnDestroy()
		{
			SceneLoad.OnSceneLoaded = (Action<Scene>)Delegate.Remove(SceneLoad.OnSceneLoaded, new Action<Scene>(OnSceneLoad));
		}

		private void OnSceneLoad(Scene scene)
		{
			bool active = false;
			for (int i = 0; i < activeInScene.Length; i++)
			{
				if (activeInScene[i] == SceneLoad.CurrentScene)
				{
					active = true;
					break;
				}
			}
			base.gameObject.SetActive(active);
		}
	}
	public class ScreenInfo : MonoBehaviour
	{
		private static ScreenInfo _instance;

		private int screenWidth;

		private int screenHeight;

		private float currentAspect;

		public bool showOnScreen;

		public static Action<float> OnScreenAspectChanged;

		public static Action<int, int> OnScreenResolutionChanged;

		private void Awake()
		{
			if (_instance != null)
			{
				UnityEngine.Object.Destroy(this);
			}
			else
			{
				_instance = this;
			}
		}

		private void Start()
		{
			screenWidth = Screen.width;
			screenHeight = Screen.height;
			currentAspect = screenWidth / screenHeight;
			StartCoroutine(ScreenTracker());
		}

		private IEnumerator ScreenTracker()
		{
			WaitForSecondsRealtime wait = new WaitForSecondsRealtime(0.5f);
			while (base.gameObject.activeInHierarchy)
			{
				yield return wait;
				if (screenWidth != Screen.width || screenHeight != Screen.height)
				{
					screenWidth = Screen.width;
					screenHeight = Screen.height;
					float num = screenWidth / screenHeight;
					if (Mathf.Abs(currentAspect - num) > 0.02f)
					{
						currentAspect = num;
						OnScreenAspectChanged?.Invoke(currentAspect);
					}
					OnScreenResolutionChanged?.Invoke(screenWidth, screenHeight);
				}
			}
		}

		private void OnGUI()
		{
			if (showOnScreen)
			{
				GUI.Label(new Rect(10f, 10f, 200f, 30f), $"W: {screenWidth} H: {screenHeight}");
			}
		}
	}
	public class GetPercentOfSuccessfulDungeons : MonoBehaviour
	{
		[Space(10f)]
		public bool activate = true;

		public bool breakAtFirstFailure;

		public int amountOfTries = 1000;

		[ReadOnlyInInspector]
		[Space(10f)]
		[Header("Successful Percentage")]
		public float percentOfSuccessfulTries;

		[ReadOnlyInInspector]
		[Space(10f)]
		[Header("Wrongful Seeds")]
		public List<int> seeds = new List<int>();

		private void Start()
		{
			if (activate)
			{
				StartCoroutine("GenerateDungeons");
			}
		}

		private IEnumerator GenerateDungeons()
		{
			int successes = 0;
			int tries;
			for (tries = 0; tries < amountOfTries; tries++)
			{
				yield return new WaitForSeconds(0.1f);
				LevelGenerator.currentInstance.ReplaceDungeon(0f, 0f, 2, 10, goesDown: false, useSavedPosition: true, ignoreSavedState: true);
				yield return new WaitForSeconds(0.1f);
				NavMeshPath navMeshPath = new NavMeshPath();
				if (!NavMesh.CalculatePath(LevelGenerator.currentInstance.GetSpawnPointUp(), LevelGenerator.currentInstance.GetSpawnPointDown(), 1, navMeshPath))
				{
					continue;
				}
				if (navMeshPath.status == NavMeshPathStatus.PathComplete)
				{
					successes++;
					continue;
				}
				seeds.Add(LevelGenerator.currentInstance.GetSeed());
				if (breakAtFirstFailure)
				{
					break;
				}
			}
			percentOfSuccessfulTries = 100f * ((float)successes / (float)tries);
		}
	}
