namespace Deftly
{
	public class Door : MonoBehaviour
	{
		[Header("Door setup assumes Closed position")]
		public GameObject DoorMesh;

		public LayerMask CanUseThisDoor;

		public Vector3 OpenDirection;

		public AnimationCurve OpenCurve;

		public AnimationCurve CloseCurve;

		[Space]
		public float TotalTimeToUse;

		public AudioClip OpenSound;

		public AudioClip CloseSound;

		protected bool DoorIsMoving;

		protected bool DoorIsOpen;

		protected float Progress;

		public bool ManuallyTriggered;

		public bool Locked;

		public bool StartClosed;

		protected int Occupancy;

		protected Vector3 ClosedPosition;

		protected Vector3 OpenPosition;

		protected AudioSource NoiseMaker;

		public virtual void Reset()
		{
			OpenDirection = Vector3.right;
			OpenCurve = AnimationCurve.Linear(0f, 0f, 1f, 1f);
			CloseCurve = AnimationCurve.Linear(0f, 0f, 1f, 1f);
			TotalTimeToUse = 0.5f;
			OpenSound = null;
			CloseSound = null;
			ManuallyTriggered = false;
			Locked = false;
		}

		public virtual void Awake()
		{
			ClosedPosition = base.gameObject.transform.position;
			OpenPosition = ClosedPosition + base.gameObject.transform.InverseTransformDirection(OpenDirection);
		}

		public virtual void Start()
		{
			NoiseMaker = GetComponent<AudioSource>();
			Occupancy = 0;
			if (StartClosed)
			{
				StartCoroutine(StartClose());
			}
			base.gameObject.layer = LayerMask.NameToLayer("Trigger");
		}

		private IEnumerator StartClose()
		{
			yield return new WaitForSeconds(0.5f);
			Close();
		}

		public virtual void OnTriggerEnter(Collider col)
		{
			if (!ManuallyTriggered && !Locked && (bool)DoorMesh && GameUtils.LayerMaskIncludesLayer(CanUseThisDoor, col.gameObject.layer))
			{
				Occupancy++;
			}
		}

		public virtual void OnTriggerExit(Collider col)
		{
			if (!ManuallyTriggered && !Locked && (bool)DoorMesh && GameUtils.LayerMaskIncludesLayer(CanUseThisDoor, col.gameObject.layer))
			{
				Occupancy--;
			}
		}

		public virtual void Update()
		{
			if (DoorIsMoving)
			{
				Progress += Time.deltaTime;
			}
			if (!ManuallyTriggered && !Locked)
			{
				if (DoorIsOpen && !DoorIsMoving && Occupancy == 0)
				{
					Close();
				}
				if (!DoorIsOpen && !DoorIsMoving && Occupancy > 0)
				{
					Open();
				}
			}
		}

		public virtual void Open()
		{
			StartCoroutine(OpenDoor());
		}

		public virtual void Close()
		{
			StartCoroutine(CloseDoor());
		}

		protected virtual IEnumerator OpenDoor()
		{
			while (DoorIsMoving)
			{
				yield return null;
			}
			if (!DoorIsOpen)
			{
				Progress = 0f;
				DoorIsMoving = true;
				if (OpenSound != null)
				{
					NoiseMaker.clip = OpenSound;
					NoiseMaker.Play();
				}
				while (Progress <= TotalTimeToUse)
				{
					DoorMesh.transform.position = ClosedPosition + base.gameObject.transform.InverseTransformDirection(OpenDirection * CloseCurve.Evaluate(Progress / TotalTimeToUse));
					yield return null;
				}
				DoorIsMoving = false;
				DoorIsOpen = true;
				yield return null;
			}
		}

		protected virtual IEnumerator CloseDoor()
		{
			while (DoorIsMoving)
			{
				yield return null;
			}
			if (DoorIsOpen)
			{
				Progress = 0f;
				DoorIsMoving = true;
				if (CloseSound != null)
				{
					NoiseMaker.clip = CloseSound;
					NoiseMaker.Play();
				}
				while (Progress <= TotalTimeToUse)
				{
					DoorMesh.transform.position = OpenPosition + base.gameObject.transform.InverseTransformDirection(-OpenDirection * CloseCurve.Evaluate(Progress / TotalTimeToUse));
					yield return null;
				}
				DoorIsMoving = false;
				DoorIsOpen = false;
				yield return null;
			}
		}
	}
