	public abstract class InteractableSceneObject : MonoBehaviour
	{
		public static InteractableSceneObject CurrentSelected;

		public string InteractableName { get; protected set; }

		public bool IsSelected { get; protected set; }

		public int InteractionPriority { get; protected set; }

		public float InteractRange { get; protected set; } = 3f;


		public virtual bool CanInteract { get; protected set; } = true;


		public virtual Vector3 GetCenterPosition()
		{
			return base.transform.position;
		}

		public abstract void Interact(Character interactor = null);

		public virtual void InteractionSelect(Character interactor)
		{
			if (CurrentSelected != null)
			{
				CurrentSelected.InteractionDeselect(interactor);
			}
			IsSelected = true;
			if (TryGetComponent<InteractableTooltipBase>(out var component))
			{
				component.SetHovered(isHovered: true);
			}
		}

		public virtual void InteractionDeselect(Character interactor = null)
		{
			IsSelected = false;
			if (TryGetComponent<InteractableTooltipBase>(out var component))
			{
				component.SetHovered(isHovered: false);
			}
		}
	}
	public class InteractableSelector : MonoBehaviour
	{
		public float InteractRadius;

		public LayerMask InteractableLayer;

		public Character owner;

		protected List<InteractableSceneObject> Targets;

		protected List<InteractableSceneObject> OutOfRange;

		protected List<Monster> monsters;

		protected bool InteractPressed;

		protected List<int> Deselect;

		private void Reset()
		{
			InteractRadius = 2f;
			InteractableLayer = 1;
			Targets = null;
		}

		private void Awake()
		{
			Targets = new List<InteractableSceneObject>();
			monsters = new List<Monster>();
			Deselect = new List<int>();
			if (owner == null)
			{
				owner = GetComponent<Character>();
			}
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
				instance.OnInputBehaviorChanged = (Action<InputBroker.InputBehavior>)Delegate.Combine(instance.OnInputBehaviorChanged, new Action<InputBroker.InputBehavior>(OnInputBehaviorChanged));
			}
		}

		private void OnInputBehaviorChanged(InputBroker.InputBehavior behaviour)
		{
			if (Targets == null || Targets.Count <= 0)
			{
				return;
			}
			foreach (InteractableSceneObject target in Targets)
			{
				if (target != null)
				{
					target.InteractionDeselect(owner);
				}
			}
			Targets.Clear();
		}

		private void Update()
		{
			if (!InputBlocker.Blocked && !InteractPressed)
			{
				InteractPressed = SingletonBehaviour<InputBroker>.Instance.Interact;
				_ = InteractPressed;
			}
		}

		protected virtual void FixedUpdate()
		{
			Scan();
			if (InteractPressed)
			{
				InteractWithCurrentTarget();
			}
			InteractPressed = false;
		}

		protected virtual void Scan()
		{
			InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
			if (instance.LocalInputBehavior != 0)
			{
				return;
			}
			foreach (InteractableSceneObject target in Targets)
			{
				if (target != null && !target.CanInteract)
				{
					target.InteractionDeselect(owner);
				}
			}
			Targets.RemoveAll((InteractableSceneObject x) => x == null || !x.CanInteract);
			RaycastHit[] array = Physics.SphereCastAll(base.transform.position, InteractRadius, Vector3.up, 0.01f, InteractableLayer);
			foreach (RaycastHit raycastHit in array)
			{
				InteractableSceneObject component = raycastHit.transform.GetComponent<InteractableSceneObject>();
				if (component != null && !Targets.Contains(component) && component.CanInteract)
				{
					Targets.Add(component);
				}
			}
			OutOfRange = Targets.FindAll((InteractableSceneObject x) => Vector3.Distance(base.transform.position, x.GetCenterPosition()) > x.InteractRange);
			foreach (InteractableSceneObject item in OutOfRange)
			{
				item.InteractionDeselect(owner);
				Targets.Remove(item);
			}
			if (Targets.Count < 1)
			{
				Player.PlayerChar.DroppedItemInRange = null;
				Player.PlayerChar.MerchantInRange = null;
				ScanForEnemies();
				return;
			}
			if (Targets.Count > 1)
			{
				Targets = Targets.OrderByDescending((InteractableSceneObject x) => x.InteractionPriority).ToList();
			}
			InteractableSceneObject interactableSceneObject = Targets[0];
			interactableSceneObject.InteractionSelect(owner);
			if (!string.IsNullOrEmpty(interactableSceneObject.InteractableName))
			{
				instance.SetHighlightedTarget(interactableSceneObject.transform);
			}
			else
			{
				ScanForEnemies();
			}
			Player.PlayerChar.DroppedItemInRange = null;
			Player.PlayerChar.MerchantInRange = null;
			for (int num = Targets.Count - 1; num >= 0; num--)
			{
				_ = Targets[num];
				MerchantInteractable component3;
				if (interactableSceneObject.TryGetComponent<DroppedItem>(out var component2))
				{
					Player.PlayerChar.DroppedItemInRange = component2;
				}
				else if (interactableSceneObject.TryGetComponent<MerchantInteractable>(out component3))
				{
					Player.PlayerChar.MerchantInRange = component3;
				}
			}
		}

		private void ScanForEnemies()
		{
			monsters.Clear();
			RaycastHit[] array = Physics.SphereCastAll(base.transform.position + base.transform.forward * 1.8f, 2f, Vector3.up, 0.01f, SingletonBehaviour<InputBroker>.Instance.EnemyLayer);
			if (array != null && array.Length != 0)
			{
				Array.Sort(array, (RaycastHit hit1, RaycastHit hit2) => hit1.distance.CompareTo(hit2.distance));
				RaycastHit[] array2 = array;
				foreach (RaycastHit raycastHit in array2)
				{
					Monster component = raycastHit.transform.GetComponent<Monster>();
					if (!(component == null) && component.Alive() && !monsters.Contains(component))
					{
						monsters.Add(component);
					}
				}
			}
			if (monsters.Count > 0)
			{
				SingletonBehaviour<InputBroker>.Instance.SetHighlightedTarget(monsters[0].myTransform);
			}
			if (monsters.Count == 0)
			{
				SingletonBehaviour<InputBroker>.Instance.SetHighlightedTarget(null);
			}
		}

		protected virtual void InteractWithCurrentTarget()
		{
			if (Targets.Count > 0)
			{
				InteractableSceneObject interactableSceneObject = Targets[0];
				if (!(interactableSceneObject == null))
				{
					interactableSceneObject.Interact(owner);
					owner.myTransform.LookAt(interactableSceneObject.transform.position.WithY(owner.myTransform.position.y));
				}
			}
		}
	}
