		}

		public Type SourceType
		{
			get
			{
				return Type.GetType(m_typeName);
			}
			set
			{
				m_typeName = value.AssemblyQualifiedName;
			}
		}

		public List<DataEntity> Content
		{
			get
			{
				return m_data;
			}
			set
			{
				m_data = value;
			}
		}

		public VaultStaticDataGroup(Type t)
		{
			SourceType = t;
		}

		public void AddEntity(DataEntity data)
		{
			Content.Add(data);
		}

		public void RemoveEntity(int key)
		{
			for (int i = 0; i < Content.Count; i++)
			{
				if (Content[i].GetDbKey() == key)
				{
					Content.RemoveAt(i);
				}
			}
		}

		public void Sanitize()
		{
			Content.RemoveAll((DataEntity x) => x == null);
		}
	}
}
namespace Cleverous.ThatHurtModule
{
	public class Floatie : MonoBehaviour
	{
		[Tooltip("The UI Text Label for the Floatie.")]
		public TextMeshProUGUI Label;

		private float m_baseTextSize;

		private Color m_baseColor;

		private int m_index;

		private Vector3 m_origin;

		private Vector3 m_goalOffset;

		private Vector3 m_velocityOffset;

		private float m_aliveTime;

		private float m_lifeTime;

		private bool m_isVelocityBased;

		public virtual void Init(int myIndex)
		{
			Deactivate();
			m_origin = Vector3.up * 5000f;
			m_baseTextSize = Label.fontSize;
			m_baseColor = Label.color;
			m_index = myIndex;
			SetRandomOffset();
		}

		protected virtual void Update()
		{
			if (!Mathf.Approximately(m_lifeTime, 0f))
			{
				if (m_aliveTime > m_lifeTime)
				{
					Deactivate();
				}
				m_aliveTime += Time.unscaledDeltaTime;
				if (!(m_aliveTime < 0f))
				{
					float num = m_aliveTime / m_lifeTime;
					Label.color = new Color(Label.color.r, Label.color.g, Label.color.b, ThatHurt.Instance.VisibilityCurve.Evaluate(num));
					base.transform.position = GetPos(num);
					base.transform.localScale = GetScale(num);
				}
			}
		}

		private void SetRandomOffset()
		{
			m_goalOffset = new Vector3(UnityEngine.Random.Range(ThatHurt.Instance.OffsetMin.x, ThatHurt.Instance.OffsetMax.x), UnityEngine.Random.Range(ThatHurt.Instance.OffsetMin.y, ThatHurt.Instance.OffsetMax.y), UnityEngine.Random.Range(ThatHurt.Instance.OffsetMin.z, ThatHurt.Instance.OffsetMax.z));
		}

		private Vector3 GetPos(float progress)
		{
			Vector3 vector = new Vector3((m_isVelocityBased ? m_velocityOffset.x : m_goalOffset.x) * ThatHurt.Instance.MoveCurveH.Evaluate(progress), (m_isVelocityBased ? 1f : m_goalOffset.y) * ThatHurt.Instance.MoveCurveV.Evaluate(progress), (m_isVelocityBased ? m_velocityOffset.z : m_goalOffset.z) * ThatHurt.Instance.MoveCurveH.Evaluate(progress));
			return Vector3.Lerp(ThatHurt.Instance.GameCamera.WorldToScreenPoint(m_origin), ThatHurt.Instance.GameCamera.WorldToScreenPoint(m_origin + vector * ThatHurt.Instance.IntensityScale), progress);
		}

		private static Vector3 GetScale(float progress)
		{
			return new Vector3(ThatHurt.Instance.ScaleH.Evaluate(progress), ThatHurt.Instance.ScaleV.Evaluate(progress), ThatHurt.Instance.ScaleH.Evaluate(progress));
		}

		public virtual void Pop(Vector3 origin, string value, float sizeMultiplier, Color color, float timingOffset)
		{
			m_isVelocityBased = false;
			m_origin = origin;
			m_aliveTime = timingOffset;
			Label.text = value;
			Label.color = color;
			Label.fontSize = (int)(m_baseTextSize * sizeMultiplier);
			base.transform.position = new Vector3(-5000f, -5000f, -5000f);
			m_lifeTime = ThatHurt.Instance.FloatieLifetime;
		}

		public virtual void Pop(Vector3 origin, string value, float sizeMultiplier, float lifetimeOverride, Color color, float timingOffset)
		{
			Pop(origin, value, sizeMultiplier, color, timingOffset);
			m_lifeTime = lifetimeOverride;
		}

		public virtual void Pop(Vector3 origin, string value, float sizeMultiplier)
		{
			Pop(origin, value, sizeMultiplier, m_baseColor, 0f);
		}

		public virtual void Pop(Vector3 origin, string value)
		{
			Pop(origin, value, 1f, m_baseColor, 0f);
		}

		public virtual void Pop(Vector3 origin, Vector3 velocity, string value, float sizeMultiplier, Color color, float timingOffset)
		{
			m_isVelocityBased = true;
			m_velocityOffset = velocity;
			m_origin = origin;
			m_aliveTime = timingOffset;
			Label.text = value;
			Label.color = color;
			Label.fontSize = (int)(m_baseTextSize * sizeMultiplier);
			base.transform.position = new Vector3(-5000f, -5000f, -5000f);
			m_lifeTime = ThatHurt.Instance.FloatieLifetime;
		}

		public virtual void Pop(Vector3 origin, Vector3 velocity, string value, float sizeMultiplier)
		{
			Pop(origin, value, sizeMultiplier, m_baseColor, 0f);
		}

		public virtual void Pop(Vector3 origin, Vector3 velocity, string value)
		{
			Pop(origin, value, 1f, m_baseColor, 0f);
		}

		public virtual void Deactivate()
		{
			base.gameObject.transform.position = Vector3.up * 5000f;
		}
	}
	public class ThatHurt : MonoBehaviour
	{
		public enum ThatHurtColor
		{
			White,
			Healing,
			Damage,
			Mana,
			Experience,
			Gold
		}

		public static ThatHurt Instance;

		[Header("Setup / References")]
		[Tooltip("Master toggle for enabling or disabling the floaties.")]
		public bool FloatiesEnabled;

		[Tooltip("Number formatting forces every Pop to be kilo formatted with string methods. \n\nNOTE!! This is a significant performance impact since it does not used the integer pool.")]
		public bool KiloFormatting;

		[Tooltip("How many floaties prefabs to load into a pool for reuse.")]
		public int PoolSize;

		[Tooltip("The floatie prefab that will be instantiated in the UI Canvas")]
		public Floatie FloatiePrefab;

		[Tooltip("The UI Canvas the floaties will exist on.")]
		public Canvas GameCanvas;

		[SerializeField]
		private Color whiteColor = Color.white;

		[SerializeField]
		private Color healingColor = Color.white;

		[SerializeField]
		private Color damageColor = Color.white;

		[SerializeField]
		private Color experienceColor = Color.white;

		[SerializeField]
		private Color manaColor = Color.white;

		[SerializeField]
		private Color goldColor = Color.white;

		[Tooltip("The Main Camera the floaties should be orienting toward.")]
		[SerializeField]
		private Camera m_gameCamera;

		[Header("Behavioral Settings")]
		[Tooltip("How long the floaties should exist.")]
		public float FloatieLifetime;

		[Tooltip("The minimum speed the floaties should move.")]
		public float SpeedMin;

		[Tooltip("The maximum speed the floaties should move.")]
		public float SpeedMax;

		[Tooltip("The minimum distance the floaties should deviate from the origin position when spawned.\nIt's best to set these to low values and adjust the Intensity Scale.")]
		public Vector3 OffsetMin;

		[Tooltip("The maximum distance the floaties should deviate from the origin position when spawned.\nIt's best to set these to low values and adjust the Intensity Scale.")]
		public Vector3 OffsetMax;

		[Tooltip("The sclar value for Offets, making it easier to adjust .. well.. intensity..")]
		public int IntensityScale;

		[Header("Curves")]
		[Tooltip("The curve/speed over time for moving the floaties horizontally.")]
		public AnimationCurve MoveCurveH;

		[Tooltip("The curve/speed over time for moving the floaties vertically.")]
		public AnimationCurve MoveCurveV;

		[Tooltip("The curve for fading the floaties out over time.")]
		public AnimationCurve VisibilityCurve;

		[Tooltip("The curve for controlling horizontal floatie scale over time.")]
		public AnimationCurve ScaleH;

		[Tooltip("The curve for controlling vertical floatie scale over time.")]
		public AnimationCurve ScaleV;

		private static Floatie[] m_pool;

		private Transform m_floatieFolder;

		private static string[] m_numbers;

		private const int NumBufferSize = 10000;

		private static int m_next;

		private bool m_initialized;

		public Camera GameCamera
		{
			get
			{
				if (m_gameCamera == null)
				{
					m_gameCamera = Camera.main;
				}
				return m_gameCamera;
			}
			set
			{
				m_gameCamera = value;
			}
		}

		private static int NextIndex
		{
			get
			{
				if (m_next >= Instance.PoolSize)
				{
					m_next = 0;
				}
				return m_next++;
			}
		}

		private Color GetColor(ThatHurtColor color)
		{
			return color switch
			{
				ThatHurtColor.White => whiteColor, 
				ThatHurtColor.Healing => healingColor, 
				ThatHurtColor.Damage => damageColor, 
				ThatHurtColor.Mana => manaColor, 
				ThatHurtColor.Experience => experienceColor, 
				ThatHurtColor.Gold => goldColor, 
				_ => throw new Exception($"Unhandled enum value {color}"), 
			};
		}

		public virtual void Reset()
		{
			FloatiesEnabled = true;
			PoolSize = 50;
			FloatieLifetime = 1f;
			SpeedMin = 2f;
			SpeedMax = 3f;
			OffsetMin = new Vector3(-1f, 1f, -1f);
			OffsetMax = Vector3.one + Vector3.up;
			IntensityScale = 2;
			MoveCurveH = new AnimationCurve(new Keyframe(0f, 0f), new Keyframe(1f, 1f));
			MoveCurveV = AnimationCurve.Linear(0f, 1f, 1f, 0f);
			VisibilityCurve = new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(0.8f, 0.8f), new Keyframe(1f, 0f));
			ScaleH = AnimationCurve.Constant(0f, 1f, 1f);
			ScaleV = AnimationCurve.Constant(0f, 1f, 1f);
		}

		public virtual void Awake()
		{
			if (!m_initialized)
			{
				if (FloatiePrefab == null)
				{
					throw new ArgumentNullException("FloatiePrefab", "ThatHurt - Floatie Prefab cannot be null!");
				}
				if (GameCanvas == null)
				{
					throw new ArgumentNullException("GameCanvas", "ThatHurt - Game Canvas cannot be null!");
				}
				if (GameCamera == null)
				{
					throw new ArgumentNullException("GameCamera", "ThatHurt - Game Camera cannot be null!");
				}
				Instance = this;
				m_pool = new Floatie[100];
				m_floatieFolder = new GameObject("Damage Floaties Pool Folder").transform;
				m_floatieFolder.SetParent(GameCanvas.transform);
				for (int i = 0; i < PoolSize; i++)
				{
					m_pool[i] = UnityEngine.Object.Instantiate(FloatiePrefab.gameObject, Vector3.zero, Quaternion.identity, m_floatieFolder).GetComponent<Floatie>();
					m_pool[i].Init(i);
				}
				m_numbers = new string[10000];
				for (int j = 0; j < 10000; j++)
				{
					m_numbers[j] = j.ToString();
				}
				m_initialized = true;
			}
		}

		public static string GetStringOfNumber(int value)
		{
			if (!Instance.KiloFormatting)
			{
				if (value <= m_numbers.Length)
				{
					return m_numbers[value];
				}
				return value.ToString();
			}
			return KiloFormat(value);
		}

		public static void Pop(Vector3 worldPos, int value)
		{
			if (Instance.FloatiesEnabled)
			{
				m_pool[NextIndex].Pop(worldPos, GetStringOfNumber(value), 1f, Instance.GetColor(ThatHurtColor.White), 0f);
			}
		}

		public static void Pop(Vector3 worldPos, int value, float sizeMultiplier, ThatHurtColor color)
		{
			if (Instance.FloatiesEnabled)
			{
				m_pool[NextIndex].Pop(worldPos, GetStringOfNumber(value), sizeMultiplier, Instance.GetColor(color), 0f);
			}
		}

		public static void Pop(Vector3 worldPos, int value, float sizeMultiplier)
		{
			if (Instance.FloatiesEnabled)
			{
				m_pool[NextIndex].Pop(worldPos, Instance.KiloFormatting ? KiloFormat(value) : m_numbers[value], sizeMultiplier, Instance.GetColor(ThatHurtColor.White), 0f);
			}
		}

		public static void Pop(Vector3 worldPos, Vector3 velocity, int value)
		{
			if (Instance.FloatiesEnabled)
			{
				m_pool[NextIndex].Pop(worldPos, velocity, GetStringOfNumber(value), 1f, Instance.GetColor(ThatHurtColor.White), 0f);
			}
		}

		public static void Pop(Vector3 worldPos, Vector3 velocity, int value, float sizeMultiplier, ThatHurtColor color)
		{
			if (Instance.FloatiesEnabled)
			{
				m_pool[NextIndex].Pop(worldPos, velocity, GetStringOfNumber(value), sizeMultiplier, Instance.GetColor(color), 0f);
			}
		}

		public static void Pop(Vector3 worldPos, Vector3 velocity, int value, float sizeMultiplier)
		{
			if (Instance.FloatiesEnabled)
			{
				m_pool[NextIndex].Pop(worldPos, velocity, GetStringOfNumber(value), sizeMultiplier, Instance.GetColor(ThatHurtColor.White), 0f);
			}
		}

		public static void PopText(Vector3 worldPos, string value, float sizeMultiplier, ThatHurtColor color, float timingOffset)
		{
			if (Instance.FloatiesEnabled)
			{
				m_pool[NextIndex].Pop(worldPos, value, sizeMultiplier, Instance.GetColor(color), timingOffset);
			}
		}

		public static void PopText(Vector3 worldPos, string value, float sizeMultiplier, float lifetimeOverride, ThatHurtColor color, float timingOffset)
		{
			if (Instance.FloatiesEnabled)
			{
				m_pool[NextIndex].Pop(worldPos, value, sizeMultiplier, lifetimeOverride, Instance.GetColor(color), timingOffset);
			}
		}

		public static void PopText(Vector3 worldPos, Vector3 velocity, string value, float sizeMultiplier, ThatHurtColor color, float timingOffset)
		{
			if (Instance.FloatiesEnabled)
			{
				m_pool[NextIndex].Pop(worldPos, velocity, value, sizeMultiplier, Instance.GetColor(color), timingOffset);
			}
		}

		public static string KiloFormat(int num)
		{
			if (num >= 100000000)
			{
				return (num / 1000000).ToString("#,0M");
			}
			if (num >= 10000000)
			{
				return (num / 1000000).ToString("0.#") + "M";
			}
			if (num >= 100000)
			{
				return (num / 1000).ToString("#,0K");
			}
			if (num >= 10000)
			{
				return (num / 1000).ToString("0.#") + "K";
			}
			return num.ToString("#,0");
		}
	}
