	public class RagdollScript : MonoBehaviour
	{
		private void Awake()
		{
			Ragdoll(state: false);
		}

		private void Update()
		{
			if (UnityEngine.Input.GetMouseButtonDown(0))
			{
				Ragdoll(state: true);
				GetComponent<Animator>().enabled = false;
				Physics.Raycast(Camera.main.ScreenPointToRay(UnityEngine.Input.mousePosition), out var hitInfo, 100f, -1, QueryTriggerInteraction.Collide);
				if (hitInfo.rigidbody != null)
				{
					hitInfo.rigidbody.velocity = (base.transform.position - Camera.main.transform.position).normalized * 15f;
				}
			}
		}

		private void Ragdoll(bool state)
		{
			Rigidbody[] componentsInChildren = GetComponentsInChildren<Rigidbody>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].isKinematic = !state;
			}
		}
	}
