	public class TimeScaleTester : MonoBehaviour
	{
		[Range(0f, 1.2f)]
		public float Value;

		private float m_cache;

		private bool m_isDirty;

		private void Update()
		{
			if (UnityEngine.Input.GetKeyUp(KeyCode.Semicolon))
			{
				UnityEngine.Debug.Log($"Down Time: {Value}");
				Value -= 0.1f;
				Value = Mathf.Clamp(Value, 0.05f, 1.2f);
				m_isDirty = true;
			}
			if (UnityEngine.Input.GetKeyUp(KeyCode.Quote))
			{
				UnityEngine.Debug.Log($"Up Time: {Value}");
				Value += 0.1f;
				Value = Mathf.Clamp(Value, 0.05f, 1.2f);
				m_isDirty = true;
			}
			if (m_isDirty || Math.Abs(m_cache - Value) > 0.02f)
			{
				Time.timeScale = Value;
				m_cache = Value;
				m_isDirty = false;
			}
		}
	}
