	public class AnimStateDenial : StateMachineBehaviour
	{
		private AgentLocomotionBase m_agent;

		[Header("State Entry - Block during this state")]
		public bool Apply;

		public bool DenyFire;

		public bool DenyAbility;

		public bool DenyMove;

		public bool DenyLook;

		public bool DenyIk;

		protected int ActiveDenialId;

		public override void OnStateEnter(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			if (m_agent == null)
			{
				m_agent = animator.gameObject.GetComponent<AgentLocomotionBase>();
			}
			if (Apply && !(m_agent == null))
			{
				ActiveDenialId = m_agent.AgentOwner.AddDenial(new RuntimeDenial(DenyMove, DenyLook, DenyFire, DenyAbility, DenyIk));
			}
		}

		public override void OnStateExit(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			if (m_agent == null)
			{
				m_agent = animator.gameObject.GetComponent<AgentLocomotionBase>();
			}
			if (Apply && !(m_agent == null))
			{
				m_agent.AgentOwner.RemoveDenialById(ActiveDenialId);
			}
		}
	}
