	public abstract class AgentLocomotionBase : MonoBehaviour, IManagedTick, IAgentLocomotion
	{
		[Header("References")]
		public ProdigyAgent AgentOwner;

		protected bool IsBeingPushed;

		protected Vector3 PushVector;

		protected Vector3 MoveAffectorSingleFrame;

		protected const int PushDecel = 5;

		private float m_nextStepTime;

		private void OnDrawGizmosSelected()
		{
			if (Application.isPlaying)
			{
				PlayerInput input = AgentOwner.GetInput();
				Gizmos.color = Color.red;
				Gizmos.DrawRay(base.transform.position + Vector3.up * 2f, input.Move);
				Gizmos.DrawSphere(base.transform.position + input.Move, 0.2f);
				Gizmos.color = Color.green;
				Gizmos.DrawRay(base.transform.position + Vector3.up * 2f, input.Look);
				Gizmos.DrawSphere(base.transform.position + input.Look, 0.2f);
			}
		}

		private void Reset()
		{
			AgentOwner = GetComponent<ProdigyAgent>();
		}

		public virtual void ManagedTick()
		{
			PlayerInput input = AgentOwner.GetInput();
			Player playerChar = Player.PlayerChar;
			Motion(input.Move, input.Look, playerChar.PerformingAttack(), playerChar.PerformingCast());
		}

		public virtual void Motion(Vector3 moveDirInput, Vector3 lookDirInput, bool attacking, bool casting)
		{
			if (!AgentOwner.Vitals.IsDead)
			{
				_ = moveDirInput * AgentOwner.Definition.MoveSpeed * Time.deltaTime + MoveAffectorSingleFrame + PushVector;
				if (!AgentOwner.GetDenialState().DenyRotate)
				{
					Vector3 vector = base.transform.position + lookDirInput;
					UnityEngine.Debug.Log($"ROTATIONTEST {vector}");
					vector.y = base.transform.position.y;
				}
				if (PushVector.magnitude < 0.1f)
				{
					IsBeingPushed = false;
					PushVector = Vector3.zero;
				}
				else
				{
					PushVector = Vector3.Lerp(PushVector, Vector3.zero, Time.deltaTime * 5f);
				}
				MoveAffectorSingleFrame = Vector3.zero;
			}
		}

		protected virtual void OnAnimatorMove()
		{
			if (!(AgentOwner.Animator == null))
			{
				Vector3 vector = (AgentOwner.GetDenialState().DenyMove ? Vector3.zero : base.transform.InverseTransformDirection(AgentOwner.GetInput().Move).normalized);
				Vector3 vector2 = (AgentOwner.GetDenialState().DenyRotate ? base.transform.forward : base.transform.InverseTransformDirection(AgentOwner.GetInput().Look).normalized);
				AgentOwner.Animator.SetBool(GameSettings.Instance.AnimParamIsMoving, Math.Abs(vector.x) > 0.01f || Math.Abs(vector.z) > 0.01f);
				AgentOwner.Animator.SetFloat(GameSettings.Instance.AnimParamMoveX, vector.x);
				AgentOwner.Animator.SetFloat(GameSettings.Instance.AnimParamMoveZ, vector.z);
				AgentOwner.Animator.SetFloat(GameSettings.Instance.AnimParamMoveAngle, Mathf.Atan2(vector.x, vector.z) * 57.29578f);
				AgentOwner.Animator.SetFloat(GameSettings.Instance.AnimParamLookH, Mathf.Atan2(vector2.x, vector2.z) * 57.29578f);
				AgentOwner.Animator.SetFloat(GameSettings.Instance.AnimParamLookV, Mathf.Atan2(vector2.y, vector2.z) * 57.29578f);
				AgentOwner.Animator.SetFloat(GameSettings.Instance.AnimParamSpeedMove, 1f);
				AgentOwner.Animator.SetFloat(GameSettings.Instance.AnimParamSpeedLook, 1f);
				AgentOwner.Animator.SetFloat(GameSettings.Instance.AnimParamSpeedAttack, 1f);
			}
		}

		public virtual void Push(Vector3 directionVector)
		{
			IsBeingPushed = true;
			PushVector += directionVector / (AgentOwner.Definition.WeightKg * 0.2f);
		}

		public virtual void Teleport(Vector3 targetWorldPosition)
		{
			base.transform.position = targetWorldPosition;
		}

		public virtual void ApplySingleFrameVelocity(Vector3 velocity)
		{
			MoveAffectorSingleFrame += velocity;
		}

		public virtual void AnimFootDown()
		{
			if (!(AgentOwner.AudioPlayer == null) && !(Time.time < m_nextStepTime))
			{
				m_nextStepTime = Time.time + 0.1f;
				AgentOwner.AudioPlayer.PlayOneShot(AgentOwner.Definition.FeetSounds.Any());
			}
		}
	}
	public interface IAgentLocomotion
	{
		void Motion(Vector3 move, Vector3 look, bool attacking, bool casting);

		void Push(Vector3 directionVector);

		void Teleport(Vector3 targetWorldPosition);
	}
	[AddComponentMenu("Cleverous/Prodigy/Agent/Prodigy Agent Locomotion")]
	public class ProdigyAgentLocomotion : AgentLocomotionBase
	{
		public NavMeshAgent navMeshAgent;

		public bool UseOnlyBaseClassMotion;

		public bool LookForwardAlways = true;

		private float characterMovespeedModifier = 1f;

		private Character character;

		private float currentSpeed;

		private Vector3 lastMoveInput = Vector3.zero;

		private float lastMoveMagnitude;

		public bool IsMoving
		{
			get
			{
				if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior != InputBroker.InputBehavior.ClickToMove)
				{
					return lastMoveInput.magnitude > 0.01f;
				}
				if (!navMeshAgent.hasPath)
				{
					return navMeshAgent.pathPending;
				}
				return true;
			}
		}

		private void Awake()
		{
			character = GetComponent<Character>();
		}

		public override void Motion(Vector3 moveDirInput, Vector3 lookDirInput, bool attacking, bool casting)
		{
			lastMoveInput = moveDirInput;
			lastMoveMagnitude = moveDirInput.magnitude;
			if (UseOnlyBaseClassMotion)
			{
				base.Motion(moveDirInput, lookDirInput, attacking, casting);
			}
			else
			{
				if (AgentOwner.Vitals.IsDead)
				{
					return;
				}
				currentSpeed = AgentOwner.Definition.MoveSpeed;
				if (character != null)
				{
					if (character.HasEffect(EffectType.PercentSpeed))
					{
						float num = character.EffectValue(EffectType.PercentSpeed) / 100f;
						currentSpeed += currentSpeed * num;
					}
					bool flag = character.Running();
					characterMovespeedModifier = (flag ? 1f : AgentOwner.Definition.WalkMultiplier);
					currentSpeed *= characterMovespeedModifier;
					if (currentSpeed < 0f)
					{
						currentSpeed = 0f;
					}
				}
				Vector3 vector = MoveAffectorSingleFrame + PushVector;
				if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove)
				{
					navMeshAgent.speed = currentSpeed;
				}
				else if (!AgentOwner.GetDenialState().DenyMove)
				{
					vector += moveDirInput * currentSpeed;
				}
				if (vector.magnitude > 0.01f)
				{
					navMeshAgent.Move(vector * Time.deltaTime);
				}
				if (AgentOwner.GetDenialState().DenyMove && !AgentOwner.Vitals.IsDead && (navMeshAgent.hasPath || navMeshAgent.pathPending))
				{
					navMeshAgent.isStopped = true;
				}
				if (!AgentOwner.GetDenialState().DenyRotate && !casting)
				{
					if (LookForwardAlways && (!attacking || SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free))
					{
						if (moveDirInput.magnitude > 0.025f)
						{
							Vector3 targetPosition = base.transform.position + moveDirInput;
							targetPosition.y = base.transform.position.y;
							Player.PlayerChar.TurnTowardPosition(targetPosition);
						}
					}
					else if (lookDirInput.magnitude > 0.025f)
					{
						Vector3 targetPosition2 = base.transform.position + lookDirInput;
						targetPosition2.y = base.transform.position.y;
						Player.PlayerChar.TurnTowardPosition(targetPosition2);
					}
				}
				if (PushVector.magnitude < 0.1f)
				{
					IsBeingPushed = false;
					PushVector = Vector3.zero;
				}
				else
				{
					PushVector = Vector3.Lerp(PushVector, Vector3.zero, Time.deltaTime * 5f);
				}
				MoveAffectorSingleFrame = Vector3.zero;
			}
		}

		public float GetMoveSpeedMultiplier()
		{
			if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free)
			{
				float num = (character.InRunningState() ? 1f : AgentOwner.Definition.WalkMultiplier);
				return AgentOwner.GetInput().Move.magnitude * num;
			}
			if (!navMeshAgent.hasPath)
			{
				return 0f;
			}
			return Mathf.Clamp01(navMeshAgent.desiredVelocity.magnitude / AgentOwner.Definition.MoveSpeed);
		}

		protected override void OnAnimatorMove()
		{
			base.OnAnimatorMove();
			AgentOwner.Animator.SetFloat(GameSettings.Instance.AnimParamMoveMag, GetMoveSpeedMultiplier());
		}
	}
	[AddComponentMenu("Cleverous/Prodigy/Agent/Prodigy Agent")]
	public class ProdigyAgent : Tickable, IAgent, IUseLocomotion
	{
		public enum Team
		{
			Players,
			Enemies
		}

		[AssetDropdown(typeof(ProdigyAgentDefinition))]
		public ProdigyAgentDefinition Definition;

		[Header("Agent Behaviors")]
		[SerializeField]
		private AgentLocomotionBase m_locomotion;

		[SerializeField]
		private CharacterVitals m_vitals;

		[SerializeField]
		private AgentEquipment m_equipment;

		[SerializeField]
		private Animator m_animator;

		[SerializeField]
		private Collider m_collider;

		public AudioSource AudioPlayer;

		protected List<RuntimeDenial> DenialList;

		private uint m_ownerPlayerNetworkId;

		private ProdigyPlayer m_player;

		private List<AgentTransformState> m_clientStateHistory;

		private List<AgentTransformState> m_serverStateHistory;

		private ParticleSystem levelupFX;

		private float m_timeSpentOutsideOfErrorTolerance;

		public Transform MyTransform
		{
			get
			{
				if (!(base.transform == null))
				{
					return base.transform;
				}
				return null;
			}
		}

		public AgentLocomotionBase Locomotion => m_locomotion;

		public AttributeSet Attributes => m_vitals.Char.attributes;

		public CharacterVitals Vitals => m_vitals;

		public Animator Animator => m_animator;

		public Collider Collider => m_collider;

		public Alignment Alignment => Vitals.Alignment;

		public RuntimeDenial DenialState { get; protected set; }

		private void OnDrawGizmos()
		{
			if (Application.isPlaying)
			{
				UnityEngine.Debug.DrawRay(base.transform.position, GetInput().Look, Color.cyan);
				UnityEngine.Debug.DrawRay(base.transform.position, GetInput().Move, Color.blue);
			}
		}

		protected virtual void Reset()
		{
			m_locomotion = GetComponent<AgentLocomotionBase>();
			m_vitals = GetComponent<CharacterVitals>();
			m_equipment = GetComponent<AgentEquipment>();
			m_animator = GetComponent<Animator>();
			m_collider = GetComponent<Collider>();
		}

		private void Awake()
		{
			DenialState = new RuntimeDenial(move: false, rotate: false, fire: false, ability: false, ik: false);
			DenialList = new List<RuntimeDenial>();
			if (m_equipment == null)
			{
				m_equipment = GetComponent<AgentEquipment>();
			}
			m_clientStateHistory = new List<AgentTransformState>();
			m_serverStateHistory = new List<AgentTransformState>();
			Animator.updateMode = AnimatorUpdateMode.AnimatePhysics;
			CharacterVitals vitals = Vitals;
			vitals.OnLevelUp = (Action<int>)Delegate.Combine(vitals.OnLevelUp, new Action<int>(OnLevelUp));
		}

		public override void OnStartClient()
		{
			base.OnStartClient();
			if (m_player == null)
			{
				m_player = Game.GetPlayer(m_ownerPlayerNetworkId);
			}
			if (Definition.SpawnEffect != null)
			{
				UnityEngine.Object.Instantiate(Definition.SpawnEffect, base.transform.position, Quaternion.identity);
			}
		}

		public override void OnStartServer()
		{
			base.OnStartServer();
		}

		public override void GameTick()
		{
			if (!Vitals.IsDead)
			{
				DenialTickProcessing();
				m_locomotion?.ManagedTick();
				m_equipment.ManagedTick();
				AgentTransformState item = new AgentTransformState(base.transform.position, base.transform.rotation, Game.Tick);
				m_clientStateHistory.Add(item);
				if (m_clientStateHistory.Count > 30)
				{
					m_clientStateHistory.RemoveAt(0);
				}
				if (m_serverStateHistory.Count > 30)
				{
					m_serverStateHistory.RemoveAt(0);
				}
			}
		}

		protected virtual void DenialTickProcessing()
		{
			DenialState.DenyMove = false;
			DenialState.DenyRotate = false;
			DenialState.DenyAbility = false;
			DenialState.DenyFire = false;
			DenialState.DenyIk = false;
			foreach (RuntimeDenial denial in DenialList)
			{
				DenialState.DenyMove = DenialState.DenyMove || denial.DenyMove;
				DenialState.DenyRotate = DenialState.DenyRotate || denial.DenyRotate;
				DenialState.DenyAbility = DenialState.DenyAbility || denial.DenyAbility;
				DenialState.DenyFire = DenialState.DenyFire || denial.DenyFire;
				DenialState.DenyIk = DenialState.DenyIk || denial.DenyIk;
			}
		}

		protected virtual void CmdSendStateToServer(AgentTransformState state)
		{
			m_clientStateHistory.Add(state);
		}

		protected virtual void RpcStateToClients(AgentTransformState state)
		{
			m_serverStateHistory.Add(state);
		}

		protected virtual void RpcForceTransformCorrection(AgentTransformState state)
		{
			LocalForceTransformPosition(state.Position);
		}

		protected virtual void LocalForceTransformPosition(Vector3 pos)
		{
			base.transform.position = pos;
		}

		public void SetOwnerPlayerId(uint id)
		{
			m_ownerPlayerNetworkId = id;
		}

		public virtual PlayerInput GetInput()
		{
			if (!(m_player == null))
			{
				return m_player.GetCurrentInput();
			}
			return default(PlayerInput);
		}

		public virtual RuntimeDenial GetDenialState()
		{
			return DenialState;
		}

		public virtual bool RemoveDenialById(int id)
		{
			for (int i = 0; i < DenialList.Count; i++)
			{
				if (DenialList[i].Id == id)
				{
					DenialList.RemoveAt(i);
					return true;
				}
			}
			return false;
		}

		public virtual int AddDenial(RuntimeDenial d)
		{
			DenialList.Add(d);
			return d.Id;
		}

		protected virtual void OnLevelUp(int level)
		{
			if (level > 1)
			{
				if (levelupFX != null)
				{
					levelupFX = UnityEngine.Object.Instantiate(GameSettings.Instance.LevelUpFxTemplate, base.transform.position, base.transform.rotation, base.transform).GetComponent<ParticleSystem>();
				}
				levelupFX.Play();
			}
		}
	}
	public class RuntimeDenial
	{
		protected static int IdIndex;

		public bool DenyMove;

		public bool DenyRotate;

		public bool DenyFire;

		public bool DenyAbility;

		public bool DenyIk;

		public int Id { get; protected set; }

		public RuntimeDenial(bool move, bool rotate, bool fire, bool ability, bool ik)
		{
			Id = IdIndex++;
			DenyMove = move;
			DenyRotate = rotate;
			DenyFire = fire;
			DenyAbility = ability;
			DenyIk = ik;
		}

		public override bool Equals(object other)
		{
			DenialAction denialAction = other as DenialAction;
			if (denialAction != null)
			{
				return Id == denialAction.GetId();
			}
			return false;
		}

		public override int GetHashCode()
		{
			return base.GetHashCode();
		}
	}
	public class AnimatorOperation : DataEntity
	{
		public enum ParamTypes
		{
			Bool,
			Float,
			Int,
			Trigger
		}

		[Header("[ANIMATOR OP]")]
		public ParamTypes ParamTarget;

		public string ParamName;

		public bool ParamBool;

		public float ParamFloat;

		public int ParamInt;

		public AnimatorOperation(string paramName, bool boolVal)
		{
			ParamName = paramName;
			ParamBool = boolVal;
		}

		public AnimatorOperation(string paramName, float floatVal)
		{
			ParamName = paramName;
			ParamFloat = floatVal;
		}

		public AnimatorOperation(string paramName, int intVal)
		{
			ParamName = paramName;
			ParamInt = intVal;
		}

		public AnimatorOperation(string triggerName)
		{
			ParamName = triggerName;
		}

		protected override void Reset()
		{
			base.Reset();
			ParamTarget = ParamTypes.Bool;
			ParamName = "None";
			ParamBool = false;
			ParamFloat = 0f;
			ParamInt = 0;
		}

		public void Execute(Animator target)
		{
			switch (ParamTarget)
			{
			case ParamTypes.Bool:
				target.SetBool(ParamName, ParamBool);
				break;
			case ParamTypes.Float:
				target.SetFloat(ParamName, ParamFloat);
				break;
			case ParamTypes.Int:
				target.SetInteger(ParamName, ParamInt);
				break;
			case ParamTypes.Trigger:
				target.SetTrigger(ParamName);
				break;
			default:
				throw new ArgumentOutOfRangeException();
			}
		}
	}
	public class DenialAction : DataEntity
	{
		private static int m_index;

		[Header("[DENIAL ACTION]")]
		[Tooltip("Deny movement inputs.")]
		public bool DenyMove;

		[Tooltip("Deny rotation inputs.")]
		public bool DenyRotate;

		[Tooltip("Deny firing inputs.")]
		public bool DenyFire;

		[Tooltip("Deny firing inputs.")]
		public bool DenyAbility;

		[Tooltip("Deny IK from weighting over the animations.")]
		public bool DenyIk;

		[Tooltip("How long it should deny these parameters.")]
		public float DenialTime;

		private readonly int m_id;

		private static int NextId => m_index++;

		protected override void Reset()
		{
			base.Reset();
			DenyMove = false;
			DenyRotate = false;
			DenyFire = false;
			DenyAbility = false;
			DenyIk = false;
			DenialTime = 0f;
		}

		public DenialAction(bool move, bool rotate, bool fire, bool ability, bool ik, float time)
		{
			m_id = NextId;
			DenyMove = move;
			DenyRotate = rotate;
			DenyFire = fire;
			DenyAbility = ability;
			DenyIk = ik;
			DenialTime = time;
		}

		public int GetId()
		{
			return m_id;
		}

		public override bool Equals(object other)
		{
			DenialAction denialAction = other as DenialAction;
			if (denialAction != null)
			{
				return m_id == denialAction.GetId();
			}
			return false;
		}

		public override int GetHashCode()
		{
			return base.GetHashCode();
		}
	}
