	[AddComponentMenu("Cleverous/Prodigy/Agent/Death Handler")]
	public class AgentDeathHandler : MonoBehaviour
	{
		[Header("References")]
		public ProdigyAgent AgentOwner;

		public NavMeshAgent NavAgent;

		[Header("...When Death Occurs")]
		public bool DestroyGameObject;

		public int DestroyAfterSeconds;

		public bool DisableAnimator;

		public bool DisableNavAgent;

		public bool ExectueOperation;

		[AssetDropdown(typeof(AnimatorOperation))]
		public AnimatorOperation DeathAnimOp;

		[Header("Layers")]
		public bool SetCorpseLayer;

		public bool SetLayerOnBodies;

		[Header("Ragdoll")]
		public bool RagdollActivate;

		public float ImpactForceMultiplier = 1f;

		public Rigidbody[] RagdollBodies;

		public Collider[] RagdollColliders;

		private CharacterVitals.Damage m_final;

		private bool m_isDead;

		private float m_deadTimer;

		protected virtual void Reset()
		{
			AgentOwner = GetComponent<ProdigyAgent>();
			DisableAnimator = true;
			ExectueOperation = false;
			DeathAnimOp = null;
			SetCorpseLayer = true;
			SetLayerOnBodies = true;
		}

		protected virtual void Awake()
		{
			m_isDead = false;
			m_deadTimer = 0f;
			if (AgentOwner.Vitals != null)
			{
				CharacterVitals vitals = AgentOwner.Vitals;
				vitals.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Combine(vitals.OnKilled, new Action<CharacterVitals.Damage>(AgentKilled));
			}
		}

		protected virtual void Update()
		{
			if (m_isDead && DestroyGameObject)
			{
				m_deadTimer += Time.deltaTime;
				if (m_deadTimer > (float)DestroyAfterSeconds)
				{
					UnityEngine.Object.Destroy(base.gameObject);
				}
			}
		}

		protected virtual void AgentKilled(CharacterVitals.Damage finalData)
		{
			m_isDead = true;
			m_final = finalData;
			if (AgentOwner.Vitals.IsDead)
			{
				if (DisableAnimator)
				{
					AgentOwner.Animator.enabled = false;
				}
				if (DisableNavAgent && NavAgent != null)
				{
					NavAgent.enabled = false;
				}
				if (ExectueOperation)
				{
					DeathAnimOp?.Execute(AgentOwner.Animator);
				}
				if (SetCorpseLayer)
				{
					base.gameObject.layer = GameSettings.Instance.CorpseLayer;
				}
				if (SetLayerOnBodies)
				{
					LayerSetDeep();
				}
				if (RagdollActivate)
				{
					LocalRagdoll();
				}
			}
		}

		protected virtual void LayerSetDeep()
		{
			Collider[] ragdollColliders = RagdollColliders;
			for (int i = 0; i < ragdollColliders.Length; i++)
			{
				ragdollColliders[i].gameObject.layer = GameSettings.Instance.CorpseLayer;
			}
		}

		protected virtual void LocalRagdoll()
		{
			if (!(m_final.source != null))
			{
				for (int i = 0; i < RagdollBodies.Length; i++)
				{
					RagdollColliders[i].enabled = true;
					RagdollBodies[i].isKinematic = false;
					RagdollBodies[i].useGravity = true;
				}
				return;
			}
			for (int j = 0; j < RagdollBodies.Length; j++)
			{
				RagdollBodies[j].velocity = Vector3.zero;
				RagdollColliders[j].enabled = true;
				RagdollBodies[j].isKinematic = false;
				RagdollBodies[j].useGravity = true;
			}
		}
	}
	public class AgentSpawner : MonoBehaviour
	{
		public int Radius;

		public float SpawnDelay;

		public AudioSource AudioPlayer;

		public AudioClip StartWaveSound;

		public List<Transform> SpawnLocations;

		public SpawnDefinition[] Waves;

		public static int WaveId;

		public static float WaveTimer;

		public Action OnEnemyElimination;

		public Action OnEnemySpawned;

		public Action OnWaveStarted;

		[HideInInspector]
		public bool IsManaged;

		private WaitForSeconds m_spawnEachDelay;

		private int m_elims;

		private int m_spawned;

		private void OnDrawGizmosSelected()
		{
			if (SpawnLocations == null)
			{
				Gizmos.DrawWireSphere(base.transform.position, Radius);
				return;
			}
			foreach (Transform spawnLocation in SpawnLocations)
			{
				Gizmos.DrawWireSphere(spawnLocation.position, Radius);
			}
		}

		protected virtual void Reset()
		{
			Waves = new SpawnDefinition[1];
			Radius = 5;
			SpawnDelay = 0.2f;
		}

		protected virtual void Awake()
		{
			if (SpawnLocations == null)
			{
				SpawnLocations = new List<Transform> { base.transform };
			}
			m_spawnEachDelay = new WaitForSeconds(SpawnDelay);
			WaveId = 0;
		}

		protected virtual void Update()
		{
			if (!IsManaged)
			{
				WaveTimer -= Time.deltaTime;
				if (WaveId > Waves.Length - 1)
				{
					WaveId = 0;
				}
				if (WaveTimer <= 0f)
				{
					PerformNextSequence();
				}
			}
		}

		protected virtual void OnSpawn()
		{
			m_spawned++;
			OnEnemySpawned?.Invoke();
		}

		protected virtual void OnElimination(CharacterVitals.Damage d)
		{
			m_elims++;
			OnEnemyElimination?.Invoke();
		}

		public virtual void PerformNextSequence()
		{
			StartCoroutine(NextSequence());
		}

		protected IEnumerator NextSequence()
		{
			WaveTimer = Waves[WaveId].Time;
			if (StartWaveSound != null && AudioPlayer != null)
			{
				AudioPlayer.clip = StartWaveSound;
				AudioPlayer.Play();
			}
			foreach (Transform spawnPoint in SpawnLocations)
			{
				if (WaveId > Waves.Length - 1)
				{
					yield break;
				}
				for (int i = 0; i < Waves[WaveId].Count; i++)
				{
					Vector2 vector = UnityEngine.Random.insideUnitCircle * Radius;
					if (!NavMesh.SamplePosition(spawnPoint.position + new Vector3(vector.x, spawnPoint.position.y, vector.y), out var hit, Radius, -1))
					{
						UnityEngine.Debug.LogWarning($"Failed to spawn an Agent on wave {WaveId}.", this);
						yield return null;
					}
					ProdigyAgent component = UnityEngine.Object.Instantiate(Waves[WaveId].Spawn.AgentPrefab, hit.position, Quaternion.identity).GetComponent<ProdigyAgent>();
					if (component != null)
					{
						CharacterVitals vitals = component.Vitals;
						vitals.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Combine(vitals.OnKilled, new Action<CharacterVitals.Damage>(OnElimination));
					}
					OnSpawn();
					yield return m_spawnEachDelay;
					hit = default(NavMeshHit);
				}
			}
			OnWaveStarted?.Invoke();
			WaveId++;
		}

		public int GetTotalEliminations()
		{
			return m_elims;
		}

		public int GetTotalSpawned()
		{
			return m_spawned;
		}
	}
