	public class AgentSpawnerEndless : MonoBehaviour
	{
		public int Radius;

		public float SpawnDelay;

		[AssetDropdown(typeof(ProdigyAgentDefinition))]
		public ProdigyAgentDefinition Spawn;

		public int Count;

		protected int Eliminations;

		private WaitForSeconds m_delay;

		protected virtual void OnDrawGizmos()
		{
			Gizmos.color = Color.cyan;
			Gizmos.DrawWireSphere(base.transform.position, Radius);
		}

		protected virtual void Reset()
		{
			Radius = 5;
			SpawnDelay = 0.2f;
		}

		protected virtual void Awake()
		{
			m_delay = new WaitForSeconds(SpawnDelay);
		}

		protected virtual void Start()
		{
			PerformSequence();
		}

		protected virtual void Update()
		{
			if (Eliminations >= Count)
			{
				PerformSequence();
			}
		}

		protected virtual void OnElimination(CharacterVitals.Damage d)
		{
			Eliminations++;
		}

		public virtual void PerformSequence()
		{
			StartCoroutine(NextSequence());
		}

		protected IEnumerator NextSequence()
		{
			Eliminations = 0;
			for (int i = 0; i < Count; i++)
			{
				Vector2 vector = UnityEngine.Random.insideUnitCircle * Radius;
				if (!NavMesh.SamplePosition(base.transform.position + new Vector3(vector.x, base.transform.position.y, vector.y), out var hit, Radius, -1))
				{
					yield return null;
				}
				ProdigyAgent component = UnityEngine.Object.Instantiate(Spawn.AgentPrefab, hit.position, Quaternion.identity).GetComponent<ProdigyAgent>();
				if (component != null)
				{
					CharacterVitals vitals = component.Vitals;
					vitals.OnKilled = (Action<CharacterVitals.Damage>)Delegate.Combine(vitals.OnKilled, new Action<CharacterVitals.Damage>(OnElimination));
				}
				yield return m_delay;
				hit = default(NavMeshHit);
			}
		}
	}
