	public static class DebugDraw
	{
		public static void DrawMarker(Vector3 position, float size, Color color, float duration, bool depthTest = true)
		{
			Vector3 start = position + Vector3.up * size * 0.5f;
			Vector3 end = position - Vector3.up * size * 0.5f;
			Vector3 start2 = position + Vector3.right * size * 0.5f;
			Vector3 end2 = position - Vector3.right * size * 0.5f;
			Vector3 start3 = position + Vector3.forward * size * 0.5f;
			Vector3 end3 = position - Vector3.forward * size * 0.5f;
			UnityEngine.Debug.DrawLine(start, end, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(start2, end2, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(start3, end3, color, duration, depthTest);
		}

		public static void DrawPlane(Vector3 position, Vector3 normal, float size, Color color, float duration, bool depthTest = true)
		{
			Vector3 vector = ((!(normal.normalized != Vector3.forward)) ? (Vector3.Cross(normal, Vector3.up).normalized * normal.magnitude) : (Vector3.Cross(normal, Vector3.forward).normalized * normal.magnitude));
			Vector3 vector2 = position + vector * size;
			Vector3 vector3 = position - vector * size;
			vector = Quaternion.AngleAxis(90f, normal) * vector;
			Vector3 vector4 = position + vector * size;
			Vector3 vector5 = position - vector * size;
			UnityEngine.Debug.DrawLine(vector2, vector3, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(vector4, vector5, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(vector2, vector4, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(vector4, vector3, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(vector3, vector5, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(vector5, vector2, color, duration, depthTest);
			UnityEngine.Debug.DrawRay(position, normal * size, color, duration, depthTest);
		}

		public static void DrawVector(Vector3 position, Vector3 direction, float raySize, float markerSize, Color color, float duration, bool depthTest = true)
		{
			UnityEngine.Debug.DrawRay(position, direction * raySize, color, duration, depthTest: false);
			DrawMarker(position + direction * raySize, markerSize, color, duration, depthTest: false);
		}

		public static void DrawTriangle(Vector3 a, Vector3 b, Vector3 c, Color color, float duration)
		{
			UnityEngine.Debug.DrawLine(a, b, color, duration);
			UnityEngine.Debug.DrawLine(b, c, color, duration);
			UnityEngine.Debug.DrawLine(c, a, color, duration);
		}

		public static void DrawTriangle(Vector3 a, Vector3 b, Vector3 c, Color color, Transform t, float duration = 0f)
		{
			a = t.TransformPoint(a);
			b = t.TransformPoint(b);
			c = t.TransformPoint(c);
			UnityEngine.Debug.DrawLine(a, b, color, duration);
			UnityEngine.Debug.DrawLine(b, c, color, duration);
			UnityEngine.Debug.DrawLine(c, a, color, duration);
		}

		public static void DrawMesh(Mesh mesh, Color color, Transform t, float duration = 0f)
		{
			for (int i = 0; i < mesh.triangles.Length; i += 3)
			{
				DrawTriangle(mesh.vertices[mesh.triangles[i]], mesh.vertices[mesh.triangles[i + 1]], mesh.vertices[mesh.triangles[i + 2]], color, t, duration);
			}
		}

		public static Color RandomColor()
		{
			return new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value);
		}
	}
	public class DebugExtras
	{
		public static void DrawCircle(Vector3 pos, Vector3 upDir, float radius, Color color, float duration = 0f)
		{
			Vector3 vector = upDir.normalized * radius;
			Vector3 rhs = Vector3.Slerp(vector, -vector, 0.5f);
			Vector3 vector2 = Vector3.Cross(vector, rhs).normalized * radius;
			Matrix4x4 matrix4x = default(Matrix4x4);
			matrix4x[0] = vector2.x;
			matrix4x[1] = vector2.y;
			matrix4x[2] = vector2.z;
			matrix4x[4] = vector.x;
			matrix4x[5] = vector.y;
			matrix4x[6] = vector.z;
			matrix4x[8] = rhs.x;
			matrix4x[9] = rhs.y;
			matrix4x[10] = rhs.z;
			Matrix4x4 matrix4x2 = matrix4x;
			Vector3 start = pos + matrix4x2.MultiplyPoint3x4(new Vector3(Mathf.Cos(0f), 0f, Mathf.Sin(0f)));
			Vector3 vector3 = Vector3.zero;
			for (int i = 0; i < 91; i++)
			{
				vector3.x = Mathf.Cos((float)(i * 4) * (MathF.PI / 180f));
				vector3.z = Mathf.Sin((float)(i * 4) * (MathF.PI / 180f));
				vector3.y = 0f;
				vector3 = pos + matrix4x2.MultiplyPoint3x4(vector3);
				UnityEngine.Debug.DrawLine(start, vector3, color, duration);
				start = vector3;
			}
		}

		public static void DrawArc2D(Vector3 center, Vector3 direction, float radius, float angleRange, Color color, int segments = 12, float duration = 0f)
		{
			Vector3 vector = Quaternion.AngleAxis(0f - angleRange / 2f, Vector3.up) * direction;
			float num = Mathf.Sign(Vector3.Dot(vector, Vector3.right)) * Vector3.Angle(vector, Vector3.forward);
			Vector3 start = new Vector3(center.x + Mathf.Sin(MathF.PI / 180f * num) * radius, center.y, center.z + Mathf.Cos(MathF.PI / 180f * num) * radius);
			float num2 = num;
			for (int i = 0; i <= segments; i++)
			{
				Vector3 vector2 = new Vector3(center.x + Mathf.Sin(MathF.PI / 180f * num2) * radius, center.y, center.z + Mathf.Cos(MathF.PI / 180f * num2) * radius);
				UnityEngine.Debug.DrawLine(start, vector2, color, duration);
				start = vector2;
				num2 += angleRange / (float)segments;
			}
		}

		private static Vector3 GetPointOnBezierCurve(Vector3 p0, Vector3 p1, Vector3 p2, Vector3 p3, float t)
		{
			float num = 1f - t;
			float num2 = t * t;
			float num3 = num * num;
			float num4 = num3 * num;
			float num5 = num2 * t;
			return num4 * p0 + 3f * num3 * t * p1 + 3f * num * num2 * p2 + num5 * p3;
		}
	}
	public static class RuntimeDebug
	{
		public class DebugCircle : MonoBehaviour
		{
			public float LifeTime = 5f;

			public Vector3 Center = Vector3.zero;

			public float Radius = 5f;

			public Color Hue = Color.red;

			public Vector3 Forward = Vector3.forward;

			public float AngleFov = 360f;

			public float Quality = 32f;

			public void Update()
			{
				LifeTime -= Time.deltaTime;
				if (LifeTime < 0f)
				{
					UnityEngine.Object.Destroy(base.gameObject);
				}
			}

			public void OnDrawGizmos()
			{
				DrawCircle(Center, Radius, Hue, AngleFov, Forward, Quality);
			}
		}

		private static Material m_mat;

		private static void Validate()
		{
			if (!(m_mat != null))
			{
				m_mat = new Material(Shader.Find("Hidden/Internal-Colored"))
				{
					hideFlags = HideFlags.HideAndDontSave
				};
				m_mat.SetInt("_SrcBlend", 5);
				m_mat.SetInt("_DstBlend", 10);
				m_mat.SetInt("_Cull", 0);
				m_mat.SetInt("_ZWrite", 0);
			}
		}

		public static void DrawLine(Vector3 start, Vector3 end, Color color)
		{
			Validate();
			GL.Begin(1);
			m_mat.SetPass(0);
			GL.Color(color);
			Vector3 vector = start;
			Vector3 vector2 = end;
			GL.Vertex3(vector.x, vector.y, vector.z);
			GL.Vertex3(vector2.x, vector2.y, vector2.z);
			GL.End();
		}

		public static void DrawRay(Vector3 start, Vector3 direction, Color color)
		{
			DrawLine(start, start + direction, color);
		}

		public static void DrawCapsuleOutline(CapsuleCollider capsule, Color color)
		{
			Validate();
			GL.Begin(1);
			m_mat.SetPass(0);
			GL.Color(color);
			Vector3 vector = capsule.transform.position + capsule.center;
			Vector3[] array = new Vector3[4]
			{
				new Vector3(vector.x - capsule.radius, vector.y - capsule.height / 2f, vector.z),
				new Vector3(vector.x - capsule.radius, vector.y + capsule.height / 2f, vector.z),
				new Vector3(vector.x + capsule.radius, vector.y + capsule.height / 2f, vector.z),
				new Vector3(vector.x + capsule.radius, vector.y - capsule.height / 2f, vector.z)
			};
			GL.Vertex3(array[0].x, array[0].y, array[0].z);
			GL.Vertex3(array[1].x, array[1].y, array[1].z);
			GL.Vertex3(array[1].x, array[1].y, array[1].z);
			GL.Vertex3(array[2].x, array[2].y, array[2].z);
			GL.Vertex3(array[2].x, array[2].y, array[2].z);
			GL.Vertex3(array[3].x, array[3].y, array[3].z);
			GL.Vertex3(array[3].x, array[3].y, array[3].z);
			GL.Vertex3(array[0].x, array[0].y, array[0].z);
			GL.End();
		}

		public static void DrawCircle(Vector3 center, float radius, Color color, float angleFov = 360f, Vector3 forward = default(Vector3), float quality = 16f)
		{
			Validate();
			GL.PushMatrix();
			m_mat.SetPass(0);
			GL.Begin(1);
			GL.Color(color);
			float num = Mathf.Atan2(forward.z, forward.x);
			float num2 = num - angleFov / 2f * (MathF.PI / 180f);
			float num3 = num + angleFov / 2f * (MathF.PI / 180f);
			float num4 = (num3 - num2) / quality;
			int num5 = 0;
			for (float num6 = num2; num6 < num3; num6 += num4)
			{
				Vector3 vector = new Vector3(Mathf.Cos(num6) * radius + center.x, Mathf.Sin(num6) * radius + center.z, center.y);
				if (num5 > 0)
				{
					GL.Vertex3(vector.x, vector.z, vector.y);
				}
				GL.Vertex3(vector.x, vector.z, vector.y);
				num5++;
				if (num5 > 1000)
				{
					UnityEngine.Debug.LogError("Something wrong with inputs for the debug circle caused excessive looping.");
					break;
				}
			}
			GL.End();
			GL.PopMatrix();
		}

		public static void DrawFovCone(Vector3 center, float radius, Color color, float angleFov = 360f, Vector3 forward = default(Vector3), float quality = 16f)
		{
			DrawCircle(center, radius, color, angleFov, forward, quality);
			DrawCircle(center, 0.2f, color, angleFov, forward, quality);
			m_mat.SetPass(0);
			GL.Begin(1);
			GL.Color(color);
			float num = Mathf.Atan2(forward.z, forward.x);
			float f = num - angleFov / 2f * (MathF.PI / 180f);
			float f2 = num + angleFov / 2f * (MathF.PI / 180f);
			Vector3 vector = new Vector3(Mathf.Cos(f) * radius + center.x, Mathf.Sin(f) * radius + center.z, center.y);
			GL.Vertex3(vector.x, vector.z, vector.y);
			Vector3 vector2 = new Vector3(Mathf.Cos(f) * 0.2f + center.x, Mathf.Sin(f) * 0.2f + center.z, center.y);
			GL.Vertex3(vector2.x, vector2.z, vector2.y);
			GL.End();
			GL.Begin(1);
			GL.Color(color);
			Vector3 vector3 = new Vector3(Mathf.Cos(f2) * radius + center.x, Mathf.Sin(f2) * radius + center.z, center.y);
			GL.Vertex3(vector3.x, vector3.z, vector3.y);
			Vector3 vector4 = new Vector3(Mathf.Cos(f2) * 0.2f + center.x, Mathf.Sin(f2) * 0.2f + center.z, center.y);
			GL.Vertex3(vector4.x, vector4.z, vector4.y);
			GL.End();
		}

		public static DebugCircle CreateCircle(Vector3 center, float radius, Color color, float time, float angleFov = 360f, Vector3 forward = default(Vector3), float quality = 32f)
		{
			DebugCircle debugCircle = new GameObject("DebugCircle").AddComponent<DebugCircle>();
			debugCircle.LifeTime = time;
			debugCircle.Radius = radius;
			debugCircle.Center = center;
			debugCircle.AngleFov = angleFov;
			debugCircle.Forward = forward;
			debugCircle.Quality = quality;
			return debugCircle;
		}
	}
	[AddComponentMenu("Cleverous/Prodigy/Utility/Camera Fade")]
	public class FadeCamera : MonoBehaviour
	{
		public AnimationCurve FadeCurve = new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(0.6f, 0.7f, -1.8f, -1.2f), new Keyframe(1f, 0f));

		private float m_alpha;

		private Texture2D m_texture;

		private bool m_done;

		private float m_time;

		private void OnDestroy()
		{
			if (m_texture != null)
			{
				UnityEngine.Object.Destroy(m_texture);
			}
		}

		public void Reset()
		{
			m_done = false;
			m_alpha = 1f;
			m_time = 0f;
		}

		[RuntimeInitializeOnLoadMethod]
		public void RedoFade()
		{
			Reset();
		}

		public void OnGUI()
		{
			if (!m_done)
			{
				if (m_texture == null)
				{
					m_texture = new Texture2D(1, 1);
				}
				m_texture.SetPixel(0, 0, new Color(0f, 0f, 0f, m_alpha));
				m_texture.Apply();
				m_time += Time.deltaTime;
				m_alpha = FadeCurve.Evaluate(m_time);
				GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), m_texture);
				if (m_alpha <= 0f)
				{
					m_done = true;
				}
			}
		}
	}
	[AddComponentMenu("Cleverous/Prodigy/Utility/FPS To UI Text")]
	public class FpsToText : MonoBehaviour
	{
		[Header("// Sample Groups of Data ")]
		[Tooltip("Instead of reporting a specific framerate, this will sample many frames and report the average.")]
		public bool GroupSampling;

		[Tooltip("If Group Sampling is on, how many frames would you want to sample to report an average on?")]
		[Range(0f, 20f)]
		public int SampleSize;

		[Header("// Config ")]
		[Tooltip("The Text Component you want the result pushed to. If you're using TMP then you need to change this in the code to a TMP_Text component instead.")]
		public Text TargetText;

		[Tooltip("How often (in frames) do you want to update the Text component?")]
		[Range(1f, 20f)]
		public int UpdateTextEvery;

		[Tooltip("This will smooth out the results so they blend together between updates and are easier to read.")]
		public bool Smoothed;

		[Tooltip("This sets how many numbers are buffered into memory as strings in order to obtain zero allocations at runtime.\n\nAlthough this is trivial in memory usage, realistically, there's no reason to be over 1000.")]
		[Range(0f, 1000f)]
		public int NumberBufferSize;

		[Header("// System FPS (updates once/sec)")]
		[Tooltip("Would you like to read the System Tick instead of calculating it in this script?\n\nTests show that differences are negligible, but the option remains available to you.")]
		public bool UseSystemTick;

		[Header("// Color Config ")]
		[Tooltip("Optionally change the color of the TargetText based on FPS performance.")]
		public bool UseColors;

		[Tooltip("If the framerate is above 'OkayBelow' it will be the 'Good' color.")]
		public Color Good;

		[Tooltip("If the framerate is below 'OkayBelow' it will be the 'Okay' color.")]
		public Color Okay;

		[Tooltip("If the framerate is below 'BadBelow' it will be the 'Bad' color.")]
		public Color Bad;

		[Tooltip("Threshold for defining an 'okay' framerate. Below this value is considered okay, but not high enough to be good, and not low enough to be bad.")]
		public int OkayBelow;

		[Tooltip("Threshold for defining an 'bad' framerate. Below this value is considered bad.")]
		public int BadBelow;

		protected int[] FpsSamples;

		protected int SampleIndex;

		protected int TextUpdateIndex;

		private int m_sysLastSysTick;

		private int m_sysLastFrameRate;

		private int m_sysFrameRate;

		private string m_localfps;

		private static string[] m_numbers;

		public int Framerate { get; private set; }

		protected virtual void Reset()
		{
			GroupSampling = true;
			SampleSize = 20;
			UpdateTextEvery = 1;
			Smoothed = true;
			UseColors = true;
			Good = Color.green;
			Okay = Color.yellow;
			Bad = Color.red;
			OkayBelow = 60;
			BadBelow = 30;
			UseSystemTick = false;
			NumberBufferSize = 1000;
		}

		protected virtual void Start()
		{
			m_numbers = new string[NumberBufferSize];
			for (int i = 0; i < NumberBufferSize; i++)
			{
				m_numbers[i] = i.ToString();
			}
			FpsSamples = new int[SampleSize];
			for (int j = 0; j < FpsSamples.Length; j++)
			{
				FpsSamples[j] = 1;
			}
			if (!TargetText)
			{
				base.enabled = false;
			}
		}

		protected virtual void Update()
		{
			if (GroupSampling)
			{
				Group();
			}
			else
			{
				SingleFrame();
			}
			m_localfps = m_numbers[Framerate];
			SampleIndex = ((SampleIndex < SampleSize - 1) ? (SampleIndex + 1) : 0);
			TextUpdateIndex = ((TextUpdateIndex <= UpdateTextEvery) ? (TextUpdateIndex + 1) : 0);
			if (TextUpdateIndex == UpdateTextEvery)
			{
				TargetText.text = m_localfps;
			}
			if (UseColors)
			{
				if (Framerate < BadBelow)
				{
					TargetText.color = Bad;
				}
				else
				{
					TargetText.color = ((Framerate < OkayBelow) ? Okay : Good);
				}
			}
		}

		protected virtual void SingleFrame()
		{
			Framerate = Mathf.Clamp(UseSystemTick ? GetSystemFramerate() : ((int)(Smoothed ? (1f / Time.smoothDeltaTime) : (1f / Time.deltaTime))), 0, m_numbers.Length - 1);
		}

		protected virtual void Group()
		{
			FpsSamples[SampleIndex] = Mathf.Clamp(UseSystemTick ? GetSystemFramerate() : ((int)(Smoothed ? (1f / Time.smoothDeltaTime) : (1f / Time.deltaTime))), 0, m_numbers.Length - 1);
			Framerate = 0;
			bool flag = true;
			int num = 0;
			while (flag)
			{
				if (num == SampleSize - 1)
				{
					flag = false;
				}
				Framerate += FpsSamples[num];
				num++;
			}
			Framerate /= FpsSamples.Length;
		}

		protected virtual int GetSystemFramerate()
		{
			if (Environment.TickCount - m_sysLastSysTick >= 1000)
			{
				m_sysLastFrameRate = m_sysFrameRate;
				m_sysFrameRate = 0;
				m_sysLastSysTick = Environment.TickCount;
			}
			m_sysFrameRate++;
			return m_sysLastFrameRate;
		}
	}
	[AddComponentMenu("Cleverous/Prodigy/Game/Game")]
	[DefaultExecutionOrder(-99999)]
	public class Game : MonoBehaviour
	{
		public static Game Instance;

		protected static System.Random Rng;

		public static bool ShowAllHealthbars;

		[AssetDropdown(typeof(GameSettings))]
		[SerializeField]
		private GameSettings m_settings;

		protected static Dictionary<uint, Tickable> Tickables;

		private static List<uint> m_sortedTickablesIdList;

		private static bool m_tickablesDirty;

		public static Action OnInputTick;

		public static Action<ProdigyAgent> OnLocalAvatarSpawned;

		public static Action<ProdigyPlayer> OnPlayerJoined;

		private static int m_tick;

		public const int TickRate = 30;

		private bool m_ready;

		public GameSettings Settings
		{
			get
			{
				return m_settings;
			}
			set
			{
				m_settings = value;
			}
		}

		public static bool GameplayInputIsAllowed { get; set; }

		public static Dictionary<uint, ProdigyPlayer> Players { get; protected set; }

		public static ProdigyPlayer LocalPlayer { get; set; }

		public static int Tick
		{
			get
			{
				return m_tick;
			}
			set
			{
				m_tick = value;
			}
		}

		protected virtual void Init()
		{
			if (!m_ready)
			{
				Instance = this;
				Rng = new System.Random();
				Tickables = new Dictionary<uint, Tickable>();
				m_sortedTickablesIdList = new List<uint>();
				Players = new Dictionary<uint, ProdigyPlayer>();
				Settings.Initialize();
				m_ready = true;
			}
		}

		protected virtual void Awake()
		{
			Init();
		}

		private void Update()
		{
			GameTick();
		}

		protected virtual void GameTick()
		{
			InputSystem.Update();
			OnInputTick?.Invoke();
			if (Tickables.Count > 0)
			{
				if (m_tickablesDirty)
				{
					m_sortedTickablesIdList.Sort();
					m_tickablesDirty = false;
				}
				foreach (uint sortedTickablesId in m_sortedTickablesIdList)
				{
					if (Tickables.TryGetValue(sortedTickablesId, out var value))
					{
						value.GameTick();
					}
					else
					{
						UnityEngine.Debug.LogWarning($"<color=green>GAME: Tickable was invalid.</color> ( {sortedTickablesId} )");
					}
				}
			}
			Tick++;
		}

		public static void GameplayInputToggle(bool state)
		{
			GameplayInputIsAllowed = state;
		}

		public static void RegisterTickable(Tickable tickable)
		{
			if (tickable == null)
			{
				UnityEngine.Debug.LogWarning("Tickable was null.");
				return;
			}
			Tickables.Add(tickable.Id, tickable);
			m_sortedTickablesIdList.Add(tickable.Id);
			m_tickablesDirty = true;
		}

		public static void DeRegisterTickable(Tickable tickable)
		{
			Tickables.Remove(tickable.Id);
			m_sortedTickablesIdList.Remove(tickable.Id);
			m_tickablesDirty = true;
		}

		public static Tickable GetTickable(uint id)
		{
			if (!Tickables.TryGetValue(id, out var value))
			{
				return null;
			}
			return value;
		}

		public static void RegisterPlayer(ProdigyPlayer player)
		{
			Players.Add(player.Id, player);
			OnPlayerJoined?.Invoke(player);
			LocalPlayer = player;
		}

		public static bool DeregisterPlayer(ProdigyPlayer player)
		{
			if (Players == null || Players.Count == 0)
			{
				return false;
			}
			Players.Remove(player.Id);
			LocalPlayer = null;
			return true;
		}

		public static ProdigyPlayer GetPlayer(uint id)
		{
			if (!Players.TryGetValue(id, out var value))
			{
				return null;
			}
			return value;
		}

		public static ProdigyPlayer GetPlayer(int agentLifeId)
		{
			return (from x in Players
				where x.Value != null && x.Value.RuntimeAvatar.Vitals.LifeId == agentLifeId
				select x.Value).FirstOrDefault();
		}

		public static int GetRandomInt(int min, int max)
		{
			return Rng.Next(min, max);
		}

		public static float GetRandomFloat01()
		{
			return UnityEngine.Random.value;
		}

		public static bool LayerIsInMask(GameObject obj, LayerMask layerMask)
		{
			return (layerMask.value & (1 << obj.layer)) > 0;
		}

		public static void QuitGame()
		{
			Application.Quit();
		}
	}
	public static class GameUtils
	{
		public static bool LayerMaskIncludesLayer(LayerMask mask, int layer)
		{
			return (int)mask == ((int)mask | (1 << layer));
		}
	}
