	[AddComponentMenu("Cleverous/Prodigy/Game/Prodigy Camera")]
	public class ProdigyCamera : MonoBehaviour
	{
		public static ProdigyCamera Instance;

		public static Camera GameCamera;

		public Camera GameCam;

		[Tooltip("The speed that the camera follows the player. Set to a very high value (9999) for tight/matched following, or a low value (3) for loose/soft following.")]
		public float FollowSpeed;

		[Tooltip("The camera will follow the aim direction of the player multiplied by this amount. High values are uncomfortable, but low values (~0.12) can add some style.")]
		[Range(0f, 1f)]
		public float FollowAimStrength;

		[SerializeField]
		private float rotationMax = 80f;

		public float cameraZoomSpeed;

		private IAgent m_follow;

		private Vector3 m_shakeOffset;

		private float m_shakeAmount;

		private Vector3 m_targetPosition;

		private Vector3 camMaxZoom = new Vector3(0f, 0f, -23f);

		private Vector3 camMinZoom = new Vector3(0f, 0f, -12f);

		private Vector3 targetZoomAmount;

		private const float gamepadZoomMult = 50f;

		private const float keyboardZoomMult = 250f;

		private const float rotateMult = 5f;

		private const float rotateResetMult = 0.1f;

		private Quaternion originalRotation;

		private float originalYRotation;

		private float targetRotation;

		protected virtual void Reset()
		{
			FollowSpeed = 12f;
			FollowAimStrength = 0.12f;
		}

		protected virtual void Awake()
		{
			Instance = this;
			GameCamera = GameCam;
			Game.OnLocalAvatarSpawned = (Action<ProdigyAgent>)Delegate.Combine(Game.OnLocalAvatarSpawned, new Action<ProdigyAgent>(AssignLocalPlayerAvatarTarget));
			m_targetPosition = base.transform.position;
			targetZoomAmount = GameCam.transform.localPosition;
			originalRotation = base.transform.rotation;
			originalYRotation = base.transform.rotation.eulerAngles.y;
		}

		private void Start()
		{
			InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
			instance.OnCameraZoomInput = (Action<float>)Delegate.Combine(instance.OnCameraZoomInput, new Action<float>(OnCamZoomInput));
		}

		private void OnDestroy()
		{
			if (SingletonBehaviour<InputBroker>.InstanceExists())
			{
				InputBroker instance = SingletonBehaviour<InputBroker>.Instance;
				instance.OnCameraZoomInput = (Action<float>)Delegate.Remove(instance.OnCameraZoomInput, new Action<float>(OnCamZoomInput));
			}
		}

		private void OnCamZoomInput(float value)
		{
			if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove)
			{
				OnCamZoomInputMouseWheel(value);
			}
		}

		private void OnCamZoomInputMouseWheel(float value)
		{
			float z = MathTG.Remap(value, -360f, 360f, -3f, 3f);
			Vector3 vector = new Vector3(0f, 0f, z);
			Vector3 vector2 = GameCam.transform.localPosition + vector;
			if (vector2.z > camMinZoom.z)
			{
				vector2 = camMinZoom;
			}
			else if (vector2.z < camMaxZoom.z)
			{
				vector2 = camMaxZoom;
			}
			targetZoomAmount = vector2;
		}

		private void OnCamZoomInputGamepad(float value)
		{
			if (!SingletonBehaviour<InputBroker>.Instance.HoldingSpellWheel)
			{
				Vector3 vector = new Vector3(0f, 0f, value * 50f);
				Vector3 vector2 = GameCam.transform.localPosition + vector;
				if (vector2.z > camMinZoom.z)
				{
					vector2 = camMinZoom;
				}
				else if (vector2.z < camMaxZoom.z)
				{
					vector2 = camMaxZoom;
				}
				targetZoomAmount = vector2;
			}
		}

		protected virtual void Update()
		{
			if (m_follow == null || m_follow.Vitals == null || m_follow.Vitals.IsDead || m_follow.MyTransform == null)
			{
				base.transform.position = m_targetPosition;
				return;
			}
			GameCam.transform.localPosition = Vector3.Slerp(GameCam.transform.localPosition, targetZoomAmount, cameraZoomSpeed * Time.deltaTime);
			m_targetPosition = Vector3.Lerp(m_targetPosition, m_follow.MyTransform.position + m_follow.GetInput().Look * FollowAimStrength, Time.deltaTime * FollowSpeed);
			m_shakeOffset = UnityEngine.Random.insideUnitSphere * m_shakeAmount;
			m_shakeAmount = Mathf.Clamp(m_shakeAmount - Time.unscaledDeltaTime, 0f, m_shakeAmount);
			base.transform.position = m_targetPosition + m_shakeOffset;
			if (SingletonBehaviour<InputBroker>.Instance.CameraZoomInputValue != 0f && (UnityEngine.Input.GetKey(KeyCode.W) || UnityEngine.Input.GetKey(KeyCode.S)))
			{
				OnCamZoomInput(SingletonBehaviour<InputBroker>.Instance.CameraZoomInputValue * 250f * Time.unscaledDeltaTime);
			}
			if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.Free)
			{
				OnCamZoomInputGamepad(SingletonBehaviour<InputBroker>.Instance.CameraZoomInputValue * Time.unscaledDeltaTime);
			}
			UpdateCameraRotation();
		}

		private void UpdateCameraRotation()
		{
			float num = Mathf.Abs(base.transform.rotation.eulerAngles.y - originalYRotation);
			targetRotation = Mathf.MoveTowards(targetRotation, 0f, Time.unscaledDeltaTime * num * 0.1f);
			if (!SingletonBehaviour<InputBroker>.Instance.HoldingSpellWheel)
			{
				float num2 = 0f - SingletonBehaviour<InputBroker>.Instance.CameraRotateInputValue;
				targetRotation += num2 * Time.unscaledDeltaTime * 5f;
				targetRotation = Mathf.Clamp(targetRotation, -1f, 1f);
			}
			base.transform.localRotation = Quaternion.Euler(originalRotation.eulerAngles.x, originalYRotation + targetRotation * rotationMax, originalRotation.eulerAngles.z);
		}

		public void InstantTeleportToTarget()
		{
			if (m_follow == null)
			{
				UnityEngine.Debug.LogError("Could not instant teleport to follow taget, follow target is null.");
			}
			else
			{
				base.transform.position = m_follow.MyTransform.position + m_follow.GetInput().Look * FollowAimStrength;
			}
		}

		protected virtual void AssignLocalPlayerAvatarTarget(IAgent obj)
		{
			m_follow = obj;
		}

		public virtual void Shake(float amount)
		{
			if (SaveData.SettingsSave.screenShake)
			{
				m_shakeAmount = amount;
			}
		}
	}
	[AddComponentMenu("Cleverous/Prodigy/Game/Prodigy Player")]
	public class ProdigyPlayer : Tickable
	{
		public static Action<ProdigyPlayer, ProdigyAgent> OnAvatarSet;

		public static Action OnAvatarRemoved;

		[HideInInspector]
		public ProdigyAgent RuntimeAvatar;

		[AssetDropdown(typeof(ProdigyAgentDefinition))]
		protected ProdigyAgentDefinition AvatarDefinition;

		private bool m_registeredPlayer;

		private PlayerInput m_currentInput;

		private List<PlayerInput> m_inputHistory;

		private List<PlayerInput> m_inputQueue;

		private Vector3 m_PlayerSpawnPos;

		private Vector3 lastLook;

		protected static bool IsInputBlocked => InputBlocker.Blocked;

		private bool HasAvatar => RuntimeAvatar != null;

		private void Awake()
		{
			m_currentInput = default(PlayerInput);
			m_inputQueue = new List<PlayerInput>();
			m_inputHistory = new List<PlayerInput>();
			lastLook = Vector3.zero;
		}

		private void OnDestroy()
		{
			Game.DeregisterPlayer(this);
			OnAvatarRemoved?.Invoke();
		}

		public virtual void Initialize(ProdigyAgentDefinition avatarDefinition, Vector3 spawnPos)
		{
			AvatarDefinition = avatarDefinition;
			m_PlayerSpawnPos = spawnPos;
		}

		public override void OnStartClient()
		{
			base.OnStartClient();
			if (!m_registeredPlayer)
			{
				Game.RegisterPlayer(this);
				m_registeredPlayer = true;
			}
			CmdRequestGameTick();
			TrySpawnAvatar(giveDefaultItems: true, m_PlayerSpawnPos);
		}

		public override void OnStartServer()
		{
			base.OnStartServer();
			RpcSyncGameTick(Game.Tick);
		}

		public override void GameTick()
		{
			LocalClientCollectInput();
			AllClientsProcessInput();
		}

		private void LocalClientCollectInput()
		{
			if (IsInputBlocked)
			{
				m_currentInput.Set(Vector3.zero, Vector3.zero, lastLook, interact: false, altInteract: false, cycle: false, fire1: false, fire2: false, rage: false);
				return;
			}
			m_currentInput.Set(SingletonBehaviour<InputBroker>.Instance.Move, SingletonBehaviour<InputBroker>.Instance.MoveRaw, SingletonBehaviour<InputBroker>.Instance.Look, SingletonBehaviour<InputBroker>.Instance.Interact, SingletonBehaviour<InputBroker>.Instance.AltInteract, SingletonBehaviour<InputBroker>.Instance.CycleEquipment, SingletonBehaviour<InputBroker>.Instance.Fire1, SingletonBehaviour<InputBroker>.Instance.Fire2, SingletonBehaviour<InputBroker>.Instance.Rage);
			lastLook = SingletonBehaviour<InputBroker>.Instance.Look;
		}

		private void AllClientsProcessInput()
		{
			RpcInputToClients(m_currentInput);
		}

		protected virtual void TrySpawnAvatar(bool giveDefaultItems, Vector3 position)
		{
			UnityEngine.Debug.Log("Spawning avatar");
			ServerSpawnAvatar(giveDefaultItems, position);
		}

		public virtual void RequestRespawn(Vector3 position = default(Vector3))
		{
			if (position == default(Vector3))
			{
				position = base.transform.position;
			}
			TrySpawnAvatar(giveDefaultItems: false, position);
		}

		public virtual void RequestDestruction(bool skipSave)
		{
			if (HasAvatar)
			{
				if (!skipSave)
				{
					Player.PlayerChar.ForceFlushSave();
				}
				UnityEngine.Debug.Log("Destroying avatar");
				UnityEngine.Object.Destroy(RuntimeAvatar.gameObject);
				OnAvatarRemoved?.Invoke();
			}
		}

		protected virtual void ServerSpawnAvatar(bool giveDefaultItems, Vector3 position)
		{
			if (AvatarDefinition == null)
			{
				UnityEngine.Debug.LogError("Cannot spawn an Avatar without Definition.");
				return;
			}
			GameObject gameObject = UnityEngine.Object.Instantiate(AvatarDefinition.AgentPrefab, position, base.transform.rotation);
			ProdigyAgent component = gameObject.GetComponent<ProdigyAgent>();
			if (gameObject.TryGetComponent<NavMeshAgent>(out var component2) && component2.enabled)
			{
				component2.enabled = false;
				gameObject.transform.position = position;
				component2.enabled = true;
			}
			component.SetOwnerPlayerId(base.Id);
			if (HasAvatar)
			{
				UnityEngine.Object.Destroy(RuntimeAvatar.gameObject);
			}
			SetAvatarObject(component);
		}

		public virtual void SetAvatarObject(ProdigyAgent obj)
		{
			RuntimeAvatar = obj;
			OnAvatarSet?.Invoke(this, obj);
			Game.OnLocalAvatarSpawned(obj);
		}

		public virtual ProdigyAgentDefinition GetAvatarDefinition()
		{
			return AvatarDefinition;
		}

		public virtual void TrySetAvatarDefinition(ProdigyAgentDefinition definition)
		{
			CmdTrySetAgentDefinition(definition.GetDbKey());
		}

		protected virtual void CmdTrySetAgentDefinition(int vaultIndex)
		{
			SvrSetAgentDefinition(vaultIndex);
		}

		protected virtual void SvrSetAgentDefinition(int vaultIndex)
		{
			ProdigyAgentDefinition prodigyAgentDefinition = (ProdigyAgentDefinition)Vault.Get(vaultIndex);
			if (prodigyAgentDefinition != null)
			{
				AvatarDefinition = prodigyAgentDefinition;
			}
			RpcSetAgentDefinition(vaultIndex);
		}

		protected virtual void RpcSetAgentDefinition(int vaultIndex)
		{
			ProdigyAgentDefinition prodigyAgentDefinition = (ProdigyAgentDefinition)Vault.Get(vaultIndex);
			if (prodigyAgentDefinition != null)
			{
				AvatarDefinition = prodigyAgentDefinition;
			}
		}

		protected virtual void SendInputToServer(PlayerInput input)
		{
			HandleInputsFromClient(input);
		}

		protected virtual void HandleInputsFromClient(PlayerInput input)
		{
			m_inputQueue.Add(input);
			RpcInputToClients(input);
		}

		protected virtual void RpcInputToClients(PlayerInput input)
		{
		}

		public PlayerInput GetCurrentInput()
		{
			return m_currentInput;
		}

		public void CmdRequestGameTick()
		{
			RpcSyncGameTick(Game.Tick);
		}

		public void RpcSyncGameTick(int serverTickId)
		{
			Game.Tick = serverTickId;
		}
	}
