	public enum ScanType
	{
		Directional,
		DirectionalMany,
		Box,
		BoxMany,
		Cone,
		ConeMany,
		Radius,
		RadiusMany
	}
	public enum ScanSorting
	{
		Undefined,
		NearestFirst,
		LeftFirst,
		RightFirst
	}
	public static class Targetter
	{
		public static Vector3 GetAimPos(Vector3 position, Vector3 direction)
		{
			return position + direction;
		}

		public static Collider GetObjInDirection(Vector3 origin, Vector3 dir, LayerMask mask, float maxRadius, float maxDistance)
		{
			if (!Physics.SphereCast(origin, maxRadius, dir, out var hitInfo, maxDistance, mask))
			{
				return null;
			}
			return hitInfo.collider;
		}

		public static Collider[] GetAllObjInDirection(Vector3 origin, Vector3 dir, LayerMask mask, float sweepRadius, float maxDistance, int maxCount = 10)
		{
			RaycastHit[] array = Physics.SphereCastAll(origin, sweepRadius, dir, maxDistance, mask);
			if (array.Length == 0)
			{
				return null;
			}
			int num = ((array.Length > maxCount) ? maxCount : array.Length);
			Collider[] array2 = new Collider[num];
			for (int i = 0; i < num; i++)
			{
				array2[i] = array[i].collider;
			}
			return array2;
		}

		public static Collider RadiusSweep(Vector3 origin, LayerMask mask, float maxRadius)
		{
			Collider[] array = Physics.OverlapSphere(origin, maxRadius, mask);
			if (array.Length != 0)
			{
				return array[0];
			}
			return null;
		}

		public static Collider[] RadiusSweepAll(Vector3 origin, LayerMask mask, float maxRadius, int maxCount = 999)
		{
			Collider[] array = Physics.OverlapSphere(origin, maxRadius, mask);
			if (array.Length == 0)
			{
				return null;
			}
			if (array.Length < maxCount)
			{
				return array;
			}
			Collider[] array2 = new Collider[maxCount];
			for (int i = 0; i < maxCount; i++)
			{
				array2[i] = array[i];
			}
			return array2;
		}

		public static RaycastHit[] RadiusSweepAllValidated(Vector3 origin, Vector3 validationOffset, LayerMask targetMask, LayerMask validationMask, float maxRadius, int maxCount = 999)
		{
			Collider[] array = Physics.OverlapSphere(origin, maxRadius, targetMask);
			if (array.Length == 0)
			{
				return null;
			}
			List<RaycastHit> list = new List<RaycastHit>();
			foreach (Collider collider in array)
			{
				Vector3 vector = origin + validationOffset;
				Vector3 direction = collider.ClosestPoint(vector) - vector;
				if (Physics.Raycast(origin + validationOffset, direction, out var hitInfo, direction.magnitude + 1f, validationMask) && hitInfo.collider == collider)
				{
					list.Add(hitInfo);
				}
				if (list.Count >= maxCount)
				{
					break;
				}
			}
			return list.ToArray();
		}

		public static Collider BoxSweep(Vector3 origin, Vector3 halfExtents, Quaternion orientation, LayerMask mask)
		{
			Collider[] array = Physics.OverlapBox(origin, halfExtents, orientation, mask);
			if (array.Length != 0)
			{
				return array[0];
			}
			return null;
		}

		public static Collider[] BoxSweepAll(Vector3 origin, Vector3 halfExtents, Quaternion orientation, LayerMask mask, int maxCount, ScanSorting sort = ScanSorting.Undefined)
		{
			Collider[] array = Physics.OverlapBox(origin, halfExtents, orientation, mask);
			if (array.Length == 0)
			{
				return null;
			}
			if (array.Length < maxCount)
			{
				return array;
			}
			Collider[] array2 = new Collider[maxCount];
			for (int i = 0; i < maxCount; i++)
			{
				array2[i] = array[i];
			}
			return array2;
		}

		public static RaycastHit[] ConeSweepAll(Vector3 origin, Vector3 direction, LayerMask mask, float radius, float distance, float angle, ScanSorting sort, bool debug = false, float debugTime = 0f)
		{
			Vector3 vector = origin - direction * radius;
			Vector3 origin2 = origin - direction * distance;
			List<RaycastHit> list = new List<RaycastHit>();
			RaycastHit[] array = Physics.SphereCastAll(new Ray(origin2, direction), distance, distance, mask);
			for (int i = 0; i < array.Length; i++)
			{
				Vector3 to = array[i].point - vector;
				if (!(Vector3.Angle(direction, to) > angle / 2f))
				{
					if (debug)
					{
						UnityEngine.Debug.DrawLine(vector, array[i].point, Color.cyan);
					}
					list.Add(array[i]);
				}
			}
			if (!debug)
			{
				return list.ToArray();
			}
			Vector3 vector2 = Quaternion.Euler(0f, angle / 2f, 0f) * direction;
			Vector3 vector3 = Quaternion.Euler(0f, (0f - angle) / 2f, 0f) * direction;
			DebugExtras.DrawArc2D(vector, direction, radius + distance, angle, Color.green, 12, debugTime);
			DebugExtras.DrawArc2D(vector, direction, radius, angle, Color.green, 12, debugTime);
			UnityEngine.Debug.DrawRay(vector + vector2 * radius, vector2 * distance, Color.green, debugTime);
			UnityEngine.Debug.DrawRay(vector + vector3 * radius, vector3 * distance, Color.green, debugTime);
			return list.ToArray();
		}
	}
	public abstract class Tickable : MonoBehaviour
	{
		private static uint idCounter;

		private uint internalId;

		private bool m_registeredForTick;

		[HideInInspector]
		public int SpawnedAtTick;

		public uint Id => internalId;

		private void Start()
		{
			OnStartServer();
			OnStartClient();
		}

		public virtual void OnStartClient()
		{
			SpawnedAtTick = Game.Tick;
			RegisterForTick();
		}

		public virtual void OnStartServer()
		{
			RegisterForTick();
		}

		private void OnDestroy()
		{
			Game.DeRegisterTickable(this);
		}

		protected void RegisterForTick()
		{
			if (!m_registeredForTick)
			{
				internalId = idCounter++;
				Game.RegisterTickable(this);
				m_registeredForTick = true;
			}
		}

		public abstract void GameTick();
	}
	public class TransformLookAtCamera : MonoBehaviour
	{
		public bool Invert;

		public bool IsExclamationMark;

		private Vector3 directionToCamera;

		private Camera c;

		protected virtual void Start()
		{
			c = ProdigyCamera.GameCamera;
		}

		protected virtual void Update()
		{
			if (c == null)
			{
				base.gameObject.SetActive(value: false);
				return;
			}
			if (Invert)
			{
				base.transform.LookAt(c.transform.forward * 10000f);
			}
			else
			{
				base.transform.LookAt(c.transform);
			}
			if (IsExclamationMark)
			{
				directionToCamera = c.transform.position - base.transform.position;
				base.transform.rotation = Quaternion.LookRotation(-directionToCamera);
			}
		}
	}
	public class ThatHurtTrigger : MonoBehaviour
	{
		[Header("References")]
		public CharacterVitals TargetVitals;

		private void Reset()
		{
			TargetVitals = GetComponent<CharacterVitals>();
		}

		public void Awake()
		{
			if (TargetVitals == null)
			{
				TargetVitals = GetComponent<CharacterVitals>();
			}
			CharacterVitals targetVitals = TargetVitals;
			targetVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Combine(targetVitals.OnDamaged, new Action<CharacterVitals.Damage>(OnHurt));
			CharacterVitals targetVitals2 = TargetVitals;
			targetVitals2.OnHealed = (Action<CharacterVitals.Heal>)Delegate.Combine(targetVitals2.OnHealed, new Action<CharacterVitals.Heal>(OnHeal));
			CharacterVitals targetVitals3 = TargetVitals;
			targetVitals3.OnLearned = (Action<int>)Delegate.Combine(targetVitals3.OnLearned, new Action<int>(OnLearn));
			CharacterVitals targetVitals4 = TargetVitals;
			targetVitals4.OnEnergized = (Action<int>)Delegate.Combine(targetVitals4.OnEnergized, new Action<int>(OnEnergize));
			CharacterVitals targetVitals5 = TargetVitals;
			targetVitals5.OnMissed = (Action)Delegate.Combine(targetVitals5.OnMissed, new Action(OnMissed));
		}

		public void OnDestroy()
		{
			if (TargetVitals != null)
			{
				CharacterVitals targetVitals = TargetVitals;
				targetVitals.OnDamaged = (Action<CharacterVitals.Damage>)Delegate.Remove(targetVitals.OnDamaged, new Action<CharacterVitals.Damage>(OnHurt));
				CharacterVitals targetVitals2 = TargetVitals;
				targetVitals2.OnHealed = (Action<CharacterVitals.Heal>)Delegate.Remove(targetVitals2.OnHealed, new Action<CharacterVitals.Heal>(OnHeal));
				CharacterVitals targetVitals3 = TargetVitals;
				targetVitals3.OnLearned = (Action<int>)Delegate.Remove(targetVitals3.OnLearned, new Action<int>(OnLearn));
				CharacterVitals targetVitals4 = TargetVitals;
				targetVitals4.OnEnergized = (Action<int>)Delegate.Remove(targetVitals4.OnEnergized, new Action<int>(OnEnergize));
				CharacterVitals targetVitals5 = TargetVitals;
				targetVitals5.OnMissed = (Action)Delegate.Remove(targetVitals5.OnMissed, new Action(OnMissed));
			}
		}

		private void OnHurt(CharacterVitals.Damage data)
		{
			if (data.isCritical)
			{
				string text = (data.IsFullyResisted() ? I2Loca.GetFormat("DamageFullResist", data.value) : ((!data.IsPartiallyResisted()) ? data.value.ToString() : I2Loca.GetFormat("DamagePartialResist", data.value, data.damageResisted)));
				ThatHurt.PopText(TargetVitals.transform.position + Vector3.up * 2f, I2Loca.Get("CriticalStrike") + "\n" + text, 1f, ThatHurt.ThatHurtColor.Damage, 0f);
			}
			else if (data.damageResisted > 0)
			{
				if (data.IsFullyResisted())
				{
					ThatHurt.PopText(TargetVitals.transform.position + Vector3.up * 2f, I2Loca.GetFormat("DamageFullResist", data.value), 1f, ThatHurt.ThatHurtColor.Damage, 0f);
				}
				else
				{
					ThatHurt.PopText(TargetVitals.transform.position + Vector3.up * 2f, I2Loca.GetFormat("DamagePartialResist", data.value, data.damageResisted), 1f, ThatHurt.ThatHurtColor.Damage, 0f);
				}
			}
			else
			{
				ThatHurt.Pop(TargetVitals.transform.position + Vector3.up * 2f, data.value, 1f, ThatHurt.ThatHurtColor.Damage);
			}
		}

		private void OnHeal(CharacterVitals.Heal data)
		{
			ThatHurt.PopText(TargetVitals.transform.position + Vector3.up * 2f, I2Loca.GetFormat("PlusHp", data.value), 1f, ThatHurt.ThatHurtColor.Healing, 0f);
		}

		private void OnLearn(int data)
		{
			ThatHurt.Pop(TargetVitals.transform.position + Vector3.up * 2f, data, 1f, ThatHurt.ThatHurtColor.Gold);
		}

		private void OnEnergize(int data)
		{
			string arg = ((data >= 0) ? "+" : "");
			ThatHurt.PopText(TargetVitals.transform.position + Vector3.up * 2f, string.Format("{0}{1} {2}", arg, data, I2Loca.Get("Mana")), 1f, ThatHurt.ThatHurtColor.Mana, 0f);
		}

		private void OnMissed()
		{
			ThatHurt.PopText(TargetVitals.transform.position, I2Loca.Get("Missed"), 1f, ThatHurt.ThatHurtColor.White, 0f);
		}
	}
	public class AgentHealthBar : MonoBehaviour
	{
		public GameObject HealthBarObject;

		public MeshRenderer HealthbarMesh;

		public CharacterVitals agentVitals;

		private MaterialPropertyBlock m_propMatBlock;

		protected virtual void Awake()
		{
			m_propMatBlock = new MaterialPropertyBlock();
		}

		private void Start()
		{
			if (agentVitals == null)
			{
				agentVitals = GetComponentInParent<CharacterVitals>();
			}
			if (!SaveData.SettingsSave.showHealthBars)
			{
				base.gameObject.SetActive(value: false);
			}
		}

		protected virtual void Update()
		{
			if (!agentVitals.IsDead && agentVitals.GetHealth() < agentVitals.GetMaxHealth())
			{
				HealthBarObject.SetActive(value: true);
				base.transform.LookAt(base.transform.position + Camera.main.transform.forward);
				UpdateParams();
			}
			else
			{
				HealthBarObject.SetActive(value: false);
			}
		}

		protected virtual void UpdateParams()
		{
			HealthbarMesh.GetPropertyBlock(m_propMatBlock);
			m_propMatBlock.SetFloat("_Fill", agentVitals.GetHealth() / agentVitals.GetMaxHealth());
			HealthbarMesh.SetPropertyBlock(m_propMatBlock);
		}
	}
