		public void SetInputMode(InputMode mode)
		{
			switch (mode)
			{
			case InputMode.None:
				Inputs.CharacterInputs.Disable();
				Inputs.Menu.Disable();
				break;
			case InputMode.Menu:
				Inputs.CharacterInputs.Disable();
				Inputs.Menu.Enable();
				break;
			case InputMode.Game:
				Inputs.Menu.Disable();
				Inputs.CharacterInputs.Enable();
				break;
			}
			ActiveInputMode = mode;
			OnInputModeChanged?.Invoke(mode);
		}

		public void OnVirtualCursorActive(bool newState)
		{
			if (newState)
			{
				Inputs.Menu.Navigate.Disable();
			}
			else
			{
				Inputs.Menu.Navigate.Enable();
			}
		}

		private void InputActionChangeCallback(object obj, InputActionChange change)
		{
			if (change != InputActionChange.ActionPerformed || obj == null || !(obj is InputAction { activeControl: not null } inputAction))
			{
				return;
			}
			InputDevice device = inputAction.activeControl.device;
			if (device.name.Equals("Mouse") && !inputAction.name.Equals("Click"))
			{
				return;
			}
			InputBehavior localInputBehavior = LocalInputBehavior;
			LocalInputBehavior = ((device.name.Equals("Keyboard") || device.name.Equals("Mouse")) ? InputBehavior.ClickToMove : InputBehavior.Free);
			if (localInputBehavior != LocalInputBehavior)
			{
				string targetScheme = LocalInputBehavior switch
				{
					InputBehavior.ClickToMove => "Keyboard", 
					InputBehavior.Free => "Gamepad", 
					_ => throw new ArgumentOutOfRangeException(), 
				};
				string bindingGroup = Inputs.controlSchemes.First((InputControlScheme x) => x.name == targetScheme).bindingGroup;
				Inputs.bindingMask = InputBinding.MaskByGroup(bindingGroup);
				if (LocalInputBehavior == InputBehavior.Free && m_navMeshAgent != null && m_navMeshAgent.isOnNavMesh)
				{
					m_navMeshAgent.ResetPath();
					SetHighlightedTarget(null);
				}
				OnInputBehaviorChanged?.Invoke(LocalInputBehavior);
			}
		}

