		public virtual void ManagedTick()
		{
			if (!(TargetAgent == null) && !(TargetPlayer == null))
			{
				ReadPressedInputs();
				switch (LocalInputBehavior)
				{
				case InputBehavior.ClickToMove:
					ParseClickToMove();
					break;
				case InputBehavior.Free:
					ParseFree();
					break;
				default:
					throw new ArgumentOutOfRangeException();
				}
			}
		}

		public void BlockMovement(bool statement)
		{
			movementLocked = statement;
			UnityEngine.Debug.Log("BlockMovement " + statement);
			m_navMeshAgent.isStopped = movementLocked;
		}

		protected virtual void ResetInputs()
		{
			Move = Vector3.zero;
			Fire1 = false;
			Fire2 = false;
			Rage = false;
			Interact = false;
			AltInteract = false;
			CycleEquipment = false;
			Stationary = false;
			Menu = false;
			Inventory = false;
			Quest = false;
		}

		protected virtual void ReadPressedInputs()
		{
			Fire1 = Inputs.CharacterInputs.Fire1.IsPressed();
			Fire2 = Inputs.CharacterInputs.Fire2.IsPressed();
			if (Inputs.CharacterInputs.CameraZoom.enabled)
			{
				CameraZoomInputValue = Inputs.CharacterInputs.CameraZoom.ReadValue<float>();
			}
			else
			{
				CameraZoomInputValue = 0f;
			}
			CameraRotateInputValue = Inputs.CharacterInputs.CameraRotate.ReadValue<float>();
			if (LocalInputBehavior != 0)
			{
				Stationary = Inputs.CharacterInputs.Stationary.IsPressed();
			}
		}

		protected virtual void ParseFree()
		{
			Vector2 vector = Inputs.Persistent.Move.ReadValue<Vector2>();
			MoveRaw = vector;
			Vector2 vector3 = (LookRaw = Inputs.CharacterInputs.Look.ReadValue<Vector2>());
			if (InputBlocker.Blocked)
			{
				Vector3 move = (Look = Vector3.zero);
				Move = move;
				return;
			}
			Player playerChar = Player.PlayerChar;
			if (Fire1 && !playerChar.PerformingAttack() && !playerChar.PerformingCast())
			{
				playerChar.SelectAttack();
				playerChar.StartAttack();
			}
			if (movementLocked)
			{
				Vector3 move = (Look = Vector3.zero);
				Move = move;
				return;
			}
			Vector2 vector4 = new Vector2((float)Screen.width * 0.5f + vector3.x * ((float)Screen.width * 0.5f), (float)Screen.height * 0.5f + vector3.y * ((float)Screen.height * 0.5f));
			Physics.Raycast(ProdigyCamera.GameCamera.ScreenPointToRay((LocalInputBehavior == InputBehavior.ClickToMove) ? vector3 : vector4), out var hitInfo, 100f, NavigationLayers, QueryTriggerInteraction.Collide);
			Vector3 vector5 = hitInfo.point - TargetAgent.MyTransform.position;
			if (vector5.magnitude > 1f)
			{
				Look = vector5;
				m_lookDirCache = vector5;
			}
			else
			{
				Look = m_lookDirCache.normalized;
			}
			Move = Vector3.ProjectOnPlane(ProdigyCamera.GameCamera.transform.TransformVector(vector), Vector3.up);
		}

		public virtual Vector3 GetMouseLocation()
		{
			Vector2 vector = Inputs.CharacterInputs.Look.ReadValue<Vector2>();
			Vector2 vector2 = new Vector2((float)Screen.width * 0.5f + vector.x * ((float)Screen.width * 0.5f), (float)Screen.height * 0.5f + vector.y * ((float)Screen.height * 0.5f));
			if (Physics.Raycast(ProdigyCamera.GameCamera.ScreenPointToRay((LocalInputBehavior == InputBehavior.ClickToMove) ? vector : vector2), out var hitInfo, 100f, NavigationLayers, QueryTriggerInteraction.Collide))
			{
				return hitInfo.point;
			}
			if (Mouse.current != null)
			{
				return ProdigyCamera.GameCamera.ScreenToWorldPoint(Mouse.current.position.ReadValue());
			}
			UnityEngine.Debug.LogWarning("Get mouse location failed");
			return default(Vector3);
		}

		private bool IsTargetValid(Transform targetTransform)
		{
			ContainerDestroyable component2;
			InteractableSceneObject component3;
			if (targetTransform.TryGetComponent<Character>(out var component))
			{
				if (component != null && !component.Alive())
				{
					return false;
				}
			}
			else if (targetTransform.TryGetComponent<ContainerDestroyable>(out component2))
			{
				if (component2 != null && component2.IsDestroyed)
				{
					return false;
				}
			}
			else if (targetTransform.TryGetComponent<InteractableSceneObject>(out component3) && component3 != null && !component3.CanInteract)
			{
				return false;
			}
			return true;
		}

		protected virtual void ParseClickToMove()
		{
			bool flag = ((ClickMovementStyle == ClickToMoveStyle.Continuous) ? Mouse.current.leftButton.isPressed : Mouse.current.leftButton.wasPressedThisFrame);
			bool wasPressedThisFrame = Mouse.current.leftButton.wasPressedThisFrame;
			bool wasReleasedThisFrame = Mouse.current.leftButton.wasReleasedThisFrame;
			bool mouseReleased = !Mouse.current.leftButton.isPressed;
			bool fire = Fire1;
			Fire1 = false;
			UpdateClickToMoveTargets(flag, wasPressedThisFrame, wasReleasedThisFrame, mouseReleased);
			UpdateClickToMoveHighlight();
			if (InputBlocker.Blocked)
			{
				return;
			}
			bool flag2 = false;
			bool flag3 = false;
			Player playerChar = Player.PlayerChar;
			Item activeWeapon = playerChar.activeWeapon;
			if (activeWeapon != null && !activeWeapon.IsMelee && playerChar.PerformingAttack() && !Stationary)
			{
				flag2 = true;
				flag3 = true;
			}
			if (playerChar.ShiftLootTarget == null)
			{
				if (playerChar.GetPetCount() == 1)
				{
					playerChar.ShiftLootTarget = playerChar.GetPet();
				}
				else if (playerChar.GetPartyMemberCount() > 0)
				{
					playerChar.ShiftLootTarget = playerChar.GetPartyMember();
				}
			}
			if (playerChar.ShiftLootTarget != null && hoveredInteractable != null && hoveredInteractable.CanInteract && UnityEngine.Input.GetKey(KeyCode.LeftShift) && hoveredInteractable is DroppedItem targetDroppedItem)
			{
				if (wasReleasedThisFrame && playerChar.ShiftLootTarget.CanEnterAIState(AIState.GetItem))
				{
					playerChar.ShiftLootTarget.SetTargetDroppedItem(targetDroppedItem);
					playerChar.ShiftLootTarget.SetAIState(AIState.GetItem);
				}
				flag3 = true;
				flag2 = true;
			}
			else
			{
				Character pet = playerChar.GetPet();
				if (pet != null && hoveredInteractable != null && hoveredInteractable.CanInteract && UnityEngine.Input.GetKey(KeyCode.LeftShift))
				{
					InteractableSceneObject interactableSceneObject = hoveredInteractable;
					MerchantInteractable hoveredMerchant = interactableSceneObject as MerchantInteractable;
					if ((object)hoveredMerchant != null)
					{
						MerchantType getMerchantType = hoveredMerchant.GetMerchantType;
						if (getMerchantType == MerchantType.Armor || getMerchantType == MerchantType.Magic || getMerchantType == MerchantType.Fish || getMerchantType == MerchantType.Gambler || getMerchantType == MerchantType.Goods || getMerchantType == MerchantType.Jeweler || getMerchantType == MerchantType.Potions || getMerchantType == MerchantType.Trader || getMerchantType == MerchantType.Traveling || getMerchantType == MerchantType.Weapons || getMerchantType == MerchantType.WeaponsArmor || getMerchantType == MerchantType.Identifier)
						{
							if (wasReleasedThisFrame)
							{
								if (pet.CanEnterAIState(AIState.SpeakMerchant))
								{
									Fate.SetPause(paused: true);
									if (hoveredMerchant.GetMerchantType == MerchantType.Identifier)
									{
										uint cost = hoveredMerchant.MerchChar.GetIdentifyCostForInventory(pet.inventory);
										if (cost != 0)
										{
											string formatReplaceTags = I2Loca.GetFormatReplaceTags("PetIdentifyMerchant", I2Loca.Get(hoveredMerchant.InteractableName));
											formatReplaceTags += string.Format("{0}{1} : {2}{3}{4}", Environment.NewLine, I2Loca.Get("Cost"), "<style=C1>", cost, "</style>");
											SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(formatReplaceTags, delegate(bool confirmed)
											{
												if (confirmed)
												{
													if (SingletonBehaviour<PlayerStatus>.Instance.CanAfford(cost))
													{
														pet.SetTargetMerchant(hoveredMerchant);
														pet.SetAIState(AIState.SpeakMerchant);
													}
													else
													{
														SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("ErrorMsg_NotEnoughGold", null);
													}
												}
												Fate.SetPause(paused: false);
											}, twoButtons: true);
										}
										else
										{
											SingletonBehaviour<PromptUI>.Instance.ShowPromptSingleButton("NothingToIdentify", null);
										}
									}
									else
									{
										SingletonBehaviour<PromptUI>.Instance.ShowPromptRaw(I2Loca.GetFormatReplaceTags("PetSellMerchant", I2Loca.Get(hoveredMerchant.InteractableName)), delegate(bool confirmed)
										{
											if (confirmed)
											{
												pet.SetTargetMerchant(hoveredMerchant);
												pet.SetAIState(AIState.SpeakMerchant);
											}
											Fate.SetPause(paused: false);
										}, twoButtons: true);
									}
								}
								else
								{
									SingletonBehaviour<AudioManager>.Instance.PlayAudioClip(AudioData.AudioClipName.Fail, randomizePitch: false);
								}
							}
							flag3 = true;
							flag2 = true;
						}
					}
				}
			}
			if (!flag3 && hoveredInteractable != null && hoveredInteractable.CanInteract)
			{
				if (wasPressedThisFrame)
				{
					intendedInteractable = hoveredInteractable;
					Vector3 centerPosition = intendedInteractable.GetCenterPosition();
					if (!(Vector3.Distance(TargetAgent.MyTransform.position, centerPosition) < hoveredInteractable.InteractRange))
					{
						SetMoveDestination(centerPosition);
					}
				}
				if (wasReleasedThisFrame)
				{
					if (intendedInteractable == hoveredInteractable)
					{
						Vector3 centerPosition2 = hoveredInteractable.GetCenterPosition();
						if (Vector3.Distance(TargetAgent.MyTransform.position, centerPosition2) < hoveredInteractable.InteractRange)
						{
							hoveredInteractable.Interact(Player.PlayerChar);
							TargetAgent.MyTransform.LookAt(hoveredInteractable.transform.position.WithY(TargetAgent.MyTransform.position.y));
							interactWhenInRangeTarget = null;
							interactWhenInRange = false;
							m_navMeshAgent.isStopped = true;
							SetMoveDestination(TargetAgent.MyTransform.position);
						}
						else
						{
							interactWhenInRange = true;
							interactWhenInRangeTarget = hoveredInteractable;
							SetMoveDestination(centerPosition2);
						}
					}
					else
					{
						intendedInteractable = null;
						interactWhenInRangeTarget = null;
						interactWhenInRange = false;
					}
				}
				if (intendedInteractable != null)
				{
					flag2 = true;
				}
			}
			if (wasReleasedThisFrame)
			{
				intendedInteractable = null;
			}
			bool flag4 = false;
			if (flag && !flag2)
			{
				if (!(damageableTarget != null))
				{
					SetMoveDestination(hoveredPosition);
					SetLookDestination(hoveredPosition);
					UnityEngine.Debug.DrawRay(hoveredPosition, Vector3.up * 3f, Color.green, 2f);
				}
				else if (activeWeapon != null)
				{
					if (activeWeapon.IsMelee && playerChar.InAttackRange(damageableTarget.gameObject))
					{
						if (characterTarget != null)
						{
							playerChar.SetTarget(characterTarget);
						}
						flag4 = true;
						m_navMeshAgent.isStopped = true;
						SetMoveDestination(TargetAgent.MyTransform.position);
						if (wasPressedThisFrame)
						{
							playerChar.TurnTowardPosition(damageableTarget.position);
						}
						else
						{
							SetLookDestination(damageableTarget.position);
						}
					}
					else if (!activeWeapon.IsMelee)
					{
						if (playerChar.InAttackRange(damageableTarget.gameObject))
						{
							if (characterTarget != null)
							{
								playerChar.SetTarget(characterTarget);
							}
							flag4 = true;
						}
						if (flag4)
						{
							m_navMeshAgent.isStopped = true;
							SetMoveDestination(TargetAgent.MyTransform.position);
						}
						else
						{
							SetMoveDestination(damageableTarget.position);
						}
						SetLookDestination(damageableTarget.position);
					}
					else
					{
						SetMoveDestination(damageableTarget.position);
						SetLookDestination(damageableTarget.position);
					}
				}
				else if (playerChar.InAttackRange(damageableTarget.gameObject))
				{
					flag4 = true;
					m_navMeshAgent.isStopped = true;
					SetMoveDestination(TargetAgent.MyTransform.position);
					if (wasPressedThisFrame)
					{
						playerChar.TurnTowardPosition(damageableTarget.position);
					}
					else
					{
						SetLookDestination(damageableTarget.position);
					}
				}
				else
				{
					SetMoveDestination(damageableTarget.position);
					SetLookDestination(damageableTarget.position);
				}
			}
			Fire1 = !flag2 && (flag4 || Stationary) && fire;
			if (!(playerChar.attackTimer > 0f) && fire && !flag2 && (flag4 || Stationary))
			{
				playerChar.SelectAttack();
				playerChar.StartAttack();
			}
			if (movementLocked)
			{
				Vector3 move = (Look = Vector3.zero);
				Move = move;
				m_navMeshAgent.isStopped = true;
				m_navMeshAgent.ResetPath();
				return;
			}
			UpdateAgentAvoidance();
			if (interactWhenInRange && interactWhenInRangeTarget != null)
			{
				if (Vector3.Distance(TargetAgent.MyTransform.position, interactWhenInRangeTarget.GetCenterPosition()) < interactWhenInRangeTarget.InteractRange)
				{
					interactWhenInRangeTarget.Interact(playerChar);
					TargetAgent.MyTransform.LookAt(interactWhenInRangeTarget.transform.position.WithY(TargetAgent.MyTransform.position.y));
					interactWhenInRangeTarget = null;
					interactWhenInRange = false;
					m_navMeshAgent.isStopped = true;
					SetMoveDestination(TargetAgent.MyTransform.position);
					return;
				}
			}
			else if (attackWhenInRange && attackWhenInRangeTarget != null)
			{
				if (!IsTargetValid(attackWhenInRangeTarget))
				{
					attackWhenInRange = false;
					attackWhenInRangeTarget = null;
				}
				else if (playerChar.InAttackRange(attackWhenInRangeTarget.gameObject))
				{
					SetMoveDestination(TargetAgent.MyTransform.position);
					SetLookDestination(attackWhenInRangeTarget.position);
					playerChar.SelectAttack();
					playerChar.StartAttack();
					attackWhenInRange = false;
					attackWhenInRangeTarget = null;
					return;
				}
			}
			if (m_navMeshAgent != null && m_navMeshAgent.enabled)
			{
				if (m_navMeshAgent.hasPath)
				{
					Move = m_navMeshAgent.desiredVelocity;
					if (hoveredDamageable == null)
					{
						Look = Move;
					}
				}
				else
				{
					Move = Vector3.zero;
					Look = m_cachedLookDestination - TargetAgent.MyTransform.position;
				}
			}
			else
			{
				Vector3 vector = m_cachedMoveDestination - TargetAgent.MyTransform.position;
				Move = ((vector.magnitude < 0.1f) ? Vector3.zero : vector.normalized);
				Look = m_cachedLookDestination - TargetAgent.MyTransform.position;
			}
			if (Stationary)
			{
				m_navMeshAgent.isStopped = true;
				Look = m_cachedLookDestination - TargetAgent.MyTransform.position;
			}
			MoveRaw = Move;
			LookRaw = Look;
		}

		private void UpdateAgentAvoidance()
		{
			if (Move.magnitude < 0.01f)
			{
				m_navMeshAgent.obstacleAvoidanceType = ObstacleAvoidanceType.NoObstacleAvoidance;
				return;
			}
			bool flag = Player.PlayerChar.attackTimer > 0f || Player.PlayerChar.castTimer > 0f;
			if (!flag)
			{
				flag = Physics.SphereCast(TargetAgent.MyTransform.position + Vector3.up, m_navMeshAgent.radius, TargetAgent.MyTransform.forward, out var _, m_navMeshAgent.radius * 2f, (int)EnemyLayer | (int)InteractLayer);
			}
			m_navMeshAgent.obstacleAvoidanceType = (flag ? ObstacleAvoidanceType.HighQualityObstacleAvoidance : ObstacleAvoidanceType.NoObstacleAvoidance);
		}

		private void UpdateClickToMoveTargets(bool mousePressed, bool pressedThisFrame, bool releasedThisFrame, bool mouseReleased)
		{
			if (InputBlocker.Blocked || Player.PlayerChar.Fishing())
			{
				hoveredPosition = TargetAgent.MyTransform.position;
				hoveredTarget = null;
				hoveredDamageable = null;
				return;
			}
			if (TryGetMousePositionRaycastHit(out var hit))
			{
				Vector3 vector = Player.PlayerChar.myTransform.position + Vector3.up * 0.2f;
				Vector3 vector2 = hit.point - vector;
				float magnitude = vector2.magnitude;
				if (Physics.Raycast(vector, vector2.normalized, out var hitInfo, magnitude, LayerMask.GetMask("Default")))
				{
					hoveredPosition = hitInfo.point;
					hoveredTarget = hitInfo.transform;
				}
				else
				{
					hoveredPosition = hit.point;
					hoveredTarget = hit.transform;
				}
				if (hoveredTarget != null && IsTargetValid(hoveredTarget))
				{
					hoveredDamageable = (GameUtils.LayerMaskIncludesLayer(EnemyLayer, hoveredTarget.gameObject.layer) ? hoveredTarget : null);
				}
				if (pressedThisFrame && hoveredDamageable != null)
				{
					lockedDamageable = hoveredDamageable;
				}
				if (lockedDamageable != null)
				{
					hoveredDamageable = lockedDamageable;
				}
				hoveredInteractable = ((hoveredTarget != null) ? hoveredTarget.GetComponentInParent<InteractableSceneObject>() : null);
				if (hoveredInteractable != null && !hoveredInteractable.CanInteract)
				{
					hoveredInteractable = null;
				}
				else if (interactWhenInRangeTarget != null && pressedThisFrame)
				{
					interactWhenInRangeTarget = null;
					interactWhenInRange = false;
				}
				if (hoveredDamageable == null && hoveredInteractable == null)
				{
					hoveredTarget = null;
				}
				characterTarget = ((hoveredDamageable != null) ? hoveredDamageable.GetComponent<Character>() : null);
			}
			else
			{
				hoveredTarget = null;
				hoveredDamageable = null;
			}
			if (releasedThisFrame)
			{
				attackWhenInRange = hoveredDamageable != null && IsTargetValid(hoveredDamageable);
				attackWhenInRangeTarget = hoveredDamageable;
			}
			if (lockedDamageable != null && (mouseReleased || !IsTargetValid(lockedDamageable)))
			{
				lockedDamageable = null;
				hoveredDamageable = null;
			}
			damageableTarget = lockedDamageable;
		}

		private bool TryGetMousePositionRaycastHit(out RaycastHit hit)
		{
			Camera gameCamera = ProdigyCamera.GameCamera;
			for (int i = 0; i < 16; i++)
			{
				mouseHoverHits[i] = default(RaycastHit);
			}
			Ray ray = gameCamera.ScreenPointToRay(Mouse.current.position.ReadValue());
			if (Physics.SphereCastNonAlloc(ray.origin, 1f, ray.direction, mouseHoverHits, 100f, CombinationLayer, QueryTriggerInteraction.Collide) > 0)
			{
				IOrderedEnumerable<RaycastHit> source = mouseHoverHits.OrderByDescending(delegate(RaycastHit h)
				{
					if (h.collider == null)
					{
						return int.MinValue;
					}
					int num = 0;
					float num2 = Vector3.Distance(h.collider.transform.position, ray.origin);
					int num3 = (int)Mathf.Max(0f, 10f - num2 * 10f);
					num += num3;
					if (h.collider.TryGetComponent<InteractableSceneObject>(out var component))
					{
						if (component.CanInteract)
						{
							return num + component.InteractionPriority;
						}
						if (h.collider.TryGetComponent<CharacterVitals>(out var component2))
						{
							if (component2.IsDead)
							{
								return int.MinValue;
							}
							return num + 1000000;
						}
						return int.MinValue;
					}
					if (h.collider.TryGetComponent<CharacterVitals>(out var component3))
					{
						if (!component3.IsDead)
						{
							return num + 1000000;
						}
						if (h.collider.TryGetComponent<InteractableSceneObject>(out var component4))
						{
							if (!component4.CanInteract)
							{
								return int.MinValue;
							}
							return num + component4.InteractionPriority;
						}
						return int.MinValue;
					}
					ContainerDestroyable component5;
					return h.collider.TryGetComponent<ContainerDestroyable>(out component5) ? (component5.IsDestroyed ? int.MinValue : (num + 100000)) : (-2147483647);
				});
				hit = source.First();
				return hit.collider != null;
			}
			hit = default(RaycastHit);
			return false;
		}

		private void UpdateClickToMoveHighlight()
		{
			Transform newTarget = null;
			if (lockedDamageable != null)
			{
				newTarget = lockedDamageable;
			}
			else if (hoveredInteractable != null)
			{
				newTarget = hoveredInteractable.transform;
			}
			else if (hoveredDamageable != null)
			{
				newTarget = hoveredDamageable;
			}
			else if (interactWhenInRangeTarget != null)
			{
				newTarget = interactWhenInRangeTarget.transform;
			}
			else if (attackWhenInRangeTarget != null)
			{
				newTarget = attackWhenInRangeTarget.transform;
			}
			SetHighlightedTarget(newTarget);
		}

		public void SetHighlightedTarget(Transform newTarget, bool forceUpdate = false)
		{
			if (HighlightedTarget == newTarget)
			{
				bool flag = true;
				if (HighlightedTarget != null && HighlightedTarget.TryGetComponent<CharacterVitals>(out var component))
				{
					Character @char = component.Char;
					if (@char != null && (@char.IsMimic() || @char.IsShrine()))
					{
						flag = false;
					}
				}
				if (flag && !forceUpdate)
				{
					return;
				}
			}
			if (HighlightedTarget != null)
			{
				SetHighlightMaterialState(HighlightedTarget, highlight: false);
				if (HighlightedTarget.TryGetComponent<InteractableSceneObject>(out var component2))
				{
					component2.InteractionDeselect(Player.PlayerChar);
				}
			}
			HighlightedTarget = newTarget;
			if (HighlightedTarget != null)
			{
				SetHighlightMaterialState(HighlightedTarget, highlight: true);
				if (newTarget.TryGetComponent<InteractableSceneObject>(out var component3))
				{
					if (newTarget.TryGetComponent<CharacterVitals>(out var component4) && newTarget.gameObject.layer == LayerMask.NameToLayer("Player Damagable"))
					{
						SimpleSingletonBehaviour<PlayerUI>.Instance.SetTarget(component4);
						return;
					}
					component3.InteractionSelect(Player.PlayerChar);
					SimpleSingletonBehaviour<PlayerUI>.Instance.SetTarget(component3.InteractableName);
				}
				else
				{
					if (!newTarget.TryGetComponent<CharacterVitals>(out var component5))
					{
						return;
					}
					Character char2 = component5.Char;
					if (char2 != null && char2.IsMimic())
					{
						AIState aIState = char2.GetAIState();
						if (aIState == AIState.Wander || aIState == AIState.UniqueIdle || aIState == AIState.Inactive)
						{
							SimpleSingletonBehaviour<PlayerUI>.Instance.SetTarget(I2Loca.Get("Item_Chest") + "?");
							return;
						}
					}
					SimpleSingletonBehaviour<PlayerUI>.Instance.SetTarget(component5);
				}
			}
			else
			{
				SimpleSingletonBehaviour<PlayerUI>.Instance.SetTarget("");
			}
		}

		private void SetHighlightMaterialState(Transform target, bool highlight)
		{
			if (target == null)
			{
				return;
			}
			SkinnedMeshRenderer[] componentsInChildren = target.GetComponentsInChildren<SkinnedMeshRenderer>();
			if (componentsInChildren == null)
			{
				return;
			}
			SkinnedMeshRenderer[] array = componentsInChildren;
			foreach (SkinnedMeshRenderer skinnedMeshRenderer in array)
			{
				if (skinnedMeshRenderer == null)
				{
					continue;
				}
				Material[] materials = skinnedMeshRenderer.materials;
				if (materials == null)
				{
					continue;
				}
				for (int j = 0; j < materials.Length; j++)
				{
					if (materials[j].shader == null)
					{
						continue;
					}
					_ = materials[j].shader.keywordSpace;
					LocalKeyword[] keywords = materials[j].shader.keywordSpace.keywords;
					for (int k = 0; k < keywords.Length; k++)
					{
						LocalKeyword keyword = keywords[k];
						if (keyword.name.Contains("_SELECTED"))
						{
							Material material = new Material(materials[j]);
							material.SetKeyword(in keyword, highlight);
							materials[j] = material;
							break;
						}
					}
				}
				skinnedMeshRenderer.SetMaterials(materials.ToList());
			}
		}

