	public class AnimEventReload : StateMachineBehaviour
	{
		private AgentEquipment m_eq;

		[Range(0f, 1f)]
		[Tooltip("This is the Normalized Time at which you want the action to callback.\n\n* TIP: Get the percentage position you want from the Animation preview.\n   After clicking on an animation in the inspector, you can scrub the preview which shows you the percentage at that point.")]
		public float TimingStart;

		[Range(0f, 1f)]
		[Tooltip("This is the Normalized Time at which you want the action to callback.\n\n* TIP: Get the percentage position you want from the Animation preview.\n   After clicking on an animation in the inspector, you can scrub the preview which shows you the percentage at that point.")]
		public float TimingEnd;

		private bool m_startFired;

		private bool m_endFired;

		protected virtual void Reset()
		{
			TimingStart = 0f;
			TimingEnd = 1f;
		}

		public override void OnStateEnter(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			m_startFired = false;
			m_endFired = false;
			if (m_eq == null)
			{
				m_eq = animator.GetComponent<AgentEquipment>();
			}
			if (!(m_eq == null) && TimingStart < 0.01f)
			{
				m_startFired = true;
			}
		}

		public override void OnStateUpdate(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			if (!m_startFired && stateInfo.normalizedTime >= TimingStart)
			{
				m_startFired = true;
			}
			if (!m_endFired && stateInfo.normalizedTime >= TimingEnd)
			{
				m_endFired = true;
			}
		}

		public override void OnStateExit(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
		}
	}
	public class AnimEventSwap : StateMachineBehaviour
	{
		private AgentEquipment m_eq;

		[Range(0f, 1f)]
		[Tooltip("This is the Normalized Time at which you want the action to callback.\n\n* TIP: Get the percentage position you want from the Animation preview.\n   After clicking on an animation in the inspector, you can scrub the preview which shows you the percentage at that point.")]
		public float TimingStart;

		[Range(0f, 1f)]
		[Tooltip("This is the Normalized Time at which you want the action to callback.\n\n* TIP: Get the percentage position you want from the Animation preview.\n   After clicking on an animation in the inspector, you can scrub the preview which shows you the percentage at that point.")]
		public float TimingOccur;

		[Range(0f, 1f)]
		[Tooltip("This is the Normalized Time at which you want the action to callback.\n\n* TIP: Get the percentage position you want from the Animation preview.\n   After clicking on an animation in the inspector, you can scrub the preview which shows you the percentage at that point.")]
		public float TimingEnd;

		private bool m_startFired;

		private bool m_occurFired;

		private bool m_endFired;

		protected virtual void Reset()
		{
			TimingStart = 0f;
			TimingOccur = 0.5f;
			TimingEnd = 1f;
		}

		public override void OnStateEnter(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			m_startFired = false;
			m_occurFired = false;
			m_endFired = false;
			if (m_eq == null)
			{
				m_eq = animator.GetComponent<AgentEquipment>();
			}
			if (!(m_eq == null) && TimingStart < 0.01f)
			{
				m_startFired = true;
				m_eq.AnimCallbackSwapBegin();
			}
		}

		public override void OnStateUpdate(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			if (!(m_eq == null))
			{
				if (!m_startFired && stateInfo.normalizedTime >= TimingStart)
				{
					m_startFired = true;
					m_eq.AnimCallbackSwapBegin();
				}
				if (!m_occurFired && stateInfo.normalizedTime >= TimingOccur)
				{
					m_occurFired = true;
					m_eq.AnimCallbackSwapOccur();
				}
				if (!m_endFired && stateInfo.normalizedTime >= TimingEnd)
				{
					m_endFired = true;
					m_eq.AnimCallbackSwapEnd();
				}
			}
		}

		public override void OnStateExit(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			if (!(m_eq == null))
			{
				if (!m_occurFired)
				{
					m_eq.AnimCallbackSwapOccur();
				}
				if (!m_endFired)
				{
					m_eq.AnimCallbackSwapEnd();
				}
			}
		}
	}
	public class AnimStateSetLayerWeight : StateMachineBehaviour
	{
		[Header("Dependency")]
		public bool ParameterRequirement;

		public string ParameterName;

		public bool RequiredValue;

		[Header("State Entry")]
		public bool Apply;

		public float Weight;

		[Header("State Exit")]
		public bool _Apply;

		public float _Weight;

		private bool m_isValid;

		public override void OnStateEnter(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			m_isValid = !ParameterRequirement || (ParameterRequirement && animator.GetBool(ParameterName) == RequiredValue);
			if (m_isValid && Apply)
			{
				animator.SetLayerWeight(layerIndex, Weight);
			}
		}

		public override void OnStateExit(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
		{
			if (m_isValid && _Apply)
			{
				animator.SetLayerWeight(layerIndex, _Weight);
			}
		}
	}
	[AddComponentMenu("Cleverous/Prodigy/Agent/Prodigy Agent Equipment")]
	public class AgentEquipment : MonoBehaviour, IManagedTick
	{
		[SerializeField]
		private ProdigyAgent m_agentOwner;

		private Player player;

		[SerializeField]
		private Transform m_weaponMountL;

		[SerializeField]
		private Transform m_weaponMountR;

		private int[] m_invWeaponSlotIndexes;

		private int m_currentWeaponIndex;

		private float m_lastSwapTime;

		private bool m_fired;

		public ProdigyAgent AgentOwner
		{
			get
			{
				return m_agentOwner;
			}
			set
			{
				m_agentOwner = value;
			}
		}

		public Transform WeaponMountL
		{
			get
			{
				return m_weaponMountL;
			}
			set
			{
				m_weaponMountL = value;
			}
		}

		public Transform WeaponMountR
		{
			get
			{
				return m_weaponMountR;
			}
			set
			{
				m_weaponMountR = value;
			}
		}

		public Action OnEquipmentChanged { get; set; }

		public Action OnFired { get; set; }

		public bool IsSwapping { get; set; }

		public bool IsReloading { get; set; }

		public bool IsReloadingOrSwapping
		{
			get
			{
				if (!IsReloading)
				{
					return IsSwapping;
				}
				return true;
			}
		}

		public Item CurrentWeapon => Player.PlayerChar.activeWeapon;

		public GameObject CurrentWeaponObject => CurrentWeapon.physicalObject;

		public int CurrentWeaponFireId { get; protected set; }

		public bool IsInAttackAnimation { get; protected set; }

		private void Reset()
		{
			AgentOwner = GetComponent<ProdigyAgent>();
		}

		private void Start()
		{
			Initialize(AgentOwner);
		}

		public virtual void Initialize(ProdigyAgent owner)
		{
			AgentOwner = owner ?? GetComponent<ProdigyAgent>();
			player = AgentOwner.Vitals.Char as Player;
			BindToInventory();
			if (GameSettings.Instance.Debugging)
			{
				UnityEngine.Debug.Log("<B>EQUIPMENT</B> - <color=yellow>INITIALIZE: </color><color=cyan>EQUIPMENT <color=green>has subscribed</color> to the Inventory for " + base.gameObject.name + ".</color>", this);
			}
		}

		public virtual void BindToInventory()
		{
		}

		private void RebindToInventory()
		{
			Initialize(AgentOwner);
		}

		public virtual void ManagedTick()
		{
			PlayerInput input = AgentOwner.GetInput();
			if (IsInAttackAnimation || AgentOwner.GetDenialState().DenyFire || AgentOwner.Vitals.IsDead || Fate.isPaused || FateChoiceUI.FateChoiceActive)
			{
				return;
			}
			if (input.CycleEquipment && Time.time > m_lastSwapTime + 0.2f)
			{
				Player.PlayerChar.ToggleActiveWeaponSet();
				ThatHurt.PopText(Player.PlayerChar.myTransform.position, I2Loca.Get("WeaponsToggled"), 1f, ThatHurt.ThatHurtColor.White, 0f);
			}
			InputBroker.InputBehavior localInputBehavior = SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior;
			bool flag = localInputBehavior != 0 && EventSystem.current.IsPointerOverGameObject();
			if (input.Fire2 && !InputBlocker.Blocked && !flag)
			{
				bool num = localInputBehavior == InputBroker.InputBehavior.ClickToMove && Mouse.current != null;
				Vector3? targetPosition = null;
				Character character = null;
				if (num)
				{
					character = SingletonBehaviour<InputBroker>.Instance.HoveredCharacter;
					_ = Camera.main;
					Vector3 pos = Mouse.current.position.ReadValue();
					if (Physics.Raycast(Camera.main.ScreenPointToRay(pos), out var hitInfo, 10000f))
					{
						targetPosition = ((!NavMesh.SamplePosition(hitInfo.point, out var hit, 2f, -1)) ? new Vector3?(hitInfo.point.WithY(Player.PlayerChar.myTransform.position.y)) : new Vector3?(hit.position));
					}
				}
				else
				{
					float num2 = 0.6f;
					int mask = LayerMask.GetMask("Player Damagable", "Player");
					if (Physics.Raycast(player.myTransform.position + Vector3.up * num2, player.myTransform.forward, out var hitInfo2, 10000f, mask) && hitInfo2.collider.TryGetComponent<Character>(out var component))
					{
						character = component;
					}
				}
				if (!targetPosition.HasValue)
				{
					Vector3 vector = player.myTransform.position + player.myTransform.forward * 7.5f;
					NavMeshHit hit3;
					if (NavMesh.SamplePosition(vector, out var hit2, 2f, -1))
					{
						targetPosition = hit2.position;
					}
					else if (NavMesh.SamplePosition(Vector3.Lerp(vector, player.myTransform.position, 0.5f), out hit3, 2f, -1))
					{
						targetPosition = hit3.position;
					}
				}
				if (!targetPosition.HasValue)
				{
					targetPosition = player.myTransform.position + player.myTransform.forward;
				}
				if (input.Fire2)
				{
					if (SingletonBehaviour<InputBroker>.Instance.LocalInputBehavior == InputBroker.InputBehavior.ClickToMove)
					{
						Vector3 vec = ((character != null) ? character.myTransform.position : (targetPosition.HasValue ? targetPosition.Value : input.Look));
						Player.PlayerChar.myTransform.LookAt(vec.WithY(Player.PlayerChar.myTransform.position.y));
					}
					SingletonBehaviour<InputBroker>.Instance.StopMove();
					input.Fire2 = player.TryCastCurrentSpell(targetPosition, player.myTransform.forward, character);
				}
			}
			else if (input.Rage)
			{
				Player.PlayerChar.CastRageSpell();
			}
		}

		protected virtual void Fire(int fireId = 0)
		{
			CurrentWeaponFireId = fireId;
			Player.PlayerChar.AttackFrameReached();
			OnFired?.Invoke();
			m_fired = true;
		}

		public virtual void AnimCallbackAttackBegin(int id)
		{
			CurrentWeaponFireId = id;
			IsInAttackAnimation = true;
		}

		public virtual void AnimCallbackAttackOccur(int id)
		{
			if (!m_fired)
			{
				Fire(id);
			}
		}

		public virtual void AnimCallbackAttackEnd()
		{
			IsInAttackAnimation = false;
			m_fired = false;
			Player.PlayerChar.AttackDone();
		}

		protected virtual void CmdWeaponSwapStart(int newIndex, int oldIndex)
		{
			SvrWeaponSwapStart(newIndex, oldIndex);
		}

		protected virtual void SvrWeaponSwapStart(int newIndex, int oldIndex)
		{
			WeaponSwapStart(newIndex, oldIndex);
			RpcWeaponSwapStart(newIndex, oldIndex);
		}

		protected virtual void RpcWeaponSwapStart(int newIndex, int oldIndex)
		{
			WeaponSwapStart(newIndex, oldIndex);
		}

		protected virtual void WeaponSwapStart(int newIndex, int oldIndex)
		{
			AnimCallbackSwapBegin();
			AnimCallbackSwapOccur();
			AnimCallbackSwapEnd();
		}

		public virtual void AnimCallbackSwapBegin()
		{
			if (GameSettings.Instance.Debugging)
			{
				UnityEngine.Debug.Log("<B>EQUIPMENT</B> - <color=red>Callback Swap |Begin|</color>");
			}
			IsSwapping = true;
		}

		public virtual void AnimCallbackSwapOccur()
		{
			if (GameSettings.Instance.Debugging)
			{
				UnityEngine.Debug.Log("<B>EQUIPMENT</B> - <color=red>Callback Swap _Occur_</color>");
			}
		}

		public virtual void AnimCallbackSwapEnd()
		{
			if (GameSettings.Instance.Debugging)
			{
				UnityEngine.Debug.Log("<B>EQUIPMENT</B> - <color=red>Callback Swap *End*</color>");
			}
			IsSwapping = false;
			OnEquipmentChanged?.Invoke();
		}
	}
}
