		[SerializeField]
		private bool drawGizmos;

		[SerializeField]
		private bool LogOutOfRange;

		private GameObject fogPlane;

		private float FogRefreshRateTimer;

		private const string levelScanDataPath = "/LevelData";

		[NonSerialized]
		public bool isRunning = true;

		private float loopInterval = 0.25f;

		public List<FogRevealer> _FogRevealers => fogRevealers;

		public Transform _LevelMidPoint => levelMidPoint;

		public float _UnitScale => unitScale;

		public Shadowcaster shadowcaster { get; private set; } = new Shadowcaster();


		public LevelData levelData { get; private set; } = new LevelData();


		private void Start()
		{
			CheckProperties();
			InitializeVariables();
			if (LevelDataToLoad == null)
			{
				ScanLevel();
				if (!saveDataOnScan)
				{
				}
			}
			else
			{
				LoadLevelData();
			}
			InitializeFog();
			shadowcaster.Initialize(this);
			ForceUpdateFog();
			StartCoroutine(LoopingCoroutine());
		}

		private void Update()
		{
			UpdateFog();
		}

		private IEnumerator LoopingCoroutine()
		{
			while (isRunning)
			{
				ScanLevel();
				yield return new WaitForSeconds(loopInterval);
			}
		}

		public void StopScanning()
		{
			isRunning = false;
		}

		private void CheckProperties()
		{
			foreach (FogRevealer fogRevealer in fogRevealers)
			{
				if (fogRevealer._RevealerTransform == null)
				{
					UnityEngine.Debug.LogErrorFormat("Please assign a Transform component to each Fog Revealer!");
				}
			}
			if (unitScale <= 0f)
			{
				UnityEngine.Debug.LogErrorFormat("Unit Scale must be bigger than 0!");
			}
			if (scanSpacingPerUnit <= 0f)
			{
				UnityEngine.Debug.LogErrorFormat("Scan Spacing Per Unit must be bigger than 0!");
			}
			if (levelMidPoint == null)
			{
				UnityEngine.Debug.LogErrorFormat("Please assign the Level Mid Point property!");
			}
			if (fogPlaneMaterial == null)
			{
				UnityEngine.Debug.LogErrorFormat("Please assign the \"FogPlane\" material to the Fog Plane Material property!");
			}
		}

		private void InitializeVariables()
		{
			if (obstacleLayers.value == 0)
			{
				obstacleLayers = LayerMask.GetMask("Default");
			}
			if (levelNameToSave == string.Empty)
			{
				levelNameToSave = "Default";
			}
		}

		private void InitializeFog()
		{
			fogPlane = GameObject.CreatePrimitive(PrimitiveType.Plane);
			fogPlane.name = "[RUNTIME] Fog_Plane";
			fogPlane.transform.position = new Vector3(levelMidPoint.position.x, levelMidPoint.position.y + fogPlaneHeight, levelMidPoint.position.z);
			fogPlane.transform.localScale = new Vector3((float)levelDimensionX * unitScale / 10f, 1f, (float)levelDimensionY * unitScale / 10f);
			fogPlaneTextureLerpTarget = new Texture2D(levelDimensionX, levelDimensionY);
			fogPlaneTextureLerpBuffer = new Texture2D(levelDimensionX, levelDimensionY);
			fogPlaneTextureLerpBuffer.wrapMode = TextureWrapMode.Clamp;
			fogPlaneTextureLerpBuffer.filterMode = FilterMode.Bilinear;
			fogPlane.GetComponent<MeshRenderer>().material = new Material(fogPlaneMaterial);
			fogPlane.GetComponent<MeshRenderer>().material.SetTexture("_MainTex", fogPlaneTextureLerpBuffer);
			fogPlane.GetComponent<MeshCollider>().enabled = false;
			fogPlane.layer = 22;
			Transform parent = fogPlane.transform;
			UnityEngine.Object.Instantiate(fogCover).transform.SetParent(parent, worldPositionStays: false);
		}

		private void OnDestroy()
		{
			UnityEngine.Object.Destroy(fogPlane);
		}

		private void ForceUpdateFog()
		{
			UpdateFogField();
			Graphics.CopyTexture(fogPlaneTextureLerpTarget, fogPlaneTextureLerpBuffer);
		}

		private void UpdateFog()
		{
			fogPlane.transform.position = new Vector3(levelMidPoint.position.x, levelMidPoint.position.y + fogPlaneHeight, levelMidPoint.position.z);
			FogRefreshRateTimer += Time.deltaTime;
			if (FogRefreshRateTimer < 1f / FogRefreshRate)
			{
				UpdateFogPlaneTextureBuffer();
				return;
			}
			FogRefreshRateTimer -= 1f / FogRefreshRate;
			foreach (FogRevealer fogRevealer in fogRevealers)
			{
				if (!fogRevealer._UpdateOnlyOnMove || fogRevealer.GetCurrentLevelCoordinates(this) != fogRevealer._LastSeenAt)
				{
					break;
				}
				if (fogRevealer == fogRevealers.Last())
				{
					return;
				}
			}
			UpdateFogField();
			UpdateFogPlaneTextureBuffer();
		}

		private void UpdateFogField()
		{
			shadowcaster.ResetTileVisibility();
			foreach (FogRevealer fogRevealer in fogRevealers)
			{
				fogRevealer.GetCurrentLevelCoordinates(this);
				shadowcaster.ProcessLevelData(fogRevealer._CurrentLevelCoordinates, Mathf.RoundToInt((float)fogRevealer._SightRange / unitScale));
			}
			UpdateFogPlaneTextureTarget();
		}

		private void UpdateFogPlaneTextureBuffer()
		{
			Color[] pixels = fogPlaneTextureLerpBuffer.GetPixels();
			Color[] pixels2 = fogPlaneTextureLerpTarget.GetPixels();
			if (pixels.Length != pixels2.Length)
			{
				UnityEngine.Debug.LogErrorFormat("Fog plane texture buffer and target have different pixel counts");
				return;
			}
			for (int i = 0; i < pixels.Length; i++)
			{
				pixels[i] = Color.Lerp(pixels[i], pixels2[i], fogLerpSpeed * Time.deltaTime);
			}
			fogPlaneTextureLerpBuffer.SetPixels(pixels);
			fogPlaneTextureLerpBuffer.Apply();
		}

		private void UpdateFogPlaneTextureTarget()
		{
			fogPlaneTextureLerpTarget.SetPixels(shadowcaster.fogField.GetColors(fogPlaneAlpha, this));
			fogPlaneTextureLerpTarget.Apply();
		}

		private void ScanLevel()
		{
			levelData.levelDimensionX = levelDimensionX;
			levelData.levelDimensionY = levelDimensionY;
			levelData.unitScale = unitScale;
			levelData.scanSpacingPerUnit = scanSpacingPerUnit;
			for (int i = 0; i < levelDimensionX; i++)
			{
				levelData.AddColumn(new LevelColumn(Enumerable.Repeat(LevelColumn.ETileState.Empty, levelDimensionY)));
				for (int j = 0; j < levelDimensionY; j++)
				{
					if (Physics.BoxCast(new Vector3(GetWorldX(i), levelMidPoint.position.y + rayStartHeight, GetWorldY(j)), new Vector3((unitScale - scanSpacingPerUnit) / 2f, unitScale / 2f, (unitScale - scanSpacingPerUnit) / 2f), Vector3.down, Quaternion.identity, rayMaxDistance, obstacleLayers, (QueryTriggerInteraction)(2 - Convert.ToInt32(ignoreTriggers))))
					{
						levelData[i][j] = LevelColumn.ETileState.Obstacle;
					}
					else
					{
						levelData[i][j] = LevelColumn.ETileState.Empty;
					}
				}
			}
		}

		private void LoadLevelData()
		{
			UnityEngine.Debug.LogFormat("Level scan data with a name of \"{0}\" is assigned, loading...", LevelDataToLoad.name);
			string json = LevelDataToLoad.ToString();
			levelData = JsonUtility.FromJson<LevelData>(json);
			levelDimensionX = levelData.levelDimensionX;
			levelDimensionY = levelData.levelDimensionY;
			unitScale = levelData.unitScale;
			scanSpacingPerUnit = levelData.scanSpacingPerUnit;
			UnityEngine.Debug.LogFormat("Successfully loaded level scan data with the name of \"{0}\"", LevelDataToLoad.name);
		}

		public int AddFogRevealer(FogRevealer fogRevealer)
		{
			fogRevealers.Add(fogRevealer);
			return fogRevealers.Count - 1;
		}

		public void RemoveFogRevealer(int revealerIndex)
		{
			if (fogRevealers.Count > revealerIndex && revealerIndex > -1)
			{
				fogRevealers.RemoveAt(revealerIndex);
				return;
			}
			UnityEngine.Debug.LogFormat("Given index of {0} exceeds the revealers' container range", revealerIndex);
		}

		public void ReplaceFogRevealerList(List<FogRevealer> fogRevealers)
		{
			this.fogRevealers = fogRevealers;
		}

		public bool CheckLevelGridRange(Vector2Int levelCoordinates)
		{
			bool flag = levelCoordinates.x >= 0 && levelCoordinates.x < levelData.levelDimensionX && levelCoordinates.y >= 0 && levelCoordinates.y < levelData.levelDimensionY;
			if (!flag && LogOutOfRange)
			{
				UnityEngine.Debug.LogFormat("Level coordinates \"{0}\" is out of grid range", levelCoordinates);
			}
			return flag;
		}

		public bool CheckWorldGridRange(Vector3 worldCoordinates)
		{
			Vector2Int levelCoordinates = WorldToLevel(worldCoordinates);
			return CheckLevelGridRange(levelCoordinates);
		}

		public bool CheckVisibility(Vector3 worldCoordinates, int additionalRadius)
		{
			Vector2Int vector2Int = WorldToLevel(worldCoordinates);
			if (additionalRadius == 0)
			{
				return shadowcaster.fogField[vector2Int.x][vector2Int.y] == Shadowcaster.LevelColumn.ETileVisibility.Revealed;
			}
			int num = 0;
			for (int i = -1; i < additionalRadius + 1; i++)
			{
				for (int j = -1; j < additionalRadius + 1; j++)
				{
					if (!CheckLevelGridRange(new Vector2Int(vector2Int.x + i, vector2Int.y + j)))
					{
						num = 0;
						break;
					}
					num += Convert.ToInt32(shadowcaster.fogField[vector2Int.x + i][vector2Int.y + j] == Shadowcaster.LevelColumn.ETileVisibility.Revealed);
				}
			}
			if (num > 0)
			{
				return true;
			}
			return false;
		}

		public Vector2Int WorldToLevel(Vector3 worldCoordinates)
		{
			Vector2Int unitVector = GetUnitVector(worldCoordinates);
			return new Vector2Int(unitVector.x + levelDimensionX / 2, unitVector.y + levelDimensionY / 2);
		}

		public Vector3 GetWorldVector(Vector2Int worldCoordinates)
		{
			return new Vector3(GetWorldX(worldCoordinates.x + levelDimensionX / 2), 0f, GetWorldY(worldCoordinates.y + levelDimensionY / 2));
		}

		public Vector2Int GetUnitVector(Vector3 worldCoordinates)
		{
			return new Vector2Int(GetUnitX(worldCoordinates.x), GetUnitY(worldCoordinates.z));
		}

		public float GetWorldX(int xValue)
		{
			if (levelData.levelDimensionX % 2 == 0)
			{
				return levelMidPoint.position.x - ((float)levelDimensionX / 2f - (float)xValue) * unitScale;
			}
			return levelMidPoint.position.x - ((float)levelDimensionX / 2f - ((float)xValue + 0.5f)) * unitScale;
		}

		public int GetUnitX(float xValue)
		{
			return Mathf.RoundToInt((xValue - levelMidPoint.position.x) / unitScale);
		}

		public float GetWorldY(int yValue)
		{
			if (levelData.levelDimensionY % 2 == 0)
			{
				return levelMidPoint.position.z - ((float)levelDimensionY / 2f - (float)yValue) * unitScale;
			}
			return levelMidPoint.position.z - ((float)levelDimensionY / 2f - ((float)yValue + 0.5f)) * unitScale;
		}

		public int GetUnitY(float yValue)
		{
			return Mathf.RoundToInt((yValue - levelMidPoint.position.z) / unitScale);
		}
	}
