	public class csEyeController : MonoBehaviour
	{
		private Vector3 currentSpeed;

		[SerializeField]
		[Range(0f, 10f)]
		private float acceleration = 6f;

		[SerializeField]
		[Range(0f, 10f)]
		private float speedXLimit = 6f;

		[SerializeField]
		[Range(0f, 10f)]
		private float speedYLimit = 6f;

		private void Update()
		{
			if (Input.GetKey(KeyCode.W))
			{
				if (currentSpeed.y < speedYLimit)
				{
					currentSpeed.y += acceleration * Time.deltaTime;
				}
			}
			else if (Input.GetKey(KeyCode.S))
			{
				if (currentSpeed.y > 0f - speedYLimit)
				{
					currentSpeed.y -= acceleration * Time.deltaTime;
				}
			}
			else if (currentSpeed.y > acceleration * Time.deltaTime)
			{
				currentSpeed.y -= acceleration * Time.deltaTime;
			}
			else if (currentSpeed.y < (0f - acceleration) * Time.deltaTime)
			{
				currentSpeed.y += acceleration * Time.deltaTime;
			}
			else
			{
				currentSpeed.y = 0f;
			}
			if (Input.GetKey(KeyCode.A))
			{
				if (currentSpeed.x > 0f - speedXLimit)
				{
					currentSpeed.x -= acceleration * Time.deltaTime;
				}
			}
			else if (Input.GetKey(KeyCode.D))
			{
				if (currentSpeed.x < speedXLimit)
				{
					currentSpeed.x += acceleration * Time.deltaTime;
				}
			}
			else if (currentSpeed.x > acceleration * Time.deltaTime)
			{
				currentSpeed.x -= acceleration * Time.deltaTime;
			}
			else if (currentSpeed.x < (0f - acceleration) * Time.deltaTime)
			{
				currentSpeed.x += acceleration * Time.deltaTime;
			}
			else
			{
				currentSpeed.x = 0f;
			}
			base.transform.Translate(new Vector3(currentSpeed.x, 0f, currentSpeed.y) * Time.deltaTime);
		}
	}
	public class csFogVisibilityAgent : MonoBehaviour
	{
		[SerializeField]
		private csFogWar fogWar;

		[SerializeField]
		private bool visibility;

		[SerializeField]
		[Range(0f, 2f)]
		private int additionalRadius;

		private List<MeshRenderer> meshRenderers;

		private List<SkinnedMeshRenderer> skinnedMeshRenderers;

		private void Start()
		{
			try
			{
				fogWar = UnityEngine.Object.FindObjectOfType<csFogWar>();
			}
			catch
			{
				UnityEngine.Debug.LogErrorFormat("Failed to fetch csFogWar component. Please rename the gameobject that the module is attachted to as \"FogWar\", or change the implementation located in the csFogVisibilityAgent.cs script.");
			}
			meshRenderers = GetComponentsInChildren<MeshRenderer>().ToList();
			skinnedMeshRenderers = GetComponentsInChildren<SkinnedMeshRenderer>().ToList();
		}

		private void Update()
		{
			if (fogWar == null || !fogWar.CheckWorldGridRange(base.transform.position))
			{
				return;
			}
			visibility = fogWar.CheckVisibility(base.transform.position, additionalRadius);
			foreach (MeshRenderer meshRenderer in meshRenderers)
			{
				meshRenderer.enabled = visibility;
			}
			foreach (SkinnedMeshRenderer skinnedMeshRenderer in skinnedMeshRenderers)
			{
				skinnedMeshRenderer.enabled = visibility;
			}
		}
	}
	public class csRevealerSpawner : MonoBehaviour
	{
		[SerializeField]
		private csFogWar fogWar;

		[SerializeField]
		private GameObject exampleRevealer;

		private void Start()
		{
			try
			{
				fogWar = UnityEngine.Object.FindObjectOfType<csFogWar>();
			}
			catch
			{
				UnityEngine.Debug.LogErrorFormat("Failed to fetch csFogWar component. Please rename the gameobject that the module is attachted to as \"FogWar\", or change the implementation located in the csFogVisibilityAgent.cs script.");
			}
		}

		private void Update()
		{
			if (Input.GetKeyDown(KeyCode.R))
			{
				Transform component = UnityEngine.Object.Instantiate(position: new Vector3(UnityEngine.Random.Range((float)(-fogWar.levelData.levelDimensionX) / 2.5f, (float)fogWar.levelData.levelDimensionX / 2.5f), fogWar._LevelMidPoint.position.y + 0.5f, UnityEngine.Random.Range((float)(-fogWar.levelData.levelDimensionY) / 2.5f, (float)fogWar.levelData.levelDimensionY / 2.5f)), original: exampleRevealer, rotation: Quaternion.identity).GetComponent<Transform>();
				fogWar.AddFogRevealer(new csFogWar.FogRevealer(component, 3, updateOnlyOnMove: false));
			}
			if (Input.GetKeyDown(KeyCode.C) && fogWar._FogRevealers.Count > 2)
			{
				fogWar.RemoveFogRevealer(fogWar._FogRevealers.Count - 1);
			}
		}
	}
	public class Shadowcaster
	{
		public class FogField
		{
			private List<LevelColumn> levelRow = new List<LevelColumn>();

			private Color[] colors;

			public LevelColumn this[int index]
			{
				get
				{
					if (index >= 0 && index < levelRow.Count)
					{
						return levelRow[index];
					}
					UnityEngine.Debug.LogErrorFormat("index given in x axis is out of range");
					return null;
				}
				set
				{
					if (index >= 0 && index < levelRow.Count)
					{
						levelRow[index] = value;
					}
					else
					{
						UnityEngine.Debug.LogErrorFormat("index given in x axis is out of range");
					}
				}
			}

			public void AddColumn(LevelColumn levelColumn)
			{
				levelRow.Add(levelColumn);
			}

			public void Reset(csFogWar fogWar)
			{
				foreach (LevelColumn item in levelRow)
				{
					item.Reset(fogWar);
				}
			}

			public Color[] GetColors(float fogPlaneAlpha, csFogWar fogWar)
			{
				if (colors == null)
				{
					colors = new Color[levelRow.Count * levelRow[0].Count()];
				}
				for (int i = 0; i < levelRow[0].Count(); i++)
				{
					for (int j = 0; j < levelRow.Count; j++)
					{
						int num = (int)levelRow[j][levelRow[0].Count() - 1 - i];
						float num2 = 1 - num;
						if (fogWar.keepRevealedTiles && num == 2)
						{
							num2 = fogWar.revealedTileOpacity;
						}
						colors[levelRow.Count() * (i + 1) - (j + 1)] = new Color(1f, 1f, 1f, num2 * fogPlaneAlpha);
					}
				}
				return colors;
			}
		}

		public class LevelColumn
		{
			public enum ETileVisibility
			{
				Hidden,
				Revealed,
				PreviouslyRevealed
			}

			private List<ETileVisibility> levelColumn = new List<ETileVisibility>();

			public ETileVisibility this[int index]
			{
				get
				{
					if (index >= 0 && index < levelColumn.Count)
					{
						return levelColumn[index];
					}
					UnityEngine.Debug.LogErrorFormat("index given in y axis is out of range");
					return ETileVisibility.Hidden;
				}
				set
				{
					if (index >= 0 && index < levelColumn.Count)
					{
						levelColumn[index] = value;
					}
					else
					{
						UnityEngine.Debug.LogErrorFormat("index given in y axis is out of range");
					}
				}
			}

			public LevelColumn(IEnumerable<ETileVisibility> visibilityTiles)
			{
				levelColumn = new List<ETileVisibility>(visibilityTiles);
			}

			public void Reset(csFogWar fogWar)
			{
				for (int i = 0; i < levelColumn.Count; i++)
				{
					if (!fogWar.keepRevealedTiles)
					{
						levelColumn[i] = ETileVisibility.Hidden;
					}
					else if (levelColumn[i] == ETileVisibility.Revealed)
					{
						levelColumn[i] = ETileVisibility.PreviouslyRevealed;
					}
				}
			}

			public int Count()
			{
				return levelColumn.Count;
			}
		}

		private class QuadrantIterator
		{
			public enum ECardinal
			{
				East,
				North,
				West,
				South
			}

			private csFogWar fogWar;

			public ECardinal cardinal { get; set; }

			public Vector2Int originPoint { get; set; }

			public QuadrantIterator(csFogWar fogWar)
			{
				this.fogWar = fogWar;
			}

			public Vector2Int QuadrantToLevel(Vector2Int quadrantVector)
			{
				Vector2Int worldCoordinates = default(Vector2Int);
				worldCoordinates = cardinal switch
				{
					ECardinal.North => new Vector2Int(originPoint.x - quadrantVector.y, originPoint.y + quadrantVector.x), 
					ECardinal.West => new Vector2Int(originPoint.x - quadrantVector.x, originPoint.y - quadrantVector.y), 
					ECardinal.South => new Vector2Int(originPoint.x + quadrantVector.y, originPoint.y - quadrantVector.x), 
					_ => new Vector2Int(originPoint.x + quadrantVector.x, originPoint.y + quadrantVector.y), 
				};
				return fogWar.WorldToLevel(fogWar.GetWorldVector(worldCoordinates));
			}
		}

		private class ColumnIterator
		{
			public int depth { get; private set; }

			public int maxDepth { get; private set; }

			public float startSlope { get; set; }

			public float endSlope { get; set; }

			public ColumnIterator(int depth, int maxDepth, float startSlope, float endSlope)
			{
				this.depth = depth;
				this.maxDepth = maxDepth;
				this.startSlope = startSlope;
				this.endSlope = endSlope;
			}

			public List<Vector2Int> GetTiles()
			{
				List<Vector2Int> list = new List<Vector2Int>();
				int num = Mathf.RoundToInt((float)depth * startSlope);
				int num2 = Mathf.RoundToInt((float)depth * endSlope);
				for (int i = num; i < num2 + 1; i++)
				{
					list.Add(new Vector2Int(depth, i));
				}
				if (endSlope == 1f)
				{
					list.RemoveAt(list.Count - 1);
				}
				return list;
			}

			public bool IsProceedable()
			{
				return depth < maxDepth;
			}

			public void ProceedIfPossible()
			{
				if (depth < maxDepth)
				{
					depth++;
				}
			}
		}

		private csFogWar fogWar;

		private QuadrantIterator quadrantIterator;

		public FogField fogField { get; private set; } = new FogField();


		public void Initialize(csFogWar fogWar)
		{
			this.fogWar = fogWar;
			for (int i = 0; i < fogWar.levelData.levelDimensionX; i++)
			{
				fogField.AddColumn(new LevelColumn(Enumerable.Repeat(LevelColumn.ETileVisibility.Hidden, fogWar.levelData.levelDimensionY)));
			}
			quadrantIterator = new QuadrantIterator(fogWar);
		}

		public void ResetTileVisibility()
		{
			fogField.Reset(fogWar);
		}

		public void ProcessLevelData(Vector2Int revealerPoint, int sightRange)
		{
			RevealTile(fogWar.WorldToLevel(fogWar.GetWorldVector(revealerPoint)));
			quadrantIterator.originPoint = revealerPoint;
			foreach (int value in Enum.GetValues(typeof(QuadrantIterator.ECardinal)))
			{
				quadrantIterator.cardinal = (QuadrantIterator.ECardinal)value;
				Queue<ColumnIterator> queue = new Queue<ColumnIterator>();
				queue.Enqueue(new ColumnIterator(1, sightRange, -1f, 1f));
				while (queue.Count > 0)
				{
					ColumnIterator columnIterator = queue.Dequeue();
					List<Vector2Int> tiles = columnIterator.GetTiles();
					Vector2Int quadrantPoint = default(Vector2Int);
					bool flag = true;
					foreach (Vector2Int item in tiles)
					{
						if (IsTileObstacle(item) || IsTileVisible(columnIterator, item))
						{
							RevealTileIteratively(item, sightRange);
						}
						if (!flag)
						{
							if (IsTileObstacle(quadrantPoint) && IsTileEmpty(item))
							{
								columnIterator.startSlope = GetQuadrantSlope(item);
							}
							if (IsTileEmpty(quadrantPoint) && IsTileObstacle(item))
							{
								if (!columnIterator.IsProceedable())
								{
									continue;
								}
								ColumnIterator columnIterator2 = new ColumnIterator(columnIterator.depth, sightRange, columnIterator.startSlope, GetQuadrantSlope(item));
								columnIterator2.ProceedIfPossible();
								queue.Enqueue(columnIterator2);
							}
						}
						quadrantPoint = item;
						flag = false;
					}
					if (IsTileEmpty(quadrantPoint) && columnIterator.IsProceedable())
					{
						columnIterator.ProceedIfPossible();
						queue.Enqueue(columnIterator);
					}
				}
			}
		}

		private void RevealTileIteratively(Vector2Int quadrantPoint, int sightRange)
		{
			Vector2Int levelCoordinates = quadrantIterator.QuadrantToLevel(quadrantPoint);
			if (fogWar.CheckLevelGridRange(levelCoordinates) && !(quadrantPoint.magnitude > (float)sightRange))
			{
				fogField[levelCoordinates.x][levelCoordinates.y] = LevelColumn.ETileVisibility.Revealed;
			}
		}

		private void RevealTile(Vector2Int levelCoordinates)
		{
			if (fogWar.CheckLevelGridRange(levelCoordinates))
			{
				fogField[levelCoordinates.x][levelCoordinates.y] = LevelColumn.ETileVisibility.Revealed;
			}
		}

		private bool IsTileEmpty(Vector2Int quadrantPoint)
		{
			Vector2Int levelCoordinates = quadrantIterator.QuadrantToLevel(quadrantPoint);
			if (!fogWar.CheckLevelGridRange(levelCoordinates))
			{
				return true;
			}
			return fogWar.levelData[levelCoordinates.x][levelCoordinates.y] == csFogWar.LevelColumn.ETileState.Empty;
		}

		private bool IsTileObstacle(Vector2Int quadrantPoint)
		{
			Vector2Int levelCoordinates = quadrantIterator.QuadrantToLevel(quadrantPoint);
			if (!fogWar.CheckLevelGridRange(levelCoordinates))
			{
				return false;
			}
			return fogWar.levelData[levelCoordinates.x][levelCoordinates.y] == csFogWar.LevelColumn.ETileState.Obstacle;
		}

		private bool IsTileVisible(ColumnIterator columnIterator, Vector2Int quadrantPoint)
		{
			if ((float)quadrantPoint.y >= (float)columnIterator.depth * columnIterator.startSlope)
			{
				return (float)quadrantPoint.y <= (float)columnIterator.depth * columnIterator.endSlope;
			}
			return false;
		}

		private float GetQuadrantSlope(Vector2Int quadrantPoint)
		{
			return (float)(quadrantPoint.y * 2 - 1) / ((float)quadrantPoint.x * 2f);
		}
	}
}
